void dfs(int l, int r, int par = 0){
	if(l >= r) return ;

	g[par].push_back(++c);
	int pos = c;	
	if(l % 2 == 0){
		Node p = seg[0].get(l, r);
		Node q = seg[1].get(p.ind, r);
		seg[0].update(p.ind, INF);
		seg[1].update(q.ind, INF);
		ans[pos] = {p.data, q.data};

		dfs(l, p.ind, c);
		dfs(p.ind + 1, q.ind, pos);
		dfs(q.ind + 1, r, c);
	}else{
		Node p = seg[1].get(l, r);
		Node q = seg[0].get(l, r);
		seg[1].update(p.ind, INF);
		seg[0].update(q.ind, INF);
		ans[pos] = {p.data, q.data};

		dfs(l, p.ind, c);
		dfs(p.ind + 1, q.ind, pos);
		dfs(q.ind + 1, r, c);
	}
}

