array<pair<int, int>, 2> shiftIndices(array<pair<int, int>, 2> mi, int by) {
    return array<pair<int, int>, 2> { { { mi[0].first, mi[0].second + by }, { mi[1].first, mi[1].second + by } } };
}

class Treap {
public:
	typedef struct _node {
		int val;
		_node* l;
		_node* r;
		int cnt;
		int prior;

        array<pair<int, int>, 2> minIndex;

		_node(int val) :val(val), l(nullptr), r(nullptr), cnt(1) {
            prior = (rand() << 16) | rand();
            minIndex[0] = make_pair(val, 0);
            minIndex[1] = make_pair(1e9, -1);
        }

		void push() {

		}

		void recalc() {
            int cntl = Cnt(l);
            int cntr = Cnt(r);
			cnt = 1 + cntl + cntr;

            if (cntl > 0) {
                minIndex = l->minIndex;
            } else {
                minIndex[0] = make_pair((int)1e9, -1);
                minIndex[1] = make_pair((int)1e9, -1);
            }

            minIndex[cntl % 2] = min(minIndex[cntl % 2], make_pair(val, cntl));

            if (cntr > 0) {
                auto shifted = shiftIndices(r->minIndex, cntl + 1);
                minIndex[(cntl + 1) % 2] = min(minIndex[(cntl + 1) % 2], shifted[0]);
                minIndex[(cntl + 1 + 1) % 2] = min(minIndex[(cntl + 1 + 1) % 2], shifted[1]);
            }
		}

		static int Cnt(_node* v) {
			if (!v)
				return 0;
			return v->cnt;
		}
	}*node;

	static int Cnt(node v) {
		if (!v)
			return 0;
		return v->cnt;
	}

	node root;

	size_t Size;

	node merge(node l, node r) {
		if (!l)
			return r;
		if (!r)
			return l;
		if (l->prior < r->prior) {
			l->push();
			l->r = merge(l->r, r);
			l->recalc();
			return l;
		}
		else {
			r->push();
			r->l = merge(l, r->l);
			r->recalc();
			return r;
		}
	}

	static void split(node v, int idx, node& l, node& r) {
		l = r = nullptr;
		if (!v)
			return;
		v->push();
		if (Cnt(v->l) < idx) {
			l = v;
			split(l->r, idx - Cnt(v->l) - 1, l->r, r);
			l->recalc();
		}
		else {
			r = v;
			split(r->l, idx, l, r->l);
			r->recalc();
		}
	}

public:
	Treap() {
		root = nullptr;
		Size = 0;
	}

	Treap(node n) {
        root = n;
        Size = n ? n->cnt : 0;
    }

	size_t size() const {
		return Size;
	}

	void insert(int idx, int val) { //insert at the idx - position
		node l = nullptr, r = nullptr;
		split(root, idx, l, r);
		node cur_node = new _node(val);
		root = merge(merge(l, cur_node), r);
		++Size;
	}

	void erase(int idx) {
		node l = nullptr, m = nullptr, r = nullptr;
		split(root, idx, l, r);
		split(r, 1, m, r);
		root = merge(l, r);
		--Size;
	}

	void push_back(int val) {
		return insert(Size, val);
	}
	void push_front(int val) {
		return insert(0, val);
	}

	node operator [] (int idx) {
		node l = nullptr, m = nullptr, r = nullptr;
		split(root, idx, l, r);
		split(r, 1, m, r);
		if (m == nullptr) {
			throw runtime_error("IndexTreapOutOfBound");
		}
		root = merge(merge(l, m), r);
		return m;
	}

	pair<int, node> getKey() const {
        return make_pair(root ? root->minIndex[0].first : (int)1e9, root);
    }
};

