    cin >> n;
    for (int i = 0; i < n; ++i) {
        scanf("%d", p + i);
    }

    build(1, 0, n - 1);

    set<pii> foo;
    foo.insert({0, n - 1});

    int cur = 0;
    while (!foo.empty()) {
        auto cand = foo.begin();
        int ind = query(1, 0, n - 1, (*foo.begin()).fi, (*foo.begin()).se);

        for (auto it = next(foo.begin()); it != foo.end(); ++it) {
            int bar = query(1, 0, n - 1, (*it).fi, (*it).se);
            if (p[bar] < p[ind]) {
                cand = it;
                ind = bar;
            }
        }

        pii tmp = *cand;
        foo.erase(cand);
        int another = query(1, 0, n - 1, ind + 1, tmp.se);
        if (ind > tmp.fi) {
            foo.insert({tmp.fi, ind - 1});
        }
        if (ind + 1 < another) {
            foo.insert({ind + 1, another - 1});
        }
        if (another < tmp.se) {
            foo.insert({another + 1, tmp.se});
        }

        q[cur++] = p[ind];
        q[cur++] = p[another];
    }

    for (int i = 0; i < n; ++i) {
        printf("%d%c", q[i], " \n"[i == n - 1]);
    }

    return 0;
}

