void build(int k,int l,int r){
//	cout<<k<<" "<<l<<  " "<<r<<endl;
	if(l==r-1){
		Jtree[k]=Otree[k]={0x3f3f3f3f,l};
		if(l%2) Jtree[k]={p[l],l};
		else Otree[k]={p[l],l};
		return;
	}
	int mid=(l+r)>>1;
	build(k*2,l,mid);
	build(k*2+1,mid,r);
	Jtree[k]=min(Jtree[k*2],Jtree[k*2+1]);
	Otree[k]=min(Otree[k*2],Otree[k*2+1]);
}
pair<int,int> getJ(int k,int a,int b,int l,int r){
	if(r<=a||l>=b) return {0x3f3f3f3f+1,l};
	if(r<=b&&l>=a) return Jtree[k];
	int mid=(l+r)>>1;
	return min(getJ(k*2,a,b,l,mid),getJ(k*2+1,a,b,mid,r));
}
pair<int,int> getO(int k,int a,int b,int l,int r){
	if(r<=a||l>=b) return {0x3f3f3f3f+1,l};//cout<<k<<" "<<a<<" "<<b<<" "<<l<<" "<<r<<endl;
	if(r<=b&&l>=a) return Otree[k];
	int mid=(l+r)>>1;
	return min(getO(k*2,a,b,l,mid),getO(k*2+1,a,b,mid,r));
}
