void dfs(int l, int r, int d) {
	if (r - l < 2) return;

	int miidx, nidx;
	if (l & 1) {
		miidx = segodd.query(l, r).se;
		nidx = segeven.query(miidx + 1, r).se;
	}
	else {
		miidx = segeven.query(l, r).se;
		nidx = segodd.query(miidx + 1, r).se;
	}

	pq.push(pip(d, pii(p[miidx], p[nidx])));

	dfs(l, miidx, d + 1);
	dfs(miidx + 1, nidx, d + 1);
	dfs(nidx + 1, r, d + 1);

	return;
}

