const int N = 200010;
int ch[N << 1][2];
int key[N << 1];
int odd[N << 1], eve[N << 1];
int op[N << 1], ep[N << 1];

int cnt = 1;

int n, a[N];

#define L (ch[x][0])
#define R (ch[x][1])
#define mid ((l + r) >> 1)

void upd(int x) {
	odd[x] = odd[L] <= odd[R] ? odd[L] : odd[R];
	op[x] = odd[L] <= odd[R] ? op[L] : op[R];

	eve[x] = eve[L] <= eve[R] ? eve[L] : eve[R];
	ep[x] = eve[L] <= eve[R] ? ep[L] : ep[R];
}

void build(int x, int l, int r) {
	if(l == r) {
		odd[x] = eve[x] = N;
		op[x] = ep[x] = l;
		if(l % 2) odd[x] = a[l];
		else eve[x] = a[l];
	}
	else {
		L = ++ cnt;
		R = ++ cnt;
		build(L, l, mid);
		build(R, mid + 1, r);
		upd(x);
	}
}

int query(int x, int l, int r, int ll, int rr, int OE) {
	if(l >= ll && r <= rr) return OE ? op[x] : ep[x];
	int ans = 0;
	if(mid >= ll) {
		int p = query(L, l, mid, ll, rr, OE);
		if(!ans || a[p] < a[ans]) ans = p;
	}
	if(mid < rr) {
		int p = query(R, mid + 1, r, ll, rr, OE);
		if(!ans || a[p] < a[ans]) ans = p;
	}
	return ans;
}

struct Node {
	int former, latter;
	vector <int> son;
}nod[N];
int nodCnt;

int solve(int l, int r, bool P) {
	int x = ++ nodCnt;
	nod[x].former = query(1, 1, n, l, r, P ^ 1);
	nod[x].latter = query(1, 1, n, nod[x].former + 1, r, P);
	if(l < nod[x].former) nod[x].son.push_back(solve(l, nod[x].former - 1, P));
	if(r > nod[x].latter) nod[x].son.push_back(solve(nod[x].latter + 1, r, P));
	if(nod[x].former + 1 != nod[x].latter) nod[x].son.push_back(solve(nod[x].former + 1, nod[x].latter - 1, P ^ 1));
	return x; 
}

struct Heap {
	int key[N], cnt;
	void push(int x) {
		int now = ++ cnt;
		key[now] = x;
		while(now >> 1 && a[nod[key[now >> 1]].former] > a[nod[key[now]].former]) {
			swap(key[now >> 1], key[now]);
			now >>= 1;
		}
	}
	void pop() {
		key[1] = 0; key[1] = key[cnt]; key[cnt --] = 0;
		int now = 1, son = now << 1;
		while(son <= cnt) {
			if(son + 1 <= cnt && a[nod[key[son]].former] > a[nod[key[son + 1]].former]) ++ son;
			if(a[nod[key[now]].former] > a[nod[key[son]].former]) {
				swap(key[now], key[son]);
				now = son; son = now << 1;
			}
			else break;
		}
	}
	bool empty() {return cnt == 0;}
}hp;

