                        if(no[i].id < pos) continue;
                        if(used[no[i].num]) {
                            continue;
                        }

                        if(sum(no[i].id) - sum(pos-1) > 0) continue;
                    if((no[i].id - pos + 1) % 2 == 0) {
                        used[num] = 1;
                        used[no[i].num] = 1;
                        que[se++] = num;
                        que[se++] = no[i].num;
                        add(no[i].id);
                        if(no[i].id == len) len--;
                        add(pos);
                        ppp = 1;
                        break;
                    }
                    if(ppp) break;
                }

            }
            flag++;
        }
    }
    for(int i = 0; i < se; ++i) {
        printf("%d", que[i]);
        if(i != se-1) printf(" ");
    }
    return 0;
}

