inline void push(int p)
{
  for(int i=0;i<=1;++i)
    if(a[t[p<<1][i].x]<a[t[p<<1|1][i].x])
      t[p][i].x=t[p<<1][i].x;
    else t[p][i].x=t[p<<1|1][i].x;
}
void build(int p,int l,int r)
{
  if(l==r){t[p][l%2].x=l;return ;}
  int mid=(l+r)>>1;
  build(p<<1,l,mid);build(p<<1|1,mid+1,r);
  push(p);
}
inline int ask(int p,int l,int r,int tl,int tr,int c)
{
  if(tl==l&&r==tr)return t[p][c].x;
  int mid=(l+r)>>1;
  if(tr<=mid)return ask(p<<1,l,mid,tl,tr,c);
  else if(tl>mid)return ask(p<<1|1,mid+1,r,tl,tr,c);
  else{
    int k=ask(p<<1,l,mid,tl,mid,c),kk=ask(p<<1|1,mid+1,r,mid+1,tr,c);
    if(a[k]<a[kk])return k;else return kk;
  }
}
