    FOR(k, 0, 2) FOR(i, 0, n + n) st[k][i] = mp(INF, INF);
    FOR(i, 0, n) {
        upd(st[i & 1], i, mp(a[i], i));
    }
    vi res;
    vii todos, tmp;
    todos.pb(mp(0, n - 1));
    while (sz(todos)) {
        vii vs;
        FOR(i, 0, sz(todos)) {
            int l = todos[i].fi;
            int r = todos[i].se;
            if (l > r) continue;
            pi mn = query(st[l & 1], l, r);
            if (mn.se == r) mn = query(st[l & 1], l, r - 1);
            int ix = mn.se;
            mn = query(st[(l & 1) ^ 1], ix + 1, r);
            int ix2 = mn.se;
            vs.pb(mp(a[ix], a[ix2]));
            tmp.pb(mp(l, ix - 1));
            tmp.pb(mp(ix + 1, ix2 - 1));
            tmp.pb(mp(ix2 + 1, r));
        }
        sort(all(vs));
        FOR(i, 0, sz(vs)) {
            res.pb(vs[i].fi);
            res.pb(vs[i].se);
        }
        todos = tmp;
        tmp.clear();
    }
