#define maxn 100010
int a[maxn], b[maxn], v[maxn << 1], d[maxn << 1];
struct tree {
	int le, rig;
	int mn, sm;
} ta[maxn << 2], tb[maxn << 2]; 
void build(int id, int l, int r) {
	ta[id].le = tb[id].le = l;
	ta[id].rig = tb[id].rig = r;
	tb[id].sm = ta[id].sm = 0;
	if (l == r) {
		ta[id].mn = a[l];
		tb[id].mn = b[l];
		return;
	}
	int mid = (l + r) / 2;
	build(id * 2, l, mid);
	build(id * 2 + 1, mid + 1, r);
	ta[id].mn = min(ta[id * 2].mn, ta[id * 2 + 1].mn);
	tb[id].mn = min(tb[id * 2].mn, tb[id * 2 + 1].mn);
}
void updatea(int id, int pos, int val) {
	if (ta[id].le == ta[id].rig) {
		ta[id].mn += val;
		ta[id].sm = 1;
		return;
	}
	int mid = (ta[id].le + ta[id].rig) / 2;
	if (pos <= mid) {
		updatea(id * 2, pos, val);
	} else {
		updatea(id * 2 + 1, pos, val);
	}
	ta[id].mn = min(ta[id * 2].mn, ta[id * 2 + 1].mn);
	ta[id].sm = ta[id << 1].sm + ta[id << 1 | 1].sm;
}
void updateb(int id, int pos, int val) {
	if (tb[id].le == tb[id].rig) {
		tb[id].mn += val;
		tb[id].sm++;
		return;
	}
	int mid = (tb[id].le + tb[id].rig) / 2;
	if (pos <= mid) {
		updateb(id * 2, pos, val);
	} else {
		updateb(id * 2 + 1, pos, val);
	}
	tb[id].mn = min(tb[id * 2].mn, tb[id * 2 + 1].mn);
	tb[id].sm = tb[id << 1].sm + tb[id << 1 | 1].sm;
}
int querya(int id, int l, int r) {
	if (ta[id].le == l && ta[id].rig == r) {
		return ta[id].mn;
	}
	int mid = (ta[id].le + ta[id].rig) / 2;
	if (r <= mid) {
		return querya(id * 2, l, r);
	} else if (l > mid) {
		return querya(id * 2 + 1, l, r);
	} else {
		return min(querya(id * 2, l, mid), querya(id * 2 + 1, mid + 1, r));
	}
} 
