int build(int no,int l,int r,int ind){
	if(l==r){
		if(l%2==ind){
			tree[no][ind]={it[l],l};
		}
		else{
			tree[no][ind]={n+1,l};
		}
	}
	else{
		int mid=(l+r)/2;
		build(no*2+1,l,mid,ind);
		build(no*2+2,mid+1,r,ind);
		if(tree[no*2+1][ind].a<tree[no*2+2][ind].a){
			tree[no][ind]=tree[no*2+1][ind];
		}
		else{
			tree[no][ind]=tree[no*2+2][ind];
		}
	}
}
pair<int,int> query(int no,int l,int r,int aa,int bb,int ind){
	if(bb<l or aa>r){
		return {n+1,-1};
	}
	if(aa<=l and r<=bb){
		return tree[no][ind];
	}
	else{
		int mid=(l+r)/2;
		pair<int,int> ac=query(no*2+1,l,mid,aa,bb,ind);
		pair<int,int> cc=query(no*2+2,mid+1,r,aa,bb,ind);
		if(ac.a<cc.a){
			return ac;
		}
		else{
			return cc;
		}
	}
}
