const int MAX_N = 212345;
struct RMQStatic {
  int *a;
  int dp_min[20][MAX_N]; // [i][j] := answer index of start_pos == j, len == 2^i
  int log2(int b) {return 31 - __builtin_clz(b);}
  // O(NlogN)
  void build(int* a, int N) {
    this->a = a;
    int M = log2(N) + 1;
    REP(i, N) dp_min[0][i] = i;
    for (int i = 1, len = 1; i < M; i++, len <<= 1) {
      for (int j = 0; j + len < N; j++) {
        {
          int s = dp_min[i - 1][j];
          int t = dp_min[i - 1][j + len];
          dp_min[i][j] = a[s] <= a[t] ? s : t;
        }
      }
    }
  }

  // O(1)
  // [from..to]の間で最小の値の添字を返す。複数ある場合は一番最初のを返す
  int query(int from, int to) {
    int k = log2(to - from + 1);
    int s = dp_min[k][from];
    int t = dp_min[k][to - (1 << k) + 1];
    return a[s] <= a[t] ? s : t;
  }
};

int P[MAX_N];
int E[MAX_N];
int O[MAX_N];

const int INF = 1001001001;
RMQStatic rmq_e;
RMQStatic rmq_o;

struct Part {
  int from, to;
  int x, y;
  Part(int from, int to) : from(from), to(to) { // [from, to]
    if (from % 2 == 0) {
      int x1 = rmq_e.query(from, to - 2);
      int y1 = rmq_o.query(x1 + 1, to);
      this->x = x1;
      this->y = y1;
    } else {
      int x2 = rmq_o.query(from, to - 2);
      int y2 = rmq_e.query(x2 + 1, to);
      this->x = x2;
      this->y = y2;
    }

  }
  bool operator < (const Part& o) const {
    if (x != o.x) return P[x] > P[o.x];
    return P[y] > P[o.y];
  }
};

int main2() {
  int N = nextInt();
  REP(i, N) P[i] = nextInt();
  REP(i, N) {
    if (i % 2 == 0) {
      E[i] = P[i];
      O[i] = INF;
    } else {
      E[i] = INF;
      O[i] = P[i];
    }
  }
  rmq_e.build(E, N);
  rmq_o.build(O, N);

  vector<int> ans;
  priority_queue< Part > pq;
  pq.push( Part(0, N-1) );
  while (!pq.empty()) {
    Part top = pq.top(); pq.pop();
    // cout << "[" << top.from << " " << top.to << "] (" << top.x << "," << top.y << ")" << endl;
    {
      int nx = top.from, ny = top.x - 1;
      // cout << nx << " "<< ny << endl;
      if (ny - nx + 1 >= 2) pq.push(Part(nx, ny));
    }
    {
      int nx = top.x + 1, ny = top.y - 1;
      // cout << nx << " "<< ny << endl;
      if (ny - nx + 1 >= 2) pq.push(Part(nx, ny));
    }
    {
      int nx = top.y + 1, ny = top.to;
      // cout << nx << " "<< ny << endl;
      if (ny - nx + 1 >= 2) pq.push(Part(nx, ny));
    }
    ans.push_back(P[top.x]);
    ans.push_back(P[top.y]);
  }

  REP(i, ans.size()) {
    if (i > 0) printf(" ");
    printf("%d", ans[i]);
  }
  printf("\n");

  return 0;
}

