using namespace std;
typedef long long ll;
typedef pair<int,int> P;
typedef pair<P, int> PP;

const double EPS = 1e-10;
const ll INF = 100000000;
const ll MOD = 1000000007;

#define MAX_N (1<<18)

struct segtree{
    int n, dat[2*MAX_N-1]; //(1<<17) = 130000

    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        for(int i = 0; i < 2*n-1; i++) dat[i] = INF;
    }

    void update(int k, int a){
        k += n-1;
        dat[k] = a;
        while(k > 0){
            k = (k-1)/2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    //(a,b,0,0,seg.n)で呼ぶ
    int query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return INF;
        if(a <= l && r <= b) return dat[k];
        else{
            int vl = query(a,b,k*2+1,l,(l+r)/2);
            int vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl, vr);
        }
    }
}seg1, seg2;

int n;
int p[200000];
int v2p[200000];
int id;
P val[200000];
vector<int> e[200000];

void solve(int st, int en, int par_id) {
    if(st == en) return;
    int pos, pos2;
    if(st&1) {
        pos = seg1.query(st, en, 0, 0, seg1.n);
    } else {
        pos = seg2.query(st, en, 0, 0, seg2.n);
    }
    pos = v2p[pos];
    if((pos+1)&1) {
        pos2 = seg1.query(pos+1, en, 0, 0, seg1.n);
    } else {
        pos2 = seg2.query(pos+1, en, 0, 0, seg2.n);
    }
    pos2 = v2p[pos2];
    int now_id = id;
    val[id++] = P(p[pos], p[pos2]);
    if(par_id != -1) {
        e[par_id].push_back(now_id);
    }

    solve(st, pos, now_id);
    solve(pos+1, pos2, now_id);
    solve(pos2+1, en, now_id);
}

int main(){
    cin >> n;
    rep(i,n) cin >> p[i];
    rep(i,n) p[i]--;
    rep(i,n) v2p[p[i]] = i;
    seg1.init(n);
    seg2.init(n);
    rep(i,n) {
        if(i&1) {
            seg1.update(i, p[i]);
        } else {
            seg2.update(i, p[i]);
        }
    }
    solve(0, n, -1);
    vector<P> ans;
    ans.push_back(val[0]);
    priority_queue<PP, vector<PP>, greater<PP>> que;
    rep(i,e[0].size()) {
        que.push(PP(val[e[0][i]], e[0][i]));
    }
    while(!que.empty()) {
        PP p = que.top();
        que.pop();
        ans.push_back(p.first);
        rep(i, e[p.second].size()) {
            que.push(PP(val[e[p.second][i]], e[p.second][i]));
        }
    }

    rep(i,ans.size()) {
        cout << ans[i].first+1 << " " << ans[i].second+1;
        if(i != ans.size()-1) {
            cout << " ";
        } else {
            cout << endl;
        }
    }
}

