class SegmentTree{
	int n;
	vector<int>A,st;

	int left(int p)
	{
		return (p<<1);
	}

	int right(int p)
	{
		return (p<<1)+1;
	}

	void build(int p,int l,int r)
	{
		if(l==r)
		st[p]=l;
		else
		{
			build(left(p),l,(l+r)/2);
			build(right(p),((l+r)/2)+1,r);
			long long li=st[left(p)];
			long long ri=st[right(p)];

			if(A[li]<A[ri])
			st[p]=li;
			else
			st[p]=ri;				
		}
	}

	int rmq(int p,int l,int r,int i,int j)
	{
		if(i>r || j<l)
		return -1;
		else if(l>=i && r<=j)
		return st[p];

		int li=rmq(left(p),l,(l+r)/2,i,j);
		int ri=rmq(right(p),((l+r)/2)+1,r,i,j);

		if(li==-1)
		return ri;
		else if(ri==-1)
		return li;
		else
		{
			if(A[li]<A[ri])
			return li;
			else
			return ri;
		}
	}

	public:
		SegmentTree(const vector<int> &_A)
		{
			A=_A;
			n=(int)(A.size());
			st.assign(4*n,0);
			build(1,0,n-1);
		}

		int rmq(int i,int j)
		{
			return rmq(1,0,n-1,i,j);
		}
};

