void rec(int l,int r){//[l,r]  l%2!=r%2
  if(l+1==r){
      val[number++]=mkp(P[l],P[r]);
      return;
  }

  int left_val=INF;
  if(l%2){
      left_val=odd_seg.getMin(l,r+1);
      odd_seg.update(trans[left_val],INF);
  }else{
      left_val=even_seg.getMin(l,r+1);
      even_seg.update(trans[left_val],INF);
  }
  seg.update(trans[left_val],INF);

  int right_val=0;
  if(r%2){
      right_val=odd_seg.getMin(trans[left_val]+1,r+1);
      odd_seg.update(trans[right_val],INF);
  }else{
      right_val=even_seg.getMin(trans[left_val]+1,r+1);
      even_seg.update(trans[right_val],INF);
  }
  seg.update(trans[right_val],INF);

  int now=number;
  val[number++]=mkp(left_val,right_val);
  if(l<trans[left_val]){
      g[now].push_back(number);
      rec(l,trans[left_val]-1);
  }
  if(trans[right_val]-trans[left_val]+1>2){
      g[now].push_back(number);
      rec(trans[left_val]+1,trans[right_val]-1);
  }
  if(trans[right_val]<r){
      g[now].push_back(number);
      rec(trans[right_val]+1,r);
  }

  return;
}

int main(){
