struct RMQ {

	int n, m;
	vector <int> v;
	vector <int> rmq[20];
	vector <int> lg;

	RMQ(vector <int> &v) {
		n = v.size();
		lg.resize(n + 1);
		this->v = v;

		lg[1] = 0;
		for(int i = 1; i <= n; i++)
			lg[i] = 1 + lg[i / 2];
		m = lg[n];

		for(int i = 0; i < m; i++) rmq[i].resize(n);

		for(int i = 0; i < v.size(); i++) 
			rmq[0][i] = i;

		for(int i = 1; i < m; i++) 
			for(int j = 0; j + (1 << i) <= v.size(); j++)
				rmq[i][j] = (v[rmq[i - 1][j]] > v[rmq[i - 1][j + (1 << (i - 1))]] ? rmq[i - 1][j + (1 << (i - 1))] : rmq[i - 1][j]);
	}

	int getMinPos(int l, int r) {
		int i = lg[r - l + 1];
		i--;
		int p1 = rmq[i][l];
		int p2 = rmq[i][r - (1 << i) + 1];
		if(v[p1] < v[p2]) return p1;
		return p2;
	}
} ;

