            if (Pos + 1 <= ind - 1)
                seg.insert( mk(Pos + 1, ind - 1) );
            if (ind + 1 <= r)
                seg.insert( mk(ind + 1, r) );

            u[res] = 1;
            ans[++cnt] = i, ans[++cnt] = res;
        }
    }
    for (int i = 1; i <= n; i++)
        cout << ans[i] << " ";
}

