ll INF = 1e9;

struct SegtreeRMQ {
    ll n;
    ll inf;
    vector<ll> dat;

    void init(ll n_input, ll inf_input){
        inf = inf_input;
        n = 1;
        while(n < n_input)n <<= 1;
        dat.resize(2*n+10);
        for(int i = 0; i<2*n-1; i++) dat[i] = inf;
    }

    void update(ll k, ll a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1)/2;
            dat[k] = min(dat[2*k+1], dat[2*k+2]);
        }
    }

    ll query(ll a, ll b, ll k, ll l, ll r){
        if(r<=a || b<=l)return inf;
        if(a<=l && r<=b)return dat[k];
        ll vl = query(a, b, 2*k+1, l, (l+r)/2);
        ll vr = query(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

int main()
{
    int n;
    cin >> n;
    vector<int> p(n+1);
    vector<int> pos(n+1);
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        pos[p[i]] = i;
    }
    SegtreeRMQ st[2];
    st[0].init(n, INF);
    st[1].init(n, INF);

    for(int i = 0; i < n; i++)
    {
        if(i % 2 == 0)
        {
            st[0].update(i, p[i]);
            st[1].update(i, INF);
        }
        else
        {
            st[1].update(i, p[i]);
            st[0].update(i, INF);
        }
    }
    set<vector<ll>> cand;

    function<void(ll, ll)> process = [&](ll l, ll r)
    {
        if(r <= l) return;
        ll lmi = st[l%2].query(l, r, 0, 0, st[0].n);
        ll lpos = pos[lmi];
        ll rmi = st[(l+1)%2].query(lpos+1, r, 0, 0, st[0].n);
        ll rpos = pos[rmi];
        cand.insert({lmi, rmi, l, lpos, rpos, r});
    };

    process(0, n);
    vector<ll> ans;
    while(cand.size() > 0)
    {
        vector<ll> ret = *cand.begin();
        cand.erase(cand.begin());
        ans.push_back(ret[0]);
        ans.push_back(ret[1]);
        process(ret[2], ret[3]);
        process(ret[3]+1, ret[4]);
        process(ret[4]+1, ret[5]);
    }
    for(int i = 0; i < n; i++)
    {
        cout << ans[i] << " ";
    }
}

