int findPosMin(int ind, int l, int r) {
    int p = -1;
    int val = INF;
    l += step;
    r += step;
    while (l <= r) {
          if (val > tree[ind][l]) {
              val = tree[ind][l];
              p = pos[ind][l];
          }
          if (val > tree[ind][r]) {
              val = tree[ind][r];
              p = pos[ind][r];
          }
          l = (l+1)/2;
          r = (r-1)/2;
    }
    return p;
}

int findPosMin(int l, int r) {
