}

int dfs(int l, int r) {
    //cout << "DFS " << l << ' ' << r << endl;
    if (l + 1 == r) {
        ps[a[l]] = make_pair(a[l], a[r]);
        cs[a[l]] = 0;
      //  cout << "DFS returns " << a[l] << endl;
        return a[l];
    }

    int p = findPosMin((l&1), l, r);
    if ((p - l)&1) {
        int pp = findPosMin((l&1), l, p-1);
        ps[a[pp]] = make_pair(a[pp], a[p]);
        if (pp > l) {
            prs[dfs(l, pp-1)] = a[pp];
            cs[a[pp]]++;
        }

        if (pp + 1 < p) {
            prs[dfs(pp+1, p-1)] = a[pp];
            cs[a[pp]]++;
        }

        if (p < r) {
            prs[dfs(p+1, r)] = a[pp];
            cs[a[pp]]++;        
        }
        //cout << "DFS returns " << a[pp] << endl;

        return a[pp];
    }
    else {
        int pp = findPosMin(1 - (p&1), p+1, r);
        ps[a[p]] = make_pair(a[p], a[pp]);
        if (p > l) {
            prs[dfs(l, p-1)] = a[p];
            cs[a[p]]++;
        }

        if (p + 1 < pp) {
            prs[dfs(p+1, pp-1)] = a[p];
            cs[a[p]]++;
        }

        if (pp < r) {
            prs[dfs(pp+1, r)] = a[p];
            cs[a[p]]++;
        }
       // cout << "DFS returns " << a[p] << endl;

        return a[p];
    }

}

