struct TreeArray{
	int tree[maxn],a[maxn],N;
	void update(int x,int val){
		int lx,i;
		a[x]=val;
		while(x<=N){
			tree[x]=a[x];
			lx=lowbit(x);
			for(i=1;i<lx;i<<=1)
				tree[x]=min(tree[x],tree[x-i]);
			x+=lowbit(x);
		}
	}
	int query(int x,int y){
		int ans=maxn;
		while(y>=x){  
        	ans=min(a[y],ans);
			y--;  
			for(;y-lowbit(y)>=x;y-=lowbit(y))
				ans=min(tree[y],ans);
		}
		return ans;
	}
};
