#include<bits/stdc++.h>
using namespace std;

const int N = 2e5 + 10;
const int L = 18;
const int inf = 0x3f3f3f3f;

int n, a[N], b[2][N];
int dp[2][N][L], key[2][N][L];
int len[N];

void init(int op){
    for(int i=1; i<=n; i++){
        dp[op][i][0] = b[op][i];
        key[op][i][0] = i;
    }

    for(int j=1; j<L; j++){
        for(int i=1; i<=n; i++){
            int k = i + (1 << (j - 1));
            if(k > n)   k = n;
            if(dp[op][i][j-1] < dp[op][k][j-1]){
                key[op][i][j] = key[op][i][j-1];
            } else {
                key[op][i][j] = key[op][k][j-1];
            }
            dp[op][i][j] = b[op][key[op][i][j]];
        }
    }
}

int query(int op, int l, int r){
    int g = len[r - l + 1];
    int k = r - (1 << g) + 1;
    if(dp[op][l][g] < dp[op][k][g]){
        return key[op][l][g];
    } else {
        return key[op][k][g];
    }
}

int getfst(int l, int r){
    return query(1 - (l & 1), l, r);
}

int getsec(int l, int r){
    return query(l & 1, l, r);
}

struct Node{
    int l, r, v, w;
    Node(){}
    Node(int l, int r):l(l),r(r){
        v = getfst(l, r);
    }
    bool operator < (const Node &A)const{
        return a[v] > a[A.v];
    }
};

priority_queue<Node> Q;
Node nd;

void add(int l, int r){
    if(l < r){
        Q.push(Node(l, r));
    }
}

int main(){
    memset(len, -1, sizeof(len));
    for(int i=0; (1<<i) < N; i++){
        len[1<<i] = i;
    }
    for(int i=1; i<N; i++){
        if(len[i] == -1){
            len[i] = len[i-1];
        }
    }
    int p, q;
    while(~scanf("%d", &n)){
        for(int i=1; i<=n; i++){
            scanf("%d", a+i);
            b[1 - (i & 1)][i] = a[i];
            b[i & 1][i] = inf;
        }

        init(0);
        init(1);

        Q.push(Node(1, n));

        bool st = 0;
        while(!Q.empty()){
            if(st)  putchar(' ');
            st = 1;
            nd = Q.top(); Q.pop();

            if(nd.r == nd.l + 1){
                printf("%d %d", a[nd.l], a[nd.r]);
            } else {
                p = getfst(nd.l, nd.r);
                q = getsec(p, nd.r);
                printf("%d %d", a[p], a[q]);
                add(nd.l, p-1);
                add(p+1, q-1);
                add(q+1, nd.r);
            }
        }

        puts("");
    }
    return 0;
}

