signed main(){
	int N;
	cin >> N;
	vector<int>a(N);
	REP(i,N)cin >> a[i];
	auto odd = SegmentTree<pair<int,int>>(N,{INF,INF},[&](pair<int,int> a,pair<int,int> b){return min(a,b);});
	auto even = SegmentTree<pair<int,int>>(N,{INF,INF},[&](pair<int,int> a,pair<int,int> b){return min(a,b);});
	REP(i,N){
		if(i&1)odd.update(i,{a[i],i});
		else even.update(i,{a[i],i});
	}
	priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<pair<int,pair<int,int>>>>que;
	que.push({-INF,{0,N}});
	auto f = [&](int l,int r)->pair<int,pair<int,int>>{
		if(l & 1)return {odd.query(l,r).first,{l,r}};
		else return {even.query(l,r).first,{l,r}};
	};
	while(!que.empty()){
		auto q = que.top();
		que.pop();
		int l = q.second.first,r = q.second.second;
		if(l & 1){
			auto lid = odd.query(l,r);
			odd.update(lid.second,{INF,INF});
			auto rid = even.query(l,r);
