			if(lid.second - l >= 2)que.push(f(l,lid.second));
			if(rid.second - (lid.second + 1) >= 2)que.push(f(lid.second+1,rid.second));
			if(r - (rid.second + 1) >= 2)que.push(f(rid.second+1,r));
		}else{
			auto lid = even.query(l,r);
			even.update(lid.second,{INF,INF});
			auto rid = odd.query(lid.second,r);
			odd.update(rid.second,{INF,INF});
			ans.push_back({lid.first,rid.first});
			if(lid.second - l >= 2)que.push(f(l,lid.second));
			if(rid.second - (lid.second + 1) >= 2)que.push(f(lid.second+1,rid.second));
			if(r - (rid.second + 1) >= 2)que.push(f(rid.second+1,r));
		}
	}
	for(auto e:ans){
		cout << e.first << " " << e.second << " ";
	}
	cout << endl;
}

