template<typename T, typename E>
struct SegmentTree {
    using F = function<T(T, T)>;
    using G = function<T(T, E)>;
    using H = function<E(E, E)>;
    using P = function<E(E, size_t)>;
    int n;
    F f; //要素と要素のマージ
    G g; //要素に作用素を作用
    H h; //作用素と作用素をマージ
    T ti; //要素の単位元?
    E ei; //作用素の単位元?
    P p; //b個の作用素aをマージした場合
    vector<T> dat;
    vector<E> laz;

    SegmentTree(int n_, F f, G g, H h, T ti, E ei,
                P p = [](E a, size_t b) {
                    b++;
                    return a;
                }) :
            f(f), g(g), h(h), ti(ti), ei(ei), p(p) {
        init(n_);
    }

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat.assign(2 * n - 1, ti);
        laz.assign(2 * n - 1, ei);
    }

    void build(int n_, vector<T> v) {
        for (int i = 0; i < n_; i++) dat[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; i--)
            dat[i] = f(dat[i * 2 + 1], dat[i * 2 + 2]);
    }

    inline void eval(int len, int k) {
        if (laz[k] == ei) return;
        if (k * 2 + 1 < n * 2 - 1) {
            laz[k * 2 + 1] = h(laz[k * 2 + 1], laz[k]);
            laz[k * 2 + 2] = h(laz[k * 2 + 2], laz[k]);
        }
        dat[k] = g(dat[k], p(laz[k], len));
        laz[k] = ei;
    }

    T update(int a, int b, E x, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a || b <= l) return dat[k];
        if (a <= l && r <= b) {
            laz[k] = h(laz[k], x);
            return g(dat[k], p(laz[k], r - l));
        }
        return dat[k] = f(update(a, b, x, k * 2 + 1, l, (l + r) / 2),
                          update(a, b, x, k * 2 + 2, (l + r) / 2, r));
    }

    T update(int a, int b, E x) {
        return update(a, b, x, 0, 0, n);
    }

    T query(int a, int b, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a || b <= l) return ti;
        if (a <= l && r <= b) return dat[k];
        T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }

    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    T query(int a) {
        return query(a, a + 1, 0, 0, n);
    }

    /**
     * kをxに更新する
     */
    void update(int k, T x) {
        update(k, k + 1, x);
//        query(k,k+1);//evaluate
//        k+=n-1;
//        dat[k]=x;
//        while(k){
//            k=(k-1)/2;
//            dat[k]=f(dat[k*2+1],dat[k*2+2]);
//        }
    }
};


class Solve {
public:
    Int N;
    vector<Int> P;
    vector<Int> iP;

    auto make_indexTree() {
        using T = pair<int, int>; // value, time
        using E = pair<int, int>;
        auto f = [](T a, T b) {
            if (a.second > b.second) return a;
            else return b;
        }; // 要素と要素のマージ
        auto g = [](T a, E b) {
            if (a.second > b.second) return a;
            else return b;
        }; // 要素に作用素を作用
        auto h = [](E a, E b) {
            if (a.second > b.second) return a;
            else return b;
        }; // 作用素と作用素をマージ
        auto p = [](E a, int b) {
            return a;
        }; // 作用素を区間加算する場合
        T ti = make_pair(0, -1); //要素の単位元?
        E ei = make_pair(0, -1); //作用素の単位元?
        SegmentTree<T, E> treeone(N + 1, f, g, h, ti, ei, p);

        return treeone;
    }

    auto make_minTree() {
        using T = int;
        using E = int;
        auto f = [](T a, T b) { return min(a, b); }; // 要素と要素のマージ
        auto g = [](T a, E b) { return min(a, b); }; // 要素に作用素を作用
        auto h = [](E a, E b) { return min(a, b); }; // 作用素と作用素をマージ
        auto p = [](E a, int b) { return a; }; // 作用素を区間加算する場合
        T ti = INF; //要素の単位元?
        E ei = INF; //作用素の単位元?
        SegmentTree<T, E> treeone(N + 1, f, g, h, ti, ei, p);

        return treeone;
    }

    auto make_cntTree() {
        using T = int;
        using E = int;
        auto f = [](T a, T b) { return a + b; }; // 要素と要素のマージ
        auto g = [](T a, E b) { return a + b; }; // 要素に作用素を作用
        auto h = [](E a, E b) { return a + b; }; // 作用素と作用素をマージ
        auto p = [](E a, int b) { return a * b; }; // 作用素を区間加算する場合
        T ti = 0; //要素の単位元?
        E ei = 0; //作用素の単位元?
        SegmentTree<T, E> treeone(N + 1, f, g, h, ti, ei, p);

        return treeone;
    }

    void solve() {
        cin >> N;
        P.resize(N);
        iP.resize(N);

        for (int i = 0; i < N; ++i) {
            cin >> P[i];
            P[i]--;
            iP[P[i]] = i;
        }

        auto prevTree = make_indexTree();
        auto nextTree = make_indexTree();
        prevTree.update(0, N, make_pair(0, 0));
        nextTree.update(0, N, make_pair(N, 0));
        auto oddValue = make_minTree();
        auto evenValue = make_minTree();
        for (int i = 0; i < N; ++i) {
            if (i % 2 == 0) evenValue.update(i, i + 1, P[i]);
            if (i % 2 == 1) oddValue.update(i, i + 1, P[i]);
        }
        auto cntValue = make_cntTree();

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq; //value
        vector<bool> used(N, false);
        vector<Int> ans;

        if (true) {
            Int lvalue = evenValue.query(0, N);
            Int rvalue = oddValue.query(iP[lvalue] + 1, N);
            pq.emplace(lvalue, rvalue);
        }

        int time = 1;
        for (int i = 0; i < N / 2; ++i) {
            auto top = pq.top();
            pq.pop();
            ans.push_back(top.first);
            ans.push_back(top.second);
            used[iP[top.first]] = used[iP[top.second]] = true;

            vector<Int> begs;
            if (iP[top.second] - iP[top.first] > 1) {
                if (!used[iP[top.first] + 1]) {
                    begs.push_back(iP[top.first] + 1);
                }
            }

            // prevTreeの更新
            prevTree.update(iP[top.first], iP[top.second] + 1, make_pair(iP[top.first], time++));
            if (iP[top.second] + 1 < N) {
                prevTree.update(iP[top.second] + 1, nextTree.query(iP[top.second] + 1).first,
                                make_pair<int, int>(iP[top.second] + 1, time++));
                if (!used[iP[top.second] + 1]) {
                    begs.push_back(iP[top.second] + 1);
                }
            }


            // nextTreeの更新
            if (iP[top.first] - 1 >= 0) {
                nextTree.update(prevTree.query(iP[top.first] - 1).first, iP[top.first],
                                make_pair(iP[top.first], time++));
                if (!used[iP[top.first] - 1]) {
                    begs.push_back(iP[top.first] - 1);
                }
            }
            nextTree.update(iP[top.first] + 1, iP[top.second], make_pair(iP[top.second], time++));

            // cntValueの更新
            cntValue.update(iP[top.first], iP[top.second] + 1, 1);


            for (auto e : begs) {
                Int ldx = prevTree.query(e).first;
                Int rdx = nextTree.query(e).first;
                if (rdx - ldx < 2) continue;

                if (cntValue.query(ldx) % 2 == 0) {
                    Int lvalue = evenValue.query(ldx, rdx);
                    Int rvalue = oddValue.query(iP[lvalue] + 1, rdx);
                    pq.emplace(lvalue, rvalue);
                } else {
                    Int lvalue = oddValue.query(ldx, rdx);
                    Int rvalue = evenValue.query(iP[lvalue] + 1, rdx);
                    pq.emplace(lvalue, rvalue);
                }
            }
        }

        for (auto e : ans) {
            cout << e + 1 << " ";
        }
        cout << endl;
        return;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

