typedef pair<int,int> pii;
const int MAX = (2e5)+1;

int n, p[MAX];
vector<int> res;
map<pii, pair<pii, pii> > pq;

struct segment_tree {
	int a[MAX], t[2*MAX];
	void build() {
		for(int i = 0; i < n; i++) t[i + n] = i;
		for(int i = n-1; i >= 1; i--) {
			if(a[t[i<<1]] < a[t[i<<1|1]]) t[i] = t[i<<1];
			else t[i] = t[i<<1|1];
		}
	}
	void invalidate(int i) {
		a[i] = INT_MAX;
		for(i += n; i > 1; i >>= 1) {
			if(a[t[i]] < a[t[i^1]]) t[i>>1] = t[i];
			else t[i>>1] = t[i^1];
		}
	}
	int query(int l, int r) {
		int ret = l;
		++r;
		for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if(l & 1) {
				if(a[t[l]] < a[ret]) ret = t[l];
				++l;
			}
			if(r & 1) {
				--r;
				if(a[t[r]] < a[ret]) ret = t[r];
			}
		}
		return ret;
	}
} st[2];

pii getxy(int l, int r) {
	int xi = st[l % 2].query(l, r);
	int yi = st[l % 2 ^ 1].query(xi+1, r);
	return make_pair(xi, yi);
}

