// セグメントツリー (点変更・区間クエリ)
template <typename monoid>
struct segment_tree {
    using M = monoid;
    using T = typename M::value_type;

    size_t sz;
    vector<T> x;

    segment_tree(size_t n = 0) {
        sz = 1;
        while (sz < n) sz *= 2;
        x.assign(sz * 2, M::id());
        initialize();
    }

    template <typename iterator>
    segment_tree(iterator first, iterator last) {
        sz = 1;
        size_t n = distance(first, last);
        while (sz < n) sz *= 2;
        x.assign(sz * 2, M::id());
        copy(first, last, x.begin() + sz);
        initialize();
    }

    void fill(const T& val) {
        std::fill(x.begin() + sz, x.end(), val);
        initialize();
    }

    void initialize() {
        for (int i = (int)sz - 1; i >= 1; --i) {
            x[i] = M::op(x[i * 2 + 0], x[i * 2 + 1]);
        }
    }

    T accumulate(size_t l, size_t r) const {
        T al = M::id(), ar = M::id();
        for (l += sz, r += sz; l < r; l /= 2, r /= 2) {
            if (l & 1) al = M::op(al, x[l++]);
            if (r & 1) ar = M::op(x[--r], ar);
        }
        return M::op(al, ar);
    }

    void update(size_t i, const T &val) {
        x[i += sz] = val;
        while (i > 1) {
            x[i / 2] = M::op(x[i], x[i ^ 1]);
            i /= 2;
        }
    }

    T operator[](size_t i) const { return x[sz + i]; }
};

template <typename T>
struct min_monoid {
    using value_type = T;
    static constexpr T id() { lint INF = numeric_limits<lint>::max(); pair<lint, lint> ret{INF, INF}; return ret; }
    static T op(const T &a, const T &b) { return min(a, b); }
};

template <typename value_type>
using rmq = segment_tree<min_monoid<value_type>>;

int main(void) {
    lint n; cin >> n;
    vector<lint> p(n); repeat(i, n) cin >> p[i];

    const lint INF =  1e9;
    rmq<pair<lint, lint>> even(n), odd(n);
    repeat(i, n) {
        (i % 2 == 0 ? even : odd).update(i, {p[i], i});
        (i % 2 == 0 ? odd : even).update(i, {INF, i});
    }

    // [l, r) 内を調べる
    auto get_lr = [&](lint l, lint r) -> pair<pair<lint, lint>, pair<lint, lint>> {
        pair<lint, lint> nl, nr;
        if (l % 2 == 0) {
            nl = even.accumulate(l, r);
            nr = odd.accumulate(l, r);
        }
        else {
            nl = odd.accumulate(l, r);
            nr = even.accumulate(l, r);
        }
        return {nl, nr};
    };

    /*
    auto showpair = [](const pair<int, int> p) -> string {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ")";
    };
    */

    using tup = tuple<lint, lint, lint>;
    priority_queue<tup, vector<tup>, greater<tup>> que;

    que.push( tup{0LL, 0LL, n} );

    vector<lint> res;
    while (!que.empty()) {
        lint l, r;
        tie(ignore, l, r) = que.top();
        que.pop();

        auto a = get_lr(l, r);
        auto m1 = a.first;
        auto m2 = a.second;
        res.push_back(m1.first);
        res.push_back(m2.first);

        //dump(l); dump(r); cout << " m1=" << showpair(m1) << " m2=" << showpair(m2); vdump(res);

        if (l < m1.second) {
            auto b = get_lr(l, m1.second);
            que.push( tup{b.first.first, l, m1.second} );
            //cout << "push (" << b.first.first << ", " << l << ", " << m1.second << ")" << endl;
        }
        if (m1.second + 1 < m2.second) {
            auto b = get_lr(m1.second + 1, m2.second);
            que.push( tup{b.first.first, m1.second + 1, m2.second} );
            //cout << "push (" << b.first.first << ", " << m1.second + 1 << ", " << m2.second << ")" << endl;
        }
        if (m2.second + 1 < r) {
            auto b = get_lr(m2.second + 1, r);
            que.push( tup{b.first.first, m2.second + 1, r} );
            //cout << "push (" << b.first.first << ", " << m2.second + 1 << ", " << r << ")" << endl;
        }
    }

    repeat(i, n) {
        cout << res[i] << (i < n - 1 ? ' ' : '\n');
    }
}

