using namespace std;
inline int read()
{
	int x = 0, f = 1; char ch = getchar();
	while (ch < '0' || ch > '9') { if (ch == '-') f = -1; ch = getchar(); }
	while (ch >= '0' && ch <= '9') { x = x * 10 + ch - '0'; ch = getchar(); }
	return x * f;
}
const int M = 262144;
const int N = 1e6 + 10;
int n, a[N], L[N], R[N], ss[N];
bool fl[N];
pii ps[N];

pii mg(pii a,pii b)
{
	return pii(min(a.X, b.X), min(a.Y, b.Y));
}
int qr(int p)
{
	static int s1[800010],s2[800010];
	int n1 = 0, n2 = 0;
	for(int l = p + M - 1, r = n + M + 3; l ^ r ^ 1; l >>= 1, r >>= 1)
	{
		if(~l & 1) s1[++ n1] = l ^ 1;
		if(r & 1) s2[++ n2] = r ^ 1;
	}
	while(n2) s1[++ n1] = s2[n2 --];
	int g;
	rep(i, 1, n1)
		if(ss[s1[i]]) {g = s1[i]; break;}
	while(g < M)
	{
		if(ss[g + g]) g = g + g;
		else g = g + g + 1;
	}
	return R[g] - 1;
}
void Clear(int x)
{
	for(x += M; x; x >>= 1) ss[x] = 1;
}
void build()
{
	rep(i, 1, M) L[i + M] = R[i + M] = i;
	rep(i, 1, n)
		if((n - i) & 1) ps[i + M] = pii(a[i], 1e9);
		else ps[i + M] = pii(1e9, a[i]);
	rrep(i, M - 1, 1)
		L[i] = L[i + i], R[i] = R[i + i + 1],
		ps[i] = mg(ps[i + i], ps[i + i + 1]);
}
void pd(int x)
{
	if(fl[x])
	{
		swap(ps[x].X, ps[x].Y);
		if(x <= M) fl[ls] ^= 1, fl[rs] ^= 1;
		fl[x] = 0;
	}
}
void Push_down(int x)
{
	pd(ls);
	pd(rs);
	ps[x] = mg(ps[ls], ps[rs]);
}
pii Query(int x,int l,int r)
{
	if(R[x] < l || r < L[x]) return pii(1e9,1e9);
	pd(x);
	if(l <= L[x] && R[x] <= r) return ps[x];
	pii t = mg(Query(ls, l, r), Query(rs, l, r));
	Push_down(x);
	return t;
}
void Del(int p)
{
	int x = 1;
	while(1)
	{
		pd(x);
		if(x > M) break;
		if(p <= R[ls]) x = ls;
		else x = rs;
	}
	ps[x] = pii(1e9, 1e9);
	for(x >>= 1; x; x >>= 1) ps[x] = mg(ps[ls], ps[rs]);
}
void Upd(int x,int l,int r)
{
	if(R[x] < l || r < L[x]) return;
	pd(x);
	if(l <= L[x] && R[x] <= r) {fl[x] ^= 1; return;}
	Upd(ls, l, r);
	Upd(rs, l, r);
	Push_down(x);
}
int ans[N], cnt, rv[N];
int main()
{
	n = read();
	rep(i, 1, n)
		a[i] = read(), rv[a[i]] = i;
	build();
	Clear(n + 1);
	while(cnt < n)
	{
		int x = rv[Query(1, 1, n).X], t = qr(x);
		int y = rv[Query(1, x, t).Y];
		ans[++ cnt] = a[x];
		ans[++ cnt] = a[y];
		Upd(1, x, y);
		Del(x);
		Del(y);
		Clear(x);
		Clear(y);
	}
	rep(i, 1, cnt) printf("%d ",ans[i]);
	return 0;
}

