typedef pair<int,int> P;
const int MAX_N=2e5;
int N,p[MAX_N+1],N2;
P ma[MAX_N<<2],mi[MAX_N<<2];
bool laz[MAX_N<<2];
int ans[MAX_N];
P query(int l,int r,int f,int k=0,int a=0,int b=N2){
	if (r<=a || b<=l){
		return P(0,N);
	}
	if (laz[k]){
		laz[k]=false;
		if (b-a==1){
			ma[k].first*=-1;
			mi[k].first*=-1;
		}else{
			laz[k*2+1]^=true;
			laz[k*2+2]^=true;
			swap(ma[k],mi[k]);
			ma[k].first*=-1;
			mi[k].first*=-1;
		}
	}
	if (l<=a && b<=r){
		if (f==0){
			return ma[k];
		}else{
			return mi[k];
		}
	}
	P ln=query(l,r,f,k*2+1,a,(a+b)/2),rn=query(l,r,f,k*2+2,(a+b)/2,b);
	P ret;
	if (f==0){
		ret=max(ln,rn);
	}else{
		ret=min(ln,rn);
	}
	return ret;
}
void mul(int l,int r,int k=0,int a=0,int b=N2){
	if (r<=a || b<=l){
		return;
	}
	if (l<=a && b<=r){
		laz[k]^=true;
		return;
	}
	mul(l,r,k*2+1,a,(a+b)/2);
	mul(l,r,k*2+2,(a+b)/2,b);
	query(a,(a+b)/2,0,k*2+1,a,(a+b)/2);
	query((a+b)/2,b,1,k*2+2,(a+b)/2,b);
	ma[k]=max(ma[k*2+1],ma[k*2+2]);
	mi[k]=min(mi[k*2+1],mi[k*2+2]);
}
void update(int inx,int k=0,int a=0,int b=N2){
	if (inx<a || b<=inx){
		return;
	}
	if (laz[k]){
		laz[k]=false;
		if (b-a==1){
			ma[k].first*=-1;
			mi[k].first*=-1;
		}else{
			laz[k*2+1]^=true;
			laz[k*2+2]^=true;
			swap(ma[k],mi[k]);
			ma[k].first*=-1;
			mi[k].first*=-1;
		}
	}
	if (a+1==b){
		ma[k]=mi[k]=P(0,N);
	}else{
		update(inx,k*2+1,a,(a+b)/2);
		update(inx,k*2+2,(a+b)/2,b);
		query(a,(a+b)/2,0,k*2+1,a,(a+b)/2);
		query((a+b)/2,b,1,k*2+2,(a+b)/2,b);
		ma[k]=max(ma[k*2+1],ma[k*2+2]);
		mi[k]=min(mi[k*2+1],mi[k*2+2]);
	}		
}
int bit[MAX_N+1];
void add(int x){
	while(x<=N){
		bit[x]++;
		x+=x&(-x);
	}
}
int smq(int x){
	int ret=0;
	while(x){
		ret+=bit[x];
		x-=x&(-x);
	}
	return ret;
}
int main(){
	cin>>N;
	REP(i,N){
		cin>>p[i];
		p[i]=N+1-p[i];
	}
	p[N]=0;
	N2=1;
	while(N2<N){
		N2<<=1;
	}
	REP(i,N2){
		if (i<N){
			ma[N2+i-1]=mi[N2+i-1]=P(p[i],i);
			if (i%2){
				ma[N2+i-1].first*=-1;
				mi[N2+i-1].first*=-1;
			}
		}else{
			ma[N2+i-1]=mi[N2+i-1]=P(0,N);
		}
	}
	REP(i,N2-1){
		int inx=N2-i-2;
		int l=inx*2+1,r=inx*2+2;
		ma[inx]=max(ma[l],ma[r]);
		mi[inx]=min(mi[l],mi[r]);
	}
	REP(i,N>>1){
		P p1=query(0,N2,0);
		ans[i*2]=N+1-p[p1.second];
		int lb=p1.second+1,ub=N+1;
		int sm1=smq(lb);
		while(ub-lb>1){
			int mid=(lb+ub)>>1;
			int sm=smq(mid);
			if (sm==sm1){
				lb=mid;
			}else{
				ub=mid;
			}
		}
		P p2=query(p1.second,lb,1);
		ans[i*2+1]=N+1-p[p2.second];
		mul(p1.second,p2.second);

		update(p1.second);
		update(p2.second);
		add(p1.second+1);
		add(p2.second+1);
	}
	REP(i,N){
		if (i){
			cout<<" ";
		}
		cout<<ans[i];
	}
	cout<<endl;
	return 0;
}

