	rep(i,n) cin>>v[i], v[i]--;
	vint rank(n);
	rep(i,n) rank[v[i]] = i;
	vint odd(n, INF);
	vint even(n, INF);
	int mn = INF;
	rep(i,n){
		if(i&1) odd[i] = v[i];
		else even[i] = v[i],mins(mn, v[i]);
	}
	RMQ<int> oRMQ(odd);
	RMQ<int> eRMQ(even);
	using P = pair<int,pii>;
	priority_queue<P> pq;
	pq.push(mkp(-mn, pii(0,n-1)));
	vint ans;
	while(pq.size()){
		int val1;
		pii seg;
		tie(val1, seg) = pq.top();
		pq.pop();
		val1 *= -1;
		// cout<<val1<<" "<<seg.fi<<" "<<seg.se<<endl;
		int pos1 = rank[val1];
		int val2;
		if(seg.fi&1){
			val2 = eRMQ.query(pos1, seg.se);
		}
		else{
			val2 = oRMQ.query(pos1, seg.se);
		}
		int pos2 = rank[val2];
		// cout<<"val "<<val1<<" "<<val2<<endl;
		// cout<<"pos "<<pos1<<" "<<pos2<<endl;
		ans.PB(val1);
		ans.PB(val2);
		if(seg.fi != pos1){
			P tmp;
			tmp.se = pii(seg.fi, pos1-1);
			tmp.fi = -(tmp.se.fi%2==0?eRMQ.query(tmp.se.fi, tmp.se.se): oRMQ.query(tmp.se.fi, tmp.se.se));
			pq.push(tmp);
		}
		if(pos1+1 != pos2){
			P tmp;
			tmp.se = pii(pos1+1, pos2-1);
			tmp.fi = -(tmp.se.fi%2==0?eRMQ.query(tmp.se.fi, tmp.se.se): oRMQ.query(tmp.se.fi, tmp.se.se));
			pq.push(tmp);	
		}
		if(pos2 != seg.se){
			P tmp;
			tmp.se = pii(pos2+1, seg.se);
			tmp.fi = -(tmp.se.fi%2==0?eRMQ.query(tmp.se.fi, tmp.se.se): oRMQ.query(tmp.se.fi, tmp.se.se));
			pq.push(tmp);
		}
	}
	rep(i,n){
		if(i) cout<<" ";
		cout<<ans[i]+1;
	}
	cout<<endl;
}


