using namespace std;

const int MAXN = 200000 + 1000;
const int MAXK = 20;


int n, p[MAXN];
pair<int, int> rmq[MAXN][MAXK];
vector<int> ans;

pair<int, int> query(int l, int r)
{
	if((r - l + 1) & 1) r++;
	// cerr << l << ' '<< r << endl;
	int k = log2(r - l + 1);
	// cerr << k << endl;
	return min(rmq[l][k], rmq[r - (1 << k) + 1][k]);
}

struct State
{
	pair<int, int> v;
	int l, r;
	State(int _l = 0, int _r = 0) : v(query(_l, _r)), l(_l), r(_r)
	{}
	bool operator < (const State &s) const
	{
		return v > s.v;
	}
};
priority_queue<State> pq;

int main()
{
	ios::sync_with_stdio(false);
	// freopen("1.in", "r", stdin);
	// freopen("1.out", "w", stdout);

	cin >> n;
	for(int i = 0; i < n; i++)
		cin >> p[i];
	for(int i = 0; i < n; i++)
		rmq[i][0] = rmq[i][1] = make_pair(p[i], i);
	for(int j = 2; j < MAXK; j++)
		for(int i = 0; i + (1 << (j - 1)) < n; i++)
			rmq[i][j] = min(rmq[i][j - 1], rmq[i + (1 << (j - 1))][j - 1]);

	pq.push(State(0, n - 1));

	while(!pq.empty())
	{
		State s = pq.top();
		pq.pop();
		int p0 = s.v.second, l = s.l, r = s.r;
		int p1 = query(p0 + 1, r).second;
		ans.push_back(p[p0]);
		ans.push_back(p[p1]);
		if(l <= p0 - 1) pq.push(State(l, p0 - 1));
		if(p0 + 1 <= p1 - 1) pq.push(State(p0 + 1, p1 - 1));
		if(p1 + 1 <= r)	pq.push(State(p1 + 1, r));
	}
	for(int i = 0; i < n; i++)
		cout << ans[i] << ' ';
	cout << endl;

	return 0;
}

