    }
    segtree<int>seg1(a),seg2(b);
    vector<int>ans;
    priority_queue<dat>pq;
    pq.push({0,n-1,seg2.query(0,n-1).first});
    rep(_,n/2){
        auto x = pq.top();
        pq.pop();
        ans.push_back(x.v);
        int hoge = (x.l%2 ? seg1 :seg2).query(x.l,x.r+1).second;
        (x.l%2 ? seg1 :seg2).update(hoge,INT_MAX/2);
        auto p = (x.l%2 ? seg2 : seg1).query(hoge,x.r+1);
