#define pp 131072

set< pair<int,int> > prt;
int su[300001];
int tree[2][pp*2];
int n;
pair<int,int> seq[300001];
priority_queue< pair<int,int>, vector< pair<int,int> >, greater< pair<int,int> > > pq;

int upd(int ww, int idx, int vall){
    idx += pp;
    tree[ww][idx] = vall;
    idx /= 2;
    while(idx){
        tree[ww][idx] = min(tree[ww][idx*2], tree[ww][idx*2+1]);
        idx >>= 1;
    }
}

int gett(int ww, int ss, int ee){
    //printf("gett: %d %d %d ", ww, ss, ee);
    int ans = n + 100;
    ss += pp; ee += pp;
    while(ss <= ee){
        if(ss%2 == 1){
            ans = min(ans, tree[ww][ss++]);
        }else if(ee%2 == 0){
            ans = min(ans, tree[ww][ee--]);
        }
        if(ss>ee) break;
        ss >>= 1; ee >>= 1;
    }
    //printf(": %d\n", ans);
    return ans;
}

pair<int,int> getBest(int ss, int ee){
    int target1 = gett(ss%2, ss/2, (ee-1)/2);
    int t1 = seq[target1-1].second;
    //printf("%d\n", t1);
    int target2 = gett((t1+1)%2, (t1+1)/2, ee/2);
    return make_pair(target1, target2);
}

int main(){
    scanf("%d",&n);
    for(int i=0;i<pp*2;i++) tree[0][i] = tree[1][i] = n+100;
    for(int i=0;i<n;i++){
        scanf("%d",&su[i]);
        seq[i] = {su[i], i};
        upd(i%2,i/2,su[i]);
    }
    prt.insert({0, n-1});
    sort(seq, seq + n);
    pq.push(getBest(0, n-1));
    while(!pq.empty()){
        pair<int,int> target = pq.top(); pq.pop();
        printf("%d %d ", target.first, target.second);
        int pl1 = seq[target.first-1].second;
        int pl2 = seq[target.second-1].second;
        upd(pl1%2, pl1/2, n+100);
        upd(pl2%2, pl2/2, n+100);
        auto it = prt.upper_bound({pl1, n+100});
        it--;
        prt.erase(it);
        int ss = (*it).first;
        int ee = (*it).second;
        //printf("%d %d %d %d\n",ss, pl1, pl2, ee);
        if(ss < pl1-1){
            prt.insert({ss, pl1-1});
            pq.push(getBest(ss, pl1-1));
        }
        if(pl1+1 < pl2-1){
            prt.insert({pl1+1, pl2-1});
            pq.push(getBest(pl1+1, pl2-1));
        }
        if(pl2+1 < ee){
            prt.insert({pl2+1, ee});
            pq.push(getBest(pl2+1, ee));
        }
    }
    printf("\n");
}

