const int DEPTH = 18;
const int NUM_ELEMS = 1 << DEPTH;

pii evenragetree[2 * NUM_ELEMS];
pii oddragetree[2 * NUM_ELEMS];

inline pii getEven(int idx) {
  return evenragetree[idx];
}
inline pii getOdd(int idx) {
  return oddragetree[idx];
}

void build(int idx) {
  assert(idx >= NUM_ELEMS);
  idx /= 2;
  while(idx) {
    evenragetree[idx] = min(getEven(2*idx), getEven(2*idx+1));
    oddragetree[idx] = min(getOdd(2*idx), getOdd(2*idx+1));
    idx /= 2;
  }
}

pii minEven(int l, int r) {
  pii ret = {1e9, -1};
  l += NUM_ELEMS;
  r += NUM_ELEMS;
  while(l <= r) {
    if(l == r) {
      ret = min(ret, evenragetree[l]);
      break;
    }
    if(l%2) {
      ret = min(ret, evenragetree[l]);
      l++;
    }
    if(r%2 == 0) {
      ret = min(ret, evenragetree[r]);
      r--;
    }
    l /= 2;
    r /= 2;
  }
  return ret;
}

pii minOdd(int l, int r) {
  pii ret = {1e9, -1};
  l += NUM_ELEMS;
  r += NUM_ELEMS;
  while(l <= r) {
    if(l == r) {
      ret = min(ret, oddragetree[l]);
      break;
    }
    if(l%2) {
      ret = min(ret, oddragetree[l]);
      l++;
    }
    if(r%2 == 0) {
      ret = min(ret, oddragetree[r]);
      r--;
    }
    l /= 2;
    r /= 2;
  }
  return ret;
}

void upd(int idx, int val) {
  if(idx % 2) oddragetree[idx + NUM_ELEMS] = {val, idx};
  else evenragetree[idx + NUM_ELEMS] = {val, idx};
  idx += NUM_ELEMS;
  build(idx);
}

int n;
void solve(vector<pii>& ret, int l, int r) {
  if(l >= r) return;
  pii ff, ss;
  if(l%2) {
    ff = minOdd(l, r);
    ss = minEven(ff.second+1, r);
  }
  else {
    ff = minEven(l, r);
    ss = minOdd(ff.second+1, r);
  }
  ret.push_back({ff.first, ss.first});
  vector<pii> a, b, c;
  solve(a, l, ff.second - 1);
  solve(b, ff.second + 1, ss.second-1);
  solve(c, ss.second+1, r);
  int aa = 0;
  int bb = 0;
  int cc = 0;
  while(aa < a.size() || bb < b.size() || cc < c.size()) {
    if(aa < a.size() && (bb == b.size() || a[aa] < b[bb]) && (cc == c.size() || a[aa] < c[cc])) {
      ret.push_back(a[aa++]);
    }
    else if(bb < b.size() && (cc == c.size() || b[bb] < c[cc])) {
      ret.push_back(b[bb++]);
    }
    else {
      ret.push_back(c[cc++]);
    }
  }
}
