  }
  for(int i = 0; i < n; i++) {
    int t;
    cin >> t;
    upd(i, t);
  }
  vector<pii> ret;
  solve(ret, 0, n-1);
  for(auto out: ret) cout << out.first << " " << out.second << " "; cout << "\n";
}

