        vector<int> ans;
        while(!pq.empty()){
            tie(a,b,s,t,g)=pq.top();pq.pop();
            ans.emplace_back(a);ans.emplace_back(b);
            l=f[a],r=f[b];
            if(g){
                if(s!=l) a=e.gt(s,l),pq.emplace(a,o.gt(f[a]+1,l+1),s,l,true);
                if(l+1!=r) a=o.gt(l+1,r),pq.emplace(a,e.gt(f[a],r),l+1,r,false);
                if(r!=t) a=e.gt(r,t),pq.emplace(a,o.gt(f[a]+1,t+1),r,t,true);
            }
            else{
                if(s!=l) a=o.gt(s,l),pq.emplace(a,e.gt(f[a],l),s,l,false);
                if(l!=r) a=e.gt(l,r),pq.emplace(a,o.gt(f[a]+1,r+1),l,r,true);
                if(r+1!=t) a=o.gt(r+1,t),pq.emplace(a,e.gt(f[a],t),r+1,t,false);
            }
        }
        for(auto i:ans) out<<i<<" ";
        out<<endl;
    }
};

