int main()
{
    int N;
    cin >> N;
    vector<int> p(N);
    REP(i, N) cin >> p[i];

    vector<int> q;
    for (int loop = 0; loop < N / 2; loop++) {
        //Step1:奇数番目のものから最小のものを取り出す
        int min_value = N + 1, min_index = 0, num = 1;
        for (int i = 0; i < N; i++) {
            if (p[i] == N + 1)
                continue;

            if (num % 2 == 1) {
                if (min_value > p[i]) {
                    min_value = p[i];
                    min_index = i;
                }
            }
            num++;
        }
        q.push_back(min_value);
