        min_value = N + 1;
        for (int i = min_index + 1; i < N; i += 2) {
            if (p[i] == N + 1)
                break;

            if (min_value > p[i]) {
                min_value = p[i];
                min_index = i;
            }
        }
        q.push_back(min_value);
        p[min_index] = N + 1;
    }

    REP (i, N)
        printf("%d ", q[i]);
    printf("\n");
