            mn[v][i][j]=min(mn[v][i][j-1],mn[v][i+(1<<(j-1))][j-1]);
}
int hp(int l,int r,int v){
    int k=0;
    while((1<<(k+1))<=r-l+1)	k++;
    return min(mn[v][l][k],mn[v][r-(1<<k)+1][k]);
}
