const int INF=1e9;

int n,m=1;
int a[800005];
int g[2][800005];
int ans[200005];


void update(int k){
	int odd,pos=k;
	odd=k%2;
	k+=m-1;
	g[odd][k]=pos;
	g[(odd+1)%2][k]=INF;
	while(k>1){
		k/=2;
		for(int i=0;i<2;i++){
			if(g[i][k*2]==INF&&g[i][k*2+1]!=INF) g[i][k]=g[i][k*2+1];
			else if(g[i][k*2+1]==INF&&g[i][k*2]!=INF) g[i][k]=g[i][k*2];
			else if(g[i][k*2]!=INF&&g[i][k*2+1]!=INF){
				if(a[g[i][k*2]]<a[g[i][k*2+1]]) g[i][k]=g[i][k*2];
				else g[i][k]=g[i][k*2+1];
			}
		}
	}
}

int rmq(int l,int r,int k,int l1,int r1){
	int odd=l%2;
	if(l<=l1&&r>=r1) return g[odd][k];
	if(r<l1||l>r1) return INF;
	else{
		int x=rmq(l,r,k*2,l1,(l1+r1)/2),y=rmq(l,r,k*2+1,(l1+r1+1)/2,r1);
		if(x==INF&&y!=INF) return y;
		else if(x!=INF&&y==INF) return x;
		else if(x==INF&&y==INF) return INF;
		else{
			if(a[x]<a[y]) return x;
			else return y;
		}
	}
}

struct range{
	int a,b;
	int mint;
};

bool operator>(const range &x,const range &y){
	if(x.mint!=INF&&y.mint!=INF)return a[x.mint]>a[y.mint];
	else if(x.mint==INF&&y.mint!=INF) return true;
	else if(x.mint!=INF&&y.mint==INF) return false;
	else return true;
}


int main(){
	scanf("%d",&n);
	fill(a,a+800005,INF);
	fill(g[0],g[0]+800005,INF);
	fill(g[1],g[1]+800005,INF);
	while(m<n) m*=2;
	for(int i=1;i<=n;i++) {
		scanf("%d",a+i);
	}
	for(int i=1;i<=m;i++){
		update(i);
	}
	priority_queue<range,vector<range>,greater<range> > pq;
	range init={1,n,rmq(1,n,1,1,m)};
	pq.push(init);
	int id=1;
	while(id<=n&&!pq.empty()){
		range f=pq.top();
		pq.pop();
		ans[id++]=f.mint;
		range forw,bacw={f.mint+1,f.b,rmq(f.mint+1,f.b,1,1,m)};
		if(f.a<f.mint-1){
			forw={f.a,f.mint-1,rmq(f.a,f.mint-1,1,1,m)};
			pq.push(forw);
		}
		ans[id++]=bacw.mint;
		range sec,thir;
		if(bacw.a<bacw.mint-1){
			sec={bacw.a,bacw.mint-1,rmq(bacw.a,bacw.mint-1,1,1,m)};
			pq.push(sec);
		}
		if(bacw.mint+1<bacw.b){
			thir={bacw.mint+1,bacw.b,rmq(bacw.mint+1,bacw.b,1,1,m)};
			pq.push(thir);
		}
	}
	for(int i=1;i<=n;i++){
		if(i>1) printf(" ");
		printf("%d",a[ans[i]]);
	}
	printf("\n");
return 0;
}

