const int maxn = 2e5 + 5;
const int mod = 1e9 + 7;
int n, a[maxn];
struct IT{
    ii s[maxn*4];
    void Build(int x , int l , int r , bool delta){
        if(l == r){
            s[x] = mp(a[l] , l);
            if((l & 1) != delta)s[x].first = 1e9;
            return;
        }
        int mid = l + r >> 1;
        Build(x*2,l,mid,delta);
        Build(x*2+1,mid+1,r,delta);
        s[x] = min(s[x * 2] , s[x * 2 + 1]);
    }
    ii Query(int x , int l , int r , int L ,int R){
        if(L > r || l > R){
            return mp(1e9,0);
        }
        if(L <= l && r <= R)return s[x];
        int mid = l + r >> 1;
        return min(Query(x*2,l,mid,L,R),Query(x*2+1,mid+1,r,L,R));
    }
}s[2];
int id[maxn];
