        assert(!((r - l + 1) & 1));
        if(l > r)return mp(mp((int)1e9,(int)1e9),mp(l,r));
        auto tmp = s[(l & 1)].Query(1,1,n,l,r);
        return mp(mp(tmp.first,s[!(l & 1)].Query(1,1,n,tmp.second,r).first),mp(l,r));
    };
    priority_queue<pair<ii,ii>,vector<pair<ii,ii>>,greater<pair<ii,ii>>> pq;
    pq.push(Cal(1,n));
