  for (int i = 1; i < N; i += 2) update2((i-1)/2, p[i]); 

  vector<int> ans;
  map<int, pii> segmap;
  priority_queue<pii, vector<pii> ,greater<pii> > pque;
  pii fmi = query(0, N/2, 0, 0, n);
