        if (pos<l || pos>r) return;
        if (l==pos && pos==r) {
            st[id] = min(st[id], val);
            return;
        }
        int mid = (l+r)/2;
        update(pos, val, l, mid, id*2);
        update(pos, val, mid+1, r, id*2+1);
        st[id] = min(st[id*2], st[id*2+1]);
    }

    ii get(int u, int v, int l=1, int r=n, int id=1) {
        if (u>r || v<l) return ii(inf, inf);
        if (u<=l && r<=v) return st[id];
        int mid = (l+r)/2;
        return min(get(u, v, l, mid, id*2), get(u, v, mid+1, r, id*2+1));
    }
} b[2];

