void divideInterval(P1 id,int i,int j){
    P1 tmp = id;
    if(i>N||j>N)while(1);
    minInterval.push(P2(seg[tmp.first%2].query(tmp.first,i,0,0,seg[0].n).first,P1(tmp.first,i)));
    minInterval.push(P2(seg[(i+1)%2].query(i+1,j,0,0,seg[0].n).first,P1(i+1,j)));
    minInterval.push(P2(seg[(j+1)%2].query(j+1,tmp.second,0,0,seg[0].n).first,P1(j+1,tmp.second)));
}

