void init(int id, int m){
    memset(st[id], 0, sizeof(st[id]));
    a[id][0] = 1e9;
    for(int i = 1;i <= m;i++){
        st[id][i][0] = i;
    }
    for(int j = 1;(1 << j) <= m;j++){
        for(int i = 1;i + j - 1 <= m;i++){
            if(a[id][st[id][i][j - 1]] < a[id][st[id][i + (1 << (j - 1))][j - 1]]){
                st[id][i][j] = st[id][i][j - 1];
            }else{
                st[id][i][j] = st[id][i + (1 << (j - 1))][j - 1];
            }
        }
    }
}

int query(int id, int l, int r){
    int len = r - l + 1;
    int k = 31 - __builtin_clz(len);
    if(a[id][st[id][l][k]] < a[id][st[id][r - (1 << k) + 1][k]]){
        return st[id][l][k];
    }else{
        return st[id][r - (1 << k) + 1][k];
    }
}

struct node{
    int l, r;
    LL id;
    LL val;
    node(int l=0, int r=0, LL val=0, LL id=0):l(l), r(r), val(val), id(id){}
    bool operator < (const node & rhs) const{
        return val > rhs.val;
    } 
};

int q[maxn];
int tot;

int query1(int l, int r){
    int tmp = query(l & 1, (l + 1) / 2, (r + (l & 1)) / 2);
    if(l & 1){
        tmp = tmp * 2 - 1;
    }else{
        tmp = tmp * 2;
    }
    return tmp; 
}

pair<int, int> Query(int l, int r){
    int first = query1(l, r);
    int second = query1(first + 1, r);
    return make_pair(first, second);
}

