        node now = *s.begin();
        s.erase(s.begin());
        int l = now.l, r = now.r;
        int lmid = now.v, rmid = ask((lmid & 1) ^ 1, 1, 1, n, lmid, r);
        printf("%d %d ", a[lmid], a[rmid]);
        s.insert(node(l, lmid - 1));
        s.insert(node(lmid + 1, rmid - 1));
        s.insert(node(rmid + 1, r));
    }
    puts("");
    return 0;
}

