template<class T>
struct SegTree
{
	lint n;
	vector<T> t;
	T neutral;

	SegTree(lint _n, const T& _neutral) : neutral(_neutral)
	{
		n = 1;
		while (n < _n)
		{
			n *= 2;
		}
		rep(i, n)
		{
			t.resize(2 * n, neutral);
		}
	}

	using funcT = T(T val1, T val2);
	funcT* un;

	void update(lint i, const T& val)
	{
		i += n - 1;
		t[i] = val;
		while (i > 0)
		{
			i = (i - 1) / 2;
			t[i] = un(t[i * 2 + 1], t[i * 2 + 2]);
		}
	}

	T query_impl(lint a, lint b, lint k, lint l, lint r)
	{
		if (r <= a || b <= l)
			return neutral;
		if (a <= l && r <= b)
			return t[k];
		else
		{
			const T c1 = query_impl(a, b, 2 * k + 1, l, (l + r) / 2);
			const T c2 = query_impl(a, b, 2 * k + 2, (l + r) / 2, r);
			return un(c1, c2);
		}
	}

	T query(lint l, lint r)
	{
		return query_impl(l, r, 0, 0, n);
	}

};

int main()
{
	lint n;
	cin >> n;
	vec p(n);
	rep(i, n)
		cin >> p[i];

	set<lint> zp;
	zp.insert(0);
	zp.insert(n);

	SegTree<xy> tra(n, xy(-1, inf)), trb(n, xy(-1, inf));
	tra.un = [](xy p, xy q)
	{
		lint ps = p.x, qs = q.x;

		xy ans{ -1,inf };

		if (ps % 2 == 0)
		{
			if (p.y < ans.y)
				ans = p;
		}
		if (qs % 2 == 0)
		{
			if (q.y < ans.y)
				ans = q;
		}

		return ans;
	};
	trb.un = [](xy p, xy q)
	{
		lint ps = p.x, qs = q.x;

		xy ans{ -1,inf };

		if (ps % 2 == 1)
		{
			if (p.y < ans.y)
				ans = p;
		}
		if (qs % 2 == 1)
		{
			if (q.y < ans.y)
				ans = q;
		}

		return ans;
	};
	rep(i, n)
	{
		tra.update(i, xy(i, p[i]));
		trb.update(i, xy(i, p[i]));
	}

	vec ans;

	rep(i, n / 2)
	{
		xy a1{ -1,inf }, a2{ -1,inf };
		lint s = 0, ms;

		auto it = zp.begin(), it2 = it;
		it2++;
		while (it2 != zp.end())
		{
			xy aa;
			if (s == 0)
			{
				aa = tra.query(*it, *it2);
			}
			else
			{
				aa = trb.query(*it, *it2);
			}
			if (aa.y < a1.y)
			{
				ms = s;
				a1 = aa;
			}

			++s %= 2;
			it = it2;
			it2++;
		}

		it2 = zp.upper_bound(a1.x);
		it = it2;
		it--;
		if (ms == 0)
			a2 = trb.query(*it, *it2);
		else
			a2 = tra.query(*it, *it2);

		ans.push_back(a1.y);
		ans.push_back(a2.y);

		zp.insert(a1.x + 1);
		zp.insert(a2.x + 1);
		tra.update(a1.x, xy{ -1, inf });
		trb.update(a1.x, xy{ -1, inf });
		tra.update(a2.x, xy{ -1, inf });
		trb.update(a2.x, xy{ -1, inf });
	}

	rep(i, n)
		cout << ans[i] << spacel(i, n);

	return 0;
}

