template <typename Monoid>
struct RMQ {
  RMQ(int sz, const Monoid UNITY) : UNITY(UNITY) {
    init(sz);
    dat.assign((n << 1) - 1, UNITY);
  }

  RMQ(const vector<Monoid> &a, const Monoid UNITY) : UNITY(UNITY) {
    int a_sz = a.size();
    init(a_sz);
    dat.resize((n << 1) - 1);
    REP(i, a_sz) dat[n - 1 + i] = a[i];
    for (int i = n - 2; i >= 0; --i) dat[i] = min(dat[(i << 1) + 1], dat[(i << 1) + 2]);
  }

  void update(int node, Monoid val) {
    node += n - 1;
    dat[node] = val;
    while (node > 0) {
      node = (node - 1) >> 1;
      dat[node] = min(dat[(node << 1) + 1], dat[(node << 1) + 2]);
    }
  }

  Monoid query(int a, int b) { return query(a, b, 0, 0, n); }

  int find(int a, int b, Monoid val) { return find(a, b, val, 0, 0, n); }

  Monoid operator[](const int idx) const { return dat[idx + n - 1]; }

private:
  int n = 1;
  const Monoid UNITY;
  vector<Monoid> dat;

  void init(int sz) { while (n < sz) n <<= 1; }

  Monoid query(int a, int b, int node, int left, int right) {
    if (right <= a || b <= left) return UNITY;
    if (a <= left && right <= b) return dat[node];
    return min(query(a, b, (node << 1) + 1, left, (left + right) >> 1), query(a, b, (node << 1) + 2, (left + right) >> 1, right));
  }

  int find(int a, int b, Monoid val, int node, int left, int right) {
    if (dat[node] > val || right <= a || b <= left) return -1;
    if (right - left == 1) return node - (n - 1);
    int res_l = find(a, b, val, (node << 1) + 1, left, (left + right) >> 1);
    if (res_l != -1) return res_l;
    return find(a, b, val, (node << 1) + 2, (left + right) >> 1, right);
  }
};

int main() {
  int n; cin >> n;
  vector<int> p(n); REP(i, n) cin >> p[i];
  RMQ<int> even(p, INF), odd(p, INF);
  for (int i = 1; i < n; i += 2) even.update(i, INF);
  for (int i = 0; i < n; i += 2) odd.update(i, INF);
  vector<int> ans;
  using P = pair<int, pair<int, int>>;
  priority_queue<P, vector<P>, greater<P>> que;
  que.emplace(even.query(0, n), make_pair(0, n));
  while (!que.empty()) {
    int l, r; tie(l, r) = que.top().second; que.pop();
    int x, x_idx, y, y_idx;
    if (l & 1) {
      x = odd.query(l, r); x_idx = odd.find(l, r, x);
      y = even.query(x_idx, r); y_idx = even.find(x_idx, r, y);
    } else {
      x = even.query(l, r); x_idx = even.find(l, r, x);
      y = odd.query(x_idx, r); y_idx = odd.find(x_idx, r, y);
    }
    ans.emplace_back(x);
    ans.emplace_back(y);
    if (l < x_idx) que.emplace(l & 1 ? odd.query(l, x_idx) : even.query(l, x_idx), make_pair(l, x_idx));
    if (x_idx + 1 < y_idx) que.emplace((x_idx + 1) & 1 ? odd.query(x_idx + 1, y_idx) : even.query(x_idx + 1, y_idx), make_pair(x_idx + 1, y_idx));
    if (y_idx + 1 < r) que.emplace((y_idx + 1) & 1 ? odd.query(y_idx + 1, r) : even.query(y_idx + 1, r), make_pair(y_idx + 1, r));
  }
  REP(i, n) cout << ans[i] << " \n"[i + 1 == n];
  return 0;
}

