//区間の最小値をインデックス付きで求めてくれるセグメント木
struct Segtree{
    int n;
    vector<P> dat;
    Segtree(){}
    Segtree(int _n){
        n = 1;
        while(n < _n) n *= 2;
        dat.clear();
        rep(i, 0, 2 * n){
            dat. push_back(P(INF, -1));
        }
    }
    void update(int k, int a){
        dat[k + n - 1].first = a;
        dat[k + n - 1].second = k;
        k += n - 1;        
        while(k > 0){
            k = (k - 1) / 2;
            int l = 2 * k + 1, r = 2 * k + 2;
            int MIN = INF, id = -1; 
            if(dat[l].first > dat[r].first){
                MIN = dat[r].first; id = dat[r].second;
            }else{
                MIN = dat[l].first; id = dat[l].second;
            }
            dat[k].first = MIN; dat[k].second = id;
        }
    }
    // max[a, b)
    P query(int a, int b){
        return query(a, b, 0, 0, n);
    }
    P query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return P(INF, -1);
        if(a <= l && r <= b) return dat[k];
        else{
            int mid = (l + r) / 2;
            P vl = query(a, b, 2 * k + 1, l, mid);
            P vr = query(a, b,  2 * k + 2, mid, r);
            return (vl.first > vr.first ? vr : vl);
        }
    }
};

