using namespace std;
ll v[MAXN],lazy[4*MAXN],seg[2][4*MAXN];
ll n;

void build(ll node,ll l,ll r){
    if(l==r){
        if(l%2){
            seg[1][node]=l;
            seg[0][node]=MAXN-1;
        }
        else{
            seg[0][node]=l;
            seg[1][node]=MAXN-1;
        }
        return;
    }
    build(2*node,l,(l+r)/2);
    build(2*node+1,(l+r)/2+1,r);
    if(v[seg[0][2*node]]<v[seg[0][2*node+1]]){
        seg[0][node]=seg[0][2*node];
    }
    else{
        seg[0][node]=seg[0][2*node+1];
    }
    if(v[seg[1][2*node]]<v[seg[1][2*node+1]]){
        seg[1][node]=seg[1][2*node];
    }
    else{
        seg[1][node]=seg[1][2*node+1];
    }
}

ll query(ll node,ll l,ll r,ll p,ll q){
    if(l>q||r<p)
        return MAXN-1;
    ll ans,ans1,ans2;
    if(l>=p&&r<=q){
        ans=seg[p%2][node];
        if(lazy[node])
            ans=1-ans;
        return ans;
    }
    if(lazy[node]){
        lazy[node]=0;
        lazy[2*node]=1-lazy[2*node];
        lazy[2*node+1]=1-lazy[2*node+1];
    }
    ans1=query(2*node,l,(l+r)/2,p,q);
    ans2=query(2*node+1,(l+r)/2+1,r,p,q);
    if(v[ans1]<v[ans2])
        return ans1;
    else return ans2;
}
class cmp{
    public:
        bool operator()(pair<ll,ll>a,pair<ll,ll>b){
            if(v[query(1,0,n-1,a.ff,a.ss)]<v[query(1,0,n-1,b.ff,b.ss)])
                return 0;
            else return 1;
        }
};

priority_queue<pair<ll,ll>,vector<pair<ll,ll> >,cmp>pq;
vector<ll>ans;

void solve(ll a,ll b){
    pq.push(mp(a,b));
    ll w,e,r,z;
    while(!pq.empty()){
        w=pq.top().ff;
        e=pq.top().ss;
        pq.pop();
        r=query(1,0,n-1,w,e);
        z=query(1,0,n-1,r+1,e);
        ans.pb(v[r]);
        ans.pb(v[z]);
        if(r-1-w>=1)
        pq.push(mp(w,r-1));
        if(z-1-r-1>=1)
        pq.push(mp(r+1,z-1));
        if(e-z-1>=1)
        pq.push(mp(z+1,e));
    }
}


