int build(int *arr,int x){
    if(x>=MAX) {
        if(x-MAX<N/2) return arr[x];
        return INF;
    }
    return arr[x]=min(build(arr,x*2),build(arr,x*2+1));
}
int find_min(int *arr,int x,int y,int a,int b,int p){
    if(x<=a&&b<=y) return arr[p];
    if(x>=b||y<=a) return INF;
    return min(find_min(arr,x,y,a,(a+b)/2,2*p),find_min(arr,x,y,(a+b)/2,b,2*p+1));
}
struct range{
    int x,y;
    int r_min1,r_min2,r_idx1,r_idx2;
    void r_gen(int a,int b){
        x=a,y=b;
        if(a>=b) return;
        r_min1=find_min(seg[x%2],x/2,y/2,0,MAX,1);
        r_idx1=invp[r_min1];
        //printf("%d %d %d %d %d %d\n",x,y,r_min1,r_idx1,(r_idx1+1)/2,(y+1)/2);
        r_min2=find_min(seg[!(x%2)],(r_idx1+1)/2,(y+1)/2,0,MAX,1);
        r_idx2=invp[r_min2];
    }
    bool operator<(const range &a)const{
        return r_min1>a.r_min1;
    }
};
