template<typename Monoid>
struct SegmentTree{
    private:
    typedef function<Monoid(Monoid,Monoid)> F;
    typedef function<Monoid(Monoid,Monoid)> G;
    int n;
    F f;
    G g;
    Monoid id;
    vector<Monoid> dat;
    public:
    SegmentTree(int n_,F f,G g,Monoid id):f(f),g(g),id(id){init(n_);};
    void init(int n_){
        n=1;
        while (n<n_) n*=2;
        dat.resize(2*n-1,id);
    }
    void build(vector<Monoid> v){
        int n_=v.size();
        rep(i,n_) dat[i+n-1]=v[i];
        for (int i=n-2;i>=0;i--) dat[i]=f(dat[2*i+1],dat[2*i+2]);
    }
    void update(int i,Monoid a){
        i+=n-1;
        dat[i]=g(dat[i],a);
        while (i>0){
            i=(i-1)/2;
            dat[i]=f(dat[2*i+1],dat[2*i+2]);
        }
    }
    Monoid query(int a,int b,int k,int l,int r){
        if (r<=a||b<=l) return id;
        if (a<=l&&r<=b) return dat[k];
        Monoid vl=query(a,b,2*k+1,l,(l+r)/2);
        Monoid vr=query(a,b,2*k+2,(l+r)/2,r);
        return f(vl,vr);
    }
    Monoid query(int a,int b){
        return query(a,b,0,0,n);
    }
    Monoid operator[](int i){
        return dat[i+n-1];
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<int> p(N);
    rep(i,N) cin >> p[i];
    map<int,int> m;
    rep(i,N) m[p[i]]=i;
    auto f=[](int a,int b){return min(a,b);};
    auto g=[](int a,int b){return b;};
    SegmentTree<int> seg0(N,f,g,INF),seg1(N,f,g,INF);
    for (int i=0;i<N;i+=2) seg0.update(i,p[i]);
    for (int i=1;i<N;i+=2) seg1.update(i,p[i]);
    vector<int> ans;
    set<int> border;
    border.insert(N),border.insert(-1);
    rep(i,N/2){
        int a=seg0.query(0,N),b=seg1.query(0,N);
        if (border.lower_bound(m[a])!=border.lower_bound(m[b])){
            if (a<b){
                auto itr=border.upper_bound(m[a]);
                int ul=*itr,ll=*(--itr);
                b=seg1.query(ll+1,ul);
            }
            else{
                auto itr=border.upper_bound(m[b]);
                int ul=*itr,ll=*(--itr);
                a=seg0.query(ll+1,ul);
            }
        }
        bool swaped=false;
        if (m[a]>m[b]) swap(a,b),swaped=true;
        ans.push_back(a),ans.push_back(b);
        border.insert(m[a]),border.insert(m[b]);
        if (swaped) swap(a,b);
        seg0.update(m[a],INF),seg1.update(m[b],INF);
    }
    rep(i,N){
        cout << ans[i];
        if (i!=N-1) cout << ' ';
        else cout << endl;
    }
}

