        if (k2<id2-1 && a[k2]<=mi) flag=2,mi=a[k2];
        if (k3<r && a[k3]<=mi) flag=3,mi=a[k3];
        if (flag==1){
            R[k]=a[k1]; ++k1; ++k;
            R[k]=a[k1]; ++k1; ++k;
        }
        if (flag==2){
            R[k]=a[k2]; ++k2; ++k;
            R[k]=a[k2]; ++k2; ++k;
