inline void add(int op,int pos,int l, int r, int cnt) {
    if(a[cnt]<a[sgt[op][pos]])sgt[op][pos]=cnt;
    if(l==r)return;
	int mid=(l+r)>>1;
	if(cnt<=mid)add(op,pos<<1,l,mid,cnt);
	else add(op,pos<<1|1,mid+1,r,cnt);
}
inline int ask(int op,int pos,int l, int r, int L, int R) {
    if(l>R||r<L)return 0;
    if(L<=l&&r<=R)return sgt[op][pos];
    int mid=(l+r)>>1;
    int lans=ask(op,pos<<1,l,mid,L,R);
	int rans=ask(op,pos<<1|1,mid+1,r,L,R);
	return a[lans]<a[rans]?lans:rans;
}
struct stru{
    int l,r,v;
    stru(int _l,int _r){
    	l=_l,r=_r,v=(l>r)?0:ask(l&1,1,1,n,l,r); 
	}
	bool operator <(const stru &other) const{
		return a[v]<a[other.v]; 
	}
};
