struct Binary_indexed_tree{
    int N;
    vi bit;
    Binary_indexed_tree(int n):N(n){
        bit.resize(N+1,0);
    }
    void add(int x,int a){
        for(x;x<=N;x+=(x&-x)) bit[x]+=a;
    }
    ll sum(int x){
        ll ret=0;
        for(x;x>0;x-=(x&-x)) ret+=bit[x];
        return ret;
    }
    ll lower_bound(ll X){
        if(sum(N)<X) return -1;
        ll ret=0,memo=1,sum=0;
        while(memo*2<=N) memo*=2;
        while(memo>0){
            if(memo+ret<=N&&sum+bit[memo+ret]<X){
                sum+=bit[memo+ret];
                ret+=memo;
            }
            memo/=2;
        }
        return ret+1;
    }
};
struct Union_Find{
    ll N;
    vi par;
    vi siz;
    Union_Find(int n):N(n){
        par.resize(N);
        siz.resize(N,1);
        rep(i,0,N) par[i]=i;
    }
    ll root(ll X){
        if(par[X]==X) return X;
        return par[X]=root(par[X]);
    }
    bool same(ll X,ll Y){
        return root(X)==root(Y);
    }
    void unite(ll X,ll Y){
        X=root(X);
        Y=root(Y);
        if(X==Y) return;
        par[X]=Y;
        siz[Y]+=siz[X];
        siz[X]=0;
    }
    ll size(ll X){
        return siz[root(X)];
    }
};
ll modpow(ll X,ll Y){
    ll sum=X,cnt=1;
    vi A;
    while(cnt<=Y){
        A.pb(sum);
        sum*=sum;
        sum%=MOD;
        cnt*=2;
    }
    int M=A.size();
    ll ret=1;
    REP(i,1,M){
        if(Y>=(1ll<<M-i)){
            Y-=(1ll<<M-i);
            ret*=A[M-i];
            ret%=MOD;
        }
    }
    return ret;
}
ll fac[MAX],finv[MAX],inv[MAX];
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
ll COM(ll n,ll r){
    if(n<r||n<0||r<0) return 0;
    return fac[n]*finv[r]%MOD*finv[n-r];
}
ll memo,N;
void update(ll X,ll Y,vi &A,vector<vector<pii>> &min){
    A[X]=Y;
    min[X/memo][X%2]=mp(INF,INF);
    ll Z=X/memo*memo;
    rep(i,Z,std::min(Z+memo,N)) min[i/memo][i%2]=std::min(min[i/memo][i%2],mp(A[i],i));
}
pii RMQ(ll left,ll right,vi &A,vector<vector<pii>> &min){
    pii ret=mp(INF,INF);
    if(left/memo==right/memo){
        REP(i,left,right){
            if(right%2==i%2) ret=std::min(ret,mp(A[i],i));
        }
    }
    else{
        rep(i,left,std::min(left/memo+memo,N)){
            if(right%2==i%2) ret=std::min(ret,mp(A[i],i));
        } 
        REP(i,right/memo*memo,right){
            if(right%2==i%2) ret=std::min(ret,mp(A[i],i));
        }
        rep(i,left/memo+1,right/memo) ret=std::min(ret,min[i][right%2]);
    }
    return ret;
}
signed main(){
    cin>>N;
    memo=sqrt(N)+1;
    vector<vector<pii>> min(memo+1,vector<pii>(2,mp(INF,INF)));
    vi A(N);
    rep(i,0,N) cin>>A[i];
    rep(i,0,N) min[i/memo][i%2]=std::min(min[i/memo][i%2],mp(A[i],i));
    vi P(N+1);
    rep(i,0,N) P[A[i]]=i;
    std::set<ll> set,flag;
    REP(i,1,N) flag.insert(i);
    set.insert(N-1);
    while(!flag.empty()){
    for(auto i:flag){
        ll X=*set.lower_bound(P[i]);
        if(X%2==P[i]%2) continue;
        pii p=RMQ(P[i]+1,X,A,min);
        cout<<i<<" "<<p.first<<" ";
        update(P[i],INF,A,min);
        update(p.second,INF,A,min);
        set.insert(P[i]-1);
        set.insert(p.second-1);
        flag.erase(p.first);
        flag.erase(i);
        break;
    }
    }
    cout<<endl;
}

