void getP(vector<int> &p1, vector<int> &p2, int n) {
	int buf;
	for (int i = 0; i < n/2; i++) {
		scanf("%d", &buf);
		p1[i] = buf;
		scanf("%d", &buf);
		p2[i] = buf;
