    void resize(int m) {
        n = 1;
        while(n < m) n *= 2;
        dat.resize(2*n-1);
        rep(i,0,2*n-1) dat[i] = INT_MAX;
    }

    // k番目 (0-indexed) の値を a に更新
    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    // [a, b) の最小値を返す
    // 最初に呼び出すときは XX.query(a, b, 0, 0, -1) とする
    T query(int a, int b, int k, int l, int r) {
        if(r == -1) r = n;
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return dat[k];
        else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

vector<pii> ans;
rmq<int> even, odd;
struct Elem {
    int x, y, val;
};
bool operator<(const Elem &a, const Elem &b) {
    return a.val > b.val;
}

// position [l, r)
void solve() {
    priority_queue<Elem> q;
    // printf("N = %lld\n", N);
    q.push(Elem{0, N, even.query(0, N, 0, 0, -1)});

    while(!q.empty()) {
        Elem t = q.top(); q.pop();
        int l = t.x, r = t.y;
        // printf("l = %lld, r = %lld, min = %lld\n", l, r, t.val);
        if(l >= r) continue;
        int lb = odd.query(l, r, 0, 0, -1);
        int ub = even.query(l, r, 0, 0, -1);
        int mi = min(pos[lb], pos[ub]);
        int ma = max(pos[lb], pos[ub]);
        // printf("push: %lld and %lld\n", p[mi], p[ma]);
        ans.push_back(pii(p[mi], p[ma]));

        q.push(Elem{l, mi, (l%2 ? odd : even).query(l, mi, 0, 0, -1)});
        q.push(Elem{mi+1, ma, ((mi+1)%2 ? odd : even).query(mi+1, ma, 0, 0, -1)});
        q.push(Elem{ma+1, r, ((ma+1)%2 ? odd : even).query(ma+1, r, 0, 0, -1)});
    }
}

