using namespace std;

struct State {
	int x;
	int y;
	int idx1;
	int idx2;
	int L;
	int R;
	State(int x, int y, int idx1, int idx2, int L, int R) : x(x), y(y), idx1(idx1), idx2(idx2), L(L), R(R) {}
	bool operator>(const State& s) const {
		if (x != s.x) return x > s.x;
		return y > s.y;
	}
};

State solve(int L, int R, vector<int>& a) {
	int idx1 = -1, x = 1000000000;
	for (int i = L; i < R; i += 2) {
		if (a[i] < x) {
			x = a[i];
			idx1 = i;
		}
	}

	int idx2 = -1;
	x = 1000000000;
	for (int i = idx1 + 1; i < R; i += 2) {
		if (a[i] < x) {
			x = a[i];
			idx2 = i;
		}
	}
	State res(a[idx1], a[idx2], idx1, idx2, L, R);
	return res;
}

int main() {
