		cin >> a[i];		
	}
	vector<int> ans;
	priority_queue<State, vector<State>, greater<State> > pq;
	pq.push(solve(0, n, a));
	while (!pq.empty()) {
		State s = pq.top();
		pq.pop();
		ans.push_back(s.x);
		ans.push_back(s.y);
		if (s.L < s.idx1) pq.push(solve(s.L, s.idx1, a));
		if (s.idx1 + 1 < s.idx2) pq.push(solve(s.idx1 + 1, s.idx2, a));
		if (s.idx2 + 1 < s.R) pq.push(solve(s.idx2 + 1, s.R, a));
	}

	cout << ans[0];
