int query(int l, int r){
	if(r-l<=0) return n;
	if(r-l<=2) return l;
	int t = 0;
	while(l+(2<<(t+1))<=r) t++;
	int res = b[l][t];
	int res2 = query(l+(2<<t), r);
	return a[res]<a[res2]?res:res2;
}

vector<int> solve(){
	priority_queue<PP,vector<PP>,greater<PP>> q;
	q.push(PP(query(0, n), P(0, n)));
	vector<int> res; res.reserve(n);
	while(!q.empty()){
		PP p = q.top(); q.pop();
		int x = p.fst, l = p.snd.fst, r = p.snd.snd;
		res.push_back(x);
		int y = query(x+1, r);
		res.push_back(y);
		if(l<x){
			q.push(PP(query(l, x), P(l, x)));
		}
		if(x+1<y){
			q.push(PP(query(x+1, y), P(x+1, y)));
		}
		if(y+1<r){
			q.push(PP(query(y+1, r), P(y+1, r)));
		}
	}
	return res;
}

