	que.push(piece[0]);

	while (!que.empty()) {
		pii p = que.top(); que.pop();
		ans.push_back(p.first);
		ans.push_back(p.second);

		int id = piece_to_id[p];
		for (int i : nxt[id]) que.push(piece[i]);
	}

	for_(i,0,N) cout << ans[i] << (i < N - 1 ? " " : "\n");
}

