	inline int MinPos(int a, int b) {
		return c[a] < c[b] ? a : b;
	}
	inline void Build(int o, int l, int r) {
		if (l == r) return (void)(mn[o] = l);
		int mid = (l + r) >> 1;
		Build(o << 1, l, mid);
		Build(o << 1 | 1, mid + 1, r);
		mn[o] = MinPos(mn[o << 1], mn[o << 1 | 1]);
	}
	inline void Init(int fl) {
		for (int i = 0; i <= n; i++) c[i] = N;
