		Build(1, 1, n);
	}
	inline int MinPos(int o, int l, int r, int L, int R) {
		if (l >= L && r <= R) return mn[o];
		int mid = (l + r) >> 1, res = 0;
		if (L <= mid) res = MinPos(res, MinPos(o << 1, l, mid, L, R));
		if (R > mid) res = MinPos(res, MinPos(o << 1 | 1, mid + 1, r, L, R));
		return res;
	}
};
