using namespace std;

using P = pair<int, int>;

int main() {
    int n; cin >> n;
    vector<int> tbl[2][18];
    vector<int> p[2];
    const int INF = 1<<30;
    p[0].resize(n, INF);
    p[1].resize(n, INF);
    for (int i = 0; i < n; i++) cin >> p[i%2][i];
    for (int k = 0; k < 2; k++) {
        for (int e = 0; e < 18; e++) {
            tbl[k][e].resize(n);
            for (int i = 0; i + (1<<e) <= n; i++) {
                if (e == 0) tbl[k][0][i] = i;
                else {
                    int x = tbl[k][e-1][i], y = tbl[k][e-1][i + (1<<(e-1))];
                    tbl[k][e][i] = p[k][x] > p[k][y] ? y : x;
                }
            }
        }
    }
    function<int(int, int, int)> rmq = [&](int l, int r, int k) {
        int lb = 0, ub = 18;
        while (ub - lb > 1) {
            int m = (lb + ub) / 2;
            if (1 << m <= r - l) lb = m;
            else ub = m;
        }
        int x = tbl[k][lb][l], y = tbl[k][lb][r-(1<<lb)];
        return p[k][x] > p[k][y] ? y : x;
    };
    map<P, vector<P> > mp;
    function<P(int, int)> solve = [&](int l, int r) {
        int b = l % 2, i = rmq(l, r, b), j = rmq(i, r, b^1);
        P p0 = {p[b][i], p[b^1][j]};
        if (l < i) { P q = solve(l, i); mp[p0].push_back(q); }
        if (i+1 < j) { P q = solve(i+1, j); mp[p0].push_back(q); }
        if (j+1 < r) { P q = solve(j+1, r); mp[p0].push_back(q); }
        return p0;
    };
    P p0 = solve(0, n);
    priority_queue<pair<int, P> > pq;
    auto get_val = [](P q) { return -q.first; };
    pq.push({get_val(p0), p0});
    while (!pq.empty()) {
        P p = pq.top().second;
        pq.pop();
        cout << p.first << ' ' << p.second << ' ';
        for (P q : mp[p]) pq.push({get_val(q), q});
    }
    cout << endl;
}

