/*
子供の頂点を求める式
k*2+1
k*2+2
親を求める式
(k-1)/2
*/

template<typename T>
class RMQ{
public:
    T arr[1000000+10];
    int n;

    /*
    template <>
    RMQ<std::pair<int,int>>::RMQ(int N,int a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = std::pair<int,int>(a,i);

        n = 1;
        while(n<N) n*=2;

    }
    */

    /*
    RMQ<int>(int N,int a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = a;

        n = 1;
        while(n<N) n*=2;

    }
    */

    RMQ(int N,T a){
        for(int i = 0; i < 1000000+10; i++)
            arr[i] = a;

        n = 1;
        while(n<N) n*=2;

    }

    T query(int a,int b){
        return query(a,b,0,0,n);
    }

    T query(int a,int b,int k,int l,int r){
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return arr[k];

        else{
            T vl = query(a,b,k*2+1,l , (l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl,vr);
        }

    }

    void update(int k,T a){
        k += n-1;

        arr[k] = a;

        while(k > 0){
            k = (k-1)/2;
            arr[k] = min(arr[k*2+1],arr[k*2+2]);
        }
    }
private:

};


