    for(int i = 0; i < n; i++){
        cin >> p[i];
        p[i]--;
        if(i % 2) sego.set(i, p[i]);
        else sege.set(i, p[i]);
        q[p[i]] = i;
    }
    sego.build();
    sege.build();
    priority_queue<int, vector<int>, greater<int>> que;
    que.push(sege.query(0, n));
    set<int> st;
    st.insert(-1);
    st.insert(n);
    while(que.size()){
        int u = que.top();
        que.pop();
        auto itr = st.lower_bound(q[u]);
        int r = *itr;
        int l = *(--itr);
        int v;
        if(q[u] % 2){
            v = sege.query(q[u], r);
            if(q[u] != l + 1) que.push(sego.query(l + 1, q[u]));
            if(q[v] != q[u] + 1) que.push(sege.query(q[u] + 1, q[v]));
            if(r != q[v] + 1) que.push(sego.query(q[v + 1], r));
        }
        else{
            v = sego.query(q[u], r);
