template<typename T>
struct SparseTable {
  vector<T> v;
  VV st;
  int op(const int a, const int b) {
    return (v[a] == v[b]) ? min(a, b) : ((v[a] < v[b]) ? a : b);
  } 
  void init(const vector<T> &_v) {
    v = _v;
    int n = v.size();
    st = {V(n)}; iota(all(st[0]), 0);
    for (int j = 0; n>>(j+1); ++j) {
      int m = n+1-(1<<(j+1));
      st.push_back(V(m));
      rep(i, m) st[j+1][i] = op(st[j][i], st[j][i+(1<<j)]);
    }
  }
  int index(const int l, const int r) { int d = fLog2(r-l); return op(st[d][l], st[d][r-(1<<d)]); }
  T query(const int l, const int r) { return v[index(l, r)]; }
};


V p;
SparseTable<int> rmq[2];


vector<P> rec(int l, int r) {
  if (l == r) return {};

  int k = r - l; // k is even
  int m = l % 2;
  int i = rmq[m].index(l, r);
  int j = rmq[m^1].index(i, r);

  vector<vector<P>> sub(3);
  sub[0] = rec(l, i);
  sub[1] = rec(i+1, j);
  sub[2] = rec(j+1, r);

  vector<P> mgd, mgd2;
  merge(all(sub[0]), all(sub[1]), back_inserter(mgd));
  merge(all(mgd), all(sub[2]), back_inserter(mgd2));

  vector<P> res = {{p[i], p[j]}};
  res.insert(res.end(), all(mgd2));
  return res;
}


