	int a,b;
	node(){a=(1<<24)+500000;b=(1<<24)+500000;}
	node(int x,int y){a=x;b=y;}
	bool operator<(const node obj)const{
		return a<obj.a;
	}
};

node min(node a,node b){
	if (a<b)	return a;
	else		return b;
}

queue<node> q[1000000];
int num[100050];
void dfs(int index,int l,int r){
	if (l>=r)	{
		q[index].push(node((1<<23)+index,(1<<23)+index));
		return;
	}
	int minn1=1<<30,pos1=0;
	for (int i=l;i<r;i+=2){
		if (num[i]<minn1){
			minn1=num[i];
			pos1=i;
		}
	}
	int minn2=1<<30,pos2=0;
	for (int i=pos1+1;i<=r;i+=2){
		if (num[i]<minn2){
			minn2=num[i];
			pos2=i;
		}
	}
	dfs(index*3,l,pos1-1);
	dfs(index*3+1,pos1+1,pos2-1);
	dfs(index*3+2,pos2+1,r);
	q[index].push(node(minn1,minn2));
	int index1=index*3,index2=index*3+1;
	int index3=index*3+2;
	for (int i=l;i<=r;i++){
		node tmp1=q[index1].front();
		node tmp2=q[index2].front();
		node tmp3=q[index3].front();
		if (tmp1<tmp2&&tmp1<tmp3){
			q[index1].pop();
			q[index].push(tmp1);
		}
		else if (tmp2<tmp1&&tmp2<tmp3){
			q[index2].pop();
			q[index].push(tmp2);
		}
		else{
			q[index3].pop();
			q[index].push(tmp3);
		}
	}
}

