void build(int v = 1, int l = 1, int r = n) {
    if(l == r) {
        t[v][0] = { a[l], l };
        t[v][1] = { l & 1 ? a[l] : INF, l };
        t[v][2] = { l % 2 == 0 ? a[l] : INF, l };
    }
    else {
        int m = (l + r) / 2;
        build(v * 2, l, m);
        build(v * 2 + 1, m + 1, r);
        for(int sh = 0; sh < 3; sh++)
            t[v][sh] = min(t[v * 2][sh], t[v * 2 + 1][sh]);
    }
}

void upd(int pos, int val, int v = 1, int l = 1, int r = n) {
    if(l == r) {
        t[v][0] = { val, l };
        t[v][1] = { val, l };
        t[v][2] = { val, l };
    }
    else {
        int m = (l + r) / 2;
        if(pos <= m)
            upd(pos, val, v * 2, l, m);
        else
            upd(pos, val, v * 2 + 1, m + 1, r);
        for(int sh = 0; sh < 3; sh++)
            t[v][sh] = min(t[v * 2][sh], t[v * 2 + 1][sh]);
    }
}

pair<int, int> getVal(int sh, int l, int r, int tv = 1, int tl = 1, int tr = n) {
    if(l > r)
        return { INF, INF };
    else if(l == tl && r == tr) {
        return t[tv][sh];
    }
    else {
        int tm = (tl + tr) / 2;
        pair<int, int> res1 = getVal(sh, l, min(tm, r), tv * 2, tl, tm);
        pair<int, int> res2 = getVal(sh, max(tm + 1, l), r, tv * 2 + 1, tm + 1, tr);
        return min(res1, res2);
    }
}

int get(vector<int>& res, int pos) {
    if(pos >= (int)res.size())
        return INF;
    return res[pos];
}

vector<int> solve(int l, int r) {
    if(l >= r)
        return vector<int>(0);
    assert((r - l + 1) % 2 == 0);
    int p1 = getVal((l & 1) ? 1 : 2, l, r - 1).second;
    int p2 = getVal((p1 & 1) ? 2 : 1, p1 + 1, r).second;
    upd(p1, INF);
    upd(p2, INF);
    vector<int> left = solve(l, p1 - 1);
    vector<int> mid = solve(p1 + 1, p2 - 1);
    vector<int> right = solve(p2 + 1, r);
    vector<int> res;
    res.push_back(a[p1]);
    res.push_back(a[p2]);
    int l1 = 0, l2 = 0, l3 = 0;
    while(true) {
        if(l1 == (int)left.size() && l2 == (int)mid.size() && l3 == (int)right.size())
            break;
        int mn = 1e9;
        if(get(left, l1) < mn)
            mn = left[l1];
        if(get(mid, l2) < mn)
            mn = mid[l2];
        if(get(right, l3) < mn)
            mn = right[l3];
        if(get(left, l1) == mn) {
            res.push_back(left[l1]);
            res.push_back(left[l1 + 1]);
            l1 += 2;
        }
        if(get(mid, l2) == mn) {
            res.push_back(mid[l2]);
            res.push_back(mid[l2 + 1]);
            l2 += 2;
        }
        if(get(right, l3) == mn) {
            res.push_back(right[l3]);
            res.push_back(right[l3 + 1]);
            l3 += 2;
        }
    }
    return res;
}

