#define MAX_LOG 22
template<class T,class comp>
class SparseTable {
	vector<T>t[MAX_LOG];
	vector<int>l2;
public:
	T DEFAULT;
	int n;
	void init(int n_,T DEF) {
		DEFAULT=DEF;
		n = n_;
		rep(i, MAX_LOG)t[i].assign(n, DEFAULT);
		l2.assign(n + 1, 0);
		int k = 0;
		rep(i, n + 1) {
			while ((1 << (k + 1)) <= i)k++;
			l2[i] = k;
		}
	}
	void set_array(int n_, T*a,T DEF) {
		init(n_,DEF);
		rep(i, n)t[0][i] = a[i];
		for (int i = 1; i < MAX_LOG; i++) {
			for (int j = 0; j + (1 << (i - 1)) < n; j++){
				if(comp()(t[i-1][j],t[i-1][j+(1<<(i-1))]))t[i][j]=t[i-1][j];
				else t[i][j]=t[i-1][j+(1<<(i-1))];
			}
		}
	}
	T query(int a, int b) {
		int w = b - a;
		int l = l2[w];
		return comp()(t[l][a],t[l][b-(1<<l)])?t[l][a]:t[l][b - (1 << l)];
	}
};
SparseTable<P,less<P>>t[2];
struct st{
	int l,r;
	bool operator<(const st&b)const{
		return t[l%2].query(l,r)>t[b.l%2].query(b.l,b.r);
	}
};
