	int re=min(getodd(l,mid,node<<1,L,min(mid,R)),getodd(mid+1,r,(node<<1)+1,max(mid+1,L),R));
	return re;
}
int geteven(int l,int r,int node,int L,int R){
	if (L>R){
		return INF;
	}
	if (l==L && r==R){
		return tree[node].even;
	}
	int mid=(l+r)>>1;
	int re=min(geteven(l,mid,node<<1,L,min(mid,R)),geteven(mid+1,r,(node<<1)+1,max(mid+1,L),R));
