struct SegmentTree {
    struct Node {
        Node operator*(const Node& o) const {
            return { min(p, o.p) };
        }
        pair<int, int> p;
    };

    SegmentTree(int n) : e({ { n * 2 + 1, -1 } }), n(n) {
        for (m = 2; m < n; m *= 2); // m >= n
        t = vector<Node>(m + n + n % 2, e);
    }
    Node *data() {
        return &t[m];
    }
    void build() {
        for (int i = (n - 1 + m) / 2; i > 0; i--) {
            t[i] = t[i * 2] * t[i * 2 + 1];
        }
    }
    const Node& root() const {
        return t[1];
    }
    void update(int i, const Node& o) {
        for (t[i += m] = o; i /= 2, i > 0;) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    Node query(int l, int r) const {
        Node o[2] = { e, e };
        for (l += m, r += m; l < r; l /= 2, r /= 2) {
            if (r & 1) o[1] = t[--r] * o[1];
            if (l & 1) o[0] = o[0] * t[l++];
        }
        return o[0] * o[1];
    }
    void print() {
        for (int j = 1; j <= m; j *= 2) {
            int k = min(j * 2, m + n);
            for (int i = j; i < k; i++) {
                cout << t[i].p.first << ',' << t[i].p.second << " \n"[i == k - 1];
            }
        }
    }
    vector<Node> t;
    const Node e;
    int n, m;
};

