//初始化RMQ,  b数组下标从1开始，从0开始简单修改
void rmq_init(){
    for(int i=2; i<=n; i++) if(i & (i-1)) lg[i] = lg[i-1]; else lg[i] = lg[i-1]+1;
    for(int k=0; k<2; k++)for(int i=1; i<=n; i++)dp[k][i][0] = (i%2 == k) ? a[i]:n+1;
    for(int k=0; k<2; k++)
        for(int j=1; (1<<j)<=n; j++)
            for(int i=1; i+(1<<j)-1<=n; i++)
            dp[k][i][j] = min(dp[k][i][j-1], dp[k][i+(1<<(j-1))][j-1]);
}
//查询最大值 ,中间部分是交叉的
int rmq(int x, int l,int r){
    int k = lg[r-l+1];
    return min(dp[x][l][k], dp[x][r-(1<<k)+1][k]);
}

pair<int, int> calc(int l, int r){
    int x = rmq(l&1, l, r);
    int y = rmq((pos[x]+1)&1, pos[x]+1, r);
    return {-x, -y};
}

