Node nodes[N];

int nid = 0;


void init(){
    for(int pp=0; pp<=1; ++pp)
      for(int i=0; i<n; ++i)
        rmq[pp][0][i] = n;

    for(int pp=0; pp<=1; ++pp)
      for(int i=pp; i<n; i+=2)
        rmq[pp][0][i] = i;

    for(int pp=0; pp<=1; ++pp)
      for (int i=1; (1<<i)-1<n; ++i)
        for (int j=0; j+(1<<i)-1<n; ++j){
            int& L = rmq[pp][i-1][j];
            int& R = rmq[pp][i-1][j+(1<<(i-1))];
            rmq[pp][i][j] = (p[L] <= p[R] ? L : R);
        }
}

int query(int pp, int l, int r){
    int d = r - l + 1;
    int x = 31 - __builtin_clz(d);

    int& L = rmq[pp][x][l];
    int& R = rmq[pp][x][r-(1<<x)+1];
    return p[L] <= p[R] ? L : R;
}

int build(int l, int r){
  if(l>=r) return -1;
  int id = nid;

  ++nid;

  nodes[id].l = l;
  nodes[id].r = r;

  nodes[id].res.first = query(l%2, l ,r);
  nodes[id].res.second = query((nodes[id].res.first+1)%2, nodes[id].res.first+1, r);

  int x = build(l, nodes[id].res.first-1);
  if(x != -1) nodes[id].out.push_back(x);
  x = build(nodes[id].res.first+1, nodes[id].res.second-1);
  if(x != -1) nodes[id].out.push_back(x);
  x = build(nodes[id].res.second+1, r);
  if(x != -1) nodes[id].out.push_back(x);
  return id;
}

void solve(){
  int pos = 0;
  map<pair<int, int>, int> ps;
  ps[ {p[nodes[0].res.first], p[nodes[0].res.second]}] = 0;
  while(!ps.empty()){
    auto item = (*ps.begin());
    ps.erase(ps.begin());
    res[pos] = item.first.first;
    ++pos;
    res[pos] = item.first.second;
    ++pos;
    for(auto child: nodes[item.second].out){
      ps[{p[nodes[child].res.first], p[nodes[child].res.second] }] = child;
    }
  }

}

