pair<int, int> even[400005];
pair<int, int> odd[400005];
int arr[200005];
int n;
int sz;
const int inf=0x3f3f3f3f;
void update(int idx, pair<int, int> val, pair<int, int> *tree){
	idx+=sz;
	while(idx){
		tree[idx]=min(tree[idx], val);
		idx/=2;
	}
}
pair<int, int> query(int a, int b, pair<int, int> *tree){
	pair<int, int> ret={inf, inf};
	a+=sz;
	b+=sz;
	while(a<=b){
		if(a&1)
			ret=min(ret, tree[a++]);
		if(!(b&1))
			ret=min(ret, tree[b--]);
		a/=2;
		b/=2;
	}
	return ret;
}
int main(){
	memset(even, 0x3f, sizeof(even));
	memset(odd, 0x3f, sizeof(odd));
	scanf("%d", &n);
	sz=1;
	while(sz<n/2)sz*=2;
	for(int i=0;i<n;i++){
		int x;
		scanf("%d", &x);
		arr[i]=x;
		int idx=i/2;
		if(i&1)
			update(idx, {x, i}, odd);		
		else
			update(idx, {x, i}, even);
	}
	queue<pair<int, int> > q;
	q.push({0, n-1});
	vector<pair<int, int> > ans;
	while(!q.empty()){
		int sz=q.size();
		priority_queue<pair<int, int> > pq;
		for(int i=0;i<sz;i++){
			int le=q.front().first;
			int ri=q.front().second;
			q.pop();
			if(le>=ri+1)
				continue;
			if(le+1==ri){
				pq.push({-arr[le], -arr[ri]});
				continue;
			}
			if(le&1){
				int left=le/2;
				int right=ri/2;
				auto l=query(left, right-1, odd);
				auto r=query(l.second/2+1, right, even);
				pq.push({-l.first, -r.first});
				q.push({le, l.second-1});
				q.push({l.second+1, r.second-1});
				q.push({r.second+1, ri});
				continue;
			}	
			int left=le/2;
			int right=ri/2;
			auto l=query(left, right, even);
			auto r=query(l.second/2, right, odd);
			pq.push({-l.first, -r.first});
			q.push({le, l.second-1});
			q.push({l.second+1, r.second-1});
			q.push({r.second+1, ri});
		}
		while(!pq.empty()){
			int a=-pq.top().first;
			int b=-pq.top().second;
			pq.pop();
			ans.push_back({a, b});
		}
	}
	for(int i=0;i<ans.size();i++)
		printf("%d %d ", ans[i].first, ans[i].second);
	printf("\n");
	return 0;
}

