struct segt {
	int sz,arr[800005],val[200005];
	void init(int n) {
		for(sz=1;sz<=n;sz<<=1);
		for(int i=0;i<=sz;i++) val[i]=1000000000;
		for(int i=1;i<=sz+sz;i++) arr[i]=sz;
	}
	void build() {
		for(int i=0;i<sz;i++) arr[i+sz]=i;
		for(int i=sz-1;i>0;i--) {
			if (val[arr[i+i]]<val[arr[i+i+1]]) arr[i]=arr[i+i];
			else arr[i]=arr[i+i+1];
		}
	}
	int getmin(int i,int x,int y,int a,int b) {
		if (x>=a&&y<=b) return arr[i];
		if (y<=a||x>=b) return sz;
		register int m=(x+y)>>1;
		int X=getmin(i+i,x,m,a,b),Y=getmin(i+i+1,m,y,a,b);
		if (val[X]<val[Y]) return X;
		return Y;
	}
	int getmin(int a,int b) {
		return getmin(1,0,sz,a,b);
	}
}sodd,seven;
