inline void update(int &x,int y) { if ( a[x] > a[y] ) x = y; }
inline void build(int p,int l,int r)
{
    if ( l == r )
        return ( ( l & 1 ) ? odd[p] = l : even[p] = l ) , void();
    int mid = l + r >> 1;
    build( p<<1 , l , mid ) , build( p<<1|1 , mid+1 , r );
    update( odd[p] , odd[p<<1] ) , update( odd[p] , odd[p<<1|1] );
    update( even[p] , even[p<<1] ) , update( even[p] , even[p<<1|1] );
}
inline int query(int p,int l,int r,int ql,int qr,int op)
{
    if ( ql <= l && qr >= r ) return op ? even[p] : odd[p];
    int mid = l + r >> 1 , res = 0;
    if ( ql <= mid ) update( res , query(p<<1,l,mid,ql,qr,op) );
    if ( qr > mid ) update( res , query(p<<1|1,mid+1,r,ql,qr,op) );
    return res;
}
struct sec
{
    int l,r,ansl,ansr,op;
    sec (int _l,int _r,int _op)
    {
        l = _l , r = _r , op = _op;
        ansl = query(1,1,n,l,r,op);
        ansr = query(1,1,n,ansl+1,r,op^1);
    }
    friend bool operator < (sec x,sec y)
    {
        if ( a[x.ansl] == a[y.ansl] )
            return a[x.ansr] < a[y.ansr];
        return a[x.ansl] < a[y.ansl];
    }
};
set <sec> S;
inline void solve(void)
{
    S.insert( sec(1,n,0) );
    while ( S.size() )
    {
        sec now = *S.begin(); S.erase(now);
        printf("%d %d ",a[now.ansl],a[now.ansr]);
        if ( now.l < now.ansl-1 ) S.insert(sec(now.l,now.ansl-1,now.op));
        if ( now.ansl+1 < now.ansr-1 ) S.insert(sec(now.ansl+1,now.ansr-1,now.op^1));
        if ( now.ansr+1 < now.r ) S.insert(sec(now.ansr+1,now.r,now.op));
    }
}
