const int kN = 2e5 + 5;
const int kInf = 1e9;
int p[kN], rv[kN];

struct SparseTable {
    int sp[20][kN];

    SparseTable() = default;
    SparseTable(const vector<int> &a) {
        for (int i = 0; i < a.size(); ++i) sp[0][i] = a[i];
        for (int i = 1; (1 << i) <= a.size(); ++i) {
            for (int j = 0; j + (1 << i) <= a.size(); ++j)
                sp[i][j] = min(sp[i - 1][j], sp[i - 1][j + (1 << (i - 1))]);
        }
    }

    int Query(int l, int r) {
        int p = 31 - __builtin_clz(r - l + 1);
        return min(sp[p][l], sp[p][r - (1 << p) + 1]);
    }
} sp[2];

vector<tuple<int, int, int>> ans;

void Dfs(int l, int r, int d = 0) {
    if (l > r) return;
    int x = sp[l % 2].Query(l, r);
    int y = sp[1 - l % 2].Query(rv[x] + 1, r);
    assert(x < kInf && y < kInf);
    ans.emplace_back(d, x, y);
    Dfs(l, rv[x] - 1, d + 1);
    Dfs(rv[x] + 1, rv[y] - 1, d + 1);
    Dfs(rv[y] + 1, r, d + 1);
}

