vector<pint> alt;
map<pint,int> inv;
vector<int> graph[210000];


void solve(int left, int right, int par) {
    if (left >= right) return;

    pair<VAL,int> pa = rmq[left%2].get(left, right - 1);
    pair<VAL,int> pb = rmq[(left+1)%2].get(left + 1, right);

//    cout << "----------------" << endl;
