using namespace std;


struct SegmentTree{

    vector<int> data;
    vector<int> odd;
    vector<int> even;
    int n=1;
    int inf = INT_MAX;

    SegmentTree(int n_){
        while(n<n_)n*=2;
        data.resize(n*2-1);
        odd.resize(n*2-1,inf);
        even.resize(n*2-1,inf);
    }

    void add(int a,int x){
        x+=n-1;
        data[x]+=a;
        while(x){
            x=(x-1)/2;
            data[x]=min(data[2*x+1],data[2*x+2]);
        }
    }

    void set(){
        for(int i=n-1;i<2*n;i++){
            ((i-(n-1))%2==0 ? even[i]:odd[i])=data[i];
        }
        for(int i=n-1;i<2*n-1;i++){
            int x=i;
            while(x){
                x=(x-1)/2;
                even[x]=min(even[2*x+1],even[2*x+2]);
                odd[x] =min(odd[2*x+1],  odd[2*x+2]);
            }
        }



    }

    int getMin(int a,int b,int k,int l,int r){

        if(l>=b||r<=a)return inf;
        if(l>=a&&r<=b)return data[k];

        return min(getMin(a,b,2*k+1,l,(r+l)/2), getMin(a,b,2*k+2,(r+l)/2,r));
    }

    //[a,b)
    int getMin(int a,int b){
        return getMin(a,b,0,0,n);
    }


    int getEvenMin(int a,int b,int k,int l,int r){

        if(l>=b||r<=a)return inf;
        if(l>=a&&r<=b)return even[k];

        return min(getEvenMin(a,b,2*k+1,l,(r+l)/2), getEvenMin(a,b,2*k+2,(r+l)/2,r));
    }

    //[a,b)
    int getEvenMin(int a,int b){
        return getEvenMin(a,b,0,0,n);
    }

    int getOddMin(int a,int b,int k,int l,int r){

        if(l>=b||r<=a)return inf;
        if(l>=a&&r<=b)return odd[k];

        return min(getOddMin(a,b,2*k+1,l,(r+l)/2), getOddMin(a,b,2*k+2,(r+l)/2,r));
    }

    //[a,b)
    int getOddMin(int a,int b){
        return getOddMin(a,b,0,0,n);
    }

};

