typedef long long ll;
#define INF (1<<30)
typedef pair<int, int> pii;
vector<int> even_p, odd_p;
vector<pii> even, odd;

/* RMQ begin */
//dat{ val , index }
int init(int n_,vector<pii>& dat) {
	int n = 1;
	while (n < n_) n *= 2;
	dat.resize(2 * n - 1);
	for (int i = 0; i < 2 * n - 1;i++) dat[i] = { INF,INF };
	return n;
}

// k = p_index
void update(int k, int a,int n,vector<pii>& dat) {
	int temp = k;
	k /= 2;
	k += n - 1;
	dat[k] = { a, temp};

	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
// [a,b)の最小値
pii query(int a, int b, int k, int l, int r,vector<pii>& dat) {
	// [a,b)と[l,r)が交差しなければ,INT_MAX
	if (r <= a || b <= l) return{ INF,INF };
	// [a,b)が[l,r)を完全に含んでいれば,この節点の値
	if (a <= l && r <= b) return dat[k];
	else {
		pii vl = query(a, b, k * 2 + 1, l, (l + r) / 2, dat);
		pii vr = query(a, b, k * 2 + 2, (l + r) / 2, r, dat);
		return min(vl, vr);
	}
}
/* RMQ end */

struct Node {
	// [l,r)
	int l, r;
	// even(odd) index 
	int a, b;

	int Min_val, Min_index;
	Node(int l, int r) :l(l), r(r) {
		if (l % 2 == 0) {
			a = l / 2;
			b = r / 2;
			auto x = query(a, b+1, 0, 0, even_p.size(), even);
			Min_val = x.first; Min_index = x.second;
		}
		else {
			a = (l - 1) / 2;
			b = (r - 1) / 2;
			auto x = query(a, b+1, 0, 0, odd_p.size(), odd);
			Min_val = x.first; Min_index = x.second;
		}
	}

	bool operator <(const Node&o) const {
		// 昇順
		return o.Min_val < Min_val;
	}
};

