const int MAX_N = 200010;
int N;
SegmentTreeMin<pii> even, odd;
vector<int> P;
vector<int> E[MAX_N];
vector<int> PA;
void dfs(int L, int R, int pa = 0)
{
    // cerr << L << " " << R << " " << pa << endl;
    pii mi1, mi2;
    if (L == R)
    {
        E[pa].push_back(P[L]);
        PA[P[L]] = P[R];
        return;
    }
    if (L % 2 == 0)
    {
        mi1 = even.min(L, R - 1);
        mi2 = odd.min(mi1.second + 1, R);
    }
    else
    {
        mi1 = odd.min(L, R - 1);
        mi2 = even.min(mi1.second + 1, R);
    }
    int A = mi1.second;
    int B = mi2.second;
    E[pa].push_back(mi1.first);
    PA[mi1.first] = mi2.first;
    if (L < A)
    {
        dfs(L, A, mi1.first);
    }
    if (A + 1 < B)
    {
        dfs(A + 1, B, mi1.first);
    }
    if (B + 1 < R)
    {
        dfs(B + 1, R, mi1.first);
    }
}

int main()
{
    cin >> N;
    P.resize(N);
    PA.resize(N + 1);
    for (int i = 0; i < N; i++)
    {
        cin >> P[i];
    }
    odd.init(N + 1, mp(INF, INF));
    even.init(N + 1, mp(INF, INF));
    for (int i = 0; i < N; i++)
    {
        if (i % 2 == 0)
        {
            even.update(i, mp(P[i], i));
        }
        else
        {
            odd.update(i, mp(P[i], i));
        }
    }

    dfs(0, N);

    priority_queue<int, vector<int>, greater<int>> que;
    que.push(E[0].front());
    vector<int> ans;

    while (not que.empty())
    {
        int q = que.top();
        que.pop();
        ans.push_back(q);
        ans.push_back(PA[q]);
        // cerr << q << " " << PA[q] << endl;
        for (auto &val : E[q])
        {
            que.push(val);
        }
    }
    for (int i = 0; i < ans.size(); i++)
    {
        cout << ans[i] << " ";
    }
    cout << endl;
    return 0;
}

