void updatep(ll v, ll tl, ll tr, ll pos, ll val) {
	if (tl == tr) {
		treep[v] = val;
		return;
	}
	ll tm = (tl + tr) / 2;
	if (pos <= tm)updatep(2 * v, tl, tm, pos, val);
	else updatep(2 * v + 1, tm + 1, tr, pos, val);
	treep[v] = min(treep[2 * v], treep[2 * v + 1]);
}
void updatenep(ll v, ll tl, ll tr, ll pos, ll val) {
	if (tl == tr) {
		treenep[v] = val;
		return;
	}
	ll tm = (tl + tr) / 2;
	if (pos <= tm)updatenep(2 * v, tl, tm, pos, val);
	else updatenep(2 * v + 1, tm + 1, tr, pos, val);
	treenep[v] = min(treenep[2 * v], treenep[2 * v + 1]);
}
ll minnp(ll v, ll tl, ll tr, ll l, ll r) {
	if (l > r)return 1000000000;
	if (tl == l && tr == r)return treep[v];
	ll tm = (tl + tr) / 2;
	return min(minnp(2 * v, tl, tm, l, min(r, tm)), minnp(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
}
ll minnnep(ll v, ll tl, ll tr, ll l, ll r) {
	if (l > r)return 1000000000;
	if (tl == l && tr == r)return treenep[v];
	ll tm = (tl + tr) / 2;
	return min(minnnep(2 * v, tl, tm, l, min(r, tm)), minnnep(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
}

ll n, temp;

int main() {
	scanf("%lld", &n);
	for (int i = 0; i < n; i++) {
		scanf("%lld", &temp);
		index[temp] = i;
		if (i % 2 == 0) {
			updatep(1, 0, n - 1, i, temp);
			updatenep(1, 0, n - 1, i, 1000000000);
		}
		else {
			updatenep(1, 0, n - 1, i, temp);
			updatep(1, 0, n - 1, i, 1000000000);
		}
	}
	int counter = 0;
	vector<pair<ll, ll>> v[2];
	int now = 0, future = 1;
	v[now].push_back(make_pair(0, n - 1));
	while (counter < n) {
		vector<pair<ll, ll>> currentresults;
		for (auto it : v[now]) {
			ll f, s;
			if (it.first % 2 == 0) {
				f = minnp(1, 0, n - 1, it.first, it.second - 1);
				s = minnnep(1, 0, n - 1, index[f] + 1, it.second);
			}
			else {
				f = minnnep(1, 0, n - 1, it.first, it.second - 1);
				s = minnp(1, 0, n - 1, index[f] + 1, it.second);
			}
			currentresults.push_back(make_pair(f, s));
		}
		sort(currentresults.begin(), currentresults.end());
		printf("%lld %lld ", currentresults[0].first, currentresults[0].second);
		counter += 2;
		ll f = currentresults[0].first, s = currentresults[0].second;
		for (auto it : v[now]) {
			if (index[f] >= it.first && index[s] <= it.second) {
				if (it.first < index[f])v[future].push_back(make_pair(it.first, index[f] - 1));
				if (index[s] - index[f] > 1)v[future].push_back(make_pair(index[f] + 1, index[s] - 1));
				if (index[s] < it.second)v[future].push_back(make_pair(index[s] + 1, it.second));
			}
			else {
				v[future].push_back(it);
			}
		}
		v[now].resize(0);
		swap(now, future);
	}
	return 0;
}

