template <typename G>
struct DoublingLowestCommonAncestor
{
	const int LOG;
	vector<int> dep;
	const G &g;
	vector<vector<int>> table;

	DoublingLowestCommonAncestor(const G &g) : g(g), dep(g.size()), LOG(32 - __builtin_clz(g.size()))
	{
		table.assign(LOG, vector<int>(g.size(), -1));
	}

	void dfs(int idx, int par, int d)
	{
		table[0][idx] = par;
		dep[idx] = d;
		for (auto &to : g[idx])
		{
			if (to != par)
				dfs(to, idx, d + 1);
		}
	}

	void build()
	{
		dfs(0, -1, 0);
		for (int k = 0; k + 1 < LOG; k++)
		{
			for (int i = 0; i < table[k].size(); i++)
			{
				if (table[k][i] == -1)
					table[k + 1][i] = -1;
				else
					table[k + 1][i] = table[k][table[k][i]];
			}
		}
	}

	int query(int u, int v)
	{
		if (dep[u] > dep[v])
			swap(u, v);
		for (int i = LOG - 1; i >= 0; i--)
		{
			if (((dep[v] - dep[u]) >> i) & 1)
				v = table[i][v];
		}
		if (u == v)
			return u;
		for (int i = LOG - 1; i >= 0; i--)
		{
			if (table[i][u] != table[i][v])
			{
				u = table[i][u];
				v = table[i][v];
			}
		}
		return table[0][u];
	}
};

int main()
{
	ll n, i, p[222222], q[222222];
	cin >> n;
	for (i = 0; i < n;i++)
		cin >> p[i];
	for (i = 0; i < n;i++)
		q[p[i]] = i;
	set<ll> s1, s2;
	set<ll> so, se;
	s1.insert(-1);
	s1.insert(n);
	s2.insert(1);
	s2.insert(-n);
	SegmentTree<ll> seg1(n, [](ll a, ll b) { return min(a, b); }, 1e9);
	SegmentTree<ll> seg2(n, [](ll a, ll b) { return min(a, b); }, 1e9);
	for (i = 0; i < n;i+=2)
		seg1.update(i, p[i]);
	for (i = 1; i < n; i += 2)
		seg2.update(i, p[i]);
	so.insert(seg1.query(0, n));
	se.insert(seg2.query(0, n));
	vector<ll> ans;
	for (i = 0; i * 2 < n; i++)
	{
		ll n1 = *so.begin(), n2;
		ans.pb(n1);
		auto itr1 = s1.upper_bound(q[n1]), itr2 = s2.upper_bound(-q[n1]);
		if ((-(*itr2) + 1) % 2 == 0)
		{
			se.erase(seg2.query(-(*itr2) + 1, *itr1));
			n2 = seg2.query(q[n1] + 1, *itr1);
		}
		else{
			se.erase(seg1.query(-(*itr2) + 1, *itr1));
			n2 = seg1.query(q[n1] + 1, *itr1);
		}
		ans.pb(n2);
		so.erase(n1);
		s1.insert(q[n1]);
		s2.insert(-q[n1]);
		s1.insert(q[n2]);
		s2.insert(-q[n2]);
		if ((-(*itr2) + 1) % 2 == 0)
		{
			so.insert(seg1.query(-(*itr2) + 1, q[n1]));
			se.insert(seg2.query(-(*itr2) + 1, q[n1]));
			so.insert(seg2.query(q[n1] + 1, q[n2]));
			se.insert(seg1.query(q[n1] + 1, q[n2]));
			so.insert(seg1.query(q[n2] + 1, *itr1));
			se.insert(seg2.query(q[n2] + 1, *itr1));
		}
		else
		{
			so.insert(seg2.query(-(*itr2) + 1, q[n1]));
			se.insert(seg1.query(-(*itr2) + 1, q[n1]));
			so.insert(seg1.query(q[n1] + 1, q[n2]));
			se.insert(seg2.query(q[n1] + 1, q[n2]));
			so.insert(seg2.query(q[n2] + 1, *itr1));
			se.insert(seg1.query(q[n2] + 1, *itr1));
		}
	}
	for (i = 0; i < n;i++)
		cout << ans[i] << " ";
}

