        if (i % 2 == 0) rmq0.update(i, p[i]);
        else rmq1.update(i, p[i]);
    }
    priority_queue<seg, vector<seg>, greater<seg>> pq;
    pq.push(getSeg(0, N));
    for (int i = 0; i < N / 2; i++) {
        seg cur = pq.top(); pq.pop();
        int l = cur.second.first, r = cur.second.second;
        int mid = ap[cur.first];
        cout << cur.first << " ";
        if (l != mid) pq.push(getSeg(l, mid));
        int pri;
        if ((mid + 1) % 2 == 0) pri = rmq0.query(mid + 1, r, 0, 0, rmq0.n);
        else  pri = rmq1.query(mid + 1, r, 0, 0, rmq1.n);
        cout << pri << " ";
