		tmp->val=tbl[tree][l];
		tmp->idx=l*2+tree;
		tmp->rgt=0;
		tmp->left=0;
		return tmp;
	}
	int m=(l+r)>>1;
	node* ll = build(l,m,tree);
	node* rr = build(m,r,tree);
	if (ll->val<rr->val) {
		tmp->val=ll->val;
		tmp->idx=ll->idx;
	} else {
		tmp->val=rr->val;
		tmp->idx=rr->idx;
	}
	tmp->left=ll;
	tmp->rgt=rr;
	//printf("%d %d %d %d %d\n",tree,l,r,tmp->val,tmp->idx);
	return tmp;
}

