    }
    void Build(int l, int r, int rt)
    {
        // 将 T[rt].seg 初始化为合适的值
        if (l == r) {
            // 将 T[rt].seg 初始化为合适的值
            T[rt].seg = INF;
            return;
        }
        int m = (l + r) >> 1;
        Build(lson);
        Build(rson);
        push_up(rt);
    }
    void Update(int L, int R, int c, int l, int r, int rt)
    {
        if (L <= l && r <= R) {
            // 用 c 更新 T[rt].lazy 和 T[rt].seg
            T[rt].seg = c;
            return;
        }
        int m = (l + r) >> 1;
        if (L <= m) Update(L, R, c, lson);
        if (R > m) Update(L, R, c, rson);
        push_up(rt);
    }
    int Query(int L, int R, int l, int r, int rt)
    {
        if (L <= l && r <= R) return T[rt].seg;
        int m = (l + r) >> 1;
        int ret = INF; // 将 ret 初始化为合适的值
        if (L <= m) ret = min(ret, Query(L, R, lson)); // 用 Query(L, R, lson) 更新 ret
        if (m < R) ret = min(ret, Query(L, R, rson)); // 用 Query(L, R, rson) 更新 ret
        return ret;
    }
} ST[2];
int n, a[MAX_N], pos[MAX_N];
struct cmp
{
    bool operator () (pair<int, int> &a, pair<int, int> &b) {
        int al = a.first, ar = a.second, bl = b.first, br = b.second;
        return ST[bl & 1].Query(bl, br, 1, n, 1) < ST[al & 1].Query(al, ar, 1, n, 1);
    }
};
priority_queue<pair<int, int>, vector<pair<int, int> >, cmp> pq;
int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        pos[a[i]] = i;
    }
    ST[0].Build(1, n, 1);
    ST[1].Build(1, n, 1);
    for (int i = 1; i <= n; i++) {
        if (i & 1) ST[1].Update(i, i, a[i], 1, n, 1);
        else ST[0].Update(i, i, a[i], 1, n, 1);
    }
    pq.push(make_pair(1, n));
    pair<int, int> t;
    int p, q, l, r, cnt = 0;
    while (!pq.empty()) {
        t = pq.top(); pq.pop();
        l = t.first, r = t.second;
        //printf("!%d %d\n", l, r);
        p = ST[l & 1].Query(l, r, 1, n, 1);
        q = ST[(l + 1) &1].Query(pos[p] + 1, r, 1, n, 1);
        cnt += 2;
        printf("%d %d%c", p, q, cnt == n ? '\n' : ' ');
        if (cnt == n) break;
        if (l < pos[p] - 1) pq.push(make_pair(l, pos[p] - 1));
        if (pos[p] + 1 < pos[q] - 1) pq.push(make_pair(pos[p] + 1, pos[q] - 1));
        if (pos[q] + 1 < r) pq.push(make_pair(pos[q] + 1, r));
    }
    return 0;
}

