	bool operator < (const dat& T) const{
		return a[val.first] < a[T.val.first];
	}
};

set <dat> s;

void build_odd(int l, int r, int ind){
	if(l == r){
		oddt[ind] = {odd[l], l};
		return;
	}
	int mid = (l + r) / 2;
	build_odd(l, mid, ind * 2);
	build_odd(mid + 1, r, ind * 2 + 1);
	oddt[ind] = min(oddt[ind * 2], oddt[ind * 2 + 1]);
}

void build_even(int l, int r, int ind){
	if(l == r){
		event[ind] = {even[l], l};
		return;
	}
	int mid = (l + r) / 2;
	build_even(l, mid, ind * 2);
	build_even(mid + 1, r, ind * 2 + 1);
	event[ind] = min(event[ind * 2], event[ind * 2 + 1]);
}

pair<int, int> query(int l, int r, int ind, int lx, int ly, pair<int, int>* tree){
	//printf("QUERY %d %d %d %d\n", l, r, lx, ly);
	if(lx > r || ly < l) return {INF, INF};
	if(lx <= l && r <= ly){
		//printf("ANS %d %d %d\n", l, r, tree[ind].second);
		return tree[ind];
	}

	int mid = (l + r) / 2;

	return min(query(l, mid, ind * 2, lx, ly, tree), query(mid + 1, r, ind * 2 + 1, lx, ly, tree));
}

pair <int, int> solve(int l, int r){
	int mn, mn2;
	//printf("%d %d\n", l ,r);
	if(l & 1){
		//odd - even
		mn = query(1, n / 2, 1, (l + 1) / 2, r / 2, oddt).second;
		//printf("MN %d\n", mn);
		mn2 = query(1, n / 2, 1, mn, r / 2, event).second;
		//printf("ODD %d %d\n", mn, mn2);
		mn = mn * 2 - 1;
		mn2 = mn2 * 2;
	}
	else{
		//even - odd
		mn = query(1, n / 2, 1, l / 2, (r - 1) / 2, event).second;
		mn2 = query(1, n / 2, 1, mn + 1, (r + 1) / 2, oddt).second;

		mn = mn * 2;
		mn2 = mn2 * 2 - 1;
	}

	return {mn, mn2};
}

