#define repeat(i, n) for (int i = 0; (i) < int(n); ++(i))
#define repeat_reverse(i, n) for (int i = (n)-1; (i) >= 0; --(i))
using namespace std;
template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;

template <class Monoid>
struct segment_tree {
    typedef Monoid monoid_type;
    typedef typename Monoid::underlying_type underlying_type;
    int n;
    vector<underlying_type> a;
    Monoid mon;
    segment_tree() = default;
    segment_tree(int a_n, underlying_type initial_value = Monoid().unit(), Monoid const & a_mon = Monoid()) : mon(a_mon) {
        n = 1; while (n < a_n) n *= 2;
        a.resize(2*n-1, mon.unit());
        fill(a.begin() + (n-1), a.begin() + (n-1 + a_n), initial_value); // set initial values
        repeat_reverse (i, n-1) a[i] = mon.append(a[2*i+1], a[2*i+2]); // propagate initial values
    }
    void point_set(int i, underlying_type z) { // 0-based
        a[i+n-1] = z;
        for (i = (i+n)/2; i > 0; i /= 2) { // 1-based
            a[i-1] = mon.append(a[2*i-1], a[2*i]);
        }
    }
    underlying_type range_concat(int l, int r) { // 0-based, [l, r)
        underlying_type lacc = mon.unit(), racc = mon.unit();
        for (l += n, r += n; l < r; l /= 2, r /= 2) { // 1-based loop, 2x faster than recursion
            if (l % 2 == 1) lacc = mon.append(lacc, a[(l ++) - 1]);
            if (r % 2 == 1) racc = mon.append(a[(-- r) - 1], racc);
        }
        return mon.append(lacc, racc);
    }
};
template <typename T>
struct min_indexed_t {
    typedef pair<T, int> underlying_type;
    underlying_type unit() const { return make_pair(numeric_limits<T>::max(), -1); }
    underlying_type append(underlying_type a, underlying_type b) const { return min(a, b); }
};

int main() {
    // input
    int n; scanf("%d", &n);
    vector<int> p(n); repeat (i, n) scanf("%d", &p[i]);
    assert (n % 2 == 0);

    // solve
    segment_tree<min_indexed_t<int> > even(n), odd(n);
    repeat (i, n) {
        auto & segtree = (i % 2 == 0 ? even : odd);
        segtree.point_set(i, make_pair(p[i], i));
    }
    reversed_priority_queue<tuple<int, int, int> > que;
    auto push = [&](int l, int r) {
        if (l == r) return;
        auto & left  = (l % 2 == 0 ? even : odd);
        int x = left.range_concat(l, r - 1).first;
        que.emplace(x, l, r);
    };
    push(0, n);
    vector<int> result;
    while (not que.empty()) {
        int l, r; tie(ignore, l, r) = que.top(); que.pop();
        auto & left  = (l % 2 == 0 ? even : odd);
        auto & right = (l % 2 == 0 ? odd : even);
        int m1 = left.range_concat(l, r - 1).second;
        int m2 = right.range_concat(m1 + 1, r).second;
        result.push_back(p[m1]);
        result.push_back(p[m2]);
        push(l, m1);
        push(m1 + 1, m2);
        push(m2 + 1, r);
    }

    // output
    repeat (i, n) {
        printf("%d%c", result[i], i < n - 1 ? ' ' : '\n');
    }
    return 0;
}

/*
题目要求每次删除P的相邻2个数加入到Q的开头。考虑其逆过程：即在得到Q的情况下，每次删除Q的开头2个数插入到P中相邻两个位置；问题转换成找到一个能够完成构造的Q，最小化其字典序
考虑当前求解P[l ~ r]的字典序最小的Q，贪心找到一个字典序最小的pair(P[x], P[y])，满足P[l ~ x - 1]有偶数个数、P[y + 1 ~ r]有偶数个数，显然P[x + 1 ~ y - 1]中也有偶数个数
这三个部分是独立的，可以分别求解最小的字典序。用堆维护即可
*/

#include <queue>
#include <cstdio>
#include <cstring>

using namespace std;
const int Max_N(200050);

int N, P[Max_N], ST[2][20][Max_N], Log[Max_N];

inline int cmin(int a, int b)
{
	return P[a] < P[b] ? a : b;
}

inline int rmq(int c, int l, int r)
{
	int k = Log[r - l + 1];
	return cmin(ST[c][k][l], ST[c][k][r - (1 << k) + 1]);
}

struct pil
{
	pil(const int &_x = 0, const int &_y = 0) : x(_x), y(_y) {}
	int x, y;
	inline bool operator<(const pil &b) const
	{
		return P[x] == P[b.x] ? P[y] < P[b.y] : P[x] < P[b.x];
	}
	inline bool operator>(const pil &b) const
	{
		return b < *this;
	}
};

struct node
{
	node(const int &_l, const int &_r)
	{
		l = _l, r = _r;
		int a = rmq(l & 1, l, r - 1);
		v = pil(a, rmq(r & 1, a + 1, r));
	}
	int l, r;
	pil v;
	inline bool operator<(const node &b) const
	{
		return v > b.v;
	}
};

int main()
{
	scanf("%d", &N);
	P[0] = 0X3F3F3F3F;
	for (int i = 1;i <= N;++i)
		scanf("%d", P + i);
	for (int i = 1;i <= N;++i)
		ST[i & 1][0][i] = i;
	for (int c = 0;c <= 1;++c)
		for (int j = 1;(1 << j) <= N;++j)
			for (int i = 1;i + (1 << j) - 1 <= N;++i)
				ST[c][j][i] = cmin(ST[c][j - 1][i], ST[c][j - 1][i + (1 << (j - 1))]);
	Log[0] = Log[1] = 0;
	for (int i = 2;i <= N;++i)
		Log[i] = Log[i >> 1] + 1;
	priority_queue<node> Q;
	Q.push(node(1, N));
	while (Q.empty() == false)
	{
		node t = Q.top();
		Q.pop();
		printf("%d %d ", P[t.v.x], P[t.v.y]);
		if (t.l <= t.v.x - 1)
			Q.push(node(t.l, t.v.x - 1));
		if (t.v.x + 1 <= t.v.y - 1)
			Q.push(node(t.v.x + 1, t.v.y - 1));
		if (t.v.y + 1 <= t.r)
			Q.push(node(t.v.y + 1, t.r));
	}
	return 0;
}

