#define INF 2000000000
#define MOD 998244353

using namespace std;

struct Node {
	int val[2];
};
Node t[800000];
int n;
int arr[200000];
int pos[200001];
priority_queue < pair < int, pair <int, int> > > pq;

void build(int v, int l, int r) {
	if (l == r) {
		t[v].val[l % 2] = arr[l];
		t[v].val[1 - l % 2] = INF;
		return; 
	}
	int mid = (l + r) / 2;
	build(2 * v, l, mid);
	build(2 * v + 1, mid + 1, r);
	t[v].val[0] = min(t[2 * v].val[0], t[2 * v + 1].val[0]);
	t[v].val[1] = min(t[2 * v].val[1], t[2 * v + 1].val[1]);
}

void setVal(int v, int l, int r, int index, int val) {
	if (l == r) {
		t[v].val[0] = t[v].val[1] = val;
		return;
	}
	int mid = (l + r) / 2;
	if (index <= mid)
		setVal(2 * v, l, mid, index, val);
	else
		setVal(2 * v + 1, mid + 1, r, index, val);
	for (int i = 0; i < 2; i++) 
		t[v].val[i] = min(t[2 * v].val[i], t[2 * v + 1].val[i]);	
}

int get(int v, int l, int r, int wl, int wr, int flag) {
	if (wl > wr)
		return INF;
	if (wl == l && wr == r) 
		return t[v].val[flag];
	int mid = (l + r) / 2;
	return min(get(2 * v, l, mid, wl, min(mid, wr), flag), 
		get(2 * v + 1, mid + 1, r, max(mid + 1, wl), wr, flag));
}

int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &arr[i]);
		pos[arr[i]] = i;
	}
	for (int i = 0; i < 4 * n; i++) 
		t[i].val[0] = t[i].val[1] = INF;
	build(1, 0, n - 1);
	pq.push(make_pair(-t[1].val[0], make_pair(0, n - 1)));
	for (int i = 0; i < n; i += 2) {
		pair < int, pair <int, int> > p = pq.top();
		pq.pop();
		int l = pos[-p.first];
		int next = get(1, 0, n - 1, l + 1, p.second.second, 1 - (p.second.first % 2));
		int r = pos[next];
		pair < int, pair <int, int> > f, s, tt;
		f.second = make_pair(p.second.first, l - 1);
		s.second = make_pair(l + 1, r - 1);
		tt.second = make_pair(r + 1, p.second.second);
		// cout << f.second.first << " | " << f.second.second << endl;
		// cout << s.second.first << " | " << s.second.second << endl;
		// cout << tt.second.first << " | " << tt.second.second << endl;
		if (f.second.second - f.second.first > 0) {
			f.first = -get(1, 0, n - 1, f.second.first, f.second.second, f.second.first % 2);
			pq.push(f);
		}
		if (s.second.second - s.second.first > 0) {
			s.first = -get(1, 0, n - 1, s.second.first, s.second.second, s.second.first % 2);
			pq.push(s);
