pii Min[2][maxn];
struct Seg
{
	int l, r;
	pii pos;
};
struct cmp
{
	bool operator () (const Seg & i, const Seg & j)
	{
		return p[i.pos.first] > p[j.pos.first];
	}
};
priority_queue<Seg, vector<Seg>, cmp> Q;
void pushup(int rt)
{
	Min[0][rt] = min(Min[0][ls], Min[0][rs]);
	Min[1][rt] = min(Min[1][ls], Min[1][rs]);
}
void build(int rt, int l, int r)
{
	if(l == r)
	{
		int id = l & 1;
		Min[id][rt] = mp(p[l], l);
		Min[id ^ 1][rt] = mp(INF, l);
		return;
	}
	int mid = l + r >> 1;
	build(ls, l, mid); build(rs, mid + 1, r);
	pushup(rt);
}
pii query(int rt, int l, int r, int a, int b)
{
	if(a <= l && r <= b) return Min[a & 1][rt];
	int mid = l + r >> 1;
	if(b <= mid) return query(ls, l, mid, a, b);
	if(a > mid) return query(rs, mid + 1, r, a, b);
	return min(query(ls, l, mid, a, b), query(rs, mid + 1, r, a, b));
}
pii getPos(int l, int r)
{
	pii p1 = query(1, 1, n, l, r);
	pii p2 = query(1, 1, n, p1.second + 1, r);
	return mp(p1.second, p2.second);
}
void ins(int l, int r)
{
	if(l > r) return;
	Q.push(Seg{l, r, getPos(l, r)});
}
void solve()
{
	vector<int> ans;
	ins(1, n);
	while(!Q.empty())
	{
		Seg x = Q.top(); Q.pop();
		ans.push_back(p[x.pos.first]);
		ans.push_back(p[x.pos.second]);
		ins(x.l, x.pos.first - 1);
		ins(x.pos.first + 1, x.pos.second - 1);
		ins(x.pos.second + 1, x.r);
	}
	for(auto v : ans) printf("%d ", v);
}
