	minn2[rt]=min(minn2[ls],minn2[rs]);
}
int query1(int rt,int l,int r,int x,int y)
{
	if (x<=l&&r<=y) return minn1[rt];
	int mid=(l+r)/2;
	int ret=inf;
	if(x<=mid) ret=min(ret,query1(ls,l,mid,x,y));
	if (y>=mid+1) ret=min(ret,query1(rs,mid+1,r,x,y));
	return ret;
}
int query2(int rt,int l,int r,int x,int y)
{
	if (x<=l&&r<=y) return minn2[rt];
	int mid=(l+r)/2;
	int ret=inf;
	if(x<=mid) ret=min(ret,query2(ls,l,mid,x,y));
	if (y>=mid+1) ret=min(ret,query2(rs,mid+1,r,x,y));
	return ret;
}
int solve(int l,int r)
{
	int tmpa,tmpb;
	if (l&1)
	{
		tmpa=query1(1,1,n,l,r);
		tmpb=query2(1,1,n,pos[tmpa],r);
	}
	else
	{
		tmpa=query2(1,1,n,l,r);
		tmpb=query1(1,1,n,pos[tmpa],r);
	}
	int posa=pos[tmpa],posb=pos[tmpb];
	p[++cnt].a=tmpa,p[cnt].b=tmpb,p[cnt].id=cnt;
	int cntt=cnt;
	if (posa!=l)
