struct Node {
	int l,r,st,L,R;
	bool operator < (const Node &rhs) const {
		return a[L]>a[rhs.L];
	}
};

priority_queue<Node> q;

int Q(int s,int t,int st,int ans=inf) {
	for(s=s+M-1,t=t+M+1;s^t^1;s>>=1,t>>=1) {
		if(~s&1) ans=min(ans,tr[s^1][st]);
		if(t&1) ans=min(ans,tr[t^1][st]);
	}
	return ans;
}

inline void A(int l,int r,int st) {
	if(l>r) return ;
	int s=book[Q(l,r,st)],t=book[Q(s,r,st^1)];
	tr[s+M][st]=inf,tr[t+M][st^1]=inf;
	q.push((Node){l,r,st,s,t});
}

