  vector<int> p(n);
  for (int i = 0; i < n; ++i) {
    cin >> p[i];
  }

  vector<int> u, v;
  for (int i = 0; i < n; ++i) {
    if (i & 1) {
      u.push_back(p[i]);
      v.push_back(inf);
    } else {
      u.push_back(inf);
      v.push_back(p[i]);
    }
  }

  segtree even, odd;
  odd.init(u);
  even.init(v);

  int idx = 0;
  vector<vector<int>> G(n);
  vector<pair<int, int>> val(n);

  function<void(int, int)> solve = [&](int l, int r) {
    int x, y;
    x = (l & 1 ? odd : even).get_min(l, r).second;
    y = (l & 1 ? even : odd).get_min(x, r).second;

    int v = idx;
    idx++;

    val[v] = make_pair(p[x], p[y]);
    if (l != x) {
      G[v].push_back(idx);
      solve(l, x);
    }
    if (x + 1 != y) {
      G[v].push_back(idx);
      solve(x + 1, y);
    }
    if (y + 1 != r) {
      G[v].push_back(idx);
      solve(y + 1, r);
    }
  };

  solve(0, n);

  vector<int> ans;

  priority_queue<data> que;
  que.push(data(val[0], 0));
  while (!que.empty()) {
