void buildc (int l,int r,int x) {
	c[x].l=l;c[x].r=r;
	if (l==r) {
		if (l%2==1) c[x].x=l; else c[x].x=-1;
		return;
	}
	int m=(l+r)>>1;
	buildc(l,m,x<<1);
	buildc(m+1,r,x<<1|1);
	int t1=c[x<<1].x,t2=c[x<<1|1].x;
	if (t1==-1) c[x].x=t2;
	else if (t2==-1) c[x].x=t1;
	else {
		if (a[t1]<a[t2]) c[x].x=t1; else c[x].x=t2;
	}
}
void buildd (int l,int r,int x) {
	d[x].l=l;d[x].r=r;
	if (l==r) {
		if (l%2==0) d[x].x=l; else d[x].x=-1;
		return;
	}
	int m=(l+r)>>1;
	buildd(l,m,x<<1);
	buildd(m+1,r,x<<1|1);
	int t1=d[x<<1].x,t2=d[x<<1|1].x;
	if (t1==-1) d[x].x=t2;
	else if (t2==-1) d[x].x=t1;
	else {
		if (a[t1]<a[t2]) d[x].x=t1; else d[x].x=t2;
	}
}
int queryc (int l,int r,int x) {
	if (c[x].l>=l && c[x].r<=r) {
		return c[x].x;
	}
	int m=(c[x].l+c[x].r)>>1;
	if (r<=m) return queryc(l,r,x<<1);
	else if (l>m) return queryc(l,r,x<<1|1);
	else {
		int t1=queryc(l,m,x<<1),t2=queryc(m+1,r,x<<1|1);
		if (t1==-1) return t2;
		else if (t2==-1) return t1;
		else {
			if (a[t1]<a[t2]) return t1; else return t2;
		}
	}
}
int queryd (int l,int r,int x) {
	if (d[x].l>=l && d[x].r<=r) {
		return d[x].x;
	}
	int m=(d[x].l+d[x].r)>>1;
	if (r<=m) return queryd(l,r,x<<1);
	else if (l>m) return queryd(l,r,x<<1|1);
	else {
		int t1=queryd(l,m,x<<1),t2=queryd(m+1,r,x<<1|1);
		if (t1==-1) return t2;
		else if (t2==-1) return t1;
		else {
			if (a[t1]<a[t2]) return t1; else return t2;
		}
	}
}
void work (int l,int r,int dep) {
	if (l>r) return;
	int x,y;
	if (l%2==1) x=queryc(l,r,1); else x=queryd(l,r,1);
	if (l%2==1) y=queryd(x+1,r,1); else y=queryc(x+1,r,1);
	s++;
	ans[s].first=a[x];ans[s].second.first=a[y];ans[s].second.second=dep;
	work(l,x-1,dep+1);work(x+1,y-1,dep+1);work(y+1,r,dep+1);
}
bool comp (pair<int,pair<int,int> >x,pair<int,pair<int,int> > y) {
	if (x.second.second<y.second.second) return true;
	else if (x.second.second>y.second.second) return false;
	if (x.first<y.first) return true;
	else return false;
}
