    pa[x.fr] = y.fr;

    while(!pque.empty()) {
        PP q = pque.top(); pque.pop();
        int a = q.fr;
        ans.push_back(a);
        ans.push_back(pa[a]);

        int l = q.sc.fr, r = q.sc.sc;
        if(l % 2 == 0) {
            x = even.get(l, r);
            y = odd.get(l, r);
        } else {
            x = odd.get(l, r);
            y = even.get(l, r);
        }

        int u = x.sc, v = y.sc;
        if(l + 1 < u) pque.push(f(l, u));
        if(u + 1 < v) pque.push(f(u + 1, v));
        if(v + 1 < r) pque.push(f(v + 1, r));
    }

    rep(i, n) {
        cout << ans[i] << " ";
    }
    cout << endl;
}

