		a[i & 1][i] = p[i];
		a[(i & 1) ^ 1][i] = N;
		mn[0][0][i] = mn[1][0][i] = i;
	}
	for (int i = 0; i < 2; i++) {
		for (int j = 1; j < K; j++) {
			for (int k = 1; k + (1 << j) - 1 <= n; k++) {
				mn[i][j][k] = getmin(i, mn[i][j - 1][k], mn[i][j - 1][k + (1 << (j - 1))]);
			}
		}
	}
	for (int i = 2; i < N; i++) {
		lg[i] = lg[i / 2] + 1;
	}
	dijkstra(1, n);
	for (int i = 1; i <= k; i++) {
		cout << ans[i] << ' ';
	}
}

