struct RMQ {
    int n;
    bool odd;
    vector<pii> data;
    RMQ() {}
    RMQ(int n_, bool odd_) {
        n=1;
        odd=odd_;
        while(n<n_) n<<=1;
        data.resize(n<<1,{INF,-1});
    }
    void update(int i,int x) {
        if(i%2!=odd) return;

        int idx=i;
        i+=n-1;
        data[i]={x,idx};
        while(i>0) {
            i=(i-1)/2;
            data[i]=min(data[i*2+1],data[i*2+2]);
        }
    }
    pii query(int a,int b) {
        return query(a,b,0,0,n);
    }
    pii query(int a,int b,int k,int l,int r) {
        if(r<=a or b<=l) return {INF,-1};
        if(a<=l and r<=b) return data[k];
        pii ml=query(a,b,k*2+1,l,(r+l)/2);
        pii mr=query(a,b,k*2+2,(r+l)/2,r);
        return min(ml,mr);
    }
};

vector<int> a;
RMQ sgt[2];

void calc(int l,int r,deque<pii> &ret,int d) {
    if(r-l==2) {
        ret.push_back({a[l],a[l+1]});
        return;
    }
    pii X=sgt[d%2].query(l,r);
    pii Y=sgt[!(d%2)].query(X.second+1, r);

    ret.push_back({X.first,Y.first});

    deque<pii> F,B,C;
    if(Y.second-X.second>1) calc(X.second+1,Y.second,C,d+1);

    for(int i=l; i<X.second; i+=2) {
        F.push_back({a[i], a[i+1]});
    }
    for(int i=Y.second+1; i<r; i+=2) {
        B.push_back({a[i], a[i+1]});
    }
    sort(ALL(F));
    sort(ALL(B));

    while(!F.empty() || !C.empty() || !B.empty()) {
        pii m={INF,INF};
        if(!F.empty()) chmin(m,F.front());
        if(!C.empty()) chmin(m,C.front());
        if(!B.empty()) chmin(m,B.front());
        if(!F.empty() && m==F.front()) F.pop_front();
        else if(!C.empty() && m==C.front()) C.pop_front();
        else if(!B.empty() && m==B.front()) B.pop_front();
        ret.push_back(m);
    }
}

