struct Sparse_Table {
	static const int MAX_N = 2e5 + 6;
	static const int MAX_P = __lg(MAX_N)+1;
	int st[MAX_P][MAX_N];
	int lg2[MAX_N];
	int pow2[MAX_P];
	int n;
	//starting from 1 ~ n
	vector<int> a;
	void init(int _n,vector<int> &_a) {
		n=_n;
		for (int i:_a) a.push_back(i);
//		cout<<"n = "<<n<<" , a : ";
//		for (int i:a) cout<<i<<' ';
//		cout<<endl;
		lg2[1] = 0;
		for (int i=2;MAX_N>i;i++) lg2[i] = lg2[i/2]+1;
		pow2[0]=1;
		for (int i=1;MAX_P>i;i++) pow2[i] = pow2[i-1] * 2;
		for (int i=1;n>=i;i++) {
			st[0][i] = a[i];
		}
		for (int i=1;MAX_P>i;i++) {
			for (int j=1;n>=j;j++) {
				int r=j+pow2[i-1];
				if (r>n) r=n;
				st[i][j] = min(st[i-1][j],st[i-1][r]);
			}
		}
	}
	int query(int l,int r) {
		int dis=(r-l+1);
		return min(st[lg2[dis]][l],st[lg2[dis]][r-pow2[lg2[dis]]+1]);
	}

} all,odd,even;

const int INF = 1e9 + 7;
const int MAX_N = 2e5 +6;
int pos[MAX_N];

priority_queue<piii,vector<piii>,greater<piii> > pq;

void add(int L,int R,int l,int r) {
	if (L>=R) return;
	if (l>R || L>r) return;
	if (L%2==0) pq.push(make_pair(even.query(L,R),make_pair(L,R)) );
	else pq.push(make_pair(odd.query(L,R),make_pair(L,R)) );
}

int main () {
	vector<int> a,b,c;
	a.resize(1);
	b.resize(1);
	c.resize(1);
	int n;
	scanf("%d",&n);
	for (int i=1;n>=i;i++) {
		int x;
		scanf("%d",&x);
		a.push_back(x);
		pos[x] = i;
		if (i%2==1) {
			b.push_back(x);
			c.push_back(INF);
		}
		else {
			b.push_back(INF);
			c.push_back(x);
		}
	}
	all.init(n,a);
	odd.init(n,b);
	even.init(n,c);
//	cout<<"query = "<<all.query(1,n)<<endl;
//	system("pause");
	bool check=false;
	pq.push(make_pair(odd.query(1,n),make_pair(1,n)));
	while (!pq.empty()) {
		piii p=pq.top();
		pq.pop();
		if(check) printf(" ");
		check=true;
		printf("%d",p.first);
		int p1=pos[p.first];
		int v1=p.first;
		int L=p.second.first,R=p.second.second;
//		cout<<"L  = "<<L<<" , R= "<<R<<endl;
		int v2;
		if (L%2 == 1) v2 = even.query(L,R);
		else v2=odd.query(L,R);
		printf(" %d",v2);
		int p2=pos[v2];
//		cout<<"p1 = "<<p1<<" , p2 = "<<p2<<endl;
		add(1,p1-1,L,R);
		add(p1+1,p2-1,L,R);
		add(p2+1,n,L,R);
	}
	puts("");
}

