#define Rep(i, n) for (int i = 1; i <= n; i ++)

using namespace std;

const int N = 200010;

int p[N];

struct Tr{
	int mx0, mx1;
	int mx0i, mx1i;
	int l0, tg;
}t[N * 4];

void up(Tr &x, Tr lc, Tr rc)
{
	if (lc.mx0 > rc.mx0) x.mx0 = lc.mx0, x.mx0i = lc.mx0i;
	else x.mx0 = rc.mx0, x.mx0i = rc.mx0i;
	if (lc.mx1 > rc.mx1) x.mx1 = lc.mx1, x.mx1i = lc.mx1i;
	else x.mx1 = rc.mx1, x.mx1i = rc.mx1i;

	if (lc.l0) x.l0 = lc.l0;
	else x.l0 = rc.l0;
}

void push_down(int x)
{
	if (t[x].tg) {
		swap(t[x << 1].mx0, t[x << 1].mx1);
		swap(t[x << 1].mx0i, t[x << 1].mx1i);
		swap(t[x << 1 | 1].mx0, t[x << 1 | 1].mx1);
		swap(t[x << 1 | 1].mx0i, t[x << 1 | 1].mx1i);
		t[x << 1].tg ^= 1, t[x << 1 | 1].tg ^= 1, t[x].tg = 0;
	}
}

void build(int x, int l, int r)
{
	if (l == r) {
		if (l & 1) t[x].mx1 = p[l], t[x].mx1i = l;
		else t[x].mx0 = p[l], t[x].mx0i = l; 
		return;
	}
	int mid = (l + r) >> 1;
	build(x << 1, l, mid); build(x << 1 | 1, mid + 1, r);
	up(t[x], t[x << 1], t[x << 1 | 1]);
}

void modify(int x, int l, int r, int a)
{
	if (l == r) {
		if ((l & 1) ^ t[x].tg) t[x].mx1 = 0;
		else t[x].mx0 = 0;
		t[x].l0 = l;
		return;
	}
	push_down(x);
	int mid = (l + r) >> 1;
	if (a <= mid) modify(x << 1, l, mid, a);
	else modify(x << 1 | 1, mid + 1, r, a);
	up(t[x], t[x << 1], t[x << 1 | 1]);
}

void modify0(int x, int l, int r, int a, int b)
{
	if (a <= l && r <= b){
		t[x].tg ^= 1;
		swap(t[x].mx0, t[x].mx1);
		swap(t[x].mx0i, t[x].mx1i);
		return;
	}
	push_down(x);
	int mid = (l + r) >> 1;
	if (a <= mid) modify0(x << 1, l, mid, a, b);
	if (b > mid) modify0(x << 1 | 1, mid + 1, r, a, b);
	up(t[x], t[x << 1], t[x << 1 | 1]);
}

Tr query(int x, int l, int r, int a, int b)
{
	if (a <= l && r <= b) return t[x];
	push_down(x);
	int mid = (l + r) >> 1;
	Tr ret = (Tr){0, 0, 0}, lc = (Tr){0, 0, 0}, rc = (Tr){0, 0, 0};
	if (a <= mid) lc = query(x << 1, l, mid, a, b);
	if (b > mid) rc = query(x << 1 | 1, mid + 1, r, a, b);
	up(ret, lc, rc);
	return ret;
}

int ans[N];

int main()
{
	//freopen("B.in", "r", stdin);
	//freopen("B.out", "w", stdout);

	int n;
	scanf("%d", &n);
	Rep(i, n){ scanf("%d", &p[i]); p[i] = n + 1 - p[i];}
	//Rep(i, n) printf("%d ", p[i]);
	//printf("\n");
	build(1, 1, n);

	Rep(i, n / 2){
		Tr t1 = query(1, 1, n, 1, n);
	//	printf("_%d %d\n", t1.mx1, t1.mx1i);
		int tr = query(1, 1, n, t1.mx1i, n).l0;
		if (!tr) tr = n + 1;
		Tr t0 = query(1, 1, n, t1.mx1i + 1, tr - 1);
		//printf("%d %d\n", t1.mx1i + 1, tr - 1);
		ans[i * 2 - 1] = t1.mx1, ans[i * 2] = t0.mx0;
		//printf("%d %d\n", t1.mx1i, t0.mx0i);
		modify(1, 1, n, t1.mx1i); modify(1, 1, n, t0.mx0i);
		modify0(1, 1, n, t1.mx1i, t0.mx0i);
	}

	Rep(i, n) printf("%d ", n + 1 - ans[i]);

	return 0;
}
