typedef long long ll;
const int maxn = 200005;

int n,a[maxn];
vector<pair<int,int>> pr;
vector<int>e[maxn];
struct ST {
    int l,r,val[2],idx[2];
} st[maxn*4];
void build(int id,int l,int r) {
    st[id].l=l,st[id].r=r;
    st[id].val[0]=st[id].val[1]=st[id].idx[0]=st[id].idx[1]=n+1;
    if(l==r) {
        st[id].val[l&1]=a[l];
        st[id].idx[l&1]=l;
        return;
    }
    int m=(l+r)>>1;
    build(id<<1,l,m);
    build(id<<1|1,m+1,r);
    for(int i=0; i<2; i++) {
        if(st[id<<1].val[i]<st[id<<1|1].val[i]) {
            st[id].val[i]=st[id<<1].val[i];
            st[id].idx[i]=st[id<<1].idx[i];
        } else {
            st[id].val[i]=st[id<<1|1].val[i];
            st[id].idx[i]=st[id<<1|1].idx[i];
        }
    }
}
int query(int id, int l,int r,int flag) {
    if(st[id].l==l&&st[id].r==r) {
        return st[id].idx[flag];
    }
    int m=(st[id].l+st[id].r)>>1;
    if(r<=m)return query(id<<1,l,r,flag);
    if(l>m)return query(id<<1|1,l,r,flag);
    int lret=query(id<<1,l,m,flag);
    int rret=query(id<<1|1,m+1,r,flag);
    if(a[lret]>a[rret])return rret;
    return lret;
}

void dfs(int l,int r,int fa_idx) {
    if(l>r)return;
    if(l+1==r) {
        int sz=pr.size();
        pr.push_back(make_pair(l,r));
        e[fa_idx].push_back(sz);
        return;
    }
    int idxl=query(1,l,r,l&1);
    int idxr=query(1,idxl+1,r,(l+1)&1);
    int sz=pr.size();
    pr.push_back(make_pair(idxl,idxr));
    e[fa_idx].push_back(sz);
    dfs(l,idxl-1,sz);
    dfs(idxl+1,idxr-1,sz);
    dfs(idxr+1,r,sz);
}

struct cmp {
    bool operator()(int x,int y) {
        auto prx=make_pair(a[pr[x].first],a[pr[x].second]);
        auto pry=make_pair(a[pr[y].first],a[pr[y].second]);
        return prx>pry;
    }
};

struct Item {
  int l,r,fa_idx;
  Item(int l,int r,int fa_idx):l(l),r(r),fa_idx(fa_idx){}
};

