struct RMQ{
    ll n;
    vector<l_l>data;
    RMQ(ll vs){
        n=1;
        while(n<vs)n*=2;
        data.resize(2*n-1,l_l(inf,-1));
    }
    void update(ll k,ll a){
        k+=n-1;
        data[k]=l_l(a,k-(n-1));
        while(k>0){
            k=(k-1)/2;
            data[k]=min(data[2*k+1],data[2*k+2]);
        }
    }
    l_l query(ll a,ll b,ll k,ll l,ll r){
        if(r<=a||b<=l)return l_l(inf,-1);
        if(a<=l&&r<=b){
            return data[k];
        }else{
            l_l vl=query(a,b,2*k+1,l,(l+r)/2);
            l_l vr=query(a,b,2*k+2,(l+r)/2,r);
            return min(vl,vr);
        }
    }
    l_l query(ll a,ll b){return query(a,b,0,0,n);}//[a,b)の最小値
};
