void dfs(ll l,ll r,vector<l_l>&ans){
    if(l>r)return;
    if(l+1==r){
        ans.pb({p[l],p[r]});
        return;
    }
    ll sl=l,sr=l+1;
    if(l%2==0){
        sl=ev.query(l,r+1).se;
    }else{
        sl=od.query(l,r+1).se;
    }
    if(l%2==1){
        sr=ev.query(sl,r+1).se;
    }else{
        sr=od.query(sl,r+1).se;
    }
    ans.pb({p[sl],p[sr]});
    if(sl==l&&sr==l+1){
        dfs(l+2,r,ans);return;
    }
    if(sl==l&&sr==r){
        dfs(l+1,r-1,ans);return;
    }
    if(sl==r-1&&sr==r){
        dfs(l,r-2,ans);return;
    }
    vector<l_l>v[3];
    dfs(l,sl-1,v[0]);
    dfs(sl+1,sr-1,v[1]);
    dfs(sr+1,r,v[2]);
    ll sz[3];rep(i,0,2)sz[i]=v[i].size();
    ll pos[3];rep(i,0,2)pos[i]=0;


