vector<pair<int,int>> merge(vector<pair<int,int>> &v1,vector<pair<int,int>> &v2,vector<pair<int,int>> &v3){
    vector<pair<int,int>> res;
    int cnt1=0,cnt2=0,cnt3=0;
    while(v1[cnt1].first<INF||v2[cnt2].first<INF||v3[cnt3].first<INF){
        if(v1[cnt1]<v2[cnt2]){
            if(v1[cnt1]<v3[cnt3]) res.push_back(v1[cnt1++]);
            else res.push_back(v3[cnt3++]);
        }else{
            if(v2[cnt2]<v3[cnt3]) res.push_back(v2[cnt2++]);
            else res.push_back(v3[cnt3++]);
        }
    }
    return res;
}


vector<pair<int,int>> rec(int l,int r){//[l,r]  l%2!=r%2
  if(l+1==r){
      vector<pair<int,int>> res;
      res.push_back(mkp(P[l],P[r]));
      return res;
  }

  int left_val=INF;
  if(l%2){
      left_val=odd_seg.getMin(l,r+1);
      odd_seg.update(trans[left_val],INF);
  }else{
      left_val=even_seg.getMin(l,r+1);
      even_seg.update(trans[left_val],INF);
  }
  seg.update(trans[left_val],INF);

  int right_val=0;
  if(r%2){
      right_val=odd_seg.getMin(l,r+1);
      odd_seg.update(trans[right_val],INF);
  }else{
      right_val=even_seg.getMin(l,r+1);
      even_seg.update(trans[right_val],INF);
  }
  seg.update(trans[right_val],INF);

  vector<pair<int,int>> v1,v2,v3;

  if(l<trans[left_val]) v1=rec(l,trans[left_val]-1);
  if(trans[right_val]-trans[left_val]+1>2) v2=rec(trans[left_val]+1,trans[right_val]-1);
  if(trans[right_val]<r) v3=rec(trans[right_val]+1,r);

  v1.push_back(mkp(INF,INF));
  v2.push_back(mkp(INF,INF));
  v3.push_back(mkp(INF,INF));
  vector<pair<int,int>> res;
  res.push_back(mkp(left_val,right_val));
  vector<pair<int,int>> w=merge(v1,v2,v3);
  for(int i=0;i<w.size();i++) res.push_back(w[i]);

  return res;
}

