      else even[i]=P[i];
  }

  odd_seg.initialize(odd);
  even_seg.initialize(even);
  seg.initialize(P);

  vector<pair<int,int>> ans=rec(0,N-1);

  for(int i=0;i<ans.size();i++){
      cout<<ans[i].first<<" "<<ans[i].second<<" ";
  }
  cout<<endl;

  return 0;
}

