void join(int *a, int i, int j, int n) {
	int *p1 = a;
	int *p2 = a + i + 1;
	int *p3 = a + j + 1;
	int index = 0;

	temp[index++] = a[i];
	temp[index++] = a[j];

	while (index < n) {
		if (p1 < a + i && (
				(p2 < a + j && p3 < a + n && *p1 < *p2 && *p1 < *p3) ||
				(p2 < a + j && p3 == a + n && *p1 < *p2) ||
				(p3 < a + n && *p1 < *p3) ||
				(p2 == a + j && p3 == a + n)))
		{
			temp[index++] = *p1++;
			temp[index++] = *p1++;
		}
		else if (p2 < a + j && (
				(p1 < a + i && p3 < a + n && *p2 < *p1 && *p2 < *p3) ||
				(p1 < a + i && p3 == a + n && *p2 < *p1) ||
				(p3 < a + n && *p2 < *p3) ||
				(p1 == a + i && p3 == a + n)))
		{
			temp[index++] = *p2++;
			temp[index++] = *p2++;
		}
		else {
			temp[index++] = *p3++;
			temp[index++] = *p3++;
		}
	}

	copy(temp, temp + n, a);
}

void solve(int *a, int n) {
	if (n > 2) {
		int pos1 = 0;
		int pos2 = 1;
		int a1 = numeric_limits<int>::max();
		int a2 = numeric_limits<int>::max();

		for (int i = 0; i < n; i += 2) {
			if (a1 > a[i]) {
				a1 = a[i];
				pos1 = i;
			}
		}
		for (int i = pos1 + 1; i < n; i += 2) {
			if (a2 > a[i]) {
				a2 = a[i];
				pos2 = i;
			}
		}

		solve(a, pos1);
		solve(a + pos1 + 1, pos2 - pos1 - 1);
		solve(a + pos2 + 1, n - pos2 - 1);

		join(a, pos1, pos2, n);
	}
}

