vector<P> calc(int l, int r){
    if (r <= 0 || l >= n || l >= r) return {};
    // cout << l << r << endl;
    int mi = sg.query(l,r,0,0,sg.width,l%2);
    int j = pos[mi];
    int mi2 = sg.query(j+1,r,0,0,sg.width,(j+1)%2);
    int j2 = pos[mi2];
    vector<P> ret0 = calc(l, j), ret1 = calc(j+1, j2), ret2 = calc(j2+1, r), ret;
    ret.push_back(P(mi, mi2));
    // REP(i,ret0.size()) cout << ret0[i].first << ret0[i].second << endl;
    int i0, i1, i2;
    i0 = i1 = i2 = 0;
    while (i0 < ret0.size() || i1 < ret1.size() || i2 < ret2.size()){
        P c0 = (i0 == ret0.size() ? P(INF,INF) : ret0[i0]);
        P c1 = (i1 == ret1.size() ? P(INF,INF) : ret1[i1]);
        P c2 = (i2 == ret2.size() ? P(INF,INF) : ret2[i2]);
        if (c0 <= c1 && c0 <= c2){
            ret.push_back(c0);
            i0++;
        }else if (c1 <= c0 && c1 <= c2){
            ret.push_back(c1);
            i1++;
        }else{
            ret.push_back(c2);
            i2++;
        }
    }
    return ret;
}

