struct minimum
{
	int x, y, ans[maxn][logn];
	inline void Init()
	{
		memset(ans, 127 / 2, sizeof(ans));
	}
	inline void Rmq()
	{
		for(int k = 1; k < logn; ++k)
			for(int i = 1; i <= n; ++i)
			{
				if(i + bin[k] - 1 > n) break;
				ans[i][k] = min(ans[i][k - 1], ans[i + bin[k - 1]][k - 1]);
			}
	}
	inline int Min(int l, int r)
	{
