};
minimum a, b;
inline bool Check(int x, int y)
{
	return ans[x] < ans[y] || (ans[x] == ans[y] && ans[x + 1] < ans[y + 1]);
}
void Solve(int l, int r)
{
	if(r - l < 1) return;
	if(r - l == 1)
	{
		ans[l] = c[l], ans[r] = c[r];
		return;
	}
	int p = n + 1, q = n + 1, x, y;
	for(int i = l; i <= r; i += 2)
	{
		x = c[i], y = (l & 1) ? b.Min(i + 1, r) : a.Min(i + 1, r);
		if(x < p || (x == p && y < q)) p = x, q = y;
	}
	Solve(l, pos[p] - 1), Solve(pos[p] + 1, pos[q] - 1), Solve(pos[q] + 1, r);
	int u = l, v = pos[p] + 1, w = pos[q] + 1;
	for(int i = l + 2; i <= r; i += 2)
	{
		if((v > pos[q] - 1 || Check(u, v)) && (w > r || Check(u, w)) && (u <= pos[p] - 1)) tmp[i] = ans[u], tmp[i + 1] = ans[u + 1], u += 2;
		else
		{
			if((u > pos[p] - 1 || Check(v, u)) && (w > r || Check(v, w)) && (v <= pos[q] - 1)) tmp[i] = ans[v], tmp[i + 1] = ans[v + 1], v += 2;
			else
				if((u > pos[p] - 1 || Check(w, u)) && (v > pos[q] - 1 || Check(w, v)) && (w <= r)) tmp[i] = ans[w], tmp[i + 1] = ans[w + 1], w += 2;
		}
	}
	ans[l] = p, ans[l + 1] = q;
	for(int i = l + 2; i <= r; ++i) ans[i] = tmp[i];
}
