int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    RMQ<int> odd(n), even(n);
    vi pos(n);
    rep(i, n){
        int e; cin >> e; e--;
        pos[e] = i;
        if(i % 2 == 0){
            even.set(i, e); odd.set(i, 10 * n);
        }
        else {
            odd.set(i, e); even.set(i, 10 * n);
        }
    }

    using Elem = tuple<int, int, int>;
    priority_queue<Elem, vector<Elem>, greater<Elem>> q;
    q.push(Elem(even.query(0, n), 0, n));

    vi res(n);
    rep(i, n / 2){
        auto cur = q.top(); q.pop();
        int va;
        int l, r; tie(va, l, r) = cur;

        auto& a = (l % 2 == 0 ? even:odd), b = (l % 2 == 0 ? odd:even);
        int pa = pos[va];
        int vb = b.query(pa + 1, r), pb = pos[vb];
        res[2 * i] = va; res[2 * i + 1] = vb;

        if(l != pa){
            q.push(Elem(a.query(l, pa), l, pa));
        }
        if(pa + 1 != pb){
            q.push(Elem(b.query(pa + 1, pb), pa + 1, pb));
        }
        if(pb + 1 != r){
            q.push(Elem(a.query(pb + 1, r), pb + 1, r));
        }

        assert(q.size() < n);
    }

    rep(i, n){
        cout << (i == 0 ? "":" ") << res[i] + 1;
    }
    cout << endl;

    return 0;
}

