int n,i,j,a[800005],b[800005][2],sum,sum2,top2,ans[800005];
int max1[800005],max2[800005],max3[800005],max4[800005],p1,p2,p3;
int top,nex[800005],to[800005],fir[800005];
set<pair<int,int> > s;
set<pair<int,int> > :: iterator it;
void lj(int u,int v){
	top++;
	nex[top]=fir[u];
	fir[u]=top;
	to[top]=v;
}
void buildtree(int u,int v,int w){
	int mid=(u+v>>1);
	if(u==v){
		if(v&1){
			max1[w]=a[v];
			max2[w]=n+1;
			max3[w]=v;
		}
		else{
			max1[w]=n+1;
			max2[w]=a[v];
			max4[w]=v;
		}
		return;
	}
	buildtree(u,mid,w<<1);
	buildtree(mid+1,v,(w<<1)|1);
	if(max1[w<<1]<max1[(w<<1)|1]){
		max1[w]=max1[w<<1];
		max3[w]=max3[w<<1];
	}
	else{
		max1[w]=max1[(w<<1)|1];
		max3[w]=max3[(w<<1)|1];
	}
	if(max2[w<<1]<max2[(w<<1)|1]){
		max2[w]=max2[w<<1];
		max4[w]=max4[w<<1];
	}
	else{
		max2[w]=max2[(w<<1)|1];
		max4[w]=max4[(w<<1)|1];
	}
}
void xtree(int u,int v,int w){
	int mid=(u+v>>1);
	if(p1<=u&&v<=p2){
		if(p3==1){
			if(max1[w]<sum2){
				sum2=max1[w];
				sum=max3[w];
			}
		}
		else{
			if(max2[w]<sum2){
				sum2=max2[w];
				sum=max4[w];
			}
		}
		return;
	}
	if(p1<=mid) xtree(u,mid,w<<1);
	if(p2>=mid+1) xtree(mid+1,v,(w<<1)|1);
}
void gb(int u,int v,int w,int ww){
	if(u>v)
		return;

	int fir=0,sec=0;

	p1=u;p2=v;
	if(u&1)
		p3=1;
	else
		p3=2;
	sum=0;sum2=n+1;
	xtree(1,n,1);
	fir=sum;

	p1=fir+1;p2=v;
	if(fir&1)
		p3=2;
	else
		p3=1;
	sum=0;sum2=n+1;
	xtree(1,n,1);
	sec=sum;

	b[ww][0]=a[fir];
	b[ww][1]=a[sec];
	if(w!=0)
		lj(w,ww);

	top2++;
	gb(u,fir-1,ww,top2);
	top2++;
	gb(fir+1,sec-1,ww,top2);
	top2++;
	gb(sec+1,v,ww,top2);
}
int main(){
    int v;
    n=read();
    for(i=1;i<=n;i++)
    	a[i]=read();
    buildtree(1,n,1);
    top2=1;
    gb(1,n,0,1);
    s.insert(make_pair(b[1][0],1));
    top=0;
    while(s.size()!=0){
    	it=s.begin();
    	v=it->second;
    	top++;
    	ans[top]=b[v][0];
    	top++;
    	ans[top]=b[v][1];
		for(int top1=fir[v];top1;top1=nex[top1])
			s.insert(make_pair(b[to[top1]][0],to[top1]));
		s.erase(make_pair(b[v][0],v));
	}
	for(i=1;i<=top;i++)
		pus(ans[i],1);
    cout<<endl;
	return 0;
}

