template <class T>
class SegTree {
    int n;                     // 葉の数
    vector<pair<T, int>> data; // データを格納するvector
    T def;                     // 初期値かつ単位元
    function<pair<T, int>(pair<T, int>, pair<T, int>)>
        operation;            // 区間クエリで使う処理
    function<T(T, T)> update; // 点更新で使う処理

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    pair<T, int> _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return mp(def, -1); // 交差しない
        if (a <= l && r <= b)
            return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            pair<T, int> c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            pair<T, int> c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return operation(c1, c2);
        }
    }

  public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTree(size_t _n, T _def,
            function<pair<T, int>(pair<T, int>, pair<T, int>)> _operation,
            function<T(T, T)> _update)
        : def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n < _n) {
            n *= 2;
        }
        data = vector<pair<T, int>>(2 * n - 1);
        rep(i, 2 * n - 1) {
            data[i] = mp(def, i - n + 1);
        }
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n - 1;
        data[i] = mp(update(data[i].first, x), i - n + 1);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    // [a, b)の区間クエリを実行
    pair<T, int> query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // 添字でアクセス
    T operator[](int i) {
        return data[i + n - 1];
    }
};

vi solve(SegTree<ll> &odd, SegTree<ll> &even, int N) {
    pql<pair<int, pair<int, int>>> Q;
    Q.push(mp(0, mp(0, N)));
    vi ans;
    ans.reserve(N);
    while (!Q.empty()) {
        auto item = Q.top();
        Q.pop();
        int l = item.second.first;
        int r = item.second.second;
        dump(l, r);

        if (l % 2 == 0) {
            auto pl2 = even.query(l, r);
            auto pr2 = odd.query(pl2.second, r);
            ans.push_back(pl2.first);
            ans.push_back(pr2.first);
            int l2 = pl2.second;
            int r2 = pr2.second;
            dump(l2, r2);

            if (l != l2) {
                Q.push(mp(even.query(l, l2).first, mp(l, l2)));
            }
            if (l2 + 1 != r2) {
                Q.push(mp(odd.query(l2 + 1, r2).first, mp(l2 + 1, r2)));
            }
            if (r2 + 1 != r) {
                Q.push(mp(even.query(r2 + 1, r).first, mp(r2 + 1, r)));
            }
        } else {
            auto pl2 = odd.query(l, r);
            auto pr2 = even.query(pl2.second, r);
            ans.push_back(pl2.first);
            ans.push_back(pr2.first);
            int l2 = pl2.second;
            int r2 = pr2.second;
            dump(l2, r2);

            if (l != l2) {
                Q.push(mp(odd.query(l, l2).first, mp(l, l2)));
            }
            if (l2 + 1 != r2) {
                Q.push(mp(even.query(l2 + 1, r2).first, mp(l2 + 1, r2)));
            }
            if (r2 + 1 != r) {
                Q.push(mp(odd.query(r2 + 1, r).first, mp(r2 + 1, r)));
            }
        }
    }
    return ans;
}

