void solve(vector<int> dir, int f, int s)
{
	int flag = 0;
	if (dir.empty()) return;
	int maxhead = 0, cnt = 0, down;
	for (int i = 0; i < dir.size() - 1; ++i) {
		if (dir[i] != f && dir[i] != s) {
			if (dir[i + 1] != f && dir[i + 1] != s) {
				if (dir[i] > maxhead) {
					maxhead = dir[i];
					down = i;
					flag = 1;
				}
			}
		}
	}
	if (!flag) return;
	ans.push_back(dir[down + 1]); ans.push_back(dir[down]);
	vector<int> nex;
	for (int i = 0; i < dir.size(); ++i) {
		if (i != down && i != down + 1) {
			nex.push_back(dir[i]);
		}
	}
	solve(nex, f, s);
}

