template<typename dst>
node *solve(int l, int r, const dst &todd, const dst &teven){
    node *ret = new node();
    int sl, sr;
    ret->children[0] = ret->children[1] = ret->children[2] = nullptr;
    ret->val.first  = (l % 2 ? todd : teven).get(l, r);
    sl = pinv[ret->val.first];
    ret->val.second = (l % 2 ? teven : todd).get(sl+1, r);
    sr = pinv[ret->val.second];
    if(l < sl) ret->children[0] = solve(l, sl, todd, teven);
    if(sl+1 < sr) ret->children[1] = solve(sl+1, sr, todd, teven);
    if(sr+1 < r) ret->children[2] = solve(sr+1, r, todd, teven);
    return ret;
}
