            count_++;
            int count__ = count_;
            G[par].push_back(count_);
            if(l < f[mi]-1)dfs(0, l, f[mi]-1, -1, par);
            if(f[mi]+1 < r)dfs(0, f[mi]+1, r, -1, count__);
        }
    }
}

