#include <bits/stdc++.h>
using namespace std;

const int maxn = 440000;

template <typename T>
struct WinnerTree {
	int m;
	T b[1<<20];
	void build(T *a, int n) {
		m = 1<<(32-__builtin_clz(n));
		for (int i = 0; i < m; i++) b[m+i] = ((i < n) ? a[i] : a[0]);
		for (int i = m-1; i >= 0; i--) b[i] = min(b[i+i], b[i+i+1]);
	}
	void update(int p, T x) {
		for (p += m, b[p] = x, p >>= 1; p; p >>= 1) b[p] = min(b[p+p], b[p+p+1]);
	}
	T get(int l, int r) {
		l += m, r += m;
		assert(l < r);
		T ret = b[l];
		while (l < r) {
			if (l & 1) ret = min(ret, b[l]);
			if (r & 1) ret = min(ret, b[r-1]);
			l = l+1>>1, r >>= 1;
		}
		return ret;
	}
};

WinnerTree<pair<int, int>> wt1, wt2;

int p[maxn];
pair<int, int> p1[maxn];
pair<int, int> p2[maxn];
pair<int, int> res[maxn];
vector<int> g[maxn];
int o = 0;

inline void solve(int l, int r, int p) {
	if(l >= r) return;
	pair<int, int> fir, sec;
	if(l & 1) {
		fir = wt2.get(l / 2, r / 2);
		sec = wt1.get((fir.second + 1) / 2, (r + 1) / 2);
	} else {
		fir = wt1.get(l / 2, r / 2);
		sec = wt2.get(fir.second / 2, r / 2);
	}
	res[++ o] = make_pair(fir.first, sec.first);
	g[p].push_back(o);
	int no = o;
	solve(l, fir.second, no);
	solve(fir.second + 1, sec.second, no);
	solve(sec.second + 1, r, no);
}

struct comp {
	bool operator () (const int& i, const int& j) {
		return res[i].first > res[j].first;
	}
};

priority_queue<int, vector<int>, comp> q;
vector<int> ans;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	int n; cin >> n;
	for(int i = 0; i < n; ++ i) cin >> p[i];
	for(int i = 0; i < n; i += 2) p1[i / 2] = make_pair(p[i], i);
	for(int i = 1; i < n; i += 2) p2[i / 2] = make_pair(p[i], i);
	wt1.build(p1, n / 2); wt2.build(p2, n / 2);
	solve(0, n, 0);
	q.push(1);
	while(!q.empty()) {
		int cur = q.top(); q.pop();
		ans.push_back(res[cur].first);
		ans.push_back(res[cur].second);
		for(auto v : g[cur]) q.push(v);
	}
	assert(ans.size() == n);
	for(int i = 0; i < n; ++ i) cout << ans[i] << " \n"[i == n - 1];
	return 0;
}

