        pos[arr[i]]=i;
        update(1,i%2,0,n-1,i,arr[i]);
        update(1,1-i%2,0,n-1,i,n+1);
    }
    queue<ii>q;
    queue<int>dep;
    q.push(ii(0,n-1));
    dep.push(0);
    while(q.size()){
      ii top=q.front();
      q.pop();
      int d=dep.front();
      dep.pop();
      int a=top.first,b=top.s;
      if(a>=b)continue;
      if(a+1==b){
        //cout<<arr[a]<<' '<<arr[b]<<endl;
