        int second_val=get(1,1-a%2,0,n-1,idx,b);
        int second_idx=pos[second_val];
        q.push(ii(idx+1,second_idx-1));
        dep.push(d+1);
        q.push(ii(second_idx+1,b));
        dep.push(d+1);
        sol[d].push_back(ii(val,second_val));
      }
    }
   for(int i=0;i<N;i++){
    sort(sol[i].begin(),sol[i].end());
    for(int j=0;j<sol[i].size();j++)cout<<sol[i][j].f<<' '<<sol[i][j].s<<' ';
   }
    return 0;
}

