int n;
int dat_odd[2 * (1 << 17) - 1];
int dat_even[2 * (1 << 17) - 1];

void init(int n_) {
    n = 1;
    while (n < n_) {
        n *= 2;
    }

    REP (i, 2 * n - 1) {
        dat_odd[i] = 100000;
        dat_even[i] = 100000;
    }
}


int body(int &argc, char **argv);

// main function (DO NOT EDIT)
int main (int argc, char **argv) {
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    return body(argc, argv);
}

vector<int> ps;

void update(int k, int a) {
    int *dat = nullptr;
    if (k % 2 == 0) {
        dat = dat_even;
        k /= 2;
    } else {
        dat = dat_odd;
        k /= 2;
    }

    k += n - 1;
    dat[k] = a;
    while (k > 0) {
        k = (k - 1) / 2;
        auto n1 = dat[k * 2 + 1];
        auto n2 = dat[k * 2 + 2];
        if (n1 == 100000) {
            dat[k] = n2;
        } else if (n2 == 100000) {
            dat[k] = n1;
        } else {
            if (ps[n1] < ps[n2]) {
                dat[k] = n1;
            } else {
                dat[k] = n2;
            }
        }
    }
}

int query(int * dat,int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
        return 100000;
    }

    if (a <= l && r <= b) {
        return dat[k];
    } else {
        int vl = query(dat, a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(dat, a, b, k * 2 + 2, (l + r) / 2, r);
        if (vl >= 100000) {
            return vr;
        } else if (vr >= 100000) {
            return vl;
        }
        if (ps[vl] < ps[vr]) {
            return vl;
        } else {
            return vr;
        }
    }
}

// [a, b)の最小値
int query_int(int a, int b, int k, int l, int r) {
    int *dat = nullptr;
    if (a % 2 == 0) {
        dat = dat_even;
    } else {
        dat = dat_odd;
    }
    a /= 2;
    b /= 2;

    return query(dat, a, b, k, l, r);

}
int body(int &argc, char **argv) {
    auto N = read<i32>();
    ps = read<i32>(N);

    init(N / 2);
    REP(i, N) {
        update(i, i);
    }

    using namespace debug;

    unordered_map<pair<i32, i32>, i32> candidates;

    auto calc = [&](i32 begin, i32 end) -> i32 {
        i32 first = query_int(begin, end, 0, 0, n);
        //i32 second = query_int(first + 1, end + 1, 0, 0, n);
        return first;
    };

    candidates.insert(make_pair(make_pair(0, N), calc(0, N)));

    auto qs = V<i32>();
    while (qs.size() != (size_t)N) {
        auto next = min_element(candidates.begin(), candidates.end(), [&](auto e1, auto e2) {
            return ps[e1.second] < ps[e2.second];
        });


        auto begin = next->first.first;
        auto end = next->first.second;
        auto first = next->second;
        auto second = query_int(first + 1, end + 1, 0, 0, n);

        qs.push_back(ps[first]);
        qs.push_back(ps[second]);
        candidates.erase(next);

        if (begin != first) {
            candidates.insert(make_pair(make_pair(begin, first), calc(begin, first)));
        }
        if (first + 1 != second) {
            candidates.insert(make_pair(make_pair(first + 1, second), calc(first + 1, second)));
        }
        if (second + 1 != end) {
            candidates.insert(make_pair(make_pair(second + 1, end), calc(second + 1, end)));
        }
    }

    REP (i, N) {
        cout << qs[i];
        if (i != N - 1) {
            cout << " ";
        }
    }
    cout << endl;

    return 0;
}

