// SegmentTree (実装は range minimum query)
class SegmentTree
{
private:
	// const long long inf = 1e18;
	long long inf = 1e18;
	int n;
	vector<long long> dat;
public:
	SegmentTree(int n_) {
		n = 1;
		while (n < n_) {
			n *= 2;
		}

		dat.assign(n * 2 - 1, inf);
	};
	~SegmentTree() {
		dat.clear();
	};

	void update(int k, int a) {
		k += n - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k*2 + 1], dat[k*2 + 2]);
		}
	}

	long long query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) {
			return inf;
		}

		if (a <= l && r <= b) {
			return dat[k];
		} else {
			long long vl = query(a, b, k*2 + 1, l, (l+r)/2);
			long long vr = query(a, b, k*2 + 2, (l+r)/2, r);
			return min(vl, vr);
		}
	}

	// [a, b)の範囲での値
	long long query(int a, int b) {
		return query(a, b, 0, 0, n);
	}

	void show() {
		int i = 0;
		for (auto e: dat) {
			printf("%3d: %6lld\n", i, e);
			i++;
		}
	}
};

vector<SegmentTree> segs;
vector<int> val2index;

class AAA {
public:
	int x, y;
	int r, l;

	AAA(int ll, int rr) {
		l = ll;
		r = rr;
// printf("AAA %d - %d: ", l, r);

		if (r - l < 1) {
// printf("-1\n");
			x = y = -1;
			return;
		}

		x = segs[l % 2].query(l, r);
		y = segs[(l + 1) % 2].query(l, r);
// printf("xy %d %d\n", x, y);
	}
};

bool operator < (const AAA &a, const AAA &b) {
	return a.x < b.x;
}
bool operator > (const AAA &a, const AAA &b) {
	return a.x > b.x;
}

int main() {
	int n;
	cin >> n;

	vector<int> p(n, 0);
	segs.assign(2, SegmentTree(n));
	val2index.assign(n + 1, -1);

	for (int i = 0; i < n; i++) {
		cin >> p[i];
		val2index[p[i]] = i;
		segs[i % 2].update(i, p[i]);
	}
	// show(val2index);
	priority_queue<AAA, vector<AAA>, greater<AAA>> que;
	vector<int> ans;

	AAA aaa(0, n);

	que.push(aaa);
	while(!que.empty()) {
		auto a = que.top();
		que.pop();

		if (a.x == -1) {
			continue;
		}

		ans.emplace_back(a.x);
		ans.emplace_back(a.y);

		// cout << "ans: ";
		// show(ans);

		int x_idx = val2index[a.x];
		int y_idx = val2index[a.y];

		que.push(AAA(a.l,       x_idx));
		que.push(AAA(x_idx + 1, y_idx));
		que.push(AAA(y_idx + 1, a.r));
	}

	show(ans);
	return 0;
}

