template<typename T>
struct SparseTable {
  vector<T> v;
  VV st;
  int op(const int a, const int b) {
    return (v[a] == v[b]) ? min(a, b) : ((v[a] < v[b]) ? a : b);
  } 
  void init(const vector<T> &_v) {
    v = _v;
    int n = v.size();
    st = {V(n)}; iota(all(st[0]), 0);
    for (int j = 0; n>>(j+1); ++j) {
      int m = n+1-(1<<(j+1));
      st.push_back(V(m));
      rep(i, m) st[j+1][i] = op(st[j][i], st[j][i+(1<<j)]);
    }
  }
  int index(const int l, const int r) { int d = fLog2(r-l); return op(st[d][l], st[d][r-(1<<d)]); }
  T query(const int l, const int r) { return v[index(l, r)]; }
};


SparseTable<int> rmq[2];


int main() {
  int n; cin >> n;
  V p(n); cin >> p;
  VV q(2, V(n, INF));
  rep(i, n) q[i%2][i] = p[i];
  rep(i, 2) rmq[i].init(q[i]);

  auto f = [&] (int l, int r) {
    int m = l % 2;
    int i = rmq[m].index(l, r);
    return p[i];
  };

  priority_queue<pair<int, P>> pq;
  pq.emplace(-f(0, n), P{0, n});
  V ans;

  while (!pq.empty()) {
    auto [_, lr] = pq.top(); pq.pop();
    auto [l, r] = lr;

    int m = l % 2;
    int i = rmq[m].index(l, r);
    int j = rmq[m^1].index(i, r);
    ans.push_back(p[i]);
    ans.push_back(p[j]);

    if (l < i)   pq.emplace(-f(l, i), P{l, i});
    if (i+1 < j) pq.emplace(-f(i+1, j), P{i+1, j});
    if (j+1 < r) pq.emplace(-f(j+1, r), P{j+1, r});
  }

  cout << ans << '\n';
  return 0;
}

