struct SparseTable{
    vector<vector<P>>table;
    vector<int>logtable;
    void init(vector<int>v){
        int len=0;
        while((1<<len)<=v.size())len++;
        table.assign(len,vector<P>(1<<len));
        rep(i,v.size())table[0][i]={v[i],i};
        for(int i=1;i<len;i++){
            for(int j=0;j+(1<<i)<=(1<<len);j++){
                table[i][j]=min(table[i-1][j],table[i-1][j+(1<<(i-1))]);
            }
        }
        logtable.resize(v.size()+1);
        for(int i=2;i<logtable.size();i++){
            logtable[i]=logtable[(i>>1)]+1;
        }
    }
    P query(int l,int r){
        int len=logtable[r-l];
        return min(table[len][l],table[len][r-(1<<len)]);
    }
};
vector<SparseTable>st(2);
vector<vector<int>>ans;
void func(int x,int y){
    //[x,y)
    P l=st[x%2].query(x,y);
