vector<pll> rek(int start, int end, vll& p){

	if(end - start == 2){
		return {{p[start], p[start+1]}};
	}

	if(end - start == 0){
		return {};
	}

	ll mi_ger = start;
	ll mi_un = start+1;

	for (int i = start; i < end; i+=2) {
		if(p[i] < p[mi_ger]){
			mi_ger = i;
		}
	}

	for (int i = mi_ger+1; i < end; i+=2) {
		if(p[i] < p[mi_un]){
			mi_un = i;
		}
	}

	vector<pll> s1 = rek(start, mi_ger, p);
	vector<pll> s2 = rek(mi_ger+1, mi_un, p);
	vector<pll> s3 = rek(mi_un+1, end, p);

	vector<pll> erg = {{p[mi_ger], p[mi_un]}};

	while(sz(s1) || sz(s2) || sz(s3)){
		auto tmp = s1.begin();

		if(sz(s2)){
			if(!sz(s1)){
				tmp = s2.begin();
			} else{
				if((*s2.begin()) < (*tmp))
					tmp = s2.begin();
			}
		}

		if(sz(s3)){
			if(!sz(s1) && !sz(s2)){
				tmp = s3.begin();
			} else {
				if((*s3.begin()) < (*tmp))
					tmp = s3.begin();
			}
		}

		erg.pb(*tmp);
		if(tmp == s1.begin())
			s1.erase(s1.begin());
		if(tmp == s2.begin())
			s2.erase(s2.begin());
		if(tmp == s3.begin())
			s3.erase(s3.begin());
	}

	return erg;
}

