signed main(){
	int N;
	cin >> N;
	vector<int>a(N);
	REP(i,N)cin >> a[i];
	auto odd = SegmentTree<pair<int,int>>(N,{INF,INF},[&](pair<int,int> a,pair<int,int> b){return min(a,b);});
	auto even = SegmentTree<pair<int,int>>(N,{INF,INF},[&](pair<int,int> a,pair<int,int> b){return min(a,b);});
	REP(i,N){
		if(i&1)odd.update(i,{a[i],i});
		else even.update(i,{a[i],i});
	}
	priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<pair<int,pair<int,int>>>>que;
	que.push({-INF,{0,N}});
	auto f = [&](int l,int r)->pair<int,pair<int,int>>{
		return {min(even.query(l,r).first,odd.query(l,r).first),{l,r}};
	};
	while(!que.empty()){
		auto q = que.top();
		que.pop();
		int l = q.second.first,r = q.second.second;
		if(l & 1){
			auto lid = odd.query(l,r);
			odd.update(lid.second,{INF,INF});
			auto rid = even.query(l,r);
			even.update(rid.second,{INF,INF});
			ans.push_back({lid.first,rid.first});
			if(lid.second - l >= 2)que.push(f(l,lid.second));
			if(rid.second - (lid.second + 1) >= 2)que.push(f(lid.second+1,rid.second));
			if(r - (rid.second + 1) >= 2)que.push(f(rid.second+1,r));
		}else{
			auto lid = even.query(l,r);
			even.update(lid.second,{INF,INF});
			auto rid = odd.query(lid.second,r);
			odd.update(rid.second,{INF,INF});
			ans.push_back({lid.first,rid.first});
			if(lid.second - l >= 2)que.push(f(l,lid.second));
			if(rid.second - (lid.second + 1) >= 2)que.push(f(lid.second+1,rid.second));
			if(r - (rid.second + 1) >= 2)que.push(f(rid.second+1,r));
		}
	}
	for(auto e:ans){
		cout << e.first << " " << e.second << " ";
	}
	cout << endl;
}

