void change(int aa[], int bb[], int r) {
	bb[r]=aa[r];
	for (int i=1; i<lowbit(r); i<<=1)
		bb[r]=min(bb[r], bb[r-i]);
}
int getmin(int aa[], int bb[], int l, int r) {
	int ret=aa[r];
	while (l<=r) {
		ret=min(ret, aa[r]);
		for (--r; r-l>=lowbit(r); r-=lowbit(r))
			ret=min(ret, bb[r]);
	}
	return ret;
}
