int solve(int l, int r) {
	if (l>r)
		return -1;
	if (r-l==1) {
		return getid(make_pair(a[l], a[r]));
	}
	int v1=getmin(abit[l&1], bit[l&1], (l>>1)+1, ((r-1)>>1)+1);
	int p1=gao[v1];
	int v2=getmin(abit[(l&1)^1], bit[(l&1)^1], ((p1+1)>>1)+1, (r>>1)+1);
	int p2=gao[v2];
	int x=getid(make_pair(v1, v2));
	solve(l, p1-1);
	solve(p2+1, r);
	int y=solve(p1+1, p2-1);
	g[y].push_back(x);
	indgr[x]++;
	return x;
}
