struct seg_tr{
    const static int MAX=1<<18;
    int tr[MAX<<1];
    void init(int n,int *arr) {
        for(int i=0;i<n;i++) tr[i+MAX]=arr[i];
        for(int i=MAX-1;i;i--) tr[i]=min(tr[i*2],tr[i*2+1]);
    }
    int get(int l,int r) {
        l+=MAX;r+=MAX;

        int mx=MAX;
        while(l<=r){
            mx=min({mx,tr[l],tr[r]});
            if(l&1)l++; if(!(r&1)) r--;
            l>>=1; r>>=1;
        }
        return mx;
    }
}tr[2];

int n,arr[200000],tmp[200000],pos[200001];
