struct td{
    int l,r,v[2];
    bool operator<(const td &rhs)const {
        return v[0]>rhs.v[0];
    }
};

bool make(int l,int r,td &v) {
    if(l>r) return false;

    v.v[0] = tr[l%2].get(l/2,(r-l%2)/2);

    int li=(pos[v.v[0]]+1)/2;
    v.v[1]=tr[(l%2)^1].get(li,r/2);
    v.l=l; v.r=r;
    return true;
}
