void msort(int l,int r)
{
	if (r-l<3) return;
	int i,j,k,ms=l,ms2;
	bool sx=1,jx=1;	
	vector<int> t;
	for (i=l;i<r;i++)
	{
		if (num[i]<num[i+1]) jx=0; else sx=0;
	}
	if (sx) 
	{
		for (i=l;i<=r;i++) t.push_back(num[i]);	
		for (i=0;i<t.size();i++) num[i+l]=t[i];
		return;
	}
	if (jx)
	{
		for (i=r-1;i>=l;i-=2) {t.push_back(num[i]);t.push_back(num[i+1]);}
		for (i=0;i<t.size();i++) num[i+l]=t[i];
		return;
	}
	for (i=l+2;i<r;i+=2)
	{
		if (num[i]<num[ms]) ms=i;
	}
	ms2=ms+1;
	for (i=ms+3;i<=r;i+=2)
	{
		if (num[i]<num[ms2]) ms2=i;
	}
	t.push_back(num[ms]);
	t.push_back(num[ms2]);
	if (ms+1==ms2)
	{
		msort(l,ms-1);
		msort(ms2+1,r);
		i=l;j=ms2+1;
		while (i<ms&&j<r)
		{
			if (num[i]<num[j])
			{
				t.push_back(num[i]);
				t.push_back(num[i+1]);
				i+=2;
			}
			else
			{
				t.push_back(num[j]);
				t.push_back(num[j+1]);
				j+=2;
			}
		}
		while (i<ms)
		{
			t.push_back(num[i]);
			t.push_back(num[i+1]);
			i+=2;
		}
		while (j<r)
		{
			t.push_back(num[j]);
			t.push_back(num[j+1]);
			j+=2;
		}
	}
	else
	{
		msort(l,ms-1);
		msort(ms+1,ms2-1);
		msort(ms2+1,r);
		i=l;j=ms2+1;k=ms+1;
		while (i<ms&&j<r&&k<ms2)
		{
			if (num[i]<num[j]&&num[i]<num[k])
			{
				t.push_back(num[i]);
				t.push_back(num[i+1]);
				i+=2;
			}
			else if (num[j]<num[i]&&num[j]<num[k])
			{
				t.push_back(num[j]);
				t.push_back(num[j+1]);
				j+=2;
			}
			else
			{
				t.push_back(num[k]);
				t.push_back(num[k+1]);
				k+=2;
			}
		}
		while (i<ms&&j<r)
		{
			if (num[i]<num[j])
			{
				t.push_back(num[i]);
				t.push_back(num[i+1]);
				i+=2;
			}
			else
			{
				t.push_back(num[j]);
				t.push_back(num[j+1]);
				j+=2;
			}
		}
		while (i<ms&&k<ms2)
		{
			if (num[i]<num[k])
			{
				t.push_back(num[i]);
				t.push_back(num[i+1]);
				i+=2;
			}
			else
			{
				t.push_back(num[k]);
				t.push_back(num[k+1]);
				k+=2;
			}
		}
		while (j<r&&k<ms2)
		{
			if (num[j]<num[k])
			{
				t.push_back(num[j]);
				t.push_back(num[j+1]);
				j+=2;
			}
			else
			{
				t.push_back(num[k]);
				t.push_back(num[k+1]);
				k+=2;
			}
		}
		while (i<ms)
		{
			t.push_back(num[i]);
			t.push_back(num[i+1]);
			i+=2;
		}
		while (j<r)
		{
			t.push_back(num[j]);
