		pair < int, pair <int, int> > p = pq.top();
		pq.pop();
		int l = pos[-p.first];
		int next = get(1, 0, n - 1, p.second.first, p.second.second, 1 - p.second.first % 2);
		int r = pos[next];
		pair < int, pair <int, int> > f, s, tt;
