    ll m=sqrt(N)+1;
    vector<vector<pii>> min(m+1,vector<pii>(2,mp(INF,INF)));
    vector<bool> F2(m+1);
    rep(i,0,N){
        min[i/m][i%2]=std::min(min[i/m][i%2],mp(A[i],i));
    }
    std::set<ll> set;
    set.insert(N-1);
    rep(_,0,N/2){
        pii p=RMQ(0,0,N-1,m,N,min,A,F,F2);
        ll X=*set.lower_bound(p.second);
        pii q=RMQ(1,p.second,X,m,N,min,A,F,F2);
