priority_queue<data> q;

struct Seg{
	int t[maxn<<2];
	#define mid (l+r>>1)
	#define ls u<<1
	#define rs u<<1|1
	#define lc ls,l,mid
	#define rc rs,mid+1,r
	#define rt 1,1,n
	void clear(){
		memset(t,0x3f,sizeof t);
	}
	void update(int u,int l,int r,int k,int v){
		if(l==r){
			t[u]=v;
			return;
		}
		if(k<=mid)update(lc,k,v);
		else update(rc,k,v);
		t[u]=min(t[ls],t[rs]);
	}
	int query(int u,int l,int r,int ql,int qr){
		if(ql<=l&&r<=qr){
			return t[u];
		}
		int ret=oo;
		if(ql<=mid)ret=min(ret,query(lc,ql,qr));
		if(qr>mid)ret=min(ret,query(rc,ql,qr));
		return ret;
	}
}a[2];

