const int MAXN = 2 * 100000, INF = 1000 * 1000 * 1000;
int a[MAXN + 1], n;
pair<int, int> t[4 * MAXN + 1][4];
bool ff;

void build(int v = 1, int l = 1, int r = n) {
    if(l == r) {
        t[v][0] = { a[l], l };
        t[v][1] = { l & 1 ? a[l] : INF, l };
        t[v][2] = { l % 2 == 0 ? a[l] : INF, l };
    }
    else {
        int m = (l + r) / 2;
        build(v * 2, l, m);
        build(v * 2 + 1, m + 1, r);
        for(int sh = 0; sh < 3; sh++)
            t[v][sh] = min(t[v * 2][sh], t[v * 2 + 1][sh]);
    }
}

void upd(int pos, int val, int v = 1, int l = 1, int r = n) {
    if(l == r) {
        t[v][0] = { val, l };
        t[v][1] = { val, l };
        t[v][2] = { val, l };
    }
    else {
        int m = (l + r) / 2;
        if(pos <= m)
            upd(pos, val, v * 2, l, m);
        else
            upd(pos, val, v * 2 + 1, m + 1, r);
        for(int sh = 0; sh < 3; sh++)
            t[v][sh] = min(t[v * 2][sh], t[v * 2 + 1][sh]);
    }
}

pair<int, int> getVal(int sh, int l, int r, int tv = 1, int tl = 1, int tr = n) {
    if(l > r)
        return { INF, INF };
    else if(l == tl && r == tr) {
        return t[tv][sh];
    }
    else {
        int tm = (tl + tr) / 2;
        pair<int, int> res1 = getVal(sh, l, min(tm, r), tv * 2, tl, tm);
        pair<int, int> res2 = getVal(sh, max(tm + 1, l), r, tv * 2 + 1, tm + 1, tr);
        return min(res1, res2);
    }
}

vector<int> ans;
vector<pair<int, int> > vec;

pair<int, int> solve(int l, int r) {
    if(l >= r)
        return { INF, INF };
    //cout << l << " " << r << "\n";
    assert((r - l + 1) % 2 == 0);
    int p1 = getVal((l & 1) ? 1 : 2, l, r - 1).second;
    int p2 = getVal((p1 & 1) ? 2 : 1, p1 + 1, r).second;
    upd(p1, INF);
    upd(p2, INF);
    pair<int, int> lft = solve(l, p1 - 1);
    pair<int, int> mid = solve(p1 + 1, p2 - 1);
    pair<int, int> rght = solve(p2 + 1, r);

    vec.push_back(lft);
    vec.push_back(mid);
    vec.push_back(rght);
    sort(vec.begin(), vec.end());
    for(int i = 2; i >= 0; i--) {
        if(vec[i].first == INF)
            continue;
        ans.push_back(vec[i].second);
        ans.push_back(vec[i].first);
    }
    vec.clear();

    return { a[p1], a[p2] };
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    cin >> n;
    for(int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }
    build();
    pair<int, int> temp = solve(1, n);
    ans.push_back(temp.second);
    ans.push_back(temp.first);
    reverse(ans.begin(), ans.end());
    for(auto x: ans)
        printf("%d ", x);
    printf("\n");
    return 0;
}

