void f(int p, int q) {
	int i, t1, t2;
	if (q - p <= 0) return;
	if (q - p == 1) {
		qu.push({p, q, p, q});
		return;
	}
	for (i = 1; 1<<i <= q-p+1; i++);
	i--;
	t1 = mn(d[p][i], d[q - (1 << i) + 1][i]);
	if (q - t1 == 1) {
		qu.push({t1, q, p, q});
		return;
	}
	for (i = 1; 1<<i <= q-t1; i++);
	i--;
	t2 = mn(d[t1 + 1][i], d[q - (1 << i) + 2][i]);
	qu.push({t1, t2, p, q});
}
