class Seg{
public: 

  //遅延用の型  
  struct T{
    int type; //0 - empty   , 1 - update
    int value;
    T():type(0),value(0){}
    T(int type,int value):type(type),value(value){}
  };

  //マージ可能な主データ型
  struct D{
    int value,idx;
    D():value(INF),idx(INF){} /*適切な値にする!!!!!!*/
    D(int value,int idx):value(value),idx(idx){}
    bool operator < (D a)const {return value < a.value;} //merge用
  };

  int n;
  vector<D> dat;
  vector<T> td;
  D returnD = D(INF,INF); // 範囲外の時に返す値。

  Seg(){n=-1;}
  Seg(int n_){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1,T());
    dat.resize(2*n-1,D());
  }

  D merge(D a,D b){return min(a,b);}

  void delay(int k,int len){
    return;
    if(td[k].type==0) return;
  }

  D update(int k,int x,int idx, int len){
    dat[k].value = x;
    dat[k].idx = idx;
    return dat[k];
  }

  //[a,b)の値をx変更　add(a,b,x)
  D query(int a,int b,int x,int idx,bool flg=true,int k=0,int l=0,int r=-1){
    if(r==-1) r=n, assert(a <= n && b <= n);
    if(r<=a||b<=l) return flg? dat[k]:returnD;
    if(a<=l&&r<=b) return flg? update(k, x, idx, r - l):dat[k];

    //delay(k, r - l);
    D vl = query(a,b,x,idx,flg,k*2+1,l,(l+r)/2);
    D vr = query(a,b,x,idx,flg,k*2+2,(l+r)/2,r);
    if(flg) dat[k] = merge(vl,vr);
    return merge(vl,vr);
  }

  //[a,b)の合計値を得る　find(a,b);
  P find(int a,int b){
    D res = query(a,b,0,0,false);
    return P(res.idx,res.value);
  }
};

