        st[0].update(i, p[i]);
    for(int i=1; i<N; i+=2)
        st[1].update(i, p[i]);

    vector<int> ans;
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;
    pq.push(make_tuple(st[0].query(0, N), 0, N-1));
