        n=1;
        while(n<n_)n*=2;
        node.assign(2*n,INF);
    }
    void update(int k,int x){
        k+=n-1;
        node[k]=x;
        while(k>0){
            k=(k-1)/2;
            node[k]=min(node[2*k+1],node[2*k+2]);
        }
    }
    int getmin(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return INF;
        if(a<=l&&r<=b)return node[k];
        int vl=getmin(a,b,2*k+1,l,(l+r)/2);
        int vr=getmin(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
    }
};
int main(){
    int n;cin>>n;
    int a[200010],id[200010];
    priority_queue<pair<P,P>,vector<pair<P,P>>,greater<pair<P,P>>> q;
    Segtree tree1(n+1),tree2(n+1);
    for(int i=0;i<n;i++){
        cin>>a[i];
        id[a[i]]=i;
        if(i%2==0){
            tree1.update(i,a[i]);
        }else{
            tree2.update(i,a[i]);
        }
    }
    q.push(make_pair(P(tree1.getmin(0,n),id[tree1.getmin(0,n)]),P(-1,n)));
    vector<int> ans;
    while(!q.empty()){
        pair<P,P> p=q.top();q.pop();
        int idx=p.first.second,l=p.second.first,r=p.second.second;
        ans.push_back(p.first.first);
        int nl=idx+1,nr;
        if(idx%2==0){
            tree1.update(idx,INF);
            int mi=tree2.getmin(idx,r);
            ans.push_back(mi);
            tree2.update(id[mi],INF);
            nr=id[mi];
        }else{
            tree2.update(idx,INF);
            int mi=tree1.getmin(idx,r);
            ans.push_back(mi);
            tree1.update(id[mi],INF);
            nr=id[mi];
        }
        if(idx-l>2){
            if((l+1)%2==0){
                q.push(make_pair(P(tree1.getmin(l+1,idx),id[tree1.getmin(l+1,idx)]),P(l,idx)));
            }else{
                q.push(make_pair(P(tree2.getmin(l+1,idx),id[tree2.getmin(l+1,idx)]),P(l,idx)));
            }
        }
        if(nr-nl>=2){
            if(nl%2==0){
                q.push(make_pair(P(tree1.getmin(nl,nr),id[tree1.getmin(nl,nr)]),P(nl-1,nr)));
            }else{
                q.push(make_pair(P(tree2.getmin(nl,nr),id[tree2.getmin(nl,nr)]),P(nl-1,nr)));
            }
        }
        if(r-nr>2){
            if((nr+1)%2==0){
                q.push(make_pair(P(tree1.getmin(nr+1,r),id[tree1.getmin(nr+1,r)]),P(nr,r)));
            }else{
                q.push(make_pair(P(tree2.getmin(nr+1,r),id[tree2.getmin(nr+1,r)]),P(nr,r)));
            }
        }
    }
    for(int i=0;i<ans.size();i++){
        cout<<ans[i]<<" ";
    }
    cout<<endl;
}

