};
bool operator<( Node n1 , Node n2 ){
	return n1.val < n2.val;
}
bool operator>( Node n1 , Node n2 ){
	return n1.val > n2.val;
}

struct Rmq{
	Node tree[MAXN*4];
	bool sw;	//  1:odd  0:even
	Rmq(){ sw = 0; }
	Rmq( bool ssw ){ sw = ssw; }
	void update( int pos ){
		tree[pos] = min( tree[ pos << 1 ] , tree[ pos << 1 | 1 ] );
	}
	void build( int l , int r , int pos ){
		if( l == r ){
			if( sw == (l & 1) )
				tree[pos] = Node( l , inp[l] );
			else
				tree[pos] = Node( 0 , INF );
		}else{
			int mid = (l+r) >> 1;
			build( l , mid , pos << 1 );
			build( mid+1 , r , pos << 1 | 1 );
			update( pos );
		}
	}
	Node query( int gl , int gr , int l , int r , int pos ){
		if( gl <= l  &&  r <= gr ) return tree[pos];
		int mid = (l+r) >> 1;
		Node ans1 = Node( 0 , INF) , ans2 = Node( 0 , INF);
		if( gl <= mid ) ans1 = query( gl , gr , l , mid , pos << 1 );
		if( gr > mid ) ans2 = query( gl , gr , mid+1 , r , pos << 1 | 1 );
		return min( ans1 , ans2 );
	}
	Node query( int gl , int gr ){	// [ gl , gr ]
		return query( gl , gr , 1 , n , 1 );
	}
};
