const int N = 2e5 + 7;

struct segm_tree
{
    int t[4 * N];
    int ind[4 * N];

    void build(int v, int l, int r, const vector <int> &a)
    {
        if (r - l == 1)
        {
            t[v] = a[l];
            ind[v] = l;
        }
        else
        {
            int m = (l + r) / 2;
            build(v * 2 + 1, l, m, a);
            build(v * 2 + 2, m, r, a);
            if (t[v * 2 + 1] < t[v * 2 + 2])
            {
                t[v] = t[v * 2 + 1];
                ind[v] = ind[v * 2 + 1];
            }
            else
            {
                t[v] = t[v * 2 + 2];
                ind[v] = ind[v * 2 + 2];
            }
        }
    }

    pair <int, int> get(int v, int l, int r, int tl, int tr)
    {
        if (tl >= r || tr <= l)
        {
            return {1e9, -1};
        }
        if (tl >= l && tr <= r)
        {
            return {t[v], ind[v]};
        }
        else
        {
            int tm = (tl + tr) / 2;
            return min(get(v * 2 + 1, l, r, tl, tm), get(v * 2 + 2, l, r, tm, tr));
        }
    }

    segm_tree()
    {
    }
};

segm_tree t[2];
int n;
int arr[N];
vector <int> ans;

set <pair <pair <int, int>, pair <int, int> > > e;

pair <int, int> find_splits(int l, int r)
{
    int p = l % 2;
    int op = p ^ 1;
    auto a = t[p].get(0, l, r + 1, 0, n);
    int ind = a.second;
    auto b = t[op].get(0, ind + 1, r + 1, 0, n);
    int jnd = b.second;
    return {ind, jnd};
}

void add_segment(int l, int r)
{
    if (l > r)
    {
        return;
    }
    auto a = find_splits(l, r);
    int x = a.first, y = a.second;
    e.insert({{arr[x], arr[y]}, {l, r}});
}

void upd()
{
    auto it = e.begin();
    int l = it->second.first, r = it->second.second;
    auto g = find_splits(l, r);
    add_segment(l, g.first - 1);
    add_segment(g.first + 1, g.second - 1);
    add_segment(g.second + 1, r);
    ans.push_back(it->first.first);
    ans.push_back(it->first.second);
    e.erase(it);
}

