            S.insert(sec(now.l,now.ansl-1,now.op));
        if ( now.ansl+1 < now.ansr-1 )
            S.insert(sec(now.ansl+1,now.ansr-1,now.op^1));
        if ( now.ansr+1 < now.r )
            S.insert(sec(now.ansr+1,now.r,now.op));
    }
}
