using namespace std;

using ll = long long;
using pii = pair<int, int>;


vector<pii> solve(int l , int r, vector<int> const& a) {
    int mi1 = 1e9, mi1p = 0;
    for(int offset = 0; offset + l < r; offset += 2) {
        if(mi1 > a[l + offset]) {
            mi1 = a[l + offset];
            mi1p = l + offset;
        }
    }
    int mi2 = 1e9, mi2p = 0;
    for(int offset = 1; offset + mi1p < r; offset += 2) {
        if(mi2 > a[mi1p + offset]) {
            mi2 = a[mi1p + offset];
            mi2p = mi1p + offset;
        }
    }
    vector<pii> res = {make_pair(mi1, mi2)};
    vector<pii> tmp;
    if(l != mi1p) {
        auto t = solve(l, mi1p, a);
        for(auto& p : t) {
            tmp.push_back(move(p));
        }
    }
    if(mi1p + 1 != mi2p) {
        auto t = solve(mi1p + 1, mi2p, a);
        for(auto& p : t) {
            tmp.push_back(move(p));
        }
    }
    if(mi2p + 1 != r) {
        auto t = solve(mi2p + 1, r, a);
        for(auto& p : t) {
            tmp.push_back(move(p));
        }
    }
    sort(tmp.begin(), tmp.end());
    for(auto& t : tmp) {
        res.push_back(move(t));
    }
    return res;
}

