int N;
int A[100001];
int B[100001];
vector<PP> Q;

PP segA[1 << 19];
PP segB[1 << 19];

void segupdate(PP* seg, int i, int val, int p) {
	seg[i] = make_pair(val, p);
	while (i > 1) {
		i /= 2;
		seg[i] = min(seg[i * 2], seg[i * 2 + 1]);
	}
}

void segcreate(PP* seg, int* dat) {
	fill(seg, seg + (1 << 19), make_pair(INF, -1));
	REP(i, 0, N / 2) {
		segupdate(seg, i + (1 << 18), dat[i], i);
	}
}

PP segminrec(PP* seg, int a, int b, int i, int l, int r) {
	if (r <= a || b <= l) return make_pair(INF, -1);
	if (a <= l && r <= b) return seg[i];

	return min(
		segminrec(seg, a, b, i * 2, l, (l + r) / 2),
		segminrec(seg, a, b, i * 2 + 1, (l + r) / 2, r));
}
PP segmin(PP* seg, int a, int b) {
	return segminrec(seg, a, b, 1, 0, 1 << 18);
}



void input() {
	cin >> N;
	REP(i, 0, N / 2) {
		cin >> A[i];
		cin >> B[i];
	}
	return;
}

struct Tree {
	PP p;
	Tree* l;
	Tree* c;
	Tree* r;
	Tree(PP pp, Tree* ll, Tree* cc, Tree* rr) {
		p = pp;
		l = ll;
		c = cc;
		r = rr;
	}
	bool operator<(const Tree& right) const {
		return p < right.p;
	}
};

Tree* solverec(bool rev,int st, int n) {
	if (n == 0) {
		return NULL;
	} else if (n == 1) {
		PP p;
		if (!rev) {
			p = make_pair(A[st], B[st]);
		} else {
			p = make_pair(B[st], A[st + 1]);
		}
		return new Tree(p, NULL, NULL, NULL);
	} else {
		PP p;
		Tree* l;
		Tree* c;
		Tree* r;
		if (!rev) {
			auto ml = segmin(segA, st, st + n);
			auto mr = segmin(segB, st, st + n);
			p = make_pair(ml.first, mr.first);

			l = solverec(rev, st, ml.second - st);
			c = solverec(!rev, ml.second, mr.second - ml.second);
			r = solverec(rev, mr.second + 1, st - mr.second + n - 1);
		} else {
			auto ml = segmin(segB, st, st + n);
			auto mr = segmin(segA, st + 1, st + 1 + n);
			p = make_pair(ml.first, mr.first);

			l = solverec(rev, st, ml.second - st);
			c = solverec(!rev, ml.second + 1, mr.second - ml.second - 1);
			r = solverec(rev, mr.second, st - mr.second + n);
		}
		return new Tree(p, l, c, r);
	}
}

void solve() {
	segcreate(segA, A);
	segcreate(segB, B);

	priority_queue<Tree*> que;
	auto root = solverec(false, 0, N / 2);
	que.push(root);
	while(!que.empty()){
		auto tp = que.top(); que.pop();
		Q.push_back(tp->p);
		if (tp->l) que.push(tp->l);
		if (tp->c) que.push(tp->c);
		if (tp->r) que.push(tp->r);
	}
	return;
}

void output() {
	REP(i, 0, N / 2) {
		cout << Q[i].first << ' ' << Q[i].second << (i == N / 2 - 1 ? '\n' : ' ');
	}
	return;
}


int main() {
	input();
	solve();
	output();
	return 0;
}

