struct ST {
	pair<int,int> st[K][1<<K];int n;  // K such that 2^K>n
	void init(pair<int,int> *a, int _n){
		n=_n;
		fore(i,0,n)st[0][i]=a[i];
		fore(k,1,K)fore(i,0,n-(1<<k)+1)
			st[k][i]=oper(st[k-1][i],st[k-1][i+(1<<(k-1))]);
	}
	pair<int,int> query(int s, int e){
		int k=31-__builtin_clz(e-s);
		return oper(st[k][s],st[k][e-(1<<k)]);
	}
};

int n;
pair<int,int> v[2][200005];
ST w[2];

vector<int> doit(int s, int e){
	//deb("%d %d\n",s,e);
	assert(s<=e);
	assert((e-s)%2==0);
	vector<int> r;
	if(s==e)return r;
	auto p=w[s%2].query(s,e);//deb(" %d\n",p.snd);
	r.pb(p.fst);
	auto q=w[1-s%2].query(p.snd+1,e);//deb("  %d\n",q.snd);
	r.pb(q.fst);
	vector<int> v0=doit(s,p.snd),v1=doit(p.snd+1,q.snd),v2=doit(q.snd+1,e);
	reverse(v0.begin(),v0.end());reverse(v1.begin(),v1.end());reverse(v2.begin(),v2.end());
	while(!v0.empty()||!v1.empty()||!v2.empty()){
		pair<int,int> x=NEUT;
		if(!v0.empty())x=min(x,mp(v0.back(),0));
		if(!v1.empty())x=min(x,mp(v1.back(),1));
		if(!v2.empty())x=min(x,mp(v2.back(),2));
		if(x.snd==0){
			r.pb(v0.back());v0.pop_back();
			r.pb(v0.back());v0.pop_back();
		}
		else if(x.snd==1){
			r.pb(v1.back());v1.pop_back();
			r.pb(v1.back());v1.pop_back();
		}
		else {
			assert(x.snd==2);
			r.pb(v2.back());v2.pop_back();
			r.pb(v2.back());v2.pop_back();
		}
	}
	assert(r.size()==e-s);
	return r;
}

