void RMQ_init(int n, int v) {
	for(int i = 1; i <= n; i ++) d[v][i][0] = a[v][i];
	for(int j = 1; (1 << j) <= n; j ++)
		for(int i = 1; i + (1 << j) - 1 <= n; i ++)
			d[v][i][j] = min(d[v][i][j - 1], d[v][i + (1 << (j - 1))][j - 1]);
}

int RMQ(int a, int b, int v) {
	int k = 0;
	while((1 << (k + 1)) <= b - a + 1) k ++;
	return min(d[v][a][k], d[v][b - (1 << k) + 1][k]);
}

