const int N = (int)2e5 + 9;
const int LG = 20;

int tab[2][N][LG];
int pos[N];
int p[N];

int LOG[N];

int query(int bit, int L, int R){
    int p = LOG[R-L+1];
    return min(tab[bit][L][p], tab[bit][R-(1<<p)+1][p]);
}

pii compute(int L, int R){
    int res1 = query(L%2, L, R);
    int id = pos[res1];
    int res2 = query(!(L%2), id + 1, R);
    return mp(res1, res2);
}

struct Q{
    pii pr;
    int Lef;
    int Rig;
    bool operator< (const Q &f) const {
        return pr > f.pr;
    }
};

int main(){
    fastIO;
    int n;
    cin >> n;
    for(int i = 1; i <= n; i ++ ){
        cin >> p[i];
        pos[p[i]] = i;
    }
    int pr = 0;
    for(int i = 1; i <= n; i ++ ){
        while((1 << (pr + 1)) <= i)
            pr ++ ;
        LOG[i] = pr;
    }
    for(int bit = 0 ; bit < 2; bit ++ ){
        for(int i = 1; i <= n; i ++ ){
            if(i % 2 == bit){
                tab[bit][i][0] = p[i];
            }
            else{
                tab[bit][i][0] = (int)1e9;
            }
        }
        for(int j = 1; j < LG; j ++ ){
            for(int i = 1; i <= n ; i ++ ){
                if(i + (1 << j) - 1 <= n){
                    tab[bit][i][j] = min(tab[bit][i][j-1], tab[bit][i+(1<<(j-1))][j-1]);
                }
            }
        }
    }
    priority_queue<Q> pp;
    pp.push({compute(1,n),1, n});
    Q cur;

    int cl, cr;
    int id1, id2;
    while(!pp.empty()){
        cur = pp.top();
        pp.pop();
        cout << cur.pr.fi << " " << cur.pr.se << " ";
        id1 = pos[cur.pr.fi];
        id2 = pos[cur.pr.se];
        cl = cur.Lef;
        cr = cur.Rig;
        // cl..id1-1 | id1 + 1..id2-1 | id2+1..cr
        if(cl < id1){
            pp.push({compute(cl, id1-1), cl, id1-1});
        }
        if(id1 + 1 <= id2 - 1){
            pp.push({compute(id1+1, id2-1), id1 + 1, id2 - 1});
        }
        if(id2+1 <= cr){
            pp.push({compute(id2+1, cr), id2 + 1, cr});
        }
    }
    return 0;
}

