template<class T> class segtree {
	int n;
	vector<T> data;
	T id;
	function<T(T, T)> operation;
	function<T(T, T)> update;
public:
	segtree(int _n, T _id, function<T(T, T)> _operation, function<T(T, T)> _update)
		:id(_id), operation(_operation), update(_update) {
		n = 1;
		while (n < _n + 2) n <<= 1;
		data = vector<T>(2 * n, id);
	}
	void change(int i, T x) {
		i += n;
		data[i] = update(data[i], x);
		while (i > 1) {
			i >>= 1;
			data[i] = operation(data[i << 1], data[i << 1 | 1]);
		}
	}
	T get(int a, int b) {
		T left = id; T right = id;
		a += n; b += n;
		while (a < b) {
			if (a & 1) left = operation(left, data[a++]);
			if (b & 1) right = operation(data[--b], right);
			a >>= 1; b >>= 1;
		}
		return operation(left, right);
	}
	T get_all() { return data[1]; }
	T operator[](int i) { return data[i + n]; }
};

segtree<int> evenseg(200010, inf, [](int a, int b) {return min(a, b); }, [](int a, int b) {return b; });
segtree<int> oddseg(200010, inf, [](int a, int b) {return min(a, b); }, [](int a, int b) {return b; });
vector<int> edge(200010), pl(200010);
vector<vector<int>> graph(200010, vector<int>());
int root = -1;

void solve(int l, int r, int k, int prev) {
	if (l >= r) return;
	int mi;
	if (k) mi = oddseg.get(l, r);
	else mi = evenseg.get(l, r);
	int to;
	if (k) to = evenseg.get(pl[mi] + 1, r);
	else to = oddseg.get(pl[mi] + 1, r);
	edge[mi] = to;
	if (prev == -1) root = mi;
	else graph[prev].pb(mi);
	solve(l, pl[mi], k, mi);
	solve(pl[mi] + 1, pl[to], k ^ 1, mi);
	solve(pl[to] + 1, r, k, mi);
}

