		if (i & 1) oddseg.change(i, a[i]);
		else evenseg.change(i, a[i]);
		pl[a[i]] = i;
	}
	solve(0, n, 0, -1);
	vector<int> ans;
	priority_queue<int, vector<int>, greater<int>> que;
	que.push(root);
	while (!que.empty()) {
		int q = que.top(); que.pop();
		ans.pb(q);
		ans.pb(edge[q]);
		for (int i : graph[q]) que.push(i);
	}
	for (int i : ans) cout << i << ' ';
	cout << '\n';
}

