int n;

void build(int par){
    for(int i = n - 1 ; i > 0 ; --i){
        t[par][i] = min(t[par][2 * i] , t[par][2 * i + 1]);
    }
}

void modify(int par , int p , int val){
    for(t[par][p += n] = val ; p > 1 ; p /= 2){
        t[par][p / 2] = min(t[par][p] , t[par][p ^ 1]);
    }
}

int query(int par , int l , int r){//[l , r)
    int res = INF;
    for(l += n , r += n ; l < r ; l /= 2 , r /= 2){
        if(l % 2){
            res = min(res, t[par][l]);
            ++l;
        }
        if(r % 2){
            --r;
            res = min(res , t[par][r]);
        }
    }
    return res;
}


map<int , vector<pii>> ans;

int last = 0;
map<int , pii> code;
map<pii , int> rcode;

vi g[MAXN];

void solve(vi & p , int l , int r , int k , int prev = -1){
	if(r - l < 1)return;
	if(r >= sz(p) || l < 0)return;
	if(r - l == 1){
		code[last] = {p[l] , p[r]};
		rcode[{p[l] , p[r]}] = last;
		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;
	}else{
		pii o = {0 , 0};

		int par = l % 2;
		o.fi = query(par , l , r + 1);
		if(sz(tot) * 2 == sz(p))exit(0);
		int pos1 = pos[o.fi];
		o.se = query((pos1 + 1) % 2 , pos1 + 1 , r + 1);
		code[last] = o;
		rcode[o] = last;
		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;


		int pos2 = pos[o.se];

		rep(q , 2){
			modify(q , pos1 , INF);
			modify(q , pos2 , INF);

		}

		solve(p , pos1 + 1 , pos2 - 1 , k - 1 , prev);
		solve(p , l , pos1 - 1 , k - 1 , prev);
		solve(p , pos2 + 1 , r , k - 1 , prev);

	}
}

vi restore(){
	vi res;
	priority_queue<pii , vector<pii> , greater<pii>> q; 
	q.push(code[0]);
	while(!q.empty()){
		pii u = q.top();
		q.pop();
		res.pb(u.fi);
		res.pb(u.se);

		for(int c : g[rcode[u]]){
			q.push(code[c]);
		}
	}
	return res;
}

