// http://www.prefield.com/algorithm/container/range_minimum.html
int *buildRMQ(int *a, int n) {
  int logn = 1;
  for (int k = 1; k < n; k *= 2) ++logn;
  int *r = new int[n * logn];
  int *b = r; copy(a, a+n, b);
  for (int k = 1; k < n; k *= 2) {
    copy(b, b+n, b+n); b += n;
    REP(i, n-k) b[i] = min(b[i], b[i+k]);
  }
  return r;
}
int minimum(int x, int y, int *rmq, int n) {
  int z = y - x, k = 0, e = 1, s; // y - x >= e = 2^k なる最大 k
  s = ( (z & 0xffff0000) != 0 ) << 4; z >>= s; e <<= s; k |= s;
  s = ( (z & 0x0000ff00) != 0 ) << 3; z >>= s; e <<= s; k |= s;
  s = ( (z & 0x000000f0) != 0 ) << 2; z >>= s; e <<= s; k |= s;
  s = ( (z & 0x0000000c) != 0 ) << 1; z >>= s; e <<= s; k |= s;
  s = ( (z & 0x00000002) != 0 ) << 0; z >>= s; e <<= s; k |= s;
  return min( rmq[x+n*k], rmq[y+n*k-e+1] );
}

int* rmq[2];

struct K {
  int bg, ed;
  int i1, i2;
  K(int bg, int ed) : bg(bg), ed(ed) {
    int v1 = minimum(bg/2, (ed-2)/2, rmq[bg%2], n/2);
    i1 = v2i[v1];
    int v2 = minimum((i1+1)/2, (ed-1)/2, rmq[bg%2^1], n/2);
    i2 = v2i[v2];
  }
};
bool operator>(const K& a, const K& b) {
  return vs[a.i1] > vs[b.i1];
}


int main(void) {
  scanf("%d", &n);
  REP(i, n) {
    scanf("%d", &vs[i]);
    v2i[vs[i]] = i;
    hvs[i%2][i/2] = vs[i];
  }
  REP(i, 2) {
    rmq[i] = buildRMQ(hvs[i], n/2);
  }

  vector<int> res;
  priority_queue<K, vector<K>, greater<K> > q;
  q.push(K(0, n));
  while(!q.empty()) {
    K cur = q.top(); q.pop();
    int i1 = cur.i1;
    int i2 = cur.i2;
    res.push_back(vs[i1]);
    res.push_back(vs[i2]);
    if(cur.bg < i1) {
      q.push(K(cur.bg, i1));
    }
    if(i1 + 1 < i2) {
      q.push(K(i1+1, i2));
    }
    if(i2 + 1 < cur.ed) {
      q.push(K(i2+1, cur.ed));
    }
  }
  REP(i, n) {
    printf("%d%c", res[i], i == n-1 ? '\n' : ' ');
  }

  return 0;
}

