template <typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> dat;

	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		dat.resize(n * 2 - 1, init_val);
	}

	void update(int i, T x) {
		i += n - 1;
		dat[i] = min(dat[i], x);
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	void set(int i, T x) {
		dat[i + n - 1] = x;
		update(i, x);
	}

	// 探索範囲[a,b), 現在見ているkノード[l,r)
	T query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;

		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return dat[k];
		return min( query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r) );
	}
};

int N;
int p[212345], ans[212345];

int main() {
	cin >> N;
	REP(i, N) scanf("%d", p + i);

	if (N == 2) {
		printf("%d %d\n", p[0], p[1]);
		return 0;
	}

	SegTree<pii> segodd(N, pii(INF, -1)), segeven(N, pii(INF, -1));
	REP(i, N) {
		if (i & 1) segodd.update(i, pii(p[i], i));
		else segeven.update(i, pii(p[i], i));
	}

	priority_queue<pip, vector<pip>, greater<pip> > pq;
	if ((N - 1) & 1) pq.push(pip(segeven.query(0, N - 3).fi, pii(0, N - 1)));
	else pq.push(pip(segodd.query(0, N - 3).fi, pii(0, N - 1)));

	int ansp = 0;
	while (!pq.empty()) {
		pip now = pq.top(); pq.pop();

		int l = now.se.fi, r = now.se.se;
		if (r == -1) {
			ans[ansp++] = p[l];
			ans[ansp++] = p[l + 1];
			continue;
		}

		int idx;
		if (r & 1) idx = segeven.query(l, r - 2).se;
		else idx = segodd.query(l, r - 2).se;



		ans[ansp++] = p[idx];
		ans[ansp++] = p[r];

		if (idx - l > 1) {
			if (idx - l == 2) pq.push(pip(p[l], pii(l, -1)));
			else {
				int nextnum;
				if ((idx - 1) & 1) nextnum = segeven.query(l, idx - 3).fi;
				else nextnum = segodd.query(l, idx - 3).fi;

				pq.push(pip(nextnum, pii(l, idx - 1)));
			}
		}

		if (r - idx > 2) {
			if (r - idx == 3) pq.push(pip(p[idx + 1], pii(idx + 1, -1)));
			else {
				int nextnum;
				if ((r - 1) & 1) nextnum = segeven.query(idx + 1, r - 3).fi;
				else nextnum = segodd.query(idx + 1, r - 3).fi;
				pq.push(pip(nextnum, pii(idx + 1, r - 1)));
			}
		}
	}

	REP(i, N) printf("%d%c", ans[i], i == N - 1 ? '\n' : ' ');

	return 0;
}

