inline int Get() {
	char ch;
	while ((ch = getchar()) < '0' || ch > '9');
	int Num = ch - '0';
	while ((ch = getchar()) >= '0' && ch <= '9')
		Num = (Num << 3) + (Num << 1) + ch - '0';
	return Num;
}
int n, a[N];
pII val[N << 3];
std :: priority_queue <pII, std :: vector <pII>, std :: greater <pII> > que;
void build(int k, int l, int r) {
	if (l == r) {
		val[k] = std :: make_pair(std :: make_pair(a[l], l), std :: make_pair(inf, 0));
		return;
	}

	int mid = l + r >> 1;
	build(k << 1, l, mid), build((k << 1) | 1, mid + 1, r);
	if ((l ^ mid) & 1) {
		val[k].first = std :: min(val[k << 1].first, val[(k << 1) | 1].first);
		val[k].second = std :: min(val[k << 1].second, val[(k << 1) | 1].second);
	}
	else {
		val[k].first = std :: min(val[k << 1].first, val[(k << 1) | 1].second);
		val[k].second = std :: min(val[k << 1].second, val[(k << 1) | 1].first);
	}
	return;
}
pII query(int k, int l, int r, int x, int y) {
	if (x <= l && r <= y) return val[k];

	int mid = l + r >> 1;
	if (y <= mid) return query(k << 1, l, mid, x, y);
	if (x > mid) return query((k << 1) | 1, mid + 1, r, x, y);

	pII vl = query(k << 1, l, mid, x, y), vr = query((k << 1) | 1, mid + 1, r, x, y), res;

	if (((std :: max(l, x)) ^ mid) & 1) {
		res.first = std :: min(vl.first, vr.first);
		res.second = std :: min(vl.second, vr.second);
	}
	else {
		res.first = std :: min(vl.first, vr.second);
		res.second = std :: min(vl.second, vr.first);
	}

	return res;
}
void insert(int l, int r) {
	pII res = query(1, 1, n, l, r);
	que.push(std :: make_pair(res.first, std :: make_pair(l, r)));
}
