		pII cur = que.top(); que.pop();

		int l = cur.second.first, r = cur.second.second;

		int posL = cur.first.second;
		int posR = query(1, 1, n, posL + 1, r).first.second;

		printf("%d %d ", a[posL], a[posR]);

