			cc.push({ pos + 1 , apos });
		if (apos + 1 != ck.second)
			cc.push({ apos + 1, ck.second });

		printf("%d %d ", top.first.first, top.first.second);

	} while (cc.size() || pq.size());

	return 0;
}

