ui seed;
ui rd(){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;}

const int N = 2e+5+5;

int n;
struct node{
	ui val;
	int l,r,key,tot;
	int v[2];
}tree[N];
int fa[N];
int p[N],q[N];
bool bz[N];

int getrt(int x){for(;fa[x];x=fa[x]);return x;}

void update(int x){
	if(tree[tree[x].l].tot&1){
		tree[x].v[0]=min(tree[tree[x].l].v[0],tree[tree[x].r].v[0]);
		tree[x].v[1]=min(tree[tree[x].l].v[1],tree[tree[x].r].v[1]);
	}
	else{
		tree[x].v[0]=min(tree[tree[x].l].v[0],tree[tree[x].r].v[1]);
		tree[x].v[1]=min(tree[tree[x].l].v[1],tree[tree[x].r].v[0]);
	}
	tree[x].v[(tree[tree[x].l].tot+1)&1]=min(tree[x].v[(tree[tree[x].l].tot+1)&1],tree[x].key);
	tree[x].tot=tree[tree[x].l].tot+tree[tree[x].r].tot+1;
}

int merge(int x,int y){
	fa[x]=fa[y]=0;
	if (!x||!y)return x^y;
	if (tree[x].val<tree[y].val){
		y=merge(tree[x].r,y);
		fa[y]=x,tree[x].r=y;
		update(x);
		return x;
	}
	x=merge(x,tree[y].l);
	fa[x]=y,tree[y].l=x;
	update(y);
	return y;
}

int findth(int x,int y){
	if (x==y)return tree[tree[x].l].tot+1;
	if (y<x)return findth(tree[x].l,y);
	return tree[tree[x].l].tot+1+findth(tree[x].r,y);
}

pir split(int x,int k){
	fa[x]=0;
	if (!k)return make_pair(0,x);
	if (k>=tree[x].tot)return make_pair(x,0);
	if (k<=tree[tree[x].l].tot){
		pir u=split(tree[x].l,k);
		tree[x].l=u.se;
		if (u.se)fa[u.se]=x;
		update(x);
		return make_pair(u.fi,x);
	}
	pir u=split(tree[x].r,k-tree[tree[x].l].tot-1);
	tree[x].r=u.fi;
	if (u.fi)fa[u.fi]=x;
	update(x);
	return make_pair(x,u.se);
}

set<int>s;

void del(int x){
	int rt=getrt(x);
	s.erase(tree[rt].v[1]);
	int k=findth(rt,x);
	pir u=split(rt,k);
	if (u.se)s.insert(tree[u.se].v[1]);
	u=split(u.fi,k-1);
	if (u.fi)s.insert(tree[u.fi].v[1]);
}

int main(){
	n=get();
	seed=16792369;
	fo(i,1,n){p[i]=get();q[p[i]]=i;}
	int rt=0;
	tree[0].v[0]=tree[0].v[1]=1E+9;
	fo(i,1,n){
		tree[i].val=rd();
		tree[i].key=tree[i].v[1]=p[i];
		tree[i].v[0]=1e+9;
		tree[i].tot=1;
		rt=merge(rt,i);
	}
	s.clear();
	s.insert(tree[rt].v[1]);
	fo(i,1,n/2){
		int x=*s.begin(),y;
		int rt=getrt(q[x]);
		pir u=split(rt,findth(rt,q[x]));
		if (tree[u.se].tot&1){
			y=tree[u.se].v[1];
			merge(u.fi,u.se);
			if (q[x]<q[y])printf("%d %d ",x,y);
			else printf("%d %d ",y,x);
			del(q[x]),del(q[y]);
			bz[y]=1;
		}
		else merge(u.fi,u.se);
	}
	putchar('\n');
	return 0;
}

