bool used[200000 + 5];

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    init(n, node1, pos1);
    init(n, node2, pos2);
    rep(i, n) {
        cin >> p[i];
        if (i % 2 == 0) update(i, p[i], node1, pos1);
        else update(i, p[i], node2, pos2);
    }
    pair<int, int> v1 = get_min(0, n, node1, pos1);
    update(v1.se, INT_MAX, node1, pos1);
    pair<int, int> v2 = get_min(v1.se + 1, n, node2, pos2);
    update(v2.se, INT_MAX, node2, pos2);
    pq.push(make_pair(make_pair(v1.fi, v2.fi), make_pair(0, v1.se)));
    pq.push(make_pair(make_pair(v1.fi, v2.fi), make_pair(v1.se + 1, v2.se)));
    pq.push(make_pair(make_pair(v1.fi, v2.fi), make_pair(v2.se + 1, n)));
    while (!pq.empty()) {
        pair<pii, pii> p = pq.top(); pq.pop();
        if (!used[p.fi.fi] && !used[p.fi.se]) {
            used[p.fi.fi] = true;
            used[p.fi.se] = true;
            ans.pb(p.fi.fi);
            ans.pb(p.fi.se);
        }
        int l = p.se.fi;
        int r = p.se.se;
        if (l == r) continue;
        pair<int, int> p1 = make_pair(INT_MAX, INT_MAX);
        pair<int, int> p2 = make_pair(INT_MAX, INT_MAX);
        if (l % 2 == 0) {
            p1 = get_min(l, r, node1, pos1);
            update(p1.se, INT_MAX, node1, pos1);
            p2 = get_min(p1.se + 1, r, node2, pos2);
            update(p2.se, INT_MAX, node2, pos2);
        }
        else {
            p1 = get_min(l, r, node2, pos2);
            update(p1.se, INT_MAX, node2, pos2);
            p2 = get_min(p1.se + 1, r, node1, pos1);
            update(p2.se, INT_MAX, node1, pos1);
        }
        pq.push(make_pair(make_pair(p1.fi, p2.fi), make_pair(l, p1.se)));
        pq.push(make_pair(make_pair(p1.fi, p2.fi), make_pair(p1.se + 1, p2.se)));
        pq.push(make_pair(make_pair(p1.fi, p2.fi), make_pair(p2.se + 1, r)));
    }
    rep(i, n) cout << ans[i] << " " ;
    cout << endl;
}

