void solve(){
    int N;
    cin >> N;

    vector<int> p(N),val_to_index(N+1);
    segtree<int,min_> seg_even(N,inf,inf),seg_odd(N,inf,inf);
    rep(i,0,N){
        cin >> p[i];
        if(i%2==0) seg_even.update(i,p[i]);
        else seg_odd.update(i,p[i]);
        val_to_index[p[i]]=i;
    }

    auto min_pair=[&](int l,int r){
        int l_=l%2==0?val_to_index[seg_even.query(l,r-1)]:val_to_index[seg_odd.query(l,r-1)],
            r_=l%2==0?val_to_index[seg_odd.query(l_+1,r)]:val_to_index[seg_even.query(l_+1,r)];
        return make_pair(l_,r_);
    };

    vector<int> ans;
    priority_queue<tuple<int,int,int>,vector<tuple<int,int,int>>,greater<tuple<int,int,int>>> pq;
    pq.push(make_tuple(p[min_pair(0,N).first],0,N));

    while(!pq.empty()){
        int l=get<1>(pq.top()),r=get<2>(pq.top());
        pq.pop();

        auto tmp=min_pair(l,r);
        int l_=tmp.first,r_=tmp.second;
        ans.push_back(p[l_]);
        ans.push_back(p[r_]);

        if(l_-l>=2) pq.push(make_tuple(p[min_pair(l,l_).first],l,l_));
        if(r_-(l_+1)>=2) pq.push(make_tuple(p[min_pair(l_+1,r_).first],l_+1,r_));
        if(r-(r_+1)>=2) pq.push(make_tuple(p[min_pair(r_+1,r).first],r_+1,r));
    }

    rep(i,0,N){
        cout << ans[i];
        if(i==N-1) cout << endl;
        else cout << " ";
    }
}

