pair<int, vector<P> > solver(int l, int r){
  ll mini = INF;
  ll ind = 0;
  for(int i=l;i<r;i+=2)
    if(p[i] < mini){
      mini = p[i];
      ind = i;
    }
  auto left = solvel(l, ind);
  auto right = solvel(ind+1, r);

  vector<P> ret(0);
  ll li = 0;
  ll ri = 0;
  while(li < left.size() && ri < right.size()){
    if(left[li] < right[ri]){
      ret.push_back(left[li]);
      li++;
    }else{
      ret.push_back(right[ri]);
      ri++;
    }
  }
  for(int i = li; i<left.size();i++)
    ret.push_back(left[i]);
  for(int i = ri; i<right.size();i++)
    ret.push_back(right[i]);
  return pair<int, vector<P> >(mini, ret);
}

vector<P> solvel(int l, int r){
  //cout << l << " " << r << endl;
  if(l>=r)
    return vector<P>(0);

  ll mini = INF;
  ll ind = 0;
  for(int i=l;i<r;i+=2)
    if(p[i] < mini){
      mini = p[i];
      ind = i;
    }
  auto left = solvel(l, ind);
  ll rmini;
  vector<P> right;
  tie(rmini, right) = solver(ind+1, r);

  vector<P> ret(1, P(mini, rmini));
  ll li = 0;
  ll ri = 0;
  while(li < left.size() && ri < right.size()){
    if(left[li] < right[ri]){
      ret.push_back(left[li]);
      li++;
