const int SPT_MAX = 123456;
const int SPT_lg = 20;
const int INF = 123456789;

template <class T> class SPT{
	T x[SPT_MAX + 1][SPT_lg];
	int lg[SPT_MAX + 1];

	T eval(T a , T b){
		return min(a,b);
	}

public:

	void dft(int n , T a[]){
		lg[1] = 0;
		for(int i = 2 ; i <= SPT_MAX ; ++i) lg[i] = lg[i / 2] + 1;
		for(int i = 0 ; i < n ; ++i) x[i][0] = a[i];
		for(int i = n ; i < SPT_MAX ; ++i) x[i][0] = INF;
		for(int j = 0 ; j < SPT_lg - 1 ; ++j){
			for(int i = 0 ; i < n - (1 << j) ; ++i){
				x[i][j + 1] = eval(x[i][j] , x[i + (1 << j)][j]);
			}
		}
	}

	T get(int s , int f){
		int z = f - s;
		return eval(x[s][lg[z]] , x[f - (1 << lg[z])][lg[z]]);
	}
};

const int MC = 200010;
int N;
SPT<int> spt[2];
int p[2][MC];
int r[MC];
vector<P2> ans;

void solve(int s , int t , vector<P2> &V){
	if(s==t) return;
	int a = spt[s%2].get(s/2,t/2);
	int b = spt[(s+1)%2].get((r[a]+1)/2,(t+1)/2);
	V.PB(MP(a,b));
	vector<P2> u[3];
	solve(s,r[a],u[0]);
	solve(r[a]+1,r[b],u[1]);
	solve(r[b]+1,t,u[2]);
	u[0].PB(MP(INF,INF));
	u[1].PB(MP(INF,INF));
	u[2].PB(MP(INF,INF));
	int w[3] = {0,0,0};
	while(u[0][w[0]].first != INF || u[1][w[1]].first != INF || u[2][w[2]].first != INF){
		if(u[0][w[0]].first < u[1][w[1]].first && u[0][w[0]].first < u[2][w[2]].first){
			V.PB(u[0][w[0]]);
			++w[0];
		} else if(u[1][w[1]].first < u[0][w[0]].first && u[1][w[1]].first < u[2][w[2]].first){
			V.PB(u[1][w[1]]);
			++w[1];
		} else {
			V.PB(u[2][w[2]]);
			++w[2];
		}
	}
}

