    auto itr = wall.upper_bound(p1);
    int r = *itr;
    itr--;
    int l = *itr;
    if(p1%2==0){
      if((p1-l)%2==1) p2 = odd.query(p1, r);
      else sw=true,p2 = odd.query(l+1, p1);
      assert(p2!=INF);
      p2 = pos[p2];
      odd.update(p2, INF);
      even.update(p1, INF);
    }
    else {
      if((p1-l)%2==1) p2 = even.query(p1, r);
      else sw=true, p2 = even.query(l+1, p1);
      assert(p2!=INF);
      p2 = pos[p2];
      even.update(p2, INF);
      odd.update(p1, INF);
    }
    if(sw) swap(p1,p2);
    ans.pb(vec[p1]);ans.pb(vec[p2]);
    used[vec[p1]] = used[vec[p2]] = true;
    wall.insert(p1);
    wall.insert(p2);
  }

  rep(i,n) cout << ans[i]+1 << " \n"[i==n-1];

  return 0;
}

