priority_queue<node> Q;

int GetMin(int l, int r)
{
	int len = (r - l + 2) / 2;
	int k = lg[len];
	if ((r - l + 1) & 1)
		return pos[min(f[l][k], f[r - 2 * (bin[k] - 1)][k])];
	else return pos[min(f[l][k], f[r - 2 * (bin[k] - 1) - 1][k])]; 
}

node F(int l, int r)
{
	int ps1 = GetMin(l, r);
	int ps2 = GetMin(ps1 + 1, r);
	return (node){l, r, make_pair(ps1, ps2)};
}

void Solve(int l, int r)
{
	int ps1 = GetMin(l, r);
	int ps2 = GetMin(ps1 + 1, r);
	Q.push((node){l, r, make_pair(ps1, ps2)});
	pair<int, int> v;
	while (!Q.empty())
	{
		node t = Q.top();
		l = t.l, r = t.r, v = t.v;
		ans.push_back(make_pair(a[v.first], a[v.second]));
		Q.pop();
		if (l < v.first - 1) Q.push(F(l, v.first - 1));
		if (v.first + 1 < v.second - 1) Q.push(F(v.first + 1, v.second - 1));
		if (v.second + 1 <r) Q.push(F(v.second + 1, r));
	}
}

