using namespace std;

typedef pair<int, int> ii;

struct SegmentTree {
  private:
    int n;
    int idx;
    vector<int> nodes;

  public:
    ii min_odd; ///先頭になる最小の値とそのインデックス
    ii min_even; ///先頭の次になる値とそのインデックス

    SegmentTree () {}
    SegmentTree (int size) {
      n = size;
      nodes.resize(n);
      idx = 0;
      min_odd = ii{10000000, 0};
      min_even = ii{10000000, 0};
    }

    void add (int x) {
      nodes[idx] = x;
      if (idx%2==0) {
        if (x < min_odd.first) {
          min_odd = ii{x, idx};
          min_even = ii{1000000, 0};
        }
      } else {
        if (x < min_even.first) min_even = ii{x, idx};
      }
      idx++;
    }

    bool empty () {
      return n == 0;
    }

    vector<SegmentTree> get () {
      vector<SegmentTree> res(3);
      int index[] = {-1, min_odd.second, min_even.second, n};
      for (int i = 0; i < 3; i++) {
        SegmentTree s(index[i+1]-index[i]-1);
        for (int j = index[i]+1; j < index[i+1]; j++) {
          s.add(nodes[j]);
        }
        res[i] = s;
      }
      return res;
    }

    bool operator< (const SegmentTree &a) const {
      return min_odd.first > a.min_odd.first;
    }
};


int main() {
  int n, x;
  cin >> n;
  SegmentTree s(n);
  for (int i = 0; i < n; i++) {
    cin >> x;
