inline void maketree(int L, int R){
	t[l].l=t[l].r=t[l].f=t[l].p[0]=t[l].p[1]=0;
	if(L<R){
		int mid=(L+R)>>1, l1=l;
		l++; t[l1].l=l; maketree(L, mid);
		l++; t[l1].r=l; maketree(mid+1, R);
		update(l1);
	}else t[l].p[L&1]=L;
}
inline void pushdown(int i){
	if(t[i].f){
		t[t[i].l].f^=1; swap(t[t[i].l].p[0], t[t[i].l].p[1]);
		t[t[i].r].f^=1; swap(t[t[i].r].p[0], t[t[i].r].p[1]);
		t[i].f=0;
	}
}
inline void ins(int i, int x, int L, int R){
	if(L==R){w[L]=inf; t[i].p[0]=t[i].p[1]=0; return;}
	pushdown(i);
	int mid=(L+R)>>1;
	if(x<=mid)ins(t[i].l, x, L, mid); else ins(t[i].r, x, mid+1, R);
	update(i);
}
inline void insf(int i, int a, int b, int L, int R){
	if(a<=L&&R<=b){t[i].f^=1; swap(t[i].p[0], t[i].p[1]); return;}
	pushdown(i);
	int mid=(L+R)>>1;
	if(a<=mid)insf(t[i].l, a, b, L, mid);
	if(mid<b)insf(t[i].r, a, b, mid+1, R);
	update(i);
}
inline int check(int i, int a, int b, int L, int R){
	if(a==L&&R==b)return t[i].p[0];
	pushdown(i);
	int mid=(L+R)>>1, x1, x2;
	if(b<=mid)return check(t[i].l, a, b, L, mid);
	if(a>mid)return check(t[i].r, a, b, mid+1, R);
	x1=check(t[i].l, a, mid, L, mid); x2=check(t[i].r, mid+1, b, mid+1, R);
	return w[x1]<=w[x2]?x1:x2;
}

