void init(int n_){
  n=1;
  while(n<n_) n*=2;
  for(int i=0;i<=2*n-1;i++) dat[0][i]=dat[1][i]=INF;
}

void update(int k, int a,int p){
  k+=n-1;
  dat[p][k]=a;
  while(k>0){
    k=(k-1)/2;
    dat[p][k]=min(dat[p][k*2+1],dat[p][k*2+2]);
  }
}

int query(int a, int b, int k, int l, int r,int p){
  if(r<=a || b<=l) return INF;
  if(a<=l && r<=b) return dat[p][k];
  else{
    int vl=query(a,b,k*2+1,l,(l+r)/2,p);
    int vr=query(a,b,k*2+2,(l+r)/2,r,p);
    return min(vl,vr);
  }
}

