  int odd,even;
  if((r-l)==1) odd=l, even=r;
  else{
    odd=ind[query(l,r+1,0,0,n,l%2)];
    even=ind[query(l,r+1,0,0,n,(l+1)%2)];
  }
  if(odd>N||odd<1||even>N||even<1) return res;
  vector<pair<int,int> > V1=dfs(l,odd-1);
