    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    cin >> n;

    for(int i = 0; i < n; ++i)
        cin >> arr[i];

    init();

    priority_queue<vector<int>> pq;

    pair<int, int> ree1 = query(0, n, 0);
    pair<int, int> ree2 = query(ree1.second, n, 1);

    pq.push({-ree1.first, -ree2.first, ree1.second, ree2.second, 0, n});

    while(!pq.empty()){

        vector<int> state = pq.top(); pq.pop();
        int l = state[2], r = state[3], pl = state[4], pr = state[5];

        cout << -state[0] << " " << -state[1] << " ";

        //left side
        if(pl < l){
            ree1 = query(pl, l, pl % 2);
            ree2 = query(ree1.second, l, 1 - pl % 2);
            pq.push({-ree1.first, -ree2.first, ree1.second, ree2.second, pl, l});
        }

        //center side
        if(l + 1 < r){
            ree1 = query(l + 1, r, 1 - l % 2);
            ree2 = query(ree1.second, r, l % 2);
            pq.push({-ree1.first, -ree2.first, ree1.second, ree2.second, l + 1, r});
        }

        //right side
        if(r + 1 < pr){
            ree1 = query(r + 1, pr, 1 - r % 2);
            ree2 = query(ree1.second, pr, r % 2);
            pq.push({-ree1.first, -ree2.first, ree1.second, ree2.second, r + 1, pr});
        }

    }

    return 0;

}

