bool solve2(int s, int e)
{
	if (e - s < 0) 
	{
		return false;
	}
	a = INF;
	b = INF;
	mia = lower_bound(p + s, p + e, 0);
	for (int i = s; i <= e; i += 2)
	{
		if (p[i] < a)
		{
			a = p[i];
			mia = p + i;
		}
	}
	for (auto i = mia + 1; i <= p + e; i += 2)
	{
		if (*i < b)
		{
			b = *i;
			mib = i;
		}
	}
	divi2.push_back(mia - p);
	divi2.push_back(mib - p);
	return true;
}

