int solve(int l, int r)
{
	if(r - l + 1 == 2)
	{
		cnt++, w[cnt].fir = a[l], w[cnt].sec = a[r];
		return cnt; 
	}
	int x = pos[query(l, r, l & 1)], y = pos[query(x + 1, r, (l & 1) ^ 1)]; 
	cnt++, w[cnt].fir = a[x], w[cnt].sec = a[y]; int tmp = cnt; 
	if(x > l) adde(tmp, solve(l, x - 1)); 
	if(x + 1 < y - 1) adde(tmp, solve(x + 1, y - 1)); 
	if(y + 1 < r) adde(tmp, solve(y + 1, r));
	return tmp; 
}

