using namespace std;
struct Segtree {
  vector<pair<int, int>> tree;
  int n;
  Segtree() = default;
  Segtree(const vector<pair<int, int>> &v) {
    n = v.size();
    tree = vector<pair<int, int>>(2 * n, {INT_MAX, INT_MAX});
    for (int i = 0; i < n; ++i) {
      update(i, v[i]);
    }
  }

  void update(int i, pair<int,int> val) {
    int p = i + n;
    tree[p] = val;
    p /= 2;
    while (p) {
      tree[p] = tree[p * 2];
      if (p * 2 + 1 < tree.size()) {
        tree[p] = min(tree[p], tree[p * 2 + 1]);
      }
      p /= 2;
    }
  }

  pair<int,int> query(int start, int end) {
    int l = n + start;
    int r = n + end - 1;
    pair<int,int> ret = {INT_MAX, -1};
    while (l <= r) {
      if (l & 1) {
        ret = min(ret, tree[l]);
        l++;
      }

      if ((r & 1) == 0) {
        ret = min(ret, tree[r]);
        r--;
      }
      l /= 2;
      r /= 2;
    }
    return ret;
  }
};
