	for (int i = 1; i <= N; ++i) {
		cin >> a[i];
	}
}

pair<int, int> solve(int l, int r) {
	if (vis[{l, r}]) return dp[{l, r}];
	int ll, rr;
	if (l % 2 == 1) {
		ll = tree.query(1, l, r).posOdd;
		rr = tree.query(1, ll, r).posEven;
	}
	else {
		ll = tree.query(1, l, r).posEven;
		rr = tree.query(1, ll, r).posOdd;
	}
	vis[{l, r}] = true;
	dp[{l, r}] = {ll, rr};
	return {ll, rr};
}

