			q.push({solve(out.fi, in.fi - 1), {out.fi, in.fi - 1}});
		}
		if (in.se != out.se) {
			q.push({solve(in.se + 1, out.se), {in.se + 1, out.se}});
		}
		if (in.fi + 1 != in.se) {
			q.push({solve(in.fi + 1, in.se - 1), {in.fi + 1, in.se - 1}});
		}
	}

	for (int i = 0; i < res.size(); ++i) {
