void buildEven(int node, int startt, int endd){
    if(startt == endd){
        if(startt&1){
            treeEven[node] = INT_MAX;
        }
        else{
            treeEven[node] = p[startt];
        }
        return;
    }
    buildEven(2*node + 1, startt, (startt+endd)/2);
    buildEven(2*node + 2, (startt+endd)/2 + 1, endd);
    treeEven[node] = min(treeEven[2*node + 1], treeEven[2*node + 2]);
}

int queryMinEven(int node, int startt, int endd, int left, int right){
    if(left > endd || right < startt){
        return INT_MAX;
    }
    if(startt>=left && endd<=right){
        return treeEven[node];
    }
    int leftMin = queryMinEven(2*node+1,startt,(startt+endd)/2,left,right);
    int rightMin = queryMinEven(2*node+2,(startt+endd)/2+1,endd,left,right);
    return min(leftMin,rightMin);
}


void buildOdd(int node, int startt, int endd){
    if(startt == endd){
        if(startt&1){
            treeOdd[node] = p[startt];
        }
        else{
            treeOdd[node] = INT_MAX;
        }
        return;
    }
    buildOdd(2*node + 1, startt, (startt+endd)/2);
    buildOdd(2*node + 2, (startt+endd)/2 + 1, endd);
    treeOdd[node] = min(treeOdd[2*node + 1], treeOdd[2*node + 2]);
}

int queryMinOdd(int node, int startt, int endd, int left, int right){
    if(left > endd || right < startt){
        return INT_MAX;
    }
    if(startt>=left && endd<=right){
        return treeOdd[node];
    }
    int leftMin = queryMinOdd(2*node+1,startt,(startt+endd)/2,left,right);
    int rightMin = queryMinOdd(2*node+2,(startt+endd)/2+1,endd,left,right);
    return min(leftMin,rightMin);
}

