int fBegin[N], fEnd[N];
int id[N];

void build() {
    for (int i = 1; i <= n; ++i) {
        fBegin[i] = inf;
        fEnd[i] = -inf;
    }
    for (int i = 1; i <= n; ++i) {
        id[i] = i / M;
        fBegin[id[i]] = min(fBegin[id[i]], i);
        fEnd[id[i]] = max(fEnd[id[i]], i);
        C[id[i]][i & 1].push_back(mk(p[i], i));
    }
    k = id[n] + 1;
    for (int j = 0; j < k; ++j) {
        sort(C[j][0].begin(), C[j][0].end());
        sort(C[j][1].begin(), C[j][1].end());
    }
}

void rm(int i) {

    for (int rc = 0; rc < 2; ++rc) {
        for (int t = 0; t + 1 < C[id[i]][rc].size(); ++t) if (C[id[i]][rc][t].second == i){
            for (; t + 1 < C[id[i]][rc].size(); ++t)
                swap(C[id[i]][rc][t], C[id[i]][rc][t + 1]);
        }
        if (!C[id[i]][rc].empty() && C[id[i]][rc].back().second == i) {
            C[id[i]][rc].pop_back();
        }
    }
}

void merge(vii& a, vii& b) {
    vii tmp = a;
    assert(tmp.size() == a.size());
    a.clear();
    int j = 0;
    for (auto xx : tmp) {
        while (j < b.size() && b[j].first < xx.first) a.push_back(b[j++]);
        a.push_back(xx);
    }
    while (j < b.size()) a.push_back(b[j++]);
}

void fix(int u, int v) {

    vii ls[2];
    for (int j = 0; j < 2; ++j) {
        ls[j].clear();
        for (int i = 0; i < C[id[u]][j].size(); ++i) {
            ii xx = C[id[u]][j][i];
            if (xx.second >= u && xx.second <= v) ls[j].push_back(xx);
            else C[id[u]][j][i - ls[j].size()] = xx;
        }
        for (int t = 0; t < ls[j].size(); ++t) C[id[u]][j].pop_back();
    }

    merge(C[id[u]][0], ls[1]);
    merge(C[id[u]][1], ls[0]);
}

void reverseSQ(int u, int v) {
    if (u > v) return;
    if (id[u] == id[v]) {
        fix(u, v);
        return;
    }

    int ru = id[u] + 1;
    while (ru < id[v]) {
        cid[ru++] ^= 1;
    }
    if (u == fBegin[id[u]]) cid[id[u]] ^= 1;
    else fix(u, fEnd[id[u]]);

    if (v == fEnd[id[v]]) cid[id[v]] ^= 1;
    else fix(fBegin[id[v]], v);
}

