        for (int j = 0; j < k; ++j) {
            if (!C[j][cid[j] ^ 1].empty()) {
                if (u == -1 || p[u] > C[j][cid[j] ^ 1][0].first) {
                    u = C[j][cid[j] ^ 1][0].second;
                }
            }
        }
        int mv = n;
        auto it = st.lower_bound(u);
        if (it != st.end()) mv = *it - 1;
        int v = -1;
