    {
        if(l>r) return {0x3f3f3f3f,0x3f3f3f3f};
        if(l<=L&&r>=R)
            return mx[o];
        int mid=L+R>>1;
        pi ret={0x3f3f3f3f,0x3f3f3f3f};
        if(l<=mid) ret=min(ret,query(l,r,Lson));
        if(r>mid) ret=min(ret,query(l,r,Rson));
        return ret;
    }
}mx,odd,even;
void build(int L=1,int R=n,int o=1)
{
    if(L==R)
    {
        mx.mx[o].first=p[L];
        mx.mx[o].second=odd.mx[o].second=even.mx[o].second=L;
        odd.mx[o].first=even.mx[o].first=0x3f3f3f3f;
        if(L&1) odd.mx[o].first=p[L];
        else even.mx[o].first=p[L];
        return;
    }
    int mid=L+R>>1;
    build(Lson);
    build(Rson);
    mx.mx[o]=min(mx.mx[lson],mx.mx[rson]);
    odd.mx[o]=min(odd.mx[lson],odd.mx[rson]);
    even.mx[o]=min(even.mx[lson],even.mx[rson]);
}
vi G[maxn];
pi pp[maxn];
int ti=0;
int solve(int l=1,int r=n)
{
    if(l>r) return 0;
    if(l+1==r)
    {
        pp[++ti]={p[l],p[r]};
        return ti;
    }
    assert((r-l+1)%2==0);
    pi tar=mx.query(l,r);
    pi tt;
    int ret=-1;
    if((tar.second-l+1)&1)
    {
        if(tar.second&1)
            tt=even.query(tar.second,r);
        else tt=odd.query(tar.second,r);
        pp[++ti]={tar.first,tt.first};
    }
    else{
        if(tar.second&1) tt=even.query(l,tar.second);
        else tt=odd.query(l,tar.second);
        pp[++ti]={tt.first,tar.first};
    }
    ret=ti;
    if(tt.second>tar.second) swap(tt,tar);
    int L=solve(l,tt.second-1);
    int mid=solve(tt.second+1,tar.second-1);
    int R=solve(tar.second+1,r);
    G[ret].push_back(L);
    G[ret].push_back(mid);
    G[ret].push_back(R);
    return ret;
}
