		y = Y;
		z = Z;
	}
};

bool operator < (node a, node b) {
	return (mp(a.x, mp(a.y, a.z)) < mp(b.x, mp(b.y, b.z)));
}

int rmq[2][nmax], a[2][nmax], q[nmax], s, n;
set<node> answer;

int ask(int z, int ind, int l1, int r1, int l, int r) {
	if (l1 > r || l > r1) {
		return -1;
	}
	if (l <= l1 && r1 <= r) {
		return rmq[z][ind];
	}
	int ind1 = ask(z, ind * 2, l1, (l1 + r1) / 2, l, r);
	int ind2 = ask(z, ind * 2 + 1, (l1 + r1) / 2 + 1, r1, l, r);
	if (ind1 == -1) return ind2;
	else if (ind2 == -1) return ind1;
	else return (a[z][ind1] > a[z][ind2] ? ind2 : ind1);
}

void get(int l, int r, int lvl) {
	if (l > r) return;
	int ind = ask(l & 1, 1, 0, s - 1, l, r) - s;
	int ind1 = ask((l & 1) ^ 1, 1, 0, s - 1, ind, r) - s;
	answer.insert(node(lvl, q[ind], q[ind1]));
	get(l, ind - 1, lvl + 1);
	get(ind + 1, ind1 - 1, lvl + 1);
	get(ind1 + 1, r, lvl + 1);
}

