	pres.insert(-1);
	pres.insert(N);
	mpres.insert(1);
	mpres.insert(-N);

	vector<int> p(N);
	rep(i, N) {
		cin >> p[i];
		m[p[i]] = i;
	}

	vector<int> pOdd = p, pEven = p;
	rep(i, N) {
		if (i % 2) pEven[i] = INF;
		else pOdd[i] = INF;
	}

	rmqOdd = RangeMinQuery(pOdd);
	rmqEven = RangeMinQuery(pEven);

	vector<int> q;
	REP(i, 1, N) {
		if (p[m[i]] == INF) continue;
		int pt = m[i];

		int limit = *(pres.upper_bound(pt)) - 1;
		int backLimit = -*(mpres.upper_bound(-pt)) + 1;
		RangeMinQuery &rmq = pt % 2 ? rmqEven : rmqOdd;

		if ((pt - backLimit) % 2 == 0) {
			int pt2 = pt + 1;
			int minVal = p[pt2];

			q.push_back(i);
			q.push_back(minVal);

			p[pt2] = INF;
			pres.insert(pt);
			pres.insert(pt2);
			mpres.insert(-pt);
			mpres.insert(-pt2);
		} else {
			int limit = backLimit;
			int minVal = rmq.find(limit, pt - 1);

			q.push_back(minVal);
			q.push_back(i);

			int pt2 = m[minVal];
			p[pt2] = INF;
			pres.insert(pt);
			pres.insert(pt2);
			mpres.insert(-pt);
			mpres.insert(-pt2);
		}
	}

