const int maxn = 100005;
const int INF = 0x7fffffff;
using pii = std::pair<int, int>;
int n, A[maxn]; int log2[maxn];
pii minv[2][17][maxn];
inline void process() {
  for(int typ = 0; typ < 2; typ ++) {
    for(int i = 1; i <= n; i ++) {
      pii &th = minv[typ][0][i];
      th.second = i;
      if((i & 1) == typ) th.first = A[i];
      else th.first = INF;
    }
    for(int j = 1; (1 << j) <= n; j ++) {
      pii *las = minv[typ][j - 1], *B = minv[typ][j];
      const int len = 1 << j;
      for(int i = 1; i <= n; i ++) {
        if(i + len - 1 > n) {
          B[i].first = INF;
        } else {
          B[i] = std::min(las[i], las[i + (len >> 1)]);
        }
#ifdef LOCAL
        printf("minv[%d][%d][%d] : (%d, %d)\n", typ, j, i, B[i].first, B[i].second);
        fflush(stdout);
#endif
      }
    }
  }
  log2[1] = 0;
  for(int i = 2; i <= n; i ++) {
    log2[i] = log2[i - 1];
    if((1 << (log2[i] + 1)) <= i) log2[i] ++;
  }
}
inline pii query(int typ, int L, int R) {
  int p = log2[R - L + 1];
  return std::min(minv[typ][p][L], minv[typ][p][R - (1 << p) + 1]);
}

struct Node {
  int v, p, L, R;
  bool operator <(const Node &res) const {
    return v < res.v;
  }
  bool operator >(const Node &res) const {
    return v > res.v;
  }
};
std::priority_queue<Node, std::vector<Node>, std::greater<Node> > Q;
inline void ins_seg(int L, int R) {
  if(L > R) return;
  pii th = query(L & 1, L, R);
  Q.push((Node){th.first, th.second, L, R});
}

int main() {
  scanf("%d", &n);
  for(int i = 1; i <= n; i ++) scanf("%d", &A[i]);
  process(); ins_seg(1, n);
  std::vector<int> ret;
  while(!Q.empty()) {
    Node pr = Q.top(); Q.pop();
    ret.push_back(pr.v);
    pii rp = query((pr.p & 1) ^ 1, pr.p + 1, pr.R);
    ret.push_back(rp.first);
    ins_seg(pr.L, pr.p - 1);
    ins_seg(pr.p + 1, rp.second - 1);
    ins_seg(rp.second + 1, pr.R);
  }
  for(int i = 0; i < n; i ++) {
    if(i > 0) putchar(' ');
    printf("%d", ret[i]);
  }
  puts("");
  return 0;
}

