// Range Minimum Query (区間最小クエリ、RMQ)
// Verified: AOJ DSL_2_A: Range Minimum Query (int型のみ)

template <typename T>
class rmq {
public:
    int n;
    vector<T> dat;

    // 要素数 m の RMQ を作る
    void resize(int m) {
        n = 1;
        while(n < m) n *= 2;
        dat.resize(2*n-1);
        rep(i,0,2*n-1) dat[i] = INT_MAX;
    }

    // k番目 (0-indexed) の値を a に更新
    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    // [a, b) の最小値を返す
    // 最初に呼び出すときは XX.query(a, b, 0, 0, -1) とする
    T query(int a, int b, int k, int l, int r) {
        if(r == -1) r = n;
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return dat[k];
        else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

vector<pii> ans;
rmq<int> even, odd;
struct Elem {
    int x, y, val;
};
bool operator<(const Elem &a, const Elem &b) {
    return a.val > b.val;
}

// position [l, r)
void solve() {
    priority_queue<Elem> q;
    q.push(Elem{0, N, even.query(0, N, 0, 0, -1)});

    while(!q.empty()) {
        Elem t = q.top(); q.pop();
        int l = t.x, r = t.y;
        int mi = pos[(l%2 ? odd : even).query(l, r, 0, 0, -1)];
        int ma = pos[(l%2 ? even: odd).query(mi, r, 0, 0, -1)];
        ans.push_back(pii(p[mi], p[ma]));

        if(l < mi) q.push(Elem{l, mi, (l%2 ? odd : even).query(l, mi, 0, 0, -1)});
        if(mi+1 < ma) q.push(Elem{mi+1, ma, ((mi+1)%2 ? odd : even).query(mi+1, ma, 0, 0, -1)});
        if(ma+1 < r) q.push(Elem{ma+1, r, ((ma+1)%2 ? odd : even).query(ma+1, r, 0, 0, -1)});
    }
}

