vector<pair<int,int> > dfs(int l, int r){
  vector<pair<int,int> > res;
  if(l>=r||l<1||r>N) return res;
  int odd=l, even=r;
  for(int i=l;i<=r;i++){
    if((i-(l-1))%2) if(P[i]<P[odd]) odd=i;
  }
  for(int i=odd+1;i<=r;i++){
    if((i-(l-1))%2==0) if(P[i]<P[even]) even=i;
  }

  vector<pair<int,int> > tmp=dfs(l,odd-1);
  for(auto p:tmp) res.push_back(p);
  tmp.clear();

  tmp=dfs(odd+1,even-1);
  for(auto p:tmp) res.push_back(p);
  tmp.clear();

  tmp=dfs(even+1,r);
  for(auto p:tmp) res.push_back(p);

  sort(res.rbegin(),res.rend());
  res.push_back({P[odd],P[even]});
  reverse(res.begin(),res.end());
  return res;
}

