deque<pair<int, int> > mg(const deque<pair<int, int> > &a, const deque<pair<int, int> > &b){
	deque<pair<int, int> > c;
	c.clear();
	for (int i = 0, j = 0; i < a.size() || j < b.size();){
		if (i == a.size()){
			c.push_back(b[j++]);
			continue;
		}
		if (j == b.size()){
			c.push_back(a[i++]);
			continue;
		}
		if (a[i] < b[j]){
			c.push_back(a[i++]);
		}
		else{
			c.push_back(b[j++]);
		}
	}
	return c;
}

deque<pair<int, int> > run(int l, int r){
	deque<pair<int, int> > res;
	vector<pair<int, int> > tmp;
	res.clear();
	if (l >= r){
		return  res;
	}
	int x = find(1, 0, n, l, r, l & 1);
	int pos_x = b[x];
	int y = find(1, 0, n, pos_x + 1, r, 1 ^ (l & 1));
	int pos_y = b[y];

	res = mg(res, run(l, pos_x));
	res = mg(res, run(pos_x + 1, pos_y));
	res = mg(res, run(pos_y + 1, r));

	res.push_front(mp(x ,y));
	//cout << l << ' ' << r << endl;
	//for (auto p : res) cout << "(" << p.X << "," << p.Y << ")" << " "; cout << endl;
	return res;
}

