int build0(int v, int l, int r)
{
	if (l > r)
		return inf;
	if (l == r)
	{
		t0[v] = a[2 * l];
		return t0[v];
	}
	int m = (l + r) / 2;
	t0[v] = min(build0(2 * v, l, m), build0(2 * v + 1, m + 1, r));
	return t0[v];
}

int build1(int v, int l, int r)
{
	if (l > r)
		return inf;
	if (l == r)
	{
		t1[v] = a[2 * (l - 1) + 1];
		return t1[v];
	}
	int m = (l + r) / 2;
	t1[v] = min(build1(2 * v, l, m), build1(2 * v + 1, m + 1, r));
	return t1[v];
}

int dzen0(int v, int l, int r, int tl, int tr)
{
	if (tl > tr || l > r)
		return inf;
	if (l == tl && r == tr)
	{
		return t0[v];
	}
	int m = (l + r) / 2;
	return min(dzen0(2 * v, l, m, tl, min(tr, m)), dzen0(2 * v + 1, m + 1, r, max(tl, m + 1), tr));
}

int dzen1(int v, int l, int r, int tl, int tr)
{
	if (tl > tr || l > r)
