const int N = 2e5, INF = 1e9;

vector<int> o, a, b;

int ta[4 * N], tb[4 * N], p[2 * N];

void builda(int v, int l, int r)
{
	if (r - l == 1)
	{
		ta[v] = a[l];
		return;
	}       

	int m = (l + r) / 2;

	builda(2 * v, l, m);
	builda(2 * v + 1, m, r);

	ta[v] = min(ta[2 * v], ta[2 * v + 1]); 
}

void buildb(int v, int l, int r)
{
	if (r - l == 1)
	{
		tb[v] = b[l];
		return;
	}       

	int m = (l + r) / 2;

	buildb(2 * v, l, m);
	buildb(2 * v + 1, m, r);

	tb[v] = min(tb[2 * v], tb[2 * v + 1]); 
}

int geta(int v, int l, int r, int L, int R)
{
	if (l >= R || L >= r)
		return INF;
	if (L <= l && r <= R)
		return ta[v];

	int m = (l + r) / 2;

	return min(geta(2 * v, l, m, L, R), geta(2 * v + 1, m, r, L, R));
}

int getb(int v, int l, int r, int L, int R)
{
	if (l >= R || L >= r)
		return INF;
	if (L <= l && r <= R)
		return tb[v];

	int m = (l + r) / 2;

	return min(getb(2 * v, l, m, L, R), getb(2 * v + 1, m, r, L, R));
}

vector<int> f(int l, int r, int d = 0)
{
	//cout << l << " " << r << " " << d <<"\n";

	vector<int> res;

	if (r <= l)
		return res;
	if (l + 1 == r)
	{
		res.push_back(o[l]);
		res.push_back(o[r]);	
		return res;
	}

	int la, ra, xa;
	int lb, rb, xb;

	if (l & 1)
	{
		la = l / 2, ra = r / 2;
		xa = getb(1, 0, b.size(), la, ra);
		lb = (l + 1) / 2, rb = r / 2 + 1;
		xb = geta(1, 0, a.size(), lb, rb);		
	}
	else
	{
		la = l / 2, ra = r / 2 + 1;
		xa = geta(1, 0, a.size(), la, ra);
		lb = l / 2, rb = r / 2 + 1;
		xb = getb(1, 0, b.size(), lb, rb);
	}                           

	res.push_back(xa);
	res.push_back(xb);

	vector<int> cd[3];

	cd[0] = f(l, p[xa] - 1, d + 1);	
	cd[1] = f(p[xa] + 1, p[xb] - 1, d + 1);
	cd[2] = f(p[xb] + 1, r, d + 1);

	cd[0].push_back(INF);
	cd[1].push_back(INF);
	cd[2].push_back(INF);

	int i1 = 0, i2 = 0, i3 = 0;

	while (res.size() <= r - l)
	{
		int x1 = cd[0][i1], x2 = cd[1][i2], x3 = cd[2][i3];

		if (x1 < x2 && x1 < x3)
		{
			res.push_back(cd[0][i1]);
			res.push_back(cd[0][i1 + 1]);
			i1 += 2;
		}
		else if (x2 < x3)
		{
                	res.push_back(cd[1][i2]);
			res.push_back(cd[1][i2 + 1]);
			i2 += 2;
		}
		else
		{
                	res.push_back(cd[2][i3]);
			res.push_back(cd[2][i3 + 1]);
			i3 += 2;
		}
	}                 

	return res;
}

