        cout<<val<<' '<<val2<<' ';
        for (int i=1; i<=3; i++) {
            if (ans[cur*3+i].first==0x3f3f3f3f) continue;
            q.push({cur*3+i,ans[cur*3+i].first,ans[cur*3+i].second});
        }
    }
