		for(int k=1;k<=20;k++)
			for(int i=1;i<=dn;i++)
				if(i+(1<<k)-1<=dn)
				{
					ef[i][k]=std::min(ef[i][k-1],ef[i+(1<<(k-1))][k-1]);
					of[i][k]=std::min(of[i][k-1],of[i+(1<<(k-1))][k-1]);
				}
//		printf("fuck %d %d %d\n",of[1][0],of[2][0],of[1][1]);
