//		printf("query : %d %d\n",L,R);
		int x=1,k=0;
		while(x*2<=(R-L+1))x<<=1,k++;
//		printf("%d , %d : %d %d\n",L,R-x+1,of[L][k],of[R-x+1][k]);
		return std::min(of[L][k],of[R-x+1][k]);
	}
	int query_even(int L,int R)
	{
		int x=1,k=0;
		while(x*2<=(R-L+1))x<<=1,k++;
		return std::min(ef[L][k],ef[R-x+1][k]);
	}
	inline int ev(int L,int R){return query_even((L+1)>>1,R>>1);}
	inline int od(int L,int R){return query_odd((L>>1)+1,(R+1)>>1);}
