void rec(int l ,int r,int deap){
  if(l == r) return;
  int i = idx[segs[l % 2].get_inter(l,r)];
  int j = idx[segs[(l + 1) % 2].get_inter(l,r)];
  rec(l,i,deap + 1);
  rec(i + 1,j,deap + 1);
  rec(j + 1,r,deap + 1);;
  ans.push_back({deap,{p[i],p[j]}});
}
int main() {
  cin >> n;
  rep(i, 0, n - 1) {
     cin >> p[i]; 
     idx[p[i]] = i;
     segs[i % 2].update(i,p[i]);
  }

  rec(0,n,0);

  sort(ans.begin(),ans.end());

  for(auto p : ans){
    cout << p.second.first << " " << p.second.second << " " ;
  }
  cout << endl;
}

