typedef long long LL;

const int MaxN = 2e5, Pow = 20;
int n, tot;
int a[MaxN + 5];
int odd[MaxN + 5];
int even[MaxN + 5];
struct ARR {
	pair <int, int> w;
	int dep;
}ans[MaxN + 5];
pair <int, int> rmq[2][MaxN + 5][Pow + 2];

pair <int, int> MIN(pair <int, int> A, pair <int, int> B) {
	if (A.first < B.first) return A;
	return B;
}

void Make_RMQ(int t, int a[])
{
	int k = (int)(log(a[0] * 10) / log(2.0));	
	for (int i = 1; i <= a[0]; i++) {
		rmq[t][i][0].first = a[i];
		rmq[t][i][0].second = i * 2 - t; 
	}
	for (int i = 1; i <= k; i++)
		for (int j = 1; j <= a[0] - (1 << i) + 1; j++) 
			rmq[t][j][i] = MIN(rmq[t][j][i - 1], rmq[t][j + (1 << (i - 1))][i - 1]);
}

pair <int, int> Ask(int t, int l, int r)
{
	int k = (int)(log(r - l + 1.0) / log(2.0));
	return MIN(rmq[t][l][k], rmq[t][r - (1 << k) + 1][k]);
}

void Init() 
{
	memset(odd, 0, sizeof(odd));
	memset(even, 0, sizeof(even));
	memset(a, 0, sizeof(a));
	for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
	for (int i = 1; i <= n; i++) 
		if (i & 1) odd[++odd[0]] = a[i];
			else even[++even[0]] = a[i];
	Make_RMQ(1, odd); Make_RMQ(0, even);
}

void Work(int dep, int L, int R)
{
	if (R < L) return;
	pair <int, int> l, r;
	if (L & 1) {
		l = Ask(1, (L + 1) / 2, (R + 1) / 2);
		r = Ask(0, (l.second + 1) / 2, R / 2);
		ans[++tot].w = make_pair(l.first, r.first);
		ans[tot].dep = dep;
		Work(dep + 1, L, l.second - 1);
		Work(dep + 1, l.second + 1, r.second - 1);
		Work(dep + 1, r.second + 1, R);
	}
	else {
		l = Ask(0, L / 2, R / 2);
		r = Ask(1, (l.second + 2) / 2, (R + 1) / 2);
		ans[++tot].w = make_pair(l.first, r.first);
		ans[tot].dep = dep;
		Work(dep + 1, L, l.second - 1);
		Work(dep + 1, l.second + 1, r.second - 1);
		Work(dep + 1, r.second + 1, R);
	}
}

bool cmp(ARR A, ARR B) {
	if (A.dep == B.dep) return A.w < B.w;
	return A.dep < B.dep;
}

void Solve()
{
	tot = 0;
	Work(1, 1, n);
	sort(ans + 1, ans + tot + 1, cmp);
	for (int i = 1; i <= tot; i++) 
		printf("%d %d ", ans[i].w.first, ans[i].w.second);
	printf("\n");
}

int main()
{
	while (~scanf("%d", &n)) {
		Init();
		Solve();
	}
	return 0;
}

