class YoungMaids{
    int N;
    vi P,I;
    vector<vi> E;
    void init(){
        cin>>N;
        P.resize(N);
        I.resize(N+1);
        E.resize(N+1);
        for(int i=0;i<N;++i) cin>>P[i];
    }
    int dfs(int l,int r){
        assert((l+r)%2 == 0);
        if(r==l+2){
            I[P[l]] = P[r-1];
            return P[l];
        }
        int ie = l, io = l+1;
        for(int i=2;i<r-l;++i){
            if(i%2==0 && P[l+i]<P[ie]){
                ie = l+i;
                io = l+i+1;
            }
            else if(i%2 && P[l+i]<P[io]) io = l+i;
        }
        I[P[ie]] = P[io];
        if(ie>l) E[P[ie]].push_back(dfs(l, ie));
        if(io>ie+1) E[P[ie]].push_back(dfs(ie+1, io));
        if(r>io+1) E[P[ie]].push_back(dfs(io+1, r));
        return P[ie];
    }


public:
    void solve(){
        init();
        int beg = dfs(0, N);
        priority_queue<int, vector<int>, greater<int>> que;
        que.push(beg);
        while(!que.empty()){
            int k = que.top();
            que.pop();
            cout<<k<<' '<<I[k]<<' ';
            for(auto j:E[k]) que.push(j);
        }
        cout<<endl;
    }
};

int main(){
    YoungMaids().solve();
    return 0;
}

