map<int,map<int,int> > num;
struct node {
    int x,y;
    node(int _x = 0,int _y = 0) {
        x = _x; y = _y;
    }
    bool operator < (node a) const {
        return best[num[a.x][a.y]] < best[num[x][y]];
    }
};
priority_queue<node> heap;
void build(int num,int pos,int l,int r) {
    if(l>r) return ;
    if(l==r) {
        tree[num][pos] = {inf,0};
        return ;
    }
    int mid = (l+r)/2;
    build(num,pos<<1,l,mid); build(num,pos<<1|1,mid+1,r);
    tree[num][pos] = min(tree[num][pos<<1],tree[num][pos<<1|1]);
}
void update(int num,int pos,int l,int r,int x,int val) {
    if(l>r || l>x || r<x) return ;
    if(l==r) {
        tree[num][pos] = {val,x};
        return ;
    }
    int mid = (l+r)/2;
    update(num,pos<<1,l,mid,x,val); update(num,pos<<1|1,mid+1,r,x,val);
    tree[num][pos] = min(tree[num][pos<<1],tree[num][pos<<1|1]);
}
pair<int,int> query(int num,int pos,int l,int r,int x,int y) {
    if(l>r || r<x || y<l) return {inf,0};
    if(x<=l && r<=y) return tree[num][pos];
    int mid = (l+r)/2;
    return min(query(num,pos<<1,l,mid,x,y), query(num,pos<<1|1,mid+1,r,x,y));
}
void f(int l,int r) {
//    printf("F %d %d\n",l,r);
    int i,x,y;
    pair<int,int> t1,t2;
    t1 = query(l&1,1,1,n,l,r);
    x = t1.Y;
    t2 = query(!(l&1),1,1,n,x,r);
    y = t2.Y;
    num[l][r] = cnt++;
    best[num[l][r]] = {p[x],p[y]};
    if(l<=x-1) f(l,x-1), a[num[l][r]].push_back({l,x-1});
    if(y+1<=r) f(y+1,r), a[num[l][r]].push_back({y+1,r});
    if(x+1<=y-1) f(x+1,y-1), a[num[l][r]].push_back({x+1,y-1});
}
main() {
    int i,x,y,cur;
    scanf("%d",&n);
    build(0,1,1,n); build(1,1,1,n);
    for(i=1;i<=n;i++) scanf("%d",&p[i]), update(i&1,1,1,n,i,p[i]);
    f(1,n);
    heap.push(node(1,n));
    while(!heap.empty()) {
        x = heap.top().x; y = heap.top().y; heap.pop();
        cur = num[x][y];
        printf("%d %d ",best[cur].X,best[cur].Y);
        for(i=0;i<a[cur].size();i++) heap.push(node(a[cur][i].X,a[cur][i].Y));
    }
}

