#define MOD 1000000007
#define INF 1000000000
#define MAX_N 100005

int n;                      // 葉の数。2 のべき乗
pair<int, int> even[MAX_N * 2 - 1];    // 偶数番目の要素のセグメント木 (位置, 値)
pair<int, int> odd[MAX_N * 2 - 1];     // 奇数番目の要素のセグメント木 (位置, 値)
// セグメント木での Range Minimum Query (RMQ) の実装
// 区間[i, j] に含まれる最小値の取得と、値の更新
// 初期化
void init() {
    REP(i, 2*n-1){
        even[i].first = i * 2;
        even[i].second = INF;
        odd[i].first = i * 2 + 1;
        odd[i].first = INF;
    }
}
// 値の更新 O(log n)
// i 番目の値 (0-indexed) を x に変更
void update(bool isEven, int i, pair<int, int> x) {
    // 葉の番号
    i += n - 1;
    if(isEven) { even[i] = x; }
    else { odd[i] = x; }
    // 登りながら更新
    while(i>0) {
        i = (i-1)/2;
        if(isEven) {
            if(even[i*2+1].second < even[i*2+2].second) { even[i] = even[i*2+1]; }
            else { even[i] = even[i*2+2]; }
        }
        else {
            if(odd[i*2+1].second < odd[i*2+2].second) { odd[i] = odd[i*2+1]; }
            else { odd[i] = odd[i*2+2]; }
        }
    }
}
// 最小値の取得 O(log n)
// [a, b) の最小値、 l, r にはノード k に対応づく区間を与える
// 一番初めは query_impl(a, b, 0, 0, n) のように呼ぶ
pair<int, int> query_impl(bool isEven, int a, int b, int k, int l, int r) {
    if(r <= a || b <= l){ return make_pair(INF, INF); } // 交差しない？
    if(a <= l && r <= b){
        if(isEven) { return even[k]; }
        else { return odd[k]; }
    }  // 完全に含む？
    else {
        pair<int, int> vl = query_impl(isEven, a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子を見る
        pair<int, int> vr = query_impl(isEven, a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子を見る
        //printf("  vl.second %d vr.second %d\n", vl.second, vr.second);
        if(vl.second < vr.second) { return vl; }
        else { return vr; }
    }
}
pair<int, int> query(bool isEven, int a, int b) {
    return query_impl(isEven, a, b, 0, 0, n);
}

int ans[MAX_N * 2];
int N;

struct x_less {
    bool operator()(const pair< int, pair<int, int> >& x, const pair< int, pair<int, int> >& y) const {
        return x.first < y.first;
    }
};

int main()
{
    ZERO(ans);
    cin >> N;
    n = N / 2;
    // セグメント木の構築
    init();
    REP(i, N) {
        int tmp;
        //scanf("%d", &tmp);
        cin >> tmp;
        bool isEven = (i % 2 == 0);
        //printf("add ind %d (%d, %d) to %s\n", i / 2, i, tmp, (isEven) ? "even" : "odd");
        update(isEven, i / 2, make_pair(i, tmp));
    }

    // 区間 (区間の最小値, 区間の範囲 [) )
    priority_queue< pair<int, pair<int, int> >,
        vector< pair<int, pair<int, int> > >,
        greater< pair<int, pair<int, int> > > > range;
    range.push(make_pair(query(true, 0, n).second, make_pair(0, N)));
    //printf("min: %d\n", query(true, 0, n).second);
    //printf("min: %d\n", query(false, 0, n).second);

    int ans_ind = 0;
    while(ans_ind < N) {
        // 最小の値を持つ区間を取得
        pair< int, pair<int, int> > min_range = range.top();
        range.pop();
        bool isEven = (min_range.second.first % 2 == 0);    // 区間の始点は偶数か？
        // 確定した値を入れる
        pair<int, int> cand1, cand2;
        //printf("min_range.second (%d, %d)\n", min_range.second.first, min_range.second.second);
        if(isEven) {
            cand1 = query(true, min_range.second.first / 2, min_range.second.second / 2);
            cand2 = query(false, min_range.second.first / 2, min_range.second.second / 2);
        } else {
            cand1 = query(false, min_range.second.first / 2, min_range.second.second / 2);
            cand2 = query(true, min_range.second.first / 2 + 1, min_range.second.second / 2 + 1);
        }
        //printf("get (%d, %d) (%d, %d)\n", cand1.first, cand1.second, cand2.first, cand2.second);
        ans[ans_ind] = cand1.second;
        ans_ind++;
        ans[ans_ind] = cand2.second;
        ans_ind++;
        if(ans_ind >= N) { break; }
        // 区間を 3 つに分割
        pair<int, int> range1 = make_pair(min_range.second.first, cand1.first);
        pair<int, int> range2 = make_pair(cand1.first + 1, cand2.first);
        pair<int, int> range3 = make_pair(cand2.first + 1, min_range.second.second);
        // 各区間を priority_queue に入れる
        if(range1.first != range1.second) {
            isEven = (range1.first % 2 == 0);
            int min_range1 = query(isEven, range1.first / 2, range1.second / 2).second;
            range.push(make_pair(min_range1, range1));
            //printf("1add %d [%d, %d)\n", min_range1, range1.first, range1.second);
        }
        if(range2.first != range2.second) {
            isEven = (range2.first % 2 == 0);
            int min_range2 = query(isEven, range2.first / 2, range2.second / 2).second;
            range.push(make_pair(min_range2, range2));
            //printf("2add %d [%d, %d)\n", min_range2, range2.first, range2.second);
        }
        if(range3.first != range3.second) {
            isEven = (range3.first % 2 == 0);
            int min_range3 = query(isEven, range3.first / 2, range3.second / 2).second;
            range.push(make_pair(min_range3, range3));
            //printf("3add %d [%d, %d)\n", min_range3, range3.first, range3.second);
        }
        //printf("\n");
    }
    //assert(range.size() == 0);
    REP(i, N) {
        printf("%d", ans[i]);
        if(i != N - 1) { printf(" "); }
    }
    printf("\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAX_N = 1 << 19;
const int def = 1 << 25;
const int INF = 1 << 25;

typedef pair<int, int> ValIdx;
struct MinSegTreeIdx {
	int n;
	ValIdx node[2 * MAX_N - 1];

	void init(int n_) {
		n = 1;
		while(n < n_) n *= 2;
		for(int i = 0; i < 2 * n - 1; i++) node[i] = make_pair(def, -1);
	}

	ValIdx merge(ValIdx l, ValIdx r) {
		if(l.first <= r.first) return l;
		return r;
	}

	void update(int k, int a) {
		k += n - 1;
		node[k] = make_pair(a, k - (n - 1));
		while(k > 0) {
			k = (k - 1) / 2;
			node[k] = merge(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}

	ValIdx query(int a, int b) { return query(a, b, 0, 0, n); }

	ValIdx query(int a, int b, int k, int l, int r) {
		if(r <= a || b <= l) return make_pair(def, def);
		if(a <= l && r <= b) return node[k];
		ValIdx vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ValIdx vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return merge(vl, vr);
	}

	void show() {
		for(int i = 0; i < n; i++) cout << node[i + n - 1].first << " ";
		cout << endl;
	}
};

int a[200000];
MinSegTreeIdx even, odd;
int N;
set<int> s;

typedef pair<int, int> P;
typedef pair<P, int> Pi;

vector<P> ps;
vector<int> children[200000];

Pi f(int L, int R){
	int len = R - L;
	if(len <= 0) {
		return { {-1, -1}, -1 };
	}

	int id = ps.size();
	ps.push_back({ -1, -1 });

	if(len == 2) {
		ps[id] = { a[L], a[L + 1] };
		return { ps[id] ,id };
	}

	MinSegTreeIdx* st1 = &even;
	MinSegTreeIdx* st2 = &odd;
	if(L % 2 == 1) {
		st1 = &odd;
		st2 = &even;
	}

	auto res1 = st1->query(L, R - 1);
	//cout << res1.first << " " << res1.second << endl;
	int l = res1.second;
	int right = *s.upper_bound(l);
	auto res2 = st2->query(l + 1, right);
	//cout << res2.first << " " << res2.second << endl;
	int r = res2.second;

	s.insert(l);
	s.insert(r);

	auto k1 = f(L, l), k2 = f(l + 1, r), k3 = f(r + 1, R);
	if(k1.second != -1) children[id].push_back(k1.second);
	if(k2.second != -1) children[id].push_back(k2.second);
	if(k3.second != -1) children[id].push_back(k3.second);

	//st1->update(l, INF);
	//st1->update(r, INF);
	//st2->update(l, INF);
	//st2->update(r, INF);

	ps[id] = { a[l], a[r] };
	return { ps[id] ,id };
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;

	even.init(N);
	odd.init(N);

	for(int i = 0; i < N; i++) {
		cin >> a[i];
		if(i % 2 == 0) {
			even.update(i, a[i]);
			odd.update(i, INF);
		}
		else {
			even.update(i, INF);
			odd.update(i, a[i]);
		}
	}
	//even.show();
	//odd.show();

	s.insert(N);

	deque<int> ans;
	priority_queue<Pi, vector<Pi>, greater<Pi>> q;
	auto res = f(0, N);
	q.push(res);
	while(q.size()) {
		auto pi = q.top();
		q.pop();
		ans.push_back(pi.first.first);
		ans.push_back(pi.first.second);
		int id = pi.second;
		for(auto c : children[id]) {
			q.push({ ps[c], c });
		}
	}

	for(int i = 0; i < N; i++) {
		cout << ans[i] << " ";
	}
	cout << endl;
}

