	std::cin>>n;
	std::vector<RMiQ> st(2,RMiQ(n,INF));
	rep(i,n){
		std::cin>>p[i];
		st[i%2].update(i,p[i]);
		d[p[i]]=i;
	}
	interval.insert(0);
	interval.insert(n);
	min.insert(st[0].query(0,n));
	std::vector<int> ans;
	rep(i,n/2){
		int x=*min.begin();
		ans.emplace_back(x);
		int l=d[x]+1,r=*interval.upper_bound(d[x]);
		int y=st[l%2].query(l,r);
