		if(l!=d[x])min.insert(st[l%2].query(l,d[x]));
		if(d[x]+1!=d[y])min.insert(st[(d[x]+1)%2].query(d[x]+1,d[y]));
		if(d[y]+1!=r)min.insert(st[(d[y]+1)%2].query(d[y]+1,r));
	}
