void build(int v = 1, int tl = 1, int tr = n){
	t[1][v] = t[0][v] = mp(inf, 0);
	if(tl == tr)
		return;
	int tm = (tl + tr) / 2;
	build(v * 2, tl, tm);
	build(v * 2 + 1, tm + 1, tr);
}
void upd(int type, int pos, int x, int v = 1, int tl = 1, int tr = n){
	if(tl == tr){
		t[type][v] = mp(x, pos);
		return;
	}
	int tm = (tl + tr) / 2;
	if(pos <= tm)
		upd(type, pos, x, v * 2, tl, tm);
	else
		upd(type, pos, x, v * 2 + 1, tm + 1, tr);
	t[type][v] = minim(t[type][v * 2], t[type][v * 2 + 1]);
}
pair<int, int> get(int type, int l, int r, int v = 1, int tl = 1, int tr = n){
	if(tl > r || tr < l || l > r)
		return mp(inf, 0);
	if(tl >= l && tr <= r)
		return t[type][v];
	int tm = (tl + tr) / 2;
	return minim(get(type, l, r, v * 2, tl, tm), get(type, l, r, v * 2 + 1, tm + 1, tr));
}
pair<int, int> solve(int l, int r){
	if(l >= r)
		return mp(inf, inf);
	int si = l % 2;
	pair<int, int> L = get(si, l, r);
	pair<int, int> R = get((si ^ 1), L.S + 1, r);
