            }
            ans.push_back(m.first);
            if (m.second != orr.l) {
                er.push({orr.l, m.second, (orr.even ? et : ot).query(orr.l / 2, m.second / 2), orr.even});
            }
            if (m.second + 1 != orr.r) {
                er.push({m.second + 1, orr.r, (!orr.even ? et : ot).query(orr.l / 2, (m.second + 1) / 2), !orr.even});
            }
