    for (int i = 1; i <= n; i++)
    {
        if (u[i]) continue;

        int ind = pos[i], l, r, res;

        pair <int, int> cur_seg = *(--seg.upper_bound( mk(ind, inf) ));

        l = cur_seg.fr;
        r = cur_seg.sc;

        res = get( ind + 1, r, (ind & 1) );

        if (res == inf)
        {
            res = get( l, ind - 1, (ind & 1) );

            int Pos = pos[res];

            if (Pos > ind)
                swap(Pos, ind);

            if ( (Pos - l + 1) % 2 == 0)
                continue;

            seg.erase( cur_seg );

            if (l <= Pos - 1)
                seg.insert( mk(l, Pos - 1) );
            if (Pos + 1 <= ind - 1)
                seg.insert( mk(Pos + 1, ind - 1) );
            if (ind + 1 <= r)
                seg.insert( mk(ind + 1, r) );

            u[res] = 1;

            ans[++cnt] = res;
            ans[++cnt] = i;
        }
        else
        {
            int Pos = pos[res];

            if (Pos > ind)
                swap(Pos, ind);

            if ( (Pos - l + 1) % 2 == 0)
                continue;

            seg.erase( cur_seg );

            if (l <= Pos - 1)
                seg.insert( mk(l, Pos - 1) );
            if (Pos + 1 <= ind - 1)
                seg.insert( mk(Pos + 1, ind - 1) );
            if (ind + 1 <= r)
                seg.insert( mk(ind + 1, r) );

            u[res] = 1;
            ans[++cnt] = i, ans[++cnt] = res;
        }
    }
    for (int i = 1; i <= n; i++)
        cout << ans[i] << " ";
}

