int f(int p, int q, int r) {
	int t, mn=1e9, mi;
	p = bs + p/2;
	q = bs + q/2;
	while(p<q) {
		if(p%2==1) {
			t = tr[r][p];
			if(a[t]<mn) mn=a[t], mi=t;
			p++;
		}
		if(q%2==0) {
			t = tr[r][q];
			if(a[t]<mn) mn=a[t], mi=t;
			q--;
		}
		p/=2, q/=2;
	}
	if(p==q) {
		t = tr[r][p];
		if(a[t]<mn) mn=a[t], mi=t;
	}
	return mi;
}

