deque<pair<int, int>> merge(deque<pair<int, int>> a, deque<pair<int, int>> b){
	deque<pair<int, int>> res(a.size() + b.size());
	merge(all(a), all(b), res.begin());
	return res;
}

vector<int> p, idx;
deque<pair<int, int>> dfs(int l, int r, SegTree<Monoid>& even, SegTree<Monoid>& odd){
	if(l >= r) return deque<pair<int, int>>();
	if(r - l == 2){
		deque<pair<int, int>> res = {make_pair(p[l], p[l + 1])};
		return res;
	}

	int L, R;
	if(l % 2){
		L = idx[odd.query(l, r - 1)]; //閉区間
		R = idx[even.query(L,r)]; // 閉区間
	}else{
		L = idx[even.query(l,r - 1)]; // 閉区間
		R = idx[odd.query(L, r)]; //閉区間
	}
	//cout << L << ' ' << R << endl;

	deque<pair<int, int>> a = dfs(l, L, even, odd);
	deque<pair<int, int>> b = dfs(L + 1, R, even, odd);
	deque<pair<int, int>> c = dfs(R + 1, r, even, odd);

	deque<pair<int, int>> res = merge(merge(a,b),c);
	res.emplace_front(make_pair(p[L], p[R]));
	return res;
}

