struct Seg_Tree{

	int x[N];
	int val[N<<2],id[N<<2];

	void build(int root,int l,int r){
		if(l==r){
			val[root]=x[l],id[root]=l;
			return ;
		}
		int m=(l+r)>>1;
		build(lson,l,m);
		build(rson,m+1,r);
		if(val[lson]>val[rson]) id[root]=id[rson];
		else id[root]=id[lson];
		val[root]=min(val[lson],val[rson]);
	}

	int query(int root,int l,int r,int a,int b){
		if(l==a && r==b) return id[root];

		int m=(l+r)>>1;
		if(b<=m) return query(lson,l,m,a,b);
		else if(a>m) return query(rson,m+1,r,a,b);
		else{
			int L=query(lson,l,m,a,m);
			int R=query(rson,m+1,r,m+1,b);
			if(x[L]>x[R]) return R;
			else return L;
		}
	}
}t[2];
int a[N],n;

struct Node{
	pii x,y,z;
	Node(){}
	Node(pii x,pii y,pii z){
		this->x=x;
		this->y=y;
		this->z=z;
	}
	bool operator < (const Node& tmp) const{
		return x>tmp.x;
	}
};

pii getfuck(int l,int r){
	int lid=t[l&1].query(1,1,n,l,r);
	int rid=t[!(l&1)].query(1,1,n,lid+1,r);
	return pii(lid,rid);
}

