	for(int i=2;i<=n;i+=2) t[0].x[i]=a[i],t[0].x[i-1]=INF;

	t[0].build(1,1,n),t[1].build(1,1,n);

	pii tmp=getfuck(1,n);
	Node cur=Node(pii(a[tmp.first],a[tmp.second]),tmp,pii(1,n));
