int tree[2][804040], n;
map <int, int> pos;

void build (int i, int ind, int l, int r, int x, int v) {
	if (l == r) {
		tree[i][ind] = v;
		return;
	}
	int mid = (l+r)/2;
	if (x <= mid) {
		build(i, ind*2, l, mid, x, v);
	} else {
		build(i, ind*2+1, mid+1, r, x, v);
	}
	tree[i][ind] = min(tree[i][ind*2], tree[i][ind*2+1]);
}

int query (int i, int ind, int l, int r, int x, int y) {
	if (l == x && r == y) {
		return tree[i][ind];
	}
	if (l > y || r < x || x > y) {
		return 1<<30;
	}
	int mid = (l+r)/2;
	return min(query(i, ind*2, l, mid, x, min(mid, y)), query(i, ind*2+1, mid+1, r, max(mid+1, x), y));
}

node* sol (int l, int r) {
	if (l >= r) {
		return NULL;
	}

	int x, y;
	x = query(l%2, 1, 0, n-1, l, r);
	y = query(1-(l%2), 1, 0, n-1, pos[x]+1, r);
	node *new_node = new node(x, y);
	new_node->ch.push_back(sol(pos[x]+1, pos[y]-1));
	new_node->ch.push_back(sol(l, pos[x]-1));
	new_node->ch.push_back(sol(pos[y]+1, r));

	return new_node;
}

