	datax() {
		n = v1 = v2 = 0;
	}
	datax(int n, int v1, int v2) : n(n), v1(v1), v2(v2) {}
	datax operator + (const datax &l) const {
		datax rv = datax();
		rv.n = n + l.n;
		rv.v1 = v1, rv.v2 = v2;
		if (n % 2 == 1) {
			rv.v1 = min(rv.v1, l.v2);
