	}
};
datax indt[600000];
void update(int p, int v) {
	p += IT_MAX - 1;

	datax u = datax(1, v, INF);
	if (v == INF) u = datax(0, INF, INF);
	indt[p] = u;
	for (p /= 2; p; p /= 2) indt[p] = indt[2 * p] + indt[2 * p + 1];
}

set <int> Sx;
datax getv(int p1, int p2) {
	p1 += IT_MAX - 1;
	p2 += IT_MAX - 1;

	vector <datax> V1;
	vector <datax> V2;

	for (; p1 <= p2; p1 /= 2, p2 /= 2) {
		if (p1 % 2 == 1) V1.push_back(indt[p1++]);
		if (p2 % 2 == 0) V2.push_back(indt[p2--]);
	}
	reverse(all(V2));

	datax rv = datax(0, INF, INF);
	for (auto it : V1) rv = rv + it;
	for (auto it : V2) rv = rv + it;
	return rv;
}

