  auto min_fn = [](int x, int y) { return min(x, y); };
  SegmentTree<int> tree1(min_fn, INF, ps1);
  SegmentTree<int> tree2(min_fn, INF, ps2);

  auto make_range_fn = [&](int l, int r) -> Range {
    if (l % 2 == 0) {
      return Range(l, r, tree1.GetRange(l, r));
    } else {
      return Range(l, r, tree2.GetRange(l, r));
    }
  };

  auto compare_range_fn = [](Range r1,  Range r2) {
    return r1.v > r2.v;
  };
  priority_queue<Range, vector<Range>, decltype(compare_range_fn)> pq(compare_range_fn);
  pq.push(Range(0, n, tree1.GetRange(0, n)));

  vector<int> outputs;

  while (!pq.empty()) {
    Range range = pq.top();
    pq.pop();
    int v1 = range.v;
    int i1 = v_to_i[v1];
    outputs.push_back(range.v);

    int v2;
    if (range.l % 2 == 0) {
      v2 = tree2.GetRange(i1 + 1, range.r);
    } else {
      v2 = tree1.GetRange(i1 + 1, range.r);
    }
    int i2 = v_to_i[v2];
    outputs.push_back(v2);

    if (range.l < i1) {
      pq.push(make_range_fn(range.l, i1));
    }
    if (i1 + 1 < i2) {
      pq.push(make_range_fn(i1 + 1, i2));
    }
    if (i2 + 1 < range.r) {
      pq.push(make_range_fn(i2 + 1, range.r));
    }
  }

  for (int output : outputs) {
    cout << output << " ";
  }
  cout << endl;
}

