struct Info {
    pii Pair;
    int a;
    int b;
    int dom_even;
    int dom_odd;
    bool operator<(const Info& i) const
    {
        return i.Pair < Pair;
    }
};
ostream& operator<<(ostream& os, const Info& i)
{
    os << "Pair: " << i.Pair << endl;
    os << "(a,b): (" << i.a << ", " << i.b << ")" << endl;
    os << "dom_even: " << i.dom_even << endl;
    os << "dom_odd: " << i.dom_odd << endl;
    return os;
}
priority_queue<Info> Queue;  // (pair, (a, b))

void act(const int a, const int b, const SegmentTree<Min_Plus>& oddseg, const SegmentTree<Min_Plus>& evenseg)  // [a, b)
{
    if (a >= b) {
        return;
    }
    if (a < 0) {
        return;
    }
    if (b > N) {
        return;
    }
    assert(a % 2 == b % 2);
    const bool left_even = a % 2 == 0;
    const auto& dom_oddseg = (left_even) ? oddseg : evenseg;
    const auto& dom_evenseg = (left_even) ? evenseg : oddseg;

    const int dom_evenmin = dom_evenseg.accumulate(a / 2, b / 2);
    const int dom_evenmin_ind = rev[dom_evenmin];
    const int dom_oddmin = dom_oddseg.accumulate((dom_evenmin_ind + 1) / 2, (b + 1) / 2);
    const int dom_oddmin_ind = rev[dom_oddmin];
    Queue.push(Info{make_pair(dom_evenmin + 1, dom_oddmin + 1), a, b, dom_evenmin_ind, dom_oddmin_ind});
}

