typedef pair<int, int> P;
P b[200005];
int nn;
int binary(int k) {
	int lb = -1, ub = nn;
	while (ub - lb > 1) {
		int mid = (ub + lb) / 2;
		if (b[mid].first >= k)ub = mid;
		else lb = mid;
	}
	return b[ub].second;
}
signed main(void)
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	int a[200005];
