		cin >> a[i];
	}
	init(nn);
	init2(nn);
	for (int i = 0; i < nn; i++) {
		b[i] = P(a[i], i);
	}
	sort(b, b + nn);
	for (int i = 0; i < nn; i += 2) {
		update(i, a[i]);
	}
	for (int i = 1; i < nn; i += 2) {
		update2(i, a[i]);
	}
	vector<int> ans;
	priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> que;
	que.push(make_tuple(query(0, nn, 0, 0, n), 0, nn));
	int cnt = 0;
	while (!que.empty()) {
		cnt += 1;
		tuple<int, int, int> now;
		now = que.top();
		que.pop();
		int mi, a, b;
		mi = get<0>(now);
		a = get<1>(now);
		b = get<2>(now);
		int pomi;
		pomi = binary(mi);
		int ma;
		if (pomi % 2 == 0)
			ma = query2(a, b, 0, 0, n);
		else ma = query(a, b, 0, 0, n);
		ans.push_back(mi);
		ans.push_back(ma);
		int poma;
		poma = binary(ma);
		if (pomi > a) {
			if (a % 2 == 0)
				que.push(make_tuple(query(a, pomi, 0, 0, n), a, pomi));
			else
				que.push(make_tuple(query2(a, pomi, 0, 0, n), a, pomi));
		}
		if (poma - 1 > pomi + 1) {
			if ((pomi + 1) % 2 == 0)
				que.push(make_tuple(query(pomi + 1, poma, 0, 0, n), pomi + 1, poma));
			else
				que.push(make_tuple(query2(pomi + 1, poma, 0, 0, n), pomi + 1, poma));
		}
		if (b - 1 > poma) {
			if ((poma + 1) % 2 == 0)
				que.push(make_tuple(query(poma + 1, b, 0, 0, n), poma + 1, b));
			else
				que.push(make_tuple(query2(poma + 1, b, 0, 0, n), poma + 1, b));
		}
	}
	for (int i = 0; i < nn; i++) {
