typedef pair<int, int> P;

int n, a, b;
P *mia, *mib;
P seg1[4 * (2 * N + 1)], seg2[4 * (2 * N + 1)];
vector<int> divi, divi2, divi3;
map<P, bool> flag;
priority_queue<P, vector<P>, greater<P> > pq;

void init(P aa[], int nn)
{
	n = 1;
	while (n < nn) n *= 2;

	for (int i = 0; i < n * 2 - 1; i++)
		aa[i] = MP(INF,INF);
}


void update(P aa[], int k, int c, int nn)
{
	int num = k;
	k += nn - 1;
	aa[k] = MP(c, num);
	int cc = nn;
	while (k != 0)
	{
		k = (k - 1) / 2;
		if (aa[k].first <= c)
			break;
		aa[k] = MP(c, num);
	}
}

P* query(int s, int e, int k, int l, int r, P aa[])
{
	if (r <= s || l >= e) return NULL;
	if (r <= e && s <= l) 
	{
		return aa + k;
	}
	else
	{
		P* vl = query(s, e, k * 2 + 1, l, (l + r) / 2, aa);
		P* vr = query(s, e, k * 2 + 2, (l + r) / 2, r, aa);
		if (vl == NULL)
		{
			if (vr == NULL)
			{
				return NULL;
			}
			else
			{
				return vr;
			}
		}
		if (vr == NULL)
		{
			return vl;
		}
		return *vl < *vr ? vl : vr;
	}
}
bool solve2(int s, int e)
{
	if (e - s <= 0)
	{
		return false;
	}
	if (s % 2) 
	{
		mia = query(s, e, 0, 0, n, seg2);
		if ((*mia).first == INF)
		{
			return false;
		}
		mib = query((*mia).second, e, 0, 0, n, seg1);
	}
	else
	{
	//	cout << endl << endl;
		//cout << s << " " << e << endl;
		mia = query(s , e, 0, 0, n, seg1);
		if ((*mia).first == INF)
		{
			return false;
		}
		mib = query((*mia).second, e, 0, 0, n, seg2);
	}
	divi2.push_back((*mia).second);
	divi2.push_back((*mib).second);
	return true;
}

void solve()
{
	sort(divi.begin(), divi.end());
	for (int i = 0; i < divi.size() - 1; i++)
	{
			if (solve2(divi[i] + 1, divi[i + 1])) 
			{
				pq.push(MP((*mia).first, (*mib).first));

			}
		}
	for (int i = 0; i < divi2.size(); i++)
	{
		divi.push_back(divi2[i]);
	}
	while (!(divi2.empty()))
	{
		divi2.pop_back();
	}
	if (pq.empty())
	{
		return;
	}
	cout << pq.top().first << " " << pq.top().second << " ";
	pq.pop();
	solve();
}

int main() 
{
	cin >> n;
	int nn = n;
	init(seg1, n);
	init(seg2, n);
	for (int i = 0; i < nn; i+=2)
	{
		cin >> a >> b;
		update(seg1, i, a, n);
		update(seg2, i + 1, b, n);
	}
	divi.push_back(-1);
	divi.push_back(n);
	solve();
	cout << endl;
}

