void add(int id, int l, int r, int loc, int data) {
  if (l == r) {
    seg[id].val[loc & 1] = data;
    seg[id].val[2] = data;
    return ;
  }
  int mid = (l + r) >> 1;
  if (loc <= mid) {
    add(id << 1, l, mid, loc, data);
  }
