template<class InputIt1, class InputIt2, class OutputIt>
OutputIt merged(InputIt1 first1, InputIt1 last1,
    InputIt2 first2, InputIt2 last2,
    OutputIt d_first)
{
    for (; first1 != last1; ++d_first) {
        if (first2 == last2) {
            return std::copy(first1, last1, d_first);
        }
        if (*first2 < *first1) {
            *d_first = *first2;
            ++first2;
        }
        else {
            *d_first = *first1;
            ++first1;
        }
    }
    return std::copy(first2, last2, d_first);
}

void sol(ll l, ll r, vector<pair<ll, ll>>& vec) {
    if (l == r - 2) {
        vec.push_back({ perm[l], perm[l + 1] });
        return;
    }
    int mid = (l + r) / 2;
    pair<ll, ll> mn = get(0, 0, n, l, r);
    if (l % 2 != 0) swap(mn.first, mn.second);
    pair<ll, ll> q2;
    ll vl1 = pos[mn.first], vl2 = pos[mn.second];
    q2 = get(0, 0, n, vl1, r);
    if (l % 2 != 0) swap(q2.first, q2.second);
    vl2 = pos[q2.second];
    vector<tuple<ll, ll, ll>> cur;
    vec.push_back({ mn.first + 1, mn.second + 1 });

    if (vl1 != l) {
        pair<ll, ll> q = get(0, 0, n, l, vl1);
        if (l % 2 != 0) swap(q.first, q.second);
        cur.push_back({ q.first, l, vl1 });
    }
    if (vl1 + 1 != vl2) {
        pair<ll, ll> q2 = get(0, 0, n, vl1 + 1, vl2);
        if ((vl1 + 1) % 2 != 0) swap(q2.first, q2.second);
        cur.push_back({ q2.first, vl1 + 1, vl2 });
    }
    if (vl2 != r - 1) {
        pair<ll, ll> q = get(0, 0, n, vl2 + 1, r);
        if ((vl2 + 1) % 2 != 0) swap(q.first, q.second);
        cur.push_back({ q.first, vl2 + 1, r });
    }

    sort(cur.begin(), cur.end());
    vector<pair<ll, ll>> nwe;
    for (auto c : cur) {
        vector<pair<ll, ll>> nw;
        sol(get<1>(c), get<2>(c), nw);
        ll i2 = 0;
        vector<pair<ll, ll>> upd;
        upd = nwe;
        nwe.clear();
        merged(upd.begin(), upd.end(), nw.begin(), nw.end(), std::back_inserter(nwe));
    }
    for (auto cur : nwe) vec.push_back(cur);
}

