    inline void modify(int k,int l,int r,int x)
    {
        if(l==r){ma[0][k]=ma[1][k]=1e9;return ;}
        reg int mid=(l+r)>>1;push_down(k);
        if(x<=mid)modify(ls,l,mid,x);
