struct SegmentTree{
    private:
        int n;
        vector<P> node; //セグ木の持つデータの型を入力
        P e = P(50000000,0); //単位元
    public:
        P F(P a,P b){
            if (a.first<=b.first) return a;
            else return b;
        }

        void init(vector<P> v) {
            int sz = v.size();
            n = 1; while(n < sz) n *= 2;
            node.resize(2*n-1, e);

            rep(i,sz) node[i+n-1] = v[i];
            per(i,n-1) node[i] = F(node[2*i+1], node[2*i+2]);

            //rep(i,2*n-1) cout << node[i] << endl;
        }

        void update(int x,P val){
            x += n-1;
            node[x] = val;
            while(x > 0) {
                x =(x-1)/2;
                node[x]=F(node[2*x+1],node[2*x+2]);
            }

        }

        P get(int a, int b, int k=0, int l=0, int r=-1) {
            if(r < 0) r = n;
            if(r <= a || b <= l) return e;
            if(a <= l && r <= b) return node[k];

            P vl = get(a, b, 2*k+1, l, (l+r)/2);
            P vr = get(a, b, 2*k+2, (l+r)/2, r);
            return F(vl, vr);
        }
};

int n;
vector<P> ps0,ps1;
int p;
priority_queue<PP,vector<PP>,greater<PP>> que={};
SegmentTree s0,s1; 
vector<int> ans;

void upd(){
    P seg = que.top().second, p = que.top().first;
    que.pop();
    int l = seg.first,r = seg.second, m = p.first, pos = p.second;
    if (pos%2==0) {
        P p_ = s1.get(pos+1,r);
        ans.push_back(m);ans.push_back(p_.first);
        if (l!=pos) que.push(PP(s0.get(l,pos),P(l,pos)));
        if (pos+1!=p_.second) que.push(PP(s1.get(pos+1,p_.second),P(pos+1,p_.second)));
        if (r!=p_.second+1) que.push(PP(s0.get(p.second+1,r),P(p.second+1,r)));
    }else{
        P p_ = s0.get(pos+1,r);
        ans.push_back(m);ans.push_back(p_.first);
        if (l!=pos) que.push(PP(s1.get(l,pos),P(l,pos)));
        if (pos+1!=p_.second) que.push(PP(s0.get(pos+1,p_.second),P(pos+1,p_.second)));
        if (r!=p_.second+1) que.push(PP(s1.get(p_.second+1,r),P(p_.second+1,r)));
    }
}


void solve(){
    cin >> n;
    rep(i,n){
       cin >> p;
       if (i%2==0){
           ps0.push_back(P(p,i));
           ps1.push_back(P(500000,0));
       }else{
           ps0.push_back(P(500000,0));
           ps1.push_back(P(p,i));
       }
       //cout << as[i] << endl;
    }
    s0.init(ps0); s1.init(ps1);
    que.push(PP(s0.get(0,n),P(0,n)));
    rep(i,n/2){
        upd();
    }

    rep(i,n){
        cout << ans[i] << " ";
    }

}



int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    solve();

}

