	return a[res]<a[res2]?res:res2;
}

forward_list<int> rec(int l, int r, int &sz){
	sz = 0;
	if(r-l<=0) return forward_list<int>();
	int x1 = query(l, r);
	int x2 = query(x1+1, r);
	forward_list<int> v[3];
	int s1, s2, s3;
	v[0] = rec(l, x1, s1);
	v[1] = rec(x1+1, x2, s2);
	v[2] = rec(x2+1, r, s3);
	sz = s1+s2+s3+2;
	if(s1<s3){
		v[0].swap(v[2]);
		swap(s1, s3);
	}
	if(s1<s2){
		v[0].swap(v[1]);
		swap(s1, s2);
	}
	forward_list<int>::iterator it[3] = {v[0].begin(), v[1].begin(), v[2].begin()};
	forward_list<int>::iterator it0 = v[0].before_begin();
	while(true){
		bool f = false;
