		rep(i, 3){
			if(it[i]!=v[i].end() && (t<0 || a[*it[i]]<a[*it[t]])) t = i;
		}
		if(t<0) break;
		if(t>0){
			v[0].insert_after(it0, *it[t]++);
			v[0].insert_after(it0, *it[t]++);
			++it[0];
			++it[0];
		} else {
			++it0;
			++it0;
			++it[0];
			++it[0];
		}
	}
	v[0].insert_after(v[0].before_begin(), x2);
	v[0].insert_after(v[0].before_begin(), x1);
	return v[0];
}

