map<vector<int>, vector<int> > cache;

vector<int> solve(vector<int> p){
	if(p.size()==0) return p;
	if(cache.find(p)!=cache.end()){
		return cache[p];
	}
	vector<int> mini=p;
	for(int i=0;i<p.size()-1;i++){
		int a=p[i],b=p[i+1];
		vector<int> p1=p;
		p1.erase(p1.begin()+i);
		p1.erase(p1.begin()+i);
		vector<int> ans=solve(p1);
		ans.push_back(a);
		ans.push_back(b);
		if(lexicographical_compare (
			ans.begin(), ans.end(),
			mini.begin(), mini.end()
		)){
			mini=ans;
		}
	}
	cache[p]=mini;
	return mini;
}

