struct Node{
	int data, ind;

	Node(int data, int ind) : data(data), ind(ind) {}
	Node operator*(const Node r){return data < r.data ? *this : r;}
} e(INF, INF);

struct SegmentTree{
	vector<Node> seg;
	int sz = 1;

	SegmentTree(int n){
		while(sz < n) sz *= 2;
		seg.assign(sz * 2, e);
	}

	void update(int k, int x){
		k += sz - 1;
		seg[k] = Node(x, k - (sz - 1));
		while(k){
			k = (k - 1) / 2;
			seg[k] = seg[2 * k + 1] * seg[2 * k + 2];
		}
	}

	Node get(int a, int b){
		return get(a, b, 0, 0, sz);
	}

	Node get(int a, int b, int k, int l, int r){
		if(b<=l||r<=a) return e;
		if(a<=l&&r<=b) return seg[k];

		return get(a, b, 2 * k + 1, l, (l + r) / 2) * get(a, b, 2 * k + 2, (l + r) / 2, r);
	}
};

