        int n;
        in>>n;
        vector<int> O(n/2),E(n/2),f(n+1);
        fr(i,n/2) in>>O[i]>>E[i],f[O[i]]=f[E[i]]=i;
        SegMIN<int> o(O,INT_MAX),e(E,INT_MAX);
        using P=tuple<int,int,int,int,bool>;
        priority_queue<P,vector<P>,greater<P>> pq;
        int a=o.mn(0,n/2),b=e.mn(f[a],n/2);
        pq.emplace(a,b,0,n/2,false);
        bool g;
        int s,t,l,r;
        vector<int> ans;
        while(!pq.empty()){
            tie(a,b,s,t,g)=pq.top();pq.pop();
            ans.emplace_back(a);ans.emplace_back(b);
            l=f[a],r=f[b];
            if(g){
                if(s!=l){
                    a=e.mn(s,l);
                    if(a>n) return;
                    pq.emplace(a,o.mn(f[a]+1,l+1),s,l,true);
                }
                if(l+1!=r){
                    a=o.mn(l+1,r);
                    if(a>n) return;
                    pq.emplace(a,e.mn(f[a],r),l+1,r,false);
                }
                if(r!=t){
                    a=e.mn(r,t);
                    if(a>n) return;
                    pq.emplace(a,o.mn(f[a]+1,r+1),r,t,true);
                }
            }
            else{
                if(s!=l){
                    a=o.mn(s,l);
                    if(a>n) return;
                    pq.emplace(a,e.mn(f[a],l),s,l,false);
                }
                if(l!=r){
                    a=e.mn(l,r);
                    if(a>n) return;
                    pq.emplace(a,o.mn(f[a]+1,r+1),l,r,true);
                }
                if(r+1!=t){
                    a=o.mn(r+1,t);
                    if(a>n) return;
                    pq.emplace(a,e.mn(f[a],t),r+1,t,false);
                }
            }
        }
        for(auto i:ans) out<<i<<" ";
        out<<endl;
    }
};

