            ans.pb(b[ok]);
        for(int j = 0; j < g[ok].size(); j++)
            st.insert(mk(a[b[g[ok][j]].fr], g[ok][j]));
    }
    for(int i = 0; i < sz(ans); i++)
        cout << a[ans[i].fr] << " " << a[ans[i].sc] << " ";
}


