//SegmentTree(セグ木)
template <class T>
class SegmentTree {
private:
	T init_val;
	std::vector<T> ary;
	std::function<T(T, T)> func;
public:
	// 使用例(データの大きさNとする)
	// SegmentTree<T> st(N,  INF, [](T l, T r){return std::min(l, r);}); 最小値
	// SegmentTree<T> st(N, -INF, [](T l, T r){return std::max(l, r);}); 最大値
	// SegmentTree<T> st(N,    0, [](T l, T r){return l+r;});            合計
	SegmentTree(int n, T val, std::function<T(T, T)> f) : init_val(val), func(f) {
		ary.resize(static_cast<int>(std::pow(2, std::ceil(std::log(n) / std::log(2)) + 1) - 1), val);
	}
	void init(int n, T val, std::function<T(T, T)> f) {
		ary.resize(static_cast<int>(std::pow(2, std::ceil(1.0*std::log(n) / std::log(2)) + 1) - 1), val);
		init_val = val;
		func = f;
	}
	void update(int i, T val) {
		i += ary.size() / 2;
		ary[i] = val;
		while (i > 0) {
			i = (i - 1) / 2;
			ary[i] = func(ary[2 * i + 1], ary[2 * i + 2]);
		}
	}
	// 区間[a, b)のfuncの返す値を返す (query_(a, b, 0, 0, n)と呼び出す)
	T query_(int a, int b, int i, int l, int r) {
		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return ary[i];
		else {
			T vl = query_(a, b, 2 * i + 1, l, (l + r) / 2);
			T vr = query_(a, b, 2 * i + 2, (l + r) / 2, r);
			return func(vl, vr);
		}
	}
	// 上限(b)は少し大きめに取るべし
	T query(int a, int b) {
		return query_(a, b, 0, 0, ary.size() / 2 + 1);
	}
};

SegmentTree<int> odd(1, 0, [](int l, int r) {return std::min(l, r); }), even(1, 0, [](int l, int r) {return std::min(l, r); });
std::vector<int> inv;

std::deque<PAIR> calc(int l, int r) {
	std::deque<PAIR> res;
	if (l >= r) return res;

	int minL, minR;
	int posL, posR;
	if (l % 2 == 0) {
		minL = odd.query(l, r + 1);
		posL = inv[minL];
		minR = even.query(posL + 1, r + 1);
		posR = inv[minR];
	}
	else {
		minL = even.query(l, r + 1);
		posL = inv[minL];
		minR = odd.query(posL + 1, r + 1);
		posR = inv[minR];
	}
	std::vector<std::deque<PAIR>> vec;
	vec.emplace_back(calc(l, posL - 1));
	vec.emplace_back(calc(posL + 1, posR - 1));
	vec.emplace_back(calc(posR + 1, r));
	{
		while (true) {
			PAIR max(-INFINT, -INFINT);
			int pos = -1;
			REP(i, 3) {
				if (vec[i].empty()) continue;
				if (max < vec[i].back()) {
					max = vec[i].back();
					pos = i;
				}
			}
			if (pos == -1) break;
			res.push_front(max);
			vec[pos].pop_back();
		}
	}
	res.push_front(PAIR(minL, minR));
	return res;
}

signed main() {
	INIT;
	VAR(int, n);
	VEC(int, p, n);
	REP(i, n) --p[i];

	odd.init(n, INFINT, [](int l, int r) {return std::min(l, r); });
	even.init(n, INFINT, [](int l, int r) {return std::min(l, r); });
	REP(i, n) {
		if (i % 2 == 0) {
			odd.update(i, p[i]);
		}
		else {
			even.update(i, p[i]);
		}
	}

	inv.resize(n);
	REP(i, n) {
		inv[p[i]] = i;
	}

	auto ans(calc(0, n - 1));
	while (!ans.empty()) {
		auto now(ans.front()); ans.pop_front();
		OUT(now.first + 1)SP OUT(now.second + 1)SP;
	}BR;
	return 0;
}

