#include <bits/stdc++.h>
using namespace std;

// 0-indexed
template <class T>
struct SegmentTree {
  // a,b,c: T, e:T(unit)
  // abc = (ab)c = a(bc)
  // ae = ea = a
  typedef function<T(T, T)> F;
  int n;
  F f;
  T unit;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(int newn, F f, T t) : f(f), unit(t) { init(newn); }
  SegmentTree(const vector<T> &v, F f, T t) : f(f), unit(t) {
    int _n = v.size();
    init(v.size());
    for (int i = 0; i < _n; ++i) dat[n + i] = v[i];
    for (int i = n - 1; i; --i) dat[i] = f(dat[i << 1], dat[(i << 1) | 1]);
  }
  void init(int newn) {
    n = 1;
    while (n < newn) n <<= 1;
    dat.assign(n << 1, unit);
  }

  // "go up" process
  void update(int k, T newdata) {
    dat[k += n] = newdata;
    while (k >>= 1) {
      dat[k] = f(dat[(k << 1) | 0], dat[(k << 1) | 1]);
    }
  }
  // [a,b)
  T query(int a, int b) {
    T vl = unit, vr = unit;
    for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) vl = f(vl, dat[l++]);
      if (r & 1) vr = f(dat[--r], vr);
    }
    return f(vl, vr);
  }
};

using P = pair<int, int>;
int n;
vector<int> p;
SegmentTree<P> odd, ev;
vector<vector<int>> memo;
vector<P> res, v;

int solve(int l, int r);

int main() {
  cin >> n;
  p.resize(n);
  memo.assign(n, vector<int>(3, -1));
  for (int &x : p) cin >> x;
  {
    auto f = [](P l, P r) { return min(l, r); };
    odd = SegmentTree<P>(n / 2, f, P(2 * n, 2 * n));
    ev = SegmentTree<P>(n / 2, f, P(2 * n, 2 * n));
    for (int i = 0; i < n / 2; ++i) {
      ev.update(i, P(p[2 * i], 2 * i));
      odd.update(i, P(p[2 * i + 1], 2 * i + 1));
    }
  }
  {
    auto f = [](int l, int r) { return v[l] > v[r]; };
    priority_queue<int, vector<int>, decltype(f)> pq(f);
    pq.push(solve(0, n));
    assert(v.size() == n / 2);
    while (pq.size()) {
      int now = pq.top();
      pq.pop();
      res.push_back(v[now]);
      for (int i = 0; i < 3; ++i)
        if (memo[now][i] >= 0) pq.push(memo[now][i]);
    }
  }
  for (int i = 0; i < n / 2; ++i)
    cout << res[i].first << " " << res[i].second << " \n"[i == n / 2 - 1];
  return 0;
}

int solve(int l, int r) {
  if (l >= r) return -1;
  int lid, rid;
  P now;
  if (l & 1) {
    P op = odd.query(l >> 1, r >> 1);
    lid = op.second;
    P ep = ev.query((lid + 1) >> 1, (r + 1) >> 1);
    rid = ep.second;
    now = P(op.first, ep.first);
  } else {
    P ep = ev.query((l + 1) >> 1, (r + 1) >> 1);
    lid = ep.second;
    P op = odd.query(lid >> 1, r >> 1);
    rid = op.second;
    now = P(ep.first, op.first);
  }
  int num = v.size();
  v.emplace_back(now);
  memo[num][0] = solve(l, lid);
  memo[num][1] = solve(lid + 1, rid);
  memo[num][2] = solve(rid + 1, r);
  return num;
}

