typedef pair<int,int> pii;

const int MX = 1<<20;

struct Tree{
	pii t[MX*2];
	pii find(int s, int e){
		s += MX, e += MX;
		pii r = pii(1e9, -1);
		while(s <= e){
			if( s&1 ) r = min(r, t[s++]);
			if(~e&1 ) r = min(r, t[e--]);
			s /= 2, e /= 2;
		}
		return r;
	}
	void update(int x, int v){
		x += MX; t[x] = pii(v, x-MX);
		while(x > 1) x /= 2, t[x] = min(t[x*2], t[x*2+1]);
	}
} t[2];

int D[MX];

void solve(int s, int e, vector<int> &A)
{
	if( s > e ) return;
	pii p = t[s%2].find(s, e);
	pii q = t[~s&1].find(p.second+1, e);
	if( q.second < 0 ) return;

	vector<int> t[3];
	solve(s, p.second-1, t[0]);
	solve(p.second+1, q.second-1, t[1]);
	solve(q.second+1, e, t[2]);

	A.push_back(p.first);
	A.push_back(q.first);
	for(int i = 0; i < 3; i++) reverse(t[i].begin(), t[i].end());
	while(1){
		int x = 0;
		if( t[0].size() && (t[1].empty() || t[1].back() > t[0].back()) && (t[2].empty() || t[2].back() > t[0].back())) x = 0;
		else if( t[1].size() && (t[2].empty() || t[2].back() > t[1].back())) x = 1;
		else if( t[2].size() ) x = 2;
		else break;
		for(int u = 0; u < 2; u++) A.push_back(t[x].back()), t[x].pop_back();
	}
}

