        qujian x;
        x.l=1;
        x.r=n;
        x.vl=query(1,n,1,n,1,1);
        x.vr=query(head[x.vl]+1,n,1,n,1,0);
        priority_queue<qujian>q;
        q.push(x);
        int l,r,vl,vr;
        for(int i=1;i<=n/2;i++)
        {
            x=q.top();
            q.pop();
            l=x.l;
            r=x.r;
            vl=x.vl;
            vr=x.vr;
            ans[s++]=vl;
            ans[s++]=vr;
            if(l<head[vl]-1)
            {
                x.l=l;
                x.r=vl-1;
                x.vl=query(x.l,x.r,1,n,1,x.l&1);
                x.vr=query(head[x.vl]+1,x.r,1,n,1,x.r&1);
