#define N 200050
#define INF 1000000007
int a[N];

int mn[2][N*8],pos[2][N*8];

#define ls p<<1
#define rs (p<<1)|1
void setTree(int p,int l,int r)
{
	if(l==r)
	{
		for(int i=0;i<2;i++)
			mn[i][p]=INF,pos[i][p]=l;
		(l&1)? mn[1][p]=a[l]: mn[0][p]=a[l];
		return;
	}
	int mid=(l+r)>>1;
	setTree(ls,l,mid);
	setTree(rs,mid+1,r);
	for(int i=0;i<2;i++)
	{
		int tmp= mn[i][ls]<mn[i][rs]? ls: rs;
		mn[i][p]=mn[i][tmp],pos[i][p]=pos[i][tmp];
	}
}

int query(int p,int l,int r,int gl,int gr,int tp)
{
	if(l==gl && r==gr)
	{
		if(l==r)
			return (l&1)==tp? l: -1;
		else
			return pos[tp][p];
	}
	int mid=(l+r)>>1;
	if(gr<=mid) return query(ls,l,mid,gl,gr,tp);
	else if(gl>mid) return query(rs,mid+1,r,gl,gr,tp);
	else
	{
		int tl=query(ls,l,mid,gl,mid,tp);
		int tr=query(rs,mid+1,r,mid+1,gr,tp);
		if(tl==-1) return tr;
		else if(tr==-1) return tl;
		else return a[tl]<a[tr]? tl: tr;
	}
}

