template <typename T>
struct segtree {
    int N;
    vector<T> t;
    T zero;
    function<T(T, T)> f;

    segtree() {}
    void init(int n, T _zero, function<T(T, T)> _f) {
        f = _f;
        zero = _zero;
        N = 1;
        while (N < n) N <<= 1;
        t.assign(2 * N, zero);
    }
    segtree(int n, T _zero, function<T(T, T)> _f) {
        init(n, _zero, _f);
    }
    segtree(vector<T> &a, T _zero, function<T(T, T)> _f) {
        int n = a.size();
        init(n, _zero, _f);

        for (int i = 0; i < n; i++) t[N + i] = a[i];
        for (int i = N - 1; i > 0; i--) {
            t[i] = f(t[i * 2], t[i * 2 + 1]);
        }
    }

    T get(int l, int r) {
        T res = zero;
        l += N;
        r += N;
        while (l <= r) {
            if (l % 2 == 1) res = f(res, t[l]);
            if (r % 2 == 0) res = f(res, t[r]);
            l = (l + 1) >> 1;
            r = (r - 1) >> 1;
        }
        return res;
    }

    void upd(int x, T y) {
        x += N;
        t[x] = y;
        while (x > 1) {
            x >>= 1;
            t[x] = f(t[x * 2], t[x * 2 + 1]);
        }
    }
};

vector<int> solve(vector<int> a) {
    int n = a.size();

    vector<int> pos(n);
    for (int i = 0; i < n; i++) pos[a[i]] = i;

    vector<segtree<pair<int, int> > > tt(2);
    vector<vector<pair<int, int> > > vv(2);
    for (int i = 0; i < n; i++) {
        vv[i % 2].push_back({a[i], i});
        vv[(i % 2) ^ 1].push_back({INF, -1});
    }
    for (int i = 0; i < 2; i++) {
        tt[i] = segtree<pair<int, int> >(vv[i], {INF, -1}, [&](const pair<int, int> &x, const pair<int, int> &y) {
            return min(x, y);
        });
    }

    set<pair<int, int> > st;
    set<pair<int, int> > cands;
    auto add = [&](int l, int r) {
        assert(l % 2 != r % 2);
        if (l > r) return;
        st.insert({l, r});
        cands.insert(tt[l % 2].get(l, r));
    };
    add(0, n - 1);

    vector<int> ans;
    while (!cands.empty()) {
    ///for (int i = 0; i < n; i++) {
        //if (used[i]) continue;
        //int x = pos[i];
        int i = cands.begin()->first;
        int x = cands.begin()->second;
        cands.erase(cands.begin());
        auto it = st.lower_bound(make_pair(x + 1, -1));
        it--;
        auto o = *it;
        st.erase(it);

        assert(o.first <= x && x <= o.second);
        assert(o.second != x);
        assert(o.first % 2 == x % 2);

        int y = tt[(x % 2) ^ 1].get(x, o.second).second;
        ans.push_back(a[x]);
        ans.push_back(a[y]);
        add(o.first, x - 1);
        add(x + 1, y - 1);
        add(y + 1, o.second);
    }
    return ans;
}

