struct RangeMinQuery{
  ll dat[(1<<19)-1];
  ll idx[(1<<19)-1];
  int size,n;

  void init(int n_){
    n=n_;
    size=1;
    while(size<n) size*=2;
    for(int i=0;i<n+1;i++) dat[i]=INF;
    for(int i=0;i<2*size-1;i++) idx[i]=n;
  }

  void update(int k,ll a){
    dat[k]=a;
    k+=size-1;
    idx[k]=k-(size-1);
    while(k>0){
      k=(k-1)/2;
      if(dat[idx[k*2+1]]<dat[idx[k*2+2]])idx[k]=idx[k*2+1];
      else idx[k]=idx[k*2+2];
    }
  }

  ll subquery(int a,int b,int k,int l,int r){
    if(r<=a||b<=l)return n;
    if(a<=l&&r<=b)return idx[k];
    else{
      ll il=subquery(a,b,k*2+1,l,(l+r)/2),ir=subquery(a,b,k*2+2,(l+r)/2,r);
      if(dat[il]<dat[ir])return il;
      else return ir;
    }
  }

  ll query(int a,int b){
    return subquery(a,b,0,0,size);
  }
};


