            if(r < 0) r = n;
            if(r <= a || b <= l) return e;
            if(a <= l && r <= b) return node[k];

            P vl = get(a, b, 2*k+1, l, (l+r)/2);
            P vr = get(a, b, 2*k+2, (l+r)/2, r);
            return F(vl, vr);
        }
};

