	}
	nn(int a, int i) {
		mn = mx = a;
		imn = imx = i;
	}
};

nn combine(nn a, nn b) {
	if (a.mn == -1) 
		a.mn = 1e9, a.imn = 1e9;
	if (b.mn == -1) 
		b.mn = 1e9, b.imn = 1e9;
	if (a.mx == -1) 
		a.mx = -1e9, a.imx = -1e9;
	if (b.mx == -1) 
		b.mx = -1e9, b.imx = -1e9;

	nn res = a;
	if (a.mn > b.mn)
		res.mn = b.mn, res.imn = b.imn;
	if (a.mx < b.mx)
		res.mx = b.mx, res.imx = b.imx;
	return res;
}

nn t[N * 4];

void update(int v, int tl, int tr, int p, int val) {
	if (tl == tr) {
		t[v] = nn(val, p);
	}
	else {
		int tm = (tl + tr) >> 1;
		if (tm >= p)
			update(v * 2, tl, tm, p, val);
		else update(v * 2 + 1, tm + 1, tr, p, val);
		t[v] = combine(t[v * 2], t[v * 2 + 1]);
	}
}

nn get(int v, int tl, int tr, int l, int r) {
	if (tl > r || tr < l) return nn();
	if (l <= tl && tr <= r) return t[v];
	int tm = (tl + tr) >> 1;
	return combine(
		get(v * 2, tl, tm, l, r),
		get(v * 2 + 1, tm + 1, tr, l, r)
	);
}

