			if(pp1&&pp2) q.push(node(t.p1+1,t.p2-1,pp1,pp2));
		}
		if(t.p2+1<=t.r) {
			int pp1=0,pp2=0,z=(t.p2+1)%2;
			pp1=ask(z,t.p2+1,t.r);
			if(pp1) pp2=ask(1-z,pp1+1,t.r);
			if(pp1&&pp2) q.push(node(t.p2+1,t.r,pp1,pp2)); 
		}
	}
	cout<<endl;
	return 0;
}

