struct Min {
  using T = pair<int, int>;
  T operator()(const T a, const T b) {
    return min(a, b);
  }
};
template <class M>
class SparseTable {
  using V = typename M::T;
  M calc;

 public:
  SparseTable() = default;
  //SparseTable &operator=(const SparseTable &) = default;
  SparseTable(vector<V> &v) : n(v.size()), lg2(n + 1) {
    for (int i = 2; i <= n; ++i) {
      lg2[i] = lg2[i >> 1] + 1;
    }
    data = vector<vector<V>>(lg2[n] + 1, vector<V>(n));
    data[0] = v;
    for (int i = 1; i < data.size(); ++i) {
      for (int j = 0; j <= n - (1 << i); ++j) {
        data[i][j] = calc(data[i - 1][j], data[i - 1][j + (1 << (i - 1))]);
      }
    }
    DBG(data)
  };

 private:
  size_t n;
  vector<size_t> lg2;
  vector<vector<V>> data;

 public:
  size_t size() { return n; }
  V query(int l, int r) {
    int len = r - l;
    int lg = lg2[len];
    return calc(data[lg][l], data[lg][r - (1 << lg)]);
  }
};
struct P {
  int a, b, p, q, l, r;
  bool operator<(const P &rhs) const {
    return a > rhs.a or (a == rhs.a and b > rhs.b);
  }
};
class Solver {
 public:
