    }
    priority_queue<P> pq;
    vector<int> ans;
    {
      auto mini = st[0].query(0, n);
      auto min2 = st[1].query((mini.second + 1), n);
      pq.push(P{mini.first, min2.first, mini.second, min2.second, 0, n});
