		sval = oddsg.get(fpos + 1, tail);
		spos = p[sval];
	}else{
		fval = oddsg.get(head, tail);
		fpos = p[fval];
		sval = evensg.get(fpos + 1, tail);
		spos = p[sval];
	}

	//cout << "head tail = " << head << " - " << tail << endl;
	//cout << "fpos = " << fpos << "fval = " << fval << endl;
	//cout << "spos = " << spos << "sval = " << sval << endl;

	deque<long long> ff;
	deque<long long> ss;
	deque<long long> tt;
	ff = dfs(head, fpos, oddsg, evensg);
	ss = dfs(fpos+1, spos, oddsg, evensg);
	tt = dfs(spos+1, tail, oddsg, evensg);

	//merge
	while(ff.size() != 0 || ss.size() != 0 || tt.size() != 0){
		long long mini = INT_MAX;
		int who = -1;
		if(ff.size() > 0 && ff[0] < mini){
			who = 1;
			mini = ff[0];
		}

		if(ss.size() > 0 && ss[0] < mini){
			who = 2;
			mini = ss[0];
		}

		if(tt.size() > 0 && tt[0] < mini){
			who = 3;
			mini = tt[0];
		}
		long long f;
		long long s;
		if(who == 1){
			f = ff[0];
			ff.pop_front();
			s = ff[0];
			ff.pop_front();
		}else if(who == 2){
			f = ss[0];
			ss.pop_front();
			s = ss[0];
			ss.pop_front();
		}else{
			f = tt[0];
			tt.pop_front();
			s = tt[0];
			tt.pop_front();
		}
		//cout << "who = " << who << endl;
		//cout << "push front" << f << " " << s << endl;
		ret.push_back(f);
		ret.push_back(s);
	}

	ret.push_front(sval);
	ret.push_front(fval);
	return ret;
}

