struct SegmentTree{
    private:
        int n;
        vector<P> node; //セグ木の持つデータの型を入力
        P e = P(50000000,0); //単位元
    public:
        P F(P a,P b){
            if (a.first<=b.first) return a;
            else return b;
        }

        void init(vector<P> v) {
            int sz = v.size();
            n = 1; while(n < sz) n *= 2;
            node.resize(2*n-1, e);

            rep(i,sz) node[i+n-1] = v[i];
            per(i,n-1) node[i] = F(node[2*i+1], node[2*i+2]);

            //rep(i,2*n-1) cout << node[i] << endl;
        }

        void update(int x,P val){
            x += n-1;
            node[x] = val;
            while(x > 0) {
                x =(x-1)/2;
                node[x]=F(node[2*x+1],node[2*x+2]);
            }

        }

        P get(int a, int b, int k=0, int l=0, int r=-1) {
            if(r < 0) r = n;
            if(r <= a || b <= l) return e;
            if(a <= l && r <= b) return node[k];

            P vl = get(a, b, 2*k+1, l, (l+r)/2);
            P vr = get(a, b, 2*k+2, (l+r)/2, r);
            return F(vl, vr);
        }
};

