struct SEG{
	int mi[1000100][2];
	void build(int rt,int l,int r)
	{
		if(l==r)
		{
			mi[rt][0]=mi[rt][1]=inf;
			mi[rt][l&1]=nu[l];
			return;
		}
		int mid=(l+r)/2;
		build(rt*2,l,mid);
		build(rt*2+1,mid+1,r);
		mi[rt][0]=min(mi[rt*2][0],mi[rt*2+1][0]);
		mi[rt][1]=min(mi[rt*2][1],mi[rt*2+1][1]);
	}
	int ask(int rt,int l,int r,int st,int ed,int sym)
	{
		if(l>ed||r<st)return inf;
		if(l>=st&&r<=ed)return mi[rt][sym];
		int mid=(l+r)/2;
		return min(ask(rt*2,l,mid,st,ed,sym),
					ask(rt*2+1,mid+1,r,st,ed,sym));
	}
}seg;

struct Sta{
	int l,r,mi;
	bool operator >(const Sta &o)const{
		return mi>o.mi;
	}
};

