{
	q.push((Sta){1,n,seg.ask(1,1,n,1,n,1)});
	int l,r;
	Sta cur;
	while(!q.empty())
	{
		cur=q.top();q.pop();
		l=pos[cur.mi];
		r=pos[seg.ask(1,1,n,l+1,cur.r,(l+1)&1)];
		ans[++top]=nu[l];ans[++top]=nu[r];
		if(cur.l<=l-1)ins(cur.l,l-1);
		if(l+1<=r-1)ins(l+1,r-1);
		if(r+1<=cur.r)ins(r+1,cur.r);
	}
}
