class SegTree {
private:
	int t[N << 2][2];
	void build(int l, int r, int x) {
		if (l == r) {
			t[x][0] = inf, t[x][1] = inf;
			t[x][l & 1] = p[l];
			return;
		}
		int m = (l + r) >> 1;
		build(l, m, x << 1), build(m + 1, r, x << 1 | 1);
		t[x][0] = min(t[x << 1][0], t[x << 1 | 1][0]);
		t[x][1] = min(t[x << 1][1], t[x << 1 | 1][1]);
	}
	int getMin(int l, int r, int s, int e, int x, int parity) {
		if (l > r || l > e || r < s) return inf;
		if (s <= l && r <= e) return t[x][parity];
		int m = (l + r) >> 1;
		return min(getMin(l, m, s, e, x << 1, parity), getMin(m + 1, r, s, e, x << 1 | 1, parity));
	}
public:
	int n;
	void init(int _n) { n = _n; build(0, n - 1, 1); }
	int getMin(int l, int r, int parity) { return getMin(0, n - 1, l, r, 1, parity); }
