class Union_find{
private:
	vector<int> par;
	vector<int> rank;
	int n;

public:
	Union_find(int a){
		n = a;
		for(int i = 0;i < n;i++){
			par.push_back(i);
			rank.push_back(0);
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}else{
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

class LazySegTree{
private:
	int n;
	vector<pair<ll, ll> > node, node2[2];
	vector<bool> lazyFlag;
public:
	LazySegTree(){}
	LazySegTree(vector<ll> v){
		int sz = v.size();
		n = 1; while(n < sz) n *= 2;
		node.resize(2*n-1, {INF_LL, INF_LL});
		REP(i, 2)
			node2[i].resize(2*n-1, {INF_LL, INF_LL});
		lazyFlag.resize(2*n-1, false);
		REP(i, sz) node[i+n-1] = {v[i], i};
		REP(i, 2)
			REP(j, sz){
				if(j % 2 == i){
					node2[i][j+n-1] = {v[j], j};
				}else{
					node2[i][j+n-1] = {INF_LL, INF_LL};
				}
			}
		for(int i = n-2;i >= 0;i--) node[i] = min(node[2*i+1],node[2*i+2]);
		REP(j, 2)
			for(int i = n-2;i >= 0;i--) node2[j][i] = min(node2[j][2*i+1],node2[j][2*i+2]);

	}


	/*
	void add(int a, int b, ll x, int k=0, int l=0, int r=-1){
		if(r < 0) r = n;
		eval(k, l, r);
		if(b <= l || r <= a) return;

		if(a <= l && r <= b){
			lazy[k] += x;
			lazyFlag[k] = true;
			eval(k, l, r);
		}else{
			add(a, b, x, k*2+1, l, (l+r)/2);
			add(a, b, x, k*2+2, (l+r)/2, r);
			node[k] = node[k*2+1] + node[k*2+2];
		}
	}
	*/

	void update(int k, ll x){
		ll v = k+n-1;
		node[v] = {x, k};
		node2[0][v] = {x, k};
		node2[1][v] = {x, k};
		while(v > 0){
			v = (v-1)/2;
			node[v] = min(node[v*2+1], node[v*2+2]);
			node2[0][v] = min(node2[0][v*2+1], node2[0][v*2+2]);
			node2[1][v] = min(node2[1][v*2+1], node2[1][v*2+2]);
		}
	}

	pair<ll, ll> query(int a, int b, int k=0, int l=0, int r=-1){
		if(r < 0) r = n;

		if(b <= l || r <= a) return {INF_LL, INF_LL};
		if(a <= l && r <= b) return node[k];

		return min(query(a, b, k*2+1, l, (l+r)/2), query(a, b, k*2+2, (l+r)/2, r));
	}

	pair<ll, ll> query2(int a, int b, int type, int k = 0, int l = 0, int r = -1){
		if(r < 0) r = n;
		if(b <= l || r <= a) return {INF_LL, INF_LL};
		if(a <= l && r <= b) return node2[type][k];

		return min(query2(a, b, type, k*2+1, l, (l+r)/2), query2(a, b, type, k*2+2, (l+r)/2, r));
	}
};

