struct Segtree
{
	int a[MAX_N], t[MAX_N], n;

	inline int choose(int lhs, int rhs)
	{
		return (a[lhs] < a[rhs] ? lhs : rhs);
	}

	inline void init(int _n)
	{
		n = _n;

		for(int i = 0; i < n; ++i)
			t[i + n] = i;

		for(int i = n - 1; i > 0; --i)
			t[i] = choose(t[2 * i], t[2 * i + 1]);
	}

	inline pii extract(int l, int r)
	{
#ifdef __LOCAL
		assert(l <= r);
#endif

		int pos = l;

		l += n;
		r += n + 1;

		while(l < r)
		{
			if(l & 1)
				pos = choose(pos, t[l++]);

			if(r & 1)
				pos = choose(pos, t[--r]);

			l /= 2;
			r /= 2;
		}

		pii answ = {pos, a[pos]};
		a[pos] = INT_INF;
		pos += n;

		for(; pos > 0; pos /= 2)
			t[pos / 2] = choose(t[pos], t[pos ^ 1]);

		return answ;
	}
};

Segtree even, odd;
int n;

template<typename T>
vector<T> merge(const vector<T>& lhs, const vector<T>& rhs)
{
	vector<T> answ;

	int i = 0, j = 0;

	while(i < len(lhs) && j < len(rhs))
	{
		if(lhs[i] < rhs[j])
			answ.push_back(lhs[i++]);
		else
			answ.push_back(rhs[j++]);
	}

	while(i < len(lhs))
		answ.push_back(lhs[i++]);

	while(j < len(rhs))
		answ.push_back(rhs[j++]);

	return answ;
}

inline int firsteven(int l, int r)
{
	l += (l & 1);

	return l / 2;
}

inline int lasteven(int l, int r)
{
	r -= (r & 1);

	return r / 2;
}

inline int firstodd(int l, int r)
{
	l += 1 - (l & 1);

	return l / 2;
}

inline int lastodd(int l, int r)
{
	r -= 1 - (r & 1);

	return r / 2;
}

vector<pii> build(int l, int r)
{
	vector<pii> answ;

	if(r < l)
		return answ;

	DBG(make_pair(l, r));

	int subl = NIL, subr = NIL;

	if(l & 1)
	{
		auto pr1 = odd.extract(firstodd(l, r), lastodd(l, r));
		subl = 2 * pr1.first + 1;

		auto pr2 = even.extract(firsteven(subl, r), lasteven(subl, r));
		answ.emplace_back(pr1.second, pr2.second);

		subr = 2 * pr2.first;
	}
	else
	{
		auto pr1 = even.extract(firsteven(l, r), lasteven(l, r));
		subl = 2 * pr1.first;

		auto pr2 = odd.extract(firstodd(subl, r), lastodd(subl, r));
		answ.emplace_back(pr1.second, pr2.second);

		subr = 2 * pr2.first + 1;
	}

	vector<pii> append;

	append = merge(append, build(l, subl - 1));
	append = merge(append, build(subl + 1, subr - 1));
	append = merge(append, build(subr + 1, r));

	for(auto& x: append)
		answ.push_back(x);

	return answ;
}

void solve()
{
	cin >> n;

	for(int i = 0; i < n; ++i)
