void update(int p,int p2,int s,int e,int idx,int val){
  if(idx<s||e<idx)return;
  if(idx==s&&s==e){
    tree[p][p2]=val;
    return;
  }
  update(p*2,p2,s,(s+e)/2,idx,val);
  update(p*2+1,p2,(s+e)/2+1,e,idx,val);
  tree[p][p2]=min(tree[p*2][p2],tree[p*2+1][p2]);
}
