void push_up(int k)
{
    t[k]=min(t[k*2],t[k*2+1]);
    od[k]=min(od[k*2],od[k*2+1]);
    ev[k]=min(ev[k*2],ev[k*2+1]);
}
void build(int k,int l,int r)
{
    if(l==r)
    {
        t[k]=a[l];
        od[k]=ev[k]=inf;
        if(l%2==0)  ev[k]=min(ev[k],a[l]);
        else  od[k]=min(od[k],a[l]);
        return;
    }
    int mid=(l+r)/2;
    build(k*2,l,mid);
    build(k*2+1,mid+1,r);
    push_up(k);
}
int query(int k,int l,int r,int x,int y,int book)
{
    if(l>=x&&r<=y)
    {
        if(book==0)  return ev[k];
        if(book==1)  return od[k];
        return t[k];
    }
    int mid=(l+r)/2;
    int res=inf;
    if(mid>=x)  res=min(res,query(k*2,l,mid,x,y,book));
    if(mid<y)   res=min(res,query(k*2+1,mid+1,r,x,y,book));
    return res;
}
