#include<bits/stdc++.h>

using namespace std;

const int INF = 1 << 30;


template< typename T >
struct SegmentTree
{
  vector< T > seg;
  int sz;

  SegmentTree(int n)
  {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz - 1, INF);
  }

  T merge(T a, T b)
  {
    return (min(a, b));
  }

  void set(int k, int x)
  {
    seg[k + sz - 1] = x;
  }

  void build()
  {
    for(int k = sz - 2; k >= 0; k--) {
      seg[k] = merge(seg[2 * k + 1], seg[2 * k + 2]);
    }
  }

  T rmq(int a, int b, int k, int l, int r)
  {
    if(a >= r || b <= l) return (INF);
    if(a <= l && r <= b) return (seg[k]);
    return (merge(rmq(a, b, 2 * k + 1, l, (l + r) >> 1),
                  rmq(a, b, 2 * k + 2, (l + r) >> 1, r)));
  }

  T rmq(int a, int b)
  {
    return (rmq(a, b, 0, 0, sz));
  }

  void update(int k, T x)
  {
    k += sz - 1;
    seg[k] = x;
    while(k > 0) {
      k = (k - 1) >> 1;
      seg[k] = merge(seg[2 * k + 1], seg[2 * k + 2]);
    }
  }
};

int rev[200000];
SegmentTree< int > seg1(200000), seg2(200000);
vector< int > g[200000];
pair< int, int > ans[200000];
int ptr;

void rec(int l, int r, int par = 0)
{
  if(l >= r) return;

  g[par].push_back(++ptr);
  int curr = ptr;

  if(l % 2 == 0) {
    auto p = seg1.rmq(l, r);
    auto q = seg2.rmq(rev[p], r);
    seg1.update(rev[p], INF);
    seg2.update(rev[q], INF);
    ans[curr] = {p, q};
    rec(l, rev[p], par);
    rec(rev[p] + 1, rev[q], curr);
    rec(rev[q] + 1, r, par);
  } else {
    auto p = seg2.rmq(l, r);
    auto q = seg1.rmq(rev[p], r);
    seg2.update(rev[p], INF);
    seg1.update(rev[q], INF);
    ans[curr] = {p, q};
    rec(l, rev[p], par);
    rec(rev[p] + 1, rev[q], curr);
    rec(rev[q] + 1, r, par);
  }
}

int main()
{
  int N;
  cin >> N;
  vector< int > P(N);
  for(int i = 0; i < N; i++) {
    cin >> P[i];
    --P[i];
  }


  for(int i = 0; i < N; i += 2) {
    seg1.set(i, P[i]);
    seg2.set(i + 1, P[i + 1]);
  }
  seg1.build();
  seg2.build();
  for(int i = 0; i < N; i++) rev[P[i]] = i;
  rec(0, N);

  typedef pair< int, int > Pi;
  priority_queue< Pi, vector< Pi >, greater< >> que;
  for(auto &to : g[0]) que.emplace(ans[to].first, to);

  bool first = false;
  while(!que.empty()) {
    auto p = que.top();
    que.pop();
    if(first++) cout << " ";
    cout << ans[p.second].first + 1 << " " << ans[p.second].second + 1;
    for(auto &to : g[p.second]) que.emplace(ans[to].first, to);
  }
  cout << endl;
}

