      dv(1, n);

      while(!st.empty())
      {
            pair <int, int> vv = *st.begin();
            st.erase(st.begin());
            cout << vv.fr << " " << a[v[vv.sc].sc] << " ";
            for(int to : g[vv.sc])
                  st.insert(mk(a[v[to].fr], to));
      }
}

