struct rango {
    int l, r, mn;

    rango () {}
    rango (int _l, int _r, int _mn) : l(_l), r(_r), mn(_mn) {}

    bool operator < (const rango b) const {
        return st[l%2].v[mn] > st[b.l%2].v[b.mn];
    }
};

