    st[1].cons(1, n, 1);

    priority_queue<rango> pq;
    pq.emplace(1, n, st[1].query(1, n, 1, n, 1));
    while (pq.size()) {
        rango r = pq.top(); pq.pop();
        int seg = st[1-r.l%2].query(1, n, r.mn, r.r, 1);

        cout << st[r.l%2].v[r.mn] << " " << st[1-r.l%2].v[seg] << " ";

        if (r.mn != r.l)
            pq.emplace(r.l, r.mn-1, st[r.l%2].query(1, n, r.l, r.mn-1, 1));
        if (r.mn != seg-1)
            pq.emplace(r.mn+1, seg-1, st[1-r.mn%2].query(1, n, r.mn+1, seg-1, 1));
        if (seg != r.r)
            pq.emplace(seg+1, r.r, st[1-seg%2].query(1, n, seg+1, r.r, 1));
    }

