#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> PII;
#define FF first
#define SS second

const int N = 200000 + 5;
const int INF = 1<<30;
class SegTree{
	private:
		int size;
		PII nodes[4*N];
		inline int lc(int x){return 2*x+1;}
		inline int rc(int x){return 2*x+2;}
		void build(int l, int r ,int id, PII arr[]){
			if(r-l==1){
				nodes[id]=arr[l];
				return;
			}
			int mid=(l+r)>>1;
			build(l, mid, lc(id), arr);
			build(mid, r, rc(id), arr);
			nodes[id] = min(nodes[lc(id)], nodes[rc(id)]);
		}
		PII query(int ql, int qr, int l, int r, int id){
			if(qr <= l or r <= ql) return {INF,INF};
			if(ql <= l and r <= qr) return nodes[id];
			int mid=(l+r)>>1;
			return min(query(ql, qr, l, mid, lc(id)), query(ql, qr, mid, r, rc(id)));
		}
		void modify(int ql, int qr, int l, int r, int id, PII v){
			if(qr <= l or r <= ql) return;
			if(ql <= l and r <= qr){
				nodes[id]=v;
				return;
			}
			int mid=(l+r)>>1;
			modify(ql, qr, l, mid, lc(id), v);
			modify(ql, qr, mid, r, rc(id), v);
			nodes[id] = min(nodes[lc(id)], nodes[rc(id)]);
		}
	public:
		void build(int n, PII arr[]){
			size=n;
			build(0, size, 0, arr);
		}
		PII query(int l, int r){
			return query(l, r, 0, size, 0);
		}
		void modify(int p, PII v){
			modify(p, p+1, 0, size, 0, v);
		}
} odd, even;

int arr[N], ans[N];
PII o[N], e[N];

int main(int argc, char* argv[]){
	int n; cin>>n;
	fill(o, o+n, (PII){INF,INF});
	fill(e, e+n, (PII){INF,INF});
	for(int i=0;i<n;i++){
		cin>>arr[i];
		if(i&1) o[i]={arr[i],i};
		else e[i]={arr[i],i};
	}
	odd.build(n, o);
	even.build(n, e);
	set<int> block;
	block.insert(0);
	block.insert(n);
	priority_queue<PII,vector<PII>,greater<PII>> pq;
	pq.push(even.query(0, n));
	for(int i=0;i<(n/2);i++){
		PII pos = pq.top();pq.pop();
		if(pos.SS & 1){
			PII sec = even.query(pos.SS, *block.upper_bound(pos.SS));
			odd.modify(pos.SS, {INF,INF});
			even.modify(sec.SS, {INF,INF});
			auto it = block.upper_bound(pos.SS);
			it--;
			pq.push(odd.query(*it, pos.SS));
			pq.push(even.query(pos.SS, sec.SS));
			pq.push(odd.query(sec.SS, *block.upper_bound(sec.SS)));
			block.insert(pos.SS);
			block.insert(sec.SS);
			ans[i*2]=pos.FF;
			ans[i*2+1]=sec.FF;
		}else{
			PII sec = odd.query(pos.SS, *block.upper_bound(pos.SS));
			even.modify(pos.SS, {INF,INF});
			odd.modify(sec.SS, {INF,INF});
			auto it = block.upper_bound(pos.SS);
			it--;
			pq.push(even.query(*it, pos.SS));
			pq.push(odd.query(pos.SS, sec.SS));
			pq.push(even.query(sec.SS, *block.upper_bound(sec.SS)));
			block.insert(pos.SS);
			block.insert(sec.SS);
			ans[i*2]=pos.FF;
			ans[i*2+1]=sec.FF;
		}
	}
	for(int i=0;i<n;i++) cout<<ans[i]<<" \n"[i==n-1];
	return 0;
}

#include<bits/stdc++.h>
using std::vector;
using std::pair;
using pii = pair<int, int>;
int arr[200010];

struct indexed_tree {
	vector<pii> tree;
	int k = 1;
	indexed_tree(int n) {
		while (k < n)k *= 2;
		tree.resize(k * 2 + 10, { 0x7fffffff,-1 });
	}
	void update(int idx, pii a) {
		idx += k;
		while (idx) {
			tree[idx] = std::min(tree[idx], a);
			idx /= 2;
		}
	}
	pii getRange(int left, int right) {
		left += k; right += k;
		pii ret = { 0x7fffffff,-1 };
		while (left <= right) {
			if (left % 2 == 1)ret = std::min(ret, tree[left]);
			if (right % 2 == 0)ret = std::min(ret, tree[right]);
			left = (left + 1) / 2;
			right = (right - 1) / 2;
		}
		return ret;
	}
};
indexed_tree odd(200000), even(200000);
struct node {
	pair<pii,pii> q;
	int l, r;
	bool operator>(const node& p) const{
		return q > p.q;
	}
};
int main() {
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &arr[i]);
		if (i % 2 == 0)even.update(i, { arr[i],i });
		else odd.update(i, { arr[i],i });
	}
	std::priority_queue<node, vector<node>, std::greater<node>> heap;
	heap.push({ {even.getRange(0,n - 1),odd.getRange(0,n - 1)},0,n - 1 });
	std::string print = "";
	while (!heap.empty()) {
		int L = heap.top().l;
		int R = heap.top().r;
		int one = heap.top().q.first.second;
		int two = heap.top().q.second.second;
		int a = heap.top().q.first.first;
		int b = heap.top().q.second.first;
		heap.pop();
		char str[50];
		sprintf(str,"%d %d ", a, b);
		print += str;
		if (one > two)std::swap(one, two);
		vector<pii> segs = { { L, one - 1 },{ one + 1,two - 1 },{ two + 1,R } };
		for (pii s :segs) {

			int l = s.first;
			int r = s.second;
			if (l > r)continue;
			auto o = odd.getRange(l, r);
			auto e = even.getRange(l, r);
			if (l % 2 == 0) {
				heap.push({ {e,o},l,r });
			}
			else {
				heap.push({ {o,e},l,r });
			}
		}
	}
	printf("%s", print.c_str());
}

