inline void Solv(int l,int r,int L,int R){
	if(l>=r) return;
	if(l+1==r){
		B[L]=make_pair(A[l],A[r]);
		return;
	}
	int Min=0,Minn=0;
	for(int i=l;i<=r;i+=2)
	 if(A[i]<A[Min]||Min==0) Min=i;
	for(int i=Min+1;i<=r;i+=2)
	 if(A[i]<A[Minn]||Minn==0) Minn=i;
	B[L]=make_pair(A[Min],A[Minn]);
	int Mid=L+((Min-1)-(l-1))/2,Midd=R-(r-(Minn+1-1))/2;
	Solv(l,Min-1,L+1,Mid); 
	Solv(Min+1,Minn-1,Mid+1,Midd); 
	Solv(Minn+1,r,Midd+1,R);
	sort(B+L+1,B+R+1);
	return ;
}
