const int INF = 1 << 25;

struct SegmentTree {
  int n;
  vector<int> dat;
  SegmentTree(const vector<int> &init) {
    n = 1;
    while (n < init.size()) n *= 2;
    dat.resize(2 * n - 1, INF);
    for (int i = 0; i < init.size(); i++) {
      dat[i + n - 1] = init[i];
    }
    for (int i = n - 2; i >= 0; i--) {
      dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
  }
  int query(int a, int b, int k, int l, int r) const {
    if (r <= a || b <= l) return INF;
    if (a <= l && r <= b) return dat[k];
    int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return min(vl, vr);
  }
  int query(int a, int b) const { return query(a, b, 0, 0, n); }
};

int main() {
  int N;
  while (cin >> N) {
    vector<int> p(N);
    for (int i = 0; i < N; i++) {
      cin >> p[i];
    }
    vector<int> even, odd;
    map<int, int> mp;
    for (int i = 0; i < N; i++) {
      if (i % 2 == 0) {
        even.push_back(p[i]);
      } else {
        odd.push_back(p[i]);
      }
      mp[p[i]] = i;
    }
    SegmentTree evenRMQ(even), oddRMQ(odd);
    function<vector<pair<int, int>>(int, int)> solve = [&](int s, int t) {
      if (s >= t) {
        return vector<pair<int, int>>();
      }
      const SegmentTree &rmq1 = s % 2 == 0 ? evenRMQ : oddRMQ;
      const SegmentTree &rmq2 = s % 2 == 0 ? oddRMQ : evenRMQ;
      int ns = mp[rmq1.query(s / 2, t / 2)];
      int nt = mp[rmq2.query((ns + 1) / 2, (t + 1) / 2)];
      auto a = solve(s, ns);
      auto b = solve(ns + 1, nt);
      auto c = solve(nt + 1, t);
      vector<pair<int, int>> tmp(a.size() + b.size()),
          ans(a.size() + b.size() + c.size());
      merge(a.begin(), a.end(), b.begin(), b.end(), tmp.begin());
      merge(c.begin(), c.end(), tmp.begin(), tmp.end(), ans.begin());
      ans.insert(ans.begin(), make_pair(p[ns], p[nt]));
      return ans;
    };
    auto ans = solve(0, N);
    for (auto p : ans) {
      cout << p.first << " " << p.second << " ";
    }
    cout << endl;
  }
  return 0;
}

