inline void push(int node,int start,int end,int ind){
	if(lazy[node][ind]==1)return ;
	tree[node][ind].fi*=lazy[node][ind];
	if(start!=end){
		lazy[node*2][ind]*=lazy[node][ind];
		lazy[node*2+1][ind]*=lazy[node][ind];
	}
	lazy[node][ind]=1;
}

inline void build(int node,int start,int end,int ind){
	if(start>end)return ;
	lazy[node][ind]=1;
	if(start%2==1){
		if(start==end){tree[node][ind].fi=a[start];tree[node][ind].se=start;return ;}
	}
	else{
		//~ cout<<start<<"()()"<<endl;
		if(start==end){tree[node][ind].fi=-a[start];tree[node][ind].se=start;return ;}
	}
	build(node*2,start,mid,ind),build(node*2+1,mid+1,end,ind);
	if(ind==1){
		tree[node][ind]=max(tree[node*2][ind],tree[node*2+1][ind]);
	}
	else{
		tree[node][ind]=min(tree[node*2][ind],tree[node*2+1][ind]);
	}
} 

inline void update(int node,int start,int end,int l,int r,int ind,int val){
	push(node,start,end,ind);
	if(start>end || start>r || end<l)return ;
	if(start>=l && end<=r){
		if(l==r){
			if(ind==1)
			tree[node][ind].fi=-inf;
			else tree[node][ind].fi=inf;
			////~ lazy[node][ind]
		}
		else{lazy[node][ind]*=val;push(node,start,end,ind);return ;}
		return ;
	}
	update(node*2,start,mid,l,r,ind,val),update(node*2+1,mid+1,end,l,r,ind,val);
	if(ind==1){
		tree[node][ind]=max(mp(lazy[node*2][ind]*tree[node*2][ind].fi, tree[node*2][ind].se),mp(lazy[node*2+1][ind]*tree[node*2+1][ind].fi, tree[node*2+1][ind].se));
	}
	else{
		tree[node][ind]=min(mp(lazy[node*2][ind]*tree[node*2][ind].fi, tree[node*2][ind].se),mp(lazy[node*2+1][ind]*tree[node*2+1][ind].fi, tree[node*2+1][ind].se));
	}
}

inline PII query(int node,int start,int end,int l,int r,int ind){
	if(start>end || start>r || end<l){
		if(ind==1)return mp(-inf,-inf);
		else return mp(inf,inf);
	}
	push(node,start,end,ind);
	if(start>=l && end<=r){return tree[node][ind];}
	if(ind==1){
		return max(query(node*2,start,mid,l,r,ind),query(node*2+1,mid+1,end,l,r,ind));
	}
	else return min(query(node*2,start,mid,l,r,ind),query(node*2+1,mid+1,end,l,r,ind));
}

