	node(){}
	node(int L, int R):l(L), r(R){
		m=(l+r)>>1; p=a=0;
		lch=rch=NULL;
	}
}pn[400010], *r[2];
int n, arr[200010], nT; vector<pii> t1, ret;
void build(node *p, int a){
	p->a=a;
	if(p->r-p->l==1){
		p->p=p->l; return;
	}
	p->lch=&(pn[nT++]=node(p->l, p->m)); build(p->lch, a);
	p->rch=&(pn[nT++]=node(p->m, p->r)); build(p->rch, a);
	if(arr[p->lch->p<<1|a]<arr[p->rch->p<<1|a]) p->p=p->lch->p;
	else p->p=p->rch->p;
}
int query(node *p, int l, int r){
	if(r<=p->l||p->r<=l) return n>>1;
	if(l<=p->l&&p->r<=r) return p->p;
	int q1=query(p->lch, l, r), q2=query(p->rch, l, r);
	if(arr[q1<<1|p->a]<arr[q2<<1|p->a]) return q1;
	else return q2;
}
void dfs(int l, int r, int a){
	if(r>l){
		int p1=query(::r[a], l>>1, (r>>1)+(a^1)), p2=query(::r[a^1], p1+a, (r>>1)+1);
		p1=p1<<1|a, p2=p2<<1|a; p2^=1;
		vector<pii> r1, r2, r3;
		dfs(l, p1-1, a); r1=ret;
		dfs(p1+1, p2-1, a^1); r2=ret;
		dfs(p2+1, r, a); r3=ret;
		t1.resize(r1.size()+r2.size());
		merge(r1.begin(), r1.end(), r2.begin(), r2.end(), t1.begin());
		ret.resize((r-l+1)/2);
		ret[0]=pii(arr[p1], arr[p2]);
		merge(t1.begin(), t1.end(), r3.begin(), r3.end(), ret.begin()+1);
		return;
	}
	ret.clear(); return;
}
