#include <bits/stdc++.h>
using namespace std;

int n, A[200005];
struct BIT {
	struct node {
		int var, var2, lazy;//홀수, 짝수 자리중 최소
		node() { var = var2 = 1e9; lazy = 0; }
	};
	vector<node> tree;
	BIT(int V):tree(4*V){}
	node merge(node p, node q) {
		node ret;
		ret.var = min(p.var, q.var);
		ret.var2 = min(p.var2, q.var2);
		return ret;
	}
	void build(int x, int L, int R) {
		if (L == R) {
			if (L & 1) {
				tree[x].var = A[L];
			}
			else {
				tree[x].var2 = A[L];
			}
			return;
		}
		int mid = (L + R) >> 1;
		build(x + x, L, mid);
		build(x + x + 1, mid + 1, R);
		tree[x] = merge(tree[x + x], tree[x + x + 1]);
	}
	void push(int x, int L, int R) {
		if (tree[x].lazy) {
			int mid = (L + R) >> 1;
			tree[x + x].lazy ^= 1;
			tree[x + x + 1].lazy ^= 1;
			swap(tree[x + x].var, tree[x + x].var2);
			swap(tree[x + x + 1].var, tree[x + x + 1].var2);
			tree[x].lazy = 0;
		}
	}
	void flip(int x, int L, int R, int le, int ri) {
		if (ri < L || R < le)return;
		if (le <= L && R <= ri) {
			swap(tree[x].var, tree[x].var2);
			tree[x].lazy ^= 1;
			return;
		}
		push(x, L, R);
		int mid = (L + R) >> 1;
		flip(x + x, L, mid, le, ri);
		flip(x + x + 1, mid + 1, R, le, ri);
		tree[x] = merge(tree[x + x], tree[x + x + 1]);
	}
	void erase(int x, int L, int R, int idx) {
		if (idx< L || R < idx)return;
		if (L==idx && idx==R) {
			tree[x].var = tree[x].var2 = 1e9;
			return;
		}
		push(x, L, R);
		int mid = (L + R) >> 1;
		if (idx <= mid)erase(x + x, L, mid, idx);
		else erase(x + x + 1, mid + 1, R, idx);
		tree[x] = merge(tree[x + x], tree[x + x + 1]);
	}
	int query(int x, int L, int R, int le, int ri) {
		if (ri < L || R < le)return 1e9;
		if (le <= L && R <= ri) {
			return tree[x].var2;
		}
		push(x, L, R);
		int mid = (L + R) >> 1;
		int ret = query(x + x, L, mid, le, ri);
		ret = min(ret, query(x + x + 1, mid + 1, R, le, ri));
		return ret;
	}
};
int pos[200005];
int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &A[i]);
		pos[A[i]] = i;
	}
	BIT bit(n);
	bit.build(1, 1, n);
	vector<int> ans;
	set<int> sp;
	//6			2 4 1 6 5 3

	for (int ite = 1; ite <= n / 2; ite++) {
		int mn = bit.tree[1].var;
		int idx = pos[mn];

		auto it = sp.lower_bound(idx);
		int ed = n;
		if (it != sp.end())ed = (*it) - 1;

		int mn2 = bit.query(1, 1, n, idx + 1, ed);
		ans.push_back(mn); ans.push_back(mn2);
		int idx2 = pos[mn2];

		bit.erase(1, 1, n, idx);
		bit.erase(1, 1, n, idx2);

		sp.insert(idx); sp.insert(idx2);

		bit.flip(1, 1, n, idx + 1, idx2 - 1);
	}
	for (int i = 0; i < ans.size(); i++)printf("%d ", ans[i]);
}

