struct node{
	P val; int pos;
	bool operator < (const node &a) const{
		return val > a.val;
	}
} tmp, tmp2;
vector<int> link[maxn];
priority_queue<node> Q;
P ans[maxn], a[maxn], b[maxn], A[maxn], B[maxn];
int n, m, cnt;

int solve(int l, int r){
	vector<P> tmpA[3], tmpB[3];
	P best, pos, tmp; best.L = n+1; best.R = n+1;
	int cntA, cntB, p, q;

	cntA = cntB = 0;
	for (int i=l; i<=r; i++){
		if (i == l || a[i].R < A[cntA].R) A[++cntA] = a[i];
		if (i == l || b[i].R > B[cntB].R) B[++cntB] = b[i];
	}
	p = 1; q = cntB;
	while (p <= cntA){
		while (2 <= q && A[p].R < B[q-1].R) q--;
		if (A[p].R > B[q].R) break;
		tmp = make_pair(A[p].L, B[q].L);
		if (tmp < best){
			best = tmp;
			pos = make_pair(A[p].R, B[q].R);
		}
		p++;
	}

	cntA = cntB = 0;
	for (int i=l; i<=r; i++){
		if (i == l || a[i].R > A[cntA].R) A[++cntA] = a[i];
		if (i == l || b[i].R < B[cntB].R) B[++cntB] = b[i];		
	}
	p = cntA; q = 1;
	while (q <= cntB){
		while (2 <= p && B[q].R < A[p-1].R) p--;
		if (B[q].R > A[p].R) break; //printf("%d %d\n", B[q].R, A[p].R);
		tmp = make_pair(B[q].L, A[p].L);
		if (tmp < best){
			best = tmp;
			pos = make_pair(B[q].R, A[p].R);
		}
		q++;
	}

	ans[++cnt] = best; //printf("%d %d\n", best.L, best.R);
	int x = pos.L, y = pos.R; //printf("~%d %d\n", x, y);
	for (int i=0; i<=2; i++) { tmpA[i].clear(); tmpB[i].clear(); }
	for (int i=l; i<=r; i++){
		//printf("~%d %d\n", a[i].R, b[i].R);
		if (a[i].R < x) tmpA[0].push_back(a[i]);
		else if (x < a[i].R && a[i].R < y) tmpA[1].push_back(a[i]);
		else if (y < a[i].R) tmpA[2].push_back(a[i]);
		if (b[i].R < x) tmpB[0].push_back(b[i]);
		else if (x < b[i].R && b[i].R < y) tmpB[1].push_back(b[i]);
		else if (y < b[i].R) tmpB[2].push_back(b[i]);
	}

	int tot = 0, now = cnt;
	for (int i=0; i<=2; i++){
		//printf("%d %d\n", i, tmpA[i].size());
		if (tmpA[i].size()){
			for (int j=0; j<tmpA[i].size(); j++){
				a[l+tot+j] = tmpA[i][j];
				b[l+tot+j] = tmpB[i][j];
			}
			link[now].push_back(solve(l+tot, l+tot+tmpA[i].size()-1));
			tot += tmpA[i].size();
		} 
	}
	return now;
}

void print(){
	tmp.val = ans[1]; tmp.pos = 1;
	Q.push(tmp);
	while (m--){
		tmp = Q.top(); Q.pop();
		printf("%d %d ", tmp.val.L, tmp.val.R);
		for (int i=0; i<link[tmp.pos].size(); i++){
			tmp2.val = ans[link[tmp.pos][i]];
			tmp2.pos = link[tmp.pos][i];
			Q.push(tmp2);
		}
	}
}

int main(){
	n = read(); m = n >> 1;
	for (int i=1; i<=m; i++){
