template<typename M>
struct SegmentTree {

  /**
  * @brief コンストラクタ. O(n)
  * @param[in] n セグ木のサイズ.
  * @param[in] f モノイドの演算.
  * @param[in] e モノイドの単位元.
  * @details 使い方
  *   e.g. Range Minimum
  *   SegmentTree<int> segt(
  *            n,
  *            [](int a,int b){ return min(a+b); },
  *            INF);
  *               // 全て単位元で初期化される.
  */
  SegmentTree(
    int n,
    const function<M(M,M)>& f,
    const M& e) : n(n), f(f), e(e) {
    sz = 1;
    while (sz < n) sz <<= 1;
    data.assign(2 * sz, e);
  }

  /**
  * @brief 全体に初期値を入れる. O(n)
  * @param[in] v 要素モノイドのvector. 初期化する.
  * @details 使い方
  *   segt.build(vector<int>(n, 0));
  */
  void build(const vector<M>& v) {
    assert(v.size() <= n);
    for (int i = 0; i < v.size(); ++i) {
      data[i + sz] = v[i];
    }
    for (int i = sz-1; i > 0; --i) {
      data[i] = f(data[2 * i], data[2 * i + 1]);
    }
  }

  /**
  * @brief 指定した位置に更新クエリを実行する. O(log n)
  * @param[in] k 位置k の要素に作用させる.
  * @param[in] q 値x をq(x) で更新する.
  * @details 使い方
  *   e.g. Add Query
  *   int i, x; // 位置i をx を足したい.
  *   segt.update(i, [&](int a){ return a + x; });
  *
  *   e.g. Update Query
  *   int i, x; // 位置i をx に更新したい.
  *   segt.update(i, [&](int a){ return x; });
  */
  template<class UpdateQuery>
  void update(int k, const UpdateQuery &q) {
    k += sz;
    data[k] = q(data[k]);
    while (k >>= 1) {
      data[k] = f(data[2 * k], data[2 * k + 1]);
    }
  }

  /**
  * @brief 指定した区間に取得クエリを実行する. O(log n)
  * @param[in] l, r 区間[l, r) を取得する.
  * @return 取得した値.
  * @details 使い方
  *   e.g. Range Minimum
  *   int l, r; // 区間[l, r) のminを取得したい.
  *   cout << segt.query(l, r) << endl;
  */
  M query(int a, int b) const {
    return query(a, b, 1, 0, sz);
  }

  /**
  * @brief 指定したindexの要素を取得. O(1)
  * @param[in] i 取得したい要素のindex
  * @return 取得した値.
  */
  M operator[](int k) const {
    return data[k + sz];
  }

  /**
  * @brief vector みたいに出力.
  */
  friend ostream& operator<<(ostream& os, SegmentTree& s) {
    os << "[";
    for (int i = 0; i < s.n; ++i) {
      if (i) os << " ";
      os << s[i];
    }
    return os << "]";
  }

private:
  int n, sz;
  vector<M> data;
  const function<M(M,M)> f;
  const M e;

  M query(int a, int b, int k, int l, int r) const {
    if (r <= a || b <= l) {
      return e;
    } else if (a <= l && r <= b) {
      return data[k];
    } else {
      return f(query(a,b,2*k,  l,(l+r)/2),
               query(a,b,2*k+1,(l+r)/2,r));
    }
  }
};

vector<P> ans;
set<pair<P, P>> sections;

void solve(int n, SegmentTree<P> &stod, SegmentTree<P> &stev) {
  if(SZ(sections) == 0) return;
  auto mi = *(sections.begin());
  sections.erase(mi);
  int l = mi.second.first;
  int r = mi.second.second;

  P lmi = (l%2 == 0) ? stod.query(l, r-1) : stev.query(l, r-1);
  P rmi = (l%2 == 0) ? stev.query(lmi.second+1, r) : stod.query(lmi.second+1, r);
  ans.emplace_back(lmi.first, rmi.first);

  vi vl = {l, lmi.second+1, rmi.second+1};
  vi vr = {lmi.second, rmi.second, r};

  REP(i, 3) {
    l = vl[i], r = vr[i];
    if(l + 1 >= r) continue;
    lmi = (l%2 == 0) ? stod.query(l, r-1) : stev.query(l, r-1);
    rmi = (l%2 == 0) ? stev.query(lmi.second+1, r) : stod.query(lmi.second+1, r);
    sections.insert({{lmi.first, rmi.first}, {lmi.second, rmi.second+1}});
  }

  /*
  for(auto &e: sections) {
    cout << e << " ";
  }
  cout << endl;
  cout << endl;
   */

  solve(n, stod, stev);
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int n; cin >> n;
  vi p(n);
  REP(i, n) {
    cin >> p[i];
  }

  SegmentTree<P> stod(n, [](P a, P b){return min(a, b);}, make_pair(INF, INF)), stev(n, [](P a, P b){return min(a, b);}, make_pair(INF, INF));
  vector<P> od(n, {INF, INF}), ev(n, {INF, INF});
  for(int i=0;i<n;i+=2) {
    od[i] = {p[i], i};
  }
  for(int i=1;i<n;i+=2) {
    ev[i] = {p[i], i};
  }
  stod.build(od);
  stev.build(ev);

  P l = stod.query(0, n-1);
  P r = stev.query(l.second+1, n);
  sections.insert({{INF, INF}, {0, n}});
  solve(n, stod, stev);

  for(auto &e: ans) {
    if(e.first == INF) continue;
    cout << e.first << " " << e.second << " ";
  }
  cout << endl;

}

