const int INF = 1000000000;

typedef pair<int, int> ii;
typedef vector<int> vi;
typedef vector<ii> vii;
typedef vector<vi> vvi;

vi arr;
vii oddMin;
vii evenMin;

void buildTree(int n, int lb, int rb){

    if(lb + 1 == rb){
        if(lb % 2 == 0){
            evenMin[n] = mp(arr[lb], lb);
        } else {
            oddMin[n] = mp(arr[lb], lb);
        }
    } else {
        int mb = (lb+rb)/2;
        buildTree(2*n, lb, mb);
        buildTree(2*n+1, mb, rb);
        evenMin[n] = min(evenMin[2*n], evenMin[2*n+1]);
        oddMin[n] = min(oddMin[2*n], oddMin[2*n+1]);
    }
}

ii rmq(int l, int r, bool even, int lb, int rb, int n = 1){
    //cout << l << " " << r << endl;
    if(l == r) return mp(INF, -1);
    if(l <= lb && r >= rb){
        return even ? evenMin[n] : oddMin[n];
    } else {
        int mb = (lb + rb) / 2;
        if(r <= mb){
            return rmq(l, r, even, lb, mb, 2*n);
        } else if (l >= mb){
            return rmq(l, r, even, mb, rb, 2*n+1);
        } else {
            return min (rmq(l, r, even, lb, mb, 2*n), rmq(l, r, even, mb, rb, 2*n+1));
        }
    }
}
int N;
vvi adj;
vi neigh;
// normally:
// rmq(rev) -> odd indeces;
// rmq(!rev) -> even indeces
int getAdj(int lb, int rb, bool rev){
    if(lb == rb) return INF;
    auto em = rmq(lb, rb, !rev, 0, N).second;
    auto om = rmq(em, rb, rev, 0, N).second;
    neigh[em] = om;
    int a = getAdj(lb, em, rev);
    int b = getAdj(em+1, om, !rev);
    int c = getAdj(om+1, rb, rev);
    if(a != INF) adj[em].pb(a);
    if(b != INF) adj[em].pb(b);
    if(c != INF) adj[em].pb(c);
    return em;
}

