		counter += 2;
		ll f = currentresults[0].first, s = currentresults[0].second;
		for (auto it : v[now]) {
			if (it.first > it.second)continue;
			if (index[f] >= it.first && index[s] <= it.second) {
				if (it.first < index[f])v[future].push_back(make_pair(it.first, index[f] - 1));
				if (index[f] < index[s])v[future].push_back(make_pair(index[f] + 1, index[s] - 1));
				if (index[s] < it.second)v[future].push_back(make_pair(index[s] + 1, it.second));
			}
			else {
				v[future].push_back(it);
			}
		}
		v[now].resize(0);
		swap(now, future);
	}
	return 0;
}

#include <bits/stdc++.h>
#define REP(i,n) for (int i=0;i<(n);i++)
#define RREP(i,n) for (int i=(n)-1;i>=0;i--)
using namespace std;

int N;
vector<int> p;

vector<int> solve(int start, int end) {
    vector<int> retval;

    if (start >= end)
        return retval;

    assert((end - start) % 2 == 0);

    //Step1.先頭に来るものを選ぶ
    int min_value = N + 1, min_index = 0, min_index2 = 0;
    for (int i = start; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index = i;
        }
    }
    retval.emplace_back(min_value);

    //Step2.2番目に来るものを選ぶ
    min_value = N + 1;
    for (int i = min_index + 1; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index2 = i;
        }
    }
    retval.emplace_back(min_value);

    if (start - end == 2)
        return retval;

    //残ったところを再帰的に行う
    vector<int> forward = solve(start, min_index);
    vector<int> mid     = solve(min_index + 1, min_index2);
    vector<int> back    = solve(min_index2 + 1, end);

    vector<pair<int, int> > pairs;
    for (int i = 0; i < forward.size(); i += 2) {
        pairs.emplace_back(forward[i], forward[i + 1]);
    }
    for (int i = 0; i < mid.size(); i+= 2) {
        pairs.emplace_back(mid[i], mid[i + 1]);
    }
    for (int i = 0; i < back.size(); i += 2) {
        pairs.emplace_back(back[i], back[i + 1]);
    }

    sort(pairs.begin(), pairs.end());

    for (auto p : pairs) {
        retval.push_back(p.first);
        retval.push_back(p.second);
    }

    return retval;
}

int main()
{
    cin >> N;
    p.resize(N);
    REP(i, N) cin >> p[i];

    vector<int> q = solve(0, N);

    REP (i, N)
        printf("%d ", q[i]);
    printf("\n");
}

