#define INF 1120000000

template<typename T>
class SegTree {
public:
  int n;
  vector<T> data;
  vector<int> pos;
  SegTree(int n_){
    n=1;
    while(n<n_) n*=2;
    data.resize(n+1, INF);
    pos.resize(2*n, n);
  }
  inline int query(int l, int r){ // position of min value
    int ret = n;
    for(l+=n, r+=n; l<r; l/=2, r/=2){
      if(l&1){
        if(data[ret] > data[pos[l]]) ret = pos[l];
        l++;
      }
      if(r&1){
        r--;
        if(data[ret] > data[pos[r]]) ret = pos[r];
      }
    }
    return ret;
  }
  inline void update(int k, T a){
    data[k]=a;
    pos[k+n]=k;
    k+=n;
    while(k>0){
      k = k/2;
      if(data[pos[k*2]] < data[pos[k*2+1]]){
        pos[k] = pos[k*2];
      }
      else {
        pos[k] = pos[k*2+1];
      }
    }
  }
  inline T operator[](int idx){ return data[idx+n]; }
};


int main(){
  int n;
  cin>>n;
  vector<int> vec(n);
  rep(i,n) cin>>vec[i], vec[i]--;
  SegTree<int> st[2] = SegTree<int>(n);
  rep(i,n){
    st[i%2].update(i, vec[i]);
  }

  vector<int> ans;

  using P = pair<int,int>;
  priority_queue<pair<int,P>, vector<pair<int,P>>, greater<pair<int,P>>> pq;
  pq.push(mp(vec[st[0].query(0,n)], mp(0,n)));

  while(!pq.empty()){
    auto p = pq.top(); pq.pop();
    int l = p.se.fi, r = p.se.se;
    int p1 = st[l%2].query(l,r);
    int p2;
    bool sw = false;
    if((p1-l)%2==0) p2 = st[!(p1%2)].query(p1, r);
    else sw=true,p2 = st[!(p1%2)].query(l, p1);
    st[!(p1%2)].update(p2, INF);
    st[(p1%2)].update(p1, INF);

    if(sw) swap(p1,p2);
    ans.pb(vec[p1]);ans.pb(vec[p2]);

    auto ins = [&](int a, int b){
      if(a==b) return;
      pq.push(mp(vec[st[a%2].query(a,b)], mp(a,b)));
    };

    ins(l,p1);
    ins(p1+1,p2);
    ins(p2+1,r);
  }

  rep(i,n) cout << ans[i]+1 << " \n"[i==n-1];

  return 0;
}

