struct Tree {
	#define lson l,mid,x<<1
	#define rson mid+1,r,x<<1|1
	int mi[N<<2], arr[N];
	Tree() {arr[0] = 1e9;}
	void build(int l, int r, int x) {
		if(l == r) return mi[x] = l, void();
		int mid = l + r >> 1;
		build(lson), build(rson);
		mi[x] = mi[x << 1 | (arr[mi[x<<1]] > arr[mi[x<<1|1]])];
	}
	int qry(int l, int r, int x, int L, int R) {
		if(L <= l and r <= R) return mi[x];
		int mid = l + r >> 1, t1 = 0, t2 = 0;
		if(L <= mid) t1 = qry(lson, L, R);
		if(mid < R) t2 = qry(rson, L, R);
		return arr[t1] < arr[t2] ? t1 : t2;
	}
	#undef lson
	#undef rson
};

