template<typename T> class segtree {
private:
    int n,sz;
    vector<pair<T, int> > node;
public:
    segtree(const vector<T>& v) : n(1), sz((int)v.size()){
        while(n < sz) n *= 2;
        node.resize(2*n, make_pair(numeric_limits<T>::max(), sz));
        for(int i = 0; i < sz; i++){
            node[i+n] = make_pair(v[i], i);
        }
        for(int i=n-1; i>=1; i--){
            node[i] = min(node[2*i], node[2*i+1]);
        }
    }
    void update(int k, T a)
    {
        node[k+n] = make_pair(a, k);
        k += n;
        while(k>>=1){
            node[k] = min(node[2*k], node[2*k+1]);
        }
    }
    pair<T, int> query(int a,int b,int k=0,int l=0,int r=-1)
    {
        pair<T, int> res1 = make_pair(numeric_limits<T>::max(), sz);
        pair<T, int> res2 = make_pair(numeric_limits<T>::max(), sz);
        a += n, b += n;
        while(a != b){
            if(a % 2) res1 = min(res1, node[a++]);
            if(b % 2) res2 = min(res2, node[--b]);
            a >>= 1, b>>= 1;
        }
        return min(res1, res2);
    }
    void _print()
    {
        for(int i = 0; i < sz; i++){
            pair<T, int> p;
            p = query(i,i+1);
            cout << "st[" << i << "]: " << p.first << " " << p.second << endl;
        }
    }
};

vector<int> p;
vector<segtree<int>> sg;

vector<P> dfs(int l, int r){
    if(r <= l)return vector<P>(0);
    if(r-l == 2){return {P(p[l], p[l+1])};}

    auto lmin = (l%2)? sg[1].query(l, r) : sg[0].query(l, r);
    int li = lmin.second;
    auto rmin = (l%2)? sg[0].query(li+1, r) : sg[1].query(li+1, r);
    int ri = rmin.second;

    auto a = dfs(l, li);
    auto b = dfs(li+1, ri);
    auto c = dfs(ri+1, r);

    vector<P> res;
    res.push_back(P(lmin.first, rmin.first));

    ll ai = 0, bi = 0, ci = 0; 
    while(ai < a.size() || bi < b.size() || ci < c.size()){
        int f = -1;
        P minp;
        if(ai < a.size()){
            f = 0;
            minp = a[ai];
        }
        if(bi < b.size()){
            if(f == -1 || b[bi] < minp){
                f = 1;
                minp = b[bi];
            }
        }
        if(ci < c.size()){
            if(f == -1 || c[ci] < minp){
                f = 2;
                minp = c[ci];
            }
        }
        res.push_back(minp);
        if(f == 0){ai++;}
        if(f == 1){bi++;}
        if(f == 2){ci++;}
    }

    return res;
}

