template<typename T>
struct segtree{
	int n;
	vector<T> dat;
	T ZERO;
	function<T(T,T)> f;

	segtree(int n_,T zero, function<T(T,T)> f_)
	:ZERO(zero), f(f_){
	  n = 1;
	  while(n < n_)n*=2;
	  dat.resize(2*n);
	  for(int i = 0;i < 2*n;i++)dat[i] = ZERO;
	}

	void update(int k, T a){
	  k += n - 1;dat[k] = a;
	  while(k > 0){
		k = (k-1)/2;
		dat[k] = f(dat[k*2+1],dat[k*2+2]);
	  }
	}

	void set(int k, T a) {
		k += n - 1;dat[k] = a;
	}

	void build(){
		for(int i = n - 2;i >= 0;i--){
			dat[i] = f(dat[2 * i + 1], dat[2 * i + 2]);
		}
	}

	T get(int k){return dat[k+n-1];}

	T que(int a,int b){
		T L = ZERO,R = ZERO;
		int A = a + n - 1;
		int B = b + n - 1;
		while(A < B){
			if((A & 1) == 0)L = f(L,dat[A++]);
            if((B & 1) == 0)R = f(dat[--B],R);
            A = A >> 1;
            B = B >> 1;
		}
		return f(L,R);
	}
};

ll mp[222222];
segtree<ll> evenSeg(222222, INF, [](ll a, ll b){return min(a, b);});
segtree<ll> oddSeg(222222, INF, [](ll a, ll b){return min(a, b);});

pair<P, P> getPair(int l, int r){
	ll fi,se;
	if(l % 2) {
		fi = oddSeg.que(l, r+1);
		se = evenSeg.que(mp[fi], r+1);
	}
	else {
		fi = evenSeg.que(l, r+1);
		se = oddSeg.que(mp[fi], r+1);
	}
	return MP(MP(fi, se), MP(l, r));
}

