    vector<int> p(N); cin >> p;
    // range min
    SegmentTree< pii > seg1(N, [](pii a, pii b){ return min(a, b); }, mp(INT_MAX, INT_MAX));
    SegmentTree< pii > seg2(N, [](pii a, pii b){ return min(a, b); }, mp(INT_MAX, INT_MAX));

    rep(i, 0, N){
        if(i%2 == 0) seg1.update(i, pii(p[i], i));
        else seg2.update(i, pii(p[i], i));
    }
    auto compare = [&](piii a, piii b){
        int ta, tb;
        if(a.second == 0) ta = seg1.query(a.first.first, a.first.second).first;
        else ta = seg2.query(a.first.first, a.first.second).first;
        if(b.second == 0) tb = seg1.query(b.first.first, b.first.second).first;
        else tb = seg2.query(b.first.first, b.first.second).first;
        return ta > tb;
    };
    priority_queue<
        piii,
        vector<piii>,
        decltype(compare)
    > pq{compare};
    pq.push(piii(pii(0, N), 0));
    vector<int> ans;

    while(!pq.empty()){
        auto [LR, flag] = pq.top();pq.pop();
        auto [l, r] = LR;
        // cerr << LR << endl;
        pii t1, t2;
        if(flag){
            t1 = seg2.query(l, r);
            t2 = seg1.query(t1.second, r);
        }else{
            t1 = seg1.query(l, r);
            t2 = seg2.query(t1.second, r);
        }
        ans.push_back(t1.first);
        ans.push_back(t2.first);
        if(t1.second - l > 1) pq.push(piii(pii(l, t1.second), flag));
        if(t2.second - t1.second > 1) pq.push(piii(pii(t1.second + 1, t2.second), 1 - flag));
        if(r - t2.second > 1) pq.push(piii(pii(t2.second, r), flag));
    }
    cout << ans << endl;

    return 0;
}

