inline void lazy_eval(int type,int k){
	if(type==0){
		if(lazy[type][k]!=-1)dat[type][k]=min(dat[type][k],lazy[type][k]);
	}
	else if(lazy[type][k]!=-1)dat[type][k]=max(dat[type][k],lazy[type][k]);
	if(k<n_-1){
		if(lazy[type][k*2+1]==-1){
			lazy[type][k*2+1]=lazy[type][k];
		}
		if(lazy[type][k*2+2]==-1){
			lazy[type][k*2+2]=lazy[type][k];
		}
		if(type==0 && lazy[type][k]!=-1){
			lazy[type][k*2+1]=min(lazy[type][k],lazy[type][k*2+1]);
			lazy[type][k*2+2]=min(lazy[type][k],lazy[type][k*2+2]);
		}else if(lazy[type][k]!=-1){
			lazy[type][k*2+1]=max(lazy[type][k],lazy[type][k*2+1]);
			lazy[type][k*2+2]=max(lazy[type][k],lazy[type][k*2+2]);
		}
	}
}

inline void lazy_upd(int type,int k){
	if(type==0)dat[type][k]=min(dat[type][k*2+1],dat[type][k*2+2]);
	else dat[type][k]=max(dat[type][k*2+1],dat[type][k*2+2]);
}

void update(int type,int a,int b,int v,int k=0,int l=0,int r=n_){
	lazy_eval(type,k);
	//printf("%d %d %d %d %d %d %d\n",type,a,b,v,l,r,dat[type][k]);
	if(b<=l || r<=a)return;
	if(a<=l && r<=b){
		if(lazy[type][k]==-1)lazy[type][k]=v;
		if(type==0)lazy[type][k]=min(lazy[type][k],v);
		if(type==1)lazy[type][k]=max(lazy[type][k],v);
		lazy_eval(type,k);
		return;
	}
	int mid=(l+r)/2;
	update(type,a,b,v,k*2+1,l,mid);
	update(type,a,b,v,k*2+2,mid,r);
	lazy_upd(type,k);
}

int query(int type,int a,int b,int k=0,int l=0,int r=n_){
	lazy_eval(type,k);
	if(b<=l || r<=a){
		if(type==0)return INF;
		else return 0;
	}
	if(a<=l && r<=b){
		return dat[type][k];
	}
	int mid=(l+r)/2;
	int vl=query(type,a,b,k*2+1,l,mid);
	int vr=query(type,a,b,k*2+2,mid,r);
	lazy_upd(type,k);
	if(type==0)return min(vl,vr); 
	return max(vl,vr);
}

void update2(int type,int k,P a){
	k+=n_-1;
	minist[type][k]=a;
	while(k>0){
		k=(k-1)/2;
		minist[type][k]=min(minist[type][k*2+1],minist[type][k*2+2]);
	}
}

P query2(int type,int a,int b,int k=0,int l=0,int r=n_){
	if(b<=l || r<=a)return P(INF,0);
	if(a<=l && r<=b)return minist[type][k];
	int mid=(l+r)/2;
	P vl=query2(type,a,b,k*2+1,l,mid);
	P vr=query2(type,a,b,k*2+2,mid,r);
	return min(vl,vr); 
}

