				update2(1,v2.second/2,P(INF,0));
				update2(0,v3.second/2,P(INF,0));
			}else{
				P v3=query2(0,v2.second/2+1,rb/2+1);
				q[i*2]=v2.first;
				q[i*2+1]=v3.first;
				update(0,0,v2.second+1,v2.second);
				update(0,0,v3.second+1,v3.second);
				update(1,v2.second+1,n,v2.second+1);
				update(1,v3.second+1,n,v3.second+1);
				update2(1,v2.second/2,P(INF,0));
				update2(0,v3.second/2,P(INF,0));
			}
		}
	}
	for(int i=0;i<n;i++){
		printf("%d%c",q[i],i+1==n?'\n':' ');
	}
	return 0;
}

