const int maxn=2e5+999;

struct node{
	int x,y,posx,posy,L,R;
	node(int a,int b,int c,int d,int e,int f){x=a,y=b,posx=c,posy=d;L=e,R=f;}
	friend bool operator<(node a,node b){
		return a.x==b.x?a.y>b.y:a.x>b.x;
	}
};
int n;
struct seg{
	pi val[maxn<<2];
	void pushup(int rt){
		if(val[ls].first<val[rs].first)val[rt]=val[ls];
		else val[rt]=val[rs];
	}
	void build(int l,int r,int rt,int *a){
		if(l==r)return val[rt]=mp(a[l],l),void();
		int mid=l+r>>1;
		build(l,mid,ls,a);
		build(mid+1,r,rs,a);
		pushup(rt);
	}
	void modify(int pos,int l,int r,int rt){
		if(l==r){val[rt].first=INT_MAX;val[rt].second=0;return;}
		int mid=l+r>>1;
		if(pos<=mid)modify(pos,l,mid,ls);
		else modify(pos,mid+1,r,rs);
		pushup(rt);
	}
	pi query(int L,int R,int l,int r,int rt){
		if(L>R)return mp(-1,-1);
		if(L<=l&&r<=R)return val[rt];
		int mid=l+r>>1;pi ret=mp(INT_MAX,0);
		if(L<=mid)ret=query(L,R,l,mid,ls);
		if(R>mid){
			pi tmp=query(L,R,mid+1,r,rs);
			if(tmp.first<ret.first)ret=tmp;
		}
		return ret;
	}
}seg[2];
int a[maxn],b[2][maxn];
priority_queue<node>q;
node get(int l,int r){ 
	pi tmp1=seg[l&1].query(l,r,1,n,1),tmp2=seg[(l-1)&1].query(tmp1.second,r,1,n,1);
	seg[l&1].modify(tmp1.second,1,n,1);seg[(l-1)&1].modify(tmp2.second,1,n,1);
	node ret=node(tmp1.first,tmp2.first,tmp1.second,tmp2.second,l,r);
	return ret;
}
