		pos[p[i]] = i;

		int par = i % 2;

		t[par][n + i] = p[i];
		t[par ^ 1][n + i] = INF;
	}


	build(0);
	build(1);

	solve(p , 0 , n - 1);

	for(int e : restore()){
		cout << e << " ";
	}

	return 0;
}

