using pii = pair<int, int>;
int arr[200010];

struct indexed_tree {
	vector<pii> tree;
	int k = 1;
	indexed_tree(int n) {
		while (k < n)k *= 2;
		tree.resize(k * 2 + 10, { 0x7fffffff,-1 });
	}
	void update(int idx, pii a) {
		idx += k;
		while (idx) {
			tree[idx] = std::min(tree[idx], a);
			idx /= 2;
		}
	}
	pii getRange(int left, int right) {
		left += k; right += k;
		pii ret = { 0x7fffffff,-1 };
		while (left <= right) {
			if (left % 2 == 1)ret = std::min(ret, tree[left]);
			if (right % 2 == 0)ret = std::min(ret, tree[right]);
			left = (left + 1) / 2;
			right = (right - 1) / 2;
		}
		return ret;
	}
};
struct node {
	pair<pii,pii> q;
	int l, r;
	bool operator>(const node& p) const{
		return q > p.q;
	}
};
int main() {
	int n;
	scanf("%d", &n);

	indexed_tree odd(n), even(n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &arr[i]);
		if (i % 2 == 0)even.update(i, { arr[i],i });
		else odd.update(i, { arr[i],i });
	}
	std::priority_queue<node, vector<node>, std::greater<node>> heap;
	auto tmp = even.getRange(0, n - 1);
	heap.push({ {tmp,odd.getRange(tmp.second+1,n - 1)},0,n - 1 });
	std::string print = "";
	int cnt = 0;
	while (!heap.empty()) {
		cnt++;
		int L = heap.top().l;
		int R = heap.top().r;
		int one = heap.top().q.first.second;
		int two = heap.top().q.second.second;
		int a = heap.top().q.first.first;
		int b = heap.top().q.second.first;
		heap.pop();
		char str[50];
		sprintf(str,"%d %d ", a, b);
		print += str;
		if (one > two)std::swap(one, two);
		vector<pii> segs = { { L, one - 1 },{ one + 1,two - 1 },{ two + 1,R } };
		if (L + 1 != R) {
			for (pii s : segs) {

				int l = s.first;
				int r = s.second;
				if (l+1 > r)continue;

				assert((r - l + 1) % 2 == 0);
				if (l % 2 == 0) {

					auto e = even.getRange(l, r);
					auto o = odd.getRange(e.second+1, r);
					heap.push({ {e,o},l,r });
				}
				else {
					auto o = odd.getRange(l, r);
					auto e = even.getRange(o.second + 1, r);
					heap.push({ {o,e},l,r });
				}
			}
		}
	}
	//assert(cnt == n / 2);
	printf("%s", print.c_str());
}

