void rec(const int order, const int a, const int b, const SegmentTree<Min_Plus>& oddseg, const SegmentTree<Min_Plus>& evenseg)  // [a, b)
{
    if (a >= b) {
        return;
    }
    if (a < 0) {
        return;
    }
    if (b > N) {
        return;
    }
    assert(a % 2 == b % 2);
    const bool left_even = a % 2 == 0;
    const auto& dom_oddseg = (left_even) ? oddseg : evenseg;
    const auto& dom_evenseg = (left_even) ? evenseg : oddseg;

    const int dom_evenmin = dom_evenseg.accumulate(a / 2, b / 2);
    const int dom_evenmin_ind = rev[dom_evenmin];
    // show(dom_evenmin + 1);
    // show(dom_evenmin_ind);
    const int dom_oddmin = dom_oddseg.accumulate((dom_evenmin_ind + 1) / 2, (b + 1) / 2);
    const int dom_oddmin_ind = rev[dom_oddmin];
    // show(dom_oddmin + 1);
    // show(dom_oddmin_ind);

    pairs.push_back(make_pair(order, make_pair(dom_evenmin + 1, dom_oddmin + 1)));
    rec(order + 1, a, dom_evenmin_ind, oddseg, evenseg);
    rec(order + 1, dom_evenmin_ind + 1, dom_oddmin_ind, oddseg, evenseg);
    rec(order + 1, dom_oddmin_ind + 1, b, oddseg, evenseg);
}

