struct node{
	int l,r,x,y;
	node(){}
	node(int l,int r,int x,int y):l(l),r(r),x(x),y(y){}
	friend bool operator<(node c,node d){
		return a[c.x]>a[d.x];
	}
};
priority_queue<node> q;

void update(int k){
	t[0][k].mn=min(t[0][k<<1].mn,t[0][k<<1|1].mn);
	if (t[0][k].mn==t[0][k<<1].mn) t[0][k].pos=t[0][k<<1].pos;
	else t[0][k].pos=t[0][k<<1|1].pos;
	t[1][k].mn=min(t[1][k<<1].mn,t[1][k<<1|1].mn);
	if (t[1][k].mn==t[1][k<<1].mn) t[1][k].pos=t[1][k<<1].pos;
	else t[1][k].pos=t[1][k<<1|1].pos;
}

void build(int k,int l,int r){
	t[0][k].l=l; t[0][k].r=r;
	t[1][k].l=l; t[1][k].r=r;
	if (l==r){
		t[l&1][k].mn=a[l];
		t[l-1&1][k].mn=inf;
		t[0][k].pos=t[1][k].pos=l;
		return;
	}
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	update(k);
}

void query(int tp,int k,int L,int R,int &mn,int &p){
	if (L<=t[tp][k].l&&t[tp][k].r<=R){
		if (t[tp][k].mn<mn) mn=t[tp][k].mn,p=t[tp][k].pos;
		return;
	}
	int mid=(t[tp][k].l+t[tp][k].r)>>1;
	if (L<=mid) query(tp,k<<1,L,R,mn,p);
	if (R>mid) query(tp,k<<1|1,L,R,mn,p); 
}

void push(int l,int r){
	int a,b,p1,p2;
	a=b=inf;
	query(l&1,1,l,r,a,p1);
	query(l-1&1,1,l,r,b,p2);
	q.push(node(l,r,p1,p2));
}

