	while (!q.empty()){
		k=q.top(); q.pop();
		b[++m]=k.x; b[++m]=k.y;
		if (k.l+1<k.x) push(k.l,k.x-1);
		if (k.y+1<k.r) push(k.y+1,k.r);
		if (k.x+1<k.y) push(k.x+1,k.y-1);
	}
	for (i=1;i<=m;i++) printf("%d ",a[b[i]]);
	return 0;
}

