vector<int> e[N],ans;
pa query(int rt,int l,int r,int x,int y)
{
	pa ret;
	ret=make_pair(inf,inf);
	if (x<=l&&r<=y) return minn[rt];
	int mid=(l+r)/2;
	if (x<=mid)
	{
		pa tmp=query(ls,l,mid,x,y);
		ret.fi=min(ret.fi,tmp.fi);
		ret.se=min(ret.se,tmp.se);
	}
	if (y>=mid+1)
	{
		pa tmp=query(rs,mid+1,r,x,y);
		ret.fi=min(ret.fi,tmp.fi);
		ret.se=min(ret.se,tmp.se);
	}
	return ret;
}
int solve(int l,int r)
{
	pa tmpp=query(1,1,n,l,r);
	if ((l&1)==0) swap(tmpp.fi,tmpp.se);
	int posa=pos[tmpp.fi],posb=pos[tmpp.se];
	p[++cnt].a=tmpp.fi,p[cnt].b=tmpp.se,p[cnt].id=cnt;
	int cntt=cnt;
	if (posa!=l)
	{
		du[cntt]++;
		e[solve(l,posa-1)].push_back(cntt);
	}
	if (posa+1!=posb)
	{
		du[cntt]++;
		e[solve(posa+1,posb-1)].push_back(cntt);
	}
	if (posb!=r)
	{
		du[cntt]++;
		e[solve(posb+1,r)].push_back(cntt);
	}
	return cntt;
}
void build(int rt,int l,int r)
{
	if (l==r)
	{
		if (l&1) minn[rt].fi=a[l],minn[rt].se=inf;
		else minn[rt].fi=inf,minn[rt].se=a[l];
		return ;
	}
	int mid=(l+r)/2;
	build(ls,l,mid);
	build(rs,mid+1,r);
	minn[rt].fi=min(minn[ls].fi,minn[rs].fi);
	minn[rt].se=min(minn[ls].se,minn[rs].se);
}
