    }
    a /= 2;
    b /= 2;

    return query(dat, a, b, k, l, r);

}
int body(int &argc, char **argv) {
    auto N = read<i32>();
    ps = read<i32>(N);

    init(N / 2);
    REP(i, N) {
        update(i, i);
    }

    using namespace debug;

    unordered_map<pair<i32, i32>, pair<i32, i32>> candidates;

    auto calc = [&](i32 begin, i32 end) -> pair<i32, i32> {
        i32 first = query_int(begin, end, 0, 0, n);
        i32 second = query_int(first + 1, end + 1, 0, 0, n);
        return make_pair(first, second);
    };

    candidates.insert(make_pair(make_pair(0, N), calc(0, N)));

    auto qs = V<i32>();
    while (qs.size() != N) {
        auto next = min_element(candidates.begin(), candidates.end(), [&](auto e1, auto e2) {
            return ps[e1.second.first] < ps[e2.second.first];
        });

        qs.push_back(ps[next->second.first]);
        qs.push_back(ps[next->second.second]);
        candidates.erase(next);

        auto begin = next->first.first;
        auto end = next->first.second;
        auto first = next->second.first;
        auto second = next->second.second;

        if (begin != first) {
            candidates.insert(make_pair(make_pair(begin, first), calc(begin, first)));
        }
        if (first + 1 != second) {
            candidates.insert(make_pair(make_pair(first + 1, second), calc(first + 1, second)));
        }
        if (second + 1 != end) {
            candidates.insert(make_pair(make_pair(second + 1, end), calc(second + 1, end)));
        }
    }

    REP (i, N) {
        cout << qs[i];
        if (i != N - 1) {
            cout << " ";
        }
    }
    cout << endl;

    return 0;
}

