const int INF = 100000000;

class IndexSegmentTree {
private:
    int n;
    vector<int> dat;
    vector<int> v;
public:
    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat.assign(2 * n - 1, -1);
        v.assign(n, INF);
    }
    // k: index(0-indexed), a: value
    void update(int p, int a) {
        v[p] = a;
        int k = p + n - 1;
        dat[k] = p;
        while (k>0) {
            k = (k - 1) / 2;
            if (dat[k * 2 + 1] == -1) {
                dat[k] = dat[k * 2 + 2];
            }else if (dat[k * 2 + 2] == -1 || v[dat[k * 2 + 1]] <= v[dat[k * 2 + 2]]) {
                dat[k] = dat[k * 2 + 1];
            }else {
                dat[k] = dat[k * 2 + 2];
            }
        }
    }
    // query(a, b) =>  minimum in [a,b]
    int query(int a, int b) {
        return _query(a, b, 0, 0, n - 1);
    }
    // v[dat[k]] is minimum in [l,r]
    int _query(int a, int b, int k, int l, int r) {
        if (r<a || b<l) return -1;
        if (a <= l&&r <= b) {
            return dat[k];
        }
        else {
            int vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = _query(a, b, k * 2 + 2, (l + r) / 2 + 1, r);
            if (vr == -1) {
                return vl;
            }
            else if (vl == -1) {
                return vr;
            }
            else {
                if (v[vl] > v[vr]) {
                    return vr;
                }
                else {
                    return vl;
                }
            }
        }
    }
    // k: index(0-indexed)
    int get(int k) {
        return v[k];
    }
};

