PII query(int l, int r, int t) {
	assert(l <= r);
	int k = lg2[r-l+1];
	if(t ^ (l%2))
		return min(odd[k][l], odd[k][r-(1<<k)+1]);
	else
		return min(even[k][l], even[k][r-(1<<k)+1]);
}

int main() {
	int n;
	scanf("%d", &n);
	for(int i=0; i<n; i++) {
		scanf("%d", a+i);
		odd[0][i] = MP(a[i], i), even[0][i] = MP(n+1, i);
		if(i%2 == 0)	swap(odd[0][i], even[0][i]);
	}
	for(int i=1, l=1; i<LOGN; i++, l<<=1) {
		for(int j=0; j+l<n; j++) {
			odd[i][j] = min(odd[i-1][j], odd[i-1][j+l]);
			even[i][j] = min(even[i-1][j], even[i-1][j+l]);
		}
	}
	for(int i=1, lg=0; i<=n; i++) {
		if((1<<(lg+1)) < i)	lg++;
		lg2[i] = lg;
	}

	priority_queue<pair<PII, PII> > pq;
	VI ans;
	pq.push(MP(query(0, n-1, 0), MP(0, n-1)));
	while(!pq.empty()) {
		auto p = pq.top();	pq.pop();
		int l = p.S.F, r = p.S.S, i = p.F.S;
		// printf("%d %d %d\n", l, r, i);
		assert(r <= n);
		if(l>r)	continue;
		auto tmp = query(i, r, 1);
		int j = tmp.S;
		ans.PB(p.F.F);
		ans.PB(tmp.F);
		// printf("(i, j) = (%d, %d)\n", i, j);
		if(l <= i-1)	pq.push(MP(query(l, i-1, 0), MP(l, i-1)));
		if(i+1 <= j-1)	pq.push(MP(query(i+1, j-1, 0), MP(i+1, j-1)));
		if(j+1 <= r)	pq.push(MP(query(j+1, r, 0), MP(j+1, r)));
	}

	for(int i=0; i<SZ(ans); i++)	printf("%d%c", ans[i], " \n"[i==SZ(ans)-1]);
}

