void bt(int p,int x,int y)
{
	tree[p].a=x;tree[p].b=y;
	if(x==y)
	{
		if(x&1)tree[p].ma[1]=v[x],tree[p].id[1]=x;
		else tree[p].ma[0]=v[x],tree[p].id[0]=x;
		return;
	}
	int mid=x+y>>1;
	bt(p<<1,x,mid);bt(p<<1|1,mid+1,y);
	update(p);
}
int getmax(int p,int x,int y,int k)
{
	if(tree[p].a>=x&&tree[p].b<=y)return tree[p].id[k];
