	if(tree[ls].b>=x&&tree[ls].a<=y)t1=getmax(ls,x,y,k);
	if(tree[rs].b>=x&&tree[rs].a<=y)t2=getmax(rs,x,y,k);
	if(v[t1]>v[t2])return t1;
	else return t2;
}
