	void push(int x){
		a[++tot]=x; x=tot;
		int y=x>>1;
		while (y) {
			if (c[a[y]]>c[a[x]]) swap(a[x],a[y]),x=y,y=x>>1;
			else break;
		}
	}
	void pop(){
		swap(a[1],a[tot]); tot--;
		int x=1,y=2;
		while (y<=tot) {
			if (y<tot&&c[a[y]]>c[a[y+1]]) y++;
			if (c[a[x]]>c[a[y]]) swap(a[x],a[y]),x=y,y=x<<1;
			else break;
		}
	}
	int empty(){ return tot==0; }
	int top(){ return a[1]; }
