void build(int x,int l,int r){
	if (l>r) return;
	if (l==r) { m[x][0]=a[l]; return; }
	int mid=(l+r)>>1;
	build(tl(x),l,mid);
	build(tr(x),mid+1,r);
	m[x][0]=m[tl(x)][0],m[x][1]=m[tl(x)][1];
	if ((mid-l+1)&1) m[x][0]=min(m[x][0],m[tr(x)][1]),m[x][1]=min(m[x][1],m[tr(x)][0]);
	else m[x][0]=min(m[x][0],m[tr(x)][0]),m[x][1]=min(m[x][1],m[tr(x)][1]);
}
int query(int x,int l,int r,int ll,int rr,int k){
	if (l>r) return INF;
	if (ll<=l&&r<=rr) return m[x][k^((l-ll)&1)];
	int mid=(l+r)>>1,t1=INF,t2=INF;
	if (ll<=mid) t1=min(t1,query(tl(x),l,mid,ll,rr,k));
	if (rr>mid) t2=min(t2,query(tr(x),mid+1,r,ll,rr,k));
	return min(t1,t2);
}
