    menorodd = even.query(1, 0, n - 1, menorev, r);
  }
  vector<ii> a = go(l, menorev - 1);
  vector<ii> b = go(menorev + 1, menorodd - 1);
  vector<ii> c = go(menorodd + 1, r);
  int pta = 0;
  int ptb = 0;
  int ptc = 0;
  ret.pb(mp(p[menorev], p[menorodd]));
  while(pta < a.size() or ptb < b.size() or ptc < c.size()) {
    if(pta == a.size()) {
      if(ptb == b.size()) {
        ret.pb(c[ptc]);
        ptc++;
      }
      else if(ptc == c.size()) {
        ret.pb(b[ptb]);
        ptb++;
      }
      else if(b[ptb] < c[ptc]) {
