        ret.pb(a[pta]);
        pta++;
      }
      else {
        ret.pb(c[ptc]);
        ptc++;
      }
    }
    else if(ptc == c.size()) {
      if(a[pta] < b[ptb]) {
        ret.pb(a[pta]);
        pta++;
      }
      else {
        ret.pb(b[ptb]);
        ptb++;
      }
    }
    else {
      if(a[pta] < b[ptb] and a[pta] < c[ptc]) {
