priority_queue <pair <pair <int, int>, pair <int, int>>> pq;

void update (int pa, int idx, int l, int r, int q, int u)
{
    if (l == r)
    {
        tree[pa][idx] = u;
        return;
    }

    int mid = (l + r) >> 1;

    if (q <= mid)
        update (pa, idx * 2, l, mid, q, u);
    else
        update (pa, idx * 2 + 1, mid + 1, r, q, u);

    if (tree[pa][idx * 2] < tree[pa][idx * 2 + 1])
        tree[pa][idx] = tree[pa][idx * 2];
    else
        tree[pa][idx] = tree[pa][idx * 2 + 1];
}


int find (int pa, int idx, int l, int r, int ql, int qr)
{
    if (ql <= l && r <= qr)
        return tree[pa][idx];

    int mid = (l + r) >> 1;

    int la, ra;

    if (ql <= mid)
        la = find (pa, idx * 2, l, mid, ql, qr);
    else
        la = (1 << 30);

    if (mid < qr)
        ra = find (pa, idx * 2 + 1, mid + 1, r, ql, qr);
    else
        ra = (1 << 30);

    return (la < ra) ? la : ra;
}

pair <int, int> get (int l, int r)
{
    pair <int, int> f;
    f.first = -find (l & 1, 1, 1, n, l, r);
    f.second = -find ((l & 1) ^ 1, 1, 1, n, id[-f.first], r);
    return f;
}

void add (int l, int r)
{
    if (r < l)
        return;
    pair <int, int> f = get (l, r);
    ///printf ("%d %d = %d %d\n", l, r, -f.first, -f.second);

    pq.push ({f, {l, r}});
}

