    {
        scanf ("%d", &p[i]);
        id[p[i]] = i;
        update (i & 1, 1, 1, n, i, p[i]);
        update ((i & 1) ^ 1, 1, 1, n, i, (1 << 30));
    }

    pq.push ({{get (1, n)}, {1, n}});

    for (i = 0; i < n; i += 2)
    {
        pair <pair <int, int>, pair <int, int>> pqt = pq.top ();
