typedef pair<int,int> pii;

class node{
public:
	int ch;
	pii p;
	node *par;
	node() {
		ch = 0;
		p = pii(0,0);
	}
	node (int x, int y){
		ch = 0;
		p = pii(x, y);
	}
	bool operator < (const node &a) const {
		return p > a.p;
	}
};

int tree[2][804040], n;
map <int, int> pos;
set <node> leave;

void build (int i, int ind, int l, int r, int x, int v) {
	if (l == r) {
		tree[i][ind] = v;
		return;
	}
	int mid = (l+r)/2;
	if (x <= mid) {
		build(i, ind*2, l, mid, x, v);
	} else {
		build(i, ind*2+1, mid+1, r, x, v);
	}
	tree[i][ind] = min(tree[i][ind*2], tree[i][ind*2+1]);
}

int query (int i, int ind, int l, int r, int x, int y) {
	if (l == x && r == y) {
		return tree[i][ind];
	}
	if (l > y || r < x || x > y) {
		return 1<<30;
	}
	int mid = (l+r)/2;
	return min(query(i, ind*2, l, mid, x, min(mid, y)), query(i, ind*2+1, mid+1, r, max(mid+1, x), y));
}

void sol (int l, int r, node *par) {
	if (l >= r) {
		return;
	}

	int x, y;
	x = query(l%2, 1, 0, n-1, l, r);
	y = query(1-(l%2), 1, 0, n-1, pos[x]+1, r);
	node *new_node = new node(x, y);
	new_node->par = par;
	sol(pos[x]+1, pos[y]-1, new_node);
	sol(l, pos[x]-1, new_node);
	sol(pos[y]+1, r, new_node);
	if (par != NULL) {
		par->ch++;
	}
	if (new_node->ch == 0) {
		leave.insert(*new_node);
	}
}

