			   if (x.ansx+1<=x.ansy-1)
			   {
			   		y.l=x.ansx+1; y.r=x.ansy-1; y.work();
			   		st.insert(y);
			   }
			   if (x.ansy+1<=x.r)
			   {
			   		y.l=x.ansy+1; y.r=x.r; y.work();
			   		st.insert(y);
			   }
		}
		for (i=1;i<=n;++i) printf("%d ",ans[i]);
}

