#define _(x) b[p]=a[x],b[p+1]=a[x+1],p+=2,x+=2
using namespace std;
const int N=200010;
int a[N],b[N],n;
void solve(int l,int r)
{
    /*
    get x which is min in [l,r) and posx - l & 1 = 0
    get y which is min in [posx+1,r] and posy-posx & 1 = 1
    then the first pair is (x,y)
    get ans of [l,posx) (posx,posy) (posy,r]
    O(n) merge_sort them greedly
    */
    if(l+1==r||l>r) return;
    int posx=l,posy;
    for(int i=l+2;i<r;i+=2)if(a[i]<a[posx]) posx=i;//get wrong answer because of "i++" instead of "i+=2"
    posy=posx+1;
    for(int i=posx+3;i<=r;i+=2)if(a[i]<a[posy]) posy=i;
//  printf("(%d %d): posx: %d,posy: %d\n",l,r,posx,posy);//debug
    solve(l,posx-1);
    solve(posx+1,posy-1);
    solve(posy+1,r);
    b[l]=a[posx];b[l+1]=a[posy];
    int p1=l,p2=posx+1,p3=posy+1,p=l+2;
    for(;p1<=posx-1&&p2<=posy-1&&p3<=r;)
    {
        if(a[p1]<a[p2]&&a[p1]<a[p3]) _(p1);
        else if(a[p2]<a[p1]&&a[p2]<a[p3]) _(p2);
        else _(p3);
    }
    for(;p1<=posx-1&&p2<=posy-1;)
    {
        if(a[p1]<a[p2]) _(p1);
        else _(p2);
    }
    for(;p1<=posx-1&&p3<=r;)
    {
        if(a[p1]<a[p3]) _(p1);
        else _(p3);
    }
    for(;p2<=posy-1&&p3<=r;)
    {
        if(a[p2]<a[p3]) _(p2);
        else _(p3);
    }
    for(;p1<=posx-1;) _(p1);
    for(;p2<=posy-1;) _(p2);
    for(;p3<=r;) _(p3);
    for(int i=l;i<=r;i++) a[i]=b[i];
}
int main()
{
//  freopen("in.txt","r",stdin);
    scanf("%d",&n);
    for(int i=1;i<=n;i++) scanf("%d",&a[i]);
    solve(1,n);
    for(int i=1;i<=n;i++) printf("%d ",a[i]);   
    return 0;
}

