//vb奇数，va偶数
void push_down(int o)
{
    if(ff[o])
    {
        swap(vb[o<<1],vc[o<<1]);
        swap(vb[o<<1|1],vc[o<<1|1]);
        ff[o<<1]^=ff[o],ff[o<<1|1]^=ff[o];
        ff[o]=0;
    }
}
void update(int o,int l,int r,int pos,int x)
{
    if(l==r)
    {
        if(pos&1) vb[o]=x,vc[o]=K;
        else vb[o]=K,vc[o]=x;
        return ;
    }
    int mid=l+r>>1;
    push_down(o);
    if(pos<=mid) update(o<<1,l,mid,pos,x);
    else update(o<<1|1,mid+1,r,pos,x);
    vb[o]=min(vb[o<<1],vb[o<<1|1]);
    vc[o]=min(vc[o<<1],vc[o<<1|1]);
}
void update2(int o,int l,int r,int nl,int nr)
{
    if(l==nl&&r==nr)
    {
        ff[o]^=1;swap(vb[o],vc[o]);
        return ;
    }
    int mid=l+r>>1;
    push_down(o);
    if(nr<=mid) update2(o<<1,l,mid,nl,nr);
    else if(nl>mid) update2(o<<1|1,mid+1,r,nl,nr);
    else update2(o<<1,l,mid,nl,mid),update2(o<<1|1,mid+1,r,mid+1,nr);
    vb[o]=min(vb[o<<1],vb[o<<1|1]);
    vc[o]=min(vc[o<<1],vc[o<<1|1]);
}
int query(int o,int l,int r,int nl,int nr,int x)
{
    if(l==nl&&r==nr)
    {
        if(x==1) return vb[o];
        else return vc[o];
    }
    int mid=l+r>>1;
    push_down(o);
    if(nr<=mid) return query(o<<1,l,mid,nl,nr,x);
    else if(nl>mid) return query(o<<1|1,mid+1,r,nl,nr,x);
    else return min(query(o<<1,l,mid,nl,mid,x),query(o<<1|1,mid+1,r,mid+1,nr,x));
}
void add(set<vector<int>> &st,int a,int b,int c,int d)
{
    vector<int>t;
    t.PB(a),t.PB(b),t.PB(c),t.PB(d);
    st.insert(t);
}
