struct pair_t {
	using S = min_t<ll>;
	using T = min_t<ll>;
	S first;
	T second;

	static pair_t zero() { return pair_t(S(), T()); }
	pair_t() {}
	pair_t(S f, T s) : first(f), second(s) {}
	bool is_zero() const { return first.is_zero() && second.is_zero(); }
	pair_t operator+ (const pair_t& r) const {
		if (is_zero()) return r;
		else if (r.is_zero()) return *this;
		pair_t ret;
		ret.first = first + r.first;
		ret.second = second + r.second;
		return ret;
	}
};

struct lazy_t {
	ll add;
	lazy_t() {}
	lazy_t(ll add) : add(add) {}
	static lazy_t zero() {
		return{ 1 };
	}
	bool is_zero() const {
		return add == 1;
	}
	//lazy_t operator+ (lazy_t& to) {
	lazy_t go_down(const lazy_t& to) {
		if (is_zero()) return to;
		if (to.is_zero()) return *this;
		lazy_t ret;
		ret.add = to.add * add;
		return ret;
	}
	pair_t resolve(const pair_t& val, int l, int r) {
		if (is_zero()) return val;
		if (add == 0) {
			return pair_t((ll)1e8, (ll)1e8);
		} else if (add == -1) {
			return pair_t(val.second.val, val.first.val);
		}
	}
};

class lazy_seg_tree {
	using val_t = pair_t;

	vector<val_t> dat;
	vector<lazy_t> lazy;
	int n;

	void propagate(int i) {
		dat[i] = dat[i * 2 + 1] + dat[i * 2 + 2];
	}

	void propagate_if_lazy(int k, int l, int r) {
		if (lazy[k].is_zero()) return;
		dat[k] = lazy[k].resolve(dat[k], l, r);
		lazy[2 * k + 1] = lazy[k].go_down(lazy[2 * k + 1]);
		lazy[2 * k + 2] = lazy[k].go_down(lazy[2 * k + 2]);
		lazy[k] = lazy_t::zero();
	}

	val_t query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return val_t::zero();
		if (a <= l && r <= b) return lazy[k].resolve(dat[k], l, r);

		propagate_if_lazy(k, l, r);
		const int m = (l + r) / 2;
		val_t vl = query(a, b, 2 * k + 1, l, m);
		val_t vr = query(a, b, 2 * k + 2, m, r);
		return vl + vr;
	}

	val_t update(int a, int b, lazy_t x, int k, int l, int r) {
		if (r <= a || b <= l) return lazy[k].resolve(dat[k], l, r);
		if (a <= l && r <= b) {
			lazy[k] = x.go_down(lazy[k]);
			return lazy[k].resolve(dat[k], l, r);
		}

		propagate_if_lazy(k, l, r);
		const int m = (l + r) / 2;
		val_t vl = update(a, b, x, 2 * k + 1, l, m);
		val_t vr = update(a, b, x, 2 * k + 2, m, r);
		return dat[k] = vl + vr;
	}

public:
	lazy_seg_tree(vector<pair_t>& vals) {
		n = 1;
		while (n < sz(vals)) n <<= 1;
		dat.assign(2 * n - 1, val_t::zero());
		lazy.assign(2 * n - 1, lazy_t::zero());
		for (int i = 0; i < sz(vals); i++) dat[n - 1 + i] = vals[i];
		for (int i = n - 2; i >= 0; i--) propagate(i);
	}

	val_t query(int a, int b) {
		return query(a, b, 0, 0, n);
	}

	void update(int a, int b, lazy_t x) {
		update(a, b, x, 0, 0, n);
	}
};
