		ans.push_back(qa1.first.val);
		int a1idx = val2idx[qa1.first.val];
		auto it = ranges.lower_bound(a1idx);
		if (it == ranges.end() || it->first != a1idx) {
			--it;
		}

		pair_t qa2 = lst.query(a1idx, it->second);
		ans.push_back(qa2.second.val);
		int a2idx = val2idx[qa2.second.val];

		lst.update(a1idx, a1idx + 1, 0);
		lst.update(a2idx, a2idx + 1, 0);
		lst.update(a1idx + 1, a2idx, -1);

		vector<Pii> nranges;
		nranges.emplace_back(it->first, a1idx);
		nranges.emplace_back(a1idx + 1, a2idx);
		nranges.emplace_back(a2idx + 1, it->second);
		ranges.erase(it);
		for (auto& nt : nranges) {
			if (nt.first != nt.second) {
				ranges[nt.first] = nt.second;
			}
		}
	}
	writerArr(ans);

	return 0;
}

