void update1(ll k , ll a){
  k += N/2-1;
  dat1[k] = a;
  while(k > 0){
    k = (k-1)/2;
    dat1[k] = min(dat1[k*2 + 1],dat1[k*2 + 2]);
  }
}

void update2(ll k , ll a){
  k += N/2-1;
  dat2[k] = a;
  while(k > 0){
    k = (k-1)/2;
    dat2[k] = min(dat2[k*2 + 1],dat2[k*2 + 2]);
  }
}

//get min of [a,b)
