ll query1(ll a, ll b , ll k , ll l , ll r){
  if(r <= a || b <= l) return INF;
  if(a <= l && r <= b) return dat1[k];
  else{
    ll vl = query1(a,b,k*2+1,l,(l+r)/2);
    ll vr = query1(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
