void lazify(ll i,ll s,ll e)
{
	if(lazy[i])
	{
		swap(tree[i][0],tree[i][1]);
		if(s!=e)
		{
			lazy[2*i]^=lazy[i];
			lazy[2*i+1]^=lazy[i];
		}
		lazy[i]=0;
	}
}
void upd_flip(ll l,ll r,ll s,ll e,ll i)
{	
	lazify(i,s,e);
	if(s>r||e<l||l>r)return;
	if(s>=l&&e<=r)
	{
		lazy[i]^=1;
		lazify(i,s,e);
		return;
	}
	ll mid=(s+e)>>1;
	upd_flip(l,r,s,mid,2*i);
	upd_flip(l,r,mid+1,e,2*i+1);
	tree[i][0]=min(tree[2*i][0],tree[2*i+1][0]);
	tree[i][1]=min(tree[2*i][1],tree[2*i+1][1]);
}
pll query(ll l,ll r,ll s,ll e,ll i)
{
	if(s>r||e<l)return mp(INF,0);
	lazify(i,s,e);
	if(s>=l&&e<=r)return tree[i][0];
	ll mid=(s+e)>>1;
	return min(query(l,r,s,mid,2*i),query(l,r,mid+1,e,2*i+1));
}
pll query1(ll l,ll r,ll s,ll e,ll i)
{
	if(s>r||e<l)return mp(INF,INF);
	lazify(i,s,e);
	if(s>=l&&e<=r)return tree[i][1];
	ll mid=(s+e)>>1;
	return min(query1(l,r,s,mid,2*i),query1(l,r,mid+1,e,2*i+1));
}
void upd(ll l,ll s,ll e,ll i)
{
	lazify(i,s,e);
	if(s>l||e<l)return;
	if(s>=l&&e<=l)
	{
		tree[i][l%2]=mp(INF,l);
		tree[i][1-(l%2)]=mp(INF,l);
		return;
	}
	ll mid=(s+e)>>1;
	upd(l,s,mid,2*i);
	upd(l,mid+1,e,2*i+1);
	tree[i][0]=min(tree[2*i][0],tree[2*i+1][0]);
	tree[i][1]=min(tree[2*i][1],tree[2*i+1][1]);
}
void build(ll l,ll r,ll i)
{
	if(l==r)
	{
		tree[i][(l%2)]=mp(a[l],l);
		tree[i][1-(l%2)]=mp(INF,0);
		return;
	}
	ll mid=(l+r)>>1;
	build(l,mid,2*i);
	build(mid+1,r,2*i+1);
	tree[i][0]=min(tree[2*i][0],tree[2*i+1][0]);
	tree[i][1]=min(tree[2*i][1],tree[2*i+1][1]);
}
