void build(int v, int tl, int tr){
	if(tl == tr){
		a[tl % 2][v].f = p[tl];
		a[tl % 2][v].s = tl;
		a[1 - tl % 2][v].f = n + 1;
		return;
	}
	int tm = (tl + tr) >> 1;
	build(v + v, tl, tm);
	build(v + v + 1, tm + 1, tr);
	a[0][v] = min(a[0][v + v], a[0][v + v + 1]);
	a[1][v] = min(a[1][v + v], a[1][v + v + 1]);
}

void push(int v){
	add[v] %= 2;
	if(add[v] == 0)
		return;
	swap(a[0][v + v], a[1][v + v]);
	swap(a[0][v + v + 1], a[1][v + v + 1]);
	add[v + v]++;
	add[v + v + 1]++;
	add[v] = 0;
}

pii get(int v, int tl, int tr, int l, int r, int c){
	if(r < tl || tr < l)
		return mp(n + 1, 0);
	if(l <= tl && tr <= r)
		return a[c][v];
	int tm = (tl + tr) >> 1;
	push(v);
	pii res = min(get(v + v, tl, tm, l, r, c), get(v + v + 1, tm + 1, tr, l, r, c));
	a[0][v] = min(a[0][v + v], a[0][v + v + 1]);
	a[1][v] = min(a[1][v + v], a[1][v + v + 1]);
	return res;
}

void updpos(int v, int tl, int tr, int pos){
	if(tl == tr){
		a[0][v].f = a[1][v].f = n + 1;
		return;
	}
	int tm = (tl + tr) >> 1;
	if(pos <= tm)
		updpos(v + v, tl, tm, pos);
	else updpos(v + v + 1, tm + 1, tr, pos);
	a[0][v] = min(a[0][v + v], a[0][v + v + 1]);
	a[1][v] = min(a[1][v + v], a[1][v + v + 1]);
}

void upd(int v, int tl, int tr, int l, int r){
	if(r < tl || tr < l)
		return;
	if(l <= tl && tr <= r){
		add[v]++;
		swap(a[0][v], a[1][v]);
		return;
	}
	int tm = (tl + tr) >> 1;
	push(v);
	upd(v + v, tl, tm, l, r);
	upd(v + v + 1, tm + 1, tr, l, r);
	a[0][v] = min(a[0][v + v], a[0][v + v + 1]);
	a[1][v] = min(a[1][v + v], a[1][v + v + 1]);
}

int solve(int l, int r){
	if(l > r)
		return 0;
	int L = get(1, 1, n, l, r, l % 2).s;
	int R = get(1, 1, n, L + 1, r, 1 - l % 2).s;
	pa[p[L]] = p[R];
	g[p[L]].pb(solve(l, L - 1));
	g[p[L]].pb(solve(L + 1, R - 1));
	g[p[L]].pb(solve(R + 1, r));
	return p[L];

}

