struct segment_tree {
	int mod, t[2*MAX];
	void build() {
		for(int i = 0; i < n; i++) t[i + n] = (i % 2 == mod ? p[i] : INT_MAX);
		for(int i = n-1; i >= 1; i--) t[i] = min(t[i<<1], t[i<<1|1]);
	}
	int query(int l, int r) {
		++r;
		int ret = INT_MAX;
		for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if(l & 1) ret = min(t[l++], ret);
			if(r & 1) ret = min(t[--r], ret);
		}
		return ret;
	}
} st[2];

pii getxy(int l, int r) {
	int x = st[l % 2].query(l, r);
	int y = st[l % 2 ^ 1].query(pos[x]+1, r);
	return make_pair(-x, -y);
}

