	if(v[Min[k][l][LLOG]]<v[Min[k][r-(1<<LLOG)+1][LLOG]])
		return Min[k][l][LLOG];
	else
		return Min[k][r-(1<<LLOG)+1][LLOG];
}
void chk(vector<int>&V,int l,int r)
{
	if(l>r)
		return ;
	int ll,rr,i,j,k;
	ll=query(l&1,(l>>1)+1,((r-1)>>1)+1);
	rr=query(r&1,((ll+1)>>1)+1,(r>>1)+1);
	vector<int>vv;
	chk(V,l,ll-1);
	chk(V,ll+1,rr-1);
	chk(V,rr+1,r);
	i=l;
	j=ll+1;
	k=rr+1;
	vv.push_back(V[ll]);
	vv.push_back(V[rr]);
	while(i<=ll-1||j<=rr-1||k<=r)
	{
		if(i<=ll-1&&(j>rr-1||V[i]<=V[j])&&(k>r||V[i]<=V[k]))
		{
			vv.push_back(V[i++]);
			vv.push_back(V[i++]);
		}
		else if(j<=rr-1&&(i>ll-1||V[j]<=V[i])&&(k>r||V[j]<=V[k]))
		{
			vv.push_back(V[j++]);
			vv.push_back(V[j++]);
		}
		else if(k<=r&&(i>ll-1||V[k]<=V[i])&&(j>rr-1||V[k]<=V[j]))
		{
			vv.push_back(V[k++]);
			vv.push_back(V[k++]);
		}
	}
	for(i=0;i<vv.size();i++)
		V[i+l]=vv[i];
	return ;
}
