{
	int n=v.size()>>1,i,j,k;
	for(i=1;i<=n;i++)
		LOG[i]=LOG[i-1]+(i>(1<<(LOG[i-1]+1)));
	for(k=0;k<2;k++)
		for(j=0;j<n;j++)
			Min[k][j+1][0]=j<<1|k;
	for(k=0;k<2;k++)
		for(i=1;i<=LOG[n];i++)
			for(j=1;j<=n;j++)
				if(j+(1<<(i-1))<=n)
