void push(int v)
{
	if (flag[v])
		{
			swap(t[v*2][0],t[v*2][1]);
			swap(t[v*2+1][0],t[v*2+1][1]);
			flag[v*2]^=1;
			flag[v*2+1]^=1;
			flag[v]=0;
		}
}

pair<int,int> better(pair<int,int> p1,pair<int,int> p2){
	if (p1.first!=p2.first)
	{
		if (p1.first<p2.first)
			return p1;
		return p2;
	}
	return p1;
}

pair<int,int> get(int v,int tl,int tr,int l,int r,int rem){
	if (l>r)
		return make_pair(1e9,-1);
	if (tl==l&&tr==r)
		return t[v][rem];
	push(v);
	int tm=tl+tr;
	tm/=2;
	return better(get(v*2,tl,tm,l,min(r,tm),rem),get(v*2+1,tm+1,tr,max(tm+1,l),r,rem));
}

void run_kill(int v,int tl,int tr,int ps)
{
	if (tl==tr)
	{
		t[v][0]=t[v][1]=make_pair(1000000000,-1);
		return;
	}
	push(v);
	int tm=tl+tr;
	tm/=2;
	if (ps<=tm)
		run_kill(v*2,tl,tm,ps);
	else
		run_kill(v*2+1,tm+1,tr,ps);
	for (int i=0;i<2;i++)
	{
		t[v][i]=better(t[v*2][i],t[v*2+1][i]);
	}
}

void update(int v,int tl,int tr,int l,int r)
{
	if (l>r)
		return;
	if (tl==l&&tr==r)
	{
		swap(t[v][0],t[v][1]);
		flag[v]^=1;
		return;
	}
	push(v);
	int tm=tl+tr;
	tm/=2;
	update(v*2,tl,tm,l,min(r,tm));
	update(v*2+1,tm+1,tr,max(tm+1,l),r);
	for (int i=0;i<2;i++)
	{
		t[v][i]=better(t[v*2][i],t[v*2+1][i]);
	}
}

void kill(int ps)
{
	blockers.insert(ps);
	//cout<<"@@@"<<ps<<endl;

	update(1,1,n,ps+1,n);
	run_kill(1,1,n,ps);
}

void build(int v,int tl,int tr)
{
	if (tl==tr)
	{
		t[v][tl%2]=make_pair(ar[tl],tl);
		t[v][1-tl%2]=make_pair(1e9,-1);
		return;
	}
	int tm=tl+tr;
	tm/=2;
	build(v*2,tl,tm);
	build(v*2+1,tm+1,tr);
	for (int i=0;i<2;i++)
	{
		t[v][i]=better(t[v*2][i],t[v*2+1][i]);
	}
}

