pair < int, int > f(pair < int, int > x, pair < int, int > y){
    if (x.F < y.F){
        return {x.F, min(y.F, x.S)};
    } else
        return {y.F, min(y.S, x.F)};
}
void build(int k, int v, int tl, int tr){
    if (tl == tr){
        t[k][v].F = p[k][tl];
        t[k][v].S = 1e7;
        return;
    }
    int mid = (tl + tr) / 2;
    build(k, v + v, tl, mid);
    build(k, v + v + 1, mid + 1, tr);
    t[k][v] = f(t[k][v + v], t[k][v + v + 1]);
}
pair < int, int > query(int k, int v, int tl, int tr, int l, int r){
    if (l > r) return {1e7, 1e7};
    if (l == tl && r == tr) return t[k][v];
    int mid = (tl + tr) / 2;
    auto p1 = query(k, v + v, tl, mid, l, min(r, mid));
    auto p2 = query(k, v + v + 1, mid + 1, tr, max(l, mid + 1), r);
    return f(p1, p2);
}
pair < int, int > f(int l, int rr){
  // cout << l << " -- " << rr << endl;
    pair < int, int > res;
    if (l >= rr){
        return {1e7, 1e7};
    }
    auto x = query(l % 2, 1, 1, n, (l + 1) / 2, (rr + 1) / 2);
    x.F = r[x.F];
    if (x.S != 1e7)
    x.S = r[x.S];
    if (x.F + 1 > rr){
        res.F = x.S;
    } else
        res.F = x.F;
   // cout << "res.F = " << res.F << " " << (res.F + 1) / 2 + (res.F % 2 == 0) << " " << (rr + 1) /2 << " " << ((res.F % 2) ^ 1) << endl;
    x = query(((res.F % 2) ^ 1), 1, 1, n, (res.F + 1) / 2 + (res.F % 2 == 0), (rr + 1) / 2);
    res.S = r[x.F];
    res.F = a[res.F];
    res.S = a[res.S];
    return res;
}
