const int inf=LLONG_MAX/3;

struct SegTree{
	vector<pi> buf;
	int s;
	SegTree(int n){
		s=1;
		while(s<n)s*=2;
		buf.assign(s*2,pi(inf,-1));
	}
	void Update(int i,pi v){
		i+=s;
		buf[i]=v;
		while(i>>=1)
			buf[i]=min(buf[i*2],buf[i*2+1]);
	}
	pi Get(int b,int e,int l,int r,int i){
		if(e<=l||r<=b)return pi(inf,-1);
		if(b<=l&&r<=e)return buf[i];
		return min(Get(b,e,l,(l+r)/2,i*2),Get(b,e,(l+r)/2,r,i*2+1));
	}
	pi Get(int b,int e){
		if(e<=b)return pi(inf,-1);
		return Get(b,e,0,s,1);
	}
};

