void RMQ_init()
{
    logs[0]=-1;for(int i=1;i<=n;i++)logs[i]=logs[i>>1]+1;
    for(int i=1;i<=n;i++){if(i&1)d1[i][0]=A[i];else d1[i][0]=inf;p1[i][0]=i;}
