    }
}
int RMQ(int x,int l,int r)
{
    int K=logs[r-l+1];
    if(x==1)return d1[l][K]<d1[r-(1<<K)+1][K]?p1[l][K]:p1[r-(1<<K)+1][K];
    return d2[l][K]<d2[r-(1<<K)+1][K]?p2[l][K]:p2[r-(1<<K)+1][K];
}
