Q query1(int a,int b,int k,int l,int r){
//	cout<<a<<" "<<b<<" "<<k<<" "<<l<<" "<<r<<endl;
	if(r<=a||b<=l)return Q(INF,INF);
	if(a<=l&&r<=b)return seg1[k];
