}

void build(int v,int tl,int tr)
{
   // cout << v << " " << tl << " " << tr << endl;
    if (tl == tr)
    {
        t[v].f = t[v].s = p[tl];
        t[v].len = 1;
        t[v].fp = t[v].sp = tl;
    }
    else
    {
        int tm = (tl+tr)/2;
        build(v*2,tl,tm);
        build(v*2+1,tm+1,tr);
        t[v] = combine(t[v*2], t[v*2+1]);
    }
    //cout << "-" << endl;
}

node query(int v,int tl,int tr,int l,int r)
{
   // cout << v << " " << tl << " " << tr << " " << l << " " << r << endl;

    if (tl == l && tr == r)
    {
        return t[v];
    }
    else
    {
        int tm = (tl+tr)/2;
        if (tm >= r)
        {
            return query(v*2,tl,tm,l,r);
        }

        if (tm < l)
        {
            return query(v*2+1,tm+1,tr,l,r);
        }
        return  combine(query(v*2,tl,tm,l,tm), query(v*2+1,tm+1,tr,tm+1,r));
    }
}

void solve(int l,int r,int pr)
{
    if (l >= r) return;
    node q1 = query(1, 1, n, l, r);
    node q2 = query(1,1,n, q1.fp + 1, r);
   // cout << l << " "<< r << ": " << q1.fp << " " << q2.fp << endl;
    ans.push_back(make_pair(pr, make_pair(p[q1.fp], p[q2.fp])));
    solve(l, q1.fp - 1, pr+1);
    solve(q1.fp+1, q2.fp-1,pr+1);
    solve(q2.fp+1,r,pr+1);
}

