struct treap {
    int v, y, sz, mn;
    treap *l, *r;

    treap(int v) : v(v), y(rand()), sz(1), mn(v), l(0), r(0) {};
};

using ptreap = treap*;

int get_sz(ptreap t) {
    if (!t) {
        return 0;
    }
    return t->sz;
}

int get_mn(ptreap t) {
    if (!t) {
        return 1e9;
    }
    return t->mn;
}

void recalc(ptreap t) {
    if (!t) {
        return;
    }
    t->sz = get_sz(t->l) + get_sz(t->r) + 1;
    t->mn = min(t->v, min(get_mn(t->l), get_mn(t->r)));
}

ptreap* split(ptreap t, int x) {
    if (!t) {
        return new ptreap[2] {0, 0};
    }
    int q = get_sz(t->l);
    ptreap* r;
    if (x <= q) {
        r = split(t->l, x);
        t->l = r[1];
        r[1] = t;
    } else {
        r = split(t->r, x - q - 1);
        t->r = r[0];
        r[0] = t;
    }
    recalc(t);
    return r;
}

ptreap merge(ptreap l, ptreap r) {
    if (!l || !r) {
        return l ? l : r;
    }

    ptreap t;
    if (l->y < r->y) {
        l->r = merge(l->r, r);
        t = l;
    } else {
        r->l = merge(l, r->l);
        t = r;
    }
    recalc(t);
    return t;
}

int find_min(ptreap t) {
    assert(t != nullptr);
    if (t->mn == t->v) {
        return get_sz(t->l);
    }
    if (t->mn == get_mn(t->l)) {
        return find_min(t->l);
    }
    return find_min(t->r) + get_sz(t->l) + 1;
}

