#include <bits/stdc++.h>
using namespace std;

#define N 400001
#define INF 2e9
int maxi[N*4],lazy[N*4];

int seg[N*4][2];
int pen[N],in[N],ind[N];
void init(int pos,int l,int r) {
    lazy[pos] = -1;
    if(l==r) {
        seg[pos][0] = seg[pos][1] = INF;
        int bit = l&1;
        seg[pos][bit] = in[l];
        if(bit&1) {
            maxi[pos] = in[l];
        } else {
            maxi[pos] = INF;
        }
        return;
    }
    int mid = (l+r)/2;
    init(pos*2,l,mid);
    init(pos*2+1,mid+1,r);
    seg[pos][0] = min(seg[pos*2][0],seg[pos*2+1][0]);
    seg[pos][1] = min(seg[pos*2][1],seg[pos*2+1][1]);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
void push(int pos,int l,int r) {
    if(lazy[pos]!=-1) {
        maxi[pos] = seg[pos][lazy[pos]];
        if(l!=r) {
            lazy[pos*2] = lazy[pos*2+1] = lazy[pos];
        }
        lazy[pos] = -1;
    }
}
void updateE(int pos,int l,int r,int ind,int v) {
    push(pos,l,r);
    if(r<ind || ind<l) {
        return;
    }
    if(l==r) {
        maxi[pos] = v;
        seg[pos][0] = seg[pos][1] = v;
        return;
    }
    int mid = (l+r)/2;
    updateE(pos*2,l,mid,ind,v);
    updateE(pos*2+1,mid+1,r,ind,v);
    seg[pos][0] = min(seg[pos*2][0],seg[pos*2+1][0]);
    seg[pos][1] = min(seg[pos*2][1],seg[pos*2+1][1]);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
void update(int pos,int l,int r,int ql,int qr,int v) {
    push(pos,l,r);
    if(r<ql || qr<l) {
        return;
    }
    if(ql<=l && r<=qr) {
        lazy[pos] = v;
        push(pos,l,r);
        return;
    }
    int mid = (l+r)/2;
    update(pos*2,l,mid,ql,qr,v);
    update(pos*2+1,mid+1,r,ql,qr,v);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
int getMaxi(int pos,int l,int r,int ql,int qr,int bit) {
    if(r<ql || qr<l) {
        return INF;
    }
    if(ql<=l && r<=qr) {
        return seg[pos][bit];
    }
    int mid = (l+r)/2;
    return min(getMaxi(pos*2,l,mid,ql,qr,bit),getMaxi(pos*2+1,mid+1,r,ql,qr,bit));
}
void update(int ind,int v) {
    while(ind<N) {
        pen[ind] += v;
        ind += ind&(-ind);
    }
}
int query(int ind) {
    int ret = 0;
    while(ind>0) {
        ret += pen[ind];
        ind = ind&(ind-1);
    }
    return ret;
}
int ret[N];
void solve() {
    //input
    int n;scanf("%d",&n);
    for(int i=1;i<=n;++i) {
        scanf("%d",&in[i]);
        ind[in[i]] = i;
    }
    //pre cal
    init(1,1,n);
    int pos = 0;
    //solve
    while(pos<n) {
        int x = maxi[1];
        int index = ind[x];
        int q = query(index);
        int y = 0,cur = 0;
        for(int i = 20;i>=0;--i) {
            int ny = y + (1<<i);
            if(ny<=n && cur + pen[ny] <=q) {
                y = ny;
                cur += pen[ny];
            }
        }
        y = getMaxi(1,1,n,index,y,y&1);
        if(y==INF) {
            printf("-1\n");
            return;
        }
        y = ind[y];
        update(index,1);
        update(y,1);
        x = index;
        updateE(1,1,n,x,INF);
        updateE(1,1,n,y,INF);
        if(x+1<=y-1) {
            update(1,1,n,x+1,y-1,q);
        }
        ret[pos++] = in[x];
        ret[pos++] = in[y];
    }
    //output
    for(int i=0;i<n;++i) {
       printf("%d ",ret[i]);
    }
    putchar('\n');
}
int main() {
    solve();
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 100005;

struct Node {
  int val[3];
  Node() {
    val[0] = val[1] = val[2] = INT_MAX;
  }
};

int a[N], m[N];

struct S {
  int l, r, val;
  bool operator < (const S &b) const {
    return val > b.val;
  }
};

int n;
Node seg[N << 2];

void add(int id, int l, int r, int loc, int data) {
  if (l == r) {
    seg[id].val[loc & 1] = data;
    seg[id].val[2] = data;
    return ;
  }
  int mid = (l + r) >> 1;
  if (loc <= mid) {
    add(id << 1, l, mid, loc, data);
  }
  else {
    add(id << 1 | 1, mid + 1, r, loc, data);
  }
  seg[id].val[0] = min(seg[id << 1].val[0], seg[id << 1 | 1].val[0]);
  seg[id].val[1] = min(seg[id << 1].val[1], seg[id << 1 | 1].val[1]);
  seg[id].val[2] = min(seg[id << 1].val[2], seg[id << 1 | 1].val[2]);
}

int query(int id, int l, int r, int ll, int rr, int flag) {
  if (l == ll && r == rr) {
    return seg[id].val[flag];
  }
  int mid = (l + r) >> 1;
  if (mid >= rr) {
    return query(id << 1, l, mid, ll, rr, flag);
  }
  if (mid < ll) {
    return query(id << 1 | 1, mid + 1, r, ll, rr, flag);
  }
  return min(query(id << 1, l, mid, ll, mid, flag), query(id << 1 | 1, mid + 1, r, mid + 1, rr, flag));
}

int main() {
  scanf("%d", &n);
  for (int i = 1; i <= n; ++i) {
    scanf("%d", &a[i]);
    m[a[i]] = i;
    add(1, 1, n, i, a[i]);
  }
  a[n + 1] = INT_MAX;
  priority_queue<S> q;
  q.push({1, n, query(1, 1, n, 1, n, 1)});
  vector<int> res;
  while (!q.empty()) {
    S s = q.top();
    q.pop();
    res.push_back(s.val);
    int now = m[s.val];
    int go = query(1, 1, n, now + 1, s.r, (now & 1) ^ 1);
    res.push_back(go);
    go = m[go];
    if (now > s.l) {
      q.push({s.l, now - 1, query(1, 1, n, s.l, now - 1, s.l & 1)});
    }
    if (now + 1 < go) {
      q.push({now + 1, go - 1, query(1, 1, n, now + 1, go - 1, (now + 1) & 1)});
    }
    if (go < s.r) {
      q.push({go + 1, s.r, query(1, 1, n, go + 1, s.r, (go + 1) & 1)});
    }
  }
  for (int i = 0; i < n ; ++i) {
    printf("%d%c", res[i], i < n - 1 ? ' ' : '\n');
  }
  return 0;
}

