		int c = rev[a.Fi], d = rev[a.Se];
		if(b.Fi + 1 < c) T.push(make_pair(get(b.Fi, c), pii(b.Fi, c)));
		if(c+1 < d) T.push(make_pair(get(c, d), pii(c, d)));
		if(d+1 < b.Se) T.push(make_pair(get(d, b.Se), pii(d, b.Se)));
	}
}

