class SegmentTree {
public:
  P Storage[1<<18]; // 0=> value 1=> index
  int N;
  void init(int n) {
    N=1;
    while(N<n) N*=2;

    for(int i=0;i<N*2;++i) {
      Storage[i].first=INF;
      Storage[i].second=0;
    }
  }

  void updateLeaf(int i, int value) {
    i += N-1;
    Storage[i].first=value;
    Storage[i].second=i-(N-1);
    while(i>0) {
      i = (i-1) / 2;
      Storage[i] = min(Storage[i*2+1], Storage[i*2+2]);
    }
  }

  P getMin(int a,int b,int k,int l, int r) {
    if(b<=l || a>=r) return P(INF, 0);
    if(a<=l && b>=r) {
      return Storage[k];
    } else {
      P tl = getMin(a,b,k*2+1,l,(l+r)/2);
      P tr = getMin(a,b,k*2+2,(l+r)/2,r);
      return min(tl,tr);
    }
  }
};

