const int MAXN = 2e5;
const pii INF = {1e9, 1e9};
struct node {
    pii x, mn; // {val, ind}
    int y;
    node * left = nullptr, * right = nullptr;
    node() {}
    node(pii _x) : x(_x), mn(_x), y(rand()) {}
} nodes[MAXN];
int ffr = 0;
typedef node * pnode;

void update(pnode v) {
    if (!v) return;
    v->mn = min({v->left ? v->left->mn : INF, v->right ? v->right->mn : INF, v->x});
}

pnode merge(pnode left, pnode right) {
    if (!left) return right;
    if (!right) return left;
    if (left->y > right->y) {
        left->right = merge(left->right, right);
        update(left);
        return left;
    } else {
        right->left = merge(left, right->left);
        update(right);
        return right;
    }
}

pair<pnode, pnode> split(pnode tree, int x) {
    if (!tree) return {tree, tree};
    if (tree->x.ss > x) {
        auto tmp = split(tree->left, x);
        tree->left = tmp.ss;
        update(tree);
        return {tmp.ff, tree};
    } else {
        auto tmp = split(tree->right, x);
        tree->right = tmp.ff;
        update(tree);
        return {tree, tmp.ss};
    }
}

pnode pushback(pnode tree, pii x) {
    pnode xptr = &(nodes[ffr++] = node(x));
    return merge(tree, xptr);
}

vector<int> g[MAXN];
vector<pii> ps;

int build(pnode even, pnode odd) {
    int num = ps.size();
    // dbg(num);
    pii mne = even->mn;
    auto tmp_odd = split(odd, mne.ss);
    pii mno = tmp_odd.ss->mn;

    ps.pb(mne.ff, mno.ff);
    auto tmp_odd2 = split(tmp_odd.ss, mno.ss);
    auto tmp_odd3 = split(tmp_odd2.ff, mno.ss - 1);

    auto odd1 = tmp_odd.ff;
    auto odd2 = tmp_odd3.ff;
    auto odd3 = tmp_odd2.ss;

    auto tmp_even = split(even, mne.ss);
    auto tmp_even2 = split(tmp_even.ff, mne.ss - 1);
    auto tmp_even3 = split(tmp_even.ss, mno.ss);

    auto even1 = tmp_even2.ff;
    auto even2 = tmp_even3.ff;
    auto even3 = tmp_even3.ss;

    if (even1) 
        g[num].pb(build(even1, odd1));
    if (even2) 
        g[num].pb(build(odd2, even2));
    if (even3) 
        g[num].pb(build(even3, odd3));

    return num;
}

