ll segTreeOdds[4*MAXN], segTreeEvens[4*MAXN];


void initSegTree(ll * arr, ll * segtree, int at, int from, int to) {
  if (from > to) {
    return;
  }
  if (from == to) {
    segtree[at] = arr[from];
    return;
  }
  int mid = (from + to) / 2;
  initSegTree(arr, segtree, 2*at, from, mid);
  initSegTree(arr, segtree, 2*at+1, mid+1, to);
  segtree[at] = min(segtree[2*at], segtree[2*at+1]);
}


ll querySegTree(ll * segtree, int at, int from, int to, int ql, int qr) {
  if (from > to) {
    return INF;
  }
  if (to < ql || qr < from) {
    return INF;
  }
  if (ql <= from && to <= qr) {
    return segtree[at];
  }
  int mid = (from + to) / 2;
  return min(querySegTree(segtree, 2*at, from, mid, ql, qr), querySegTree(segtree, 2*at+1, mid+1, to, ql, qr));
}


void updateSegTree(ll * segtree, int at, int from, int to, int pos, ll val) {
  if (from == to) {
    segtree[at] = val;
    return;
  }
  int mid = (from + to) / 2;
  if (pos <= mid) {
    updateSegTree(segtree, 2*at, from, mid, pos, val);
  } else {
    updateSegTree(segtree, 2*at+1, mid+1, to, pos, val);
  }
  segtree[at] = min(segtree[2*at], segtree[2*at+1]);
}


