  initSegTree(evens, segTreeEvens, 1, 1, N);
}


void solve() {
  set < pair<ll, pair<int, int> > > Q;
  Q.insert({querySegTree(segTreeOdds, 1, 1, N, 1, N), {1, N}});
  while (!Q.empty()) {
    int l = Q.begin()->second.first;
    int r = Q.begin()->second.second;
    //cerr << "L = " << l << ", R = " << r << "\n";
    Q.erase(Q.begin());
    int idL, idR;
    ll v1 , v2;
    if (l % 2 == 1) {
      v1 = querySegTree(segTreeOdds, 1, 1, N, l, r);
      idL = valToPos[v1];
      v2 = querySegTree(segTreeEvens, 1, 1, N, idL, r);
      idR = valToPos[v2];
      updateSegTree(segTreeOdds, 1, 1, N, idL, INF);
      updateSegTree(segTreeEvens, 1, 1, N, idR, INF);
    } else {
      v1 = querySegTree(segTreeEvens, 1, 1, N, l, r);
      idL = valToPos[v1];
      v2 = querySegTree(segTreeOdds, 1, 1, N, idL, r);
      idR = valToPos[v2];
      updateSegTree(segTreeEvens, 1, 1, N, idL, INF);
      updateSegTree(segTreeOdds, 1, 1, N, idR, INF);
    }
    //cerr << "V1 = " << v1 << ", V2 = " << v2 << ", idL = " << idL << ", idR = " << idR << "\n";

    cout << v1 << " " << v2 << " ";

    bool inBetween = false;
    if (idL + 1 < idR) {
      //cerr << "Putting stuff in between\n";
      inBetween = true;
      if (idL+1 % 2 == 1) {
        Q.insert({querySegTree(segTreeOdds, 1, 1, N, idL+1, idR-1), {idL+1, idR-1}});
      } else {
        Q.insert({querySegTree(segTreeEvens, 1, 1, N, idL+1, idR-1), {idL+1, idR-1}});
      }
    }
    if (inBetween) {
      if (l < idL) {
        //cerr << "Putting stuff before\n";
        if (l % 2 == 1) {
          Q.insert({querySegTree(segTreeOdds, 1, 1, N, l, idL-1), {l, idL-1}});
        } else {
          Q.insert({querySegTree(segTreeEvens, 1, 1, N, l, idL-1), {l, idL-1}});
        }
      }
      if (idR + 1 < r) {
        //cerr << "Putting stuff after\n";
        if (idR+1 % 2 == 1) {
          Q.insert({querySegTree(segTreeOdds, 1, 1, N, idR+1, r), {idR+1, r}});
        } else {
          Q.insert({querySegTree(segTreeEvens, 1, 1, N, idR+1, r), {idR+1, r}});
        }
      }
    } else {
      if (querySegTree(segTreeOdds, 1, 1, N, l, r) == INF) {
        continue;
      }
      if (l % 2 == 1) {
        Q.insert({querySegTree(segTreeOdds, 1, 1, N, l, r), {l, r}});
      } else {
        Q.insert({querySegTree(segTreeEvens, 1, 1, N, l, r), {l, r}});
      }
    }
  }
}


