                                  [](P a, P b){return b;}, mk(inf, inf), pv0);
  seg[1] = SegmentTree<P, P>(n, [](P a, P b){return min(a, b);},
                                  [](P a, P b){return b;}, mk(inf, inf), pv1);

  auto find = [&](int l, int r) -> pair<P, P>{
    auto p = seg[l&1].query(l, r - 1);
    int m = p.second;
    auto p2 = seg[(1-l&1)].query(m+1, r);
    int m2 = p2.second;
    return mk(mk(p.first, p2.first), (mk(m, m2)));
  };
  // (first, second), [l, r)
  using PPP = pair<pair<P, P>, P>;
  priority_queue<PPP, vector<PPP>, greater<PPP>> pq;
  pq.push(mk(find(0, n), mk(0, n)));
  vector<int> res; res.reserve(n);
  while(!pq.empty()){
    auto q = pq.top(); pq.pop();
