    l[2] = q2.second + 1, r[2] = q.second.second;
    rep(i, 3){
      if(l[i] >= r[i])continue;
      pq.push(mk(find(l[i], r[i]), mk(l[i], r[i])));
    }
  }
  rep(i, n)res[i]++;
  cout << res << endl;
  return 0;
}

