qj make(int l,int r,int mnl,int mnr,bool type)
{
	qj a;
	a.l=l;a.r=r;a.mnl=mnl;a.mnr=mnr;a.type=type;
	return a;
}
void builda(int l,int r,int node)
{
	if (l==r) odd[node]=make_pair(a[l],l);
	else
	{
		int mid=(l+r)/2;
		builda(l,mid,node*2);
		builda(mid+1,r,node*2+1);
		odd[node]=min(odd[node*2],odd[node*2+1]);
	}
}
void buildb(int l,int r,int node)
{
	if (l==r) even[node]=make_pair(b[l],l);
	else
	{
		int mid=(l+r)/2;
		buildb(l,mid,node*2);
		buildb(mid+1,r,node*2+1);
		even[node]=min(even[node*2],even[node*2+1]);
	}
}
pair<int,int> querya(int beg,int en,int l,int r,int node)
{
	if (l>en || r<beg) return make_pair(1e9,1e9);
	if (l>=beg && r<=en) return odd[node];
	int mid=(l+r)/2;
	return min(querya(beg,en,l,mid,node*2),querya(beg,en,mid+1,r,node*2+1));
}
pair<int,int> queryb(int beg,int en,int l,int r,int node)
{
	if (l>en || r<beg) return make_pair(1e9,1e9);
	if (l>=beg && r<=en) return even[node];
	int mid=(l+r)/2;
	return min(queryb(beg,en,l,mid,node*2),queryb(beg,en,mid+1,r,node*2+1));
}
