const int MAX_N = 300010;
int n;
template<class V, int NV> struct SegTree{
    V comp(V l, V r) {return min(l, r);};

    vector<V> dat;

    SegTree() {
        dat = vector<V>(MAX_N, {INF, INF});
        n = 1;
        while(n < NV) n *= 2;
        rep(i, 2 * n - 1) dat[i] = {INF, INF};
    }

    // k番目の値(0-indexed)をaに変更
    void update(int k, V a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = comp(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    // [a, b)の最小値を探す．
    V query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return {INF, INF};
        if(a <= l && r <= b) return dat[k];
        else {
            V vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            V vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(vl, vr);
        }
    }
};
