#include <bits/stdc++.h>

#define MAX_N 200001
#define INF 0x3FFFFFFF

using namespace std;

struct interval {
  int l, r;
  int val;
};

bool operator<(const interval &a, const interval &b) {
  return a.val > b.val;
}

int a[MAX_N], idx[MAX_N], even[4 * MAX_N], odd[4 * MAX_N];

void initEven(int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (X == Y) { even[k] = X & 1 ? INF : a[X]; return; }
  int M = (X + Y) / 2;
  initEven(2 * k + 1, X, M);
  initEven(2 * k + 2, M + 1, Y);
  even[k] = min(even[2 * k + 1], even[2 * k + 2]);
}

void initOdd(int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (X == Y) { odd[k] = X & 1 ? a[X] : INF; return; }
  int M = (X + Y) / 2;
  initOdd(2 * k + 1, X, M);
  initOdd(2 * k + 2, M + 1, Y);
  odd[k] = min(odd[2 * k + 1], odd[2 * k + 2]);
}

int query(int *tree, int x, int y, int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (x <= X && Y <= y) return tree[k];
  if (y < X || Y < x) return INF;
  int M = (X + Y) / 2;
  return min(query(tree, x, y, 2*k+1, X, M), query(tree, x, y, 2*k+2, M+1, Y));
}

void addInterval(priority_queue<interval> &pq, int l, int r) {
  if (l < r) {
    if (l & 1) pq.push(interval {l, r, query(odd, l, r - 1)});
    else pq.push(interval {l, r, query(even, l, r - 1)});
  }
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
    idx[a[i]] = i;
  }
  initEven();
  initOdd();
  priority_queue<interval> pq;
  pq.push(interval {1, n, query(odd, 1, n - 1)});
  vector<int> result;
  while (!pq.empty()) {
    interval iv = pq.top();
    pq.pop();

    result.push_back(iv.val);
    int second;
    if (idx[iv.val] & 1) second = query(even, idx[iv.val] + 1, iv.r);
    else second = query(odd, idx[iv.val] + 1, iv.r);
    result.push_back(second);

    addInterval(pq, iv.l, idx[iv.val] - 1);
    addInterval(pq, idx[iv.val] + 1, idx[second] - 1);
    addInterval(pq, idx[second] + 1, iv.r);
  }
  for (int r : result) printf("%d ", r);
  printf("\n");
  return 0;
}

