int n;  // array size
PII t[2 * N][2];

void modify(int p, int value, bool sel) {  // set value at position p
	int pos = p;
	for (t[p += n][sel] = MP(value, pos); p > 1; p >>= 1) t[p >> 1][sel] = min(t[p][sel], t[p ^ 1][sel]);
}

PII query(int l, int r, bool sel) {  // min on interval [l, r)
	PII res = MP(inf, n);
	for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
		if (l & 1) res = min(res, t[l++][sel]);
		if (r & 1) res = min(res, t[--r][sel]);
	}
	return res;
}

vector <int> g[N];

int id;

PII M[N];

int go(int p, int k)
{
	if (p >= k)
		return -1;

	auto q = query(p, k, p & 1);

	vector < vector<int> > V;

	auto pom = query(q.second, k, 1 - (p & 1));

	int myid = id++;

	M[myid] = MP(q.first, pom.first);

	int v = go(p, q.second);
	if(v != -1)
		g[myid].push_back(v);

	v = go(q.second + 1, pom.second);
	if(v != -1)
		g[myid].push_back(v);

	v = go(pom.second + 1, k);
	if (v != -1)
		g[myid].push_back(v);

	return myid;
}

