		int i, j, k;
		N = n;
		for (k = 0, i = 1; i <= N; i++) {
			if (i == bit(k + 1)) k++;
			b[i] = k;
		}
		for (i = 0; i < N; i++) x[i][0] = p[i];
		for (j = 1; j <= k; j++) {
			for (i = 0; i < N; i++) {
				x[i][j] = x[i][j - 1];
				if (i + bit(j - 1) < N)
					chkmin(x[i][j],  x[i + bit(j  -  1)][j  -  1]);
			}
		}
	}
//return min value between [st, en)
	int range_min(int st, int en) {
		int j = b[en - st];
		return min(x[st][j], x[en - bit(j)][j]);
	}
} m[2];

