	if(l == r) return ;
	int val_min = m[l % 2].range_min(l / 2, (r - 1) / 2 + 1);
	int pos1 = pos[val_min];
	val_min = m[(pos1 + 1) % 2].range_min((pos1 + 1) / 2, r / 2 + 1);
	int pos2 = pos[val_min];
	pii rlt = {p[pos1], p[pos2]};
	ans.push_back(make_pair(rlt, par));
	if(l < pos1 - 1) calc(l, pos1 - 1, rlt);
	if(pos1 + 1 < pos2 - 1) calc(pos1 + 1, pos2 - 1, rlt);
	if(r > pos2 + 1) calc(pos2 + 1, r, rlt);
}
