  if(t1.first==t2.first){
    if(t1.second<t2.second)return 1;
    else if(t1.second==t2.second)return 2;//same
  }
  return 0;
}

vector<pii> func(int s, int g, vi a){
  vector<pii> ret;
  if(s==g)return ret;
  int i,j,k,m1,m2;
  for(i=m1=s;i<g;i+=2)if(a[m1]>a[i])m1=i;
  for(i=m2=m1+1;i<g;i+=2)if(a[m2]>a[i])m2=i;
  ret.push_back(pii(a[m1],a[m2]));
  vector<pii> t1,t2,t3;
  t1=func(s,m1,a);
  t2=func(m1+1,m2,a);
  t3=func(m2+1,g,a);
  for(i=j=k=0;i<t1.size()||j<t2.size()||k<t3.size();){
    if(i<t1.size() && (j==t2.size()||check(t1[i],t2[j])==1) && (k==t3.size()||check(t1[i],t3[k])==1)){//min:t1
      ret.push_back(t1[i]);
      i++;
    }
    if(j<t2.size() && (i==t1.size()||check(t2[j],t1[i])==1) && (k==t3.size()||check(t2[j],t3[k])==1)){//min:t2
      ret.push_back(t2[j]);
      j++;
    }
    if(k<t3.size() && (j==t2.size()||check(t3[k],t2[j])==1) && (i==t1.size()||check(t3[k],t1[i])==1)){//min:t3
      ret.push_back(t3[k]);
      k++;
    }
  }
  return ret;
}

