typedef pair<int, int> pi;

vector<int> p, inv;

pi millor(pi x) {
  int millor = 1e9;
  for (int i = x.first; i < x.second; i++) {
    if (p[i] < millor and (i-x.first)%2 == 0)
      millor = p[i];
  }
  int segon = 1e9;
  for (int j = inv[millor]+1; j < x.second; j++)
    if (p[j] < segon and (x.second-j)%2 == 1)
      segon = p[j];
  return pi(millor,segon);
}

