      v = min(l->v, r->v);
    }
  }
  void up(int x, int val){
    if (s == e){
      v = val;
      return;
    }
    if (x <= m)l->up(x,val);
    else r->up(x,val);
    v = min(l->v, r->v);
  }
  int query(int a, int b){
    if (a == s && b == e)return v;
    if (b <= m)return l->query(a,b);
    if (a > m)return r->query(a,b);
    return min(l->query(a,m), r->query(m+1, b));
  }
} *odd, *even, *all;

int fw[200100];
void update(int x, int v){
  ++x;
  for (;x<=N;x+=x&(-x))fw[x]+=v;
}

int remain(int x){
  ++x;
  int res = 0;
  for (;x;x-=x&(-x))res+=fw[x];
  return res;
}

