    // cerr<<"Check " << curval << ' '<<curind <<' '<<remain(curind) <<'\n';
    if (done.find(curind) != done.end())continue; // Already taken
    if (remain(curind)%2)continue; // Odd number left on left side
    int abv = (*done.ub(curind)) - 1;
    // cout<<"Index " << curind<<' '<<curval<<'\n';
    int minval;
    if (curind%2==0){
