class SegmentTree
{
    int a[2][Nmax<<2];

    public:
    void build(int node, int st, int dr)
    {
        if(st == dr)
        {
            if(st&1) a[1][node] = val[st], a[0][node] = n+1;
                else a[0][node] = val[st], a[1][node] = n+1;
            return;
        }

        build(left_son, st, mid); build(right_son, mid+1, dr);
        a[0][node] = min(a[0][left_son], a[0][right_son]);
        a[1][node] = min(a[1][left_son], a[1][right_son]);
    }

    int query(int node, int st, int dr)
    {
        if(Left <= st && dr <= Right) return a[qr][node];

        int ans1 = n+1, ans2 = n+1;
        if(Left <= mid) ans1 = query(left_son, st, mid);
        if(mid < Right) ans2 = query(right_son, mid+1, dr);
        return min(ans1, ans2);
    }
} aint;

