pair<int, int> getmin (pair<int, int>* t, int v, int tl, int tr, int l, int r) {
	if (l > r)
		return {1000000000, -1};
	if (l == tl && r == tr)
		return t[v];
	int tm = (tl + tr) / 2;

    pair<int, int> res0 = getmin(t, v*2, tl, tm, l, min(r,tm));
	pair<int, int> res1 = getmin(t, v*2+1, tm+1, tr, max(l,tm+1), r);
    if (res0.first < res1.first) return res0;
    else return res1;
}


void update (pair<int, int> *t, int v, int tl, int tr, int pos, int new_val) {
	if (tl == tr)
    {
		t[v].first = new_val;
		t[v].second = tl;
    }
	else {
		int tm = (tl + tr) / 2;
		if (pos <= tm)
			update (t, v*2, tl, tm, pos, new_val);
		else
			update (t, v*2+1, tm+1, tr, pos, new_val);

		if (t[v*2].first < t[v*2+1].first)
        {
            t[v].first = t[v*2].first;
            t[v].second = t[v*2].second;
        }
        else
        {
            t[v].first = t[v*2+1].first;
            t[v].second = t[v*2+1].second;
        }
	}
}

int solve(int l, int r, int p)
{
    if (l < r) return -1;
    int i = idx;
    idx++;

    int ll = getmin(a[p], 1, 0, n-1, l, r).second;
    int rr = getmin(a[1-p], 1, 0, n-1, ll, r).second;
    hj[i].a = getmin(a[p], 1, 0, n-1, l, r).first;
    hj[i].b = getmin(a[1-p], 1, 0, n-1, ll, r).first;

    hj[i].next[0] = solve(p, 0, ll-1);
    hj[i].next[1] = solve(1-p, ll, rr-1);
    hj[i].next[2] = solve(p, rr+1, n-1);

    return i;
}


