		rev[t] = false;
		if (l == r) {
			val[0][t] = val[1][t] = INF;
			st[t] = l & 1, val[l & 1][t] = a[l];
		} else {
			int z = (l + r) >> 1;
			build(ls, l, z), build(rs, z + 1, r);
			up(t);
		}
