		down(t);
		int z = (l + r) >> 1, ret = INF;
		if (L <= z) ret = min(ret, qry(ls, l, z, L, R, x));
		if (R > z) ret = min(ret, qry(rs, z + 1, r, L, R, x));
		up(t);
		return ret;
	}
	int qryst(int t, int l, int r, int P) {
		if (l == r) return st[t];
		down(t);
		int z = (l + r) >> 1, ret;
		if (P <= z) ret = qryst(ls, l, z, P);
		else ret = qryst(rs, z + 1, r, P);
		up(t);
		return ret;
	}
	int qrymin(int t, int l, int r, int L, int R) {
		if (L > R) return INF;
		if (L <= l && r <= R) return min(val[0][t], val[1][t]);
		down(t);
		int z = (l + r) >> 1, ret = INF;
		if (L <= z) ret = min(ret, qrymin(ls, l, z, L, R));	
		if (R > z) ret = min(ret, qrymin(rs, z + 1, r, L, R));
		up(t);
		return ret;
	}
} seg;
void dfs(int l, int r) {
	int x = seg.qrymin(1, 1, n, l, r), y;		
	if (x >= INF) return ;
	dd(x), de(y);
}
void bfs() {
	priority_queue<pair<int, pair<int, int> > > que;
	que.push(mp(-1, mp(1, n)));
	while (!que.empty()) {
		int x = -que.top().fi, y;
		int l = que.top().se.fi;
		int r = que.top().se.se;
		que.pop();
		if (x >= INF) continue;
		int st = seg.qryst(1, 1, n, p[x]);	
		if (st & 1) {
			y = seg.qry(1, 1, n, p[x] + 1, r, 0);
		} else {
			y = seg.qry(1, 1, n, l, p[x] - 1, 1);	
		}
		if (p[x] < p[y]) {
			printf("%d %d ", x, y);
		} else {
			printf("%d %d ", y, x);
		}
		seg.updval(1, 1, n, p[x], INF);	
		seg.updval(1, 1, n, p[y], INF);	
		seg.upd(1, 1, n, p[x], n);
		seg.upd(1, 1, n, p[y], n);	
		pair<int, pair<int, int> > seq[3];
		if (p[x] < p[y]) {
			int lv = seg.qrymin(1, 1, n, l, p[x] - 1);
			int mv = seg.qrymin(1, 1, n, p[x], p[y]);
			int rv = seg.qrymin(1, 1, n, p[y] + 1, r);
			seq[0] = mp(lv, mp(l, p[x] - 1));
			seq[1] = mp(mv, mp(p[x] + 1, p[y] - 1));
			seq[2] = mp(rv, mp(p[y] + 1, r));
		} else {
			int lv = seg.qrymin(1, 1, n, l, p[y] - 1);
			int mv = seg.qrymin(1, 1, n, p[y], p[x]);
			int rv = seg.qrymin(1, 1, n, p[x] + 1, r);
			seq[0] = mp(lv, mp(l, p[y] - 1));
			seq[1] = mp(mv, mp(p[y] + 1, p[x] - 1));
			seq[2] = mp(rv, mp(p[x] + 1, r));
		}
		sort(seq, seq + 3);
		rep(i, 0, 3)
			que.push(mp(-seq[i].fi, seq[i].se));
	}
}
