vector<pii> rec(const int a, const int b, const SegmentTree<Min_Plus>& oddseg, const SegmentTree<Min_Plus>& evenseg)  // [a, b)
{
    if (a >= b) {
        return vector<pii>{};
    }
    if (a < 0) {
        return vector<pii>{};
    }
    if (b > N) {
        return vector<pii>{};
    }
    assert(a % 2 == b % 2);
    const bool left_even = a % 2 == 0;
    const auto& dom_oddseg = (left_even) ? oddseg : evenseg;
    const auto& dom_evenseg = (left_even) ? evenseg : oddseg;

    const int dom_evenmin = dom_evenseg.accumulate(a / 2, b / 2);
    const int dom_evenmin_ind = rev[dom_evenmin];
    // show(dom_evenmin + 1);
    // show(dom_evenmin_ind);
    const int dom_oddmin = dom_oddseg.accumulate((dom_evenmin_ind + 1) / 2, (b + 1) / 2);
    const int dom_oddmin_ind = rev[dom_oddmin];
    // show(dom_oddmin + 1);
    // show(dom_oddmin_ind);


    vector<pii> result{make_pair(dom_evenmin + 1, dom_oddmin + 1)};
    vector<pii> p1 = rec(a, dom_evenmin_ind, oddseg, evenseg);
    vector<pii> p2 = rec(dom_evenmin_ind + 1, dom_oddmin_ind, oddseg, evenseg);
    vector<pii> p3 = rec(dom_oddmin_ind + 1, b, oddseg, evenseg);

    if (not p1.empty()) {
        if (not p2.empty()) {
            if (not p3.empty()) {
                vector<pii> p12;
                merge(p1.begin(), p1.end(), p2.begin(), p2.end(), back_inserter(p12));
                merge(p12.begin(), p12.end(), p3.begin(), p3.end(), back_inserter(result));
                return result;
            } else {
                merge(p1.begin(), p1.end(), p2.begin(), p2.end(), back_inserter(result));
                return result;
            }
        } else {
            if (not p3.empty()) {
                merge(p1.begin(), p1.end(), p3.begin(), p3.end(), back_inserter(result));
                return result;
            } else {
                result.insert(result.end(), p1.begin(), p1.end());
                return result;
            }
        }
    } else {
        if (not p2.empty()) {
            if (not p3.empty()) {
                merge(p2.begin(), p2.end(), p3.begin(), p3.end(), back_inserter(result));
                return result;
            } else {
                result.insert(result.end(), p2.begin(), p2.end());
                return result;
            }
        } else {
            if (not p3.empty()) {
                result.insert(result.end(), p3.begin(), p3.end());
                return result;
            } else {
                return result;
            }
        }
    }
}

