void chk(int *V,int l,int r)
{
	if(l>r)
		return ;
	int ll,rr,i,j,k;
	ll=query(l&1,(l>>1)+1,((r-1)>>1)+1);
	rr=query(r&1,((ll+1)>>1)+1,(r>>1)+1);
