	while(i<=ll-1||j<=rr-1||k<=r)
	{
		if(i<=ll-1&&(j>rr-1||V[i]<=V[j])&&(k>r||V[i]<=V[k]))
		{
			vv.push_back(V[i++]);
			vv.push_back(V[i++]);
		}
		else if(j<=rr-1&&(i>ll-1||V[j]<=V[i])&&(k>r||V[j]<=V[k]))
