const int maxn = (int) 2e5 + 17;

int nn;

struct segtree
{
	vector< pair<int, int> > T;
	segtree() { }

	segtree(int n)
	{
		nn = n;
		T.resize(4 * n);

		forn (i, 4 * n)
			T[i] = make_pair((int) inf, (int) inf);
	}

	void upd(int i, int x, int v = 1, int l = 0, int r = nn - 1)
	{
		if (l == r)
			T[v] = make_pair(x, i);
		else
		{
			int m = (l + r) / 2;
			i <= m ? upd(i, x, 2 * v, l, m) : upd(i, x, 2 * v + 1, m + 1, r);
			T[v] = min(T[2 * v], T[2 * v + 1]);
		}
	}

	pair<int, int> get(int lq, int rq, int v = 1, int l = 0, int r = nn - 1)
	{
		if (l > rq || r < lq)
			return make_pair(inf, inf);

		if (lq <= l && r <= rq)
			return T[v];

		int m = (l + r) / 2;
		return min(get(lq, rq, 2 * v, l, m), get(lq, rq, 2 * v + 1, m + 1, r));
	}
};

int n;
int p[maxn];
vector< pair<int, int> > pp[maxn];
segtree ev, od;

bool read()
{
	if (scanf("%d", &n) != 1)
		return false;

	forn (i, n)
		scanf("%d", p + i);

	return true;
}

void go(int lq, int rq, int h)
{
	if (lq >= rq)
		return ;

	pair<int, int> ft, sc;

	if (lq & 1 ^ 1)
	{
		ft = ev.get(lq, rq);
		sc = od.get(ft.second, rq);
	}
	else
	{
		ft = od.get(lq, rq);
		sc = ev.get(ft.second, rq);
	}

	pp[h].push_back(make_pair(ft.first, sc.first));
	go(lq, ft.second - 1, h + 1);
	go(ft.second + 1, sc.second - 1, h + 1);
	go(sc.second + 1, rq, h + 1);
}

void solve()
{
	ev = od = segtree(n);

	forn (i, n)
		if (i & 1)
		{
			od.upd(i, p[i]);
			ev.upd(i, inf);
		}
		else
		{
			ev.upd(i, p[i]);
			od.upd(i, inf);
		}

	go(0, n - 1, 0);

	forn (i, n)
	{
