struct tree{
  int t[N * 4], pos[N * 4];
  void build(int *a, int v, int tl, int tr){
    if(tl == tr){
      t[v] = a[tl];
      pos[v] = tl;
      return;
    }
    int tm = (tl + tr) >> 1;
    build(a, v * 2, tl, tm);
    build(a, v * 2 + 1, tm + 1, tr);
    t[v] = min(t[v * 2], t[v * 2 + 1]);
    pos[v] = (t[v * 2] < t[v * 2 + 1] ? pos[v * 2] : pos[v * 2 + 1]);
  }

  pii get(int v, int tl, int tr, int l, int r){
    if(l > r){
      return {inf, inf};
    }
    if(l == tl && r == tr){
      return make_pair(t[v], pos[v]);
    }
    int tm = (tl + tr) >> 1;
    pii a = get(v * 2, tl, tm, l, min(r, tm));
    pii b = get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
    return min(a, b);
  }
}t1, t2;

