      p2[i] = inf;
    } else{
      p2[i] = p[i];
      p1[i] = inf;
    }
  }
  t1.build(p1, 1, 1, n);
  t2.build(p2, 1, 1, n);
  s.insert(make_pair(get(1, n), make_pair(1, n)));
  while(!s.empty()){
    int l = (*s.begin()).second.first;
    int r = (*s.begin()).second.second;
    s.erase(s.begin());
    int id1, id2;
    if(l % 2){
      id1 = t1.get(1, 1, n, l, r).second;
      id2 = t2.get(1, 1, n, id1, r).second;
    } else{
      id1 = t2.get(1, 1, n, l, r).second;
      id2 = t1.get(1, 1, n, id1, r).second;
    }
    assert(id1 != id2 && id1 < id2);
    ans.push_back(p[id1]);
    ans.push_back(p[id2]);
    if(id1 > l){
      s.insert({get(l, id1 - 1), {l, id1 - 1}});
    }
    if(id1 + 1 <= id2 - 1){
      s.insert({get(id1 + 1, id2 - 1), {id1 + 1, id2 - 1}});
    }
    if(id2 < r){
      s.insert({get(id2 + 1, r), {id2, r}});
    }
  }
  for(int i : ans){
    printf("%d ", i);
  }
  return 0;
}

