void build(int n, int *A, int st[][20]) {
  for (int i = 0; i < n; ++i)
    st[i][0] = i;
  for (int j = 1, k = 2; k <= n; ++j, k <<= 1)
    for (int i = 0; i + k <= n; ++i) {
      int a = st[i][j - 1], b = st[i + k / 2][j - 1];
      st[i][j] = A[a] < A[b] ? a : b;
    }
}
int get(int *A, int st[][20], int l, int r) {
  int d = 1, k = 0;
  while ((d << 1) <= r - l + 1) d <<= 1, ++k;
  int a = st[l][k], b = st[r - d + 1][k];
  return A[a] < A[b] ? a : b;
}
int solve(int l, int r) {
  if (l > r) return -1;
  int ansl = get(a[l & 1], st[l & 1], l / 2, (r - 1) / 2);
  int ansr = get(a[~l & 1], st[~l & 1], ansl + (l & 1), r / 2);
  ansl = ansl * 2 + (l & 1), ansr = ansr * 2 + (~l & 1);
  nxt[ansl] = ansr;
  son[ansl][0] = solve(l, ansl - 1);
  son[ansl][1] = solve(ansl + 1, ansr - 1);
  son[ansl][2] = solve(ansr + 1, r);
  return ansl;
}
