struct node{
	int p, sz, v, best, midx;
	node* l;
	node* r;
	node(int v): best(v), midx(0), v(v), p(rand()), l(NULL), r(NULL), sz(1){}
};
int best(node *t){
	if(t == NULL) return 1e7;
	return t->best;
}

int sz(node *t){
	if(t == NULL) return 0;
	return t->sz;
}

int midx(node *t){
	if(t == NULL) return 0;
	return t->midx;
}
void updsz(node *t){
	if(t == NULL) return;
	t->sz = sz(t->l)+sz(t->r)+1;
	t->best = min(t->v,min(best(t->l),best(t->r)));
	if(t->best == t->v){
		t->midx = sz(t->l);
	} else if(t->best == best(t->l)){
		t->midx = midx(t->l);
	} else if(t->best == best(t->r)){
		t->midx = sz(t->l) + 1 + midx(t->r);
	}
}
void split(node *t, node *& l, node *& r, int k){//k on left
	if(t == NULL){
		l = r = NULL;
	} else if(sz(t->l) >= k){
		split(t->l,l,t->l,k);
		r = t;
	} else {
		split(t->r, t->r, r, k-1-sz(t->l));
		l = t;
	}
	updsz(t);
}
void merge(node *&t, node *l, node *r){
	if(l == NULL){
		t = r;
	} else if(r == NULL){
		t = l;
	} else if(l -> p <= r -> p){
		merge(l->r,l->r,r);
		t = l;
	} else {
		merge(r->l,l,r->l);
		t = r;
	}
	updsz(t);
}
void ins(node *&t, node *c, int k){
	if(t == NULL){
		t = c;
	} else if(c->p >= t->p){
		split(t,c->l,c->r,k);
		t = c;
	} else if(sz(t->l) >= k){
		ins(t->l,c,k);
	} else {
		ins(t->r,c,k-1-sz(t->l));
	}
	updsz(t);
}
void del(node *&t, int k){
	if(t == NULL){
		return;
	}
	if(sz(t->l) == k){
		merge(t,t->l,t->r);
	} else if(sz(t->l) > k){
		del(t->l,k);
	} else {
		del(t->r,k);
	}
	updsz(t);
}
void pt(node *t){
	if(t == NULL) return;
	pt(t->l);
	cout << t->v << " ";
	pt(t->r);
}

