using namespace std;

typedef pair<int,int> P;
typedef pair<P,P> PP;
#define INF (2*100000+1000)

class SegmentTree {
public:
  P Storage[1<<20]; // 0=> value 1=> index
  int N;
  void init(int n) {
    N=1;
    while(N<n) N*=2;

    for(int i=0;i<N*2;++i) {
      Storage[i].first=INF;
      Storage[i].second=0;
    }
  }

  void updateLeaf(int i, int value) {
    i += N-1;
    Storage[i].first=value;
    Storage[i].second=i-(N-1);
    while(i>0) {
      i = (i-1) / 2;
      Storage[i] = min(Storage[i*2+1], Storage[i*2+2]);
    }
  }

  P getMin(int a,int b,int k,int l, int r) {
    if(b<=l || a>=r) return P(INF, 0);
    if(a<=l && b>=r) {
      return Storage[k];
    } else {
      P tl = getMin(a,b,k*2+1,l,(l+r)/2);
      P tr = getMin(a,b,k*2+2,(l+r)/2,r);
      return min(tl,tr);
    }
  }
};

SegmentTree evenTree;
SegmentTree oddTree;
priority_queue<PP, vector<PP>, greater<PP> > Q;
int N;

int main() {
  scanf("%d", &N);
  evenTree.init(N);
  oddTree.init(N);
  for(int i=0;i<N;++i) {
    int p;
    scanf("%d", &p);
    if(i%2==0) {
      evenTree.updateLeaf(i, p);
    } else {
      oddTree.updateLeaf(i, p);
    }
  }
  vector<int> answer;

  Q.push(PP(evenTree.getMin(0,N,0,0,evenTree.N),P(0, N)));
  while(!Q.empty()) {
    PP pp=Q.top();Q.pop();
    P range = pp.second;
    int index=pp.first.second;
    answer.push_back(pp.first.first);
    P minValue;
    if (index%2==0) {
      minValue=oddTree.getMin(index+1, range.second,0,0,oddTree.N);
    } else {
      minValue=evenTree.getMin(index+1, range.second,0,0,evenTree.N);
    }
    answer.push_back(minValue.first);
    P newRanegs[]={
      P(range.first, pp.first.second),
      P(pp.first.second+1, minValue.second),
      P(minValue.second+1, range.second)
    };
    for(int i=0;i<3;++i) {
      P r=newRanegs[i];
      if(r.second==r.first) continue;
      P v;
      if(r.first%2==0) {
        v=evenTree.getMin(r.first,r.second,0,0,evenTree.N);
      } else {
        v=oddTree.getMin(r.first,r.second,0,0,oddTree.N);
      }
      Q.push(PP(v, r));
    }
  }

  for(int i=0;i<N;++i) {
    printf("%d ", answer[i]);
  }
  printf("\n");


  return 0;
}

