    for (bool sp=0; begin!=end; ++begin) { if (sp) putchar(' '); else sp = true; printf(fmt, *begin); }
    putchar('\n');
}
template<class T> struct IRMQ {
    static const int npos = -1;

    int n, g; T *d;
    IRMQ() : n(0), g(0), d(NULL) {}
    template<class Iter> IRMQ(Iter begin, Iter end) : n(0), g(0), d(0) { build(begin, end); }
    IRMQ(const IRMQ &y) : n(y.n), g(0), d(NULL) { if (y.n) build(y.d[0], y.d[0] + n); }
    IRMQ(IRMQ &&y) : n(0), g(0), d(NULL) { swap(*this, y); }
    ~IRMQ() { if (n) { n = 0; delete d; d = NULL; } }
    friend void swap(IRMQ &x, IRMQ &y) { swap(x.n, y.n); swap(x.g, y.g); swap(x.d, y.d); }
    IRMQ& operator=(IRMQ y) { swap(*this, y); return *this; }

    template<class Iter> void build(Iter begin, Iter end) { // random access iterator
	n = end - begin;
	if (n == 0) return;
	g = __lg(n);
	d = new T[n*(g+1)];
	REP (i, n) { d[i] = *begin; ++begin; }
	for (int t=0, b=0; t<g; t++, b+=n) for (int i=0, j=1<<t; j<=n-(1<<t); i++, j++)
	    d[b+n+i] = (d[b+j] < d[b+i]? d[b+j]: d[b+i]);
    }

    const T at(int i) const { return d[i]; }

    const T min_v(int l, int r) const {
	int h = __lg(r - l), b = n * h;
	r -= 1<<h;
	return d[b+r] < d[b+l]? d[b+r]: d[b+l];
    }

    int min_i(int l, int r) const {
	return first_less_equal(l, min_v(l, r));
    }

    // for i in [l .. n-1]:
    //   if at(i) < v: return i;
    // return npos;
    int first_less_than(int l, const T v) const {
	for (int t=g+1; t--; )
	    if (l + (1<<t) <= n && !(d[n*t+l] < v))
		l += 1 << t;
	return l<n? l: npos;
    }

    // for i in [l .. n-1]:
    //   if at(i) <= v: return i;
    // return npos;
    int first_less_equal(int l, const T v) const {
	for (int t=g+1; t--; )
	    if (l + (1<<t) <= n && v < d[n*t+l])
		l += 1 << t;
	return l<n? l: npos;
    }

    // for i in [r-1 .. 0]:
    //   if at(i) < v: return i;
    // return npos;
    int last_less_than(int r, const T v) const {
	for (int t=g+1; t--; )
	    if (0 <= r - (1<<t) && !(d[n*t+r-(1<<t)] < v))
		r -= 1 << t;
	return r? r-1: npos;
    }

    // for i in [r-1 .. 0]:
    //   if at(i) < v: return i;
    // return npos;
    int last_less_equal(int r, const T v) const {
	for (int t=g+1; t--; )
	    if (0 <= r - (1<<t) && v < d[n*t+r-(1<<t)])
		r -= 1 << t;
	return r? r-1: npos;
    }
};

int N;
int A[200011];
int E[200011], O[200011];

void MAIN() {
    scanf("%d", &N);
    REP (i, N) scanf("%d", A+i);

    REP (i, N) {
	E[i] = O[i] = 1<<29;
	if (i&1) O[i] = A[i];
	else E[i] = A[i];
    }
    using Tuple = tuple<int, int, int>;
    IRMQ<int> E_rmq(E, E+N);
    IRMQ<int> O_rmq(O, O+N);

    VI ans; ans.reserve(N);
    priority_queue<Tuple> Q;
    Q.emplace(-1, 0, N);

    auto push = [&](int l, int r) {
	if (l + 1 >= r) return;
	if (l % 2 == 0) {
	    Q.emplace(-E_rmq.min_v(l, r), l, r);
	} else {
	    Q.emplace(-O_rmq.min_v(l, r), l, r);
	}
    };

    while (!Q.empty()) {
	int dummy, l, r;
	tie(dummy, l, r) = Q.top(); Q.pop();
	int pos1, pos2;
	if (l % 2 == 0) {
	    pos1 = E_rmq.min_i(l, r);
	    pos2 = O_rmq.min_i(pos1, r);
	} else {
	    pos1 = O_rmq.min_i(l, r);
	    pos2 = E_rmq.min_i(pos1, r);
	}
	ans.push_back(A[pos1]);
	ans.push_back(A[pos2]);
	push(l, pos1);
	push(pos1+1, pos2);
	push(pos2+1, r);
    }

    rprintf("%d", ans.begin(), ans.end());
}

