const int MAX_N = 2 * 131072;
int o[MAX_N * 2 - 1], e[MAX_N * 2 - 1];

void update(int* arr, int n, int i, int x) {
    i += MAX_N - 1;
    arr[i] = x;
    while (i > 0) {
        i = (i - 1) / 2;
        arr[i] = std::min(arr[i * 2 + 1], arr[i * 2 + 2]);
    }
}

// minimum value of [a, b)
int query(int* arr, int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return INT_MAX;
    if (a <= l && r <= b) return arr[k];
    else {
        int vl = query(arr, a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(arr, a, b, k * 2 + 2, (l + r) / 2, r);
        return std::min(vl, vr);
    }
}

