    function<vector<P>(int,int)> solve=[&](int l,int r){
        if(l>=r) return vector<P>(0);
        P fs,sc;
        if(l%2){
            fs=od.query(l,r);
            sc=ev.query(fs.second,r);
        }else{
            fs=ev.query(l,r);
            sc=od.query(fs.second,r);
        }
        vector<P> lv,cv,rv,v;
        v.push_back({fs.first,sc.first});
        lv=solve(l,fs.second);
        cv=solve(fs.second+1,sc.second);
        rv=solve(sc.second+1,r);
        int il=0,ic=0,ir=0;
        while(il<lv.size() or ic<cv.size() or ir<rv.size()){
            P lval=(il<lv.size()?lv[il]:P(INF,INF)),cval=(ic<cv.size()?cv[ic]:P(INF,INF)),rval=(ir<rv.size()?rv[ir]:P(INF,INF));
            if(lval<cval and lval<rval){
                v.push_back(lval);il++;
            }else if(cval<lval and cval<rval){
                v.push_back(cval);ic++;
            }else if(rval<lval and rval<cval){
                v.push_back(rval);ir++;
            }
        }
        return v;
    };

    auto ans=solve(0,n);
    rep(i,n/2) cout<<ans[i].first<<" "<<ans[i].second<<(i+1==n/2?"\n":" ");
    return 0;
}

