void dfs(int L, int R, int pa = 0) {
    //cout <<"*"<< L << " " << R << endl;
    pair<int, int> mi1, mi2;
    // 区間が2であれば、ペアが確定
    if (L + 1 == R) {
        E[pa].push_back(p[L]);
        pR[p[L]] = p[R];
        return;
    }

    if (L % 2 == 0) {
        mi1 = st1.query(L, R, 0, 0, n);
        mi2 = st2.query(mi1.second + 1, R + 1, 0, 0, n);
    } else {
        mi1 = st2.query(L, R, 0, 0, n);
        mi2 = st1.query(mi1.second + 1, R + 1, 0, 0, n);
    }
    int i = mi1.second;
    int j = mi2.second;
    //cout << mi1.first << " " << mi2.first << endl;
    //ペアが決まったので、代入
    E[pa].push_back(mi1.first);
    pR[mi1.first] = mi2.first;
    //cout << "OK" << endl;
    if (L != i) dfs(L, i - 1, mi1.first);
    if (i + 1 != j) dfs(i + 1, j - 1, mi1.first);
    if (R != j) dfs(j + 1, R, mi1.first); 

}

