const int INF = 1e9;

struct BIT{
    int n;
    VL bit;

    BIT(){}
    BIT(int x){
        n = x;
        bit.resize(x+1);
    }

    void init(int x){
        n = x;
        bit.resize(x+1);
    }

    void add(int i, ll x){
        i++;
        while (i <= n){
            bit[i] += x;
            i += i & -i;
        }
    }

    // [0, i]
    ll sum(int i){
        i++;
        ll ret = 0;
        while (i > 0){
            ret += bit[i];
            i -= i & -i;
        }
        return ret;
    }

    // [l, r)
    ll sum(int l, int r){
        if (l >= r) return 0;
        return sum(r-1) - sum(l-1);
    }
};


struct SegmentTree{
    int n, width;
    VI dat[2];
    BIT bit;

    void init(int x){
        n = x;
        dat[0].resize(4*n);
        dat[1].resize(4*n);
        width = 1;
        while(width < n) width *= 2;
        REP(j,2) REP(i,2*width-1) dat[j][i] = INF;
        bit.init(n);
    }

    void update(int i, int x, int k){
        i += width-1;
        dat[k][i] = x;
        while (i>0){
            i = (i-1)/2;
            dat[k][i] = min(dat[k][i*2+1],dat[k][i*2+2]);
        }
    }

    int query(int a, int b, int k, int l, int r, int p){
        if (bit.sum(l) == bit.sum(r-1)){
            if (r<=a || b<=l) return INF;
            if (a<=l && r<=b) return dat[(p+bit.sum(l)) % 2][k];
        }
        int vl = query(a,b,k*2+1,l,(l+r)/2,p);
        int vr = query(a,b,k*2+2,(l+r)/2,r,p);
        return min(vl,vr);
    }
};

