  int siz;
public:
  segtree(int n){
    siz=1;
    while(siz<=n) siz*=2;
    node.resize(siz*2+1,P(17441744174417,0));
  }
  void upd(int pos,int x){
    ll fpos=pos;
    pos+=siz-1;
    node[pos]=P(x,fpos);
    while(pos>0){
      pos=(pos-1)/2;
      node[pos]=min(node[pos*2+1],node[pos*2+2]);
    }
  }
  P get_min(int a,int b,int pos,int l,int r){
    if(a<=l&&r<=b) return node[pos];
    if(r<=a||b<=l) return P(17441744174417,0);
    int mid=(l+r)/2;
    P lb=get_min(a,b,pos*2+1,l,mid);
    P rb=get_min(a,b,pos*2+2,mid,r);
    return min(lb,rb);
  }
  P min_q(int a,int b){
    return get_min(a,b,0,0,siz);
  }
};
P2 mk_P(ll x,ll y,ll z){
  return P2(x,P(y,z));
}
