struct node {
	int x, y, z;
	node(){}
	node(int X, int Y, int Z) {
		x = X;
		y = Y;
		z = Z;
	}
};

bool operator < (node a, node b) {
	return (mp(a.x, mp(a.y, a.z)) < mp(b.x, mp(b.y, b.z)));
}

int rmq[2][nmax], a[2][nmax], q[nmax], s, n, top = 1;
