void update(int n,int l,int r,int s,int e){

	if(r < s || l > e) return;
	if(l >= s && r <= e){
		segm[n].fi=v[l], segm[n].se=l;
		sego[n].fi=sege[n].fi=1e9;
		sego[n].se=sege[n].se=-1;
		if(l % 2) sego[n].fi=v[l], sego[n].se=l;
		else sege[n].fi=v[l], sege[n].se=l;
		return;
	}
	int mid=(l + r) / 2;
	update(n * 2 + 1,l,mid,s,e), update(n * 2 + 2,mid + 1,r,s,e);
	int lin=n * 2 + 1,rin=n * 2 + 2;
	if(segm[lin].fi < segm[rin].fi) segm[n].fi=segm[lin].fi, segm[n].se=
		segm[lin].se;
	else segm[n].fi=segm[rin].fi, segm[n].se=segm[rin].se;
	if(sego[lin].fi < sego[rin].fi) sego[n].fi=sego[lin].fi, sego[n].se=
		sego[lin].se;
	else sego[n].fi=sego[rin].fi, sego[n].se=sego[rin].se;
	if(sege[lin].fi < sege[rin].fi) sege[n].fi=sege[lin].fi, sege[n].se=
		sege[lin].se;
	else sege[n].fi=sege[rin].fi, sege[n].se=sege[rin].se;
}
pair<int, int> get(int n,int l,int r,int s,int e,int t){
	if(r < s || l > e) return{1e9, -1};
	else if(l >= s && r <= e){
		if(t == 1) return segm[n];
		if(t == 2) return sego[n];
		if(t == 3) return sege[n];
	}
	int mid=(l + r) / 2;
	pair<int, int> ret={ 1e9, -1 },li,ri;
	li=get(n * 2 + 1,l,mid,s,e,t);
	ri=get(n * 2 + 2,mid + 1,r,s,e,t);
	if(li.fi < ri.fi) ret.fi=li.fi, ret.se=li.se;
	else ret.fi=ri.fi, ret.se=ri.se;
	return ret;
}
