    int j = 0;
    int length = b - a + 1;
    length /= 2;
    while (length) {
        j++;
        length /= 2;
    }
    int ret = dp[a][j];
    if (num[ret] > num[dp[b-(1<<j)+1][j]]) ret = dp[b-(1<<j)+1][j];
    return ret;
}

