//セグ木を用いたRMQ
const int MAX_N = 420000;

struct RMQ {
    int n, dat[2 * MAX_N - 1];

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        for (int i = 0; i < 2 * n - 1; i++) dat[i] = LLONG_MAX;
    }

    void update(int k, int a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return LLONG_MAX;
        if (a <= l && r <= b) return dat[k];
        else {
            int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
};

typedef pair<int, P> seg;
RMQ rmq0, rmq1;
int N;
int p[220000], ap[220000];

// [l, r)
seg getSeg(int l, int r) {
    int pri;
    if (l % 2 == 0) pri = rmq0.query(l, r, 0, 0, rmq0.n);
    else  pri = rmq1.query(l, r, 0, 0, rmq1.n);
    return seg(pri, P(l, r));
}

signed main() {
