int even[ac], odd[ac], l[ac], r[ac], pos_odd[ac], pos_even[ac]; 
bool num;

struct node{
	int l, r, pos, x;
};

struct cmp{
	bool operator () (node a, node b){
		return a.x > b.x;//堆是反的
	}
};

priority_queue<node, vector<node>, cmp> q;

inline int read()
{
	int x = 0;char c = getchar();
	while(c > '9' || c < '0') c = getchar();
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x;
}

inline void up(int a, int b){
	if(a < ans) ans = a, pos = b;
}

inline void update(int x)
{//因为是排列，所以必然有一个更小，因此保证了贪心的正确性
	int ll = x * 2, rr = ll + 1;
	if(even[ll] < even[rr]) even[x] = even[ll], pos_even[x] = pos_even[ll];
	else even[x] = even[rr], pos_even[x] = pos_even[rr];
	if(odd[ll] < odd[rr]) odd[x] = odd[ll], pos_odd[x] = pos_odd[ll];
	else odd[x] = odd[rr], pos_odd[x] = pos_odd[rr];
}

void build(int x, int ll, int rr)
{
	l[x] = ll, r[x] = rr;
	if(ll == rr)
	{
		if(ll & 1) even[x] = inf, odd[x] = s[ll];
		else even[x] = s[ll], odd[x] = inf;
		pos_even[x] = pos_odd[x] = ll;
		return ;
	}
	int mid = (l[x] + r[x]) >> 1;
	build(x * 2, ll, mid), build(x * 2 + 1, mid + 1, rr);
	update(x);
}

void find(int x, int ll, int rr)
{
	if(l[x] == ll && r[x] == rr)
	{
		if(num) up(odd[x], pos_odd[x]);
		else up(even[x], pos_even[x]);
		return ;
	}
	int mid = (l[x] + r[x]) >> 1;
	if(rr <= mid) find(x * 2, ll, rr);
	else if(ll > mid) find(x * 2 + 1, ll, rr);
	else find(x * 2, ll, mid), find(x * 2 + 1, mid + 1, rr);
}

inline void add(int ll, int rr)
{
	if(ll >= rr) return ;
	ans = inf, num = ll & 1;//如果ll是偶数，那么pos也应该是偶数，否则为奇数，因为要求奇偶是相对于当前区间的l而言的
	find(1, ll, rr);
	q.push((node){ll, rr, pos, ans});
}

void pre()
{
	n = read();
	for(R i = 1; i <= n; i ++) s[i] = read();	
}

void work()
{
	add(1, n);
	while(!q.empty())
	{
		node x = q.top();
		q.pop();
		ss[++ tot] = x.x;
		ans = inf, num = (x.pos + 1) & 1;//接下来那个数相当于在[pos + 1, r]中寻找相对与pos + 1为奇数位的最小值
		find(1, x.pos + 1, x.r), ss[++ tot] = ans;
		int tmp = pos;//add一次之后pos就改变了...
		add(x.l, x.pos - 1), add(x.pos + 1, tmp - 1), add(tmp + 1, x.r);
	}
	for(R i = 1; i <= n; i ++) printf("%d ", ss[i]);
	printf("\n");
}

int main()
{
	//freopen("in.in", "r", stdin);
	pre();
	build(1, 1, n);
	work();	
	//fclose(stdin);
	return 0;
}

