using namespace std;
uint32_t rand32() {
    static uint32_t x = 12345;
    x ^= x << 13; x ^= x >> 17; x ^= x << 5;
    return x;
}
// https://www.slideshare.net/iwiwi/2-12188757
struct node_t {
    int val;
    node_t *lch, *rch;
    int cnt;
    int minv, minp;
    node_t(int v) : val(v), lch(nullptr), rch(nullptr), cnt(1), minv(v), minp(0) {}
};
int count(node_t *t) { return !t ? 0 : t->cnt; }
int minval(node_t *t) { return !t ? INT_MAX : t->minv; }
int minpos(node_t *t) { return !t ? 0 : t->minp; }
node_t *update(node_t *t) {
    t->cnt = count(t->lch) + count(t->rch) + 1;
    int x = minval(t->lch), y = t->val, z = minval(t->rch);
    if (x < y && x < z) {
        t->minv = x;
        t->minp = minpos(t->lch);
    } else if (y < x && y < z) {
        t->minv = y;
        t->minp = count(t->lch);
    } else {
        t->minv = z;
        t->minp = count(t->lch) + 1 + minpos(t->rch);
    }
    return t;
}
node_t *merge(node_t *l, node_t *r) {
    if (!l || !r) return !l ? r : l;
    if (rand32() % (count(l) + count(r)) < count(l)) {
        l->rch = merge(l->rch, r);
        return update(l);
    } else {
        r->lch = merge(l, r->lch);
        return update(r);
    }
}
pair<node_t*, node_t*> split(node_t *t, int k) {
    if (!t) return {nullptr, nullptr};
    if (k <= count(t->lch)) {
        auto s = split(t->lch, k);
        t->lch = s.second;
        return {s.first, update(t)};
    } else {
        auto s = split(t->rch, k - count(t->lch) - 1);
        t->rch = s.first;
        return {update(t), s.second};
    }
}
int main()
{
    int N; cin >> N;
    node_t *odd = nullptr, *even = nullptr;
    for (int i = 0; i < N; i++) {
        int p; cin >> p;
        if (i % 2 == 0) {
            odd = merge(odd, new node_t(p));
        } else {
            even = merge(even, new node_t(p));
        }
    }
    using Tup = tuple<int, node_t*, node_t*>;
    priority_queue<Tup, vector<Tup>, greater<Tup>> Q;
    Q.push({minval(odd), odd, even});
    while (!Q.empty()) {
        int v; node_t *odd, *even;
        tie(v, odd, even) = Q.top();
        Q.pop();
        cout << minval(odd) << ' ';
        int p = minpos(odd);
        node_t *a, *b;
        tie(a, odd) = split(odd, p);
        tie(b, even) = split(even, p);
        if (a) Q.push({minval(a), a, b});
        tie(ignore, odd) = split(odd, 1);
        cout << minval(even) << ' ';
        int q = minpos(even);
        tie(a, odd) = split(odd, q);
        tie(b, even) = split(even, q);
        if (b) Q.push({minval(b), b, a});
        tie(ignore, even) = split(even, 1);
        if (odd) Q.push({minval(odd), odd, even});
    }
