vector<pii> solve(vec v) {
  if (v.empty()) 
    return {};
  vec a[3];
  int x = 0, y = sz(v) - 1;
  int mn = sz(v) - 1;
  for (int i = sz(v) - 2; i >= 0; i -= 2) {
    if (v[mn] > v[i + 1]) 
      mn = i + 1;
    if (mp(v[x], v[y]) > mp(v[i], v[mn])) {
      x = i;
      y = mn;
    }
  }
  for (int i = 0; i < x; i++) 
    a[0].pb(v[i]);
  for (int i = x + 1; i < y; i++) 
    a[1].pb(v[i]);
  for (int i = y + 1; i < sz(v); i++) 
    a[2].pb(v[i]);
  vector<pii> q[3], t;
  for (int i = 0; i < 3; i++) {
    q[i] = solve(a[i]);
    for (auto it : q[i]) {
      t.pb(it);
    }
  }
  sort(all(t));
  reverse(all(t));
  t.pb(mp(v[x], v[y]));
  reverse(all(t));
  return t;
}

