const int N=1<<18,big=0x3f3f3f3f;
int a[N];
set<int>se;

struct node
{
	int l,r,f;
	pair<int,int> m[3];
}p[N*5];

void dn(int i)
{
	if(p[i].f==-1)return;
	p[i].m[2]=p[i].m[p[i].f];
	if(~p[i].f && p[i].l<p[i].r-1)p[i*2].f=p[i*2+1].f=p[i].f;
	p[i].f=-1;
}

void up(int i)
{
	for(int j=0;j<3;j++)p[i].m[j]=min(p[i*2].m[j],p[i*2+1].m[j]);
}

void build(int i,int l,int r)
{
	int m=(l+r)>>1;
	p[i].l=l;
	p[i].r=r;
	p[i].f=0;
	if(l==r-1)
	{
		p[i].m[l&1]=make_pair(a[l],l);
		p[i].m[(~l)&1]=make_pair(big,0);
		p[i].m[2]=p[i].m[0];
	}
	else
	{
		build(i*2,l,m);
		build(i*2+1,m,r);
		up(i);
	}
	//printf("i=%d %d %d2=%d %d\n",i,l,r,p[i].m[2].first,p[i].m[2].second);
}

void edit(int i,int l,int r)
{
	int m=(p[i].l+p[i].r)>>1;
	dn(i);
	if(l<=p[i].l && r>=p[i].r)
	{
		p[i].m[2]=p[i].m[p[i].f=(~l)&1];
		//printf("i=%d l&1=%d p[i].m[2]=%d %d\n",i,l&1,p[i].m[2].second,p[i].m[2].first);
		return;
	}
	if(l<m)edit(i*2,l,r);
	if(r>m)edit(i*2+1,l,r);
	dn(i*2);
	dn(i*2+1);
	up(i);
	//printf("i=%d l=%d r=%d pl=%d pr=%d pm0=%d pm1=%d pm2=%d\n",i,l,r,p[i].l,p[i].r,p[i].m[0].second,p[i].m[1].second,p[i].m[2].second);
}

pair<int,int> query(int i,int l,int r)
{
	int m=(p[i].l+p[i].r)>>1;
	dn(i);
	if(l<=p[i].l && r>=p[i].r)return p[i].m[2];
	pair<int,int> ans=make_pair(big,0);
	if(l<m)ans=min(ans,query(i*2,l,r));
	if(r>m)ans=min(ans,query(i*2+1,l,r));
	//printf("i=%d ans=%d %d\n",i,ans.first,ans.second);
	return ans;
}

