inline int sum(int i,int j,int k,int l,int r)
{
	if(l<=j && k<=r)
	  return f[i][2];
	else
	  {
	   int p=0;
	   if(l<=(j+k>>1))
	     p+=sum(i<<1,j,j+k>>1,l,r);
	   if(r>(j+k>>1))
	     p+=sum(i<<1|1,(j+k>>1)+1,k,l,r);
	   return p;
	  }
}
inline void modify(int i,int j,int k,int x,int y,int p)
{
	if(j==k)
	  f[i][y]=p;
	else
	  {
	   if(x<=(j+k>>1))
	     modify(i<<1,j,j+k>>1,x,y,p);
	   else
	     modify(i<<1|1,(j+k>>1)+1,k,x,y,p);
	   if(y<2)
	     f[i][y]=min(f[i<<1][y],f[i<<1|1][y]);
	   else
	     f[i][y]=f[i<<1][y]+f[i<<1|1][y];
	  }
}
inline int minn(int i,int j,int k,int l,int r,int x)
{
	if(l<=j && k<=r)
	  return f[i][x];
	else
	  {
	   int p=1e9;
	   if(l<=(j+k>>1))
	     p=min(p,minn(i<<1,j,j+k>>1,l,r,x));
	   if(r>(j+k>>1))
	     p=min(p,minn(i<<1|1,(j+k>>1)+1,k,l,r,x));
	   return p;
	  }
