void preprocess(int M[MAXN+5][20], int A[MAXN], int n)
{
    for (int i=0; i<n; i++)
        M[i][0] = i;
    for (int j=1; (1<<j)<=n; j++) {
        for (int i=0; i+(1<<j)-1<n; i++) {
            if (A[M[i][j-1]] < A[M[i+(1<<(j-1))][j-1]])
                M[i][j] = M[i][j-1];
            else 
                M[i][j] = M[i+(1<<(j-1))][j-1];
        }
    }
}

int RMQ(int M[MAXN+5][20], int arr[MAXN+5], int l, int r)
{
    int k=0;
    while ((1<<k)<=(r-l+1))
        k++;
    k--;
    int ret;
    if (arr[M[l][k]] < arr[M[r-(1<<k)+1][k]])
        ret = M[l][k];
    else 
        ret = M[r-(1<<k)+1][k];
    assert(l <= ret && ret <= r);
    return ret;
}

int solve(int l, int r)
{
    list<pair<int,int>> *ret = new list<pair<int,int>>();
    if (l >= r) {
        return 0;
    }
    //pr("solve") pr(l) pr(r) nl
    if (l+1 == r) {
        all_pairs.pb(mp(a[l],a[r]));
        return sz(all_pairs)-1;
    }

    int id = sz(all_pairs);
    int rec1, rec2, rec3;
    if (l%2 == 0) {
        int first = RMQ(evenM, evens, l/2, r/2);
        //prl(first)
        int second = RMQ(oddM, odds, first, r/2);
        //prl(second)
        all_pairs.pb(mp(a[2*first], a[2*second+1]));

        rec1 = solve(l,2*first-1);
        rec2 = solve(2*first+1,2*second);
        rec3 = solve(2*second+2, r);
    }
    else {
        int first = RMQ(oddM, odds, l/2, (r-1)/2);
        //prl(first)
        int second = RMQ(evenM, evens, first+1, r/2);
        //prl(second) nl
        all_pairs.pb(mp(a[2*first+1], a[2*second]));

        rec1 = solve(l,2*first);
        rec2 = solve(2*first+2,2*second-1);
        rec3 = solve(2*second+1, r);
    } 

    constr[id].pb(rec1);
    constr[id].pb(rec2);
    constr[id].pb(rec3);
    indegree[rec1]++;
    indegree[rec2]++;
