    return id;
}

struct item 
{
    pair<int,int> p;
    int i;
};
bool operator < (const item & a, const item & b) {
    return a.p > b.p;
}

vector<pair<int,int>> sort_pairs()
{
    int n = sz(all_pairs);
    vector<pair<int,int>> ret;
    priority_queue<item> q;

    for0(i,n) {
        /*prp(all_pairs[i]);
        prl(indegree[i]);
        printv(constr[i]);*/
        if (indegree[i] == 0) {
            q.push((item){all_pairs[i],i});
        }
    }

    while (!q.empty()) {
        item top = q.top(); q.pop();
        ret.pb(top.p);
        iter(constr[top.i]) {
            indegree[*it]--;
            if (indegree[*it] == 0) {
                q.push((item){all_pairs[*it],*it});
            }
        }
    }

    return ret;
}

