struct segtree{
    static const int SEG=1<<18;
    vector<pint> dat;
    segtree():dat(SEG*2,pint(INF,INF)){}
    void update(int k,pint p){
        k+=SEG-1;
        dat[k]=p;
        while(k){
            k=(k-1)/2;
            dat[k]=min(dat[k*2+1],dat[k*2+2]);
        }
    }
    pint query(int a,int b,int k=0,int l=0,int r=SEG){
        if(r<=a||b<=l)return pint(INF,INF);
        if(a<=l&&r<=b)return dat[k];
        return min(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
};

int N;
int P[222222];

segtree odd,even;

typedef tuple<pint,pint,pint>T;

T calc(int l,int r){
    int ll,rr;
    if(l&1){
        ll=odd.query(l,r).se;
        rr=even.query(ll,r).se;

    }
    else{
        ll=even.query(l,r).se;
        rr=odd.query(ll,r).se;
    }


    return T({P[ll],P[rr]},{ll,rr},{l,r});
}

