	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
//	cout<<T[x].l<<' '<<T[x].r<<' '<<T[x].Id1<<' '<<T[x].Id2<<endl;
}
inline int Ask(int x,int l,int r,int Opt){
//	cout<<x<<' '<<T[x].l<<' '<<T[x].r<<' '<<l<<' '<<r<<endl;
	if(l<=T[x].l&&T[x].r<=r) return Opt==1?T[x].Id1:T[x].Id2;
	int Ans=0,Anss=0;
	if(l<=T[x<<1].r) Ans=Ask(x<<1,l,r,Opt);
	if(r>T[x<<1].r) Anss=Ask((x<<1)+1,l,r,Opt);
	if(A[Ans]>A[Anss]) Ans=Anss;
	return Ans;
}
inline void Solv(int l,int r,int L,int R){
	if(l>=r) return;
	if(l+1==r){
		B[L]=make_pair(A[l],A[r]);
		return;
	}
	int Min=Ask(1,l,r,l%2);
	int Minn=Ask(1,Min,r,(l%2)^1);
	B[L]=make_pair(A[Min],A[Minn]);
	int Mid=L+((Min-1)-(l-1))/2,Midd=R-(r-(Minn+1-1))/2;
	int ll=L+1,mid=Mid+1,rr=Midd+1,f=L+1;
	Solv(l,Min-1,L+1,Mid); 
	Solv(Min+1,Minn-1,Mid+1,Midd); 
	Solv(Minn+1,r,Midd+1,R);
	for(;ll<=Mid&&mid<=Midd&&rr<=R;)
	 if(B[ll]<B[mid]&&B[ll]<B[rr]) C[f++]=B[ll++];
	 else if(B[mid]<B[ll]&&B[mid]<B[rr]) C[f++]=B[mid++];
	 else C[f++]=B[rr++];
	int _l=0,_r=0,_ll=0,_rr=0;
	ll<=Mid?_l=ll,_ll=Mid:(_l=mid,_ll=Midd);
	rr<=R?_r=rr,_rr=R:(_r=mid,_rr=Midd);
	if(_l==_r&&_ll==_rr) _r=N+1;
	for(;_l<=_ll&&_r<=_rr;)
	 if(B[_l]<B[_r]) C[f++]=B[_l++];
	 else C[f++]=B[_r++];
	for(;_l<=_ll;) C[f++]=B[_l++];
	for(;_r<=_rr;) C[f++]=B[_r++];
	for(int i=L+1;i<=R;i++) B[i]=C[i];
	return ;
}
