struct STN{
	int e,o;
	void merge(STN& L, STN& R){
		e = A[L.e] < A[R.e] ? L.e : R.e;
		o = A[L.o] < A[R.o] ? L.o : R.o;
	}
	void operator=(int pos){
		if(pos % 2 == 0) e = pos, o = N;
		if(pos % 2 == 1) e = N, o = pos;
	}
};
STN ST[4*MAXN];
void STB(int id = 1,int l = 0,int r = N){
	if(r - l < 2){
		ST[id] = l;
		return;
	}
	int M = (l+r)>>1, L=id<<1, R=L|1;
	STB(L, l, M); STB(R, M, r);
	ST[id].merge(ST[L],ST[R]);
}

STN STQ(int x,int y,int id = 1,int l = 0,int r = N){
	if(x == l && y == r)	return ST[id];
	int M = (l+r)>>1, L=id<<1, R=L|1;
	if(x>=M)	return STQ(x,y,R,M,r);
	if(y<=M)	return STQ(x,y,L,l,M);
	STN res,ln=STQ(x, M, L, l, M),rn=STQ(M, y, R, M, r);
	return res.merge(ln, rn), res;
}

void STU(int p,int x,int id = 1,int l = 0,int r = N){
	if(r - l < 2){
		ST[id]=x;
		return;
	}
	int M = (l+r)>>1, L=id<<1, R=L|1;
	if(p < M) STU(p, x, L, l, M);
	else STU(p, x, R, M, r);
	ST[id].merge(ST[L],ST[R]);
}

void f() {
	Q.push({{0,N},0});
	while(!Q.empty()) {
		int lo = Q.front().first.first;
		int hi = Q.front().first.second;
		int id = Q.front().second;
		Q.pop();
		if(lo + 1 >= hi) {
			V[id] = {INF,INF};
			continue;
		}
		STN n1 = STQ(lo,hi);
		int pos1 = lo % 2 == 0 ? n1.e : n1.o;
		STN n2 = STQ(pos1,hi);
		int pos2 = lo % 2 == 0 ? n2.o : n2.e;
		V[id] = {A[pos1],A[pos2]};
		Q.push({{lo,pos1},curid});
		G[id].pb(curid++);
		Q.push({{pos1+1,pos2},curid});
		G[id].pb(curid++);
		Q.push({{pos2+1,hi},curid});
		G[id].pb(curid++);
	}
}

