using namespace std;

template <typename T> class SegmentTree {
    int array_size;        // もとの配列のサイズ
    int n;
    std::vector<T> data;
    std::function<T (T,T)> op;
    T unit;

public:
    enum Mode {
        RangeMinimumQuery,
        RangeMaximumQuery,
        RangeSummationQuery,
    };

    SegmentTree() {

    }

    void init(int array_size, Mode mode) {
        this->array_size = array_size;
        if (mode == RangeMinimumQuery) {
            unit = INT_MAX;
            op = [](T a, T b) { return std::min(a, b); };
        }
        else if (mode == RangeMaximumQuery) {
            unit = 0;
            op = [](T a, T b) { return std::max(a, b); };
        }
        else if (mode == RangeSummationQuery) {
            unit = 0;
            op = [](T a, T b) { return a + b; };
        }
        else {
            assert(false);
        }

        n = 1;
        while (n < array_size) { n *= 2; }   // _n以上の最小の2冪
        data.resize(2 * n - 1, unit);
    }

    template <typename F> SegmentTree(int array_size, T unit, F op) : array_size(array_size), unit(unit), op(op) {
        while (n < array_size) { n *= 2; }   // _n以上の最小の2冪
        data.resize(2 * n - 1, unit);
    }

    T access(int idx) {
        return data[idx + n - 1];
    }

    // array[idx] = x
    // O(log N)
    void update(int idx, T x) {
        assert(0 <= idx and idx < array_size);
        idx += n - 1;   // 木での対象のインデックス
        data[idx] = x;
        while (idx > 0) {
            idx = (idx - 1) / 2;                                    // 親のインデックス
            data[idx] = op(data[idx * 2 + 1], data[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // op(array[left, right))
    // O(log N)
    T query(int left, int right) {
        assert(0 <= left and left < right and right <= array_size);
        return query(left, right, 0, 0, n);
    }

private:
    // [a, b)の目的値をノードk（区間[l, r]）から検索
    T query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return unit;
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->data.at(k);
        }
            // 一部含む
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return op(vl, vr);
        }
    }
};


void solve(int N, vector<int> &P) {

    unordered_map<int, int> value_idx;
    SegmentTree<int> odd, even;
    odd.init(N + 100, SegmentTree<int>::RangeMinimumQuery);
    even.init(N + 100, SegmentTree<int>::RangeMinimumQuery);
    FOR(i, 0, N) {
        value_idx[P[i]] = i;
        if (i % 2 == 0) {
            even.update(i, P[i]);
        }
        else {
            odd.update(i, P[i]);
        }
    }

    vector<int> ans;

    priority_queue<tuple<int, int, int>> pq;
    pq.push(make_tuple(INF, 0, N));

    while (not pq.empty()) {
        int k, l, r;
        tie(k, l, r) = pq.top(); pq.pop();

        if (l + 1 == r) {
            ans.emplace_back(P[l]);
            ans.emplace_back(P[r]);
            continue;
        }

        int mini = INF, mini_idx = -1;
        int mini2 = INF, mini_idx2 = -1;
        if (l % 2 == 0) {
            mini = even.query(l, r);
            mini_idx = value_idx[mini];
            even.update(mini_idx, INF);

            mini2 = odd.query(mini_idx + 1, r);
            mini_idx2 = value_idx[mini2];
            odd.update(mini_idx2, INF);
        }
        else {
            mini = odd.query(l, r);
            mini_idx = value_idx[mini];
            odd.update(mini_idx, INF);

            mini2 = even.query(mini_idx + 1, r);
            mini_idx2 = value_idx[mini2];
            even.update(mini_idx2, INF);
        }

        ans.emplace_back(mini);
        ans.emplace_back(mini2);

        int key = 0;
        if (mini_idx > l) {
            if (l % 2 == 0) {
                key = even.query(l, mini_idx);
            } else {
                key = odd.query(l, mini_idx);
            }
            pq.push(make_tuple(-key, l, mini_idx));
        }

        if (mini_idx2 > mini_idx + 1) {
            if ((mini_idx + 1) % 2 == 0) {
                key = even.query(mini_idx + 1, mini_idx2);
            } else {
                key = odd.query(mini_idx + 1, mini_idx2);
            }
            pq.push(make_tuple(-key, mini_idx + 1, mini_idx2));
        }

        if (r > mini_idx2 + 1) {
            if ((mini_idx2 + 1) % 2 == 0) {
                key = even.query(mini_idx2 + 1, r);
            } else {
                key = odd.query(mini_idx2 + 1, r);
            }
            pq.push(make_tuple(-key, mini_idx2 + 1, r));
        }
    }

    print_vec(ans);
}


