int sp[2][N][20],po[20],ar[2*N];
int v[2][N],perm[2*N];
void pre()
{
    int i,k;
    ar[1]=0,k=1,po[0]=1;
    while(k<N)
    {
        for(i=k+1;i<2*k;i++)
            ar[i]=ar[k];
        ar[2*k]=1+ar[k],k*=2;
    }
    for(i=1;i<20;i++)
        po[i]=2*po[i-1];
        return ;
}
void up(int f,int j,int n)
{
    sp[f][j][0]=j;
    for(int k=1;k<20;k++)
    {
        if(j+po[k]<=n)
            sp[f][j][k]=v[f][sp[f][j][k-1]]<v[f][sp[f][j+po[k-1]][k-1]]?sp[f][j][k-1]:sp[f][j+po[k-1]][k-1];
    }
    return ;
}
int query(int f,int a,int b)
{
    int y,x=b-a+1;
    y=ar[x],x-=po[y];
    return v[f][sp[f][a][y]]<v[f][sp[f][a+x][y]]?sp[f][a][y]:sp[f][a+x][y];
}
ii call(int l,int r)
{
    int f=(l&1);
    int p=query(f,(l/2),(r-1)/2);
    int q=query(f^1,p+f,(r/2));
    return {lchild(p)+f,rchild(q)-f};
}
ii value(int l,int r)
{
    ii temp=call(l,r);
    return {perm[temp.F],perm[temp.S]};
}
void solve()
{
    int n,m,i,l,r,a,b;
    in(n);
    rep(i,n)
        in(a),v[i&1][i/2]=a,perm[i]=a;
    m=(n/2);
    pre();
    rrep(i,m)
        up(0,i,m),up(1,i,m);
    set<pair<ii,ii> > st;
    set<pair<ii,ii> > :: iterator itr;
    st.insert({value(0,n-1),{0,n-1}});
    vi ans;
