        tie(a,b)=call(l,r);
        if(a>l)
            st.insert({value(l,a-1),{l,a-1}});
        if(b>a+1)
            st.insert({value(a+1,b-1),{a+1,b-1}});
        if(r>b+1)
            st.insert({value(b+1,r),{b+1,r}});
    }
