    auto findSmallestPair = [&](int s, int t) {
      const SegmentTree &rmq1 = s % 2 == 0 ? evenRMQ : oddRMQ;
      const SegmentTree &rmq2 = s % 2 == 0 ? oddRMQ : evenRMQ;
      int a = mp[rmq1.query(s / 2, t / 2)];
      int b = mp[rmq2.query((a + 1) / 2, (t + 1) / 2)];
      return make_pair(a, b);
    };
    auto newEnclosure = [&](int s, int t) {
      auto ps = findSmallestPair(s, t);
      return Enclosure{s, t, ps.first, ps.second, p[ps.first]};
    };
    priority_queue<Enclosure> pq;
    pq.push(newEnclosure(0, N));
    while (!pq.empty()) {
      auto e = pq.top();
      pq.pop();
      cout << p[e.a] << " " << p[e.b] << " ";
      if (e.s < e.a) {
        pq.push(newEnclosure(e.s, e.a));
      }
      if (e.a + 1 < e.b) {
        pq.push(newEnclosure(e.a + 1, e.b));
      }
      if (e.b + 1 < e.t) {
        pq.push(newEnclosure(e.b + 1, e.t));
      }
    }
    cout << endl;
  }
  return 0;
}

