            l = r = nullptr;
        }else{
            // l = new SegTree(left, (right - left) / 2 + left);
            // r = new SegTree((right - left) / 2 + left + 1, right);
            l = new SegTree(left, (right + left) / 2);
            r = new SegTree((right + left) / 2 + 1, right);
        }
    }
    void set(int idx, pair<ll, int> val){
        if(right < idx || idx < left){ return; }
        value = min(value, val);
        prints(left, right, value);
        if(left != idx || right != idx){
            l -> set(idx, val);
            r -> set(idx, val);
        }
    }
