const int inf = 1 << 30;

class SqrtDiv {
private:
    vector<int> v;
    vector<int> block;
    int blockSize;
public:
    SqrtDiv(int n) {
        v.resize(n, inf);
        blockSize = ceil(sqrt(n) + 1e-9);
        block.resize((n + blockSize - 1) / blockSize, inf);
    }

    void set(int n, int x) {
        v[x] = n;
        x /= blockSize;
        block[x] = inf;
        REP (i, x * blockSize, (x + 1) * blockSize) {
            block[x] = min(block[x], v[i]);
        }
    }

    int get(int l, int r) {
        int ans = inf;
        REP (i, 0, block.size()) {
            int ll = i * blockSize;
            int rr = (i + 1) * blockSize;
            if (rr <= l || r <= ll) continue;
            else if (l <= ll && rr <= r) ans = min(ans, block[i]);
            else {
                REP (j, max(ll, l), min(rr, r)) {
                    ans = min(ans, v[j]);
                }
            }
        }
        return ans;
    }
};

