        ml[ai] = i;
        sq[0].set(ai, i);
        sq[1].set(ai, i);
        sq[!(i % 2)].set(inf, i);
    }

    priority_queue<Data, vector<Data>> pq;
    pq.emplace(0, N, sq[0].get(0, N));
    while (pq.size()) {
        auto t = pq.top();
        pq.pop();
        int lt = ml[t.m];
        int g = sq[!(t.r % 2)].get(lt + 1, t.r);
        int gpos = ml[g];
