struct monoid {
    int val, idx;

    static monoid op(monoid lhs, monoid rhs) {
        return lhs.val < rhs.val ? lhs : rhs;
    }

    static monoid e() { return {mod, -1}; }
};

struct seg {
    int val, idx, l, r;
};

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<monoid>> a(2, vector<monoid>(n, {mod, -1}));
    rep(i, n) {
        scanf("%d", &a[i % 2][i].val);
        a[i % 2][i].idx = i;
    }
    segtree<monoid, monoid::op, monoid::e> st0(a[0]), st1(a[1]);

    auto cmp = [](const seg& s1, const seg& s2) { return s1.val > s2.val; };
    priority_queue<seg, vector<seg>, decltype(cmp)> que(cmp);
    auto get_min = [&](int l, int r) {
        return l % 2 == 0 ? st0.prod(l, r) : st1.prod(l, r);
    };
    auto mo = st0.all_prod();
    que.push({mo.val, mo.idx, 0, n});

    vector<int> ans;
    while (!que.empty()) {
        auto s = que.top();
        que.pop();
        ans.push_back(s.val);
        auto [w, j] = get_min(s.idx + 1, s.r);
        ans.push_back(w);
        if (s.idx - s.l) {
            mo = get_min(s.l, s.idx);
            que.push({mo.val, mo.idx, s.l, s.idx});
        }
        if (j - s.idx - 1) {
            mo = get_min(s.idx + 1, j);
            que.push({mo.val, mo.idx, s.idx + 1, j});
        }
        if (s.r - j - 1) {
            mo = get_min(j + 1, s.r);
            que.push({mo.val, mo.idx, j + 1, s.r});
        }
    }
    for (auto i : ans) printf("%d ", i);
    printf("\n");
}

