class Segment{
    public :
        P1 dat[400005];
        int n;
        void init(int n_){
            n=1;
            while(n<n_)n*=2;
            for(int i=0;i<2*n-1;++i)dat[i]=P1(INF,INF);
        }

        P1 Min(P1 a,P1 b){
            if(a.first<b.first)return a;
            else return b;
        }

        void update(int k,P1 a){
            k+=n-1;
            dat[k]=a;
            while(k>0){
                k=(k-1)/2;
                dat[k]=Min(dat[k*2+1],dat[k*2+2]);
            }
        }

        P1 query(int a,int b,int k,int l,int r){
            if(a<=l&&r<=b)return dat[k];
            if(r<=a||b<=l)return P1(INF,INF);
            else {
                P1 vl=query(a,b,k*2+1,l,(l+r)/2);
                P1 vr=query(a,b,k*2+2,(l+r)/2,r);
                return Min(vl,vr);
            }
        }
};

