const int N = 2e5+7;
const int M = 1<<19;

int n;

int p[N];

struct tree
{
	PII load[2*M];

	void insert(int a, int v)
	{
		a += M;
		load[a] = mp(v, a-M);
		a /= 2;

		while(a>=1)
		{
			load[a] = min(load[2*a], load[2*a+1]);
			a /= 2;
		}
	}

	PII query(int a, int b)
	{
		if(a>b)
			return mp(-1, -1);

		a += M;
		b += M;

		PII res = min(load[a], load[b]);

		while(a<b-1)
		{
			if(a%2==0)
				res = min(res, load[a+1]);

			if(b%2==1)
				res = min(res, load[b-1]);

			a /= 2;
			b /= 2;
		}

		return res;
	}

	tree()
	{
		for(int i = 0; i < 2*M; ++i)
		{
			load[i] = mp(inf, inf);
		}
	}
};

tree P, NP;

set<pair<pair<PII, PII>, PII> > Q;

void solve(pair<pair<PII, PII>, PII> v)
{
	Q.erase(Q.begin());

	int a = v.nd.st, b = v.nd.nd, l = v.st.st.nd, r = v.st.nd.nd;

	cout << p[l] << " " << p[r] << " ";

	PII A1, A2, B1, B2, C1, C2;

	if(a%2==1)
	{
		A1 = NP.query(a, l-1);
		A2 = P.query(A1.nd+1, l-1);	
	}
	else
	{
		A1 = P.query(a, l-1);
		A2 = NP.query(A1.nd+1, l-1);
	}

	if((l+1)%2==1)
	{
		B1 = NP.query(l+1, r-1);
		B2 = P.query(B1.nd+1, r-1);
	}
	else
	{
		B1 = P.query(l+1, r-1);
		B2 = NP.query(B1.nd+1, r-1);
	}

	if((r+1)%2==1)
	{
		C1 = NP.query(r+1, b);
		C2 = P.query(C1.nd+1, b);
	}
	else
	{
		C1 = P.query(r+1, b);
		C2 = NP.query(C1.nd+1, b);
	}

	if(a<l-1) Q.emplace(mp(A1, A2), mp(a, l-1));
	if(l+1<r-1) Q.emplace(mp(B1, B2), mp(l+1, r-1));
	if(r+1<b) Q.emplace(mp(C1, C2), mp(r+1, b));
}

int32_t main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(NULL);

	cin >> n;

	for(int i = 1; i <= n; ++i)
	{
		cin >> p[i];
	}

	for(int i = 1; i <= n; ++i)
	{
		if(i%2)
			NP.insert(i, p[i]);
		else
			P.insert(i, p[i]);
	}

	PII q1 = NP.query(1, n);
	PII q2 = P.query(q1.nd+1, n);

	Q.emplace(mp(q1, q2), mp(1, n));

	while(!Q.empty())
		solve(*Q.begin());
}

#include <bits/stdc++.h>
