const int N = 2e5 + 10;
const int INF = 1e9 + 10;

int n;
int A[N];

int cmp(int i, int j) {
    return A[i] < A[j];
}

int func(int i, int j) {
    return cmp(i, j) ? i : j;
}


struct seg_tree {
    int T[N*4];
    void st_update(int u, int L, int R, int i, int x) {
        if (i < L || R < i)
            return;
        if (L == R) {
            A[i] = x;
            T[u] = i;
        } else {
            int mid = (L + R) / 2;
            st_update(u * 2, L, mid, i, x);
            st_update(u * 2 + 1, mid + 1, R, i, x);
            T[u] = func(T[u * 2], T[u * 2 + 1]);
        }
    }

    void update(int i, int x) {
        st_update(1, 1, n, i, x);
    }

    int st_query(int u, int L, int R, int i, int j) {
        if (j < L || R < i) {
            return 0;
        }
        if (i <= L && R <= j) {
            return T[u];
        }

        int mid = (L + R) / 2;
        return func(st_query(u * 2, L, mid, i, j),
                    st_query(u * 2 + 1, mid + 1, R, i, j));
    }

    int query(int i, int j) {
        return st_query(1, 1, n, i, j);
    }
} st[2];

deque<int> solve(int i, int j) {
    if (i > j)
        return deque<int>();

//    printf("i=%d j=%d\n", i, j);
//    printf("l=%d r=%d\n", l, r);
    deque<int> a, b, c;

    int p = i % 2;

    int l = st[p].query(i, j);
    int r = st[1 - p].query(l + 1, j);

    deque<int> ans;
    a = solve(i, l - 1);
    b = solve(l + 1, r - 1);
    c = solve(r + 1, j);
    ans.push_back(A[l]);
    ans.push_back(A[r]);
    while (!a.empty() || !b.empty() || !c.empty()) {
        deque<int> *vp = NULL;
        if (!a.empty() && (vp == NULL || a[0] < vp->at(0))) vp = &a;
        if (!b.empty() && (vp == NULL || b[0] < vp->at(0))) vp = &b;
        if (!c.empty() && (vp == NULL || c[0] < vp->at(0))) vp = &c;
        for (int k = 0; k < 2; k++) {
            int x = vp->front();
            ans.push_back(x);
            vp->pop_front();
        }
    }
    return ans;
}

