	{
		assert((R - L) % 2 == 0);
		assert(R - L);
		pair<int, int> one, two;
		if (turn)
		{
			//反転
			one = sg[1].query(L / 2, R / 2);
			two = sg[0].query(ceil(L, 2), ceil(R, 2));
		}
		else
		{
			//反転していない
