inline void pushup(int rt,int tp)
{
	if(A[tree[rt<<1][tp]]<A[tree[rt<<1|1][tp]])
		tree[rt][tp]=tree[rt<<1][tp]; 
	else tree[rt][tp]=tree[rt<<1|1][tp];
}
inline void built(int l,int r,int rt,int tp)
{
	if(l==r){tree[rt][tp]=l*2-tp; return ;}
	int mid=(l+r)>>1; 
	built(l,mid,rt<<1,tp); built(mid+1,r,rt<<1|1,tp);
	pushup(rt,tp);
}
inline int query(int L,int R,int l,int r,int rt,int tp)
{
	if(L>R) return 0;
	if(L<=l&&r<=R) return tree[rt][tp];
	int mid=(l+r)>>1;
	if(mid<L) return query(L,R,mid+1,r,rt<<1|1,tp);
	if(mid>=R) return query(L,R,l,mid,rt<<1,tp);
	int x1=query(L,R,l,mid,rt<<1,tp);
	int x2=query(L,R,mid+1,r,rt<<1|1,tp);
	if(A[x1]<A[x2]) return x1; else return x2;  
}
