void build(int v, int tl, int tr) {
     if (tl + 1 == tr) {
          rmq1[v] = rmq0[v] = make_pair(MAXN, tl);
          if (tl % 2 == 0)
               rmq0[v] = make_pair(p[tl], tl);
          else
               rmq1[v] = make_pair(p[tl], tl);
          return;
     }
     int m = (tl + tr) >> 1;
     build(v * 2 + 1, tl, m);
     build(v * 2 + 2, m, tr);
     rmq0[v] = min(rmq0[v * 2 + 1], rmq0[v * 2 + 2]);
     rmq1[v] = min(rmq1[v * 2 + 1], rmq1[v * 2 + 2]);
}

pair<int, int> get0(int v, int tl, int tr, int l, int r) {
     if (r <= tl || tr <= l)
          return make_pair(MAXN, 0);
     if (l <= tl && tr <= r)
          return rmq0[v];
     int m = (tl + tr) >> 1;
     return min(get0(v * 2 + 1, tl, m, l, r), get0(v * 2 + 2, m, tr, l, r));
}
pair<int, int> get1(int v, int tl, int tr, int l, int r) {
     if (r <= tl || tr <= l)
          return make_pair(MAXN, 0);
     if (l <= tl && tr <= r)
          return rmq1[v];
     int m = (tl + tr) >> 1;
     return min(get1(v * 2 + 1, tl, m, l, r), get1(v * 2 + 2, m, tr, l, r));
}

pair<int, int> get_(int l, int r) {
     if (l % 2 == 0) {
          int x = get0(0, 0, n, l, r).second;
          return make_pair(x, get1(0, 0, n, x + 1, r).second);
     }
     else {
          int x = get1(0, 0, n, l, r).second;
          return make_pair(x, get0(0, 0, n, x + 1, r).second);
     }
}

