	built(1,n/2,1,0); 
	built(1,n/2,1,1);
	q.push((node){1,n,query(1,n/2,1,n/2,1,1)});
	while(!q.empty())
	{
		node lx=q.top(); q.pop();
		if(lx.l>lx.r) continue;
		int td=ks(lx.x,lx.r,0);
