// セグメント木を持つグローバル配列
int n_even, n_odd, dat_even[2 * MAX_N - 1], dat_odd[2 * MAX_N - 1];

// 初期化
void init_even(int n_){
    // 簡単のため要素数を2のべき乗に
    n_even = 1;
    while(n_even < n_)n_even *= 2;

    // 全ての値をINT_MAXに
    for(int i = 0; i < 2 * n_even - 1; i++)dat_even[i] = INT_MAX;
}

// 初期化
void init_odd(int n_){
    // 簡単のため要素数を2のべき乗に
    n_odd = 1;
    while(n_odd < n_)n_odd *= 2;

    // 全ての値をINT_MAXに
    for(int i = 0; i < 2 * n_odd - 1; i++)dat_odd[i] = INT_MAX;
}

// k番目の値(0-indexed)をaに変更
void update_even(int k, int a){
    // 葉の接点
    k += n_even - 1;
    dat_even[k] = a;
    // 登りながら更新
    while(k > 0){
        k = (k - 1) / 2;
        dat_even[k] = min(dat_even[k * 2 + 1], dat_even[k * 2 + 2]);
    }
}

// k番目の値(0-indexed)をaに変更
void update_odd(int k, int a){
    // 葉の接点
    k += n_odd - 1;
    dat_odd[k] = a;
    // 登りながら更新
    while(k > 0){
        k = (k - 1) / 2;
        dat_odd[k] = min(dat_odd[k * 2 + 1], dat_odd[k * 2 + 2]);
    }
}

// [a,b)の最小値を求める
// 後ろのほうの引数は、計算の簡単のための引数。
// kは節点の番号、l, rはその節点が[l, r)に対応づいていることを表す。
// したがって、外からはquery(a, b, 0, 0, n)として呼ぶ。
int query_even(int a, int b, int k, int l, int r){
    // [a, b)と[l, r)が交差しなければ、INT_MAX
    if (r <= a || b <= l)return INT_MAX;

    // [a, b)が[l, r)を完全に含んでいれば、この節点の値
    if (a <= l && r <= b)return dat_even[k];
    else {
        // そうでなければ、2つの子の最小値
        int vl = query_even(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query_even(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}

// [a,b)の最小値を求める
// 後ろのほうの引数は、計算の簡単のための引数。
// kは節点の番号、l, rはその節点が[l, r)に対応づいていることを表す。
// したがって、外からはquery(a, b, 0, 0, n)として呼ぶ。
int query_odd(int a, int b, int k, int l, int r){
    // [a, b)と[l, r)が交差しなければ、INT_MAX
    if (r <= a || b <= l)return INT_MAX;

    // [a, b)が[l, r)を完全に含んでいれば、この節点の値
    if (a <= l && r <= b)return dat_odd[k];
    else {
        // そうでなければ、2つの子の最小値
        int vl = query_odd(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query_odd(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}

