class RMQ{
private:
    int n;
    vector<vector<int>> data; // doubling_range_min  data[k][p] : min(src[p:p+2^k])  including p and not including p+2^k
public:
    RMQ(const vector<int> &src): n(src.size()){
        data.emplace_back(src);
        for (int k = 0, r = 1; r < n; ++k, r <<= 1 ){
            data.emplace_back(data[k]);
            for (int p = 0; p + r < n; ++p) data[k + 1][p] = min(data[k][p], data[k][p + r]);
        }
    }
    int query(int L, int R){ // min(data[0][L..R] including both ends. [L, R]
        if (L == R) return data[0][L];
        int k = 31 - __builtin_clz(R - L);
        return min(data[k][L], data[k][R + 1 - (1<<k)]);
    }
};

int get_smallest(int s, int t, RMQ & rmq0, RMQ & rmq1){
    assert(s <= t - 1);
    if (s & 1){
        return rmq1.query(s, t - 1);
    }else{
        return rmq0.query(s, t - 1);
    }
}

void process(int s, int t, priority_queue<int> & pq, vector<tuple<int, int, int>> & data, RMQ & rmq0, RMQ & rmq1, const vector<int> & idx){
    if (s + 1 >= t) return;
    int x = get_smallest(s, t - 1, rmq0, rmq1);
    int y = get_smallest(idx[x] + 1, t, rmq0, rmq1);
    data[x] = make_tuple(y, s, t);
    pq.push(-x);
}

vector<int> solve(int N, const vector<int> & ps){
    // 分割統治する。
    // pq に、(x, y, s, t) を入れる。 (x, y) 区間 ps[s:t - 1) のうち、sから数えて偶数位置にある最小の x、xの位置から数えて奇数位置にある最小y
    // pq から、x最小のものを取り出し、処理する。
    //   qs の末尾に、x, y を追加する。
    //   ps[s:t) を、x, y の位置で分割する。
    //      idx[x] = i, idx[y] = j とすると、[s:i), [i + 1:j), [j + 1:t) に分割する。
    //      区間の幅がゼロのときは、処理をスキップする。
    //   分割した区間のそれぞれについて、区間内の最小のx, y を求め、pq に追加する。
    // 上記の操作のため、以下の前処理をしておく。
    // idx[v] = i : ps[i] = v の逆引き
    // rmq0, rmq1 : psの区間のうち、偶数位置、奇数位置での最小値を返す range minimum query。
    //              rmq0 であれば、奇数位置をINFとして長さNの rmq を用意すればよい。
    vector<int> qs = {};
    priority_queue<int> pq;
    vector<tuple<int, int, int>> data(N);  // data[x] = (y, s, t)
    vector<int> idx(N + 1);
    for (int i = 0; i < N; ++i) idx[ps[i]] = i;
    vector<int> ps0 = ps;
    vector<int> ps1 = ps;
    for (int i = 1; i < N; i += 2) ps0[i] = INF;
    for (int i = 0; i < N; i += 2) ps1[i] = INF;
    RMQ rmq0(ps0);
    RMQ rmq1(ps1);
    process(0, N, pq, data, rmq0, rmq1, idx);
    while (not pq.empty()){
        int x, y, s, t;
        x = -pq.top();
        pq.pop();
        tie(y, s, t) = data[x];
        qs.push_back(x);
        qs.push_back(y);
        process(s,          idx[x], pq, data, rmq0, rmq1, idx);
        process(idx[x] + 1, idx[y], pq, data, rmq0, rmq1, idx);
        process(idx[y] + 1, t,      pq, data, rmq0, rmq1, idx);
    }
    return qs;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N;
    cin >> N;
    vector<int> ps(N);
    for (auto & p : ps) cin >> p;
    print(solve(N, ps));
    return 0;
}

