#define mp make_pair
typedef pair<int,int> pii;
typedef pair<pii,pii> piii;

int a[200100],n,p=0;
piii ans[100100];

void find_ans(int l,int r){
	if (l>r) return;
	int min=2147483647,p1=0;
	for (int i=l;i<r;i+=2){
		if (a[i]<min){
			min=a[i];
			p1=i;
		}
	}
	min=2147483647;
	int p2=0;
	for (int i=p1+1;i<=r;i+=2){
		if (a[i]<min){
			min=a[i];
			p2=i;
		}
	}
	ans[++p]=mp(mp(a[p1],a[p2]),mp(p1,p2));
	find_ans(l,p1-1);
	find_ans(p1+1,p2-1);
	find_ans(p2+1,r);
}

bool comp(piii a,piii b){
	if (b.second.first>a.second.first && b.second.second<a.second.second) return true;
	else if (b.second.first<a.second.first && b.second.second>a.second.second) return false;
	else{
		return b.first>a.first;
	}
}

int main(){
	cin>>n;
	for (int i=1;i<=n;i++) cin>>a[i];
	find_ans(1,n);
	sort(ans+1,ans+n/2+1,comp);
	for (int i=1;i<=n/2;i++) cout<<ans[i].first.first<<" "<<ans[i].first.second<<" ";
	cout<<endl;
}

#include<bits/stdc++.h>
using namespace std;
const int Max_N=2*1e5;
int N,A[Max_N+10]={};
pair<int,int> B[Max_N+10]={};
vector<int> Del;
struct kk{
	int l,r,Id1,Id2,Rev;
} T[Max_N*4+10]={};
inline void Build(int x,int l,int r){
	T[x].l=l; T[x].r=r;
	if(l==r){
		if(l%2) T[x].Id1=l;
		else T[x].Id2=l;
		return;
	}
	Build(x<<1,l,(l+r)>>1);
	Build((x<<1)+1,((l+r)>>1)+1,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
//	cout<<T[x].l<<' '<<T[x].r<<' '<<T[x].Id1<<' '<<T[x].Id2<<endl;
}
inline void DownTag(int x){
	if(T[x].Rev){
		swap(T[x<<1].Id1,T[x<<1].Id2);
		swap(T[(x<<1)+1].Id1,T[(x<<1)+1].Id2);
		T[x<<1].Rev^=1; T[(x<<1)+1].Rev^=1;
		T[x].Rev=0;
	}
}
inline void Add(int x,int k,int Val){
	DownTag(x);
	if(T[x].l==T[x].r){
		A[k]=Val;
		return;
	}
	if(k<=T[x<<1].r) Add(x<<1,k,Val);
	else Add((x<<1)+1,k,Val);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline void Change(int x,int l,int r){
	DownTag(x);
	if(l<=T[x].l&&T[x].r<=r){
		swap(T[x].Id1,T[x].Id2);
		T[x].Rev^=1;
		return;
	}
	if(l<=T[x<<1].r) Change(x<<1,l,r);
	if(r>T[x<<1].r) Change((x<<1)+1,l,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline int Ask(int x,int l,int r,int Opt){
//	cout<<x<<' '<<T[x].l<<' '<<T[x].r<<' '<<l<<' '<<r<<endl;
	if(l<=T[x].l&&T[x].r<=r) return Opt==1?T[x].Id1:T[x].Id2;
	int Ans=0,Anss=0;
	if(l<=T[x<<1].r) Ans=Ask(x<<1,l,r,Opt);
	if(r>T[x<<1].r) Anss=Ask((x<<1)+1,l,r,Opt);
	if(A[Ans]>A[Anss]) Ans=Anss;
	return Ans;
}
inline void Solv(){
	Del.push_back(N+1);
	for(int i=1;i<=N/2;i++){
		int Min=Ask(1,1,N,1);
		int r=lower_bound(Del.begin(),Del.end(),Min)-Del.begin();
		int Minn=Ask(1,Min,Del[r]-1,2);
//		cout<<Min<<' '<<Minn<<' '<<Del[r]-1<<endl;
		B[i]=make_pair(A[Min],A[Minn]);
		Add(1,Min,1<<30); Add(1,Minn,1<<30);
		if(Min+1<Minn-1) Change(1,Min+1,Minn-1);
		Del.insert(Del.begin()+r,Min);
		Del.insert(Del.begin()+r+1,Minn);
	}
}
int main(){
	scanf("%d",&N); A[0]=1<<30;
	for(int i=1;i<=N;i++) scanf("%d",&A[i]);
	Build(1,1,N); Solv();
	for(int i=1;i<=N/2;i++) printf("%d %d ",B[i].first,B[i].second); puts("");
	return 0;
}

