const int inf = 1e9;
const int N = 2e5 + 10;  // limit for array size
int n;  // array size
PII t[2 * N][2];

void modify(int p, int value, bool sel) {  // set value at position p
	int pos = p;
	for (t[p += n][sel] = MP(value, pos); p > 1; p >>= 1) t[p >> 1][sel] = min(t[p][sel], t[p ^ 1][sel]);
}

PII query(int l, int r, bool sel) {  // min on interval [l, r)
	PII res = MP(inf, n);
	for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
		if (l & 1) res = min(res, t[l++][sel]);
		if (r & 1) res = min(res, t[--r][sel]);
	}
	return res;
}

vector<int> go(int p, int k)
{
	vector < int > res;

	if (p >= k)
		return res;

	auto g = query(p, k, p & 1);

	vector < vector<int> > V;

	auto pom = query(g.second, k, 1 - (p & 1));

	res.push_back(g.first);
	res.push_back(pom.first);

	V.push_back(go(p, g.second));
	V.push_back(go(g.second + 1, pom.second));
	V.push_back(go(pom.second + 1, k));

	vector<int> st = { 0,0,0 };
	while (true)
	{
		auto pom = MP(inf, inf);
		REP(i, 3)
		{
			if (V[i].size() > st[i])
				pom = min(pom, MP(V[i][st[i]], i));
		}

		if (pom.second == inf)
			break;

		res.push_back(V[pom.second][st[pom.second]]);
		st[pom.second]++;
		res.push_back(V[pom.second][st[pom.second]]);
		st[pom.second]++;
	}

	return res;
}

int main()
{
	scanf("%d", &n);

	REP(i, 2 * n + 1)
		t[i][0] = t[i][1] = MP(inf, i);

	REP(i, n)
	{
		int p;
		scanf("%d", &p);
		if (i & 1)
		{
			modify(i, p, 1);
			modify(i, inf, 0);
		}
		else
		{
			modify(i, inf, 1);
			modify(i, p, 0);
		}
	}

	vector<int> q = go(0, n);

	REP(i, n)
		printf("%d ", q[i]);
	printf("\n");

	return 0;
}

