//[l,r)での辞書順最小のペアのインデックスを返す
pii dfs1(int l, int r){
    //辞書順最小のもの
    int L, R;
    pii a, b;
    if(l%2 == 0){
        a = seg2.query(l/2, r/2);
        L = a.second;
        b = seg1.query(L/2, r/2);
        R = b.second;
    }
    else{
        a = seg1.query(l/2, r/2);
        L = a.second;
        b = seg2.query((L+1)/2, (r+1)/2);
        R = b.second;
    }
    return pii(L, R);
}

int main(){
    int N;
    cin >> N;
    rep(i, N){
        cin >> p[i];
        if(i%2 == 0) seg2.change(i/2, pii(p[i], i));
        else seg1.change(i/2, pii(p[i], i));
    }
    vector<int> ans;
    que.push(P(p[dfs1(0, N).first], pii(0, N)));
    while(!que.empty()){
        int l = que.top().second.first, r = que.top().second.second;
        que.pop();
        pii x = dfs1(l, r);
        int L = x.first, R = x.second;
        ans.pb(p[L]), ans.pb(p[R]);
        if(l < L) que.push(P(p[dfs1(l, L).first], pii(l, L)));
        if(L+1 < R) que.push(P(p[dfs1(L+1, R).first], pii(L+1, R)));
        if(R+1 < r) que.push(P(p[dfs1(R+1, r).first], pii(R+1, r)));
    }
    for(auto &e: ans) cout << e << ' ';
    cout << endl;
}

