	///read
	int n; cin >> n;
	rep(i, 1, n + 1) {
		scanf("%d", &p[i]);
		pos[p[i]] = i;
	}


	///prework
	tree.init(n);
	priority_queue<int, vector<int>, greater<int> > que;
	pii tmp = tree.query(1, n - 1);
	que.push(tmp.fi);

	///work
	set<int> s; s.insert(1); bod[1] = n;
	vi ans;
	rep(i, 0, n/2) {
		int u = que.top(); que.pop();
		ans.pb(u); u = pos[u]; // de(u);
		auto it = s.lower_bound(u);
		int beg = *it;

		//get v
		pii tmp = tree.query(u + 1, bod[*it]); 
		int v;
		if (u & 1) v = tmp.se;
			else v = tmp.fi;
		ans.pb(v); 
		v = pos[v];

		//change
		tree.change(u, INF);
		tree.change(v, INF);
		if (v < bod[beg]) {
			bod[v + 1] = bod[beg];
			pii nex = tree.query(v + 1, bod[v + 1] - 1);
			if ((v + 1) & 1) que.push(nex.fi);
				else que.push(nex.se);
			s.insert(v + 1);
		}
		if (u > beg) {
			bod[beg] = u - 1;
			pii nex = tree.query(beg, u - 1 - 1);
			if (beg & 1) que.push(nex.fi);
				else que.push(nex.se);
		}
		else s.erase(*it);
		if (u + 1 < v) {
			bod[u + 1] = v - 1;
			pii nex = tree.query(u + 1, v - 1 - 1);
			if ((u + 1) & 1) que.push(nex.fi);
				else que.push(nex.se);
			s.insert(u + 1);
		}
	}

	///print
	rep(i, 0, sz(ans)) printf("%d ", ans[i]);




