constexpr int INF = 1 << 29;
constexpr int LIM = 404040;

class RMQ {
    int arr[LIM];
    int n;
    public:

    RMQ() {}

    RMQ(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        fill(arr, arr+LIM, INF);
    }

    void update(int k, int a) {
        k += n-1;
        arr[k] = a;
        while (k > 0) {
            k = (k-1) / 2;
            arr[k] = min(arr[2*k+1], arr[2*k+2]);
        }
    }

    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1) r = n;
        if (r <= a || b <= l) return INF;

        if (a <= l && r <= b) return arr[k];
        else {
            int vl = query(a, b, k*2+1, l, (l+r)/2);
            int vr = query(a, b, k*2 + 2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

int N, a[202020];

RMQ rmq[2];

int loc[202020];

vector<int> solve(int left, int right) {
    vector<int> ans;
    if (left >= right) return ans;

    int b = left%2;
    int v = rmq[b].query(left, right), lv = loc[v];
    int w = rmq[1-b].query(lv+1, right), lw = loc[w];

    ans.push_back(v); ans.push_back(w);
    rmq[b].update(lv, INF); rmq[1-b].update(lw, INF);

    vector<int> v1 = solve(left, lv);
    vector<int> v2 = solve(lv+1, lw);
    vector<int> v3 = solve(lw+1, right);

    for (int j1 = 0, j2 = 0, j3 = 0; j1 < v1.size() || j2 < v2.size() || j3 < v3.size(); ) {
        if (j1 < v1.size() &&
                (j2 == v2.size() || v1[j1] < v2[j2]) && (j3 == v3.size() || v1[j2] < v3[j3])) {
            ans.push_back(v1[j1]); ans.push_back(v1[j1+1]);
            j1 += 2;
        } else if (j2 < v2.size() &&
                (j1 == v1.size() || v2[j2] < v1[j1]) && (j3 == v3.size() || v2[j2] < v3[j3])) {
            ans.push_back(v2[j2]); ans.push_back(v2[j2+1]);
