void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	auto F = [](pair<ll,ll> x,pair<ll,ll> y){
		if(x.first<y.first) return x;
		return y;
	};
	vector<SegmentTree<pair<ll,ll>,decltype(F)>> segv(2,SegmentTree<pair<ll,ll>,decltype(F)>(N, F, {INF,INF}));
	rep(i,N){
		segv[i%2].update(i, {a[i],i});
	}

	vector<ll> ans;
	//{最小値、index, l, r}
	priority_queue<array<ll,4>,vector<array<ll,4>>,greater<array<ll,4>>> que;
	ll l=0;
	ll r=N;
	pair<ll,ll> pr=segv[l%2].query(l,r);
	que.push({pr.first, pr.second, l, r});

	while(!que.empty()){
		array<ll,4> ar=que.top();
		que.pop();
		ll x=ar[0];
		ll index=ar[1];
		ll l=ar[2];
		ll r=ar[3];
		pair<ll,ll> y=segv[(l+1)%2].query(index,r);
		ans.push_back(x);
		ans.push_back(y.first);
		vector<pair<ll,ll>> z{{l,index}, {index+1,y.second}, {y.second+1, r}};
		for(pair<ll,ll> &range : z){
			ll l=range.first;
			ll r=range.second;
			if(l<r){
				pair<ll,ll> pr=segv[l%2].query(l,r);
				que.push({pr.first, pr.second, l, r});
			}
		}
	}

	pv(ans);

}

