struct tree{
    vector<int> data;
    tree(){
        data.resize(4 * maxn);
        fill(data.begin(), data.end(), maxn);
    }
    void update(int id, int l, int r, int pos, int v){
        if(l == r) data[id] = v;
        else{
            int mid = (l + r)>>1;
            if(pos <= mid) update(id + id, l, mid, pos, v);
            else update(id + id + 1, mid + 1, r, pos, v);
            data[id] = min(data[id + id], data[id + id + 1]);
        }
    }
    void update(int pos, int v){
        update(1, 0, maxn-1, pos, v);
    }
    int query(int id, int l, int r, int x, int y){
        if(l > y || r < x) return maxn;
        if(x <= l && r <= y) return data[id];
        int mid = (l + r)>>1;
        return min(query(id + id, l, mid, x, y), query(id + id + 1, mid + 1, r, x, y));
    }
    int query(int x, int y){
        return query(1, 0, maxn-1, x, y);
    }
};
tree pares, impares;
