    impares = tree();
    for(int e = 0; e < n; e++)
        if(e & 1) impares.update(e, arr[e]);
        else pares.update(e, arr[e]);
    sol.clear();
    priority_queue<tuple<int, int, int > > pq;
    pq.push(make_tuple(- pares.query(0, n-1), 0, n-1));
    while(!pq.empty()){
        int best, second, l, r;
        tie(best, l, r) = pq.top(); pq.pop();
        // if(l >= r) continue;
        if(l % 2 == 0){
            best = pares.query(l, r);
            second = impares.query(pos[best] + 1, r);
        } else {
            best = impares.query(l, r);
            second = pares.query(pos[best] + 1, r);
        }
        sol.push_back(best);
        sol.push_back(second);
        if(l % 2 == 1 && l < pos[best])
            pq.push(make_tuple(- impares.query(l, pos[best]-1), l, pos[best]-1));
        else if(l % 2 == 0 && l < pos[best])
            pq.push(make_tuple(- pares.query(l, pos[best]-1), l, pos[best]-1));

        if(l % 2 == 1 && pos[best] + 1 < pos[second])
            pq.push(make_tuple( - pares.query(pos[best] + 1, pos[second] - 1), pos[best] + 1,
            pos[second]-1));
        else if(l % 2 == 0 && pos[best] + 1 < pos[second])
            pq.push(make_tuple( - impares.query(pos[best] + 1, pos[second] - 1), pos[best] + 1,
            pos[second]-1));

        if(l % 2 == 1 && pos[second] < r)
            pq.push(make_tuple( - impares.query(pos[second] + 1, r), pos[second] + 1, r));
        else if(l % 2 == 0 && pos[second] < r)
            pq.push(make_tuple( - pares.query(pos[second] + 1, r), pos[second] + 1, r));
    }
    for(int e = 0; e < n; e++)
        printf("%d%c", sol[e], " \n"[e == n-1]);
    return 1;
}
