int dfs(int l, int r){
	int d = INF;
	while(1){
		PLL mini = sg.query(l, r);
		if(mini.first == INF_LL) break;;

		if(sg.query2(mini.second+1, r, (mini.second+1)%2).first != INF_LL){
			PLL nxt = sg.query2(mini.second+1, r, (mini.second+1)%2);
			sg.update(mini.second, INF_LL);
			sg.update(nxt.second, INF_LL); 

			int a = dfs(mini.second+1, nxt.second);
			res.push_back({a, {mini.first, nxt.first}});
			dfs(l, mini.second);
			dfs(nxt.second+1, r);
			d = min(a, d);
		}else{
			PLL bef = sg.query2(l, mini.second, (mini.second+1)%2);
			if(bef.first == INF_LL) break;;
			sg.update(mini.second, INF_LL);
			sg.update(bef.second, INF_LL);

			int a = dfs(bef.second+1, mini.second);
			res.push_back({a, {bef.first, mini.first}});
			dfs(l, bef.second);
			dfs(mini.second+1, r);
			d = min(a, d);
		}
	}
	return d-1;
}

