void modify(int l,int r,int pos,int v,int idx,PI* seg){
	if(l==r){
		seg[idx]=PI(v,l);
	}else{
		int mid=(l+r)>>1;
		if(pos<=mid)
			modify(l,mid,pos,v,idx<<1,seg);
		else
			modify(mid+1,r,pos,v,idx<<1|1,seg);
		seg[idx]=min(seg[idx<<1],seg[idx<<1|1]);
	}
}
