	if(l==ql && r==qr){
		return seg[idx];
	}
	int mid=(l+r)>>1;
	if(qr<=mid)
		return query(l,mid,ql,qr,idx<<1,seg);
	else if(ql>mid)
		return query(mid+1,r,ql,qr,idx<<1|1,seg);
	else{
		return min(query(l,mid,ql,mid,idx<<1,seg),query(mid+1,r,mid+1,qr,idx<<1|1,seg));
	}
}
