int mmin(int x,int y){ return a[x]<a[y]?x:y;}
void build(int nd,int l,int r)
{
	if(l==r)
	{
		mi[nd][l&1]=l;
		mi[nd][l&1^1]=0;
		return ;
	}
	int mid=(l+r)/2;
	build(nd<<1,l,mid);
	build(nd<<1|1,mid+1,r);
	mi[nd][0]=mmin(mi[nd<<1][0],mi[nd<<1|1][0]);
	mi[nd][1]=mmin(mi[nd<<1][1],mi[nd<<1|1][1]);
