int query(int nd,int l,int r,int ql,int qr,int d)
{
	if(l>qr||r<ql) return 0;
	if(l>=ql&&r<=qr) return mi[nd][d];
	int mid=(l+r)/2;
	return mmin(query(nd<<1,l,mid,ql,qr,d),query(nd<<1|1,mid+1,r,ql,qr,d));
}
