void dfs(int l=0, int r=n, vector<int> &_ans=ans, bool bit=false) {
    if (l >= r) {
        _ans = vector<int>();
        return;
    }
    int top = sgt[0 ^ bit].query(l, r),
        bot = sgt[1 ^ bit].query(pinv[top]+1, r);
    _ans.push_back(top);
    _ans.push_back(bot);
    if (r - l == 2) return;
    vector<int> left, mid, right;
    dfs(l, pinv[top], left, bit);
    dfs(pinv[top]+1, pinv[bot], mid, !bit);
    dfs(pinv[bot]+1, r, right, bit);
    for (int i=0, j=0, k=0; ; ) {
        P lp = (i < left.size()  ? P{left[i],  left[i+1]}  : P_INF),
          mp = (j < mid.size()   ? P{mid[j],   mid[j+1]}   : P_INF),
          rp = (k < right.size() ? P{right[k], right[k+1]} : P_INF),
          minp = min({lp, mp, rp});
        if (minp == P_INF) break;
        else if (minp == lp) i += 2;
        else if (minp == mp) j += 2;
        else if (minp == rp) k += 2;
        _ans.push_back(minp.fi);
        _ans.push_back(minp.se);        
    }
}

