struct Data {
  int num, idx;
  Data() : num(0x7FFFFFFF), idx(-1) {}
  Data(int n, int i) : num(n), idx(i) {}
};

inline Data Merge(Data left, Data right) {
  return left.num < right.num ? left : right;
}

struct SegmentTree {
  int n; vector<Data> data;
  SegmentTree(int N) : n(1 << N), data(n * 2) {}
  void update (int pos, Data value) {
    data[pos] = value;
    while (pos < 2*n-1) {
      int l = pos, r = pos^1;
      if (l > r) swap(l, r);
      pos = pos / 2 + n;
      data[pos] = Merge(data[l], data[r]);
    }
  }
  Data sub(int fr, int to, int node, int la, int ra) {
    if (ra<=fr || to<=la) return Data();
    if (fr<=la && ra<=to) return data[node];
    Data vl = sub(fr, to, (node-n)*2+0, la, (la+ra)/2);
    Data vr = sub(fr, to, (node-n)*2+1, (la+ra)/2, ra);
    return Merge(vl, vr);
  }
  Data query(int fr, int to) { return sub(fr, to, 2*n-2, 0, n); }
};

struct Tree {
  tuple<int,int> val;
  vector<shared_ptr<Tree>> children;
};

shared_ptr<Tree> solve(int fr, int to, SegmentTree& even, SegmentTree& odd) {
  if (fr == to) {
    return nullptr;
  }
  auto t1 = even.query(fr, to);
  auto t2 = odd.query(t1.idx+1, to);
  auto c1 = solve(fr, t1.idx, even, odd);
  auto c2 = solve(t1.idx+1, t2.idx, odd, even);
  auto c3 = solve(t2.idx+1, to, even, odd);
  auto res = make_shared<Tree>();
  res->val = make_tuple(t1.num, t2.num);
  if (c1) res->children.push_back(c1);
  if (c2) res->children.push_back(c2);
  if (c3) res->children.push_back(c3);
  return res;
}

bool operator>(const shared_ptr<Tree>& lhs, const shared_ptr<Tree>& rhs) {
  return lhs->val > rhs->val;
}

