		p[tmp] = i;

		if(i%2 == 0){
			evensg.update(i, tmp);
		}else{
			oddsg.update(i, tmp);
		}
	}

	deque<long long> ans;
	//                     first ,          head,   tail
	priority_queue<pair<long long, pair<long long, long long> >,
		vector<pair<long long, pair<long long, long long> > >,
		greater<pair<long long, pair<long long, long long> > > >Q;

	Q.push(make_pair(evensg.get(0, N), make_pair(0, N)));

	while(!Q.empty()){
		long long head = Q.top().second.first;
		long long tail = Q.top().second.second;
		Q.pop();
		if(head + 1 >= tail){
			continue;
		}
		if((tail - head)%2 != 0){
			return 1;
		}

		long long fpos;
		long long fval;
		long long spos;
		long long sval;

		if(head % 2 == 0){
			fval = evensg.get(head, tail);
			fpos = p[fval];
			sval = oddsg.get(fpos + 1, tail);
			spos = p[sval];
		}else{
			fval = oddsg.get(head, tail);
			fpos = p[fval];
			sval = evensg.get(fpos + 1, tail);
			spos = p[sval];
		}

		if(fval == INF || sval == INF){
			return 1;
		}

		ans.push_back(fval);
		ans.push_back(sval);

		head = head;
		tail = fpos;
		if(head % 2 == 0){
			fval = evensg.get(head, tail);
		}else{
			fval = oddsg.get(head, tail);
		}
		Q.push(make_pair(fval, make_pair(head, tail)));


		head = fpos + 1;
		tail = spos;
		if(head % 2 == 0){
			fval = evensg.get(head, tail);
		}else{
			fval = oddsg.get(head, tail);
		}
		Q.push(make_pair(fval, make_pair(head, tail)));


		head = spos + 1;
		tail = tail;
		if(head % 2 == 0){
			fval = evensg.get(head, tail);
		}else{
			fval = oddsg.get(head, tail);
		}
		Q.push(make_pair(fval, make_pair(head, tail)));
	}

	for(int i = 0; i < ans.size(); i++){
		cout << ans[i];
		if(i != ans.size() - 1){
			cout << " ";
		}
	}
	cout << endl;
}

