  }

  int nk = ds.size();
  D nd;
  reps(i, ss.X, ss.Y) {
    rep(j, 2) d.st[j].erase(pii(P[i], i));
    nd.st[(i-ss.X)%2].insert(pii(P[i], i));
    belong[i] = nk;
  }

  pii ret;
  if (!rev) {
    nd.seg = as;
    d.seg = bs;
    swap(d.st[0], d.st[1]);
    ret = pii(nk, k);
  } else {
    nd.seg = bs;
    d.seg = as;
    ret = pii(k, nk);
  }
  ds.eb(nd);
  return ret;
}

