int rec(int l, int r, vector<pair<int,int> >& ans) {
  if (r == l) {
    return 0;
  } else if (r-l == 1) {
    ans.push_back(make_pair(a[l], a[r]));
    return 0;
  } else if (r-l == 2) {
    if (a[l] < a[r]) {
      ans.push_back(make_pair(a[l+1], a[r]));
      return a[l];
    } else {
      ans.push_back(make_pair(a[l], a[l+1]));
      return a[r];
    }
  }

  vector<pair<int,int> > left;
  vector<pair<int,int> > right;
  pair<int,int> pp;
  int p,il = 0,ir = 0, imin = l;

  if ((r - l + 1) % 2 == 0) {
    for (int i = l + 1; i <= r-1; i++) {
      if (a[i] < a[imin]) {
        imin = i;
      }
    }

    if (imin == l) {
      p = rec(l + 1, r, ans);
      ans.push_back(make_pair(a[imin], p));
    } else if (imin == r - 1) {
      rec(l, r - 2, ans);
      ans.push_back(make_pair(a[r-1], a[r]));
    } else {
      if ((imin - l) % 2 == 0) {
        rec(l, imin - 1, left);
        pp.first = a[imin];
        pp.second = rec(imin + 1, r, right);
      } else {
        pp.first = rec(l, imin - 1, left);
        pp.second = a[imin];
        rec(imin + 1, r, right);
      }

      while (il < left.size() && ir < right.size()) {
        if (left[il].first > right[ir].first) {
          ans.push_back(left[il++]);
        } else {
          ans.push_back(right[ir++]);
        }
      }

      while (il < left.size()) {
        ans.push_back(left[il++]);
      }

      while (ir < right.size()) {
        ans.push_back(right[ir++]);
      }

      ans.push_back(pp);
    }

    return 0;
  } else {
    for (int i = l + 1; i <= r; i++) {
      if (a[i] < a[imin]) {
        imin = i;
      }
    }

    if (imin == l) {
      rec(l + 1, r, ans);
    } else if (imin == r) {
      rec(l, r - 1, ans);
    } else {
      rec(l, imin - 1, left);
      rec(imin + 1, r, right);

      while (il < left.size() && ir < right.size()) {
        if (left[il].first > right[ir].first) {
          ans.push_back(left[il++]);
        } else {
          ans.push_back(right[ir++]);
        }
      }

      while (il < left.size()) {
        ans.push_back(left[il++]);
      }

      while (ir < right.size()) {
        ans.push_back(right[ir++]);
      }
    }

    return a[imin];
  }
}

