typedef pair<int, int> P;
typedef pair<P, P> PP;
class Min {
public:
	int operator()(int a, int b) const {
		return min(a, b);
	}
};
template<typename T, typename BiOp>
struct SegmentTree {
	vector<T> data;
	T e;
	BiOp op;
	int size;
	SegmentTree(int n, T e, BiOp op) :e(e), op(op) {
		size = 1;
		while (size < n) size *= 2;
		data.resize(size * 2 - 1);
		for (int i = 0; i < size * 2 - 1; i++) data[i] = e;
	}
	void update(int k, T v) {
		k += size - 1;
		data[k] = v;
		while (k > 0) {
			k = (k - 1) / 2;
			data[k] = op(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}
	T query(int a, int b, int k, int l, int r) const {
		if (b <= l || r <= a) return e;
		if (a <= l && r <= b) {
			return data[k];
		}
		return op(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
	}
	T query(int a, int b) const {
		return query(a, b, 0, 0, size);
	}
	T get(int i) {
		return data[i + size - 1];
	}
};
int p[200000];
int pos[200000];
P get_min(SegmentTree<int, Min> &even, SegmentTree<int, Min> &odd, int l, int r) {
	if (l % 2 == 0) {
		int a = even.query(l, r);
		int b = odd.query(pos[a], r);
		return P(a, b);
	}
	else {
		int a = odd.query(l, r);
		int b = even.query(pos[a], r);
		return P(a, b);
	}
}
int main() {
	int N;
	cin >> N;
	SegmentTree<int, Min> even(N, 1 << 30, Min()), odd(N, 1 << 30, Min());
	for (int i = 0; i < N; i++) {
		cin >> p[i];
		p[i]--;
		pos[p[i]] = i;
		if (i % 2 == 0) even.update(i, p[i]);
		else odd.update(i, p[i]);
	}
	P head = get_min(even, odd, 0, N);
	priority_queue<PP, vector<PP>, greater<PP>> Q;
	Q.push(PP(P(head.first, head.second), P(0, N)));
	vector<int> ans;
	while (!Q.empty()) {
		PP now = Q.top(); Q.pop();
		ans.push_back(now.first.first + 1);
		ans.push_back(now.first.second + 1);
		int a = pos[now.first.first], b = pos[now.first.second];
		int l = now.second.first, r = now.second.second;
		if (l < a) {
			Q.push(PP(get_min(even, odd, l, a), P(l, a)));
		}
		if (b - a > 1) {
			Q.push(PP(get_min(even, odd, a + 1, b), P(a + 1, b)));
		}
		if (b + 1 < r) {
			Q.push(PP(get_min(even, odd, b + 1, r), P(b + 1, r)));
		}
	}
	for (int i = 0; i < N; i++) cout << ans[i] << " ";
