void updata(int x, int no)
{  
    int lx, i;
    while (x <= n)  
    {  
        h[no][x] = a[no][x];
        lx = lowbit(x);  
        for (i=1; i<lx; i<<=1)
            h[no][x] = min(h[no][x], h[no][x-i]); 
        x += lowbit(x);
    }         
}  
int query(int x, int y, int no)  
{  
    int ans = INF;  
    while (y >= x)  
    {  
        ans = min(a[no][y], ans); 
        y --;  
        for (; y-lowbit(y) >= x; y -= lowbit(y))
            ans = min(h[no][y], ans);  
    }  
    return ans;  
}

