	}

	segment_tree<min_indexed_t<ll>>  even(n,pe), odd(n,po);
	pq_greater<tll6> pq;
	vpll res;

	auto push_pq=[&](ll l, ll r) {
		if (l == r)return;
		if (l % 2 == 0) {
			auto x = even.range_concat(l, r);
			auto y = odd.range_concat(x.second +1, r);
			pq.push({ x.first,y.first,x.second,y.second,l,r });
		}
		else
		{
			auto x = odd.range_concat(l, r);
			auto y = even.range_concat(x.second +1, r);
			pq.push({ x.first,y.first,x.second,y.second,l,r });
		}
	};
	push_pq(0, n);
	while (!pq.empty()) {
		ll x, y, x_ind, y_ind, l, r;
		tie(x, y, x_ind, y_ind, l, r) = pq.top();
		res.push_back({ x,y });
		pq.pop();
		push_pq(l, x_ind);
		push_pq(x_ind + 1, y_ind);
		push_pq(y_ind + 1, r);
	}

	rep(i, 0, n / 2-1) cout << res[i].first << " "<< res[i].second <<" ";
