const int MAX_N = 2 * 10e5;
const int inf = 1 << 29;
int dat1[2 * MAX_N - 1];
int dat2[2 * MAX_N - 1];

struct RMQ {
  int n;
  int* dat;

  RMQ(int n_, int* dat_) {
    dat = dat_;
    n = 1;
    while (n < n_) n *= 2;
    for (int i = 0; i < 2 * n -1; ++i) {
      dat[i] = inf;
    }
  }

  void update(int k, int a) {
    k += n - 1;
    dat[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  int query(int a, int b) {
    return query(a, b, 0, 0, n);
  }

  int query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return inf;
    if (a <= l && r <= b) return dat[k];

    int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
    int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

    return min(vl, vr);
  }
};


int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  while (cin >> n) {
    vector<int> a(n);
    cin >> a;

    if (n == 2) {
      cout << a[0] << ' ' << a[1] << endl;
      continue;
    }

    vector<int> u(1, n + 1);

    map<int, int> idx;
    for (int i = 0; i < n; ++i) {
      idx[a[i]] = i;
    }

    int mx_o = -1;
    int mx_e = -1;

    for (int i = 0; i + 1 < n; ++i) {
      if (i % 2) setmax(mx_o, a[i]);
      else setmax(mx_e, a[i]);
    }

    RMQ odd(n, dat1);
    RMQ even(n, dat2);

    for (int j = 0; j < 2; ++j) {

      for (int i = 0; i < n; ++i) {
        if (i % 2) {
          odd.update(i, a[i]);
          even.update(i, inf);
        } else {
          odd.update(i, inf);
          even.update(i, a[i]);
        }
      }

      vector<int> v;
      int x, y;
      if (j) {
        x = mx_e;
        y = a[idx[x] + 1];
        even.update(idx[x], inf);
        odd.update(idx[y], inf);
      } else {
        x = mx_o;
        y = a[idx[x] + 1];
        odd.update(idx[x], inf);
        even.update(idx[y], inf);
      }
      // cout << "xy >> " << make_pair(x, y) << endl;

      {
        int p = even.query(0, n);
        int q = odd.query(idx[p], n);
        even.update(idx[p], inf);
        odd.update(idx[q], inf);
        v.push_back(p);
        v.push_back(q);
      }      

      for (int i = 0; i < n / 2 - 2; ++i) {
        int x1 = even.query(0, n);
        int y1 = odd.query(idx[x1], n);

        int x2 = odd.query(0, n);
        int y2 = even.query(idx[x2], n);

        // cout << make_pair(x1, y1) << " v.s. " << make_pair(x2, y2) << endl;

        if (y1 == inf) {
          v.push_back(x2);
          v.push_back(y2);
          odd.update(idx[x2], inf);
          even.update(idx[y2], inf);          
        } else if (y2 == inf) {
          v.push_back(x1);
          v.push_back(y1);
          even.update(idx[x1], inf);
          odd.update(idx[y1], inf);
        } else {
          if (x1 < x2) {
            v.push_back(x1);
            v.push_back(y1);
            even.update(idx[x1], inf);
            odd.update(idx[y1], inf);
          } else {
            v.push_back(x2);
            v.push_back(y2);
            odd.update(idx[x2], inf);
            even.update(idx[y2], inf);
          }
        }
      }
      v.push_back(x);
      v.push_back(y);

      setmin(u, v);
    }

    each (i, u) cout << i << ' ';
    cout << endl;
  }

  return 0;
}

