RMQ<pair<int,int>> odd(0,0);
RMQ<pair<int,int>> even(0,0);

vector<pair<int,int>> result;
int arr[2*100000+10];
priority_queue<pipii,std::vector<pipii> ,std::greater<pipii>> pq;

//範囲  l <= x < r
void solve(){

    int l = pq.top().second.first;
    int r = pq.top().second.second;

    //cout << l << " " << r << endl;

    pq.pop();

    if(l + 2 == r){
        result.push_back(pii(arr[l],arr[l+1]));
    }else{

        pii p1;
        pii p2;

        if(l%2 == 0){
            p1 = even.query(l,r);
            p2 = odd.query(p1.second,r);
        }else{
            p1 = odd.query(l,r);
            p2 = even.query(p1.second,r);
        }

        //cout << p1.first << ":" << p1.second << endl;
        //cout << p2.first << ":" << p2.second << endl;

        result.push_back(pii(p1.first,p2.first));

        vector<pair<int, int>> next = {{l, p1.second}, {p1.second + 1, p2.second}, {p2.second + 1, r}};
        for(auto n: next){
            if(n.second - n.first > 1){
                pq.push(pipii(( (n.first % 2 == 0) ? even : odd ).query(n.first, n.second).first, n));
            }
        }

    }
    return ;
}


