        arr[i*2+1] = b;

        even.update(2*i,pair<int,int>(a,2*i));
        odd.update(2*i+1,pair<int,int>(b,2*i+1));
    }

    pq.push({0,{0,n*2}});

    while(!pq.empty())
        solve();

    //cout << result.size() << endl;

    for(int i = 0; i < result.size(); i++){
        cout << result[i].first << " " << result[i].second << (i == result.size()-1 ? '\n' : ' ');
    }

}

