const int maxn=200005;
int n;
int a[maxn],pos[maxn],st[maxn*2][30],Log2[maxn];
priority_queue<pair<pii,pii> >q;

int two(int x){
	int res=1,m=2;
	while(x){
		if(x&1)res*=m;
		m*=m;
		x>>=1;
	}
	return res;
}

pii get_ans(int l,int r){
	int base=Log2[r-l];
	int mn1;
	if(base)mn1=min(st[l][base],st[r-two(base)+1][base]);
	else mn1=st[l][base];
	int pos1=pos[mn1];
	base=Log2[r-pos1-1];
	int mn2;
	if(base)mn2=min(st[pos1+1][base],st[r-two(base)+2][base]);
	else mn2=st[pos1+1][base];
	return mk(-mn1,-mn2);
}

int main(){
//	freopen("E.in","r",stdin);
//	freopen("E.out","w",stdout); 
	scanf("%d",&n);
	REP(i,n)scanf("%d",&a[i]),pos[a[i]]=i;
	Log2[0]=0;
	REP(i,n){
		int base=Log2[i-1];
		if(two(base+1)<=i)base++;
		Log2[i]=base;
	}
	REP(i,n)st[i][0]=st[i][1]=a[i];
	int len=1,j=1;
	while(len<n){
		len*=2;
		j++;
		REP(i,n)st[i][j]=min(st[i][j-1],st[i+len][j-1]);
	}
	q.push(mk(get_ans(1,n),mk(1,n)));
	while(!q.empty()){
		pii c=q.top().fi,d=q.top().se;
		q.pop();
		c.fi=-c.fi;c.se=-c.se;
		printf("%d %d ",c.fi,c.se);
		c.fi=pos[c.fi];c.se=pos[c.se];
		if(c.fi-d.fi>=2)q.push(mk(get_ans(d.fi,c.fi-1),mk(d.fi,c.fi-1)));
		if(c.se-c.fi>=3)q.push(mk(get_ans(c.fi+1,c.se-1),mk(c.fi+1,c.se-1)));
		if(d.se-c.se>=2)q.push(mk(get_ans(c.se+1,d.se),mk(c.se+1,d.se)));
	}
	return 0;
}

