const ll N_ = (1 << 18);
ll segOdd[2*N_-1];
//Range Minimum Query
void updateOdd(ll k, ll x){
  k += N_-1;
  segOdd[k] = x;
  while(k > 0){
    k = (k-1)/2;
    segOdd[k] = min(segOdd[2*k+1], segOdd[2*k+2]);
  }
}

ll queryOdd(ll x, ll y, ll k, ll left, ll right){
  if(right <= x || y <= left) return INFL;
  if(x <= left && right <= y) return segOdd[k];
  ll mid = (left + right) / 2;
  ll l = queryOdd(x, y, 2*k+1, left, mid);
  ll r = queryOdd(x, y, 2*k+2, mid, right);
  return min(l, r);
}

ll segEven[2*N_-1];
//Range Minimum Query
void updateEven(ll k, ll x){
  k += N_-1;
  segEven[k] = x;
  while(k > 0){
    k = (k-1)/2;
    segEven[k] = min(segEven[2*k+1], segEven[2*k+2]);
  }
}

ll queryEven(ll x, ll y, ll k, ll left, ll right){
  if(right <= x || y <= left) return INFL;
  if(x <= left && right <= y) return segEven[k];
  ll mid = (left + right) / 2;
  ll l = queryEven(x, y, 2*k+1, left, mid);
  ll r = queryEven(x, y, 2*k+2, mid, right);
  return min(l, r);
}

ll N;
vector<ll> p, q;

vector<pair<ll, ll>> saiki(ll start, ll n){
  if(n == 0) return {};
  if(n == 2){
    return {{p[start], p[start + 1]}};
  }
  ll x, y, x_pos, y_pos;
  if(start % 2){
    x = queryOdd(start, start + n, 0, 0, N_);
    x_pos = q[x];
    y = queryEven(x_pos+1, start + n, 0, 0, N_);
    y_pos = q[y];
  }else{
    x = queryEven(start, start + n, 0, 0, N_);
    x_pos = q[x];
    y = queryOdd(x_pos+1, start + n, 0, 0, N_);
    y_pos = q[y];
  }
  vector<pair<ll, ll>> res = {{x, y}};
  vector<pair<ll, ll>> a1 = saiki(start, x_pos-start);
  vector<pair<ll, ll>> a2 = saiki(x_pos+1, y_pos-x_pos-1);
  vector<pair<ll, ll>> a3 = saiki(y_pos+1, n-(y_pos-start)-1);
  ll at1 = 0, at2 = 0, at3 = 0;
  while(at1 < a1.size() || at2 < a2.size() || at3 < a3.size()){
    pair<ll, ll> A, B, C;
    if(at1 == a1.size()){
      A = {INFL, INFL};
    }else{
      A = a1[at1];
    }
    if(at2 == a2.size()){
      B = {INFL, INFL};
    }else{
      B = a2[at2];
    }
    if(at3 == a3.size()){
      C = {INFL, INFL};
    }else{
      C = a3[at3];
    }
    pair<ll, ll> D;
    if(A <= B && A <= C){
      at1++;
      D = A;
    }else if(B <= A && B <= C){
      at2++;
      D = B;
    }else{
      at3++;
      D = C;
    }
    res.pb(D);
  }
  return res;
}

void solve(){
  rep(i, N){
    updateEven(i, INFL);
    updateOdd(i, INFL);
    if(i % 2) updateOdd(i, p[i]);
    else updateEven(i, p[i]);
  }
  vector<pair<ll, ll>> ans = saiki(0, N);
  rep(i, ans.size()){
    cout << ans[i].f + 1 << " " << ans[i].s + 1;
    if(i == ans.size() - 1) cout << endl;
    else cout << " ";
  }
}

