        cout << delim << a << " " << b;
        delim = " ";

        auto ib = r[b];

        st.set(ia / 2, ia % 2, 1L << 20);
        st.set(ib / 2, ib % 2, 1L << 20);
        st.swap_range((ia + 1) / 2, (ib + 1) / 2);
        picked.insert(ia);
        picked.insert(ib);
    }

    cout << endl;
}

