	pair<int, int> solve(int l, int r) {
		pair<int, int> ans = {INF, INF};
		for (int i = l; i < r; i++) {
			for (int j = i + 1; j < r; j++) {
				if ((i - l) % 2 == 1) continue;
				if ((j - i) % 2 == 0) continue;
				ans = min(ans, make_pair(a[i], a[j]));
			}
		}
		// if (ans.first == INF) {
		// 	cerr << l << ' ' << r << endl;
		// 	exit(0);
		// }
		return ans;
	} 

