int segtree[2][1<<19];
void seginit(){
	lol(z,2)lol(i,(1<<19))segtree[z][i]=mod;
}
void update(int i,int x,int z){
	i+=(1<<18)-1;
	segtree[z][i]=min(segtree[z][i],x);
	while(i){
		i=(i-1)/2;
		segtree[z][i]=min(segtree[z][i],x);
	}
}
int query(int left,int right,int k,int a,int b,int z){
	if(b<=left||right<=a)return mod;
	if(left<=a&&b<=right)return segtree[z][k];
	int mid=(a+b)/2;
	return min(query(left,right,k*2+1,a,mid,z),query(left,right,k*2+2,mid,b,z));
}
int rmq(int left,int right,int z){
	//cout<<"$$"<<left<<" "<<right<<" "<<z<<endl;
	return query(left,right+1,0,0,(1<<18),z);
}

