    auto f = [](pll a, pll b){
        return min(a, b);
    };
    pll e = {INF, -1};
    vector<SegmentTree<pll>> seg(2, SegmentTree<pll>(N, f, e));
    REP(i, N){
        seg[i%2].set(i, {p[i], i});
