#define INF 1120000000

template<typename T> // INFに注意
class SegTree {
private:
  int n;
  vector<T> data;
  T _query(int a, int b, int k, int l, int r){
    if(r<=a || b<=l) return INF;
    if(a<=l && r<=b) return data[k];
    T vl=_query(a,b,k*2+1,l,(l+r)/2);
    T vr=_query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
public:
  SegTree(int n_){
    n=1;
    while(n<n_) n*=2;
    data.resize(2*n-1);
    fill(all(data), INF);
  }
  void update(int k, T a){ // update data[k]=a, k(0-indexed)
    k+=n-1;
    data[k]=a;
    while(k>0){
      k = (k-1)/2;
      data[k] = min(data[k*2+1], data[k*2+2]);
    }
  }
  inline T query(int a, int b){ return _query(a,b,0,0,n);} //min value in [a,b)
  inline T operator[](int idx){ return data[idx+n-1]; }
}; // END class SegTree


int main(){
  int n;
  cin>>n;
  vector<int> vec(n);
  rep(i,n) cin>>vec[i], vec[i]--;
  vector<int> pos(n);
  rep(i,n) pos[vec[i]] = i;
// dbg(vec);
  SegTree<int> even(n+1), odd(n+1);
  rep(i,n){
    if(i%2) odd.update(i, vec[i]);
    else even.update(i, vec[i]);
  }

  vector<int> ans;

  using P = pair<int,int>;
  priority_queue<pair<int,P>, vector<pair<int,P>>, greater<pair<int,P>>> pq;
  pq.push(mp(even.query(0,n),mp(0,n)));

  while(!pq.empty()){
    auto p = pq.top(); pq.pop();
    int l = p.se.fi, r = p.se.se;//dbg(l,r);
    int p1 = pos[p.fi];
    int p2;
    bool sw = false;
    if(p1%2==0){
      if((p1-l)%2==0) p2 = odd.query(p1, r);
      else sw=true,p2 = odd.query(l, p1);
      assert(p2!=INF);
      p2 = pos[p2];
      odd.update(p2, INF);
      even.update(p1, INF);
    }
    else {
      if((p1-l)%2==0) p2 = even.query(p1, r);
      else sw=true, p2 = even.query(l, p1);
      assert(p2!=INF);
      p2 = pos[p2];
      even.update(p2, INF);
      odd.update(p1, INF);
    }
    if(sw) swap(p1,p2);
    ans.pb(vec[p1]);ans.pb(vec[p2]);

    auto ins = [&](int a, int b){
      if(a==b) return;
      int x;
      if(a%2==0) x = even.query(a,b);
      else x = odd.query(a,b);
      pq.push(mp(x, mp(a,b)));
    };
//    dbg(p1,p2);
    ins(l,p1);
    ins(p1+1,p2);
    ins(p2+1,r);
  }

  rep(i,n) cout << ans[i]+1 << " \n"[i==n-1];

  return 0;
}

