pti t[2][4 * N];

void build(int v, int l, int r) {
  if (l + 1 == r) {
    forn(p, 2)
      t[p][v] = (l & 1) == p ? mp(::p[l], l) : mp(INF, -1);
  } else {
    int md = (l + r) >> 1;
    build(2 * v + 1, l, md);
    build(2 * v + 2, md, r);
    forn(p, 2)
      t[p][v] = min(t[p][2 * v + 1], t[p][2 * v + 2]);
  }
}

pti min(int p, int v, int l, int r, int lf, int rg) {
  if (lf >= rg) return pti(INF, -1);
  if (l == lf && r == rg) return t[p][v];
  int md = (l + r) >> 1;
  pti ans = min(p, 2 * v + 1, l, md, lf, min(md, rg));
  ans = min(ans, min(p, 2 * v + 2, md, r, max(lf, md), rg));
  return ans;
}

int tsz;
pti val[N];
vector<int> g[N];

int build(int lf, int rg) {
  if (lf >= rg) {
    assert(lf == rg);
    return -1;
  }
  assert((rg - lf) % 2 == 0);

  int x = min(lf & 1, 0, 0, n, lf, rg).y;
  assert(x != -1);
  int y = min((~lf) & 1, 0, 0, n, x, rg).y;
  assert(y != -1);
  assert(lf <= x && x < y && y < rg);

  int v = tsz++;
  val[v] = mp(p[x], p[y]);

  int nt[] = { build(lf, x), build(x + 1, y), build(y + 1, rg) };
  forn(i, 3) if (nt[i] != -1) g[v].pb(nt[i]);

  return v;
}

void solve() {
  forn(i, N) g[i].clear();
  tsz = 0;

  build(0, 0, n);
  int root = build(0, n);
  assert(root != -1);

  vector<int> ans;
  set<pair<pti, int>> z;
  z.insert(mp(val[root], root));
  while (!z.empty()) {
    int v = z.begin()->y;
    z.erase(z.begin());
    ans.pb(val[v].x);
    ans.pb(val[v].y);
    for (auto to : g[v]) z.insert(mp(val[to], to));
  }
  assert(sz(ans) == n);

  forn(i, sz(ans)) {
    if (i > 0) putchar(' ');
    printf("%d", ans[i]);
  }
  puts("");
}

