const int MOD = 1000000007;
double PI = 4*atan(1);

template<int SZ>
class SegMin {
	public:
		pii seg[2*SZ];

		SegMin() {
			memset(seg,0,sizeof seg);	
		}

		void upd(int p, pii value) {  // set value at position p
			for (seg[p += SZ] = value; p > 1; p >>= 1) seg[p>>1] = min(seg[p],seg[p^1]);
		}

		void build() {
			for (int i = SZ-1; i > 0; --i) seg[i] = min(seg[2*i],seg[2*i+1]);	
		}

		pii query(int l, int r) {  // minimum on interval [l, r)
			pii res = {MOD,MOD};
			for (l += SZ, r += SZ; l < r; l >>= 1, r >>= 1) {
				if (l&1) res = min(res,seg[l++]);
				if (r&1) res = min(res,seg[--r]);
			}
			return res;
		}
};

int N;
vi p;
SegMin<1<<17> e,o;
set<pair<pii,pii>> bes;

void init() {
	ios_base::sync_with_stdio(0);cin.tie(0);
	cin >> N; p.resize(N);
	F0R(i,N) cin >> p[i];
	for (int i = 0; i < N; i += 2) e.upd(i/2,{p[i],i}); // OK
	for (int i = 1; i < N; i += 2) o.upd(i/2,{p[i],i});
}

void ins(int x, int y) {
    if (x > y) return;
    if (x % 2 == 0) bes.insert({e.query(x/2,y/2+1),{x,y}});  // OK
    else bes.insert({o.query(x/2,y/2),{x,y}});
}

void solve() {
    pair<pii,pii> z = *bes.begin(); bes.erase(bes.begin());
    pii b1 = z.s, b2;
    b2.f = z.f.s; // index of min
    if (z.s.f % 2 == 0) b2.s = o.query(z.f.s/2,z.s.s/2+1).s; // check
    else b2.s = e.query(z.f.s/2+1,z.s.s/2+1).s;

    cout << p[b2.f] << " " << p[b2.s] << " ";
    ins(b1.f,b2.f-1);
    ins(b2.f+1,b2.s-1);
    ins(b2.s+1,b1.s);
}

int main() {
    init();
	ins(0,N-1);
	while (bes.size()) solve();
}

