void Segment_Tree_LR_Set(long long int l,long long int r,long long int id){
	odd[id].left=l;
	odd[id].right=r;
	if(id*2<MAX_TREE){Segment_Tree_LR_Set(l, (l+r)/2, id*2);Segment_Tree_LR_Set((l+r)/2, r, id*2+1);}
}

void Segment_Tree_Change_Loop(long long int id)
{
	if(id==0){return;}
	odd[id].value=min(odd[id*2].value,odd[id*2+1].value);

	Segment_Tree_Change_Loop(id/2);
}

void Segment_Tree_Change(long long int id,long long int num){
	odd[id+MAX_TREE/2-1].value=num;
	Segment_Tree_Change_Loop((id+MAX_TREE/2-1)/2);
}

long long int Segment_Tree_Check(long long int l,long long int r,long long int id){
		//cout<<id<<" "<<l<<" "<<r<<endl;
		if(odd[id].left>=r||odd[id].right<=l||r<=l){return INF;}
		else if(l==odd[id].left&&r==odd[id].right){return odd[id].value;}
		else {return min(Segment_Tree_Check(l,min(r,odd[2*id].right),2*id),Segment_Tree_Check(max(l,odd[2*id+1].left), r, 2*id+1));}

}



