using namespace std;
typedef pair<int,int> pii;

#define MAXN    200001

int bp[MAXN] = {MAXN,MAXN};
int p[MAXN];
int ap[MAXN] = {MAXN,MAXN};
struct node_t
{
    int l, r;
    int m[2];
};
node_t nodes[MAXN<<2];
int mymin(int a, int b)
{
    return (p[a]<p[b])?a:b;
}
node_t merge(node_t a, node_t b)
{
    node_t ans;
    ans.l = a.l; ans.r = b.r;
    ans.m[0] = mymin(a.m[0], b.m[0]);
    ans.m[1] = mymin(a.m[1], b.m[1]);
    return ans;
}

int N;

void build(int o, int l, int r)
{
    if(0 == r-l)
    {
        nodes[o].l = l; nodes[o].r = r;
        nodes[o].m[l&1] = l; nodes[o].m[1-(l&1)] = -1;
    } else {
        int mid = ((l+r)>>1);
        build(o<<1, l, mid);
        build(o<<1|1, mid+1, r);
        nodes[o] = merge(nodes[o<<1], nodes[o<<1|1]);
    }
}

node_t query(int L, int R, int o, int l, int r)
{
    if(L <= l && r <= R)
        return nodes[o];
    else
    {
        int mid = ((l+r)>>1);
        if(R <= mid) return query(L,R,o<<1,l,mid);
        else if(L > mid) return query(L,R,o<<1|1,mid+1,r);
        else return merge(query(L,R,o<<1,l,mid),query(L,R,o<<1|1,mid+1,r));
    }
}

void solve(int L, int R, int re, vector<pii> &ret)
{
    if(1 == R-L)
    {
        ret.push_back(make_pair(p[L], p[R]));
    } else if(L < R) {
        int i = 0, j = 0;
        node_t lm = query(L,R,1,1,N);
        int fi = lm.m[re];
        node_t rm = query(fi+1,R,1,1,N);
        int si = rm.m[!re];
        vector<pii> s[3];
        {solve(L, fi-1, re,s[0]), solve(fi+1,si-1,!re,s[1]), solve(si+1,R,re,s[2]);};
        ret.push_back(make_pair(p[fi],p[si]));
        vector<pii>::iterator it[3] = {s[0].begin(), s[1].begin(), s[2].begin()};
        int rem = s[0].size() + s[1].size() + s[2].size();
        while(rem)
        {
            int mp = -1;
            for(i = 0;i < 3;++i)
                if(it[i] != s[i].end() && (-1 == mp || *it[i] < *it[mp]))
                    mp = i;
            ret.push_back(make_pair(it[mp]->first, it[mp]->second));
            it[mp]++;
            rem--;
        }
    }
}

int main(void)
{
    int i = 0;
    vector<pii> ans;
    p[-1] = MAXN;
    scanf("%d", &N);
    for(i = 1;i <= N;++i)
        scanf("%d", p+i);
    build(1, 1, N);
    solve(1, N, 1, ans);
    printf("%d %d", ans[0].first, ans[0].second);
    for(i = 1;i < N/2;++i)
        printf(" %d %d", ans[i].first, ans[i].second);
    puts("");
    return 0;
}

