struct Segment {
  vector<int> node;
  int ide = 1e9;
  int n = 1;

  int bin_f(int a,int b){return min(a,b);}
  int update_f(int node,int x){
    return x;
  }

  Segment()
  {
    int sz = 202020;
    while (n < sz)
      n *= 2;
    node.assign(n * 2 - 1, ide);
    for (int i = n - 2; i >= 0; i--)
      node[i] = bin_f(node[i * 2 + 1], node[i * 2 + 2]);
  }

  void update(int i, int x) {
    i += n - 1;
    node[i] = update_f(node[i], x);
    while (i) {
      i = (i - 1) / 2;
      node[i] = bin_f(node[i * 2 + 1], node[i * 2 + 2]);
    }
  }

  int get_inter(int a, int b, int k = 0, int l = 0, int r = -1) {
    if (r < 0)
      r = n;
    if (a <= l && r <= b)
      return node[k];
    if (r <= a || b <= l)
      return ide;

    int lm = get_inter(a, b, k * 2 + 1, l, (l + r) / 2);
    int rm = get_inter(a, b, k * 2 + 2, (l + r) / 2, r);
    return bin_f(lm, rm);
  }
};
int n;
int p[303030];

int idx[303030];
vector<Segment> segs(2);

using P2 = pair<int,P>;

vector<P2> ans;

int main() {
  cin >> n;
  rep(i, 0, n - 1) {
     cin >> p[i]; 
     idx[p[i]] = i;
     segs[i % 2].update(i,p[i]);
  }

  stack<P2> st;
  st.push({0,{0,n}});
  while(!st.empty()){
    int l = st.top().second.first;
    int r = st.top().second.second;
    int deap = st.top().first;
    st.pop();
    if(l == r) continue;
    int even = segs[l % 2].get_inter(l,r);
    int odd = segs[(l + 1) % 2].get_inter(l,r);
    if(even == 1e9 || odd == 1e9) continue;
    int i = idx[even];
    int j = idx[odd];
    st.push({deap + 1,{l,i}});
    st.push({deap + 1,{i + 1,j}});
    st.push({deap + 1,{j + 1,r}});
    ans.push_back({deap,{p[i],p[j]}});
  }

  sort(ans.begin(),ans.end());

  for(auto p : ans){
    cout << p.second.first << " " << p.second.second << " " ;
  }

  cout << endl;
}

