pair<pii,int> merge(pair<pii,int> p1, pair<pii,int> p2){
	pair<pii,int> ans;
	ans.se = p1.se + p2.se;
	if(p1.se & 1){
		ans.fi.fi = min(p1.fi.fi, p2.fi.se);
		ans.fi.se = min(p1.fi.se, p2.fi.fi);
	}
	else{
		ans.fi.fi = min(p1.fi.fi, p2.fi.fi);
		ans.fi.se = min(p1.fi.se, p2.fi.se);
	}
	return ans;
}
void build(int nd,int s,int e){
	if(s == e){
		tr[nd] = {{a[s], 1e18}, 1};
		return;
	}
	int m = (s + e) >> 1;
	build(nd << 1, s, m);
	build(nd << 1 | 1, m + 1, e);
	tr[nd] = merge(tr[nd << 1], tr[nd << 1 | 1]);
}
void remove(int nd,int s,int e,int idx){
	if(s == e){
		tr[nd] = {{1e18, 1e18}, 0};
		return;
	}
	int m = (s + e) >> 1;
	if(idx <= m)
		remove(nd << 1, s, m, idx);
	else
		remove(nd << 1 | 1, m + 1, e, idx);
	tr[nd] = merge(tr[nd << 1], tr[nd << 1 | 1]);
}
pair<pii,int> query(int nd,int s,int e,int l,int r){
	if(s > r || e < l)
		return {{1e18, 1e18}, 0};
	if(l <= s && e <= r){
		return tr[nd];
	}
	int m = (s + e) >> 1;
	auto it1 = query(nd << 1, s, m, l, r);
	auto it2 = query(nd << 1 | 1, m + 1, e, l, r);
	return merge(it1, it2);
}
