using namespace std;

int N;
const int MAX_N = 100010;

int a[MAX_N];

struct node{
	int pos,val,flip;
	node(){flip=0;}
	node(int pos_,int val_,int flip_):pos(pos_),val(val_),flip(flip_){}
}tree[2][MAX_N*4];

struct RMQ{

#define LL (2*k+1)
#define RR (2*k+2)

	RMQ(int n){
		for(int i=0;i<4*MAX_N;i++)tree[0][i].val=tree[1][i].val=1e9;
		make(0,1,n,0);
		make(1,1,n,0);
	}

	void make(int mod,int s,int e,int k){
		if(s>e){
			return;
		}else if(s==e){
			tree[mod][k] = node(s,s%2==mod?a[s]:1e9,0);
		}else{
			int mid = (s+e)/2;
			make(mod,s,mid,LL);
			make(mod,mid+1,e,RR);
			up(mod,k);
		}
	}

	void up(int mod,int k){
		int f = tree[mod][k].flip;
		tree[mod][k].val = tree[f^mod][LL].val;
		tree[mod][k].pos = tree[f^mod][LL].pos;

		if(tree[mod][k].val > tree[f^mod][RR].val){
			tree[mod][k].val = tree[f^mod][RR].val;
			tree[mod][k].pos = tree[f^mod][RR].pos;
		}
	}

	void update(int mod,int x,int c,int s,int e,int k){
		if(s==e){
			tree[mod][k].val=c;
			return;
		}
		int mid = (s+e)/2;
		if(x<=mid){
			update(mod^tree[mod][k].flip,x,c,s,mid,LL);
		}else{
			update(mod^tree[mod][k].flip,x,c,mid+1,e,RR);
		}
		up(mod,k);
	}

	void invert(int L,int R,int s,int e,int k){
		if(e<L || R<s)return;
		if(L<=s&&e<=R){
			swap(tree[0][k],tree[1][k]);
			tree[0][k].flip = !tree[0][k].flip;
			tree[1][k].flip = !tree[1][k].flip;
		}else{
			int mid = (s+e)/2;
			invert(L,R,s,mid,LL);
			invert(L,R,mid+1,e,RR);
		}
		up(0,k);
		up(1,k);
	}

	node query(int mod,int L,int R,int s,int e,int k){
		if(e<L || R<s)return node(0,1e9,0);
		if(L<=s&&e<=R)return tree[mod][k];
		int mid = (s+e)/2;
		node z0 = query(mod^tree[mod][k].flip,L,R,s,mid,LL);
		node z1 = query(mod^tree[mod][k].flip,L,R,mid+1,e,RR);
		if(z0.val < z1.val)return z0;
		return z1;
	}


#undef LL
#undef RR
};

