struct segTree {
	vector<pii> dat;
	int n;
	segTree(){};
	segTree(int n_) {
		n = 1;
		while(n < n_) n *= 2;
		dat.resize(2*n);
		for(int i = 0; i < dat.size(); i++) {
			dat[i].fi = 1e9;
			dat[i].se = 1e9;
		}
	}
	void update(int k, int a) {
		k += n-1;
		dat[k].fi = a;
		dat[k].se = k-(n-1);
		while(k > 0) {
			k = (k-1) / 2;
			dat[k] = min(dat[k*2+1], dat[k*2+2]);
		}
	}
	pii query(int a, int b, int k=0, int l=0, int r=-1) {
		assert(a < b);
		if(r < 0) r = n;
		if (r <= a || b <= l) 
			return pii(1e9,-1);
		if(a <= l && r <= b)
			return dat[k];
		pii vl = query(a, b, k*2 + 1, l, (l+r) / 2);
		pii vr = query(a, b, k*2 + 2, (l+r) / 2, r);
		return min(vl, vr);
	}
};

pii l_indx(int a, int b) {
	int c = a % 2;
	assert((b-a) % 2 == 0);
	return pii(a/2, (b+!c)/2);
}

pii r_indx(int a, int b) {
	pii t = l_indx(a,b);
	if(a % 2) {
		t.fi++; t.se++;
	}
	return t;
}

