const int maxN = 2e5+10, base = 1e9+7;
typedef pair<int, int> ii;
int N, M, A[maxN], vt[maxN], odd[8*maxN], even[8*maxN];
ii G[maxN];
vector <int> E[maxN];

struct cmp
{
    bool operator() (int a, int b)
    {
        return G[a].first < G[b].first;
    }
};
set <int, cmp> seta;

void Update(int k, int l, int r, int i, int x)
{
    if (l > i || r < i) return;
    if (l == r)
    {
        if (i%2) odd[k] = x;
        else even[k] = x;
        return;
    }
    int mid = (l+r)/2;
    Update(k*2, l, mid, i, x);
    Update(k*2+1, mid+1, r, i, x);
    odd[k] = min(odd[k*2], odd[k*2+1]);
    even[k] = min(even[k*2], even[k*2+1]);
}

int getodd(int k, int l, int r, int u, int v)
{
    if (l > v || r < u) return base;
    if (l >= u && r <= v) return odd[k];
    int mid = (l+r)/2;
    int res1 = getodd(k*2, l, mid, u, v);
    int res2 = getodd(k*2+1, mid+1, r, u, v);
    return min(res1, res2);
}

int geteven(int k, int l, int r, int u, int v)
{
    if (l > v || r < u) return base;
    if (l >= u && r <= v) return even[k];
    int mid = (l+r)/2;
    int res1 = geteven(k*2, l, mid, u, v);
    int res2 = geteven(k*2+1, mid+1, r, u, v);
    return min(res1, res2);
}

void solve(int par, int l, int r)
{
    int x, y;
    if (l%2)
    {
        x = getodd(1,1,N,l,r);
        y = geteven(1,1,N,vt[x]+1,r);
    }
    else
    {
        x = geteven(1,1,N,l,r);
        y = getodd(1,1,N,vt[x]+1,r);
    }
    M++; G[M] = ii(x,y);
    E[par].push_back(M);
    int tmp = M;
    if (l < vt[x]) solve(par, l, vt[x]-1);
    if (vt[x]+1 < vt[y]) solve(tmp, vt[x]+1, vt[y]-1);
    if (vt[y] < r) solve(par, vt[y]+1, r);
}

void BFS(int x)
{
    for (int i=0; i < E[x].size(); i++) seta.insert(E[x][i]);
    while (!seta.empty())
    {
        int cur = *seta.begin();
        seta.erase(seta.begin());
        cout << G[cur].first << " " << G[cur].second << " ";
        for (int i=0; i < E[cur].size(); i++) seta.insert(E[cur][i]);
    }
}

int main()
{
    cin >> N;
    for (int i=1; i <= 4*N; i++) odd[i] = even[i] = base;
    for (int i=1; i <= N; i++)
    {
        cin >> A[i];
        vt[A[i]] = i;
        Update(1,1,N,i,A[i]);
    }
    solve(0, 1, N);
    BFS(0);
}

