};

st t[N * 4];

void build (int v = 1, int tl = 1, int tr = n)
{
    if (tl == tr)
    {
        if (tl & 1)
            t[v].o = ar[tl];
        else
            t[v].e = ar[tl];
    }
    else
    {
        int tm = (tl + tr) >> 1;
        build (v + v, tl, tm);
        build (v + v + 1, tm + 1, tr);
        t[v].o = min( t[v + v].o, t[v + v + 1].o );
        t[v].e = min( t[v + v].e, t[v + v + 1].e );
    }
}
int get (int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
    if (l > r || l > tr || tl > r)
        return inf;

    if (l <= tl && tr <= r)
        return (type & 1 ? t[v].o : t[v].e );

    int tm = (tl + tr) >> 1;
    return min( get( l, r, type, v + v, tl, tm ), get(l, r, type, v + v + 1, tm + 1, tr) );
}

map <int,map <int, int> > mp;

vector <int> vec[N];

vector <pair <int, int> > Vec;

pair <int, int> Pr[N];

pair <int, int> Compute (int l, int r)
{
    int type = (l & 1 ? 1 : 0);

    int res = get(l, r, type);

    int Sc = get( pos[ res ] + 1, r, type ^ 1 );

    if (!mp[res].count( Sc ) )
    {
        Pr[++cnt] = mk(res, Sc);
        mp[res][Sc] = cnt;
    }

    vector <pair <int, int> > V;

    if(l < pos[res] - 1)
        V.pb( Compute( l, pos[res] - 1 ) );
    if(pos[res] + 1 < pos[Sc] - 1)
        V.pb( Compute( pos[res] + 1, pos[Sc] - 1 ));
    if( pos[Sc] + 1 < r)
        V.pb( Compute( pos[Sc] + 1, r ) );

    sort( all(V) );

    for (int i = 0; i < sz(V); i++)
    {
        vec[ mp[V[i].fr][V[i].sc] ].pb( mp[res][Sc] );

        if (i > 0)
            vec[ mp[V[i].fr][V[i].sc] ].pb( mp[V[i-1].fr][V[i-1].sc] );
    }
    Vec.pb( mk(res, Sc) );
    return Vec.back();
}
