const int N = (int)2e5 + 7;
const int inf = (int)1e9 + 7;

struct tree{
  int t[N * 4], pos[N * 4];
  void build(int *a, int v, int tl, int tr){
    if(tl == tr){
      t[v] = a[tl];
      pos[v] = tl;
      return;
    }
    int tm = (tl + tr) >> 1;
    build(a, v * 2, tl, tm);
    build(a, v * 2 + 1, tm + 1, tr);
    t[v] = min(t[v * 2], t[v * 2 + 1]);
    pos[v] = (t[v * 2] < t[v * 2 + 1] ? pos[v * 2] : pos[v * 2 + 1]);
  }

  pii get(int v, int tl, int tr, int l, int r){
    if(l > r){
      return {inf, inf};
    }
    if(l == tl && r == tr){
      return make_pair(t[v], pos[v]);
    }
    int tm = (tl + tr) >> 1;
    pii a = get(v * 2, tl, tm, l, min(r, tm));
    pii b = get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
    return min(a, b);
  }
}t1, t2;

int n;
int p[N], p1[N], p2[N];

vector < pii > solve(int l, int r){
  int id, id2;
  if(l % 2){
    id = t1.get(1, 1, n, l, r).second;
    id2 = t2.get(1, 1, n, id, r).second;
  } else{
    id = t2.get(1, 1, n, l, r).second;
    id2 = t1.get(1, 1, n, id, r).second;
  }
  vector < pii > ans;
  vector < pii > e;
  vector < pii > ee;
  if(l < id){
    e = solve(l, id - 1);
    for(pii j : e){
      ee.push_back(j);
    }
  }
  if(id + 1 <= id2 - 1){
    e = solve(id + 1, id2 - 1);
    for(pii j : e){
      ee.push_back(j);
    }
  }
  if(id2 < r){
    e = solve(id2 + 1, r);
    for(pii j : e){
      ee.push_back(j);
    }
  }
  ans.push_back(make_pair(p[id], p[id2]));
  sort(ee.begin(), ee.end());
  for(auto i : ee){
    ans.push_back(i);
  }
  return ans;
}

int main(){
  scanf("%d", &n);
  for(int i = 1; i <= n; ++i){
    scanf("%d", p + i);
    if(i % 2){
      p1[i] = p[i];
      p2[i] = inf;
    } else{
      p2[i] = p[i];
      p1[i] = inf;
    }
  }
  t1.build(p1, 1, 1, n);
  t2.build(p2, 1, 1, n);
  vector < pii > hey = solve(1, n);
  for(pii i : hey){
    printf("%d %d ", i.first, i.second);
  }

  return 0;
}

