		ans.PB(p.F.F);
		ans.PB(tmp.F);
		// printf("(i, j) = (%d, %d)\n", i, j);
		if(l <= i-1)	pq.push(MP(query(l, i-1, 0), MP(l, i-1)));
		if(i+1 <= j-1)	pq.push(MP(query(i+1, j-1, 0), MP(i+1, j-1)));
		if(j+1 <= r)	pq.push(MP(query(j+1, r, 0), MP(j+1, r)));
	}

	for(int i=0; i<SZ(ans); i++)	printf("%d%c", ans[i], " \n"[i==SZ(ans)-1]);
}

