typedef pair<int, int> pii;
int n, B, a[NM], Otree[NM * 2], Etree[NM * 2], inv[NM], T;
deque<pii> dq[NM / 2];
struct TREE {
	int a, b;
	int l, m, r;
	TREE() { a = INF, b = INF; }
	TREE(int a, int b) :a(a), b(b) { l = 0; m = 0; r = 0; }
}ans[NM / 2];
void input() {
	si(n);
	FOR(i, 1, n) si(a[i]), inv[a[i]] = i;
	B = n - 1;
}
void Update(int tree[], int idx, int cnt) {
	idx += B; tree[idx] = cnt; idx >>= 1;
	while (idx) tree[idx] = min(tree[idx * 2], tree[idx * 2 + 1]), idx >>= 1;
}
int Get(int tree[], int l, int r) {
	l += B, r += B;
	int res = INF;
	while (l <= r) {
		if (l & 1) res = min(res, tree[l]), l++;
		if (!(r & 1)) res = min(res, tree[r]), r--;
		l >>= 1, r >>= 1;
	}
	return res;
}
bool pro(int L, int R) {
	if (L > R) return false;
	int p, pidx, q, qidx;
	if (L & 1) p = Get(Otree, L, R - 1);
	else p = Get(Etree, L, R - 1);
	if (p == INF) return false;
	if (L&1) Update(Otree, inv[p], INF);
	else Update(Etree, inv[p], INF);
	if (L & 1) q = Get(Etree, inv[p] + 1, R), Update(Etree, inv[q], INF);
	else q = Get(Otree, inv[p] + 1, R), Update(Otree, inv[q], INF);

	pidx = inv[p], qidx = inv[q];

	int cur = T;
	ans[cur] = TREE(p, q);
	ans[cur].l = ++T;
	if (!pro(L, pidx - 1)) ans[cur].l = 0, T--;
	ans[cur].m = ++T;
	if (!pro(pidx + 1, qidx - 1)) ans[cur].m = 0, T--;
	ans[cur].r = ++T;
	if (!pro(qidx + 1, R)) ans[cur].r = 0, T--;
	return true;
}
struct HEAP {
	int idx, a, b;
	HEAP() {}
	HEAP(int idx, int a, int b) :idx(idx), a(a), b(b) {}
	bool operator<(const HEAP& rhs) {
		return a > rhs.a;
	}
}H[NM];
