	make_heap(H + 1, H + 1 + N);
	H[++N] = HEAP(1, ans[1].a, ans[1].b);
	while (N) {
		HEAP X = H[1]; pop_heap(H + 1, H + 1 + N); N--;
		fprintf(out, "%d %d ", X.a, X.b);
		if (ans[X.idx].l != 0) H[++N] = HEAP(ans[X.idx].l, ans[ans[X.idx].l].a, ans[ans[X.idx].l].b), push_heap(H + 1, H + 1 + N);
		if (ans[X.idx].m != 0) H[++N] = HEAP(ans[X.idx].m, ans[ans[X.idx].m].a, ans[ans[X.idx].m].b), push_heap(H + 1, H + 1 + N);
		if (ans[X.idx].r != 0) H[++N] = HEAP(ans[X.idx].r, ans[ans[X.idx].r].a, ans[ans[X.idx].r].b), push_heap(H + 1, H + 1 + N);
	}
}
int main() {
	input();
	FOR(i, 1, B * 2 + 1) Etree[i] = Otree[i] = INF;
	FOR(i, 1, n) {
		if (i & 1) Otree[i + B] = a[i];
		else Etree[i + B] = a[i];
	}
	for (int i = B; i >= 1; i--) {
		Otree[i] = min(Otree[i * 2], Otree[i * 2 + 1]);
		Etree[i] = min(Etree[i * 2], Etree[i * 2 + 1]);
	}
	T = 1;
	pro(1, n);
	print();
	return 0;
}

