void build(int node,int l,int r)
{
    if(l==r)
    {
        if(l%2)
            segtr[node].F=A[l],segtr[node].S=INT_MAX;
        else
            segtr[node].F=INT_MAX,segtr[node].S=A[l];
        return;
    }
    build(2*node,l,(l+r)/2);
    build(2*node+1,(l+r)/2+1,r);
    segtr[node].F=min(segtr[2*node].F,segtr[2*node+1].F);
    segtr[node].S=min(segtr[2*node].S,segtr[2*node+1].S);
}
pii query(int node,int l,int r,int ql,int qr)
{
    if(r<ql||l>qr)
        return {INT_MAX,INT_MAX};
    if(l>=ql&&r<=qr)
        return segtr[node];
    pii lchild=query(2*node,l,(l+r)/2,ql,qr);
    pii rchild=query(2*node+1,(l+r)/2+1,r,ql,qr);
    return {min(lchild.F,rchild.F),min(lchild.S,rchild.S)};
}
pii getPriority(int l,int r)
{
    pii ret=query(1,1,n,l,r);
    int odd,even;
    if(l%2)
    {
        odd=pos[ret.F];
        ret=query(1,1,n,odd+1,r);
        even=pos[ret.S];
    }
    else
    {
        odd=pos[ret.S];
        ret=query(1,1,n,odd+1,r);
        even=pos[ret.F];
    }
    return {odd,even};
}
