#include "bits/stdc++.h"
using namespace std;
const int N = 2e5 + 5;
const int SN = 1 << 19;
int n;
int arr[N];
int ans[N];
int siz;
pair < int , int > segtree[SN][2];
void build(int l , int r , int node){
	if(l == r){
		if(l & 1){
			segtree[node][0] = make_pair(N , N);
			segtree[node][1] = make_pair(arr[l] , r);
		}
		else{
			segtree[node][0] = make_pair(arr[l] , r);
			segtree[node][1] = make_pair(N , N);
		}
	}
	else{
		int mid = l + r >> 1;
		build(l , mid , node + node);
		build(mid + 1 , r , node + node + 1);
		segtree[node][0] = min(segtree[node + node][0] , segtree[node + node + 1][0]);
		segtree[node][1] = min(segtree[node + node][1] , segtree[node + node + 1][1]);
	}
}
pair < pair < int , int > , pair < int , int > > query(int l , int r , int node , int ql , int qr){
	if(l > qr || r < ql || ql > qr){
		return make_pair(make_pair(N , N) , make_pair(N , N));
	}
	if(l >= ql && r <= qr){
		return make_pair(segtree[node][0] , segtree[node][1]);
	}
	int mid = l + r >> 1;
	auto lft = query(l , mid , node + node , ql , qr);
	auto rgt = query(mid + 1 , r , node + node + 1 , ql , qr);
	lft.first = min(lft.first , rgt.first);
	lft.second = min(lft.second , rgt.second);
	return lft;
}
pair < int , int > get(int l , int r){
	auto it = query(1 , n , 1 , l , r);
	if(l & 1){
		return make_pair(it.second.second , query(1 , n , 1 , it.second.second + 1 , r).first.second);
	}
	else{
		return make_pair(it.first.second , query(1 , n , 1 , it.first.second + 1 , r).second.second);
	}
}
priority_queue < pair < int , pair < int , int > > > pq;
void solve(){
	while(!pq.empty()){
		pq.pop();
	}
	pq.push({-arr[get(1 , n).first] , {1 , n}});
	while(!pq.empty()){
		auto lol = pq.top();
		pq.pop();
		int l = lol.second.first;
		int r = lol.second.second;
		auto it = get(l , r);
		ans[++siz] = arr[it.first];
		ans[++siz] = arr[it.second];
		int mid1 = it.first;
		int mid2 = it.second;
		if(l < mid1){
			pq.push({-arr[get(l , mid1 - 1).first] , {l , mid1 - 1}});
		}
		if(mid1 + 1 < mid2){
			pq.push({-arr[get(mid1 + 1 , mid2 - 1).first] , {mid1 + 1 , mid2 - 1}});
		}
		if(mid2 + 1 <= r){
			pq.push({-arr[get(mid2 + 1 , r).first] , {mid2 + 1 , r}});
		}
	}
}
int main(){
	scanf("%d" , &n);
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d" , arr + i);
	}
	build(1 , n , 1);
	siz = 0;
	solve();
	for(int i = 1 ; i <= n ; ++i){
		printf("%d%c" , ans[i] , " \n"[i == n]);
	}
}

