void build (int v = 1, int l = 1, int r = n - 1) {
    if (l == r) {
        tree[v] = {sum[l], l};
        tre[v] = l;
    } else {
        int mid = (l + r) >> 1;
        build(v + v, l, mid);
        build(v + v + 1, mid + 1, r);
        tree[v] = max(tree[v + v], tree[v + v + 1]);
        tre[v] = max(tre[v + v], tre[v + v + 1]);
    }
}

void update (int v, int l, int r, int pos, int val) {
    if (l == r) {
        tree[v] = {val, l};
        return;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) {
        update(v + v, l, mid, pos, val);
    } else {
        update(v + v + 1, mid + 1, r, pos, val);
    }
    tree[v] = max(tree[v + v], tree[v + v + 1]);
}

void up (int v, int l, int r, int pos, int val) {
    if (l == r) {
        tre[v] = val;
        return ;
    }
    int mid = (l + r) >> 1;
    if (pos <= mid) {
        up(v + v, l, mid, pos, val);
    } else {
        up(v + v + 1, mid + 1, r, pos, val);
    }
    tre[v] = max(tre[v + v], tre[v + v + 1]);
}

int get (int v, int l, int r, int tl, int tr) {
    if (l <= tl && tr <= r) {
        return tre[v];
    } else if (tl > r || tr < l) return -inf;
    int mid = (tl + tr) >> 1;
    return max (get(v + v, l, r, tl, mid), get(v + v + 1, l, r, mid + 1, tr));
}

int find (int a) {
    if (pr[a] == a) return a;
    return pr[a] = find(pr[a]);
}

void connect (int a, int b) {
    a = find(a);
    b = find(b);
    if (a != b)
        if (a < b)
            pr[a] = pr[b];
        else
            pr[b] = pr[a];
}



