Segment_Tree_Range_Minimum_Query<pair<int,int>> SegL(MAX_N,{MAX_N,MAX_N}),SegR(MAX_N,{MAX_N,MAX_N});

pair<int,int> rec(int l, int r) {

    auto e1 = (l%2?SegR:SegL).getvar(l,r+1);
    int s = e1.second;
    auto e2 = (l%2?SegL:SegR).getvar(s,r+1);
    int t = e2.second;
    match[s] = t;

    if(0<=l&&l<=s-1&&s-1<=r&&r<N){
        pair<int,int> vl = rec(l,s-1);
        edge[s].push_back(vl.first);
    }
    if(0<=l&&l<=s+1&&s+1<t-1&&t-1<=r&&r<N) {
        pair<int,int> vc = rec(s+1,t-1);
        edge[s].push_back(vc.first);
    }
    if(0<=l&&l<=t+1&&t+1<r&&r<N){
        pair<int,int> vr = rec(t+1,r);
        edge[s].push_back(vr.first);
    }
    pair<int,int> ret = {s,t};
    return ret;
}

int main() {
