    pq.push({A[p.first],p.first});
    vector<int> ans;
    while(pq.size()) {
        auto from = pq.top().second;
        pq.pop();
        ans.push_back(A[from]);
        ans.push_back(A[match[from]]);
        for (auto to:edge[from]) pq.push({A[to],to});
    }
    for(auto e:ans) cout << e << " ";
    cout << endl;


	return 0;
}

