	ios::sync_with_stdio(false);

	cin >> N;

	even.init(N);
	odd.init(N);

	for(int i = 0; i < N; i++) {
		cin >> a[i];
		if(i % 2 == 0) {
			even.update(i, a[i]);
			odd.update(i, INF);
		}
		else {
			even.update(i, INF);
			odd.update(i, a[i]);
		}
	}
	//even.show();
	//odd.show();

	s.insert(N);

	deque<int> ans;
	priority_queue<Pi, vector<Pi>, greater<Pi>> q;
	auto res = f(0, N);
	q.push(res);
	while(q.size()) {
		auto pi = q.top();
		q.pop();
		ans.push_back(pi.first.first);
		ans.push_back(pi.first.second);
		int id = pi.second;
		for(auto c : children[id]) {
			q.push({ ps[c], c });
		}
	}

	for(int i = 0; i < N; i++) {
		cout << ans[i] << " ";
	}
	cout << endl;
}

