//     dfs(l, a);
//     dfs(a + 1, b);
//     dfs(b + 1, r);
// }

PP f(int l, int r, vector<int> &pa) {
    P x, y;
    if(l % 2 == 0) {
        x = even.get(l, r);
        y = odd.get(l, r);
    } else {
        x = odd.get(l, r);
        y = even.get(l, r);
    }
    pa[x.fr] = y.fr;
    return make_pair(x.fr, make_pair(l, r));
}

void solve() {
	cin >> n;
    p.resize(n);
    pa.resize(n); 
    rep(i, n) {
        cin >> p[i];
    }
    even.init(n, make_pair(inf, inf));
    odd.init(n, make_pair(inf, inf));
    rep(i, n) {
        if(i % 2 == 0) {
            even.update(i, make_pair(p[i], i));
        } else {
            odd.update(i, make_pair(p[i], i));
        }
    }
    vector<int> ans;

    P x, y;
    x = even.get(0, n);
    y = odd.get(0, n);
    pque.push(make_pair(x.fr, make_pair(0, n)));
    pa[x.fr] = y.fr;

    while(!pque.empty()) {
        PP q = pque.top(); pque.pop();
        int a = q.fr;
        ans.push_back(a);
        ans.push_back(pa[a]);

        int l = q.sc.fr, r = q.sc.sc;
        if(l % 2 == 0) {
            x = even.get(l, r);
            y = odd.get(l, r);
        } else {
            x = odd.get(l, r);
            y = even.get(l, r);
        }

        int u = x.sc, v = y.sc;
        if(l + 1 < u) pque.push(f(l, u, pa));
        if(u + 1 < v) pque.push(f(u + 1, v, pa));
        if(v + 1 < r) pque.push(f(v + 1, r, pa));
    }

    for(auto& z: ans) {
        cout << z << " ";
    }
    cout << endl;
}

