int findmin (std::vector<int>&p , std::vector<int>&f) {
  int id = 0;
  int id_s = 0;
  for (int i = 0; i < p.size();i++) {
    if (!f[id]) id = i;
    if (!f[i]) {
      id_s = id + 1;
      continue;
    }
    if ((i -id_s)%2==1) continue;
    if (p[i] <= p[id]) id = i;
  }
  return id;
}

int findnext (int id_prev, std::vector<int>&p , std::vector<int>&f) {
  int id = id_prev+1;
  int min = 3e5;
  for (int i = id_prev+1; i < p.size();i++) {
    if ((i -id_prev)%2 == 0) continue;
    if (!f[i]) return id;
    if (p[i] <= min) id = i;
    min = p[i];
  }
  return id;
}

