vector<int> solve(Seg &tmpA,Seg &tmpB){
  priority_queue<dat> Q;
  Q.push(dat(0,n-1,0,0,0));
  vector<int> res;

  while(!Q.empty()){
    dat t = Q.top(); Q.pop();
    int l = t.l, r = t.r, flag = t.flag;
    Seg &A = flag==0? tmpA:tmpB;
    Seg &B = flag==0? tmpB:tmpA;
    int nl, lval; tie(nl,lval) = A.find(l, r+1);
    int nr, rval; tie(nr,rval) = B.find(nl, r+1);


    res.push_back(lval);
    res.push_back(rval);
    auto push=[&tmpA,&tmpB,&Q](int l,int r,int flag){
      if(l > r) return;
      Seg &A = flag==0? tmpA:tmpB;
      Seg &B = flag==0? tmpB:tmpA;
      int idxa,a; tie(idxa,a) = A.find(l, r+1);
      int idxb,b; tie(idxb,b) = B.find(idxa, r+1);
      Q.push(dat(l, r, a, b, flag));
    };

    push(nl + 1,nr - 1,!flag);
    push(l,nl-1,flag);
    push(nr + 1,r,flag);
  }
  return res;
}

