void divisor(ll n, vector<ll>& ret) {
	for (ll i = 1; i * i <= n; i++) {
		if (n % i == 0) {
			ret.push_back(i);
			if (i * i != n) ret.push_back(n / i);
		}
	}
	sort(ret.begin(), ret.end());

}

vector<ll> lis_fast(const vector<ll>& a) {//最長部分増加列
	const ll n = a.size();
	vector<ll> A(n, INT_MAX);
	vector<ll> id(n);
	for (int i = 0; i < n; ++i) {
		id[i] = distance(A.begin(), lower_bound(A.begin(), A.end(), a[i]));
		A[id[i]] = a[i];
	}
	ll m = *max_element(id.begin(), id.end());
	vector<ll> b(m + 1);
	for (int i = n - 1; i >= 0; --i)
		if (id[i] == m) b[m--] = a[i];
	return b;
}


ll ModPow(ll x, ll n) {
	ll res = 1LL;
	while (n > 0) {
		if (n & 1) res = res * x % MOD;
		x = x * x % MOD;
		n >>= 1;
	}
	return res;
}
//nCrとか
class Combination {
public:
	Array fact;
	Array inv;
	ll mod;
	ll mod_inv(ll x) {
		ll n = mod - 2LL;
		ll res = 1LL;
		while (n > 0) {
			if (n & 1) res = res * x % mod;
			x = x * x % mod;
			n >>= 1;
		}
		return res;
	}
	ll nCr(ll n, ll r) {
		return ((fact[n] * inv[r] % mod) * inv[n - r]) % mod;
	}
	ll nPr(ll n, ll r) {
		return (fact[n] * inv[n - r]) % mod;
	}
	ll nHr(ll n, ll r) {
		return nCr(r + n - 1, r);
	}
	Combination(ll n, ll _mod) {
		mod = _mod;
		fact.resize(n + 1);
		fact[0] = 1;
		REP(i, n) {
			fact[i + 1] = (fact[i] * (i + 1LL)) % mod;
		}
		inv.resize(n + 1);
		REP(i, n + 1) {
			inv[i] = mod_inv(fact[i]);
		}
	}
};

ll gcd(ll m, ll n) {
	if (n == 0)return m;
	return gcd(n, m % n);
}//gcd

ll lcm(ll m, ll n) {
	return m / gcd(m, n) * n;
}


Matrix mIdentity(ll n) {
	Matrix A(n, Array(n));
	for (int i = 0; i < n; ++i) A[i][i] = 1;
	return A;
}

Matrix mMul(const Matrix& A, const Matrix& B) {
	Matrix C(A.size(), Array(B[0].size()));
	for (int i = 0; i < C.size(); ++i)
		for (int j = 0; j < C[i].size(); ++j)
			for (int k = 0; k < A[i].size(); ++k)
				(C[i][j] += (A[i][k] % MOD) * (B[k][j] % MOD)) %= MOD;
	return C;
}
// O( n^3 log e )
Matrix mPow(const Matrix & A, ll e) {
	return e == 0 ? mIdentity(A.size()) :
		e % 2 == 0 ? mPow(mMul(A, A), e / 2) : mMul(A, mPow(A, e - 1));
}

template <class T>class RectangleSum {
public:
	vector<vector<T>> sum;
	T GetSum(int left, int right, int top, int bottom) { //[left, right], [top, bottom]
		T res = sum[bottom][right];
		if (left > 0) res -= sum[bottom][left - 1];
		if (top > 0) res -= sum[top - 1][right];
		if (left > 0 && top > 0) res += sum[top - 1][left - 1];
		return res;
	}
	RectangleSum(const vector<vector<T>> &s, int h, int w) {
		sum.resize(h);
		for (int i = 0; i < h; i++) sum[i].resize(w, 0);
		for (int y = 0; y < h; y++) {
			for (int x = 0; x < w; x++) {
				sum[y][x] = s[y][x];
				if (y > 0) sum[y][x] += sum[y - 1][x];
				if (x > 0) sum[y][x] += sum[y][x - 1];
				if (y > 0 && x > 0) sum[y][x] -= sum[y - 1][x - 1];
			}
		}
	}
};



void solve(ll l, ll r,Array &p,Array &ret,RmqTree &odd,RmqTree& even) {
	Matrix temp(3);
	ll lnum;
	ll rnum;
	if (l % 2 == 0) {
		P lp = even.find(l, r);
		lnum = lp.second;
		P rp = odd.find(lnum + 1, r);
		rnum = rp.second;
	}
	else {
		P lp = odd.find(l, r);
		lnum = lp.second;
		P rp = even.find(lnum + 1, r);
		rnum = rp.second;
	}
	ret.push_back(p[lnum]);
	ret.push_back(p[rnum]);
	if (lnum > l) {
		solve(l, lnum, p, temp[0],odd,even);
	}
	if (rnum > lnum + 1) {
		solve(lnum + 1, rnum, p, temp[1],odd,even);
	}
	if (r - 1 > rnum) {
		solve(rnum + 1, r, p, temp[2],odd,even);
	}
	Array now(temp.size(), 0);
	priority_queue<P,vector<P>,greater<P>> que;
	REP(i, now.size()) {
		if (now[i] == temp[i].size())continue;
		que.push(make_pair(temp[i][now[i]], i));
	}
	while(que.size()) {	
		P pu = que.top();
		que.pop();
		ret.push_back(temp[pu.second][now[pu.second]]);
		ret.push_back(temp[pu.second][now[pu.second]+1]);
		now[pu.second] +=2;
		if (now[pu.second] != temp[pu.second].size())que.push(make_pair(temp[pu.second][now[pu.second]], pu.second));
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);


	ll n;
	cin >> n;
	Array p(n);
	RmqTree odd(n + 1), even(n + 1);
	REP(i, n) {
		cin >> p[i];
		if (i % 2 == 0)even.update(i, p[i]);
		else odd.update(i, p[i]);
	}
	Array ans;
	solve(0, n, p, ans,odd,even);
	REP(i, ans.size())cout << ans[i] << ' ';
	cout << endl;

	return 0;
}

