class segT{
	private:
		node d[MAXN<<2];
		void upd(int u){
			node &son= d[d[u].ls].min<d[d[u].rs].min ? d[d[u].ls]:d[d[u].rs];
			d[u].min=son.min;
			d[u].pos=son.pos;
		}
		void build(int u,int l,int r,int a[]){
			static int cnt=1;
			d[u].lp=l,d[u].rp=r;
			if(l==r){
				d[u].min=a[l];
				d[u].pos=l;
				return;
			}
			int mid=(l+r)>>1;
			d[u].ls=++cnt;
			build(cnt,l,mid,a);
			d[u].rs=++cnt;
			build(cnt,mid+1,r,a);
			upd(u);
		}
		void del(int u,int pos){
			if(d[u].lp==d[u].rp){
				d[u].min=INT_MAX;
				return;
			}
			int mid=(d[u].lp+d[u].rp)>>1;
			if(pos<=mid) del(d[u].ls,pos);
			else del(d[u].rs,pos);
			upd(u);
		}
		pair<int,int> qry(int u,int l){
			if(l<=d[u].lp) return pair<int,int>(d[u].min,d[u].pos);
			int mid=(d[u].lp+d[u].rp)>>1;
			pair<int,int> ret,rs;
			ret.first=INT_MAX;
			if(l<=mid) ret=qry(d[u].ls,l);
			rs=qry(d[u].rs,l);
			if(rs.first<ret.first) ret=rs;
			return ret;
		}
	public:
		void build(int n,int a[]){build(1,1,n,a);}
		pair<int,int> qry(int l){
			pair<int,int> ret=qry(1,l);
			del(1,ret.second);
			return ret;
		}
