int N;

vector<pair<int, int>> merge(vector<pair<int, int>> a, vector<pair<int, int>> b) {
	vector<pair<int, int>> ret;
	ret.reserve(a.size() + b.size());

	int ia = 0, ib = 0;
	for (int i = 0; i < a.size() + b.size(); i++) {
		if (ia >= a.size()) ret.push_back(b[ib++]);
		else if (ib >= b.size()) ret.push_back(a[ia++]);
		else if (a[ia] < b[ib]) ret.push_back(a[ia++]);
		else ret.push_back(b[ib++]);
	}
	return ret;
}

vector<pair<int, int>> func(int* v, int len) {
	vector<pair<int, int>> ret;

	if (len == 0) return ret;
	if (len == 2) {
		ret.push_back(make_pair(v[0], v[1]));
		return ret;
	}

	int min = N + 1;
	int min_i = 0;

	for (int i = 0; i < len; i += 2) {
		if (v[i] < min) {
			min_i = i;
			min = v[i];
		}
	}

	min = N + 1;
	int min_j = min_i + 1;
	for (int j = min_i + 1; j < len; j += 2) {
		if (v[j] < min) {
			min_j = j;
			min = v[j];
		}
	}

	//cout << min_i << " " << min_j << endl;

	ret.push_back(make_pair(v[min_i], v[min_j]));
	vector<pair<int, int>> v1 = func(&(v[0]), min_i);
	vector<pair<int, int>> v2 = func(&(v[min_i + 1]), min_j - min_i - 1);
	vector<pair<int, int>> v3 = func(&(v[min_j + 1]), len - min_j - 1);

	vector<pair<int, int>> tail = merge(v1, merge(v2, v3));

	ret.insert(ret.end(), tail.begin(), tail.end());

	return ret;
}

