int get(int l, int r, int w) {
  int k = lg[r - l + 1];
  return a[w][f[w][k][l]] < a[w][f[w][k][r - (1 << k) + 1]] ? f[w][k][l] : f[w][k][r - (1 << k) + 1];
}

const int inf = 1e9;

int n;
int ans[N];
int tmp[N];

void solve(int l, int r, int w) {
  if (r - l <= 0) {
    return;
  }
  int p = get(l, r, w);
  int q = get(p + 1, r, 1 - w);
  solve(l, p - 1, w);
  solve(p + 1, q - 1, 1 - w);
  solve(q + 1, r, w);
  int xi = l;
  int yi = p + 1;
  int zi = q + 1;
  int cnt = 2;
  tmp[0] = a[w][p];
  tmp[1] = a[1 - w][q];
  while (true) {
    int vx = (xi > p - 1 ? inf : ans[xi]);
    int vy = (yi > q - 1 ? inf : ans[yi]);
    int vz = (zi > r ? inf : ans[zi]);
    if (vx == inf && vy == inf && vz == inf) {
      break;
    }
    if (vx < vy && vx < vz) {
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
    } else
    if (vy < vx && vy < vz) {
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
    } else {
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
    }
  }
  for (int i = 0; i < cnt; ++i) {
    ans[l + i] = tmp[i];
  }
}

