  for (int i = 1; i < N; ++i) {
    lg[i] = lg[i / 2] + 1;
  }
  for (int w = 0; w < 2; ++w) {
    for (int j = 0, d = 1; d <= n; ++j, d *= 2) {
      for (int i = 0; i + d <= n; ++i) {
        if (j == 0) {
