//[l,r)での辞書順最小
vector<pii> dfs(int l, int r){
    vector<pii> res, all;
    if(l == r) return res;
    //辞書順最小のもの
    int L, R;
    pii a, b;
    if(l%2 == 0){
        a = seg2.query(l/2, r/2);
        L = a.second;
        b = seg1.query(L/2, r/2);
        R = b.second;
    }
    else{
        a = seg1.query(l/2, r/2);
        L = a.second;
        b = seg2.query((L+1)/2, (r+1)/2);
        R = b.second;
    }
    //cout << l << ' ' << r << ' ' << L << ' ' << R << endl;
    res.pb(pii(p[L], p[R]));
    for(auto &e: dfs(l, L)) all.pb(e);
    for(auto &e: dfs(L+1, R)) all.pb(e);
    for(auto &e: dfs(R+1, r)) all.pb(e);
    sort(all(all));
    for(auto &e: all) res.pb(e);
    return res;
}

