pp_p rmq(pii lr){
	auto f=[](int o,int l,int r){
		pii t=seg[o][l+=B],u=seg[o][r+=B-1];
		for(;l/2<r/2;l/=2,r/=2){
			t=l%2?t:min(t,seg[o][l+1]);
			u=r%2?min(seg[o][r-1],u):u;
		}
		return min(t,u);
	};
