const int INF = 1 << 30;

template <class Type>
class Segtree {
public:
    explicit Segtree(int N) : length(1) {
        while (length < N) length *= 2;
        nodes.assign(length * 2, INF);
    }

    Type query(int ql, int qr, int nidx, int nl, int nr) {
        if (nr <= ql || qr <= nl) return INF;
        if (ql <= nl && nr <= qr) return nodes[nidx];
        Type lvalue = query(ql, qr, nidx * 2, nl, (nl + nr) / 2);
        Type rvalue = query(ql, qr, nidx * 2 + 1, (nl + nr) / 2, nr);
        return min(lvalue, rvalue);
    }

    // half-open interval [ql, qr)
    Type query(int ql, int qr) {
        return query(ql, qr, 1, 0, length);
    }

    void update(int idx, Type value) {
        int nidx = idx + length;
        nodes[nidx] = value;
        while (nidx > 0) {
            nidx /= 2;
            nodes[nidx] = min(nodes[nidx * 2], nodes[nidx * 2 + 1]);
        }
    }

    int length;
    vector<Type> nodes;
};

vector<Segtree<int>> seg(2, Segtree<int>(200000));
int p[200000], rev[200000];

queue<pair<int, int>> rec(int l, int r) {
    if (l == r) return queue<pair<int, int>>();
    if (r - l == 2) {
        queue<pair<int, int>> ret;
        ret.push(make_pair(p[l], p[l + 1]));
        return ret;
    }

    int lmin = seg[l % 2].query(l, r);
    int d1 = rev[lmin];
    int rmin = seg[(l + 1) % 2].query(d1 + 1, r);
    int d2 = rev[rmin];

    queue<pair<int, int>> ret;
    ret.push(make_pair(lmin, rmin));
    vector<queue<pair<int, int>>> sub = {rec(l, d1), rec(d1 + 1, d2), rec(d2 + 1, r)};

    priority_queue<pair<pair<int, int>, int>, vector<pair<pair<int, int>, int>>, greater<pair<pair<int, int>, int>>> que;
    for (int i = 0; i < 3; ++i) {
        if (!sub[i].empty()) {
            que.push(make_pair(sub[i].front(), i));
            sub[i].pop();
        }
    }

    while (!que.empty()) {
        pair<int, int> p;
        int i;
        tie(p, i) = que.top();
        que.pop();
        ret.push(p);
        if (!sub[i].empty()) {
            que.push(make_pair(sub[i].front(), i));
            sub[i].pop();
        }
    }

    return ret;
}

