int query(int n, int l, int r, int ql, int qr, int q){
  if(ql <= l && r <= qr){
    return t[q][n];
  }
  int rs = INF;

  int piv = (l+r)>>1;

  if(ql<=piv){
    rs = min(rs, query(2*n, l, piv, ql, qr, q));
  }

  if(qr>piv){
    rs = min(rs, query(2*n+1, piv+1, r, ql, qr, q));
  }

  return rs;
}

