using namespace std;

const int INF = 1 << 30;

class SegTree {
  int vertexc;
  int segstart;

  vector<pair<int, int>> tree;
  vector<int> lend;
  vector<int> rend;

  void update (int u) {
    if (u == 0) return;
    tree[u] = min(tree[2 * u], tree[2 * u + 1]);
    update(u / 2);
  }

public:
  SegTree (int _length = 0) {
    segstart = 1;
    while (segstart < _length) {
      segstart *= 2;
    }
    vertexc = segstart * 2;

    tree = vector<pair<int, int>> (vertexc, make_pair(INF, INF));
    lend = vector<int> (vertexc);
    rend = vector<int> (vertexc);
    for (int i = segstart; i < vertexc; i++) {
      lend[i] = i - segstart;
      rend[i] = i - segstart;
    }

    for (int i = segstart - 1; i >= 1; i--) {
      lend[i] = lend[2 * i];
      rend[i] = rend[2 * i + 1];
    }
  }

  pair<int, int> query (int ql, int qr, int u = 1) {
    ql = max(ql, lend[u]);
    qr = min(qr, rend[u]);

    if (ql > qr) return {INF, INF};
    if (ql == lend[u] && qr == rend[u]) return tree[u];
    return min(query(ql, qr, 2 * u), query(ql, qr, 2 * u + 1));
  }

  void set (int idx, pair<int, int> val) {
    tree[idx + segstart] = val;
    update((idx + segstart) / 2);
  }
};

const int MAX_N = 2e5 + 5;

int arr [MAX_N];
SegTree both;
SegTree even;
SegTree odd;

vector<int> adj [MAX_N];
pair<int, int> val [MAX_N];

int vc;
int solve (int l, int r) {
  int idx = vc;
  vc++;

  pair<int, int> lsp;
  if (l % 2 == 0) {
    lsp = even.query(l, r - 1); // <val, idx>
  } else {
    lsp = odd.query(l, r - 1);
  }
  pair<int, int> rsp;
  if (lsp.second % 2 == 0) {
    rsp = odd.query(lsp.second + 1, r);
  } else {
    rsp = even.query(lsp.second + 1, r);
  }

  val[idx] = make_pair(lsp.first, rsp.first);

  int m1 = lsp.second;
  int m2 = rsp.second;

  if (l <= m1 - 1) {
    adj[idx].push_back(solve(l, m1 - 1));
  }

  if (m1 + 1 <= m2 - 1) {
    adj[idx].push_back(solve(m1 + 1, m2 - 1));
  }

  if (m2 + 1 <= r) {
    adj[idx].push_back(solve(m2 + 1, r));
  }

  return idx;
}

priority_queue<pair<pair<int, int>, int>,
               vector<pair<pair<int, int>, int>>,
