void expand () {
  pair<int, int> wal = PQ.top().first;
  int idx = PQ.top().second;

  cout << wal.first << " " << wal.second << " ";
  PQ.pop();

  for (int nxt : adj[idx]) {
    PQ.push(make_pair(val[nxt], nxt));
  }
}

int main () {
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  both = SegTree (n + 5);
  even = SegTree (n + 5);
  odd = SegTree (n + 5);

  for (int i = 1; i <= n; i++) {
    cin >> arr[i];

    both.set(i, make_pair(arr[i], i));
    if (i % 2 == 0) {
      even.set(i, make_pair(arr[i], i));      
    } else {
      odd.set(i, make_pair(arr[i], i));
    }
  }

  int root = solve(1, n);
  PQ.push(make_pair(val[root], root));

  while (!PQ.empty()) {
    expand();
  }
  cout << endl;
}

