int main(){
  int N;
  cin >> N;
  vector<int> P(N);
  vector<pair<int,int>> Odd, Even;
  const int INF = 1e9;
  for(int i = 0; i < N; ++i){
    int p;
    cin >> p;
    P[i] = p;
    if(i%2) Odd.emplace_back(p,i), Even.emplace_back(INF,i);
    else Even.emplace_back(p,i), Odd.emplace_back(INF,i);
  }

  using T = pair<int,int>;
  function<T(T,T)> f = [](T a, T b) -> T {
                         return min(a,b);
                       };

  T ti(INF,-1);
  SegmentTree<T> odd(f,ti), even(f,ti);
  odd.build(Odd);
  even.build(Even);
  using tup = tuple<int,int,int,int>;

  auto find_lr = [&](int l, int r) -> pair<int,int> {
               assert(l%2 == r%2);
               if(r-l < 2) return {};
               auto li = (l%2 ? odd.query(l,r) : even.query(l,r));
               auto ri = (l%2 ? even.query(li.second,r) : odd.query(li.second,r));
               return make_pair(li.second,ri.second);
              };

  vector<int> Q;
  priority_queue<tup,vector<tup>,greater<>> pq;
  {
    // auto [l,r] = find_lr(0,N);
    int l, r;
    tie(l,r) = find_lr(0,N);
    Q.push_back(P[l]);
    Q.push_back(P[r]);
    vector<pair<int,int>> v = {{0,l},{l+1,r},{r+1,N}};
    for(auto e : v){
      if(e.second-e.first < 2) continue;
      // auto [ll,rr] = find_lr(e.first,e.second);
      int ll, rr;
      tie(ll,rr) = find_lr(e.first,e.second);
      pq.emplace(P[ll],P[rr],e.first,e.second);
    }
  }
  for(int i = 1; i < N/2; ++i){
    // auto [a, b, L, R] = pq.top();
    int a, b, L, R;
    tie(a,b,L,R) = pq.top();
    pq.pop();
    Q.push_back(a);
    Q.push_back(b);
    if(R - L < 2) continue;
    // auto [l,r] = find_lr(L,R);
    int l, r;
    tie(l,r) = find_lr(L,R);
    vector<pair<int,int>> v = {{L,l},{l+1,r},{r+1,R}};
    for(auto e : v){
      if(e.second-e.first < 2) continue;
      // auto [ll,rr] = find_lr(e.first,e.second);
      int ll, rr;
      tie(ll,rr) = find_lr(e.first,e.second);
      pq.emplace(P[ll],P[rr],e.first,e.second);
    }
  }

  for(int i = 0; i < N; ++i)
    cout << Q[i] << (i+1 < N ? " " : "\n");
}

