	int x = S[p].find(l,r);
	int px = pos[x];
	int y = S[p^1].find(px + 1, r);
	int py = pos[y];

	if(par != -1) {
		adj[par].push_back({x,y,curNode});
	}
	else {
		pq.push({x,y,curNode});
	}

	getans(l, px, p, par);
	getans(px + 1, py, p^1, curNode);
	getans(py + 1, r, p, par);
}

