			fir=i;
		}
		else{
			if(v[fir-1]>v[i-1]) fir=i;
		}
	}
	for(int i=fir+1;i<=len;i+=2){
		if(sec==-1){
			sec=i;
		}
		else{
			if(v[sec-1]>v[i-1]) sec=i;
		}
