		v1.push_back(v[i-1]);
	} 
	for(int i=fir+1;i<sec;i++){
		v2.push_back(v[i-1]);
	} 
	for(int i=sec+1;i<len;i++){
		v3.push_back(v[i-1]);
	} 
	v1=dfs(v1,len1);
