void build(int x,int l,int r)
{
	if(l==r)
	{
		seg[0][x]=make_pair(a[l],l);
		seg[1][x]=make_pair(b[l],l);
		return;
	}
	int md=(l+r)/2;
	build(x*2,l,md);
	build(x*2+1,md+1,r);
	seg[0][x]=min(seg[0][x*2],seg[0][x*2+1]);
	seg[1][x]=min(seg[1][x*2],seg[1][x*2+1]);
}
pair<int,int> qry(int x,int l,int r,int ll,int rr,int t)
{
	if(ll>r||rr<l)return make_pair(1e9+7,-1);
	if(l<=ll&&r>=rr)return seg[t][x];
	int md=(ll+rr)/2;
	return min(qry(x*2,l,r,ll,md,t),qry(x*2+1,l,r,md+1,rr,t));
}
