struct S{
	int i,j;
	int t,u;
	int i2,j2;
	int base;
	S(int i,int j,int i2, int j2, int t,int u):i(i),j(j),i2(i2),j2(j2),t(t),u(u){}
	S(){}
	bool operator<(const S &s)const{
		return t>s.t;//INVERSE
	}
};

pair<bool,S> get_param(segment_tree<int> st[2],int i,int j){
	if(j-i<=1){
		return {false,S()};
	}
	int base = i%2;
	auto pr = st[base].range_query({i/2,(j+!base)/2});
	int val = pr.first, id = pr.second * 2 + base;
	/*
	dump(val);dump(id);
	dump((id+1)/2);
	dump(j/2);
	*/
	auto pr2 = st[!base].range_query({(id+1)/2,(j+base)/2});
	int val2 = pr2.first, id2 = pr2.second * 2 + (!base);
//	dump(val2);dump(id2);
	return {true,S(i,j,id,id2,val,val2)};
}

void solve(long long N, vector<long long> p){
	segment_tree<int> st[2] = {segment_tree<int>(N/2+5), segment_tree<int>(N/2+5)};
	REP(base,2){
		vector<int> p2;
		for(int i=base;i<N;i+=2)p2.push_back(p[i]);
		st[base].set_all(p2);
	}
	priority_queue<S> q;
	vector<int> ret;
	q.push(get_param(st,0,N).second);
	int ct = 0;
	while(!q.empty()){
//		cerr<<"==========="<<endl;
//		dump(q.size());
		S s(q.top());q.pop();
		int i = s.i, j = s.j;
		int base = i%2;
		if(s.t!=-1){
			ret.push_back(s.t);
			ret.push_back(s.u);
		}
//		cerr<<i<<" "<<j<<" "<<s.i2<<" "<<s.j2<<endl;
		auto pr0 = get_param(st,i,s.i2);
		if(pr0.first)q.push(pr0.second);
		auto pr1 = get_param(st,s.i2+1,s.j2);
		if(pr1.first)q.push(pr1.second);
		auto pr2 = get_param(st,s.j2+1,j);
		if(pr2.first)q.push(pr2.second);
	}
	REP(i,ret.size()){
		fout<<ret[i];
		if(i<ret.size()-1)fout<<" ";
	}
	fout<<endl;
}

int main(){	
	long long N;
	fin >> N;
	vector<long long> p(N-1+1);
	for(int i = 0 ; i <= N-1 ; i++){
		fin >> p[i];
	}
	solve(N, p);
	return 0;
}

