const int MX = 1000000;
const int INF = 1000000000;
int tree[2][MX], pos[2][MX];
int step, n;
vector<int> ans, a, prs, cs;
vector<pair<int, int> > ps;
vector<vector<int> > gr;

int findPosMin(int ind, int l, int r) {
    int p = -1;
    int val = INF;
    l += step;
    r += step;
    while (l <= r) {
          if (val > tree[ind][l]) {
              val = tree[ind][l];
              p = pos[ind][l];
          }
          if (val > tree[ind][r]) {
              val = tree[ind][r];
              p = pos[ind][r];
          }
          l = (l+1)/2;
          r = (r-1)/2;
    }
    return p;
}

int findPosMin(int l, int r) {
    int p0 = findPosMin(0, l, r);
    int p1 = findPosMin(1, l, r);
    return (a[p0] < a[p1]) ? p0 : p1;
}

int dfs(int l, int r) {
    //cout << "DFS " << l << ' ' << r << endl;
    if (l + 1 == r) {
        ps[a[l]] = make_pair(a[l], a[r]);
        cs[a[l]] = 0;
      //  cout << "DFS returns " << a[l] << endl;
        return a[l];
    }

    int p = findPosMin(l, r);
    if ((p - l)&1) {
        int pp = findPosMin((l&1), l, p-1);
        ps[a[pp]] = make_pair(a[pp], a[p]);
        if (pp > l) {
            prs[dfs(l, pp-1)] = a[pp];
            cs[a[pp]]++;
        }

        if (pp + 1 < p) {
            prs[dfs(pp+1, p-1)] = a[pp];
            cs[a[pp]]++;
        }

        if (p < r) {
            prs[dfs(p+1, r)] = a[pp];
            cs[a[pp]]++;        
        }
        //cout << "DFS returns " << a[pp] << endl;

        return a[pp];
    }
    else {
        int pp = findPosMin(1 - (p&1), p+1, r);
        ps[a[p]] = make_pair(a[p], a[pp]);
        if (p > l) {
            prs[dfs(l, p-1)] = a[p];
            cs[a[p]]++;
        }

        if (p + 1 < pp) {
            prs[dfs(p+1, pp-1)] = a[p];
            cs[a[p]]++;
        }

        if (pp < r) {
            prs[dfs(pp+1, r)] = a[p];
            cs[a[p]]++;
        }
       // cout << "DFS returns " << a[p] << endl;

        return a[p];
    }

}

void solve() {
     cin >> n;
     step = 1;
     while (step < n)
         step *= 2;
     a.assign(n, 0);
     ps.assign(n, make_pair(-1, -1));
