         cerr << cs[i] << ' ';
     cerr << endl;
     */
     for (int i = 0; i < n; ++i)
         if (prs[i] >= 0)
            gr[prs[i]].push_back(i);

     set<pair<int, int> > ST;
     /*for (int i = 0; i < n; ++i)
         if (cs[i] == 0 && ps[i].first >= 0)
            ST.insert(ps[i]);*/
     ST.insert(ps[root]);
     //cerr << "EEE" << endl;
         set<pair<int, int> >::iterator it = ST.end();
     //cerr << ST.size() << " sz" << endl;
     while (!ST.empty()) {
         set<pair<int, int> >::iterator it = ST.begin();
       //  cerr << "EEE" << endl;

         //--it;
     //cerr << "EEE" << endl;

         pair<int, int> p = *it;
         //cerr << "EEE" << endl;

         ST.erase(it);
         //cerr << "EEE" << endl;
         ans.push_back(p.first);
         ans.push_back(p.second);
         //cerr << p.first << ' ' << p.second << " in ans" << endl;
         /*if (prs[p.first] < 0)
            break;
         if (--cs[prs[p.first]] == 0)
             ST.insert(ps[prs[p.first]]);*/
         for (int i = 0; i < (int)gr[p.first].size(); ++i)
             ST.insert(ps[gr[p.first][i]]);
     }

     for (int i = n-1; i >= 0; --i)
