using namespace std;
using vi = vector<int> ;
using P = pair<int, int>;

template<typename T>
class segtree {
public:
	segtree(int n) {
		for (size = 1; size < n; size *= 2);
		vec.resize(2 * size -1, zero);
	}
	segtree(std::vector<T> v) {
		int n = v.size();
		for (size = 1; size < n; size *= 2);
		vec.resize(2 * size -1, zero);
		for (int i = 0; i < n; i++) {
			vec[i + size-1] = v[i];
		}
		for (int i = size - 2; i >= 0; i--) {
			vec[i] = func(vec[i * 2 + 1], vec[i * 2 + 2]);
		}
	}
	void set(int n, T x) {
		n += size - 1;
		while (n >= 0) {
			vec[n] = func(vec[n], x);
			n = (n + 1) / 2 - 1;
		}
	}
	int get(int a, int b) {
		return get_func(0, 0, size, a, b);
	}
private:
	T zero =2147483647;
	std::function<T(T, T)> func = [](T a, T b) {return std::min(a, b); };
	vector<T> vec;
	int size;

	int get_func(int n, int p, int q, int x, int y) {
		if (q - p == 1)return vec[n];
		if (x == p && q == y) return vec[n];
		int mean = (p + q) / 2;
		T l = zero;
		T r = zero;
		if (x < mean)l = get_func(n * 2 + 1, p, mean, x, std::min(y,mean));
		if (mean < y)r = get_func(n * 2 + 2, mean, q, std::max(x,mean), y);
		return func(l, r);
	}
};

int main() {
	int n;
	cin >> n;
	vi p(n);
	vi index(n+1);
	segtree<int> evens(n);
	segtree<int> odds(n);
	for (int i = 0; i < n; i++) {
		cin >> p[i];
		index[p[i]] = i;
		if (i % 2 == 0) {
			evens.set(i, p[i]);
		}
		else {
			odds.set(i, p[i]);
		}
	}
	priority_queue<pair<int, P>> que;
	que.emplace(-evens.get(0,n), P(0, n));
	vi ans;
	while (!que.empty()) {
		pair<int,P> p = que.top(); que.pop();
		int minimum = -p.first;
		int a = p.second.first;
		int b = p.second.second;
		int pos = index[minimum];
		int next;
		if (pos % 2 == 0) {
			next = odds.get(pos+1, b);
		}
		else {
			next = evens.get(pos+1, b);
		}
		ans.push_back(minimum);
		ans.push_back(next);
		if (a < pos) {
			if ((a) % 2 == 0) {
				int m = evens.get(a ,pos);
				que.emplace(-m, P(a, pos));
			}
			else {
				int m = odds.get(a, pos);
				que.emplace(-m, P(a, pos));
			}
		}
		if (pos + 1 < index[next]) {
			if ((pos + 1) % 2 == 0) {
				int m = evens.get(pos + 1, index[next]);
				que.emplace(-m, P(pos + 1, index[next]));
			}
			else {
				int m = odds.get(pos + 1, index[next]);
				que.emplace(-m, P(pos + 1, index[next]));
			}
		}
		if (index[next] + 1 < b) {
			if ((index[next] + 1) % 2 == 0) {
				int m = evens.get(index[next] + 1, b);
				que.emplace(-m, P(index[next] + 1, b));
			}
			else {
				int m = odds.get(index[next] + 1, b);
				que.emplace(-m, P(index[next] + 1, b));
			}
		}
	}

	for (int x : ans) {
		cout << x << " ";
	}
	cout << endl;

}

#include <bits/stdc++.h>
using namespace std;
using lint = long long int;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... U> void assign(V<T>& v, int n, const U&... u) { v.resize(n); for (auto&& i : v) assign(i, u...); }

struct M {
  using T = pair<int, int>;
  using U = int;
  static T op(const T& a, const T& b) { return T(min(a.first, b.first), max(a.second, b.second)); }
  static constexpr T e() { return T(numeric_limits<int>::max(), numeric_limits<int>::min()); }
  static void ap(T& a, const U& g, int k) { a.first *= g, a.second *= g; if (g < 0) swap(a.first, a.second); }
  static void ap(U& f, const U& g) { f *= g; }
  static constexpr U id() { return 1; }
};

template<class M> struct ST {
  using T = typename M::T;
  using U = typename M::U;
  int n;
  V<T> t;
  V<U> u;
  V<> k;

  ST(int n) : n(n) {
    t.assign(2 * n, M::e());
    u.assign(n, M::id());
    k.assign(2 * n, 1);
    for (int i = n - 1; i; i--) k[i] = k[2 * i] + k[2 * i + 1];
  }

  void _ap(int i, const U& f) {
    M::ap(t[i], f, k[i]);
    if (i < n) M::ap(u[i], f);
  }

  void build() {
    for (int i = n - 1; i; i--) t[i] = M::op(t[2 * i], t[2 * i + 1]);
  }

  T get(int l, int r) {
    _push(l, r);
    T resl = M::e(), resr = M::e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) resl = M::op(resl, t[l++]);
      if (r & 1) resr = M::op(t[--r], resr);
    }
    return M::op(resl, resr);
  }

  void push() {
    for (int i = 1; i < n; i++) {
      _ap(2 * i, u[i]);
      _ap(2 * i + 1, u[i]);
      u[i] = M::id();
    }
  }

  void _push(int l, int r) {
    for (int hl = 8 * sizeof(int) - __builtin_clz(l + n) - 1, hr = 8 * sizeof(int) - __builtin_clz(r - 1 + n) - 1; hr > 0; hl--, hr--) {
      int i = r - 1 + n >> hr;
      _ap(2 * i, u[i]);
      _ap(2 * i + 1, u[i]);
      u[i] = M::id();
      i = l + n >> hl;
      if (i == r - 1 + n >> hr or i >= n) continue;
      _ap(2 * i, u[i]);
      _ap(2 * i + 1, u[i]);
      u[i] = M::id();
    }
  }

  void set(int l, int r, const U& f) {
    _push(l, r);
    for (int i = l + n, j = r + n; i < j; i >>= 1, j >>= 1) {
      if (i & 1) _ap(i++, f);
      if (j & 1) _ap(--j, f);
    }
    for (l += n; !(l & 1);) l >>= 1;
    while (l >>= 1) t[l] = M::op(t[2 * l], t[2 * l + 1]);
    for (r += n; !(r & 1);) r >>= 1;
    while (r >>= 1) t[r] = M::op(t[2 * r], t[2 * r + 1]);
  }
};

struct M2 {
  using T = int;
  static T op(const T& a, const T& b) { return a + b; }
  static constexpr T e() { return 0; }
};

template<class M> struct ST2 {
  using T = typename M::T;
  int n;
  V<T> t;

  ST2(int n) : n(n) {
    t.assign(2 * n, M::e());
  }

  void build() {
    for (int i = n - 1; i; i--) t[i] = M::op(t[2 * i], t[2 * i + 1]);
  }

  T get(int l, int r) {
    T resl = M::e(), resr = M::e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) { 
      if (l & 1) resl = M::op(resl, t[l++]); 
      if (r & 1) resr = M::op(t[--r], resr);
    }
    return M::op(resl, resr);
  }

  void set(int i, const T& a) {
    for (t[i += n] = a; i >>= 1;) t[i] = M::op(t[2 * i], t[2 * i + 1]);
  }
};

