using F2 = std::function<T(T,T)>;

template <typename T, int N, typename F = std::plus<T> >
struct SegmentTree{
    SegmentTree(T u, F f = F()){
        size = 1;
        while(size < N){
            size <<= 1;
        }

        unit = u;
        func = f;

        init();
    }
    void addParentIndex(int parent){
        index[parent] = data[parent] == data[parent*2] ? index[parent*2] : index[parent*2+1];
    }
    void init(){
        for(int i=0;i<size;++i){
            data[i+size] = unit;
            index[i+size] = i;
        }

        for(int i=size-1;i>0;--i){
            data[i] = func(data[i*2], data[i*2+1]);
            addParentIndex(i);
        }
    }
    void update(int k, int v){
        k += size;
        data[k] = v;

        while(k > 1){
            k >>= 1;
            data[k] = func(data[k*2], data[k*2+1]);
            addParentIndex(k);
        }
    }
    inline std::tuple<T, int> query(int l, int r){
        return _query(l, r, 1, 0, size);
    }
    std::tuple<T, int> _query(int a, int b, int k, int l, int r){
        if(b <= l || r <= a){return std::make_tuple(unit, -1);}
        if(a <= l && r <= b){return std::make_tuple(data[k], index[k]);}
        int mid = (l + r) >> 1;
        auto ql = _query(a, b,   2*k,   l, mid),
             qr = _query(a, b, 2*k+1, mid, r  );
        auto res = func(fst(ql), fst(qr));
        return std::make_tuple(res, res == fst(ql) ? snd(ql) : snd(qr));
    }

    T unit, data[N*4];
    int index[N*4];
    int size;
    F func;
};

