        int a = p.fi, l = p.se.fi, r = p.se.se;
        SegTree<ll>& cur = (idx[a]&1 ? odd : even);
        SegTree<ll>& nxt = (idx[a]&1 ? even : odd);

        if(cur.query(idx[a], idx[a]+1) == INF) continue;

        int b = nxt.query(idx[a], r);

        ans.push_back(a);
        ans.push_back(b);

        cur.add(idx[a], idx[a]+1, INF);
        nxt.add(idx[b], idx[b]+1, INF);

        if(l != idx[a]) q.push(make_pair(cur.query(l, idx[a]), make_pair(l, idx[a])));
        if(idx[a] + 1 != idx[b]) q.push(make_pair(nxt.query(idx[a]+1, idx[b]), make_pair(idx[a]+1, idx[b])));
        if(idx[b] + 1 != r) q.push(make_pair(cur.query(idx[b]+1, r), make_pair(idx[b]+1, r)));
    }
    rep(i, n) {
        cout << ans[i] << (i+1 == n ? '\n' : ' ');
    }
    return 0;
}

