const int N = 200100;
const int inf = 233333333;

struct Node{
	int x, y, k;
	Node(){}
	Node(int a, int b, int c) {x = a, y = b, k = c;}
	bool operator < (const Node & a) const{
		if(k < a.k) return 1;
		if(k > a.k) return 0;
		if(x == a.x) return y < a.y;
		return x < a.x;
	}
}p[N];

int n, nn, M;
int T1[N << 2], T2[N << 2], seq[N]; 

int Min(int x, int y){if(seq[x] > seq[y]) return y; return x;}

int Query(int x, int y, int * T){
	if(x > y) return 0;
	int res = 0;
	for(x = x + M - 1, y = y + M + 1; x ^ y ^ 1; x >>= 1, y >>= 1){
		if(~ x & 1) res = Min(res, T[x ^ 1]);
		if(  y & 1) res = Min(res, T[y ^ 1]);
	}
	return res;
}

void Change(int x, int t, int * T){
	x += M;
	T[x] = t;
	for(x >>= 1; x; x >>= 1) T[x] = Min(T[x << 1], T[x << 1 | 1]);
	return;
}

void Solve(int l, int r, int dep){
	if(l > r) return;
	int x, y;
	if(l & 1){
		x = Query(l, r, T1);
		y = Query(x, r, T2);
		p[++ nn] = Node(seq[x], seq[y], dep);
	}
	else{
		x = Query(l, r, T2);
		y = Query(l, r, T1);
		p[++ nn] = Node(seq[x], seq[y], dep);
	}

	Solve(l, x - 1, dep + 1);
	Solve(x + 1, y - 1, dep + 1);
	Solve(y + 1, r, dep + 1);

	return;
}

int main(){
	seq[0] = inf;
	scanf("%d", & n);
	for(int i = 1; i <= n; i ++)
		scanf("%d", &seq[i]);
	for(M = 1; M <= n + 1; M <<= 1);
	for(int i = 1; i <= n; i += 2) T1[i + M] = i;
	for(int i = 2; i <= n; i += 2) T2[i + M] = i;
	for(int i = M - 1; i; i --) T1[i] = Min(T1[i << 1], T1[i << 1| 1]), T2[i] = Min(T2[i << 1], T2[i << 1 | 1]);
	Solve(1, n, 0);

	sort(p + 1, p + nn + 1);
	for(int i = 1; i <= nn; i ++)
		printf("%d %d ", p[i].x, p[i].y);

	return 0;
}

