#define MAXN 200010
#define L (id << 1)
#define R ((id << 1) | 1)

int n;
int p[MAXN], q[MAXN];

int node[MAXN << 2], oddmin[MAXN << 2], evenmin[MAXN << 2];

void build(int id, int l, int r) {
    if (l == r) {
        oddmin[id] = l;
        evenmin[id] = -1;
        return;
    }

    int mid = (l + r) >> 1;
    build(L, l, mid);
    build(R, mid + 1, r);

    if ((mid - l) % 2) {
        if (p[oddmin[L]] < p[oddmin[R]]) {
            oddmin[id] = oddmin[L];
        } else {
            oddmin[id] = oddmin[R];
        }

        if (evenmin[L] == -1) {
            evenmin[id] = evenmin[R];
        } else {
            if (evenmin[R] == -1 || p[evenmin[L]] < p[evenmin[R]]) {
                evenmin[id] = evenmin[L];
            } else {
                evenmin[id] = evenmin[R];
            }
        }
    } else {
        if (evenmin[R] == -1 || oddmin[L] < evenmin[R]) {
            oddmin[id] = oddmin[L];
        } else {
            oddmin[id] = evenmin[R];
        }

        if (evenmin[L] == -1 || oddmin[R] < evenmin[L]) {
            evenmin[id] = oddmin[R];
        } else {
            evenmin[id] = evenmin[L];
        }
    }
}

int query(int id, int l, int r, int ql, int qr) {
    if (l > qr || r < ql) return -1;

    bool tmp = ((l - ql) % 2 == 0);

    if (l >= ql && r <= qr) {
        return tmp ? oddmin[id] : evenmin[id];
    }

    int mid = (l + r) >> 1;

    int res1 = query(L, l, mid, ql, qr);
    int res2 = query(R, mid + 1, r, ql, qr);

    if (res1 == -1) return res2;
    if (res2 == -1) return res1;
    if (p[res1] < p[res2]) {
        return res1;
    } else {
        return res2;
    }
}

