const int N = 200022;
const int INF = 1000000000;
struct node {
    int mn, mnInd;
    node() {mn = INF,mnInd = N;}

    node (int mnn , int idx) {mn = mnn,mnInd = idx;}
};
int n,arr[N];
node odd[8*N], even[8*N];
vector <vector<pair<int,int> > > vec;

void buildOdd(int pos,int l,int r) {
    if(l == r) {
        if(l % 2)
            odd[pos] = node (arr[l],l);
        return;
    }
    int mid = (l+r)/2;
    buildOdd(pos*2,l,mid), buildOdd(pos*2+1,mid+1,r);
    if(odd[pos*2].mn < odd[pos*2+1].mn)
        odd[pos] = odd[pos*2];
    else
        odd[pos] = odd[pos*2+1];
}

void buildEven(int pos,int l,int r) {
    if(l == r) {
        if(l % 2 == 0)
            even[pos] = node (arr[l],l);
        return;
    }
    int mid = (l+r)/2;
    buildEven(pos*2,l,mid), buildEven(pos*2+1,mid+1,r);
    if(even[pos*2].mn < even[pos*2+1].mn)
        even[pos] = even[pos*2];
    else
        even[pos] = even[pos*2+1];
}

node getOdd(int pos,int l,int r,int qLow,int qHigh) {
    if(l > qHigh || r < qLow || qLow>qHigh)
        return node();
    if(l >= qLow && r <= qHigh)
        return odd[pos];
    int mid = (l+r)/2;
    node lf = getOdd(pos*2,l,mid,qLow,qHigh), ri = getOdd(pos*2+1,mid+1,r,qLow,qHigh);
    if(lf.mn < ri.mn)
        return lf;
    return ri;
}

node getEven(int pos,int l,int r,int qLow,int qHigh) {
    if(l > qHigh || r < qLow || qLow > qHigh)
        return node();
    if(l >= qLow && r <= qHigh)
        return even[pos];
    int mid = (l+r)/2;
    node lf = getEven(pos*2,l,mid,qLow,qHigh), ri = getEven(pos*2+1,mid+1,r,qLow,qHigh);
    if(lf.mn < ri.mn)
        return lf;
    return ri;
}

void solve(int l,int r,int curr) {
    if(l > r || l < 0 )
        return;
    if(vec.size() <= curr)
        vec.push_back(vector<pair<int,int> >());
    node o = getOdd(1,0,n-1,l,r);
    node e = getEven(1,0,n-1,l,r);
    pair<int,int> a,b;
    node temp = getEven(1,0,n-1,o.mnInd+1,r);
    bool aa = true;
    if(temp.mnInd >= n) {
        temp = getEven(1,0,n-1,l,o.mnInd-1);
        if(temp.mnInd >= n) {
            cout<<"LOL";
            exit(0);
        }
        a = make_pair(temp.mn,o.mn);
    } else {
        aa = false;
        a = make_pair(o.mn,temp.mn);
    }

    node temp2 = getOdd(1,0,n-1,e.mnInd+1,r);
    bool bb = true;
    if(temp2.mnInd >= n) {
        temp2 = getOdd(1,0,n-1,l,e.mnInd-1);
        if(temp2.mnInd >= n) {
            cout<<"LOL";
            exit(0);
        }
        b= make_pair(temp2.mn,e.mn);
    } else {
        bb = false;
        b=make_pair(e.mn,temp2.mn);
    }
    if(a < b) {
        vec[curr].push_back(a);
        if(aa) {
            solve(l,temp.mnInd-1,curr+1);
            solve(temp.mnInd+1,o.mnInd-1,curr+1);
            solve(o.mnInd+1,r,curr+1);
        } else {
            solve(l,o.mnInd-1,curr+1);
            solve(o.mnInd+1,temp.mnInd-1,curr+1);
            solve(temp.mnInd+1,r,curr+1);
        }
    } else {
        vec[curr].push_back(b);
        if(bb) {
            solve(l,temp2.mnInd-1,curr+1);
            solve(temp2.mnInd+1,e.mnInd-1,curr+1);
            solve(e.mnInd+1,r,curr+1);
        } else {
            solve(l,e.mnInd-1,curr+1);
            solve(e.mnInd+1,temp2.mnInd-1,curr+1);
            solve(temp2.mnInd+1,r,curr+1);
        }
    }
}

