inline void solve(int x)
{
    int aa, bb;
    for(int i=x;i;i=pre[i])
    {
        aa=i-pre[i];
        break;
    }
    if(x != n)
    {
        for(int i=x;i<=n;i=nxt[i])
        {
            bb=nxt[i]-i;
            break;
        }
        if(a[x] + a[x - aa] < a[x] + a[x + bb])
        {
            //cout << a[x] << " " << a[x + bb] << endl;
            vis[a[x + bb]] = true;
            ans.push_back({a[x], a[x + bb]});
            del(x);
            del(x + bb);
        }
        else
        {
            //cout << a[x - aa] << " " << a[x] << endl;
            ans.push_back({a[x - aa], a[x]});
            vis[a[x - aa]] = true;
            del(x);
            del(x - aa);
        }
        return ;
    }
    //cout << a[x - aa] << " " << a[x] << endl;
    ans.push_back({a[x - aa], a[x]});
    vis[a[x - aa]] = true;
    del(x);
    del(x - aa);
