	std::vector<SegmentTree<M> > even(2,SegmentTree<M>(n,M(INF,-1),[](M a, M b) { return (a.x<b.x)?a:b; }));
	// SegmentTree<M> odd(n,M(INF,-1),[](M a, M b) { return (a.x<b.x)?a:b; });
	rep(i,n) {
		even[i&1].set(i,M(p[i],i));
	}
