vector<ll> func(int lp,int rp,set<ll> odd,set<ll> even){
  if(rp-lp<2)return vector<ll>();
  vvector<ll> reses;
  vector<ll> res;
  ll lmin = *odd.begin();
  set<ll> next_odd;
  set<ll> next_even;
  int p;
  ll rmin;
  for(int i=lp,cnt=0;i<rp;++i,++cnt){
    if(cnt&1){
      even.erase(line[i]);
    }else{
      odd.erase(line[i]);
    }
    if(lmin == line[i]){
      rmin = *even.begin();
      res.emplace_back(lmin);
      res.emplace_back(rmin);
      reses.emplace_back(func(lp,i,next_odd,next_even));
      p = i + 1;
      next_odd.clear();
      next_even.clear();
      break;
    }
    if(cnt&1){
      next_even.insert(line[i]);
    }else{
      next_odd.insert(line[i]);
    }
  }

  for(int i=p,cnt=0;i<rp;++i,++cnt){
    if(cnt&1){
      next_even.erase(line[i]);
    }else{
      next_odd.erase(line[i]);
    }
    if(rmin == line[i]){
      reses.emplace_back(func(p,i,next_odd,next_even));
      reses.emplace_back(func(i+1,rp,odd,even));
      break;
    }
    if(cnt&1){
      next_even.insert(line[i]);
    }else{
      next_odd.insert(line[i]);
    }
  }
  int point[3]{0};
  while(true){
    int minp = 0;
    ll minn = INF;
    rep(i,3){
      if(point[i]<(int)reses[i].size()&&minn>reses[i][point[i]]){
	minp = i;
	minn = reses[i][point[i]];
      }
    }
    if(minn==INF)break;
    res.emplace_back(reses[minp][point[minp]]);
    res.emplace_back(reses[minp][point[minp]+1]);
    point[minp] += 2;
  }
  return res;
}


