{
    scanf("%d",&n);
    lp(i, 1, n)scanf("%d",&a[i]);
    a[n+1] = infi;

    build(1, n, 1);
    vector<pii> ans;
    solve(1, n,  ans);

    for(pii x:ans) printf("%d %d ",x.f,x.s);
    printf("\n");

    return 0;
}
