vector<int> dfs(vector<int> v,int len){
//	cout<<len<<endl;
	if(len==0) return v;
	if(len==2) return v;
	int fir=-1,sec=-1;
	for(int i=1;i<=len;i+=2){
		if(fir==-1){
			fir=i;
		}
		else{
			if(v[fir-1]>v[i-1]) fir=i;
		}
	}
	for(int i=fir+1;i<=len;i+=2){
		if(sec==-1){
			sec=i;
		}
		else{
			if(v[sec-1]>v[i-1]) sec=i;
		}
	}
	int len1=fir-1-1+1,len2=(sec-1)-(fir+1)+1,len3=len-(sec+1)+1;
//	cout<<fir<<" "<<sec<<" "<<len1<<" "<<len2<<" "<<len3<<" "<<endl;
	vector <int> v1;
	vector <int> v2;
	vector <int> v3;
	vector<int> ans;
	ans.push_back(v[fir-1]);
	ans.push_back(v[sec-1]);
	for(int i=1;i<fir;i++){
		v1.push_back(v[i-1]);
	} 
	for(int i=fir+1;i<sec;i++){
		v2.push_back(v[i-1]);
	} 
	for(int i=sec+1;i<len;i++){
		v3.push_back(v[i-1]);
	} 
	v1=dfs(v1,len1);
	v2=dfs(v2,len2);
	v3=dfs(v3,len3);
	while(v1.size()||v2.size()||v3.size()){
//		cout<<"F"<<endl;
		mpair pp;
		mpair ansp;
		ansp.first.first=0x3f3f3f3f;
		ansp.first.second=0x3f3f3f3f;
		int Len=-1;
		if(v1.size()){
//			Len++;
			pp.first.first=v1[0];
			pp.first.second=v1[1];
			pp.second=1;
			ansp=update(ansp,pp);
		}
		if(v2.size()){
//			Len++;
			pp.first.first=v2[0];
			pp.first.second=v2[1];
			pp.second=2;
			ansp=update(ansp,pp);
		}
		if(v3.size()){
//			Len++;
			pp.first.first=v3[0];
			pp.first.second=v3[1];
			pp.second=3;
			ansp=update(ansp,pp);
		}
//		sort(pp,pp+Len+1,cmp);
		if(ansp.second==1){
			ans.push_back(v1[0]);
			ans.push_back(v1[1]);
			v1.erase(v1.begin());
			v1.erase(v1.begin());
		}
		if(ansp.second==2){
			ans.push_back(v2[0]);
			ans.push_back(v2[1]);
			v2.erase(v2.begin());
			v2.erase(v2.begin());
		}
		if(ansp.second==3){
			ans.push_back(v3[0]);
			ans.push_back(v3[1]);
			v3.erase(v3.begin());
			v3.erase(v3.begin());
		}
//		for(int i=0;i<ans.size();i++) printf("%d ",ans[i]);cout<<endl;
	}
	return ans;
}
