template<class Monoid> struct SegmentTree {
	using Function = function< Monoid(Monoid, Monoid) >;

	int N; vector<Monoid> segment;
	const Function func;
	const Monoid id;

	SegmentTree(int n, const Function func, const Monoid id) : func(func), id(id) {
		N = 1;
		while (N < n) N <<= 1;
		segment.assign(2 * N, id);
	}

	void set(int num, Monoid x) {
		segment[N + num] = x;
	}
	void build() {
		for (int k = N - 1; k > 0; k--) {
			segment[k] = func(segment[2*k], segment[2*k+1]);
		}
	}
	void update(int k, Monoid x) {
		k = k + N; segment[k] = x;
		while(k >>= 1) {
			segment[k] = func(segment[2*k], segment[2*k+1]);
		}
	}

	// query:[a, b)
	Monoid query(int a, int b) {
		Monoid L = id; Monoid R = id; a += N; b += N;
		for (; a < b; a >>= 1, b >>= 1) {
			if (a & 1) L = func(L, segment[a++]);
			if (b & 1) R = func(segment[--b], R);
		}
		return func(L, R);
	}
	// 0-based numbering;
	Monoid operator[](const int k) const {
		return segment[N+k];
	}
};

struct data {
    int index, num;
};

data inf = {-1, (int) 1e9};

data mg(data a, data b) {
    if (a.num < b.num) return a;
    return b;
}

vector<vector<int>> e;
vector<pair<int, int>> pv;

void search(int l, int r, int par, vector<int> &v, SegmentTree<data> &odd, SegmentTree<data> &even) {
    if (r - l <= 0) return;
    data min1, min2;
    min1 = odd.query(l, r);
    min2 = even.query(l, r);
    if (l&1) swap(min1, min2);
    if (make_pair(v[l], v[min1.num]) < make_pair(v[min2.num], v[r-1])) {
        pv[l] = {v[l], v[min1.index]};
        e[par].emplace_back(l);
        search(l+1, min1.index, l, v, odd, even);
        search(min1.index+1, r, par, v, odd, even);
    } else {
        pv[min2.index] = {v[min2.index], v[r-1]};
        e[par].emplace_back(min2.index);
        search(l, min2.index, par, v, odd, even);
        search(min2.index+1, r-1, min2.index, v, odd, even);
    }
}

vector<int> ans;

void dfs(int root) {
    priority_queue<pair<pair<int, int>, int>, vector<pair<pair<int, int>, int>>, greater<pair<pair<int, int>, int>>> pq;
    for (auto x: e[root]) {
        pq.push({pv[x], x});
    }
    while (!pq.empty()) {
        pair<pair<int, int>, int> pp = pq.top(); pq.pop();
        for (auto x: e[pp.second]) {
            pq.push({pv[x], x});
        }
        ans.emplace_back(pp.first.first);
        ans.emplace_back(pp.first.second);
    }
}

int main(){
    int n; cin >> n;
    SegmentTree<data> odd(n, mg, inf), even(n, mg, inf);
    vector<int> v(n);
    e.resize(n+1); pv.resize(n+1);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
        if (i&1) odd.set(i, {i, v[i]});
        else even.set(i, {i, v[i]});
    }
    odd.build(); even.build();
    search(0, n, n, v, odd, even);
    dfs(n);
    for (int i = 0; i < n; i++) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << endl;
	return 0;
}

