int query(int l, int r){
	if(r-l<=0) return n;
	if(r-l<2) return l;
	int t = 0;
	while(l+(2<<(t+1))<=r) t++;
	int res = b[l][t];
	int res2 = query(l+(2<<t), r);
	return a[res]<a[res2]?res:res2;
}

vector<int> rec(int l, int r){
