struct BIT {
    vector<pii> tree;
    void init() {
        tree = vector<pii>(4*M, pii(0, 0));
    }
    void upd(int idx, pii val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] = val;
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = min(tree[2*n], tree[2*n + 1]);
    }
    pii quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return pii(1e9, 1e9);
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        pii L = quer(a, b, l, m, 2*n);
        pii R = quer(a, b, m + 1, r, 2*n + 1);
        return min(L, R);
    }
} odd, even;

struct seg {
    int l, r;
    pii x;
    bool operator <(const seg &i) const {
        return arr[x.first] > arr[i.x.first] || (arr[x.first] == arr[i.x.first] && arr[x.second] > arr[i.x.second]);
    }
};
