pii solve(int l, int r) {
    if(l & 1) {
        pii t = odd.quer(l/2, (r - 1)/2, 0, M - 1, 1);
        pii d = even.quer((t.second + 1)/2, r/2, 0, M - 1, 1);
        return pii(t.second, d.second);
    }
    else {
        pii t = even.quer(l/2, r/2, 0, M - 1, 1);
        pii d = odd.quer((t.second + 1)/2, (r - 1)/2, 0, M - 1, 1);
        return pii(t.second, d.second);
    }
}

