void build (int l,int r,int n){
    ax[n].l = l;ax[n].r = r;
    if(l==r){
      if(l%2==1)  {
        ax[n].sm1 = bx[l].first;
        ax[n].sm0 = 1000000;
      }
      else{
        ax[n].sm0 = bx[l].first;
        ax[n].sm1 = 1000000;
      }  return;
    }
    int mid = l+r>>1;
    build(l,mid,lc(n));build(mid+1,r,rc(n));
    ax[n].sm1 = min(ax[lc(n)].sm1,ax[rc(n)].sm1);
    ax[n].sm0 = min(ax[lc(n)].sm0,ax[rc(n)].sm0);
}

int finds (int l,int r,int n,bool flag){
    if(flag){
        if(ax[n].l==ax[n].r){
            return ax[n].sm1;
        }
        if(ax[n].r<l||ax[n].l>r)return 1000000;
        if(ax[n].r<=r&&ax[n].l>=l)return ax[n].sm1;
        return min(finds(l,r,lc(n),flag),finds(l,r,rc(n),flag));
    }
    else{
        if(ax[n].l==ax[n].r){
            return ax[n].sm0;
        }
        if(ax[n].r<l||ax[n].l>r)return 1000000;
        if(ax[n].r<=r&&ax[n].l>=l)return ax[n].sm0;
        return min(finds(l,r,lc(n),flag),finds(l,r,rc(n),flag));
    }
}

int sou (int l,int r,int n,bool flag,int ans){
    if(flag){
        if(ax[n].l==ax[n].r){
            if(ax[n].sm1==ans){
                    return ax[n].l;
            }
            return 0;
        }
        if(ax[n].r<l||ax[n].l>r)return 0;
        if(ax[n].r<=r&&ax[n].l>=l){
                if(ax[n].sm1==ans)return sou(l,r,lc(n),flag,ans)+sou(l,r,rc(n),flag,ans);
                return 0;
        }
        return sou(l,r,lc(n),flag,ans)+sou(l,r,rc(n),flag,ans);
    }
    else{
        if(ax[n].l==ax[n].r){
            if(ax[n].sm0==ans)return ax[n].l;
            return 0;
        }
        if(ax[n].r<l||ax[n].l>r)return 0;
        if(ax[n].r<=r&&ax[n].l>=l){
                if(ax[n].sm0==ans)return sou(l,r,lc(n),flag,ans)+sou(l,r,rc(n),flag,ans);
                return 0;
        }
        return sou(l,r,lc(n),flag,ans)+sou(l,r,rc(n),flag,ans);
    }
}

int findf (int x){
