    int l,r,ans,res;
    p = lower_bound(s.begin(),s.end(),x);r = *p - 1;
    l = *(--p) + 1;
    if(r==x){
        ans = finds(l,x-1,1,(x+1)%2);
        res = sou(l,x-1,1,(x+1)%2,ans);
    }
