// abstruct segment tree 抽象化セグメント木(非再帰)
// https://beet-aizu.github.io/library/library/segtree/basic/ushi.cpp.html
template <typename T>
struct segtree{
    using F = function<T(T,T)>;
    int n;
    F f;
    T ti;
    vector<T> dat;

    segtree(){}
    segtree(F f, T ti): f(f), ti(ti){}

    void init(int n_) {
        n = 1;
        while (n < n_) {
            n <<= 1;
        }
        dat.assign(n << 1, ti);
    }

    void build(const vector<T> &v) {
        int n_ = v.size();
        init(n_);
        for (int i = 0; i < n_; i++) {
            dat[n + i] = v[i];
        }
        for (int i = n - 1; i > 0; i--) {
            dat[i] = f(dat[i << 1], dat[(i << 1) | 1]);
        }
    }

    void set_val(int k, T x) {
        k += n;
        dat[k] = x;
        while (k >>= 1) {
            dat[k] = f(dat[k << 1],dat[(k << 1) | 1]);
        }
    }

    // [a, b)の範囲の情報を得る
    T query(int a, int b) {
        if (a >= b) {
            return ti;
        }
        T vl = ti, vr = ti;
        for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                vl = f(vl, dat[l]);
                l++;
            }
            if (r & 1) {
                r--;
                vr = f(dat[r], vr);
            }
        }
        return f(vl, vr);
    }

    template<typename C>
    int find(int st, C &check, T &acc, int k, int l, int r) {
        if(l + 1 == r){
            acc = f(acc, dat[k]);
            return check(acc) ? k-n : -1;
        }
        int m = (l + r) >> 1;
        if (m <= st) {
            return find(st, check, acc, (k << 1) | 1, m, r);
        }
        if (st <= l && !check(f(acc, dat[k]))) {
            acc = f(acc, dat[k]);
            return -1;
        }
        int vl = find(st, check, acc, k << 1, l, m);
        if (~vl) {
            return vl;
        }
        return find(st, check, acc, (k << 1) | 1, m, r);
    }

    // セグ木上の2分探索
    template<typename C>
    int find(int st, C &check){
        T acc = ti;
        return find(st, check, acc, 1, 0, n);
    }
};

