            podd[i] = plglg(inf, i);
        } else {
            peven[i] = plglg(inf, i);
            podd[i] = plglg(v, i);
        }
    }
    auto f = [](plglg a, plglg b) {
        if (a < b) {
            return a;
        } else {
            return b;
        }
    };
    segtree<plglg> segeven(f, plglg(inf, 0));
    segeven.build(peven);
    segtree<plglg> segodd(f, plglg(inf, 0));
    segodd.build(podd);
    priority_queue<tlglglglg, V<tlglglglg>, greater<tlglglglg>> que;
    plglg segp = segeven.query(0, N);
    que.push(tlglglglg(segp.first, segp.second, 0, N));
    vll ans;
    REP(i, 0, N / 2) {
        tlglglglg t = que.top();
        que.pop();
        ll val = get<0>(t);
        ll ind = get<1>(t);
        ll left = get<2>(t);
        ll right = get<3>(t);
        // cout << val << " " << ind << " " << left << " " << right << " ";
        ans.push_back(val);
        if (left % 2 == 0) {
            plglg sec = segodd.query(ind + 1, right);
            // cout << sec.first << " " << sec.second << endl;
            ans.push_back(sec.first);
            if (ind != left) {
                plglg segval = segeven.query(left, ind);
                que.push(tlglglglg(segval.first, segval.second, left, ind));
            }
            if (ind + 1 != sec.second) {
                plglg segval = segodd.query(ind + 1, sec.second);
                que.push(tlglglglg(segval.first, segval.second, ind + 1, sec.second));
            }
            if (sec.second + 1 != right) {
                plglg segval = segeven.query(sec.second + 1, right);
                que.push(tlglglglg(segval.first, segval.second, sec.second + 1, right));
            }
        } else {
            plglg sec = segeven.query(ind + 1, right);
            // cout << sec.first << " " << sec.second << endl;
            ans.push_back(sec.first);
            if (ind != left) {
                plglg segval = segodd.query(left, ind);
                que.push(tlglglglg(segval.first, segval.second, left, ind));
            }
            if (ind + 1 != sec.second) {
                plglg segval = segeven.query(ind + 1, sec.second);
                que.push(tlglglglg(segval.first, segval.second, ind + 1, sec.second));
            }
            if (sec.second + 1 != right) {
                plglg segval = segodd.query(sec.second + 1, right);
                que.push(tlglglglg(segval.first, segval.second, sec.second + 1, right));
            }
        }
    }
    REP(i, 0, N) {
        cout << ans[i] << " ";
    }
    cout << endl;
}

