inline void merge(pii&a,pii b)
{
	repl(a.xx,b.xx),repl(a.yy,b.yy);
}

inline void build(int x,int l,int r)
{
	if(l==r)
	{
		f[x].xx=l&1?s[l]:1e9;
		f[x].yy=l&1?1e9:s[l];
	}
	else
	{
		int t=(l+r)>>1;
		build(x<<1,l,t);
		build(x<<1|1,t+1,r);
		merge(f[x]=f[x<<1],f[x<<1|1]);
	}
}

pii qa;

inline void qry(int x,int l,int r,int ql,int qr)
{
	if(l>=ql&&r<=qr)return merge(qa,f[x]);
	int t=(l+r)>>1;
	if(ql<=t)qry(x<<1,l,t,ql,qr);
	if(qr>t)qry(x<<1|1,t+1,r,ql,qr);
}

inline int qry(int l,int r)
{
	qa=mp(1e9,1e9);
	qry(1,1,n,l,r);
	if(l&1)return qa.xx;
	return qa.yy;
}

