struct SegmentTree{

	int Min[N << 2];

	#define lc (o << 1)
	#define rc (o << 1 | 1)
	#define M ((L + R) >> 1)

	void build(int o, int L, int R){
		if(L == R) Min[o] = A[L];
		else{
			build(lc, L, M), build(rc, M + 1, R);
			Min[o] = min(Min[lc], Min[rc]);
		}
	}

	int query(int o, int L, int R, int l, int r){
		//if(o == 1) printf(":(%d %d)\n", l, r);
		if(l <= L && R <= r) return Min[o];
		else{
			int ret = 1e9;
			if(l <= M) ret = min(ret, query(lc, L, M, l, r));
			if(M < r) ret = min(ret, query(rc, M + 1, R, l, r));
			return ret;
		}
	}
}T[2];

