using namespace std;
vector<int> G[N];
set<PAIR> S;
PAIR C[N];
int n,m,a[N],A[4*N],B[4*N];
int minself(int x,int y)
{
	return a[x]>a[y] ? y : x;
}
void build(int t,int l,int r)
{
	int mid=(l+r)>>1;
	if(l==r){
		A[t]=B[t]=0;
		if(l&1) A[t]=l;
		else B[t]=l;
		return ;
	  }
	build(L(t),l,mid);
	build(R(t),mid+1,r);
	A[t]=minself(A[L(t)],A[R(t)]);
	B[t]=minself(B[L(t)],B[R(t)]);
}
int RMQ(int t,int l,int r,int l1,int r1,int *X)
{
	int mid=(l+r)>>1;
	if(l>r1 || r<l1) return 0;
	if(l>=l1&&r<=r1) return X[t];
	return minself(RMQ(L(t),l,mid,l1,r1,X),RMQ(R(t),mid+1,r,l1,r1,X));
}
int solve(int l,int r)
{
	int p,u,v,z;
	if(l>r) return 0;
	p=++m;
	if(l&1){
		u=RMQ(1,1,n,l,r,A);
		v=RMQ(1,1,n,u,r,B);
	  }
	else{
		u=RMQ(1,1,n,l,r,B);
		v=RMQ(1,1,n,u,r,A);
	  }
	C[p]=PAIR(a[u],a[v]);
	if(z=solve(l,u-1)) G[p].push_back(z);
	if(z=solve(u+1,v-1)) G[p].push_back(z);
	if(z=solve(v+1,r)) G[p].push_back(z);
	return p;
}
