struct SegmentTree {
private:
    int n;
    vector<int> node;
public:
    SegmentTree(vector<int> v) {
        int sz = v.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2*n-1,INF);
        for (int i = 0;i < sz;++i) node[i+n-1] = v[i];
        for (int i = n-2;i >= 0;--i) node[i] = min(node[2*i+1],node[2*i+2]);
    }
    void update(int x,int val) {
        x += (n-1);
        node[x] = val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = min(node[2*x+1],node[2*x+2]);
        }
    }

    int getmin(int a,int b,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return INF;
        if (a <= l && r <= b) return node[k];
        int vl = getmin(a,b,2*k+1,l,(l+r)/2);
        int vr = getmin(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> p(n+2),q(n+2),ans;
    vector<SegmentTree> seg(2,vector<int>(n+10,INF));
    priority_queue<P,vector<P>,greater<P>> que;
    set<int> st;
    for (int i = 1;i < n+1;++i) {
        cin >> p[i];
        q[p[i]] = i;
        seg[i&1].update(i,p[i]);
    }
    st.insert(0);
    st.insert(n+1);
    int a = seg[1].getmin(1,n+1),b = seg[0].getmin(q[a],n+1);
    que.push(P(a,b));
    for (int x = 0;x < n/2;++x) {
        P t = que.top();
        que.pop();
        ans.push_back(t.first);
        ans.push_back(t.second);
        int y[4] = {*(--st.lower_bound(q[t.first])),q[t.first],q[t.second],*st.lower_bound(q[t.second])};
        st.insert(q[t.first]);
        st.insert(q[t.second]);
        for (int i = 0;i < 3;++i) if (y[i]+1 < y[i+1]) {
            int u = seg[y[i+1]&1].getmin(y[i]+1,y[i+1]),v = seg[y[i]&1].getmin(q[u],y[i+1]);
            que.push(P(u,v));
        }
    }
    for (int i = 0;i < n;++i) cout << ans[i] << " \n"[i == n-1];
    return 0;
}

