template<typename Monoid,typename OperatorMonoid,typename F,typename G,typename H>
struct Segtree{
	int size=1;
	vector<Monoid>dat;
	vector<OperatorMonoid>lazy;
	const F f;
	const G g;
	const H h;
	Monoid M;
	OperatorMonoid OM;
	void set(int a,Monoid x){
		dat[a+size-1]=x;
	}
	void init(){
		for(int i=size-2;i>=0;i--){
			dat[i]=f(dat[i*2+1],dat[i*2+2]);
		}
	}
	void eval(int k,int l,int r){
		if(lazy[k]!=OM){
			dat[k]=g(dat[k],lazy[k],(r-l));
			if(r-l>1){
				lazy[2*k+1]=h(lazy[2*k+1],lazy[k]);
				lazy[2*k+2]=h(lazy[2*k+2],lazy[k]);
			}
			lazy[k]=OM;
		}
	}
	void update(int a,int b,OperatorMonoid M,int k=0,int l=0,int r=-1){
		if(r==-1)r=size;
		eval(k,l,r);
		if(r<=a||b<=l)return;
		if(a<=l&&r<=b){
			lazy[k]=h(lazy[k],M);
			eval(k,l,r);
			return;
		}
		update(a,b,M,k*2+1,l,(l+r)/2);
		update(a,b,M,k*2+2,(l+r)/2,r);
		dat[k]=f(dat[k*2+1],dat[k*2+2]);
	}
	Monoid query(int a,int b,int k=0,int l=0,int r=-1){
		if(r==-1)r=size;
		eval(k,l,r);
		if(r<=a||b<=l)return M;
		if(a<=l&&r<=b)return dat[k];
		Monoid lv=query(a,b,k*2+1,l,(l+r)/2);
		Monoid rv=query(a,b,k*2+2,(l+r)/2,r);
		return f(lv,rv);
	}
	Segtree(int x,F f,G g,H h,Monoid M,OperatorMonoid OM)
	:f(f),g(g),h(h),M(M),OM(OM){
		while(size<x)size*=2;
		dat.resize(size*2-1,M);
		lazy.resize(size*2-1,OM);
	}
};
int N,A[200005];
set<int>used;
set<pair<P,int>>st;
signed main(){
	cin>>N;
	auto f=[](P a,P b){
		if(a.first<b.first)return a;
		return b;
	};
	auto g=[](P a,int b,int sz){
		return P(b,a.second);
	};
	auto h=[](int a,int b){return b;};
	Segtree<P,int,decltype(f),decltype(g),decltype(h)>seg1(N/2,f,g,h,{inf,inf},inf-1),
			seg2(N/2,f,g,h,{inf,inf},inf-1);
	rep(i,N){
		cin>>A[i];
		if(i%2==0)seg1.set(i/2,{A[i],i/2});
		else seg2.set(i/2,{A[i],i/2});
	}

	seg1.init();seg2.init();
	vector<queue<P>>stacks;
	used.insert(N/2);
	while(1){
		P mnEven=seg1.query(0,seg1.size);
		if(mnEven.first==inf)break;
		int ri=*used.lower_bound(mnEven.second);
		P mnOdd=seg2.query(mnEven.second,ri);
		queue<P>st;
		rep(i,mnOdd.second-mnEven.second+1){
			if(i%2==0){
				st.push({A[(mnEven.second+i/2)*2],A[(mnOdd.second-i/2)*2+1]});
			}else {
				st.push({A[(mnEven.second+i/2)*2+1],A[(mnOdd.second-i/2)*2]});
			}
			seg1.update(mnEven.second+i,mnEven.second+i+1,inf);
			seg2.update(mnEven.second+i,mnEven.second+i+1,inf);
		}
		used.insert(mnEven.second);
		stacks.push_back(st);
	}
	rep(i,len(stacks)){
		st.insert({stacks[i].front(),i});
		stacks[i].pop();
	}
	while(!st.empty()){
		auto it=st.begin();
		cout<<it->first.first<<" "<<it->first.second<<" ";
		st.erase(it);
		if(stacks[it->second].size()){
			st.insert({stacks[it->second].front(),it->second});
			stacks[it->second].pop();
		}
	}
	cout<<endl;
}

