int M=1;
std::vector<int> seg_e, seg_o;
void init(int N){
  while(M<N) M*=2;
  M=M*2-1;
  for(int i=0;i<M;i++) {
    seg_e.push_back(1000000007);
    seg_o.push_back(1000000007);
  }
}
void update_e(int l, int r, int x, int k){
  k+=(M+1)/2-1;
  seg_e[k] = x;
  while(k>0){
    k = (k-1)/2;
    seg_e[k] = min(seg_e[k*2+1], seg_e[k*2+2]);
  }
}
void update_o(int l, int r, int x, int k){
  k+=(M+1)/2-1;
  seg_o[k] = x;
  while(k>0){
    k = (k-1)/2;
    seg_o[k] = min(seg_o[k*2+1], seg_o[k*2+2]);
  }
}
ll query_e(int a, int b, int l, int r, int k){
  if(r<=a || b<=l) return 1000000007;
  if(a<=l && r<=b) return seg_e[k];
  ll A = query_e(a, b, l, (l+r)/2, k*2+1);
  ll B = query_e(a, b, (l+r)/2, r, k*2+2);
  return min(A, B);
}
ll query_o(int a, int b, int l, int r, int k){
  if(r<=a || b<=l) return 1000000007;
  if(a<=l && r<=b) return seg_o[k];
  ll A = query_o(a, b, l, (l+r)/2, k*2+1);
  ll B = query_o(a, b, (l+r)/2, r, k*2+2);
  return min(A, B);
}
