    else update_o(0, (M+1)/2, a, i);
  }
  std::vector<int> ans;
  set<int> h;
  h.insert(N);

  multiset<vector<ll>> q;
  q.insert(std::vector<ll> {query_e(0, N, 0, (M+1)/2, 0), 0, N-1});

  while(!q.empty()){
    auto itr = q.begin();
    ll l = (*q.begin())[1], r = (*q.begin())[2], a = (*q.begin())[0], b;
    q.erase(itr);
