#include <bits/stdc++.h>
using namespace std;

#define N 200001
#define INF 2e9

int seg[N*4][2],in[N],ind[N],lazy[N*4];
void init(int pos,int l,int r) {
    lazy[pos] = 1;
    if(l==r) {
        seg[pos][0] = seg[pos][1] = INF;
        seg[pos][l&1] = in[l];
        return;
    }
    int mid = (l+r)/2;
    init(pos*2,l,mid);
    init(pos*2+1,mid+1,r);
    seg[pos][0] = min(seg[pos*2][0],seg[pos*2+1][0]);
    seg[pos][1] = min(seg[pos*2][1],seg[pos*2+1][1]);
}
int query(int pos,int l,int r,int ql,int qr,int bit) {
    if(qr<l || r<ql) {
        return INF;
    }
    if(ql<=l&& r<=qr) {
        return seg[pos][bit];
    }
    int mid = (l+r)/2;
    return min(query(pos*2,l,mid,ql,qr,bit),query(pos*2+1,mid+1,r,ql,qr,bit));
}
struct node {
    int l,r,val;
    node(int l_,int r_,int n) {
        l = l_,r = r_;
        val = query(1,1,n,l,r,l&1);
    }
    friend bool operator<(node x,node y) {
        return x.val>y.val;
    }
};
int ret[N];
void solve() {
    //input
    int n;
    scanf("%d",&n);
    for(int i=1;i<=n;++i) {
        scanf("%d",&in[i]);
        ind[in[i]] = i;
    }
    init(1,1,n);
    priority_queue<node> pq;
    node root = node(1,n,n);
    pq.push(root);
    int pos = 0;
    while(!pq.empty()) {
        node tmp = pq.top();
        pq.pop();
        int l = tmp.l,r = tmp.r, x = tmp.val;
        int xind = ind[x];
        int y = query(1,1,n,xind,r, (l&1)^1);
        ret[pos++] = x;
        ret[pos++] = y;
        int yind = ind[y];
        if(l<=xind-1) {
            pq.push(node(l,xind-1,n));
        }
        if(xind+1<=yind-1) {
            pq.push(node(xind+1,yind-1,n));
        }
        if(yind+1<=r) {
            pq.push(node(yind+1,r,n));
        }
    }
    for(int i=0;i<n;++i) {
        printf("%d ",ret[i]);
    }
    putchar('\n');
}
int main() {
    solve();
    return 0;
}

