#include <bits/stdc++.h>

using namespace std;

const int N = 200010;

int a[2][N];
int lg[N];
int f[2][18][N];

int get(int l, int r, int w) {
  int k = lg[r - l + 1];
  return a[w][f[w][k][l]] < a[w][f[w][k][r - (1 << k) + 1]] ? f[w][k][l] : f[w][k][r - (1 << k) + 1];
}

const int inf = 1e9;

int n;
int ans[N];
int tmp[N];

void solve(int l, int r, int w) {
  if (r - l <= 0) {
    return;
  }
  int p = get(l, r, w);
  int q = get(p + 1, r, 1 - w);
  solve(l, p - 1, w);
  solve(p + 1, q - 1, 1 - w);
  solve(q + 1, r, w);
  int xi = l;
  int yi = p + 1;
  int zi = q + 1;
  int cnt = 2;
  tmp[0] = a[w][p];
  tmp[1] = a[1 - w][q];
  while (true) {
    int vx = (xi > p - 1 ? inf : ans[xi]);
    int vy = (yi > q - 1 ? inf : ans[yi]);
    int vz = (zi > r ? inf : ans[zi]);
    if (vx == inf && vy == inf && vz == inf) {
      break;
    }
    if (vx < vy && vx < vz) {
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
    } else
    if (vy < vx && vy < vz) {
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
    } else {
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
    }
  }
  for (int i = 0; i < cnt; ++i) {
    ans[l + i] = tmp[i];
  }
}

int main() {
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int w = i % 2;
    scanf("%d", a[w] + i);
    a[1 - w][i] = inf;
  }
  lg[0] = -1;
  for (int i = 1; i < N; ++i) {
    lg[i] = lg[i / 2] + 1;
  }
  for (int w = 0; w < 2; ++w) {
    for (int j = 0, d = 1; d <= n; ++j, d *= 2) {
      for (int i = 0; i + d <= n; ++i) {
        if (j == 0) {
          f[w][j][i] = i;
        } else {
          f[w][j][i] = (a[w][f[w][j - 1][i]] < a[w][f[w][j - 1][i + d / 2]] ? f[w][j - 1][i] : f[w][j - 1][i + d / 2]);
        }
      }
    }
  }
  return 0;
  solve(0, n - 1, 0);
  for (int i = 0; i < n; ++i) {
    if (i > 0) putchar(' ');
    printf("%d", ans[i]);
  }
  putchar('\n');
}

