        pos_to_score.push(make_pair(-minscore3,l++));
        //cerr << "ccc" << endl;
      }
    }
    else{
      aa = query2(a,b,0,0,N/2);
      bb = query1(taiou[aa]+1,b+1,0,0,N/2);
      //cerr << "  " << aa << " " << bb << " " << endl;
