        pos_to_score.push(make_pair(-minscore1,l++));
        //cerr << "ddd" << endl;
      }
      if(taiou[bb] - taiou[aa] > 1){
        ll minscore2 = query1(taiou[aa]+1,taiou[bb],0,0,N/2);
        kukan.push_back(make_pair(taiou[aa]+1,taiou[bb]-1));
