   vector<int> p(N);
   for (int i = 0; i < N; ++i) {
      cin >> p[i];
   }

   SegmentTree<pair<int,int>> even(N,
         [](pair<int,int> a, pair<int,int> b){ return min(a, b); }, {IINF,-1});
   SegmentTree<pair<int,int>> odd(N,
         [](pair<int,int> a, pair<int,int> b){ return min(a, b); }, {IINF,-1});

   for (int i = 0; i < N; ++i) {
      if (i % 2 == 0) {
         even.set(i, {p[i],i});
         odd.set(i, {IINF,-1});
      } else {
         odd.set(i, {p[i],i});
         even.set(i, {IINF,-1});
      }
   }

   even.build();
   odd.build();

   priority_queue<trio<int,int,int>, vector<trio<int,int,int>>, greater<trio<int,int,int>>> que;
   que.push({ even.query(0, N).first, 0, N });

   vector<int> ans;

   for (int k = 0; k < N/2; ++k) {

      int l = que.top().second, r = que.top().third;
      que.pop();

      int i, j;
      if (l % 2 == 0) {
         i = even.query(l, r).second;
         j = odd.query(i+1, r).second;
      } else {
         i = odd.query(l, r).second;
         j = even.query(i+1, r).second;
      }

      ans.push_back(p[i]);
      ans.push_back(p[j]);

      if (l < i) que.push({l % 2 == 0 ? even.query(l, i).first : odd.query(l, i).first, l, i});
      if (i+1 < j) que.push({(i+1) % 2 == 0 ? even.query(i+1, j).first : odd.query(i+1, j).first, i+1, j});
      if (j+1 < r) que.push({(j+1) % 2 == 0 ? even.query(j+1, r).first : odd.query(j+1, r).first, j+1, r});
   }

   for (int i = 0; i < N; ++i) {
      cout << ans[i] << (i == N-1 ? "\n" : " ");
   }

   return 0;
}

