#include<cstdio>
struct Splay
{
	int v,s,min;
	Splay *ch[2];
	Splay(int x=0):v(x),s(1),min(x),ch{0,0}{}
	int cmp(int k)
	{
		int d=k-(ch[0]?ch[0]->s:0);
		if(d==1)return -1;
		return d>0;
	}
	void maintain()
	{
		s=1;min=v;
		if(ch[0])s+=ch[0]->s,min=min>ch[0]->min?ch[0]->min:min;
		if(ch[1])s+=ch[1]->s,min=min>ch[1]->min?ch[1]->min:min;
	}
};
void rotate(Splay *&o,int d)
{
	if(!o->ch[d^1])return;
	Splay *k=o->ch[d^1];
	o->ch[d^1]=k->ch[d];
	k->ch[d]=o;
	o->maintain();
	k->maintain();
	o=k;
}
void splay(Splay *&o,int k)
{
	if(!o)return;
	int d=o->cmp(k);
	if(d==1)k-=o->ch[0]->s+1;
	if(d!=-1)
	{
		Splay *p=o->ch[d];
		int e=p->cmp(k),k2=(!e?k:k-p->ch[0]->s-1);
		if(e!=-1)
		{
			splay(p->ch[e],k2);
			if(d==e)rotate(o,d^1);
			else rotate(o->ch[d],d);
		}
		rotate(o,d^1);
	}
}
Splay *merge(Splay *left,Splay *right)
{
	if(!left)return right;
	splay(left,left->s);
	left->ch[1]=right;
	left->maintain();
	return left;
}
void split(Splay *o,int k,Splay *&left,Splay *&right)
{
	if(!o){left=right=0;return;}
	splay(o,k);
	left=o;
	right=o->ch[1];
	o->ch[1]=0;
	left->maintain();
}
Splay *findmin(Splay *o)
{
	for(;;)
		if(o->min==o->v)return o;
		else if(o->ch[0]&&o->ch[0]->min==o->min)o=o->ch[0];
		else o=o->ch[1];
}
int n,p[220000],at[220000];
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)scanf("%d",p+i),at[p[i]]=i;
	Splay *odd=new Splay(p[1]),*even=new Splay(p[2]);
	for(int i=3;i<=n;i++)
		if(i&1)odd=merge(odd,new Splay(p[i]));
		else even=merge(even,new Splay(p[i]));
	for(int i=1;i<n;i+=2)
	{
		Splay *pos=findmin(odd);
		printf("%d ",pos->v);
