		while(at[even->v]<at[pos->v])rotate(even,0);
		if(at[even->v]>at[pos->v])
		{
			rotate(even,1);
			while(at[even->ch[1]->v]>at[pos->v])rotate(even->ch[1],1);
			while(at[even->v]<at[pos->v])rotate(even,0);
		}
		Splay *pos2=findmin(even->ch[1]);
