const int MAX_N = 2e5 + 7;
const int INF = 1e9 + 7;
///----------------------------------------------
int bod[MAX_N];
int p[MAX_N];
struct Tree {
	static const int Tree_N = MAX_N << 2;
	pii val[Tree_N]; int n;
	int ls(int o) { return o << 1; }
	int rs(int o) { return o << 1 | 1; }
	void update(int o) { 
		val[o].fi = min(val[ls(o)].fi, val[rs(o)].fi); 
		val[o].se = min(val[ls(o)].se, val[rs(o)].se);	
	}
	void build(int o, int l, int r) {
		if (l == r) {
			val[o].fi = l&1 ? p[l] : INF;
			val[o].se = l&1 ? INF  : p[l];
		} 
		else {
			int mid = (l + r) >> 1;
			build(ls(o), l, mid);
			build(rs(o), mid + 1, r);
			update(o);
		}
	}
	int init(int _n) { n = _n; build(1, 1, n); }
	//--
	pii _query(int o, int l, int r, int ql, int qr) {
		if (ql <= l && qr >= r) return val[o]; else {
			int mid = (l + r) >> 1;
			pii ret = mp(INF, INF);
			if (ql <= mid) {
				pii tmp =  _query(ls(o), l, mid, ql, qr);
				ret.fi = min(ret.fi, tmp.fi);
				ret.se = min(ret.se, tmp.se);
			}
			if (qr >  mid) {
				pii tmp = _query(rs(o), mid + 1, r, ql, qr);
				ret.fi = min(ret.fi, tmp.fi);
				ret.se = min(ret.se, tmp.se);
			}
			return ret;
		}
	}
	pii query(int ql, int qr) { return _query(1, 1, n, ql, qr); }
	//--
	void _change(int o, int l, int r, int qx, int qv) {
		if (l == r) {
			if (l&1) val[o].fi = qv; 
				else val[o].se = qv;
		}
		else {
			int mid = (l + r) >> 1;
			if (qx <= mid) _change(ls(o), l, mid, qx, qv);
				else _change(rs(o), mid + 1, r, qx, qv);
			update(o);
		}
	}
	void change(int qx, int qv) { _change(1, 1, n, qx, qv); }
}	tree;
