	tree.init(n);
	priority_queue<int, vector<int>, greater<int> > que;
	pii tmp = tree.query(1, n);
	que.push(tmp.fi);

	///work
	set<int> s; s.insert(1); bod[1] = n;
	vi ans;
	rep(i, 0, n/2) {
		int u = que.top(); que.pop(); de(u);
		ans.pb(u); u = pos[u]; 
		auto it = s.lower_bound(u);
		//get v
		if (i == 2) {
			de(u + 1);
			de(bod[*it]);
		}
		pii tmp = tree.query(u + 1, bod[*it]); 
		int v;
		if (u & 1) v = tmp.se;
			else v = tmp.fi;
		ans.pb(v); 
		v = pos[v];

		de(v);
		//change
		tree.change(u, INF);
		tree.change(v, INF);
		if (v < bod[*it]) {
			s.insert(v + 1);
			bod[v + 1] = bod[*it];
			pii nex = tree.query(v + 1, bod[v + 1] - 1);
			if ((v + 1) & 1) {
				de(nex.fi);
				que.push(nex.fi);
			}
			else {
				de(pos[nex.se]);
				que.push(nex.se);
			}
		}
		if (u > *it) {
			bod[*it] = u - 1;
			pii nex = tree.query(*it, u - 1 - 1);
			if ((*it) & 1) {
				de(nex.fi);
				que.push(nex.fi);
			}
			else {
				de(nex.se);
				que.push(nex.se);
			}
		}
		if (u + 1 < v) {
			s.insert(u + 1);
			bod[u + 1] = v - 1;
			pii nex = tree.query(u + 1, v - 1 - 1);
			if ((u + 1) & 1) {
				de(nex.fi);
				que.push(nex.fi);
			}
			else {
				de(nex.se);
				que.push(nex.se);
			}
		}
		if (i == 3) break;
	}

	///print
	rep(i, 0, sz(ans)) printf("%d ", ans[i]);




