	int num;
	long long int ret;
	bool is_min;
	long long int Update(int place) {
		if (place >= (int)v.size() / 2) {
			return v[place];
		}
		if (is_min) {
			v[place] = min(Update(place * 2), Update(place * 2 + 1));
			return v[place];
		}
		v[place] = max(Update(place * 2), Update(place * 2 + 1));
		return v[place];
	}
	void RMQ(int a, int b, int place) {
		if (l[place] >= a&&r[place] <= b) {
			if (is_min)ret = min(ret, v[place]);
			else ret = max(ret, v[place]);
			return;
		}
		if (l[place]>b || r[place]<a) return;
		RMQ(a, b, place * 2);
		RMQ(a, b, place * 2 + 1);
		return;
	}
public:
	void Left(int place) {
		if (place >= (int)v.size() / 2) {
			l[place] = place - v.size() / 2;
			return;
		}
		Left(place * 2);
		Left(place * 2 + 1);
		l[place] = l[place * 2];
		return;
	}
	void Right(int place) {
		if (place >= (int)v.size() / 2) {
			r[place] = place - v.size() / 2;
			return;
		}
		Right(place * 2);
		Right(place * 2 + 1);
		r[place] = r[place * 2 + 1];
		return;
	}
	Segment_Tree(int n, bool min) {
		num = 1;
		while (num < n * 2) {
			num *= 2;
		}
		l.resize(num);
		r.resize(num);
		if (min) {
			v.resize(num, LLONG_MAX);
			is_min = true;
		}
		else v.resize(num, LLONG_MIN);
		Left(1);
		Right(1);
	}
	void Insert(int place, long long int num, bool update) {
		place += v.size() / 2;
		v[place] = num;
		if (!update)return;
		place /= 2;
		while (place) {
			if (is_min)v[place] = min(v[place * 2], v[place * 2 + 1]);
			else v[place] = max(v[place * 2], v[place * 2 + 1]);
			place /= 2;
		}
	}
	void TopDown() {
		Update(1);
	}
	long long int RMQ(int a, int b) {
		if (is_min)ret = LLONG_MAX;
		else ret = LLONG_MIN;
		RMQ(a, b, 1);
		return ret;
	}
};


int main() {
	ios::sync_with_stdio(false);
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> num[i];
		num[i] = num[i] * MOD + i;
	}
	Segment_Tree odd((int)N / 2, true);
	Segment_Tree even((int)N / 2, true);
	for (int i = 0; i < N / 2; i++) {
		odd.Insert(i, num[i * 2 + 1] , false);
		even.Insert(i, num[i * 2] , false);
	}
	odd.TopDown();
	even.TopDown();
	M = N / 2;
	list<long long int>ret;
	while (M) {
		long long int o_box = odd.RMQ(0, (int)N / 2 - 1);
		//long long int o_bag = even.RMQ((int)(o_box%MOD) / 2 + 1, min((int)(o_box%MOD) / 2 + 1 + (int)M - 1, (int)N / 2 - 1));
		long long int o_bag = LLONG_MAX;
		long long int e_box = even.RMQ(0, (int)N / 2 - 1);
		//long long int e_bag = odd.RMQ((int)(e_box%MOD) / 2 , min((int)(e_box%MOD) / 2  + (int)M - 1, (int)N / 2 - 1));
		long long int e_bag = LLONG_MAX;
		if (o_bag == LLONG_MAX) {
			ret.push_back(e_box / MOD);
			ret.push_back(e_bag / MOD);

			even.Insert((e_box %MOD) / 2, LLONG_MAX, true);
			odd.Insert((e_bag%MOD) / 2, LLONG_MAX, true);
		}
		else if (e_bag == LLONG_MAX) {
			ret.push_back(o_box / MOD);
			ret.push_back(o_bag / MOD);

			odd.Insert((o_box %MOD) / 2, LLONG_MAX, true);
			even.Insert((o_bag%MOD) / 2, LLONG_MAX, true);
		}
		else if (o_box < e_box) {
			ret.push_back(o_box / MOD);
			ret.push_back(o_bag / MOD);

			odd.Insert((o_box %MOD) / 2, LLONG_MAX, true);
			even.Insert((o_bag%MOD) / 2, LLONG_MAX, true);
		}
		else if (e_box < o_box) {
			ret.push_back(e_box / MOD);
			ret.push_back(e_bag / MOD);

			even.Insert((e_box %MOD) / 2, LLONG_MAX, true);
			odd.Insert((e_bag%MOD) / 2, LLONG_MAX, true);
		}
		M--;
	}
	for (auto i : ret) {
		cout << i << " ";
	}
	cout << endl;
	return 0;
}

