using namespace std;
const int inf = 1001001001;
const ll infl = 1001001001001001001ll;
const int dd[] = {0, 1, 0, -1, 0};

const int MN = 1 << 18;
const int SS = MN << 1;

int seg0[SS], seg1[SS];
int idx[MN];

void update(int* seg, int x, int v) {
  x += MN - 1;
  seg[x] = v;
  while (x > 0) {
    x = (x - 1) / 2;
    seg[x] = min(seg[x + x + 1], seg[x + x + 2]);
  }
}

int query(int* seg, int a, int b, int x=0, int l=0, int r=MN) {
  if (b <= l || r <= a) return inf;
  if (a <= l && r <= b) return seg[x];
  int m = (l + r) / 2;
  return min(query(seg, a, b, x + x + 1, l, m), query(seg, a, b, x + x + 2, m, r));
}

