      update(seg0, i, P[i]);
      update(seg1, i, inf);
    } else {
      update(seg0, i, inf);
      update(seg1, i, P[i]);
    }
  }

  struct Range {
    int l, r;
    int *even, *odd;
    int mini;
    Range(int l, int r, int *even, int *odd) : l(l), r(r), even(even), odd(odd) {
      mini = query(even, l, r);
    }
    bool operator<(const Range& rhs) const {
      return mini > rhs.mini;
    }
    vec<Range> next() {
      vec<Range> res;
      int minj = query(odd, idx[mini] + 1, r);
      cout << mini << " " << minj << " ";
      if (l < idx[mini]) res.pb(l, idx[mini], even, odd);
      if (idx[mini] + 1 < idx[minj]) res.pb(idx[mini] + 1, idx[minj], odd, even);
      if (idx[minj] + 1 < r) res.pb(idx[minj] + 1, r, even, odd);
      return res;
    }
  };

  priority_queue<Range> pq;
  pq.em(0, N, seg0, seg1);
  while (!pq.empty()) {
    auto x = pq.top();
    pq.pop();
    for (auto&& r : x.next()) {
      pq.em(r);
    }
  }
  cout << endl;
}

