struct tournament {
	node t[2 * offset];	
	node merge(node l, node r) {
		return {min(l.mn, r.mn), l.mn < r.mn ? l.pos : r.pos};
	}
	void init(int *arr) {
		for (int i = 0; i < N; i++)
			t[i + offset] = {arr[i], i};
		for (int i = offset - 1; i >= 0; i--)
			t[i] = merge(t[2 * i], t[2 * i + 1]);
	}
	node query(int x, int lo, int hi, int from, int to) {
		if (lo >= to || hi <= from)
			return {N + 1, 0};
		if (lo >= from && hi <= to)
			return t[x];
		int mid = (lo + hi) / 2;
		return merge(query(2 * x, lo, mid, from, to), query(2 * x + 1, mid, hi, from, to));
	}
	int query(int from, int to) {
		return query(1, 0, offset, from, to).pos;
	}
};

