ll solve(ll l,ll r){
  if(r-l<=1)while(1);
  ll x=INF,xidx=-1,y=INF,yidx=-2;
  P p,q;
  if(l%2==0){
    p=seg1.query(l,r);
    if(p.se<=-1||q.se<=-1)while(1);
    q=seg2.query(p.se,r);
  }
  else{
    p=seg2.query(l,r);
    if(p.se<=-1||q.se<=-1)while(1);
    q=seg1.query(p.se,r);
  }
  x=p.fi,xidx=p.se,y=q.fi,yidx=q.se;
  ll idx=ret.size();
  ret.EB(x,y); 
