  if(l<xidx)g[idx].PB(solve(l,xidx));
  if(yidx+1<r)g[idx].PB(solve(yidx+1,r));
  if(xidx+2<yidx)g[idx].PB(solve(xidx+1,yidx));
  return idx;
}
