int nn;
int binary(int k) {
	int lb = -1, ub = nn;
	while (ub - lb > 1) {
		int mid = (ub + lb) / 2;
		if (b[mid].first >= k)ub = mid;
		else lb = mid;
	}
	return b[ub].second;
}
