vector<int> pyon(int l, int r) {
    if(debug) cout << l sp << r ln;
    if(l == r) return vector<int>();
    int a = s[l & 1].query(l, r);
    int b = s[~l & 1].query(pos[a] + 1, r);
    vector<int> x = pyon(l, pos[a]), y = pyon(pos[a] + 1, pos[b]), z = pyon(pos[b] + 1, r);
    int xi = 0, yi = 0, zi = 0;
    vector<int> ans = {a, b}; ans.reserve(2 + x.size() + y.size() + z.size());
    while(1) {
        int x0 = xi < x.size() ? x[xi] : INT_MAX;
        int y0 = yi < y.size() ? y[yi] : INT_MAX;
        int z0 = zi < z.size() ? z[zi] : INT_MAX;
        if(x0 == INT_MAX && y0 == INT_MAX && z0 == INT_MAX) break;
        if(x0 < y0 && x0 < z0) {
            ans.push_back(x0);
            ans.push_back(x[++xi]);
            ++xi;
        } else if(y0 < z0) {
            ans.push_back(y0);
            ans.push_back(y[++yi]);
            ++yi;
        } else {
            ans.push_back(z0);
            ans.push_back(z[++zi]);
            ++zi;
        }
    }
    return ans;
}

