pii RMQ(bool flag,ll left,ll right,ll m,ll N,vector<vector<pii>> &min,vi &A,vector<bool> &F,vector<bool> &F2){
    pii ret=mp(INF,INF);
    if(left/m==right/m){
        REP(i,left,right){
            if((F[i]^F2[i/m])==flag) ret=std::min(ret,mp(A[i],i));
        }
    }
    else{
        rep(i,left,left/m*m+m){
            if((F[i]^F2[i/m])==flag) ret=std::min(ret,mp(A[i],i));
        }
        REP(i,right/m*m,right){
            if((F[i]^F2[i/m])==flag) ret=std::min(ret,mp(A[i],i));
        }
        rep(i,left/m+1,right/m){
            ret=std::min(ret,min[i][(flag^F2[i])]);
        }
    }
    return ret;
}
void update(ll left,ll right,ll m,ll N,vector<vector<pii>> &min,vi &A,vector<bool> &F,vector<bool> &F2){
    min[left/m][0]=min[left/m][1]=min[right/m][0]=min[right/m][1]=mp(INF,INF);
    rep(i,left,std::min({N,left/m*m+m,right+1})) F[i]=!F[i];
    if(left/m!=right/m) rep(i,std::max(left,right/m*m),right+1) F[i]=!F[i];
    A[left]=INF;
    A[right]=INF;
    rep(i,left/m*m,std::min(N,left/m*m+m)) min[i/m][F[i]]=std::min(min[i/m][F[i]],mp(A[i],i));
    rep(i,right/m+m,std::min(N,right/m*m+m)) min[i/m][F[i]]=std::min(min[i/m][F[i]],mp(A[i],i));
    rep(i,left/m+1,right/m) F2[i]=!F2[i];
}
