void build(int v = 1, int tl = 1, int tr = n)
{
      if(tl == tr)
      {
            t[v][tl % 2] = mk(a[tl], tl);
            t[v][(tl % 2) ^ 1] = mk(inf, 0);
      }
      else
      {
            int tm = (tl + tr) >> 1;
            build(v << 1, tl, tm);
            build((v << 1) | 1, tm + 1, tr);
            t[v][0] = min(t[v << 1][0], t[(v << 1) | 1][0]);
            t[v][1] = min(t[v << 1][1], t[(v << 1) | 1][1]);
      }
}

pair <int, int> get(int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
      if(l > tr || tl > r) return mk(inf, 1);
      if(l <= tl && tr <= r) return t[v][type];
      int tm = (tl + tr) >> 1;
      return min(get(l, r, type, v << 1, tl, tm),
                        get(l, r, type, (v << 1) | 1, tm + 1, tr));
}

void dv(int l, int r)
{
      if(l >= r) return ;
      if(l + 1 == r)
      {
            ans.pb(mk(mk(l, r), mk(l, r)));
            return ;
      }
      int aa = get(l, r - 1, l % 2).sc;
      int bb = get(aa + 1, r, (l % 2) ^ 1).sc;
      ans.pb(mk(mk(aa, bb), mk(l, r)));
      dv(l, aa - 1);
      dv(aa + 1, bb - 1);
      dv(bb + 1, r);
}

bool cmp( pair < pair <int, int>, pair <int, int> > aa, pair < pair <int, int>, pair <int, int> > bb)
{
      if(bb.sc.fr < aa.sc.fr || aa.sc.sc < bb.sc.sc) return 0;
      return a[aa.fr.fr] < a[bb.fr.fr];
}

