const int MAXN = 2e5 + 5;
const int LOGN = 19;

int N;
int P[MAXN];

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(P[i]);
    }
}

struct RMQ {
    int a[MAXN];
    int minp[LOGN][MAXN];

    inline int lessp(int i, int j)
    {
        return a[i] < a[j] ? i : j;
    }

    void init()
    {
        for (int i = 1; i <= N; ++i) {
            minp[0][i] = i;
        }
        for (int k = 1; (1 << k) <= N; ++k) {
            for (int i = 1; i + (1 << k) - 1 <= N; ++i) {
                int j = i + (1 << (k - 1));
                minp[k][i] = lessp(minp[k - 1][i], minp[k - 1][j]);
            }
        }
    }

    int query(int l, int r)
    {
        int k = 31 - __builtin_clz(r - l + 1);
        return lessp(minp[k][l], minp[k][r - (1 << k) + 1]);
    }
};

RMQ rmq[2];

struct Atom {
    int l, r;

    Atom() { }
    Atom(int l_, int r_): l(l_), r(r_) { assert((r - l) & 1); }

    Pii getval() const
    {
        int x = rmq[l & 1].query(l, r);
        int y = rmq[r & 1].query(x, r);
        return MP(P[x], P[y]);
    }

    friend bool operator< (const Atom &a, const Atom &b)
    {
        return a.getval() > b.getval();
    }
};

void solve()
{
    static int R[MAXN];

    for (int i = 1; i <= N; ++i) {
        R[P[i]] = i;
    }

    for (int i = 1; i <= N; ++i) {
        rmq[i & 1].a[i] = P[i];
        rmq[!(i & 1)].a[i] = +oo;
    }
    rmq[0].init();
    rmq[1].init();

    vector<int> ans;
    std::priority_queue<Atom> q;

    q.push(Atom(1, N));
    while (!q.empty()) {
        Atom u = q.top();
        Pii t = u.getval();
        q.pop();
        ans.push_back(t.x);
        ans.push_back(t.y);
        int tl = R[t.x], tr = R[t.y];
        if (u.l < tl)
            q.push(Atom(u.l, tl - 1));
        if (tl + 1 < tr)
            q.push(Atom(tl + 1, tr - 1));
        if (tr < u.r)
            q.push(Atom(tr + 1, u.r));
    }

    for (auto x : ans) {
        printf("%d ", x);
    }
    puts("");
}

