void push(int v){
	if(la[v]){
		la[v*2+1] ^= 1;
		la[v*2+2] ^= 1;
	}
	la[v] = 0;
}

pii getValue(int v){
	if(la[v]){
		return mp(t[v].second, t[v].first);
	}else return t[v];
}

void remin(int &a, int b){
	a = min(a, b);
}

void refresh(int v){
	t[v].first = min(getValue(v*2+1).first, getValue(v*2+2).first);
	t[v].second = min(getValue(v*2+1).second, getValue(v*2+2).second);
}

set<int> dp;

void build(int v, int tl, int tr){
	if(tl == tr){
		if(tl & 1) t[v] = mp(INF, p[tl]);
		else t[v] = mp(p[tl], INF);
	}else{
		int tm = (tl+tr)/2;
		build(v*2+1, tl, tm);
		build(v*2+2, tm+1, tr);
		refresh(v);
	}
}

void upd(int v, int tl, int tr, int l, int r){
	if(tl > r || tr < l) return;
	if(l <= tl && tr <= r){
		la[v] ^= 1;
		return;
	}
	push(v);
	int tm = (tl+tr)/2;
	upd(v*2+1, tl, tm, l, r);
	upd(v*2+2, tm+1, tr, l, r);
	refresh(v);
}

pii getMin(int v, int tl, int tr, int l, int r){
	if(tl > r || tr < l) return mp(INF, INF);
	if(l <= tl && tr <= r) return getValue(v);
	push(v);
	int tm = (tl+tr)/2;
	pii r1 = getMin(v*2+1, tl, tm, l, r);
	pii r2 = getMin(v*2+2, tm+1, tr, l, r);
	refresh(v);
	pii ret;
	ret.first = min(r1.first, r2.first);
	ret.second = min(r1.second, r2.second);
	return ret;
}

void rem(int v, int tl, int tr, int p){
	if(tl == tr){
		t[v] = mp(INF, INF);
	}else{
		push(v);
		int tm = (tl+tr)/2;
		if(p <= tm) rem(v*2+1, tl, tm, p);
		else rem(v*2+2, tm+1, tr, p);
		refresh(v);
	}
}

void solve(){
	cin >> n;
	fr(i, 0, n){
		cin >> p[i]; 
		--p[i]; 
		invp[p[i]] = i;
	}
	dp.insert(n);
	build(0, 0, n-1);
	fr(i, 0, n/2){
		int lv = getMin(0, 0, n-1, 0, n-1).first;
		int lp = invp[lv];
		int rb = (*dp.lower_bound(lp));
		int rv = getMin(0, 0, n-1, lp+1, rb-1).second;
		int rp = invp[rv];
		dp.insert(rp);
		dp.insert(lp);
		ans[i*2] = lv;
		ans[i*2+1] = rv;
		upd(0, 0, n-1, lp+1, rp-1);
		rem(0, 0, n-1, lp);
		rem(0, 0, n-1, rp);
	}
	fr(i, 0, n){
		if(i) cout << " ";
		cout << ans[i] + 1; 
	}
}

