vl dfs(int l, int r, bool f){
	if(r-l <= 0) return {};
	if(r-l == 2) return {p[l], p[l+1]};
	ll left = seg[f].query(l,r);
	ll right = seg[(f+1)%2].query(l,r);
	int lp = pos[left];
	int rp = pos[right];
	vvl v(3);
	v[0] = dfs(l,lp,f);
	v[1] = dfs(lp+1,rp,!f);
	v[2] = dfs(rp+1,r,f);
	vl id(3,0);
	vl res;
	res.push_back(left); res.push_back(right);
	while(id[0]+id[1]+id[2] < v[0].size()+v[1].size()+v[2].size()){
		vl mn(3);
		rep(i,3) mn[i] = id[i] == v[i].size() ? inf : v[i][id[i]];
		rep(i,3){
			if(mn[i] == min({mn[0], mn[1], mn[2]})){
				res.push_back(v[i][id[i]]);
				res.push_back(v[i][id[i]+1]);
				id[i] += 2;
				break;
			}
		}
	}
	return res;
}

