struct tree
{
	PII load[2*M];

	void insert(int a, int v)
	{
		a += M;
		load[a] = mp(v, a-M);
		a /= 2;

		while(a>=1)
		{
			load[a] = min(load[2*a], load[2*a+1]);
			a /= 2;
		}
	}

	PII query(int a, int b)
	{
		if(a>b)
			return mp(-1, -1);

		a += M;
		b += M;

		PII res = min(load[a], load[b]);

		while(a<b-1)
		{
			if(a%2==0)
				res = min(res, load[a+1]);

			if(b%2==1)
				res = min(res, load[b-1]);

			a /= 2;
			b /= 2;
		}

		return res;
	}

	tree()
	{
		for(int i = 0; i < 2*M; ++i)
		{
			load[i] = mp(inf, inf);
		}
	}
};

