void divi(int L, int R){
	if(L+1 == R || L > R) return;
	int i, j, k;
	int p1 = 0, p2 = 0;
	p1 = get(!(L&1), (L+1)/2, R/2);
	p2 = get(L&1, (p1+2)/2, (R+1)/2);
	divi(L, p1-1);
	divi(p1+1, p2-1);
	divi(p2+1, R);
	b[L] = a[p1]; b[L+1] = a[p2];
	int i1 = L, i2 = p1+1, i3 = p2+1, l = L+1;
	while(i1 < p1-1 || i2 < p2-1 || i3 < R){
		int np = 0;
		if(i1 < p1-1) np = i1;
		if(i2 < p2-1 && (!np || a[i2] < a[np])) np = i2;
		if(i3 < R && (!np || a[i3] < a[np])) np = i3;
		b[++l] = a[np]; b[++l] = a[np+1];
		if(np == i1) i1 += 2;
		else if(np == i2) i2 += 2;
		else i3 += 2;
	}
	for(i = L; i <= R; i++) a[i] = b[i];
}
