//{{{ Segment Tree
template <class T>
struct segment_tree {
	int n;
	vector<T> x;
	vector<int> id;
	segment_tree(int n_) {
		n=1;
		while(n < n_)n*=2;
		x.assign(n*2,init_val());
		id.assign(n*2,-1);
	}

	T init_val(){
		return INF;
	}
	T f(const T &a, const T &b){
		return min(a,b);
	}
	pair<T,int> range(int a,int b,int i,int l,int r){
		if(r<=a or b<=l)return {init_val(),-1};
		if(a<=l and r<=b)return {x[i],id[i]};
		else{
			int m = (l+r)/2;
			auto pl = range(a,b,i*2+1,l,m), pr = range(a,b,i*2+2,m,r);
			pair<T,int> ret;
			ret.first = f(pl.first,pr.first);
			if(pl.first<pr.first){
				ret.second = pl.second;
			}else{
				ret.second = pr.second;
			}
			return ret;
		}
	}
	pair<T,int> range(int a,int b){
		return range(a,b,0,0,n);
	}
	void set(int a,const T &v,int i,int l,int r){
		if(r-l==1){
			x[i] = v;
			id[i] = l;
		}else{
			int m = (l+r)/2;
			if(a<m)set(a,v,i*2+1,l,m);
			else set(a,v,i*2+2,m,r);
			x[i] = f(x[i*2+1],x[i*2+2]);
			if(x[i*2+1]<x[i*2+2])id[i] = id[i*2+1];
			else id[i] = id[i*2+2];
		}
	}
	void set(int a,const T &v){
		set(a,v,0,0,n);
	}
	void set_all(const vector<T> &v, int i,int l,int r){
		if(r-l==1){
			x[i] = v[l];
			id[i] = l;
		}else{
			int m = (l+r)/2;
			set_all(v,i*2+1,l,m);
			set_all(v,i*2+2,m,r);
			x[i] = f(x[i*2+1],x[i*2+2]);
			if(x[i*2+1]<x[i*2+2])id[i] = id[i*2+1];
			else id[i] = id[i*2+2];
		}
	}
	void set_all(const vector<T> &v){
		set_all(v,0,0,n);
	}
};
