template <class T>
struct sparse {
    int n, logn;
    vector<vector<T>> st;
    function<T(T, T)> func = [&](T a, T b) { return min(a, b); };

    sparse(vector<T> a) {
        n = a.size();
        logn = 32 - __builtin_clz(n);
        st.resize(logn);
        st[0] = a;
        for (int j = 1; j < logn; j++) {
            st[j].resize(n - (1 << j) + 1);
            for (int i = 0; i <= n - (1 << j); i++) {
                st[j][i] = func(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
            }
        }
    }

    T get(int from, int to) const {
        int lg = 32 - __builtin_clz(to - from + 1) - 1;
        return func(st[lg][from], st[lg][to - (1 << lg) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> p(n), rev(n + 1), fr(n + 1);
    vector<vector<int>> s(2, vector<int>(n, 1e9)), ch(n + 1);
    for (int i = 0; i < n; i++) {
        cin >> p[i];
        rev[p[i]] = i;
        s[i & 1][i] = p[i];
    }
    vector<sparse<int>> st = {sparse<int>(s[0]), sparse<int>(s[1])};
    function<int(int, int)> solve = [&](int a, int b) {  // [a, b)
        if (a == b) {
            return -1;
        }
        int dep = a & 1;
        int mn = st[dep].get(a, b - 1);
        int pos = rev[mn];
        int mo = st[dep ^ 1].get(pos + 1, b - 1);
        int pot = rev[mo];
        fr[mn] = mo;
        ch[mn].emplace_back(solve(a, pos));
        ch[mn].emplace_back(solve(pos + 1, pot));
        ch[mn].emplace_back(solve(pot + 1, b));
        return mn;
    };
    int root = solve(0, n);
    debug(root);
    vector<int> q;
    priority_queue<int, vector<int>, greater<int>> pq;
    pq.push(root);
    while (!pq.empty()) {
        int v = pq.top();
        pq.pop();
        q.emplace_back(v);
        for (int i : ch[v]) {
            if (i > 0) pq.push(i);
        }
    }
    for (int i : q) {
        cout << i << " " << fr[i] << " ";
    }
    cout << endl;
    return 0;
}

