pair<int, int> getSp(int l, int r, int type){
	int lvl = gg[r - l + 1];
	return min(sp[type][lvl][l], sp[type][lvl][r - (1 << lvl) + 1]);
}

pair<int, int> tmp[3];

int getVal(int l, int r){
	if (l > r) return INF;
	if (l % 2 == 0){
		return getSp(l, r, 0).x;
	} else {
		return getSp(l, r, 1).x;
	}
}

int sz = 0;
