void rec(int p, int l, int r){
	//cout << "===" << l << ' ' << r << "===" << endl;
	if (l > r) return;
	int now = sz++;
	g[p].pub(now);
	pair<int, int> v, u;
	if (l % 2 == 0){
		v = getSp(l, r, 0);
		u = getSp(v.y + 1, r, 1);
	} else {
		v = getSp(l, r, 1);
		u = getSp(v.y + 1, r, 0);
	}
	//cout << v.x << ' ' << u.x << ' ';
	dd[now] = mp(v.x, u.x);
	rec(now, l, v.y - 1);
	rec(now, v.y + 1, u.y - 1);
	rec(now, u.y + 1, r);
}

