vv<ii> merge(vv<ii>& a,vv<ii>& b){
	vv<ii> ans;
	while(!(a.empty() or b.empty())){
		if(a.front() < b.front()){
			ans.pb(a.front());a.pop_front();
		}else{
			ans.pb(b.front());b.pop_front();
		}
	}
	if(b.empty())swap(a,b);
	if(a.empty())for(auto e: b)ans.pb(e);
	return ans;
}

vv<ii> recurse(int left,int right){
	if(left > right)return vv<ii>();
	// find smallest on left;
	int mn = 0;
	FOR(i,right-left+1){
		if(i%2 == 0){
			if(arr[left + mn] > arr[left+i])mn = i;
		}
	}
	int mn2 = 0;
	FOR(j,right-left+1){
		if(right - j <= left + mn)break;
		if(j%2 == 0){
			if(arr[right-mn2] > arr[right-j])mn2 = j;
		}
	}
	vv<ii> ans;
	ans.pb({arr[left+mn],arr[right-mn2]});
	auto a = recurse(left,left+mn-1);
	auto b = recurse(left+mn+1,right-mn2-1);
	auto c = recurse(right-mn2+1,right);
	b = merge(b,c);
	a = merge(a,b);
	for(auto e: a)
		ans.pb(e);
	return ans;
}

