using P = pair<int, int>;
using PP = pair<P, P>;

const int INF = (1 << 29);

// 最小値を計算するSegment tree
struct SegmentTree {
    const int DEFULT_VAL = INF;

    vector<int> dat;
    int end;

    SegmentTree(vector<int>& d) {
        int n = d.size();
        end = 1;
        while (end < n) end *= 2;

        dat.resize(2 * end - 1, DEFULT_VAL);

        for (int i = 0; i < d.size(); i++) {
            dat[i + end - 1] = d[i];
        }
        for (int i = end - 2; i >= 0; i--) {
            dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    void update(int idx, int a) {
        int id = idx + end - 1;
        dat[id] = a;
        while (id > 0) {
            id = (id - 1) / 2;
            dat[id] = min(dat[id * 2 + 1], dat[id * 2 + 2]);
        }
    }

    int query(int lb, int ub) {
        return query(lb, ub, 0, 0, end);
    }

    int query(int lb, int ub, int id, int node_lb, int node_ub) {
        if (node_ub <= lb || ub <= node_lb) { return DEFULT_VAL; }

        if (lb <= node_lb && node_ub <= ub) { return dat[id]; }
        else {
            int vl = query(lb, ub, id * 2 + 1, node_lb, (node_lb + node_ub) / 2),
                vr = query(lb, ub, id * 2 + 2, (node_lb + node_ub) / 2, node_ub);
            return min(vl, vr);
        }
    }
};

int main() {
    int N;
    cin >> N;

    static vector<int> p[2];
    static int rev[300000];
    p[0].resize(N); p[1].resize(N);

    for (int i = 0; i < N; i++) {
        cin >> p[i % 2][i];
        p[(i + 1) % 2][i] = INF;

        rev[p[i % 2][i]] = i;
    }

    static SegmentTree segtrees[2] = {
        SegmentTree(p[0]),
        SegmentTree(p[1])
    };

    vector<int> ans;
    priority_queue<PP, vector<PP>, greater<PP>> Q;
    auto temp = segtrees[0].query(0, N);
    Q.push({{temp, segtrees[1].query(rev[temp] + 1, N)},
            {0, N}});

    while (!Q.empty()) {
        auto pp = Q.top(); Q.pop();

        int X = pp.first.first;
        int Y = pp.first.second;
        P seg = pp.second;

        ans.push_back(X); ans.push_back(Y);

        auto push = [&](int L, int R) {
            if (R - L < 2) return;
            int a = segtrees[L % 2].query(L, R);
            int b = segtrees[(L + 1) % 2].query(rev[a] + 1, R);
            Q.push({{a, b}, {L, R}});
        };

        // [L, rX), [rX + 1, rY), [rY + 1, R)
        push(seg.first, rev[X]);
        push(rev[X] + 1, rev[Y]);
        push(rev[Y] + 1, seg.second);
    }

    for (int x : ans) {
        cout << x << " ";
    }
    cout << endl;

    return 0;
}

