struct stnode{
    ii even, odd;
    int len;
	void merge(stnode& L, stnode& R){
        if(L.len % 2 == 0){
            even = min(L.even, R.even);
            odd = min(L.odd, R.odd);
        }else{
            even = min(L.even, R.odd);
            odd = min(L.odd, R.even);
        }
        len = L.len+R.len;
    }
	void operator=(ii x){
        len = 1;
        odd = {2e6+6,-1};
        even = x;
    }
};
struct ST{
	vector<stnode> T;
    vi a;
	int N;
	void init(int n, vi &A){
		T.resize(4*n + 4);
		N = n;
        a = A;
	}
	void build(){build(1,0,N);}
	void build(int id, int l, int r){
		if(r - l < 2){
			T[id] = {a[l],l};
			return;
		}
		int M = (l+r)>>1, L=id<<1, R=L|1;
		build(L, l, M); build(R, M, r);
		T[id].merge(T[L],T[R]);
	}

	stnode query(int x, int y){return query(x,y,1,0,N);}
	stnode query(int x, int y, int id, int l, int r){
		if(x == l && y == r)	return T[id];
		int M = (l+r)>>1, L=id<<1, R=L|1;
		if(x>=M)	return query(x,y,R,M,r);
		if(y<=M)	return query(x,y,L,l,M);
		stnode res,ln=query(x, M, L, l, M),rn=query(M, y, R, M, r);
		return res.merge(ln, rn), res;
	}

};

ST st;
struct seg{
    int l, r, bst;
    seg(int _l, int _r){
        l=_l;
        r=_r;
        bst = st.query(l, r+1).even.fst;
    }
    bool operator<(const seg &o) const{
        return bst > o.bst;
    }
};

