void seg_init(int n_, P dat[])
{
    seg_n = 1;
    while (seg_n <= n_)
        seg_n *= 2;

    for (int i = 0; i < 2 * seg_n - 1; i++)
        dat[i] = {INT_MAX, -1};
}

void seg_update(int k, int a, P dat[])
{
    int k_ = k;
    k += seg_n - 1;
    dat[k] = {a, k_};
    while (k > 0)
    {
        k = (k - 1) / 2;
        dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
}

P seg_query(int a, int b, int k, int l, int r, P dat[])
{
    if (r <= a || b <= l)
        return {INT_MAX, -1};

    if (a <= l && r <= b)
        return dat[k];
    else
    {
        P vl = seg_query(a, b, k * 2 + 1, l, (l + r) / 2, dat);
        P vr = seg_query(a, b, k * 2 + 2, (l + r) / 2, r, dat);

        return min(vl, vr);
    }
}

