*/

    res.push_back({l.first, r.first});

    vector<P> lv = solve(f, l.second - 1);
    vector<P> mv = solve(l.second + 1, r.second - 1);
    vector<P> rv = solve(r.second + 1, e);

    SORT(lv);
    SORT(mv);
    SORT(rv);

    int i = 0, j = 0, k = 0;

    while (i < lv.size() || j < mv.size() || k < rv.size())
    {
        if (i < lv.size() && (mv.size() <= j || lv[i] < mv[j]) && (rv.size() <= k || lv[i] < rv[k]))
