	struct node {
		int l2, r2, k;
		inline bool leaf() {
			return l2 + 1 == r2;
		}
		pair< node, node > childs() {
			node hidari(l2, mid(), left()), migi(mid(), r2, right());
			return make_pair(hidari, migi);
		}
		node(int _l2, int _r2, int _k) : l2(_l2), r2(_r2), k(_k) {}
		node() {
		}

	private:
		inline int left() {
			return 2 * k + 1;
		}
		inline int right() {
			return 2 * k + 2;
		}
		inline int mid() {
			return (l2 + r2) / 2;
		}
	};
