		//sotogawa
		if (o.r2 <= l || r <= o.l2)
			return UNITY;
		//uchigawa
		if (l <= o.l2 && o.r2 <= r)
			return A[o.k];
		//sonota
		auto c = o.childs();
		Monoid vl = get(l, r, c.first);
		Monoid vr = get(l, r, c.second);

		return merge(vl, vr);
	}
	Monoid get(int l, int r) {
		node o(0, n, 0);
		return get(l, r, o);
	}
