	int x=table[w][b][L],y=table[w][b][R-(1<<b)];
	return x==-1?y:y==-1?x:A[x]<A[y]?x:y;
}
int dfs(int L,int R)
{
	int mid=query(L,R,L%2?2:1),mmid=query(mid+1,R,mid%2?1:2),id=ans.size();
	ans.push_back(make_pair(-A[mid],-A[mmid]));
