#include <bits/stdc++.h>
using namespace std;

#define N 200001
#define INF 2e9
int maxi[N*4],lazy[N*4];

int seg[N*4][2];
int pen[N],in[N],ind[N];
void init(int pos,int l,int r) {
    lazy[pos] = -1;
    if(l==r) {
        seg[pos][0] = seg[pos][1] = INF;
        int bit = l&1;
        seg[pos][bit] = in[l];
        if(bit&1) {
            maxi[pos] = in[l];
        } else {
            maxi[pos] = INF;
        }
        return;
    }
    int mid = (l+r)/2;
    init(pos*2,l,mid);
    init(pos*2+1,mid+1,r);
    seg[pos][0] = min(seg[pos*2][0],seg[pos*2+1][0]);
    seg[pos][1] = min(seg[pos*2][1],seg[pos*2+1][1]);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
void push(int pos,int l,int r) {
    if(lazy[pos]!=-1) {
        maxi[pos] = seg[pos][lazy[pos]];
        if(l!=r) {
            lazy[pos*2] = lazy[pos*2+1] = lazy[pos];
        }
        lazy[pos] = -1;
    }
}
void updateE(int pos,int l,int r,int ind,int v) {
    push(pos,l,r);
    if(l==r) {
        maxi[pos] = v;
        seg[pos][0] = seg[pos][1] = v;
        return;
    }
    int mid = (l+r)/2;
    if(ind<=mid) {
        updateE(pos*2,l,mid,ind,v);
    } else {
        updateE(pos*2+1,mid+1,r,ind,v);
    }

    seg[pos][0] = min(seg[pos*2][0],seg[pos*2+1][0]);
    seg[pos][1] = min(seg[pos*2][1],seg[pos*2+1][1]);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
void update(int pos,int l,int r,int ql,int qr,int v) {
    push(pos,l,r);
    if(r<ql || qr<l) {
        return;
    }
    if(ql<=l && r<=qr) {
        lazy[pos] = v;
        push(pos,l,r);
        return;
    }
    int mid = (l+r)/2;
    update(pos*2,l,mid,ql,qr,v);
    update(pos*2+1,mid+1,r,ql,qr,v);
    maxi[pos] = min(maxi[pos*2],maxi[pos*2+1]);
}
int getMaxi(int pos,int l,int r,int ql,int qr,int bit) {
    if(r<ql || qr<l) {
        return INF;
    }
    if(ql<=l && r<=qr) {
        return seg[pos][bit];
    }
    int mid = (l+r)/2;
    return min(getMaxi(pos*2,l,mid,ql,qr,bit),getMaxi(pos*2+1,mid+1,r,ql,qr,bit));
}
void update(int ind,int v) {
    while(ind<N) {
        pen[ind] += v;
        ind += ind&(-ind);
    }
}
int query(int ind) {
    int ret = 0;
    while(ind>0) {
        ret += pen[ind];
        ind = ind&(ind-1);
    }
    return ret;
}
int ret[N];
void solve() {
    //input
    int n;scanf("%d",&n);
    for(int i=1;i<=n;++i) {
        scanf("%d",&in[i]);
        ind[in[i]] = i;
    }
    //pre cal
    init(1,1,n);
    int pos = 0;
    //solve
    while(pos<n) {
        int x = maxi[1];
        int index = ind[x];
        int q = query(index);
        int y = 0,cur = 0;
        for(int i = 20;i>=0;--i) {
            int ny = y + (1<<i);
            if(ny<=n && cur + pen[ny] <=q) {
                y = ny;
                cur += pen[ny];
            }
        }
        y = getMaxi(1,1,n,index,y,(index&1)^1);
        y = ind[y];
        update(index,1);
        update(y,1);
        x = index;
        updateE(1,1,n,x,INF);
        updateE(1,1,n,y,INF);
        if(x+1<=y-1) {
            update(1,1,n,x+1,y-1,q);
        }
        ret[pos++] = in[x];
        ret[pos++] = in[y];
    }
    //output
    for(int i=0;i<n;++i) {
       printf("%d ",ret[i]);
    }
    putchar('\n');
}
int main() {
    solve();
    return 0;
}

