class Segment{
    public :
        P1 dat[400005];
        int n;
        void init(int n_){
            n=1;
            while(n<n_)n*=2;
            for(int i=0;i<2*n-1;++i)dat[i]=P1(INF,INF);
        }

        P1 Min(P1 a,P1 b){
            if(a.first<b.first)return a;
            else return b;
        }

        void update(int k,P1 a){
            k+=n-1;
            dat[k]=a;
            while(k>0){
                k=(k-1)/2;
                dat[k]=Min(dat[k*2+1],dat[k*2+2]);
            }
        }

        P1 query(int a,int b,int k,int l,int r){
            if(a<=l&&r<=b)return dat[k];
            if(r<=a||b<=l)return P1(INF,INF);
            else {
                P1 vl=query(a,b,k*2+1,l,(l+r)/2);
                P1 vr=query(a,b,k*2+2,(l+r)/2,r);
                return Min(vl,vr);
            }
        }
};

int N;
int Index[200005];
vector<int> p,q;
vector<P1> interval;
priority_queue<P2,vector<P2>,greater<P2> > minInterval;
Segment seg[2];

void divideInterval(P1 id,int i,int j){
    P1 tmp = id;
    minInterval.push(P2(seg[tmp.first%2].query(tmp.first,i,0,0,seg[0].n).first,P1(tmp.first,i)));
    minInterval.push(P2(seg[(i+1)%2].query(i+1,j,0,0,seg[0].n).first,P1(i+1,j)));
    minInterval.push(P2(seg[(j+1)%2].query(j+1,tmp.second,0,0,seg[0].n).first,P1(j+1,tmp.second)));
}

