        seg[i%2].update(i,P1(x,i));
    }
    minInterval.push(P2(seg[0].query(0,N,0,0,seg[0].n).first,P1(0,N)));
    for(int cnt=0;cnt<N/2;++cnt){
        P2 nextInterval = minInterval.top();
        int l = nextInterval.second.first,r = nextInterval.second.second;
        minInterval.pop();
        P1 i,j;
        //cout<<l<<" "<<r<<endl;
        i = seg[l%2].query(l,r,0,0,seg[0].n);
        j = seg[!(l%2)].query(i.second+1,r,0,0,seg[1].n);
        q.PB(i.first);
        q.PB(j.first);
