void build(int l,int r,int now,int o) {
	if (l==r) {
		if (o) {
			if (l%2==1) tr[o][now]=a[l];else tr[o][now]=1<<30; 
		}else {
			if (l%2==0) tr[o][now]=a[l];else tr[o][now]=1<<30;

		}
		return;
	}
	int mid=(l+r)>>1;
	build(l,mid,now*2,o);
	build(mid+1,r,now*2+1,o);
	tr[o][now]=min(tr[o][now*2],tr[o][now*2+1]);
}

void ask(int l,int r,int now,int o) {
	if (ll<=l && rr>=r) {
		num=min(tr[o][now],num); 
		return;
	}
	int mid=(l+r)>>1;
	if (ll<=mid) ask(l,mid,now*2,o);
	if (rr>mid) ask(mid+1,r,now*2+1,o);
}


void work(int l,int r,int o) {
	ll=l;rr=r;num=1<<20;
	ask(1,n,1,o);
}

