bool comp(T p, T q){
  if(p.a <= q.a && p.b >= q.b)  return false;
  else if(p.a >= q.a && p.b <= q.b) return true;
  else{
    if(p.c < q.c) return false;
    else return true;
  }
}

priority_queue<T, vector<T>, decltype(&comp)> pq(&comp);

void init(int n_, int* da){
  n = 1;
  while(n < n_) n *= 2;

  for(int i = 0; i < 2*n-1; i++){
    da[i] = MA;
  }
}

//k番目をaに変更
void update(int k, int a, int* da){
  k += n-1;
  da[k] = a;
  while(k > 0){
    k = (k-1)/2;
    da[k] = min(da[k*2+1], da[k*2+2]);
  }
}

int query(int a, int b, int k, int l, int r, int* da){
  if(r <= a || b <= l) {
    //cout << 40 << endl;
    return MA;
  }
  if(a <= l && r <= b){
    //cout << 43 << " " << dat[k] << endl;
    return da[k];
  }
  else{
    int vl = query(a, b, k*2+1, l, (l+r)/2, da);
    int vr = query(a, b, k*2+2, (l+r)/2, r, da);
    //cout << "vl vr" << vl << " " << vr << endl;
    return min(vl, vr);
  }
}

void deal(int i, int s, int e){
  if(e <= s)  return ;

  //cout << 58 << endl;
  //cout << s/2 << " " << e/2 << endl;
  int m1 = query(s/2, e/2, 0, 0, n, dat[i]);
  if(m1 == MA)  return;
  //cout << 53 << endl; //cout << m1 << endl;
  int m2 = query((q[m1]+i)/2, (e+i)/2, 0, 0, n, dat[1-i]);
  if(m2 == MA)  return;
  //cout << 54 << " " << m2 << endl;
  pq.push(T(s, e, m1, m2));
  //cout << 66 << endl;
  //cout << q[m1] << " " << q[m2] << endl;
  deal(i, s, q[m1]);
  deal(1-i, q[m1]+1, q[m2]);
  deal(i, q[m2]+1, e);
}

