		p[++head].x=b[ln];
		p[head].y=c[maxpla];
		p[head].fa=lastnode;
		solve((l<<1)-1,(ln<<1)-1,lastnode);
		solve((ln<<1)+1,(maxpla<<1)-2,head);
		solve((maxpla<<1),(r<<1),lastnode);
	}
	else
	{
		l>>=1;
		r=(r+1)>>1;
		getmax2(1,l,r,1,n>>1);
		int ln=maxpla;
		getmax1(1,ln+1,r,1,n>>1);
		p[++head].x=c[ln];
		p[head].y=c[maxpla];
		p[head].fa=lastnode;
		add(lastnode,head);
		solve((l<<1),(ln<<1)-2,lastnode);
		solve((ln<<1),(maxpla<<1)-1,head);
		solve((maxpla<<1)+1,(r<<1)-1,lastnode);
	}
}
