	if(r-l<=2) return l;
	int t = 0;
	while(l+(2<<(t+1))<=r) t++;
	int res = b[l][t];
	int res2 = query(l+(2<<t), r);
	return a[res]<a[res2]?res:res2;
}

vector<int> solve(){
	priority_queue<PP,vector<PP>,function<bool(PP,PP)>> q([](const PP &p1, const PP &p2){ return a[p1.fst]>a[p2.fst];});
	q.push(PP(query(0, n), P(0, n)));
	vector<int> res; res.reserve(n);
	while(!q.empty()){
		PP p = q.top(); q.pop();
		int x = p.fst, l = p.snd.fst, r = p.snd.snd;
		res.push_back(x);
		int y = query(x+1, r);
