		if(l<x){
			q.push(PP(query(l, x), P(l, x)));
		}
		if(x+1<y){
			q.push(PP(query(x+1, y), P(x+1, y)));
		}
		if(y+1<r){
			q.push(PP(query(y+1, r), P(y+1, r)));
		}
	}
	return res;
}

