map<P, vector<P> > graph;
map<P, P> val;
void dfs(int l, int r) {
  if ( r - l <= 1 ) return;
  if ( l%2 ) {
    P p = odd.query(l, r);
    P q = evn.query(p.second+1, r);
    int ll = p.second, rr = q.second;
    graph[P(l, r)].push_back(P(l, ll));
    graph[P(l, r)].push_back(P(ll+1, rr));
    graph[P(l, r)].push_back(P(rr+1, r));
    val[P(l, r)] = P(p.first, q.first);
    dfs(l, ll);
    dfs(ll+1, rr);
    dfs(rr+1, r);    
  } else {
    P p = evn.query(l, r);
    P q = odd.query(p.second+1, r);
    int ll = p.second, rr = q.second;
    graph[P(l, r)].push_back(P(l, ll));
    graph[P(l, r)].push_back(P(ll+1, rr));
    graph[P(l, r)].push_back(P(rr+1, r));
    val[P(l, r)] = P(p.first, q.first);
    dfs(l, ll);
    dfs(ll+1, rr);
    dfs(rr+1, r);    
  }
}

