template< typename T >
struct SparseTable {
  vector< vector< T > > st;
  vector< int > lookup;

  SparseTable(const vector< T > &v) {
    int b = 0;
    while((1 << b) <= v.size()) ++b;
    st.assign(b, vector< T >(1 << b));
    for(int i = 0; i < v.size(); i++) {
      st[0][i] = v[i];
    }
    for(int i = 1; i < b; i++) {
      for(int j = 0; j + (1 << i) <= (1 << b); j++) {
        st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
      }
    }
    lookup.resize(v.size() + 1);
    for(int i = 2; i < lookup.size(); i++) {
      lookup[i] = lookup[i >> 1] + 1;
    }
  }

  inline T query(int l, int r) {
    int b = lookup[r - l];
    return min(st[b][l], st[b][r - (1 << b)]);
  }
};

set<pair<int,P>> st;

void f(int l,int r,int count,bool c,SparseTable<P> &st1,SparseTable<P> &st2){
    if(r<=l) return;
    if(c==0){
        P ll = st1.query(l,r);
        P rr = st2.query(l,r);
        int li = ll.second, ri = rr.second;
        st.insert(make_pair(count,make_pair(ll.first,rr.first)));
        f(l,li,count+1,c,st1,st2);
        f(li+1,ri,count+1,c^1,st1,st2);
        f(ri+1,r,count+1,c,st1,st2);
    }
    else{
        P ll = st2.query(l,r);
        P rr = st1.query(l,r);
        int li = ll.second, ri = rr.second;
        st.insert(make_pair(count,make_pair(ll.first,rr.first)));
        f(l,li,count+1,c,st1,st2);
        f(li+1,ri,count+1,c^1,st1,st2);
        f(ri+1,r,count+1,c,st1,st2);
    }
    return;
}

