using namespace std;

int a[200005];
int where[200005];
int n;
vector< pair<int, long long> > v;

int solve(int lo, int hi, int find, int level) {
    int x = -1;
    int y = -1;
    if (lo + 2 == hi) {
        if (a[lo] < a[lo + 1]) {
            x = lo;
            y = lo + 1;
        }
        else {
            x = lo + 1;
            y = lo;
        }
    }
    else if (hi - lo > n - 2 * (int)v.size()) {
        for (int i = find; ; ++i) {
            if (lo <= where[i] && where[i] < hi) {
                if (x == -1)
                    x = where[i];
                else if ((x - where[i]) & 1) {
                    y = where[i];
                    break;
                }
            }
        }
    }
    else {
        for (int i = lo; i < hi; ++i)
            if (x == -1 || a[x] > a[i])
                x = i;
        for (int i = x - 1; i >= lo; i -= 2)
            if (y == -1 || a[y] > a[i])
               y = i;
        for (int i = x + 1; i < hi; i += 2)
            if (y == -1 || a[y] > a[i])
               y = i;
    }
    if (a[x] == find) {
        ++find;
        if (a[y] == find)
            ++find;
    }
    if (x > y) swap(x, y);
    v.push_back(make_pair(level, (long long)a[x] * (n + 1) + a[y]));
    if (lo + 1 < x)
        find = solve(lo, x, find, level + 1);
    if (x + 2 < y)
        find = solve(x + 1, y, find, level + 1);
    if (y + 2 < hi)
        find = solve(y + 1, hi, find, level + 1);
    return find;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", a + i);
        where[a[i]] = i;
    }
    solve(0, n, 1, 0);
    sort(v.begin(), v.end());
    for (int i = 0; i < n / 2; ++i)
        printf("%lld %lld ", v[i].second / (n + 1), v[i].second % (n + 1));
    printf("\n");
}

