#include <bits/stdc++.h>
using namespace std;
#define lson l, m, rt << 1
#define rson m + 1, r, rt << 1 | 1
const int MAX_N = 2e5 + 5;
const int INF = 1e9 + 7;
int pos[MAX_N], n;
typedef pair<int, int> pii;
struct Segment_Tree {
    int seg[MAX_N << 2];
    void push_up(int rt) {
        seg[rt] = min(seg[rt << 1], seg[rt << 1 | 1]);
    }
    void Build(int l, int r, int rt) {
        if (l == r) {
            seg[rt] = INF;
            return;
        }
        int m = (l + r) / 2;
        Build(lson);
        Build(rson);
        push_up(rt);
    }
    void Update(int pos, int c, int l, int r, int rt) {
        if (l == r) {
            seg[rt] = c;
            return;
        }
        int m = (l + r) / 2;
        if (pos <= m) Update(pos, c, lson);
        else Update(pos, c, rson);
        push_up(rt);
    }
    int Query(int L, int R, int l, int r, int rt) {
        if (L <= l && r <= R) return seg[rt];
        int m = (l + r) / 2, res = INF;
        if (L <= m) res = min(res, Query(L, R, lson));
        if (R > m) res = min(res, Query(L, R, rson));
        return res;
    }
} ST[2];
struct cmp {
    bool operator () (const pii &x, const pii &y) const {
        return ST[x.first % 2].Query(x.first, x.second, 1, n, 1) > ST[y.first % 2].Query(y.first, y.second, 1, n, 1);
    }

};
priority_queue<pii, vector<pii>, cmp> que;
int main() {
    int x, l, r, p, q;
    scanf("%d", &n);
    ST[0].Build(1, n, 1);
    ST[1].Build(1, n, 1);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &x);
        pos[x] = i;
        ST[i % 2].Update(i, x, 1, n, 1);
    }
    que.push(make_pair(1, n));
    while (!que.empty()) {
        l = que.top().first;
        r = que.top().second;
        que.pop();
        p = ST[l % 2].Query(l, r, 1, n, 1);
        q = ST[(l + 1) % 2].Query(pos[p], r, 1, n, 1);
        //printf("%d %d %d %d\n", p, q, pos[p], pos[q]);
        if (l < pos[p] - 1) que.push(make_pair(l, pos[p] - 1));
        if (pos[p] + 1 < pos[q] - 1) que.push(make_pair(pos[p] + 1, pos[q] - 1));
        if (pos[q] + 1 < r) que.push(make_pair(pos[q] + 1, r));
        printf("%d %d%c", p, q, que.empty() ? '\n' : ' ');
    }
}

