using namespace std;
typedef pair<int, int> pa;
constexpr int INF = 1145141919;

struct SparseTable {
    vector<vector<pa>> st;
    vector<int> lookup;

    void init(vector<int> &v) {
        int b = 0;
        while ((1 << b) <= v.size()) ++b;
        st.assign(b, vector<pa>(1 << b));
        for (int i = 0; i < v.size(); i++) st[0][i] = {v[i], i};
        for (int i = 1; i < b; i++) {
            for (int j = 0; j + (1 << i) <= (1 << b); j++) {
                st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
            }
        }

        lookup.resize(v.size() + 1);
        for (int i = 2; i < lookup.size(); i++) {
            lookup[i] = lookup[i >> 1] + 1;
        }
    }

    inline pa rmq(int l, int r) {
        int b = lookup[r - l];
        return min(st[b][l], st[b][r - (1 << b)]);
    }
};

int n;
vector<int> p;
vector<SparseTable> tables;
vector<vector<int>> ret;

void solve(int x, int y) {
    auto fi = tables[x % 2].rmq(x, y);
    auto se = tables[(x + 1) % 2].rmq(fi.second + 1, y);
    pa minValue = {fi.first, se.first}, minIndex{fi.second, se.second};

    int here = ret.size();
    ret.push_back({minValue.first, minValue.second});
    if (x != minIndex.first) {
        ret[here].push_back(ret.size());
        solve(x, minIndex.first);
    }
    if (minIndex.first + 1 != minIndex.second) {
        ret[here].push_back(ret.size());
        solve(minIndex.first + 1, minIndex.second);
    }
    if (minIndex.second + 1 != y) {
        ret[here].push_back(ret.size());
        solve(minIndex.second + 1, y);
    }
}

