	{
		return;
	}
	cout << pq.top().first.first.first << " " << pq.top().first.second << " ";
	int s = pq.top().second.first, e = pq.top().second.second, se = pq.top().first.first.second, es = pq.top().first.second;
	pq.pop();
	if (solve2(s, se))
	{
		pq.push(MP(MP(*mia, (*mib).second), MP(s, se)));
	}
	if (solve2(se + 1, es))
	{
		pq.push(MP(MP(*mia, (*mib).second), MP(se + 1, es)));
	}
	if (solve2(es + 1, e))
	{
		pq.push(MP(MP(*mia, (*mib).second), MP(es + 1, e)));
	}
	solve();
}

