// Segment tree
struct F { // min func
  typedef P TT;
  vp d; int c;
  F(P d0=P(INF,-1), P d1=P(INF,-1), int c=0):d({d0,d1}),c(c) {}
  F operator+(const F& f) const {
    return F(min(d[0],f.d[0]), min(d[1],f.d[1]), c+f.c);
  }
};
struct seg {
  vector<F> d; int n;
  seg(){}
  seg(int mx) {
    n = 1; while (n < mx) n <<= 1;
    d = vector<F>(n<<1);
  }
  void upd(int i) { d[i] = d[i<<1]+d[i<<1|1];}
  F& operator[](int i) { return d[n+i];}
  void init() { for(int i=n-1;i;--i) upd(i);}
  void set(int i, F f) {
    i+=n; d[i] = f;
    for (i>>=1;i;i>>=1) upd(i);
  }
  F get(int l, int r) {
    l += n; r += n;
    F lf, rf;
    while (l < r) {
      if (l&1) lf = lf + d[l++];
      if (r&1) rf = d[--r] + rf;
      l >>= 1; r >>= 1;
    }
    return lf + rf;
  }
};
