struct List {
  int h, t;
  vi f, p;
  List():h(-1),t(-1) {}
  int add(int i, int j=-1) {
    if (!~j) {
      j = sz(f);
      f.pb(-1); p.pb(-1);
    }
    if (!~i) { h = t = j; return j;}
    p[j] = i;
    if (~f[i]) p[f[i]] = j; else t = j;
    f[j] = f[i];
    f[i] = j;
    return j;
  }
  void del(int i) {
    if (~f[i]) p[f[i]] = -1; else t = p[i];
    if (~p[i]) f[p[i]] = -1; else h = f[i];
    f[i] = p[i] = -1;
  }
};
