#include <bits/stdc++.h>

using namespace std;
const int inf = 1e9;

vector<vector<int>> T(2, vector<int> (2 * 1000 * 1000, inf));

vector<pair<int, int>> v[250000];
vector<int> p, poz;
int n;

void update(vector<int> &T, int node, int lf, int rt, int poz, int val) {
    if(lf == rt) {
        T[node] = min(T[node], val);
        return;
    }

    int mid = (lf + rt) / 2;

    if(poz <= mid)
        update(T, 2 * node, lf, mid, poz, val);
    else
        update(T, 2 * node + 1, mid + 1, rt, poz, val);

    T[node] = min(T[2 * node], T[2 * node + 1]);
}

int query(vector<int> &T, int node, int lf, int rt, int st, int dr) {
    if(lf >= st and rt <= dr) {
        return T[node];
    }

    int mid = (lf + rt) / 2;
    int ans = 1e8;

    if(st <= mid)
        ans = min(ans, query(T, 2 * node, lf, mid, st, dr));
    if(dr > mid)
        ans = min(ans, query(T, 2 * node + 1, mid + 1, rt, st, dr));

    return ans;
}

void solve(int lf, int rt, int parity, int depth) {
    //cerr << lf << " " << rt << " " << parity << " " << depth << "\n";
    int first = poz[query(T[parity], 1, 0, n - 1, lf, rt)];
    //cerr << first << "\n";
    int second = poz[query(T[1 - parity], 1, 0, n - 1, first + 1, rt)];
    //cerr << second << "\n";

    v[depth].push_back(make_pair(p[first], p[second]));

    if(first > lf) {
        solve(lf, first - 1, parity, depth + 1);
    }

    if(second < rt) {
        solve(second + 1, rt, parity, depth + 1);
    }

    if(second > first + 1) {
        solve(first + 1, second - 1, 1 - parity, depth + 1);
    }
}

