    for(int i = 0; i < n; ++i) {
        cin >> p[i];
        poz[p[i]] = i;
        update(T[i % 2], 1, 0, n - 1, i, p[i]);
    }

    solve(0, n - 1, 0, 0); 

    vector<int> ans;

    for(int i = 0; i < n; ++i) {
        sort(v[i].begin(), v[i].end());
        for(auto temp : v[i]) {
            ans.push_back(temp.first);
            ans.push_back(temp.second);
        }
    }

    for(auto val : ans)
        cout << val << " ";
    cout << "\n";
}

