        if (i & 1)
            odd[i >> 1] = t;
        else
            even[i >> 1] = t;
    }
    build(0, even, 0, (n >> 1) - 1, evenTree);
    build(0, odd, 0, (n >> 1) - 1, oddTree);
    node nd;
    nd.l = 0, nd.r = n - 1, nd.m = evenTree[0];
    pq.push(nd);
    while (!pq.empty()) {
        node nd = pq.top();
        pq.pop();
        vec.push_back(nd.m);
        int pair = nd.l % 2 == 0 ? query(oddTree, 0, 0, (n >> 1) - 1, pos[nd.m] >> 1, nd.r >> 1) : query(evenTree, 0, 0, (n >> 1) - 1, (pos[nd.m] >> 1) + 1, nd.r >> 1);
        vec.push_back(pair);
        if (nd.l < pos[nd.m])
            qPush(nd.l, pos[nd.m] - 1);
        if (pos[pair] - pos[nd.m] > 1)
            qPush(pos[nd.m] + 1, pos[pair] - 1);
        if (nd.r > pos[pair])
            qPush(pos[pair] + 1, pos[nd.r]);
    }
    for (i = 0; i < n; ++i)
        cout << vec[i] << ' ';
    cout << endl;
    return 0;
}

