using std::swap;

const int N=2e5+10,Node=N<<2,Inf=1e9+10;

int n,p[N],pos[N];

struct SegmentTree{
	#define ls z<<1
	#define rs z<<1|1
	int root,mn[Node][2],cnt,rev[Node];

	void Update(int z) {
		mn[z][0]=min(mn[ls][0],mn[rs][0]);
		mn[z][1]=min(mn[ls][1],mn[rs][1]);
	}

	void Build(int z,int l,int r) {
		if (l==r) {
			int op=l&1;
			mn[z][op]=p[l];
			mn[z][op^1]=Inf;
			return ;
		}
		int mid=(l+r)>>1;
		Build(ls,l,mid);
		Build(rs,mid+1,r);
		Update(z);
	}

	void setrev(int z) {
		rev[z]^=1;
		swap(mn[z][0],mn[z][1]);
	}

	void downrev(int z) {
		if (!rev[z]) return ;
		setrev(ls); setrev(rs);
		rev[z]=0;
	}

	void Find(int z,int l,int r,int q) {
		if (l==r) {
			mn[z][0]=mn[z][1]=Inf;
			return ;
		}
		downrev(z);
		int mid=(l+r)>>1;
		if (q<=mid) Find(ls,l,mid,q);
		else Find(rs,mid+1,r,q);
		Update(z);
	}

	int findMin(int z,int l,int r,int ql,int qr) {
		if (ql<=l && r<=qr) {
			return mn[z][0];
		}
		downrev(z);
		int mid=(l+r)>>1,ret=Inf;
		if (ql<=mid) ret=min(ret,findMin(ls,l,mid,ql,qr));
		if (qr>mid)  ret=min(ret,findMin(rs,mid+1,r,ql,qr));
		return ret;
	}

	void reverse(int z,int l,int r,int ql,int qr) {
		if (ql<=l && r<=qr) {
			setrev(z);
			return ;
		}
		downrev(z);
		int mid=(l+r)>>1;
		if (ql<=mid) reverse(ls,l,mid,ql,qr);
		if (qr>mid) reverse(rs,mid+1,r,ql,qr);
		Update(z);
	}

}St;

set<int>q;

void Init() {
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%d",&p[i]),pos[p[i]]=i;
}

void Solve() {
	St.root=1;
	q.insert(n+1);
	St.Build(St.root,1,n);
	for (int i=1;i<=n;i+=2) {
		if (i!=1) printf(" ");
		int v1=St.mn[St.root][1],v2;
		St.Find(St.root,1,n,pos[v1]); int pos2=*(q.lower_bound(pos[v1]));
		v2=St.findMin(St.root,1,n,pos[v1]+1,pos2-1); St.Find(St.root,1,n,pos[v2]);
		q.insert(pos[v1]); q.insert(pos[v2]);
		if (pos[v2]-pos[v1]>1) St.reverse(St.root,1,n,pos[v1]+1,pos[v2]-1);
		printf("%d %d",v1,v2);
	}
	putchar('\n');
}

int main() {
	Init();
	Solve();
	return 0;
}

