template <class T>
struct sparse {
    int n, logn;
    vector<vector<T>> st;
    function<T(T, T)> func = [&](T a, T b) { return min(a, b); };

    sparse(vector<T> a) {
        n = a.size();
        logn = 32 - __builtin_clz(n);
        st.resize(logn);
        st[0] = a;
        for (int j = 1; j < logn; j++) {
            st[j].resize(n - (1 << j) + 1);
            for (int i = 0; i <= n - (1 << j); i++) {
                st[j][i] = func(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);
            }
        }
    }

    T get(int from, int to) const {
        int lg = 32 - __builtin_clz(to - from + 1) - 1;
        return func(st[lg][from], st[lg][to - (1 << lg) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> p(n), rev(n + 1);
    vector<vector<int>> s(2, vector<int>(n, 1e9));
    for (int i = 0; i < n; i++) {
        cin >> p[i];
        rev[p[i]] = i;
        s[i & 1][i] = p[i];
    }
    vector<sparse<int>> st = {sparse<int>(s[0]), sparse<int>(s[1])};
    function<vector<int>(int, int)> solve = [&](int a, int b) {  // [a, b)
        vector<int> res;
        if (a == b) {
            return res;
        }
        int dep = a & 1;
        int mn = st[dep].get(a, b - 1);
        int pos = rev[mn];
        int mo = st[dep ^ 1].get(pos + 1, b - 1);
        int pot = rev[mo];
        res = {mn, mo};
        vector<vector<int>> u;
        u.emplace_back(solve(a, pos));
        u.emplace_back(solve(pos + 1, pot));
        u.emplace_back(solve(pot + 1, b));
        vector<int> it(3);
        while (true) {
            int t = 1e9;
            for (int i = 0; i < 3; i++) {
                if (it[i] < u[i].size()) t = min(t, u[i][it[i]]);
            }
            if (t == 1e9) {
                break;
            }
            for (int i = 0; i < 3; i++) {
                if (it[i] < u[i].size() && u[i][it[i]] == t) {
                    res.emplace_back(u[i][it[i]]);
                    res.emplace_back(u[i][it[i] + 1]);
                    it[i] += 2;
                    break;
                }
            }
        }
        return res;
    };
    vector<int> q = solve(0, n);
    for (int i : q) {
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

