const int MAX_N = 100005;

template<class V> class segtree {
private:
    int n,sz;
    vector<V> node, lazy;
    vector<int> node_id;
    vector<bool> lazyFlag;

public:
    segtree(vector<V> v) {
        sz = (int)v.size();
        n = 1;
        while(n < sz){
            n *= 2;
        }
        node.resize(2*n-1);
        node_id.resize(2*n-1);
        lazy.resize(2*n-1, 0);
        lazyFlag.resize(2*n-1,false);
        rep(i,sz){
            node[i+n-1] = v[i];
            node_id[i+n-1] = i;
        }
        for(int i=n-2; i>=0; i--){
            if(node[i*2+1] < node[i*2+2]){
                node[i] = node[i*2+1];
                node_id[i] = node_id[i*2+1];
            }else{
                node[i] = node[i*2+2];
                node_id[i] = node_id[i*2+2];
            }
        }
    }
    void eval(int k, int l, int r) {
        if(lazyFlag[k]) {
            node[k] = lazy[k];
            if(r - l > 1) {
                lazy[k*2+1] = lazy[k*2+2] = lazy[k];
                lazyFlag[k*2+1] = lazyFlag[k*2+2] = true;
            }
            lazyFlag[k] = false;
        }
    }
    void range(int a, int b, V x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a){
            return;
        }
        if(a <= l && r <= b) {
            lazy[k] = x;
            lazyFlag[k] = true;
            eval(k, l, r);
        }
        else {
            range(a, b, x, 2*k+1, l, (l+r)/2);
            range(a, b, x, 2*k+2, (l+r)/2, r);
            if(node[k*2+1] < node[k*2+2]){
                node[k] = node[k*2+1];
                node_id[k] = node_id[k*2+1];
            }else{
                node[k] = node[k*2+2];
                node_id[k] = node_id[k*2+2];
            }
        }
    }
    pair<V,int> query(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a){
            return pair<V,int>(INT_MAX,-1);
        }
        if(a <= l && r <= b){
            return pair<V,int>(node[k],node_id[k]);
        }
        pair<V,int> vl = query(a, b, 2*k+1, l, (l+r)/2);
        pair<V,int> vr = query(a, b, 2*k+2, (l+r)/2, r);
        return min(vl,vr);
    }
    void print()
    {
        rep(i,sz){
            pair<V,int> p;
            p = query(i,i+1);
            cout << "st[" << i << "]: " << p.fi << " " << p.se << endl;
        }
    }
};

