        if(s.l == s.r){
            continue;
        }
        if(s.l % 2 == 0){
            P q = st2.query(s.pl+1,s.r);
            res.pb(s.mn),res.pb(q.fi);
            P p1 = st1.query(s.l,s.pl);
            que.push((state){s.l,s.pl,p1.fi,p1.se});
            P p2 = st2.query(s.pl+1,q.se);
            que.push((state){s.pl+1,q.se,p2.fi,p2.se});
            P p3 = st1.query(q.se+1,s.r);
            que.push((state){q.se+1,s.r,p3.fi,p3.se});
        }else{
            P q = st1.query(s.pl+1,s.r);
            res.pb(s.mn),res.pb(q.fi);
            P p1 = st2.query(s.l,s.pl);
            que.push((state){s.l,s.pl,p1.fi,p1.se});
            P p2 = st1.query(s.pl+1,q.se);
            que.push((state){s.pl+1,q.se,p2.fi,p2.se});
            P p3 = st2.query(q.se+1,s.r);
            que.push((state){q.se+1,s.r,p3.fi,p3.se});
        }
    }
    rep(i,n-1){
        cout << res[i] << " ";
    }
    cout << res[n-1] << endl;
    return 0;
}

