int get_min(int x, int l, int r, int L, int R, int v) {
	if(L >= l && R <= r) return segtree[x][v];
	if(L > r || R < l) return 0;
	return min_i(get_min(x, l, r,  L,          (L+R)/2, 2*v),
		         get_min(x, l, r, (L+R)/2 + 1,  R,      2*v + 1));
}

