int main() {
    int n;
    cin >> n;
    vector<ii> es, os;
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        if (i % 2 == 0) {
            es.emplace_back(p, i);
        } else {
            os.emplace_back(p, i);
        }
    }
    SegTree<ii> et(es, [](ii a, ii b) {return min(a, b);}, ii(1e9, 0));
    SegTree<ii> ot(os, [](ii a, ii b) {return min(a, b);}, ii(1e9, 0));
    priority_queue<range> er;
    range orr = {-1, -1, ii(-1, -1), true};
    er.push({0, n, et.query(0, n / 2), true});
    vi ans;
    while (er.size() || orr.l != -1) {
        if (orr.l != -1) {
            ans.push_back(orr.mi.first);
            if (orr.mi.second != orr.l) {
                er.push({orr.l, orr.mi.second, (orr.even ? et : ot).query((orr.l + orr.even) / 2, (orr.mi.second + orr.even) / 2), orr.even});
            }
            if (orr.mi.second + 1 != orr.r) {
                er.push({orr.mi.second + 1, orr.r, (!orr.even ? et : ot).query((orr.mi.second + 1 + !orr.even) / 2, (orr.r + !orr.even) / 2), !orr.even});
            }
            orr = {-1, -1, ii(-1, -1), true};
            continue;
        }

        range rem = er.top();
        ans.push_back(rem.mi.first);
        if (rem.l != rem.mi.second) {
            er.push({rem.l, rem.mi.second, (rem.even ? et : ot).query((rem.l + rem.even) / 2, (rem.mi.second + rem.even) / 2), rem.even});
        }
        orr = {rem.mi.second + 1, rem.r, (!rem.even ? et : ot).query((rem.mi.second + 1 + !rem.even) / 2, (rem.r + !rem.even) / 2), !rem.even};
        er.pop();
    }

    printvec(ans);
}

#include<cstdio>
#include<algorithm>
#include<iostream>
#define N 200000
using namespace std;
int n;
int a[N],wz[N];
bool del1;
struct node{
	int x[2];
	bool bz;
	int sum;
}f[N*4];
void combine(int x){
	f[x].x[0]=min(f[x+x].x[0],f[x+x+1].x[0]);
	f[x].x[1]=min(f[x+x].x[1],f[x+x+1].x[1]);
	f[x].sum=f[x+x].sum+f[x+x+1].sum;
}
void build(int l,int r,int s){
	if (l==r){
		f[s].x[l&1]=a[l];
		f[s].x[(l&1)^1]=n+1;
		f[s].sum=1;
		return;
	}
	build(l,(l+r)/2,s+s),build((l+r)/2+1,r,s+s+1);
	combine(s);
}
void down(int l,int r,int s){
	if (f[s].bz){
		swap(f[s].x[0],f[s].x[1]);
		f[s].bz=0;
		if (l!=r){
			f[s+s].bz^=1,f[s+s+1].bz^=1;
		}
	}
}
int find(int l,int r,int s,int ll,bool sig){
	down(l,r,s);
	if (r<ll)return n+1;
	if (f[s].x[sig]==n+1)return n+1;
	if (l>=ll&&f[s].sum==r-l+1)return f[s].x[sig];
	int x=find(l,(l+r)/2,s+s,ll,sig);
	if (del1&&ll)return x;
	int y=find((l+r)/2+1,r,s+s+1,ll,sig);
	if ((l+r)/2+1>=ll&&f[s+s+1].sum!=(r-((l+r)/2+1)+1))del1=1;
	return min(x,y);
}
int get(int l,int r,int s,int ll){
	down(l,r,s);
	if (l==r)return f[s].x[1]==a[l];
	if ((l+r)/2>=ll)return get(l,(l+r)/2,s+s,ll);
	else
		return get((l+r)/2+1,r,s+s+1,ll);
}
void del(int l,int r,int s,int ll){
	down(l,r,s);
	if (r<ll||l>ll)return;
	if (l==r){
