pii pMin(pii a, pii b){
    return mp(min(a.first, b.first), min(a.second, b.second));
}

pii query(int s, int e, int index, int qs, int qe){
    if(qe < s || qs > e) return mp(block, block);
    if(s== e){
        return segTree[index];
    }
    if(qs <= s && e <= qe){
        return segTree[index];
    }
    int mid = (s+e)/2;
    return pMin(query(s, mid, index*2, qs, qe),
            query(mid+1,e, index*2+1, qs, qe));
}

void update(int s, int e, int index, int loc, int val = block){
    if(s == e && s == loc){
        if(s & 1)segTree[index].second = block;
        else segTree[index].first = block;
        return;
    }
    if(loc <s || loc > e) return;
    int mid = (s+e)/2;
    update(s, mid, index*2, loc, val);
    update(mid+1, e, index*2+1, loc, val);
    segTree[index] = pMin(segTree[index*2], segTree[index*2+1]);
}

void buildTree(int s, int e, int index){
    if(s == e){
        segTree[index] = mp(block, block); 
        if(s & 1)segTree[index].second = p[s];//SECOND IF FOR ODD!!!!!!!!!!!!1
        else segTree[index].first = p[s];//FIRST IS FOR EVEN!!!!!!!!!!!!!!!!!!!
        return;
    }
    int mid = (s+e)/2;
    buildTree(s, mid, index*2);
    buildTree(mid+1, e, index*2+1);
    segTree[index] = pMin(segTree[index*2], segTree[index*2+1]);
}
