    priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> pq;
    pii t = query(1, n, 1, 1, n-1);
    pq.push(mp(t.second, mp(1, n)));
    while(!pq.empty()){
        pair<int, pii> temp = pq.top();
        pq.pop();
        s = temp.second.first;
        e = temp.second.second;
        if(e -s < 1)continue;
        int val = temp.first;
        pii temp2 = query(1, n, 1, inv[val] + 1, e);
        int second = (e - inv[temp2.first]) % 2 == 0 ? temp2.first : temp2.second;
