		if(l < k) push(l, k - 1);
		int g = M[Q(k + 1, r)];
		if(k + 1 <= g - 1) push(k + 1, g - 1);
		if(g + 1 <= r) push(g + 1, r);
		ans[++tot] = a[k];
		ans[++tot] = a[g];
		vis[a[k]] = 1;
		vis[a[g]] = 1;
	}
	forn(i, 1, tot) printf("%d ", ans[i]);
	return 0;
}

