  vpl vals;
  priority_queue<pair<pll, pll> > pq;
  pll pv = preview(0, n - 1);
  pq.push(mp(mp(-a[pv.f], -a[pv.s]), mp(0, n - 1)));

  while (!pq.empty()) {
    pair<pll, pll> top = pq.top();
    pq.pop();
    vals.pb(top.f);

    ll l = top.s.f, r = top.s.s;
    pll cur = preview(l, r);

    vpl ivals;
    if (cur.f - l > 1) ivals.pb(mp(l, cur.f - 1));
    if (cur.s - cur.f > 2) ivals.pb(mp(cur.f + 1, cur.s - 1));
    if (r - cur.s > 1) ivals.pb(mp(cur.s + 1, r));

    for (pll v: ivals) {
      // cout << v << endl;
      pll pv = preview(v.f, v.s);
      pq.push(mp(mp(-a[pv.f], -a[pv.s]), mp(v.f, v.s)));
    }
  }

  for (pll x: vals) {
    cout << -x.f << " " << -x.s << " ";
  }
  cout << '\n';
}

