  priority_queue<tiib,vector<tiib>,decltype(c)> q(c);  
  queue<int> ans;

  {
    int l = 0; int r = n-1; int b = 0;
    int r_index=0, l_index=0;
    for(l_index = l; l_index < r;l_index++){
      if(st[b].find(l,r) == st[b].find(l_index,l_index)){break;}
    }
    for(r_index = r; r_index >= l_index;r_index--){
      if(st[!b].find(l_index,r) == st[!b].find(r_index,r_index)){break;}
    }
