    int l = get<0>(now); int r = get<1>(now); int b = get<2>(now);
    if(l >= r) continue; 
    ans.push(l),ans.push(r);
    if(l == r-1){continue;}
    int r_index=0, l_index=0;
    for(l_index = l; l_index < r;l_index++){
      if(st[b].find(l,r) == st[b].find(l_index,l_index)){break;}
