    SegmentTree<ll> tree_odd(n, 1e18, minll);
    SegmentTree<ll> tree_even(n, 1e18, minll);

    rep (i, n) {
        tree_all.update(i, plist[i]);
        if (i & 1LL) tree_odd.update(i, plist[i]);
        else tree_even.update(i, plist[i]);
    }

    S V<ll> ans;
    priority_queue_incr<t3> q;
    q.push(t3(tree_even.query(0, n), 0, n));
    ll loops = 0LL;

    while (!q.empty()) {
        auto item = q.top(); q.pop();
        ll minval = get<0>(item);
        ll begin = get<1>(item);
        ll end = get<2>(item);

        loops++;

        assert(!((end - begin) & 1LL));
        assert(minval < 1e17);

        ll minidx = rmap[minval];
        ll minval2nd = 1e18;
        ll minidx2nd = 1e18;

        debug_printf("begin=%lld end=%lld minidx=%lld minval=%lld\n",
                     begin, end, minidx, minval);

        if (begin & 1LL) minval2nd = tree_even.query(minidx + 1LL, end);
        else minval2nd = tree_odd.query(minidx + 1LL, end);
        assert(minval2nd < 1e17);
        minidx2nd = rmap[minval2nd];
        ans.pb(minval);
        ans.pb(minval2nd);

        debug_printf("  minidx2nd=%lld minval2nd=%lld\n",
                     minidx2nd, minval2nd);

        assert(minidx < minidx2nd);

        ll nmin;

        if (minidx - begin >= 2LL) {
            if (begin & 1LL) nmin = tree_odd.query(begin, minidx);
            else nmin = tree_even.query(begin, minidx);
            q.push(t3(nmin, begin, minidx));
        }
        if (minidx2nd - (minidx + 1) >= 2LL) {
            if ((minidx + 1) & 1LL) nmin = tree_odd.query(minidx + 1, minidx2nd);
            else nmin = tree_even.query(minidx + 1, minidx2nd);
            q.push(t3(nmin, minidx + 1, minidx2nd));
        }
        if (end - (minidx2nd + 1) >= 2LL) {
            if ((minidx2nd + 1) & 1LL) nmin = tree_odd.query(minidx2nd + 1, end);
            else nmin = tree_even.query(minidx2nd + 1, end);
            q.push(t3(nmin, minidx2nd + 1, end));
        }
    }

    assert(loops == n / 2LL);

    rep (i, n) cout << ans[i] << ((i == n-1) ? "" : " ");
    cout << endl;
}

