#define rep2(x,fr,to) for(int (x)=(fr);(x)<(to);(x)++)
#define rep(x,to) for(int (x)=0;(x)<(to);(x)++)
#define repr(x,fr,to) for(int (x)=(fr);(x)>=(to);(x)--)
#define all(c) (c).begin(),(c).end()
#define sz(v) (int)(v).size()

typedef int64_t ll; typedef vector<int> VI; typedef pair<int,int> pii;
const ll mod = 1e9+7;

struct Segtree{
	typedef ll sgT;
	vector<sgT> seg;
	int nbn; sgT INF;
	void init(int n){
		for(nbn=1; nbn<n+2; nbn<<=1); INF=1LL<<29; // min:+inf,max:-inf
		seg.assign(nbn*2, INF);
	}
	sgT comp(sgT l, sgT r){return min(l, r);}  //min<->max
	void update(int k,sgT x){
		k+=nbn-1; seg[k]=x;
		while(k>0){ k=(k-1)/2; seg[k]=comp(seg[k*2+1],seg[k*2+2]); }
	}
	sgT query2(int a,int b,int l,int r,int k){
		if(b<=l||r<=a) return INF;
		if(a<=l&&r<=b) return seg[k];
		return comp(query2(a,b,l,(l+r)/2,k*2+1), query2(a,b,(l+r)/2,r,k*2+2));
	}
	sgT query(int a,int b){ return query2(a,b,0,nbn,0); }
	sgT get(int a){return seg[nbn+a-1];}  // =query(a,a+1)
};

struct Sts{
	int v,l,r,a,b;
	Sts(int v,int l,int r,int a,int b):v(v),l(l),r(r),a(a),b(b){}
	bool operator>(const Sts& b) const {
		return v > b.v; 
	}

};

Segtree sgg, sgk;


int gtps(int l, int r, int v,  Segtree& sgt){

	int lo=l-1, hi=r;
	while(hi - lo >1){
		int md = (hi + lo) >> 1;
		if( sgt.query(lo, md+1) <= v ) hi = md; else lo = md; 
	}

	return hi;
}

Sts f(int l, int r){
	//cout <<"l="<<l <<"  ";
	int v,a,b;
	if(l%2){
		v = sgk.query(l,r);
		a = gtps(l,r,v,sgk);
		int t = sgg.query(a+1,r);
		b = gtps(a+1,r,t,sgg);
	}else{
		v = sgg.query(l,r);
		a = gtps(l,r,v,sgg);
		int t = sgk.query(a+1,r);
		b = gtps(a+1,r,t,sgk);
	}

	return Sts(v,l,r,a,b);
}

