	rep(i,n){
		int c; cin >>c;
		p[i] = c;
		if(i%2) sgk.update(i,c);
		else sgg.update(i,c);
	}
	Sts sta = f(0,n);
	priority_queue<Sts, vector<Sts>, greater<Sts> > pq;
	pq.push(sta);
	VI ans;
	while(!pq.empty()){
		auto cr = pq.top(); pq.pop();
		//printf("%d:%d:%d:%d:%d   ",cr.v,cr.l,cr.r,cr.a,cr.b);
		//if(cr.v > n) continue;
		ans.push_back(p[cr.a]);
		ans.push_back(p[cr.b]);
		if(cr.a - cr.l > 1){
			auto nx = f(cr.l, cr.a);
			pq.push(nx);
		}
		if(cr.b - cr.a > 1){
			auto nx = f(cr.a+1, cr.b);
			pq.push(nx);
		}
		if(cr.r - cr.b > 1){
			auto nx = f(cr.b+1, cr.r);
			pq.push(nx);
		}
	}

	for(auto x :ans) printf("%d ",x); puts("");
	return 0;
}

