struct ST{
    int n,a[max_n];
    int lg[max_n],st[max_n][max_log+1];
    void init(int* _a,int _n){
        n=_n;
        for(int i=1;i<=n;i++)a[i]=_a[i];
        lg[1]=0;
        for(int i=2;i<=n;i++){
            lg[i]=lg[i-1];
            if(i==(i&-i))lg[i]++;
        }
        for(int i=1;i<=n;i++)st[i][0]=a[i];
        for(int j=1;j<=max_log;j++){
