const ll N_ = (1 << 18);
ll segOdd[2*N_-1];
//Range Minimum Query
void updateOdd(ll k, ll x){
  k += N_-1;
  segOdd[k] = x;
  while(k > 0){
    k = (k-1)/2;
    segOdd[k] = min(segOdd[2*k+1], segOdd[2*k+2]);
  }
}

ll queryOdd(ll x = 0, ll y = 0, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return INFL;
  if(x <= left && right <= y) return segOdd[k];
  ll mid = (left + right) / 2;
  ll l = queryOdd(x, y, 2*k+1, left, mid);
  ll r = queryOdd(x, y, 2*k+2, mid, right);
  return min(l, r);
}

ll segEven[2*N_-1];
//Range Minimum Query
void updateEven(ll k, ll x){
  k += N_-1;
  segEven[k] = x;
  while(k > 0){
    k = (k-1)/2;
    segEven[k] = min(segEven[2*k+1], segEven[2*k+2]);
  }
}

ll queryEven(ll x, ll y, ll k = 0, ll left = 0, ll right = N_){
  if(right <= x || y <= left) return INFL;
  if(x <= left && right <= y) return segEven[k];
  ll mid = (left + right) / 2;
  ll l = queryEven(x, y, 2*k+1, left, mid);
  ll r = queryEven(x, y, 2*k+2, mid, right);
  return min(l, r);
}

ll N;
vector<ll> p, q;
vector<ll> ans;
void saiki(ll start, ll M){
  typedef pair<ll, pair<ll, ll>> P;
  priority_queue<P, vector<P>, greater<P>> pque;
  pque.push({queryEven(0, M), {0, M}});
  while(!pque.empty()){
    P pq = pque.top();
    pque.pop();
    if(pq.s.s == 0){
      continue;
    }
    if(pq.s.s == 2){
      ans.pb(p[pq.s.f]);
      ans.pb(p[pq.s.f+1]);
      continue;
    }
    ll x, y, x_pos, y_pos;
    ll start = pq.s.f;
    ll n = pq.s.s;
    if(start % 2){
      x = queryOdd(start, start + n);
      x_pos = q[x];
      y = queryEven(x_pos+1, start + n);
      y_pos = q[y];
    }else{
      x = queryEven(start, start + n);
      x_pos = q[x];
      y = queryOdd(x_pos+1, start + n);
      y_pos = q[y];
    }
    ans.pb(x);
    ans.pb(y);
    if(start % 2){
      pque.push({queryOdd(start, start + x_pos-start), {start, x_pos-start}});
    }else{
      pque.push({queryEven(start, x_pos-start), {start, x_pos-start}});
    }
    if((x_pos+1) % 2){
      pque.push({queryOdd(x_pos+1, y_pos), {x_pos+1, y_pos-x_pos-1}});
    }else{
      pque.push({queryEven(x_pos+1, y_pos), {x_pos+1, y_pos-x_pos-1}});
    }
    if((y_pos+1) % 2){
      pque.push({queryOdd(y_pos+1, n+start), {y_pos+1, n-y_pos+start-1}});
    }else{
      pque.push({queryEven(y_pos+1, n+start), {y_pos+1, n-y_pos+start-1}});
    }
  }
  rep(i, N){
    cout << ans[i] + 1;
    if(i == N-1) cout << endl;
    else cout << " ";
  }
  return;
}

void solve(){
  rep(i, N){
    updateEven(i, INFL);
    updateOdd(i, INFL);
    if(i % 2) updateOdd(i, p[i]);
    else updateEven(i, p[i]);
  }
  saiki(0, N);
}

