#include <bits/stdc++.h>
using namespace std;
pair<int, int> even[400005];
pair<int, int> odd[400005];
int arr[200005];
int n;
int sz;
const int inf=0x3f3f3f3f;
void update(int idx, pair<int, int> val, pair<int, int> *tree){
	idx+=sz;
	while(idx){
		tree[idx]=min(tree[idx], val);
		idx/=2;
	}
}
pair<int, int> query(int a, int b, pair<int, int> *tree){
	pair<int, int> ret={inf, inf};
	a+=sz;
	b+=sz;
	while(a<=b){
		if(a&1)
			ret=min(ret, tree[a++]);
		if(!(b&1))
			ret=min(ret, tree[b--]);
		a/=2;
		b/=2;
	}
	return ret;
}
vector<pair<int, int> > vec;
int degree[100005];
int parent[100005];
void solve(int le, int ri, int par){
	if(le>=ri+1)
		return;
	if(par!=-1)
		degree[par]++;
	if(le+1==ri){
		parent[vec.size()]=par;
		vec.push_back({arr[le], arr[ri]});
		return;
	}
	if(le&1){
		int left=le/2;
		int right=ri/2;
		auto q=query(left, right-1, odd);
		auto p=query(q.second/2+1, right, even);
		int now=vec.size();
		parent[now]=par;
		vec.push_back({q.first, p.first});
		solve(le, q.second-1, par);
		solve(q.second+1, p.second-1, now);
		solve(p.second+1, ri, par);
		return;
	}
	int left=le/2;
	int right=ri/2;
	auto q=query(left, right, even);
	auto p=query(q.second/2, right, odd);
	int now=vec.size();
	parent[now]=par;
	vec.push_back({q.first, p.first});
	solve(le, q.second-1, par);
	solve(q.second+1, p.second-1, now);
	solve(p.second+1, ri, par);
}
int main(){
	memset(even, 0x3f, sizeof(even));
	memset(odd, 0x3f, sizeof(odd));
	scanf("%d", &n);
	sz=1;
	while(sz<n/2)sz*=2;
	for(int i=0;i<n;i++){
		int x;
		scanf("%d", &x);
		arr[i]=x;
		int idx=i/2;
		if(i&1)
			update(idx, {x, i}, odd);		
		else
			update(idx, {x, i}, even);
	}
	solve(0, n-1, -1);
	priority_queue<pair<pair<int, int>, int> > pq;
	for(int i=0;i<vec.size();i++){
		if(degree[i]==0)
			pq.push({vec[i], i});
	}
	vector<pair<int, int> > ans;
	while(!pq.empty()){
		auto now=pq.top();
		pq.pop();
		ans.push_back(now.first);
		int next=parent[now.second];
		if(next==-1)
			continue;
		if(--degree[next]==0)
			pq.push({vec[next], next});
	}
	reverse(ans.begin(), ans.end());
	for(int i=0;i<ans.size();i++)
		printf("%d %d ", ans[i].first, ans[i].second);
	printf("\n");
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int Max_N=2*1e5;
int N,A[Max_N+10]={},Del[Max_N+10]={};
pair<int,int> B[Max_N+10]={};
inline int lowbit(int x){
	return x & - x;
}
inline void ADD(int x,int k){
	if(!x) return;
	for(;x;x-=lowbit(x)) Del[x]=min(Del[x],k);
}
inline int ASK(int x){
	int Min=Del[x];
	for(;x<=N;x+=lowbit(x)) Min=min(Min,Del[x]);
	return Min;
}
struct kk{
	int l,r,Id1,Id2,Rev;
} T[Max_N*4+10]={};
inline void Build(int x,int l,int r){
	T[x].l=l; T[x].r=r;
	if(l==r){
		if(l%2) T[x].Id1=l;
		else T[x].Id2=l;
		return;
	}
	Build(x<<1,l,(l+r)>>1);
	Build((x<<1)+1,((l+r)>>1)+1,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
//	cout<<T[x].l<<' '<<T[x].r<<' '<<T[x].Id1<<' '<<T[x].Id2<<endl;
}
inline void DownTag(int x){
	if(T[x].Rev){
		swap(T[x<<1].Id1,T[x<<1].Id2);
		swap(T[(x<<1)+1].Id1,T[(x<<1)+1].Id2);
		T[x<<1].Rev^=1; T[(x<<1)+1].Rev^=1;
		T[x].Rev=0;
	}
}
inline void Add(int x,int k,int Val){
	DownTag(x);
	if(T[x].l==T[x].r){
		A[k]=Val;
		return;
	}
	if(k<=T[x<<1].r) Add(x<<1,k,Val);
	else Add((x<<1)+1,k,Val);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline void Change(int x,int l,int r){
	if(l<=T[x].l&&T[x].r<=r){
		swap(T[x].Id1,T[x].Id2);
		T[x].Rev^=1;
		return;
	}
	DownTag(x);
	if(l<=T[x<<1].r) Change(x<<1,l,r);
	if(r>T[x<<1].r) Change((x<<1)+1,l,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline int Ask(int x,int l,int r,int Opt){
//	cout<<x<<' '<<T[x].l<<' '<<T[x].r<<' '<<l<<' '<<r<<endl;
    DownTag(x);
	if(l<=T[x].l&&T[x].r<=r) return Opt==1?T[x].Id1:T[x].Id2;
	int Ans=0,Anss=0;
	if(l<=T[x<<1].r) Ans=Ask(x<<1,l,r,Opt);
	if(r>T[x<<1].r) Anss=Ask((x<<1)+1,l,r,Opt);
	if(A[Ans]>A[Anss]) Ans=Anss;
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
	return Ans;
}
inline void Solv(){
	for(int i=1;i<=N/2;i++){
		int Min=Ask(1,1,N,1);
		int r=ASK(Min);
		int Minn=Ask(1,Min,r,2);
//		cout<<Min<<' '<<Minn<<' '<<r<<endl;
		B[i]=make_pair(A[Min],A[Minn]);
		Add(1,Min,1<<30); Add(1,Minn,1<<30);
		if(Min+1<Minn-1) Change(1,Min+1,Minn-1);
		ADD(Min,Min); ADD(Minn,Minn);
	}
}
int main(){
	scanf("%d",&N); A[0]=1<<30;
	for(int i=1;i<=N;i++) scanf("%d",&A[i]);
	for(int i=0;i<=N;i++) Del[i]=N;
	Build(1,1,N); Solv();
	for(int i=1;i<=N/2;i++) printf("%d %d ",B[i].first,B[i].second); puts("");
	return 0;
}

