	while (n < n_)n *= 2;
	for (int i = 0; i < 2 * n - 1; i++) {
		dat[i] = INT_MAX;
	}
}
void init2(int n_) {
	n2 = 1;
	while (n2 < n_)n2 *= 2;
	for (int i = 0; i < 2 * n2 - 1; i++) {
		dat2[i] = INT_MAX;
	}
}
void update(int k, int a) {
	k += n - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
void update2(int k, int a) {
	k += n2 - 1;
	dat2[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat2[k] = min(dat2[k * 2 + 1], dat2[k * 2 + 2]);
	}
}
int query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return INT_MAX;
	if (a <= l&&r <= b)return dat[k];
	else {
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}
int query2(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return INT_MAX;
	if (a <= l&&r <= b)return dat2[k];
	else {
		int vl = query2(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = query2(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}
typedef pair<int, int> P;
P b[200005];
int nn;
int binary(int k) {
	int lb = -1,ub = nn;
	while (ub - lb > 1) {
		int mid = (ub + lb) / 2;
		if (b[mid].first >= k)ub = mid;
		else lb = mid;
	}
	return b[ub].second;
}
