	if (mid >= y) return ask(x, y, l, mid, cnt * 2, bit);
	else if (mid < x) return ask(x, y, mid + 1, r, cnt * 2 + 1, bit);
	else return min(ask(x, mid, l, mid, cnt * 2, bit), ask(mid + 1, y, mid + 1, r, cnt * 2 + 1, bit));

}

