#define SIZE 200010

bool taken[SIZE] = {0};
int st[2][SIZE * 4], p[SIZE], a[SIZE], pos[SIZE];
int bound[SIZE * 4][2];

#define Lsn (curr << 1)
#define Rsn ((curr << 1) | 1)
void construct (int L, int R, int curr) {
   if (L == R) {
      st[L & 1][curr] = p[L];
      return;
   }
   int m = ((L + R) >> 1);
   construct (L, m, Lsn); construct (m + 1, R, Rsn);
   st[0][curr] = min (st[0][Lsn], st[0][Rsn]);
   st[1][curr] = min (st[1][Lsn], st[1][Rsn]);
}

int find_min (int i, int j, int L, int R, int curr, int u) {
   if (i > j) return -1;
   if (i == L && j == R) {
      int l = i, r = j;
      if (st[u][curr] == INF) return -1;
      while (l < r) {
         int m = ((l + r) >> 1);
         if (st[u][Lsn] < st[u][Rsn]) {
            curr = Lsn;
            r = m;
         }
         else {
            curr = Rsn;
            l = m + 1;
         }
      }
      return l;
   }
   int m = ((L + R) >> 1);
   if (j <= m) return find_min (i, j, L, m, Lsn, u);
   if (i > m) return find_min (i, j, m + 1, R, Rsn, u);
   int p1 = find_min (i, m, L, m, Lsn, u), p2 = find_min (m + 1, j, m + 1, R, Rsn, u);
   if (p1 == -1) return p2;
   if (p2 == -1) return p1;
   return ((p[p1] < p[p2]) ? p1 : p2); 
} 

void update_bound (int i, int j, int L, int R, int curr, pii bnd) {
   //cout << i << " " << j << endl;
   if (i > j) return;
   if (i == L && j == R) {
      bound[curr][1] = min (bound[curr][1], bnd.Y);
      bound[curr][0] = max (bound[curr][0], bnd.X);
      return;
   }
   int m = ((L + R) >> 1);
   if (j <= m) update_bound (i, j, L, m, Lsn, bnd);
   else if (i > m) update_bound (i, j, m + 1, R, Rsn, bnd);
   else {
      update_bound(i, m, L, m, Lsn, bnd); update_bound(m + 1, j, m + 1, R, Rsn, bnd);
   }
}

void update (int i, int L, int R, int curr, int u) {
   while (L < R) {
      int m = ((L + R) >> 1);
      if (i <= m) {
         curr = Lsn;
         R = m;
      }
      else {
         curr = Rsn;
         L = m + 1;
      }
   }
   st[u][curr] = INF;
   while (curr != 1) {
      curr = (curr >> 1);
      st[u][curr] = min (st[u][Lsn], st[u][Rsn]);
   }
}

pii get_bnd (int i, int L, int R, int curr) {
   int l = 1, r = INF;
   while (L < R) {
      l = max (l, bound[curr][0]);
      r = min (r, bound[curr][1]);
      int m = ((L + R) >> 1);
      if (i <= m) {
         curr = Lsn;
         R = m;
      }
      else {
         curr = Rsn;
         L = m + 1;
      }
   }
   return MP(l, r);
}

int main() {
   int n, k = 1;
   scanf("%d", &n);
   for (int i = 0 ; i < SIZE * 4 ; ++i) {
      st[0][i] = st[1][i] = INF;
      bound[i][0] = 1; bound[i][1] = n;
   }
   for (int i = 1 ; i <= n ; ++i) {
      scanf("%d", p + i);
      pos[p[i]] = i;
   }
   construct (1, n, 1); 
   for (int i = 1 ; i <= n ; ++i) {
      if (taken[i]) continue;
      pii bnd = get_bnd(pos[i], 1, n, 1);
      int p2 = find_min(pos[i] + 1, bnd.Y, 1, n, 1, ((pos[i] & 1) ^ 1));
      int p1 = find_min(bnd.X, pos[i] - 1, 1, n, 1, ((pos[i] & 1) ^ 1));
      int pp;
      if (p1 == -1) pp = p2;
      else if (p2 == -1) pp = p1;
      else pp = (p[p1] < i) ? p1 : p2;
      if (pp > pos[i]) {
         a[k++] = i; a[k++] = p[pp];
      }
      else {
         a[k++] = p[pp]; a[k++] = i;
      }
      taken[i] = taken[p[pp]] = true;
      update (pp, 1, n, 1, (pp & 1));
      update (pos[i], 1, n, 1, (pos[i] & 1));
      if (pp < pos[i]) {
         update_bound (pp + 1, pos[i] - 1, 1, n, 1, MP(pp + 1, pos[i] - 1)); 
         update_bound (pos[i] - 1, n, 1, n, 1, MP(pos[i] - 1, n)); 
         update_bound (1, pp - 1, 1, n, 1, MP(1, pp - 1)); 
      }
      else {
         update_bound (pos[i] + 1, pp - 1, 1, n, 1, MP(pos[i] + 1, pp - 1)); 
         update_bound (1, pos[i] - 1, 1, n, 1, MP(1, pos[i] - 1)); 
         update_bound (pp + 1, n, 1, n, 1, MP(pp + 1, n)); 
      }
   } 
   for (int i = 1 ; i <= n ; ++i) printf("%d ", a[i]);
   printf("\n");

   return 0;
}

