struct RMQ
{
	static const int MAX_LOG = 20;

	int lg2[MAXN + 5], mn[MAX_LOG + 1][MAXN + 5];

	inline int min_id(int u, int v) { return !u || !v ? u | v : (p[u] < p[v] ? u : v); }

	inline void build(int t)
	{
		lg2[1] = 0;
		for(int i = 2; i <= n; ++i) lg2[i] = lg2[i >> 1] + 1;

		for(int i = 1; i <= n; ++i) mn[0][i] = (i & 1) == t ? i : 0;
		for(int k = 1; k <= lg2[n]; ++k)
			for(int i = 1; i + (1 << k) - 1 <= n; ++i)
				mn[k][i] = min_id(mn[k - 1][i], mn[k - 1][i + (1 << (k - 1))]);
	}

	inline int query(int l, int r)
	{
		int k = lg2[r - l + 1];
		return min_id(mn[k][l], mn[k][r - (1 << k) + 1]);
	}
};

struct seg
{
	int l, r, mn;

	inline bool operator > (const seg &rhs) const { return this->mn > rhs.mn; }

	seg() { }
	seg(int _l, int _r, int _mn): l(_l), r(_r), mn(_mn) { }
};

inline void solve()
{
	static RMQ S[2];
	for(int i = 0; i < 2; ++i) S[i].build(i);

	static priority_queue<seg, vector<seg>, greater<seg> > Q;
	static vector<int> ans;

	Q.emplace(1, n, p[S[1].query(1, n)]);
	while(!Q.empty())
	{
		int l = Q.top().l, r = Q.top().r;
		Q.pop();
		if(l + 1 == r)
		{
			ans.push_back(p[l]);
			ans.push_back(p[r]);
			continue;
		}

		int x = S[l & 1].query(l, r), y = S[(l + 1) & 1].query(x + 1, r);
		ans.push_back(p[x]);
		ans.push_back(p[y]);

		if(l < x) Q.emplace(l, x - 1, p[S[l & 1].query(l, x - 1)]);
		if(x + 1 < y) Q.emplace(x + 1, y - 1, p[S[(x + 1) & 1].query(x + 1, y- 1)]);
		if(y < r) Q.emplace(y + 1, r, p[S[(y + 1) & 1].query(y + 1, r)]);
	}

	for(auto i : ans) printf("%d ", i);
	puts("");
}

