    for(int i = 0; i < 2 * MAX + 7; i++)
        tree[i].first = tree[i].second = INF;
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        g[p[i]] = i;
        tree[i + MAX] = {p[i], INF};
        if(i & 1) swap(tree[i + MAX].first, tree[i + MAX].second);
    }
    for(int node = MAX - 1; node; node--)
    {
        tree[node].first = min(tree[2 * node].first, tree[2 * node + 1].first);
        tree[node].second = min(tree[2 * node].second, tree[2 * node + 1].second);
    }
