class Seg{
public: 

  //遅延用の型  
  struct T{
    int type; //0 - empty   , 1 - update
    int value;
    T():type(0),value(0){}
    T(int type,int value):type(type),value(value){}
  };

  //マージ可能な主データ型
  struct D{
    int value,idx;
    D():value(INF),idx(INF){} /*適切な値にする!!!!!!*/
    D(int value,int idx):value(value),idx(idx){}
    bool operator < (D a)const {return value < a.value;} //merge用
  };

  int n;
  vector<D> dat;
  vector<T> td;
  D returnD = D(INF,INF); // 範囲外の時に返す値。

  Seg(){n=-1;}
  Seg(int n_){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1,T());
    dat.resize(2*n-1,D());
  }

  D merge(D a,D b){return min(a,b);}

  void delay(int k,int len){
    return;
    if(td[k].type==0) return;
  }

  D update(int k,int x,int idx, int len){
    dat[k].value = x;
    dat[k].idx = idx;
    return dat[k];
  }

  //[a,b)の値をx変更　add(a,b,x)
  D query(int a,int b,int x,int idx,bool flg=true,int k=0,int l=0,int r=-1){
    if(r==-1) r=n, assert(a <= n && b <= n);
    if(r<=a||b<=l) return flg? dat[k]:returnD;
    if(a<=l&&r<=b) return flg? update(k, x, idx, r - l):dat[k];

    //delay(k, r - l);
    D vl = query(a,b,x,idx,flg,k*2+1,l,(l+r)/2);
    D vr = query(a,b,x,idx,flg,k*2+2,(l+r)/2,r);
    if(flg) dat[k] = merge(vl,vr);
    return merge(vl,vr);
  }

  //[a,b)の合計値を得る　find(a,b);
  P find(int a,int b){
    D res = query(a,b,0,0,false);
    return P(res.idx,res.value);
  }
};

void insert(vector<int> &a,vector<int> b){for(int c:b) a.push_back(c);}

struct dat{
  int l, r;
  int lval,rval;
  int flag;
  dat(){};
  dat(int l,int r,int lval,int rval,int flag):l(l),r(r), lval(lval), rval(rval),flag(flag){};
  bool operator < (dat a)const {return P(lval,rval) > P(a.lval,a.rval);}
};

int n;
vector<int> p;
vector<int> solve(Seg &A,Seg &B){
  priority_queue<dat> Q;
  Q.push(dat(0,n-1,A.find(0,n).second,B.find(0,n).second,0));
  vector<int> res;

  while(1){
    dat t = Q.top(); Q.pop();
    int l = t.l, r = t.r, flag = t.flag;
    int nl, lval; tie(nl,lval) = A.find(l, r+1);
    int nr, rval; tie(nr,rval) = B.find(l, r+1);
    if(lval == INF || rval == INF) break;
    A.query(nl, nl + 1, INF, INF);
    B.query(nr, nr + 1, INF, INF);

    if(flag) swap(nl, nr), swap(lval, rval);

    /*pr(l,r);
    pr(nl,lval, nr, rval);
    pr(t.lval,t.rval);
    cout<<endl;
    */

    assert(t.lval == lval && t.rval == rval);

    res.push_back(lval);
    res.push_back(rval);
    auto push=[&A,&B,&Q](int nl,int nr,int flag){
      if(nl > nr) return;
      int a = A.find(nl, nr+1).second;
      int b = B.find(nl, nr+1).second;
      if(flag) swap(a,b);
      Q.push(dat(nl, nr, a, b, flag));
    };

    push(nl + 1,nr - 1,!flag);
    push(l,nl-1,flag);
    push(nr + 1,r,flag);
  }
  return res;
