void propagate(int l,int r,int i) {
    if(!rev[i]) return;

    rev[i] = 0;
    swap(tree[i].f, tree[i].s);
    rev[i<<1] ^= 1 , rev[(i<<1)|1] ^= 1;

}

void build(int l,int r,int i) {
    if(l == r) {
        if(l&1) tree[i] = {l,n+1};
        else tree[i] = {n+1,l};
        return;
    }

    int mid = (l+r)>>1;
    build(l, mid, i<<1) , build(mid+1, r, (i<<1)|1);

    if(a[tree[i<<1].f]  < a[tree[(i<<1)|1].f])
        tree[i].f = tree[i<<1].f;
    else
        tree[i].f = tree[(i<<1)|1].f;



    if(a[tree[i<<1].s]  < a[tree[(i<<1)|1].s])
        tree[i].s = tree[i<<1].s;
    else
        tree[i].s = tree[(i<<1)|1].s;

}

void removee(int l,int r,int i,int x) {

    propagate(l, r, i);

    if(l == r){
        tree[i] = {n+1,n+1};
        return;
    }

    int mid = (l+r)>>1;
    if(mid >= x) removee(l,mid,i<<1,x);
    else removee(mid+1, r, (i<<1)|1, x);

    if(a[tree[i<<1].f]  < a[tree[(i<<1)|1].f])
        tree[i].f = tree[i<<1].f;
    else
        tree[i].f = tree[(i<<1)|1].f;



    if(a[tree[i<<1].s]  < a[tree[(i<<1)|1].s])
        tree[i].s = tree[i<<1].s;
    else
        tree[i].s = tree[(i<<1)|1].s;

}

void flip (int l,int r,int i,int x,int y) {
    propagate(l, r, i);

    if(l > y || r < x) return ;

    if(l >= x && r <= y) {
        rev[i] ^= 1;
        propagate(l, r, i);
        return ;
    }
    int mid = (l+r)>>1;

    flip(l, mid, i<<1, x, y) , flip(mid+1, r, (i<<1)|1, x, y);

    if(a[tree[i<<1].f]  < a[tree[(i<<1)|1].f])
        tree[i].f = tree[i<<1].f;
    else
        tree[i].f = tree[(i<<1)|1].f;



    if(a[tree[i<<1].s]  < a[tree[(i<<1)|1].s])
        tree[i].s = tree[i<<1].s;
    else
        tree[i].s = tree[(i<<1)|1].s;

}

int query(int l,int r,int i, int x,int y , bool t) {
    propagate(l, r, i);

    if(l > y || r < x) return n+1;

    if(l >= x && r <= y) return t ? tree[i].f:tree[i].s;

    int mid = (l+r)>>1;

    int r1 = query(l, mid, i<<1, x, y, t);
    int r2 = query(mid+1, r, (i<<1)|1, x, y, t);

    if(a[r1]  < a[r2]) return r1;
    return r2;
}

void mergeee(vector<pii> &a,vector<pii> &b, vector<pii> &ret) {

    int i = 0, j = 0;

    while(i < sz(a) && j < sz(b)) {
        if(a[i] < b[j]) ret.pb(a[i++]);
        else ret.pb(b[j++]);
    }

    while(i < sz(a)) ret.pb(a[i++]);

    while(j < sz(b)) ret.pb(b[j++]);

}

void solve(int l,int r , vector<pii> &ans) {
    if(l >= r) return;
    int x = query(1, n,  1, l, r, false);
    int y = query(1, n, 1, l, r, true);
    int tx = query(1, n, 1, x, r, true);
    int ty =  query(1, n, 1, y, r, false);

    vector<pii> ans1 , ans2 , ans3;

    if(ty == n+1 || (a[x] < a[y] && tx != n+1)) {
        ans.pb({a[x],a[tx]});

        removee(1, n, 1, x) , removee(1, n, 1, tx);
        flip(1, n, 1, l, x) , flip(1, n, 1, l, tx);

        solve(l,x-1, ans1) , solve(x+1,tx-1,ans2) , solve(tx+1,r,ans3);
    }
    else  {
        ans.pb({a[y],a[ty]});
        removee(1, n, 1, y) , removee(1, n, 1, ty);
        flip(1, n, 1, l, y) , flip(1, n, 1, l, ty);
        solve(l,y-1, ans1) , solve(y+1,ty-1,ans2) , solve(ty+1,r,ans3);
