#include "bits/stdc++.h"
using namespace std;

pair<int, int> INF = { 1000000000, -1 };

class SegmentTree {
private:
	vector<pair<int, int> > Node;
public:
	SegmentTree(vector<int>& V) : Node(V.size() * 2, INF) {
		for (int i = 0; i < V.size(); i++) {
			Node[i + V.size()] = { V[i], i };
		}
		for (int i = V.size() - 1; i >= 1; i--) {
			Node[i] = min(Node[i * 2], Node[i * 2 + 1]);
		}
	}
	pair<int, int> Query(int L, int R) {
		L += Node.size() / 2, R += Node.size() / 2;
		pair<int, int> ANS = INF;
		while (L < R) {
			if (L & 1) {
				ANS = min(ANS, Node[L]);
				L++;
			}
			if (R & 1) {
				ANS = min(ANS, Node[R - 1]);
				R--;
			}
			L >>= 1, R >>= 1;
		}
		return ANS;
	}
};

struct Range {
	pair<int, int> MAX1, MAX2;
	int L, R;
};

bool operator< (Range R1, Range R2) {
	return R1.MAX1.first > R2.MAX1.first;
}

int main() {
	int N;
	cin >> N;
	vector<int> P(N), VE(N, INF.first), VO(N, INF.first);
	for (int i = 0; i < N; i++) cin >> P[i], i % 2 == 0 ? VE[i] = P[i] : VO[i] = P[i];
	SegmentTree Even(VE), Odd(VO);
	priority_queue<Range> PQ;
	Range R;
	R.L = 0, R.R = N;
	R.MAX1 = Even.Query(0, N);
	R.MAX2 = Odd.Query(R.MAX1.second + 1, N);
	PQ.push(R);
	vector<long long> ANS;
	while (!PQ.empty()) {
		Range P = PQ.top();
		PQ.pop();
		ANS.push_back(P.MAX1.first);
		ANS.push_back(P.MAX2.first);
		if (P.L != P.MAX1.second) {
			Range NR;
			NR.L = P.L, NR.R = P.MAX1.second;
			if (NR.L % 2 == 0) {
				NR.MAX1 = Even.Query(NR.L, NR.R);
				NR.MAX2 = Odd.Query(NR.MAX1.second + 1, NR.R);
			}
			else {
				NR.MAX1 = Odd.Query(NR.L, NR.R);
				NR.MAX2 = Even.Query(NR.MAX1.second + 1, NR.R);
			}
			PQ.push(NR);
		}
		if (P.MAX1.second + 1 != P.MAX2.second) {
			Range NR;
			NR.L = P.MAX1.second + 1, NR.R = P.MAX2.second;
			if (NR.L % 2 == 0) {
				NR.MAX1 = Even.Query(NR.L, NR.R);
				NR.MAX2 = Odd.Query(NR.MAX1.second + 1, NR.R);
			}
			else {
				NR.MAX1 = Odd.Query(NR.L, NR.R);
				NR.MAX2 = Even.Query(NR.MAX1.second + 1, NR.R);
			}
			PQ.push(NR);
		}
		if (P.MAX2.second + 1 != P.R) {
			Range NR;
			NR.L = P.MAX2.second + 1, NR.R = P.R;
			if (NR.L % 2 == 0) {
				NR.MAX1 = Even.Query(NR.L, NR.R);
				NR.MAX2 = Odd.Query(NR.MAX1.second + 1, NR.R);
			}
			else {
				NR.MAX1 = Odd.Query(NR.L, NR.R);
				NR.MAX2 = Even.Query(NR.MAX1.second + 1, NR.R);
			}
			PQ.push(NR);
		}
	}
	for (int i = 0; i < N; i++) {
		cout << ANS[i] << (i == N - 1 ? '\n' : ' ');
	}
}

