const int N = 200010;

int a[N];
int tree[2][4 * N];

void put(int x, int l, int r, int p, int *t) {
  if (l == r) {
    t[x] = p;
    return;
  }
  int s = (l + r) / 2;
  if (p <= s) {
    put(2 * x, l, s, p, t);
  } else {
    put(2 * x + 1, s + 1, r, p, t);
  }
  if (t[2 * x] == -1) {
    t[x] = t[2 * x + 1];
  } else
  if (t[2 * x + 1] == -1) {
    t[x] = t[2 * x];
  } else {
    t[x] = (a[t[2 * x]] < a[t[2 * x + 1]] ? t[2 * x] : t[2 * x + 1]);
  }
}

int get(int x, int l, int r, int ql, int qr, int *t) {
  if (r < ql || l > qr) {
    return -1;
  }
  if (l >= ql && r <= qr) {
    return t[x];
  }
  int s = (l + r) / 2;
  int el = get(2 * x, l, s, ql, qr, t);
  int er = get(2 * x + 1, s + 1, r, ql, qr, t);
  if (el == -1) {
    return er;
  }
  if (er == -1) {
    return el;
  }
  return a[el] < a[er] ? el : er;
}

const int inf = 1e9;

int n;

vector <int> solve(int l, int r, int w) {
  if (r - l <= 0) {
    assert(r - l < 0);
    return vector <int>();
  }
  vector <int> res;
  int p = get(1, 0, n - 1, l, r, tree[w]);
  int q = get(1, 0, n - 1, p + 1, r, tree[1 - w]);
  assert(p != -1);
  assert(q != -1);
  res.push_back(a[p]);
  res.push_back(a[q]);
  vector <int> x = solve(l, p - 1, w);
  vector <int> y = solve(p + 1, q - 1, 1 - w);
  vector <int> z = solve(q + 1, r, w);
  x.push_back(inf);
  y.push_back(inf);
  z.push_back(inf);
  reverse(x.begin(), x.end());
  reverse(y.begin(), y.end());
  reverse(z.begin(), z.end());
  while (true) {
    int vx = x.back();
    int vy = y.back();
    int vz = z.back();
    if (vx == inf && vy == inf && vz == inf) {
      break;
    }
    if (vx < vy && vx < vz) {
      res.push_back(x.back());
      x.pop_back();
      assert(x.back() != inf);
      res.push_back(x.back());
      x.pop_back();
    } else
    if (vy < vx && vy < vz) {
      res.push_back(y.back());
      y.pop_back();
      assert(y.back() != inf);
      res.push_back(y.back());
      y.pop_back();
    } else {
      res.push_back(z.back());
      z.pop_back();
      assert(z.back() != inf);
      res.push_back(z.back());
      z.pop_back();
    }
  }
  return res;
}

