#include <bits/stdc++.h>
#define ls (o << 1)
#define rs (o << 1 | 1)
#define mid ((L + R) >> 1)
using namespace std;
typedef long long LL;
const int N = 200500;
const int mod = 1e9 + 7;
int p[N], n, tr[N << 2][2];
void build(int o, int L, int R) {
	if (L + 1 == R) {
		tr[o][L & 1] = L;
		tr[o][R & 1] = n;
		return;
	}
	build(ls, L, mid);
	build(rs, mid, R);
	tr[o][0] = p[tr[ls][0]] < p[tr[rs][0]] ? tr[ls][0] : tr[rs][0];
	tr[o][1] = p[tr[ls][1]] < p[tr[rs][1]] ? tr[ls][1] : tr[rs][1];
}
pair<int, int> q(int o, int L, int R, int l, int r) {
	if (l <= L && R <= r) {
		return make_pair(tr[o][0], tr[o][1]);
	}
	if (l >= mid)
		return q(rs, mid, R, l, r);
	else if (r <= mid)
		return q(ls, L, mid, l, r);

	auto t1 = q(ls, L, mid, l, r);
	auto t2 = q(rs, mid, R, l, r);
	return make_pair(p[t1.first] < p[t2.first] ? t1.first : t2.first,
	                 p[t1.second] < p[t2.second] ? t1.second : t2.second);
}
void change(int o, int L, int R, int pos) {
	if (R - L == 1) {
		tr[o][L & 1] = n;
		return;
	}
	if (pos < mid)
		change(ls, L, mid, pos);
	else
		change(rs, mid, R, pos);
	tr[o][0] = p[tr[ls][0]] < p[tr[rs][0]] ? tr[ls][0] : tr[rs][0];
	tr[o][1] = p[tr[ls][1]] < p[tr[rs][1]] ? tr[ls][1] : tr[rs][1];
}
typedef pair<int, int> PII;
vector<PII> ans;
bool cmp(const PII &o, const PII &p) {
	return min(o.first, o.second) < min(p.first, p.second);
}
int cnt = 0;
void solve(int l, int r) {
	if (r - l == 0) return;
	while (1) {
		auto ret = q(1, 0, n, l, r);
		if (ret.first == n && ret.second == n) break;
		if (p[ret.first] < p[ret.second]) {
			if (ret.first + 1 == r ||
			    q(1, 0, n, ret.first + 1, r).second == n) {
				ans.push_back(make_pair(p[ret.second], p[ret.first]));
				change(1, 0, n, ret.first);
				change(1, 0, n, ret.second);
				solve(ret.second + 1, ret.first);
			} else {
				auto nxt = q(1, 0, n, ret.first + 1, r);
				ans.push_back(make_pair(p[ret.first], p[nxt.second]));
				change(1, 0, n, ret.first);
				change(1, 0, n, nxt.second);
				solve(ret.first + 1, nxt.second);
			}
		} else {
			if (ret.second + 1 == r ||
			    q(1, 0, n, ret.second + 1, r).first == n) {
				ans.push_back(make_pair(p[ret.first], p[ret.second]));
				change(1, 0, n, ret.first);
				change(1, 0, n, ret.second);
				solve(ret.first + 1, ret.second);
			} else {
				auto nxt = q(1, 0, n, ret.second + 1, r);
				ans.push_back(make_pair(p[ret.second], p[nxt.first]));
				change(1, 0, n, nxt.first);
				change(1, 0, n, ret.second);
				solve(ret.second + 1, nxt.first);
			}
		}
	}
}
