typedef pair<int , int> P;

int n;
vector<P> odd, even;

struct SEG{
	int na,m;
	P d[200000];
	SEG(int _n):m(_n){
		na=1;
		while(na<_n)na*=2;
		REP(i, 2*na -1)d[i]=MP(-INF, 0);
	}
	void update(int a, P v){
		a+=na-1;
		d[a]=v;
		while(a>0){
			a=(a-1)/2;
			d[a] = max(d[a*2+1], d[a*2+2]);
		}
	}
	P query(int a, int b){
		return _query(a, b, 0, 0, m);
	}
	P _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return MP(-INF, 0);
		if(a<=l && r <= b) return d[k];
		else{
			P vl = _query(a,b,k*2+1, l, (l+r)/2);
			P vr = _query(a,b,k*2+2, (l+r)/2,r);
			return max(vl, vr);
		}
	}
};

typedef pair<P, P> R;

int ans[200000];
int main() {
	cin >> n;
	SEG odd(n/2), even(n/2);
	REP(i,n/2){
		int a,b;
		cin >> a >> b;
		odd.update(i, MP(-a, i*2));
		even.update(i, MP(-b, i*2 + 1));
	}
	priority_queue<R> rs;
	rs.push(MP(odd.query(0,n/2), MP(0, n)));
	int j=0;
	REP(i, n/2){
		R pr = rs.top();rs.pop();
		P p = pr.first, r = pr.second;
		if(r.first%2){ // even
			P emin = p;
			P omin = odd.query((emin.second+2)/2, (r.second + 2)/2);
			ans[j++]=-emin.first;ans[j++]=-omin.first;
			if(r.first - emin.second < 0)rs.push(MP(even.query(r.first / 2, emin.second/2), MP(r.first, emin.second)));
			if(emin.second+1 - omin.second < 0)rs.push(MP(odd.query((emin.second+2)/2, omin.second/2), MP(emin.second+1, omin.second)));
			if(omin.second+1 - r.second < 0)rs.push(MP(even.query(omin.second/2, r.second/2), MP(omin.second+1, r.second)));
		}else{ // odd
			P omin = p;
			P emin = even.query(omin.second/2, r.second/2);
			ans[j++]=-omin.first;ans[j++]=-emin.first;
			if(r.first - omin.second < 0)rs.push(MP(odd.query(r.first / 2, omin.second/2), MP(r.first, omin.second)));
			if(omin.second+1 - emin.second < 0)rs.push(MP(even.query(omin.second/2, emin.second/2), MP(omin.second+1, emin.second)));
			if(emin.second+1 - r.second < 0)rs.push(MP(odd.query((emin.second+2)/2, r.second/2), MP(emin.second+1, r.second)));
		}
	}
	REP(i, n){
		cout << ans[i];
		if(i!=n-1)cout << " ";
	}
	cout << endl;
}

