    if (i % 2) {
      o[i / 2] = p;
    } else {
      e[i / 2] = p;
    }
    p0[p] = i;
  }

  int* ot = buildRMQ(o, N / 2);
  int* et = buildRMQ(e, N / 2);
  priority_queue<pair<int, pair<int, int> >,
                 vector<pair<int, pair<int, int> > >,
                 greater<pair<int, pair<int, int> > > >
      q;
  q.push(make_pair(minimum(0, N / 2 - 1, et, N / 2), make_pair(0, N)));

  bool first = true;
  for (;;) {
    if (q.empty())
      break;

    pair<int, pair<int, int> > top = q.top();
    int l = top.second.first, r = top.second.second;
    q.pop();

    int* let = l % 2 == 0 ? et : ot;
    int* lot = l % 2 == 0 ? ot : et;
    int d = l % 2 == 0 ? 0 : 1;

    int emin = minimum(l / 2, r / 2 - 1, let, N / 2);
    int epos = p0[emin];
    int omin = minimum(epos / 2 + d, r / 2 - 1 + d, lot, N / 2);
    int opos = p0[omin];

