      q.push(make_pair(minimum(l / 2, epos / 2 - 1, let, N / 2),
                       make_pair(l, epos)));
    }
    if (opos - epos > 1) {
      q.push(make_pair(minimum(epos / 2 + d, opos / 2 - 1 + d, lot, N / 2),
                       make_pair(epos + 1, opos)));
    }
    if (r - opos > 1) {
      q.push(make_pair(minimum((opos + 1) / 2, r / 2 - 1, let, N / 2),
                       make_pair(opos + 1, r)));
    }
  }
  cout << endl;
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 10 , inf = 1e9;

int n;
int num[N] , Map[N] , val[2][N*4];

void build(int x , int l , int r)
{
	if(l == r)
	{
		val[l & 1][x] = num[l];
		val[(l & 1)^1][x] = inf;
		return;
	}
	int mid = l + r >> 1;
	build(x<<1 , l  , mid);
	build(x<<1|1 , mid + 1 , r);
	val[0][x] = min(val[0][x<<1] , val[0][x<<1|1]);
	val[1][x] = min(val[1][x<<1] , val[1][x<<1|1]);
} 
void Build(){build(1 , 1 , n);}

int ask(int x , int l , int r , int L , int R , bool o)
{
	if(l >= L && r <= R)
		return val[o][x];
	int mid = l + r >> 1 , ans = inf;
	if(L <= mid) ans = min(ans , ask(x<<1 , l , mid , L , R , o));
	if(R > mid) ans = min(ans , ask(x<<1|1 , mid + 1 , r , L , R , o));
	return ans;
}
int Ask(int l , int r , bool o) {return ask(1 , 1 , n , l , r , o);}

struct Seg
{
	int l , r , val;
	bool operator< (const Seg &t) const
	{
		return val > t.val;
	}
	Seg(){}
	Seg(int l, int r) :l(l) , r(r)
	{
		val = Ask(l , r , l&1);
	}
};

priority_queue<Seg> q;

int main()
{
	scanf("%d" , &n);
	for(int i = 1 ; i <= n ; i ++)
	{
		scanf("%d" , num + i);
		Map[num[i]] = i;
	}
	Build();
	q.push(Seg(1 , n));
	while(!q.empty())
	{
		Seg now = q.top();
		q.pop();
		int l = Map[now.val];
		bool id = l & 1; 
		int r = Map[Ask(l + 1 , now.r , id^1)];
		printf("%d %d " , num[l] , num[r]);
		if(l != now.l)
			q.push(Seg(now.l , l - 1));
		if(r - l >= 2)
			q.push(Seg(l + 1 , r - 1));
		if(now.r != r)
			q.push(Seg(r + 1 , now.r));
	}
	puts("");
}

