int f(int p, int q) {
	int i;
	if (p > q) return p;
	for (i = 1; 1 << i <= q - p + 1; i++);
	i--;
	return mn(d[p][i], d[q - (1 << i) + 1][i]);
}

void add(int p, int q) {
	int x, y;
	if (p > q) return;
	x = f(p, q);
	y = mn(f(x + 1, q - 1), q);
	qu.push({x, y, p, q});
}

