template<class V, class Merge> struct SegmentTree {
  const int n;
  const V unit_value;
  vector<V> val;

  SegmentTree(int _n) : n(1 << (33-__builtin_clz(_n-1))), unit_value(Merge::unit()), val(n, unit_value) {}

  V get(int i) const { return val[i + n / 2]; }
  void set(int i, const V &v) { val[i + n / 2] = v; }

  void build() {
    for (int i = n / 2 - 1; i > 0; i--) val[i] = Merge::merge(val[i * 2 + 0], val[i * 2 + 1]);
  }

  void update(int i, const V &v) {
    i += n / 2;
    val[i] = v;
    while (i > 1) {
      i >>= 1;
      val[i] = Merge::merge(val[i * 2 + 0], val[i * 2 + 1]);
    }
  }

  V query(int l, int r) const {
    l = max(0, min(n / 2, l)) + n / 2;
    r = max(0, min(n / 2, r)) + n / 2;
    V ret = unit_value;
    for (; l < r; l >>= 1, r >>= 1) {
      if (l & 1) ret = Merge::merge(ret, val[l++]);
      if (r & 1) ret = Merge::merge(ret, val[--r]);
    }
    return ret;
  }
};
template <class V> struct MergeRangeMinQ {
  static V merge(const V &l, const V &r) { return l < r ? l : r; }
  static V unit() { return numeric_limits<V>::max(); }
};
template<class V> using SegTreeMin = SegmentTree<V, MergeRangeMinQ<V>>;

void Main() {
  int n = ri();
  vector<int> A(n);
  rep(i, n) A[i] = ri()-1;

  vi R(n);
  rep(i, n) R[A[i]] = i;

  SegTreeMin<int> segO(n);
  SegTreeMin<int> segE(n);

  rep(i, n) {
    (i % 2 ? segO : segE).set(i, A[i]);
  }

  segO.build();
  segE.build();

  priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> q;
  q.push({0, {0, n}});

  vi ans;

  while (!q.empty()) {
    int lef = q.top().snd.fst;
    int rig = q.top().snd.snd;
    q.pop();

    if (lef == rig) continue;

    auto &segA = lef % 2 ? segO : segE;
    auto &segB = lef % 2 ? segE : segO;

    int mi1 = segA.query(lef, rig);
    int p1 = R[mi1];
    int mi2 = segB.query(p1, rig);
    int p2 = R[mi2];

    ans.emplace_back(mi1+1);
    ans.emplace_back(mi2+1);

    q.push({segA.query(lef, p1), {lef, p1}});
    q.push({segB.query(p1+1, p2), {p1+1, p2}});
    q.push({segA.query(p2+1, rig), {p2+1, rig}});
  }
  rep(i, n) {
    cout << ans[i];
    if (i + 1 < n) cout << ' ';
    else cout << endl;
  }
}

signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  Main();
  return 0;
}

