void build(int i,int l,int r,int* a,SegmentTree tree[])
//void build(int i,int l,int r,int* a,)
{
    //printf("(%d,%d)\n",l,r);
    tree[i].l=l;
    tree[i].r=r;
    if(l==r)
    {
        tree[i].sum=a[++cnt];
        return;
    }
    int mid=(l+r)>>1;
    //printf("mid=%d\n",mid);
    build(i<<1,l,mid,a,tree);
