struct subarray{
    ll low;
    ll high;
    ll mid;
    ll midval;
    ll id;
    ll deftero;
    bool operator <(const subarray &a)const
    {
        if(deftero == a.deftero)
            return midval > a.midval;

        return deftero<a.deftero;
    }

};

ll n,k,ar[N];
pi seg[4*N][2];
vector < pi > res;

void build(ll low,ll high,ll pos)
{
    if(low == high)
    {
        seg[pos][low%2].first = ar[low];
        seg[pos][(low+1)%2].first = n+1;
        seg[pos][0].second = seg[pos][1].second = low;
        return;
    }

    ll mid = (low+high)/2;

    build(low,mid,pos*2+1);
    build(mid+1,high,pos*2+2);

    seg[pos][0] = min(seg[pos*2+1][0],seg[pos*2+2][0]);
    seg[pos][1] = min(seg[pos*2+1][1],seg[pos*2+2][1]);
    return;
}

pi query(ll low,ll high,ll pos,ll slow,ll shigh,ll id)
{
    if(slow>shigh)
        return mp(n+1,n+1);
    if(low >= slow && high <= shigh)
    {
        return seg[pos][id];
    }
    if(low > shigh || high < slow)
        return mp(n+1,n+1);

    ll mid = (low+high)/2;

    return min(query(low,mid,pos*2+1,slow,shigh,id),query(mid+1,high,pos*2+2,slow,shigh,id));
}

void solve()
{
    priority_queue < subarray > pq;
    subarray init = {0,n-1,query(0,n-1,0,0,n-1,0).second,query(0,n-1,0,0,n-1,0).first,0,0};

    pq.push(init);

    while(!pq.empty())
    {
        subarray cur = pq.top();
        pq.pop();

        cout << cur.midval << " ";
        //cout << cur.low << " " << cur.high << " " << cur.mid << " " << cur.id << endl;

        subarray neo = cur;
        neo.high = neo.mid-1;
        neo.mid = query(0,n-1,0,neo.low,neo.high,neo.id).second;
        neo.midval = query(0,n-1,0,neo.low,neo.high,neo.id).first;
        neo.deftero = 0;

        if(neo.high>=neo.low)
            pq.push(neo);

        neo = cur;
        neo.low = neo.mid+1;
        neo.id = !neo.id;
        neo.mid = query(0,n-1,0,neo.low,neo.high,neo.id).second;
        neo.midval = query(0,n-1,0,neo.low,neo.high,neo.id).first;
        neo.deftero = !neo.deftero;

        if(neo.high>=neo.low)
            pq.push(neo);
    }

    return;
}

