}
pair<int, int> get(int n,int l,int r,int s,int e,bool t){
	if(r < s || l > e) return{1e9, -1};
	else if(l >= s && r <= e) return seg[t][n];
	int mid=(l + r) / 2;
	pair<int, int> ret={ 1e9, -1 },li,ri;
	li=get(n * 2 + 1,l,mid,s,e,t);
	ri=get(n * 2 + 2,mid + 1,r,s,e,t);
	if(li.fi < ri.fi) ret.fi=li.fi, ret.se=li.se;
	else ret.fi=ri.fi, ret.se=ri.se;
	return ret;
}
