		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;
	}else{
		pii o = {0 , 0};

		int par = l % 2;
		o.fi = query(par , l , r + 1);

		int pos1 = pos[o.fi];
		o.se = query((pos1 + 1) % 2 , pos1 + 1 , r + 1);

		code[last] = o;
		rcode[o] = last;

		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;


		int pos2 = pos[o.se];

	//	modify(pos1 % 2 , pos1 , INF);
	//	modify(pos2 % 2 , pos2 , INF);

		solve(p , pos1 + 1 , pos2 - 1 , prev);
		solve(p , l , pos1 - 1 , prev);
		solve(p , pos2 + 1 , r  , prev);

	}
}

vi restore(){
	vi res;
	priority_queue<pii , vector<pii> , greater<pii>> q; 
	q.push(code[0]);

	while(!q.empty()){
		pii u = q.top();
		q.pop();

		res.pb(u.fi);
		res.pb(u.se);

		for(int c : g[rcode[u]]){
			q.push(code[c]);
		}
	}
	return res;
}

