Node* buildTree(int l,int r){
	Node* x = new Node();
	x->l=l;
	x->r=r;
	x->val=inf;
	if(l!=r){
		x->lf = buildTree(l,(l+r)/2);
		x->rg = buildTree((l+r)/2+1,r);
	}
	return x;
}
void setVal(Node* curr,int pos,int val){
	if(curr->l>pos) return;
	if(curr->r<pos) return;
	if(curr->l==pos && curr->r==pos){
		curr->val = val;
	}else{
		setVal(curr->lf,pos,val);
		setVal(curr->rg,pos,val);
		curr->val = min(curr->lf->val,curr->rg->val);
	}
}

int getMin(Node* curr,int l,int r){
	if(curr->l>r) return inf;
	if(curr->r<l) return inf;
	if(l<=curr->l && curr->r<=r) return curr->val;
	return min(getMin(curr->lf,l,r),getMin(curr->rg,l,r));
}

void swapTrees(Node* t1, Node* t2, int l, int r){
	if(t1->l==t1->r)return;
	if(t1->l > r) return;
	if(t1->r < l) return;

	if(l<=t1->lf->l && t1->lf->r<=r){
		swap(t1->lf,t2->lf);
	}else swapTrees(t1->lf,t2->lf,l,r);

	if(l<=t1->rg->l && t1->rg->r<=r){
		swap(t1->rg,t2->rg);
	}else swapTrees(t1->rg,t2->rg,l,r);

	t1->val = min(t1->lf->val,t1->rg->val);
	t2->val = min(t2->lf->val,t2->rg->val);
}

