vector<P> calc(int l, int r,SegmentTree<P>&even,SegmentTree<P>&odd) {
	//pe(l); print(r);
	int k1 = l, k2 = r - 1;
	vector<P>ret;
	if (l + 1 >= r)return ret;
	if (l % 2 == 0) {
		P fi = even.query(l, r);
		k1 = fi.second;
		P se = odd.query(k1, r);
		k2 = se.second;
		ret.push_back({ fi.first,se.first });
	}
	else {
		P fi = odd.query(l, r);
		k1 = fi.second;
		P se = even.query(k1, r);
		k2 = se.second;
		ret.push_back({ fi.first,se.first });
	}
	vector<P>v1 = calc(l, k1,even,odd);
	vector<P>v2 = calc(k1 + 1, k2, even, odd);
	vector<P>v3 = calc(k2 + 1, r,even,odd);
	v1.push_back({ 1e9,1e9 });
	v2.push_back({ 1e9,1e9 });
	v3.push_back({ 1e9,1e9 });
	VREVERSE(v1); VREVERSE(v2); VREVERSE(v3);
	while (true) {
		if (v1.back() < v2.back()&&v1.back() < v3.back()) {
			P res = v1.back();
			if (res.first == 1e9)break;
			ret.push_back(res);
			v1.pop_back();
		}
		else if (v2.back() < v3.back()&&v2.back()< v1.back()) {
			P res = v2.back();
			if (res.first == 1e9)break;
			ret.push_back(res);
			v2.pop_back();
		}
		else {
			P res = v3.back();
			if (res.first == 1e9)break;
			ret.push_back(res);
			v3.pop_back();
		}
	}
	return ret;
}
void solve() {
	int N; cin >> N;
	auto f = [](P a, P b) {return min(a,b); };
	SegmentTree<P>even(N, { 1e9,1e9 }, f), odd(N, { 1e9,1e9 }, f);
	vector<int>v(N);
