template <class T>
struct segment_tree{
    using func = function< T(T, T) >;
    int size;
    T ide;
    vector<T> data, sub;
    func f = [](T a, T b){ return ((a<b)?a:b); };
    segment_tree(){}
    segment_tree(int n, T ide){
        init(n, ide);
    }

    void init(int n, T ide){
        size = 1;
        while(size < n) size *= 2;
        this->ide = ide;
        data.assign(size*2, ide);
        sub.assign(size*2, ide);
    }

    // data[x] <- y
    void update(int x, T y){
        x += size;
        data[x] = y;
        while(x > 0){
            x /= 2;
            data[x] = f(data[x*2], data[x*2+1]);
        }
    }

    // return the answer for [x, y]
    T query(int x, int y){
        T res = ide;
        x += size;
        y += size;
        while(x <= y){
            if(x%2 == 1) res = f(res, data[x++]);
            if(y%2 == 0) res = f(res, data[y--]);
            x >>= 1;
            y >>= 1;
        }
        return res;
    }
};

int main(void){
    int n;
    cin >> n;
    vector< int > pos(n+1, 0);
    segment_tree<int> st[2];
    st[0].init(n+1, n+1);
    st[1].init(n+1, n+1);
    for(int i=1;i<=n;i++){
        int p;
        cin >> p;
        st[i%2].update(i, p);
        pos[p] = i;
    }

    vector<int> ans;
    priority_queue<S, vector<S>, greater<S> > q;

    function< void(int, int) > ins = [&](int l, int r){
        int x = st[l%2].query(l, r);
        q.push(S(x, l, r));
    };

    ins(1, n);
    while(!q.empty()){
        S s = q.top();
        q.pop();
        int x = get<0>(s);
        int l = get<1>(s);
        int r = get<2>(s);
        int y = st[r%2].query(pos[x], r);
        ans.push_back(x);
        ans.push_back(y);
        if(l < pos[x]) ins(l, pos[x]-1);
        if(pos[x]+1 < pos[y]) ins(pos[x]+1, pos[y]-1);
        if(pos[y] < r) ins(pos[y]+1, r);
    }

    for(int v: ans) cout << v << " ";
    cout << endl;
}

