		for(int i=1;i<=n;i++)ST[0][i]=i;
		for(int l=2,i=1;l<=n;l<<=1,i++)for(int j=1;j<=n-l+1;j++)
			ST[i][j]=min(ST[i-1][j],ST[i-1][j+(l>>1)]);
