int solve(ST_list*a,ST_list*b,int l,int r,bool k){
	int x=a->min(l-k,r-k),y=b->min(x+k,r);
	int p=++m;id[p]={a->va[x],b->va[y]};
	if(l<=x-!k)e[p].pb(solve(a,b,l,x-!k,k));
	if(x+1<=y-k)e[p].pb(solve(b,a,x+1,y-k,k^1));
	if(y+1<=r)e[p].pb(solve(a,b,y+1,r,k));
	return p;
}

