const int MAX = 1 << 20,MAXLG = 20;
int sparse[2][MAX][MAXLG],lg[MAX];

int A[1 << 20],n;
int couple[MAX];

void build(int sparse[MAX][MAXLG],int t){
	lg[0] = -1;
	loop(i,MAX-1) lg[i + 1] = lg[i] + ((i + 1) == LSOne(i+1));
	loop(i,n) sparse[i][0] = (i%2 == t) ? A[i] : INT_MAX;
	loop(k,MAXLG-1) loop(i,n){
		int j = i + (1 << k);
		if(j >= n) j = i;
		sparse[i][k + 1] = min(sparse[i][k],sparse[j][k]);
	}
}

int RMQ(int a,int b,int sparse[MAX][MAXLG]){
	int l = lg[b - a + 1];
	return min(sparse[a][l],sparse[b - (1 << l) + 1][l]);
}


int get_cutpoint(int l,int r){
	if(l+1==r) return l+1;
	if(A[l + 1] < RMQ(l+3,r,sparse[1 - l%2])) return l+1;
	int s = 1,e = (r - l + 1)/2 - 1;
	while(s < e) {
		int m = s + (e - s + 1)/2;
		int pos = l + m*2 + 1;
		if(A[l + 1] < RMQ(pos,r,sparse[1 - l%2])) e = m-1;
		else s = m;
	}
	return l + s*2 + 1;
}

int get_pivot(int l,int r){
	int s = 0,e = (r - l + 1)/2 - 1;
	while(s < e){
		int m = s + (e - s + 1)/2;
		if(RMQ(l,r,sparse[l%2]) == RMQ(l + 2*m,r,sparse[l%2])) s = m;
		else e = m-1;
	}
	return l + 2*s;
}

deque<int> solve(int s,int e){
	int l = e - s + 1;
	assert(l%2 == 0);
	deque<int> dq;
	if(l == 0) return dq;
	if(l == 2) {
		dq.push_back(A[s]);
		dq.push_back(A[e]);
	}
	else{
		int pivot = get_pivot (s,e);
		int cutpoint = get_cutpoint(pivot,e);
	//	cerr << s << " " << e << " -> " << pivot << " " << cutpoint << endl;
		deque<int> B [3] = {solve(s,pivot - 1),solve(pivot + 1,cutpoint - 1),
				solve(cutpoint + 1,e)};
		dq.push_back(A[pivot]);
		dq.push_back(A[cutpoint]);
		int ctr = e - s + 1 - 2;
		loop(i,3) B[i].pb(INT_MAX);
		while(ctr) {
			bool choice = 0;
			loop(i,3) if(B[i].front() < B[choice].front()) {
				choice = i;
			}
			dq.push_back(B[choice].front());
			B[choice].pop_front();
			dq.push_back(B[choice].front());
			B[choice].pop_front();
			ctr -= 2;
		}
	}
//	cerr << s <<  " " << e << endl;
//	print(dq,int);
	return dq;
}

int main(){
	scanf("%d",&n);
	loop(i,n) scanf("%d",A + i);
	build(sparse[1],1);
	build(sparse[0],0);

	deque<int> dq = solve(0,n-1);
	//print(dq,int);
	loop(i,n) printf("%d%c",dq[i]," \n"[i==n-1]);
	return 0;
}

