    auto g = [](PL a, PL b) { return b; };
    using seg = SegmentTree<PL, PL>;
    vector<seg> segs(2, seg(N + 1, f, g, e1, VPL(N + 1, e1)));
    REP(i, N) { segs[i % 2].update(i, {p[i], i}); }
    auto dfs = fix([&](auto f, int l, int r, int idx) -> void {
        if(l + 2 > r) return;
        PL p = segs[l % 2].query(l, r);
        PL q = segs[(l % 2) ^ 1].query(l, r);
        ll lr = p.se;
        ll rl = q.se;

        G[idx].emplace_back(p.fi);
        pa[p.fi] = q.fi;

        if(lr != l) f(f, l, lr, p.fi);
        if(lr + 1 != rl) f(f, lr + 1, rl, p.fi);
        if(rl + 1 != r) f(f, rl + 1, r, p.fi);
    });
    dfs(0, N, 0);
    VL ans;
    PQG<ll> pq;
    pq.push(G[0].front());
    while(pq.size()) {
        ll t = pq.top();
        pq.pop();

        ans.emplace_back(t);
        ans.emplace_back(pa[t]);

        FOREACH(to, G[t]) pq.push(to);
    }
    FOREACH(a, ans) a++;
    Printv(ans);
}

