typedef pair<int, int> pii;

const int MX = 200005;

struct ITV
{
	pii v, p;

	ITV (const pii &v0, const pii &p0) : v(v0), p(p0) {}

	bool operator < (const ITV &t) const {return v > t.v;}
};

struct NODE
{
	int v, p;

	NODE (const int &v0 = 0, const int &p0 = 0) : v(v0), p(p0) {}

	NODE operator + (const NODE &t) {return (v<t.v) ? *this : t;}
};

struct SEGT
{
	#define ls (a<<1)
	#define rs (a<<1|1)
	#define mid ((l+r)>>1)

	NODE t[2][MX*4];

	void upd(int a)
	{
		t[0][a] = t[0][ls] + t[0][rs];
		t[1][a] = t[1][ls] + t[1][rs];
	}

	void build(int a, int l, int r, int *s)
	{
		if(l == r)
		{
			if(l&1) t[1][a] = NODE(s[l], l), t[0][a] = NODE(+MX, 0);
			else t[0][a] = NODE(s[l], l), t[1][a] = NODE(+MX, 0);
		}
		else build(ls, l, mid, s), build(rs, mid+1, r, s), upd(a);
	}

	NODE qur(int a, int l, int r, int ql, int qr, int p)
	{
		if(ql<=l && r<=qr) return t[p][a];
		else if(ql>r || qr<l) return NODE(+MX, 0);
		else return qur(ls, l, mid, ql, qr, p) + qur(rs, mid+1, r, ql, qr, p);
	}

	#undef ls
	#undef rs
	#undef mid
} T;

int n;
int seq[MX];

pii best_pair(int l, int r)
{
	NODE nl = T.qur(1, 1, n, l, r-1, l&1);
	NODE nr = T.qur(1, 1, n, nl.p+1, r, (nl.p+1)&1);
	return make_pair(nl.p, nr.p);
}

void work()
{
	priority_queue<ITV> que;
	pii ini = best_pair(1, n);
	que.push(ITV(make_pair(seq[ini.first], seq[ini.second]), make_pair(1, n)));
	while(que.size())
	{
		ITV x = que.top();
		que.pop();
		printf("%d %d ", x.v.first, x.v.second);
		pii d = best_pair(x.p.first, x.p.second);
		if(x.p.first < d.first)
		{
			pii t = best_pair(x.p.first, d.first-1);
			que.push(ITV(make_pair(seq[t.first], seq[t.second]), make_pair(x.p.first, d.first-1)));
		}
		if(d.second - d.first > 2)
		{
			pii t = best_pair(d.first+1, d.second-1);
			que.push(ITV(make_pair(seq[t.first], seq[t.second]), make_pair(d.first+1, d.second-1)));
		}
		if(d.second < x.p.second)
		{
			pii t = best_pair(d.second+1, x.p.second);
			que.push(ITV(make_pair(seq[t.first], seq[t.second]), make_pair(d.second+1, x.p.second)));
		}
	}
}

