            if(mi1 < mi2){
                // cout << "mi1" << ' ' << mi1 << endl;
                if(l < f[mi1]-1)dfs(0, l, f[mi1]-1, -1, par);
                dfs(1,f[mi1]+1,r,mi1, par);
            }else{
                if(f[mi2]+1<r)dfs(0,f[mi2]+1,r,-1, par);
                dfs(2,l,f[mi2]-1,mi2, par);
            }
        }else{
            int mi1 = query_odd((l-1)/2, r/2-1+1, 0, 0, n/2);
            int mi2 = query_even((l-1)/2+1, r/2+1, 0, 0, n/2);
            if(mi1 < mi2){
                if(l < f[mi1]-1)dfs(0, l, f[mi1]-1, -1, par);
                dfs(1,f[mi1]+1,r,mi1, par);
            }else{
                if(f[mi2]+1 < r)dfs(0,f[mi2]+1,r,-1, par);
                dfs(2,l,f[mi2]-1,mi2, par);
            }
        }
    }
    if(query == 1){ // 後ろ探し.
        if(l % 2 == 1){
            int mi = query_odd((l-1)/2, (r-1)/2+1, 0, 0, n/2);
            ans.push_back(P(x,mi));
            count_++;
            G[par].push_back(count_);
            if(l < f[mi]-1)dfs(0, l, f[mi]-1, -1, count_);
            if(f[mi]+1 < r)dfs(0, f[mi]+1, r, -1, par);
        }else{
            int mi = query_even(l/2, r/2+1, 0, 0, n/2);
            ans.push_back(P(x,mi));
            count_++;
            G[par].push_back(count_);
            if(l < f[mi]-1)dfs(0, l, f[mi]-1, -1, count_);
            if(f[mi]+1 < r)dfs(0, f[mi]+1, r, -1, par);
        }
    }
    if(query == 2){ // 前探し.
        if(l % 2 == 0){
            int mi = query_even(l/2, r/2+1, 0, 0, n/2);
            ans.push_back(P(mi,x));
            count_++;
            int count__ = count_;
            G[par].push_back(count_);
            if(l < f[mi]-1)dfs(0, l, f[mi]-1, -1, par);
            if(f[mi]+1 < r)dfs(0, f[mi]+1, r, -1, count__);
        }else{
            int mi = query_odd((l-1)/2, (r-1)/2+1, 0, 0, n/2);
            ans.push_back(P(mi,x));
            count_++;
            int count__ = count_;
            G[par].push_back(count_);
            if(l < f[mi]-1)dfs(0, l, f[mi]-1, -1, par);
            if(f[mi]+1 < r)dfs(0, f[mi]+1, r, -1, count__);
        }
    }
}

