void build(int v, int tl, int tr) {
    if (tl == tr) {
        for (int t = 0; t < 2; ++t) {
            if (t == (tl&1)) {
                tree[v][t] = mp(a[tl], tl);
            }   
            else {
                tree[v][t] = mp(INF, INF);
            }   
        }   
        return;
    }
    int tm = (tl + tr) >> 1;
    build(v * 2 + 1, tl, tm);
    build(v * 2 + 2, tm + 1, tr);
    for (int t = 0; t < 2; ++t)
        tree[v][t] = min(tree[v*2+1][t], tree[v*2+2][t]);
}   
ii get(int v, int tl, int tr, int l, int r, int t) {
    if (tr < l || r < tl)
        return mp(INF, INF);
    if (l <= tl && tr <= r)
        return tree[v][t];
    int tm = (tl + tr) >> 1;
    return min(get(v*2+1,tl,tm,l,r,t),get(v*2+2,tm+1,tr,l,r,t));
}   

