template <class DatTp, class Comp = std::less<DatTp> >
struct static_rmq{
	typedef unsigned long long ull;
	typedef unsigned size_type;

	std::vector<DatTp> data;
	Comp cmp;
	std::vector<std::vector<size_type> > sp_rmq;
	std::vector<ull> bl_tort;

	explicit static_rmq(const Comp &comp = Comp()) : cmp(comp) {}

	template <class Iter>
	static_rmq(Iter beg, Iter en, const Comp &comp = Comp()) : cmp(comp) {
		init(beg, en);
	}

	template <class Iter>
	void init(Iter beg, Iter en){
		sp_rmq.clear();
		bl_tort.clear();
		data.assign(beg, en);
		size_type sz = size();
		if(!sz){ return; }

		size_type sp_len = sz / 64;
		sp_rmq.reserve(64 - __builtin_clzll(sp_len | 1));

		std::vector<size_type> vec(sp_len);
		for(size_type i = 0; i < sp_len; ++i){
			size_type t = i * 64;
			for(size_type j = t + 1; j < (i + 1) * 64; ++j){
				t = minidx(t, j);
			}
			vec[i] = t;
		}
		sp_rmq.push_back(vec);

		for(size_type i = 1; (1u << i) <= sp_len; ++i){
			vec.clear();
			size_type r = (1u << (i - 1));
			std::vector<size_type> &prv = sp_rmq.back();
			for(size_type j = 0; j + r * 2 <= sp_len; ++j){
				vec.push_back(minidx(prv[j], prv[j + r]));
			}
			sp_rmq.push_back(vec);
		}

		bl_tort.assign(sz, 0ull);
		std::vector<size_type> st;
		st.reserve(64);
		for(size_type low = 0; low < sz; low += 64){
			size_type high = std::min<size_type>(low + 64, sz);
			ull val = 0;
			st.clear();
			for(size_type j = high; j-- != low; ){
				while(!st.empty()){
					size_type tp = st.back();
					if(cmp(data[tp], data[j])){ break; }
					val ^= 1ull << (tp % 64);
					st.pop_back();
				}
				st.push_back(j);
				val |= 1ull << (j % 64);
				bl_tort[j] = val;
			}
		}
	}

	size_type size() const{ return data.size(); }

	size_type minidx(size_type i, size_type j) const{
		if(i > j){ std::swap(i, j); }
		// if(j >= size()){ return i; }
		return !cmp(data[j], data[i]) ? i : j;
	}

	const DatTp& operator[] (size_type i) const{
		return data[i];
	}

	// [lt, rt]
	size_type operator() (size_type lt, size_type rt) const{
		if(lt > rt){ return lt; }
		size_type bl_lt = lt / 64, bl_rt = rt / 64;
		size_type ret;
		ull rtmask = ((2ull << (rt % 64)) - 1);
		if(bl_lt == bl_rt){
			ull bit = bl_tort[lt] & rtmask;
			size_type k = 63 - __builtin_clzll(bit);
			ret = bl_lt * 64 + k;
		}
		else{
			ret = bl_lt * 64 + 63 - __builtin_clzll(bl_tort[lt]);
			if(bl_lt + 1 != bl_rt){
				size_type numblk = bl_rt - bl_lt - 1;
				size_type k = 63 - __builtin_clzll(numblk);
				size_type cand1 = sp_rmq[k][bl_lt + 1];
				ret = minidx(ret, cand1);
				if((1u << k) != numblk){
					size_type cand2 = sp_rmq[k][bl_rt - (1u << k)];
					ret = minidx(ret, cand2);
				}
			}
			size_type cand3 = bl_rt * 64 + 63 - __builtin_clzll(bl_tort[bl_rt * 64] & rtmask);
			ret = minidx(ret, cand3);
		}
		return ret;
	}
};

typedef tuple<int,int,int,int> ti4;

vector<int> p;
priority_queue<ti4> pq;
static_rmq<int> rmqodd, rmqeven;
vector<int> inv;

void add(int lt, int rt){
	if(lt > rt){ return; }
	int idx1 = (lt & 1 ? rmqodd : rmqeven)(lt, rt - 1);
	int idx2 = (rt & 1 ? rmqodd : rmqeven)(idx1 + 1, rt);
	pq.emplace(-p[idx1], -p[idx2], lt, rt);
}

