Pair query1(int cur,int left,int right)
{
	//cout<<cur<<' '<<tree1[cur].left<<' '<<tree1[cur].right<<endl;
	if (left<=tree1[cur].left && tree1[cur].right<=right)
		return mp(tree1[cur].minn,tree1[cur].min_pos);
	int mid=(tree1[cur].left+tree1[cur].right)>>1;
	Pair res1=mp(INF,INF),res2=mp(INF,INF);
	if (left<=mid) res1=query1(cur*2,left,right);
	if (mid+1<=right) res2=query1(cur*2+1,left,right);
	if (res1.x<res2.x) return res1; else return res2;
}

Pair query2(int cur,int left,int right)
