struct node {
  int l, r, m1, m2, v1, v2;
  bool operator < (const node d) const { return v1 > d.v1;}
};

node getNode(int l, int r) {
  // cout << "l:" << l << " r:" << r << endl;
  int m1, m2;
  if(l%2) {
    m1 = seg[1].query(l, r).second;
    m2 = seg[0].query(m1+1, r).second;
  } else {
    m1 = seg[0].query(l, r).second;
    m2 = seg[1].query(m1+1, r).second;
  }
  // cout << l << " " << r << " " << m1 << " " << m2 << endl;
  return (node){l, r, m1, m2, p[m1], p[m2]};
}

