pi mn(pi a, pi b){
    if(a.x<b.x) return a;
    else return b;
}

void Upd1(int nod, int l, int r, int pos, int val){
    if(l>pos || r<pos) return;
    if(l==r){
        b1[nod]={val,pos};
        return;
    }
    int mid=(l+r)/2;
    Upd1(2*nod,l,mid,pos,val);
    Upd1(2*nod+1,mid+1,r,pos,val);
    b1[nod]=mn(b1[2*nod],b1[2*nod+1]);
}

pi Qry1(int nod, int l, int r, int lt, int rt){
    if(l>rt || r<lt) return {1e9,1e9};
    if(l>=lt && r<=rt) return b1[nod];
    int mid=(l+r)/2;
    return mn(Qry1(2*nod,l,mid,lt,rt),Qry1(2*nod+1,mid+1,r,lt,rt));
}

void Upd2(int nod, int l, int r, int pos, int val){
    if(l>pos || r<pos) return;
    if(l==r){
        b2[nod]={val,pos};
        return;
    }
    int mid=(l+r)/2;
    Upd2(2*nod,l,mid,pos,val);
    Upd2(2*nod+1,mid+1,r,pos,val);
    b2[nod]=mn(b2[2*nod],b2[2*nod+1]);
}

pi Qry2(int nod, int l, int r, int lt, int rt){
    if(l>rt || r<lt) return {1e9,1e9};
    if(l>=lt && r<=rt) return b2[nod];
    int mid=(l+r)/2;
    return mn(Qry2(2*nod,l,mid,lt,rt),Qry2(2*nod+1,mid+1,r,lt,rt));
}

pi Find(int l, int r, int p){
    if(p){
        pi x=Qry1(1,1,n,l,r);
        pi y=Qry2(1,1,n,x.second+1,r);
        pi t,g={x.first,y.first};
        if(x.second-1>=l) t=Find(l,x.second-1,p), m[g].push_back(t);
        if(y.second-1>=x.second+1) t=Find(x.second+1,y.second-1,!p), m[g].push_back(t);
        if(r>=y.second+1) t=Find(y.second+1,r,p), m[g].push_back(t);
        return g;
    }
    else{
        pi x=Qry2(1,1,n,l,r);
        pi y=Qry1(1,1,n,x.second+1,r);
        pi t,g={x.first,y.first};
        if(x.second-1>=l) t=Find(l,x.second-1,p), m[g].push_back(t);
        if(y.second-1>=x.second+1) t=Find(x.second+1,y.second-1,!p), m[g].push_back(t);
        if(r>=y.second+1) t=Find(y.second+1,r,p), m[g].push_back(t);
        return g;
    }
}


