#define PI 3.1415926535897932384626433
using namespace std;
int n;
int a[200005] = {},loc[200005];
int r[2][100005][20] = {};

int marg(int x,int y){
	if(x > n)return y;
	return (a[x] < a[y]?x:y);
}

int query(int l, int nd){
	int e = l&1;
	int res = MOD;
	int d = (nd - l)/2 + 1;
	l>>=1;
	cd(i,20,0){
		if((d>>i)&1){
			res = marg(res, r[e][l][i]);
			l = l + (1 << i);
		}
	}
	return res;
}

pair<pii,pii> solve(int l, int r){
	assert((r-l)&1);
	int f = query(l,r);
	int s = query(f+1,r);
	return {{a[f],a[s]},{l,r}};
}

int main(){
	fast_io();
	cin >> n;
	cu(i,0,n){
		cin >> a[i];
		loc[a[i]] = i;
		r[i&1][i>>1][0] = i;
	}
	cu(e,0,2){
		cu(p,1,20){
			cu(i,0,n>>1){
				if(i + (1 << p) > n/2)continue;
				r[e][i][p] = marg(r[e][i][p-1], r[e][i + (1 << (p-1))][p-1]);				
			}
		}
	}
	priority_queue<pair<pii,pii>, vector<pair<pii,pii>>, greater<pair<pii,pii>>> pq;
	pq.push(solve(0,n-1));
	while(pq.size()){
		pair<pii,pii> cur = pq.top();pq.pop();
		cout << cur.F.F << ' ' << cur.F.S << ' '; 	
		int l = cur.S.F;
		int nd = cur.S.S;
		int f = loc[cur.F.F];
		int s = loc[cur.F.S];
		if(l < f - 1)pq.push(solve(l,f-1));
		if(f + 1 < s - 1)pq.push(solve(f+1,s-1));
		if(s + 1 < nd)pq.push(solve(s+1,nd));
	}cout << '\n';
}

