	qu.push(Pi(ans[0],0));
	while(!qu.empty()){
		auto it = qu.top(); qu.pop();
		printf("%s%d %d", (it.second ? " " : ""), it.first.first, it.first.second);
		for(auto t: ch[it.second]) qu.push(Pi(ans[t],t));
	}
	puts("");
}

