vector<int> q;
vector<pair<int, int>> pairs;

pair<int, int> searchRange(vector<int> v){
	int st = v[0],
		ed = v[1],
		stp = 0,
		edp = 1;

	for(int i=2; i<v.size(); i+=2)
		if(st > v[i]){
			st = v[i];
			stp = i;
		}

	for(int i=stp+1; i<v.size(); i+=2)
		if(ed > v[i]){
			ed = v[i];
			edp = i;
		}

	return make_pair(stp, edp);
}


void put(vector<int> tmp){
	if(tmp.empty()) return;
	auto pair = searchRange(tmp);

	pairs.push_back(make_pair(tmp[pair.first],tmp[pair.second]));

	tmp.erase(tmp.begin() + pair.first);
	tmp.erase(tmp.begin() + pair.second-1);
	put(tmp);
}
