template<typename M,typename N=M>struct SegmentTree{
   using F=function<M(M,M)>; using G=function<M(M,N)>;
   int sz; vector<M> data; const F f; const G g; const M m1;
   SegmentTree(int n,const F f,const G g,const M &m1):f(f),g(g),m1(m1){
      sz=1; while(sz<n)sz<<=1; data.assign(2*sz,m1);
   }
   void build(vector<M> v){
      rep(i,0,v.size())data[i+sz]=v[i];
      for(int k=sz-1;k>0;k--)data[k]=f(data[2*k],data[2*k+1]);
   }
   void update(int k,const N &x){
      k+=sz; data[k]=g(data[k],x);
      while(k>>=1)data[k]=f(data[2*k],data[2*k+1]);
   }
   M query(int a,int b){
      M L=m1,R=m1;
      for(a+=sz,b+=sz;a<b;a>>=1,b>>=1){
         if(a&1)L=f(L,data[a++]);
         if(b&1)R=f(data[--b],R);
      } return f(L,R);
   }
   M operator[](const int &k)const{return data[k+sz];}
};

typedef pair<int,int> P;
typedef pair<int,P> T;

int main(){
   int n; cin>>n;
   vector<int> a(n); rep(i,0,n)cin>>a[i];
   SegmentTree<P> even(n,
   [](P a,P b){return min(a,b);},
   [](P a,P b){return b;},{inf,inf}),
   odd(n,[](P a,P b){return min(a,b);},
   [](P a,P b){return b;},{inf,inf});
   rep(i,0,n){
      if(i&1)odd.update(i,{a[i],i});
      else even.update(i,{a[i],i});
   }
   priority_queue<T,vector<T>,greater<T>> pq;
   auto push=[&](int lb,int rb){
      if(lb==rb)return;
      pq.push({(lb&1?odd.query(lb,rb):even.query(lb,rb)).first,{lb,rb}});
   };
   push(0,n); vector<int> res;
   while(!pq.empty()){
      auto [tmp,p]=pq.top(); pq.pop();
      int lb=p.first,rb=p.second;
      int i1=(lb&1?odd.query(lb,rb):even.query(lb,rb)).second;
      int i2=(lb&1?even.query(i1,rb):odd.query(i1,rb)).second;
      res.push_back(a[i1]); res.push_back(a[i2]);
      push(lb,i1); push(i1+1,i2); push(i2+1,rb);
   }
   rep(i,0,n)cout<<res[i]<<" ";
   return 0;
}

