#define si(n) fscanf(in,"%d",&n)
#define NM 100005
#define MOD 1000000007
#define INF 0x7fffffff
//FILE *in=fopen("input.txt","r"), *out = fopen("output.txt", "w");
FILE *in = stdin, *out = stdout;
using namespace std;

#include <deque>

typedef pair<int, int> pii;
int n, B, a[NM * 2], Otree[NM * 8], Etree[NM * 8], inv[NM * 2], T;
deque<pii> dq[NM * 4];
struct TREE {
	int a, b;
	int l, r;
	TREE() { a = INF, b = INF; }
	TREE(int a, int b) :a(a), b(b) { l = 0; r = 0; }
}ans[NM * 4];
void input() {
	si(n);
	FOR(i, 1, n) si(a[i]), inv[a[i]] = i;
	B = 1;
	while (B < n) B <<= 1;
	B--;
}
void Update(int tree[], int idx, int cnt) {
	idx += B; tree[idx] = cnt; idx >>= 1;
	while (idx) tree[idx] = min(tree[idx * 2], tree[idx * 2 + 1]), idx >>= 1;
}
int Get(int tree[], int l, int r) {
	l += B, r += B;
	int res = INF;
	while (l <= r) {
		if (l & 1) res = min(res, tree[l]), l++;
		if (!(r & 1)) res = min(res, tree[r]), r--;
		l >>= 1, r >>= 1;
	}
	return res;
}
void pro(int L, int R) {
	if (L > R) return;
	int p = min(Get(Etree, L, R), Get(Otree, L, R));
	if (p == INF) return;
	int pidx = inv[p];
	if (pidx & 1) Update(Otree, pidx, INF);
	else Update(Etree, pidx, INF);

	int q, qidx;
	if (pidx & 1) q = Get(Etree, L, R);
	else q = Get(Otree, L, R);
	qidx = inv[q];
	if (qidx & 1) Update(Otree, qidx, INF);
	else Update(Etree, qidx, INF);

	if (pidx > qidx) swap(p, q), swap(pidx, qidx);
	int cur = T;
	ans[cur] = TREE(p, q);
	ans[cur].l = ++T;
	pro(pidx + 1, qidx - 1);
	if (pidx == L && qidx == R) return;
	if (pidx == L) L = qidx + 1;
	if (qidx == R) R = pidx - 1;
	ans[cur].r = ++T;
	pro(L, R);
}
void print(int idx) {
	if (ans[idx].a == INF) return;
	//fprintf(out, "%d %d ", ans[idx].a, ans[idx].b);
	int l = ans[idx].l, r = ans[idx].r;
	print(l), print(r);
	dq[idx].push_back({ ans[idx].a, ans[idx].b });
	while (!dq[l].empty() && !dq[r].empty()) {
		if (min(dq[l].front().first, dq[l].front().second) < min(dq[r].front().first, dq[r].front().second))
			dq[idx].push_back(dq[l].front()), dq[l].pop_front();
		else
			dq[idx].push_back(dq[r].front()), dq[r].pop_front();
	}
	while (!dq[l].empty()) dq[idx].push_back(dq[l].front()), dq[l].pop_front();
	while (!dq[r].empty()) dq[idx].push_back(dq[r].front()), dq[r].pop_front();
}
int main() {
	input();
	FOR(i, 1, B * 2 + 1) Etree[i] = Otree[i] = INF;
	FOR(i, 1, n)
		if (i & 1) Update(Otree, i, a[i]);
		else Update(Etree, i, a[i]);
	T = 1;
	pro(1, n);
	print(1);
	while (!dq[1].empty()) {
		fprintf(out, "%d %d ", dq[1].front().first, dq[1].front().second);
		dq[1].pop_front();
	}
	return 0;
}

