typedef pair<int,int> pii;

#define MAXN    200001

int bp[MAXN];
int p[MAXN];
int ap[MAXN];
struct node_t
{
    int l, r;
    int m[2];
};
node_t nodes[MAXN<<2];
int mymin(int a, int b)
{
    return (p[a]<p[b])?a:b;
}
node_t merge(node_t a, node_t b)
{
    node_t ans;
    ans.l = a.l; ans.r = b.r;
    ans.m[0] = mymin(a.m[0], b.m[0]);
    ans.m[1] = mymin(a.m[1], b.m[1]);
    return ans;
}

int N;
int q[MAXN];

void build(int o, int l, int r)
{
    if(0 == r-l)
    {
        nodes[o].l = l; nodes[o].r = r;
        nodes[o].m[l&1] = l; nodes[o].m[1-(l&1)] = -1;
    } else {
        int mid = ((l+r)>>1);
        build(o<<1, l, mid);
        build(o<<1|1, mid+1, r);
        nodes[o] = merge(nodes[o<<1], nodes[o<<1|1]);
    }
}

node_t query(int L, int R, int o, int l, int r)
{
    if(L <= l && r <= R)
        return nodes[o];
    else
    {
        int mid = ((l+r)>>1);
        if(R <= mid) return query(L,R,o<<1,l,mid);
        else if(L > mid) return query(L,R,o<<1|1,mid+1,r);
        else return merge(query(L,R,o<<1,l,mid),query(L,R,o<<1|1,mid+1,r));
    }
}
int qmin(int L, int R, int re)
{
    return query(L, R, 1,1,N).m[re];
}

int nq[MAXN];
void solve(int L, int R, int re, int l, int r)
{
    if(1 == R-L)
    {
        q[l] = p[L];
        q[r] = p[R];
    } else if(L < R) {
        int i = 0, j = 0;
        node_t lm = query(L,R,1,1,N);
        int fi = lm.m[re];
        node_t rm = query(fi+1,R,1,1,N);
        int si = rm.m[!re];
        q[l] = p[fi]; q[l+1] = p[si];
        int pro[3][3] = {{L,fi-1,re},{fi+1,si-1,!re},{si+1,R,re}};
        vector<int> ava;
        int nl = l+2;
        for(i = 0;i < 3;++i)
            if(pro[i][1] > pro[i][0])
                ava.push_back(i);
        int ls[3] = {0}, ws[3] = {0};
        for(i = 0;i < ava.size();i++)
        {
            ls[i] = nl;
            solve(pro[ava[i]][0], pro[ava[i]][1], pro[ava[i]][2], nl, nl+pro[ava[i]][1]-pro[ava[i]][0]);
            ws[i] = pro[ava[i]][1]-pro[ava[i]][0]+1;
            nl += ws[i];
        }
        int its[3] = {0};
        int po = 0, rem = R-L-1;
        while(po < rem)
        {
            int mi = -1;
            for(i = 0;i < ava.size();i++)
                if(its[i] < ws[i] && (-1 == mi || q[ls[i]+its[i]]<q[ls[mi]+its[mi]]))
                    mi = i;
            nq[po++] = q[ls[mi]+its[mi]];
            nq[po++] = q[ls[mi]+its[mi]+1];
            its[mi] += 2;
        }
        for(i = 0;i < rem;++i)
            q[l+2+i] = nq[i];
    }
}

