{
    int i = 0;
    p[-1] = MAXN;
    scanf("%d", &N);
    for(i = 1;i <= N;++i)
        scanf("%d", p+i);
    build(1, 1, N);
    solve(1, N, 1, 0, N-1);
    printf("%d", q[0]);
    for(i = 1;i < N;++i)
        printf(" %d", q[i]);
    puts("");
    return 0;
}

