		return s[i]=min(d(i*2-i%2),d(i*2+2-i%2));
	}else{
		return s[i];
	}
}

pp_p rmq(pii lr){
	auto f=[](int l,int r){
		pii t=s[l+=B],u=s[r+=B];
		for(;l/4<r/4;l=l/4*2+l%2,r=r/4*2+r%2){
			t=l&2?t:min(t,s[l+2]);
			u=r&2?min(s[r-2],u):u;
		}
		return min(t,u);
	};
	pii x,y;
	x=f(lr._0,lr._1-2);
	y=f(x._1+1,lr._1-1);
	return{{x,y},lr};
}

