struct RMQ{
  int n;
  vector<int> dat;
  const int def=1<<28;
  RMQ(){}
  RMQ(int n_){init(n_);}
  RMQ(int n_,int* a){init(n_);build(n_,a);}
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.clear();
    dat.resize(2*n-1,def);
  }
  void build(int n_, int* a){
    for(int i=0;i<n_;i++) dat[i+n-1]=a[i];
    for(int i=n-2;i>=0;i--)
      dat[i]=min(dat[i*2+1],dat[i*2+2]);
  }
  void update(int k,int a){
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }
  int query(int a,int b,int k,int l,int r){
    if(r<=a||b<=l) return def;
    if(a<=l&&r<=b) return dat[k];
    int vl=query(a,b,k*2+1,l,(l+r)/2);
    int vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
  int query(int a,int b){
    return query(a,b,0,0,n);
  }
};


struct SparseTable{
  int n,h;
  vector<vector<int> > dat;
  vector<int> ht;
  SparseTable(){}
  SparseTable(int n_,int *arr){init(n_,arr);}
  void init(int n_,int *arr){
    n=1;h=1;
    while(n<n_) n*=2,h++;
    dat.clear();
    dat.resize(h,vector<int>(n_));
    for(int j=0;j<n_;j++) dat[0][j]=arr[j];
    for(int i=1,p=1;i<h;i++){
      for(int j=0;j<n_;j++){
	dat[i][j]=dat[i-1][j];
	if(j+p<n_) dat[i][j]=min(dat[i][j],dat[i-1][j+p]);
      }
      p*=2;
    }
    ht.resize(n_+1);
    ht[0]=ht[1]=0;
    for(int j=2;j<n_+1;j++)
      ht[j]=ht[j>>1]+1;
  }
  int query(int a,int b){
    b--;//[a,b)->[a,b-1]
    int l=b-a+1;
    //cout<<a<<" "<<b<<" "<<l<<" "<<ht[l]<<" "<<h<<endl;
    return min(dat[ht[l]][a],dat[ht[l]][b-(1<<ht[l])+1]);
  }
};



