void build(int curr,int l,int r){
    if(l==r){
        seg[curr][l%2] = arr[l];
        seg[curr][1-(l%2)] = 1e9;

        return;
    }
    int mid = (l+r)/2;
    build(2*curr,l,mid);
    build(2*curr+1,mid+1,r);
    seg[curr][0] = min(seg[2*curr][0],seg[2*curr+1][0]);
    seg[curr][1] = min(seg[2*curr][1],seg[2*curr+1][1]);

}
int query(int curr,int l,int r,int tl,int tr,int par){

    if(l>tr||r<tl){
        return 1e9;
    }
    if(tl<=l && r<=tr){
        return seg[curr][par];
    }
    int mid = (l+r)/2;
    return min(query(2*curr,l,mid,tl,tr,par),query(2*curr+1,mid+1,r,tl,tr,par));
}
struct segment{
    int l,r;
    bool operator<(const segment& rhs) const
    {
        return query(1,1,n,l,r,l%2) > query(1,1,n,rhs.l,rhs.r,(rhs.l)%2);
    }
};
