struct T{
	int ls,rs,left_range,right_range;
	int val[2];
}tree[MAXN<<1];
int cnt;
vector<int> vec[MAXN];
set<int> s;
int to[MAXN];

void update(int x){
	tree[x].val[0]=min(tree[tree[x].ls].val[0],tree[tree[x].rs].val[0]);
	tree[x].val[1]=min(tree[tree[x].ls].val[1],tree[tree[x].rs].val[1]);
}

int Build(int l,int r){
	int now=++cnt;
	tree[now].left_range=l;
	tree[now].right_range=r;
	if(l==r){
		tree[now].val[l&1]=num[l];
		tree[now].val[(l&1)^1]=INF;
		return now;
	}
	int mid=(l+r)>>1;
	tree[now].ls=Build(l,mid);
	tree[now].rs=Build(mid+1,r);
	update(now);
	return now;
}

int getnum(int k,int l,int r,int t){
	if(l<=tree[k].left_range && tree[k].right_range<=r){
		return tree[k].val[t];
	}
	int mid=(tree[k].left_range+tree[k].right_range)>>1;
	int re=INF;
	if(l<=mid) re=min(re,getnum(tree[k].ls,l,r,t));
	if(r>=mid+1) re=min(re,getnum(tree[k].rs,l,r,t));
	return re;
}

void DFS(int l,int r,int t,int f){
	int x=aloc[getnum(1,l,r,t)];
	int y=aloc[getnum(1,x,r,t^1)];
	vec[f].push_back(x);
	to[x]=y;
	if(l<x) DFS(l,x-1,t,f);
	if(x+1<y) DFS(x+1,y-1,t^1,x);
	if(r>y) DFS(y+1,r,t,f);
}

void solve(){
	DFS(1,n,1,0);
	int i;
	for(i=0;i<vec[0].size();i++){
		s.insert(num[vec[0][i]]);
	}
	for(i=1;i<=n/2;i++){
		int x=aloc[*s.begin()];
		s.erase(num[x]);
		printf("%d %d ",num[x],num[to[x]]);
		for(int j=0;j<vec[x].size();j++)
			s.insert(num[vec[x][j]]);
	}
	puts("");
}

