	void init()
	{
		for(int i=1; i<=lg[n]; ++i)
			for(int j=1; j+(1<<i)-1<=n; ++j)
				mn[i][j]=min(mn[i-1][j], mn[i-1][j+(1<<(i-1))]);
	}
	pii query(int l, int r)
	{
		assert(l<=r);
		int Log=lg[r-l+1]; 
		return min(mn[Log][l], mn[Log][r-(1<<Log)+1]);
	}
