#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

vector<pii> solve(int l , int r, vector<int> const& a) {
    int mi1 = 1e9, mi1p = 0;
    for(int offset = 0; offset + l < r; offset += 2) {
        if(mi1 > a[l + offset]) {
            mi1 = a[l + offset];
            mi1p = l + offset;
        }
    }
    int mi2 = 1e9, mi2p = 0;
    for(int offset = 1; offset + mi1p < r; offset += 2) {
        if(mi2 > a[mi1p + offset]) {
            mi2 = a[mi1p + offset];
            mi2p = mi1p + offset;
        }
    }
    vector<pii> res = {make_pair(mi1, mi2)};
    vector<vector<pii>> tmp;
    if(l != mi1p) {
        tmp.push_back(solve(l, mi1p, a));
    }
    if(mi1p + 1 != mi2p) {
        tmp.push_back(solve(mi1p + 1, mi2p, a));
    }
    if(mi2p + 1 != r) {
        tmp.push_back(solve(mi2p + 1, r, a));
    }
    if(tmp.size() != 0) {
        vector<int> idx(tmp.size());
        bool loop = true;
        while(loop) {
            bool f = false;
            int nxt = -1;
            for(int i = 0; i < tmp.size(); ++i) {
                if(idx[i] != tmp[i].size() && (nxt == -1 || tmp[nxt][idx[nxt]] > tmp[i][idx[i]])) {
                    nxt = i;
                }
            }
            res.push_back(move(tmp[nxt][idx[nxt]]));
            idx[nxt] += 1;
            for(int i = 0; i < tmp.size(); ++i) {
                f |= idx[i] != tmp[i].size();
            }
            loop &= f;
        }
    }
    return res;
}

