int getMin(int l, int r) {
    int d = r - l;
    if (d % 2 == 1) {
        r++;
        d++;
    }
    int k = 0;
    while ((1 << (k + 1)) <= d) k++;
    int x = st[k][l];
    int y = st[k][r - (1 << k)];
//    cout << l << " " << r << " " << k << " " << x << " " << y << "\n";
    if (p[x] < p[y]) return x;
    else return y;
}

int main() {
    std::ios::sync_with_stdio(false);

    int n;
    cin >> n;

    p.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> p[i];
    }

    int k = 0;
    while ((1 << k) <= n) k++;

    st.resize(k);

    for (int i = 0; i < k; i++) {
        st[i].resize(n);
        for (int j = 0; j < n; j++) {
            if (i <= 1) {
                st[i][j] = j;
            } else {
                st[i][j] = st[i - 1][j];
                int jj = j + (1 << (i - 1));
                if (jj < n) {
                    if (p[st[i - 1][jj]] < p[st[i - 1][j]]) {
                        st[i][j] = st[i - 1][jj];
                    }
                }
            }
        }
    }

    vector<int> res;
    set<pair<int, pair<int, int>>> ss;

    ss.insert({p[getMin(0, n)], {0, n}});

    while (ss.size() > 0) {
        pair<int, pair<int, int>> pp = *(ss.begin());
        ss.erase(ss.begin());

        int l = pp.second.first;
        int r = pp.second.second;


        int x = getMin(l, r);
        int y = getMin(x + 1, r);

//        cout << l << " " << r << " " << p[x] << " " << p[y] << "\n";

        res.push_back(p[x]);
        res.push_back(p[y]);

        if (x > l) {
            ss.insert({p[getMin(l, x)], {l, x}});
        }
        if (y > x + 1) {
            ss.insert({p[getMin(x + 1, y)], {x + 1, y}});
        }
        if (r > y + 1) {
            ss.insert({p[getMin(y + 1, r)], {y + 1, r}});
        }
    }

    for (int i = 0; i < n; i++) {
        cout << res[i] << " ";
    }
    cout << "\n";

    return 0;
}

