vi g(vi a,vi b) {
  if(a.size()==0) return b;
  if(b.size()==0) return a;
  vi ret;
  ll ai=0,bi=0;

  while(ai<a.size()&&bi<b.size()) {
    if(a[ai]>b[bi]) {
      ret.PB(b[bi]);
      ret.PB(b[bi+1]);
      bi+=2;
    } else {
      ret.PB(a[ai]);
      ret.PB(a[ai+1]);
      ai+=2;
    }
  }
  for(ll i=ai;i<a.size();i++) ret.PB(a[i]);
  for(ll i=bi;i<b.size();i++) ret.PB(b[i]);
  return ret;
}

vi g(vi a,vi b,vi c) {
  if(a.size()==0) return g(b,c);
  if(b.size()==0) return g(a,c);
  if(c.size()==0) return g(a,b);
  vi ret;
  if(a[0]<b[0]&&a[0]<c[0]) {
    for(ll i:a) ret.PB(i);
    for(ll i:g(b,c)) ret.PB(i);
  }
  if(b[0]<a[0]&&b[0]<c[0]) {
    for(ll i:b) ret.PB(i);
    for(ll i:g(a,c)) ret.PB(i);
  }
  if(c[0]<a[0]&&c[0]<b[0]) {
    for(ll i:c) ret.PB(i);
    for(ll i:g(a,b)) ret.PB(i);
  }
  return ret;
}

