class AAA {
public:
	int x;
	int y;
	int x_idx;
	int y_idx;
	vector<int> v;

	AAA(vector<int> &vv) {
		v = vv;

		if (v.empty()) {
			x = y = x_idx = y_idx = -1;
			return;
		}

		x_idx = 0;
		x = v[x_idx];
		for (int i = 2; i < v.size(); i += 2) {
			if (v[i] < x) {
				x = v[i];
				x_idx = i;
			}
		}

		y_idx = x_idx + 1;
		y = v[y_idx];
		for (int i = y_idx + 2; i < v.size(); i+= 2) {
			if (v[i] < y) {
				y = v[i];
				y_idx = i;
			}
		}

		// printf("xy %d %d, idx %d %d\n", x, y, x_idx, y_idx);
	}
};

