const int N = 200010;

int a[N];
int tree[2][4 * N];

inline void put(int x, int l, int r, int p, int *t) {
  if (l == r) {
    t[x] = p;
    return;
  }
  int s = (l + r) / 2;
  if (p <= s) {
    put(x + x, l, s, p, t);
  } else {
    put(x + x + 1, s + 1, r, p, t);
  }
  if (t[x + x] == -1) {
    t[x] = t[x + x + 1];
  } else
  if (t[x + x + 1] == -1) {
    t[x] = t[x + x];
  } else {
    t[x] = (a[t[x + x]] < a[t[x + x + 1]] ? t[x + x] : t[x + x + 1]);
  }
}

inline int get(int x, int l, int r, int ql, int qr, int *t) {
  if (r < ql || l > qr) {
    return -1;
  }
  if (l >= ql && r <= qr) {
    return t[x];
  }
  int s = (l + r) / 2;
  int el = get(x + x, l, s, ql, qr, t);
  int er = get(x + x + 1, s + 1, r, ql, qr, t);
  if (el == -1) {
    return er;
  }
  if (er == -1) {
    return el;
  }
  return a[el] < a[er] ? el : er;
}

const int inf = 1e9;

int n;

vector <int> solve(int l, int r, int w) {
  if (r - l <= 0) {
    return vector <int>();
  }
  vector <int> res(r - l + 1);
  if (r - l + 1 == 2) {
    res[0] = a[l];
    res[1] = a[r];
    return res;
  }
  int p = get(1, 0, n - 1, l, r, tree[w]);
  int q = get(1, 0, n - 1, p + 1, r, tree[1 - w]);
  int sz = 0;
  res[sz++] = a[p];
  res[sz++] = a[q];
  vector <int> x = solve(l, p - 1, w);
  vector <int> y = solve(p + 1, q - 1, 1 - w);
  vector <int> z = solve(q + 1, r, w);
  int sz_x = (int)x.size();
  int sz_y = (int)y.size();
  int sz_z = (int)z.size();
  int ix = 0, iy = 0, iz = 0;
  while (true) {
    int vx = (ix >= sz_x ? inf : x[ix]);
    int vy = (iy >= sz_y ? inf : y[iy]);
    int vz = (iz >= sz_z ? inf : z[iz]);
    if (vx == inf && vy == inf && vz == inf) {
      break;
    }
    if (vx < vy && vx < vz) {
      res[sz++] = x[ix++];
      res[sz++] = x[ix++];
    } else
    if (vy < vx && vy < vz) {
      res[sz++] = y[iy++];
      res[sz++] = y[iy++];
    } else {
      res[sz++] = z[iz++];
      res[sz++] = z[iz++];
    }
  }
  return res;
}

