inline void chkmin(int &x, int y) {
	if (y < x) x = y;
}
struct RMQ {
	int b[MX];
	int x[MX][L];
	int N;
	void build(int *p, int n) {
		int i, j, k;
		N = n;
		for (k = 0, i = 1; i <= N; i++) {
			if (i == bit(k + 1)) k++;
			b[i] = k;
		}
		for (i = 0; i < N; i++) x[i][0] = p[i];
		for (j = 1; j <= k; j++) {
			for (i = 0; i < N; i++) {
				x[i][j] = x[i][j - 1];
				if (i + bit(j - 1) < N)
					chkmin(x[i][j],  x[i + bit(j  -  1)][j  -  1]);
			}
		}
	}
//return min value between [st, en)
	int range_min(int st, int en) {
		int j = b[en - st];
		return min(x[st][j], x[en - bit(j)][j]);
	}
};
int pos[100005], p[100005], a[2][100005];
RMQ R[2];
int cnt = 0;
vi calc(int l, int r) {
//	cout << l << ' ' << r << '\n';
	cnt ++;
	vi tmp;
//	if(cnt > 5) return tmp;
	if(r == l + 1){
		vi ret;
		ret.push_back(make_pair(p[l], p[r]));
		return ret;
	}
	int mn = R[l % 2].range_min((l - l % 2) / 2, (r - l % 2) / 2 + 1);
	int id = pos[mn];
	int mn1 = R[(id + 1) % 2].range_min((id + 1 - (id + 1) % 2) / 2, (r - (id + 1) % 2) / 2 + 1);
	int id1 = pos[mn1];
	vi ret_L, ret_R, ret_mid;
	int curL = -1, curR = -1, curm = -1;
	if(id > l) ret_L = calc(l, id - 1), curL = ret_L.size() - 1;
	if(r > id1 + 1) ret_R = calc(id1 + 1, r), curR = ret_R.size() - 1;
	if(id1 - 1 > id + 1) ret_mid = calc(id + 1, id1 - 1), curm = ret_mid.size() - 1;
	vi ret;
	while(1){
		if(curL == -1 && curR == -1 && curm == -1) break;
		if(curL == -1){
			if(curR == -1 || ret_mid[curm] < ret_R[curR]) ret.push_back(ret_mid[curm]), curm --;
			else ret.push_back(ret_R[curR]), curR --;
		}
		else if(curR == -1){
			if(curL == -1 || ret_mid[curm] < ret_L[curL]) ret.push_back(ret_mid[curm]), curm --;
			else ret.push_back(ret_L[curL]), curL --;
		}
		else if(curm == -1){
			if(curR == -1 || ret_mid[curL] < ret_R[curR]) ret.push_back(ret_mid[curL]), curL --;
			else ret.push_back(ret_R[curR]), curR --;
		}
		else {
			if(ret_mid[curm] < ret_R[curR] && ret_mid[curm] < ret_L[curL]) ret.push_back(ret_mid[curm --]);
			else if(ret_L[curL] < ret_mid[curm] && ret_L[curL] < ret_R[curR]) ret.push_back(ret_L[curL --]);
			else if(ret_R[curR] < ret_L[curL] && ret_mid[curm] < ret_mid[curm]) ret.push_back(ret_R[curR --]);
		}
	}
	reverse(ret.begin(), ret.end());
	ret.push_back(make_pair(p[id], p[id1]));
	return ret;
}

