typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 30;
const int MOD = 1e9 + 7;

struct Node {
  Node *left, *right;
  int a, b;
  int minv[2], cnt;
  void pushup() {
    for (int k = 0; k < 2; ++k) {
      minv[k] = min(left->minv[k], right->minv[k]);
      cnt = left->cnt + right->cnt;
    }
  }
};

const int N = 2e5 + 10;
int p[N], r[N], ret[N];
Node pool[N << 1], *last;

Node* build(int a, int b) {
  Node* cur = last++;
  cur->a = a;
  cur->b = b;
  if (a + 1 == b) {
    cur->minv[0] = cur->minv[1] = INF;
    cur->minv[a % 2] = p[a];
    cur->cnt = 0;
    return cur;
  }
  cur->left = build(a, (a + b) / 2);
  cur->right = build((a + b) / 2, b);
  cur->pushup();
  return cur;
}

int A, B;
int query(Node* cur, int k) {
  if (cur->a >= A && cur->b <= B) {
    return cur->minv[k];
  }
  int ret = INF;
  if ((cur->a + cur->b) / 2 > A) ret = min(ret, query(cur->left, k));
  if ((cur->a + cur->b) / 2 < B) ret = min(ret, query(cur->right, k));
  return ret;
}

void erase(Node* cur) {
  if (cur->a + 1 == cur->b) {
    cur->minv[0] = cur->minv[1] = INF;
    cur->cnt = 1;
    return;
  }
  if ((cur->a + cur->b) / 2 > A) erase(cur->left);
  else erase(cur->right);
  cur->pushup();
}

void reverse(Node* cur) {
  if (cur->a >= A && cur->b <= B) {
    swap(cur->minv[0], cur->minv[1]);
    return;
  }
  if ((cur->a + cur->b) / 2 > A) reverse(cur->left);
  if ((cur->a + cur->b) / 2 < B) reverse(cur->right);
  cur->pushup();
}

int get_inf_pos(Node* cur) {
  // trace(A, cur->a, cur->b);
  if (cur->a + 1 == cur->b) {
    return cur->cnt ? cur->a : cur->a + 1;
  }
  if (cur->left->b > A && cur->left->cnt) return get_inf_pos(cur->left);
  return get_inf_pos(cur->right);
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d", &p[i]);
    r[p[i]] = i;
  }
  last = pool;
  Node* root = build(0, n);
  for (int i = 0; i < n; i += 2) {
    // trace(i);
    A = 0, B = n;
    int x = query(root, 0);
    A = r[x] + 1;
    B = get_inf_pos(root);
    // trace(A, B);
    int y = query(root, 1);
    // trace(x, y);
    A = r[x] + 1, B = r[y];
    if (A != B) reverse(root);
    A = r[x];
    erase(root);
    A = r[y];
    erase(root);
    ret[i] = x;
    ret[i + 1] = y;
  }
  for (int i = 0; i < n; ++i) {
    printf("%d%c", ret[i], " \n"[i + 1 == n]);
  }
  return 0;
}

#include <cstdio>
