vector<int> ps;

void update(int k, int a) {
    int *dat = nullptr;
    if (k % 2 == 0) {
        dat = dat_even;
        k /= 2;
    } else {
        dat = dat_odd;
        k /= 2;
    }

    k += n - 1;
    dat[k] = a;
    while (k > 0) {
        k = (k - 1) / 2;
        auto n1 = dat[k * 2 + 1];
        auto n2 = dat[k * 2 + 2];
        if (n1 == 100000) {
            dat[k] = n2;
        } else if (n2 == 100000) {
            dat[k] = n1;
        } else {
            if (ps[n1] < ps[n2]) {
                dat[k] = n1;
            } else {
                dat[k] = n2;
            }
        }
    }
}

int query(int * dat,int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
        return 100000;
    }

    if (a <= l && r <= b) {
        return dat[k];
    } else {
        int vl = query(dat, a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(dat, a, b, k * 2 + 2, (l + r) / 2, r);
        if (vl >= 100000) {
            return vr;
        } else if (vr >= 100000) {
            return vl;
        }
        if (ps[vl] < ps[vr]) {
            return vl;
        } else {
            return vr;
        }
    }
}

