vector<int> A;
vector<int> Aindex;//Aの値からインデックスをえる。
segment_base<int> seg[2];//偶数、奇数0-index

void solve(){
	int N;
	cin >> N;
	A.resize(N);
	Aindex.resize(N+1);
	seg[0].init(N,INF);
	seg[1].init(N,INF);

	for(int i=0;i<N;++i){
		cin >> A[i];
		Aindex[ A[i] ] = i;
		seg[i&1].update(i,A[i]);
	}

	vector<int> start(3);
	start[1] = 0;
	start[2] = N;
	start[0] = seg[ start[1]&1 ].query(start[1],start[2]);
	priority_queue< vector<int>,vector< vector<int> >,greater< vector<int> > > que;
	que.push( start );
	int pos = 0;
	vector<int> ans(N);
	vector<int> temp(3);
	while( !que.empty() ){
		temp = que.top();que.pop();
		int L,R;//値
		L = temp[0];
		int Lindex = Aindex[ L ];

		R = seg[(Lindex&1)^1].query( temp[1], temp[2] ); 
		int Rindex = Aindex[ R ];

		ans[pos++] = L;
		ans[pos++] = R;

		//区間の分割	,取った間は偶奇がずれる。
		vector<int> next(3);
		if( temp[1] < Lindex ){
			next[1] = temp[1];
			next[2] = Lindex;
			next[0] = seg[next[1]&1].query(next[1],next[2]);
			que.push( next );
		}
		if( Lindex+1 < Rindex ){
			next[1] = Lindex+1;
			next[2] = Rindex;
			next[0] = seg[next[1]&1].query(next[1],next[2]);
			que.push( next );
		}
		if( Rindex+1 < temp[2] ){
			next[1] = Rindex+1;
			next[2] = temp[2];
			next[0] = seg[next[1]&1].query(next[1],next[2]);
			que.push( next );
		}
	}

	for(int i=0;i< N ;++i){
		if(i)cout << " ";
		cout << ans[i];
	}
	cout << endl;
}

