struct SegmentTree{
private:
    int n;
    vector<pair<int,int>> node;
public:
    SegmentTree(const vector<int> &v){
        int sz=(int)v.size();
        n=1;
        while(n<sz)n*=2;
        node.resize(2*n-1);
        for(int i=0;i<n;i++){
            if(i<sz)node[i+n-1]={v[i],i};
            else node[i+n-1]={INF,INF};
        }
        for(int i=n-2;i>=0;i--){
            node[i]=min(node[2*i+1],node[2*i+2]);
        }
    }
    pair<int,int> get(int a,int b,int k=0,int l=0,int r=-1){
        if(r==-1)r=n;
        if(b<=l||r<=a)return {INF,INF};
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return min(get(a,b,2*k+1,l,(l+r)/2),get(a,b,2*k+2,(l+r)/2,r));
        }
    }
};

vector<pair<int,int>> solve(int l,int r,SegmentTree &segev,SegmentTree &segod){
    if(l==r){
        return vector<pair<int,int>>{{INF,INF}};
    }
    vector<pair<int,int>> res;
    res.reserve((r-l)/2+1);
    if(l%2==0){
        auto lmn=segev.get(l/2,r/2);
        auto rmn=segod.get(lmn.second,r/2);
        res.push_back({lmn.first,rmn.first});
        auto fi=solve(l,lmn.second*2,segev,segod);
        auto se=solve(lmn.second*2+1,rmn.second*2+1,segev,segod);
        auto th=solve(rmn.second*2+2,r,segev,segod);
        int ifi=0,ise=0,ith=0;
        for(int i=0;i<(r-l-2)/2;i++){
            pair<int,int> what={INF,INF};
            int which=-1;
            if(fi[ifi]<what){
                what=fi[ifi];
                which=0;
            }
            if(se[ise]<what){
                what=se[ise];
                which=1;
            }
            if(th[ith]<what){
                what=th[ith];
                which=2;
            }
            if(which==0)ifi++;
            else if(which==1)ise++;
            else ith++;
            res.push_back(what);
        }
        res.push_back({INF,INF});
    }
    else{
        auto lmn=segod.get(l/2,r/2);
        auto rmn=segev.get(lmn.second+1,r/2+1);
        res.push_back({lmn.first,rmn.first});
        auto fi=solve(l,lmn.second*2+1,segev,segod);
        auto se=solve(lmn.second*2+2,rmn.second*2,segev,segod);
        auto th=solve(rmn.second*2+1,r,segev,segod);
        int ifi=0,ise=0,ith=0;
        for(int i=0;i<(r-l-2)/2;i++){
            pair<int,int> what={INF,INF};
            int which=-1;
            if(fi[ifi]<what){
                what=fi[ifi];
                which=0;
            }
            if(se[ise]<what){
                what=se[ise];
                which=1;
            }
            if(th[ith]<what){
                what=th[ith];
                which=2;
            }
            if(which==0)ifi++;
            else if(which==1)ise++;
            else ith++;
            res.push_back(what);
        }
        res.push_back({INF,INF});
    }
    return res;
}

