const int maxn = 2e5 + 5;
int n;
int a[maxn];
pi st[2][maxn << 1];

void upd(pi st[], int p, pi val) {
    for (st[p += n] = val; p > 1; ) p >>= 1, st[p] = min(st[p << 1], st[p << 1 | 1]);
}
pi query(pi st[], int l, int r) {
    pi res = mp(INF, INF);
    for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
        if (l & 1) chkmin(res, st[l++]);
        if (r & 1) chkmin(res, st[--r]);
    }
    return res;
}

pi getmin(int l, int r) {
    if (l > r) return mp(INF, INF);
    pi mn = query(st[l & 1], l, r);
    if (mn.se == r) mn = query(st[l & 1], l, r - 1);
    int ix = mn.se;
    mn = query(st[(l & 1) ^ 1], ix + 1, r);
    int ix2 = mn.se;
    return mp(ix, ix2);
}

pi getmin2(int l, int r) {
    if (l > r) return mp(INF, INF);
    pi mn = query(st[l & 1], l, r);
    if (mn.se == r) mn = query(st[l & 1], l, r - 1);
    int ix = mn.se;
    mn = query(st[(l & 1) ^ 1], ix + 1, r);
    int ix2 = mn.se;
    return mp(-a[ix], -a[ix2]);
}

void solve() {
    cin >> n;
    FOR(i, 0, n) cin >> a[i];
    FOR(k, 0, 2) FOR(i, 0, n + n) st[k][i] = mp(INF, INF);
    FOR(i, 0, n) {
        upd(st[i & 1], i, mp(a[i], i));
    }
    vi res;
    priority_queue<pair<pi, pi> > pq;
    pq.push(mp(getmin2(0, n - 1), mp(0, n - 1)));
    while (sz(pq)) {
        int l = pq.top().se.fi;
        int r = pq.top().se.se;
        pq.pop();
        pi mn = getmin(l, r);
        res.pb(a[mn.fi]), res.pb(a[mn.se]);
        int ax[] = {l, mn.fi + 1, mn.se + 1};
        int ay[] = {mn.fi - 1, mn.se - 1, r};
        FOR(i, 0, 3) {
            int ll = ax[i];
            int rr = ay[i];
            if (ll <= rr) {
                pq.push(mp(getmin2(ll, rr), mp(ll, rr)));
            }
        }
    }
    FOR(i, 0, sz(res)) cout << res[i] << " \n"[i == sz(res) - 1];
}

