struct SEG{
	int l;
	int r;
	int m[2];
	int loc[2];
	bool ch;
	SEG *chl,*chr;
	void init(int l_,int r_,int m0 = INF,int m1 = INF,int loc0 = -1,int loc1 = -1){
		l = l_;
		r = r_;
		m[0] = m0;
		m[1] = m1;
		loc[0] = loc0;
		loc[1] = loc1;
		ch = false;
	}
	void mkch(){
		chl = new SEG;
		chl->init(l,(l+r)/2);
		chr = new SEG;
		chr->init((l+r)/2,r);
		ch = true;
	}
	void set(int a,int x){
		if(a < l || r <= a)return;
		if(l == a && r == a+1){
			m[a&1] = x;
			loc[a&1] = a;
			return;
		}
		if(!ch)mkch();
		chl->set(a,x);
		chr->set(a,x);
		int ml = chl->m[a&1];
		int mr = chr->m[a&1];
		if(ml <= mr){
			m[a&1] = ml;
			loc[a&1] = chl->loc[a&1];
		}
		else {
			m[a&1] = mr;
			loc[a&1] = chr->loc[a&1];
		}
	}
	pair<int,int> min_loc(int a,int b,int c){
		if(b <= l || r <= a)return pair<int,int>(INF,-1);
		if(a <= l && r <= b)return pair<int,int>(m[c],loc[c]);
		P pl = chl->min_loc(a,b,c);
		P pr = chr->min_loc(a,b,c);
		return min(pl,pr);
	}
}seg;

struct node{
	int a;
	int b;
	node* ch[3];
	bool operator < ( const node y ) const {
		if(this->a == y.a)return this->b < y.b;
		else return this->a < y.a;
	}
	bool operator > ( const node y ) const {
		if(this->a == y.a)return this->b > y.b;
		else return this->a > y.a;
	}
};

node* sol(int l,int r){
	if(r-l == 0)return nullptr;
	node* ret = new node;
	P a = seg.min_loc(l,r,l&1);
	P b = seg.min_loc(a.sc+1,r,(r+1)&1);
	ret->a = a.fr;
	ret->b = b.fr;
	ret->ch[0] = sol(l,a.sc);
	ret->ch[1] = sol(a.sc+1,b.sc);
	ret->ch[2] = sol(b.sc+1,r);
	return ret;
}

