		code[last] = {p[l] , p[r]};
		rcode[{p[l] , p[r]}] = last;

		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;
	}else{
		pii o = {0 , 0};

		int par = l % 2;
		o.fi = query(par , l , r + 1);

		int pos1 = pos[o.fi];
		o.se = query((pos1 + 1) % 2 , pos1 + 1 , r + 1);

		code[last] = o;
		rcode[o] = last;

		if(prev != -1){
			g[prev].pb(last);
		}
		prev = last;
		++last;


