		rep(q , 2){
			modify(q , pos1 , INF);
			modify(q , pos2 , INF);

		}

		solve(p , pos1 + 1 , pos2 - 1 , prev);
		solve(p , l , pos1 - 1 , prev);
		solve(p , pos2 + 1 , r  , prev);

	}
}

vi restore(){
	vi res;
	priority_queue<pii , vector<pii> , greater<pii>> q; 
	q.push(code[0]);

	while(!q.empty()){
		pii u = q.top();
		q.pop();

		res.pb(u.fi);
		res.pb(u.se);

		for(int c : g[rcode[u]]){
			q.push(code[c]);
		}
	}
	return res;
}

