void buatst(int id,int depth){
	for(int i=1;i<=n;i++)
	{
		if((i+(1<<(depth-1)))>n)
			st[id][depth][i]=st[id][depth-1][i];
		else
		{
			st[id][depth][i]=min(st[id][depth-1][i],st[id][depth-1][i+(1<<(depth-1))]);
		}
	}
}
void basecasest(int id){
	for(int i=1;i<=n;i++)
	{
		if(jenis(i)==id)
			st[id][0][i]=mp(perm[i],i);
		else
			st[id][0][i]=mp(INF,i);
	}
}
void buatst(int id){
	basecasest(id);
	for(int i=1;i<logn;i++)
		buatst(id,i);
}
void buatst(){
	for(int id=0;id<2;id++)
		buatst(id);
}
void isimsb(){
	msb[0]=-1;			//harusnya ini dak mungkin
	msb[1]=0;
	for(int i=2;i<=n;i++)
	{
		msb[i]=msb[i-1];
		while((1<<(msb[i]+1))<=i)				//loopnya harusnya at most 1 kali
			msb[i]++;
	}
}
pii query(int id,int l,int r){
	int panjang=r-l+1;
	return min(st[id][msb[panjang]][l],st[id][msb[panjang]][r-(1<<msb[panjang])+1]);
}
void updateans(int angka){
	ans[idx++]=angka;
}
void masukkan(int l,int r){
	if(l>r)
		return;
	pq.push(mp(-query(jenis(l),l,r).fi,mp(l,r)));
}
pii rangetarget(int l,int r){
	pii ret,temp;
	temp=query(jenis(l),l,r);
	ret.fi=temp.se;
	temp=query(jenis(l)^1,ret.fi,r);
	ret.se=temp.se;
	return ret;
}
void pecah(int l,int r,int ll,int rr){
	masukkan(l,ll-1);
	masukkan(ll+1,rr-1);
	masukkan(rr+1,r);
}
