	masukkan(1,n);
	while(!pq.empty())
	{
		pii range=pq.top().se;
		pq.pop();
		pii pilihan=rangetarget(range.fi,range.se);
		updateans(perm[pilihan.fi]);
		updateans(perm[pilihan.se]);
		pecah(range.fi,range.se,pilihan.fi,pilihan.se);
	}
}
