int ind[200100];

struct node{
  int s,e,m,v;
  node *l, *r;
  node(int _s, int _e){
    s=_s;e=_e;m=(s+e)/2;
    if (s == e){
      v = A[s];
    }
    else{
      l = new node(s,m);
      r = new node(m+1, e);
      v = min(l->v, r->v);
    }
  }
  void up(int x, int val){
    if (s == e){
      v = val;
      return;
    }
    if (x <= m)l->up(x,val);
    else r->up(x,val);
    v = min(l->v, r->v);
  }
  int query(int a, int b){
    if (a == s && b == e)return v;
    if (b <= m)return l->query(a,b);
    if (a > m)return r->query(a,b);
    return min(l->query(a,m), r->query(m+1, b));
  }
} *odd, *even, *all;

int fw[200100];
void update(int x, int v){
  ++x;
  for (;x<=N;x+=x&(-x))fw[x]+=v;
}

int remain(int x){
  ++x;
  int res = 0;
  for (;x;x-=x&(-x))res+=fw[x];
  return res;
}

int main(){
  // freopen("in.txt","r",stdin);
  cin >> N;
  done.insert(N);
  for (int i=0;i<N;++i){
    update(i+1,1);
    cin>>P[i];
    ind[P[i]] = i;
    if (i%2==0)A[i] = P[i];
    else A[i] = INF;
  }
  even = new node(0,N);
  for (int i=0;i<N;++i){
    if (i%2)A[i] = P[i];
    else A[i] = INF;
  }
  odd = new node(0,N);
  int cnt = 1, nxt = INF;
  for (int i=0;i<N;++i)A[i] = P[i];
  all = new node(0,N);

  while (SZ(ans) != N){
    int curval = cnt++;
    if (nxt != INF){
      curval= nxt;
      nxt = INF;
      --cnt;
    }
    int curind = ind[curval];
    if (done.find(curind) != done.end())continue; // Already taken
    if (remain(curind)%2)continue; // Odd number left on left side
    int abv = (*done.ub(curind)) - 1;
    int minval;
    if (curind%2==0){
      minval = odd->query(curind, abv);
    }else{
      minval = even->query(curind, abv);
    }
    // cerr<<curval<<' '<<minval<<'\n';
    int mindex = ind[minval];
    if (curind%2==0){
      odd->up(mindex, INF);
    }else{
      even->up(mindex, INF);
    }
    ans.pb(curval);
    ans.pb(minval);
    done.insert(curind);
    done.insert(mindex);
    update(curind,-1);
    update(mindex, -1);
    all->up(curind, INF);
    all->up(mindex, INF);
    nxt = all->query(curind, mindex);
  }
  for (auto i : ans)cout<<i<<' ';
}

