ll N, M;
vector<ll> E[1010];
bool visited[1010];
bool ok;

void dfs(ll now, ll from, ll start){
  if(now == start && from != -1){
    ok = 1;
    return;
  }
  if(visited[now]) return;
  visited[now] = 1;
  for(ll to : E[now]){
    dfs(to, now, start);
  }
}

ll dist[1010];
ll last;

void dijkstra(ll s){
  rep(i, 1010) dist[i] = INFL;
  dist[s] = 0;
  priority_queue<P, vector<P>, greater<P>> pque;
  pque.push({0, s});
  while(!pque.empty()){
    P p = pque.top();
    pque.pop();
    if(dist[p.s] < p.f) continue;
    for(ll to : E[p.s]){
      if(to == s){
        last = p.s;
        continue;
      }
      if(dist[to] > p.f + 1){
        dist[to] = p.f + 1;
        pque.push({dist[to], to});
      }
    }
  }
}


pair<ll, pair<ll, ll>> solve(ll start){
  dijkstra(start);
  return {dist[last], {last, start}};

}


