  rep(i, N){
    ok = 0;
    rep(j, N) visited[j] = 0;
    dfs(i, -1, i);
    if(ok){
      ANS.pb(solve(i));
    }
  }
  if(ANS.size() == 0){
    cout << -1 << endl;
    return 0;
  }
  sort(ANS.begin(), ANS.end());

  rep(a, ANS.size()){
    dijkstra(ANS[a].s.s);
    set<ll> ans;
    ll now = ANS[a].s.f;
    while(true){
      ans.insert(now);
      if(now == ANS[a].s.s) break;
      ll d = dist[now];
      rep(i, 1010){
        if(dist[i] == d - 1){
          now = i;
        }
