struct SegtreeMin {
    long long n;
    long long inf;
    vector<long long> dat;

    void initialize(long long n_input, long long inf_input){
        inf = inf_input;
        n = 1;
        while(n < n_input)n <<= 1;
        dat.resize(2*n-1);
        for(int i = 0; i<2*n-1; i++) dat[i] = inf;
    }

    void update(long long k, long long a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1)/2;
            dat[k] = min(dat[2*k+1], dat[2*k+2]);
        }
    }

    long long min_between(long long a, long long b){
        return query(a, b+1, 0, 0, n);
    }

    long long query(long long a, long long b, long long k, long long l, long long r){
        if(r<=a || b<=l)return inf;
        if(a<=l && r<=b)return dat[k];
        long long vl = query(a, b, 2*k+1, l, (l+r)/2);
        long long vr = query(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

long long N;
long long P[200000];
long long INF = 1<<30;
SegtreeMin st[2];
long long pos[200001];
long long range_l[200001];
long long range_r[200001];
long long l, r, in_l, in_r, out_l, out_r, parity;

int main(){
    cin >> N;
    st[0].initialize(N, INF);
    st[1].initialize(N, INF);
    for(i=0; i<N; i++){
        cin >> P[i];
        pos[P[i]] = i;
        st[i%2].update(i, P[i]);
    }
    long long min = st[0].min_between(0, N-1);
    priority_queue<long long> pque;
    pque.push(-min);
    range_l[min] = 0;
    range_r[min] = N-1;
    vector<long long> ans = {};

    for(i=0; i<N/2; i++){
        l = -pque.top();
        pque.pop();
        out_l = range_l[l];
        out_r = range_r[l];
        in_l = pos[l];
        parity = in_l % 2;
        r = st[1-parity].min_between(in_l, out_r);
        in_r = pos[r];
        ans.push_back(l);
        ans.push_back(r);
        if(out_l != in_l){
            j = st[parity].min_between(out_l, in_l-1);
            pque.push(-j);
            range_l[j] = out_l;
            range_r[j] = in_l-1;
        }
        if(in_l != in_r-1){
            j = st[1-parity].min_between(in_l+1, in_r-1);
            pque.push(-j);
            range_l[j] = in_l+1;
            range_r[j] = in_r-1;
        }
        if(in_r != out_r){
            j = st[parity].min_between(in_r+1, out_r);
            pque.push(-j);
            range_l[j] = in_r+1;
            range_r[j] = out_r;
        }
    }
    for(i=0; i<N; i++){
        cout << ans[i] << " \n"[i==N-1];
    }
    return 0;
}

