// Range Minimum Query (区間最小クエリ、RMQ)
// Verified: AOJ DSL_2_A: Range Minimum Query (int型のみ)

template <typename T>
class rmq {
public:
    int n;
    vector<T> dat;

    // 要素数 m の RMQ を作る
    rmq(int m) {
        n = 1;
        while(n < m) n *= 2;
        dat.resize(2*n-1);
        rep(i,0,2*n-1) dat[i] = INT_MAX;
    }

    // k番目 (0-indexed) の値を a に更新
    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    // [a, b) の最小値を返す
    // 最初に呼び出すときは XX.query(a, b, 0, 0, -1) とする
    T query(int a, int b, int k, int l, int r) {
        if(r == -1) r = n;
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return dat[k];
        else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

void pbeasy(vector<pii> &v, int a, int b) {
    v.push_back(pii(a, b));
}

signed main() {
    int N; cin >> N;
    rmq<int> even(N), odd(N);
    rep(i,0,N) {
        cin >> p[i];
        pos[ p[i] ] = i;
        if(i % 2) odd.update(i, p[i]);
        else even.update(i, p[i]);
    }

    vector<pii> ans;
    int lb = INF, ub = INF;
    rep(i,0,N) {
        if(i%2 == 0) {
            if(lb == INF || p[lb] > p[i]) lb = i;
        }
        else {
            if(ub == INF || p[ub] > p[i]) ub = i;
        }
    }
    if(lb > ub) swap(lb, ub);
    pbeasy(ans, p[lb], p[ub]);
    // printf("lb = %lld, ub = %lld\n", lb, ub);

    repq(i,1,N) {
        int x = pos[i], mi;
        if(x == lb || x == ub) continue;
        if(x % 2 == 1 && odd.dat[odd.n-1+x] == INT_MAX) continue;
        if(x % 2 == 0 && even.dat[even.n-1+x] == INT_MAX) continue;
        if(x < lb) {
            if(x % 2) {
                mi = even.query(0, lb, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                even.update(pos[mi], INT_MAX);
                odd.update(x, INT_MAX);
            }
            else {
                mi = odd.query(0, lb, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                odd.update(pos[mi], INT_MAX);
                even.update(x, INT_MAX);
            }
        }
        else if(lb < x && x < ub) {
            if(x % 2) {
                mi = even.query(lb+1, ub, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                even.update(pos[mi], INT_MAX);
                odd.update(x, INT_MAX);
            }
            else {
                mi = odd.query(lb+1, ub, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                odd.update(pos[mi], INT_MAX);
                even.update(x, INT_MAX);
            }
        }
        else {
            if(x % 2) {
                mi = even.query(ub+1, N, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                even.update(pos[mi], INT_MAX);
                odd.update(x, INT_MAX);
            }
            else {
                mi = odd.query(ub+1, N, 0, 0, -1);
                if(mi == INT_MAX) continue;
                pbeasy(ans, p[min(pos[mi], pos[i])], p[max(pos[mi], pos[i])]);
                odd.update(pos[mi], INT_MAX);
                even.update(x, INT_MAX);
            }
        }
        // printf("elem = %lld, mi = %lld\n", i, mi);
    }
    rep(i,0,ans.size()) {
        if(i != 0) cout << " ";
        printf("%lld %lld", ans[i].first, ans[i].second);
    }
    cout << endl;
    return 0;
}

