    //assert(t.lval == lval && t.rval == rval);
    res.push_back(lval), res.push_back(rval);

    auto push=[&A,&B,&Q](int nl,int nr,int flag){
      if(nl > nr) return;
      int idxa,a; tie(idxa,a) = A.find(nl, nr+1);
      int idxb,b; tie(idxb,b) = B.find(nl, nr+1);
      if(idxa > idxb) swap(a,b);
      Q.push(dat(nl, nr, a, b, flag));
    };

    push(nl + 1,nr - 1,flag);
    push(l,nl-1,flag);
    push(nr + 1,r,flag);
  }
  return res;
}

