        return i;
    return a[i] < a[j] ? i : j;
}

struct Node {
    int len = 0;
    int min_odd = -1;
    int min_even = -1;

    Node() = default;

    Node(int len, int min_odd, int min_even): len(len), min_odd(min_odd), min_even(min_even) {}

    void unite(Node other) {
        if (len % 2)
            swap(other.min_odd, other.min_even);
        min_odd = get_min(min_odd, other.min_odd);
        min_even = get_min(min_even, other.min_even);
        len += other.len;
    }
};

Node t[4 * N + 10];
set<int> moved;

void build(int i, int l, int r) {
    if (l == r) {
        t[i] = Node(1, -1, l);
        return;
    }
    int m = (l + r) / 2;
    build(2 * i + 1, l, m);
    build(2 * i + 2, m + 1, r);
    t[i] = t[2 * i + 1];
    t[i].unite(t[2 * i + 2]);
}

void del(int i, int tl, int tr, int pos) {
    if (tl == tr) {
        moved.insert(pos);
        a[pos] = N;
        t[i] = Node(0, -1, -1);
        return;
    }
    int m = (tl + tr) / 2;
    if (pos <= m)
        del(2 * i + 1, tl, m, pos);
    else
        del(2 * i + 2, m + 1, tr, pos);
    t[i] = t[2 * i + 1];
    t[i].unite(t[2 * i + 2]);
}

Node get(int i, int tl, int tr, int l, int r) {
    if (l == tl && r == tr)
        return t[i];
    Node nl;
    Node nr;
    int m = (tl + tr) / 2;
    if (l <= m)
        nl = get(2 * i + 1, tl, m, l, min(r, m));
    if (r > m)
        nr = get(2 * i + 2, m + 1, tr, max(m + 1, l), r);
    nl.unite(nr);
    return nl;
}

