inline void push_up(int a)
{
     if(sum[a * 2] < sum[a * 2 + 1])
        sum[a] = sum[a * 2], id[a] = id[a * 2];
     else
        sum[a] = sum[a * 2 + 1], id[a] = id[a * 2 + 1];
     if(sum2[a * 2] < sum2[a * 2 + 1])
        sum2[a] = sum2[a * 2], id2[a] = id2[a * 2];
     else
        sum2[a] = sum2[a * 2 + 1], id2[a] = id2[a * 2 + 1];
}

void build(int l, int r, int nn)
{
    sum[nn] = sum2[nn] = inf;
    if(l == r)
    {
        if(l&1)
            sum[nn] = num[l], id[nn] = l;
        else
            sum2[nn] = num[l], id2[nn] = l;
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, nn * 2);
    build(mid + 1, r, nn * 2 + 1);
    push_up(nn);
}

void get(int l, int r, int nn, int ll, int rr)
{
    if(l >= ll&&r <= rr)
    {
        if(ll&1)
        {
            if(ans > sum[nn])
                ans = sum[nn], ans2 = id[nn];
        }
        else
        {
            if(ans > sum2[nn])
                ans = sum2[nn], ans2 = id2[nn];
        }
        return;
    }
    if(l > rr||r < ll)
        return;
    int mid = (l + r) / 2;
    get(l, mid, nn * 2, ll, rr);
    get(mid + 1, r, nn * 2 + 1, ll, rr);
}

void solve(int l, int r, int fa)
{
    if(l > r)
        return;
    ans = inf;
    get(1, n, 1, l, r);
    int pos = ans2;
    ans = inf;
    get(1, n, 1, pos + 1, r);
    int pos2 = ans2;
    an++;
    ans3[an].a = num[pos];
    ans3[an].b = num[pos2];
    ans3[an].id = an;
    if(fa != -1)
        eg[fa].push_back(an), du[an]++;
    int tmp = an;
    solve(l, pos - 1, tmp);
    solve(pos + 1, pos2 - 1, tmp);
    solve(pos2 + 1, r, tmp);
    return;
}

