const int INF = numeric_limits<int>::max();

template<typename T>
struct SegmentTree {

	T id;
	function <T(T, T)> op;
	vector<T> dat;
	int size;

	SegmentTree(int n, T id, function <T(T, T)> op) : id(id), op(op) {
		size = 1;
		while (size < n) size <<= 1;
		dat.assign(size * 2 + 10, id);
	}

	void update(int k, T x) {
		k += size, dat[k] = x;
		while (k > 1) k >>= 1, dat[k] = op(dat[k << 1], dat[(k << 1) | 1]);
	}

	void merge(int k, T x) { update(k, op(x, dat[k + size])); }
	//[a, b)
	T query(int a, int b) {
		T tl = id, tr = id;
		for (int l = a + size, r = b + size; l < r; l >>= 1, r >>= 1) {
			if (l & 1) tl = op(tl, dat[l++]);
			if (r & 1) tr = op(tr, dat[--r]);
		}
		return (op(tl, tr));
	}
};


int main()
{
	int N; cin >> N;
	vint pos(N+1);

	SegmentTree<int> seg1(N, INF, [](int a, int b) { return (min(a, b)); } );
	SegmentTree<int> seg2(N, INF, [](int a, int b) { return (min(a, b)); } );

	auto inspect = [&](int l, int r) {
		int val1 = (l&1?seg2:seg1).query(l, r);
		int val2 = (l&1?seg1:seg2).query(pos[val1], r);
		return (Pi(val1, val2));
	};

	for (int i = 0; i < N; i++) {
		int A;
		cin >> A;
		(i&1?seg2:seg1).update(i, A);
		pos[A] = i;
	}

	priority_queue<pair<Pi, Pi>, vector<pair<Pi, Pi>>, greater<pair<Pi, Pi>>> que;
	que.emplace(inspect(0, N), Pi(0, N));

	vint ans;

	while (!que.empty()) {
		Pi value, range;
		int l, r;
		tie(value, range) = que.top(); que.pop();	
		tie(l, r) = range;
		ans.push_back(value.first); ans.push_back(value.second);
		int posl = pos[value.first], posr = pos[value.second];

		if (l + 1 < posl) que.emplace(inspect(l, posl), Pi(l, posl));
		if (posl + 2 < posr) que.emplace(inspect(posl + 1, posr), Pi(posl + 1, posr));
		if (posr + 2 < r) que.emplace(inspect(posr + 1, r), Pi(posr + 1, r));
	}
	cout << ans[0];
