int m;
pii seg[N];

pii getpos(int x) {
	int l = seg[x].F, r = seg[x].S;
	int p1 = get(l & 1, l, r);
	int p2 = get((l & 1) ^ 1, p1 + 1, r);
	return {p1, p2};
}

int getans(int x) {
	int l = seg[x].F, r = seg[x].S;
	int p1 = get(l & 1, l, r);
	return p[p1];
}

void dijkstra(int L, int R) {
	seg[++m] = {L, R};
	priority_queue <pii, vector <pii>, greater <pii> > pq;
	pq.push({getans(m), m});
	while (!pq.empty()) {
		pii cur = pq.top();
		pq.pop();

		int l = seg[cur.S].F, r = seg[cur.S].S;
		if (r - l + 1 >= 2) {
			pii pos = getpos(cur.S);
			ans[++k] = p[pos.F];
			ans[++k] = p[pos.S];

			seg[++m] = {l, pos.F - 1};
			pq.push({getans(m), m});
			seg[++m] = {pos.F + 1, pos.S - 1};
			pq.push({getans(m), m});
			seg[++m] = {pos.S + 1, r};
			pq.push({getans(m), m});
		}
	}
}

