class Solver {
  public:
    int N;
    vector<int> P;
    vector<pii> solve(int s, int e) {
        if(e <= s) return {};
        int p = s;
        for(int i = s; i < e; i += 2) {
            if(P[p] > P[i]) p = i;
        }
        int q = p + 1;
        for(int i = q; i < e; i += 2) {
            if(P[q] > P[i]) q = i;
        }

        vector<pii> res;
        res.push_back(make_pair(P[p], P[q]));
        vector<vector<pii>> tmp;
        tmp.push_back(solve(s, p));
        tmp.push_back(solve(p + 1, q));
        tmp.push_back(solve(q + 1, e));
        vector<pii> tmp2;
        rep(i, tmp.size()) for(auto a : tmp[i]) tmp2.push_back(a);
        sort(all(tmp2));
        for(auto a : tmp2) res.push_back(a);
        return res;
    }
    bool solve() {
        cin >> N;
        P.resize(N); cin >> P;
        auto res = solve(0, N);
        vector<int> ans;
        for(auto a : res) {
            ans.push_back(a.first);
            ans.push_back(a.second);
        }
        rep(i, N) {
            cout << ans[i] << (i == N - 1 ? "\n" : " ");
        }        
        return 0;
    }
};

