#include <cstdio>

#define Rep(i, n) for (int i = 1; i <= n; i ++)

using namespace std;

const int N = 200010;

int p[N];

struct Tr{
	int mx, mx0, mx1;
	int mxi, mx0i, mx1i;
	int l0, r0;
}t[N * 4];

void up(Tr &x, Tr lc, Tr rc)
{
	if (lc.mx > rc.mx) x.mx = lc.mx, x.mxi = lc.mxi;
	else x.mx = rc.mx, x.mxi = rc.mxi;
	if (lc.mx0 > rc.mx0) x.mx0 = lc.mx0, x.mx0i = lc.mx0i;
	else x.mx0 = rc.mx0, x.mx0i = rc.mx0i;
	if (lc.mx1 > rc.mx1) x.mx1 = lc.mx1, x.mx1i = lc.mx1i;
	else x.mx1 = rc.mx1, x.mx1i = rc.mx1i;

	if (lc.l0) x.l0 = lc.l0;
	else x.l0 = rc.l0;
	if (rc.r0) x.r0 = rc.r0;
	else x.r0 = lc.r0;
}

void build(int x, int l, int r)
{
	if (l == r) {
		if (l & 1) t[x].mx = t[x].mx1 = p[l], t[x].mxi = t[x].mx1i = l;
		else t[x].mx = t[x].mx0 = p[l], t[x].mxi = t[x].mx0i = l; 
		return;
	}
	int mid = (l + r) >> 1;
	build(x << 1, l, mid); build(x << 1 | 1, mid + 1, r);
	up(t[x], t[x << 1], t[x << 1 | 1]);
}

void modify(int x, int l, int r, int a)
{
	if (l == r) {
		if (l & 1) t[x].mx = t[x].mx1 = 0;
		else t[x].mx = t[x].mx0 = 0;
		t[x].l0 = t[x].r0 = l;
		return;
	}
	int mid = (l + r) >> 1;
	if (a <= mid) modify(x << 1, l, mid, a);
	else modify(x << 1 | 1, mid + 1, r, a);
	up(t[x], t[x << 1], t[x << 1 | 1]);
}

Tr query(int x, int l, int r, int a, int b)
{
	if (a <= l && r <= b) return t[x];
	int mid = (l + r) >> 1;
	Tr ret = (Tr){0, 0, 0}, lc = (Tr){0, 0, 0}, rc = (Tr){0, 0, 0};
	if (a <= mid) lc = query(x << 1, l, mid, a, b);
	if (b > mid) rc = query(x << 1 | 1, mid + 1, r, a, b);
	up(ret, lc, rc);
	return ret;
}

int ans[N];

int main()
{
	int n;
	scanf("%d", &n);
	Rep(i, n){ scanf("%d", &p[i]); p[i] = n + 1 - p[i];}

	build(1, 1, n);

	Rep(i, n / 2){
		Tr t1 = query(1, 1, n, 1, n);
		int tr = query(1, 1, n, t1.mxi, n).l0;
		if (!tr) tr = n + 1;
		if ((tr - 1 - t1.mxi) & 1) {
			ans[i * 2 - 1] = t1.mx;
			Tr t0 = query(1, 1, n, t1.mxi + 1, tr - 1);
			if (t1.mxi & 1){
				ans[i * 2] = t0.mx0;
				modify(1, 1, n, t0.mx0i);	
			}
			else {
				ans[i * 2] = t0.mx1;
				modify(1, 1, n, t0.mx1i);
			}
		}
		else {
			ans[i * 2] = t1.mx;
			int tl = query(1, 1, n, 1, t1.mxi).r0;
			Tr t0 = query(1, 1, n, tl + 1, t1.mxi - 1);
			if (t1.mxi & 1 - 1){
				ans[i * 2 - 1] = t0.mx0;
				modify(1, 1, n, t0.mx0i);	
			}
			else {
				ans[i * 2 - 1] = t0.mx1;
				modify(1, 1, n, t0.mx1i);
			}
		}

		modify(1, 1, n, t1.mxi);
	}

	Rep(i, n) printf("%d ", n + 1 - ans[i]);

	return 0;
}

