#define MOD 1000000007

int P[200010], R[200010];
vector<int> es(524288, INT32_MAX), os = es;

int smin(vector<int>& V, int& s, int& t, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s) {
		return INT32_MAX;
	}
	if (s <= l && r <= t) {
		return V[k];
	}
	int lv = smin(V, s, t, k * 2, l, (l + r) / 2);
	int rv = smin(V, s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return min(lv, rv);
}

void segfy(vector<int>& V) {
	for (int i = 262143;i > 0;i--) {
		V[i] = min(V[i * 2], V[i * 2 + 1]);
	}
}

queue<pair<int, int>> ans(int s, int t, bool e = 1) {
	queue<pair<int, int>> ret;
	if (s > t) {
		ret.push({ MOD,MOD });
		return ret;
	}
	if (s + 1 == t) {
		ret.push({ P[s],P[t] });
		ret.push({ MOD,MOD });
		return ret;
	}

	int lv, rv, l, r;
	if (e) {
		lv = smin(os, s, t);
		l = R[lv];
		rv = smin(es, l, t);
		r = R[rv];
		ret.push({ lv,rv });
	}
	else {
		lv = smin(es, s, t);
		l = R[lv];
		rv = smin(os, l, t);
		r = R[rv];
		ret.push({ lv,rv });
	}

	auto ret1 = ans(s, l - 1, e);
	auto ret2 = ans(l + 1, r - 1, !e);
	auto ret3 = ans(r + 1, t, e);

	bool r1 = (ret1.front().first != MOD),
		r2 = (ret2.front().first != MOD),
		r3 = (ret3.front().first != MOD);

	while (r1 || r2 || r3) {
		auto t1 = ret1.front();
		auto t2 = ret2.front();
		auto t3 = ret3.front();

		if (t1 < t2 && t1 < t3) {
			ret.push(t1);
			ret1.pop();
			if (ret1.size() == 1)r1 = 0;
		}
		else if (t2 < t1 && t2 < t3) {
			ret.push(t2);
			ret2.pop();
			if (ret2.size() == 1)r2 = 0;
		}
		else {
			ret.push(t3);
			ret3.pop();
			if (ret3.size() == 1)r3 = 0;
		}
	}
	ret.push({ MOD,MOD });
	return ret;
}

