template<typename Type>
class RMQ {
private:
	int size_; std::vector<Type> dat;
public:
	RMQ() : size_(0), dat(std::vector<Type>()) {};
	RMQ(int size__) {
		for (size_ = 1; size_ < size__; ) size_ <<= 1;
		dat.resize(size_ << 1, std::numeric_limits<Type>::max());
	}
	template<class T>
	RMQ(T begin_, T end_) {
		int n = end_ - begin_;
		for (size_ = 1; size_ < n; size_ <<= 1); dat.resize(size_ << 1, std::numeric_limits<Type>::max());
		for (int i = 0; i < n; i++) dat[i + size_] = *(begin_ + i);
		for (int i = size_ - 1; i > 0; i--) dat[i] = std::min(dat[i << 1], dat[(i << 1) + 1]);
	}
	inline unsigned size() { return size_; }
	inline void update(unsigned i, Type x) {
		i += size_; dat[i] = x;
		while (i > 1) {
			i >>= 1;
			dat[i] = std::min(dat[i << 1], dat[i << 1 | 1]);
		}
	}
	inline Type query(unsigned l, unsigned r) {//(l,r]
		Type ret = std::numeric_limits<Type>::max();
		l += size_; r += size_;
		while (l != r) {
			if (l & 1) ret = std::min(ret, dat[l++]); l >>= 1;
			if (r & 1) ret = std::min(ret, dat[--r]); r >>= 1;
		}
		return ret;
	}
};
int n;
int t[500001];
vector<P>ans;
signed main() {
	cin >> n;
	RMQ<int>A(n), B(n);//偶数番目  奇数番目
	for (int i = 0; i < n; i++) {
		int a; cin >> a;
		t[a] = i;
		if (i & 1) {
			B.update(i / 2, a);
		}
		else {
			A.update(i / 2, a);
		}
	}
	priority_queue<p, vector<p>, greater<p>>Q;
	Q.push({ A.query(0, n / 2) ,{0,n} });
	while (Q.size()) {
		p w = Q.top(); Q.pop();
		int x = w.second.first, y = w.second.second;
		if (x >= y)continue;
		if (x & 1) {
			int S = B.query(x / 2, y / 2);
			int index = t[S];
			int K = A.query(index / 2 + 1, y / 2 + 1);
			int o = t[K];
			ans.push_back({ S,K });
			Q.push({ B.query(x / 2,index / 2),{x,index} });
			Q.push({ A.query((index+1) / 2,o / 2),{ index + 1, o } });
			Q.push({ B.query((o+1) / 2,y / 2),{ o + 1, y } });
		}
		else {
			int S = A.query(x / 2, y / 2);
			int index = t[S];
			int K = B.query(index / 2, y / 2);
			int o = t[K];
			ans.push_back({ S,K });
			Q.push({ A.query(x / 2,index / 2),{ x,index } });
			Q.push({ B.query((index + 1) / 2,o / 2),{ index + 1, o } });
			Q.push({ A.query((o + 1) / 2,y / 2),{ o + 1, y } });
		}
	}
	for (int i = 0; i < n / 2; i++) {
		if (i)cout << " ";
		cout << ans[i].first << " " << ans[i].second;
	}
	cout << endl;
}

