    res3 = check(at[b] + 1, r);

    i1 = i2 = i3 = 0;
    while (i1 < (int)res1.size() || i2 < (int)res2.size() || i3 < (int)res3.size()) {
        if (i1 >= (int)res1.size()) {
            if (i2 >= (int)res2.size()) {
                res.push_back(res3[i3]); i3++;
            } else if (i3 >= (int)res3.size()) {
                res.push_back(res2[i2]); i2++;
            } else {
                if (res2[i2] < res3[i3]) {
                    res.push_back(res2[i2]); i2++;
                } else {
                    res.push_back(res3[i3]); i3++;
                }
            }
        } else {
            if (i2 >= (int)res2.size()) {
                if (i3 >= (int)res3.size()) {
                    res.push_back(res1[i1]); i1++;
                } else if (res1[i1] < res3[i3]) {
                    res.push_back(res1[i1]); i1++;
                } else {
                    res.push_back(res3[i3]); i3++;
                }
            } else if (i3 >= (int)res3.size()) {
                if (res1[i1] < res2[i2]) {
                    res.push_back(res1[i1]); i1++;
                } else {
                    res.push_back(res2[i2]); i2++;
                }
            } else {
                if (res1[i1] < res2[i2]) {
                    if (res1[i1] < res3[i3]) {
                        res.push_back(res1[i1]); i1++;
                    } else {
                        res.push_back(res3[i3]); i3++;
                    }
                } else {
                    if (res2[i2] < res3[i3]) {
                        res.push_back(res2[i2]); i2++;
                    } else {
                        res.push_back(res3[i3]); i3++;
                    }
                }
            }
        }
    }

    // cout << "check(" << l << ", " << r << ")" << endl;
    // for (int i = 0; i < (int)res.size(); i++) {
    //     cout << res[i].first << ' ' << res[i].second << (i == (int)res.size() - 1 ? '\n' : ' ');
    // }

    return res;
}

