class SparseTable
{
private:
    vector<int> logTable;
    vector<vector<int> > data;
public:
    SparseTable(const vector<int>& v){
        int n = v.size();
        logTable.assign(n+1, 0);
        for(int i=2; i<=n; ++i)
            logTable[i] = logTable[i>>1] + 1;

        data.assign(1, v);
        for(int i=1; (1<<i)<=n; ++i){
            int len = 1 << i;
            data.push_back(vector<int>(n - len + 1));
            for(int j=0; j<n-len+1; ++j)
                data[i][j] = min(data[i-1][j], data[i-1][j+len/2]);
        }
    }
    int query(int a, int b){ // 区間[a,b)の最小値を返す
        int i = logTable[b-a];
        int len = 1 << i;
        return min(data[i][a], data[i][b-len]);
    }
};

const int INF = INT_MAX / 2;

void solve(const vector<int>& v, vector<int>& ans)
{
    int n = v.size();
    vector<int> pos(n);
    vector<vector<int> > v2(2, vector<int>(n, INF));
    for(int i=0; i<n; ++i){
        pos[v[i]] = i;
        v2[i%2][i] = v[i];
    }

    vector<SparseTable> st = {v2[0], v2[1]};
    priority_queue<int, vector<int>, greater<int> > pq;
    pq.push(st[0].query(0, n));
    set<int> usedPos;
    usedPos.insert(-1);
    usedPos.insert(n);

    ans.clear();
    while(!pq.empty()){
        int x = pq.top();
        pq.pop();

        int i = pos[x];
        auto it = usedPos.upper_bound(i);
        int b = *it;
        -- it;
        int a = *it;
        if((i - a) % 2 == 0)
            continue;

        int y = st[(b+1)%2].query(i+1, b);
        int j = pos[y];
        ans.push_back(x);
        ans.push_back(y);
        usedPos.insert(i);
        usedPos.insert(j);

        vector<int> tmp = {a, i, j, b};
        for(int k=0; k<3; ++k){
            if(tmp[k] + 1 == tmp[k+1])
                continue;
            int z = st[tmp[k+1]%2].query(tmp[k]+1, tmp[k+1]);
            pq.push(z);
        }
    }
}

int main()
{
    int n;
    cin >> n;
    vector<int> v(n);
    for(int i=0; i<n; ++i){
        cin >> v[i];
        -- v[i];
    }

    vector<int> ans;
    solve(v, ans);
    for(int i=0; i<n; ++i)
        ++ ans[i];

    cout << ans[0];
    for(int i=1; i<n; ++i)
        cout << ' ' << ans[i];
    cout << endl;

    return 0;
}

