	Segtree() : size(1 << 18)
	{
		fill_n(data, 1 << 19 + 2, Pi(INF, INF));
	}

	void update(int k, int x)
	{
		k += size - 1;
		data[k] = Pi(x, k - size + 1);
		while(k != 0) {
			k = (k - 1) >> 1;
			data[k] = min(data[k * 2 + 1], data[k * 2 + 2]);
		}
	}

