	{
		return (query(a, b, 0, 0, size - 1));
	}

	Pi query(int a, int b, int k, int l, int r)
	{
		if(b < l || r < a) return (Pi(INF, INF));
		if(a <= l && r <= b) return (data[k]);
		return (min(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2 + 1, r)));
