		if(d.nmpos - 1 - d.mpos - 1 != -1) pq.push( getNode(d.mpos + 1, d.nmpos - 1) );
		if(d.r - d.nmpos - 1 != -1) pq.push( getNode(d.nmpos + 1, d.r) );
	}
	cout << endl;
	return (0);
}

Node getNode(int l, int r)
{
	int mpos, nmpos;
	if(l % 2 == 0) {
		mpos = tree1.query(l, r).second, nmpos = tree2.query(mpos + 1, r).second;
	} else {
		mpos = tree2.query(l, r).second, nmpos = tree1.query(mpos + 1, r).second;
	}
	return ((Node) { l, r, mpos, nmpos, P[mpos], P[nmpos] } );
}

