pair<int, int>vert[214514];
vector<int>dag[214514];
vector<segment>sg;
int N;

int ceil(int a, int b)
{
	assert(a >= 0);
	if (a == 0)return 0;
	return (a - 1) / b + 1;
}

int NEXT_V = 0;
int next_v()
{
	NEXT_V++;
	return NEXT_V - 1;
}

int main(void)
{
	cin >> N;
	sg.push_back(segment(N / 2));
	sg.push_back(segment(N / 2));
	for (int i = 0; i < N; ++i)
	{
		int p; cin >> p;
		sg[i % 2].update(i / 2, make_pair(p, i));
	}
	function<void(int, int, int, bool)>f = [&](int L, int R, int now, bool turn)
	{
		assert((R - L) % 2 == 0);
		assert(R - L);
		pair<int, int> one, two;
		if (turn)
		{
			//反転
			one = sg[1].query(L / 2, R / 2);
			two = sg[0].query(ceil(one.second, 2), ceil(R, 2));
		}
		else
		{
			//反転していない
			one = sg[0].query(ceil(L, 2), ceil(R, 2));
			two = sg[1].query(one.second / 2, R / 2);
		}
		vert[now] = make_pair(one.first, two.first);
		if (L < one.second)
		{
			int next = next_v();
			dag[now].push_back(next);
			f(L, one.second, next, turn ^ false);
		}
		if (one.second + 1 < two.second)
		{
			int next = next_v();
			dag[now].push_back(next);
			f(one.second + 1, two.second, next, turn ^ true);
		}
		if (two.second + 1 < R)
		{
			int next = next_v();
			dag[now].push_back(next);
			f(two.second + 1, R, next, turn ^ false);
		}
	};
	f(0, N, next_v(), false);
	priority_queue<pair<pair<int, int>, int>,vector<pair<pair<int, int>, int>>,Compare>que;
	//first:値　second:index
	que.push(make_pair(vert[0], 0));
	vector<int>ans;
	while (!que.empty())
	{
		auto p = que.top(); que.pop();
		ans.push_back(p.first.first);
		ans.push_back(p.first.second);
		for (int next : dag[p.second])
		{
			que.push(make_pair(vert[next], next));
		}
	}
	for (int i = 0; i < N; ++i)
	{
		cout << ans[i] << " \n"[i == N - 1];
	}
	return 0;
}

#include <bits/stdc++.h>
#define ls (o << 1)
#define rs (o << 1 | 1)
#define mid ((L + R) >> 1)
using namespace std;
typedef long long LL;
const int N = 200500;
const int mod = 1e9 + 7;
int p[N], n, tr[N << 2][2];
void build(int o, int L, int R) {
	if (L + 1 == R) {
		tr[o][L & 1] = L;
		tr[o][R & 1] = n;
		return;
	}
	build(ls, L, mid);
	build(rs, mid, R);
	tr[o][0] = p[tr[ls][0]] < p[tr[rs][0]] ? tr[ls][0] : tr[rs][0];
	tr[o][1] = p[tr[ls][1]] < p[tr[rs][1]] ? tr[ls][1] : tr[rs][1];
}
pair<int, int> q(int o, int L, int R, int l, int r) {
	if (l <= L && R <= r) {
		return make_pair(tr[o][0], tr[o][1]);
	}
	if (l >= mid)
		return q(rs, mid, R, l, r);
	else if (r <= mid)
		return q(ls, L, mid, l, r);

	auto t1 = q(ls, L, mid, l, r);
	auto t2 = q(rs, mid, R, l, r);
	return make_pair(p[t1.first] < p[t2.first] ? t1.first : t2.first,
	                 p[t1.second] < p[t2.second] ? t1.second : t2.second);
}
typedef pair<int, int> PII;
vector<PII> ans;
bool cmp(const PII &o, const PII &p) {
	return min(o.first, o.second) < min(p.first, p.second);
}
void solve(int l, int r) {
	if (r - l == 0) return;
	if (r - l == 2) {
		ans.push_back(make_pair(p[l], p[l + 1]));
		return;
	}
	auto ret = q(1, 0, n, l, r);
	if (p[ret.first] < p[ret.second]) {
		if (ret.first + 1 < r) {
			auto nxt = q(1, 0, n, ret.first + 1, r);
			ans.push_back(make_pair(p[ret.first], p[nxt.second]));
			solve(l, ret.first);
			solve(ret.first + 1, nxt.second);
			solve(nxt.second + 1, r);
		} else {
			ans.push_back(make_pair(p[ret.second], p[ret.first]));
			solve(l, ret.second);
			solve(ret.second + 1, ret.first);
		}
	} else {
		if (ret.second + 1 < r) {
			auto nxt = q(1, 0, n, ret.second + 1, r);
			ans.push_back(make_pair(p[ret.second], p[nxt.first]));
			solve(l, ret.second);
			solve(ret.second + 1, nxt.first);
			solve(nxt.first + 1, r);
		} else {
			ans.push_back(make_pair(p[ret.first], p[ret.second]));
			solve(l, ret.first);
			solve(ret.first + 1, ret.second);
		}
	}
}
