pint val[222222];

void solve(int l,int r){
    int x,y;
    if(l%2==0){
        x=even.get_min(l,r).se;
        y=odd.get_min(x+1,r).se;
    }
    else{
        x=odd.get_min(l,r).se;
        y=even.get_min(x+1,r).se;
    }

    val[cur]={P[x],P[y]};

    int v=cur;
    cur++;
    if(x!=l){
        G[v].pb(cur);
        solve(l,x);
    }
    if(x+1!=y){
        G[v].pb(cur);
        solve(x+1,y);
    }
    if(y+1!=r){
        G[v].pb(cur);
        solve(y+1,r);
    }
}

