void rgeupd (int l, int r, int i) {
	if (l > y || r < x) return;
	else if (x <= l && r <= y) {
		lazy[i] = z; return;
	}
	int m = (l + r) >> 1;
	rgeupd(l, m, i << 1); rgeupd(m + 1, r, (i << 1) + 1);
	if (lazy[i << 1].fi < lazy[(i << 1) + 1].fi) lazy[i] = lazy[i << 1];
	else lazy[i] = lazy[(i << 1) + 1];
	//cout << lazy[i << 1].fi << ' ' << lazy[(i << 1) + 1].fi << endl;
	//cout << l << ' ' << r << ' ' << lazy[i].fi << ' ' << lazy[i].se << endl;
	return;
}
pii query (pii *seg, int l, int r, int i) {
	if (l > y || r < x) return {inf, -1};
	else if (x <= l && r <= y) return seg[i];
	int m = (l + r) >> 1;
	pii lc = query(seg, l, m, i << 1);
	pii rc = query(seg, m + 1, r, (i << 1) + 1);
	if (lc.fi < rc.fi) return lc;
	else return rc;
}
