const int sz=2e5+7;
int a[sz],n,pos[sz];
int xds[sz*4][2];
void build(int nd,int L,int r)
{	int mid=(L+r)/2;
	if(L==r)
	{	xds[nd][0]=xds[nd][1]=sz;
		xds[nd][L%2]=a[L]; return ;
	}
	build(nd*2,L,mid); build(nd*2+1,mid+1,r);
	for(int ii=0;ii<2;ii++)
		xds[nd][ii]=min(xds[nd*2][ii],xds[nd*2+1][ii]);
}
int ask(int nd,int L,int r,int x,int y,int k)
{	int mid=(L+r)/2;
	if(L>y||r<x) return sz;
	if(L>=x&&r<=y) return xds[nd][k];
	return min(ask(nd*2,L,mid,x,y,k),ask(nd*2+1,mid+1,r,x,y,k));
}
struct ST
{	int l,r,v;
	ST(int aa=0,int bb=0,int cc=0):l(aa),r(bb),v(cc){}
	bool operator < (const ST& rsh) const
	{
		return v>rsh.v;
	}
};
priority_queue<ST> Q;
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++){scanf("%d",&a[i]); pos[a[i]]=i;}
	build(1,1,n);
	while(!Q.empty()) Q.pop();
	int v=ask(1,1,n,1,n,1);
	Q.push(ST(1,n,v));
	for(int i=2;i<=n;i+=2)
	{	ST t=Q.top(); Q.pop();
		v=ask(1,1,n,t.l,t.r,t.l%2);
