		v=ask(1,1,n,p+1,t.r,(p+1)%2);
		printf("%d%c",v,i<n?' ':'\n');
		int pp=pos[v];
		if(t.l<p-1)
		{	v=ask(1,1,n,t.l,p-1,t.l%2);
			Q.push(ST(t.l,p-1,v));
		}
		if(p+1<pp-1)
		{	v=ask(1,1,n,p+1,pp-1,(p+1)%2);
			Q.push(ST(p+1,pp-1,v));
		}
		if(pp+1<t.r)
		{	v=ask(1,1,n,pp+1,t.r-1,(pp+1)%2);
