    bool operator < (const Node &A)const{
        return a[l] > a[A.l];
    }
};

void init(int op){
    for(int i=1; i<=n; i++){
        dp[op][i][0] = b[op][i];
        key[op][i][0] = i;
    }

    for(int j=1; j<L; j++){
        for(int i=1; i<=n; i++){
            int k = i + (1 << (j - 1));
            if(k > n)   k = n;
            if(dp[op][i][j-1] < dp[op][k][j-1]){
                key[op][i][j] = key[op][i][j-1];
            } else {
                key[op][i][j] = key[op][k][j-1];
            }
            dp[op][i][j] = b[op][key[op][i][j]];
        }
    }
}

priority_queue<Node> Q;
Node nd;

int query(int op, int l, int r){
    int g = len[r - l + 1];
    int k = r - (1 << g) + 1;
    if(dp[op][l][g] < dp[op][k][g]){
        return key[op][l][g];
    } else {
        return key[op][k][g];
    }
}

int getkey(int l, int r){
    return query(l & 1, l, r);
}

