void segbuild(Node *u, int k){
	if(u->lo == u->hi){
		u->mn = (u->lo & 1) == k ? a[u->lo] : INF;
	}else{
		int mi = u->lo + u->hi >> 1;
		u->lchi = new Node(u->lo, mi);
		u->rchi = new Node(mi+1, u->hi);
		segbuild(u->lchi, k); segbuild(u->rchi, k);
		u->mn = min(u->lchi->mn, u->rchi->mn);
	}
}

int segquery(Node *u, int l, int r){
	if(l == u->lo && r == u->hi)
		return u->mn;
	int mi = u->lo + u->hi >> 1;
	if(r <= mi)
		return segquery(u->lchi, l, r);
	else if (l > mi)
		return segquery(u->rchi, l, r);
	else{
		int resl = segquery(u->lchi, l, mi);
		int resr = segquery(u->rchi, mi+1, r);
		return min(resl, resr);
	}
}

