const int INF = 1e9 + 7;

struct segtree{
    static const int SEG=1<<18;
    vector<P> dat;
    segtree():dat(SEG*2, P(INF,INF)){}
    void update(int k, P p){
        k+=SEG-1;
        dat[k]=p;
        while(k){
            k=(k-1)/2;
            dat[k]=min(dat[k*2+1],dat[k*2+2]);
        }
    }
    P query(int a,int b,int k=0,int l=0,int r=SEG){
        if(r<=a||b<=l)return P(INF,INF);
        if(a<=l&&r<=b)return dat[k];
        return min(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
};

int n;
int p[200005];

segtree odd,even;

typedef tuple<P,P,P> T;

T calc(int l, int r) {
    int ll, rr;
    if (l%2 == 1) {
        ll = odd.query(l,r).second;
        rr = even.query(ll,r).second;
    } else {
        ll = even.query(l,r).second;
        rr = odd.query(ll,r).second;
    }
    return T({p[ll], p[rr]}, {ll,rr}, {l,r});
}

