void push_up(node a,node b,node &ret) {
    if (a.x<b.x) ret=a;
    else ret=b;
}
void fill(int l,int r,int cur,int t) {
    if (l==r) {
        if (l%2==t) seg[t][cur]={a[l],l};
        else seg[t][cur]={0x3f3f3f3f,0x3f3f3f3f};
        return;
    }
    fill(l,(l+r)/2,2*cur+1,t);
    fill((l+r)/2+1,r,2*cur+2,t);
    push_up(seg[t][2*cur+1],seg[t][2*cur+2],seg[t][cur]);
}
node que(int l,int r,int tl,int tr,int cur,int t) {
    if (r<tl or tr<l) return {0x3f3f3f3f,0x3f3f3f3f};
    if (tl<=l and r<=tr) return seg[t][cur];
    node a=que(l,(l+r)/2,tl,tr,2*cur+1,t);
    node b=que((l+r)/2+1,r,tl,tr,2*cur+2,t),ret;
    push_up(a,b,ret);
    return ret;
}
void func(int l,int r,int cur) {
    if (l>r) {ans[cur]={0x3f3f3f3f,0x3f3f3f3f}; return;}
    int ind=-1;
    if (l%2==0) ind=que(0,n-1,l,r,0,0).ind;
    else ind=que(0,n-1,l,r,0,1).ind;
    int ind2=que(0,n-1,ind+1,r,0,(l%2==0)).ind;
    ans[cur]={a[ind],a[ind2]};
    func(l,ind-1,3*cur+1); func(ind+1,ind2-1,3*cur+2); func(ind2+1,r,3*cur+3);
}
