    auto pe = rmq_preprocess(even);
    auto po = rmq_preprocess(odd);
    priority_queue<state, vector<state>, compare_state> q;
    state root = build(odd, po, even, pe, 0, n, false);
    q.emplace(root);
    vl answer;
    while(not q.empty()) {
      state a = q.top(); q.pop();
      answer.emplace_back(v[a.x]);
