        q.emplace(build(odd, po, even, pe, a.x + 1, a.y, not a.inverse));
      }
      if (a.to - a.y > 1) {
        q.emplace(build(odd, po, even, pe, a.y + 1, a.to, a.inverse));
      }
    }
