void go(int lq, int rq, int h)
{
	if (lq >= rq)
		return ;

	pair<int, int> ft, sc;

	if (lq & 1 ^ 1)
	{
		ft = ev.get(lq, rq);
		sc = od.get(ft.second, rq);
	}
	else
	{
		ft = od.get(lq, rq);
		sc = ev.get(ft.second, rq);
	}

	pp[h].push_back(make_pair(ft.first, sc.first));
	go(lq, ft.second - 1, h + 1);
	go(ft.second + 1, sc.second - 1, h + 1);
	go(sc.second + 1, rq, h + 1);
}

void solve()
{
	ev = od = segtree(n);

	forn (i, n)
		if (i & 1)
		{
			od.upd(i, p[i]);
			ev.upd(i, inf);
		}
		else
		{
			ev.upd(i, p[i]);
			od.upd(i, inf);
		}

	go(0, n - 1, 0);

	forn (i, maxn)
		if (!pp[i].empty())
		{
			sort(pp[i].begin(), pp[i].end());

			for (auto k : pp[i])
				printf("%d %d ", k.first, k.second);
