void upd(int v, int l, int r, int pos, int val) {
    if (l == r - 1) {
        tree[v][!(l % 2)] = INF;
        tree[v][l % 2] = val;
    }
    else {
        int mid = (l + r) / 2;
        if (pos < mid) {
            upd(v * 2 + 1, l, mid, pos, val);
        }
        else {
            upd(v * 2 + 2, mid, r, pos, val);
        }
        for (int i = 0; i <= 1; i++) tree[v][i] = min(tree[v * 2 + 1][i], tree[v * 2 + 2][i]);
    }
}

pair<ll, ll> get(int v, int l, int r, int askl, int askr) {
    if (l >= askr || r <= askl) return { INF, INF };

    if (l >= askl && r <= askr) return { tree[v][0], tree[v][1] };

    int mid = (l + r) / 2;
    pair<ll, ll> q = get(v * 2 + 1, l, mid, askl, askr), q2 = get(v * 2 + 2, mid, r, askl, askr);

    return { min(q.first, q2.first), min(q.second, q2.second) };
}
