using namespace std;

const int inf = 1e9 + 7;
const int N = 2e5 + 5;

typedef long long ll;

int n, a[N];
pair <int, int> t[N * 4][2];
deque < pair <int, int> > ans;

void build(int v = 1, int tl = 1, int tr = n)
{
      if(tl == tr)
      {
            t[v][tl % 2] = mk(a[tl], tl);
            t[v][(tl % 2) ^ 1] = mk(inf, 0);
      }
      else
      {
            int tm = (tl + tr) >> 1;
            build(v << 1, tl, tm);
            build((v << 1) | 1, tm + 1, tr);
            t[v][0] = min(t[v << 1][0], t[(v << 1) | 1][0]);
            t[v][1] = min(t[v << 1][1], t[(v << 1) | 1][1]);
      }
}

pair <int, int> get(int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
      if(l > tr || tl > r) return mk(inf, 1);
      if(l <= tl && tr <= r) return t[v][type];
      int tm = (tl + tr) >> 1;
      return min(get(l, r, type, v << 1, tl, tm),
                        get(l, r, type, (v << 1) | 1, tm + 1, tr));
}

deque < pair <int, int> > dv(int l, int r)
{
      deque < pair <int, int> > v1, v2, v3, v4;
      if(l >= r) return v4;
      if(l + 1 == r)
      {
            v4.pb(mk(a[l], a[r]));
            return v4;
      }
      int aa = get(l, r - 1, l % 2).sc;
      int bb = get(aa + 1, r, (l % 2) ^ 1).sc;
      v4.pb(mk(a[aa], a[bb]));
      v1 = dv(l, aa - 1);
      v2 = dv(aa + 1, bb - 1);
      v3 = dv(bb + 1, r);
      while(0 < v1.size() && 0 < v2.size() && 0 < v3.size())
      {
            if(v1.front() < v2.front() && v1.front() < v3.front())
            {
                  v4.pb(v1.front());
                  v1.pop_front();
            }
            else if(v2.front() < v1.front() && v2.front() < v3.front())
            {
                  v4.pb(v2.front());
                  v2.pop_front();
            }
            else
            {
                  v4.pb(v3.front());
                  v3.pop_front();
            }
      }

      while(0 < v1.size() && 0 < v2.size())
      {
            if(v1.front() < v2.front())
            {
                  v4.pb(v1.front());
                  v1.pop_front();
            }
            else
            {
                  v4.pb(v2.front());
                  v2.pop_front();
            }
      }
      while(0 < v1.size() && 0 < v3.size())
      {
            if(v1.front() < v3.front())
            {
                  v4.pb(v1.front());
                  v1.pop_front();
            }
            else
            {
                  v4.pb(v3.front());
                  v3.pop_front();
            }
      }
      while(0 < v3.size() && 0 < v2.size())
      {
            if(v3.front() < v2.front())
            {
                  v4.pb(v3.front());
                  v3.pop_front();
            }
            else
            {
                  v4.pb(v2.front());
                  v2.pop_front();
            }
      }

      while(0 < v1.size())
      {
            v4.pb(v1.front());
            v1.pop_front();
      }
      while(0 < v2.size())
      {
            v4.pb(v2.front());
            v2.pop_front();
      }
      while(0 < v3.size())
      {
            v4.pb(v3.front());
            v3.pop_front();
      }

      return v4;
}

