pair < int, int > query(int idx, int l, int r, int linc, int rinc, pair < int, int > *tree)
{
    if(l >= linc and r <= rinc)
        return tree[idx];

    if(l > rinc or r < linc)
        return {INF, INF};

    int mid = l + ((r - l) >> 1);
    pair < int, int > x = query(idx << 1, l, mid, linc, rinc, tree);
    x = min(x, query((idx << 1) + 1, mid + 1, r, linc, rinc, tree));

    return x;
}

pair < int, int > get_range(int l, int r)
{
    if(l & 1)
    {
        assert(!(r & 1) and "REVERSE PARITY EVEN");

        pair < int, int > x = query(1, 0, od.size() - 1, l/2, r/2 - 1, odd);
        pair < int, int > y = query(1, 0, ev.size() - 1, x.second/2+1, r/2, even);

        return {x.first, y.first};
    }
    else
    {
        assert((r & 1) and "REVERSE PARITY ODD");

        pair < int, int > x = query(1, 0, ev.size() - 1, l/2, r/2, even);
        pair < int, int > y = query(1, 0, od.size() - 1, x.second/2, r/2, odd);

        return {x.first, y.first};
    }
}

