template <class T>
class SegmentTree {
    const int n;
    const T default_value = INF; //change here
    vector<T> data;
    inline T merge(T a, T b) {
        return min(a, b); //change here
    }
    inline T sub(int l, int r, int node, int lb, int ub) {
        if (ub <= l || r <= lb) return default_value;
        if (l <= lb && ub <= r) return data[node];
        T vl = sub(l, r, node * 2 + 0, lb, (lb + ub) / 2);
        T vr = sub(l, r, node * 2 + 1, (lb + ub) / 2, ub);
        return merge(vl, vr);
    }
public:
    SegmentTree(const int s) : n(1 << s), data(n * 2, default_value) {}
    inline void update(int p, T val) {
        data[p += n] = val;
        while (p /= 2) {
            data[p] = merge(data[p * 2], data[p * 2 + 1]);
        }
    }
    inline T query(int l, int r) {
        return sub(l, r, 1, 0, n);
    }
};


