#define MAXN    200001

int bp[MAXN];
int p[MAXN];
int ap[MAXN];
struct node_t
{
    int l, r;
    int m[2];
};
node_t nodes[MAXN<<2];
int mymin(int a, int b)
{
    return (p[a]<p[b])?a:b;
}
node_t merge(node_t a, node_t b)
{
    node_t ans;
    ans.l = a.l; ans.r = b.r;
    ans.m[0] = mymin(a.m[0], b.m[0]);
    ans.m[1] = mymin(a.m[1], b.m[1]);
    return ans;
}

int N;
int q[MAXN];
int nq;

void build(int o, int l, int r)
{
    if(0 == r-l)
    {
        nodes[o].l = l; nodes[o].r = r;
        nodes[o].m[l&1] = l; nodes[o].m[1-(l&1)] = -1;
    } else {
        int mid = ((l+r)>>1);
        build(o<<1, l, mid);
        build(o<<1|1, mid+1, r);
        nodes[o] = merge(nodes[o<<1], nodes[o<<1|1]);
    }
}

node_t query(int L, int R, int o, int l, int r)
{
    if(L <= l && r <= R)
        return nodes[o];
    else
    {
        int mid = ((l+r)>>1);
        if(R <= mid) return query(L,R,o<<1,l,mid);
        else if(L > mid) return query(L,R,o<<1|1,mid+1,r);
        else return merge(query(L,R,o<<1,l,mid),query(L,R,o<<1|1,mid+1,r));
    }
}
int qmin(int L, int R, int re)
{
    return query(L, R, 1,1,N).m[re];
}

struct interval
{
    int l, r, re;
    interval(){}
    interval(int ll, int rr, int rree):l(ll),r(rr),re(rree){}
    bool operator>(const interval &b) const
    {
        return p[qmin(l,r,re)] > p[qmin(b.l,b.r,b.re)];
    }
};
typedef interval piin;
void solve()
{
    priority_queue< piin, vector<piin>, greater<piin> > pq;
    pq.push(interval(1,N,1));
    while(!pq.empty())
    {
        interval handle = pq.top();
        int L = handle.l, R = handle.r, re = handle.re;
        pq.pop();
        if(1 == handle.r - handle.l) {
            q[nq++] = p[handle.l];
            q[nq++] = p[handle.r];
        } else {
            int i = 0;
            node_t lm = query(handle.l, handle.r, 1,1,N);
            int fi = lm.m[handle.re];
            node_t rm = query(fi+1, handle.r, 1,1,N);
            int si = rm.m[!handle.re];
            q[nq++] = p[fi]; q[nq++] = p[si];
            int pro[3][3] = {{L,fi-1,re},{fi+1,si-1,!re},{si+1,R,re}};
            for(i = 0;i < 3;++i)
                if(pro[i][1] > pro[i][0])
                    pq.push(interval(pro[i][0],pro[i][1],pro[i][2]));
        }
    }
}

