{
    int i = 0;
    p[-1] = MAXN;
    scanf("%d", &N);
    for(i = 1;i <= N;++i)
        scanf("%d", p+i);
    build(1, 1, N);
    solve();
    printf("%d", q[0]);
    for(i = 1;i < N;++i)
        printf(" %d", q[i]);
    puts("");
    return 0;
}

