template <typename T>
class Rmq {
public:

#define INF (0x7fffffff)
	int n;
	vector<T> dat;
	void init(int _n) {
		n = 1;
		while (n < _n) {
			n *= 2;
		}
		dat.resize(2 * n);
		rep(i, n * 2 - 1) {
			dat[i] = P(INF, INF);
		}
	}

	void update(int k, int x) {
		int pos = k;
		k += n - 1;
		dat[k] = P(x, pos);
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}

	}

	T find(int a, int b, int k, int l, int r) {
		if (a <= l && r <= b)
			return dat[k];
		if (r <= a || b <= l)//等号が必要
			return P(INF, INF);
		else {
			T x1, x2;
			x1 = find(a, b, k * 2 + 1, l, (l + r) / 2);//ここはl,r
			x2 = find(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(x1, x2);
		}
	}
};

