    }
    SegTree odd(oddv), even(evenv);
    priority_queue <tuple <P,int,int>, vector <tuple <P,int,int>>, greater <tuple <P,int,int>>> pq;
    pq.push({odd.getmin(0, n), 0, n-1});
    vector <int> ans;

    // 0:次に来るやつ, 1: l 2: r
    while(!pq.empty()){
        auto tmp = pq.top(); pq.pop();
        P nel = get <0>(tmp);
        int l = get <1>(tmp), r = get <2>(tmp);
        if(l + 1 == r){
            ans.pb(p[l]), ans.pb(p[r]);
