struct node{
  int s,e,m,v;
  node *l, *r;
  node(int _s, int _e){
    s=_s;e=_e;m=(s+e)/2;
    if (s == e){
      v = A[s];
    }
    else{
      l = new node(s,m);
      r = new node(m+1, e);
      v = min(l->v, r->v);
    }
  }
  void up(int x, int val){
    if (s == e){
      v = val;
      return;
    }
    if (x <= m)l->up(x,val);
    else r->up(x,val);
    v = min(l->v, r->v);
  }
  int query(int a, int b){
    if (a == s && b == e)return v;
    if (b <= m)return l->query(a,b);
    if (a > m)return r->query(a,b);
    return min(l->query(a,m), r->query(m+1, b));
  }
} *odd, *even, *all;

struct newnode{
  int s,e,m,odd, even,lazy;
  newnode *l, *r;

  newnode(int _s, int _e){
    s=_s; e=_e; m=(s+e)/2;
    odd = even = INF;
    if (s == e){
      if (s%2 == 1)odd = A[s];
      else even = A[s];
    }
    else{
      l = new newnode(s, m);
      r = new newnode(m+1, e);
      combine();
    }
  }

  void prop(){
    if (s == e){
      if (!lazy)return;
      swap(odd, even);
      lazy = 0;
      return;
    }
    if (!lazy)return;
    swap(odd, even);
    r->lazy = 1 - r->lazy;
    l->lazy = 1-l->lazy;
    lazy = 0;
    return;
  }

  void combine(){
    int le = (m-s+1);
    l->prop(); r->prop();
    odd = even = INF;
    odd = min(l->odd,r->odd);
    even = min(l->even,r->even);
  }

  void erase(int x){
    if (s == e){
      odd = even = INF;
      return;
    }
    prop();
    if (x <= m)l->erase(x);
    else r->erase(x);
    combine();
  }

  void flip(int a, int b){
    if (s == e){
      lazy = 1-lazy;
      return;
    }
    prop();
    if (a > m)r->flip(a,b);
    else if (b <= m)l->flip (a,b);
    else {
      l->flip(a,m);
      r->flip(m+1,b);
    }
    combine();
  }

  void ask(){
    prop();
  }

}*root;

