struct MinTree {
    typedef int val_t;
    const val_t INIT = 1 << 30;

    val_t combine(const val_t &a, const val_t &b) {
        return min(a,b);
    }

    vector <val_t> T;
    int p = 1;

    MinTree(int n) {
        while (p < n) p *= 2;
        T.resize(2*p-1, INIT);
    }

    int par(int x) { return (x - 1) / 2; }

    void set(int l, val_t v) {
        l += p-1;
        T[l] = v;

        while (l > 0) {
            l = par(l);
            T[l] = combine(T[2*l+1], T[2*l+2]);
        }
    }

    val_t query(int l, int r) {
        l += p-1; r += p-1;
        val_t ans = combine(T[l],T[r]);

        while (par(l) != par(r)) {
            if (l%2 == 1) ans = combine(ans,T[l+1]);
            if (r%2 == 0) ans = combine(ans,T[r-1]);

            l = par(l);
            r = par(r);
        }

        return ans;
    }
};

