VP mergeParts(VVP &parts) {
    VP res;

    for (auto &part : parts) {
        VP newRes(res.size() + part.size());
        merge(res.begin(), res.end(), part.begin(), part.end(), newRes.begin());

        res = newRes;
    }

    return res;
}

VP solve(int l, int r, MinTree &treeOdd, MinTree &treeEven, VI &where) {
    if (l > r) return {};

    int x;
    if (l % 2) x = treeOdd.query(l, r-1);
    else x = treeEven.query(l, r-1);

    int y;
    if (l % 2) y = treeEven.query(where[x]+1, r);
    else y = treeOdd.query(where[x]+1, r);

    VVP parts = {
        solve(l, where[x]-1, treeOdd, treeEven, where),
        solve(where[x]+1, where[y]-1, treeOdd, treeEven, where),
        solve(where[y]+1, r, treeOdd, treeEven, where)
    };

    VP res = mergeParts(parts);
    res.insert(res.begin(), {x, y});

    return res;
}

