int query(int tp, int l, int r) {
	return min(p[tp][cl[r - l]][l], p[tp][cl[r - l]][r - (1 << cl[r - l])]);
}
vector<int> dfs(int l, int r) {
	if (l == r) return vector<int>();
	int ptl = inv[query(l % 2, l / 2, r / 2)];
	int ptr = inv[query((l + 1) % 2, (ptl + 1) / 2, (r + 1) / 2)];
	vector<int> pl = dfs(l, ptl);
	vector<int> pm = dfs(ptl + 1, ptr);
	vector<int> pr = dfs(ptr + 1, r);
	vector<int> ret = { p[l % 2][0][ptl / 2], p[(l + 1) % 2][0][ptr / 2] };
	int cl = 0, cm = 0, cr = 0;
	for (int i = 0; i < (r - l) / 2 - 1; i++) {
		int vl = (cl == pl.size() ? inf : pl[cl]);
		int vm = (cm == pm.size() ? inf : pm[cm]);
		int vr = (cr == pr.size() ? inf : pr[cr]);
		int vx = min({ vl, vm, vr });
		for (int j = 0; j < 2; j++) {
			ret.push_back(vl == vx ? pl[cl++] : (vm == vx ? pm[cm++] : pr[cr++]));
		}
	}
	return ret;
}
