template<typename T>
struct SegmentTree{
  using F = function<T(T,T)>;
  vector<T> data;
  int n,lastlen = 1;
  F func = [](T a, T b){return a < b ? a : b;};
  T iden = MP(INT_MAX,-1); //identity element
  SegmentTree(vector<T> v){
    n = (int)v.size();
    while(lastlen < n)lastlen *= 2;
    data.assign(lastlen*2-1,iden);
    for(int i=0;i<n;i++)data[i+lastlen-1] = v[i];
    for(int i=lastlen-2;i>=0;i--){
      data[i] = func(data[2*i+1], data[2*i+2]);
    }
  }
  void update(int point, T x){
    point+=lastlen-1;
    data[point] = x;
    while(point!=0){
      point=(point-1)/2;
      data[point]=func(data[2*point+1],data[2*point+2]);
    }
  }
  T query(int a,int b,int point=0,int left=0,int right=-1){
    if(right<0)right=lastlen;
    T ret = iden;
    if(b <= left || right <= a);
    else if(a <= left && right <= b ){
      ret = func(ret, data[point]);
    }
    else{
      T p,q;
      p = query(a,b,point*2+1,left, (left+right)/2);
      q = query(a,b,point*2+2,(left+right)/2, right);
      ret = func(ret,p);
      ret = func(ret,q);
    }      
    return ret;
  }
};


