#define fD (2*nod+1)

int arb[4*NMAX+2][2];
int v[NMAX+2];
int N;
vector<int> sol;
int where[NMAX+2];
int qry[2];

void combina(int rez[], int st[], int dr[], int a, int x, int y)
{
    int lef = min(st[(x - a) % 2], dr[(y - a) % 2]);
    int rig = min(st[(x - a + 1) % 2], dr[(y - a + 1) % 2]);
    rez[0] = lef;
    rez[1] = rig;
}

void build(int nod, int st, int dr)
{
    if( st == dr ) {
        arb[nod][0] = v[st];
        arb[nod][1] = INF;
        return ;
    }
    int m = (st + dr) / 2;
    build(fS, st, m);
    build(fD, m + 1, dr);
    combina(arb[nod], arb[fS], arb[fD], st, st, m + 1);
}

void query(int nod, int st, int dr, int x, int y)
{
    if( x <= st && dr <= y ) {
        combina(qry, qry, arb[nod], x, x, st);
        return ;
    }
    if( y < st || dr < x )
        return ;
    int m = (st + dr) / 2;
    query(fS, st, m, x, y);
    query(fD, m + 1, dr, x, y);
}

pair<int,int> query(int x, int y)
{
    qry[0] = qry[1] = INF;
    query(1, 1,N, x, y);
    return {qry[0], qry[1]};
}

struct Gap
{
    int x,y,val;

    bool operator < (const Gap& a) const {
        return val > a.val;
    }
};

priority_queue<Gap> pq;

int main()
{
    cin >> N;
    for( int i = 1;  i <= N;  ++i ) {
        cin >> v[i];
        where[ v[i] ] = i;
    }
    build(1, 1,N);

    pq.push({1,N, query(1,N).first});
    while( !pq.empty() ) {
        auto el = pq.top();
        assert(el.x < el.y && (el.x+el.y) % 2 == 1);
        pq.pop();
        int pos_lef = where[el.val];
        int pos_rig = where[query(pos_lef + 1, el.y).first];
        sol.push_back(v[pos_lef]);
        sol.push_back(v[pos_rig]);

        if( el.x < pos_lef )
            pq.push({el.x, pos_lef - 1, query(el.x, pos_lef - 1).first});
        if( pos_lef + 1 <= pos_rig - 1 )
            pq.push({pos_lef + 1, pos_rig - 1, query(pos_lef + 1, pos_rig - 1).first});
        if( pos_rig + 1 <= el.y )
            pq.push({pos_rig + 1, el.y, query(pos_rig + 1, el.y).first});
    }
    for( auto x : sol ) cout << x << ' ';
    return 0;
}

