typedef pair<int,int> pii;
#define fr first
#define sc second

const int maxn=2e5+5;

pii node[maxn];
int n,rt,tot,cnt;
int f[20][maxn][2];
int a[maxn],now[maxn],pre[maxn],son[maxn];

int read() {
	int x=0,f=1;char ch=getchar();
	for(;ch<'0'||ch>'9';ch=getchar())if(ch=='-')f=-1;
	for(;ch>='0'&&ch<='9';ch=getchar())x=x*10+ch-'0';
	return x*f;
}

void add(int a,int b) {
	if(!b)return;
	pre[++tot]=now[a];
	now[a]=tot,son[tot]=b;
}

int cmp(int pos1,int pos2) {
	if(a[pos1]<a[pos2])return pos1;
	return pos2;
}

void make_st() {
	for(int i=1;i<20;i++)
		for(int j=1;j+(1<<i)-1<=n;j++)
			for(int k=0;k<2;k++)
				f[i][j][k]=cmp(f[i-1][j][k],f[i-1][j+(1<<(i-1))][k]);
}

int solve(int l,int r,int opt) {
	if(r<l)return 0;
	if(l+1==r) {
		node[++cnt]=make_pair(a[l],a[r]);
		return cnt;
	}
	int x=log2(r-l+1);
	int pos=cmp(f[x][l][opt],f[x][r-(1<<x)+1][opt]);
	x=log2(r-pos+1);
	int tmp=cmp(f[x][pos][opt^1],f[x][r-(1<<x)+1][opt^1]);
	node[++cnt]=make_pair(a[pos],a[tmp]);x=cnt;
	add(x,solve(l,pos-1,opt));
	add(x,solve(pos+1,tmp-1,opt^1));
	add(x,solve(tmp+1,r,opt));
	return x;
}

struct Heap {
	int tot;
	int tree[maxn];

	void ins(int u) {
		tree[++tot]=u;
		int pos=tot;
		while(pos>1) {
			if(node[tree[pos]]<node[tree[pos>>1]])
				swap(tree[pos],tree[pos>>1]),pos>>=1;
			else break;
		}
	}

	int pop() {
		int res=tree[1];
		tree[1]=tree[tot--];
		int pos=1,son=2;
		while(son<=tot) {
			if(son<tot&&node[tree[son|1]]<node[tree[son]])son|=1;
			if(node[tree[son]]<node[tree[pos]])
				tree[pos]=tree[son],pos=son,son=pos<<1;
			else break;
		}
		return res;
	}
}H;

void make_ans() {
	H.ins(rt);
	while(H.tot) {
		int u=H.pop();printf("%d %d ",node[u].fr,node[u].sc);
		for(int p=now[u];p;p=pre[p])
		    H.ins(son[p]);
	}
}

int main() {
	n=read();a[0]=2e9;
	for(int i=1;i<=n;i++)
		a[i]=read(),f[0][i][i&1]=i;
	make_st();
	rt=solve(1,n,1);
	make_ans();
	return 0;
}

