			updatep(1, 0, n - 1, i, temp);
			updatenep(1, 0, n - 1, i, 1000000000);
		}
		else {
			updatenep(1, 0, n - 1, i, temp);
			updatep(1, 0, n - 1, i, 1000000000);
		}
	}
	int counter = 0;
	vector<pair<ll, ll>> v[2];
	int now = 0, future = 1;
	v[now].push_back(make_pair(0, n - 1));
	while (counter < n) {
		vector<pair<ll, ll>> currentresults;
		for (auto it : v[now]) {
			ll f, s;
			if (it.first % 2 == 0) {
				f = minnp(1, 0, n - 1, it.first, it.second - 1);
				s = minnnep(1, 0, n - 1, index[f] + 1, it.second);
			}
			else {
				f = minnnep(1, 0, n - 1, it.first, it.second - 1);
				s = minnp(1, 0, n - 1, index[f] + 1, it.second);
			}
			currentresults.push_back(make_pair(f, s));
		}
		sort(currentresults.begin(), currentresults.end());
		printf("%lld %lld ", currentresults[0].first, currentresults[0].second);
		counter += 2;
		ll f = currentresults[0].first, s = currentresults[0].second;
		for (auto it : v[now]) {
			if (index[f] >= it.first && index[s] <= it.second) {
				if (it.first < index[f])v[future].push_back(make_pair(it.first, index[f] - 1));
				if (index[s] - index[f] > 1)v[future].push_back(make_pair(index[f] + 1, index[s] - 1));
				if (index[s] < it.second)v[future].push_back(make_pair(index[s] + 1, it.second));
			}
			else {
				v[future].push_back(it);
			}
		}
		v[now].resize(0);
		swap(now, future);
	}
	return 0;
}

