        rmq[0].update(m, mp(INF, m));
        rmq[1].update(n, mp(INF, n));
        f(l, m);
        f(m+1, n);
        f(n + 1, r);
    }

    rep(i, N)cout << ans[i] << (i != N - 1 ? ' ' : '\n');
}

