int n, ar[200001];
pair<int, int> t[800001][2];

void build(int tl, int tr, int v)
{
    if(tr == tl)
    {
        t[v][tl % 2].fr = ar[tl];
        t[v][(tl + 1) % 2].fr = 1e9;
        t[v][0].sc = tr;
        t[v][1].sc = tr;
    }else
    {
        int tm = (tr + tl) >> 1;
        build(tl, tm, v + v);
        build(tm + 1, tr, v + v + 1);

        t[v][1] = min(t[v + v][1], t[v + v + 1][1]);
        t[v][0] = min(t[v + v][0], t[v + v + 1][0]);
    }
}

pair<int, int> get(int tl, int tr, int l, int r, int v, int num)
{
    if(l > r)
        return mk(1e9, 0);
    if(tr == r && tl == l)
        return t[v][num];
    else
    {
        int tm = (tr + tl) >> 1;
        return min(get(tl, tm, l, min(tm, r), v + v, num), get(tm + 1, tr, max(l, tm + 1), r, v + v + 1, num));
    }
}

int timer = 0, sz[200001], p[200001];
