        return;

    timer++;
    int x = timer;

    int a, b;
    a = get(1, n, l, r, 1, l % 2).sc;
    b = get(1, n, a + 1, r, 1, (l + 1) % 2).sc;

    ars[timer] = mk(ar[a], ar[b]);
    if(l < a - 1)
        vec[x].push_back(timer + 1), p[timer + 1] = x, f(l, a - 1), sz[x]++;
    if(a + 1 < b - 1)
        p[timer + 1] = x, vec[x].push_back(timer + 1), f(a + 1, b - 1), sz[x]++;
    if(b + 1 < r)
        p[timer + 1] = x, vec[x].push_back(timer + 1), f(b + 1, r), sz[x]++;
}

