int MIN(int c,int d){
	if(c==INF)return d;
	if(d==INF)return c;
	return a[c]<a[d]?c:d;
}

void build(int l,int r,int node){
	if(l==r){
		if(l&1)tree1[node]=l,tree0[node]=INF;
		else tree1[node]=INF,tree0[node]=l;
		leaf[l]=node;
		return;
	}
	int mid=(l+r)>>1;
	build(l,mid,node*2);
	build(mid+1,r,node*2+1);
	tree0[node]=MIN(tree0[node*2],tree0[node*2+1]);
	tree1[node]=MIN(tree1[node*2],tree1[node*2+1]);
}

void Push(int node){
	if(tag[node]){
		swap(tree0[node],tree1[node]);
		tag[node*2]^=tag[node];
		tag[node*2+1]^=tag[node];
		tag[node]=0;
	}
}

void update(int l,int r,int vl,int vr,int node){
	if(vl>vr)return;
	if(l>vr||r<vl)return;
	if(l>=vl&&r<=vr){
		tag[node]^=1;
		Push(node);
		return;
	}
	int mid=(l+r)>>1;
	Push(node);
	update(l,mid,vl,vr,node*2);
	update(mid+1,r,vl,vr,node*2+1);
	tree0[node]=MIN(tree0[node*2],tree0[node*2+1]);
	tree1[node]=MIN(tree1[node*2],tree1[node*2+1]); 
}

int query_0(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return tag[node]?tree1[node]:tree0[node];
	Push(node);
	int mid=(l+r)>>1;
	return MIN(query_0(l,mid,vl,vr,node*2),query_0(mid+1,r,vl,vr,node*2+1));
}

int query_1(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return tag[node]?tree0[node]:tree1[node];
	Push(node);
	int mid=(l+r)>>1;
	return MIN(query_1(l,mid,vl,vr,node*2),query_1(mid+1,r,vl,vr,node*2+1));
}

int Find_nxt(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return nxt[node];
	int mid=(l+r)>>1;
	return min(Find_nxt(l,mid,vl,vr,node*2),Find_nxt(mid+1,r,vl,vr,node*2+1));
}

void del(int pos){
	int node=leaf[pos];
	tree0[node]=tree1[node]=INF;
	while(node){
		node>>=1;
		tree0[node]=MIN(tree0[node*2],tree0[node*2+1]);
		tree1[node]=MIN(tree1[node*2],tree1[node*2+1]); 
	}
}

void add(int pos,int val){
	int node=leaf[pos];
	nxt[node]=val;
	while(node){
		node>>=1;
		nxt[node]=min(nxt[node*2],nxt[node*2+1]);
	}
}

int main(){
//	freopen("E.in","r",stdin);
	ios::sync_with_stdio(false);
	cin>>n;
	REP(i,n)cin>>a[i];
	build(1,n,1);
	REP(i,n)add(i,n+1);
	REP(i,n/2-1){
		int pos=query_1(1,n,1,n,1);
		ans.push_back(a[pos]);
		int cur=Find_nxt(1,n,pos+1,n,1);
		int pos2=query_0(1,n,pos+1,cur-1,1);
		ans.push_back(a[pos2]);
		del(pos);
		del(pos2);
		add(pos,pos);
		add(pos2,pos2);
		used[pos]=used[pos2]=true;
		update(1,n,pos+1,pos2-1,1);
	}
	REP(i,n)if(!used[i])ans.push_back(a[i]);
	rep(i,ans.size())cout<<ans[i]<<" ";
	return 0;
}

