ll N, M;
vector<ll> E[1010];
bool visited[1010];
bool ok;

void dfs(ll now, ll from, ll start){
  if(now == start && from != -1){
    ok = 1;
    return;
  }
  if(visited[now]) return;
  visited[now] = 1;
  for(ll to : E[now]){
    dfs(to, now, start);
  }
}

ll dist[1010];
ll last;

void dijkstra(ll s){
  rep(i, 1010) dist[i] = INFL;
  dist[s] = 0;
  priority_queue<P, vector<P>, greater<P>> pque;
  pque.push({0, s});
  while(!pque.empty()){
    P p = pque.top();
    pque.pop();
    if(dist[p.s] < p.f) continue;
    for(ll to : E[p.s]){
      if(to == s){
        last = p.s;
        continue;
      }
      if(dist[to] > p.f + 1){
        dist[to] = p.f + 1;
        pque.push({dist[to], to});
      }
    }
  }
}


pair<ll, pair<ll, ll>> solve(ll start){
  dijkstra(start);
  return {dist[last], {last, start}};

}


int main(){
  cin >> N >> M;
  rep(i, M){
    ll a, b;
    cin >> a >> b;
    a--, b--;
    E[a].pb(b);
  }
  vector<pair<ll, pair<ll, ll>>> ANS;
  rep(i, N){
    ok = 0;
    rep(j, N) visited[j] = 0;
    dfs(i, -1, i);
    if(ok){
      ANS.pb(solve(i));
    }
  }
  if(ANS.size() == 0){
    cout << -1 << endl;
    return 0;
  }
  sort(ANS.begin(), ANS.end());

  rep(a, ANS.size()){
    dijkstra(ANS[a].s.s);
    set<ll> ans;
    ll now = ANS[a].s.f;
    while(true){
      ans.insert(now);
      if(now == ANS[a].s.s) break;
      ll d = dist[now];
      rep(i, 1010){
        if(dist[i] == d - 1){
          now = i;
        }
      }
    }
    ll to_cnt[1010], in_cnt[1010];
    rep(i, 1010){
      to_cnt[i] = 0;
      in_cnt[i] = 0;
    }
    for(auto itr = ans.begin(); itr != ans.end(); itr++){
      ll now = *itr;
      for(ll to : E[now]){
        if(ans.count(to) == 0) continue;
        to_cnt[now]++;
        in_cnt[to]++;
      }
    }
    bool p = 1;
    rep(i, 1010){
      if(in_cnt[i] > 1) p = 0;
      if(to_cnt[i] > 1) p = 0;
    }

    if(p == 0) continue;
    cout << ans.size() << endl;
    for(auto itr = ans.begin(); itr != ans.end(); itr++){
      cout << *itr + 1 << endl;
    }
    return 0;
  }
  cout << -1 << endl;
}

