void build(int i,int l,int r,int* a,SegmentTree tree[])
//void build(int i,int l,int r,int* a,)
{
    //printf("(%d,%d)\n",l,r);
    tree[i].l=l;
    tree[i].r=r;
    if(l==r)
    {
        tree[i].sum=a[++cnt];
        return;
    }
    int mid=(l+r)>>1;
    //printf("mid=%d\n",mid);
    build(i<<1,l,mid,a,tree);
    build((i<<1)|1,mid+1,r,a,tree);
    tree[i].sum=min(tree[i<<1].sum,tree[(i<<1)|1].sum);
}

int q(int i,int l,int r,SegmentTree tree[])
{
    if(tree[i].l==l&&tree[i].r==r)
        return tree[i].sum;
    int mid=(tree[i].r+tree[i].l)>>1;
    if(r<=mid) return q(i<<1,l,r,tree);
    else if(l>mid) return q((i<<1)|1,l,r,tree);
    else return min(q(i<<1,l,mid,tree),q((i<<1)|1,mid+1,r,tree));
}
