int push(int l,int r)
{
    //printf("(%d,%d)\n",l,r);
    int d=1;
    //if(l>=r) return 0;
    //printf("(%d,%d)\n",l,r);
    if(r-l==1)
    {
        d=1;
        if(l%2==1)
        {
            f.l=a[l];
            f.r=b[r];
        }
        else
        {
            f.l=b[l];
            f.r=a[r];
        }
        f.d=d;
        //printf("l=%d r=%d x=%d y=%d d=%d\n",l,r,f.l,f.r,d);
        v.push_back(f);
        return d;
    }
    int x1,y1,x2,y2;
    if(l%2==1)
    {
        x1=a[l];
        y1=q(1,l,r,tree2);
        y2=b[r];
        x2=q(1,l,r,tree1);
    }
    else
    {
        x1=b[l];
        y1=q(1,l,r,tree1);
        y2=a[r];
        x2=q(1,l,r,tree2);
    }
    //printf("x1=%d y1=%d x2=%d y2=%d\n",x1,y1,x2,y2);
    if(x1==x2&&y1==y2)
    {
        if(r-1>l+1)
        d=1+push(l+1,r-1);
        else d=1;
        f.l=x1,f.r=y1;
        f.d=d;
        v.push_back(f);
    }
    else if(x1<x2||(x1==x2&&y1<y2))
    {
        int mid=local[y1];
        //printf("mid=%d\n",mid);
        if(l+1<mid-1)
            d=max(d,1+push(l+1,mid-1));
        if(mid+1<r)
            push(mid+1,r);
        f.l=x1,f.r=y1;
        f.d=d;
        v.push_back(f);
    }
    else
    {
        int mid=local[x2];
        if(l<mid-1)
            push(l,mid-1);
        if(mid+1<r-1)
            d=max(d,1+push(mid+1,r-1));
        f.l=x2,f.r=y2;
        f.d=d;
        v.push_back(f);
    }
    return d;
}
int cmp(node a,node b)
{
    if(a.d==b.d) return a.l<b.l;
    return a.d>b.d;
}
