int sum (int r)
{
	int result = 0;
	for (; r >= 0; r = (r & (r+1)) - 1)
		result += t[r];
	return result;
}

void inc (int i, int delta)
{
	for (; i < maxx; i = (i | (i+1)))
		t[i] += delta;
}

int sum (int l, int r)
{
	return sum (r) - sum (l-1);
}

signed main()
{
    ios_base::sync_with_stdio(0);
    int n;
    cin >> n;
    int a[n];
    int m[n + 1];
    bool was[n + 1];
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
        m[a[i]] = i;
        inc(i, 1);
        was[a[i]] = 0;
    }
    set<pair<int, int> > s;
    for (int i = 0; i < n - 1; i++)
    {
        s.insert({min(a[i], a[i + 1]), max(a[i], a[i + 1])});
    }
    vector<int> ans;
    while (!s.empty())
    {
        pair<int, int> p = *(--s.end());
        s.erase(p);
        inc(m[p.first], -1);
        inc(m[p.second], -1);
        if (m[p.first] > m[p.second])
        {
            ans.pb(p.first);
            ans.pb(p.second);
        }
        else
        {
            ans.pb(p.second);
            ans.pb(p.first);
        }
        int x = m[p.first], y = m[p.second];
        if (x > y)
        {
            swap(x, y);
        }
        s.erase({min(a[x - 1], a[x]), max(a[x - 1], a[x])});
        s.erase({min(a[y + 1], a[y]), max(a[y + 1], a[y])});
        int l = -1, r = x;
        while (l < r - 1)
        {
            int mid = (l + r) / 2;
            if (sum(mid, x))
            {
                l = mid;
            }
            else
            {
                r = mid;
            }
        }
        int one = l;
        l = y, r = n;
        while (l < r - 1)
        {
            int mid = (l + r) / 2;
            if (sum(y, mid))
            {
                r = mid;
            }
            else
            {
                l = mid;
            }
        }
        int two = r;
        if (one > two)
        {
            swap(one, two);
        }
        if (one >= 0 && two < n && sum(one, one) == 1 && sum(two, two) == 1)
        {
            s.insert({min(a[one], a[two]), max(a[one], a[two])});
        }
    }
    rev(ans);
    for (int i = 0; i < ans.size(); i++)
    {
        cout << ans[i] << " ";
    }
    return 0;
}
