struct segTree{
  int t[N<<2];
  segTree(){}
  int pull(int i, int j){
    if(a[i]<a[j])return i;
    return j;
  }
  void activate(int idx, int node = 1, int s = 1, int e = n){
    if(s==e){
      t[node] = s;
    } else {
      int md = (s + e) >> 1;
      if(idx <= md)
        activate(idx,node<<1,s,md);
      else
        activate(idx,node<<1|1,md+1,e);
      t[node]=pull(t[node<<1],t[node<<1|1]);
    }
  }
  int qry(int l, int r, int node = 1, int s = 1, int e = n){
    if(r<s||e<l||l>r)return 0;
    if(l<=s&&e<=r)
      return t[node];
    int md = (s + e) >> 1;
    return pull(qry(l,r,node<<1,s,md),qry(l,r,node<<1|1,md+1,e));
  }
}oddTree, evenTree;
map<ii,vector<ii>> adj;
ii solve(int s, int e){
//  cout<<s<<' '<<e<<endl;
//  system("pause");
  if(s>e)return ii(0,0);
  int x = oddTree.qry(s,e);
  int y = evenTree.qry(s,e);
  int nxtX = evenTree.qry(x+1,e);
  int nxtY = oddTree.qry(y+1,e);
//  cout<<x<<' '<<nxtX << ' ' << y << ' '<< nxtY<<endl;
//  system("pause");
  if((a[x] < a[y] && nxtX != 0)||nxtY==0){
    ii val = (make_pair(a[x],a[nxtX]));
    vector<ii> vp;
    vp.pb(solve(s,x-1));  if(vp.back().F==0)vp.pop_back();
    vp.pb(solve(x+1,nxtX-1));  if(vp.back().F==0)vp.pop_back();
    vp.pb(solve(nxtX+1,e));  if(vp.back().F==0)vp.pop_back();
    adj[val]=vp;
    return val;
  } else {
    ii val = (make_pair(a[y],a[nxtY]));
    vector<ii> vp;
    vp.pb(solve(s,y-1));  if(vp.back().F==0)vp.pop_back();
    vp.pb(solve(y+1,nxtY-1));  if(vp.back().F==0)vp.pop_back();
    vp.pb(solve(nxtY+1,e));  if(vp.back().F==0)vp.pop_back();
    adj[val]=vp;
    return val;
  }
}
