  int a;
  int b;
  int c;
  int d;

  T(int aa, int bb, int cc, int dd):a(aa), b(bb), c(cc), d(dd){}

};

bool comp(T p, T q){
  if(p.a <= q.a && p.b >= q.b)  return false;
  else if(p.a >= q.a && p.b <= q.b) return true;
  else{
    if(p.c < q.c) return false;
    else return true;
  }
}

priority_queue<T, vector<T>, decltype(&comp)> pq(&comp);

void init(int n_, int* da){
  n = 1;
  while(n < n_) n *= 2;

  for(int i = 0; i < n; i++){
    da[i] = MA;
  }
