//k番目をaに変更
void update(int k, int a, int* dat){
  k += n-1;
  dat[k] = a;
  while(k > 0){
    k = (k-1)/2;
    dat[k] = min(dat[k*2+1], dat[k*2+2]);
  }
}

int query(int a, int b, int k, int l, int r, int* dat){
  if(r <= a || b <= l) {
    //cout << 40 << endl;
    return MA;
  }
  if(a <= l && r <= b){
    //cout << 43 << " " << dat[k] << endl;
    return dat[k];
  }
  else{
    int vl = query(a, b, k*2+1, l, (l+r)/2, dat);
    int vr = query(a, b, k*2+2, (l+r)/2, r, dat);
    //cout << "vl vr" << vl << " " << vr << endl;
    return min(vl, vr);
  }
}

void deal(int i, int s, int e){
