  pq.push(T(s, e, m1, m2));
  //cout << 66 << endl;
  //cout << q[m1] << " " << q[m2] << endl;
  deal(i, s, q[m1]);
  deal(1-i, q[m1]+1, q[m2]);
  deal(i, q[m2]+1, e);
}

