struct Tree{
    int Min;
    int id;
};
Tree seg[2][MAXN<<2];
int a[MAXN];
void push_up(int root,int l,int r,int type){
    seg[type][root].Min=min(seg[type][lson].Min,seg[type][rson].Min);
    seg[type][root].Min==seg[type][lson].Min?seg[type][root].id=seg[type][lson].id:seg[type][root].id=seg[type][rson].id;
}
void build(int root,int l,int r,int type){
    if(l==r){
        seg[type][root].Min=a[2*l-type];
        seg[type][root].id=2*l-type;
        return ;
    }
    Mid;
    build(lson,l,mid,type);
    build(rson,mid+1,r,type);
    push_up(root,l,r,type);
}
priority_queue<fc>q;
Tree query(int root,int l,int r,int ql,int qr,int type){
    Tree res1,res2;
    if(l>=ql&&r<=qr){
        Tree tmp;
        if(type==1) tmp.id=seg[type][root].id;
        else tmp.id=seg[type][root].id;
        tmp.Min=seg[type][root].Min;
        return tmp;
    }
    if(l>qr||r<ql) return res1={inf,0};
    Mid;
    res1=query(lson,l,mid,ql,qr,type);
    res2=query(rson,mid+1,r,ql,qr,type);
    if(res1.Min<res2.Min)
        return res1;
    else return res2;
}
fc work(int l,int r){
    Tree res1,res2;
    if(l&1){
        res1=query(1,1,n/2,(l+1)/2,r/2,1);
        res2=query(1,1,n/2,(res1.id+1)/2,r/2,0);
    }
    else{
        res1=query(1,1,n/2,l/2,r/2,0);
        res2=query(1,1,n/2,res1.id/2+1,r/2+1,1);
    }
    fc tmp={res1.Min,res2.Min,l,r,res1.id,res2.id};
    return tmp;
}
