	int k = lg(r-l+1);
	if(v[sp[id][l][k]] <= v[sp[id][r-(1<<k)+1][k]]) return sp[id][l][k];
	return sp[id][r-(1<<k)+1][k];
}
void pre() {
	for(int id = 0;id<2;id++) {
		for(int i=0;i<(n+1-id)/2;i++) {
			sp[id][i][0] = i*2+id;
		}
		for(int j=1;(1<<j) <= n;j++) {
			for(int i=0;i+(1<<j)-1<n;i++) {
				if(v[sp[id][i][j-1]] < v[sp[id][i+(1<<(j-1))][j-1]]) {
					sp[id][i][j] = sp[id][i][j-1];
				} else {
					sp[id][i][j] = sp[id][i+(1<<(j-1))][j-1];
				}
			}
		}
	}
}
vi g[100100];
ii bs[100100];
int ctr = 0;
void pr(int l, int r,int u) {
	//printf("find %d %d, v %d\n",l,r,u);
	int ml = qu(l,r);
	int mr = qu(ml+1,r);
	bs[u] = {v[ml],v[mr]};
	if(ml-1 >= l) {
		ctr++;
		int k = ctr;
		pr(l,ml-1,k);
		g[u].push_back(k);
	}
	if(mr-1 >= ml+1) {
		ctr++;
		int k = ctr;
		pr(ml+1,mr-1,k);
		g[u].push_back(k);
	}
	if(mr+1 <= r) {
		ctr++;
		int k = ctr;
		pr(mr+1,r,k);
		g[u].push_back(k);
	}
}
