inline void put(int x, int l, int r, int p, int *t) {
  if (l == r) {
    t[x] = p;
    return;
  }
  int s = (l + r) / 2;
  if (p <= s) {
    put(x + x, l, s, p, t);
  } else {
    put(x + x + 1, s + 1, r, p, t);
  }
  if (t[x + x] == -1) {
    t[x] = t[x + x + 1];
  } else
  if (t[x + x + 1] == -1) {
    t[x] = t[x + x];
  } else {
    t[x] = (a[t[x + x]] < a[t[x + x + 1]] ? t[x + x] : t[x + x + 1]);
  }
}

inline int get(int x, int l, int r, int ql, int qr, int *t) {
  if (r < ql || l > qr) {
    return -1;
  }
  if (l >= ql && r <= qr) {
    return t[x];
  }
  int s = (l + r) / 2;
  int el = get(x + x, l, s, ql, qr, t);
  int er = get(x + x + 1, s + 1, r, ql, qr, t);
  if (el == -1) {
    return er;
  }
  if (er == -1) {
    return el;
  }
  return a[el] < a[er] ? el : er;
}

const int inf = 1e9;

int n;
int ans[N];
int tmp[N];

void solve(int l, int r, int w) {
  if (r - l <= 0) {
    return;
  }
  int p = get(1, 0, n - 1, l, r, tree[w]);
  int q = get(1, 0, n - 1, p + 1, r, tree[1 - w]);
  solve(l, p - 1, w);
  solve(p + 1, q - 1, 1 - w);
  solve(q + 1, r, w);
  int xi = l;
  int yi = p + 1;
  int zi = q + 1;
  int cnt = 2;
  tmp[0] = a[p];
  tmp[1] = a[q];
  while (true) {
    int vx = (xi > p - 1 ? inf : ans[xi]);
    int vy = (yi > q - 1 ? inf : ans[yi]);
    int vz = (zi > r ? inf : ans[zi]);
    if (vx == inf && vy == inf && vz == inf) {
      break;
    }
    if (vx < vy && vx < vz) {
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
      tmp[cnt] = ans[xi];
      ++cnt; ++xi;
    } else
    if (vy < vx && vy < vz) {
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
      tmp[cnt] = ans[yi];
      ++cnt; ++yi;
    } else {
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
      tmp[cnt] = ans[zi];
      ++cnt; ++zi;
    }
  }
  for (int i = 0; i < cnt; ++i) {
    ans[l + i] = tmp[i];
  }
}

