vector <int> g[2*N];
vector <pair <int, int> > ans;

void build(int v, int tl, int tr, int o) {
    if(tl == tr) {
        if(o == 0)
            t[v][o] = mk(a[tl*2-1], tl*2-1);
        else
            t[v][o] = mk(a[tl*2], tl*2);
        return;
    }
    int tm = (tl + tr) / 2;
    build(v + v, tl, tm, o);
    build(v + v + 1, tm + 1, tr, o);
    t[v][o] = t[v + v][o];
    if(t[v][o].fr > t[v + v + 1][o].fr)
        t[v][o] = t[v + v + 1][o];
}

pair <int, int> get(int v, int tl, int tr, int l, int r, int o) {
    if(l > r) return mk(inf, 0);

    if(tl == l && r == tr)
        return t[v][o];

    int tm = (tl + tr) / 2;

    pair <int, int> nw = get(v + v, tl, tm, l, min(tm, r), o);
    pair <int, int> nw2 = get(v + v + 1, tm + 1, tr, max(tm + 1, l), r, o);

    if(nw.fr < nw2.fr) return nw;
    return nw2;
}

void A(int l, int r, int p) {
    if(l > r) return;
    int num = ++cnt;
    g[p].pb(num);
    if(l & 1) {
        int pos = get(1, 1, n, (l + 1) / 2, r / 2, 0).sc;
        int ps = get(1, 1, n, (pos + 1) / 2, r / 2, 1).sc;
        b[num] = mk(pos, ps);
        A(l, pos - 1, num);
        A(pos + 1, ps - 1, num);
        A(ps + 1, r, num);
    }
    else {
        int pos = get(1, 1, n, l / 2, r / 2, 1).sc;
        int ps = get(1, 1, n, pos / 2 + 1, r / 2 + 1, 0).sc;
        b[num] = mk(pos, ps);
        A(l, pos - 1, num);
        A(pos + 1, ps - 1, num);
        A(ps + 1, r, num);
    }
}

inline void solve() {
    scanf("%d", &n);
    for(int i = 1; i <= n; i++)
        scanf("%d", &a[i]);

    n /= 2;
    build(1, 1, n, 0);
    build(1, 1, n, 1);

    A(1, 2*n, 0);

    set <pair <int, int> > st;
    st.insert(mk(-1, 0));

    while(!st.empty()) {
        int ok = st.begin()->sc;
        st.erase(st.begin());
        if(ok != 0)
            ans.pb(b[ok]);
        for(int j = 0; j < g[ok].size(); j++)
            st.insert(mk(a[b[g[ok][j]].fr], g[ok][j]));
    }

    for(int i = 0; i < sz(ans); i++)
        cout << a[ans[i].fr] << " " << a[ans[i].sc] << " ";
}


