vector<int> A;
vector<int> ans;
vector<int> Aindex;//Aの値からインデックスをえる。
segment_base<int> seg0,seg1;//偶数、奇数0-index

vector< PII > f(int L,int R){//[L,R)

	int res1,res2;
	int res1_Index,res2_Index;
	if( L&1 ){//奇数番目から始まる場合
		res1 = seg1.query(L>>1,R>>1);
		res1_Index = Aindex[res1];
		//seg1.update(res1_Index/2,INF);

		res2 = seg0.query( (res1_Index>>1) + 1,(R>>1) + 1);
		res2_Index = Aindex[res2];
		//seg0.update(res2_Index/2,INF);
	}else{
		res1 = seg0.query( (L>>1),(R>>1) );
		res1_Index = Aindex[res1];
		//seg0.update(res1_Index/2,INF);

		res2 = seg1.query( (res1_Index>>1),(R>>1) );
		res2_Index = Aindex[res2];
		//seg1.update(res2_Index/2,INF);
	}

	vector< vector<PII> > B(3);
	vector< priority_queue<PII,vector<PII>,greater<PII> > > pq(3);

	int spL,spR;//分割地点
	spL = res1_Index;
	spR = res2_Index;
	if( L < spL ){
		B[0] = f(L,spL);
		int size = B[0].size();
		for(int i=0;i<size;++i){
			pq[0].push( B[0][i] );
		}
	}
	if( spL+1 < spR ){
		B[1] = f(spL+1,spR);
		int size = B[1].size();
		for(int i=0;i<size;++i){
			pq[1].push( B[1][i] );
		}
	}
	if( spR+1 < R ){
		B[2] = f(spR+1,R);
		int size = B[2].size();
		for(int i=0;i<size;++i){
			pq[2].push( B[2][i] );
		}
	}

	vector<PII> ans( (R-L)/2 );
	int posAns = 0;
	PII pii(res1,res2);
	ans[posAns] = pii;
	posAns = 1;

	while( !pq[0].empty() || !pq[1].empty() || !pq[2].empty() ){
		PII res(INF,INF);
		int num = 0;
		for(int i=0;i<3;++i){
			if( pq[i].empty() ) continue;
			PII now = pq[i].top();
			if( now < res ){
				res = now;
				num = i;
			}
		}
		ans[posAns] = res;
		++posAns;
		pq[num].pop();
	}

	return ans;
}
void solve(){
	int N;
	cin >> N;
	A.resize(N);
	Aindex.resize(N+1);
	seg0.init(N/2,INF);
	seg1.init(N/2,INF);

	for(int i=0;i<N;++i){
		cin >> A[i];
		Aindex[ A[i] ] = i;
