			seg1.update(i/2,A[i]);
		}else{
			seg0.update(i/2,A[i]);
		}
	}

	vector<PII> ans = f(0,N);
	for(int i=0;i<N/2;++i){
		if(i)cout << " ";
		cout << ans[i].first << " " << ans[i].second;
	}
	cout << endl;
}

