struct S {
    int tr[555005];
    void build(int cur, int l, int r, int *arr) {
        if (l == r) {
            tr[cur] = arr[l];
        } else {
            int m = (l + r) / 2;
            int dcur = cur + cur;
            build(dcur, l, m, arr);
            build(dcur + 1, m + 1, r, arr);
            tr[cur] = min(tr[dcur], tr[dcur + 1]);
        }
    }
    void build(int *arr, int n) {
        build(1, 0, n - 1, arr);
    }
    int getMin(int cur, int l, int r, int x, int y) {
        if (x > r || y < l) return INF;
        if (x <= l && r <= y) return tr[cur];
        int dcur = cur + cur;
        int m = (l + r) / 2;
        return min(getMin(dcur, l, m, x, y), getMin(dcur + 1, m + 1, r, x, y));
    }
    void update(int cur, int l, int r, int x, int y) {
        if (l == r) {
            tr[cur] = y;
        } else {
            int dcur = cur + cur;
            int m = (l + r) / 2;
            if (x <= m) {
                update(dcur, l, m, x, y);
            } else {
                update(dcur + 1, m + 1, r, x, y);
            }
        }
    }
};
