template<typename T>
class WaveletMatrix {
public:
	vector<T> data;
	vector<Bitvector> bitv;
	vector<int> border;
	int bitsize;
	WaveletMatrix(vector<T>& dat) : bitsize(sizeof(T) * 8), data(dat) {
		bitv.reserve(bitsize);
		REP(i, bitsize + 1)
			bitv.push_back(Bitvector(data.size()));
		border.resize(bitsize + 1);
		REP(j, data.size())
			bitv[0].set(j, bitcheck(data[j], bitsize - 1));
		bitv[0].calcblock();
		vector<T> buf[2];
		buf[0] = data;
		buf[1].resize(data.size());

		REP(i, bitsize - 1) {
			border[i + 1] = bitv[i].rank(data.size(), 0);
			int cou[2] = { 0, border[i + 1] };
			REP(j, data.size()) {
				bitv[i + 1].set(cou[bitv[i].get(j)], bitcheck(buf[i % 2][j], bitsize - i - 2));
				buf[1 - i % 2][cou[bitv[i].get(j)]] = buf[i % 2][j] << (i + 1) >> (i + 1);
				cou[bitv[i].get(j)]++;
			}
			bitv[i + 1].calcblock();
		}
		border[bitsize] = bitv[bitsize - 1].rank(data.size(), 0);
	}

	pii search(int s, int e, unsigned int t, int b = 0) {
		if (b == bitsize) return{ s,e };
		bool cur = bitcheck(t, bitsize - 1);
		return search(cur*border[b + 1] + bitv[b].rank(s, cur), cur*border[b + 1] + bitv[b].rank(e, cur), t << 1, b + 1);
	}
	int backward(int a, unsigned int t, int b = 0) {
		if (b == bitsize - 1) return a;
		backward(bitv[bitsize - b - 1].select(a + 1 - bitcheck(t, 0) * border[bitsize - b], bitcheck(t, 0)) - 1, t >> 1, b + 1);
	}

	int rank(int s, int e, T t) {
		pii r = search(s, e, t);
		return r.second - r.first;
	}

	int select(int a, T t) {
		pii r = search(0, data.size(), t);
		return  backward(r.first + a - 1, t);
	}

	T kthelement(int s, int e, int k, int b = 0) {
		int eo = bitv[b].rank(e, 0), so = bitv[b].rank(s, 0), cou = eo - so;
		if (b == bitsize - 1) return cou <= k;
		return (cou <= k ?
			kthelement(border[b + 1] + (s - so), border[b + 1] + (s - so) + (e - s - cou), k - cou, b + 1) :
			kthelement(so, so + cou, k, b + 1)) | ((cou <= k) << (bitsize - b - 1));
	}
	int less(int s, int e, T t, int b = 0) {
		int eo = bitv[b].rank(e, 0), so = bitv[b].rank(s, 0), cou = (eo - so);
		if (b == bitsize) return e - s;
		return bitcheck(t, bitsize - b - 1) ?
			less(border[b + 1] + (s - so), border[b + 1] + (s - so) + (e - s - cou), t, b + 1) + cou :
			less(so, so + cou, t, b + 1);
	}

	~WaveletMatrix() {
		REP(i, bitsize) bitv[i].clear();
	}
};

signed main() {
	int n;
	cin >> n;
	vector<int> num[2];
	num[0].resize(n / 2);
	num[1].resize(n / 2);
	REP(i, n) {
		scanf("%d", &num[i%2][i/2]);
	}
	WaveletMatrix<int> *wm[2];

	wm[0] = new WaveletMatrix<int>(num[0]);
	wm[1] = new WaveletMatrix<int>(num[1]);

	queue<pii> cc;
	cc.push({ 0,n });

	priority_queue<pair<pii, pair<pii,pii>>, vector<pair<pii, pair<pii, pii>>>, greater<pair<pii, pair<pii, pii>>>> pq;
	do {
		while (cc.size()) {
			pii ck = cc.front();
			cc.pop();

			int turn = ck.first % 2;

			int cur = wm[turn]->kthelement(ck.first / 2, (ck.second + !turn) / 2, 0);
			int pos = wm[turn]->select(1, cur);
			pos = pos * 2 + turn;
			int aik = wm[!turn]->kthelement((pos + 1) / 2, (ck.second + turn) / 2, 0);
			int apos = wm[!turn]->select(1, aik);
			apos = apos * 2 + !turn;

			pq.push({ {cur,aik}, {ck, {pos,apos} } });
		}

		auto top = pq.top();
		pq.pop();
		pii ck = top.second.first;
		int pos = top.second.second.first, apos = top.second.second.second;
		if (ck.first != pos)
			cc.push({ ck.first, pos });
		if (pos + 1 != apos)
			cc.push({ pos + 1 , apos });
		if (apos + 1 != ck.second)
			cc.push({ apos + 1, ck.second });

		printf("%d %d ", top.first.first, top.first.second);

	} while (cc.size() || pq.size());

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int Max_N=4*1e5;
int N,A[Max_N+10]={},Del[Max_N+10]={};
pair<int,int> B[Max_N+10]={};
inline int lowbit(int x){
	return x & - x;
}
inline void ADD(int x,int k){
	for(;x;x-=lowbit(x)) Del[x]=min(Del[x],k);
}
inline int ASK(int x){
	int Min=Del[x];
	for(;x<=N;x+=lowbit(x)) Min=min(Min,Del[x]);
	return Min;
}
struct kk{
	int l,r,Id1,Id2,Rev;
} T[Max_N*4+10]={};
inline void Build(int x,int l,int r){
	T[x].l=l; T[x].r=r;
	if(l==r){
		if(l%2) T[x].Id1=l;
		else T[x].Id2=l;
		return;
	}
	Build(x<<1,l,(l+r)>>1);
	Build((x<<1)+1,((l+r)>>1)+1,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline void DownTag(int x){
	if(T[x].Rev){
		swap(T[x<<1].Id1,T[x<<1].Id2);
		swap(T[(x<<1)+1].Id1,T[(x<<1)+1].Id2);
		T[x<<1].Rev^=1; T[(x<<1)+1].Rev^=1;
		T[x].Rev=0;
	}
}
inline void Add(int x,int k,int Val){
	DownTag(x);
	if(T[x].l==T[x].r){
		A[k]=Val;
		return;
	}
	if(k<=T[x<<1].r) Add(x<<1,k,Val);
	else Add((x<<1)+1,k,Val);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline void Change(int x,int l,int r){
	if(l<=T[x].l&&T[x].r<=r){
		swap(T[x].Id1,T[x].Id2);
		T[x].Rev^=1;
		return;
	}
	DownTag(x);
	if(l<=T[x<<1].r) Change(x<<1,l,r);
	if(r>T[x<<1].r) Change((x<<1)+1,l,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline int Ask(int x,int l,int r,int Opt){
    DownTag(x);
	if(l<=T[x].l&&T[x].r<=r) return Opt==1?T[x].Id1:T[x].Id2;
	int Ans=0,Anss=0;
	if(l<=T[x<<1].r) Ans=Ask(x<<1,l,r,Opt);
	if(r>T[x<<1].r) Anss=Ask((x<<1)+1,l,r,Opt);
	if(A[Ans]>A[Anss]) Ans=Anss;
	return Ans;
}
inline void Solv(){
	for(int i=1;i<=N/2;i++){
		int Min=Ask(1,1,N,1);
		int r=ASK(Min);
		int Minn=Ask(1,Min,r,2);
//		cout<<Min<<' '<<Minn<<' '<<r<<endl;
		B[i]=make_pair(A[Min],A[Minn]);
		Add(1,Min,1<<30); Add(1,Minn,1<<30);
		if(Min+1<Minn-1) Change(1,Min+1,Minn-1);
		ADD(Min,Min); ADD(Minn,Minn);
	}
}
int main(){
	scanf("%d",&N); A[0]=1<<30;
	for(int i=1;i<=N;i++) scanf("%d",&A[i]);
	for(int i=0;i<=N;i++) Del[i]=N;
	Build(1,1,N); Solv();
	for(int i=1;i<=N/2;i++) printf("%d %d ",B[i].first,B[i].second); puts("");
	return 0;
}

