void update(int k){
	int odd,pos=k;
	odd=k%2;
	k+=m-1;
	g[odd][k]=pos;
	g[(odd+1)%2][k]=INF;
	while(k>1){
		k/=2;
		for(int i=0;i<2;i++){
			if(g[i][k*2]==INF&&g[i][k*2+1]!=INF) g[i][k]=g[i][k*2+1];
			else if(g[i][k*2+1]==INF&&g[i][k*2]!=INF) g[i][k]=g[i][k*2];
			else if(g[i][k*2]!=INF&&g[i][k*2+1]!=INF){
				if(a[g[i][k*2]]<a[g[i][k*2+1]]) g[i][k]=g[i][k*2];
				else g[i][k]=g[i][k*2+1];
			}
		}
	}
}

int rmq(int l,int r,int k,int l1,int r1){
	int odd=l%2;
	if(l<=l1&&r>=r1) return g[odd][k];
	if(r<l1||l>r1) return INF;
	else{
		int x=rmq(l,r,k*2,l1,(l1+r1)/2),y=rmq(l,r,k*2+1,(l1+r1+1)/2,r1);
		if(x==INF&&y!=INF) return y;
		else if(x!=INF&&y==INF) return x;
		else if(x==INF&&y==INF) return INF;
		else{
			if(a[x]<a[y]) return x;
			else return y;
		}
	}
}

struct range{
	int a,b;
	int mint;
};

bool operator>(const range &x,const range &y){
	if(x.mint!=INF&&y.mint!=INF)return a[x.mint]>a[y.mint];
	else if(x.mint==INF&&y.mint!=INF) return true;
	else if(x.mint!=INF&&y.mint==INF) return false;
	else return true;
}


