    vector<II> ls = solve(l,i);
    vector<II> ms = solve(i+1,j);
    vector<II> rs = solve(j+1,r);

    int lsi = 0, msi = 0, rsi = 0;
    while(lsi < ls.size() || msi < ms.size() || rsi < rs.size()) {
      II ll = make_pair(INF_INT_MAX, INF_INT_MAX), mm = make_pair(INF_INT_MAX, INF_INT_MAX), rr = make_pair(INF_INT_MAX, INF_INT_MAX);
      if(lsi < ls.size()) {
        ll = ls[lsi];
      }
      if(msi < ms.size()) {
        mm = ms[msi];
      }
      if(rsi < rs.size()) {
        rr = rs[rsi];
      }

      if(ll.first < mm.first && ll.first < rr.first) {
        lsi++;
        ret.push_back(ll);
