void eval(int k){
    cnt[k]+=lazy[k];
    if (k*2+1<lazy.size()) {
        lazy[k*2]+=lazy[k];
        lazy[k*2+1]+=lazy[k];
    }
    lazy[k]=0;
    if ((cnt[k]&1)^(seg[k].first&1)) {
        swap(seg[k].second.first,seg[k].second.second);
        seg[k].first=cnt[k];
        if(k)eval(k>>1);
    }
}
void update(int x,int y, int k, int l, int r){
    eval(k);
    if (x<=l&&r<=y) {
        lazy[k]++;
        eval(k);
        return;
    }
    if (x<r&&l<y) {
        update(x, y, k*2, l, (l+r)>>1);
        update(x, y, k*2+1, (l+r)>>1, r);
    }
}
