}
P query(int x,int y, int k, int l, int r,int v){
    eval(k);
    if (x<=l&&r<=y) {
        if (v) {
            return seg[k].second.first;
        }else{
            return seg[k].second.second;
        }
    }
    else if (x<r&&l<y) {
        return min(query(x, y, k*2, l, (l+r)>>1, v),query(x, y, k*2+1, (l+r)>>1, r, v));
    }else{
        return {inf,-1};
    }
}
