const int N = 2e6+10;
int a[N],  pos[N], sum1[N<<2], sum2[N<<2], n,  ans;
// 1 奇数 , 2 偶数
typedef pair<int,int> pi;
struct node
{
    int first,second,l,r;
    bool operator <(const node &A)const
    {
        if((A.l>=l&&A.r<=r)||(l>=A.l&&r<=A.r))
        {
            if(A.l>=l&&A.r<=r) return 1;
            else return 0;
        }
        return A.first>first;
    }
};
vector<node>p;
void build(int l,int r,int rt)
{
    if(l==r)
    {
        scanf("%d", &a[l]);
        if(l&1)   sum1[rt]=a[l],sum2[rt]=0x3f3f3f3f;
        else sum1[rt]=0x3f3f3f3f,sum2[rt]=a[l];
        pos[a[l]]=l;
        return ;
    }
    int mid=(l+r)/2;
    build(l,mid,rt*2);
    build(mid+1,r,rt*2+1);
    sum1[rt]=min(sum1[rt<<1],sum1[rt<<1|1]);
    sum2[rt]=min(sum2[rt<<1],sum2[rt<<1|1]);
    return ;
}
int query1(int l,int r,int rt,int L,int R)
{
    if(L<=l&&R>=r)  return sum1[rt];
    int mid=(l+r)/2;
    int ans=0x3f3f3f3f;
    if(L<=mid) ans=min(ans,query1(l,mid,rt*2,L,R));
    if(R>mid) ans=min(ans,query1(mid+1,r,rt*2+1,L,R));
    return ans;
}
int query2(int l,int r,int rt,int L,int R)
{
    if(L<=l&&R>=r)  return sum2[rt];
    int mid=(l+r)/2;
    int ans=N+1;
    if(L<=mid) ans=min(ans,query2(l,mid,rt*2,L,R));
    if(R>mid) ans=min(ans,query2(mid+1,r,rt*2+1,L,R));
    return ans;
}
void dfs(int l,int r)
{
    if(l<1||r<1||l>=r||l>n||r>n) return ;
    if(l&1)
    {
        int x=query1(1,n,1,l,r);
        int al=pos[x];
        int y=query2(1,n,1,al+1,r);
        int ar=pos[y];
        p.push_back((node)
        {
            x,y,al,ar
        });
        dfs(al+1,ar-1);
        dfs(l,al-1);
        dfs(ar+1,r);
    }
    else
    {
        int x=query2(1,n,1,l,r);
        int al=pos[x];
        int y=query1(1,n,1,al+1,r);
        int ar=pos[y];
        p.push_back((node)
        {
            x,y,al,ar
        });
        dfs(al+1,ar-1);
        dfs(l,al-1);
        dfs(ar+1,r);
    }
}

