struct tree
{
	int ov,ev,lz,li;
}tr[800010];
void pd(int i)
{
	if(tr[i].lz)
	{
		swap(tr[i*2].ov,tr[i*2].ev);    tr[i*2].lz^=1;
		swap(tr[i*2+1].ov,tr[i*2+1].ev);tr[i*2+1].lz^=1;
		tr[i].lz=0;
	}
}
int mx(int a,int b)
{
	if(x[a]<x[b])return a;
	return b;
}
void clear(int i,int l,int r,int k)
{
	if(l==r)
	{
		tr[i].ov=tr[i].ev=0;
		tr[i].li=l;
		return ;
	}
	pd(i);
	if(k<=(l+r)/2)
	{
		clear(i*2,l,(l+r)/2,k);
		swap(tr[i*2+1].ov,tr[i*2+1].ev);
		tr[i*2+1].lz^=1;
	}
	else clear(i*2+1,(l+r)/2+1,r,k);
	tr[i].ov=mx(tr[i*2].ov,tr[i*2+1].ov);
	tr[i].ev=mx(tr[i*2].ev,tr[i*2+1].ev);
	if(tr[i*2].li)tr[i].li=tr[i*2].li;
	else tr[i].li=tr[i*2+1].li;
}
int sl(int i,int l,int r,int k)
{
	if(r<k)return 0;
	if(l>=k)return tr[i].li;
	int a;
	a=sl(i*2,l,(l+r)/2,k);
	if(a)return a;
	return sl(i*2+1,(l+r)/2+1,r,k); 
}
int se(int i,int l,int r,int ql,int qr)
{
	if(l>qr ||ql>r)return 0;
	//cout<<"se "<<l<<" "<<r<<" "<<tr[i].ov<<" "<<tr[i].ev<<endl;
	if(ql<=l && r<=qr)return tr[i].ov;
	pd(i);
	return mx(se(i*2,l,(l+r)/2,ql,qr),se(i*2+1,(l+r)/2+1,r,ql,qr));
}
void bu(int i,int l,int r)
{
	if(l==r)
	{
		if(l&1)tr[i].ov=l;
		else tr[i].ev=l;
		return ;
	}
	bu(i*2,l,(l+r)/2);bu(i*2+1,(l+r)/2+1,r);
	tr[i].ov=mx(tr[i*2].ov,tr[i*2+1].ov);
	tr[i].ev=mx(tr[i*2].ev,tr[i*2+1].ev);
