int n,a[2][200005],pos[200005],mi[2][200005][20];
typedef pair<int,pair<int,int> > pip;
priority_queue<pip,vector<pip>,greater<pip> > pq;
inline int query(int k,int l,int r){
	int lg=31-__builtin_clz(r-l+1);
	return min(mi[k][l][lg],mi[k][r-(1<<lg)+1][lg]);
}
int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n;
	for(int i=0;i<n;i++){
		int x;
		cin>>x;
		pos[x]=i;
		a[i&1][i]=x;
		a[(i&1)^1][i]=INF;
	}
	//RMQ Init
	for(int k=0;k<2;k++){
		for(int i=0;i<n;i++){
			mi[k][i][0]=a[k][i];
		}
		for(int j=1;(1<<j)<=n;j++){
			for(int i=0;(i+(1<<j)-1)<n;i++){
				mi[k][i][j]=min(mi[k][i][j-1],mi[k][i+(1<<(j-1))][j-1]);
			}
		}
	}
	pq.push(MP(query(0,0,n-1),MP(0,n-1)));
	while(!pq.empty()){
		pip u=pq.top();
		pq.pop();
		int q1=u.X,q2=query((pos[u.X]&1)^1,pos[u.X]+1,u.R);
		cout<<q1<<' '<<q2<<' ';
		if(u.L<pos[q1])pq.push(MP(query(u.L&1,u.L,pos[q1]-1),MP(u.L,pos[q1]-1)));
		if(pos[q1]+1<pos[q2])pq.push(MP(query((pos[q1]+1)&1,pos[q1]+1,pos[q2]-1),MP(pos[q1]+1,pos[q2]-1)));
		if(pos[q2]<u.R)pq.push(MP(query((pos[q2]+1)&1,pos[q2]+1,u.R),MP(pos[q2]+1,u.R)));
	}
	return 0;
}

