const int INF = 1001001001;
const int MAX = 400010;

struct segtree {
    int N, dat[2*MAX];
    segtree() {}
    segtree(int n) {
        N = 1;
        while(N < n) N *= 2;
        for(int i = 0; i < 2*N-1; i++)
            dat[i] = INF;
    }
    // update k th element
    void update(int k, int a) {
        k += N-1; // leaf
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }
    // min [a, b)
    int query(int a, int b) { return query(a, b, 0, 0, N); }
    int query(int a, int b, int k, int l, int r) {
        if(r <= a or b <= l) return INF;
        if(a <= l and r <= b) return dat[k];
        int m = (l + r) / 2;
        return min(query(a, b, k*2+1, l, m), query(a, b, k*2+2, m, r));
    }
};

segtree even, odd;
vi dict;

struct Data
{
    int a, b;
    int x, y;

    bool operator< (const Data& d) const
    {
        return x > d.x;
    }
};

Data make(int a, int b)
{
    int x, y;
    //cout << "a = " << a << ", b = " << b << flush;

    if(a%2 == 0){
        x = even.query(a/2, b/2);
        y = odd.query(dict[x]/2, b/2);
    }
    else{
        // 01234567
        x = odd.query(a/2, b/2);
        y = even.query(dict[x]/2+1, b/2+1);
    }

    //cout << ", x = " << x << ", dict[x] = " << dict[x] << ", y = " << dict[y]  << endl;
    return {a, b, x, y};
}

signed main()
{
    int n;
    cin >> n;

    even = segtree(n);
    odd  = segtree(n);
    dict = vi(n+1);

    rep(i, n){
        int p;
        cin >> p;
        dict[p] = i;
        if(i%2 == 0) even.update(i/2, p);
        else         odd.update(i/2, p);
    }

    /*
    rep(i, n/2) cout << even.query(i, i+1) << ", ";
    cout << endl;
    rep(i, n/2) cout << odd.query(i, i+1) << ", ";
    cout << endl;
    */

    priority_queue<Data> segs;
    segs.push(make(0, n));


    while(!segs.empty())
    {
        Data d = segs.top();
        segs.pop();

        cout << d.x << ' ' << d.y << ' ';

        if(d.a < dict[d.x])         segs.push(make(d.a, dict[d.x]));
        if(dict[d.x]+1 < dict[d.y]) segs.push(make(dict[d.x]+1, dict[d.y]));
        if(dict[d.y]+1 < d.b)       segs.push(make(dict[d.y]+1, d.b));
    }

    cout << endl;
}

