int qry(int left,int right,int a,int b,int k,int flip){
	if(right<=a||b<=left)return mod;
	if(left<=a&&b<=right)return seg[flip][k];
	int mid=(a+b)/2;
	return min(qry(left,right,a,mid,k*2+1,flip),qry(left,right,mid,b,k*2+2,flip));
}
