void Update(int tree[], int idx, int cnt) {
	idx += B; tree[idx] = cnt; idx >>= 1;
	while (idx) tree[idx] = min(tree[idx * 2], tree[idx * 2 + 1]), idx >>= 1;
}
int Get(int tree[], int l, int r) {
	l += B, r += B;
	int res = INF;
	while (l <= r) {
		if (l & 1) res = min(res, tree[l]), l++;
		if (!(r & 1)) res = min(res, tree[r]), r--;
		l >>= 1, r >>= 1;
	}
	return res;
}
bool pro(int L, int R) {
	if (L > R) return false;
	int p = min(Get(Etree, L, R), Get(Otree, L, R));
	if (p == INF) return false;
	int pidx = inv[p];
	if (pidx & 1) Update(Otree, pidx, INF);
	else Update(Etree, pidx, INF);

	int q, qidx;
	if (pidx & 1) q = Get(Etree, L, R);
	else q = Get(Otree, L, R);
	qidx = inv[q];
	if (qidx & 1) Update(Otree, qidx, INF);
	else Update(Etree, qidx, INF);

	if (pidx > qidx) swap(p, q), swap(pidx, qidx);
	int cur = T;
	ans[cur] = TREE(p, q);
	ans[cur].l = ++T;
	if (!pro(pidx + 1, qidx - 1)) ans[cur].l = 0, T--;
	if (pidx == L && qidx == R) return true;
	if (pidx == L) L = qidx + 1;
	if (qidx == R) R = pidx - 1;
	ans[cur].r = ++T;
	if (!pro(L, R)) ans[cur].r = 0, T--;
	return true;
}
