class SegmentTree {
  ll n;
  vector<pll> dat;

public:
  SegmentTree(ll size) {
    n = 1;
    while(n < size) n *= 2;
    REP(i, 0, 2 * n - 1) dat.push_back(pll(INF, INF));
  }

  pll query(ll a, ll b) { return rquery(a, b, 0, 0, n); }

  void update(ll k, pll a) {
    k += n - 1;
    dat[k] = a;
    while(k > 0) {
      k = (k - 1) / 2;
      dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

private:
  pll rquery(ll a, ll b, ll k, ll l, ll r) {
    if(r <= a || b <= l) return pll(INF, INF);
    if(a <= l && r <= b) return dat[k];
    pll vl = rquery(a, b, k * 2 + 1, l, (l + r) / 2);
    pll vr = rquery(a, b, k * 2 + 2, (l + r) / 2, r);
    return op(vl, vr);
  }

  pll op(pll a, pll b) { return min(a, b); }
};

struct segment {
  ll l, r;
  pll v;

public:
  bool operator<(const segment &s) const { return v > s.v; }
};

