int query(int o,int l,int r) {
	//printf("%d %d %d\n",o,l,r);
	int len=Log[r-l+1];
	return min(d[o][l][len],d[o][r-(1<<len)+1][len]);
}

int query_begin(int x) {
	int ret=0;
	for (;x;x-=x&(-x)) ret=max(ret,t1[x]);
	return ret;
}

void begin_add(int x) {
	int tmp=x;
	for (;x<=n;x+=x&(-x)) t1[x]=max(t1[x],tmp);
}

int query_end(int x) {
	int ret=n+1;
	for (;x<=n;x+=x&(-x)) ret=min(ret,t2[x]);
	return ret;
}

void end_add(int x) {
	int tmp=x;
	for (;x;x-=x&(-x)) t2[x]=min(t2[x],tmp);
}

void Push(int l,int r) {
	if (l>r) return;
	S.push(query(l&1,l,r));
}

