                nu=1;
            }
        }
        if(nb<b.size()){
            if(b[nb]<n1){
                n1=b[nb],n2=b[nb+1];
                nu=2;
            }
        }
        if(nc<c.size()){
            if(c[nc]<n1){
                n1=c[nc],n2=c[nc+1];
                nu=3;
            }
        }
        if(n1==inf)break;
        ret.push_back(n1);
        ret.push_back(n2);
        if(nu==1)na+=2;
        else if(nu==2)nb+=2;
        else if(nu==3)nc+=2;

    }
    return ret;
}
