    void resize(int m) {
        n = 1;
        while(n < m) n *= 2;
        dat.resize(2*n-1);
        rep(i,0,2*n-1) dat[i] = INT_MAX;
    }

    // k番目 (0-indexed) の値を a に更新
    void update(int k, T a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k*2+1], dat[k*2+2]);
        }
    }

    // [a, b) の最小値を返す
    // 最初に呼び出すときは XX.query(a, b, 0, 0, -1) とする
    T query(int a, int b, int k, int l, int r) {
        if(r == -1) r = n;
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return dat[k];
        else {
            T vl = query(a, b, k*2+1, l, (l+r)/2);
            T vr = query(a, b, k*2+2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

vector<pii> ans;
rmq<int> even, odd;

// position [l, r)
vector<pii> solve(int l, int r) {
    if(l >= r) return vector<pii>();
    // printf("l = %lld, r = %lld\n", l, r);
    vector<pii> ret;
    int lb = odd.query(l, r, 0, 0, -1);
    int ub = even.query(l, r, 0, 0, -1);
    int mi = min(pos[lb], pos[ub]);
    int ma = max(pos[lb], pos[ub]);
    ret.push_back(pii(p[mi], p[ma]));
    // printf("push: %lld and %lld\n", p[mi], p[ma]);

    vector< vector<pii> > v(3);
    v[0] = solve(l, mi);
    v[1] = solve(mi+1, ma);
    v[2] = solve(ma+1, r);
    vector<pii> temp;
    rep(i,0,3) rep(j,0,v[i].size()) {
        temp.push_back(v[i][j]);
    }
    sort(temp.begin(), temp.end());

    rep(i,0,temp.size()) ret.push_back(temp[i]);
    return ret;
}

