typedef vector<pair<int, int> > vi;

#define bit(x) (1 << (x))
#define MX 400005
#define L 20    //N 보다  큰  2 의  최소제곱지수
inline void chkmin(int &x, int y) {
	if (y < x) x = y;
}
struct RMQ {
	int b[MX];
	int x[MX][L];
	int N;
	void build(int *p, int n) {
		int i, j, k;
		N = n;
		for (k = 0, i = 1; i <= N; i++) {
			if (i == bit(k + 1)) k++;
			b[i] = k;
		}
		for (i = 0; i < N; i++) x[i][0] = p[i];
		for (j = 1; j <= k; j++) {
			for (i = 0; i < N; i++) {
				x[i][j] = x[i][j - 1];
				if (i + bit(j - 1) < N)
					chkmin(x[i][j],  x[i + bit(j  -  1)][j  -  1]);
			}
		}
	}
//return min value between [st, en)
	int range_min(int st, int en) {
		int j = b[en - st];
		return min(x[st][j], x[en - bit(j)][j]);
	}
};
int pos[200005], p[200005], a[2][200005];
RMQ R[2];
int cnt = 0;
vi calc(int l, int r) {
//	cerr << l << ' ' << r << '\n';
//	if(cnt > 5) return tmp;
	if(r == l + 1){
		vi ret;
		ret.push_back(make_pair(p[l], p[r]));
		return ret;
	}
	int mn = R[l % 2].range_min(l / 2, (r - 1) / 2 + 1);
	int id = pos[mn];
	int mn1 = R[(id + 1) % 2].range_min((id + 1) / 2, (r) / 2 + 1);
	int id1 = pos[mn1];
//	cout << "id" << id << ' ' << id1 << '\n';
	vi ret_L, ret_R, ret_mid;
	int curL = -1, curR = -1, curm = -1;
	if(id - 1 > l) ret_L = calc(l, id - 1), curL = ret_L.size() - 1;
//	cerr << l << ' ' << r << '\n';
	if(r > id1 + 1) ret_R = calc(id1 + 1, r), curR = ret_R.size() - 1;
//	cerr << l << ' ' << r << '\n';
	if(id1 - 1 > id + 1) ret_mid = calc(id + 1, id1 - 1), curm = ret_mid.size() - 1;
	vi ret;
//	cout << "lr" << l << ' ' << r << '\n';
	while(1){
		if(curL == -1 && curR == -1 && curm == -1) break;
		if(curL == -1){
			if(curm == -1) ret.push_back(ret_R[curR --]);
			else if(curR == -1 || ret_mid[curm] < ret_R[curR]) ret.push_back(ret_mid[curm]), curm --;
			else ret.push_back(ret_R[curR]), curR --;
		}
		else if(curR == -1){
			if(curm == -1) ret.push_back(ret_L[curL --]);
			else if(curL == -1 || ret_mid[curm] < ret_L[curL]) ret.push_back(ret_mid[curm]), curm --;
			else ret.push_back(ret_L[curL]), curL --;
		}
		else if(curm == -1){
			if(ret_L[curL] < ret_R[curR]) ret.push_back(ret_L[curL]), curL --;
			else ret.push_back(ret_R[curR]), curR --;
		}
		else {
			if(ret_mid[curm] < ret_R[curR] && ret_mid[curm] < ret_L[curL]) ret.push_back(ret_mid[curm --]);
			else if(ret_L[curL] < ret_mid[curm] && ret_L[curL] < ret_R[curR]) ret.push_back(ret_L[curL --]);
			else if(ret_R[curR] < ret_L[curL] && ret_R[curR] < ret_mid[curm]) ret.push_back(ret_R[curR --]);
		}
	}

	reverse(ret.begin(), ret.end());
	ret.push_back(make_pair(p[id], p[id1]));
	return ret;
}

