	int mid=L+R>>1;
	int x=l<=mid?QT(w<<1,L,mid):0,y=r>mid?QT(w<<1|1,mid+1,R):0;
	return Y[x]<Y[y]?x:y;
}

void motree(int w,int L,int R)
{
	if (l<=L&&r>=R)
