using namespace std;

typedef pair <int, int> ii;

const int Maxn = 200005;
const int Maxm = 1048576;

int mn[Maxm][2];
bool ch[Maxm];
int lim[Maxm];
int n;
int a[Maxn];

int Better(int i, int j)
{
	if (i == -1) return j;
	if (j == -1) return i;
	return a[i] < a[j]? i: j;
}

void downOn(int v)
{
	swap(mn[v][0], mn[v][1]);
	ch[v] = !ch[v];
}

void Down(int v)
{
	if (ch[v]) {
		downOn(2 * v); downOn(2 * v + 1);
		ch[v] = false;
	}
}

void Union(int v)
{
	mn[v][0] = Better(mn[2 * v][0], mn[2 * v + 1][0]);
	mn[v][1] = Better(mn[2 * v][1], mn[2 * v + 1][1]);
}

void Create(int v, int l, int r)
{
	lim[v] = n - 1;
	if (l == r) { mn[v][l % 2] = l; mn[v][1 - l % 2] = -1; }
	else {
		int m = l + r >> 1;
		Create(2 * v, l, m); Create(2 * v + 1, m + 1, r);
		Union(v);
	}
}

void Erase(int v, int l, int r, int ind)
{
	if (l == r) a[l] = Maxn;
	else {
		Down(v);
		int m = l + r >> 1;
		if (ind <= m) Erase(2 * v, l, m, ind);
		else Erase(2 * v + 1, m + 1, r, ind);
		Union(v);
	}
}

int getMin(int v, int l, int r, int a, int b, int wh)
{
	if (l == a && r == b) return mn[v][wh];
	else {
		Down(v);
		int m = l + r >> 1;
		int res = -1;
		if (a <= m) res = Better(res, getMin(2 * v, l, m, a, min(m, b), wh));
		if (m + 1 <= b) res = Better(res, getMin(2 * v + 1, m + 1, r, max(m + 1, a), b, wh));
		return res;
	}
}

void Change(int v, int l, int r, int a, int b)
{
	if (l == a && r == b) downOn(v);
	else {
		Down(v);
		int m = l + r >> 1;
		if (a <= m) Change(2 * v, l, m, a, min(m, b));
		if (m + 1 <= b) Change(2 * v + 1, m + 1, r, max(m + 1, a), b);
		Union(v);
	}
}

void UpdateLim(int v, int l, int r, int a, int b, int val)
{
	if (l == a && r == b) lim[v] = min(lim[v], val);
	else {
		int m = l + r >> 1;
		if (a <= m) UpdateLim(2 * v, l, m, a, min(m, b), val);
		if (m + 1 <= b) UpdateLim(2 * v + 1, m + 1, r, max(m + 1, a), b, val);
	}
}

int GetLim(int v, int l, int r, int x)
{
	int res = lim[v];
	if (l < r) {
		int m = l + r >> 1;
		if (x <= m) res = min(res, GetLim(2 * v, l, m, x));
		else res = min(res, GetLim(2 * v + 1, m + 1, r, x));
	}
	return res;
}

int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
		scanf("%d", &a[i]);
	Create(1, 0, n - 1);
	for (int i = 0; i < n / 2; i++) {
		int A = getMin(1, 0, n - 1, 0, n - 1, 0);
		int lim = GetLim(1, 0, n - 1, A);
		int B = getMin(1, 0, n - 1, A + 1, lim, 1);
		printf("%d %d%c", a[A], a[B], i + 1 < n / 2? ' ': '\n');
		Erase(1, 0, n - 1, A); Erase(1, 0, n - 1, B);
		if (A > 0) UpdateLim(1, 0, n - 1, 0, A - 1, A - 1);
		if (A + 1 < B) {
			UpdateLim(1, 0, n - 1, A + 1, B - 1, B - 1);
			Change(1, 0, n - 1, A + 1, B - 1);
		}
	}
	return 0;
}

