#define PB push_back
#define MP make_pair
#define F first
#define S second
#define sz(x) ((int)(x).size())
#define all(x) (x).begin(),(x).end()

const int maxn = 2e5+10;
const int64 MO = 1e9+7;
const int64 IN = 1e9;

set <pair<int,pii>> st;
int seg[3][maxn * 4], pos[3][maxn * 4];
int p[maxn];
int N;

void pull (int idx, int id) {
	if (seg[idx][id * 2 + 0] < seg[idx][id * 2 + 1])
		pos[idx][id] = pos[idx][id * 2 + 0];
	else
		pos[idx][id] = pos[idx][id * 2 + 1];
	seg[idx][id] = min(seg[idx][id * 2 + 0], seg[idx][id * 2 + 1]);
	return;
}

pii pull (pii x, pii y) {
	if (x.F < y.F)
		return x;
	else
		return y;
}

void build (int idx, int l = 0, int r = N, int id = 1) {
	if (r - l == 1) {
		seg[idx][id] = IN;
		pos[idx][id] = -1;
		if (idx == 2 || (idx == 0 && l % 2 == 0) || (idx == 1 && l % 2 == 1)) {
			seg[idx][id] = p[l];
			pos[idx][id] = l;
		}
		return;
	}
	int mid = (l + r) >> 1;
	build(idx, l, mid, id * 2 + 0);
	build(idx, mid, r, id * 2 + 1);
	pull(idx, id);
	return;
}

pii getmn (int idx, int st, int en, int l = 0, int r = N, int id = 1) {
	if (st >= r || en <= l)
		return MP( IN, -1 );
	if (st <= l && en >= r)
		return MP( seg[idx][id], pos[idx][id] );
	int mid = (l + r) >> 1;
	return pull(getmn(idx, st, en, l, mid, id * 2 + 0), getmn(idx, st, en, mid, r, id * 2 + 1));
}

int main () {
	ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
	cin >> N;
	for (int i = 0; i < N; i++)
		cin >> p[i];
	build(0); build(1); build(2);
	st.insert( MP( getmn(0, 0, N - 1).F, MP( 0, N - 1 ) ) );
	while (sz(st)) {
		pair<int,pii> x = *st.begin();
		st.erase(x);
		int l, r, ps, f;
		l = x.S.F;
		r = x.S.S;
		ps = getmn(l % 2, l, r).S;
		f = getmn(1 - ps % 2, ps + 1, r + 1).S;
		if (ps - l > 1)
			st.insert( MP( getmn(l % 2, l, ps - 1).F, MP( l, ps - 1 ) ) );
		if (f - ps > 1)
			st.insert( MP( getmn(1 - ps % 2, ps + 1, f - 1).F, MP( ps + 1, f - 1 ) ) );
		if (r - f > 1)
			st.insert( MP( getmn(1 - f % 2, f + 1, r).F, MP( f + 1, r ) ) );
		cout << p[ps] << " " << p[f] << " ";
	} cout << "\n";
}

