		ans.push_back(mi);
		ans.push_back(ma);
		int poma;
		poma = binary(ma);
		if (pomi > a) {
			if (a % 2 == 0)
				que.push(make_tuple(query(a, pomi, 0, 0, n), a, pomi));
			else
				que.push(make_tuple(query2(a, pomi, 0, 0, n), a, pomi));
		}
		if (poma - 1 > pomi + 1) {
			if ((pomi + 1) % 2 == 0)
				que.push(make_tuple(query(pomi + 1, poma, 0, 0, n), pomi + 1, poma));
			else
				que.push(make_tuple(query2(pomi + 1, poma, 0, 0, n), pomi + 1, poma));
		}
		if (b - 1 > poma) {
			if ((poma + 1) % 2 == 0)
				que.push(make_tuple(query(poma + 1, b, 0, 0, n), poma + 1, b));
			else
				que.push(make_tuple(query2(poma + 1, b, 0, 0, n), poma + 1, b));
		}
	}
	for (int i = 0; i < nn; i++) {
		cout << ans[i] << " ";
	}
	return 0;
}

