const int kN = 2e5 + 5;
const int kInf = 1e9;
int p[kN], rv[kN];

struct SparseTable {
    int sp[20][kN];

    SparseTable() = default;
    SparseTable(const vector<int> &a) {
        for (int i = 0; i < a.size(); ++i) sp[0][i] = a[i];
        for (int i = 1; (1 << i) <= a.size(); ++i) {
            for (int j = 0; j + (1 << i) <= a.size(); ++j)
                sp[i][j] = min(sp[i - 1][j], sp[i - 1][j + (1 << (i - 1))]);
        }
    }

    int Query(int l, int r) {
        int p = 31 - __builtin_clz(r - l + 1);
        return min(sp[p][l], sp[p][r - (1 << p) + 1]);
    }
} sp[2];

vector<pair<int, int>> Dfs(int l, int r) {
    if (l > r) return {};
    int x = sp[l % 2].Query(l, r);
    int y = sp[1 - l % 2].Query(rv[x] + 1, r);
    assert(x < kInf && y < kInf);
    vector<pair<int, int>> res = {make_pair(x, y)};
    auto lhs = Dfs(l, rv[x] - 1), mhs = Dfs(rv[x] + 1, rv[y] - 1), rhs = Dfs(rv[y] + 1, r);
    reverse(lhs.begin(), lhs.end());
    reverse(mhs.begin(), mhs.end());
    reverse(rhs.begin(), rhs.end());
    while (lhs.size() || mhs.size() || rhs.size()) {
        auto lf = lhs.empty() ? make_pair(kInf, -1) : lhs.back();
        auto mf = mhs.empty() ? make_pair(kInf, -1) : mhs.back();
        auto rf = rhs.empty() ? make_pair(kInf, -1) : rhs.back();
        if (lf < mf && lf < rf) {
            res.push_back(lf);
            lhs.pop_back();
        }
        if (mf < lf && mf < rf) {
            res.push_back(mf);
            mhs.pop_back();
        }
        if (rf < lf && rf < mf) {
            res.push_back(rf);
            rhs.pop_back();
        }
    }
    return res;
}

