    for (int i = 0; i < n; ++i) {
        v[i % 2].push_back(p[i]);
        v[1 - i % 2].push_back(kInf);
    }
    sp[0] = SparseTable(v[0]);
    sp[1] = SparseTable(v[1]);
    auto ans = Dfs(0, n - 1);
    for (auto u : ans) printf("%d %d ", u.first + 1, u.second + 1);
    puts("");
    return 0;
}

