using namespace std;

struct Monoid{
	using T = int; //モノイドの台集合の型
	T operator()(const T &a, const T &b) { return min(a,b); } //二項演算
	static constexpr T identity() { return INF; } //単位元
};

template<class Monoid>
class SegTree{ //SegTree<Monoid> seg(n);
	private:
		using T = typename Monoid::T; //台集合の型をエイリアス
		Monoid op; //演算の関数オブジェクト
		const int n; //列の長さ
		vector<T> t; //内部二分木

		void prop_to(int i) { //ノードiに伝搬
			t[i] = op(t[2 * i], t[2 * i + 1]);
		}

	public:
		SegTree(int n) : n(n), t(2 * n, op.identity()) {} //単位元で埋める初期化
		SegTree(const vector<T> &v) : n(v.size()), t(2 * n){ //配列を用いて初期化
			copy(begin(v), end(v), begin(t) + n);
			for(int i = n - 1; i > -0; i--) prop_to(i);
		}

		void set(int i, const T &x){
			t[i += n] = x; 
			while(i >>= 1) prop_to(i);
		}

		void add(int i, const T &x){
			set(i, get(i) * x);
		}

		T get(int i) { return t[i + n]; } //列のi番目を返す

		T query(int l, int r){
			T accl = op.identity(), accr = op.identity();
			for(l += n, r += n; l < r; l >>= 1, r >>= 1){
				if(l & 1) accl = op(accl, t[l++]);
				if(r & 1) accr = op(t[r-1], accr);
			}
			return op(accl, accr);
		}
};

vector<int> p, idx;
list<pair<int, int>> dfs(int l, int r, SegTree<Monoid>& even, SegTree<Monoid>& odd){
	if(l >= r) return list<pair<int, int>>();
	if(r - l == 2){
		list<pair<int, int>> res = {make_pair(p[l], p[l + 1])};
		return res;
	}

	int L, R;
	if(l % 2){
		L = idx[odd.query(l, r - 1)]; //閉区間
		R = idx[even.query(L,r)]; // 閉区間
	}else{
		L = idx[even.query(l,r - 1)]; // 閉区間
		R = idx[odd.query(L, r)]; //閉区間
	}

	list<pair<int, int>> res[3];
	res[0] = dfs(l, L, even, odd);
	res[1] = dfs(L + 1, R, even, odd);
	res[2] = dfs(R + 1, r, even, odd);

	int order[] = {0,1,2};
	if(res[order[0]].front() > res[order[1]].front()){
		swap(order[0], order[1]);
	}
	if(res[order[1]].front() > res[order[2]].front()){
		swap(order[1], order[2]);
	}
	if(res[order[0]].front() > res[order[1]].front()){
		swap(order[0], order[1]);
	}

	list<pair<int, int>> a;
	copy(all(res[order[0]]), back_inserter(a));
	copy(all(res[order[1]]), back_inserter(a));
	copy(all(res[order[2]]), back_inserter(a));
	a.emplace_front(make_pair(p[L], p[R]));

	return a;
}

