template<class M>
struct MonoidSegTree {
  int n;
  int size;
  vector<M> seg;

  MonoidSegTree(const vector<M> A) {
    n = A.size();
    size = 1;
    while (size < n) size *= 2;
    seg.resize(size);
    fill(seg.begin(),seg.end(),mp(INF,0));
    seg.insert(seg.end(), A.begin(), A.end());
    seg.resize(size*2);
    fill(seg.begin()+size+A.size(),seg.end(),mp(INF,0));
    for (int i=size-1; i>0; --i){
    	if(seg[i*2].fi<seg[i*2+1].fi) seg[i]=seg[i*2];
    	else seg[i]=seg[i*2+1];
    }
  }

  void Update(int k, const M v) {
    k += size;
    seg[k] = v;
    while (k > 1) {
      k /= 2;
	  if(seg[k*2].fi<seg[k*2+1].fi) seg[k]=seg[k*2];
      else seg[k]=seg[k*2+1];
    }
  }

  M Get(int l, int r) {//半開区間
    M retl = mp(INF,0); // the identity element
    M retr = mp(INF,0);

    l += size;
    r += size;
    for (; l < r; l>>=1, r>>=1) {
      if (r & 1) if(seg[--r].fi<retr.fi) retr=seg[r];
      if (l & 1) if(seg[l].fi<retl.fi) retl=seg[l++];
    }
    if(retl.fi<retr.fi) return retl;
    else return retr;
  }

  M At(int k) {
    return seg[k+size];
  }
};

