void update(int n,int l,int r,int s,int e){

	if(r < s || l > e) return;
	if(l >= s && r <= e){
		segm[n].fi=v[l], segm[n].se=l;
		sego[n].fi=sege[n].fi=1e9;
		sego[n].se=sege[n].se=-1;
