		sege[lin].se;
	else sege[n].fi=sege[rin].fi, sege[n].se=sege[rin].se;
}
pair<int, int> get(int n,int l,int r,int s,int e,int t){
	if(r < s || l > e) return{1e9, -1};
	else if(l >= s && r <= e){
		if(t == 1) return segm[n];
		if(t == 2) return sego[n];
		if(t == 3) return sege[n];
	}
	int mid=(l + r) / 2;
	pair<int, int> ret={ 1e9, -1 },li,ri;
	li=get(n * 2 + 1,l,mid,s,e,t);
	ri=get(n * 2 + 2,mid + 1,r,s,e,t);
	if(li.fi < ri.fi) ret.fi=li.fi, ret.se=li.se;
	else ret.fi=ri.fi, ret.se=ri.se;
	return ret;
}
