template<class Value = int>
class SegmentTree{
  int n;
  vector<Value> V;
  Value DEFAULT_VALUE;

  //evaluation function
  static Value default_evaluate(Value a, Value b){
    return min(a,b);
  }

  function< Value(Value, Value) > evaluate;

  //return evaluated value in [a,b)
  //T[at] covers [l,r)
  Value RangeEvaluation(int a, int b, int at, int l, int r){
    //out of range
    if(r <= a || b <= l) return DEFAULT_VALUE;
    //covered
    if(a <= l && r <= b) return V[at];

    //partially covered
    else{
      Value val_left = RangeEvaluation(a,b, at*2+1, l, (l+r)/2);
      Value val_right = RangeEvaluation(a,b, at*2+2, (l+r)/2, r);
      return evaluate(val_left, val_right);
    }
  }

 public:
  SegmentTree(int size, Value DEFAULT = 1e7, function< Value(Value, Value) > eval = default_evaluate){
    DEFAULT_VALUE = DEFAULT;
    evaluate = eval;
    n=1;
    while(n<size) n <<= 1;
    V = vector<Value>(2*n - 1, DEFAULT_VALUE);
  }

  void update(int at, Value new_val){
    at += n-1;
    V[at] = new_val;
    while(at>0){
      at = (at-1)/2;
      V[at] = evaluate(V[at*2 + 1], V[at*2 + 2]);
    }
  }


  //return evaluated value in [l,r)
  Value RangeEvaluation(int l, int r){
    if(l>=r) return DEFAULT_VALUE;
    if(l>=n) return DEFAULT_VALUE;
    return RangeEvaluation(l,r, 0, 0, n);
  }
};



int main(){
  int n;
  cin >> n;
  vector<int> p(n);
  cin >> p;

  vector<int> pos(n);
  for(int i=0; i<n; i++){
    pos[p[i]-1] = i;
  }

  SegmentTree<int> even(n/2+1), odd(n/2+1);
  for(int i=0; i<n; i++){
    if(i&1){
      odd.update(i/2, p[i]);
    }else{
      even.update(i/2, p[i]);
    }
  }

  int m = n/2;

  vector<pair<int,int>> ans;
  priority_queue<pair<int,pair<int,int>>, vector<pair<int,pair<int,int>>>, greater<pair<int,pair<int,int>>>> pq;

  pq.push( {even.RangeEvaluation(0,n/2), {0,n}} );
  while(pq.size()){
    auto p = pq.top();
    pq.pop();
    int l = p.second.first;
    int r = p.second.second;

    int x = -1;
    int y = -1;
    if(l&1){
      x = odd.RangeEvaluation(l/2, r/2);
    }else{
      x = even.RangeEvaluation(l/2, r/2);
    }
    if(l&1){
      y = even.RangeEvaluation((pos[x-1]+1)/2, (r+1)/2);
    }else{
      y = odd.RangeEvaluation(pos[x-1]/2, r/2);
    }

    ans.push_back( {x,y} );

    int x_pos = pos[x-1];
    int y_pos = pos[y-1];

    if( x_pos&1 ){
      odd.update(x_pos/2, 1e7);
    }else{
      even.update(x_pos/2, 1e7);
    }
    if( y_pos&1 ){
      odd.update(y_pos/2, 1e7);
    }else{
      even.update(y_pos/2, 1e7);
    }

    if( l < x_pos ){
      int val;
      if(l&1){
        val = odd.RangeEvaluation(l/2, x_pos/2);
      }else{
        val = even.RangeEvaluation(l/2, x_pos/2);
      }
      pq.push( {val, {l, x_pos}} );
    }

    if( y_pos - x_pos >= 2 ){
      int val;
      if( (x_pos+1)&1 ){
        val = odd.RangeEvaluation((x_pos+1)/2, y_pos/2);
      }else{
        val = even.RangeEvaluation((x_pos+1)/2, y_pos/2);
      }
      pq.push( {val, {x_pos+1, y_pos}} );
    }

    if( y_pos < r-1 ){
      int val;
      if( (y_pos+1)&1 ){
        val = odd.RangeEvaluation((y_pos+1)/2, r/2);
      }else{
        val = even.RangeEvaluation((y_pos+1)/2, r/2);
      }
      pq.push( {val, {y_pos+1, r}});
    }
  }

  println(join(ans, " "));

  return 0;
}

