void build(int n , int s , int e) {
	if (s == e) {
		seg[(s & 1) ^ 1][n] = oo;
		seg[(s & 1)][n] = p[s];
		return;
	}
	build(2 * n, s, (s + e) / 2);
	build(2 * n + 1, (s + e) / 2 + 1, e);
	seg[0][n] = min(seg[0][2 * n], seg[0][2 * n + 1]);
	seg[1][n] = min(seg[1][2 * n], seg[1][2 * n + 1]);
}
int get(int type, int n , int s , int e, int l , int r) {
	if (s > r || e < l)return oo;
	if (s >= l && e <= r)return seg[type][n];
	return min(get(type, 2 * n, s, (s + e) / 2, l, r), get(type, 2 * n + 1, (s + e) / 2 + 1, e, l, r));
}
struct inv {
	int l , r , x , y;
	inv(int _l , int _r) {
		l = _l;
		r = _r;
		x = get(l & 1, 1, 1, n, l, r);
		y = get((l & 1) ^ 1, 1, 1, n, bk[x], r);
	}
	bool operator<(const inv &r) const {
		if (x != r.y)
			return x > r.x;
		return y > r.y;
	}
};
