int mat[2][4 * 200005];

int f(int a0, int a1) {
	if (a0 == -1) return a1;
	if (a1 == -1) return a0;
	if (num[a0] < num[a1]) return a0;
	return a1;
}

void build(int at, int l, int r) {
	mat[0][at] = mat[1][at] = -1;
	if (l == r) {
		mat[l & 1][at] = l;
		return;
	}
	int mid = (l + r) / 2;
	build(at * 2, l, mid);
	build(at * 2 + 1, mid + 1, r);

	for (int i = 0; i < 2; i++) {
		mat[i][at] = f(mat[i][at * 2], mat[i][at * 2 + 1]);
	}
}

int query(int at, int l, int r, int L, int R, int parity) {
	if (R < l || r < L) return -1;
	if (L <= l && r <= R) {
		return mat[parity][at];
	}
	if (l == r) {
		if ((l & 1) == parity) {
			return mat[parity][at];
		}
		return -1;
	}
	int mid = (l + r) / 2;
	int x = query(at * 2, l, mid, L, R, parity);
	int y = query(at * 2 + 1, mid + 1, r, L, R, parity);
	return f(x, y);
}

struct Tree {
	int left, mid, right;
	PII val;
	Tree() {
		left = mid = right = -1;
		val = { -1, -1 };
	}
};
Tree tree[200005];
bool operator<(Tree A, Tree B) {
	return A.val < B.val;
}

int cur = 0;

int solve(int l, int r) {
	int x = query(1, 1, n, l, r, l & 1);
	int y = query(1, 1, n, x, r, 1 ^ (l & 1));
	// l .. x ... y .. r
	int now = cur++;
	if (x != l) {
		tree[now].left = solve(l, x - 1);
	}
	if (y != x + 1) {
		tree[now].mid = solve(x + 1, y - 1);
	}
	if (y != r) {
		tree[now].right = solve(y + 1, r);
	}
	tree[now].val = PII(num[x], num[y]);
	return now;
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &num[i]);
	}

	build(1, 1, n);

	int root = solve(1, n);
	set<Tree> S;
	S.insert(tree[root]);
	VI ans;
	while (!S.empty()) {
		Tree u = *S.begin();
		S.erase(u);

		ans.push_back(u.val.first);
		ans.push_back(u.val.second);
		if (u.left != -1) S.insert(tree[u.left]);
		if (u.mid != -1) S.insert(tree[u.mid]);
		if (u.right != -1) S.insert(tree[u.right]);
	}

	for (int i = 0; i < SZ(ans); i++) {
		if (i) printf(" ");
		printf("%d", ans[i]);
	}
	printf("\n");
	return 0;
}

