const int N=200005,inf=1e9;
#define lc pos+pos
#define rc lc|1
int a[N],rev[N],seg[2][4*N],n;
void update(int low,int high,int pos,int ind,int val,int i)
{
  if(low==high)
    {
      seg[i][pos]=val;
      return;
    }
  int mid=(low+high)>>1;
  if(ind<=mid) update(low,mid,lc,ind,val,i);
  else update(mid+1,high,rc,ind,val,i);
  seg[i][pos]=min(seg[i][lc],seg[i][rc]);
}
int query(int low,int high,int pos,int l,int r,int i)
{
  if(low>r || high<l) return inf;
  if(low>=l && high<=r) return seg[i][pos];
  int mid=(low+high)>>1;
  return min(query(low,mid,lc,l,r,i),query(mid+1,high,rc,l,r,i));
}
vector<ii> fun(int low,int high)
{
  if(low>high)
    return vector<ii>();
  if(high-low==1)
    {
      vector<ii> tmp;
      tmp.pb(mp(a[low],a[high]));
      return tmp;
    }
  int mn1=query(1,n,1,low,high,(low+1)&1),mn2=query(1,n,1,low,high,(high+1)&1);
  int ind1=rev[mn1],ind2=rev[mn2];
  vector<ii> ans,l,r;
  if(a[low]<=mn2)
    {
      int split=ind1;
      assert((split-low)&1==1);
      ans.pb(mp(a[low],mn1));
      l=fun(low+1,split-1),r=fun(split+1,high);
    }
  else
    {
      int split=ind2;
      assert((high-split)&1==1);
      ans.pb(mp(mn2,a[high]));
      l=fun(low,split-1),r=fun(split+1,high-1);
    }
  int i=0,j=0;
  while(i<sz(l) && j<sz(r))
    {
      if(l[i]<r[j]) ans.pb(l[i++]);
      else ans.pb(r[j++]);
    }
  while(i<sz(l)) ans.pb(l[i++]);
  while(j<sz(r)) ans.pb(r[j++]);
  return ans;
}
