  rep(j,0,2)
    rep(i,0,4*N) seg[j][i]=inf;
  rep(j,0,2)
    for(int i=1+j;i<=n;i+=2)
      update(1,n,1,i,a[i],1-j);
  vector<ii> ans=fun(1,n);
  set<int> check;
  for(auto it:ans)
    {
      cout<<it.fi<<" "<<it.se<<" ";
      check.insert(it.fi); check.insert(it.se);
    }
  assert(sz(check)==n);
  cout<<endl;
  return 0 ;
}

