//	cout<<"!!!"<<l<<' '<<r<<' '<<_l<<' '<<_ll<<' '<<_r<<' '<<_rr<<endl;
	for(;_l<=_ll&&_r<=_rr;)
	 if(B[_l]<B[_r]) C[f++]=B[_l++];
	 else C[f++]=B[_r++];
	for(;_l<=_ll;) C[f++]=B[_l++];
	for(;_r<=_rr;) C[f++]=B[_r++];
