const int MAX = 2e5 + 10 ;

int arr[MAX] , Min[MAX][20][2] , lg[MAX] , occ[MAX] ;
int n  ;

struct sparse_table
{
	void preprocess()
	{
		lg[1] = 0 ;
		for(int i = 2 ; i <= n ; ++i)
			lg[i] = lg[i/2] + 1 ;
		for(int i = 1 ; i <= n ; ++i)
		{
			if(i & 1)
				Min[i][0][1] = arr[i] , Min[i][0][0] = 1e9 ;
			else
				Min[i][0][0] = arr[i] , Min[i][0][1] = 1e9 ;
		}
		for(int j = 1 ; (1 << j) <= n ; ++j)
		{
			for(int i = 1 ; i + (1 << j) - 1 <= n ; ++i)
			{
				Min[i][j][0] = min(Min[i][j-1][0] , Min[i + (1 << (j - 1))][j-1][0]) ;
				Min[i][j][1] = min(Min[i][j-1][1] , Min[i + (1 << (j - 1))][j-1][1]) ;
			}
		}
	}

	int RminQ(int l , int r , bool t)
	{
		int j = lg[r-l+1] ;
		return min(Min[l][j][t] , Min[r - (1 << j) + 1][j][t]) ;
	}
};

int main()
{
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	cin>>n ;
	for(int i = 1 ; i <= n ; ++i)
	{
		cin>>arr[i] ;
		occ[arr[i]] = i ;
	}
	set< pair<int , int> >ranges ;
	ranges.insert({1 , n}) ;
	sparse_table tree ;
	tree.preprocess() ;
	set<int>Min ;
	Min.insert(tree.RminQ(1 , n , 1)) ;
	vector<int>ans ;
	while(Min.size())
	{
		int x = *Min.begin() ;
		int idx = occ[x] ;
		pair<int , int>p = *prev(ranges.lower_bound({idx+1 , -1})) ;
		int y = tree.RminQ(idx+1 , p.second , !(idx%2)) ;
		int idy = occ[y] ;
		ans.push_back(x) ;
		ans.push_back(y) ;
		Min.erase(x) ;
		ranges.erase(p) ;
		if(p.first < idx)
		{
			ranges.insert({p.first , idx-1}) ;
			Min.insert(tree.RminQ(p.first , idx-1 , p.first % 2)) ;
		}
		if(idx+1 < idy)
		{
			ranges.insert({idx+1 , idy-1}) ;
			Min.insert(tree.RminQ(idx+1 , idy-1 , (idx+1) % 2)) ;
		}
		if(idy+1 <= p.second)
		{
			ranges.insert({idy+1 , p.second}) ;
			Min.insert(tree.RminQ(idy+1 , p.second , (idy+1) % 2)) ;
		}
	}
	for(auto &i : ans)
		cout<<i<<" " ;
	cout<<"\n" ;
	return 0 ;
}

