			int mid=(l+r)>>1;
			if (Get(mid)-s) r=mid;
			else l=mid;
		}
		int y;
		if (Get(l)-s) y=Query(1,x+1,l-1);else if (Get(r)-s) y=Query(1,x+1,r-1);
		else y=Query(1,x+1,r);
		printf("%d %d ",a[x],a[y]);
		if (x<y-1) Modify(1,x+1,y-1);
		Change(1,x);
