#define ls(x) (x << 1)
#define rs(x) ((x << 1) | 1)
	const int M = 2e5 + 20;
	int id[2][M << 2];

	inline void update(int x){
		rep(t,0,1){
			if ( a[id[t][ls(x)]] > a[id[t][rs(x)]] ) id[t][x] = id[t][rs(x)];
			else id[t][x] = id[t][ls(x)];
		}
	}
	void build(int x,int l,int r){
		if ( l == r ){
			id[l & 1][x] = l;
			return;
		}
		int mid = (l + r) >> 1;
		build(ls(x),l,mid) , build(rs(x),mid + 1,r);
		update(x);
	}
	int query(int x,int l,int r,int L,int R,int t){
		if ( L > R ) return 0;
		if ( L <= l && R >= r ) return id[t][x];
		int mid = (l + r) >> 1; int lres = 0,rres = 0;
		if ( L <= mid ) lres = query(ls(x),l,mid,L,R,t);
		if ( R > mid ) rres = query(rs(x),mid + 1,r,L,R,t);
		if ( a[lres] < a[rres] ) return lres;
		return rres;
	}
}
