    }
    void init(int n_) { n = 1; while (n < n_) n *= 2; dat.assign(n * 2, I); }
    template<class T_ = T, class SA = enable_if_t<is_same<remove_reference_t<T_>, T>::value>>
    void update(int k, T_&& v) { dat[k += n] = v; while (k /= 2) dat[k] = op(dat[k * 2], dat[k * 2 + 1]); }
    T query(int a, int b) const {
        T vl = I, vr = I;
        for (int l = a + n, r = b + n; l < r; l /= 2, r /= 2) { if (l & 1) vl = op(vl, dat[l++]); if (r & 1) vr = op(dat[--r], vr); }
        return op(vl, vr);
    }
    template<class C> int find(int a, int b, C&& check) const { return find(a, b, check, 1, 0, n); }
private:
    template<class C> int find(int a, int b, C&& check, int k, int l, int r) const {
        if (!check(dat[k]) || r <= a || b <= l) return -1; else if (k >= n) return k - n;
        int m = (l + r) / 2; int vl = find(a, b, check, k * 2, l, m); if (~vl) return vl;
        else return find(a, b, check, k * 2 + 1, m, r);
    }
};

