using ST = SegmentTree<int, min_of<int>, identity>;

int main() {
    int N;
    cin >> N;
    vector<int> P(N);
    rep(i, N) cin >> P[i], P[i]--;

    vector<int> idx(N);
    rep(i, N) idx[P[i]] = i;

    ST st[2];
    {
        vector<int> v;
        v.assign(N, identity);
        rep(i, N / 2) v[2 * i] = P[2 * i];
        st[0].build(v);
        v.assign(N, identity);
        rep(i, N / 2) v[2 * i + 1] = P[2 * i + 1];
        st[1].build(v);
    }

    vector<pair<int, int>> ranges(N);
    priority_queue<int, vector<int>, greater<int>> pq;
    {
        auto p_begin = st[0].dat[1];
        ranges[p_begin] = { 0, N };
        pq.push(p_begin);
    }

    vector<int> Q(N);
    rep(i, N / 2) {
        int p = pq.top();
        int o = idx[p] % 2;
        int q = st[1 - o].query(idx[p] + 1, ranges[p].second);
        pq.pop();
        Q[2 * i] = p + 1;
        Q[2 * i + 1] = q + 1;

        if (idx[p] != ranges[p].first) {
            int r = st[o].query(ranges[p].first, idx[p]);
            ranges[r] = { ranges[p].first, idx[p] };
            pq.push(r);
        }
        if (idx[p] + 1 != idx[q]) {
            int r = st[1 - o].query(idx[p] + 1, idx[q]);
            ranges[r] = { idx[p] + 1, idx[q] };
            pq.push(r);
        }
        if (idx[q] + 1 != ranges[p].second) {
            int r = st[o].query(idx[q] + 1, ranges[p].second);
            ranges[r] = { idx[q] + 1, ranges[p].second };
            pq.push(r);
        }
    }

    rep(i, N) cout << Q[i] << (!--N ? "\n" : " ");
}

