void build(int id,int l,int r)
{
	if (l==r)
	{
		mi[id][l&1]=num[l];
		mi[id][(l&1)^1]=n+1;
		return;
	}
	build(id*2,l,(l+r)/2);
	build(id*2+1,(l+r)/2+1,r);
	mi[id][0]=min(mi[id*2][0],mi[id*2+1][0]);
	mi[id][1]=min(mi[id*2][1],mi[id*2+1][1]);
}
int query(int id,int l,int r,int ql,int qr,int t)
{
	if (ql<=l&&r<=qr) return mi[id][t];
	int ans=n+1;
	if (ql<=(l+r)/2) ans=min(ans,query(id*2,l,(l+r)/2,ql,qr,t));
	if (qr>(l+r)/2) ans=min(ans,query(id*2+1,(l+r)/2+1,r,ql,qr,t));
	return ans;
}
