const int MAX_N = 1 << 20;

//葉の数
int N;
//扱うデータ型をllとしている.適宜修正.
//ki, gu
ll dat[2][2 * MAX_N - 1];

void init(int n_){
  //簡単のため, 要素数を2のべき乗に
  N = 1;
  while(N < n_) N *= 2;

  //初期化処理をここに書く
  rep(i,2 * N - 1){
    rep(j,2){
      dat[j][i] = LINF;
    }

  }
}

//k番目の値について, 処理を行う
//例として, aに変更している
void update(int k, int a){
  int guki = k%2;
  //葉のノード番号
  k += N-1;

  //葉の更新処理をここに書く.
  dat[guki][k] = a;

  //登りながら更新.
  while(k > 0){
    k = (k-1) / 2;
    //中間ノードの更新処理をここに書く.
    dat[guki][k] = min(dat[guki][k * 2 + 1], dat[guki][k * 2 + 2]);
  }

  return;
}

//[a,b)における評価値を得る. ここでは最小値としている.
//nowが現在の接点番号, nowは[l, r)に対応している.
//呼ぶ時は query(a,b,0,0,N)
ll query(int a, int b, int now, int l, int r, int guki){
  //[a,b)と[l,r)が交差しなければ, 無を返す.
  //評価値が最小値ならばINT_MAX. 修正すること.
  if(r <= a || b <= l) return LINF;

  // [a, b)が[l, r)を完全に含んでいれば, このノードの値
  if(a <= l && r <= b){
    return dat[guki][now];
  }else{
    //そうでなければ, 2つの個の複合値
    //ここでは, 2つの子の最小値. 修正すること.
    ll vl = query(a, b, now*2+1, l, (l+r)/2, guki);
    ll vr = query(a, b, now*2+2, (l+r)/2, r, guki);
    return min(vl, vr);
  }
}
vector<int> p2i;

vector<pair<int, int>> saiki(int l, int r){
  vector<pair<int, int>> ret;
  if(r-l <= 0) return ret;
  int min_l = query(l, r, 0, 0, N, l%2);
  int li = p2i[min_l];
  int min_r = query(li+1, r, 0, 0, N, (li+1)%2);
  int ri = p2i[min_r];
  ret.push_back({min_l, min_r});
  //cerr<<"mun"<<l<<" "<<r<<endl;
  vector<pair<int, int>> r1 = saiki(l,li);
  vector<pair<int, int>> r2 = saiki(li+1,ri);
  vector<pair<int, int>> r3 = saiki(ri+1,r);
  r1.push_back({INF,INF});
  r2.push_back({INF,INF});
  r3.push_back({INF,INF});
  int i1=0,i2=0,i3=0;
  while(i1<r1.size()-1 || i2<r2.size()-1 || i3<r3.size()-1){
    ret.push_back(min({r1[i1],r2[i2],r3[i3]}));
    if(min({r1[i1],r2[i2],r3[i3]}) == r1[i1]){
      i1++;
    }else if(min({r1[i1],r2[i2],r3[i3]}) == r2[i2]){
      i2++;
    }else{
      i3++;
    }
  }
  return ret;
}

