vi a;
struct D {
  int tot, s;
  vi d;
  seg t;
  D(vi& d) : tot(sz(d)), s(0), d(d), t(sz(d)) {
    rep(i,sz(d)) {
      F x(P(INF,d[i]),P(INF,d[i]),1);
      x.d[!(i&1)].fi = a[d[i]];
      t[i] = x;
    }
    t.init();
  }
  int f(int i) { return lower_bound(rng(d),i)-d.begin();}
  int cnt(int l, int r) {
    l = f(l); r = f(r);
    return t.get(l,r).c;
  }
  void del(int i) {
    i = f(i);
    t.set(i,F());
    --tot;
  }
  int get(int l) {
    l = f(l);
    return t.get(l,sz(d)).d[s].se;
  }
  P get() {
    return t.get(0,sz(d)).d[s^1];
  }
};


int main() {
