  ds.pb(D(b));
  PQ(P) q;
  q.push(ds[0].get());

  while (sz(q)) {
    P np = q.top(); q.pop();
    // cerr<<np<<endl;
    int l = np.se;
    // if (di[l] == -1) continue;
    int j = di[l];
    int r = ds[j].get(l);
    ans.pb(a[l]); ans.pb(a[r]);
    ds[j].del(l); ds[j].del(r);
    di[l] = di[r] = -1;

    vi b;
    if (ds[j].cnt(l,r)*2 < ds[j].tot) {
      for (int i = g.f[l]; i != r; i = g.f[i]) {
        b.pb(i);
      }
    } else {
      for (int i = g.p[l]; i != -1; i = g.p[i]) {
        b.pb(i);
      }
      for (int i = g.f[r]; i != -1; i = g.f[i]) {
