    sort(rng(b));
    for (int i : b) {
      ds[j].del(i);
      di[i] = sz(ds);
    }
    if (sz(b)) {
      ds.pb(D(b));
      q.push(ds.back().get());
    }
    if (ds[j].tot) q.push(ds[j].get());
    // rep(k,sz(ds)) cerr<<k<<" "<<ds[k].tot<<endl;

