#include<functional>
#include<vector>
template<typename T> class SparseTable {
 public:
  explicit SparseTable(const std::vector<T>& v, const std::function<bool(T, T)>& F = std::less<T>()) : V(v), F(F), table_(v.size()) {
    for(auto i = 0; i < v.size(); ++i) table_[0].emplace_back(i);
    for(auto i = 1; pow2(i) <= v.size(); ++i) {
      for(auto j = 0; j + pow2(i) - 1 < v.size(); ++j) {
        auto a = table_[i - 1][j + pow2(i - 1)];
        auto b = table_[i - 1][j];
        table_[i].emplace_back(F(v[a], v[b]) ? a : b);
      }
    }
  }
  T index(int l, int r) const {
    auto d = leftmost(r - l + 1);
    auto a = table_[d][r - pow2(d) + 1];
    auto b = table_[d][l];
    return F(V[a], V[b]) ? a : b;
  }
  T find(int l, int r) const {
    return V[index(l, r)];
  }
 private:
  inline int pow2(int n) const {return 1 << n;}
  inline int leftmost(int n) const {return std::__lg(n);}
  const std::vector<T> V;
  const std::function<bool(T, T)> F;
  std::vector<std::vector<int>> table_;
};

#include<bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Node {
  pair<int, int> v;
  vector<int> child;
};

int main() {
  int N;
  cin >> N;
  vector<int> P(N);
  for(auto& p: P) cin >> p;

  vector<int> E(N, INF), O(N, INF);
  for(auto i=0; i<N; i+=2) {
    E[i] = P[i];
    O[i+1] = P[i+1];
  }
  SparseTable<int> even(E), odd(O);

  vector<Node> node;
  function<int(int, int)> dfs = [&](auto l, auto r){
    if(r<=l) return -1;
    int i, j;
    if(l&1) {
      i = odd.index(l, r);
      j = even.index(i+1, r);
    } else {
      i = even.index(l, r);
      j = odd.index(i+1, r);
    }
    Node n;
    n.v = {P[i], P[j]};
    for(auto k: {dfs(l, i-1), dfs(i+1, j-1), dfs(j+1, r)}) n.child.emplace_back(k);
    node.emplace_back(n);
    return int(node.size() - 1);
  };

  auto first = true;
  auto root = dfs(0, N-1);
  priority_queue<int, vector<int>, function<bool(int, int)>> q([&](auto l, auto r) {return node[l].v > node[r].v;});
  q.emplace(root);
  while(!q.empty()) {
    auto i = q.top();
    q.pop();
    cout << (first ? "" : " ") << node[i].v.first << " " << node[i].v.second;
    for(auto j: node[i].child) if(j!=-1) q.emplace(j);
    first = false;
  }
  cout << endl;
}

