void update(vector<int> &T, int node, int lf, int rt, int poz, int val) {
    if(lf == rt) {
        T[node] = min(T[node], val);
        return;
    }

    int mid = (lf + rt) / 2;

    if(poz <= mid)
        update(T, 2 * node, lf, mid, poz, val);
    else
        update(T, 2 * node + 1, mid + 1, rt, poz, val);

    T[node] = min(T[2 * node], T[2 * node + 1]);
}

int query(vector<int> &T, int node, int lf, int rt, int st, int dr) {
    if(lf >= st and rt <= dr) {
        return T[node];
    }

    int mid = (lf + rt) / 2;
    int ans = 1e8;

    if(st <= mid)
        ans = min(ans, query(T, 2 * node, lf, mid, st, dr));
    if(dr > mid)
        ans = min(ans, query(T, 2 * node + 1, mid + 1, rt, st, dr));

    return ans;
}

