N pull(N l , N r){
	N ans;
	ans.sml[0] = min(l.sml[0] , r.sml[0]);
	ans.sml[1] = min(l.sml[1] , r.sml[1]);

	ans.val[0] = min(l.val[0] , r.val[0]);
	ans.val[0] = min(ans.val[0] , mp(l.sml[0] , r.sml[1]));

	ans.val[1] = min(l.val[1] , r.val[1]);
	ans.val[1] = min(ans.val[1] , mp(l.sml[1] , r.sml[0]));
	return ans;
}
void build(int now , int l , int r){
	if(l == r){
		st[now].val[0] = st[now].val[1] = mp(INF , INF);
		if(l % 2 == 0) st[now].sml[0] = x[l] , st[now].sml[1] = INF;
		if(l % 2 == 1) st[now].sml[0] = INF , st[now].sml[1] = x[l];
	}
	else {
		build(ls , l , mid + 0);
		build(rs , mid + 1 , r);
		st[now] = pull(st[ls] , st[rs]);
	}
}
N query(int now , int l , int r , int ql , int qr){
	if(ql <= l && r <= qr) return st[now];
	else if(qr <= mid + 0) return query(ls , l , mid + 0 , ql , qr);
	else if(mid + 1 <= ql) return query(rs , mid + 1 , r , ql , qr);
	return pull(query(ls , l , mid + 0 , ql , qr) , query(rs , mid + 1 , r , ql , qr));
}
