		std::queue<range> next;
		while (not que.empty()) {
			auto [l, r] = que.front(); que.pop();
			if (r - l < 2) continue;
			usize i = ((l & 1) ? st2.fold(l, r) : st1.fold(l, r));
			usize j = ((l & 1) ? st1.fold(i, r) : st2.fold(i, r));
			heap.emplace(a[i], a[j]);
			next.emplace(l, i);
			next.emplace(i + 1, j);
			next.emplace(j + 1, r);

		}
		std::swap(que, next);
		auto p = heap.top(); heap.pop();
		ans.push_back(p.first);
		ans.push_back(p.second);
	}

	for (usize i = 0; i < n; i++) {
		std::cout << ans[i] << " \n"[i + 1 == n];
	}

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n;
const int N = 300000;
int P[N], Q[N];
int X[20][N];
int ask(int l, int r)
{
    int d = log2(r - l + 1);
    return (Q[X[d][l]] < Q[X[d][r - (1 << d) + 1]]? X[d][l]: X[d][r - (1 << d) + 1]);
}
int task(int l, int r)
{
    if (l & 1) return ask(l / 2 + 1, (r + 1) / 2) * 2 - 1;
    else return (ask(l / 2 + n / 2, r / 2 + n / 2) - n / 2) * 2;
}
vector <int> ans;
struct node
{
    int l, r, w;
};
int operator < (node a, node b) {return a.w > b.w;}
priority_queue <node> H;
int main()
{
    cin >> n;
    for (int i = 1; i <= n; ++ i) cin >> P[i];
    for (int i = 1; i <= n / 2; ++ i)
        Q[i] = P[i * 2 - 1], Q[i + n / 2] = P[i * 2];
    for (int i = 1; i <= n; ++ i) X[0][i] = i;
    for (int i = 1; i < 20; ++ i)
        for (int j = 1; j <= n; ++ j)
            X[i][j] = (Q[X[i - 1][j]] < Q[X[i - 1][j + (1 << (i - 1))]]? X[i - 1][j]: X[i - 1][j + (1 << (i - 1))]);

    H.push((node){1, n, P[task(1, n)]});
    while (!H.empty())
    {
        node t = H.top(); H.pop();
        int l = task(t.l, t.r), r = task(l + 1, t.r);
        ans.push_back(P[l]); ans.push_back(P[r]);
        if (t.l <= l - 1) H.push((node){t.l, l - 1, P[task(t.l, l - 1)]});
        if (l + 1 <= r - 1) H.push((node){l + 1, r - 1, P[task(l + 1, r - 1)]});
        if (r + 1 <= t.r) H.push((node){r + 1, t.r, P[task(r + 1, t.r)]});
    }
    for (int i = 0; i < ans.size(); ++ i) cout << ans[i] << ' ';
}

