const int MAXN = 2e5 + 5;
const int INF = 1e9;
const int LOG = 20;

int a[MAXN];

pii tt1[MAXN * 4];
pii tt2[MAXN * 4];

pii st1[LOG][MAXN];
pii st2[LOG][MAXN];
int cnt;
int numlog[MAXN];


void build_sparse(int n){
    numlog[1] = 0;
    for(int i = 2; i < MAXN; i++){
        numlog[i] = numlog[i / 2] + 1;
    }

    for (int i = 0; i <= numlog[n]; i++) {
        int curlen = 1 << i;
        for (int j = 0; j < n; j++) {
            st1[i][j] = mp(INF, INF);
            st2[i][j] = mp(INF, INF);
        }
        for (int j = 0; j < n; j++) {
            if (i == 0) {
                 if(j & 1){
                    st1[i][j] = mp(a[j], j);
                }
                else{
                   st2[i][j] = mp(a[j], j);
                }


                continue;
            }
            st1[i][j] = min(st1[i - 1][j], st1[i - 1][j + curlen / 2]);
            st2[i][j] = min(st2[i - 1][j], st2[i - 1][j + curlen / 2]);
        }
    }
}

void build(int n){
    for(int i = n - 2; i >= 0; i--){
        tt1[i] = min(tt1[2 * i + 1], tt1[2 * i + 2]);
        tt2[i] = min(tt2[2 * i + 1], tt2[2 * i + 2]);
    }
}

pii get_min(int id, int v, int tl, int tr, int l, int r){
    if(l > r) return mp(INF, -1);
    if(tl == l && tr == r){
        if(id) return tt2[v];
        return tt1[v];
    }
    int tm = (tl + tr) >> 1;
    return min(get_min(id, 2 * v + 1, tl, tm, l, min(r, tm)),
               get_min(id, 2 * v + 2, tm + 1, tr, max(l, tm + 1), r));
}


pii _min(pii a, pii b){
    int mn = min(a.first, a.second);
    int mn2 = min(b.first, b.second);
    if(mn < mn2) return a;
    return b;
}

pii get_min2(int id, int l, int r){
    int curlog = numlog[r - l + 1];
    pii ans;
    if(id){
       ans = min(st2[curlog][l], st2[curlog][r - (1 << curlog) + 1]);
    }
    else{
        ans = min(st1[curlog][l], st1[curlog][r - (1 << curlog) + 1]);
    }
    return ans;
}

vi rec_sol(int l, int r){
    if(l > r){
        vi ans;
        return ans;
    }
    if(l + 1 == r){
        vi ans;
        ans.pb(a[l]);
        ans.pb(a[r]);
        return ans;
    }
    if(l + 3 == r){
        pii p1 = mp(a[l], a[l + 1]);
        pii p2 = mp(a[l + 2], a[l + 3]);
        pii p3 = mp(a[l], a[l + 3]);
        pii p4 = mp(a[l + 1], a[l + 2]);
        pii mn = _min(_min(p1, p2), _min(p3, p4));
        vi ans;
        if(mn == p1){
            ans.pb(a[l]);
            ans.pb(a[l + 1]);
            ans.pb(a[l + 2]);
            ans.pb(a[l + 3]);
        }
        else if(mn == p2){
            ans.pb(a[l + 2]);
            ans.pb(a[l + 3]);
            ans.pb(a[l]);
            ans.pb(a[l + 1]);
        }
        else if(mn == p3){
            ans.pb(a[l]);
            ans.pb(a[l + 3]);
            ans.pb(a[l + 1]);
            ans.pb(a[l + 2]);
        }
        else{
            ans.pb(a[l + 1]);
            ans.pb(a[l + 2]);
            ans.pb(a[l]);
            ans.pb(a[l + 3]);
        }
        return ans;
    }

    int mn_id, mn_id2;
    //pii mn1 = get_min(0, 0, cnt - 1, 2 * cnt - 2, cnt - 1 + l, cnt - 1 + r);
    //pii mn2 = get_min(1, 0, cnt - 1, 2 * cnt - 2, cnt - 1 + l, cnt - 1 + r);

    pii mn1 = get_min2(0, l, r);
    pii mn2 = get_min2(1, l, r);
    pii mn = min(mn1, mn2);
    mn_id = mn.second;
    if(mn_id + 3 <= r){
        int odd = (mn_id + 3) & 1;
        //mn2 = get_min(1 - odd, 0, cnt - 1, 2 * cnt - 2, cnt - 1 + mn_id + 3, cnt - 1 + r);
        mn2 = get_min2(1 - odd, mn_id + 3, r);
    }
    else{
        int odd = (mn_id - 3) & 1;
        //mn2 = get_min(1 - odd, 0, cnt - 1, 2 * cnt - 2, cnt - 1 + l, cnt - 1 + mn_id - 3);
        mn2 = get_min2(1 - odd, l, mn_id - 3);
    }
    mn_id2 = mn2.second;

    int l2 = min(mn_id, mn_id2);
    int r2 = max(mn_id, mn_id2);
    vi ans;
    ans.pb(a[l2]);
    ans.pb(a[r2]);

    vi ans2 = rec_sol(l, l2 - 1);
    vi ans3 = rec_sol(l2 + 1, r2 - 1);
    vi ans4 = rec_sol(r2 + 1, r);
    int sz2 = ans2.size();
    int sz3 = ans3.size();
    int sz4 = ans4.size();
    int c2 = 0, c3 = 0, c4 = 0;
    while(c2 < sz2 || c3 < sz3 || c4 < sz4){
        pii p2 = c2 < sz2 ? mp(ans2[c2], ans2[c2 + 1]) : mp(INF, INF);
        pii p3 = c3 < sz3 ? mp(ans3[c3], ans3[c3 + 1]) : mp(INF, INF);
        pii p4 = c4 < sz4 ? mp(ans4[c4], ans4[c4 + 1]) : mp(INF, INF);
        pii mn = _min(p2, _min(p3, p4));
        if(mn == p2){
            c2 += 2;
        }
        else if(mn == p3){
            c3 += 2;
        }
        else{
            c4 += 2;
        }
        ans.pb(mn.first);
        ans.pb(mn.second);
    }
    return ans;
}

void solve(){
