struct node {
    P e;
    vector<int> c;
} q[maxn * 4];

void updata(int &x,int y) {
    if(a[x] > a[y]) x = y;
}

void add(int f[],int t,int l,int r,int x) {
    if(l == r) {
        f[t] = x;
        return;
    }
    int mid = (l + r) >> 1;
    if(x <= mid) add(f,t << 1,l,mid,x);
    else add(f,t << 1 | 1,mid + 1,r,x);
    updata(f[t],f[t << 1]);
    updata(f[t],f[t << 1 | 1]);
}

int ff(int f[],int t,int l,int r,int ll,int rr) {
    if(ll <= l && r <= rr) return f[t];
    int mid = (l + r) >> 1;
    int k = 0;
    if(ll <= mid) updata(k,ff(f,t << 1,l,mid,ll,rr));
    if(rr > mid) updata(k,ff(f,t << 1 | 1,mid + 1,r,ll,rr));
    return k;
}

void solve(int t,int l,int r) {
    int u,v;
    if(l & 1) u = 1,v = 0;
    else u = 0,v = 1;
    int x = ff(g[u],1,1,n,l,r);
    int y = ff(g[v],1,1,n,x + 1,r);
    q[t].e = P(a[x],a[y]);
    if(l < x) {
        q[t].c.push_back(++tot);
        solve(tot,l,x - 1);
    }
    if(x + 1 < y) {
        q[t].c.push_back(++tot);
        solve(tot,x + 1,y - 1);
    }
    if(y < r) {
        q[t].c.push_back(++tot);
        solve(tot,y + 1,r);
    }
}

