const int MAX_N = (1 << 21) - 1;
const int inf = numeric_limits<int>::max();

int n;
P etree[MAX_N];
P otree[MAX_N];
vector< P > v;

void init(int k,int l,int r){
  if(r - l == 1){
    etree[k] = P(inf,-1);
    otree[k] = P(inf,-1);
  }else{
    int chl = k*2+1;
    int chr = k*2+2;
    etree[k] = P(inf,-1);
    otree[k] = P(inf,-1);
    init(chl, l, (l+r)/2);
    init(chr, (l+r)/2, r);
  }
}

void update(int t,int i,int x,int k,int l, int r){
  if(l <= i && i < r){
    if(r - l == 1){
      if(t == 0)
        etree[k] = P(x,2*l);
      else
        otree[k] = P(x,2*l+1);
    }else{
      int chl = k*2+1;
      int chr = k*2+2;
      update(t,i,x,chl,l,(l+r)/2);
      update(t,i,x,chr,(l+r)/2,r);
      if(t == 0)
        etree[k] = min(etree[chl],etree[chr]);
      else
        otree[k] = min(otree[chl],otree[chr]);
    }
  }
}

P find(int t,int a,int b,int k,int l,int r){
  if(r <= a || b <= l)return P(inf,-1);
  else if(a <= l && r <= b)
    return t == 0 ? etree[k] : otree[k];
  else{
    int chl = k*2+1;
    int chr = k*2+2;
    P vl = find(t,a,b,chl,l,(l+r)/2);
    P vr = find(t,a,b,chr,(l+r)/2,r);
    return min(vl,vr);
  }
}

