void init(int n_){
	n = 1;
	while(n<n_) n *= 2;
	for(int i=0;i<2*n-1;i++){
		dat1[i] = make_pair(100000000,i);
		dat2[i] = make_pair(100000000,i);
	}
}

void update1(int k,int a){
	k += n-1;
	dat1[k] = make_pair(a,k-n+1);
	while(k>0){
		k = (k-1)/2;
		dat1[k] = min(dat1[k*2+1],dat1[k*2+2]);
	}
}


void update2(int k,int a){
	k += n-1;
	dat2[k] = make_pair(a,k-n+1);
	while(k>0){
		k = (k-1)/2;
		dat2[k] = min(dat2[k*2+1],dat2[k*2+2]);
	}
}

pair<int,int> query1(int a,int b,int k,int l,int r){
	if(r <= a || b<= l)return make_pair(10000000,-1);
	if(a <= l && r <= b) return dat1[k];
	else{
		pair<int,int> vl = query1(a,b,k*2+1,l,(l+r)/2);
		pair<int,int> vr = query1(a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

pair<int,int> query2(int a,int b,int k,int l,int r){
	if(r <= a || b<= l)return make_pair(10000000,-1);
	if(a <= l && r <= b) return dat2[k];
	else{
		pair<int,int> vl = query2(a,b,k*2+1,l,(l+r)/2);
		pair<int,int> vr = query2(a,b,k*2+2,(l+r)/2,r);
		return min(vl,vr);
	}
}

void add(int a,int b){
	if(a>=b)return;
	if(a%2==0){
		pq.push(make_pair(query1(a/2,b/2+1,0,0,n).first,make_pair(a,b)));		
	}else{
		pq.push(make_pair(query2(a/2+1,b/2+1,0,0,n).first,make_pair(a,b)));			
	}

	return;
}


