using namespace std;
typedef long long LL;
const int N = 400500;
const int mod = 1e9 + 7;
int p[N], n, tr[N << 2][2];
void build(int o, int L, int R) {
	if (L + 1 == R) {
		tr[o][L & 1] = L;
		tr[o][R & 1] = n;
		return;
	}
	build(ls, L, mid);
	build(rs, mid, R);
	tr[o][0] = p[tr[ls][0]] < p[tr[rs][0]] ? tr[ls][0] : tr[rs][0];
	tr[o][1] = p[tr[ls][1]] < p[tr[rs][1]] ? tr[ls][1] : tr[rs][1];
}
pair<int, int> Q(int o, int L, int R, int l, int r) {
	if (l <= L && R <= r) {
		return make_pair(tr[o][0], tr[o][1]);
	}
	if (l >= mid)
		return Q(rs, mid, R, l, r);
	else if (r <= mid)
		return Q(ls, L, mid, l, r);

	auto t1 = Q(ls, L, mid, l, r);
	auto t2 = Q(rs, mid, R, l, r);
	return make_pair(p[t1.first] < p[t2.first] ? t1.first : t2.first,
	                 p[t1.second] < p[t2.second] ? t1.second : t2.second);
}
