  P p,q;
  if(l%2==0){
    p=seg1.query(l,r);
    q=seg2.query(p.se,r);
  }
  else{
    p=seg2.query(l,r);
    q=seg1.query(p.se,r);
  }
  ll idx=rets.size();
  g[index].push_back(idx);
  rets.emplace_back(p.fi,q.fi); 
