using namespace std;

class RangeMinQuery {
private:
	int bottomSt, bottomEd;
	vector<int> a;
	vector<int> rs, re;
	vector<int> cand;
	int set(int n) {
		int left = 2 * n + 1;
		int right = 2 * n + 2;
		if (left <= a.size() - 1) {
			a[n] = min(set(left), set(right));
			rs[n] = rs[left];
			re[n] = re[right];
		}
		return a[n];
	}
	void search(int s, int t, int n) {
		if (s <= rs[n] && re[n] <= t) {
			cand.push_back(a[n]);
			return;
		}
		int left = 2 * n + 1;
		int right = 2 * n + 2;
		if (s <= re[left]) search(s, t, left);
		if (rs[right] <= t) search(s, t, right);
	}
public:
	RangeMinQuery() {}
	RangeMinQuery(vector<int> &v) {
		bottomEd = 0;
		for (int i = 1, plus = 1; plus < v.size(); i++) {
			plus *= 2;
			bottomEd += plus;
		}
		a.resize(bottomEd + 1);
		rs.resize(bottomEd + 1);
		re.resize(bottomEd + 1);

		bottomSt = bottomEd / 2;

		for (int i = bottomSt; i <= bottomEd; i++) {
			int j = i - bottomEd / 2;
			a[i] = j < v.size() ? v[j] : LLONG_MAX;
			rs[i] = j;
			re[i] = j;
		}

		set(0);
	}

	void update(int index, int x) {
		int pt = bottomSt + index;
		a[pt] = x;
		while (pt > 0) {
			pt = (pt - 1) / 2;
			a[pt] = min(a[2 * pt + 1], a[2 * pt + 2]);
		}
	}

	int find(int s, int t) {
		cand.clear();
		search(s, t, 0);
		int ret = cand[0];
		for (int i = 1; i < cand.size(); i++) {
			ret = min(ret, cand[i]);
		}
		return ret;
	}
};

const int INF = 99999999;
RangeMinQuery rmqOdd, rmqEven;
map<int, int> m;
set<int> pres, mpres;

signed main() {
	int N;
	cin >> N;

	pres.insert(-1);
	pres.insert(N);
	mpres.insert(1);
	mpres.insert(-N);

	vector<int> p(N);
	rep(i, N) {
		cin >> p[i];
		m[p[i]] = i;
	}

	vector<int> pOdd = p, pEven = p;
	rep(i, N) {
		if (i % 2) pEven[i] = INF;
		else pOdd[i] = INF;
	}

	rmqOdd = RangeMinQuery(pOdd);
	rmqEven = RangeMinQuery(pEven);

	vector<int> q;
	REP(i, 1, N) {
		if (p[m[i]] == INF) continue;
		int pt = m[i];

		int backLimit = -*(upper_bound(all(mpres), -pt)) + 1;

		if ((pt - backLimit) % 2 == 0) {
			RangeMinQuery &rmq = pt % 2 ? rmqEven : rmqOdd;

			int limit = *(upper_bound(all(pres), pt)) - 1;
			int minVal = rmq.find(pt + 1, limit);

			q.push_back(i);
			q.push_back(minVal);

			int pt2 = m[minVal];
			rmq.update(pt2, INF);
			p[pt2] = INF;
			pres.insert(pt);
			pres.insert(pt2);
			mpres.insert(-pt);
			mpres.insert(-pt2);
		} else {
			RangeMinQuery &rmq = pt % 2 ? rmqEven : rmqOdd;

			int limit = -*(upper_bound(all(mpres), -pt)) + 1;
			int minVal = rmq.find(limit, pt - 1);

			q.push_back(minVal);
			q.push_back(i);

			int pt2 = m[minVal];
			rmq.update(pt2, INF);
			p[pt2] = INF;
			pres.insert(pt);
			pres.insert(pt2);
			mpres.insert(-pt);
			mpres.insert(-pt2);
		}
	}

	rep(i, N - 1) cout << q[i] << ' ';
	cout << q[N - 1] << endl;

	return 0;
}

