void erase_pair(int u, int v) {
	del_pair(u, v);
	if (s.size() == 0) return;

	int i1 = p[u], i2 = p[v];
	if (i1 > i2) swap(i1, i2);

	int l = get_left(i1);
	int r = get_right(i2);

	used[i1] = 1;
	used[i2] = 1;
	merge(i1, i2);
	if (i1 && used[i1 - 1])
		merge(i1, i1 - 1);
	if (i2 != n - 1 && used[i2+1])
		merge(i2, i2 + 1);

