		del_pair(a[i2], a[r]);
	if (l != -1 && r != n) {
		pair<int, int> g;
		g = mp(a[l], a[r]);
		if (g.fs > g.sc) swap(g.fs, g.sc);
		s.insert(g);
	}
}

