//[a,b)のmin 節点k[l,r)について調べる
tree find(int u,int a,int b,int k=0,int l=0,int r=n){
	if(r<=a || b<=l){
		return (tree){INF,INF};
	}else if(a<=l && r<=b){
		return dat[u][k];
	}else{
		tree t1 = find(u,a,b,2*k+1,l,(l+r)/2);
		tree t2 = find(u,a,b,2*k+2,(l+r)/2,r);
		return min(t1,t2,comp);
	}
}

