struct segtree {
    segtree(int sz) : data(4 * sz) {}

    void add(int v, int tl, int tr, int pos, pair<int, int> val) {
        if (tl == tr - 1) {
            data[v] = val;
            return;
        }
        int tm = (tl + tr) >> 1;
        if (tm > pos) {
            add(v << 1, tl, tm, pos, val);
        } else {
            add(v << 1 | 1, tm, tr, pos, val);
        }
        data[v] = min(data[v << 1], data[v << 1 | 1]);
    }

    pair<int, int> get_mn(int v, int tl, int tr, int l, int r) {
        if (tl >= r || l >= tr) {
            return {1e9, -1};
        }
        if (tl >= l && tr <= r) {
            return data[v];
        }
        int tm = (tl + tr) >> 1;
        return min(get_mn(v << 1, tl, tm, l, r),
                   get_mn(v << 1 | 1, tm, tr, l, r));
    }

    vector<pair<int, int>> data;
};

pair<int, int> calc_idx(int pos) {
    int x = pos % 2;
    if (x) {
        return {x, pos / 2};
    } else {
        return {x, (pos - 1) / 2};
    }
}

int close_parity(int pos, int b) {
    if (pos % 2 == b) {
        return pos;
    }
    return pos + 1;
}


