struct SegTree{
  //SegTree
  vector<P> dat;
  int N;
  explicit SegTree(int n){
    N=1; while(N<n) N*=2;
    dat.resize(2*N);
    rep(i,2*N-1)  dat[i]=P(INF,-1);
  }
  void init(const vector<int> &v){
    rep(i,v.size()) dat[N-1+i]=P(v[i],i);
    for(int i=N-2;i>=0;i--) dat[i]=min(dat[2*i+1],dat[2*i+2]);
  }
  void update(int i,int x){
    i+=N-1;
    dat[i]=P(x,i-N+1);
    while(i>0){
      i=(i-1)/2;
      dat[i]=min(dat[2*i+1],dat[2*i+2]);
    }
    return;
  }
  P rmq(int a,int b){
    return rmq(a,b,0,0,N);
  }
  P rmq(int a,int b,int k,int l,int r){
    //ノードkに対応する区間[l,r)を与える
    //query(a,b,0,0,n)で[a,b)のminを与える
    if(r<=a || b<=l) return P(INF,-1);
    else if(a<=l && r<=b) return dat[k];
    else{
      P lmin=rmq(a,b,2*k+1,l,(l+r)/2);
      P rmin=rmq(a,b,2*k+2,(l+r)/2,r);
      return min(lmin,rmin);
    }
  }
};

