    Val query_impl(int l,int r,int k,int a,int b){
        if(l<=a && b<=r) return dat[k];
        if(r<=a || b<=l) return E;
        int mid=(a+b)/2;
        Val lhs=query_impl(l,r,k*2+1,a,mid);
        Val rhs=query_impl(l,r,k*2+2,mid,b);
        return F(lhs,rhs);
    }

    public:
    SegmentTree(int n,int e,const function<Val(Val,Val)> f):E(e),F(f){
        N=1;
        while(N<n) N*=2;
        dat.assign(2*N-1,E);
    }

    void update(int pos,Val val){
        pos=pos+N-1;
        dat[pos]=val;
        update_impl(pos);
    }

    Val query(int l,int r){
        assert(l<=r);
        return query_impl(l,r,0,0,N);
    }


    void debug(){
        int i=1;
        int sum=0;
        while(i<=N){
            for(int j=0;j<i;j++){
                cout<<dat[sum+j];
                if(j!=i-1) cout<<" ";
            }
            cout<<endl;
            sum+=i;
            i*=2;
        }
    }
};

