const int N=200005,inf=1e9;
#define lc pos+pos
#define rc lc|1
int a[N],rev[N],seg[2][4*N],n;
void update(int low,int high,int pos,int ind,int val,int i)
{
  if(low==high)
    {
      seg[i][pos]=val;
      return;
    }
  int mid=(low+high)>>1;
  if(ind<=mid) update(low,mid,lc,ind,val,i);
  else update(mid+1,high,rc,ind,val,i);
  seg[i][pos]=min(seg[i][lc],seg[i][rc]);
}
int query(int low,int high,int pos,int l,int r,int i)
{
  if(low>r || high<l) return inf;
  if(low>=l && high<=r) return seg[i][pos];
  int mid=(low+high)>>1;
  return min(query(low,mid,lc,l,r,i),query(mid+1,high,rc,l,r,i));
}
vector<ii> fun(int low,int high)
{
  if(low>high)
    return vector<ii>();
  if(high-low==1)
    {
      vector<ii> tmp;
      tmp.pb(mp(a[low],a[high]));
      return tmp;
    }
  int mn1=query(1,n,1,low,high,low&1),ind1=rev[mn1];
  int mn2=query(1,n,1,ind1+1,high,(ind1+1)&1),ind2=rev[mn2];
  vector<ii> ans;
  assert(mn1>=1 && mn1<=n); assert(mn2>=1 && mn2<=n);
  ans.pb(mp(mn1,mn2));
  int i=0,j=0,k=0;
  vector<ii> a1=fun(low,ind1-1),a2=fun(ind1+1,ind2-1),a3=fun(ind2+1,high); 
  while(true)
    {
      vector<pair<ii,int> > tmp;
      if(i<sz(a1)) tmp.pb(mp(a1[i],0));
      if(j<sz(a2)) tmp.pb(mp(a2[j],1));
      if(k<sz(a3)) tmp.pb(mp(a3[k],2));
      if(sz(tmp)==0) break;
      sort(all(tmp));
      int idx=tmp[0].se;
      if(idx==0) ans.pb(a1[i++]);
      else if(idx==1) ans.pb(a2[j++]);
      else ans.pb(a3[k++]);
    }
  return ans;
}
int main()
{
  std::ios::sync_with_stdio(false);
  cin.tie(NULL) ; cout.tie(NULL) ;
  cin>>n;
  rep(i,1,n+1) cin>>a[i],rev[a[i]]=i;
  rep(j,0,2)
    rep(i,0,4*N) seg[j][i]=inf;
  rep(j,0,2)
    for(int i=1+j;i<=n;i+=2)
      update(1,n,1,i,a[i],1-j);
  vector<ii> ans=fun(1,n);
  for(auto it:ans) cout<<it.fi<<" "<<it.se<<" ";
  cout<<endl;
  return 0 ;
}

