VP mergeParts(VVP &parts) {
    VP res;

    for (auto &part : parts) {
        VP newRes(res.size() + part.size());
        merge(res.begin(), res.end(), part.begin(), part.end(), newRes.begin());

        res = newRes;
    }

    return res;
}

struct vertex {
    int id;
    VI edges;

    pii value;
};

int solve(int l, int r, MinTree &treeOdd, MinTree &treeEven, VI &where, vector <vertex> &graph) {
    if (l > r) return -1;

    int x;
    if (l % 2) x = treeOdd.query(l, r-1);
    else x = treeEven.query(l, r-1);

    int y;
    if (l % 2) y = treeEven.query(where[x]+1, r);
    else y = treeOdd.query(where[x]+1, r);

    VI edges = {
        solve(l, where[x]-1, treeOdd, treeEven, where, graph),
        solve(where[x]+1, where[y]-1, treeOdd, treeEven, where, graph),
        solve(where[y]+1, r, treeOdd, treeEven, where, graph)
    };

    graph.pb({
        SIZE(graph),
        edges,
        {x, y}
    });

    return SIZE(graph)-1;
}

