void initRMQ(int n, int pa) {
    for (int i = 0; i < n; i++) d[pa][i][0] = a[pa][i];
    for (int j = 1; (1 << j) <= n; j++) {
        for (int i = 0; i + (1 << j) - 1 < n; i++) {
            d[pa][i][j] = min(d[pa][i][j - 1], d[pa][i + (1 << (j - 1))][j - 1]);
        }
    }
}

int RMQ(int l, int r, int pa) {
    int k = 0;
    while ((1 << (k + 1)) <= r - l + 1) k++;
    return min(d[pa][l][k], d[pa][r - (1 << k) + 1][k]);
}


