void build(int k,int l,int r){
	if(l==r){
		mn[l&1][k]=l;
		return;
	}
	int mid=l+r>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
	for(int i=0;i<2;i++){
		if(a[mn[i][k<<1]]>a[mn[i][k<<1|1]]) mn[i][k]=mn[i][k<<1|1];
		else mn[i][k]=mn[i][k<<1];
	}
}
int query(int k,int l,int r,int L,int R,int op){
	if(L<=l&&R>=r) return mn[op][k];
	int mid=l+r>>1,ans=0;
	if(L<=mid) ans=query(k<<1,l,mid,L,R,op);
	if(R>mid){
		int t=query(k<<1|1,mid+1,r,L,R,op);
		ans=a[ans]<a[t]?ans:t;
	}
	return ans;
}
