using namespace std;
typedef pair<int, int> pa;

constexpr int INF = 1145141919;
vector<int> p;

deque<pa> solve(int x, int y) {
    pa minValue = {INF, INF}, minIndex{-1, -1};
    for (int i = 0; i < y - x; i++) {
        int here = i + x;
        if (i % 2 == 0 && minValue.first > p[here]) {
            minValue = {p[here], INF}, minIndex = {here, -1};
        }
        if (i % 2 == 1 && minValue.second > p[i]) {
            minValue.second = p[here], minIndex.second = here;
        }
    }

    vector<deque<pa>> v;
    if (x != minIndex.first)v.push_back(solve(x, minIndex.first));
    if (minIndex.first + 1 != minIndex.second)v.push_back(solve(minIndex.first + 1, minIndex.second));
    if (minIndex.second + 1 != y)v.push_back(solve(minIndex.second + 1, y));

    deque<pa> ret;
    ret.push_back(minValue);
    while (true) {
        pa mi = {INF, INF};
        int pos = -1;
        for (int i = 0; i < v.size(); i++) {
            if (v[i].empty())continue;
            if (mi > v[i][0])mi = v[i][0], pos = i;
        }
        if (pos < 0)break;
        ret.push_back(mi), v[pos].pop_front();
    }
    return ret;
}

