using namespace std;
const long long int MOD = 1000000007;

long long int power(long long int x, long long int n, long long int M) {
	long long int tmp = 1;

	if (n > 0) {
		tmp = power(x, n / 2, M);
		if (n % 2 == 0) tmp = (tmp*tmp) % M;
		else tmp = (((tmp*tmp) % M)*x) % M;
	}
	return tmp;
}

long long int N, M, K, Q, W, H, L, R;
long long int ans;

class Segment_Tree {
	vector<long long int>v;
	vector<int>l;
	vector<int>r;
	int num;
	long long int ret;
	bool is_min;
	long long int Update(int place) {
		if (place >= (int)v.size() / 2) {
			return v[place];
		}
		if (is_min) {
			v[place] = min(Update(place * 2), Update(place * 2 + 1));
			return v[place];
		}
		v[place] = max(Update(place * 2), Update(place * 2 + 1));
		return v[place];
	}
	void RMQ(int a, int b, int place) {
		if (l[place] >= a&&r[place] <= b) {
			if (is_min)ret = min(ret, v[place]);
			else ret = max(ret, v[place]);
			return;
		}
		if (l[place]>b || r[place]<a) return;
		RMQ(a, b, place * 2);
		RMQ(a, b, place * 2 + 1);
		return;
	}
public:
	void Left(int place) {
		if (place >= (int)v.size() / 2) {
			l[place] = place - v.size() / 2;
			return;
		}
		Left(place * 2);
		Left(place * 2 + 1);
		l[place] = l[place * 2];
		return;
	}
	void Right(int place) {
		if (place >= (int)v.size() / 2) {
			r[place] = place - v.size() / 2;
			return;
		}
		Right(place * 2);
		Right(place * 2 + 1);
		r[place] = r[place * 2 + 1];
		return;
	}
	Segment_Tree(int n, bool min) {
		num = 1;
		while (num < n * 2) {
			num *= 2;
		}
		l.resize(num);
		r.resize(num);
		if (min) {
			v.resize(num, LLONG_MAX);
			is_min = true;
		}
		else v.resize(num, LLONG_MIN);
		Left(1);
		Right(1);
	}
	void Insert(int place, long long int num, bool update) {
		place += v.size() / 2;
		v[place] = num;
		if (!update)return;
		place /= 2;
		while (place) {
			if (is_min)v[place] = min(v[place * 2], v[place * 2 + 1]);
			else v[place] = max(v[place * 2], v[place * 2 + 1]);
			place /= 2;
		}
	}
	void TopDown() {
		Update(1);
	}
	long long int RMQ(int a, int b) {
		if (is_min)ret = LLONG_MAX;
		else ret = LLONG_MIN;
		RMQ(a, b, 1);
		return ret;
	}
};


int main() {
	ios::sync_with_stdio(false);
	long long int num[300000];
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> num[i];
		num[i] = num[i] * MOD + i;
	}
	Segment_Tree odd((int)N*2, true);
	Segment_Tree even((int)N*2, true);
	for (int i = 0; i < N; i++) {
		if(i%2)odd.Insert(i, num[i], false);
		else even.Insert(i, num[i], false);
	}
	odd.TopDown();
	even.TopDown();
	list<long long int>ret;
	int rig = N - 1;
	for(int i=(int)(N/2);i>=1;i--){
		long long int o_box = odd.RMQ(0, rig);
		int s = (int)(o_box%MOD) + 1;
		long long int o_bag = even.RMQ(s, min(s + i * 2 - 1, rig));
		long long int e_box = even.RMQ(0, rig);
		s = (int)(e_box%MOD) + 1;
		long long int e_bag = odd.RMQ(s, min(s + i * 2 - 1, rig));
		if (o_bag == LLONG_MAX) {
			ret.push_back(e_box / MOD);
			ret.push_back(e_bag / MOD);
			even.Insert((int)(e_box %MOD), LLONG_MAX, true);
			odd.Insert((int)(e_bag%MOD), LLONG_MAX, true);
		}
		else if (e_bag == LLONG_MAX) {
			ret.push_back(o_box / MOD);
			ret.push_back(o_bag / MOD);
			odd.Insert((int)(o_box %MOD), LLONG_MAX, true);
			even.Insert((int)(o_bag%MOD), LLONG_MAX, true);
		}
		else if (o_box < e_box) {
			ret.push_back(o_box / MOD);
			ret.push_back(o_bag / MOD);
			odd.Insert((int)(o_box %MOD), LLONG_MAX, true);
			even.Insert((int)(o_bag%MOD), LLONG_MAX, true);
		}
		else {
			ret.push_back(e_box / MOD);
			ret.push_back(e_bag / MOD);
			even.Insert((int)(e_box %MOD), LLONG_MAX, true);
			odd.Insert((int)(e_bag%MOD), LLONG_MAX, true);
		}
	}

	for (auto i : ret) {
		cout << i << " ";
	}
	cout << endl;
	return 0;
}

