int mina[MAX<<2][2];
int a[MAX],lo[MAX],n;
void init(int l,int r,int k)
{
    mina[k][0]=mina[k][1]=INF;
    if(l==r)
        return;
    init(l,(l+r)/2,2*k);
    init((l+r)/2+1,r,2*k+1);
}
void build(int l,int r,int k)//左闭右闭
{
    if(l==r)
    {
        scanf("%d",&a[l]);
        lo[a[l]]=l;
        mina[k][l%2]=a[l];return;
    }
    int mid=(l+r)/2;
    build(l,mid,2*k);
    build(mid+1,r,2*k+1);
    mina[k][0]=min(mina[2*k][0],mina[2*k+1][0]);
    mina[k][1]=min(mina[2*k][1],mina[2*k+1][1]);
}
int query(int ql,int qr,int l,int r,int k,int st)
{
    if(l>=ql&&r<=qr)
        return mina[k][st];
    int mid=(l+r)/2;
    if(mid<ql)
        return query(ql,qr,mid+1,r,2*k+1,st);
    else if(mid>=qr)
        return query(ql,qr,l,mid,2*k,st);
    else
        return min(query(ql,qr,l,mid,2*k,st),query(ql,qr,mid+1,r,2*k+1,st));
}
struct node
{
    int l,r,xiao,status;
    bool operator <(node b)const
    {
        return xiao>b.xiao;
    }
    node(int x=0,int y=0,int z=0,int s=0):l(x),r(y),xiao(z),status(s){}
};
priority_queue<node>que;
int an[MAX],cnt;
int main()
{
    cnt=0;
    scanf("%d",&n);
    init(0,n-1,1);
    build(0,n-1,1);
    node tem;
    tem.l=0;tem.r=n-1;tem.xiao=query(0,n-1,0,n-1,1,0);tem.status=0;
    que.push(tem);
    while(!que.empty())
    {
        tem=que.top();que.pop();
        int now=lo[tem.xiao];
        int nxt=query(now+1,tem.r,0,n-1,1,1^tem.status);
        int to=lo[nxt];
        an[cnt++]=tem.xiao;an[cnt++]=nxt;
        if(now>tem.l)
            que.push(node(tem.l,now-1,query(tem.l,now-1,0,n-1,1,tem.status),tem.status));
        if(to-now>1)
            que.push(node(now+1,to-1,query(now+1,to-1,0,n-1,1,tem.status^1),tem.status^1));
        if(tem.r>to)
            que.push(node(to+1,tem.r,query(to+1,tem.r,0,n-1,1,tem.status),tem.status));
    }
    for(int i=0;i<cnt;i++)
        printf("%d ",an[i]);
    return 0;
}

