inline int get(int l, int r, int w) {
  int k = lg[r - l + 1];
  return a[w][f[w][k][l]] < a[w][f[w][k][r - (1 << k) + 1]] ? f[w][k][l] : f[w][k][r - (1 << k) + 1];
}

struct E {
  int l, r, p, q, w;
  E() {}
  E(int nl, int nr, int np, int nq, int nw) : l(nl), r(nr), p(np), q(nq), w(nw) {}
  bool operator < (const E &o) const {
    return a[w][p] < a[o.w][o.p];
  }
};

