using namespace std;

int N;

vector<pair<int, int>> func(int* v, int len) {
	vector<pair<int, int>> ret;

	if (len == 0) return ret;

	int min = N + 1;
	int min_i = 0;

	for (int i = 0; i < len; i += 2) {
		if (v[i] < min) {
			min_i = i;
			min = v[i];
		}
	}

	min = N + 1;
	int min_j = min_i + 1;
	for (int j = min_i + 1; j < len; j += 2) {
		if (v[j] < min) {
			min_j = j;
			min = v[j];
		}
	}

	//cout << min_i << " " << min_j << endl;

	ret.push_back(make_pair(v[min_i], v[min_j]));
	vector<pair<int, int>> v1 = func(&(v[0]), min_i);
	vector<pair<int, int>> v2 = func(&(v[min_i + 1]), min_j - min_i - 1);
	vector<pair<int, int>> v3 = func(&(v[min_j + 1]), len - min_j - 1);

	vector<pair<int, int>> tail;
	tail.insert(tail.end(), v1.begin(), v1.end());
	tail.insert(tail.end(), v2.begin(), v2.end());
	tail.insert(tail.end(), v3.begin(), v3.end());
	sort(tail.begin(), tail.end());

	ret.insert(ret.end(), tail.begin(), tail.end());

	return ret;
}

int main(void) {
	cin >> N;
	int p[200000];
	for (int i = 0; i < N; i++) cin >> p[i];
	vector<pair<int, int>> ans = func(p, N);
	for (int i = 0; i < ans.size(); i++) {
		cout << ans[i].first << " " << ans[i].second;
		if (i < ans.size() - 1) cout << " ";
	}
	cout << endl;
	system("pause");
	return 0;
}

