inline void splay(int &v){
	v=0;char c=0;int p=1;
	while(c<'0' || c>'9'){if(c=='-')p=-1;c=getchar();}
	while(c>='0' && c<='9'){v=(v<<3)+(v<<1)+c-'0';c=getchar();}
	v*=p;
}
const int N=200010;
int d[N<<2],s[N<<2],a[N],n,wz[N];
void build(int l,int r,int w){
	if(l==r){
		if(l&1)d[w]=a[l],s[w]=1<<30;
		else d[w]=1<<30,s[w]=a[l];
		return;
	}
	int mid=l+r>>1;
	build(l,mid,w<<1),build(mid+1,r,w<<1|1);
	d[w]=min(d[w<<1],d[w<<1|1]);
	s[w]=min(s[w<<1],s[w<<1|1]);
}
int query(int l,int r,int w,int L,int R,int op){
	if(L<=l && r<=R){
		if(op)return d[w];
		else return s[w];
	}
	int mid=l+r>>1,ans=1<<30;
	if(L<=mid)ans=min(ans,query(l,mid,w<<1,L,R,op));
	if(R>=mid+1)ans=min(ans,query(mid+1,r,w<<1|1,L,R,op));
	return ans;
}
