class SegmentTree {
private: 
  const long long INF = 1e18;
  vector<pair<long long, int>> tree;
  int n;
public:
  void init(int sz) {
    n = 1;
    while (n < sz) {
      n *= 2;
    }
    tree.assign(2 * n, {INF, -1});
  }

  // l, r are in [0, n - 1]
  pair<long long, int> getMin(int l, int r) {
    l = n + l; r = n + r;
    pair<long long, int> res = {INF, -1};

    while (l <= r) {
      if (l & 1) {
        res = min(res, tree[l]);
        l++;
      }
      if (r % 2 == 0) {
        res = min(res, tree[r]);
        r--;
      }
      l /= 2; r /= 2;
    }
    return res;
  }

  // pos is in [0, n - 1]
  void update(int pos, long long val) {
    pos = n + pos;
    tree[pos] = {val, pos - n};
    pos /= 2;
    while (pos >= 1) {
      tree[pos] = min(tree[pos * 2], tree[pos * 2 + 1]);
      pos /= 2;
    }
  }
};

