/*
 *範囲のminimumを取得
 */
//区間[l, r)
struct segtree {
	vector<long long> data;
	long long n;
	segtree(long long nin){
		n = pow( 2, ceil( log(nin) / log(2) ) );
		long long size = 2 * n - 1;
		this->data.resize(size, 1e9);
	}

	//API for update val
	void update(long long idx, long long val){
		update(idx, val, 0, 0, n);
	}

	long long update(long long idx, long long val, long long node_id, long long left, long long right){
		//if query idx is within range return val
		if( !( left <= idx && idx < right ) ){
			return data[node_id];
		}
		if( left + 1 < right ) {
			//when node range is not 1, get update children val and update node data
			long long mid = (left + right) / 2 ;
			long long L = update(idx, val, 2 * node_id + 1, left, mid);
			long long R = update(idx, val, 2 * node_id + 2, mid, right);
			data[node_id] = min(L, R);
		} else {
			//when node range is 1, update node data
			data[node_id] = min(data[node_id], val);
		}
		return data[node_id];
	}

	//API for get value of [l, r)
	long long get(long long l, long long r){
		return get(l, r, 0, 0, n);
	}

	/*
	 *internaly used function
	 *query_l: query left range
	 *query_r: query right range
	 *node_id: node id of 
	 *node_l:  node left range 
	 *node_r:  node right range
	 */
	long long get(long long query_l, long long query_r, long long node_id, long long node_l, long long node_r){
		//query range is outside of node range: return INF
		if( query_r <= node_l || node_r <= query_l ){
			return INF;
		}
		//query range is within node range: return node val
		if( query_l <= node_l && node_r <= query_r ){
			return data[node_id];
		}
		long long mid = (node_l + node_r) / 2;
		long long L = get(query_l, query_r, 2 * node_id + 1, node_l, mid);
		long long R = get(query_l, query_r, 2 * node_id + 2, mid, node_r);
		return min(L, R);
	}
};


deque<long long >dfs(long long head, long long tail, segtree &oddsg, segtree &evensg){
	//cout << "head tail = " << head << " - " << tail << endl;
	deque<long long> ret;
	if(head + 1 >= tail){
		return ret;
	}

	long long fpos = -1;
	long long fval = INT_MAX;
	long long spos = -1;
	long long sval = INT_MAX;

	if(head % 2 == 0){
		fval = evensg.get(head, tail);
		fpos = p[fval];
		sval = oddsg.get(fpos + 1, tail);
		spos = p[sval];
	}else{
		fval = oddsg.get(head, tail);
		fpos = p[fval];
		sval = evensg.get(fpos + 1, tail);
		spos = p[sval];
	}

	//cout << "head tail = " << head << " - " << tail << endl;
	//cout << "fpos = " << fpos << "fval = " << fval << endl;
	//cout << "spos = " << spos << "sval = " << sval << endl;

	deque<long long> ff;
	deque<long long> ss;
	deque<long long> tt;
	ff = dfs(head, fpos, oddsg, evensg);
	ss = dfs(fpos+1, spos, oddsg, evensg);
	tt = dfs(spos, tail, oddsg, evensg);

	//merge
	while(ff.size() != 0 || ss.size() != 0 || tt.size() != 0){
		long long mini = INT_MAX;
		int who = -1;
		if(ff.size() > 0 && ff[0] < mini){
			who = 1;
			mini = ff[0];
		}

		if(ss.size() > 0 && ss[0] < mini){
			who = 2;
			mini = ss[0];
		}

		if(tt.size() > 0 && tt[0] < mini){
			who = 3;
			mini = tt[0];
		}
		long long f;
		long long s;
		if(who == 1){
			f = ff[0];
			ff.pop_front();
			s = ff[0];
			ff.pop_front();
		}else if(who == 2){
			f = ss[0];
			ss.pop_front();
			s = ss[0];
			ss.pop_front();
		}else{
			f = tt[0];
			tt.pop_front();
			s = tt[0];
			tt.pop_front();
		}
		//cout << "who = " << who << endl;
		//cout << "push front" << f << " " << s << endl;
		ret.push_back(f);
		ret.push_back(s);
	}

	ret.push_front(sval);
	ret.push_front(fval);
	return ret;
}

