struct RMQ
{
	PII A[MAX * 4];
	int n;

	void init(int n)
	{
		this->n = n;
		FOR (i, 0, MAX * 4)
		{
			A[i] = MP(INF, INF);
		}
	}

	void add(int tl, int tr, int v, int pos, int val)
	{
		if (tl == tr)
		{
			A[v] = MP(val, pos);
			return;
		}

		int tm = (tl + tr) / 2;
		if (pos <= tm) add(tl, tm, v * 2, pos, val);
		else add(tm+1, tr, v * 2 + 1, pos, val);

		A[v] = min(A[v*2], A[v*2+1]);
	}

	void add(int pos, int val)
	{
		add(0, n-1, 1, pos, val);
	}

	PII get(int tl, int tr, int v, int l, int r)
	{
		if (l == tl && r == tr)
		{
			return A[v];
		}

		if (l > r) return MP(INF, INF);

		int tm = (tl + tr) / 2;
		PII res = get(tl, tm, v*2, l, min(r, tm));
		res = min(res, get(tm+1, tr, v*2+1, max(l, tm+1), r));

		return res;
	}

	PII get(int l, int r)
	{
		return get(0, n-1, 1, l, r);
	}
} R1, R2;

