	segm(int l, int r, PII v1, PII v2)
	{
		this->l = l;
		this->r = r;
		this->v1 = v1;
		this->v2 = v2;
	}

	bool operator <(const segm& s) const
	{
		return MP(v1, v2) < MP(s.v1, s.v2);
	}
};

segm getSegm(int l, int r)
{
