struct Node{
	int l , r;
	pair < int , int > w;
	Node( int l , int r , pair < int , int > w ) : l( l ) , r( r ) , w( w ){}
	friend bool operator < ( const Node & x , const Node & y ){
		return make_pair( p[x.w.first] , p[x.w.second] ) > make_pair( p[y.w.first] , p[y.w.second] );
	}
};

int GetMin( int l , int r , int f[][20] ){
	int z = len[r - l + 1];
	return min( f[l][z] , f[r - (1 << z) + 1][z] );
}

pair < int , int > Query( int l , int r ){
	int w ;
	if( l & 1 ) w = GetMin( l , r , odd );
	else w = GetMin( l , r , even );
	w = pos[w];
	int t;
	if( l & 1 ) t = GetMin( w + 1 , r , even );
	else t = GetMin( w + 1 , r , odd );
	t = pos[t];
	return make_pair( w , t );
}

priority_queue < Node > pq;

void PushStatus( int l , int r ){
	if( l >= r ) return;
	pq.push( Node( l , r , Query( l , r ) ) );
}

