	int mi[N<<2], arr[N];
	Tree() {arr[0] = 1e9;}
	void build(int l, int r, int x) {
		if(l == r) return mi[x] = l, void();
		int mid = l + r >> 1;
		build(lson), build(rson);
		mi[x] = mi[x << 1 | (arr[mi[x<<1]] > arr[mi[x<<1|1]])];
	}
