		if(L <= l and r <= R) return mi[x];
		int mid = l + r >> 1, t1 = 0, t2 = 0;
		if(L <= mid) t1 = qry(lson, L, R);
		if(mid < R) t2 = qry(rson, L, R);
		return arr[t1] < arr[t2] ? t1 : t2;
	}
	#undef lson
	#undef rson
};

