struct SegTree {
  int N;
  vector<int> dat;
  SegTree(int k) {
    N = 1;
    while (N < k) N *= 2;
    dat.assign(2 * N - 1, INT_MAX);
  }
  void update(int k, int a) {
    k += N - 1;
    dat[k] = a;
    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }
  int query(int a, int b) { return query(a, b, 0, 0, N); }
  int query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return INT_MAX;
    if (a <= l && r <= b) return dat[k];
    int m = (l + r) / 2;
    int vl = query(a, b, k * 2 + 1, l, m);
    int vr = query(a, b, k * 2 + 2, m, r);
    return min(vl, vr);
  }
};

main() {
  int N; cin >> N;
  vector<int> p(N), pos(N + 1, N);
  SegTree even(N), odd(N);
  for (int i = 0; i < N; i++) {
    cin >> p[i];
    ( (i % 2 == 0) ? even : odd ).update(i, p[i]);
    pos[p[i]] = i;
  }
  vector<int> ans;
  priority_queue<T, vector<T>, greater<T> > que;
  que.push(make_tuple(even.query(0, N), 0, N));
  while (!que.empty()) {
    T min_interval = que.top(); que.pop();
    int& eval = get<0>(min_interval);
    int& l = get<1>(min_interval);
    int& r = get<2>(min_interval);
    if (l % 2 == 0) {
      int oval = odd.query(pos[eval], r);
      if (l < pos[eval] - 1) que.push(make_tuple(even.query(l, pos[eval]), l, pos[eval]));
      if (pos[eval] < pos[oval] - 1) que.push(make_tuple(odd.query(pos[eval] + 1, pos[oval]), pos[eval] + 1, pos[oval]));
      if (pos[oval] < r - 1) que.push(make_tuple(even.query(pos[oval] + 1, r), pos[oval] + 1, r));
      ans.push_back(eval); ans.push_back(oval);
    } else {
      int oval = even.query(pos[eval], r);
      if (l < pos[eval] - 1) que.push(make_tuple(odd.query(l, pos[eval]), l, pos[eval]));
      if (pos[eval] < pos[oval] - 1) que.push(make_tuple(even.query(pos[eval] + 1, pos[oval]), pos[eval] + 1, pos[oval]));
      if (pos[oval] < r - 1) que.push(make_tuple(odd.query(pos[oval] + 1, r), pos[oval] + 1, r));
      ans.push_back(eval); ans.push_back(oval);
    }
  }
  for (int i = 0; i < N; i++) cout << ans[i] << ( (i == N - 1) ? '\n' : ' ' );
}

#include <bits/stdc++.h>
using namespace std;
struct Segtree {
  vector<pair<int, int>> tree;
  int n;
  Segtree() = default;
  Segtree(const vector<pair<int, int>> &v) {
    n = v.size();
    tree = vector<pair<int, int>>(2 * n, {INT_MAX, INT_MAX});
    for (int i = 0; i < n; ++i) {
      update(i, v[i]);
    }
  }

  void update(int i, pair<int, int> val) {
    int p = i + n;
    tree[p] = val;
    p /= 2;
    while (p) {
      tree[p] = tree[p * 2];
      if (p * 2 + 1 < tree.size()) {
        tree[p] = min(tree[p], tree[p * 2 + 1]);
      }
      p /= 2;
    }
  }

  pair<int, int> query(int start, int end) {
    int l = n + start;
    int r = n + end - 1;
    pair<int, int> ret = {INT_MAX, -1};
    while (l <= r) {
      if (l & 1) {
        ret = min(ret, tree[l]);
        l++;
      }

      if ((r & 1) == 0) {
        ret = min(ret, tree[r]);
        r--;
      }
      l /= 2;
      r /= 2;
    }
    return ret;
  }
};
int N;
int a[2 * 100000 + 100];
Segtree ost;
Segtree est;
int main() {
  ios::sync_with_stdio(false);
  cin >> N;
  vector<int> ev;
  vector<int> ov;
  for (int i = 0; i < N; ++i) {
    int c;
    cin >> c;
    a[i] = c;
    if (i & 1) {
      ov.push_back(c);
    } else
      ev.push_back(c);
  }

  vector<pair<int, int>> ovp;
  for (int i = 0; i < ov.size(); ++i) {
    ovp.push_back({ov[i], i});
  }

  vector<pair<int, int>> evp;
  for (int i = 0; i < ev.size(); ++i) {
    evp.push_back({ev[i], i});
  }
  ost = Segtree(ovp);
  est = Segtree(evp);
  auto getMin = [&](int l, int r) {
    if ((l & 1) == 0) {
      auto p1 = est.query(l / 2, r / 2);
      return p1.first;
    } else {
      auto p1 = ost.query(l / 2, r / 2);
      return p1.first;
    }
    return 0;
  };
   auto cmp = [&](const pair<int, int> &p1, const pair<int, int> &p2) {
    int l1 = p1.first;
    int r1 = p1.second;
    int l2 = p2.first;
    int r2 = p2.second;
    return getMin(l1, r1) > getMin(l2, r2);
  };
  priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(cmp)> pq(cmp);
  pq.push({0, N});
  vector<pair<int, int>> ret;
  while (pq.size()) {
    auto p = pq.top();
    pq.pop();
    int l = p.first;
    int r = p.second;
    if (l + 2 == r) {
      ret.push_back({a[l], a[l + 1]});
      continue;
    }
    int i1, i2;
    if ((l & 1) == 0) {
      auto p1 = est.query(l / 2, r / 2);
      i1 = p1.second * 2;
      auto p2 = ost.query(i1 / 2, r / 2);
      i2 = p2.second * 2 + 1;
      ret.push_back({p1.first, p2.first});
    } else {
      auto p1 = ost.query(l / 2, r / 2);
      i1 = p1.second * 2 + 1;
      auto p2 = est.query(i1 / 2 + 1, r / 2 + 1);
      i2 = p2.second * 2;
      ret.push_back({p1.first, p2.first});
    }
    if (l != i1) pq.push({l, i1});
    if (i1 + 1 != i2) pq.push({i1 + 1, i2});
    if (i2 + 1 != r) pq.push({i2 + 1, r});
  }
  for (auto c : ret) cout << c.first << ' ' << c.second << ' ';
  cout << endl;
}

