struct tree
{
	PII load[2*M];

	void insert(int a, int v)
	{
		a += M;
		load[a] = mp(v, a-M);
		a /= 2;

		while(a>=1)
		{
			load[a] = min(load[2*a], load[2*a+1]);
			a /= 2;
		}
	}

	PII query(int a, int b)
	{
		a += M;
		b += M;

		PII res = min(load[a], load[b]);

		while(a<b-1)
		{
			if(a%2==0)
				res = min(res, load[a+1]);

			if(b%2==1)
				res = min(res, load[b-1]);

			a /= 2;
			b /= 2;
		}

		return res;
	}

	tree()
	{
		for(int i = 0; i < 2*M; ++i)
		{
			load[i] = mp(inf, inf);
		}
	}
};

tree P, NP;

VPII merge(VPII a, VPII b)
{
	VPII res;

	int i = 0, j = 0;

	while(i<a.size() || j<b.size())
	{
		if(i==a.size())
			res.pb(b[j++]);
		else if(j==b.size())
			res.pb(a[i++]);
		else if(a[i]<b[j])
			res.pb(a[i++]);
		else
			res.pb(b[j++]);
	}

	return res;
}

VPII solve(int a, int b)
{
	if(a>b)
		return VPII();

	PII q1, q2;

	if(a%2==1)
	{
		q1 = NP.query(a, b);
		q2 = P.query(q1.nd+1, b);
	}
	else
	{
		q1 = P.query(a, b);
		q2 = NP.query(q1.nd+1, b);
	}

	VPII A = solve(a, q1.nd-1), B = solve(q1.nd+1, q2.nd-1), C = solve(q2.nd+1, b);

	A = merge(A, B);
	A = merge(A, C);
	A.insert(A.begin(), mp(p[q1.nd], p[q2.nd]));

	return A;
}

