vector<P> rec(int l ,int r){
  if(l == r) return vector<P>();
  int i = idx[segs[l % 2].get_inter(l,r)];
  int j = idx[segs[(l + 1) % 2].get_inter(l,r)];
  vector<P> res;
  vector<P> temp[3];
  temp[0] = rec(l,i);
  temp[1] = rec(i + 1,j);
  temp[2] = rec(j + 1,r);
  while(true){
    int num = -1;
    int se = -1;
    for(int k = 0;k < 3;k++){
      if(temp[k].empty()) continue;
      if(num < temp[k].back().first){
        num = temp[k].back().first;
        se = k;
      }
    }
    if(se == - 1) break;
    res.push_back(temp[se].back());
    temp[se].pop_back();
  }
  res.push_back({p[i],p[j]});
  reverse(res.begin(),res.end());
  return res;
}

