class SegT{
private:
  int dat[2][2 * (1 << 18) - 1];
  int NN;
  VI xs;

public:
  int mind(int x, int y){
	if(x == -1) return y;
	if(y == -1) return x;
	return (xs[x] < xs[y]? x: y);
  }

  SegT(int n_, VI& xs_){
	NN = 1;
	while(NN < n_) NN <<= 1;
	xs = xs_;
	for(int i=0;i<2*NN-1;++i) dat[0][i] = dat[1][i] = -1;
	for(int i=0;i<n_;++i)
	  dat[0][NN-1+i] = i;
	for(int i=NN-2;i>=0;--i){
	  int l = i*2+1, r = i*2+2;
	  if(r >= NN-1)
		dat[0][i] = dat[0][l];
	  else
		dat[0][i] = mind(dat[0][l], dat[0][r]);

	  if(r >= NN-1)
		dat[1][i] = dat[0][r];
	  else
		dat[1][i] = mind(dat[1][l], dat[1][r]);
	}
  }

  int query(int a, int b, int p, int k, int l, int r){
	if(r <= a || b <= l) return -1;
	if(a <= l && r <= b) return dat[(p+l-a)%2][k];
	else{
	  int m = (l+r)/2;
	  if(b <= m)
		return query(a, b, p, k*2+1, l, m);
	  if(m <= a)
		return query(a, b, p, k*2+2, m, r);
	  int vl = query(a, b, p, k*2+1, l, m);
	  int vr = query(a, b, p, k*2+2, m, r);
	  return mind(vl, vr);
	}
  }
  int query(int a, int b, int p){
