vector<pair<int,int> > merge(int l,int r)
{
	if (l>=r) return vector<pair<int,int> >();

	int p1=l;
	for (int i=l;i<=r;i++) if ((l&1)==(i&1) && a[p1]>a[i]) p1=i;
	int p2=p1+1;
	for (int i=p2;i<=r;i++) if ((p1&1)!=(i&1) && a[p2]>a[i]) p2=i;

	vector<pair<int,int> > ret=vector<pair<int,int> >();
	ret.push_back(make_pair(a[p1],a[p2]));
	vector<pair<int,int> > v[4];
	v[1]=merge(l,p1-1);
	v[2]=merge(p1+1,p2-1);
	v[3]=merge(p2+1,r);
	int i[4]={0,0,0,0};
	priority_queue<pair<pair<int,int>,int> , vector<pair<pair<int,int>,int> >,greater<pair<pair<int,int>,int> > > q;
	for (int o=1;o<=3;o++) if (i[o]<v[o].size()) q.push(make_pair(v[o][i[o]++],o));
	while (!q.empty())
	{
		auto t=q.top();q.pop();
		if (i[t.second]<v[t.second].size()) q.push(make_pair(v[t.second][i[t.second]++],t.second));
		ret.push_back(t.first);
	}
	return ret;
}

