int idx[200200];
RMQ<int> rmq0(200200), rmq1(200200);

vector<int> calc(int l, int r) {
  vector<int> res;
  if (l >= r) return res;
  int q0 = (l & 1 ? rmq1.query(l, r) : rmq0.query(l, r));
  res.push_back(q0);
  q0 = idx[q0];
  int q1 = (l & 1 ? rmq0.query(q0, r) : rmq1.query(q0, r));
  res.push_back(q1);
  q1 = idx[q1];
  vector<int> pre1 = calc(l, q0), pre2 = calc(q0 + 1, q1), pre3 = calc(q1 + 1, r);
  int i = 0, j = 0, k = 0;
  while (i < pre1.size() || j < pre2.size() || k < pre3.size()) {
    int vi = (i == pre1.size() ? inf : pre1[i]);
    int vj = (j == pre2.size() ? inf : pre2[j]);
    int vk = (k == pre3.size() ? inf : pre3[k]);
    int mi = min({vi, vj, vk});
    if (mi == vi) res.push_back(pre1[i]), res.push_back(pre1[i + 1]), i += 2;
    if (mi == vj) res.push_back(pre2[j]), res.push_back(pre2[j + 1]), j += 2;
    if (mi == vk) res.push_back(pre3[k]), res.push_back(pre3[k + 1]), k += 2;
  }
  return res;
}

