        if (u<=l && r<=v) return st[id];
        int mid = (l+r)/2;
        return min(get(u, v, l, mid, id*2), get(u, v, mid+1, r, id*2+1));
    }
} b[2];

void solve(int l, int r, int clss) {
    if (l>=r) return;
    ii tmp1 = b[l%2].get(l, r), tmp2 = b[(l+1)%2].get(tmp1.se+1, r);
    p.push_back(ii(clss, tmp1.fi));
    assigned[tmp1.fi] = tmp2.fi;
    solve(l, tmp1.se-1, clss+1);
    solve(tmp1.se+1, tmp2.se-1, clss+1);
    solve(tmp2.se+1, r, clss+1);
}

int main() {
    //freopen("youngmaids.inp", "r", stdin);
    //freopen("", "w", stdout);
    //ios::sync_with_stdio(0); cin.tie(0);
    scanf("%d", &n);
    FOR(i, 1, n) {
        int x; scanf("%d", &x);
        b[i%2].update(i, ii(x, i));
    }
    //Debug(b[1].get(1, 4).fi);
    solve(1, n, 0);
    sort(p.begin(), p.end());
    REP(i, p.sz()) printf("%d %d ", p[i].se, assigned[p[i].se]);
}

