P get(llint l, llint r)
{
	llint retl = seg[l%2].query(l, r).second;
	llint retr = seg[r%2].query(retl, r).second;
	return P(retl, retr);
}

void add(llint l, llint r)
{
	P res = get(l, r);
	Q.push(F(P(p[res.first], p[res.second]), E(P(res.first, res.second), P(l, r))));
}

