const int maxn = 2e5 + 20;
const int inf = 0x3f3f3f3f;

struct Data
{
	int len;
	int min[2];

	friend Data operator + (Data a,Data b)
	{
		return (Data)
		{
			a.len + b.len,
			{
				std::min(a.min[0], b.min[0 ^ (a.len & 1)]),
				std::min(a.min[1], b.min[1 ^ (a.len & 1)])
			}
		};

	}

	friend bool operator < (const Data &a,const Data &b)
	{
		return a.min[1] < b.min[1];
	}

} T[maxn << 2];

int N, P[maxn];
int pos[maxn];

std::set<std::pair<int,std::pair<int,int> > > set;

void build(int l,int r,int x)
{
	if(l == r)
	{
		T[x] = (Data){1, {inf, P[l]}};
	}
	else
	{
		int mid = (l + r) >> 1;

		build(l, mid, x << 1);
		build(mid + 1, r, x << 1 | 1);

		T[x] = T[x << 1] + T[x << 1 | 1];
	}
}
Data query(int l,int r,int ll,int rr,int x)
{
	if(l == ll && r == rr)
	{
		return T[x];
	}
	else
	{
		int mid = (ll + rr) >> 1;

		if(r <= mid) return query(l, r, ll, mid, x << 1);
		else if(l > mid) return query(l, r, mid + 1, rr, x << 1 | 1);
		else
		{
			return query(l, mid, ll, mid, x << 1) + query(mid + 1, r, mid + 1, rr, x << 1 | 1);
		}
	}
}
std::pair<int,std::pair<int,int> > get(int l,int r)
{
	return std::make_pair(query(l, r, 1, N, 1).min[1], std::make_pair(l, r));
}
