	int flag;
	struct Node {
		int val;
		int stdl, stdr;
	}	tree[MAXV];
	inline void buildtree(int root, int l, int r) {
		tree[root].stdl = l;
		tree[root].stdr = r;
		if (l == r) {
			tree[root].val = (l & 1) == flag ? ary[l] : INF;
			return;
