ii get(ii a[][18], int l, int r) {
	int k = lg[r - l + 1];
	return min(a[l][k], a[r - (1 << k) + 1][k]);
}

void add(int l, int r) {
	if (l >= r) return;
	seg.insert(ii(l, r));
}

void solve(int l, int r, int pos) {
	seg.erase(ii(l, r));
	if (pos % 2 == l % 2) {
		// to the right: [pos + 1, r]
		int newr = get(pmax[r % 2], (pos + 1) / 2, r / 2).second;
		printf("%d %d ", a[pos], a[newr]);
		del[pos] = del[newr] = true;

		add(l, pos - 1);
		add(pos + 1, newr - 1);
		add(newr + 1, r);
	}	else {
		// to the left: [l, pos - 1]
		int newl = get(pmax[l % 2], l / 2, (pos - 1) / 2).second;
		printf("%d %d ", a[newl], a[pos]);
		del[newl] = del[pos] = true;

		add(l, newl - 1);
		add(newl + 1, pos - 1);
		add(pos + 1, r);
	}
}

