	}

	for (int j = 1; j <= 17; ++j) {
		for (int i = 0; i + (1 << j) - 1 < n / 2; ++i) {
			for (int parity = 0; parity <= 1; ++parity) {
				pmax[parity][i][j] = min(pmax[parity][i][j - 1], pmax[parity][i + (1 << j - 1)][j - 1]);
			}
		}
	}

	// solve
	seg.insert(ii(0, n - 1));
	for (int val = 1; val <= n; ++val) {
		int pos = p[val];
		if (del[pos]) continue;

		set<ii>::iterator iter = seg.upper_bound(ii(pos, 1e9));
		--iter;

		solve((iter->first), (iter->second), pos);
