        if (i%2==0 && tip==1) t[1][i]=a[i-len+1]; else
        if (i%2==1 && tip==0)
        t[0][i]=a[i-len+1];

    for (int i=len-1;i>0;i--)
        t[tip][i]=min(t[tip][i<<1],t[tip][i<<1|1]);
