            q.push(node(tot,hhh));
        }
        if (now<r)
        {
            st[++tot]=now+1;ed[tot]=r;
            int hhh=(now&1)?query2(1,1,n>>1,(now+1)>>1,r>>1):query1(1,1,n>>1,(now>>1)+1,r>>1);
            q.push(node(tot,hhh));
        }
        if (now-id>1)
        {
            st[++tot]=id+1;ed[tot]=now-1;
            int hhh=(id&1)?query2(1,1,n>>1,(id+1)>>1,(now-1)>>1):query1(1,1,n>>1,(id>>1)+1,(now-1)>>1);
            q.push(node(tot,hhh));
        }
    }
    puts("");
    return 0;
}

