struct SEG{
	int na,m;
	P d[280000];
	SEG(int _n):m(_n){
		na=1;
		while(na<_n)na*=2;
		REP(i, 2*na -1)d[i]=MP(-INF, 0);
	}
	void update(int a, P v){
		a+=na-1;
		d[a]=v;
		while(a>0){
			a=(a-1)/2;
			d[a] = max(d[a*2+1], d[a*2+2]);
		}
	}
	P query(int a, int b){
		return _query(a, b, 0, 0, na);
	}
	P _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return MP(-INF, 0);
		if(a<=l && r <= b) return d[k];
		else{
			P vl = _query(a,b,k*2+1, l, (l+r)/2);
			P vr = _query(a,b,k*2+2, (l+r)/2,r);
			return max(vl, vr);
		}
	}
};

