void solve() {
    int N;
    cin>>N;
    vector<int> A(N);
    indice.resize(N+1);
    for(int i = 0;i < N;i++) {
        cin>>A[i];
        if(i%2==0) {
            ev.update(i,A[i]);
            od.update(i,1<<20);
        }
        else {
            od.update(i,A[i]);
            ev.update(i,1<<20);
        }
        indice[A[i]]=i;
    }

    vector<int> Q;

    add(0,N);
    while(cand.size()) {
        vector<int> v=*cand.begin();
        cand.erase(cand.begin());
        Q.push_back(v[0]);
        Q.push_back(v[1]);
        //左
        add(v[2],v[3]);
        //真ん中
        add(v[3]+1,v[4]);
