int serch(int l,int r)
{
	int now=n;
	for(int i=17;i>=0&&l<=r;i--)
	{
		if(!jump[l][i]||jump[l][i]>r+1) continue;
		now=std::min(now,v[l][i]);
		l=jump[l][i];
	}
	return now;
}
void ins(int l,int r)
{
	if(l>r) return ;
	que x;
	x.l=l;x.r=r;
	x.val=serch(l,r);
	pq.push(x);
}
void init()
{
	p[n+1]=p[n+2]=n+2;
	for(int i=1;i<=n+1;i++) jump[i][0]=i+2,v[i][0]=p[i];
	for(int i=1;i<=17;i++)
	{
		for(int j=1;j<=n+1;j++)
		{
			jump[j][i]=jump[jump[j][i-1]][i-1];
			v[j][i]=std::min(v[j][i-1],v[jump[j][i-1]][i-1]);
		}
	}
}
