constexpr int INF = 1 << 29;
constexpr int LIM = 804040;

class RMQ {
    int arr[LIM];
    int n;
    public:

    RMQ() {}

    RMQ(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        fill(arr, arr+LIM, INF);
    }

    void update(int k, int a) {
        k += n-1;
        arr[k] = a;
        while (k > 0) {
            k = (k-1) / 2;
            arr[k] = min(arr[2*k+1], arr[2*k+2]);
        }
    }

    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1) r = n;
        if (r <= a || b <= l) return INF;

        if (a <= l && r <= b) return arr[k];
        else {
            int vl = query(a, b, k*2+1, l, (l+r)/2);
            int vr = query(a, b, k*2 + 2, (l+r)/2, r);
            return min(vl, vr);
        }
    }
};

int N, a[202020];

RMQ rmq[2];

int loc[202020];

struct P {
    int a, b, ll, rr;

    P () {}
    P (int w, int x, int yy, int zz): a(w), b(x), ll(yy), rr(zz) {}

    bool operator <(const P& o) const {
        if (a != o.a) return a > o.a;
        return b > o.b;
    }
};


vector<int> solve() {
    vector<int> ans;

    priority_queue<P> que;

    int v = rmq[0].query(0, N), lv = loc[v];
    int w = rmq[1].query(lv+1, N);

    que.emplace(v, w, 0, N);

    while (!que.empty()) {
        P p = que.top(); que.pop();

        ans.push_back(p.a); ans.push_back(p.b);

        int la = loc[p.a], lb = loc[p.b];

        vector<pair<int, int>> z;
        z.emplace_back(p.ll, la); z.emplace_back(la+1, lb); z.emplace_back(lb+1, p.rr);
        for (auto q: z) {
            int l = q.first, r = q.second, b = l%2;
            if (l >= r) continue;
            int v = rmq[b].query(l, r), lv = loc[v];
            int w = rmq[1-b].query(lv+1, r);

            que.emplace(v, w, l, r);
        }
    }

    return ans;
}

int main() {
    scanf("%d", &N);
    rmq[0] = RMQ(N), rmq[1] = RMQ(N);
    for (int j = 0; j < N; ++j) {
        scanf("%d", a+j);
        loc[a[j]] = j;
        rmq[j%2].update(j, a[j]);
    }

    vector<int> ans = solve();
    for (int j = 0; j < N; ++j) {
        if (j > 0) cout << " ";
        cout << ans[j];
    }
    cout << endl;
    return 0;
}

