using namespace std;
typedef pair<int, int> pa;
constexpr int INF = 1145141919;

struct SparseTable {
    vector<vector<pa>> st;
    vector<int> lookup;

    void init(vector<int> &v) {
        int b = 0;
        while ((1 << b) <= v.size()) ++b;
        st.assign(b, vector<pa>(1 << b));
        for (int i = 0; i < v.size(); i++) st[0][i] = {v[i], i};
        for (int i = 1; i < b; i++) {
            for (int j = 0; j + (1 << i) <= (1 << b); j++) {
                st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
            }
        }

        lookup.resize(v.size() + 1);
        for (int i = 2; i < lookup.size(); i++) {
            lookup[i] = lookup[i >> 1] + 1;
        }
    }

    inline pa rmq(int l, int r) {
        int b = lookup[r - l];
        return min(st[b][l], st[b][r - (1 << b)]);
    }
};

int n;
vector<int> p;
vector<SparseTable> tables;
vector<pa> ans;

void marge(deque<pa> &x, deque<pa> &y) {
    deque<pa> ret;
    while (!(x.empty() && y.empty())) {
        if (x.empty())ret.push_back(y.front()), y.pop_front();
        else if (y.empty())ret.push_back(x.front()), x.pop_front();
        else {
            if (x.front() < y.front())ret.push_back(x.front()), x.pop_front();
            else ret.push_back(y.front()), y.pop_front();
        }
    }
    x = ret;
}

void solve(int x, int y) {
    auto fi = tables[x % 2].rmq(x, y);
    auto se = tables[(x + 1) % 2].rmq(fi.second + 1, y);
    pa minValue = {fi.first, se.first}, minIndex{fi.second, se.second};

    if (x != minIndex.first) solve(x, minIndex.first);
    if (minIndex.first + 1 != minIndex.second) solve(minIndex.first + 1, minIndex.second);
    if (minIndex.second + 1 != y) solve(minIndex.second + 1, y);

    if (x == 0 && y == n) {
        vector<pa> v = ans;
        sort(v.begin(), v.end());
        ans.clear();
        ans.push_back(minValue);
        for (auto tmp:v)ans.push_back(tmp);
    } else {
        ans.push_back(minValue);
    }
}

int main() {
    cin >> n;
    p.resize(n);
    vector<vector<int>> v(2, vector<int>(n, INF));
    for (int i = 0; i < n; i++) {
        cin >> p[i];
        v[i % 2][i] = p[i];
    }
    tables.resize(2);
    tables[0].init(v[0]), tables[1].init(v[1]);

    solve(0, n);

    for (int i = 0; i < ans.size(); i++) {
        if (i != 0)cout << " ";
        cout << ans[i].first << " " << ans[i].second;
    }
    cout << endl;
    return 0;
}

