using namespace std;



void build_tree(int node, int a, int b, const int* A, int* tree)
{
    if (a > b) return;
    if (a == b) { tree[node] = A[a]; return; }
    build_tree(node*2, a, (a+b)/2, A, tree); // Init left child
    build_tree(node*2+1, 1+(a+b)/2, b, A, tree); // Init right child
    tree[node] = min(tree[node*2], tree[node*2+1]); // Init root value
}


void update_tree(int node, int a, int b, int i, int j, int value, int* tree, int* lazy) {

    if(lazy[node] != 0) { // This node needs to be updated
        tree[node] += lazy[node]; // Update it

        if(a != b) {
            lazy[node*2] += lazy[node]; // Mark child as lazy
            lazy[node*2+1] += lazy[node]; // Mark child as lazy
        }

        lazy[node] = 0; // Reset it
    }

    if(a > b || a > j || b < i) // Current segment is not within range [i, j]
        return;

    if(a >= i && b <= j) { // Segment is fully within range
        tree[node] += value;

        if(a != b) { // Not leaf node
            lazy[node*2] += value;
            lazy[node*2+1] += value;
            lazy[node*2] = min(lazy[node*2], Inf);
            lazy[node*2+1] = min(lazy[node*2+1], Inf);
        }

        return;
    }

    update_tree(node*2, a, (a+b)/2, i, j, value, tree, lazy); // Updating left child
    update_tree(1+node*2, 1+(a+b)/2, b, i, j, value, tree, lazy); // Updating right child

    tree[node] = min(tree[node*2], tree[node*2+1]); // Updating root with max value
}


int query_tree(int node, int a, int b, int i, int j, int* tree, int* lazy) {

    if(a > b || a > j || b < i) return Inf; // Out of range


    if(lazy[node] != 0) { // This node needs to be updated
        tree[node] += lazy[node]; // Update it

        if(a != b) {
            lazy[node*2] += lazy[node]; // Mark child as lazy
            lazy[node*2+1] += lazy[node]; // Mark child as lazy
        }

        lazy[node] = 0; // Reset it
    }

    if(a >= i && b <= j) // Current segment is totally within range [i, j]
        return tree[node];

    int q1 = query_tree(node*2, a, (a+b)/2, i, j, tree, lazy); // Query left child
    int q2 = query_tree(1+node*2, 1+(a+b)/2, b, i, j, tree, lazy); // Query right child

    int res = min(q1, q2); // Return final result

    return res;
}


int Aall[MAXN+2];
int treeall[MAXN+2];
int lazyall[MAXN+2];

int Ae[MAXN+2];
int treee[MAXN+2];
int lazye[MAXN+2];


int Ao[MAXN+2];
int treeo[MAXN+2];
int lazyo[MAXN+2];

int pos[MAXN+2];


vector<pair<int,int> > Solve(int st, int en, int N) {
    if (st > en)
        return vector<pair<int,int> >();
    int x,px,y,py;


    if (st % 2 == 0) {
         x = query_tree(1, 0, N-1, st, en, &treee[0], &lazye[0]);
        if (x >= Inf)
            return vector<pair<int,int> >();

         px = pos[x];

         y = query_tree(1, 0, N-1, px+1, en, &treeo[0], &lazyo[0]);
         py = pos[y];
    } else {
        x = query_tree(1, 0, N-1, st, en, &treeo[0], &lazyo[0]);
        if (x >= Inf)
            return vector<pair<int,int> >();
        px = pos[x];

        y = query_tree(1, 0, N-1, px+1, en, &treee[0], &lazye[0]);
        py = pos[y];
    }




    if (px % 2 == 1) {
        update_tree(1, 0, N-1, px, px, Inf, &treeo[0], &lazyo[0]);
        update_tree(1, 0, N-1, py, py, Inf, &treee[0], &lazye[0]);
    } else {
        update_tree(1, 0, N-1, px, px, Inf, &treee[0], &lazye[0]);
        update_tree(1, 0, N-1, py, py, Inf, &treeo[0], &lazyo[0]);
    }

    vector<pair<int,int> > A = Solve(px+1, py-1, N);
    vector<pair<int,int> > B = Solve(st, en, N);


    vector<pair<int,int> > C;
    C.push_back(make_pair(x,y));
    int i=0;
    int j=0;
    while(i < A.size() || j < B.size()) {

        if (i==A.size()) {
            C.push_back(B[j]);
            j++;
        } else if (j==B.size()) {
            C.push_back(A[i]);
            i++;
        } else if (A[i].first<B[j].first) {
            C.push_back(A[i]);
            i++;
        } else {
            C.push_back(B[j]);
            j++;
        }
    }

    return C;
}

