    int l, r;
    int pos;
    bool operator <(const Data &other) const {
         return v[pos] > v[other.pos];
    }
};

std::priority_queue <Data> pq;


inline int check(int l, int r, int p) {
    p %= 2;
    int p2 = lg[r - l + 1];
    if(v[rmq[p][l][p2]] < v[rmq[p][r - (1 << p2) + 1][p2]])
       return rmq[p][l][p2];
    return rmq[p][r - (1 << p2) + 1][p2];
}

