    for(i = 1; i <= n; i++) {
        fscanf(fi,"%d" ,&v[i]);
        if(i % 2 == 1 && v[i] < min && i < n) {
           pos = i;
           min = v[i];
        }
    }
    for(i = 2; i <= n; i++)
        lg[i] = lg[i >> 1] + 1;
    v[0] = (1 << 30);
    for(i = 1; i <= n; i++)
        rmq[i & 1][i][0] = i;
    for(int p2 = 1; (1 << p2) <= n; p2++)
        for(i = 1; i + (1 << p2) <= n + 1; i++)
            for(int r = 0; r < 2; r++)
               if(v[rmq[r][i][p2 - 1]] < v[rmq[r][i + (1 << (p2 - 1))][p2 - 1]])
                  rmq[r][i][p2] = rmq[r][i][p2 - 1];
               else
                  rmq[r][i][p2] = rmq[r][i + (1 << (p2 - 1))][p2 - 1];
    pq.push({1, n, pos});
    while(!pq.empty()) {
         Data x = pq.top();
         pq.pop();
         pos = check(x.pos, x.r, x.l + 1);
         fprintf(fout,"%d %d " ,v[x.pos],v[pos]);
         if(x.l < x.pos - 1)
           pq.push({x.l, x.pos - 1, check(x.l, x.pos - 2, x.l)});
         if(x.pos + 1 < pos - 1)
           pq.push({x.pos + 1, pos - 1, check(x.pos + 1, pos - 2, x.pos + 1)});
         if(pos + 1 < x.r)
           pq.push({pos + 1, x.r, check(pos + 1, x.r - 1, pos + 1)});
    }
    //fclose(fi);
