void init(ll n) {
	n_ = 1;
	while (n_ <= n/2) {
		n_ <<= 1;
	}
	REP(i, 1, n_ * 2) tree[1][i] = tree[2][i] = INF;
	REP(i, 1, n) {
		if (i % 2 == 1) {
			tree[1][(i + 1) / 2 + n_] = p[i];
		}
		else {
			tree[2][i / 2 + n_] = p[i];
		}
	}
	for (ll i = n_ - 1; i >= 1; i--) {
		REP(j,1,2)	tree[j][i] = min(tree[j][i * 2], tree[j][i * 2 + 1]);
	}
}
ll query_o(ll i, ll a, ll b, ll k, ll l, ll r) {
	if (a <= l && r <= b) {
		return tree[i][k];
	}
	else if (b <= l || r <= a) {
		return INF;
	}
	else {
		ll ans1 = query_o(i, a, b, k * 2, l, (l + r) / 2);
		ll ans2 = query_o(i, a, b, k * 2 + 1, (l + r) / 2, r);
		return min(ans2, ans1);
	}
}
ll query(ll i, ll a, ll b) {
	if (a >= b) {
		return INF;
	}
	return query_o(i, a, b, 1, 0, n_);
}

ll query2(ll a, ll b) {
	a++;
	ll name;
	if (a % 2 == 1) {
		name = 1;
		return query(name, (a + 1) / 2, (b + 2) / 2);
	}
	else { 
		name = 2;
		return query(name, (a + 1) / 2, (b + 1) / 2);
	}
}

