inline node combine(node a, node b)
{
	if(b.best < a.best)
	{
		a.best = b.best;
		a.best_pos = b.best_pos;
	}
	if(mp(a.fi, b.se) < a.best)
	{
		a.best = mp(a.fi, b.se);
		a.best_pos = mp(a.fi_pos, b.se_pos);
	}
	if(b.fi < a.fi)
		a.fi = b.fi, a.fi_pos = b.fi_pos;
	if(b.se < a.se)
		a.se = b.se, a.se_pos = b.se_pos;
	return a;
}

inline void build(int v, int tl, int tr)
