			t[1][v].best_pos = mp(1e9, 1e9);
			t[1][v].fi = a[tl];
			t[1][v].fi_pos = tl;
			t[1][v].se = 1e9;
			t[1][v].se_pos = 1e9;
			t[0][v].best_pos = mp(1e9, 1e9);
			t[0][v].best = mp(1e9, 1e9);
			t[0][v].fi = 1e9;
			t[0][v].se = a[tl];
			t[0][v].fi_pos = 1e9;
			t[0][v].se_pos = tl;
		}
		return;
	}
	int tm = tl + tr >> 1;
	build(v + v, tl, tm);
	build(v + v + 1,tm + 1, tr);
	t[0][v] = combine(t[0][v + v], t[0][v + v + 1]);
	t[1][v] = combine(t[1][v + v], t[1][v + v + 1]);
}

inline node get(int id, int v, int tl, int tr, int l, int r)
{
	if(l > r) return big;
	if(tl == l && tr == r)
		return t[id][v];
	int tm = tl + tr >> 1;
	return combine(get(id, v + v, tl, tm, l, min(r, tm)), get(id, v + v + 1, tm + 1, tr, max(tm + 1, l), r)); 
}

