    for (int k=1;k<=maxbit;k++) {
        for (int i=1;i<=n;i++) {
            f2[i][k] = f2[i][k-1];
            if (i+pow2(k-1) <= n) f2[i][k] = min(f2[i][k],f2[i+pow2(k-1)][k-1]);
        }
    }
}

int fin(int s,int t) {
    if (s>t) return -1;
    int x;
    if (s%2==1) x = rmq_o(s,t);
    else x = rmq_e(s,t);
    return x;
}

void add(int s,int t) {
    if (s>t) return;
    int x = fin(s,t);
    heap.push(make_pair(-x,make_pair(s,t)));
}

