    }

    RMQi(int n) {
        N = 1;
        while (N < n)N *= 2;
        fill(dat, dat + 2 * N - 1, pii(INF, INF));
    }

    void update(int k, int a) {
        dat[k + N - 1] = pii(a, k);
        k += N - 1;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    pii query(int a, int b) {
        return query(a, b, 0, 0, N);
    }

    pii query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return pii(INF, INF);
        if (a <= l && r <= b) return dat[k];
        int m = (l + r) / 2;
        pii chl = query(a, b, 2 * k + 1, l, m);
        pii chr = query(a, b, 2 * k + 2, m, r);
        return min(chl, chr);
    }
};

int N;
int P[256 * 1024];
RMQi ki(128 * 1024);
RMQi gu(128 * 1024);

struct Sub {
    int l, r;
    bool k;
    int xi, yi;

    //[l,r)
    //k true xは奇数番目から false xは偶数番目から
    Sub(int l, int r, bool k) : l(l), r(r), k(k) {
        if (k) {
            xi = ki.query(l / 2, r / 2).SE * 2 + 1;
            yi = gu.query((xi + 1) / 2, (r + 1) / 2).SE * 2;
        } else {
            xi = gu.query(l / 2, r / 2).SE * 2;
            yi = ki.query((xi + 1) / 2, (r + 1) / 2).SE * 2 + 1;
        }
    }

    bool operator>(const Sub &o) const {
        return P[xi] > P[o.xi];
    }
};

priority_queue<Sub, vector<Sub>, greater<Sub>> que;

signed main() {
    cin >> N;
    rep(i, N) {
        cin >> P[i];
        if (i % 2 == 0) {
            gu.update(i / 2, P[i]);
        } else {
            ki.update(i / 2, P[i]);
        }
    }
    que.push(Sub(0, N, false));
    vector<int> ans;
    while (!que.empty()) {
        Sub sub = que.top();
        que.pop();
        ans.push_back(P[sub.xi]);
        ans.push_back(P[sub.yi]);
        if (sub.xi != sub.l) {
            que.push(Sub(sub.l, sub.xi, sub.k));
        }
        if (sub.yi != sub.xi + 1) {
            que.push(Sub(sub.xi + 1, sub.yi, !sub.k));
        }
        if (sub.yi != sub.r - 1) {
            que.push(Sub(sub.yi + 1, sub.r, sub.k));
        }
    }
    rep(i, ans.size()) {
        cout << (i ? " " : "") << ans[i];
    }
}

