struct segment_tree {
	int a[MAX], t[2*MAX];
	void build() {
		for(int i = 0; i < n; i++) t[i + n] = i;
		for(int i = n-1; i >= 1; i--) {
			if(a[t[i<<1]] < a[t[i<<1|1]]) t[i] = t[i<<1];
			else t[i] = t[i<<1|1];
		}
	}
	void invalidate(int i) {
		a[i] = INT_MAX;
		for(i += n; i > 1; i >>= 1) {
			if(a[t[i]] < a[t[i^1]]) t[i>>1] = t[i];
			else t[i>>1] = t[i^1];
		}
	}
	int query(int l, int r) {
		int ret = l;
		++r;
		for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if(l & 1) {
				if(a[t[l]] < a[ret]) ret = t[l];
				++l;
			}
			if(r & 1) {
				--r;
				if(a[t[r]] < a[ret]) ret = t[r];
			}
		}
		return ret;
	}
} st[2];

pii getxy(int l, int r) {
	int xi = st[l % 2].query(l, r);
	int yi = st[l % 2 ^ 1].query(xi+1, r);
	return make_pair(xi, yi);
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> n;
	fill(st[0].a, st[0].a+2*n, INT_MAX);
	fill(st[1].a, st[1].a+2*n, INT_MAX);
	for(int i = 0; i < n; i++) cin >> p[i], st[i % 2].a[i] = p[i];

	st[0].build();
	st[1].build();

	pq[make_pair(p[0], p[n-1])] = make_pair(getxy(0, n-1), make_pair(0, n-1));
	for(int l, r, xi, yi; !pq.empty(); ) {
		tie(xi, yi) = pq.begin()->second.first;
		tie(l, r) = pq.begin()->second.second;
		pq.erase(pq.begin());
		res.push_back(p[xi]);
		res.push_back(p[yi]);
		st[l % 2].invalidate(xi);
		st[l % 2 ^ 1].invalidate(yi);
		if(xi+1 < yi-1) pq[make_pair(p[xi+1], p[yi-1])] = make_pair(getxy(xi+1, yi-1), make_pair(xi+1, yi-1));
		if(l < xi-1) pq[make_pair(p[l], p[xi-1])] = make_pair(getxy(l, xi-1), make_pair(l, xi-1));
		if(yi+1 < r) pq[make_pair(p[yi+1], p[r])] = make_pair(getxy(yi+1, r), make_pair(yi+1, r));
	}
	for(int i = 0; i < n; i++) cout << res[i] << ' ';
}

