	}
	SMTBuild();
	INTERVAL beg;
	beg.L = 0, beg.R = n - 1, beg.mn = SMTQuery(0, 0, n - 1);
	PQ.push(beg);
	while (!PQ.empty())
	{
		//throw;
		INTERVAL curi = PQ.top();
		PQ.pop();
		Ans[cnt++] = curi.mn;
		Ans[cnt++] = SMTQuery(!(pos[curi.mn] & 1), pos[curi.mn] + 1, curi.R);
