pii rmq(int f, int t){
//    cout << "rmq(" << f<< " " <<t << ")=";
    assert((t - f) % 2 == 0);
    int p = 0;
    while(f + (1<< (p+1)) <= t)++p;
    assert(f + (1 << p) <= t);
    assert(f + (1 << (p+1)) > t);
    int f2 = t - (1 << p);
    if(rmq_[p-1][f2] < rmq_[p-1][f]){
        f = f2;
    }
    while(--p > 0){
        if(rmq_[p][f] != rmq_[p-1][f])f += (1<<p);
    }
//    cout << rmq_[0][f] << "," << f << endl;
    return mp(rmq_[0][f], f);
}

