void updata(int x, int no)
{  
    int lx, i;
    while (x <= n)  
    {  
        h[no][x] = a[no][x];
        lx = lowbit(x);  
        for (i=1; i<lx; i<<=1)
            h[no][x] = min(h[no][x], h[no][x-i]); 
        x += lowbit(x);
    }         
}  
int query(int x, int y, int no)  
{  
    int ans = INF;  
    while (y >= x)  
    {  
        ans = min(a[no][y], ans); 
        y --;  
        for (; y-lowbit(y) >= x; y -= lowbit(y))
            ans = min(h[no][y], ans);  
    }  
    return ans;  
}

struct pp{
	int x, y, l, r;

	pp(int x = 0, int y = 0, int l = 0, int r = 0):
		x(x), y(y), l(l), r(r) { }

	bool operator < (const pp &A)const{
		return x > A.x || (x == A.x && y > A.y);
	}
};

