using namespace std;

constexpr int N = 1 << 18;
constexpr int inf = 1e9;

struct RMQ {
  vector<pair<int, int>> rmq;

  RMQ() : rmq(N * 2, make_pair(inf, inf)) {}

  void update(int k, int v) {
    rmq[k + N] = {v, k};
    k += N;
    while (k > 1) {
      k >>= 1;
      rmq[k] = min(rmq[k * 2], rmq[k * 2 + 1]);
    }
  }

  int query(int l, int r) {
    l += N;
    r += N;
    pair<int, int> ret(inf, inf);
    while (l < r) {
      if (l & 1) ret = min(ret, rmq[l++]);
      if (r & 1) ret = min(ret, rmq[--r]);
      l >>= 1;
      r >>= 1;
    }
    return ret.second;
  }
};

struct SegTree {
  vector<int> lazy, dat;

  SegTree() : dat(N * 2), lazy(N * 2, -1) {}

  void push(int k, int l, int r) {
    if (lazy[k] != -1) {
      dat[k] = lazy[k];
      if (r - l > 1) {
        lazy[k * 2 + 0] = lazy[k];
        lazy[k * 2 + 1] = lazy[k];
      }
      lazy[k] = -1;
    }
  }

  void update(int a, int b, int v, int k = 1, int l = 0, int r = N) {
    push(k, l, r);
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      lazy[k] = v;
      push(k, l, r);
    } else {
      update(a, b, v, k * 2 + 0, l, (l + r) / 2);
      update(a, b, v, k * 2 + 1, (l + r) / 2, r);
    }
  }

  int query(int pos, int k = 1, int l = 0, int r = N) {
    push(k, l, r);
    if (r - l == 1) {
      return dat[k];
    }
    int m = l + r >> 1;
    if (pos < m) {
      return query(pos, k * 2 + 0, l, m);
    } else {
      return query(pos, k * 2 + 1, m, r);
    }
  }
};

int main() {
  int n;
  cin >> n;

  constexpr int inf = 1e9;

  RMQ odd, even;
  vector<int> a(n);
  vector<int> inv(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    a[i]--;
    if (i % 2 == 0) {
      even.update(i, a[i]);
    } else {
      odd.update(i, a[i]);
    }
    inv[a[i]] = i;
  }

  SegTree left, right;
  left.update(0, n, 0);
  right.update(0, n, n - 1);

  set<int> unused;
  for (int i = 0; i < n; i++) {
    unused.insert(i);
  }
  vector<int> ans;
  while (ans.size() < n) {
    auto it = unused.begin();
    for (; it != unused.end(); it++) {
      int x = inv[*it];
      int L = left.query(x);
      int R = right.query(x);

      if ((x - L) % 2 == 1) continue;
      if ((R - x) % 2 == 0) continue;

      if (x % 2 == 0) {
        int y = odd.query(x + 1, R + 1);
        if (a[y] == inf) continue;
        ans.push_back(a[x]);
        ans.push_back(a[y]);
        unused.erase(a[x]);
        unused.erase(a[y]);
        a[x] = inf;
        a[y] = inf;
        even.update(x, inf);
        odd.update(y, inf);

        left.update(x + 1, y, x + 1);
        left.update(y + 1, R + 1, y + 1);
        right.update(L, x, x - 1);
        right.update(x + 1, y, y - 1);

        break;
      } else {
        int y = even.query(x + 1, R + 1);
        if (a[y] == inf) continue;
        ans.push_back(a[x]);
        ans.push_back(a[y]);
        unused.erase(a[x]);
        unused.erase(a[y]);
        a[x] = inf;
        a[y] = inf;
        odd.update(x, inf);
        even.update(y, inf);

        left.update(x + 1, y, x + 1);
        left.update(y + 1, R + 1, y + 1);
        right.update(L, x, x - 1);
        right.update(x + 1, y, y - 1);

        break;
      }
    }
  }

  for (int i = 0; i < n; i++) {
    cout << ans[i] + 1 << ' ';
  }
}

