        Q.pop();
        int l = u.l, r = u.r, x = u.x, y = u.y;
        printf("%d %d ",a[x],a[y]);
        if (l < x - 1) 
            Q.push(get(l,x - 1));
        if (x + 1 < y - 1) 
            Q.push(get(x + 1, y - 1));
        if (y + 1 < r) 
            Q.push(get(y + 1, r));
    }
}

