const int MAX_N = 200005;
const int MAX_ELEMENTS = (1 << 17);
const int INF = (int)1e8;

template <typename T>
class SegmentTree {
public:
  int n;
  T dat[2 * MAX_ELEMENTS - 1];
  void init(int _n);
  void update(int k, T a);
  T query(int a, int b);
private:
  T query(int a, int b, int k, int l, int r);
};

template <typename T>
void SegmentTree<T>::init(int _n) {
  n = 1;
  while (n < _n) {
    n <<= 1;
  }
  for (int i = 0; i < 2 * n - 1; i++) {
    dat[i] = INF;
  }
  return;
}

template <typename T>
void SegmentTree<T>::update(int k, T a) {
  k += n - 1;
  dat[k] = a;
  while (k > 0) {
    k = (k - 1) / 2;
    dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
  }
  return;
}

template <typename T>
T SegmentTree<T>::query(int a, int b) {
  return query(a, b, 0, 0, n);
}

// [a, b), [l, r)
template <typename T>
T SegmentTree<T>::query(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l) {
    return INF;
  }
  if (a <= l && r <= b) {
    return dat[k];
  }
  return min(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
}


int N;
int p[MAX_N];
int at[MAX_N + 1];
SegmentTree<int> st[2];

vector<pii> check(int l, int r) {
    vector<pii> res, res1, res2, res3;
    int i1, i2, i3;
    int a, b;

    if (l >= r) {
        return res;
    }

    a = st[l % 2].query(l / 2, r / 2);
    b = st[(l + 1) % 2].query((max(l, at[a]) + 1) / 2, (r + 1) / 2);
    // cout << "a: " << a << endl;
    // cout << "b: " << b << endl;
    res.push_back(pii(a, b));
    res1 = check(l, at[a]);
    res2 = check(at[a] + 1, at[b]);
    res3 = check(at[b] + 1, r);

    i1 = i2 = i3 = 0;
    while (i1 < (int)res1.size() || i2 < (int)res2.size() || i3 < (int)res3.size()) {
        if (i1 >= (int)res1.size()) {
            if (i2 >= (int)res2.size()) {
                res.push_back(res3[i3]); i3++;
            } else if (i3 >= (int)res3.size()) {
                res.push_back(res2[i2]); i2++;
            } else {
                if (res2[i2] < res3[i3]) {
                    res.push_back(res2[i2]); i2++;
                } else {
                    res.push_back(res3[i3]); i3++;
                }
            }
        } else {
            if (i2 >= (int)res2.size()) {
                if (i3 >= (int)res3.size()) {
                    res.push_back(res1[i1]); i1++;
                } else if (res1[i1] < res3[i3]) {
                    res.push_back(res1[i1]); i1++;
                } else {
                    res.push_back(res3[i3]); i3++;
                }
            } else if (i3 >= (int)res3.size()) {
                if (res1[i1] < res2[i2]) {
                    res.push_back(res1[i1]); i1++;
                } else {
                    res.push_back(res2[i2]); i2++;
                }
            } else {
                if (res1[i1] < res2[i2]) {
                    if (res1[i1] < res3[i3]) {
                        res.push_back(res1[i1]); i1++;
                    } else {
                        res.push_back(res3[i3]); i3++;
                    }
                } else {
                    if (res2[i2] < res3[i3]) {
                        res.push_back(res2[i2]); i2++;
                    } else {
                        res.push_back(res3[i3]); i3++;
                    }
                }
            }
        }
    }

    // cout << "check(" << l << ", " << r << ")" << endl;
    // for (int i = 0; i < (int)res.size(); i++) {
    //     cout << res[i].first << ' ' << res[i].second << (i == (int)res.size() - 1 ? '\n' : ' ');
    // }

    return res;
}

