using Pi = pair<int, int>;
using Tapris = tuple<int, int, int>;
using vint = vector<int>;

const int inf = 1LL << 55;
const int mod = 1e9 + 7;

struct SegmentTree {
  vector<Pi> data;
  int n, sz;
  SegmentTree(const vint& a) {
    n = a.size();
    sz = 1; while(sz < n) sz <<= 1;
    data.resize(2*sz-1, Pi(inf, inf));
    rep(i, n) data[i+sz-1] = Pi(a[i], i);
    for(int i = sz-2; i >= 0; --i) data[i] = min(data[2*i+1], data[2*i+2]);
  }
  Pi query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return Pi(inf, inf);
    if(a <= l && r <= b) return data[k];
    Pi vl = query(a, b, 2*k+1, l, (l+r)/2);
    Pi vr = query(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }
  Pi query(int a, int b) {
    return query(a, b, 0, 0, sz);
  }
};

