      odd.push_back(p);
      even.push_back(inf);
    } else {
      odd.push_back(inf);
      even.push_back(p);
    }
  }
  SegmentTree eseg(even), oseg(odd);

  priority_queue<Tapris, vector<Tapris>, greater<Tapris> > que;

  function<void(int, int, int, bool)> dfs = [&](int l, int r, int d, bool ok) {
    if(l+1 >= r) return;
    Pi p = eseg.query(l, r);
    Pi q = oseg.query(l, r);
    if(!ok) swap(p, q);
    que.emplace(d, p.first, q.first);
    //cout<<d<<" "<<l<<" "<<r<<" "<<p.second<<" "<<q.second<<endl;
    dfs(l, min(p.second, q.second), d+1, ok);
    dfs(min(p.second, q.second)+1, max(p.second, q.second), d+1, !ok);
    dfs(max(p.second, q.second)+1, r, d+1, ok);
  };
  dfs(0, n, 0, true);
  vint ans;
  while(!que.empty()) {
    Tapris p = que.top(); que.pop();
    int a, b, c;
    tie(a, b, c) = p;
    ans.push_back(b);
    ans.push_back(c);
  }
  rep(i, ans.size()) cout << ans[i] << " \n"[i==(int)ans.size()-1];

  return 0;
}

