const ll MAXN = 2e5 + 20;
const ll INF = 8e18;
const ll MOD = 1e9 + 7;
ll mn[2][MAXN << 2], A[MAXN], pos[MAXN], n;
priority_queue<pair<pll, pll>, vector<pair<pll, pll>>, greater<pair<pll, pll>>> pq;

void build(ll id = 1, ll l = 0, ll r = MAXN) {
	if (r - l == 1) {
		mn[l & 1][id] = A[l];
		mn[(l & 1) ^ 1][id] = INF;
		return;
	}
	ll mid = (l + r) >> 1;
	build(lc, l, mid);
	build(rc, mid, r);
	for (ll i = 0; i < 2; i++) {
		mn[i][id] = min(mn[i][rc], mn[i][lc]);
	}
}

ll get(ll t, ll ql, ll qr, ll id = 1, ll l = 0, ll r = MAXN) {
	if (qr <= l || r <= ql) return INF;
	if (ql <= l && r <= qr) {
		return mn[t][id];
	}
	ll mid = (l + r) >> 1;
	return min(get(t, ql, qr, lc, l, mid), get(t, ql, qr, rc, mid, r));
}

pll get(ll ql, ll qr) {
	ll x = get(ql & 1, ql, qr);
	return {x, get(1 - (ql & 1), pos[x], qr)};
}

void update(ll l, ll r) {
	if (r <= l + 1) return;
	pq.push({get(l, r), {l, r}});
}

