struct interval {
    int l,r;
    pii mn;
    bool operator < (interval x) const{
        return mn.f > x.mn.f;
    }
};

void build(int i, int l, int r){
    if(l == r){
        tree[l&1][i] = mp(a[l], l);
        return;
    }
    int mid = (l+r)/2;
    build(2*i, l, mid);
    build(2*i+1, mid+1, r);
    tree[0][i] = min(tree[0][2*i], tree[0][2*i+1]);
    tree[1][i] = min(tree[1][2*i], tree[1][2*i+1]);
}

pii query(int i, int start, int end, int l, int r, bool parity){
    if(l <= start && r >= end) return tree[parity][i];
    if(r < start || l > end) return mp(infi,infi);
    int mid = (start+end)/2;
    return min(query(2*i,start,mid,l,r,parity), query(2*i+1,mid+1,end,l,r,parity));
}

