        if(nxt.s > curr.mn.s+1) q.push({curr.mn.s+1, nxt.s-1, query(1,1,n, curr.mn.s+1, nxt.s-1, (curr.mn.s+1)&1)});
        if(nxt.s < curr.r) q.push({nxt.s+1, curr.r, query(1,1,n, nxt.s+1, curr.r, (nxt.s+1)&1)});
    }

    lp(i,1,n) printf("%d ", ans[i]);
}

