class ITmin {
private:
	ii f[4 * N];
public:
	ITmin() {
		memset(f, 127, sizeof(f));
	}
	void update(int k, int l, int r, int pos, int val) {
		if (r < pos || pos < l) return;
		if (pos == l && r == pos) {
			f[k].fi = val; f[k].se = l;
			return;
		}
		int mid = (l + r) / 2;
		update(k * 2, l, mid, pos, val); update(k * 2 + 1, mid + 1, r, pos, val);
		f[k] = min(f[k * 2], f[k * 2 + 1]);
	}
	ii get(int k, int l, int r, int L, int R) {
		if (r < L || R < l) return mp(1e9, 0);
		if (L <= l && r <= R) return f[k];
		int mid = (l + r) / 2;
		return min(get(k * 2, l, mid, L, R), get(k * 2 + 1, mid + 1, r, L, R));
	}
};

int n;
int a[N];
ii lab[N];
vector<vector<int> > e(N);
int peak = 0;
ITmin odd, even;

ii findsec(int l, int r) {
	if (l % 2 == 1) {
		ii rec = odd.get(1, 1, n, l, r);
		return rec;
	}
	else {
		ii rec = even.get(1, 1, n, l, r);
		return rec;
	}
}

void solve(int l, int r) {
	ii fin;
	if (l % 2 == 1)
		fin = odd.get(1, 1, n, l, r);
	else {
		fin = even.get(1, 1, n, l, r);
	}
	ii sen = findsec(fin.se + 1, r);
	lab[++peak] = mp(fin.fi, sen.fi);
	int node = peak;
	if (fin.se != l) {
		e[node].push_back(peak + 1);
		solve(l, fin.se - 1);
	}
	if (fin.se + 1 < sen.se) {
		e[node].push_back(peak + 1);
		solve(fin.se + 1, sen.se - 1);
	}
	if (sen.se != r) {
		e[node].push_back(peak + 1);
		solve(sen.se + 1, r);
	}
}

vector<int> ans;
priority_queue<pair<ii, int> , vector<pair<ii, int> >, greater<pair<ii, int> > > pq;
#define make(a,b,c) mp(mp(a,b),c)
void cal() {
	pq.push(make(lab[1].fi, lab[1].se, 1));
	while (!pq.empty()) {
		pair<ii, int> u = pq.top(); pq.pop();
		ans.push_back(u.fi.fi); ans.push_back(u.fi.se);
		for (int i = 0; i < e[u.se].size(); i++) {
			int v = e[u.se][i];
			pq.push(make(lab[v].fi, lab[v].se, v));
		}
	}
	cout << ans << endl;
}

