void build(int id, int l, int r) {
    if (l == r) {
        oddmin[id] = l;
        evenmin[id] = -1;
        return;
    }

    int mid = (l + r) >> 1;
    build(L, l, mid);
    build(R, mid + 1, r);

    if ((mid - l) % 2) {
        if (p[oddmin[L]] < p[oddmin[R]]) {
            oddmin[id] = oddmin[L];
        } else {
            oddmin[id] = oddmin[R];
        }

        if (evenmin[L] == -1) {
            evenmin[id] = evenmin[R];
        } else {
            if (evenmin[R] == -1 || p[evenmin[L]] < p[evenmin[R]]) {
                evenmin[id] = evenmin[L];
            } else {
                evenmin[id] = evenmin[R];
            }
        }
    } else {
        if (evenmin[R] == -1 || oddmin[L] < evenmin[R]) {
            oddmin[id] = oddmin[L];
        } else {
            oddmin[id] = evenmin[R];
        }

        if (evenmin[L] == -1 || oddmin[R] < evenmin[L]) {
            evenmin[id] = oddmin[R];
        } else {
            evenmin[id] = evenmin[L];
        }
    }
}

int query(int id, int l, int r, int ql, int qr) {
    if (l > qr || r < ql) return -1;

    bool tmp = ((l - ql) % 2 == 0);

    if (l >= ql && r <= qr) {
        return tmp ? oddmin[id] : evenmin[id];
    }

    int mid = (l + r) >> 1;

    int res1 = query(L, l, mid, ql, qr);
    int res2 = query(R, mid + 1, r, ql, qr);

    if (res1 == -1) return res2;
    if (res2 == -1) return res1;
    if (p[res1] < p[res2]) {
        return res1;
    } else {
        return res2;
    }
}

int main() {
    cin >> n;
    for (int i = 0; i < n; ++i) {
        scanf("%d", p + i);
    }

    build(1, 0, n - 1);

    set<pii> foo;
    foo.insert({0, n - 1});

    int cur = 0;
    while (!foo.empty()) {
        auto cand = foo.begin();
        int ind = query(1, 0, n - 1, (*foo.begin()).fi, (*foo.begin()).se);

        for (auto it = next(foo.begin()); it != foo.end(); ++it) {
            int bar = query(1, 0, n - 1, (*it).fi, (*it).se);
            if (p[bar] < p[ind]) {
                cand = it;
                ind = bar;
            }
        }

        pii tmp = *cand;
        foo.erase(cand);
        int another = query(1, 0, n - 1, ind + 1, tmp.se);
        if (ind - 1> tmp.fi) {
            foo.insert({tmp.fi, ind - 1});
        }
        if (ind + 1 < another) {
            foo.insert({ind + 1, another - 1});
        }
        if (another < tmp.se) {
            foo.insert({another + 1, tmp.se});
        }

        q[cur++] = p[ind];
        q[cur++] = p[another];
    }

    for (int i = 0; i < n; ++i) {
        printf("%d%c", q[i], " \n"[i == n - 1]);
    }

    return 0;
}

