using pii=pair<int, int>;

struct Data{
   int v;
   pii s;
   Data(int vv, pii ss){v=vv; s=ss;}
};

bool operator<(const Data &l, const Data &r){
   return l.v<r.v;
}

struct SegmentTree{

   int sz;
   const int inf=1e9;
   vector<pii> seg;
   SegmentTree(vector<int>& a, int od){
      sz=1;
      while(sz*2<=a.size()) sz*=2;
      seg.resize(2*sz-1, {inf, -1});
      repeat(i, sz){
         if((i+od)%2==1) seg[i+sz-1]={a[i], i};
         else seg[i+sz-1]={inf, i};
      }
      for(int i=sz-2; i>=0; i--){
         seg[i]=mrg(seg[2*i+1], seg[2*i+2]);
      }
   }

   pii mrg(pii l, pii r){
      pii rt;
      rt.first=min(l.first, r.first);
      rt.second=(l.first<r.first?l.second:r.second);
      return rt;
   }

   pii mi(int a, int b, int i, int l, int r){
      if(a<=l and r<=b){
         return seg[i];
      }else if(b<=l or r<=a){
         return {inf, -1};
      }else{
         int m=(r+l)/2;
         auto vl=mi(a, b, 2*i+1, l, m);
         auto vr=mi(a, b, 2*i+2, m, r);
         return mrg(vl, vr);
      }
   }

   pii mi(int a, int b){
      return mi(a, b, 0, 0, sz);
   }

   void out(){
      repeat(i, sz){
         cout<< seg[i+sz-1].first<< " ";
      }cout<< endl;
   }

};

int main(){

   int N; cin>> N;
   vector<int> a(N);
   repeat(i, N) cin>> a[i], a[i]--;

   set<Data> S;
   S.insert(Data{-1, {0, N}});
   vector<int> q;
   SegmentTree od(a, 1), ev(a, 0);

   int c=0;
   while(not S.empty()){
      assert(c++<=10000000);
      int v=(*S.begin()).v;
      auto ij=(*S.begin()).s;
      int i=ij.first, j=ij.second;
      S.erase(S.begin());
      pii e, e2;
      if(i%2==0){
         e=od.mi(i, j);
         e2=ev.mi(e.second, j);
      }else{
         e=ev.mi(i, j);
         e2=od.mi(e.second, j);
      }
      q.push_back(e.first); q.push_back(e2.first);
      if(i<e.second){
