int rmq_loc (int x, int y)
{
    int ans = x;
    for (int i = x; i < y; i += 2)
        if (arr[i] < arr[ans])
            ans = i;
    return ans;
}

priority_queue <pair <int, pair <int, int> > > pq;
vector <int> ans;

void add_range (int lo, int hi)
{
    int clo = rmq_loc (lo, hi);
    pq.push(make_pair (-arr[clo], make_pair (lo, hi)));
}

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N;
    for (int i = 0; i < N; i++)
    {
        cin >> arr[i];
        oloc[arr[i]] = i;
    }

    add_range (0, N);
    while (!pq.empty())
    {
        int lo = pq.top().second.first;
        int hi = pq.top().second.second;
        pq.pop();

        int clo = rmq_loc (lo, hi);
        int clo2 = rmq_loc (clo + 1, hi + 1);
        ans.push_back(arr[clo]);
        ans.push_back(arr[clo2]);

        if (clo > lo)
            add_range (lo, clo);
        if (clo2 > clo + 1)
            add_range (clo + 1, clo2);
        if (hi > clo2 + 1)
            add_range (clo2 + 1, hi);
    }

    for (int i = 0; i < ans.size(); i++)
    {
        if (i) cout << " ";
        cout << ans[i];
    }
