pii query(pii tree[],int l,int r,int pos,int l1,int r1)
{
    if (l>=l1&&r<=r1){
        return tree[pos];
    }
    int mid=(l+r)>>1;
    pii ret=mp(inf,inf);
    if (mid>=l1)ret=query(tree,lson,l1,r1);
    if (mid+1<=r1)ret=min(ret,query(tree,rson,l1,r1));
    return ret;
}
void push_up(pii tree[],int pos)
{
    tree[pos]=min(tree[pos<<1],tree[pos<<1|1]);
}
void upd(pii tree[],int l,int r,int pos,int x,int v)
{
    if (l==r){
        tree[pos].fi=v;
        tree[pos].se=x;
        return ;
    }
    int mid=(l+r)>>1;
    if (mid>=x)upd(tree,lson,x,v);
    else upd(tree,rson,x,v);
    push_up(tree,pos);
}
