template<class T>
struct SegTree
{
	lint n;
	vector<T> t;
	T neutral;

	SegTree(lint _n, const T& _neutral) : neutral(_neutral)
	{
		n = 1;
		while (n < _n)
		{
			n *= 2;
		}
		rep(i, n)
		{
			t.resize(2 * n, neutral);
		}
	}

	using funcT = T(T val1, T val2);
	funcT* un;

	void update(lint i, const T& val)
	{
		i += n - 1;
		t[i] = val;
		while (i > 0)
		{
			i = (i - 1) / 2;
			t[i] = un(t[i * 2 + 1], t[i * 2 + 2]);
		}
	}

	T query_impl(lint a, lint b, lint k, lint l, lint r)
	{
		if (r <= a || b <= l)
			return neutral;
		if (a <= l && r <= b)
			return t[k];
		else
		{
			const T c1 = query_impl(a, b, 2 * k + 1, l, (l + r) / 2);
			const T c2 = query_impl(a, b, 2 * k + 2, (l + r) / 2, r);
			return un(c1, c2);
		}
	}

	T query(lint l, lint r)
	{
		return query_impl(l, r, 0, 0, n);
	}

};

int main()
{
	lint n;
	cin >> n;
	vec p(n);
	rep(i, n)
		cin >> p[i];

	set<lint> zp;
	zp.insert(0);
	zp.insert(n);

	SegTree<xy> tra(n, xy(-1, inf)), trb(n, xy(-1, inf));
	tra.un = [](xy p, xy q)
	{
		lint ps = p.x, qs = q.x;

		xy ans{ -1,inf };

		if (ps % 2 == 0)
		{
			if (p.y < ans.y)
				ans = p;
		}
		if (qs % 2 == 0)
		{
			if (q.y < ans.y)
				ans = q;
		}

		return ans;
	};
	trb.un = [](xy p, xy q)
	{
		lint ps = p.x, qs = q.x;

		xy ans{ -1,inf };

		if (ps % 2 == 1)
		{
			if (p.y < ans.y)
				ans = p;
		}
		if (qs % 2 == 1)
		{
			if (q.y < ans.y)
				ans = q;
		}

		return ans;
	};
	rep(i, n)
	{
		tra.update(i, xy(i, p[i]));
		trb.update(i, xy(i, p[i]));
	}

	vec ans;

	struct R
	{
		lint l, r;
		lint s;
		lint val;
		bool operator<(const R& o) const
		{
			return val > o.val;
		}
	};

	priq<R> q;
	q.push(R{ 0, n, 0, tra.query(0, n).y });
	rep(i, n / 2)
	{
		auto r = q.top();
		q.pop();

		if (r.s == 0)
		{
			auto a1 = tra.query(r.l, r.r);
			auto a2 = trb.query(a1.x + 1, r.r);

			ans.push_back(a1.y);
			ans.push_back(a2.y);

			q.push(R{ r.l, a1.x, r.s, tra.query(r.l, a1.x).y });
			q.push(R{ a1.x + 1, a2.x, (r.s + 1) % 2, trb.query(a1.x + 1, a2.x).y });
			q.push(R{ a2.x + 1, r.r, r.s, tra.query(a2.x + 1, r.r).y });
		}
		else
		{
			auto a1 = trb.query(r.l, r.r);
			auto a2 = tra.query(a1.x + 1, r.r);

			ans.push_back(a1.y);
			ans.push_back(a2.y);

			q.push(R{ r.l, a1.x, r.s, trb.query(r.l, a1.x).y });
			q.push(R{ a1.x + 1, a2.x, (r.s + 1) % 2, tra.query(a1.x + 1, a2.x).y });
			q.push(R{ a2.x + 1, r.r, r.s, trb.query(a2.x + 1, r.r).y });
		}
	}

	rep(i, n)
		cout << ans[i] << spacel(i, n);

	return 0;
}

