const int N = 2e5 + 10, M = 20, INF = ~0u >> 2;
int n, a[N], lg2[N];
std::pair<int, int> ST1[N][M], ST2[N][M];

inline void init() {
    for (int i = 0; (1 << i) < N; i++)
        lg2[1 << i] = i;
    for (int i = 0; i < N; i++)
        if (!lg2[i])
            lg2[i] = lg2[i - 1];

    for (int i = 1; i <= n; i += 2) {
        ST1[i][0] = std::make_pair(a[i], i);
        ST2[i][0] = std::make_pair(INF, i);
    }
    for (int i = 2; i <= n; i += 2) {
        ST2[i][0] = std::make_pair(a[i], i);
        ST1[i][0] = std::make_pair(INF, i);
    }
    for (int j = 1; (1 << j) <= n; j++)
        for (int i = 1; i + (1 << j) - 1 <= n; i++) {
            ST1[i][j] = std::min(ST1[i][j - 1], ST1[i + (1 << (j - 1))][j - 1]);
            ST2[i][j] = std::min(ST2[i][j - 1], ST2[i + (1 << (j - 1))][j - 1]);
        }
}

inline std::pair<int, int> query1(int l, int r) {
    static int len, k;
    len = r - l + 1;
    k = lg2[len];
    return std::min(ST1[l][k], ST1[r - (1 << k) + 1][k]);
}

inline std::pair<int, int> query2(int l, int r) {
    static int len, k;
    len = r - l + 1;
    k = lg2[len];
    return std::min(ST2[l][k], ST2[r - (1 << k) + 1][k]);
}

inline std::list<std::pair<int, int>>* process(int l, int r) {
    auto ans = new std::list<std::pair<int, int>>;
    if (l > r)
        return ans;
    int p1, p2;
    if (l & 1) {
        p1 = query1(l, r).second;
        p2 = query2(p1 + 1, r).second;
    } else {
        p1 = query2(l, r).second;
        p2 = query1(p1 + 1, r).second;
    }
    ans -> emplace_back(a[p1], a[p2]);
    auto v1 = process(l, p1 - 1), v2 = process(p1 + 1, p2 - 1), v3 = process(p2 + 1, r);
    if (v1 -> empty() && v2 -> empty()) {
        delete v1;
        delete v2;
        delete ans;
        v3 -> emplace_front(a[p1], a[p2]);
        return v3;
    }
    if (v2 -> empty() && v3 -> empty()) {
        delete v2;
        delete v3;
        delete ans;
        v1 -> emplace_front(a[p1], a[p2]);
        return v1;
    }
    if (v3 -> empty() && v1 -> empty()) {
        delete v3;
        delete v1;
        delete ans;
        v2 -> emplace_front(a[p1], a[p2]);
        return v2;
    }
    auto it1 = v1 -> begin(), it2 = v2 -> begin(), it3 = v3 -> begin();
    while (true) {
        if (it1 != v1 -> end() && (it2 == v2 -> end() || *it1 < *it2) && (it3 == v3 -> end() || *it1 < *it3)) {
            ans -> push_back(*it1);
            it1++;
        } else if (it2 != v2 -> end() && (it3 == v3 -> end() || *it2 < *it3)) {
            ans -> push_back(*it2);
            it2++;
        } else if (it3 != v3 -> end()) {
            ans -> push_back(*it3);
            it3++;
        } else {
            break;
        }
    }
    delete v1;
    delete v2;
    delete v3;
    return ans;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
        scanf("%d", a + i);
    init();

    auto ans = process(1, n);
    for (auto it = ans -> begin(); it != ans -> end(); it++)
        printf("%d %d ", it -> first, it -> second);
    putchar('\n');

    return 0;
}

