#include <bits/stdc++.h>
#define ls (o << 1)
#define rs (o << 1 | 1)
using namespace std;

const int inf = 1 << 30;

int a[200005], n;

struct Seg {
    int l, r;
    pair <int, int> v[2];
    bool lz;
} T[800005];

void push_up(int o) {
    for (int i = 0; i < 2; ++i)
        T[o].v[i] = min(T[ls].v[i], T[rs].v[i]);
}

void rev(int o) {
    T[o].lz ^= 1;
    swap(T[o].v[0], T[o].v[1]);
}

void push_down(int o) {
    if (!T[o].lz)
        return;
    rev(ls);
    rev(rs);
    T[o].lz = 0;
}

void build(int o, int l, int r) {
    T[o].l = l; T[o].r = r;
    T[o].lz = 0;
    if (l == r) {
        T[o].v[0] = T[o].v[1] = {inf, l};
        T[o].v[l & 1] = {a[l], l};
    } else {
        int m = (l + r) >> 1;
        build(ls, l, m);
        build(rs, m + 1, r);
        push_up(o);
    }
}

void del(int o, int x) {
    if (T[o].l == T[o].r) {
        T[o].v[0] = T[o].v[1] = {inf, x};
        return;
    }
    push_down(o);
    int m = (T[o].l + T[o].r) >> 1;
    del(x <= m ? ls : rs, x);
    push_up(o);
}

pair <int, int> query(int o, int l, int r, int x) {
    if (T[o].l == l && T[o].r == r)
        return T[o].v[x];
    push_down(o);
    int m = (T[o].l + T[o].r) >> 1;
    if (r <= m)
        return query(ls, l, r, x);
    if (l > m)
        return query(rs, l, r, x);
    pair <int, int> a = query(ls, l, m, x), b = query(rs, m + 1, r, x);
    return min(a, b);
}

void update(int o, int l, int r) {
    if (T[o].l == l && T[o].r == r) {
        rev(o);
        return;
    }
    int m = (T[o].l + T[o].r) >> 1;
    if (r <= m)
        update(ls, l, r);
    else if(l > m)
        update(rs, l, r);
    else {
        update(ls, l, m);
        update(rs, m + 1, r);
    }
    push_up(o);
}

