        r=pq.top().ff;
        e=pq.top().ss;
        pq.pop();
        w=query(1,0,n-1,r+1,e);
        ans.pb(v[r]);
        ans.pb(v[w]);
        solve(r+1,w-1);
        solve(w+1,e);
    }
}


