				mp b = even.range_min(a.second+1,parent_range.r);
				Q.push({b.first,b.second,a.second+1,parent_range.r});
			}
			ans=ans+to_string(parent_range.v)+" "+to_string(a.first)+" ";
		}else{
			if(parent_range.pos!=parent_range.l){//左があるか
				mp a = odd.range_min(parent_range.l,parent_range.pos);
				Q.push({a.first,a.second,parent_range.l,parent_range.pos});
			}
			mp a = even.range_min(parent_range.pos+1,parent_range.r);
