long long GCD(long long a, long long b){return b == 0 ? a : GCD(b, a % b);}
long long fast_exp(long long base, long long exp) {
    long long tot = 1;
    for(;exp > 0;exp >>= 1) {
       if((exp & 1) == 1) tot = tot * base % MOD;
       base = base * base % MOD;
    }
    return tot;
}

int n;

int interval = 500;
pair<int, int> buckets[500][2];
int arr[200005];

void update(int value, int position){

    arr[position] = value;

    int parity = position % 2;

    int left = position / interval * interval;
    int right = min(n, left + interval);

    buckets[left / interval][parity] = make_pair(1e9, 1e9);

    for(int pos = left; pos < right; ++pos){
        if(pos % 2 == parity)
            buckets[pos / interval][parity] = min(buckets[pos / interval][parity], make_pair(arr[pos], pos));
    }

}

pair<int, int> query(int left, int right, int parity){

    pair<int, int> best = make_pair(1e9, 1e9);

    for(;left % interval > 0 && left < right; ++left)
        if(left % 2 == parity)
            best = min(best, make_pair(arr[left], left));

    while(left + interval < right){
        best = min(best, buckets[left / interval][parity]);
        left += interval;
    }

    for(;left < right; ++left)
        if(left % 2 == parity)
            best = min(best, make_pair(arr[left], left));

    return best;

}

void init(){
    for(int i = 0; i < n; ++i)
        update(arr[i], i);
}

