        while ((1 << b) <= v.size()) ++b;
        st.assign(b, vector<pa>(1 << b));
        for (int i = 0; i < v.size(); i++) st[0][i] = {v[i], i};
        for (int i = 1; i < b; i++) {
            for (int j = 0; j + (1 << i) <= (1 << b); j++) {
                st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
            }
        }

        lookup.resize(v.size() + 1);
        for (int i = 2; i < lookup.size(); i++) {
            lookup[i] = lookup[i >> 1] + 1;
        }
    }

    inline pa rmq(int l, int r) {
        int b = lookup[r - l];
        return min(st[b][l], st[b][r - (1 << b)]);
    }
};

vector<int> p;
vector<SparseTable> tables;

void marge(deque<pa> &x, deque<pa> &y) {
    deque<pa> ret;
    while (!(x.empty() && y.empty())) {
        if (x.empty())ret.push_back(y.front()), y.pop_front();
        else if (y.empty())ret.push_back(x.front()), x.pop_front();
        else {
            if (x.front() < y.front())ret.push_back(x.front()), x.pop_front();
            else ret.push_back(y.front()), y.pop_front();
        }
    }
    x = ret;
}

deque<pa> solve(int x, int y) {
    auto fi = tables[x % 2].rmq(x, y);
    auto se = tables[(x + 1) % 2].rmq(fi.second + 1, y);
    pa minValue = {fi.first, se.first}, minIndex{fi.second, se.second};

    deque<pa> ret;
    if (x != minIndex.first) {
        auto tmp = solve(x, minIndex.first);
        marge(ret, tmp);
    }
    if (minIndex.first + 1 != minIndex.second) {
        auto tmp = solve(minIndex.first + 1, minIndex.second);
        marge(ret, tmp);
    }
    if (minIndex.second + 1 != y) {
        auto tmp = solve(minIndex.second + 1, y);
        marge(ret, tmp);
    }
    ret.push_front(minValue);
    return ret;
}

