void push_up(int x)
{
    mn1[x]=min(mn1[x<<1],mn1[x<<1|1]);
    mn2[x]=min(mn2[x<<1],mn2[x<<1|1]);
}
void push_down(int x)
{
    if(lazy[x])
    {
        int l=x*2,r=x*2+1;
        lazy[l]^=1;lazy[r]^=1;
        lazy[x]^=1;
        swap(mn1[l],mn2[l]);
        swap(mn1[r],mn2[r]);
    }
    return ;
}
void build(int x,int l,int r)
{
    if(l==r)
    {
        if(l%2==1)mn1[x]=a[l],mn2[x]=inf;
        else mn1[x]=inf,mn2[x]=a[l];
        return ;
    }
    int mid=(l+r)>>1;
    build(ls);build(rs);
    push_up(x);
}
int qur(int x,int l,int r,int ll,int rr,int op)
{
    if(ll<=l&&rr>=r)
    {
        if(op==1)return mn1[x];
        return mn2[x];
    }
    int mid=(l+r)>>1;
    push_down(x);
    if(ll>mid)return qur(rs,ll,rr,op);
    if(rr<=mid)return qur(ls,ll,rr,op);
    return min(qur(ls,ll,rr,op),qur(rs,ll,rr,op));
}
void del(int x,int l,int r,int pos)
{
    if(l==r){mn1[x]=mn2[x]=inf;return ;}
    int mid=(l+r)>>1;
    push_down(x);
    if(pos<=mid)del(ls,pos);
    else del(rs,pos);
    push_up(x);
}
void rev(int x,int l,int r,int ll,int rr)
{
    if(ll<=l&&rr>=r)
    {
        lazy[x]^=1;
        swap(mn1[x],mn2[x]);
        return ;
    }
    int mid=(l+r)>>1;
    push_down(x);
    if(ll<=mid)rev(ls,ll,rr);
    if(rr>mid)rev(rs,ll,rr);
    push_up(x);
}
