using namespace std;
typedef pair<int, int> P;

const int DEPTH = 17;
const int INF = 11451419;
class SegTree {
	int data[1 << (DEPTH + 1)];
public:
	SegTree() {
		for (int i = 0; i < (1 << DEPTH); i++) update(i, INF);
		data[(1 << (DEPTH + 1)) - 1] = INF;
	}
	void update(int pos, int x) {
		pos = pos + (1 << DEPTH) - 1;
		data[pos] = x;
		pos = (pos - 1) / 2;
		if (data[pos * 2 + 1] < data[pos * 2 + 2]) { data[pos] = pos * 2 + 1 - (1 << DEPTH) + 1; }
		else { data[pos] = pos * 2 + 2 - (1 << DEPTH) + 1; }
		while (pos > 0) {
			pos = (pos - 1) / 2;
			if (getNum(data[pos * 2 + 1]) < getNum(data[pos * 2 + 2])) { data[pos] = data[pos * 2 + 1]; }
			else { data[pos] = data[pos * 2 + 2]; }
		}
	}
	int getPos(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) { return (1 << DEPTH); }
		if (l <= a && b <= r) { if (id >= (1 << DEPTH) - 1) return id - (1 << DEPTH) + 1; return data[id]; }
		int u = getPos(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int v = getPos(l, r, a + (b - a) / 2, b, id * 2 + 2);
		if (getNum(u) < getNum(v)) return u;
		return v;
	}
	int getNum(int id) {
		return data[id + (1 << DEPTH) - 1];
	}
};

int n;
int p[200000];
SegTree rmq[2];

//[l, r)で問題を解く
vector<P> dfs(int l, int r) {
	if (l >= r) { return vector<P>(); }
	int posX = rmq[l % 2].getPos(l / 2, (r + 1) / 2);
	int posY = rmq[(l + 1) % 2].getPos(posX + (l % 2), (r + 1) / 2);
	vector<P> res[3];
	res[0] = dfs(l, posX * 2 + (l % 2));
	res[1] = dfs(posX * 2 + (l % 2) + 1, posY * 2 + ((l + 1) % 2));
	res[2] = dfs(posY * 2 + ((l + 1) % 2) + 1, r);

	vector<P> res2;
	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < res[i].size(); j++) {
			res2.push_back(res[i][j]);
		}
	}
	sort(res2.begin(), res2.end());

	vector<P> ret;
	ret.push_back(P(rmq[l % 2].getNum(posX), rmq[(l + 1) % 2].getNum(posY)));
	for (int i = 0; i < res2.size(); i++) { ret.push_back(res2[i]); }
	return ret;
}

