vector<P> dfs(int l, int r){
    if(r <= l)return vector<P>(0);
    if(r-l == 2){return {P(p[l], p[l+1])};}

    auto lmin = (l%2)? sg[1].query(l, r) : sg[0].query(l, r);
    int li = lmin.second;
    auto rmin = (l%2)? sg[0].query(li+1, r) : sg[1].query(li+1, r);
    int ri = rmin.second;

    auto a = dfs(l, li);
    auto b = dfs(li+1, ri);
    auto c = dfs(ri+1, r);

    vector<P> res;
    zep(i, 0, a.size())res.push_back(a[i]);
    zep(i, 0, b.size())res.push_back(b[i]);
    zep(i, 0, c.size())res.push_back(c[i]);
    sort(res.begin(), res.end());

    res.insert(res.begin(), P(lmin.first, rmin.first));
    return res;
}

