int Max[maxn << 2],Max2[maxn<<2];
void push_up(int rt){
    Max[rt] = max(Max[rt << 1], Max[rt << 1 | 1]);
}
void push_up2(int rt){
    Max2[rt] = max(Max2[rt << 1], Max2[rt << 1 | 1]);
}
void build(int l=1, int r=n, int rt=1){
    if(l == r){
        if(l&1) Max[rt]=seq[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(lson);
    build(rson);
    push_up(rt);
}
int query(int L, int R, int l=1, int r=n, int rt=1){
    if(L <= l && R >= r) return Max[rt];
    int cnt = 0;
    int mid = (l + r) >> 1;
    if(L <= mid) cnt = max(cnt, query(L, R, lson));
    if(R > mid) cnt = max(cnt, query(L, R, rson));
    return cnt;
}

void build2(int l=1, int r=n, int rt=1){
    if(l == r){
        if((l&1)==0) Max2[rt]=seq[l];
        return;
    }
    int mid = (l + r) >> 1;
    build2(lson);
    build2(rson);
    push_up2(rt);
}
int query2(int L, int R, int l=1, int r=n, int rt=1){
    if(L <= l && R >= r) return Max2[rt];
    int cnt = 0;
    int mid = (l + r) >> 1;
    if(L <= mid) cnt = max(cnt, query2(L, R, lson));
    if(R > mid) cnt = max(cnt, query2(L, R, rson));
    return cnt;
}
