        //cout<<"wa"<<a<<' '<<b<<endl;
        if(a>l)
            dfs(l,a-1,tt);
        if(a<b-1)
            dfs(a+1,b-1,tt);
        if(b<r)
            dfs(b+1,r,tt);
    }
}
