		}
		else {
			updatenep(1, 0, n - 1, i, temp);
			updatep(1, 0, n - 1, i, 1000000000);
		}
	}
	int counter = 0;
	unordered_map<ll, ll> mf;
	unordered_map<ll, ll> ms;
	set<pair<ll, ll>> ss;
	ss.insert(make_pair(0, n - 1));
	while (counter < n) {
		vector<pair<ll, ll>> currentresults;
		for (auto it : ss) {
			ll f, s;
			ll h = ghash(it.first, it.second);
			if (mf.find(h) != mf.end()) {
				f = mf[h];
				s = ms[h];
				currentresults.push_back(make_pair(f, s));
				continue;
			}
			if (it.first % 2 == 0) {
				f = minnp(1, 0, n - 1, it.first, it.second - 1);
				s = minnnep(1, 0, n - 1, index[f] + 1, it.second);
			}
			else {
				f = minnnep(1, 0, n - 1, it.first, it.second - 1);
				s = minnp(1, 0, n - 1, index[f] + 1, it.second);
			}
			mf.insert(make_pair(h, f));
			ms.insert(make_pair(h, s));
			currentresults.push_back(make_pair(f, s));
		}
		sort(currentresults.begin(), currentresults.end());
		printf("%lld %lld ", currentresults[0].first, currentresults[0].second);
		counter += 2;
		ll f = currentresults[0].first, s = currentresults[0].second;
		pair<ll, ll> del;
		for (auto it : ss) {
			if (index[f] >= it.first && index[s] <= it.second) {
				del = it;
				if (it.first < index[f])ss.insert(make_pair(it.first, index[f] - 1));
				if (index[s] - index[f] > 1)ss.insert(make_pair(index[f] + 1, index[s] - 1));
				if (index[s] < it.second)ss.insert(make_pair(index[s] + 1, it.second));
			}
		}
		ss.erase(del);
	}
	return 0;
}

