void insert(int l,int r) {
	int flag = l % 2;
	int rhs = r;
	if(flag != rhs % 2) rhs--;
	int rl = query(flag, 1, 0, n / 2 - 1, l / 2, rhs / 2);
	rhs = r;
	int rr = query(1 ^ flag, 1, 0, n / 2 - 1, (pos[rl] + 1) / 2, rhs / 2);
	pq.push({{-rl, -rr}, {l, r} });
}

void solve(int l,int r) {
	vector<int> res;
	int rl = query(0, 1, 0, n / 2 - 1, l / 2, r / 2);
	int rr = query(1, 1, 0, n / 2 - 1, pos[rl] / 2, r / 2);
	pq.push({{-rl, -rr}, {l, r}});
	while(!pq.empty()) {
		int rl = -pq.top().FI.FI;
		int rr = -pq.top().FI.SE;
		int l = pq.top().SE.FI;
		int r = pq.top().SE.SE;
		pq.pop();
		res.PB(rl), res.PB(rr);
		int pl = pos[rl];
		int pr = pos[rr];
		if(l < pl - 1) {
			insert(l, pl - 1);
		}
		if(pl + 1 < pr - 1) {
			insert(pl + 1, pr - 1);
		}
		if(pr + 1 < r) {
			insert(pr + 1, r);
		}
	}
	for(int i = 0;i < n;i++) {
		if(i) cout<<" ";
		cout<<res[i];
	}
	cout<<endl;
}

