void solverec(bool rev,int st, int n) {
	if (n == 0) {
	} else if (n == 1) {
		if (!rev) {
			Q.push_back(make_pair(A[st], B[st]));
		} else {
			Q.push_back(make_pair(B[st], A[st + 1]));
		}
	} else {
		if (!rev) {
			auto ml = segmin(segA, st, st + n);
			auto mr = segmin(segB, st, st + n);
			Q.push_back(make_pair(ml.first, mr.first));

			solverec(rev, st, ml.second - st);
			solverec(!rev, ml.second, mr.second - ml.second);
			solverec(rev, mr.second + 1, st - mr.second + n - 1);
		} else {
			auto ml = segmin(segB, st, st + n);
			auto mr = segmin(segA, st + 1, st + 1 + n);
			Q.push_back(make_pair(ml.first, mr.first));

			solverec(rev, st, ml.second - st);
			solverec(!rev, ml.second + 1, mr.second - ml.second - 1);
			solverec(rev, mr.second, st - mr.second + n);
		}
		sort(Q.end() - n + 1, Q.end());
	}
}

