template <typename T> inline T read()
{
	T sum=0, fl=1; char ch=getchar();
	for(; !isdigit(ch); ch=getchar()) if(ch=='-') fl=-1;
	for(; isdigit(ch); ch=getchar()) sum=(sum<<3)+(sum<<1)+ch-'0';
	return sum*fl;
}

const int maxn=2e5+5;
const int inf=2147483647;
int n;
int lg[maxn], ans[maxn]; set<int>S; 
priority_queue<pii, vector<pii>, greater<pii> >Q;

inline pii min(const pii&a, const pii&b) { return a.x<b.x ? a : b; }

struct RMQ
{
	pii mn[20][maxn];
	void init()
	{
		for(int i=1; i<=lg[n]; ++i)
			for(int j=1; j+(1<<i)-1<=n; ++j)
				mn[i][j]=min(mn[i-1][j], mn[i-1][j+(1<<(i-1))]);
	}
	pii query(int l, int r)
	{
		int Log=lg[r-l+1];
		return min(mn[Log][l], mn[Log][r-(1<<Log)+1]);
	}
} k[2]; //0:   1:even

void Solve()
{
	n=read<int>();
	for(int i=2; i<=n; ++i) lg[i]=lg[i>>1]+1;
	for(int i=1; i<=n; i+=2) 
	{
		k[0].mn[0][i]=mp(read<int>(), i);
		k[1].mn[0][i+1]=mp(read<int>(), i+1);
		k[0].mn[0][i+1]=mp(inf, inf);
		k[1].mn[0][i]=mp(inf, inf);
	}
	k[0].init(), k[1].init();

	Q.push(k[0].query(1, n)); S.insert(0); S.insert(n+1);
	for(int i=1; i<=2; i+=2)
	{
		pii p=Q.top(); Q.pop(); 
		int r=*S.lower_bound(p.y), l=*(--S.lower_bound(p.y));

		pii t=k[p.y&1].query(l+1, r-1);
		if(t.y<p.y) swap(p, t);
		ans[i]=p.x; ans[i+1]=t.x;
		S.insert(p.y); S.insert(t.y);

		if(l+1!=p.y) Q.push(k[p.y&1].query(l+1, p.y-1));
		if(p.y+1!=t.y) Q.push(k[p.y&1].query(p.y+1, t.y-1));
		if(t.y+1!=r) Q.push(k[r&1].query(t.y+1, r-1));
	}
	for(int i=1; i<=n; ++i) printf("%d ", ans[i]);
}

