int smin(bool V, int& s, int& t, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s) {
		return INT32_MAX;
	}
	if (s <= l && r <= t) {
		if (V)return os[k];
		return es[k];
	}
	int lv = smin(V, s, t, k * 2, l, (l + r) / 2);
	int rv = smin(V, s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return min(lv, rv);
}

