	int lin=n * 2 + 1,rin=n * 2 + 2;

	if(segm[lin].fi < segm[rin].fi) segm[n].fi=segm[lin].fi, segm[n].se=
		segm[lin].se;
	else segm[n].fi=segm[rin].fi, segm[n].se=segm[rin].se;

