        else
            a[i] = -x;
    }
    build(1, 1, n);
    int cnt = 0;
    for(int cc = 1; cc <= n / 2; ++cc)
    {
        p = query(1, 1, n, 1, n);
        ans[++cnt] = p.Min;
        S.insert(pos[ans[cnt]]);
        update2(1, 1, n, pos[ans[cnt]]);
        q = S.upper_bound(pos[ans[cnt]]);
