const int MAX_N = 1 << 18;

const int INF = 1E9;

int n, dat[2 * MAX_N - 1][2];

void init(int n_) {
	n = 1;
	while (n < n_) n *= 2;
	for (int i = 0;i < 2 * n - 1;i++) {
		for (int j = 0;j < 2;j++) {
			dat[i][j] = INF;
		}
	}
}

void update(int k, int a, int t) {
	k += n - 1;
	dat[k][t] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k][t] = min(dat[k * 2 + 1][t], dat[k * 2 + 2][t]);
	}
}

// [l, r)  query (0, N, 0, 0, n)
int query(int a, int b, int k, int l, int r, int t) {
	if (r <= a || b <= l) return INF;
	if (a <= l && r <= b) return dat[k][t];
	else {
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2, t);
		int vr = query(a, b, k * 2 + 2, (l + r) / 2, r, t);
		return min(vl, vr);
	}
}

int DP[200010];

int R[200010];

struct node {
	int l;
	int r;
	int num;
};

bool operator < (node a, node b) {
	return a.num > b.num;
}

int main() {
