    int N;
    cin >> N;
    init(N + 10);
    for (int i = 0;i < N;i++) {
    	cin >> R[i];
    	DP[R[i]] = i;
    	update(i, R[i], i & 1);
    }
    priority_queue<node> P;
    node p;
    p.l = 0;
    p.r = N - 1;
    p.num = query(0, N, 0, 0, n, 0);
    P.push(p);
    vector<int> sol;
    while (P.size() > 0) {
    	p = P.top();
    	P.pop();
    	int s = p.l;
    	int b = p.r;
    	int idx = DP[p.num];
    	int ot = query(s, b + 1, 0, 0, n, 1 - (1 & s));
    	int idx2 = DP[ot];
    	sol.push_back(p.num);
    	sol.push_back(ot);
    	if (s < idx - 1) {
    		node q;
    		q.l = s;
    		q.r = idx - 1;
    		q.num = query(s, idx, 0, 0, n, (1 & s));
    		P.push(q);
    	}
    	if (idx + 1 < idx2 - 1) {
    		node q;
    		q.l = idx + 1;
    		q.r = idx2 - 1;
    		q.num = query(idx + 1, idx2, 0, 0, n, (1 & q.l));
    		P.push(q);
    	}
    	if (idx2 + 1 < b) {
    		node q;
    		q.l = idx2 + 1;
    		q.r = b;
    		q.num = query(idx2 + 1, b + 1, 0, 0, n, (1 & q.l));
    		P.push(q);
    	}
    }
    for (int i = 0;i < sol.size();i++) {
    	if (i != 0) cout << ' ';
    	cout << sol[i];
    }
    cout << endl;
    return 0;
}

