#include "bits/stdc++.h"
using namespace std;

#define debug(args...) //fprintf(stderr, args)

const int maxn = 2e5 + 10;
const int INF = 0x3f3f3f3f;

int n, a[maxn];

int p[maxn], pos[maxn];

struct triple {
	int prior, x, y;
};

bool operator < (triple a, triple b) {
	return (a.prior < b.prior) || (a.prior == b.prior && a.x < b.x);
}

vector <triple> ans;

struct node {
	int menor[2];

	void merge(node L, node R) {
		for(int m = 0; m < 2; ++m)
			menor[m] = min(L.menor[m], R.menor[m]);
	}

} seg[4 * maxn];

void build(int idx, int i, int j) {
	if(i == j) {
		seg[idx].menor[0] = seg[idx].menor[1] = INF;
		seg[idx].menor[i % 2] = a[i];
		return;
	}

	int mid = (i + j) >> 1;
	int left = idx << 1;
	int right = left | 1;

	build(left, i, mid);
	build(right, mid + 1, j);

	seg[idx].merge(seg[left], seg[right]);
}

int query(int idx, int i, int j, int ini, int fim, int mod) {
	if(i > j || j < ini || fim < i) return INF;

	if(ini <= i && j <= fim) return seg[idx].menor[mod];

	int mid = (i + j) >> 1;
	int left = idx << 1;
	int right = left | 1;

	return min(query(left, i, mid, ini, fim, mod), query(right, mid + 1, j, ini, fim, mod));
}

void solve(int l, int r, int mod, int prior) {
	if(l >= r) return;

	assert(r - l % 2);

	int x = query(1, 0, n - 1, l, r, mod);
	int L = pos[x];
	int y = query(1, 0, n - 1, L + 1, r, (L % 2) ^ 1);
	int R = pos[y];

	ans.push_back({prior, x, y});

	solve(L + 1, R - 1, mod ^ 1, prior + 1);
	solve(l, L - 1, mod, prior + 1);
	solve(R + 1, r, mod, prior + 1);
}

int main() {
	scanf("%d", &n);

	for(int i = 0; i < n; ++i) {
