using namespace std;

const int N = 2e5 + 5, inf = 1e9 + 7;

int n, ar[N], pos[N], u[N], ans[N], cnt, level;

struct st
{
    int e, o;
    st()
    {
        e = inf;
        o = inf;
    }
};

st t[N * 4];

void build (int v = 1, int tl = 1, int tr = n)
{
    if (tl == tr)
    {
        if (tl & 1)
            t[v].o = ar[tl];
        else
            t[v].e = ar[tl];
    }
    else
    {
        int tm = (tl + tr) >> 1;
        build (v + v, tl, tm);
        build (v + v + 1, tm + 1, tr);
        t[v].o = min( t[v + v].o, t[v + v + 1].o );
        t[v].e = min( t[v + v].e, t[v + v + 1].e );
    }
}
int get (int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
    if (l > r || l > tr || tl > r)
        return inf;
    if (l <= tl && tr <= r)
        return (type & 1 ? t[v].o : t[v].e );

    int tm = (tl + tr) >> 1;
    return min( get( l, r, type, v + v, tl, tm ), get(l, r, type, v + v + 1, tm + 1, tr) );
}
vector <pair <int, int> > vec[N];

void Compute (int l, int r)
{
    queue <pair <int, pair <int, int> > > q;

    q.push( mk(l, mk( r, 0) ) );

    while (!q.empty())
    {
        l = q.front().fr;

        r = q.front().sc.fr;

        level = q.front().sc.sc;

        q.pop();

        if (l > r) continue;

        int type = (l & 1 ? 1 : 0);

        int res = get(l, r, type);

        int Sc = get( pos[ res ] + 1, r, type ^ 1 );

        vec[level].pb( mk(res, Sc) );

        q.push( mk( l, mk( pos[res] - 1, level + 1) ) );
        q.push( mk( pos[res] + 1, mk( pos[Sc] - 1, level + 1) ) );
        q.push( mk( pos[Sc] + 1, mk( r, level + 1) ) );
    }
}
main ()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
        scanf("%d", &ar[i]), pos[ ar[i] ] = i;

    build (1, 1, n);

    Compute (1, n);

    for (int i = 0; i <= n; i++)
    {
        sort( all(vec[i]) );
        for (auto x : vec[i])
            ans[++cnt] = x.fr, ans[++cnt] = x.sc;
    }

    for (int i = 1; i <= n; i++)
    {
        assert(ans[i] > 0);
        printf("%d ", ans[i]);
    }
}

#include <cmath>
