void preWork(int n){
    for(int i = 1; i <= n; i++){
        index[a[i]] = i;
        if(i%2){
            f[1][i][0] = a[i];
            f[0][i][0] = inf;
        }
        else{
            f[0][i][0] = a[i];
            f[1][i][0] = inf;
        }
    }
    pow2[0] = 1;
    for(int j = 1; j <= 17; j++){
        pow2[j] = pow2[j-1]*2;
        for(int i = 1; i <= n; i++){
            if(i+pow2[j]-1>n) f[0][i][j] = f[1][i][j] = inf;
            else{
                f[0][i][j] = min(f[0][i][j-1],f[0][i+pow2[j-1]][j-1]);
                f[1][i][j] = min(f[1][i][j-1],f[1][i+pow2[j-1]][j-1]);
            }
        }
    }
    log2[1] = 0; int base = 1;
    for(int i = 2; i <= n; i++){
        log2[i] = log2[i-1];
        if(base*2<=i){
            base *= 2;
            log2[i]++;
        }
    }
}

int spMin(int l,int r,int tag){
    int k = log2[r-l+1];
    return min(f[tag][l][k],f[tag][r-pow2[k]+1][k]);
}

