void f(int l,int r,int count,bool c,SparseTable<int> &st1,SparseTable<int> &st2){
    if(r<=l) return;
    if(c==0){
        int ll = st1.query(l,r);
        int rr = st2.query(l,r);
        int li = ind[ll], ri = ind[rr];
        st.insert(make_pair(count,make_pair(ll,rr)));
        f(l,li,count+1,c,st1,st2);
        f(li+1,ri,count+1,c^1,st1,st2);
        f(ri+1,r,count+1,c,st1,st2);
    }
    else{
        int ll = st2.query(l,r);
        int rr = st1.query(l,r);
        int li = ind[ll], ri = ind[rr];
        st.insert(make_pair(count,make_pair(ll,rr)));
        f(l,li,count+1,c,st1,st2);
        f(li+1,ri,count+1,c^1,st1,st2);
        f(ri+1,r,count+1,c,st1,st2);
    }
    return;
}

