struct Int2
{
	int x, y;
	Int2(int x, int y) :x(x), y(y) {};
	bool operator<(const Int2& other) const {
		if (x != other.x)
			return x < other.x;
		return y < other.y;
	}
	bool operator>(const Int2& other) const {
		if (x != other.x)
			return x > other.x;
		return y > other.y;
	}
};
template<int size_>
class SegmentTree {
private:
	int n, data[size_];
public:
	SegmentTree(int n) : n(n) {
		for (int i = 0; i < n * 2 - 1; i++)
			data[i] = 0x7fffffff;
	}
	void Update(int i, int x) {
		i += n - 1;
		data[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			data[i] = min(data[i * 2 + 1], data[i * 2 + 2]);
		}
	}
	int Querry(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r == -1)
			r = n;
		if (r <= a || b <= l)
			return 0x7fffffff;
		if (a <= l && r <= b)
			return data[k];
		else {
			int vl = Querry(a, b, k * 2 + 1, l, (l + r) / 2);
			int vr = Querry(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(vl, vr);
		}
	}
};
