#define ls  (n<<1)
#define rs  ((n<<1)|1)
using namespace std;

struct node{int l,r,x,y;};
int n,a[200010],b[200010],t[2][400010];
set <node> S;

bool operator < (node x,node y){return a[x.x]<a[y.x];}

void build(int op,int n,int l,int r)
{
	if (l==r)  t[op][n]=a[2*l-op];
	else
		{
			int mid=(l+r)>>1;
			build(op,ls,l,mid),build(op,rs,mid+1,r);
			t[op][n]=min(t[op][ls],t[op][rs]);
		}
}

int ask(int op,int n,int l,int r,int L,int R)
{
	if ((L<=l)&&(r<=R))  return t[op][n];
	else
		{
			int mid=(l+r)>>1;
			if (mid>=R)  return ask(op,ls,l,mid,L,R);
			if (L>mid)  return ask(op,rs,mid+1,r,L,R);
			return min(ask(op,ls,l,mid,L,R),ask(op,rs,mid+1,r,L,R));
		}
}

void doit(int l,int r)
{
	int x,y;
	if (l&1)
		{
			x=b[ask(1,1,1,n/2,l/2+1,r/2)],y=b[ask(0,1,1,n/2,x/2+1,r/2)];
		}else
		{
			x=b[ask(0,1,1,n/2,l/2,r/2)],y=b[ask(1,1,1,n/2,x/2+1,r/2+1)];
		}
	S.insert((node){l,r,x,y});
}

