{
	scanf("%d",&n);
	for (int i=1; i<=n; i++)  scanf("%d",&a[i]),b[a[i]]=i;
	build(0,1,1,n/2),build(1,1,1,n/2);
	int x=b[ask(1,1,1,n/2,1,n/2)],y=b[ask(0,1,1,n/2,x/2+1,n/2)];
	S.insert((node){1,n,x,y});
	for (node p; S.size(); )
		{
			p=*S.begin(),S.erase(S.begin());
