typedef pair<int,int> pii;

void fastStream(){cin.tie(0);std::ios_base::sync_with_stdio(0);}


class RMQ{
public:
    int n;
    vector<int> dat;
    // 初期化
    void init(int n_){
        n=1;
        while(n<n_)n*=2;
        dat.resize(n * 2 - 1, INT_MAX);
    }
    // k番目の値(0-indexed)をaに変更
    void update(int k,int a){
        // 葉の節点
        k+=n-1;
        dat[k]=a;
        // のぼりながら更新
        while(k>0){
            k=(k-1)/2;
            dat[k]=min(dat[k*2+1],dat[k*2+2]);
        }
    }
    // [a,b)の最小値を求める
    // kは節点の番号、l,rはその節点が[l,r)に対応づいていることを表す
    // したがって、外からはquery(a,b,0,0,n)として呼ぶ
    int _query(int a,int b,int k,int l,int r){
        if(r<=a||b<=l)return INT_MAX;
        else if(a<=l&&r<=b)return dat[k];
        int vl=_query(a,b,k*2+1,l,(l+r)/2);
        int vr=_query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
    int query(int a,int b){
        return _query(a,b,0,0,n);	
    }
};



int N;
int P[200010];
int RP[200010];
RMQ rmq[2];


// [l, r)
pii query(int l, int r){
    int v1= rmq[l % 2].query(l, r);
    int x1 = RP[v1];
    int v2 = rmq[(l % 2) ^ 1].query(x1, r);
    int x2 = RP[v2];
    return pii(x1, x2);
}

int main(){


    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> P[i];
        RP[P[i]] = i;
    }

    for(int i = 0; i < 2; i++)
        rmq[i].init(N);

    for(int i = 0; i < N; i++){
        rmq[i % 2].update(i, P[i]);
    }

    priority_queue<pair<pii, pii> , vector<pair<pii, pii>>, greater<pair<pii, pii> > > pq;    

    int l = 0;
    int r = N;
    pii p = query(l, r);
    int x1 = p.first;
    int x2 = p.second;

    vector<int> ans;

    // [l, x1), (x1, x2), (x2, r)
    pq.push(make_pair(pii(P[x1], P[x2]), pii(0, N)));

    while(pq.size()){
        pair<pii, pii> pp = pq.top(); pq.pop();
        ans.push_back(pp.first.first);
        ans.push_back(pp.first.second);
        const int l = pp.second.first;
        const int r = pp.second.second;
        // [l, r)を分割する
        int x1 = RP[pp.first.first];
        int x2 = RP[pp.first.second];
        if(x1 - l != 0){
            pii p = query(l, x1);
            pq.push(make_pair(pii(P[p.first], P[p.second]), pii(l, x1)));
        }
        if(x2 - (x1 + 1) != 0){
            pii p = query(x1 + 1, x2);
            pq.push(make_pair(pii(P[p.first], P[p.second]), pii(x1 + 1, x2)));
        }
        if((r - (x2 + 1) != 0)){
            pii p = query(x2 + 1, r);
            pq.push(make_pair(pii(P[p.first], P[p.second]), pii(x2 + 1, r)));
        }
    }


    for(int a : ans){
        cout << a << " ";
    }
    cout << endl;


    return 0;
}

