    auto calc = [&](int i, int j) {
        auto q0 = st(i, j); pair<int, int> v0 = i&1 ? q0.mo : q0.me;
        auto q1 = st(v0.s, j); pair<int, int> v1 = i&1 ? q1.me : q1.mo;
        return segment{ i, j, v0.f, v0.s, v1.f, v1.s };
    };

    priority_queue<segment> pq;
    pq.push(calc(0, N));

    vector<pair<int, int>> ans;
    while (!pq.empty()) {
        segment s = pq.top(); pq.pop();
        ans.eb(s.v0, s.v1);
        if (s.i0 != s.i) pq.push(calc(s.i, s.i0));
        if (s.i0 + 1 != s.i1) pq.push(calc(s.i0 + 1, s.i1));
        if (s.i1 + 1 != s.j) pq.push(calc(s.i1 + 1, s.j));
    }

    bool f = true;
    trav (v, ans) {
        if (!f) pr(" ");
        pr(v.f, " ", v.s);
        f = false;
    }
    ps();

    return 0;
}

