struct data{int l,r,cl,cr;};
int n;
int mmn[2][N],val[N],ans[N];
priority_queue<data> q;
bool operator<(data a,data b){return val[a.cl]>val[b.cl];}

void up(int &u,int l,int r){u=val[l]<val[r]?l:r;}

void build(int u,int l,int r){
	if(l==r){
		mmn[l&1][u]=l; mmn[l&1^1][u]=0;
		return;
	}
	int mid=l+r>>1;
	build(u<<1,l,mid); build(u<<1|1,mid+1,r);
	up(mmn[0][u],mmn[0][u<<1],mmn[0][u<<1|1]);
	up(mmn[1][u],mmn[1][u<<1],mmn[1][u<<1|1]);
	//printf("%d %d %d %d %d %d\n",u,l,r,mmn[0][u],mmn[1][u]);
}

int ask(int u,int L,int R,int l,int r,int o){
	if(l<=L && r>=R) return mmn[o][u];
	int mid=L+R>>1,t=0,tt;
	if(l<=mid){tt=ask(u<<1,L,mid,l,r,o); if(val[tt]<val[t]) t=tt;}
	if(r>mid){tt=ask(u<<1|1,mid+1,R,l,r,o); if(val[tt]<val[t]) t=tt;}
	return t;
}

