		}
		if(u.cr-u.cl>1){
			x=ask(1,1,n,u.cl+1,u.cr-1,(u.cl+1)&1);
			y=ask(1,1,n,x+1,u.cr-1,(u.cr-1)&1);
			q.push((data){u.cl+1,u.cr-1,x,y});
		}
		if(u.r-u.cr>1){
			x=ask(1,1,n,u.cr+1,u.r,(u.cr+1)&1);
