template<typename T>
class RMQ{
public:
    T arr[100000*2+10];
    int n;

    /*
    template <>
    RMQ<std::pair<int,int>>::RMQ(int N,int a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = std::pair<int,int>(a,i);

        n = 1;
        while(n<N) n*=2;

    }
    */

    /*
    RMQ<int>(int N,int a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = a;

        n = 1;
        while(n<N) n*=2;

    }
    */

    RMQ(int N,T a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = a;

        n = 1;
        while(n<N) n*=2;

    }

    T query(int a,int b){
        return query(a,b,0,0,n);
    }

    T query(int a,int b,int k,int l,int r){
        if(r <= a || b <= l) return INT_MAX;
        if(a <= l && r <= b) return arr[k];

        else{
            T vl = query(a,b,k*2+1,l , (l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl,vr);
        }

    }

    void update(int k,T a){
        k += n-1;

        arr[k] = a;

        while(k > 0){
            k = (k-1)/2;
            arr[k] = min(arr[k*2+1],arr[k*2+2]);
        }
    }
private:

};


template <>
class RMQ<std::pair<int,int>>
{
public:

    using T = std::pair<int,int>;

    T arr[100000*2+10];
    int n;

    RMQ(int N,int a){
        for(int i = 0; i < 100000*2+10; i++)
            arr[i] = T(a,i);

        n = 1;
        while(n<N) n*=2;

    }

    T query(int a,int b){
        return query(a,b,0,0,n);
    }

    T query(int a,int b,int k,int l,int r){
        if(r <= a || b <= l) return T(INT_MAX,-1);
        if(a <= l && r <= b) return arr[k];

        else{
            T vl = query(a,b,k*2+1,l , (l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return min(vl,vr);
        }

    }

    void update(int k,T a){
        k += n-1;

        arr[k] = a;

        while(k > 0){
            k = (k-1)/2;
            arr[k] = min(arr[k*2+1],arr[k*2+2]);
        }
    }
};

RMQ<pair<int,int>> odd(0,0);
RMQ<pair<int,int>> even(0,0);

//範囲  l <= x < r
vector<pair<int,int>> solve(int l,int r){
    if(r <= l){
        return vector<pair<int,int>>();
    }

    vector<pair<int,int>> result;

    if(l + 2 == r){
        if(l%2 == 0){
            result.push_back(pair<int,int>(even.query(l,l+1).first,odd.query(l+1,r).first));
        }else{
            result.push_back(pair<int,int>(odd.query(l,l+1).first,even.query(l+1,r).first));
        }
    }else{
        priority_queue<pii,std::vector<pii> ,std::greater<pii>> pq;

        pii p1;
        pii p2;

        if(l%2 == 0){
            p1 = even.query(l,r);
            p2 = odd.query(p1.second,r);
        }else{
            p1 = odd.query(l,r);
            p2 = even.query(p1.second,r);
        }

        //cout << p1.first << ":" << p1.second << endl;
        //cout << p2.first << ":" << p2.second << endl;

        result.push_back(pii(p1.first,p2.first));

        vector<pair<int,int>> v1 = solve(l,p1.second);
        for(auto const & v: v1) pq.push(v);
        v1 = solve(p1.second+1,p2.second);
        for(auto const & v: v1) pq.push(v);
        v1 = solve(p2.second+1,r);
        for(auto const & v: v1) pq.push(v);

        while(!pq.empty()){
            result.push_back(pq.top());
            pq.pop();
        }

    }

    return result;
}


