struct blob{
  int l,r;
  blob *tl,*tr;
  blob(){l=r=0;tl=tr=NULL;}
};

bool operator<(const blob&lx,const blob&rx){
  int mnl=min(lx.l,lx.r),mxl=max(lx.l,lx.r),
    mnr=min(rx.l,rx.r),mxr=max(rx.l,rx.r);
  if(mnl != mnr)return mnl<mnr;
  return mxl<mxr;
}

set<blob> s;
