void pop(blob&p){
  ans.emplace_back(p.r);
  ans.emplace_back(p.l);
  //cerr << p.l << "," << p.r << endl;

  blob *lb = p.tl, *rb = p.tr;

  if(lb and rb){
    blob q;
    q.l = lb->l;q.r = rb->r;
    q.tl = lb->tl;q.tr = rb->tr;
    s.erase(*lb);s.erase(*rb);
    s.emplace(q);
  }

  s.erase(p);
  if(lb)s.erase(*lb);
  if(rb)s.erase(*rb);
}

