    REP(n, N) {
        if (n % 2 == 0) {
            st_even.update(n, Ps[n]);
            st_odd.update(n, INF);
        }
        else {
            st_odd.update(n, Ps[n]);
            st_even.update(n, INF);
        }
    }

	push_que(0, N);

	vector<int> ans;
	while (!que.empty()) {
		auto ele = que.top(); que.pop();
		ans.pb(-get<0>(ele));
