    }
    vector<int> ans;
    for (int i=0; i < n; i++){
        ans.push_back(-1);
    }
    for (int i=0; i < n/2; i++){
        map<pair<int, int>, int>::iterator it = mm.end();
        it--;
        pair<int, int> p = (*it).first;
        int where = mm[p];
        mm.erase(p);
        int f = *has.upper_bound(where);
        if (i == n / 2 - 1){
            ans[0] = data[where];
            ans[1] = data[f];
            break;
        }
        set<int>::iterator itt = has.upper_bound(where);
        set<int>::iterator it1 = itt;
        it1--;
        set<int>::iterator it2 = itt;
        it2++;
        int num = *it2;
        if (it2 != has.end()){
            int f1 = data[f];
            int s1 = data[num];
            if (f1 > s1) swap(f1, s1);
            mm.erase(make_pair(f1, s1));
        }
        if (it1 == has.begin()){
            has.erase(it1);
            has.erase(itt);
        }
        else{
            set<int>::iterator it3 = it1;
            it3--;
            int nums = *it3;
            int f1 = data[nums];
            int s1 = data[where];
            if (f1 > s1) swap(f1, s1);
            mm.erase(make_pair(f1, s1));
            mm[make_pair(data[nums], data[num])] = nums;
            has.erase(it1);
            has.erase(itt);
        }
        ans[n - 2*i-1] = data[f];
        ans[n-2*i-2] = data[where];
    }
    for (int i=0; i < n; i++){
        cout << ans[i] << " ";
    }
    return 0;
}

