//{{{ Segment Tree
template <class T>
struct segment_tree {
	typedef pair<T,T> range;
	bool disjoint(const range &l,const range &r){ return l.second<=r.first or r.second<=l.first;}
	bool contain(const range &l,const range &r){ return r.first<=l.first and l.second<=r.second;}
	int n;
	vector<T> x;
	vector<int> id;
	segment_tree(int n_) {
		n=1;
		while(n < n_)n*=2;
		x.assign(n*2,init_val());
		id.assign(n*2,-1);
	}

	T init_val(){
		return INF;
	}
	T f(const T &a, const T &b){
		return min(a,b);
	}
	pair<T,int> range_query(const range &p, int i, const range &r){
		if(disjoint(p,r))return {init_val(),-1};
		else if(contain(r,p))return {x[i],id[i]};
		else{
			int m = (r.first+r.second)/2;
			auto pl = range_query(p,i*2+1,{r.first,m}), pr = range_query(p,i*2+2,{m,r.second});
			pair<T,int> ret;
			ret.first = f(pl.first,pr.first);
			if(pl.first<pr.first){
				ret.second = pl.second;
			}else{
				ret.second = pr.second;
			}
			return ret;
		}
	}
	pair<T,int> range_query(const range &p){
		return range_query(p,0,{0,n});
	}
	void set(int a,const T &v,int i,const range &r){
		if(r.second-r.first==1){
			x[i] = v;
			id[i] = r.first;
		}else{
			int m = (r.first+r.second)/2;
			int il = i*2+1, ir = i*2+2;
			if(a<m)set(a,v,il,{r.first,m});
			else set(a,v,ir,{m,r.second});
			x[i] = f(x[il],x[ir]);
			if(x[il]<x[ir])id[i] = id[il];
			else id[i] = id[ir];
		}
	}
	void set(int a,const T &v){
		set(a,v,0,0,n);
	}
	void set_all(const vector<T> &v, int i,const range &r){
		if(r.second-r.first==1){
			x[i] = v[r.first];
			id[i] = r.first;
		}else{
			int m = (r.first+r.second)/2;
			int il = i*2 + 1, ir = i*2 + 2;
			set_all(v,il,{r.first,m});
			set_all(v,ir,{m,r.second});
			x[i] = f(x[il],x[ir]);
			if(x[il]<x[ir])id[i] = id[il];
			else id[i] = id[ir];
		}
	}
	void set_all(const vector<T> &v){
		set_all(v,0,{0,n});
	}
};
