void bild(ll l,ll r,ll node){
	if(l+1==r){
		seg[node][l&1]=mp(a[l],l);
		seg[node][!(l&1)]=mp(inf,l);
		return ;
	}
	ll mid=(l+r)/2;
	bild(l,mid,2*node);
	bild(mid,r,2*node+1);
	seg[node][0]=min(seg[2*node][0],seg[2*node+1][0]);
	seg[node][1]=min(seg[2*node][1],seg[2*node+1][1]);
}
pair<ll,ll>  find_min(ll L,ll R,ll node,ll l,ll r,bool b){
	if(R<=l || r<=L){
		return mp(inf,inf);
	}
	if(l<=L && R<=r){
		return seg[node][b];
	}
	ll mid=(L+R)/2;
	return min(find_min(L,mid,2*node,l,r,b),find_min(mid,R,2*node+1,l,r,b));
}
void solv(ll l,ll r){
	if(l>=r){
		return;
	}
	if(l+2==r){
		d[p]=mp(a[l],a[l+1]);
		p++;
		return;
	}
	ll v=find_min(0,n,1,l,r,l&1).S;
	ll u=find_min(0,n,1,v+1,r,!(l&1)).S;
	d[p]=mp(a[v],a[u]);
	p++;
	solv(l,v);
	solv(v+1,u);
	solv(u+1,r);
}
ll  solvv(ll l,ll r){
