using namespace std;

const int N = 2e5 + 5, inf = 1e9 + 7;

int n, ar[N], pos[N], u[N], ans[N], cnt;

struct st
{
    int e, o;
    st()
    {
        e = inf;
        o = inf;
    }
};

st t[N * 4];

void build (int v = 1, int tl = 1, int tr = n)
{
    if (tl == tr)
    {
        if (tl & 1)
            t[v].o = ar[tl];
        else
            t[v].e = ar[tl];
    }
    else
    {
        int tm = (tl + tr) >> 1;
        build (v + v, tl, tm);
        build (v + v + 1, tm + 1, tr);
        t[v].o = min( t[v + v].o, t[v + v + 1].o );
        t[v].e = min( t[v + v].e, t[v + v + 1].e );
    }
}
set < pair <int, int> > seg;

int get (int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
    if (l > r || l > tr || tl > r)
        return inf;
    if (l <= tl && tr <= r)
        return (type & 1 ? t[v].e : t[v].o );

    int tm = (tl + tr) >> 1;
    return min( get( l, r, type, v + v, tl, tm ), get(l, r, type, v + v + 1, tm + 1, tr) );
}
main ()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
        scanf("%d", &ar[i]), pos[ ar[i] ] = i;

    build (1, 1, n);

    seg.insert( mk(1, n) );

    for (int i = 1; i <= n; i++)
    {
        if (u[i]) continue;

        int ind = pos[i], l, r, res;

        pair <int, int> cur_seg = *(--seg.upper_bound( mk(ind, inf) ));

        l = cur_seg.fr;
        r = cur_seg.sc;

        res = get( ind + 1, r, (ind & 1) );

        if (res == inf)
        {
            res = get( l, ind - 1, (ind & 1) );

            if (res == inf)
                continue;

            int Pos = pos[res];

            if (Pos > ind)
                swap(Pos, ind);

            seg.erase( cur_seg );

            if (l <= Pos - 1)
                seg.insert( mk(l, Pos - 1) );
            if (Pos + 1 <= ind - 1)
                seg.insert( mk(Pos + 1, ind - 1) );
            if (ind + 1 <= r)
                seg.insert( mk(ind + 1, r) );

            u[res] = 1;

            ans[++cnt] = res;
            ans[++cnt] = i;
        }
        else
        {
            int Pos = pos[res];

            if (Pos > ind)
                swap(Pos, ind);

            seg.erase( cur_seg );

            if (l <= Pos - 1)
                seg.insert( mk(l, Pos - 1) );
            if (Pos + 1 <= ind - 1)
                seg.insert( mk(Pos + 1, ind - 1) );
            if (ind + 1 <= r)
                seg.insert( mk(ind + 1, r) );

            u[res] = 1;
            ans[++cnt] = i, ans[++cnt] = res;
        }
    }
    for (int i = 1; i <= n; i++)
        cout << ans[i] << " ";
}

