vector<int> solve(Seg &A,Seg &B){
  priority_queue<dat> Q;
  {
    int idxa,a; tie(idxa,a) = A.find(0, n);
    int idxb,b; tie(idxb,b) = B.find(0, n);
    if(idxa > idxb) swap(a, b);
    Q.push(dat(0,n-1,a,b,0));
  }
  vector<int> res;

  while((int)res.size() < n){
    dat t = Q.top(); Q.pop();
    int l = t.l, r = t.r, flag = t.flag;
    int nl, lval; tie(nl,lval) = A.find(l, r+1);
    int nr, rval; tie(nr,rval) = B.find(l, r+1);
    //if(lval == INF || rval == INF) continue;

    A.query(nl, nl + 1, INF, INF);
    B.query(nr, nr + 1, INF, INF);

    if(nl > nr) swap(nl, nr), swap(lval, rval);

    // pr(l,r);
    // pr(nl,lval, nr, rval);
    // pr(t.lval,t.rval);
    //cout<<endl;

    //assert(t.lval == lval && t.rval == rval);
    res.push_back(lval), res.push_back(rval);

    auto push=[&A,&B,&Q](int l,int r,int flag){
      if(l > r) return;
      int idxa,a; tie(idxa,a) = A.find(l, r+1);
      int idxb,b; tie(idxb,b) = B.find(l, r+1);
      if(idxa > idxb) swap(a,b);
      //assert(a < INF && b < INF);
      Q.push(dat(l, r, a, b, flag));
    };

    push(nl + 1,nr - 1,flag);
    push(l,nl-1,flag);
    push(nr + 1,r,flag);
  }
  return res;
}

