const int INF = 1e9;

struct SegmTree {
	vii t;
	int sz;

	SegmTree(int n = 0) {
		sz = 1;
		while (sz < n) sz *= 2;
		t.assign(sz * 2, mp(INF, -1));
	}

	pii get_min(int l, int r) {
		assert(l <= r);
		assert(r < sz);
		assert(0 <= l);
		l += sz;
		r += sz;
		pii res(INF, -1);
		while (l <= r) {
			res = min(res, t[l]);
			res = min(res, t[r]);
			l = (l + 1) >> 1;
			r = (r - 1) >> 1;
		}
		return res;
	}

	void put(int pos, int val) {
		int v = sz + pos;
		t[v] = mp(val, pos);
		v >>= 1;
		while (v) {
			t[v] = min(t[v * 2], t[v * 2 + 1]);
			v >>= 1;
		}
	}
};

vii merge(const vii& left, const vii& right) {
	vii res(sz(left) + sz(right));
	merge(all(left), all(right), res.begin());
	return res;
}

int expand(int pos, int parity) {
	if  (pos == -1) {
		return -1;
	}
	if  (parity == 1) {
		return pos * 2 + 1;
	}
	return pos * 2;
}

vii solve(vector<SegmTree>& T, int l, int r) {
	if  (l > r) {
		return {};
	}

	const int len = r - l + 1;
	assert(len % 2 == 0);

	// eprintf("l=%d, r=%d\n", l, r);

	int pos = expand(T[l & 1].get_min(l / 2, (r - 1) / 2).snd, l & 1);
	assert(pos != -1);
	int pos2 = expand(T[~l & 1].get_min((pos + 1) / 2, r / 2).snd, ~l & 1);
	assert(pos2 != -1);

	vii left = solve(T, l, pos - 1);
	vii mid = solve(T, pos + 1, pos2 - 1);
	vii right = solve(T, pos2 + 1, r);

	auto res = merge(merge(left, mid), right);
	reverse(all(res));
	res.pb(mp(p[pos], p[pos2]));
	reverse(all(res));
	return res;
}

