    if(l >= qLow && r <= qHigh)
        return even[pos];
    int mid = (l+r)/2;
    node lf = getEven(pos*2,l,mid,qLow,qHigh), ri = getEven(pos*2+1,mid+1,r,qLow,qHigh);
    if(lf.mn < ri.mn)
        return lf;
    return ri;
}

