    ret.push_back({a[l], a[l + 1]});
    return ret;
  }

  int i1, i2;
  if ((l & 1) == 0) {
    auto p1 = est.query(l / 2, r / 2);
    i1 = p1.second * 2;
    auto p2 = ost.query(i1 / 2, r / 2);
    i2 = p2.second * 2 + 1;
    ret.push_back({p1.first, p2.first});
    assert(i1 < i2);
  } else {
    auto p1 = ost.query(l / 2, r / 2);
    i1 = p1.second * 2 + 1;
    auto p2 = est.query(i1 / 2 + 1, r / 2 + 1);
    i2 = p2.second * 2;
    ret.push_back({p1.first, p2.first});
    assert(i1 < i2);
  }

  auto r1 = build(l, i1);
  auto r2 = build(i1 + 1, i2);
  auto r3 = build(i2 + 1, r);
