void maintain(int o){
	siz[o]=siz[ch[o][0]]+siz[ch[o][1]]+1;
	mini[o]=val[o],minid[o]=o;
	if(ch[o][0]&&mini[o]>mini[ch[o][0]]){
		mini[o]=mini[ch[o][0]];
		minid[o]=minid[ch[o][0]];
	}
	if(ch[o][1]&&mini[o]>mini[ch[o][1]]){
		mini[o]=mini[ch[o][1]];
		minid[o]=minid[ch[o][1]];
	}
	return;
}
int which(int x){
	return ch[f[x]][1]==x;
}
void rotate(int x){
	int fx=f[x],ffx=f[f[x]];
	int d=which(x),fd=which(fx);
	f[x]=ffx;
	if(ffx)
		ch[ffx][fd]=x;
	ch[fx][d]=ch[x][d^1];
	f[ch[x][d^1]]=fx;
	ch[x][d^1]=fx;
	f[fx]=x;
	maintain(fx);
	maintain(x);
	return;
}
void pushdown(int o){
	if(ch[o][0])
		root[ch[o][0]]=tag[ch[o][0]]=tag[o];
	if(ch[o][1])
		root[ch[o][1]]=tag[ch[o][1]]=tag[o];
	return;
}
void push(int x){
	if(!x)
		return;
	push(f[x]);
	pushdown(x);
	return;
}
void splay(int x,int t){
	push(x);
	while(f[x]!=t){
		int fx=f[x];
		if(f[fx]!=t){
			if(which(fx)==which(x))
				rotate(fx);
			else rotate(x);
		}
		rotate(x);
	}
	return;
}
void build(int &o,int l,int r,int *a,int t){
	if(l>r)
		return;
	o=++cnt;
	int mid=(l+r)>>1;
	val[o]=a[mid];
	idx[a[mid]]=o;
	root[o]=tag[o]=t;
	build(ch[o][0],l,mid-1,a,t);
	build(ch[o][1],mid+1,r,a,t);
	f[ch[o][0]]=o;
	f[ch[o][1]]=o;
	maintain(o);
	return;
}
int find(int o,int x){
	if(x==siz[ch[o][0]]+1)
		return o;
	if(x<=siz[ch[o][0]])
		return find(ch[o][0],x);
	return find(ch[o][1],x-siz[ch[o][0]]-1);
}
void push_up(int o){
	if(sz[o<<1]&1){
		tr0[o]=min(tr0[o<<1],tr1[o<<1|1]);
		tr1[o]=min(tr1[o<<1],tr0[o<<1|1]);
	}
	else{
		tr0[o]=min(tr0[o<<1],tr0[o<<1|1]);
		tr1[o]=min(tr1[o<<1],tr1[o<<1|1]);
	}
	sz[o]=sz[o<<1]+sz[o<<1|1];
	return;
}
void buildseg(int o,int l,int r){
	if(l==r){
		sz[o]=1;
		tr0[o]=a[l];
		tr1[o]=0x7f7f7f7f;
		return;
	}
	int mid=(l+r)>>1;
	buildseg(o<<1,l,mid);
	buildseg(o<<1|1,mid+1,r);
	push_up(o);
	return;
}
void remove(int o,int l,int r,int x){
	if(l==r){
		sz[o]=0;
		tr0[o]=0x7f7f7f7f;
		tr1[o]=0x7f7f7f7f;
		return;
	}
	int mid=(l+r)>>1;
	if(x<=mid)
		remove(o<<1,l,mid,x);
	if(x>mid)
		remove(o<<1|1,mid+1,r,x);
	push_up(o);
	return;
}
