const ll MOD=1000000007;

const int MAX_N=1<<19;
const int INF=202020;

int n, dat[2][2*MAX_N-1];

void init(int n_){
  n=1;
  while(n<n_) n*=2;
  for(int i=0;i<=2*n-1;i++) dat[0][i]=dat[1][i]=INF;
}

void update(int k, int a,int p){
  k+=n-1;
  dat[p][k]=a;
  while(k>0){
    k=(k-1)/2;
    dat[p][k]=min(dat[p][k*2+1],dat[p][k*2+2]);
  }
}

int query(int a, int b, int k, int l, int r,int p){
  if(r<=a || b<=l) return INF;
  if(a<=l && r<=b) return dat[p][k];
  else{
    int vl=query(a,b,k*2+1,l,(l+r)/2,p);
    int vr=query(a,b,k*2+2,(l+r)/2,r,p);
    return min(vl,vr);
  }
}

int ind[202020],N,P[202020];

vector<pair<int,int> > dfs(int l, int r){
  vector<pair<int,int> > res;
  if(l>=r||l<1||r>N) return res;
  int odd,even;
  if((r-l)==1) odd=l, even=r;
  else{
    odd=ind[query(l,r+1,0,0,n,l%2)];
    even=ind[query(l,r+1,0,0,n,(l+1)%2)];
  }
  if(odd>N||odd<1||even>N||even<1) return res;
  vector<pair<int,int> > V1=dfs(l,odd-1);
  int siz1=V1.size();
  V1.push_back({INF,INF});

  vector<pair<int,int> > V2=dfs(odd+1,even-1);
  int siz2=V2.size();
  V2.push_back({INF,INF});

  vector<pair<int,int> > V3=dfs(even+1,r);
  int siz3=V3.size();
  V3.push_back({INF,INF});

  res.push_back({P[odd],P[even]});
  int l1=0,l2=0,l3=0;
  while(l1<siz1||l2<siz2||l3<siz3){
    pair<int,int> tmp[3]={V1[l1],V2[l2],V3[l3]};
    sort(tmp,tmp+3);
    if(tmp[0]==V1[l1]){
      res.push_back(V1[l1++]);
    }else if(tmp[0]==V2[l2]){
      res.push_back(V2[l2++]);
    }else{
      res.push_back(V3[l3++]);
    }
  }
  return res;
}

