  cin>>N;
  init(N+1);
  for(int i=1;i<=N;i++){
    cin>>P[i];
    ind[P[i]]=i;
    update(i,P[i],i%2);
  }
  vector<pair<int,int> > ans=dfs(1,N);
  rep(i,N/2-1) cout<<ans[i].first<<" "<<ans[i].second<<" ";
  cout<<ans[N/2-1].first<<" "<<ans[N/2-1].second<<endl;
  return 0;
}

