struct RMQ{
	int n;
	vector<pair<int,int> > dat;

	RMQ(int n_){
		n = 1;
		while(n < n_) n *= 2;
		dat.resize(2*n-1);
		for(int i = 0;i < dat.size();i++) dat[i] = make_pair(INT_MAX,INT_MAX);
	}

	void update(int k,pair<int,int> a){
		k += n-1;
		dat[k] = a;
		while(k > 0){
			k = (k-1)/2;
			dat[k] = (dat[k*2+1]<dat[k*2+2])?dat[k*2+1]:dat[k*2+2];
		}
	}

	pair<int,int> query(int a,int b,int k,int l,int r){
		if(r <= a || b <= l) return make_pair(INT_MAX,INT_MAX);
		if(a <= l && r <= b) return dat[k];
		else{
			pair<int,int> vl = query(a,b,k*2+1,l,(l+r)/2);
			pair<int,int> vr = query(a,b,k*2+2,(l+r)/2,r);
			return (vl<vr)?vl:vr;
		}
	}
};

