template<typename T>
struct segment_tree {
    vector<T> orig, data;
    vector<int> need;
    T net;
    T (*f)(T a, T b);
    segment_tree() {

    }
    void build(int l, int r, int v = 0) {
        if (l > r) {
            return;
        }
        if (l == r) {
            data[v] = orig[l];
            return;
        }
        int ls = v + v + 1, rs = v + v + 2, m = (l + r) >> 1;
        build(l, m, ls);
        build(m + 1, r, rs);
        data[v] = (*f)(data[ls], data[rs]);
    }
    T get(int l, int r, int ql, int qr, int v = 0) {
        push(l, r, v);
        if (l > qr || r < ql) {
            return net;
        }
        if (l == ql && qr == r) {
            return data[v];
        }
        int ls = v + v + 1, rs = v + v + 2, m = (l + r) >> 1;
        T resL = get(l, m, ql, min(m, qr), ls);
        T resR = get(m + 1, r, max(m + 1, ql), qr, rs);
        return (*f)(resL, resR);
    }
    T get(int ql, int qr) {
        return get(0, sz(orig) - 1, ql, qr);
    }
    void change(int l, int r, int pos, T val, int v = 0) {
        push(l, r, v);
        if (pos > r || pos < l) {
            return;
        }
        if (l == r && l == pos) {
            orig[l] = data[v] = val;
            return;
        }
        int ls = v + v + 1, rs = v + v + 2, m = (l + r) >> 1;
        change(l, m, pos, val, ls);
        change(m + 1, r, pos, val, rs);
        data[v] = (*f)(data[ls], data[rs]);
    }
    void change(int pos, T val) {
        change(0, sz(orig) - 1, pos, val);
    }
    void push(int l, int r, int v) {
        if (!need[v])
            return;
        swap(data[v].fi, data[v].se);
        need[v] = false;
        if (l != r) {
            need[v + v + 1] = !need[v + v + 1];
            need[v + v + 2] = !need[v + v + 2];
        }
    }
    void paint(int l, int r, int ql, int qr, int v = 0) {
        push(l, r, v);
        if (l > qr || r < ql) {
            return;
        }
        if (l == ql && qr == r) {
            need[v] = !need[v];
            push(l, r, v);
            return;
        }
        int ls = v + v + 1, rs = v + v + 2, m = (l + r) >> 1;
        paint(l, m, ql, min(m, qr), ls);
        paint(m + 1, r, max(m + 1, ql), qr, rs);
        data[v] = (*f)(data[ls], data[rs]);
    }
    void paint(int ql, int qr) {
        paint(0, sz(orig) - 1, ql, qr);
    }
    void build(vector<T> &prot, T nt, T (*ff)(T a, T b)) {
        f = ff;
        net = nt;
        orig = prot;
        data.resize(4 * sz(prot) + 1, nt);
        need.resize(sz(data), 0);
        build(0, sz(prot) - 1);
    }
};

