segtree even, odd;

int main() {
  int n;
  cin >> n;

  vector<int> p(n);
  for (int i = 0; i < n; ++i) {
    cin >> p[i];
  }

  vector<int> u, v;
  for (int i = 0; i < n; ++i) {
    if (i & 1) {
      u.push_back(p[i]);
      v.push_back(inf);
    } else {
      u.push_back(inf);
      v.push_back(p[i]);
    }
  }

  odd.init(u);
  even.init(v);

  // cout << odd.get_min(0, n).first << " " << even.get_min(0, n).first << endl;

  int idx = 0;
  vector<vector<int>> G(n);
  vector<pair<int, int>> val(n);

  function<void(int, int)> solve = [&](int l, int r) {
    int next_l, next_r;
    next_l = (l & 1 ? odd : even).get_min(l, r).second;
    next_r = (l & 1 ? even : odd).get_min(l, r).second;

    val[idx] = make_pair(p[next_l], p[next_r]);
    // cout << l << " " << r << " " << p[next_l] << " " << p[next_r] << endl;

    int v = idx++;
    if (l != next_l) {
      G[v].push_back(idx);
      solve(l, next_l);
    }
    if (next_l + 1 != next_r) {
      G[v].push_back(idx);
      solve(next_l + 1, next_r);
    }
    if (next_r + 1 != r) {
      G[v].push_back(idx);
      solve(next_r + 1, r);
    }
  };

  solve(0, n);

  vector<int> ans;
  priority_queue<data> que;
  que.push(data(val[0], 0));
  while (!que.empty()) {
    pair<int, int> p = que.top().p;
    int k = que.top().k;
    que.pop();

    ans.push_back(p.first);
    ans.push_back(p.second);

    for (auto e : G[k]) {
      que.push(data(val[e], e));
    }
  }

  for (int i = 0; i < n; ++i) {
    cout << ans[i] << (i + 1 == n ? "\n" : " ");
  }
}

