const int N = 200000 + 5;

class SegTree{
	private:
		struct Node{
			PII v, flag;
		} nodes[4*N];
		int size;
		inline int lc(int x){return (x<<1)+1;}
		inline int rc(int x){return (x<<1)+2;}
		inline void push(int l, int r, int id){
			if(nodes[id].flag == (PII){-1, -1}) return;
			if(r-l>1){
				nodes[lc(id)].flag = nodes[id].flag;
				nodes[rc(id)].flag = nodes[id].flag;
			}
			nodes[id].v = nodes[id].flag;
			nodes[id].flag = {-1, -1};
		}
		inline void pull(int id){
			PII l=nodes[lc(id)].v;
			PII r=nodes[rc(id)].v;
			if(nodes[lc(id)].flag.FF != -1) l=nodes[lc(id)].flag;
			if(nodes[rc(id)].flag.FF != -1) l=nodes[rc(id)].flag;
			nodes[id].v = max(l, r);
		}
		void build(int l, int r, int id, PII arr[]){
			nodes[id].flag = {-1,-1};
			if(r-l == 1){
				nodes[id].v=arr[l];
				return;
			}
			int mid=(l+r)>>1;
			build(l, mid, lc(id), arr);
			build(mid, r, rc(id), arr);
			nodes[id].v = max(nodes[lc(id)].v, nodes[rc(id)].v);
		}
		PII query(int ql, int qr, int l, int r, int id){
			if(qr <= l or r <= ql) return {0,0};
			cerr<<"at ["<<l<<", "<<r<<")\n";
			push(l, r, id);
			if(ql <= l and r <= qr) return nodes[id].v;
			int mid=(l+r)>>1;
			return max(query(ql, qr, l, mid, lc(id)), \
				query(ql, qr, mid, r, rc(id)) );
		}
		void modify(int ql, int qr, int l, int r, PII v, int id){
			if(qr <= l or r <= ql) return;
			cerr<<"at ["<<l<<", "<<r<<")\n";
			push(l, r, id);
			if(ql <= l and r <= qr){
				nodes[id].flag = v;
				return;
			}
			int mid=(l+r)>>1;
			modify(ql, qr, l, mid, v, lc(id));
			modify(ql, qr, mid, r, v, rc(id));
			pull(id);
		}
	public:
		void build(int n, PII arr[]){
			size=n;
			build(0, n, 0, arr);
		}
		PII query(int l, int r){
			cerr<<"query ["<<l<<", "<<r<<")\n";
			return query(l, r, 0, size, 0);
		}
		void modify(int l, int r, PII v){
