	if(mrk) {
		if(f&1) use =  rs.se ;
		else use = rs.fi ;
		srt.push_back( ii(arr[par] , arr[use]) ) ;
		div( f , use - 1 , 0 , 0 , L ) ;
		div( use + 1 , l , 0 , 0 , R ) ;
	}
	else{
		if(f&1) use = rs.se ;
		else use = rs.fi ; 
		p = use ;
		div( f , use - 1 , 0 , 0 , L ) ;
		div( use + 1 , l ,use , 1 , R ) ;
	}
	int p1 = 0 , p2 = 0 ; 
	while(p1 < sz(L) && p2 < sz(R) ){
		if(L[p1] < R[p2]){
			srt.push_back(L[p1]) ;
			p1++ ;
		}
		else{
			srt.push_back(R[p2]) ;
			p2++ ;
		}
	}
	while(p1 < sz(L)){
		srt.push_back(L[p1]) ;
		p1++ ;
	}
	while(p2 < sz(R)){
		srt.push_back(R[p2]) ;
		p2++ ;
	}
	L.erase(ALL(L)) ;
	R.erase(ALL(R)) ;
}

