  for (int i = 0; i < n; ++i) {
    scanf("%d", a + i);
    put(1, 0, n - 1, i, tree[i % 2]);
  }
  vector <int> ans = solve(0, n - 1, 0);
  for (int i = 0; i < n; ++i) {
    if (i > 0) putchar(' ');
    printf("%d", ans[i]);
  }
  putchar('\n');
}

