		pii r = pii(1e9, -1);
		while(s <= e){
			if( s&1 ) r = min(r, t[s++]);
			if(~e&1 ) r = min(r, t[e--]);
			s /= 2, e /= 2;
		}
		return r;
	}
	void update(int x, int v){
		x += MX; t[x] = pii(v, x-MX);
		while(x > 1) x /= 2, t[x] = min(t[x*2], t[x*2+1]);
	}
