void solve(int s, int e, vector<int> &A)
{
	if( s > e ) return;
	pii p = t[s%2].find(s, e);
	pii q = t[~s&1].find(p.second+1, e);
	if( q.second < 0 ) return;

	vector<int> t[3];
	solve(s, p.second-1, t[0]);
	solve(p.second+1, q.second-1, t[1]);
	solve(q.second+1, e, t[2]);

	A.push_back(p.first);
	A.push_back(q.first);
	for(int i = 0; i < 3; i++) reverse(t[i].begin(), t[i].end());
