node combine(const node &a, const node &b)
{
    node res;
    res.len = a.len + b.len;
    if (a.len == 1)
    {
        if (b.len == 1)
        {
            res.f = a.f;
            res.s = b.f;
            res.fp = a.fp;
            res.sp = b.fp;
        }
        else
        {
            if (a.f <= b.s)
            {
                res.fp = a.fp;
            }
            else
            {
                res.fp = b.sp;
            }

            res.f = min(a.f, b.s);
            res.s = b.f;
            res.sp = b.fp;
        }
    }
    else
    {
        if (b.len == 1)
        {
            if (a.len & 1)
            {
                res.f = a.f;
                res.fp = a.fp;

                if (a.s <= b.f)
                {
                    res.sp = a.sp;
                }
                else
