void build(int v,int tl,int tr)
{
    if (tl == tr)
    {
        t[v].f = t[v].s = p[tl];
        t[v].len = 1;
        t[v].fp = t[v].sp = tl;
    }
    else
    {
        int tm = (tl+tr)/2;
        build(v*2,tl,tm);
        build(v*2+1,tm+1,tr);
        t[v] = combine(t[v*2], t[v*2+1]);
    }
}

node query(int v,int tl,int tr,int l,int r)
{

    if (tl == l && tr == r)
    {
        return t[v];
    }
    else
    {
        int tm = (tl+tr)/2;
        if (tm >= r)
        {
            return query(v*2,tl,tm,l,r);
        }

        if (tm < l)
        {
            return query(v*2+1,tm+1,tr,l,r);
        }
        return  combine(query(v*2,tl,tm,l,tm), query(v*2+1,tm+1,tr,tm+1,r));
    }
}

void calc(int l,int r)
{
    if (l >= r) return;
    node q1 = query(1, 1, n, l, r);
    node q2 = query(1,1,n, q1.fp + 1, r);
    ans.push_back(make_pair(p[q1.fp], p[q2.fp]));

    if (l < q1.fp - 1)
    {
        q.push(make_pair(-query(1,1,n,l,q1.fp-1).f,make_pair(l, q1.fp-1)));
    }

    if (q1.fp+1 < q2.fp-1)
    {
        q.push(make_pair(-query(1,1,n,q1.fp+1, q2.fp-1).f,make_pair(q1.fp+1, q2.fp-1)));
    }

    if (q2.fp+1 < r)
    {
        q.push(make_pair(-query(1,1,n,q2.fp+1, r).f,make_pair(q2.fp+1,r)));
    }
}

