template <typename T, typename F>
class SegmentTree {
  private:
    T e;
    F op;
    ll n;
    vector<T> dat;

  public:
    SegmentTree(F f, T _e, vector<T> v) : op(f), e(_e) {
        int _n = v.size();
        n = 1;
        while(n < _n)
            n *= 2;
        dat.resize(2 * n - 1, e);
        REP(i, _n)
        dat[n + i - 1] = v[i];
        for(int i = n - 2; i >= 0; i--)
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    SegmentTree(F f, T _e, int _n) : op(f), e(_e) {
        n = 1;
        while(n < _n)
            n *= 2;
        dat.resize(2 * n - 1, e);
        for(int i = n - 2; i >= 0; i--)
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    void update(int i, T x) {
        i += n - 1;
        dat[i] = x;
        while(i > 0) {
            i = (i - 1) / 2;
            dat[i] = op(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
    }
    T get(int i) {
        i += n - 1;
        return dat[i];
    }
    T query(int l, int r) {
        //[l,r)でのクエリ処理
        T left = e, right = e;
        l += n - 1;
        r += n - 1;
        while(l < r) {
            if((l & 1) == 0)
                left = op(left, dat[l]);
            if((r & 1) == 0)
                right = op(dat[r - 1], right);
            l = l / 2;
            r = (r - 1) / 2;
        }
        return op(left, right);
    }
};

void solve() {
    ll n;
    cin >> n;
    vec<ll> p(n);
    REP(i, n) {
        cin >> p[i];
    }

    auto op = [](P a, P b) { return min(a, b); };
    vec<SegmentTree<P, decltype(op)>> seg(2, SegmentTree(op, make_pair(INF, INF), n));

    REP(i, n) {
        seg[i % 2].update(i, make_pair(p[i], i));
    }

    priority_queue<tp, vec<tp>, greater<tp>> que; //min,l,r;
    que.push(make_tuple(seg[0].query(0, n).first, 0, n));

    vec<ll> ans;
    while(que.size()) {
        auto [min, l, r] = que.top();
        que.pop();
        auto [q0, j] = seg[l % 2].query(l, r);
        auto [q1, k] = seg[1 - l % 2].query(j + 1, r);
        ans.push_back(q0);
        ans.push_back(q1);
        if(l < j)
            que.push(make_tuple(seg[l % 2].query(l, j).first, l, j));
        if(j + 1 < k)
            que.push(make_tuple(seg[(j + 1) % 2].query(j + 1, k).first, j + 1, k));
        if(k + 1 < r)
            que.push(make_tuple(seg[(k + 1) % 2].query(k + 1, r).first, k + 1, r));
    }

    for(auto i : ans)
        cout << i << " ";
    cout << en;
}

