// Problem Specific Parameter:

// Description: セグメント木　点更新 区間クエリ
// TimeComplexity: 初期化$\mathcal{O}(n \log n)$ 更新とクエリ$\mathcal{O}(\log n)$
// Verifyed: AOJ DSL_2_A

struct Segment_tree {
	using T = ll;
	const T out = (1LL << 31) - 1;

	int n;
	vector<T> data;

	inline T vmerge(T l, T r) {return min(l, r);}

	Segment_tree(int n): n(n) {data.assign(2 * n, out);}

	void update(int p, T x) { // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(int l, int r) {  // sum on interval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};

const int limit = 200010;
Segment_tree odd(limit);
Segment_tree even(limit);
int idx[limit];

int main(void) {
	int n;
	cin >> n;

	vector<int> p(n);
	rep(i, n) {
		cin >> p[i];
		if (i & 1)
			odd.update(i, p[i]);
		else
			even.update(i, p[i]);
		idx[p[i]] = i;
	}

	vector<int> ans;
	using state = tuple<int, int, int, int>;
	priority_queue<state, vector<state>, greater<state>> q;


	{
		int x = even.query(0, n);
		int y = odd.query(idx[x], n);
		q.push(state(x, y, 0, n));
	}

	while (!q.empty()) {
		int x, y, l, r;
		tie(x, y, l, r) = q.top(); q.pop();
		//cerr << x << " " << y << " " << l << " " << r << " " << ans.size() << endl;
		ans.push_back(x);
		ans.push_back(y);

		int xi = idx[x], yi = idx[y];

		if (xi - l >= 2) {
			int nx, ny;
			if (l & 1) {
				nx = odd.query(l, xi);
				ny = even.query(idx[nx], xi);
			} else {
				nx = even.query(l, xi);
				ny = odd.query(idx[nx], xi);
			}
			q.push(state(nx, ny, l, xi));
		}

		if (yi - xi - 1 >= 2) {
			int nx, ny;
			if ((xi + 1) & 1) {
				nx = odd.query(xi + 1, yi);
				ny = even.query(idx[nx], yi);
			} else {
				nx = even.query(xi + 1, yi);
				ny = odd.query(idx[nx], yi);
			}
			q.push(state(nx, ny, xi + 1, yi));
		}

		if (r - yi - 1 >= 2) {
			int nx, ny;
			if ((yi + 1) & 1) {
				nx = odd.query(yi + 1 , r);
				ny = even.query(idx[nx], r);
			} else {
				nx = even.query(yi + 1, r);
				ny = odd.query(idx[nx], r);
			}
			q.push(state(nx, ny, yi + 1, r));
		}

		//cerr << endl;
	}

	rep(i, n) cout << (i ? " " : "") << ans[i];
	cout << endl;

	return 0;
}

