template <typename T> class SparseTable {
    vector<vector<T>> st;
    vector<int> lookup;

  public:
    SparseTable(const vector<T> &v) {
        int b = 0;
        while((1U << b) <= v.size())
            ++b;
        st.assign(b, vector<T>(1 << b));
        rep(i, v.size()) st[0][i] = v[i];
        FOR(i, 1, b) rep(j, (1 << b) - (1 << i) + 1) {
            st[i][j] = min(st[i - 1][j], st[i - 1][j + (1 << (i - 1))]);
        }
        lookup.resize(v.size() + 1);
        FOR(i, 2, lookup.size()) lookup[i] = lookup[i >> 1] + 1;
    }

    constexpr T rmq(const int &l, const int &r) {
        int b = lookup[r - l];
        return min(st[b][l], st[b][r - (1 << b)]);
    }
};

struct kukan {
    int l, r, mn;
    kukan(int l, int r, int mn) : l(l), r(r), mn(mn) {}
    inline bool operator<(const kukan &x) const { return mn > x.mn; }
};

