    }
    vector<SparseTable<int>> RMQ;
    RMQ.push_back(SparseTable<int>(dat[0]));
    RMQ.push_back(SparseTable<int>(dat[1]));
    priority_queue<kukan> pque;
    pque.push(kukan(0, N, RMQ[0].rmq(0, N)));
    while(!pque.empty()) {
        kukan x = pque.top();
        pque.pop();
        ans.push_back(x.mn);
        int a = pos[x.mn];
