template<typename Monoid>
struct SegmentTree{
    using F=function<Monoid(Monoid,Monoid)>;
    int sz;
    vector<Monoid> seg;
    const F f;
    const Monoid gen;
    SegmentTree(int n,const F f,const Monoid &gen):f(f),gen(gen){
        sz=1;
        while(sz<n)sz<<=1;
        seg.assign(2*sz,gen);
    }
    void set(int k,const Monoid &x){
        seg[k+sz]=x;
    }
    void build(){
        for(int k=sz-1;k>0;k--) seg[k]=f(seg[2*k],seg[2*k+1]);
    }
    void update(int k,const Monoid &x){
        k+=sz;
        seg[k]=x;
        while(k>>=1) seg[k]=f(seg[2*k],seg[2*k+1]);
    }
   // [a,b)
    Monoid query(int a,int b){
        Monoid L=gen,R=gen;
        for(a+=sz,b+=sz;a<b;a>>=1,b>>=1){
            if(a&1) L=f(L,seg[a++]);
            if(b&1) R=f(seg[--b],R);
        }
        return f(L,R);
    }
    Monoid operator[](const int &k)const {
       return seg[k+sz];
    }
};
using P=pair<int,int>;
P f(P a,P b){
    return a<b?a:b;
}


signed main(){
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n;cin>>n;
    vector<int> v(n);
    SegmentTree<P> ev(n,f,P(INF,INF)),od(n,f,P(INF,INF));

    rep(i,n){
        cin>>v[i];
        if(i%2) od.set(i,{v[i],i});
        else    ev.set(i,{v[i],i});
    }
    ev.build();od.build();

    function<vector<P>(int,int)> solve=[&](int l,int r){
        if(l==r) return vector<P>(0);
        P fs,sc;
        if(l%2){
            fs=od.query(l,r);
            sc=ev.query(fs.second,r);
        }else{
            fs=ev.query(l,r);
            sc=od.query(fs.second,r);
        }
        set<P> ret;
        if(l<fs.second){
            for(auto p:solve(l,fs.second)) ret.insert(p);
        }
        if(fs.second+1<sc.second){
            for(auto p:solve(fs.second+1,sc.second)) ret.insert(p);
        }
        if(sc.second+1<r){
            for(auto p:solve(sc.second+1,r)) ret.insert(p);
        }
        vector<P> v;
        v.push_back({fs.first,sc.first});
        for(auto p:ret) v.push_back(p);
        return v;
    };

    auto ans=solve(0,n);
    rep(i,n/2) cout<<ans[i].first<<" "<<ans[i].second<<(i+1==n/2?"\n":" ");
    return 0;
}

