using usize = std::size_t;
using u32 = std::uint32_t;
using range = std::pair<usize, usize>;
template<class T>
using min_heap = std::priority_queue<T, std::vector<T>, std::greater<T>>;

int main() {
	usize n;
	std::cin >> n;
	std::vector<u32> a(n + 1, n + 1);
	std::vector<usize> s(n, n), t(n, n);
	for (usize i = 0; i < n; i++) {
		std::cin >> a[i];
		if (i & 1) t[i] = i;
		else s[i] = i;
	}

	auto f = [&] (const usize &lhs, const usize &rhs) {
		return (a[lhs] < a[rhs] ? lhs : rhs);
	};

	sparse_table<usize> st1(f), st2(f);
	st1.build(s.begin(), s.end());
	st2.build(t.begin(), t.end());

	std::vector<u32> ans;
	std::queue<range> que;
	min_heap<std::pair<u32, u32>> heap;
	ans.reserve(n);
	que.emplace(0, n);

	while (ans.size() < n) {
		std::queue<range> next;
		while (not que.empty()) {
			auto [l, r] = que.front(); que.pop();
			if (l == r) continue;
			usize i = ((l & 1) ? st2.fold(l, r) : st1.fold(l, r));
			usize j = ((l & 1) ? st1.fold(i, r) : st2.fold(i, r));
			heap.emplace(a[i], a[j]);
			next.emplace(l, i);
			next.emplace(i + 1, j);
			next.emplace(j + 1, r);

		}
		std::swap(que, next);
		auto p = heap.top(); heap.pop();
		ans.push_back(p.first);
		ans.push_back(p.second);
	}

	for (usize i = 0; i < n; i++) {
		std::cout << ans[i] << " \n"[i + 1 == n];
	}

	return 0;
}

