vector<int> shining(int l, int r) {
  vector<int> s;

  if (l == r) {
    return s;
  }

  int minE = N + 1;
  int minEI = l - 1;
  for (int i = l; i < r; i += 2) {
    if (p[i] < minE) {
      minE = p[i];
      minEI = i;
    }
  }
  s.push_back(minE);

  int minO = N + 1;
  int minOI = minEI;
  for (int i = minEI + 1; i < r; i += 2) {
    if (p[i] < minO) {
      minO = p[i];
      minOI = i;
    }
  }
  s.push_back(minO);

  vector<vector<int> > ss;
  ss.push_back(shining(l, minEI));
  ss.push_back(shining(minEI + 1, minOI));
  ss.push_back(shining(minOI + 1, r));

  int cnts[] = {0, 0, 0};
  while (true) {
    int min = N + 1;
    int minJ = -1;
    for (int j = 0; j < 3; j++) {
      if (cnts[j] < ss[j].size() && ss[j][cnts[j]] < min) {
	min = ss[j][cnts[j]];
	minJ = j;
      }
    }

    if (minJ == -1) {
      break;
    }

    s.push_back(min);
    s.push_back(ss[minJ][cnts[minJ] + 1]);
    cnts[minJ] += 2;
  }
}

