void build(int root,int left,int right)
{
	if (left==right)
	{
		if (left&1)
		{
			f[root][0]=a[left],f[root][1]=INF; 
		}
		else
		{
			f[root][1]=a[left],f[root][0]=INF;
		}
		return ;
	}
	int mid=(left+right)>>1;
	build(2*root,left,mid);
	build(2*root+1,mid+1,right);
	f[root][0]=min(f[2*root][0],f[2*root+1][0]);
	f[root][1]=min(f[2*root][1],f[2*root+1][1]); 
}	
int query(int root,int left,int right,int qleft,int qright,bool p)
{
	if (left>=qleft && right<=qright)
	{
		if (p)
		{
			return f[root][0];
		}
		else
		{
			return f[root][1];
		}
	}
	int mid=(left+right)>>1;
	if (qright<=mid)
	{
		return query(2*root,left,mid,qleft,qright,p);
	}
	else if (qleft>mid)
	{
		return query(2*root+1,mid+1,right,qleft,qright,p);
	}
	else
	{
		int ans1,ans2;
		ans1=query(2*root,left,mid,qleft,mid,p);
		ans2=query(2*root+1,mid+1,right,mid+1,qright,p);
		return min(ans1,ans2);
	}
}

