		return a.m > b.m;
	}
};

int min(int a, int b) {
	return a < b ? a : b;
}

int init(int node, int left, int right, int parity)
{
	int &ret = RMQ[parity][node];
	if (left == right)
		return ret = ((left % 2) == parity ? p[left] : INF);
	int mid = (left + right) / 2;
	return ret = min(init(2 * node, left, mid, parity), init(2 * node + 1, mid + 1, right, parity));
}

int query(int left, int right, int node, int nLeft, int nRight, int parity)
{
	if (right < nLeft || nRight < left)
		return 987654321;
	if (left <= nLeft && nRight <= right)
		return RMQ[parity][node];
	int nMid = (nLeft + nRight) / 2;
	return min(query(left, right, 2 * node, nLeft, nMid, parity),
		query(left, right, 2 * node + 1, nMid + 1, nRight, parity));
}

int q(int left, int right, int parity) {
	if (left > right)
		return INF;
	return query(left, right, 1, 0, N - 1, parity);
}

