		return 1000000000;
	int v1 = find_mn2(2*nd, ll, rr);
	int v2 = find_mn2(2*nd+1, ll, rr);
	if(v1 < v2)
		return v1;
	else
		return v2;
}

void calc(int ll, int rr, int seq)
{
	int l, r;
	if(ll+1==rr){
		L[m] = ll;
		R[m] = rr;
		S[m] = seq;
		m ++;
		return ;
	}
	if(ll%2==0){
		l = wh[find_mn1(1, ll, rr)];//
		r = wh[find_mn2(1, l, rr)];
	}
	else{
		l = wh[find_mn2(1, ll, rr)];
		r = wh[find_mn1(1, l, rr)];
	}
	L[m] = l;
	R[m] = r;
	S[m] = seq;
	m ++;
	int tm = m-1;
	if(l>ll){
		//calc(ll, l-1, m-1);
		calc(ll, l-1, tm);
	}
	if(r<rr)
		calc(r+1, rr, tm);
	if(l+1<r-1)
		calc(l+1, r-1, tm);
}

void solve()
{
	int i, j;
	n = 1;
	while(n<N)
		n *= 2;
	for(i=n; i<2*n; i++){
		Left[i] = i-n;
		Right[i] = i-n;
	}
	for(i=n-1; i>=1; i--){
		Left[i] = Left[2*i];
		Right[i] = Right[2*i+1];
	}
	for(i=n; i<n+N; i++){
		if( (i-n)%2 == 0)
			Tree1[i] = p[i-n];
		else
			Tree1[i] = 1000000000;
	}
	for(; i<2*n; i++){
		Tree1[i] = 1000000000;
	}
	for(i=n-1; i>=1; i--){//i--;
		if(Tree1[2*i] < Tree1[2*i+1])
			Tree1[i] = Tree1[2*i];
		else
			Tree1[i] = Tree1[2*i+1];
	}
	for(i=n; i<n+N; i++){
		if( (i-n)%2 == 1)
			Tree2[i] = p[i-n];
		else
			Tree2[i] = 1000000000;
	}
	for(; i<2*n; i++){
		Tree2[i] = 1000000000;
	}
	for(i=n-1; i>=1; i--){
		if(Tree2[2*i] < Tree2[2*i+1])
			Tree2[i] = Tree2[2*i];
		else
			Tree2[i] = Tree2[2*i+1];
	}

	for(i=0; i<N; i++){
		wh[p[i]] = i;
	}
	m = 0;
	calc(0, N-1, -1);//N
	for(i=0; i<m; i++){
		if(S[i] != -1)
			G[S[i]].push_back(i);
	}
	int u, v;
	for(i=0; i<m; i++){
		for(j=0; j<G[i].size(); j++){
			v = G[i][j];
			degree[v] ++;
		}
	}
	resL = 0;
	struct data dt, dt2;
	dt.seq = 0;
	dt.val = p[L[0]];
	pq.push(dt);
	while(!pq.empty() ){
		dt = pq.top() ;
		pq.pop() ;
		u = dt.seq ;
		res[resL] = p[L[u]];
		resL ++;
		res[resL] = p[R[u]];
		resL ++;
		for(i=0; i<G[u].size(); i++){
			v = G[u][i];
			degree[v] --;
			if(degree[v] == 0){
				dt2.seq = v;
				dt2.val = p[L[v]];
				pq.push(dt2);
			}
		}
	}
	printf("%d", res[0]);
	for(i=1; i<resL; i++){
		printf(" %d", res[i]);
	}
	printf("\n");
}

