  for (int i=0;i<N;++i){
    cin>>P[i];
    ind[P[i]] = i;
    if (i%2==0)A[i] = P[i];
    else A[i] = INF;
  }
  even = new node(0,N-1);
  for (int i=0;i<N;++i){
    if (i%2)A[i] = P[i];
    else A[i] = INF;
  }
  odd = new node(0,N-1);
  int cnt = 1, nxt = INF;
  for (int i=0;i<N;++i)A[i] = P[i];
  root = new newnode(0, N-1);
  // root->debug();
  // cout<<root->odd<<' '<<root->even<<'\n';

  for (int i=0;i<N/2;++i){
    root->ask();
    int curval = root->even;
    int curind = ind[curval];
    // cerr<<curval<<' '<<curind<<'\n';
    if (done.find(curind) != done.end())continue; // Already taken
    int abv = (*done.ub(curind)) - 1;
    int minval;
    if (curind%2==0){
      minval = odd->query(curind, abv);
    }else{
      minval = even->query(curind, abv);
    }
    // cerr<<"Pair " << curval<<' '<<minval<<'\n';
    int mindex = ind[minval];
    if (curind%2==0){
      odd->up(mindex, INF);
      even->up(curind, INF);
    }else{
      even->up(mindex, INF);
      odd ->up(curind,INF);
    }
    // cout<<curval<<' '<<minval<<' ';
    done.insert(curind);
    done.insert(mindex);
    root->erase(curind);
    root->erase(mindex);
    root->flip(curind, mindex);
  }
}

