// Segment Tree : 時間計算量 O(n log n), 空間計算量 O(n)
// require  : なし
// verified : 
//
// T はモノイド（単位元を持ち，結合則が成り立つ）であることが要求される
template <class T, class U = size_t>
struct SegTree {
	// !!! 実装時 t(lhs, rhs) の引数の順番に注意(意図せず可換則が要求されてしまう) !!!
	typedef typename T::V V;
	explicit SegTree(U _n = 0, const T &t = T()) : n(1), t(t) {
		while (n < _n) n *= 2;
		v.assign(n * 2 - 1, t.identity());
		if (n >= 2) {
			for (U i = n - 2;; --i) {
				v[i] = t(v[i * 2 + 1], v[i * 2 + 2]);
				if (i == 0) break; // Uが符号無し整数の可能性がある為こう実装している
			}
		}
	}
	V operator[](U i) const { return v[n - 1 + i]; }
	void set(U i, const V & x) {
		i += n - 1;
		v[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			v[i] = t(v[i * 2 + 1], v[i * 2 + 2]);
		}
	}
	// [a,b)の範囲についてのクエリを返す
	V get(U a, U b) const { return q(a, b, 0, 0, n); }
private:
	// t : traits のインスタンス
	// v : 完全二分木の配列表現
	// n : 完全二分木の葉の数
	T t;
	vector<V> v;
	U n;

	// [a,b)の範囲についてのクエリを返す
	// k     : 現在見ている接点の番号
	// [l,r) : kに対応した範囲 
	V q(U a, U b, U k, U l, U r) const {
		if (r <= a || b <= l) return t.identity(); // 範囲外
		if (a <= l && r <= b) return v[k];         // [l,r) ⊂ [a,b)

												   //[l,r)の一部が[a,b)に含まれる
		U c = (l + r) / 2;
		return t(
			q(a, b, k * 2 + 1, l, c),
			q(a, b, k * 2 + 2, c, r)
		);
	}
};
template <class T>
struct MinTrait {
	typedef T V;
	V identity() const { return TEN(10); }
	V operator()(const V &a, const V &b) const { return min(a, b); }
};

int main() {
	#ifdef INPUT_FROM_FILE
	ifstream cin("sample.in");
	ofstream cout("sample.out");
	#endif
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(50);

	ll n; cin >> n;
	vl a(n); REP(i, n) cin >> a[i], a[i]--;

	vl rev(n); REP(i, n) rev[a[i]] = i;

	SegTree<MinTrait<ll>> st_odd(n), st_even(n);
	REP(i, n) (i % 2 ? st_even : st_odd).set(i, a[i]);

	using P = tuple<ll, ll, ll, ll>;
	using vp = vector<P>;

	priority_queue<P, vp, greater<P>> que;
	auto f = [&](ll b, ll e) {
		if (b == e) return;
		ll i_l = rev[(b % 2 ? st_even : st_odd).get(b, e)];
		ll i_r = rev[(b % 2 ? st_odd : st_even).get(i_l, e)];
		que.push(P(a[i_l], a[i_r], b, e));
	};
	f(0, n);

	vl ans;
	while (!que.empty()) {
		ll lv, rv, b, e;
		tie(lv, rv, b, e) = que.top();
		ans.push_back(lv);
		ans.push_back(rv);
		que.pop();

		ll i_l = rev[lv], i_r = rev[rv];
		f(b, i_l);
		f(i_l + 1, i_r);
		f(i_r + 1, e);
	}
	REP(i, ans.size()) cout << ans[i] + 1 << (i != ans.size() - 1 ? " " : "");

	return 0;
}

