Q query1(int a,int b,int k,int l,int r){
//	cout<<a<<" "<<b<<" "<<k<<" "<<l<<" "<<r<<endl;
	if(r<=a||b<=l)return Q(INF,INF);
	if(a<=l&&r<=b)return seg1[k];
	else{
		Q v1=query1(a,b,k*2+1,l,(l+r)/2);
		Q v2=query1(a,b,k*2+2,(l+r)/2,r);
		return min(v1,v2);
	}
}
Q query2(int a,int b,int k,int l,int r){
//	cout<<a<<" "<<b<<" "<<k<<" "<<l<<" "<<r<<endl;
	if(r<=a||b<=l)return Q(INF,INF);
	if(a<=l&&r<=b)return seg2[k];
	else{
		Q v1=query2(a,b,k*2+1,l,(l+r)/2);
		Q v2=query2(a,b,k*2+2,(l+r)/2,r);
		return min(v1,v2);
	}
}
Q query(int a,int b,int k,int l,int r){
	if(a%2==0)return query1(a,b,k,l,r);
	return query2(a,b,k,l,r);
}

