template <class Monoid>
class SegmentTree {
  using T = typename Monoid::type;
  const int sz, n;
  std::vector<T> data;
  int expand(int n) const { return n == 1 ? n : expand((n + 1) / 2) * 2; }
public:
  SegmentTree(const std::vector<T> &init) :
    sz(init.size()), n(expand(sz)), data(n * 2, Monoid::id()) {
    std::copy(begin(init), end(init), begin(data) + n);
    for (int i = n - 1; i >= 0; --i) {
      data[i] = Monoid::op(data[i * 2 + 0], data[i * 2 + 1]);
    }
  }
  SegmentTree(const int n, const T &init = Monoid::id()) :
    SegmentTree(std::vector<T>(n, init)) {}
  int size() const { return sz; }
  void update(int p, T val) {
    assert (0 <= p && p < sz); // assertion
    data[p += n] = val;
    while (p /= 2) data[p] = Monoid::op(data[p * 2], data[p * 2 + 1]);
  }
  T query(int l, int r) const {
    assert (0 <= l && l <= r && r <= sz); // assertion
    l += n; r += n;
    T res1 = Monoid::id(), res2 = Monoid::id();
    while (l != r) {
      if (l % 2) res1 = Monoid::op(res1, data[l++]);
      if (r % 2) res2 = Monoid::op(data[--r], res2);
      l /= 2; r /= 2;
    }
    return Monoid::op(res1, res2);
  }
};

struct RMQ {
  using type = pair<int,int>;
  static type id() { return make_pair(INT_MAX, INT_MAX); }
  static type op(const type &l, const type &r) { return min(l, r); }
};

using P = pair<int, int>;
using T = tuple<P, P, P, P>;

T calc(const SegmentTree<RMQ> &even, const SegmentTree<RMQ> &odd, P section) {
  int l, r; tie(l, r) = section;
  P lx = (l % 2 == 0 ? even : odd).query(l, r);
  P rx = (l % 2 == 0 ? odd : even).query(lx.second + 1, r);
  return make_tuple(make_pair(lx.first, rx.first),
                    make_pair(l, lx.second),
                    make_pair(lx.second + 1, rx.second),
                    make_pair(rx.second + 1, r));
}

void solve(ll N, vector<ll> p) {
  SegmentTree<RMQ> even(N), odd(N);
  REP(i,N) {
    (i % 2 == 0 ? even : odd).update(i, make_pair(p[i], i));
  }
  priority_queue<T, vector<T>, greater<T>> que;
  que.push(calc(even, odd, make_pair(0, N)));
  vector<int> res;
  while (!que.empty()) {
    P val, a, b, c;
    tie(val, a, b, c) = que.top();
    que.pop();
    res.push_back(val.first);
    res.push_back(val.second);
    if (a.first < a.second) que.push(calc(even, odd, a));
    if (b.first < b.second) que.push(calc(even, odd, b));
    if (c.first < c.second) que.push(calc(even, odd, c));
  }
  REP(i,N) cout << res[i] << " \n"[i == N - 1];
}

