template <const int Size>
class sparse_table {
private:
  int value[Size + 5];
  int arr[20][Size + 5];
  int log2[Size + 5];
public:
  void init(int *a, int n) {
    for (int i = 2; i <= n; ++i)
      log2[i] = log2[i >> 1] + 1;
    for (int i = 1; i <= n; ++i) {
      value[i] = a[i];
      arr[0][i] = i;
    }
    for (int i = 1; (1 << i) <= n; ++i)
      for (int j = 1; j + (1 << i) - 1 <= n; ++j) {
        int vl = arr[i - 1][j], vr = arr[i - 1][j + (1 << (i - 1))];
        if (value[vl] < value[vr]) arr[i][j] = vl;
        else arr[i][j] = vr;
      }
  }

  inline int query(int l, int r) {
    int k = log2[r - l + 1];
    int vl = arr[k][l], vr = arr[k][r - (1 << k) + 1];
    if (value[vl] < value[vr]) return vl;
    else return vr;
  }
};
