    else tmp[i] = A[i];
  St[0].init(tmp, N);
  Pq.push(data(A[St[1].query(1, N)], 1, N));
  int cnt = 0;
  while (!Pq.empty()) {
    data d = Pq.top();
    // printf("d = (%d, %d, %d)\n", d.w, d.l, d.r);
    Pq.pop();
    int m1 = St[d.l & 1].query(d.l, d.r);
    int m2 = St[(m1 + 1) & 1].query(m1 + 1, d.r);
    B[++cnt] = A[m1];
    B[++cnt] = A[m2];
    if (d.l <= m1 - 1) Pq.push(data(A[St[d.l & 1].query(d.l, m1 - 1)], d.l, m1 - 1));
    if (m1 + 1 <= m2 - 1) Pq.push(data(A[St[(m1 + 1) & 1].query(m1 + 1, m2 - 1)], m1 + 1, m2 - 1));
    if (m2 + 1 <= d.r) Pq.push(data(A[St[(m2 + 1) & 1].query(m2 + 1, d.r)], m2 + 1, d.r));
  }
  for (int i = 1; i <= N; ++i)
    printf("%d%c", B[i], " \n"[i == N]);
}

