PP f(int l, int r) {
    P x, y;
    if(l % 2 == 0) {
        x = even.get(l, r);
        y = odd.get(x.sc, r);
    } else {
        x = odd.get(l, r);
        y = even.get(x.sc, r);
    }
    pa[x.fr] = y.fr;
    return make_pair(x.fr, make_pair(l, r));
}

void solve() {
	cin >> n;
    p.resize(n);
    pa.resize(n); 
    rep(i, n) {
        cin >> p[i];
    }
