        if(i % 2 == 0) {
            even.update(i, make_pair(p[i], i));
        } else {
            odd.update(i, make_pair(p[i], i));
        }
    }
    vector<int> ans;

    P x, y;
    x = even.get(0, n);
    y = odd.get(x.sc, n);
    pque.push(make_pair(x.fr, make_pair(0, n)));
    pa[x.fr] = y.fr;

    while(!pque.empty()) {
        PP q = pque.top(); pque.pop();
        int a = q.fr;
        ans.push_back(a);
        ans.push_back(pa[a]);

        int l = q.sc.fr, r = q.sc.sc;
        if(l % 2 == 0) {
            x = even.get(l, r);
            y = odd.get(x.sc, r);
        } else {
            x = odd.get(l, r);
            y = even.get(x.sc, r);
        }

        int u = x.sc, v = y.sc;
        if(l + 1 < u) pque.push(f(l, u));
        if(u + 1 < v) pque.push(f(u + 1, v));
        if(v + 1 < r) pque.push(f(v + 1, r));
    }

    for(auto& z: ans) {
        cout << z << " ";
    }
    cout << endl;
}

