    if (i%2==0)A[i] = P[i];
    else A[i] = INF;
  }
  even = new node(0,N);
  for (int i=0;i<N;++i){
    if (i%2)A[i] = P[i];
    else A[i] = INF;
  }
  odd = new node(0,N);
  int cnt = 1, nxt = INF;
  for (int i=0;i<N;++i)A[i] = P[i];
  all = new node(0,N);

  while (SZ(ans) != N){
    int curval = cnt++;
    if (nxt != INF){
      curval= nxt;
      nxt = INF;
      --cnt;
    }
    int curind = ind[curval];
    if (done.find(curind) != done.end())continue; // Already taken
    if (remain(curind)%2)continue; // Odd number left on left side
    int abv = (*done.ub(curind)) - 1;
    int minval;
    if (curind%2==0){
      minval = odd->query(curind, abv);
    }else{
      minval = even->query(curind, abv);
    }
    // cerr<<curval<<' '<<minval<<'\n';
    int mindex = ind[minval];
    if (curind%2==0){
      odd->up(mindex, INF);
      even->up(curind, INF);
    }else{
      even->up(mindex, INF);
      odd ->up(curind,INF);
    }
    ans.pb(curval);
    ans.pb(minval);
    done.insert(curind);
    done.insert(mindex);
    update(curind,-1);
    update(mindex, -1);
    all->up(curind, INF);
    all->up(mindex, INF);
    nxt = all->query(curind, mindex);
  }
  for (auto i : ans)cout<<i<<' ';
}

