// [a,b)の最小値
pll query(int a, int b, int k, int l, int r,vector<pll>& dat) {
	// [a,b)と[l,r)が交差しなければ,INT_MAX
	if (r <= a || b <= l) return{ INF,INF };
	// [a,b)が[l,r)を完全に含んでいれば,この節点の値
	if (a <= l && r <= b) return dat[k];
	else {
		pll vl = query(a, b, k * 2 + 1, l, (l + r) / 2, dat);
		pll vr = query(a, b, k * 2 + 2, (l + r) / 2, r, dat);
		return min(vl, vr);
	}
}
