struct cmp {
	bool operator () (pii lef, pii rig) {
		return a[lef.fi.fi] > a[rig.fi.fi];
	};
};

priority_queue<pii, vector<pii>, cmp> q;

struct node {
	int odd, even, posOdd, posEven;
};

class segmentTree {
public:
	node it[maxN * 4];
	int L[maxN * 4], R[maxN * 4];

	node combine(node a, node b) {
		node res;
		if (a.odd < b.odd) {
			res.odd = a.odd;
			res.posOdd = a.posOdd;
		}
		else {
			res.odd = b.odd;
			res.posOdd = b.posOdd;
		}
		if (a.even < b.even) {
			res.even = a.even;
			res.posEven = a.posEven;
		}
		else {
			res.even = b.even;
			res.posEven = b.posEven;
		}
		return res;
	}

	void buildTree(int x, int low, int high) {
		L[x] = low; R[x] = high;
		if (low == high) {
			it[x] = {INF, INF, low, low};
			if (low % 2 == 1) {
				it[x].odd = a[low];
			}
			else {
				it[x].even = a[low];
			}
			return;
		}
		int mid = (low + high) / 2;
		buildTree(LL(x), low, mid);
		buildTree(RR(x), mid + 1, high);
		it[x] = combine(it[LL(x)], it[RR(x)]);
	}

	node query(int x, int low, int high) {
		if (L[x] > high || R[x] < low) return {INF, INF, INF, INF};
		if (low <= L[x] && R[x] <= high) {
			return it[x];
		}
		return combine(query(LL(x), low, high), query(RR(x), low, high));
	}
} tree;

void enter() {
	cin >> N;
	for (int i = 1; i <= N; ++i) {
		cin >> a[i];
	}
}

pair<int, int> solve(int l, int r) {
	if (vis[{l, r}]) return dp[{l, r}];
	int ll, rr;
	if (l % 2 == 1) {
		ll = tree.query(1, l, r).posOdd;
		rr = tree.query(1, ll, r).posEven;
	}
	else {
		ll = tree.query(1, l, r).posEven;
		rr = tree.query(1, ll, r).posOdd;
	}
	vis[{l, r}] = true;
	dp[{l, r}] = {ll, rr};
	return {ll, rr};
}

void prepare() {
	tree.buildTree(1, 1, N);
}

vector<pair<int, int> > res;

void solve() {
	prepare();
	q.push({solve(1, N), {1, N}});
	while (!q.empty()) {
		pii u = q.top(); q.pop();
		pair<int, int> in = u.fi;
		pair<int, int> out = u.se;
		//cerr << in.fi << " " << in.se << flush << endl;
		res.push_back(in);
		if (in.fi != out.fi) {
			q.push({solve(out.fi, in.fi - 1), {out.fi, in.fi - 1}});
		}
		if (in.se != out.se) {
			q.push({solve(in.se + 1, out.se), {in.se + 1, out.se}});
		}
		if (in.fi + 1 != in.se) {
			q.push({solve(in.fi + 1, in.se - 1), {in.fi + 1, in.se - 1}});
		}
	}

	for (int i = 0; i < res.size(); ++i) {
		cout << a[res[i].fi] << " " << a[res[i].se] << " ";
	}
}

int main() {
	openFile();
	enter();
	solve();
	return 0;
}

