const int N = 200 * 1000;
const int INF = 228228228;

struct
{
	pair<int, int> mn0 = {INF, -1};
	pair<int, int> mn1 = {INF, -1};
} t[4 * N];

pair<int, int> get_t(int v, int l, int r, int L, int R, bool p)
{
	if(R <= l || r <= L)
	{
		return {INF, -1};
	}

	if(L <= l && r <= R)
	{
		if(p)
		{
			return t[v].mn1;
		}
		else
		{
			return t[v].mn0;
		}
	}

	return min(
	get_t(v << 1, l, (l + r) >> 1, L, R, p),
	get_t(v << 1 | 1, (l + r) >> 1, r, L, R, p)
	);
}

void build_t(int v, int l, int r, vector<int> &a)
{
	if(r - l == 1)
	{
		if(l & 1)
		{
			t[v].mn1 = {a[l], l};
		}
		else
		{
			t[v].mn0 = {a[l], l};
		}
	}
	else
	{
		build_t(v << 1, l, (l + r) >> 1, a);
		build_t(v << 1 | 1, (l + r) >> 1, r, a);
		t[v].mn0 = min(t[v << 1].mn0, t[v << 1 | 1].mn0);
		t[v].mn1 = min(t[v << 1].mn1, t[v << 1 | 1].mn1);
	}
}

int n;
vector<int> v;

struct ans
{
	pair<int, int> p;
	vector<ans*> v;
};

bool operator<(const ans &a, const ans &b)
{
	return a.p < b.p;
}

ans* solve(int l, int r, bool p)
{
	assert(((r - l) & 1) == 0); 
	if(r - l == 0)
	{
		return nullptr;
	}

	int p1 = get_t(1, 0, n, l, r, p).y;
	int p2 = get_t(1, 0, n, p1 + 1, r, !p).y;

	ans *a = new ans;
	a->p = {v[p1], v[p2]};

	auto a1 = solve(l, p1, p);
	auto a2 = solve(p1 + 1, p2, !p);
	auto a3 = solve(p2 + 1, r, p);

	if(a1 != nullptr)
		a->v.push_back(a1);
	if(a2 != nullptr)
		a->v.push_back(a2);
	if(a3 != nullptr)
		a->v.push_back(a3);

	return a;
}

