void upd(bool tt ,int v , int tl , int tr , int pos){
	if(a[t[tt][v]] > a[pos])
		t[tt][v] = pos;
	if(tl == tr)
		return;
	int tm = (tl + tr) >> 1;
	if((pos + 1)/2 <= tm)
		upd(tt , v << 1 , tl , tm , pos);
	else upd(tt , v << 1 |1 , tm + 1 , tr , pos);
}
int comb(int p1 , int p2){
	if(a[p1] > a[p2])
		return p2;
	else return p1;
}
int get(bool tt , int v , int tl , int tr , int l , int r){
	if(l > r or l > tr or tl > r)
		return 0;
	if(l <= tl and tr <= r){
		return t[tt][v];
	}
	int tm = (tl + tr) >> 1;
	return comb(get(tt , v << 1 , tl , tm , l , r) , get(tt , v << 1|1 , tm + 1 , tr , l , r));
}
