	while(id != n / 2){
		for(auto x : seg){
			int l = x.fi.fi , r = x.fi.se , P = x.se;
			int p1 , p2; 
			if(l + 1 == r){
				val[++id] = {a[l] , a[r]};
				par[id] = x.se;
				continue;
			}
			if(l % 2 == 1)
				p1 = get(l&1 , 1 , 1, n / 2 , (l+1)/2 , (r+1)/2),
				p2 = get(r&1 , 1 ,1 , n / 2 , (p1 + 1)/2 , (r + 1)/2);
			else 
			 	p1 = get(l&1 , 1 , 1, n / 2 , (l+1)/2 , (r)/2),
			 	p2 = get(r&1 , 1 , 1 , n / 2 , (p1 + 1)/2 + 1, (r + 1)/2);
			val[++id] = {a[p1] , a[p2]};
			par[id] = P;
			if(l < p1 - 1)
				seg2.pb({{l , p1 - 1}, id });
			if(p1 + 1 < p2 - 1)
				seg2.pb({{p1 + 1 , p2 - 1}, id });
			if(p2 + 1 < r)
				seg2.pb({{p2 + 1, r} , id});
    	}
    	seg.clear();
    	seg.swap(seg2);
    }


}
