typedef long long ll;
typedef pair<ll, ll> P;

const ll MAX_N = 1 << 17;
const ll INF=1e15;
struct Data{
  P val;
  bool operator < (const Data &rhs) const {
    return val < rhs.val;
  }
  Data():val(0, 0){;}
  Data(ll v, ll i):val(v, i){;}
};
const Data ELE(INF, INF);
Data ope(Data a, Data b){
  return min(a, b);
}
struct SegT{
  ll n;
  vector<Data> dat;
  //init
  SegT(ll n_):n(1),dat(2*MAX_N-1,ELE){
    while(n<n_)
      n*=2;
  }
  //change k-th num to a
  void update(ll k, P a){
    k+=n-1;
    dat[k].val=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=ope(dat[k*2+1],dat[k*2+2]);
    }
  }
  Data query_(int a, int b, int k, int l, int r){
    if(r<=a || b<=l) return ELE;
    if(a<=l && r<=b) return dat[k];
    else return ope(query_(a,b,k*2+1,l,(l+r)/2), query_(a,b,k*2+2,(l+r)/2,r));
  }
  Data query(int left, int right){return query_(left,right+1,0,0,n);}
};

