#define rs rt<<1|1
const int maxn = 200005;

int p[maxn],pos[maxn],n,N;
int a[maxn],b[maxn],c[maxn];
struct ST {
	int mi[maxn*4];
	int query(int rt,int L,int R,int l,int r)
	{
		if (L>=l&&R<=r) return mi[rt];
		int mid=L+R>>1,res=1<<30;
		if (l<=mid) res=min(res,query(ls,L,mid,l,r));
		if (r>mid) res=min(res,query(rs,mid+1,R,l,r));
		return res;
	}
	void build(int rt,int L,int R,int o)
	{
		if (L>=R) {
			mi[rt]=p[L<<1|o];return ;
		}
		int mid=L+R>>1;
		build(ls,L,mid,o);
		build(rs,mid+1,R,o);
		mi[rt]=min(mi[ls],mi[rs]);
	}
}od,ev;
void solve(int l,int r)
{
	if (l+2>r) return ;
	int sl,sr;
	if (l&1) {
		sl=pos[od.query(1,0,N,l>>1,r-1>>1)];
		sr=pos[ev.query(1,0,N,sl+1>>1,r>>1)];
	}
	else {
		sl=pos[ev.query(1,0,N,l>>1,r-1>>1)];
		sr=pos[od.query(1,0,N,sl+1>>1,r>>1)];
	}
	solve(l,sl-1);solve(sl+1,sr-1);solve(sr+1,r);
	int sa=0,sb=0,sc=0,i=l,u=p[sl],v=p[sr];
	for (int j=l;j<=sl-1;j++) a[++sa]=p[j];
	for (int j=sl+1;j<=sr-1;j++) b[++sb]=p[j];
	for (int j=sr+1;j<=r;j++) c[++sc]=p[j];
	p[i++]=u;p[i++]=v;a[sa+1]=b[sb+1]=c[sc+1]=1<<30;
	int ia=1,ib=1,ic=1;
	while (ia<=sa||ib<=sb||ic<=sc)
	{
		if (a[ia]<b[ib]&&a[ia]<c[ic]) p[i++]=a[ia++],p[i++]=a[ia++];
		else if (b[ib]<c[ic]) p[i++]=b[ib++],p[i++]=b[ib++];
		else p[i++]=c[ic++],p[i++]=c[ic++];
	}
}
