			up(1,n,i) data[0][i]=INF;
			up(1,n/2,i) data[0][(i<<1)-type]=P[(i<<1)-type],
						pos[0][(i<<1)-type]=(i<<1)-type;
			up(1,18,i) up(1,n,j){
