			}
		}
		void gtmn(int L,int R,int &mn,int &ps){
			int delta=R-L+1,cnt=0;
			while((1<<cnt)<=delta) cnt++; cnt--;
			ps=(data[cnt][L]<data[cnt][R-(1<<cnt)+1]?
				pos[cnt][L]:pos[cnt][R-(1<<cnt)+1]);
			mn=min(data[cnt][L],data[cnt][R-(1<<cnt)+1]);
		}
