#define SZ 666666
int n,a[SZ];
const int M=262144;
int ls[SZ],rs[SZ],ss[SZ];
bool fl[SZ];
pii ps[SZ];
pii mg(pii a,pii b)
{
	return pii(min(a.fi,b.fi),min(a.se,b.se));
}
int qr(int p)
{
	static int s1[SZ],s2[SZ];
	int n1=0,n2=0;
	for(int l=p+M-1,r=n+M+3;l^r^1;l>>=1,r>>=1)
	{
		if(~l&1) s1[++n1]=l^1;
		if(r&1) s2[++n2]=r^1;
	}
	while(n2) s1[++n1]=s2[n2--];
	int g;
	for(int i=1;i<=n1;++i)
		if(ss[s1[i]]) {g=s1[i]; break;}
	while(g<M)
	{
		if(ss[g+g]) g=g+g;
		else g=g+g+1;
	}
	return rs[g]-1;
}
void sett(int x)
{
	for(x+=M;x;x>>=1) ss[x]=1;
}
void build()
{
	for(int i=1;i<=M;++i) ls[i+M]=rs[i+M]=i;
	for(int i=1;i<=n;++i)
		if((n-i)&1) ps[i+M]=pii(a[i],1e9);
		else ps[i+M]=pii(1e9,a[i]);
	for(int i=M-1;i>=1;--i)
		ls[i]=ls[i+i],rs[i]=rs[i+i+1],
		ps[i]=mg(ps[i+i],ps[i+i+1]);
}
void pd(int x)
{
	if(fl[x])
	{
		swap(ps[x].fi,ps[x].se);
		if(x<=M) fl[x+x]^=1, fl[x+x+1]^=1;
		fl[x]=0;
	}
}
void upd(int x)
{
	pd(x+x); pd(x+x+1);
	ps[x]=mg(ps[x+x],ps[x+x+1]);
}
pii qry(int x,int l,int r)
{
	if(rs[x]<l||r<ls[x]) return pii(1e9,1e9);
	pd(x);
	if(l<=ls[x]&&rs[x]<=r)
		return ps[x];
	pii t=mg(qry(x+x,l,r),qry(x+x+1,l,r));
	upd(x); return t;
}
void del(int p)
{
	int x=1;
	while(1)
	{
		pd(x);
		if(x>M) break;
		if(p<=rs[x+x]) x=x+x;
		else x=x+x+1;
	}
	ps[x]=pii(1e9,1e9);
	for(x>>=1;x;x>>=1)
		ps[x]=mg(ps[x+x],ps[x+x+1]); 
}
void flip(int x,int l,int r)
{
	if(rs[x]<l||r<ls[x]) return;
	pd(x);
	if(l<=ls[x]&&rs[x]<=r) {fl[x]^=1; return;}
	flip(x+x,l,r); flip(x+x+1,l,r); upd(x);
}
int os[SZ],on=0,rv[SZ];
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;++i) scanf("%d",a+i),rv[a[i]]=i;
	build(); sett(n+1);
	while(on<n)
	{
		int x=rv[qry(1,1,n).fi],t=qr(x);
		int y=rv[qry(1,x,t).se];
		os[++on]=a[x]; os[++on]=a[y];
		flip(1,x,y);
		del(x); del(y);
		sett(x); sett(y);
	}
	for(int i=1;i<=on;++i) printf("%d ",os[i]);
}
