void go(int l, int r, vector<ii> &ret) {
  if(l >= r or r >= n or l < 0) return;
  int menorev, menorodd;
  assert((r - l) % 2 == 1);
  if((l % 2) == 0) {
    menorev = even.query(1, 0, n - 1, l, r);
    menorodd = odd.query(1, 0, n - 1, menorev + 1, r);
  }
  else {
    menorev = odd.query(1, 0, n - 1, l, r);
    menorodd = even.query(1, 0, n - 1, menorev + 1, r);
  }
  assert(menorev != -1 and menorodd != -1);
  vector<ii> a;
  go(l, menorev - 1, a);
  vector<ii> b;
  go(menorev + 1, menorodd - 1, b);
  vector<ii> c;
  go(menorodd + 1, r, c);
  int pta = 0;
  int ptb = 0;
  int ptc = 0;
  ret.pb(mp(p[menorev], p[menorodd]));
  while(pta < a.size() or ptb < b.size() or ptc < c.size()) {
    if(pta == a.size()) {
      if(ptb == b.size()) {
        ret.pb(c[ptc]);
        ptc++;
      }
      else if(ptc == c.size()) {
        ret.pb(b[ptb]);
        ptb++;
      }
      else if(b[ptb] < c[ptc]) {
        ret.pb(b[ptb]);
        ptb++;
      }
      else {
        ret.pb(c[ptc]);
        ptc++;
      }
    }
    else if(ptb == b.size()) {
      if(ptc == c.size()) {
        ret.pb(a[pta]);
        pta++;
      }
      else if(a[pta] < c[ptc]) {
        ret.pb(a[pta]);
        pta++;
      }
      else {
        ret.pb(c[ptc]);
        ptc++;
      }
    }
    else if(ptc == c.size()) {
      if(a[pta] < b[ptb]) {
        ret.pb(a[pta]);
        pta++;
      }
      else {
        ret.pb(b[ptb]);
        ptb++;
      }
    }
    else {
      if(a[pta] < b[ptb] and a[pta] < c[ptc]) {
        ret.pb(a[pta]);
        pta++;
      }
      else if(b[ptb] < a[pta] and b[ptb] < c[ptc]) {
        ret.pb(b[ptb]);
        ptb++;
      }
      else {
        ret.pb(c[ptc]);
        ptc++;
      }
    } 
  }
}

