const int MAXN = 2e5;
const int MAX_LOG = (int) log2 (MAXN);

int N, A[MAXN + 5];

struct RMQ
{

	int Log[MAXN + 5];
	pii Min[MAX_LOG + 1][MAXN + 5];

	inline void init ()
	{
		Log[1] = 0; for (int i = 2; i <= N; ++i) Log[i] = Log[i >> 1] + 1;
		for (int i = 1; i <= N; ++i) Min[0][i] = mp (A[i], i);
		for (int i = 1; i <= Log[N]; ++i)
			for (int j = 1; j + (1 << i) - 1 <= N; ++j)
				Min[i][j] = min (Min[i - 1][j], Min[i - 1][j + (1 << (i - 1))]);
	}

	inline pii query (int l, int r) 
	{ 
		int k = Log[r - l + 1];
		return min (Min[k][l], Min[k][r - (1 << k) + 1]);
	}
} T[2];

priority_queue <pii, vector <pii>, greater <pii> > Q;

inline void Init ()
{
	static int B[MAXN + 5];
	for (int i = 1; i <= N; ++i) B[i] = A[i];
	for (int i = 1; i <= N; i += 2) A[i] = 0x3f3f3f3f;
	T[0].init ();
	for (int i = 1; i <= N; ++i) A[i] = B[i];
	for (int i = 0; i <= N; i += 2) A[i] = 0x3f3f3f3f;
	T[1].init ();
	for (int i = 1; i <= N; ++i) A[i] = B[i];
	Q.push (T[1].query (1, N));
}

set <int> S;

inline void update (int l, int r)
{
	if (l > r) return ;
	Q.push (T[l & 1].query (l, r));
}

inline void Solve ()
{
	Init ();

	S.insert (0), S.insert (N + 1);
	for (int n = N / 2; n; --n)
	{
		int x = Q.top().y; Q.pop();
		int xr = *S.upper_bound (x), y = T[!(x & 1)].query (x + 1, xr - 1).y;
		printf("%d %d ", A[x], A[y]);

		S.insert (x), S.insert (y);
		int l = *(--S.lower_bound (x)), r = *S.upper_bound (y);

		update (l + 1, x - 1);
		update (x + 1, y - 1);
		update (y + 1, r - 1);
	}
}

inline void Input ()
{
	N = read<int>();
	for (int i = 1; i <= N; ++i) A[i] = read<int>();
}

int main ()
{

	Input ();
	Solve ();

	return 0;
}

