    using T = pair<int, int>;
    const T PINF = make_pair(INF, INF);
    vector<T> even(N, PINF), odd(N, PINF);
    REP(i, N) (i & 1 ? odd[i] : even[i]) = T(P[i], i);
    auto f = [](T a, T b) -> T { return min(a, b); };
    SparseTable<T> st_even(even, f), st_odd(odd, f);

    auto query = [&](int l, int r) -> T {
        if (l & 1) return st_odd.query(l, r);
        return st_even.query(l, r);
    };

    // min, [l, r]
    prique_r<tuple<int, int, int>> pq;
    pq.emplace(query(0, N).first, 0, N - 1);

    vector<int> res;
    while (not pq.empty()) {
        int mn, l, r;
        tie(mn, l, r) = pq.top();   pq.pop();
        int val, idx_l, idx_r;
        tie(val, idx_l) = query(l, r + 1);
        res.emplace_back(val);
        tie(val, idx_r) = query(idx_l + 1, r + 1);
        res.emplace_back(val);
        if (l < idx_l - 1)          pq.emplace(query(l,         idx_l).first, l,         idx_l - 1);    // [l, idx_l - 1]
        if (idx_l + 1 < idx_r - 1)  pq.emplace(query(idx_l + 1, idx_r).first, idx_l + 1, idx_r - 1);    // [idx_l + 1, idx_r - 1]
        if (idx_r + 1 < r)          pq.emplace(query(idx_r + 1, r + 1).first, idx_r + 1, r        );    // [idx_r + 1, r]
        // debug(res);
    }
    PV(res);

}

