void upd(int x) {
	odd[x] = odd[L] <= odd[R] ? odd[L] : odd[R];
	op[x] = odd[L] <= odd[R] ? op[L] : op[R];

	eve[x] = eve[L] <= eve[R] ? eve[L] : eve[R];
	ep[x] = eve[L] <= eve[R] ? ep[L] : ep[R];
}

void build(int x, int l, int r) {
	if(l == r) {
		odd[x] = eve[x] = N;
		op[x] = ep[x] = l;
		if(l % 2) odd[x] = a[l];
		else eve[x] = a[l];
	}
	else {
		L = ++ cnt; R = ++ cnt;
		build(L, l, mid);
		build(R, mid + 1, r);
		upd(x);
	}
}

int query(int x, int l, int r, int ll, int rr, int OE) {
	if(l >= ll && r <= rr) return OE ? op[x] : ep[x];
	int ans = 0;
	if(mid >= ll) {
		int p = query(L, l, mid, ll, rr, OE);
		if(!ans || a[p] < a[ans]) ans = p;
	}
	if(mid < rr) {
		int p = query(R, mid + 1, r, ll, rr, OE);
		if(!ans || a[p] < a[ans]) ans = p;
	}
	return ans;
}

