	if(r > nod[x].latter) nod[x].son.push_back(solve(nod[x].latter + 1, r, P));
	if(nod[x].former + 1 != nod[x].latter) nod[x].son.push_back(solve(nod[x].former + 1, nod[x].latter - 1, P ^ 1));
