int arr[200010];

struct indexed_tree {
	vector<pii> tree;
	int k = 1;
	indexed_tree(int n) {
		while (k < n)k *= 2;
		tree.resize(k * 2 + 10, { 0x7fffffff,-1 });
	}
	void update(int idx, pii a) {
		idx += k;
		while (idx) {
			tree[idx] = std::min(tree[idx], a);
			idx /= 2;
		}
	}
	pii getRange(int left, int right) {
		left += k; right += k;
		pii ret = { 0x7fffffff,-1 };
		while (left <= right) {
			if (left % 2 == 1)ret = std::min(ret, tree[left]);
			if (right % 2 == 0)ret = std::min(ret, tree[right]);
			left = (left + 1) / 2;
			right = (right - 1) / 2;
		}
		return ret;
	}
};
indexed_tree odd(200000), even(200000);
vector<pii> divide(int left, int right) {
	if (left > right)return{};
	auto O = odd.getRange(left, right);
	auto E = even.getRange(left, right);
	int o = O.first;
	int e = E.first;
	int oidx = O.second;
	int eidx = E.second;
	vector<pii> ret;
	if (left % 2 == 0) {
		ret.push_back({ e,o });
	}
	else {
		ret.push_back({ o,e });
	}
	if (oidx > eidx)std::swap(oidx, eidx);
	auto A = divide(left, oidx - 1);
	auto B = divide(oidx + 1, eidx - 1);
	auto C = divide(eidx + 1, right);
	ret.insert(ret.end(), A.begin(), A.end());
	ret.insert(ret.end(), B.begin(), B.end());
	ret.insert(ret.end(), C.begin(), C.end());
	std::sort(ret.begin()+1, ret.end());
	return ret;
}
