  newnode *l, *r;

  newnode(int _s, int _e){
    s=_s; e=_e; m=(s+e)/2;
    odd = even = INF; lazy=0;
    if (s == e){
      if (s%2 == 1)odd = A[s];
      else even = A[s];
    }
    else{
      l = new newnode(s, m);
      r = new newnode(m+1, e);
      odd = min(l->odd,r->odd);
      even = min(l->even,r->even);
    }
  }

