const int MAX_N = 2e5 + 100;

struct IDX{
	int P; vector<int> val;
	IDX() {}
	IDX(vector<int> nr) {
		int n = SZ(nr);
		for(P=1; P<n; P<<=1);
		val = vector<int>(2*P, INF);
		for(int i=0; i<P; i++) val[P+i] = (i<n ? nr[i] : INF);
		for(int i=P-1; i>=1; i--) val[i] = min(val[i*2], val[i*2+1]);
	}
	int getMin(int a, int b) {
		int res = INF;
		for(a+=P, b+=P; a<=b; a>>=1, b>>=1) {
			if(a%2==1) res = min(res, val[a++]);
			if(b%2==0) res = min(res, val[b--]);
		}
		return res;
	}
};

