		b = Re[idx[r%2].getMin((a+1)/2, r/2)];
	}
	pi getLR() const {return pi(l, r);}
	pi getAB() const {return pi(a, b);}
	bool operator<(const NODE &o) const{return Nr[a] > Nr[o.a];}
};
