struct RMQ{
	int n = 1, inf = 1 << 30;
	vector<int> tree;

	RMQ(int n_){
		while((n *= 2) < n_);
		tree.assign(2 * n, inf);
	}

	void update(int k, int x){
		tree[k += n] = x;
		while(k){
			k /= 2;
			tree[k] = min(tree[2 * k], tree[2 * k + 1]);
		}
	}

	int rmq(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return inf;
		if(a <= l && r <= b) return tree[k];
		return min(rmq(a, b, 2 * k, l, (l + r) / 2), rmq(a, b, 2 * k + 1, (l + r) / 2, r));
	}

	int rmq(int a, int b){
		return rmq(a, b, 1, 0, n);
	}
};

