		std::swap(a[0], a[1]);
	}
} t[S];
char rev[S];

inline int pmin(int a, int b) {
	return A[a] < A[b] ? a : b;
}
inline node operator+(const node &a, const node &b) {
	return {pmin(a[0], b[0]), pmin(a[1], b[1]), a.b || b.b};
}
inline void build(int l, int r, int k) {
	if (l == r) {
		t[k][l & 1] = l;
		return;
	}
	int mid = (l + r) >> 1;
	build(l, mid, k << 1);
	build(mid + 1, r, k << 1 | 1);
	t[k] = t[k << 1] + t[k << 1 | 1];
}
inline void reverse(int k) {
	t[k].swap(); rev[k] ^= 1;
}
inline void pushdown(int k) {
	if (rev[k]) {
		reverse(k << 1);
		reverse(k << 1 | 1);
		rev[k] = 0;
	}
}
inline node query(int l, int r, int a, int b, bool c, int k) {
	if (l >= a && r <= b) return t[k];
	pushdown(k);
	int mid = (l + r) >> 1;
	if (a > mid) return query(mid + 1, r, a, b, c, k << 1 | 1);
	node res = query(l, mid, a, b, c, k << 1);
	if (b > mid && (!c || !res.b)) res = res + query(mid + 1, r, a, b, c, k << 1 | 1);
	return res;
}
inline void modify(int l, int r, int a, int b, int k) {
	if (l >= a && r <= b) return reverse(k);
	pushdown(k);
	int mid = (l + r) >> 1;
	if (a <= mid) modify(l, mid, a, b, k << 1);
	if (b > mid) modify(mid + 1, r, a, b, k << 1 | 1);
	t[k] = t[k << 1] + t[k << 1 | 1];
}
inline void clear(int l, int r, int a, int k) {
	if (l == r) {
		t[k][0] = t[k][1] = 0;
		t[k].b = 1;
		return;
	}
	pushdown(k);
	int mid = (l + r) >> 1;
	if (a <= mid) clear(l, mid, a, k << 1);
	else clear(mid + 1, r, a, k << 1 | 1);
	t[k] = t[k << 1] + t[k << 1 | 1];
}

inline int _(int x) {
	return A[x] > n ? 0 : A[x];
}
inline void traverse(int l, int r, int k, int dep = 0) {
	for (int i = dep; i--; ) printf("  ");
	printf("[%d, %d] %d %d\n", l, r, _(t[k][0]), _(t[k][1]));
	if (l == r) return;
	pushdown(k);
	int mid = (l + r) >> 1;
	traverse(l, mid, k << 1, dep + 1);
	traverse(mid + 1, r, k << 1 | 1, dep + 1);
}

