			t[i] = pii(0, 0);
		}
	}
	void update(int x, int val, int c, int b, int e) {
		if(b == e) {
			t[c] = pii(val, b);
			return ;
		}
		int m = (b + e) >> 1;
		int l = c << 1;
		int r = l + 1;
		if(x <= m) update(x, val, l, b, m);
		else update(x, val, r, m+1, e);
		t[c] = min(t[l], t[r]);
	}
	pii query(int x, int y, int c, int b, int e) {
		if(x <= b && e <= y) {
			return t[c];
		}
		if(y < b || e < x) return pii(inf, inf);
		int m = (b + e) >> 1;
		int l = c << 1;
		int r = l + 1;
		return min(query(x, y, l, b, m), query(x, y, r, m+1, e));
	}
	void update(int x, int val) {
		update(x, val, 1, 1, size);
	}
	pii query(int x, int y) {
		return query(x, y, 1, 1, size);
	}
} t[2];
