	SegmentTree(){
		FOR(i,4*MAXN)st[i] = {MAXN,-1};
	}
	ii merge(ii a,ii b){
		if(a.ff < b.ff)return a;else return b;
	}
	void update(int node,int ss,int se,int i,int val){
		if(ss > i or i > se)return;
		if(ss == se){
			st[node] = {val,i};
		}else{
			int mid = (ss+se)/2;
			update(node*2+1,ss,mid,i,val);
			update(node*2+2,mid+1,se,i,val);
			st[node] = merge(st[node*2+1],st[node*2+2]);
		}
	}
	ii get(int node,int ss,int se,int l,int r){
		if(l > se or r < ss)return {MAXN,-1};
		if(l <= ss and se <= r)return st[node];
		int mid = (ss+se)/2;
		return merge(get(node*2+1,ss,mid,l,r),get(node*2+2,mid+1,se,l,r));
	}
} st[2];





