const int INF = 1e9;

struct SegmTree {
	vii t;
	int sz;

	SegmTree(int n = 0) {
		sz = 1;
		while (sz < n) sz *= 2;
		t.assign(sz * 2, mp(INF, -1));
	}

	pii get_min(int l, int r) {
		assert(l <= r);
		assert(r < sz);
		assert(0 <= l);
		l += sz;
		r += sz;
		pii res(INF, -1);
		while (l <= r) {
			res = min(res, t[l]);
			res = min(res, t[r]);
			l = (l + 1) >> 1;
			r = (r - 1) >> 1;
		}
		return res;
	}

	void put(int pos, int val) {
		int v = sz + pos;
		t[v] = mp(val, pos);
		v >>= 1;
		while (v) {
			t[v] = min(t[v * 2], t[v * 2 + 1]);
			v >>= 1;
		}
	}
};

int expand(int pos, int parity) {
	if  (pos == -1) {
		return -1;
	}
	if  (parity == 1) {
		return pos * 2 + 1;
	}
	return pos * 2;
}

vector<SegmTree> T;

struct Seg {
	int l, r;
	pii poses;

	Seg(int l, int r) : l(l), r(r) {
		assert(l < r);
		assert((r - l + 1) % 2 == 0);
		int pos = expand(T[l & 1].get_min(l / 2, (r - 1) / 2).snd, l & 1);
		int pos2 = expand(T[~l & 1].get_min((pos + 1) / 2, r / 2).snd, ~l & 1);
		poses = mp(pos, pos2);
	}

	pii calc() const {
		return mp(p[poses.fst], p[poses.snd]);
	}

	bool operator < (const Seg& s) const {
		return calc() < s.calc();
	}
};

void solve() {
	assert(n % 2 == 0);

	T.resize(2);
	forn(c, 2) {
		T[c] = SegmTree(n / 2);
	}
	forn(i, n) {
		T[i & 1].put(i / 2, p[i]);
	}

	vi q;
	set<Seg> segs;
	segs.insert(Seg(0, n - 1));
	forn(iter, n / 2) {
		assert(!segs.empty());
		auto mn = *segs.begin();
		segs.erase(segs.begin());

		auto vals = mn.calc();
		q.pb(vals.fst);
		q.pb(vals.snd);

		if  (mn.l <= mn.poses.fst - 1) {
			segs.insert(Seg(mn.l, mn.poses.fst - 1));
		}
		if  (mn.poses.fst + 1 <= mn.poses.snd - 1) {
			segs.insert(Seg(mn.poses.fst + 1, mn.poses.snd - 1));
		}
		if  (mn.poses.snd + 1 <= mn.r) {
			segs.insert(Seg(mn.poses.snd + 1, mn.r));
		}
	}

	forn(i, n) {
		printf("%d ", q[i] + 1);
	}
	puts("");
}

