    if(r <= a || b <= l) return Pi(inf, inf);
    if(a <= l && r <= b) return data[k];
    Pi vl = query(a, b, 2*k+1, l, (l+r)/2);
    Pi vr = query(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }
  Pi query(int a, int b) {
    return query(a, b, 0, 0, sz);
  }
};

