    Pi p = (ok ? eseg.query(l, r) : oseg.query(l, r));
    Pi q = (ok ? oseg.query(p.second, r) : eseg.query(p.second, r));
    que.emplace(d, p.first, q.first);
    dfs(l, p.second, d+1, ok);
    dfs(p.second+1, q.second, d+1, !ok);
    dfs(q.second+1, r, d+1, ok);
  };
  dfs(0, n, 0, true);
  vint ans;
  while(!que.empty()) {
    Tapris p = que.top(); que.pop();
    int a, b, c;
    tie(a, b, c) = p;
    ans.push_back(b);
    ans.push_back(c);
  }
  rep(i, ans.size()) cout << ans[i] << " \n"[i==(int)ans.size()-1];

  return 0;
}

