struct sMyRange
{
	size_t lBound, rBound, lPos, rPos;
};

size_t GetMinPos(
	const vector<vector<size_t>>& F,
	size_t lQ, 
	size_t rQ,
	size_t iInterval,
	size_t nLevel,
	const vector<size_t>& p,
	bool even)
{
	size_t levelSize = static_cast<size_t>(int(1) << nLevel);
	size_t lI = iInterval * levelSize;
	size_t rI = (iInterval + 1) * levelSize - 1;

	if (lQ <= lI && rQ >= rI)
		return F[nLevel][iInterval];

	size_t minValue = p.size() + 1;
	size_t ans = p.size();
	if (lQ < lI + levelSize / 2)
	{
		ans = GetMinPos(F, lQ, rQ, iInterval * 2, nLevel - 1, p, even);
		minValue = p[2 * ans + (even ? 0 : 1)];
	}
	if (rQ >= lI + levelSize / 2)
	{
		size_t pos = GetMinPos(F, lQ, rQ, iInterval * 2 + 1, nLevel - 1, p, even);
		if (p[2 * pos + (even ? 0 : 1)] < minValue)
			ans = pos;
	}

	return ans;
}

sMyRange CreateRange(
	const vector<vector<size_t>>& Feven,
	const vector<vector<size_t>>& Fodd,
	const vector<size_t>& p,
	size_t l,
	size_t r)
{
	sMyRange res;
	res.lBound = l;
	res.rBound = r;

	size_t minEven = (l+1) / 2;
	size_t minOdd = l / 2;
	size_t maxEven = r / 2;
	size_t maxOdd = (r - 1) / 2;


	if (!(l % 2))
	{
		res.lPos = GetMinPos( Feven, minEven, maxEven, 0, Feven.size() - 1, p, true );		
		res.rPos = GetMinPos(Fodd, res.lPos, maxOdd, 0, Fodd.size() - 1, p, false);
		res.lPos *= 2;
		res.rPos *= 2;
		++res.rPos;
	}
	else
	{
		res.lPos = GetMinPos(Fodd, minOdd, maxOdd, 0, Fodd.size() - 1, p, false);
		res.rPos = GetMinPos(Feven, res.lPos+1, maxEven, 0, Feven.size() - 1, p, true);
		res.lPos *= 2;
		++res.lPos;
		res.rPos *= 2;		
	}

	return res;
}

