{
	size_t N;
	cin >> N;
	vector<size_t> p(N);
	for (size_t i = 0; i < N; ++i)
		cin >> p[i];

	size_t nLevels = 1;
	size_t cnt = 1;
	while (cnt*2 < N)
	{
		++nLevels;
		cnt *= 2;
	}

	size_t inf = N + 1;

	while (p.size() < 2*cnt)
		p.push_back(inf);

	size_t curCnt = cnt;
	vector< vector<size_t> > Feven(nLevels), Fodd(nLevels);
	for (size_t i = 0; i < nLevels; ++i)
	{
		Feven[i].assign(curCnt, inf);
		Fodd[i].assign(curCnt, inf);
		curCnt /= 2;
	}

	for (size_t i = 0; i < cnt; ++i)
	{
		Feven[0][i] = i;
		Fodd[0][i] = i;
	}

	curCnt = cnt / 2;
	for (size_t i = 1; i < nLevels; ++i)
	{
		for (size_t j = 0; j < curCnt; ++j)
		{
			size_t e1 = Feven[i - 1][2 * j];
			size_t e2 = Feven[i - 1][2 * j+1];
			Feven[i][j] = (p[2*e1] < p[2*e2]) ? Feven[i - 1][2 * j] : Feven[i - 1][2 * j+1];
			size_t o1 = Fodd[i - 1][2 * j];
			size_t o2 = Fodd[i - 1][2 * j+1];
			Fodd[i][j] = (p[2*o1+1] < p[2*o2+1]) ? Fodd[i - 1][2 * j] : Fodd[i - 1][2 * j + 1];
		}

		curCnt /= 2;
	}

	vector<sMyRange> v;
	v.resize(N);
	size_t heapSize = 1;
	v[0] = CreateRange(Feven, Fodd, p, 0, N - 1);

	auto rangeCmp = [&p](const sMyRange& r1, const sMyRange& r2) -> bool { return p[r1.lPos] > p[r2.lPos]; };
	for (size_t i = 0; 2 * i < N; ++i)
	{
		sMyRange r = v[0];

		cout << p[r.lPos] << " " << p[r.rPos] << " ";

		pop_heap(v.begin(), v.begin() + heapSize, rangeCmp);
		--heapSize;

		if (r.lPos > r.lBound)
		{
			v[heapSize] = CreateRange(Feven, Fodd, p, r.lBound, r.lPos - 1);
			++heapSize;
			push_heap(v.begin(), v.begin() + heapSize, rangeCmp);
		}

		if (r.lPos + 1 < r.rPos)
		{
			v[heapSize] = CreateRange(Feven, Fodd, p, r.lPos + 1, r.rPos-1);
			++heapSize;
			push_heap(v.begin(), v.begin() + heapSize, rangeCmp);
		}

		if (r.rPos < r.rBound)
		{
			v[heapSize] = CreateRange(Feven, Fodd, p, r.rPos + 1, r.rBound);
			++heapSize;
			push_heap(v.begin(), v.begin() + heapSize, rangeCmp);
		}
	}
}

