    }
    int dfs(int l,int r){
        if(l>=r) return -1;
        assert((l+r)%2 == 0);
        int ev = P[l], od = P[l+1], ie = l, io = l+1;
        for(int i=0;i+l<r;++i){
            if(i%2==0 && P[l+i]<ev){
                ev = P[l+i];
                ie = l+i;
                od = P[l+i+1];
                io = l+i+1;
            }
            if(i%2 && P[l+i]<od){
                od = P[l+i];
                io = l+i;
            }
        }
        pr[ev] = od;
        vi x = {dfs(l, ie), dfs(ie+1, io), dfs(io+1,r)};
        for(int k:x) if(k>=0) E[ev].push_back(k);
        return ev;
    }


