void build(int v, int tl, int tr, int o) {
    if(tl == tr) {
        if(o == 0)
            t[v][o] = mk(a[tl*2-1], tl);
        else
            t[v][o] = mk(a[tl*2], tl);
        return;
    }
    int tm = (tl + tr) / 2;
    build(v + v, tl, tm, o);
    build(v + v + 1, tm + 1, tr, o);
    t[v][o] = t[v + v][o];
    if(t[v][o].fr > t[v + v + 1][o].fr)
        t[v][o] = t[v + v + 1][o];
}

pair <int, int> get(int v, int tl, int tr, int l, int r, int o) {
    if(l > r) return mk(inf, 0);

    if(tl == l && r == tr)
        return t[v][o];

    int tm = (tl + tr) / 2;

    pair <int, int> nw = get(v + v, tl, tm, l, min(tm, r), o);
    pair <int, int> nw2 = get(v + v + 1, tm + 1, tr, max(tm + 1, l), r, o);

    if(nw.fr < nw2.fr) return nw;
    return nw2;
}

int co(int n) {
    return n * 2 - 1;
}

int ce(int n) {
