struct RMQ {
	int rec[18][N],lg[N];

	void pre() {
		rep(i,2,N-1) lg[i]=lg[i>>1]+1;
		rep(j,1,lg[n]) {
			rep(i,1,n-(1<<j)+1) {
				if (w[rec[j-1][i]]>w[rec[j-1][i+(1<<j-1)]]) {
					rec[j][i]=rec[j-1][i+(1<<j-1)];
				} else rec[j][i]=rec[j-1][i];
			}
		}
	}

	int ask(int l,int r) {
		int t=lg[r-l+1];
		if (w[rec[t][l]]<w[rec[t][r-(1<<t)+1]]) return rec[t][l];
		else return rec[t][r-(1<<t)+1];
	}
} T[2];

