const int N = 1e5 + 7;
const int INF = 1e9 + 7;
const int MAX = 1 << 18;

PII tree[2 * MAX + 7];
int lazy[2 * MAX + 7];

inline void propagate(int node, int l, int r)
{
    if(lazy[node])
    {
        swap(tree[node].first, tree[node].second);
        if(l != r)
        {
            lazy[2 * node] ^= 1;
            lazy[2 * node + 1] ^= 1;
        }
        lazy[node] = 0;
    }
}

void update(int a, int b, int node = 1, int l = 0, int r = MAX - 1)
{
    propagate(node, l, r);
    if(b < l || r < a) return;
    if(a <= l && r <= b)
    {
        lazy[node] ^= 1;
        propagate(node, l, r);
        return;
    }
    update(a, b, 2 * node, l, (l + r) / 2);
    update(a, b, 2 * node + 1, (l + r) / 2 + 1, r);
    tree[node].first = min(tree[2 * node].first, tree[2 * node + 1].first);
    tree[node].second = min(tree[2 * node].second, tree[2 * node + 1].second);
}

void erase(int e, int node = 1, int l = 0, int r = MAX - 1)
{
    propagate(node, l, r);
    if(e < l || r < e) return;
    if(l == r)
    {
        tree[node].first = tree[node].second = INF;
        return;
    }
    int m = (l + r) / 2;
    erase(e, 2 * node, l, m);
    erase(e, 2 * node + 1, m + 1, r);
    tree[node].first = min(tree[2 * node].first, tree[2 * node + 1].first);
    tree[node].second = min(tree[2 * node].second, tree[2 * node + 1].second);
}

PII query(int a, int b, int node = 1, int l = 0, int r = MAX - 1)
{
    propagate(node, l, r);
    if(b < l || r < a) return {INF, INF};
    if(a <= l && r <= b) return tree[node];
    PII x = query(a, b, 2 * node, l, (l + r) / 2);
    PII y = query(a, b, 2 * node + 1, (l + r) / 2 + 1, r);
    return {min(x.first, y.first), min(x.second, y.second)};
}

