int get_cutpoint(int l,int r){
	if(l+1==r) return l+1;
	if(A[l + 1] < RMQ(l+3,r,sparse[1 - l%2])) return l+1;
	int s = 1,e = (r - l + 1)/2 - 1;
	while(s < e) {
		int m = s + (e - s + 1)/2;
		int pos = l + m*2 + 1;
		if(A[l + 1] < RMQ(pos,r,sparse[1 - l%2])) e = m-1;
		else s = m;
	}
	return l + s*2 + 1;
}

int get_pivot(int l,int r){
	int s = 0,e = (r - l + 1)/2 - 1;
	while(s < e){
		int m = s + (e - s + 1)/2;
		if(RMQ(l,r,sparse[l%2]) == RMQ(l + 2*m,r,sparse[l%2])) s = m;
		else e = m-1;
	}
	return l + 2*s;
}

void solve(int s,int e,int d = 0){
	int l = e - s + 1;
	assert(l%2 == 0);
	if(!l) return;
	if(l == 2) {
		lev[d].pb(mp(A[s],A[e]));
		return;
	}
	int pivot = get_pivot (s,e);
	int cutpoint = get_cutpoint(pivot,e);
//	cerr << s << " " << e << " -> " << pivot << " " << cutpoint << endl;
	solve(s,pivot - 1,d + 1);
	solve(pivot + 1,cutpoint - 1,d+1);
	solve(cutpoint + 1,e,d+1);
	lev[d].pb(mp(A[pivot], A[cutpoint]));
}

