const int INF = INT_MAX;

template <typename T>
struct SegmentTree {
    int n;
    vector<T> data;

    //使うときは、この3つを適宜変更する
    static T INITIAL_VALUE;
    static T merge(T x, T y); 
    void updateNode(int k, T x);

    SegmentTree(int size) {
        n = 1;
        while (n < size) n *= 2;
        data.resize(2 * n - 1, INITIAL_VALUE);
    }

    T getLeaf(int k) {
        return data[k + n - 1];
    }

    void update(int k, T x) {
        k += n - 1; //葉の節点
        updateNode(k, x);
        while (k > 0) {
            k = (k - 1) / 2;
            data[k] = merge(data[k * 2 + 1], data[k * 2 + 2]);
        }
    }

    //区間[a, b)に対するクエリに答える
    //k:節点番号, [l, r):節点に対応する区間
    T query(int a, int b, int k, int l, int r) {
        //[a, b)と[l, r)が交差しない場合
        if (r <= a || b <= l) return INITIAL_VALUE;
        //[a, b)が[l, r)を含む場合、節点の値
        if (a <= l && r <= b) return data[k];
        else {
            //二つの子をマージ
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return merge(vl, vr);
        }
    }

    //外から呼ぶ用
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};

//使うときは以下3つを変更
template <typename T>
T SegmentTree<T>::INITIAL_VALUE = T(INF, INF);

template <typename T>
T SegmentTree<T>::merge(T x, T y) {
    return min(x, y);
}

template <typename T>
void SegmentTree<T>::updateNode(int k, T x) {
    data[k] = x;
}

struct State {
	int x;
	int y;
	int idx1;
	int idx2;
	int L;
	int R;
	State(int x, int y, int idx1, int idx2, int L, int R) : x(x), y(y), idx1(idx1), idx2(idx2), L(L), R(R) {}
	bool operator>(const State& s) const {
		if (x != s.x) return x > s.x;
		return y > s.y;
	}
};

vector<SegmentTree<P>> st;

State solve(int L, int R, vector<int>& a) {
	int x, idx1;
	tie(x, idx1) = st[L % 2].query(L, R);
	int y, idx2;
	tie(y, idx2) = st[1 - L % 2].query(idx1 + 1, R);
	State res(x, y, idx1, idx2, L, R);
	return res;
}

