Segment_Tree<pii> seg2(MAX_N, pii(inf, inf)), seg1(MAX_N, pii(inf, inf));

//[l,r)での辞書順最小のペアのインデックスを返す
pii min_pair(pii sec){
    int l = sec.first, r = sec.second;
    int L, R;
    pii a, b;
    if(l%2 == 0){
        a = seg2.query(l/2, r/2);
        L = a.second;
        b = seg1.query(L/2, r/2);
        R = b.second;
    }
    else{
        a = seg1.query(l/2, r/2);
        L = a.second;
        b = seg2.query((L+1)/2, (r+1)/2);
        R = b.second;
    }
    return pii(L, R);
}

