void updata(int n)
{
    tree1[n]=min(tree1[n*2],tree1[n*2+1]);
    tree2[n]=min(tree2[n*2],tree2[n*2+1]);
    return ;
}
void build(int l,int r,int n)
{
    if(l==r)
    {
        tree1[n]=tree2[n]=0x3f3f3f3f;
        if(l%2==0)
            tree2[n]=num[l];
        else tree1[n]=num[l];
        return ;
    }
    int m=(l+r)/2;
    build(l,m,n*2);
    build(m+1,r,n*2+1);
    updata(n);
    return ;
}
int query(int a,int b,int l,int r,int n,int k)
{
    if(l>=a&&r<=b)
    {
        if(k%2==1)
            return tree1[n];
        else return tree2[n];
    }
    int m=(l+r)>>1;
    int ans=0x3f3f3f3f;
    if(a<=m)ans=min(query(a,b,l,m,n*2,k),ans);
    if(b>m)ans=min(ans,query(a,b,m+1,r,n*2+1,k));
    return ans;
}
