struct SegMinPint{
private:
	int n;
	vector<pint> node;
public:
	//vpintをセグ木にsetする
	SegMinPint(vpint v){
		int sz=v.size();
		n=1;while(n<sz) n*=2;
		node.resize(2*n-1,mp(INF,INF));
		for(int i=0;i<sz;i++) node[i+n-1]=v[i];
		for(int i=n-2;i>=0;i--) node[i]=min(node[2*i+1],node[2*i+2]);
	}
	//x番目の要素をvalに変える
	void update(int x, pint val){
		x+=(n-1);
		node[x]=val;
		while(x>0){
			x=(x-1)/2;
			node[x]=min(node[2*x+1],node[2*x+2]);
		}
	}
	//区間[a,b)の最小値を得る
	pint getmin(int a,int b,int k=0,int l=0,int r=-1){
		if(r<0) r=n;
		if(r<=a || b<=l) return mp(INF,INF);
		if(a<=l && r<=b) return node[k];
		pint vl=getmin(a,b,2*k+1,l,(l+r)/2);
		pint vr=getmin(a,b,2*k+2,(l+r)/2,r);
		return min(vl,vr);
	}
};
