int main(){
	int N;
	cin>>N;
	vint P;
	for(int i=0;i<N;i++){
		int p;
		cin>>p;
		P.pb(p);
	}
	//偶数と奇数番目のセグ木を用意する
	vpint O,E;
	for(int i=0;i<N;i++){
		if(i%2){
			O.eb(P[i],i);
			E.eb(INF,i);
		}
		else{
			O.eb(INF,i);
			E.eb(P[i],i);
		}
	}
	SegMinPint OS(O),ES(E);
	SegMinPint S[2]={ES,OS};
	//pq(最小値、範囲)
	priority_queue<pair<int,pint>,vector<pair<int,pint>>,greater<pair<int,pint>>> Q;
	//偶数のなかから一番小さいものを入れとく
	Q.push(mp(S[0].getmin(0,N).first,mp(0,N)));
	//こたえ
	vint ans;
	//ループ
	while(Q.size()){
		//範囲[l,r)
		int l=Q.top().second.first,r=Q.top().second.second;
		//1つ目を入れる
		ans.pb(S[l%2].getmin(l,r).first);
		//偶数から一番小さいものの座標を見る
		int idxA=S[l%2].getmin(l,r).second;
		//[idxA,r)で一番小さい奇数からとる
		int idxB=S[(l+1)%2].getmin(idxA+1,r).second;
		//入れる
		ans.pb(S[(l+1)%2].getmin(idxA+1,r).first);
		Q.pop();

		//3つの区間に分ける[l,idxA),[idxA+1,idxB),[idxB+1,r)
		if(l<idxA-1)
			Q.push(mp(S[l%2].getmin(l,idxA).first,mp(l,idxA)));
		if(idxA+1<idxB)
			Q.push(mp(S[(idxA+1)%2].getmin(idxA+1,idxB).first,mp(idxA+1,idxB)));
		if(idxB+1<r)
			Q.push(mp(S[(idxB+1)%2].getmin(idxB+1,r).first,mp(idxB+1,r)));

	}
	for(int i=0;i<N;i++)
		cout<<ans[i]<<(i==N-1?'\n':' ');
	return 0;
}

