	ll v=find_min(0,n,1,l,r,l&1).S;
	ll u=find_min(0,n,1,v+1,r,!(l&1)).S;
	ll o=ml[mp(a[v],a[u])];
	yal(o,solvv(l,v));
	yal(o,solvv(v+1,u));
	yal(o,solvv(u+1,r));
	return o;
}
