using Pi = pair<int, int>;
using Tapris = tuple<int, int, int>;
using vint = vector<int>;

const int64_t inf = 1LL << 55;
const int mod = 1e9 + 7;

struct SegmentTree {
  vector<Pi> data;
  int n, sz;
  SegmentTree(const vint& a) {
    n = a.size();
    sz = 1; while(sz < n) sz <<= 1;
    data.resize(2*sz-1, Pi(inf, inf));
    rep(i, n) data[i+sz-1] = Pi(a[i], i);
    for(int i = sz-2; i >= 0; --i) data[i] = min(data[2*i+1], data[2*i+2]);
  }
  Pi query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return Pi(inf, inf);
    if(a <= l && r <= b) return data[k];
    Pi vl = query(a, b, 2*k+1, l, (l+r)/2);
    Pi vr = query(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }
  Pi query(int a, int b) {
    return query(a, b, 0, 0, sz);
  }
};

signed main() {
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  int n;
  cin >> n;
  vint even, odd;
  rep(i, n) {
    int a;
    cin >> a;
    int b = inf;
    if(i&1) swap(a, b);
    even.push_back(a);
    odd.push_back(b);
  }

  SegmentTree eseg(even), oseg(odd);
  priority_queue<Tapris, vector<Tapris>, greater<Tapris> > que;
  function<void(int, int, int, bool)> dfs = [&](int l, int r, int d, bool ok) {
    if(l+1 >= r) return;
    //cout<<d<<" "<<l<<" "<<r<<endl;
    Pi p = (ok ? eseg : oseg).query(l, r);
    Pi q = (ok ? oseg : eseg).query(p.second+1, r);
    que.emplace(d, p.first, q.first);
    dfs(l, p.second, d+1, ok);
    dfs(p.second+1, q.second, d+1, !ok);
    dfs(q.second+1, r, d+1, ok);
  };
  dfs(0, n, 0, true);
  vint ans;
  while(!que.empty()) {
    Tapris p = que.top(); que.pop();
    int a, b, c;
    tie(a, b, c) = p;
    ans.push_back(b);
    ans.push_back(c);
  }
  rep(i, ans.size()) cout << ans[i] << " \n"[i==(int)ans.size()-1];

  return 0;
}

