		{
			pi.first=pi.second=0;
			next=NULL;
		}
};

int cmp(pair<int,int> q,pair<int,int> w)
{
	return q<w;
}

node* root;

int lowbit(int k)
{
	return k&(-k);
}

void update(int k)
{
	for (int i=k;i<=n;i+=lowbit(i)) c[i]++;
}

int sum(int k)
{
	int ret=0;
	for (int i=k;i>0;i-=lowbit(i)) ret+=c[i];
	return ret;
}

