				if ((now->next->pi.second-sum(now->next->pi.second))%2==1) break;
			}
			else if (now->next->pi.second>p1)
			{
				if ((now->next->pi.second-sum(now->next->pi.second))%2==1) break;
			}
			else 
			{
				if ((now->next->pi.second-sum(now->next->pi.second))%2==0) break;
			}
			now=now->next;
		}
		last=now->next->pi.second;
		ans[++cnt]=now->next->pi.first;
		now->next=now->next->next;

		now=root;
		while (1)
		{
			if (now->next->pi.second<last) now=now->next;
			else if (!(last>p1 && last<p2) && (now->next->pi.second-sum(last))%2==1) now=now->next;
			else if (last>p1 && last<p2 &&(now->next->pi.second-sum(last))%2==1) now=now->next;
			else if (last<p1 && now->next->pi.second>p1) now=now->next;
			else if (last>p1 && last<p2 && !((now->next->pi.second>p1)&&(now->next->pi.second<p2))) now=now->next;
			else if (last>p2 && now->next->pi.second<=p2) now=now->next;
			else break;
		}
		update(now->next->pi.second);
		update(last);
		ans[++cnt]=now->next->pi.first;
		now->next=now->next->next;
	}

	for (int i=1;i<n;i++) cout<<ans[i]<<" ";
	cout<<ans[n]<<endl;
}

