struct SegTree {
	int N;
	P dat[900000];
	void init(int n_) {
		N = 1;
		while (N < n_)N *= 2;
		for (int i = 0; i < 2 * N - 1; i++)dat[i].first = INT_MAX;
	}
	void update(int k, P a) {
		k += N - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	P query(int a, int b, int k, int l, int r) {
		if (a >= b)return P(INT_MAX, 0);
		if (r <= a || b <= l)return P(INT_MAX, 0);
		if (a <= l&&r <= b)return dat[k];
		P v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
		P v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(v1, v2);
	}
};
