int evenTree[N << 2], oddTree[N << 2];
int pos[N];
vector<int> vec;

struct node{
    int l, r;
    int m;

    bool operator< (const node &rhs) const {
        return m > rhs.m;
    }
};
priority_queue<node> pq;

void build(int root, int *data, int start, int end, int *dataTree) {
    if (start == end) {
        dataTree[root] = data[start];
        return;
    }
    int mid = (start + end) >> 1;
    build(root << 1 | 1, data, start, mid, dataTree);
    build((root << 1) + 2, data, mid + 1, end, dataTree);
    dataTree[root] = min(dataTree[root << 1 | 1], dataTree[(root << 1) + 2]);
}

int query(int *dataTree, int root, int start, int end, int qstart, int qend) {
    if (start == qstart && end == qend)
        return dataTree[root];
    int mid = (start + end) >> 1;
    if (qend <= mid)
        return query(dataTree, root << 1 | 1, start, mid, qstart, qend);
    if (qstart > mid)
        return query(dataTree, (root << 1) + 2, mid + 1, end, qstart, qend);
    return min(query(dataTree, root << 1 | 1, start, mid, qstart, mid), query(dataTree, (root << 1) + 2, mid + 1, end, mid + 1, qend));
}

void qPush(int l, int r) {
    node nd;
    nd.l = l, nd.r = r;
    nd.m = l % 2 == 0 ? query(evenTree, 0, 0, (n >> 1) - 1, l >> 1, r >> 1) : query(oddTree, 0, 0, (n >> 1) - 1, l >> 1, (r >> 1) - 1);
    pq.push(nd);
}

