const int M = (1e9)+7;
const int N = (1e5)+5;  // check the limit, man
const int K = 20;
int perm[2*N];
struct rmqindex // for minimum value
{
    int sp[N][K],po[K],ar[K];
    int v[N];
    rmqindex()
    {
        int i,k;
        ar[1]=0,k=1,po[0]=1;
        while(k<N)
        {
            for(i=k+1;i<2*k;i++)
                ar[i]=ar[k];
            ar[2*k]=1+ar[k],k*=2;
        }
        for(i=1;i<K;i++)
            po[i]=2*po[i-1];
    }
    int operation(int a,int b)
    {
        return v[a]<v[b]?a:b;
    }
    void build(vi &val,int n)
    {
        int i,k;
        rrep(i,n)
        {
            v[i]=val[i],sp[i][0]=i;
            for(k=1;i+po[k]<=n;k++)
                sp[i][k]=operation(sp[i][k-1],sp[i+po[k-1]][k-1]);
        }
    }
    int query(int a,int b)
    {
        int y,x=b-a+1;
        y=ar[x],x-=po[y];
        return operation(sp[a][y],sp[a+x][y]);
    }
};
rmqindex rmq[2];
ii call(int l,int r)
{
    int f=(l&1);
    int p=rmq[f].query((l/2),(r-1)/2);
    int q=rmq[f^1].query(p+f,(r/2));
//    int p=query(f,(l/2),(r-1)/2);
  //  int q=query(f^1,p+f,(r/2));
    return {lchild(p)+f,rchild(q)-f};
}
int value(int l,int r)
{
    if(l>r)
        return M;
    ii temp=call(l,r);
    return perm[temp.F];
}
triple make(int l,int r)
{
    return mt(value(l,r),l,r);
}
void solve()
{
