int comb(int x, int y)
{
        if(!x || !y){
                return x + y;
        }
        if(a[x] < a[y]){
                return x;
        }
        return y;
}

int get(int l, int r)
{
        int g = L[(r - l + 1) / 2];
        return comb(t[l][g], t[r - (2 << g) + 1][g]);
}

pair < int, int > solve(int l, int r)
{
        int i = get(l, r);
        int j = get(i + 1, r + 1);
        return {i, j};
}

set < pair < int, pair < int, int > > > S;

void add(int l, int r)
{
        if(l > r){
                return;
        }
        S.insert({a[solve(l, r).fi], {l, r}});
}

