struct ST {
    vi st, v;

    ST (int n) : st(4*n), v(n+2, 1e9) {}

    void cons (int i, int j, int pos) {
        if (i == j) {
            st[pos] = i;
            return;
        }

        int m = (i+j) / 2;
        cons(i, m, pos*2);
        cons(m+1, j, pos*2+1);

        if (v[st[pos*2]] < v[st[pos*2+1]])
            st[pos] = st[pos*2];
        else
            st[pos] = st[pos*2+1]; 
    }

    int query (int i, int j, int a, int b, int pos) {
        if (i > b || j < a)
            return -1;

        if (i >= a && j <= b)
            return st[pos];

        int m = (i+j) / 2;
        int x = query(i, m, a, b, pos*2);
        int y = query(m+1, j, a, b, pos*2+1);

        if (y == -1 || (x != -1 && v[a] < v[b]))
            return x;
        else
            return y;
    }
};

