const int maxn = 200010;

struct Segment {
  int n, t[maxn * 2];
  void init(int n) {
    fill(t, t + maxn * 2, INT_MAX);
    this->n = n;
  }
  void set(int x, int v) {
      t[x + n] = v;
  }
  void build() {
    for (int i = n - 1; i; --i)
      t[i] = min(t[i<<1], t[i<<1|1]);
  }
  int query(int l, int r) {
    r++;
    int ret = INT_MAX;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l&1) ret = min(ret, t[l++]);
      if (r&1) ret = min(ret, t[--r]);
    }
    return ret;
  }
} s[2];
int n, a[maxn], rev[maxn];

PII query(int l, int r) {
  int a = s[l & 1].query(l, r);
  int p = rev[a];
  int b = s[~l & 1].query((p + 1), r);
  return {a, b};
}

int main() {
  scanf("%d", &n);
  s[0].init(n);
  s[1].init(n);
  REP(i, n) {
    scanf("%d", &a[i]);
    s[i & 1].set(i, a[i]);
    rev[a[i]] = i;
  }
  s[0].build();
  s[1].build();
  using T = tuple<PII, int, int>;
  priority_queue<T, vector<T>, greater<T>> q;
  q.push({query(0, n - 1), 0, n - 1});
  vector<int> ans;
  while (q.size()) {
    PII tp;
    int l, r;
    tie(tp, l, r) = q.top(); q.pop();
    ans.PB(tp.F);
    ans.PB(tp.S);
    int ll = rev[tp.F];
    int rr = rev[tp.S];
    if (ll > l) q.push({query(l, ll - 1), l, ll - 1});
    if (rr < r) q.push({query(rr + 1, r), rr + 1, r});
    if (ll + 1 <= rr - 1) q.push({query(ll + 1, rr - 1), ll + 1, rr - 1});
  }
  REP(i, n) printf("%d%c", ans[i], " \n"[i + 1 == n]);
  return 0;
}

