using namespace std;

int n, ar[200001];
pair<int, int> t[1000001][2];

int build(int tl, int tr, int v)
{
    if(tr == tl)
    {
        t[v][tl % 2].fr = ar[tl];
        t[v][(tl + 1) % 2].fr = 1e9;
        t[v][0].sc = tr;
        t[v][1].sc = tr;
    }else
    {
        int tm = (tr + tl) >> 1;
        build(tl, tm, v + v);
        build(tm + 1, tr, v + v + 1);

        t[v][1] = min(t[v + v][1], t[v + v + 1][1]);
        t[v][0] = min(t[v + v][0], t[v + v + 1][0]);
    }
}

pair<int, int> get(int tl, int tr, int l, int r, int v, int num)
{
    if(l > r)
        return mk(1e9, 0);
    if(tr == r && tl == l)
        return t[v][num];
    else
    {
        int tm = (tr + tl) >> 1;
        return min(get(tl, tm, l, min(tm, r), v + v, num), get(tm + 1, tr, max(l, tm + 1), r, v + v + 1, num));
    }
}

vector<pair<int, int> > f(int l, int r)
{
    vector<pair<int, int> > ans, z, x, y;
    if(l > r)
        return ans;

    int a, b;
    a = get(1, n, l, r, 1, l % 2).sc;
    b = get(1, n, a + 1, r, 1, (l + 1) % 2).sc;

    //cout << a << " " << b << endl;
    z = f(l, a - 1);
    x = f(a + 1, b - 1);
    y = f(b + 1, r);

    int aa[4];
    aa[1] = aa[2] = aa[3] = 0;
    ans.push_back(mk(ar[a], ar[b]));

    for(int i = 0; i < z.size() + x.size() + y.size(); i++)
    {
        pair<int, int> k = mk(1e9, 1e9);
        int ind;
        if(aa[1] < z.size() && k > z[aa[1]])
        {
            k = z[aa[1]], ind = 1;
        }
        if(aa[2] < x.size() && k > x[aa[2]])
            k = x[aa[2]], ind = 2;
        if( aa[3] < y.size() && k > y[aa[3]])
            k = y[aa[3]], ind = 3;

        ans.push_back(k);
        aa[ind]++;
    }

    return ans;
}

int main()
{
    cin >> n;
    for(int i = 1; i <= n; i++)
        cin >> ar[i];

    build(1, n, 1);

    vector<pair<int, int> > ans;
    ans = f(1, n);
    for(int i = 0; i < ans.size(); i++)
        cout << ans[i].fr << " " << ans[i].sc << " ";
    return 0;
}

