using namespace std;

const int MAXN=2e5+25;

int N;
int p[MAXN],pinv[MAXN];
int seg[2][2*MAXN];

int query(int *seg, int a, int b) {
        int ret=MAXN;
        for (a += N, b += N; a<b; a>>=1,b>>=1) {
                if (a%2) ret=min(ret,seg[a++]);
                if (b%2) ret=min(ret,seg[--b]);
        }
        return ret;
}

vector<int> *solve(int a, int b) {
        //cout << "Solving " << a << " " << b << ":" << endl;
        if (b-a < 2) return new vector<int>;
        int break1=pinv[query(seg[a%2],a,b)];
        int break2=pinv[query(seg[1-a%2],break1,b)];
        //cout << "Queries return " << query(seg[a%2],a,b) << " " << query(seg[1-a%2],break1,b) << endl;
        //cout << "Breaking at " << break1 << " " << break2 << endl;

        vector<int> *v1 = solve(a,break1);
        vector<int> *v2 = solve(break1+1,break2);
        vector<int> *v3 = solve(break2+1,b);

        vector<int> *ret = new vector<int>;
        ret->push_back(p[break1]);
        ret->push_back(p[break2]);
        int i1=0,i2=0,i3=0;
        for (int i=2; i<b-a; i++) {
                int mnf = MAXN;
                if (i1 < v1->size()) mnf = min(mnf,(*v1)[i1]);
                if (i2 < v2->size()) mnf = min(mnf,(*v2)[i2]);
                if (i3 < v3->size()) mnf = min(mnf,(*v3)[i3]);
                if (i1 < v1->size() && mnf == (*v1)[i1]) {
                        ret->push_back((*v1)[i1]);
                        ret->push_back((*v1)[i1+1]);
                        i1 += 2;
                }
                if (i2 < v2->size() && mnf == (*v2)[i2]) {
                        ret->push_back((*v2)[i2]);
                        ret->push_back((*v2)[i2+1]);
                        i2 += 2;
                }
                if (i3 < v3->size() && mnf == (*v3)[i3]) {
                        ret->push_back((*v3)[i3]);
                        ret->push_back((*v3)[i3+1]);
                        i3 += 2;
                }
        }

        delete v1;
        delete v2;
        delete v3;

        return ret;
}

int main() {
        cin >> N;
        for (int i=0; i<N; i++)
                cin >> p[i];

        for (int i=0; i<N; i++)
                pinv[p[i]] = i;

        for (int i=0; i<2*N+1; i++) {
                seg[0][i] = MAXN;
                seg[1][i] = MAXN;
        }

        for (int i=0; i<N; i++) {
                seg[i%2][i+N] = p[i];
        }

        for (int i=N-1; i>0; i--) {
                seg[0][i] = min(seg[0][2*i],seg[0][2*i+1]);
                seg[1][i] = min(seg[1][2*i],seg[1][2*i+1]);
        }

        for (int i=1; i<=2*N; i++)
                cout << seg[0][i] << " ";
        cout << "\n";

        for (int i=1; i<=2*N; i++)
                cout << seg[1][i] << " ";
