template<class T, int N, class cmp = less<T>> class SparseTable
{
    int lookup[22][N+2], log_2[N+2];
public:
    T ara[N+2];

    SparseTable() {
        log_2[1] = 0;
        for (int i = 2; i<N; i++) log_2[i] = log_2[i>>1]+1;
    }

    void preprocess(int _n) {   // first assign to its member ara.
        for (int i = 0; i < _n; i++) lookup[0][i] = i;
        for (int j = 1; (1<<j)<=_n; j++) {
            for (int i = 0; (i+(1<<j)-1) < _n; i++) {
                lookup[j][i] = cmp()(ara[lookup[j-1][i]], ara[lookup[j-1][i+(1<<(j-1))]]) ? lookup[j-1][i] : lookup[j-1][i+(1<<(j-1))];
            }
        }
    }

    int query(int L, int R) {   // Returns minimum of ara[L..R] based on cmp().
        int j = log_2[R-L+1];
        return cmp()(ara[lookup[j][L]], ara[lookup[j][R-(1<<j)+1]]) ? lookup[j][L] : lookup[j][R-(1<<j)+1];
        // return cmp()(ara[lookup[j][L]], ara[lookup[j][R-(1<<j)+1]]) ? ara[lookup[j][L]] : ara[lookup[j][R-(1<<j)+1]];
    }
};

