template<class T>
class sg_tree : public vector<T>{
private:
    lli n;
    T default_value;
    T _query(lli a,lli b,lli k,lli l,lli r){
        if(r <= a || b <= l) return default_value;
        if(a <= l && r <= b) return (*this)[k];
        else {
            T vl = _query(a,b,k*2+1,l,(l+r)/2);
            T vr = _query(a,b,k*2+2,(l+r)/2,r);
            return func(vl,vr);
        }
    }
public:
    sg_tree():vector<T>(){

    }
    sg_tree(lli n,T d = INT_MAX):vector<T>(n*4,d){
		this->n = 1;
        while(n > this->n) this->n <<= 1;
        this->default_value = d;
    }
    void update(lli i,lli x){
        i += n - 1;
        (*this)[i] = x;
        while(i > 0){
            i = (i - 1) / 2;
            (*this)[i] = func((*this)[i * 2 + 1],(*this)[i * 2 + 2]);
        }

    }
    T query(lli a,lli b){
        return _query(a,b,0,0,n);
    }
    T func(T a,T b){
        return min(a,b);
    }
};

sg_tree<lli> sg_even;
sg_tree<lli> sg_odd;
mat res;
vll maping;

mat merge(vll s,mat a,mat b,mat c){
	mat res;
	res = mat();
	res.push_back(s);
	lli n = a.size() + b.size() + c.size();
	a.push_back(vll({INT_MAX,0}));
	b.push_back(vll({INT_MAX,0}));
	c.push_back(vll({INT_MAX,0}));
	for(lli i = 0,j = 0,k = 0,l = 0;i < n;i++){
		vll p = min({a[j],b[k],c[l]});
		if(p == a[j]) j++;
		if(p == b[k]) k++;
		if(p == c[l]) l++;
		res.push_back(p);
	}
	return res;

}

mat dfs(lli from,lli to){
	if(from == to) return mat();
	lli r,l;
	lli r_index,l_index;
	if(from % 2 == 0){
		l = sg_even.query(from,to);
		l_index = maping[l];
		r = sg_odd.query(l_index,to);
		r_index = maping[r];
	}else{
		l = sg_odd.query(from,to);
		l_index = maping[l];
		r = sg_even.query(l_index,to);
		r_index = maping[r];
	}
	return merge(
		vll({l,r}),
		dfs(from,l_index),
		dfs(l_index+1,r_index),
		dfs(r_index+1,to)
		);
}

