std::vector<SegmentTree<PAIR>> st;

Node node[100005];
int pos = 0;

Node* calc(int l, int r) {
	if (l >= r) return nullptr;

	Node* res = &node[pos++];
	PAIR x = st[0 + l & 1].query(l, r);
	PAIR y = st[1 - l & 1].query(x.second + 1, r);

	res->val = PAIR(x.first, y.first);
	{
		auto ptr = calc(l, x.second);
		if (ptr != nullptr) res->nex.emplace_back(ptr);
	}
	{
		auto ptr = calc(x.second + 1, y.second);
		if (ptr != nullptr) res->nex.emplace_back(ptr);
	}
	{
		auto ptr = calc(y.second + 1, r);
		if (ptr != nullptr) res->nex.emplace_back(ptr);
	}
	return res;
}

