using namespace std;
int cnt[524288],mn[524288][2],mnidx[524288][2];
void up_propgate(int idx)
{
	for (int i=0;i<2;++i)
		if (mn[idx<<1][i]<mn[(idx<<1)^1][i^(cnt[idx<<1]&1)])
		{
			mn[idx][i]=mn[idx<<1][i];
			mnidx[idx][i]=mnidx[idx<<1][i];
		}
		else
		{
			mn[idx][i]=mn[(idx<<1)^1][i^(cnt[idx<<1]&1)];
			mnidx[idx][i]=mnidx[(idx<<1)^1][i^(cnt[idx<<1]&1)];
		}
	cnt[idx]=cnt[idx<<1]+cnt[(idx<<1)^1];
}
void remove(int idx)
{
	idx+=262144;
	mn[idx][0]=1000000000;
	cnt[idx]=0;
	idx>>=1;
	while (idx)
	{
		up_propgate(idx);
		idx>>=1;
	}
}
pair<pair<int,int>,int> query(int id,int il,int ir,int l,int r,int mod)
{
	if (il>=l&&ir<=r)
		return make_pair(make_pair(mn[id][mod],mnidx[id][mod]),cnt[id]);
	if ((l>=il&&l<ir)||(r>il&&r<=ir))
	{
		pair<pair<int,int>,int> tmp=query(id<<1,il,(il+ir)>>1,l,r,mod);
		pair<pair<int,int>,int> tmp2=query((id<<1)^1,(il+ir)>>1,ir,l,r,mod^(tmp.second&1));
		return make_pair(tmp.first.first<tmp2.first.first?tmp.first:tmp2.first,tmp.second+tmp2.second);
	}
	return make_pair(make_pair(1000000000,-1),0);
}
int getcount(int l,int r)
{
	int ret=0;
	for (l+=262144,r+=262144;l<r;l>>=1,r>>=1)
	{
		if (l&1)
			ret+=cnt[l++];
		if (r&1)
			ret+=cnt[--r];
	}
	return ret;
}
int main()
{
	int n;
	scanf("%d",&n);
	set<int> inter;
	inter.insert(-1);
	inter.insert(n);
	for (int i=0;i<n;++i)
	{
		int tmp;
		scanf("%d",&tmp);
		cnt[262144+i]=1;
		mn[262144+i][0]=tmp;
		mn[262144+i][1]=1000000000;
		mnidx[262144+i][0]=mnidx[262144+i][1]=i;
	}
	for (int i=262144+n;i<524288;++i)
		for (int j=0;j<2;++j)
		{
			mn[i][j]=1000000000;
			mnidx[i][j]=i-262144;
		}
	for (int i=262144-1;i>=1;--i)
		up_propgate(i);
	int pos=0;
	for (int i=1;i<=n/2;++i)
	{
		int idx;
		if (mn[1][0]<mn[1][1])
		{
			pos=mn[1][0];
			idx=mnidx[1][0];
		}
		else
		{
			pos=mn[1][1];
			idx=mnidx[1][1];
		}
		int leftbound=*(--inter.lower_bound(idx)),rightbound=*inter.upper_bound(idx);
		++leftbound;
		pair<int,int> partner;
		if (getcount(leftbound,idx)&1)
		{
			partner=query(1,0,262144,leftbound,idx,0).first;
			printf("%d %d ",partner.first,pos);
		}
		else
		{
			partner=query(1,0,262144,idx+1,rightbound,0).first;
			printf("%d %d ",pos,partner.first);
		}
		remove(idx);
		remove(partner.second);
		inter.insert(idx);
		inter.insert(partner.second);
	}
	return 0;
}

