const int N = 2e5+5, inf = 1e9+7;
int n, v[N], ans[N], len = 0;
struct node{ 
	int l, r, x, y; 
	node(int a=0,int b=0,int c=0,int d=0) { l = a, r = b, x = c, y = d; }
	bool operator < (const node&rhs) const { return v[x] > v[rhs.x]; } 
} c; priority_queue<node> q;
struct tag{ 
	int m1, m2; 
	tag(int a=0,int b=0) { m1 = a, m2 = b; }
} A[N<<2], a, b;

inline tag operator + (const tag&a,const tag&b) { 
	tag c;
	c.m1 = v[a.m1] < v[b.m1] ? a.m1 : b.m1;
	c.m2 = v[a.m2] < v[b.m2] ? a.m2 : b.m2;
	return c;
}
#define lc k<<1
#define rc k<<1|1
int ql, qr;
inline void build(int l,int r,int k) { 
	if( l == r ) { 
		if( l & 1 ) A[k] = tag(l,0); else A[k] = tag(0,l);
		return; 
	} 
	int mid = (l + r) >> 1;
	build(l,mid,lc), build(mid+1,r,rc), A[k] = A[lc] + A[rc];
}

inline tag query(int l,int r,int k) { 
	if( ql <= l && r <= qr ) return A[k];
	int mid = (l + r) >> 1;
	if( qr <= mid ) return query(l,mid,lc);
	else if( ql > mid ) return query(mid+1,r,rc);
	else return query(l,mid,lc) + query(mid+1,r,rc);
}
inline void add(int l,int r) {
	if( l > r ) return; 
	ql = l, qr = r, a = query(1,n,1);
	if( l & 1 ) { 
		ql = a.m1, qr = r, b = query(1,n,1), qr = b.m2; 
	} else { 
		ql = a.m2, qr = r, b = query(1,n,1), qr = b.m1;
	}
	q.push(node(l,r,ql,qr));
}

int main() {
	n = read(), v[0] = inf;
	rep(i,1,n) v[i] = read();
	build(1,n,1), add(1,n);
	while( !q.empty() ) { 
		c = q.top(), q.pop();
		ans[++len] = v[c.x];
		ans[++len] = v[c.y];
		add(c.l,c.x-1);
		add(c.x+1,c.y-1);
		add(c.y+1,c.r);
	}
	rep(i,1,n) printf("%d ", ans[i]); puts("");
	return 0; 
}

