//0-indexedで用いる (実装は1-indexedの配列だけど
//SegmentTree(n,f,m1):=サイズnの初期化。ここでfは2つの区間の要素をマージする二項演算m1はモノイドの単位元である。
//set(k,x) k番目の要素にxを代入する
//build() (代入で作った場合)セグメント木を構築するのに必要
//query(a,b) 区間[a,b)に対して二項演算した結果を返す
//update(k,x) k(0-indexed)番目の要素をxに変更する 
//operator[k] k(0-indexed)番目の要素を返す

template< typename Monoid >
struct SegmentTree {
  using F = function< Monoid(Monoid, Monoid) >;

  int sz;
  vector< Monoid > seg;

  const F f;
  const Monoid M1;

  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }

  void set(int k, const Monoid &x) {
    seg[k + sz] = x;
  }

  void build() {
    for(int k = sz - 1; k > 0; k--) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  void update(int k, const Monoid &x) {
    k += sz;
    seg[k] = x;
    while(k >>= 1) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  Monoid query(int a, int b) {
    Monoid L = M1, R = M1;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) L = f(L, seg[a++]);
      if(b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  Monoid operator[](const int &k) const {
    return seg[k + sz];
  }
};


int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> p(n);
  rep(i,n) cin >> p[i];

  SegmentTree<int> seg_odd(n, [](int a, int b) { return min(a, b); }, INT_MAX);
  SegmentTree<int> seg_even(n, [](int a, int b) { return min(a, b); }, INT_MAX);

  map<int,int> v_to_pos;

  rep(i,n){
    if(i%2==0) seg_even.set(i,p[i]);
    else seg_odd.set(i,p[i]);
    v_to_pos[p[i]] = i;
  }
  seg_even.build();
  seg_odd.build();

  deque<int> ans;
  set<int> used;
  using Pi = tuple< int, int, int, int >;
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  que.push(make_tuple(-1,-1,0,n-1));
  while(!que.empty()){
    auto qt = que.top();que.pop();
    int fv = get<0>(qt);
    int sv = get<1>(qt);
    int st_ind = get<2>(qt);
    int ed_ind = get<3>(qt);
    // cout << fv << " " << sv << " " << st_ind << " " << ed_ind << endl;
    if(fv>0 && used.count(fv)==0){
      ans.push_back(fv);
      ans.push_back(sv);
      used.insert(fv);
      used.insert(sv);
    }
    if(st_ind>=ed_ind) continue;
    int nfv,nsv;
    if(st_ind%2==0){
      nfv = seg_even.query(st_ind,ed_ind+1);
      nsv = seg_odd.query(v_to_pos[nfv]+1,ed_ind+1);
    }
    else{
      nfv = seg_odd.query(st_ind,ed_ind+1);
      nsv = seg_even.query(v_to_pos[nfv]+1,ed_ind+1);
    }
    // cout << "next " << endl;
    // cout << nfv << " " << nsv << endl;
    if(nfv!=INT_MAX && nsv!=INT_MAX){

      que.push(make_tuple(nfv,nsv,st_ind,v_to_pos[nfv]-1));
      que.push(make_tuple(nfv,nsv,v_to_pos[nfv]+1,v_to_pos[nsv]-1));
      que.push(make_tuple(nfv,nsv,v_to_pos[nsv]+1,ed_ind));
    }
  }
  rep(i,ans.size()){
    cout << ans[i] << " \n"[i==ans.size()-1];
  }

  return 0;


}

