    int emin = even.query((l + 1) / 2, (r + 1) / 2);
    int omin = odd.query(l / 2, r / 2);
    int epos = P[emin], opos = P[omin];
//    cout << "pos:" << epos << "," << opos << endl;
    if(epos < opos) ans.pb(mp(min(emin, omin), mp(emin, omin)));
    else ans.pb(mp(min(emin, omin), mp(omin, emin)));

    if(epos > opos) swap(epos, opos);
    dfs(l, epos);
    dfs(epos + 1, opos);
    dfs(opos + 1, r);
}

