long long MX = 1000000009;
int n;
int arr[200009];
pair<int,int>tree[2][1000009];
int lzy[1000009];
vector<int>ans;
pair<int,int>cmp(pair<int,int>a,pair<int,int>b){
    pair<int,int>ret;
    if(a.first < b.first){
        ret.first = a.first;
        ret.second = a.second;
    }
    else{
        ret.first = b.first;
        ret.second = b.second;
    }
    return ret;
}
void build(int node,int l,int r){
    if(l == r){
        tree[0][node].second = l;
        tree[1][node].second = l;
        if(l%2 == 0){
            tree[0][node].first = arr[l];
            tree[1][node].first = MX;
        }
        else{
            tree[0][node].first = MX;
            tree[1][node].first = arr[l];
        }
        return;
    }
    build(node*2,l,(l+r)/2);
    build(node*2+1,(l+r)/2+1,r);
    tree[0][node] = cmp(tree[0][node*2],tree[0][node*2+1]);
    tree[1][node] = cmp(tree[1][node*2],tree[1][node*2+1]);
}
void lzyUPD(int node,int l,int r){
    if(lzy[node] == 0)return;
    swap(tree[0][node],tree[1][node]);
    if(l != r){
        lzy[node*2] = lzy[node];
        lzy[node*2+1] = lzy[node];
    }
    lzy[node] = 0;
}
void UPDRange(int node,int l,int r,int s,int e){
    lzyUPD(node,l,r);
    if(l >= s && r <= e){
        lzy[node] = 1;
        lzyUPD(node,l,r);
        return;
    }
    if((l+r)/2 >= s)UPDRange(node*2,l,(l+r)/2,s,e);
    else lzyUPD(node*2,l,(l+r)/2);
    if((l+r)/2+1 <= e)UPDRange(node*2+1,(l+r)/2+1,r,s,e);
    else lzyUPD(node*2+1,(l+r)/2+1,r);
    tree[0][node] = cmp(tree[0][node*2],tree[0][node*2+1]);
    tree[1][node] = cmp(tree[1][node*2],tree[1][node*2+1]);
}
void UPD(int node,int l,int r,int k,int val){
    lzyUPD(node,l,r);
    if(l == r){
        tree[0][node].first = tree[1][node].first = MX;
        return;
    }
    if((l+r)/2 >= k)UPD(node*2,l,(l+r)/2,k,val);
    else UPD(node*2+1,(l+r)/2+1,r,k,val);
    tree[0][node] = cmp(tree[0][node*2],tree[0][node*2+1]);
    tree[1][node] = cmp(tree[1][node*2+1],tree[1][node*2+1]);
}
pair<int,int>query(int node,int l,int r,int s,int e,int t){
    if(l>=s&&r<=e){
        return tree[t][node];
    }
    if((l+r)/2 >= s && (l+r)/2+1 <= e)return cmp(query(node*2,l,(l+r)/2,s,e,t),query(node*2+1,(l+r)/2+1,r,s,e,t));
    else if((l+r)/2 >= s)return query(node*2,l,(l+r)/2,s,e,t);
    else return query(node*2+1,(l+r)/2+1,r,s,e,t);
}
int main(){
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>arr[i];
    }
    build(1,0,n-1);
    set<int>s;
    s.insert(n);
    for(int i=0;i<n/2;i++){
        pair<int,int>a = query(1,0,n-1,0,n-1,0);
        UPD(1,0,n-1,a.second,MX);
        int En = *s.lower_bound(a.second);
        pair<int,int>b = query(1,0,n-1,a.second,En,1);
        UPD(1,0,n-1,b.second,MX);
        ans.push_back(a.first);
        ans.push_back(b.first);
        s.insert(a.second);
        s.insert(b.second);
        UPDRange(1,0,n-1,a.second+1,b.second-1);
    }
    for(int i=0;i<n;i++){
        cout<<ans[i]<<" ";
    }
}

