vector<int> dfs(vector<int> v,int len){
//	cout<<len<<endl;
	if(len==0) return v;
	if(len==2) return v;
	int fir=-1,sec=-1;
	for(int i=1;i<=len;i+=2){
		if(fir==-1){
			fir=i;
		}
		else{
			if(v[fir-1]>v[i-1]) fir=i;
		}
	}
	for(int i=fir+1;i<=len;i+=2){
		if(sec==-1){
			sec=i;
		}
		else{
			if(v[sec-1]>v[i-1]) sec=i;
		}
	}
	int len1=fir-1-1+1,len2=(sec-1)-(fir+1)+1,len3=len-(sec+1)+1;
//	cout<<fir<<" "<<sec<<" "<<len1<<" "<<len2<<" "<<len3<<" "<<endl;
	vector <int> v1;
	vector <int> v2;
	vector <int> v3;
	vector<int> ans;
	ans.push_back(v[fir-1]);
	ans.push_back(v[sec-1]);
	for(int i=1;i<fir;i++){
		v1.push_back(v[i-1]);
	} 
	for(int i=fir+1;i<sec;i++){
		v2.push_back(v[i-1]);
	} 
	for(int i=sec+1;i<len;i++){
		v3.push_back(v[i-1]);
	} 
	v1=dfs(v1,len1);
	v2=dfs(v2,len2);
	v3=dfs(v3,len3);
	while(v1.size()||v2.size()||v3.size()){
