			pp[Len].second=1;
		}
		if(v2.size()){
			Len++;
			pp[Len].first.first=v2[0];
			pp[Len].first.second=v2[1];
			pp[Len].second=2;
		}
		if(v3.size()){
			Len++;
			pp[Len].first.first=v3[0];
			pp[Len].first.second=v3[1];
			pp[Len].second=3;
		}
//		cout<<Len<<endl;
		sort(pp,pp+Len+1,cmp);
//		cout<<fir-1<<" "<<sec-1<<"d"<<endl;
//		cout<<pp[0].first.first<<" "<<pp[0].first.second<<endl;
//		for(int i=0;i<=Len;i++) cout<<pp[i].first.first<<" "<<pp[i].first.second<<"   ";cout<<endl;
		if(pp[0].second==1){
			ans.push_back(v1[0]);
			ans.push_back(v1[1]);
			v1.erase(v1.begin());
			v1.erase(v1.begin());
		}
		if(pp[0].second==2){
			ans.push_back(v2[0]);
			ans.push_back(v2[1]);
			v2.erase(v2.begin());
			v2.erase(v2.begin());
