//バグったら愚直解法を書いた方がいいって, はっきり分かんだね！
#include <iostream>
#include <queue>
#include <algorithm>
#include <vector>
#include <functional>
#include <tuple>
using namespace std;
typedef tuple<int, int, int> T;
typedef pair<int, int> P;

const int DEPTH = 17;
const int INF = 11451419;

class SegTree {
public:
	int data[1 << (DEPTH + 1)];
	SegTree() { for (int i = 0; i < (1 << (DEPTH + 1)); i++) data[i] = INF; }
	void update(int pos, int x) {
		pos += (1 << DEPTH) - 1;
		data[pos] = x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			data[pos] = min(data[pos * 2 + 1], data[pos * 2 + 2]);
		}
	}
	int getMin(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return INF;
		if (l <= a && b <= r) return data[id];
		int u = getMin(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int v = getMin(l, r, a + (b - a) / 2, b, id * 2 + 2);
		return min(u, v);
	}
};

int n;
int p[200000];
SegTree a[2];
int toPos[200001];
vector<P> ans;

//p[l]～p[r-1]を一つの数列(a[0], a[1], …)とみなすとき, 偶数番目の最小値を返す
int getEvenMin(int l, int r) {
	if (l >= r) return INF;
	return a[l % 2].getMin(l / 2, (r - 1 - (l % 2)) / 2 + 1);
}

//p[l]～p[r-1]を一つの数列(a[0], a[1], …)とみなすとき, 奇数番目の最小値を返す
int getOddMin(int l, int r) {
	if (l + 1 >= r) return INF;
	return a[(l + 1) % 2].getMin((l + 1) / 2, (r - 1 - ((l + 1) % 2)) / 2 + 1);
}

int main() {
	int i;

	cin >> n;
	for (i = 0; i < n; i++) cin >> p[i];
	for (i = 0; i < n; i++) toPos[p[i]] = i;
	for (i = 0; i < n / 2; i++) a[0].update(i, p[2 * i]);
	for (i = 0; i < n / 2; i++) a[1].update(i, p[2 * i + 1]);

	priority_queue<T, vector<T>, greater<T> > que;
	que.push(T(getEvenMin(0, n), 0, n));

	while (!que.empty()) {
		T t = que.top(); que.pop();
		if (get<1>(t) >= get<2>(t)) continue;

		int x = get<0>(t);
		int y = getOddMin(toPos[x], get<2>(t));
		ans.push_back(P(x, y));

		que.push(T(getEvenMin(get<1>(t), toPos[x]), get<1>(t), toPos[x]));
		que.push(T(getEvenMin(toPos[x] + 1, toPos[y]), toPos[x] + 1, toPos[y]));
		que.push(T(getEvenMin(toPos[y] + 1, get<2>(t)), toPos[y] + 1, get<2>(t)));
	}

	for (i = 0; i < ans.size(); i++) {
		cout << ans[i].first << " " << ans[i].second;
		if (i + 1 < ans.size()) cout << " ";
		else cout << endl;
	}
	return 0;
}

