typedef long long ll;

ll index[200100];
ll treenep[800100];
ll treep[800100];

void updatep(ll v, ll tl, ll tr, ll pos, ll val) {
	if (tl == tr) {
		treep[v] = val;
		return;
	}
	ll tm = (tl + tr) / 2;
	if (pos <= tm)updatep(2 * v, tl, tm, pos, val);
	else updatep(2 * v + 1, tm + 1, tr, pos, val);
	treep[v] = min(treep[2 * v], treep[2 * v + 1]);
}
void updatenep(ll v, ll tl, ll tr, ll pos, ll val) {
	if (tl == tr) {
		treenep[v] = val;
		return;
	}
	ll tm = (tl + tr) / 2;
	if (pos <= tm)updatenep(2 * v, tl, tm, pos, val);
	else updatenep(2 * v + 1, tm + 1, tr, pos, val);
	treenep[v] = min(treenep[2 * v], treenep[2 * v + 1]);
}
ll minnp(ll v, ll tl, ll tr, ll l, ll r) {
	if (l > r)return 1000000000;
	if (tl == l && tr == r)return treep[v];
	ll tm = (tl + tr) / 2;
	return min(minnp(2 * v, tl, tm, l, min(r, tm)), minnp(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
}
ll minnnep(ll v, ll tl, ll tr, ll l, ll r) {
	if (l > r)return 1000000000;
	if (tl == l && tr == r)return treenep[v];
	ll tm = (tl + tr) / 2;
	return min(minnnep(2 * v, tl, tm, l, min(r, tm)), minnnep(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
}

