struct segment{
	int tree[maxn << 2], lazy[maxn << 2];
	void pushdown(int rt){
		if(lazy[rt] == -1)
			return;
		tree[rt << 1] = lazy[rt];
		tree[rt << 1 | 1] = lazy[rt];
		lazy[rt << 1] = lazy[rt];
		lazy[rt << 1 | 1] = lazy[rt];
		lazy[rt] = -1;
	}

	void build(int x, int l, int r, int rt){
		lazy[rt] = -1;
		if(l == r){
			tree[rt] = x;
			return;
		}
		int m = (l + r) >> 1;
		build(x, lson);
		build(x, rson);
	}

	void update(int L, int R, int x, int l, int r, int rt){
		if(L <= l && r <= R){
			tree[rt] = x;
			lazy[rt] = x;
			return;
		}
		int m = (l + r) >> 1;
		pushdown(rt);
		if(L <= m)
			update(L, R, x, lson);
		if(R > m)
			update(L, R, x, rson);
	}

	int query(int L, int R, int l, int r, int rt){
		if(L <= l && r <= R)
			return tree[rt];
		int m = (l + r) >> 1;
		pushdown(rt);
		if(L <= m)
			return query(L, R, lson);
		else
			return query(L, R, rson);
	}
}t1,t2;

void init(){
	for(int i = 1; i <= n; i++){
		if(i & 1){
			L[i][0] = a[i];
			R[i][0] = INF;
		}
		else{
			L[i][0] = INF;
			R[i][0] = a[i];
		}
	}

	for(int j = 1; 1 << j <= n; j++){
		for(int i = 1; i + (1 << j) - 1 <= n; i++){
			L[i][j] = min(L[i][j - 1], L[i + (1 << (j - 1))][j - 1]);
			R[i][j] = min(R[i][j - 1], R[i + (1 << (j - 1))][j - 1]);
		}
	}
}

int RMQ(int x, int l, int r){
	int k = LG[r - l + 1];
	if(x == 1){
		return min(L[l][k], L[r - (1 << k) + 1][k]);
	}
	else{
		return min(R[l][k], R[r - (1 << k) + 1][k]);
	}
}

void modify(int l, int r){
	//cout << l << " " << r << endl;
	int mi = 0;
	if(l & 1){
		mi = RMQ(1, l ,r);
	}
	else{
		mi = RMQ(2, l, r);
	}
	Q.push(-mi);
	t1.update(l, r, l, 1, n, 1);
	t2.update(l, r, r, 1, n, 1);
}

int main(){
	for(int i = 1; i < maxn; i++)
		LG[i] = log2(i);
	cin >> n;
	for(int i = 1; i <= n; i++){
		scanf("%d", &a[i]);
		pos[a[i]] = i;
	}
	t1.build(1, 1, n, 1);
	t2.build(n, 1, n, 1);
	init();

	Q.push(-RMQ(1, 1, n));
	while(!Q.empty()){
		int cur = Q.top();
		Q.pop();
		cur = -cur;
		int p = pos[cur];
		int pp = p;
		int ed = t2.query(p, p, 1, n, 1);
		int bg = t1.query(p, p, 1, n, 1);
		ans.push_back(cur);
		int mi;
		if(p & 1){
			//printf("query %d %d\n", p, ed);
			 mi = RMQ(2, p, ed);
		}
		else{
			 mi = RMQ(1, p, ed);
		}
		ans.push_back(mi);	
		pp = pos[mi];
		//printf(">>>>%d %d %d\n", p, pp, mi);
		if(bg < p)
			modify(bg, p - 1);
		if(pp - 1 >= p + 1)
			modify(p + 1, pp - 1);
		if(pp < ed)
			modify(pp + 1, ed);
		//int tt; cin >> tt;
	}
	for(int i = 0; i < ans.size(); i++){
		printf("%d", ans[i]);
		if(i == n - 1) puts("");
		else printf(" ");
	}
	return 0;
}

