namespace SGT {

int minn[800000][2];

void build(int l,int r,int o) {
  if (l==r) {
    minn[o][l&1]=num[l];
    minn[o][!(l&1)]=inf;
  }
  else {
    int m=((l+r)>>1);
    build(l,m,o*2);
    build(m+1,r,o*2+1);
    minn[o][0]=min(minn[o*2][0],minn[o*2+1][0]);
    minn[o][1]=min(minn[o*2][1],minn[o*2+1][1]);
  }
}

void update(int l,int r,int o,int p) {
  if (l==r) minn[o][l&1]=inf;
  else {
    int m=((l+r)>>1);
    if (m>=p) update(l,m,o*2,p);
    else update(m+1,r,o*2+1,p);
    minn[o][0]=min(minn[o*2][0],minn[o*2+1][0]);
    minn[o][1]=min(minn[o*2][1],minn[o*2+1][1]);
  }
}

int query(int l,int r,int o,int lx,int rx,int d) {
  if (l>=lx&&r<=rx) return minn[o][d];
  else {
    int m=((l+r)>>1);
    if (m>=rx) return query(l,m,o*2,lx,rx,d);
    if (m<lx) return query(m+1,r,o*2+1,lx,rx,d);
    return min(query(l,m,o*2,lx,rx,d),query(m+1,r,o*2+1,lx,rx,d));
  }
}

}

