const int INF = 1e9 + 239;

struct Node {
	int len;
	int min_f;
	int min_s;
	pair<int, int> ans;

	Node() {
		len = 0;
		min_f = INF;
		min_s = INF;
		ans = {INF, INF};
	}

	Node(int x) {
		len = 1;
		min_f = x;
		min_s = INF;
		ans = {INF, INF};
	}

	Node(int len_, int min_f_, int min_s_, pair<int, int> ans_) {
		len = len_;
		min_f = min_f_;
		min_s = min_s_;
		ans = ans_;
	}

	friend Node conq(const Node &a, const Node &b) {
		if (a.len & 1) {
			pair<int, int> nans = {a.min_f, b.min_f};
			return Node(a.len + b.len, min(a.min_f, b.min_s), min(a.min_s, b.min_f), min({a.ans, b.ans, nans}));
		} else {
			pair<int, int> nans = {a.min_f, b.min_s};
			return Node(a.len + b.len, min(a.min_f, b.min_f), min(a.min_s, b.min_s), min({a.ans, b.ans, nans}));
		}
	}
};

namespace SegmentTree {
	int n;
	vector<int> a;
	vector<Node> t;

	void pull(int v) {
		t[v] = conq(t[2 * v + 1], t[2 * v + 2]);
	}

	void build(int v, int l, int r) {
		if (l + 1 == r) {
			t[v] = Node(a[l]);
		} else {
			int m = (r + l) >> 1;
			build(2 * v + 1, l, m);
			build(2 * v + 2, m, r);
			pull(v);
		}
	}

	void query(int v, int l, int r, int ql, int qr, Node &ans) {
		if (r <= ql || qr <= l) {
			return;
		} else if (ql <= l && r <= qr) {
			ans = conq(ans, t[v]);
		} else {
			int m = (r + l) >> 1;
			query(2 * v + 1, l, m, ql, qr, ans);
			query(2 * v + 2, m, r, ql, qr, ans);
		}
	}

	void init(vector<int> &a_) {
		a = a_;
		n = (int)a.size();
		t.resize(4 * n);
		build(0, 0, n);
	} 

	pair<int, int> solve(int l, int r) {
		Node ans;
		query(0, 0, n, l, r, ans);
		return ans.ans;
	}
}

