void build(pair<int, int>* arb, int par, int nod, int st, int dr)
{
    if(st == dr)
    {
        if((par && st % 2 == 0) || (!par && st % 2 != 0))
            arb[nod] = make_pair(v[st], st);
        else arb[nod] = make_pair(inf, inf);
        return;
    }
    int mij = (st + dr) / 2;
    build(arb, par, nod * 2, st, mij);
    build(arb, par, nod * 2 + 1, mij + 1, dr);
    arb[nod] = min(arb[nod * 2], arb[nod * 2 + 1]);
}

pair<int, int> query(pair<int, int>* arb, int nod, int st, int dr, int ist, int idr)
{
    if(ist <= st && dr <= idr)
    {
        return arb[nod];
    }
    int mij = (st + dr) / 2;
    pair<int, int> q1 = make_pair(inf, inf), q2 = make_pair(inf, inf);
    if(ist <= mij)
        q1 = query(arb, nod * 2, st, mij, ist, idr);
    if(idr > mij)
        q2 = query(arb, nod * 2 + 1, mij + 1, dr, ist, idr);
    return min(q1, q2);
}

