#define child 2*node
#define mid (l+r)/2

void build(int idx,int node,int l,int r){
	if(l == r){
		if(idx%2 == l%2){
			seg[node][idx] = {a[l],l};
		}
		else{
			seg[node][idx] = {INF,0};
		}
		return;
	}
	build(idx,child,l,mid);
	build(idx,child+1,mid+1,r);
	seg[node][idx] = min(seg[child][idx],seg[child+1][idx]);
}

pair<int,int> query(int idx,int node,int l,int r,int start,int end){
	if(l > end or start > r)return {INF,0};
	if(start <= l and r <= end)return seg[node][idx];
	return min(query(idx,child,l,mid,start,end),query(idx,child+1,mid+1,r,start,end));
}

