#define pp 131072

set< pair<int,int> > prt;
int su[300001];
int tree[2][pp*2];
int n;
pair<int,int> seq[300001];
priority_queue< pair<int,int>, vector< pair<int,int> >, greater< pair<int,int> > > pq;

int upd(int ww, int idx, int vall){
    idx += pp;
    tree[ww][idx] = vall;
    idx /= 2;
    while(idx){
        tree[ww][idx] = min(tree[ww][idx*2], tree[ww][idx*2+1]);
        idx >>= 1;
    }
}

int gett(int ww, int ss, int ee){
    //printf("gett: %d %d %d ", ww, ss, ee);
    int ans = n + 100;
    ss += pp; ee += pp;
    while(ss <= ee){
        if(ss%2 == 1){
            ans = min(ans, tree[ww][ss++]);
        }else if(ee%2 == 0){
            ans = min(ans, tree[ww][ee--]);
        }
        if(ss>ee) break;
        ss >>= 1; ee >>= 1;
    }
    //printf(": %d\n", ans);
    return ans;
}

pair<int,int> getBest(int ss, int ee){
    int target1 = gett(ss%2, ss/2, (ee-1)/2);
    int t1 = seq[target1-1].second;
    //printf("%d\n", t1);
    int target2 = gett((t1+1)%2, (t1+1)/2, ee/2);
    return make_pair(target1, target2);
}

