    auto e2 = (l%2?SegL:SegR).getvar(s,r+1);
    int t = e2.second;
    match[s] = t;

    if(0<=l&&l<=s-1&&s-1<=r&&r<N){
        pair<int,int> vl = rec(l,s-1);
        edge[s].push_back(vl.first);
    }
    if(0<=l&&l<=s+1&&s+1<t-1&&t-1<=r&&r<N) {
        pair<int,int> vc = rec(s+1,t-1);
        edge[s].push_back(vc.first);
