int a[200005];
int where[200005];
int n;
vector< pair<int, long long> > v;

int solve(int lo, int hi, int find, int level) {
    if (hi - lo < 2) return find;

    int x = -1;
    int y = -1;
    if (1) {
        for (int i = find; ; ++i) {
            if (lo <= where[i] && where[i] < hi) {
                if (x == -1)
                    x = where[i];
                else if ((x - where[i]) & 1) {
                    y = where[i];
                    break;
                }
            }
        }
    }
    else {
        for (int i = lo; i < hi; ++i) {
            if (x == -1 || a[x] > a[i]) {
                y = x;
                x = i;
            }
            else if (y == -1 || a[y] > a[i])
                y = i;
        }
    }
    if (a[x] == find) {
        ++find;
        if (a[y] == find)
            ++find;
    }
    if (x > y) swap(x, y);
    v.push_back(make_pair(level, (long long)a[x] * (n + 1) + a[y]));
    //printf("%d %d\n", a[x], a[y]);
    find = solve(lo, x, find, level + 1);
    find = solve(x + 1, y, find, level + 1);
    find = solve(y + 1, hi, find, level + 1);
    return find;
}

