typedef long long ll;

template<typename T> struct SparseTable{
	vector< vector<int> > table;
	vector<T> dat;
	vector<int> logTable;
	void init(vector<T> _dat,bool rev = false){
		dat = _dat;
		int n = dat.size();
		if(rev) for(int i = 0;i < n;i++) dat [i] *= -1;
		logTable.assign(n + 1,0);
		for(int i = 2;i <= n;i++){
			logTable [i] = logTable [i / 2] + 1;
		}
		table.assign(logTable [n] + 1,vector<int>(n,0));
		for(int i = 0;i < n;i++) table [0] [i] = i;
		for(int i = 1;i <= logTable [n];i++){
			for(int j = 0;j + (1 << i) <= n;j++){
				if(dat [table [i - 1] [j]] < dat [table [i - 1] [j + (1 << (i - 1))]]){
					table [i] [j] = table [i - 1] [j];
				}
				else{
					table [i] [j] = table [i - 1] [j + (1 << (i - 1))];
				}
			}
		}
	}
	int get_min(int l,int r){
		int lg = logTable [r - l];
		if(dat [table [lg] [l]] < dat [table [lg] [r - (1 << lg)]]){
			return table [lg] [l];
		}
		return table [lg] [r - (1 << lg)];
	}
};

int N;
