int new_node()
{
	return nNode++;
}

void dfs(int l,int r,int prev = -1)
{
	if(l == r) return;
	int curr = new_node();
	int x = st [l % 2].get_min(l,r);
	int y = st [l % 2 == 0].get_min(x + 1,r);
	node [curr] = make_pair(A [l % 2] [x],A [l % 2 == 0] [y]);
	if(prev != -1){
		edge [prev].push_back(curr);
		deg [curr]++;
	}
	dfs(l,x,prev);
	dfs(x + 1,y,curr);
	dfs(y + 1,r,prev);
}

