			tt.pop_front();
		}
		//cout << "who = " << who << endl;
		//cout << "push front" << f << " " << s << endl;
		ret.push_back(f);
		ret.push_back(s);
	}

	ret.push_front(sval);
	ret.push_front(fval);
	return ret;
