struct segtree{
    static const int base = 1<<18;
    int A[2*base+2], B[2*base+2], rem[2*base+2];

    void init()
    {
        for(int i=1;i<=base*2-1;i++){
            A[i] = INF;
            B[i] = INF;
            rem[i] = 0;
        }
    }

    void update(int ind, int val){
        ind += base-1;
        A[ind] = val;
        rem[ind] = 1;
        while(ind > 1){
            ind /= 2;
            if(rem[2*ind] % 2 == 1){
                A[ind] = min(A[2*ind], B[2*ind+1]);
                B[ind] = min(B[2*ind], A[2*ind+1]);
            }
            else {
                A[ind] = min(A[2*ind], A[2*ind+1]);
                B[ind] = min(B[2*ind], B[2*ind+1]);
            }
            rem[ind] = rem[2*ind] + rem[2*ind+1];
        }
    }

    mindol getmin(int ind, int s, int e, int look_s, int look_e){
        if(s<=look_s && look_e<=e) return {A[ind], B[ind], rem[ind]};
        if(look_e<s || look_s > e) return {INF, INF, 0};
        mindol a1 = getmin(ind*2, s, e, look_s, (look_s+look_e)/2);
        mindol a2 = getmin(ind*2+1, s, e, (look_s+look_e)/2+1, look_e);
        if(a1.rem % 2 == 1) return {min(a1.a, a2.b), min(a1.b, a2.a), a1.rem+a2.rem};
        else return {min(a1.a, a2.a), min(a1.b, a2.b), a1.rem+a2.rem};
    }

    int getMin(int s, int e){
        return getmin(1, s, e, 1, base).a;
    }

    void del(int ind){
        ind += base-1;
        A[ind] = INF;
        B[ind] = INF;
        rem[ind] = 0;
        while(ind > 1){
            ind /= 2;
            if(rem[2*ind] % 2 == 1){
                A[ind] = min(A[2*ind], B[2*ind+1]);
                B[ind] = min(B[2*ind], A[2*ind+1]);
            }
            else {
                A[ind] = min(A[2*ind], A[2*ind+1]);
                B[ind] = min(B[2*ind], B[2*ind+1]);
            }
            rem[ind] = rem[2*ind] + rem[2*ind+1];
        }
    }


