const int inf = 1001001001;

struct segtree {
  vector<pair<int, int>> dat;
  static const int N = 1 << 18;

  segtree() : dat(2 * N, make_pair(inf, -1)){}

  void init(vector<int> &v) {
    for (int i = 0; i < v.size(); ++i) {
      dat[i + N - 1] = make_pair(v[i], i);
    }
    for (int i = N - 2; i >= 0; --i) {
      dat[i] = min(dat[2 * i + 1], dat[2 * i + 2]);
    }
  }

  pair<int, int> get_min(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return pair<int, int>(inf, -1);
    if (a <= l && r <= b) return dat[k];

    return min(
      get_min(a, b, 2 * k + 1, l, (l + r) / 2),
      get_min(a, b, 2 * k + 2, (l + r) / 2, r)
    );
  }

  pair<int, int> get_min(int a, int b) {
    return get_min(a, b, 0, 0, N);
  }
};

