vector<int> convert(const vector<int>& res)
{
	if (res.size() <= 2) return res;

	vector<int> ans;

	int firstI = 0;
	for (int i = 2; i < res.size(); i += 2){
		if (res[i] < res[firstI]) firstI = i;
	}

	int secondI = firstI + 1;
	for (int i = secondI + 2; i < res.size(); i += 2){
		if (res[i] < res[secondI]) secondI = i;
	}

	vector<int> v1, v2, v3;
	if (firstI > 0){
		copy(res.begin(), res.begin() + (firstI), back_inserter(v1));
		v1 = convert(v1);
	}
	if (secondI - firstI > 1){
		copy(res.begin() + (firstI + 1), res.begin() + (secondI), back_inserter(v2));
		v2 = convert(v2);
	}
	if (secondI < res.size() - 1){
		copy(res.begin() + (secondI + 1), res.end(), back_inserter(v3));
		v3 = convert(v3);
	}

	ans.push_back(res[firstI]);
	ans.push_back(res[secondI]);
	while (!v1.empty() || !v2.empty() || !v3.empty()){
		int n1 = !v1.empty() ? v1[0] : N + 1;
		int n2 = !v2.empty() ? v2[0] : N + 1;
		int n3 = !v3.empty() ? v3[0] : N + 1;

		if (n1 < n2 && n1 < n3){
			ans.push_back(v1[0]);
			v1.erase(v1.begin());
			ans.push_back(v1[0]);
			v1.erase(v1.begin());
		} else if (n2 < n1 && n2 < n3){
			ans.push_back(v2[0]);
			v2.erase(v2.begin());
			ans.push_back(v2[0]);
			v2.erase(v2.begin());
		} else {
			ans.push_back(v3[0]);
			v3.erase(v3.begin());
			ans.push_back(v3[0]);
			v3.erase(v3.begin());
		}
	}

	return ans;
}

