class RMQ{
	int n,seg,init;
	vector<P> dat;
	public:
	void ini(int siz,int def){
		n = siz;
		init = def;
		seg = 1;
		while(seg < n) seg *= 2;
		dat.resize(seg * 2 - 1);
		for(int i = seg - 1;i < seg * 2 - 1;i++) dat[i] = P(init,i - seg + 1);
		for(int i = seg - 2;i >= 0;i--) dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]);
	}
	void update(int i,int x){
		i += seg - 1;
		dat[i].first = x;
		while(i){
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1],dat[i * 2 + 2]);
		}
	}
	P get(int a,int b,int k = 0,int l = 0,int r = -1){
		if(r == -1) r = seg;
		if(b <= l || r <= a) return P(init,-1);
		if(a <= l && r <= b) return dat[k];
		return min(get(a,b,k * 2 + 1,l,(l + r) / 2),get(a,b,k * 2 + 2,(l + r) / 2,r));
	}
};

