using namespace std;

inline bool Better(const vector<int> &vec, const pair<int, int> &att, const pair<int, int> &def)
{
  if (vec[att.first] == vec[def.first]) {
    return vec[att.second] < vec[def.second];
  }
  return vec[att.first] < vec[def.first];
}

pair<int, int> BestPair(const vector<int> &vec, int max_dist)
{
  pair<int, int> res = {0, 1};

  for (size_t i = 0; i < vec.size(); ++i) {
    for (size_t j = i + 1; j < vec.size(); j += 2) {
      if (j - i > static_cast<size_t>(max_dist)) {
        break;
      }
      if (Better(vec, {i, j}, res) && i % 2 == 0 && (vec.size() - j - 1) % 2 == 0) {
        res = {i, j};
      }
    }
  }
  return res;
}

vector<int> FindRes(vector<int> &vec)
{
  vector<int> res(vec.size());
  int index = 0;

  while (index < static_cast<int>(res.size())) {
    auto pos = BestPair(vec, vec.size() - index);
    res[index] = vec[pos.first];
    res[index + 1] = vec[pos.second];

    vec.erase(vec.begin() + pos.first);
    vec.erase(vec.begin() + pos.second - 1);
    index += 2;
  }
  return res;
}

int main()
{
  int n;
  cin >> n;

  vector<int> vec(n);
  for (int i = 0; i < n; ++i) {
    cin >> vec[i];
  }

  auto res = FindRes(vec);
  for (int i : res) {
    cout << i << " ";
  }
  cout << "\n";
  return 0;
}

