void build(int cn ,int b, int e)
{
    if( b==e )
    {
        if(b%2==0) tr[cn] = mp(0,b) ;
        else tr[cn] = mp(b,0) ;
        return ;
    }
    int lc = cn*2 , rc = cn*2 +1 , m = (b+e)/2 ;
    build(lc,b,m) ; build(rc,m+1,e) ;
    tr[cn] = Merge(tr[lc] , tr[rc]) ;
}

pii query(int cn ,int b, int e, int l, int r)
{
    if( e<l || b>r ) return mp(0,0) ;
    if( l<=b && e<=r ) return tr[cn] ;
    int lc = cn*2 , rc = cn*2 +1 , m = (b+e)/2 ;
    pii r1 = query(lc,b,m,l,r) , r2 = query(rc,m+1,e,l,r) ;
    return Merge(r1,r2) ;
}

