int get (int o, int id) {
    return tag[o] ? seg[o][id^1] : seg[o][id];
}

void pull (int o) {
    seg[o][0] = min(get(o<<1, 0), get(o<<1|1, 0));
    seg[o][1] = min(get(o<<1, 1), get(o<<1|1, 1));
}

void push (int o) {
    if (tag[o]) {
        swap(seg[o][0], seg[o][1]);
        tag[o<<1] ^= 1;
        tag[o<<1|1] ^= 1;
        tag[o] = 0;
    }
}

void build (int o, int l, int r) {
    if (r == l + 1) {
        seg[o][l&1] = a[l];
    } else {
        int mid = (l + r) >> 1;
        build(o<<1, l, mid);
        build(o<<1|1, mid, r);
        pull(o);
    }
}

void flip (int qL, int qR, int o=1, int nL=0, int nR=n) {
    if (nL >= qR || qL >= nR || qL >= qR) {
        return;
    } else if (qL <= nL && nR <= qR) {
        tag[o] ^= 1;
        debug(nL, nR);
    } else {
        push(o);
        int nM = (nL + nR) >> 1;
        flip(qL, qR, o<<1, nL, nM);
        flip(qL, qR, o<<1|1, nM, nR);
        pull(o);
    }
}

void chg (int x, int o=1, int nL=0, int nR=n) {
    if (nL > x || x >= nR) {
        return;
    } else if (nL == x && nR == x+1) {
        seg[o][0] = seg[o][1] = INF;
    } else {
        push(o);
        int nM = (nL + nR) >> 1;
        chg(x, o<<1, nL, nM);
        chg(x, o<<1|1, nM, nR);
        pull(o);
    }
}

int qry (int qL, int qR, int o=1, int nL=0, int nR=n) {
    if (nL >= qR || qL >= nR || qL >= qR) {
        return INF;
    } else if (qL <= nL && nR <= qR) {
        debug(tag[o], nL, nR);
        return tag[o] ? seg[o][1] : seg[o][0];
    } else {
        push(o);
        int nM = (nL + nR) >> 1;
        return min(qry(qL, qR, o<<1, nL, nM), qry(qL, qR, o<<1|1, nM, nR));
    }
}
