    auto [y, r] = rmq[(i + 1) & 1].query(i, j);
    ans[k] = y;
    ++k;
    if (i < l) {
      q.push({rmq[i & 1].query(i, l), i, l});
    }
    if (l + 1 < r) {
      q.push({rmq[(l + 1) & 1].query(l + 1, r), l + 1, r});
    }
    if (r + 1 < j) {
      q.push({rmq[(r + 1) & 1].query(r + 1, j), r + 1, j});
    }
  }
