int a[2*MAXN+5];
int evens[MAXN+5], odds[MAXN+5];
int evenM[MAXN+5][20], oddM[MAXN+5][20];

void preprocess(int M[MAXN+5][20], int A[MAXN], int n)
{
    for (int i=0; i<n; i++)
        M[i][0] = i;
    for (int j=1; (1<<j)<=n; j++) {
        for (int i=0; i+(1<<j)-1<n; i++) {
            if (A[M[i][j-1]] < A[M[i+(1<<(j-1))][j-1]])
                M[i][j] = M[i][j-1];
            else 
                M[i][j] = M[i+(1<<(j-1))][j-1];
        }
    }
}

int RMQ(int M[MAXN+5][20], int arr[MAXN+5], int l, int r)
{
    int k=0;
    while ((1<<k)<=(r-l+1))
        k++;
    k--;
    int ret;
    if (arr[M[l][k]] < arr[M[r-(1<<k)+1][k]])
        ret = M[l][k];
    else 
        ret = M[r-(1<<k)+1][k];
    assert(l <= ret && ret <= r);
    return ret;
}

vector<pair<int,int>> solve(int l, int r)
{
    if (l >= r) {
        return vector<pair<int,int>>();
    }
    //pr("solve") pr(l) pr(r) nl
    if (l+1 == r) {
        return vector<pair<int,int>>({mp(a[l],a[r])});
    }

    vector<pair<int,int>> ret, rec1,rec2,rec3;
    if (l%2 == 0) {
        int first = RMQ(evenM, evens, l/2, r/2);
        int second = RMQ(oddM, odds, first, r/2);
        //pr(first) pr(second) nl
        ret.pb(mp(a[2*first], a[2*second+1]));

        rec1 = solve(l,2*first-1);
        //iter(rec) pairs.pb(*it);
        rec2 = solve(2*first+1,2*second);
        //iter(rec) pairs.pb(*it);
        rec3 = solve(2*second+2, r);
        //iter(rec) pairs.pb(*it);
    }
    else {
        int first = RMQ(oddM, odds, l/2, (r-1)/2);
        //prl(first)
        int second = RMQ(evenM, evens, first+1, r/2);
        //prl(second) nl
        ret.pb(mp(a[2*first+1], a[2*second]));

        rec1 = solve(l,2*first);
        //iter(rec) pairs.pb(*it);
        rec2 = solve(2*first+2,2*second-1);
        //iter(rec) pairs.pb(*it);
        rec3 = solve(2*second+1, r);
        //iter(rec) pairs.pb(*it);
    }

    //sort(pairs.begin()+1,pairs.end());
    //pr("solve") pr(l) pr(r) nl 
    int i1=0, i2=0, i3=0;
    while (i1 < sz(rec1) || i2 < sz(rec2) || i3 < sz(rec3)) {
        pair<int,int> best = mp(INF,INF);
        int best_idx=0;
        if (i1 < sz(rec1) && rec1[i1] < best) {
            best = rec1[i1];
            best_idx = 0;
        }
        if (i2 < sz(rec2) && rec2[i2] < best) {
            best = rec2[i2];
            best_idx = 1;
        }
        if (i3 < sz(rec3) && rec3[i3] < best) {
            best = rec3[i3];
            best_idx = 2;
        }

        ret.pb(best);
        if (best_idx == 0)
            i1++;
        else if (best_idx == 1)
            i2++;
        else 
            i3++;
    }
    //iter(ret) {prp(*it)} nl
    return ret;
}

