typedef long long ll;

int n, a[N], nx[N * 4];
pair <int, int> t[N * 4][3];
vector < pair <int, int> > ans;

void build(int v = 1, int tl = 1, int tr = n)
{
      if(tl == tr)
      {
            t[v][tl % 2] = mk(a[tl], tl);
            t[v][(tl % 2) ^ 1] = mk(inf, 0);
            t[v][2] = mk(a[tl], tl);
            nx[v] = tl;
      }
      else
      {
            int tm = (tl + tr) >> 1;
            build(v << 1, tl, tm);
            build((v << 1) | 1, tm + 1, tr);
            t[v][0] = min(t[v << 1][0], t[(v << 1) | 1][0]);
            t[v][1] = min(t[v << 1][1], t[(v << 1) | 1][1]);
            t[v][2] = min(t[v << 1][2], t[(v << 1) | 1][2]);
            nx[v] = min(nx[v << 1], nx[(v << 1) | 1]);
      }
}

void update(int pos, int v = 1, int tl = 1, int tr = n)
{
      if(tl == tr)
      {
            t[v][tl % 2] = mk(inf, 1);
            t[v][2] = mk(inf, 1);
            nx[v] = inf;
      }
      else
      {
            int tm = (tl + tr) >> 1;
            if(pos <= tm) update(pos, v << 1, tl, tm);
            else update(pos, (v << 1) | 1, tm + 1, tr);
            t[v][0] = min(t[v << 1][0], t[(v << 1) | 1][0]);
            t[v][1] = min(t[v << 1][1], t[(v << 1) | 1][1]);
            t[v][2] = min(t[v << 1][2], t[(v << 1) | 1][2]);
            nx[v] = min(nx[v << 1], nx[(v << 1) | 1]);
      }
}

int next(int l, int r, int v = 1, int tl = 1, int tr = n)
{
      if(l > tr || tl > r) return inf;
      if(l <= tl && tr <= r) return nx[v];
      int tm = (tl + tr) >> 1;
      return min(next(l, r, v << 1, tl, tm),
                        next(l, r, (v << 1) | 1, tm + 1, tr));
}

pair <int, int> get(int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
      if(l > tr || tl > r) return mk(inf, 1);
      if(l <= tl && tr <= r) return t[v][type];
      int tm = (tl + tr) >> 1;
      return min(get(l, r, type, v << 1, tl, tm),
                        get(l, r, type, (v << 1) | 1, tm + 1, tr));
}

vector < pair <int, int> > dv(int l, int r)
{
      vector < pair <int, int> > v1, v2, v3, v4;
      if(l >= r) return v4;
      if(l + 1 == r)
      {
            v4.pb(mk(a[l], a[r]));
            return v4;
      }
      int aa = get(l, r - 1, l % 2).sc, bb = get(l + 1, r, (l % 2) ^ 1).sc, i1 = 0, i2 = 0, i3 = 0;
      v4.pb(mk(a[aa], a[bb]));
      v1 = dv(l, aa - 1);
      v2 = dv(aa + 1, bb - 1);
      v3 = dv(bb + 1, r);

      while(i1 < v1.size() && i2 < v2.size() && i3 < v3.size())
      {
            if(v1[i1] < v2[i2] && v1[i1] < v3[i3])
                  v4.pb(v1[i1 ++]);
            else if(v2[i2] < v1[i1] && v2[i2] < v3[i3])
                  v4.pb(v2[i2 ++]);
            else
                  v4.pb(v3[i3 ++]);
      }

      while(i1 < v1.size() && i2 < v2.size())
      {
            if(v1[i1] < v2[i2])
                  v4.pb(v1[i1 ++]);
            else
                  v4.pb(v2[i2 ++]);
      }
      while(i1 < v1.size() && i3 < v3.size())
      {
            if(v1[i1] < v3[i3])
                  v4.pb(v1[i1 ++]);
            else
                  v4.pb(v3[i3 ++]);
      }
      while(i3 < v3.size() && i2 < v2.size())
      {
            if(v3[i3] < v2[i2])
                  v4.pb(v3[i3 ++]);
            else
                  v4.pb(v2[i2 ++]);
      }

      while(i1 < v1.size())
            v4.pb(v1[i1 ++]);
      while(i2 < v2.size())
            v4.pb(v2[i2 ++]);
      while(i3 < v3.size())
            v4.pb(v3[i3 ++]);

      return v4;
}

