const int N = 2e5 + 5, inf = 1e9 + 7;

int n, ar[N], pos[N], u[N], ans[N], cnt, sz;

struct st
{
    int e, o;
    st()
    {
        e = inf;
        o = inf;
    }
};

st t[N * 4];

void build (int v = 1, int tl = 1, int tr = n)
{
    if (tl == tr)
    {
        if (tl & 1)
            t[v].o = ar[tl];
        else
            t[v].e = ar[tl];
    }
    else
    {
        int tm = (tl + tr) >> 1;
        build (v + v, tl, tm);
        build (v + v + 1, tm + 1, tr);
        t[v].o = min( t[v + v].o, t[v + v + 1].o );
        t[v].e = min( t[v + v].e, t[v + v + 1].e );
    }
}
int get (int l, int r, int type, int v = 1, int tl = 1, int tr = n)
{
    if (l > r || l > tr || tl > r)
        return inf;

    if (l <= tl && tr <= r)
        return (type & 1 ? t[v].o : t[v].e );

    int tm = (tl + tr) >> 1;
    return min( get( l, r, type, v + v, tl, tm ), get(l, r, type, v + v + 1, tm + 1, tr) );
}

map <int,map <int, int> > mp;

vector <int> vec[N];

vector <pair <int, int> > Vec;

pair <int, int> Pr[N];

pair <int, int> Compute (int l, int r)
{
    int type = (l & 1 ? 1 : 0);

    int res = get(l, r, type);

    int Sc = get( pos[ res ] + 1, r, type ^ 1 );

    if (!mp[res].count( Sc ) )
    {
        Pr[++cnt] = mk(res, Sc);
        mp[res][Sc] = cnt;
    }
    vector <pair <int, int> > V;

    if(l < pos[res] - 1)
        V.pb( Compute( l, pos[res] - 1 ) );
    if(pos[res] + 1 < pos[Sc] - 1)
        V.pb( Compute( pos[res] + 1, pos[Sc] - 1 ));
    if( pos[Sc] + 1 < r)
        V.pb( Compute( pos[Sc] + 1, r ) );

    sort( all(V) );

    for (int i = 0; i < sz(V); i++)
    {
        vec[ mp[V[i].fr][V[i].sc] ].pb( mp[res][Sc] );

        if (i > 0)
            vec[ mp[V[i].fr][V[i].sc] ].pb( mp[V[i-1].fr][V[i-1].sc] );
    }
    Vec.pb( mk(res, Sc) );
    return Vec.back();
}
void dfs (int v)
{
    if (u[v] == 2)
        return;
    if (u[v] == 1)
        assert(0);

    u[v] = 1;
    for(int j = 0; j < sz(vec[v]); j++)
        dfs( vec[v][j] );
    u[v] = 2;
    ans[++sz] = Pr[v].fr;
    ans[++sz] = Pr[v].sc;
}
main ()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
        scanf("%d", &ar[i]), pos[ ar[i] ] = i;

    build (1, 1, n);

    Compute (1, n);

    sort( all(Vec) );

    for (int i = 0; i < sz(Vec); i++)
    {
        if (Vec[i].fr == inf) break;
        dfs( mp[Vec[i].fr][Vec[i].sc] );
    }
    for (int i = 1; i <= n; i++)
    {
        assert(ans[i] > 0);
        printf("%d ", ans[i]);
    }
}
