inline int keisan(int A, int B) {
	pair<int, int> p1, p2;
	if (A & 1) {
		p1 = query2(A / 2, B / 2);
		p2 = query1(p1.second / 2 + 1, B / 2 + 1);
	}
	else {
		p1 = query1(A / 2, B / 2 + 1);
		p2 = query2(p1.second / 2, B / 2 + 1);
	}
	*(a + p1.first) = p2.first;
	*(b + p1.first) = A;
	*(c + p1.first) = p1.second;
	*(d + p1.first) = p2.second;
	*(e + p1.first) = B;
	return p1.first;
}

