const int N=2e5+5;
int n,a[N],pos[2][N<<2];
int MN(int x,int y){
	return a[x]<a[y]?x:y;
}
void buildtree(int k,int l,int r){
	if(l==r){
		pos[l&1][k]=l;return;
	}
	int mid=l+r>>1;
	buildtree(k<<1,l,mid);buildtree(k<<1|1,mid+1,r);
	pos[0][k]=MN(pos[0][k<<1],pos[0][k<<1|1]);
	pos[1][k]=MN(pos[1][k<<1],pos[1][k<<1|1]);
}
int find(int k,int l,int r,int L,int R,int d){
	if(l>=L&&r<=R) return pos[d][k];
	int mid=l+r>>1;
	if(R<=mid) return find(k<<1,l,mid,L,R,d);
	if(L>mid) return find(k<<1|1,mid+1,r,L,R,d);
	return MN(find(k<<1,l,mid,L,R,d),find(k<<1|1,mid+1,r,L,R,d));
}
struct info{
	int l,r,pos;
	info(int _l,int _r){
		l=_l;r=_r;
		pos=l>r?0:find(1,1,n,l,r,l&1);
	}
	bool operator <(const info &rhs)const{
		return a[pos]<a[rhs.pos];
	}
};
set<info> s;
