void eval(int k){
    cnt[k]+=lazy[k];
    if (k*2+1<lazy.size()) {
        lazy[k*2]+=lazy[k];
        lazy[k*2+1]+=lazy[k];
    }
    lazy[k]=0;
    if ((cnt[k]&1)^(seg[k].first&1)) {
        swap(seg[k].second.first,seg[k].second.second);
        seg[k].first=cnt[k];
        while (k) {
            seg[(k>>1)].second.first=min(seg[k].second.first,seg[k^1].second.first);
            seg[(k>>1)].second.second=min(seg[k].second.second,seg[k^1].second.second);
            k>>=1;
        }
    }
}
void update(int x,int y, int k, int l, int r){
    eval(k);
    if (x<=l&&r<=y) {
        lazy[k]++;
        eval(k);
        return;
    }
    if (x<r&&l<y) {
        update(x, y, k*2, l, (l+r)>>1);
        update(x, y, k*2+1, (l+r)>>1, r);
    }
}
void update(int x,int y){
    update(x,y,1,0,si);
}
P query(int x,int y, int k, int l, int r,int v){
    eval(k);
    if (x<=l&&r<=y) {
        if (v) {
            return seg[k].second.first;
        }else{
            return seg[k].second.second;
        }
    }
    else if (x<r&&l<y) {
        return min(query(x, y, k*2, l, (l+r)>>1, v),query(x, y, k*2+1, (l+r)>>1, r, v));
    }else{
        return {inf,-1};
    }
}
