using namespace std;
class SparseTable {
private:
	vector<int> ipw;
	vector<int> val;
	vector<vector<int> > arr;
public:
	SparseTable() : ipw(vector<int>()), val(vector<int>()), arr(vector<vector<int> >()) {};
	SparseTable(vector<int> v) {
		ipw = vector<int>(v.size() + 1);
		int cur = 0;
		for (int i = 1; i <= v.size(); i++) {
			if (2 << cur < i) cur++;
			ipw[i] = cur;
		}
		val = v;
		arr = vector<vector<int> >(ipw[v.size()] + 1);
		arr[0] = vector<int>(val.size());
		for (int i = 0; i < val.size(); i++) arr[0][i] = i;
		for (int i = 1; i < ipw[v.size()] + 1; i++) {
			arr[i] = vector<int>(val.size() - (1 << i) + 1);
			for (int j = 0; j < arr[i].size(); j++) {
				arr[i][j] = (val[arr[i - 1][j]] < val[arr[i - 1][j + (1 << (i - 1))]] ? arr[i - 1][j] : arr[i - 1][j + (1 << (i - 1))]);
			}
		}
	}
	int min_index(int l, int r) {
		int lc = arr[ipw[r - l]][l];
		int rc = arr[ipw[r - l]][r - (1 << ipw[r - l])];
		return val[lc] < val[rc] ? lc : rc;
	}
	int min_query(int l, int r) {
		return val[min_index(l, r)];
	}
};
int n, p[200009]; map<pair<int, int>, pair<int, int> > d; SparseTable v0, v1;
struct state {
	int l, r;
};
bool operator<(const state& s1, const state& s2) {
	pair<int, int> spl1 = d[make_pair(s1.l, s1.r)];
	pair<int, int> spl2 = d[make_pair(s2.l, s2.r)];
	return p[spl1.first] > p[spl2.first];
}
void solve(int l, int r) {
	if (l == r) return;
	int divl = (l % 2 == 0 ? v0.min_index(l / 2, r / 2) * 2 : v1.min_index(l / 2, r / 2) * 2 + 1);
	int divr = (l % 2 == 0 ? v1.min_index(divl / 2, r / 2) * 2 + 1 : v0.min_index(divl / 2 + 1, r / 2 + 1) * 2);
	d[make_pair(l, r)] = make_pair(divl, divr);
	solve(l, divl);
	solve(divl + 1, divr);
	solve(divr + 1, r);
}
int main() {
	cin >> n;
	vector<int> ve0, ve1;
	for (int i = 0; i < n; i++) {
		cin >> p[i];
		if (i % 2 == 0) ve0.push_back(p[i]);
		else ve1.push_back(p[i]);
	}
	v0 = SparseTable(ve0);
	v1 = SparseTable(ve1);
	solve(0, n);
	priority_queue<state> que; que.push(state{ 0, n });
	for (int i = 0; i < n / 2; i++) {
		state u = que.top(); que.pop();
		pair<int, int> spl = d[make_pair(u.l, u.r)];
		cout << p[spl.first] << ' ' << p[spl.second] << ' ';
		if (u.l != spl.first) que.push(state{ u.l, spl.first });
		if (spl.first + 1 != spl.second) que.push(state{ spl.first + 1, spl.second });
		if (spl.second + 1 != u.r) que.push(state{ spl.second + 1, u.r });
	}
	return 0;
}

