struct segtree {
	pair<int, int> rmq[N * 4 + 100];
	int wh[N];
	vector<int> v;
	int n;

	segtree(vector<int> v) : v(v) {
		n = len(v);
		make_rmq(1, 0, n - 1);
	}

	segtree(){}

	void make_rmq(int i, int l, int r) {
		if (l == r) {
			wh[l] = i;
			return void (rmq[i] = mp(v[l], l));
		}
		make_rmq(i * 2, l, (l + r) / 2);
		make_rmq(i * 2 + 1, (l + r) / 2 + 1, r);
		rmq[i] = min(rmq[i * 2], rmq[i * 2 + 1]);
	}

	pair<int, int> getValue(int i, int ll, int rr, int l, int r) {
		if (ll > r || rr < l) {
			return mp(inf, inf);
		}
		if (l <= ll && rr <= r) {
			return rmq[i];
		}
		return min(getValue(i * 2, ll, (ll + rr) / 2, l, r),
			getValue(i * 2 + 1, (ll + rr) / 2 + 1, rr, l, r));
	}

	void update(int i, pair<int, int> v) {
		i = wh[i];
		rmq[i] = v;
		for (i >>= 1; i; i >>= 1) {
			rmq[i] = min(rmq[i * 2], rmq[i * 2 + 1]);
		}
	}
};

