int merge (int a, int b) {
	return min(a, b);
}

int queryHelp(int loQuery, int hiQuery, int index, int loRange, int hiRange, int tree[]) {
	if (hiQuery < loRange || loQuery > hiRange)
		return inf;

	if (loQuery == loRange && hiQuery == hiRange)
		return tree[index];

	int mid = (loRange + hiRange) / 2;

	return merge(queryHelp(max(mid + 1, loQuery), hiQuery, index * 2 + 1, mid + 1, hiRange, tree),
	 queryHelp(loQuery, min(mid, hiQuery), index * 2, loRange, mid, tree));
}

int query(int a, int b, int tree[]) {
	return queryHelp(a, b, 1, 0, n - 1, tree);
}

void updateHelp(int position, int value, int index, int loRange, int hiRange, int tree[]) {
	if (position < loRange || position > hiRange)
		return ;

	if (position == loRange && loRange == hiRange) {
		tree[index] += value;
		return;
	}

	int mid = (loRange + hiRange) / 2;
	updateHelp(position, value, index * 2, loRange, mid, tree);
	updateHelp(position, value, index * 2 + 1, mid + 1, hiRange, tree);
	tree[index] = merge(tree[index * 2], tree[index * 2 + 1]);
}

void update(int position, int value, int tree[]) {
	updateHelp(position, value, 1, 0, n - 1, tree);
}

