typedef array<int, 3> arr;
void solve() {
	int N; cin >> N;
	auto f = [](P a, P b) {return min(a,b); };
	SegmentTree<P>even(N, { 1e9,1e9 }, f), odd(N, { 1e9,1e9 }, f);
	vector<int>v(N);
	REP(i, N) {
		cin >> v[i];
		if (i & 1) {
			odd.update(i, { v[i],i });
		}
		else {
			even.update(i, { v[i],i });
		}
	}
	priority_queue < array<int, 3>, vector < array<int, 3>>,greater<array<int, 3>>>que;
	que.push({ 1,0,N });
	vector<int>ans;
	while (!que.empty()) {
		arr ar = que.top(); que.pop();
		int l = ar[1], r = ar[2];
		if (l + 1 >= r)continue;
		int k1 = l, k2 = r - 1;
		if (l % 2 == 0) {
			P fi = even.query(l, r);
			k1 = fi.second;
			P se = odd.query(k1, r);
			k2 = se.second;
			ans.push_back(fi.first); ans.push_back(se.first);
		}
		else {
			P fi = odd.query(l, r);
			k1 = fi.second;
			P se = even.query(k1, r);
			k2 = se.second;
			ans.push_back(fi.first); ans.push_back(se.first);
		}
		if (k1 > l + 1) {
			int nxt = 1e9;
			if (l % 2 == 0)nxt = even.query(l, k1).first;
			else nxt = odd.query(l, k1).first;
			que.push({ nxt,l,k1 });
		}
		if (k2 > k1 + 1 + 1) {
			int nxt = 1e9;
			if ((k1 + 1) % 2 == 0)nxt = even.query(k1 + 1, k2).first;
			else nxt = odd.query(k1 + 1, k2).first;
			que.push({ nxt,k1 + 1,k2 });
		}
		if (r > k2 + 1 + 1) {
			int nxt = 1e9;
			if ((k2 + 1) % 2 == 0)nxt = even.query(k2 + 1, r).first;
			else nxt = odd.query(k2 + 1, r).first;
			que.push({ nxt,k2 + 1,r });
		}
	}
	print_space(ans);
}

