vector<int> A;
vector<int> ans;
vector<int> Aindex;//Aの値からインデックスをえる。
segment_base<int> seg0,seg1;//偶数、奇数0-index

vector<int> f(int L,int R){//[L,R)
	int res1,res2;
	int res1_Index,res2_Index;
	if( L&1 ){//奇数番目から始まる場合
		res1 = seg1.query(L/2,R/2);
		res1_Index = Aindex[res1];
		seg1.update(res1_Index/2,INF);

		res2 = seg0.query(res1_Index/2 + 1,R/2 + 1);
		res2_Index = Aindex[res2];
		seg0.update(res2_Index/2,INF);
	}else{
		res1 = seg0.query(L/2,R/2);
		res1_Index = Aindex[res1];
		seg0.update(res1_Index/2,INF);

		res2 = seg1.query(res1_Index/2,R/2);
		res2_Index = Aindex[res2];
		seg1.update(res2_Index/2,INF);
	}



	vector< vector<int> > B(3);
	int spL,spR;//分割地点
	spL = res1_Index;
	spR = res2_Index;
	if( L < spL ){
		B[0] = f(L,spL);
	}
	if( spL+1 < spR ){
		B[1] = f(spL+1,spR);
	}
	if( spR+1 < R ){
		B[2] = f(spR+1,R);
	}

	vector<int> ans(R-L);
	int posAns = 0;
	ans[0] = res1;
	ans[1] = res2;
	posAns = 2;
	vector<int> pos(3,0);
	vector<int> size(3,0);
	for(int i=0;i<3;++i){
		size[i] = B[i].size();
	}
	while(pos[0]<size[0] || pos[1]<size[1] || pos[2]<size[2]){
		int res = INF;
		int num = 0;
		for(int i=0;i<3;++i){
			if( pos[i] < size[i] ){
				int temp = B[i][ pos[i] ];
				if( temp < res ){
					res = temp;
					num = i;
				}
			}
		}
		ans[posAns] = B[num][ pos[num] ];
		++pos[num];
		++posAns;
		ans[posAns] = B[num][ pos[num] ];
		++pos[num];
		++posAns;
	}

	return ans;
}
void solve(){
	int N;
	cin >> N;
	A.resize(N);
	Aindex.resize(N+1);
	seg0.init(N/2,INF);
	seg1.init(N/2,INF);

	for(int i=0;i<N;++i){
		cin >> A[i];
		Aindex[ A[i] ] = i;
		if( i & 1 ){
			seg1.update(i/2,A[i]);
		}else{
			seg0.update(i/2,A[i]);
		}
	}

	vector<int> ans = f(0,N);
	for(int i=0;i<N;++i){
		if(i)cout << " ";
		cout << ans[i];
	}
	cout << endl;
}

