class T{
public:
  int a;
  int b;
  int c;
  int d;

  T(int aa, int bb, int cc, int dd):a(aa), b(bb), c(cc), d(dd){}

};

bool comp(T p, T q){
  if(p.a <= q.a && p.b >= q.b)  return false;
  else if(p.a >= q.a && p.b <= q.b) return true;
  else{
    if(p.c < q.c) return false;
    else return true;
  }
}

priority_queue<T, vector<T>, decltype(&comp)> pq(&comp);

void init(int n_, int* da){
  n = 1;
  while(n < n_) n *= 2;

  for(int i = 0; i < n; i++){
    da[i] = MA;
  }
}

//k番目をaに変更
void update(int k, int a, int* dat){
  k += n-1;
  dat[k] = a;
  while(k > 0){
    k = (k-1)/2;
    dat[k] = min(dat[k*2+1], dat[k*2+2]);
  }
}

int query(int a, int b, int k, int l, int r, int* dat){
  if(r <= a || b <= l) {
    //cout << 40 << endl;
    return MA;
  }
  if(a <= l && r <= b){
    //cout << 43 << " " << dat[k] << endl;
    return dat[k];
  }
  else{
    int vl = query(a, b, k*2+1, l, (l+r)/2, dat);
    int vr = query(a, b, k*2+2, (l+r)/2, r, dat);
    //cout << "vl vr" << vl << " " << vr << endl;
    return min(vl, vr);
  }
}

void deal(int i, int s, int e){
  if(e <= s)  return ;

  //cout << 58 << endl;
  //cout << s/2 << " " << e/2 << endl;
  int m1 = query(s/2, e/2, 0, 0, n, dat[i]);
  if(m1 == MA)  return;
  //cout << 53 << endl; //cout << m1 << endl;
  int m2 = query((q[m1]+i)/2, (e+i)/2, 0, 0, n, dat[1-i]);
  if(m2 == MA)  return;
  //cout << 54 << " " << m2 << endl;
  pq.push(T(s, e, m1, m2));
  //cout << 66 << endl;
  //cout << q[m1] << " " << q[m2] << endl;
  deal(i, s, q[m1]);
  deal(1-i, q[m1]+1, q[m2]);
  deal(i, q[m2]+1, e);
}

