#define MAX_N 200001
#define INF 0x3FFFFFFF

using namespace std;

struct interval {
  int l, r;
  int val;
};

bool operator<(const interval &a, const interval &b) {
  return a.val > b.val;
}

int a[MAX_N], idx[MAX_N], even[4 * MAX_N], odd[4 * MAX_N];

void initEven(int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (X == Y) { even[k] = X & 1 ? INF : a[X]; return; }
  int M = (X + Y) / 2;
  initEven(2 * k + 1, X, M);
  initEven(2 * k + 2, M + 1, Y);
  even[k] = min(even[2 * k + 1], even[2 * k + 2]);
}

void initOdd(int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (X == Y) { odd[k] = X & 1 ? a[X] : INF; return; }
  int M = (X + Y) / 2;
  initOdd(2 * k + 1, X, M);
  initOdd(2 * k + 2, M + 1, Y);
  odd[k] = min(odd[2 * k + 1], odd[2 * k + 2]);
}

int query(int *tree, int x, int y, int k = 0, int X = 0, int Y = MAX_N - 1) {
  if (x <= X && Y <= y) return tree[k];
  if (y < X || Y < x) return INF;
  int M = (X + Y) / 2;
  return min(query(tree, x, y, 2*k+1, X, M), query(tree, x, y, 2*k+2, M+1, Y));
}

