int at[100010];

struct P{
	int ppL,ppR;
  int left,right,flip;
  bool operator< (const P &P1)const{
    return ppL<P1.ppL;
  };
  bool operator> (const P &P1)const{
    return ppL>P1.ppL;
  };
};
priority_queue<P,vector<P>,greater<P> >Q;
void Qpush(int left,int right,int flip){
	if(left>right)return;
  P tmp;tmp.ppL=p[left],tmp.ppR=p[right];
  tmp.left=left,tmp.right=right,tmp.flip=flip;
  Q.push(tmp);
}
pair<int,int> Div(P now){
	int valL=rmq(now.left,now.right,now.flip);
  int placeL=at[valL];
  int valR=rmq(placeL,now.right,1-now.flip);
  int placeR=at[valR];

  Qpush(now.left,placeL-1,now.flip);
  Qpush(placeL+1,placeR-1,1-now.flip);
  Qpush(placeR+1,now.right,now.flip);
  return make_pair(valL,valR);
}

int main(){
