  cin>>n;
  lol(i,n){
    cin>>p[i];
    at[p[i]]=i;
    Update(i,p[i],i%2);
  }
  P now;now.left=0,now.right=n-1,now.flip=0;
  pair<int,int> x=Div(now);
  cout<<x.first<<" "<<x.second;
  while(!Q.empty()){
    now=Q.top();Q.pop();
    cout<<" "<<now.ppL<<" "<<now.ppR;
    Div(now);
	}
  cout<<endl;
  return 0;
}

