template<class InputIt1, class InputIt2, class OutputIt>
OutputIt merged(InputIt1 first1, InputIt1 last1,
    InputIt2 first2, InputIt2 last2,
    OutputIt d_first)
{
    for (; first1 != last1; ++d_first) {
        if (first2 == last2) {
            return std::copy(first1, last1, d_first);
        }
        if (*first2 < *first1) {
            *d_first = *first2;
            ++first2;
        }
        else {
            *d_first = *first1;
            ++first1;
        }
    }
    return std::copy(first2, last2, d_first);
}

vector<ll> ans;

void sol() {
    set<tuple<ll, ll, ll>> qu;
    qu.insert({ 0, 0, n });
    while (!qu.empty()) {
        tuple<ll, ll, ll> cur = (*qu.begin());
        qu.erase(qu.begin());
        ll l = get<1>(cur), r = get<2>(cur);

        if (l == r - 2) {
            ans.push_back(perm[l]);
            ans.push_back(perm[l + 1]);
            continue;
        }
        else {
            pair<ll, ll> mn = get(0, 0, n, l, r);
            if (l % 2 != 0) swap(mn.first, mn.second);

            pair<ll, ll> q2;
            ll vl1 = pos[mn.first], vl2;
            q2 = get(0, 0, n, vl1, r);
            if (l % 2 != 0) swap(q2.first, q2.second);
            vl2 = pos[q2.second];

            mn.second = q2.second;
            ans.push_back(mn.first + 1);
            ans.push_back(mn.second + 1);

            if (vl1 != l) {
                pair<ll, ll> q = get(0, 0, n, l, vl1);
                if (l % 2 != 0) swap(q.first, q.second);
                qu.insert({ q.first, l, vl1 });
            }
            if (vl1 + 1 != vl2) {
                pair<ll, ll> q2 = get(0, 0, n, vl1 + 1, vl2);
                if ((vl1 + 1) % 2 != 0) swap(q2.first, q2.second);
                qu.insert({ q2.first, vl1 + 1, vl2 });
            }
            if (vl2 != r - 1) {
                pair<ll, ll> q = get(0, 0, n, vl2 + 1, r);
                if ((vl2 + 1) % 2 != 0) swap(q.first, q.second);
                qu.insert({ q.first, vl2 + 1, r });
            }
        }
    }
}

