#define DEBUG 0
#define dout if(DEBUG) cout

const int MAXN = 2e5 + 5;
const int INF = 1e9;

int a[MAXN];

vi rec_sol(int l, int r){
    if(l > r){
        vi ans;
        return ans;
    }
    if(l + 1 == r){
        vi ans;
        ans.pb(a[l]);
        ans.pb(a[r]);
        return ans;
    }
    if(l + 3 == r){
        pii p1 = mp(a[l], a[l + 1]);
        pii p2 = mp(a[l + 2], a[r]);
        pii p3 = mp(a[l], a[r]);
        pii mn = min(p1, min(p2, p3));
        vi ans;
        if(mn == p1){
            ans.pb(a[l]);
            ans.pb(a[l + 1]);
            ans.pb(a[l + 2]);
            ans.pb(a[l + 3]);
        }
        else if(mn == p2){
            ans.pb(a[l + 2]);
            ans.pb(a[l + 3]);
            ans.pb(a[l]);
            ans.pb(a[l + 1]);
        }
        else{
            ans.pb(a[l]);
            ans.pb(a[r]);
            ans.pb(a[l + 1]);
            ans.pb(a[l + 2]);
        }
        return ans;
    }
    int mn_id = l;
    for(int i = l; i <= r; i++){
        if(a[i] < a[mn_id]){
            mn_id = i;
        }
    }
    int mn_id2 = mn_id + 3;
    for(int i = mn_id + 3; i <= r; i += 2){
        if(a[mn_id2] > a[i]){
            mn_id2 = i;
        }
    }
    if(mn_id2 > r){
        mn_id2 = mn_id - 3;
        for(int i = mn_id - 3; i >= l; i -= 2){
            if(a[mn_id2] > a[i]){
                mn_id2 = i;
            }
        }
    }

    int l2 = min(mn_id, mn_id2);
    int r2 = max(mn_id, mn_id2);
    vi ans;
    ans.pb(a[l2]);
    ans.pb(a[r2]);

    vi ans2 = rec_sol(l, l2 - 1);
    vi ans3 = rec_sol(l2 + 1, r2 - 1);
    vi ans4 = rec_sol(r2 + 1, r);
    int sz2 = ans2.size();
    int sz3 = ans3.size();
    int sz4 = ans4.size();
    int c2 = 0, c3 = 0, c4 = 0;
    while(c2 < sz2 || c3 < sz3 || c4 < sz4){
        pii p2 = c2 < sz2 ? mp(ans2[c2], ans2[c2 + 1]) : mp(INF, INF);
        pii p3 = c3 < sz3 ? mp(ans3[c3], ans3[c3 + 1]) : mp(INF, INF);
        pii p4 = c4 < sz4 ? mp(ans4[c4], ans4[c4 + 1]) : mp(INF, INF);
        pii mn = min(p2, min(p3, p4));
        if(mn == p2){
            c2 += 2;
        }
        else if(mn == p3){
            c3 += 2;
        }
        else{
            c4 += 2;
        }
        ans.pb(mn.first);
        ans.pb(mn.second);
    }
    return ans;
}

void solve(){
    int n;
    cin >> n;
    for(int i = 1; i <= n; i++) scanf("%d", &a[i]);
    vi ans = rec_sol(1, n);
    for(int i = 0; i < n; i++) printf("%d ", ans[i]);
}

