using namespace std;

const int MAX_N = 200005;

int N, P[MAX_N], mn[MAX_N * 4][2];

int _min(int x, int y) {
  return P[x] < P[y] ? x : y;
}

void build(int x, int l, int r) {
  if (l == r) {
    mn[x][l & 1] = l;
    return;
  }
  int mid = (l + r) >> 1;
  build(x << 1, l, mid), build(x << 1 | 1, mid + 1, r);
  mn[x][0] = _min(mn[x << 1][0], mn[x << 1 | 1][0]);
  mn[x][1] = _min(mn[x << 1][1], mn[x << 1 | 1][1]);
}

int query(int x, int L, int R, int l, int r, int op) {
  if (l <= L && R <= r)
    return mn[x][op];
  int mid = (L + R) >> 1, mn = 0;
  if (mid >= l) mn = query(x << 1, L, mid, l, r, op);
  if (mid < r) mn = _min(mn, query(x << 1 | 1, mid + 1, R, l, r, op));
  return mn;
}

class Data {
public:
  int l, r, k1, k2;
  inline friend bool operator < (const Data &a, const Data &b) {
    return P[a.k1] > P[b.k1];
  }
  Data() { }
  Data(int L, int R) {
    l = L, r = R;
    k1 = query(1, 1, N, l, r, l & 1);
    k2 = query(1, 1, N, k1, r, (l & 1) ^ 1);
  }
} ;

priority_queue<Data> Q;

