int main()
{
    auto cmp = [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first + a.second < b.first + b.second;
    };
    priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(cmp)> max_heap(cmp);

    cin >> N;
    vector<int> right(N+1, -N);
    vector<int> left(N+1, -N);

    // int p_i
    for (int i = 0; i < N; ++i) {
        cin >> p[i];
    }

    for (int i = 0; i < N-1; ++i) {
        right[p[i]] = p[i+1];
        left[p[i+1]] = p[i];
        max_heap.emplace(p[i], p[i+1]);
    }

    vector<int> used(N+1, false);
    vector<int> ans(N);
    int NN = N/2;
    for (int i = 0; i < NN; ++i) {
        int a, b;
        do {
            auto& top = max_heap.top();
            a = top.first;
            b = top.second;
            max_heap.pop();
        } while (used[a] || used[b]);

        used[a] = true;
        used[b] = true;
        int idx = (NN-i-1)*2;
        ans[idx] = a;
        ans[idx+1] = b;
        int a_left = left[a];
        int b_right = right[b];
        right[a_left] = b_right;
        left[b_right] = a_left;
        max_heap.emplace(a_left, b_right);
    }

    cout << ans[0];
    for (int i = 1; i < N; ++i) {
        cout << ' ' << ans[i];
    }
