using namespace std;

int N;
vector<int> p;

vector<int> solve(int start, int end) {
    vector<int> retval;

    if (start >= end)
        return retval;

    //Step1.先頭に来るものを選ぶ
    int min_value = N + 1, min_index = 0, min_index2 = 0;
    for (int i = start; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index = i;
        }
    }
    retval.push_back(min_value);

    //Step2.2番目に来るものを選ぶ
    min_value = N + 1;
    for (int i = min_index + 1; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index2 = i;
        }
    }
    retval.push_back(min_value);

    //残ったところを再帰的に行う
    vector<int> forward = solve(start, min_index);
    vector<int> mid     = solve(min_index + 1, min_index2);
    vector<int> back    = solve(min_index2 + 1, end);

    vector<pair<int, int> > pairs;
    for (int i = 0; i < forward.size(); i += 2) {
        pairs.push_back(make_pair(forward[i], forward[i + 1]));
    }
    for (int i = 0; i < mid.size(); i+= 2) {
        pairs.push_back(make_pair(mid[i], mid[i + 1]));
    }
    for (int i = 0; i < back.size(); i += 2) {
        pairs.push_back(make_pair(back[i], back[i + 1]));
    }

    sort(pairs.begin(), pairs.end());

    for (auto p : pairs) {
        retval.push_back(p.first);
        retval.push_back(p.second);
    }

    return retval;
}

int main()
{
    cin >> N;
    p.resize(N);
    REP(i, N) cin >> p[i];

    vector<int> q = solve(0, N);

    REP (i, N)
        printf("%d ", q[i]);
    printf("\n");
}

