    int rt=solve();
    priority_queue<D> q;
    q.push(D{pp[rt],rt});
    vi ans;
    while(!q.empty())
    {
        auto u=q.top();q.pop();
        ans.push_back(u.d.first);
        ans.push_back(u.d.second);
        for(auto v:G[u.id])
        {
            if(v)
                q.push(D{pp[v],v});
        }
    }
    print(ans);
}

