	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%d", &p[i]);
	}
	p[n] = n + 1;
	build(1, 0, n);
	solve(0, n);
	sort(ans.begin(), ans.end(), cmp);
	for (auto &i : ans) {
		cout << i.first << " " << i.second << " ";
	}
	return 0;
}

