PP segA[1 << 18];
PP segB[1 << 18];

void segupdate(PP* seg, int i, int val, int p) {
	seg[i] = make_pair(val, p);
	while (i > 1) {
		i /= 2;
		seg[i] = min(seg[i * 2], seg[i * 2 + 1]);
	}
}

void segcreate(PP* seg, int* dat) {
	fill(seg, seg + (1 << 18), make_pair(INF, -1));
	REP(i, 0, N / 2) {
		segupdate(seg, i + (1 << 17), dat[i], i);
	}
}

PP segminrec(PP* seg, int a, int b, int i, int l, int r) {
	if (r <= a || b <= l) return make_pair(INF, -1);
	if (a <= l && r <= b) return seg[i];

	return min(
		segminrec(seg, a, b, i * 2, l, (l + r) / 2),
		segminrec(seg, a, b, i * 2 + 1, (l + r) / 2, r));
}
PP segmin(PP* seg, int a, int b) {
	return segminrec(seg, a, b, 1, 0, 1 << 17);
}



void input() {
	cin >> N;
	REP(i, 0, N / 2) {
		cin >> A[i];
		cin >> B[i];
	}
	return;
}

void solverec(bool rev,int st, int n) {
	if (n == 0) {
	} else if (n == 1) {
		if (!rev) {
			Q.push_back(make_pair(A[st], B[st]));
		} else {
			Q.push_back(make_pair(B[st], A[st + 1]));
		}
	} else {
		if (!rev) {
			auto ml = segmin(segA, st, st + n);
			auto mr = segmin(segB, st, st + n);
			Q.push_back(make_pair(ml.first, mr.first));

			solverec(rev, st, ml.second - st);
			solverec(!rev, ml.second, mr.second - ml.second);
			solverec(rev, mr.second + 1, st - mr.second + n - 1);
		} else {
			auto ml = segmin(segB, st, st + n);
			auto mr = segmin(segA, st + 1, st + 1 + n);
			Q.push_back(make_pair(ml.first, mr.first));

			solverec(rev, st, ml.second - st);
			solverec(!rev, ml.second + 1, mr.second - ml.second - 1);
			solverec(rev, mr.second, st - mr.second + n);
		}
		sort(Q.end() - n + 1, Q.end());
	}
}

void solve() {
	REP(i, 0, N / 2) {
		Asort[i] = make_pair(A[i], i);
	}
	sort(Asort, Asort + N / 2);

	segcreate(segA, A);
	segcreate(segB, B);

	solverec(false, 0, N / 2);
	return;
}

void output() {
	REP(i, 0, N / 2) {
		cout << Q[i].first << ' ' << Q[i].second << (i == N / 2 - 1 ? '\n' : ' ');
	}
	return;
}


int main() {
	input();
	solve();
	output();
	return 0;
}

