void B0(node* &u = root0, int l = 1, int r = n)
{
	u = new node;
	if(l == r)
	{
		u->num = (l % 2 == 0) ? a[l] : iinf;
		return;
	}
	int mid = l + r >> 1;
	B0(u->ch[0], l, mid);
	B0(u->ch[1], mid + 1, r);
	return u->pull();
}

void Q0(node* &u = root0, int l = 1, int r = n)
{
	if(seg_a <= l && r <= seg_b)
	{
		chkmin(seg_q, u->num);
		return;
	}
	int mid = l + r >> 1;
	if(seg_a <= mid) Q0(u->ch[0], l, mid);
	if(seg_b > mid) Q0(u->ch[1], mid + 1, r);
	return;
}

int Q0(int l, int r)
{
	seg_a = l;
	seg_b = r;
	seg_q = iinf;
	if(l <= r) Q0();
	return seg_q;
}

void M0(node* &u = root0, int l = 1, int r  = n)
{
	if(l == r)
	{
		u->num = seg_q;
		return;
	}
	int mid = l + r >> 1;
	if(seg_a <= mid) M0(u->ch[0], l, mid);
	else M0(u->ch[1], mid + 1, r);
	return u->pull();
}

void B1(node* &u = root1, int l = 1, int r = n)
{
	u = new node;
	if(l == r)
	{
		u->num = (l % 2 == 1) ? a[l] : iinf;
		return;
	}
	int mid = l + r >> 1;
	B1(u->ch[0], l, mid);
	B1(u->ch[1], mid + 1, r);
