int match[maxn];

void dq(int l, int r)
{
	debug("dq(%d, %d)\n", l, r);
	if(l > r) return;
	int v0, v1, p0, p1;
	if(l % 2 == 0)
	{
		v0 = Q0(l, r);
		p0 = M[v0];
		v1 = Q1(p0 + 1, r);
		p1 = M[v1];
	}
	else
	{
		v1 = Q1(l, r);
		p1 = M[v1];
		v0 = Q0(p1 + 1, r);
		p0 = M[v0];
	}
	int i = min(p0, p1), j = max(p0, p1);
	match[i] = j;
	return dq(l, i - 1), dq(i + 1, j - 1), dq(j + 1, r);
}

