const int MN = 2e5+5;
const int MOD = 1e9+7;
const int INF = 1e9;

int N,A[MN];
pii P[MN<<2];

pii cal(pii X, pii Y)
{
	pii P;
	P.va = A[X.va]<A[Y.va] ? X.va : Y.va;
	P.vb = A[X.vb]<A[Y.vb] ? X.vb : Y.vb;
	return P;
}

void init(int s, int e, int i)
{
	if(s==e){
		if(s%2) P[i].va = s;
		else P[i].vb = s;
		return;
	}
	int m = (s+e)/2;
	init(s,m,i<<1);
	init(m+1,e,i<<1|1);
	P[i] = cal(P[i<<1],P[i<<1|1]);
}

pii get(int s, int e, int x, int y, int i)
{
	if(e<x||y<s) return pii(0,0);
	if(x<=s&&e<=y) return P[i];
	int m = (s+e)/2;
	return cal(get(s,m,x,y,i<<1),get(m+1,e,x,y,i<<1|1));
}


vector<int> solve(int s, int e)
{
	vector<int> res,V[3];
	if(s>e) return res;

	int l,r;
	if(s%2){
		l = get(1,N,s,e-1,1).va;
		r = get(1,N,l+1,e,1).vb;
	}
	else{
		l = get(1,N,s,e-1,1).vb;
		r = get(1,N,l+1,e,1).va;	
	}
	res.push_back(A[l]);
	res.push_back(A[r]);
	V[0] = solve(s,l-1);
	V[1] = solve(l+1,r-1);
	V[2] = solve(r+1,e);

	V[0].push_back(MN);
	V[1].push_back(MN);
	V[2].push_back(MN);
	int x[3] = {0};
	for(int i=0; i<(e-s-1)/2; i++){
		int r = 0;
		for(int k=0; k<3; k++)
			if(V[k][x[k]]<V[r][x[r]]) r = k;
		res.push_back(V[r][x[r]]);
		res.push_back(V[r][x[r]+1]);
		x[r]+=2;
	}
	return res;
}

