    A[0] = MN;
    for(int i=1; i<=N; i++){
    	cin >> A[i];
    }
    init(1,N,1);
    vector<int> V = solve(1,N);
    for(int x:V) cout << x << ' ';
}

#include<bits/stdc++.h>
