	for(int i = 0; i < n; i ++) {
		cin >> p[i];
		a[i % 2][i / 2] = p[i];
		pos[p[i]] = i;
	}
	R[0].build(a[0], n / 2);
	R[1].build(a[1], n / 2);
	vector<pair<int, int> > ret = calc(0, n - 1);
	for(int i = ret.size() - 1; i >= 0; i --){
		cout << ret[i].first << ' ' << ret[i].second << " \n"[i == 0];
	}
}

