	for(int i = 0; i < n; ++i){
		int a;
		scanf("%d", &a);
		p[i] = a;
		(i & 1 ? podd : peven)[i] = a;
		inv[a] = i;
	}

	rmqodd.init(ALL(podd));
	rmqeven.init(ALL(peven));

	add(0, n - 1);

	vector<int> ans;
	while(!pq.empty()){
		int elem1, elem2, lt, rt;
		tie(elem1, elem2, lt, rt) = pq.top();
