		elem1 = -elem1;
		elem2 = -elem2;
		ans.push_back(elem1);
		ans.push_back(elem2);

		int idx1 = inv[elem1];
		int idx2 = inv[elem2];
		add(lt, idx1 - 1);
		add(idx1 + 1, idx2 - 1);
		add(idx2 + 1, rt);
	}

	const char *spl = "";
