void build(int node,int start,int end,int mode)
{
	if(start==end)
	{
		tree[mode][node]=start;
		return;
	}
	build(2*node,start,(start+end)/2,mode);
	build(2*node+1,(start+end)/2+1,end,mode);
	if(arr[2*tree[mode][2*node]-mode]<=arr[2*tree[mode][2*node+1]-mode])
		tree[mode][node]=tree[mode][2*node];
	else
		tree[mode][node]=tree[mode][2*node+1];
}

