{
	if(l>end||r<start)
		return (n/2)+1;
	if(l<=start&&end<=r)
		return tree[mode][node];
	int lef=query(2*node,start,(start+end)/2,l,r,mode);
	int righ=query(2*node+1,(start+end)/2+1,end,l,r,mode);
	if(arr[2*lef-mode]<=arr[2*righ-mode])
		return lef;
	else
		return righ;
}
