bool cmp(pii x, pii y) {
    if (x.first != y.first) return x.first < y.first;
    return x.second < y.second;
}
void make_st( int num[], int dp[MAXN][24]) {
    int n = N / 2;
    for (int i = 0; i < n; i++) dp[i][0] = i;

    for(int j = 1; j <= 24; j++) {
        for (int i = 0; i < n; i++) {
            if (i+(1<<j) > n) break;
            if (num[dp[i][j-1]] > num[dp[i+(1<<(j-1))][j-1]]) dp[i][j] = dp[i+(1<<(j-1))][j-1];
            else dp[i][j] = dp[i][j-1];
        }
    }
    return;
}

int findmin(int a, int b, int num[], int dp[MAXN][24]) {
    int j = 0;
    int length = b - a + 1;
    length /= 2;
    while (length) {
        j++;
        length /= 2;
    }
    int ret = dp[a][j];
    if (num[ret] > num[dp[b-(1<<j)+1][j]]) ret = dp[b-(1<<j)+1][j];
    return ret;
}

void solve(int a, int b) {
    if (a > b) return;
//    if (a+1 == b) {
//        if (a % 2 == 0) ret.push_back({num0[a/2], num1[b/2]});
//        else ret.push_back({num1[a/2], num0[b/2]});
//        return;
//    }
    if (a % 2 == 0) {
        int x = findmin(a/2, (b-1)/2, num0, dp0);
        int y = findmin(x, b/2, num1, dp1);
        seq[r].push_back({num0[x], num1[y]});
        if(x != y) r++;
        solve(a, x*2-1);
        solve(x*2+1, y*2);
        solve(y*2+2,b);
    }
    else {
        int x = findmin(a/2, (b-1)/2, num1, dp1);
        int y = findmin(x+1, b/2, num0, dp0);
        seq[r].push_back({num1[x], num0[y]});
        if(x+1 != y) r++;
        solve(a, x*2);
        solve(x*2+2, y*2-1);
        solve(y*2+1, b);
    }
}


