		mn2[x]=min(mn2[x],mn1[rc]);
	}
}


void rot(int x){
	int o=fa[x],k=gs(x);
	fa[ch[o][k]=ch[x][!k]]=o;
	fa[x]=fa[o];
	if(fa[o])ch[fa[o]][gs(o)]=x;
	fa[ch[x][!k]=o]=x;ps(o);
}

void splay(int x,int y=0){
	for(;fa[x]!=y;rot(x))
		if(fa[fa[x]]!=y)rot(gs(x)^gs(fa[x])?x:fa[x]);
	ps(x);if(!y)rt=x;else ps(y);
}

int merge(int x,int y){
	if(!x||!y)return x+y;
	for(;ch[x][1];x=ch[x][1]);splay(x);
	ch[x][1]=y;fa[y]=x;ps(x);return x;
}
