const int inf = 1001001001;

struct segtree {
  function<int(int, int)> f;
  vector<int> node;
  static const int N = 1 << 18;
  int ide;

  segtree(int ide, function<int(int, int)> f) : ide(ide), f(f), node(2 * N, ide){}

  void init(vector<int> &v) {
    for (int i = 0; i < v.size(); ++i) {
      node[i + N - 1] = v[i];
    }
    for (int i = N - 2; i >= 0; --i) {
      node[i] = f(node[2 * i + 1], node[2 * i + 2]);
    }
  }

  int find(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return ide;
    if (a <= l && r <= b) return node[k];
    return f(
      find(a, b, 2 * k + 1, l, (l + r) / 2),
      find(a, b, 2 * k + 2, (l + r) / 2, r)
    );
  }

  int find(int a, int b) {
    return find(a, b, 0, 0, N);
  }
};

struct data {
  pair<int, int> p;
  int k;
  data(pair<int, int> p, int k) : p(p), k(k) {}
};

bool operator<(const data& a, const data& b) {
  return a.p > b.p;
}

int main() {
  int n;
  cin >> n;

  map<int, int> id;
  vector<int> p(n);
  for (int i = 0; i < n; ++i) {
    cin >> p[i];
    id[p[i]] = i;
  }

  vector<int> u, v;
  for (int i = 0; i < n; ++i) {
    if (i & 1) {
      u.push_back(p[i]);
      v.push_back(inf);
    } else {
      u.push_back(inf);
      v.push_back(p[i]);
    }
  }

  auto f = [&](int a, int b) { return min(a, b); };

  segtree even(inf, f), odd(inf, f);
  odd.init(u);
  even.init(v);

  int idx = 0;
  vector<vector<int>> G(n);
  vector<pair<int, int>> val(n);

  function<void(int, int)> solve = [&](int l, int r) {
    int x, y;
    x = id[(l & 1 ? odd : even).find(l, r)];
    y = id[(l & 1 ? even : odd).find(x, r)];

    int v = idx;
    idx++;

    val[v] = make_pair(p[x], p[y]);
    if (l != x) {
      G[v].push_back(idx);
      solve(l, x);
    }
    if (x + 1 != y) {
      G[v].push_back(idx);
      solve(x + 1, y);
    }
    if (y + 1 != r) {
      G[v].push_back(idx);
      solve(y + 1, r);
    }
  };

  solve(0, n);

  vector<int> ans;

  priority_queue<data> que;
  que.push(data(val[0], 0));
  while (!que.empty()) {
    pair<int, int> p = que.top().p;
    int k = que.top().k;
    que.pop();

    ans.push_back(p.first);
    ans.push_back(p.second);

    for (auto e : G[k]) {
      que.push(data(val[e], e));
    }
  }

  for (int i = 0; i < ans.size(); ++i) {
    cout << ans[i] << (i + 1 == n ? "\n" : " ");
  }
}

