const int N = 2e5 + 5;
int tclr[N*4], t[N*4][2], n, p[N*2], a[N*2], pos[N];

void build( int v, int tl, int tr ){
    if ( tl == tr ){
        if ( tl % 2 == 0 ){
            t[v][0] = p[tl];
            t[v][1] = 1e9;
        }
        else{
            t[v][0] = 1e9;
            t[v][1] = p[tl];
        }
        return;
    }
    int tm = ( tl + tr ) >> 1;
    build( (v<<1), tl, tm );
    build( (v<<1) + 1, tm + 1, tr );
    t[v][0] = min( t[(v<<1)][0], t[(v<<1)+1][0] );
    t[v][1] = min( t[(v<<1)][1], t[(v<<1)+1][1] );
}

void add( int& x ){
    x++;
    if ( x == 2 ){
        x = 0;
    }
}

void push( int v ){
    if ( !tclr[v] ){
        return;
    }
    add( tclr[(v<<1)] );
    add( tclr[(v<<1)+1] );
    swap( t[(v<<1)][0], t[(v<<1)][1] );
    swap( t[(v<<1)+1][0], t[(v<<1)+1][1] );
    tclr[v] = 0;
}

int get( int v, int tl, int tr, int l, int r, int tp ){
    if ( ( l == tl ) && ( r == tr ) ){
        return t[v][tp];
    }
    push(v);
    int tm = ( tl + tr ) >> 1;
    if ( r <= tm ){
        return get( (v<<1), tl, tm, l, r, tp );
    }
    if ( l >= tm + 1 ){
        return get( (v<<1) + 1, tm + 1, tr, l, r, tp );
    }
    return min( get( (v<<1), tl, tm, l, tm, tp ), get( (v<<1) + 1, tm + 1, tr, tm + 1, r, tp ) );
}

void update( int v, int tl, int tr, int l, int r ){
    if ( l > r ){
        return;
    }
    if ( ( l == tl ) && ( r == tr ) ){
        add( tclr[v] );
        swap( t[v][0], t[v][1] );
        return;
    }
    push(v);
    int tm = ( tl + tr ) >> 1;
    if ( r <= tm ){
        update( (v<<1), tl, tm, l, r );
    }
    else
    if ( l >= tm + 1 ){
        update( (v<<1) + 1, tm + 1, tr, l, r );
    }
    else{
        update( (v<<1), tl, tm, l, tm );
        update( (v<<1) + 1, tm + 1, tr, tm + 1, r );
    }
    t[v][0] = min( t[(v<<1)][0], t[(v<<1)+1][0] );
    t[v][1] = min( t[(v<<1)][1], t[(v<<1)+1][1] );
}

void upId( int v, int tl, int tr, int idx ){
    if ( tl == tr ){
        t[v][0] = 1e9;
        t[v][1] = 1e9;
        return;
    }
    push(v);
    int tm = ( tl + tr ) >> 1;
    if ( idx <= tm ){
        upId( (v<<1), tl, tm, idx );
    }
    else{
        upId( (v<<1) + 1, tm + 1, tr, idx );
    }
    t[v][0] = min( t[(v<<1)][0], t[(v<<1)+1][0] );
    t[v][1] = min( t[(v<<1)][1], t[(v<<1)+1][1] );
}

