class E {
public:
	struct group {
		int l, r;
		int a, b;
		bool operator<(const group&g) const {
			return l < g.l;
		}
	};

	vector<int> I;
	SetMinTree<int> T[2];
	minheap<pair<int, group>> H;

	void addgroup(int l, int r) {
		if (l>r) {
			return;
		}
		int len = (r-l+1)/2;
		int lowest = T[l%2].get(l/2, l/2+len-1);
		int lowestId = I[lowest];
		int second = T[(l+1)%2].get((lowestId+1)/2,r/2);
		H.push({lowest, {l, r, lowest, second}});

	}

	void solve(istream& cin, ostream& cout) {
		int N; cin >> N;
		vector<int> P(N); cin >> P;
		vector<int> Podd(N/2), Peven(N/2);
		I.resize(N);
		for (int i = 0; i < N; ++i) {
			P[i]--;
			I[P[i]] = i;
			if (i%2) {
				Podd[i/2] = P[i];
			} else {
				Peven[i/2] = P[i];
			}
  		}

		T[1].setup(Podd);
		T[0].setup(Peven);


		addgroup(0, N-1);

		for (int i = 0; i < N/2; ++i) {
			auto x = H.top();
			H.pop();
			cout << x.y.a+1 << ' ' << x.y.b+1 << ' ';
			addgroup(x.y.l, I[x.y.a]-1);
			addgroup(I[x.y.a]+1, I[x.y.b]-1);
			addgroup(I[x.y.b]+1, x.y.r);

		}
		cout << endl;

    }
};


int main() {
	ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	E solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
    return 0;
}

