template <typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> dat;

	SegTree() {}
	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		dat.resize(n * 2 - 1, init_val);
	}

	void update(int i, T x) {
		i += n - 1;
		dat[i] = min(dat[i], x);
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	void set(int i, T x) {
		dat[i + n - 1] = x;
		update(i, x);
	}

	// 探索範囲[a,b), 現在見ているkノード[l,r)
	T query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;

		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return dat[k];
		return min( query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r) );
	}
};

int N;
int p[212345], ans[212345];
SegTree<pii> segodd, segeven, segall;
pii num[212345];

// [l, r)
void dfs(int l, int r, int d) {
	if (r - l == 2) {
		num[l] = pii(d, l);
		num[l + 1] = pii(d, l);
		return;
	}

	int miidx = segall.query(l, r).se;

	if (miidx % 2 == 0) {

		num[miidx] = pii(d, miidx);
		num[miidx + 1] = pii(d, miidx);

		if (l < miidx) dfs(l, miidx, d + 1);
		if (miidx + 2 < r) dfs(miidx + 2, r, d + 1);
	}
	else {
		int nidx = -1;
		if (r & 1) nidx = segodd.query(l, r - 3).se;
		else nidx = segeven.query(l, r - 3).se;

		if (p[nidx] >= p[miidx - 1]) {
			num[miidx - 1] = pii(d, miidx - 1);
			num[miidx] = pii(d, miidx - 1);

			if (l < miidx - 1) dfs(l, miidx - 1, d + 1);
			if (miidx + 1 < r) dfs(miidx + 1, r, d + 1);
		}
		else {
			num[nidx] = pii(d, nidx);
			num[r - 1] = pii(d, nidx);

			if (l < nidx) dfs(l, nidx, d + 1);
			if (nidx + 1 < r - 1) dfs(nidx + 1, r - 1, d + 1);
		}
	}

	return;
}

