	segodd = SegTree<pii>(N, pii(INF, -1));
	segeven = SegTree<pii>(N, pii(INF, -1));
	segall = SegTree<pii>(N, pii(INF, -1));

	REP(i, N) {
		if (i & 1) segodd.update(i, pii(p[i], i));
		else segeven.update(i, pii(p[i], i));
		segall.update(i, pii(p[i], i));
	}

	dfs(0, N, 0);

	set<pii> ss;
	priority_queue<P, vector<P>, greater<P> > pq;
	REP(i, N) {
		set<pii>::iterator it = ss.find(num[i]);

		if (it != ss.end()) {
			int idx = it->se;
			pq.push(P(pii(num[idx].fi, p[idx]), pii(idx, i)));
			ss.erase(it);
		}
		else {
			ss.insert(num[i]);
		}
	}

	vector<int> ans;
	while (!pq.empty()) {
		int idx = pq.top().se.fi;
		int idx2 = pq.top().se.se; pq.pop();
		ans.push_back(p[idx]);
		ans.push_back(p[idx2]);
	}


	REP(i, N) printf("%d%c", ans[i], i == N - 1 ? '\n' : ' ');

	return 0;
}

