class IndexSegmentTree{
private:
    int n;
    vector<int> dat;
    vector<int> v;
public:
    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        dat.assign(2*n-1, -1);
        v.assign(n, INF);
    }
    // k: index(0-indexed), a: value
    void update(int p, int a){
        v[p] = a;
        int k = p + n - 1;
        dat[k] = p;
        while(k>0){
            k = (k-1)/2;
            if(dat[k*2+2]==-1 || v[dat[k*2+1]] <= v[dat[k*2+2]]){
                dat[k] = dat[k*2+1];
            }else{
                dat[k] = dat[k*2+2];
            }
        }
    }
    // query(a, b) =>  minimum in [a,b]
    int query(int a, int b){
        return _query(a, b, 0, 0, n-1);
    }
    // v[dat[k]] is minimum in [l,r]
    int _query(int a, int b, int k, int l, int r){
        if(r<a||b<l) return -1;
        if(a<=l&&r<=b){
            return dat[k];
        }else{
            int vl = _query(a, b, k*2+1, l, (l+r)/2);
            int vr = _query(a, b, k*2+2, (l+r)/2+1, r);
            if(vr == -1){
                return vl;
            }else if(vl == -1){
                return vr;
            }else{
                if (v[vl] > v[vr]){
                    return vr;
                }else{
                    return vl;
                }
            }
        }
    }
    // k: index(0-indexed)
    int get(int k){
        return v[k];
    }
};

IndexSegmentTree seg[2];
vector<int> p;
vector<P> pairs;
vector<vector<int>> G;

int dfs(int l, int r, int m){
    // [l, r]
    int min_idx = seg[m].query(l, r);
    int next_m = m ^ 1;
    int pair_idx = seg[next_m].query(min_idx + 1, r);

    int i = pairs.size();
    assert(i == G.size());
    pairs.emplace_back(p[min_idx], p[pair_idx]);
    G.push_back({});

    if(l < min_idx){
        G[i].push_back(dfs(l, min_idx - 1, m));
    }
    if(pair_idx - min_idx > 2){
        G[i].push_back(dfs(min_idx + 1, pair_idx - 1, next_m));
    }
    if(pair_idx < r){
        G[i].push_back(dfs(pair_idx, r, m));
    }

    return i;
}

void traverse(int v){
    if(v != 0){
        cout << " ";
    }
    cout << pairs[v].first << " " << pairs[v].second;

    vector<P> to_sort;
    for(int to : G[v]){
        to_sort.emplace_back(pairs[to].first, to);
    }
    sort(to_sort.begin(), to_sort.end());
    for(P p : to_sort){
        traverse(p.second);
    }
}

