		ans = ans * a % mod;
	return ans;
}
inline ll inverse(int x){ return pow(x, mod - 2); }
typedef std::pair<int, int> pr;
const int inf = 1e9;
int n;
struct mes {
	int oddmin, evenmin;
	pr v0, v1;
};
const mes lol = (mes) {inf, inf, pr(inf, inf), pr(inf, inf)};
inline mes add(const mes & x,const mes & y) {
	return (mes){std::min(x.oddmin, y.oddmin), std::min(x.evenmin, y.evenmin), 
		std::min(pr(x.oddmin, y.evenmin),std::min(x.v0, y.v0)),
		std::min(pr(x.evenmin, y.oddmin),std::min(x.v1, y.v1)), };
}
mes tree[maxn << 2];
int p[maxn], ip[maxn];
inline void build(int cur = 1,int l = 1,int r = n) {
	if(l == r) {
		if(l & 1) {
			tree[cur].oddmin = p[l];
			tree[cur].evenmin = inf;
		} else {
			tree[cur].oddmin = inf;
			tree[cur].evenmin = p[l];
		}
		tree[cur].v0 = tree[cur].v1 = pr(inf, inf);
		return ;
	}
	int mid = l + r >> 1;
	build(cur << 1, l, mid); 
	build(cur << 1 | 1, mid + 1, r);
	tree[cur] = add(tree[cur << 1], tree[cur << 1 | 1]);
}
inline mes qry(int ql,int qr,int cur = 1,int l = 1,int r = n) {
	if(ql <= l && r <= qr) return tree[cur];
	int mid = l + r >> 1; mes ans = lol;
	if(ql <= mid) ans = add(ans, qry(ql, qr, cur << 1, l, mid));
	if(mid < qr) ans = add(ans, qry(ql, qr, cur << 1 | 1, mid + 1, r));
	return ans;
}
struct range {
	int l, r; pr v;
	inline range(int L,int R) { mes x = qry(l = L, r = R); v = L & 1 ? x.v0 : x.v1; }
	inline bool operator < (const range & b) const {
		return v > b.v;
	}
};
std::priority_queue<range> heap;
int main() {
	std::ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cin >> n;
	rep(i, 1, n) {
		cin >> p[i];
		ip[p[i]] = i;
	}
	build();
	heap.emplace(1, n);
	for(;!heap.empty();) {
		range x = heap.top(); heap.pop();
		int L = x.l, Lx = ip[x.v.first], Rx = ip[x.v.second], R = x.r;
		cout << p[Lx] << ' ' << p[Rx] << ' ';
		if(L < Lx - 1) heap.emplace(L, Lx - 1);
		if(Lx + 1 < Rx - 1) heap.emplace(Lx + 1, Rx - 1);
		if(Rx + 1 < R) heap.emplace(Rx + 1, R);
	}
}

