const int TREE_SIZE = 1;


ll segTree[TREE_SIZE], lazyTree[TREE_SIZE];


void updateRange(int node, int start, int end, int l, int r, ll val)
{
    if(lazyTree[node] != 0)
    {
        // This node needs to be updated
        segTree[node] += (end - start + 1) * lazyTree[node];    // Update it
        if(start != end)
        {
            lazyTree[node*2] += lazyTree[node];                  // Mark child as lazyTree
            lazyTree[node*2+1] += lazyTree[node];                // Mark child as lazyTree
        }
        lazyTree[node] = 0;                                  // Reset it
    }
    if(start > end or start > r or end < l)              // Current segment is not within range [l, r]
        return;
    if(start >= l and end <= r)
    {
        // Segment is fully within range
        segTree[node] += (end - start + 1) * val;
        if(start != end)
        {
            // Not leaf node
            lazyTree[node*2] += val;
            lazyTree[node*2+1] += val;
        }
        return;
    }
    int mid = (start + end) / 2;
    updateRange(node*2, start, mid, l, r, val);        // Updating left child
    updateRange(node*2 + 1, mid + 1, end, l, r, val);   // Updating right child
    segTree[node] = segTree[node*2] + segTree[node*2+1];        // Updating root with max value
}


ll queryRange(int node, int start, int end, int l, int r)
{
    if(start > end or start > r or end < l)
        return 0;         // Out of range
    if(lazyTree[node] != 0)
    {
        // This node needs to be updated
        segTree[node] += (end - start + 1) * lazyTree[node];            // Update it
        if(start != end)
        {
            lazyTree[node*2] += lazyTree[node];         // Mark child as lazyTree
            lazyTree[node*2+1] += lazyTree[node];    // Mark child as lazyTree
        }
        lazyTree[node] = 0;                 // Reset it
    }
    if(start >= l and end <= r)             // Current segment is totally within range [l, r]
        return segTree[node];
    int mid = (start + end) / 2;
    ll p1 = queryRange(node*2, start, mid, l, r);         // Query left child
    ll p2 = queryRange(node*2 + 1, mid + 1, end, l, r); // Query right child
    return (p1 + p2);
}





















const int MAXN = 2e5+1;
const ll INF = 1e16;


int N;
ll ar[MAXN], evens[MAXN], odds[MAXN], valToPos[MAXN];
ll segTreeOdds[4*MAXN], segTreeEvens[4*MAXN];


void initSegTree(ll * arr, ll * segtree, int at, int from, int to) {
  if (from == to) {
    segtree[at] = arr[from];
    return;
  }
  int mid = (from + to) / 2;
  initSegTree(arr, segtree, 2*at, from, mid);
  initSegTree(arr, segtree, 2*at+1, mid+1, to);
  segtree[at] = min(segtree[2*at], segtree[2*at+1]);
}


ll querySegTree(ll * segtree, int at, int from, int to, int ql, int qr) {
  if (to < ql || qr < from) {
    return INF;
  }
  if (ql <= from && to <= qr) {
    return segtree[at];
  }
  int mid = (from + to) / 2;
  return min(querySegTree(segtree, 2*at, from, mid, ql, qr), querySegTree(segtree, 2*at+1, mid+1, to, ql, qr));
}


void input() {
  cin >> N;
  for (int i = 1 ; i <= N ; i++) {
    cin >> ar[i];
    valToPos[ar[i]] = i;
    if (i % 2 == 1) {
      odds[i] = ar[i];
      evens[i] = INF;
    } else {
      evens[i] = ar[i];
      odds[i] = INF;
    }
  }
}


void preprocess() {
  initSegTree(odds, segTreeOdds, 1, 1, N);
  initSegTree(evens, segTreeEvens, 1, 1, N);
}


void solve() {
  set < pair<ll, pair<int, int> > > Q;
  Q.insert({querySegTree(segTreeOdds, 1, 1, N, 1, N), {1, N}});
  while (!Q.empty()) {
    int l = Q.begin()->second.first;
    int r = Q.begin()->second.second;
    //cerr << "L = " << l << ", R = " << r << "\n";
    Q.erase(Q.begin());
    int idL, idR;
    ll v1 , v2;
    if (l % 2 == 1) {
      v1 = querySegTree(segTreeOdds, 1, 1, N, l, r);
      idL = valToPos[v1];
      v2 = querySegTree(segTreeEvens, 1, 1, N, idL, r);
      idR = valToPos[v2];
    } else {
      v1 = querySegTree(segTreeEvens, 1, 1, N, l, r);
      idL = valToPos[v1];
      v2 = querySegTree(segTreeOdds, 1, 1, N, idL, r);
      idR = valToPos[v2];
    }
    //cerr << "V1 = " << v1 << ", V2 = " << v2 << ", idL = " << idL << ", idR = " << idR << "\n";

    cout << v1 << " " << v2 << " ";

    if (idL + 1 < idR) {
      //cerr << "Putting stuff in between\n";
      if (idL+1 % 2 == 1) {
        Q.insert({querySegTree(segTreeOdds, 1, 1, N, idL+1, idR-1), {idL+1, idR-1}});
      } else {
        Q.insert({querySegTree(segTreeEvens, 1, 1, N, idL+1, idR-1), {idL+1, idR-1}});
      }
    }
    if (l < idL) {
      //cerr << "Putting stuff before\n";
      if (l % 2 == 1) {
        Q.insert({querySegTree(segTreeOdds, 1, 1, N, l, idL-1), {l, idL-1}});
      } else {
        Q.insert({querySegTree(segTreeEvens, 1, 1, N, l, idL-1), {l, idL-1}});
      }
    }
    if (idR + 1 < r) {
      //cerr << "Putting stuff after\n";
      if (idR+1 % 2 == 1) {
        Q.insert({querySegTree(segTreeOdds, 1, 1, N, idR+1, r-1), {idR+1, r-1}});
      } else {
        Q.insert({querySegTree(segTreeEvens, 1, 1, N, idR+1, r-1), {idR+1, r-1}});
      }
    }
  }
}


