class SegmentTree{
public:

  int n;
  vector<int> tree;

  SegmentTree(){}

  SegmentTree(int size){
    n=1;
    while(n<size) n*=2;

    tree.resize(2*n-1,INF);
  }

  SegmentTree(vector<int> v){
    int vSize=v.size();
    n=1;
    while(n<vSize) n*=2;

    tree.resize(2*n-1,INF);

    for(int i=0;i<vSize;i++) tree[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) tree[i]=min(tree[2*i+1],tree[2*i+2]);
  }

  void initialize(vector<int> v){
    int vSize=v.size();
    n=1;
    while(n<vSize) n*=2;

    tree.resize(2*n-1,INF);

    for(int i=0;i<vSize;i++) tree[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) tree[i]=min(tree[2*i+1],tree[2*i+2]);
  }

  void update(int index,int value){
    index+=n-1;

    tree[index]=value;
    while(index>0){
      index=(index-1)/2;
      tree[index]=min(tree[2*index+1],tree[2*index+2]);
    }
  }

  int getMin(int a,int b,int k=0,int l=0,int r=-1){//[a,b),getMin(a,b,0,0,-1)
    if(r<0) r=n;

    if(r<=a||b<=l) return INF;
    else if(a<=l&&r<=b) return tree[k];
    else{
      int lval=getMin(a,b,2*k+1,l,(l+r)/2);
      int rval=getMin(a,b,2*k+2,(l+r)/2,r);
      return min(lval,rval);
    }
  }
};

