            if (x == -1 || a[x] > a[i])
                x = i;
        for (int i = x + 1; i < hi; i += 2)
            if (y == -1 || a[y] > a[i])
               y = i;
    }
    if (y == -1)
        for (int i = x - 1; i >= lo; i -= 2)
            if (y == -1 || a[y] > a[i])
               y = i;
    if (a[x] == find) {
        ++find;
        if (a[y] == find)
            ++find;
    }
    if (x > y) swap(x, y);
    v.push_back(make_pair(level, (long long)a[x] * (n + 1) + a[y]));
    if (lo + 1 < x)
        find = solve(lo, x, find, level + 1);
    if (x + 2 < y)
        find = solve(x + 1, y, find, level + 1);
    if (y + 2 < hi)
        find = solve(y + 1, hi, find, level + 1);
    return find;
}

