        else even.set(i,pii(p[i],i));
    }
    odd.build(); even.build();

    using Tu = tuple<pii, int, int>;
    priority_queue<Tu, vector<Tu>, greater<Tu>> pq;
    pq.emplace(even.get(0,N),0,N);

    vector<int> ans(N);
    int cur = 0;
    while (!pq.empty()) {
        pii vall,valr;
        int l,r;
        tie(vall,l,r) = pq.top(); pq.pop();
