int minn[2][maxn << 2], d[maxn], a[maxn], pos[maxn], n, tag[maxn << 2], lim[maxn << 2], limt;
void push_down(int k){
    tag[k << 1] ^= 1; tag[k << 1 | 1] ^= 1;
    swap(minn[1][k << 1], minn[0][k << 1]);
    swap(minn[1][k << 1 | 1], minn[0][k << 1  | 1]);
    tag[k] = 0;
}
void update(int opt, int k, int l, int r, int pos, int x){
    int mid = l + r >> 1;
    if(l == r){
        minn[opt][k] = x; return; 
    }
    if(tag[k]) push_down(k);
    if(pos <= mid) update(opt, k << 1, l , mid, pos, x);
    else update(opt, k << 1 | 1, mid + 1, r, pos, x);
    if(minn[0][k << 1] > 0 && minn[0][k << 1 | 1] > 0)
    minn[0][k] = min(minn[0][k << 1], minn[0][k << 1 | 1]);
    else minn[0][k] = minn[0][k << 1] | minn[0][k << 1 | 1]; 
    if(minn[1][k << 1] > 0 && minn[1][k << 1 | 1] > 0)
    minn[1][k] = min(minn[1][k << 1], minn[1][k << 1 | 1]);
    else minn[1][k] = minn[1][k << 1] | minn[1][k << 1 | 1]; 

}
void modify(int k, int l, int r, int L, int R){
    int mid = l + r >> 1;
    if(L <= l && r <= R){
        swap(minn[0][k], minn[1][k]); tag[k] ^= 1;
        return;
    }
    if(tag[k]) push_down(k);
    if(L <= mid) modify(k << 1, l, mid, L, R);
    if(R > mid) modify(k << 1 | 1, mid + 1, r, L, R);
    if(minn[0][k << 1] > 0 && minn[0][k << 1 | 1] > 0)
    minn[0][k] = min(minn[0][k << 1], minn[0][k << 1 | 1]);
    else minn[0][k] = minn[0][k << 1] | minn[0][k << 1 | 1]; 
    if(minn[1][k << 1] > 0 && minn[1][k << 1 | 1] > 0)
    minn[1][k] = min(minn[1][k << 1], minn[1][k << 1 | 1]);
    else minn[1][k] = minn[1][k << 1] | minn[1][k << 1 | 1]; 
}

int query(int k, int l , int r, int L, int R, int opt){
    int ansx = 0, ansy = 0;
    if(L <= l && r <= R){
        ansx = minn[opt][k];
        return ansx; 
    }
    if(tag[k]) push_down(k);
    int mid = l + r >> 1;
    if(L <= mid) ansx = query(k << 1, l, mid, L, R, opt);
    if(R > mid) ansy = query(k << 1 | 1, mid + 1, r, L, R, opt);
    if(ansx > 0 && ansy > 0) return min(ansx, ansy);
    else return (ansx | ansy);
    if(minn[0][k << 1] > 0 && minn[0][k << 1 | 1] > 0)
    minn[0][k] = min(minn[0][k << 1], minn[0][k << 1 | 1]);
    else minn[0][k] = minn[0][k << 1] | minn[0][k << 1 | 1]; 
    if(minn[1][k << 1] > 0 && minn[1][k << 1 | 1] > 0)
    minn[1][k] = min(minn[1][k << 1], minn[1][k << 1 | 1]);
    else minn[1][k] = minn[1][k << 1] | minn[1][k << 1 | 1]; 
}
void query_pos(int k ,int l, int r, int x){
    int mid = l + r >> 1;
    if(lim[k]) limt = min(lim[k], limt);
    if(l == r) return;
    if(x <= mid) query_pos(k << 1, l, mid, x);
    else query_pos(k << 1 | 1, mid + 1, r, x);
}
void update_pos(int k, int l, int r, int L, int R, int x){
    if(L <= l && r <= R){
        if(!lim[k])lim[k] = x;
        else lim[k] = min(lim[k], x); 
        return;
    }
    int mid = l + r >> 1;
    if(mid >= L) update_pos(k << 1, l, mid, L, R, x);
    if(R > mid) update_pos(k << 1 | 1, mid + 1, r, L ,R , x);
}
