	if ((r - l + 1) & 1)
		return pos[min(f[l][k], f[r - 2 * (bin[k] - 1)][k])];
	else return pos[min(f[l][k], f[r - 2 * (bin[k] - 1) - 1][k])]; 
}

vector<pair<int, int> > Solve(int l, int r)
{
	if (l > r) 
	{
		vector<pair<int, int> > res;
		return res;
	}
	int ps1 = GetMin(l, r);
	int ps2 = GetMin(ps1 + 1, r);

	vector<pair<int, int> > lis[3], res;
	lis[0] = Solve(l, ps1 - 1);;
	lis[1] = Solve(ps1 + 1, ps2 - 1);
	lis[2] = Solve(ps2 + 1, r);
	int p[3] = {0};

	res.push_back(make_pair(a[ps1], a[ps2]));
	while (p[0] < lis[0].size() || p[1] < lis[1].size() || p[2] < lis[2].size())
	{
		int k = -1; pair<int, int> Min;
		for (int i = 0; i <= 2; ++i)
		{
			if (p[i] == lis[i].size()) continue;
			if (k == -1 || lis[i][p[i]] < Min)
				k = i, Min = lis[i][p[i]];
		}
		p[k]++; res.push_back(Min);
	}
	return res;
}

