		if(l==r){
			tree[nod]=pos; return;
		}
		int mid=(l+r)>>1;
		if(pos<=mid)insert(l,mid,pos,nod<<1); else insert(mid+1,r,pos,nod<<1|1);
		tree[nod]=cmp(tree[nod<<1],tree[nod<<1|1]);
	}
