void Pull(int node){
	tree0[node].fi=min(tree0[node*2].fi,tree0[node*2+1].fi);
	tree0[node].se=min(tree0[node*2].se,tree0[node*2+1].se);	
	tree1[node].fi=min(tree1[node*2].fi,tree1[node*2+1].fi);
	tree1[node].se=min(tree1[node*2].se,tree1[node*2+1].se);
}

void build(int l,int r,int node){
//	cout<<"tree:"<<l<<" "<<r<<" "<<node<<endl;
	if(l==r){
		if(l&1)tree1[node]=mk(a[l],a[l-1]),tree0[node]=mk(INF,a[l]);
		else tree1[node]=mk(INF,a[l]),tree0[node]=mk(a[l],a[l+1]);
		leaf[l]=node;
//		cout<<l<<" "<<r<<" "<<tree0[node].fi<<" "<<tree0[node].se<<" "<<tree1[node].fi<<" "<<tree1[node].se<<endl;
		return;
	}
	int mid=(l+r)>>1;
	build(l,mid,node*2);
	build(mid+1,r,node*2+1);
	Pull(node);
//	cout<<l<<" "<<r<<" "<<tree0[node].fi<<" "<<tree0[node].se<<" "<<tree1[node].fi<<" "<<tree1[node].se<<endl;
}

void Push(int node){
	if(tag[node]){
		swap(tree0[node].fi,tree0[node].se);
		swap(tree1[node].fi,tree1[node].se);
		tag[node*2]^=1;
		tag[node*2+1]^=1;
		tag[node]=0;
	}
}

void update(int l,int r,int vl,int vr,int node){
	if(vl>vr)return;
	if(l>vr||r<vl)return;
	if(l>=vl&&r<=vr){
		tag[node]^=1;
		Push(node);
		return;
	}
	int mid=(l+r)>>1;
	Push(node);
	update(l,mid,vl,vr,node*2);
	update(mid+1,r,vl,vr,node*2+1);
	Pull(node);
}

int query_0(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return tag[node]==1?tree0[node].se:tree0[node].fi;
	Push(node);
	int mid=(l+r)>>1;
	return min(query_0(l,mid,vl,vr,node*2),query_0(mid+1,r,vl,vr,node*2+1));
}

int query_1(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return tag[node]==1?tree1[node].se:tree1[node].fi;
	Push(node);
	int mid=(l+r)>>1;
	return min(query_1(l,mid,vl,vr,node*2),query_1(mid+1,r,vl,vr,node*2+1));
}

int Find_nxt(int l,int r,int vl,int vr,int node){
	if(l>vr||r<vl)return INF;
	if(l>=vl&&r<=vr)return nxt[node];
	int mid=(l+r)>>1;
	return min(Find_nxt(l,mid,vl,vr,node*2),Find_nxt(mid+1,r,vl,vr,node*2+1));
}

void del(int pos){
	int node=leaf[pos];
	tree0[node]=tree1[node]=mk(INF,INF);
	while(node){
		node>>=1;
		Pull(node);
	}
	int node2=(pos&1)?pos-1:pos+1;
	node2=leaf[node2];
	tree0[node2].se=tree1[node2].se=INF;
	while(node2){
		if(!node2||node2>n)break;
		node2>>=1;
		Pull(node2);
	}
}

void add(int pos,int val){
	int node=leaf[pos];
	nxt[node]=val;
	while(node){
		node>>=1;
		nxt[node]=min(nxt[node*2],nxt[node*2+1]);
	}
}

