	REP(i,n)cin>>a[i],P[a[i]]=i;
	build(1,n,1);
	REP(i,n)add(i,n+1);
	REP(i,n/2){
		int pos=P[query_1(1,n,1,n,1)];
		ans.push_back(a[pos]);
		int cur=Find_nxt(1,n,pos+1,n,1);
		int pos2=P[query_0(1,n,pos+1,cur-1,1)];
		ans.push_back(a[pos2]);
		del(pos);
		del(pos2);
		add(pos,pos);
		add(pos2,pos2);
		update(1,n,pos+1,pos2-1,1);
	}
	rep(i,ans.size())cout<<ans[i]<<" ";
	return 0;
}

