//[l, r)
deque<int> solve(int l, int r) {
    if (l + 1 >= r) return deque<int>();

    int val1 = (l&1?seg2:seg1).query(l, r);
    int pos1 = pos[val1];
    int rr = *used.lower_bound(pos1);
    int val2 = (l&1?seg1:seg2).query(pos1, rr);
    int pos2 = pos[val2];

    //cout << l << " " << r << " " << val1 << " " << val2 << endl;
    used.insert(pos1); used.insert(pos2);
    seg1.update(pos1, INF); seg2.update(pos2, INF);

    deque<int> a = solve(l, pos1);
    deque<int> b = solve(pos1+1, pos2); b.push_front(val2); b.push_front(val1);
    deque<int> c = solve(pos2+1, r); 

    //cout << l << " " << r << endl;
    deque<int> ret;
    int i, j, k;
    i = j = k = 0;
    while (true) {
        int pos = -1, minv = INF;
        if (i < a.size() && minv > a[i]) pos = 0, minv = a[i];
        if (j < b.size() && minv > b[j]) pos = 1, minv = b[j];
        if (k < c.size() && minv > c[k]) pos = 2, minv = c[k];
        //cout << pos << endl;
        if (pos == -1) break;
        if (pos == 0) {
            ret.push_back(a[i]);
            ret.push_back(a[i+1]);
            i += 2;
        }
        if (pos == 1) {
            ret.push_back(b[j]);
            ret.push_back(b[j+1]);
            j += 2;
        }
        if (pos == 2) {
            ret.push_back(c[k]);
            ret.push_back(c[k+1]);
            k += 2;
        }
    }
    return (ret);
}

