const double EPS = 1e-10;

struct SegmentTree {
    using P = pair<int, int>;
    const int M1;
    int n;
    vector<P> d;

    SegmentTree(int M1) : M1(M1) {}

    P& f(P& lhs, P& rhs) {
        if (lhs.first == rhs.first)
            return lhs;
        return lhs.first < rhs.first ? lhs : rhs;
    }

    void init(int n_)
    {
        for (n = 1; n < n_; n <<= 1);
        d.assign(n << 1, P(M1, n));
        for (int i = n; i < n << 1; i++) {
            d[i] = P(M1, i - n);
        }
    }

    void build(const vector<int>& v)
	{
		int n_ = v.size();
		init(n_);
		for (int i = 0; i < n_; i++) {
			d[n + i] = P(v[i], i);
		}
		for (int i = n - 1; i > 0; i--) {
			d[i] = f(d[(i << 1) | 0], d[(i << 1) | 1]);
		}
	}

    void update(int k, int x)
	{
		d[k += n] = P(x, k);
		while (k >>= 1) {
			d[k] = f(d[(k << 1) | 0], d[(k << 1) | 1]);
		}
	}

	P query(int a, int b)
	{
		P L = P(M1, n);
        P R = P(M1, n);
		int l = a + n, r = b + n;
		while (l < r) {
			if (l & 1) L = f(L, d[l++]);
			if (r & 1) R = f(d[--r], R);
			l >>= 1, r >>= 1;
		}
		return f(L, R);
	}
};
