struct Tree {
    vector<int> t;
    int siz;

    void build(vector<int> p) {
        int n = p.size();
        siz = 1;
        while (siz < n) siz *= 2;
        t.resize(2*siz);

        for (int i = 0; i < n; i++) {
            t[i+siz] = p[i];
        }

        int x = siz/2;

        while (x) {
            for (int i = x; i < 2*x; i++) {
                t[i] = min(t[2*i], t[2*i+1]);
            }
            x/=2;
        }

    }
    int query(int a, int b) {
        a += siz;
        b += siz;

        int res = min(t[a], t[b]);
        while (a / 2 != b / 2) {
            if (a%2 == 0) res = min(res, t[a+1]);
            if (b%2 == 1) res = min(res, t[b-1]);

            a/=2;
            b/=2;
        }

        return res;
    }
};

