using namespace std;
typedef pair<int, int> pa;

constexpr int INF = 1145141919;
vector<int> p;

void marge(deque<pa> &x, deque<pa> &y) {
    deque<pa> ret;
    while (!(x.empty() && y.empty())) {
        if (x.empty())ret.push_back(y.front()), y.pop_front();
        else if (y.empty())ret.push_back(x.front()), x.pop_front();
        else {
            if (x.front() < y.front())ret.push_back(x.front()), x.pop_front();
            else ret.push_back(y.front()), y.pop_front();
        }
    }
    x = ret;
}

deque<pa> solve(int x, int y) {
    pa minValue = {INF, INF}, minIndex{-1, -1};
    for (int i = 0; i < y - x; i++) {
        int here = i + x;
        if (i % 2 == 0 && minValue.first > p[here]) {
            minValue = {p[here], INF}, minIndex = {here, -1};
        }
        if (i % 2 == 1 && minValue.second > p[here]) {
            minValue.second = p[here], minIndex.second = here;
        }
    }

    deque<pa> ret;
    if (x != minIndex.first) {
        auto tmp = solve(x, minIndex.first);
        marge(ret, tmp);
    }
    if (minIndex.first + 1 != minIndex.second) {
        auto tmp = solve(minIndex.first + 1, minIndex.second);
        marge(ret, tmp);
    }
    if (minIndex.second + 1 != y) {
        auto tmp = solve(minIndex.second + 1, y);
        marge(ret, tmp);
    }
    ret.push_front(minValue);
    return ret;
}

