void dfs(int l, int r, int from){
    if(r <= l)return;

    auto lmin = sg[l%2].query(l, r);
    int li = lmin.second;
    auto rmin = sg[1-l%2].query(li+1, r);
    int ri = rmin.second;

    int at = res.size();
    res.push_back(P(lmin.first, rmin.first));
    if(from != -1)
        pr[from].push_back(at);

    dfs(l, li, at);
    dfs(li+1, ri, at);
    dfs(ri+1, r, at);
}

