		int s = (int)(o_box%MOD) + 1;
		long long int o_bag = even.RMQ(s, min(s + i * 2 - 1, rig));
		long long int e_box = even.RMQ(0, rig);
		s = (int)(e_box%MOD) + 1;
		long long int e_bag = odd.RMQ(s, min(s + i * 2 - 1, rig));
		if (o_bag == LLONG_MAX) {
			ret.push_back(e_box / MOD);
