void DFS(int t , int l , int r)
{
	if (l > r)
		return ;
	if (l + 1 == r)
	{
		vct[t].pb((Item){a[l] , a[r]});
		return ;
	}
	int minn1 = INF , pos1 , minn2 = INF , pos2;
	for (int i = l ; i <= r ; i += 2)
		if (minn1 > a[i])
		{
			minn1 = a[i];
			pos1 = i;
		}
	for (int i = pos1 + 1 ; i <= r ; i += 2)
		if (minn2 > a[i])
		{
			minn2 = a[i];
			pos2 = i;
		}
	DFS(t * 3 , l , pos1 - 1);
	DFS(t * 3 + 1 , pos1 + 1 , pos2 - 1);
	DFS(t * 3 + 2 , pos2 + 1 , r);
	vct[t].pb((Item){minn1 , minn2});
	int now1 = 0 , now2 = 0 , now3 = 0 , minn , pos;
	For(i , 1 , vct[t * 3].size() + vct[t * 3 + 1].size() + vct[t * 3 + 2].size())
	{
		minn = INF;
		if (now1 < vct[t * 3].size())
			if (minn > vct[t * 3][now1].x)
			{
				minn = vct[t * 3][now1].x;
				pos = 0;
			}
		if (now2 < vct[t * 3 + 1].size())
			if (minn > vct[t * 3 + 1][now2].x)
			{
				minn = vct[t * 3 + 1][now2].x;
				pos = 1;
			}
		if (now3 < vct[t * 3 + 2].size())
			if (minn > vct[t * 3 + 2][now3].x)
			{
				minn = vct[t * 3 + 2][now3].x;
				pos = 2;
			}
		if (pos == 0)
		{
			vct[t].pb(vct[t * 3 + pos][now1]);
			++now1;
		}
		else
		if (pos == 1)
		{
			vct[t].pb(vct[t * 3 + pos][now2]);
			++now2;
		}
		else
		{
			vct[t].pb(vct[t * 3 + pos][now3]);
			++now3;
		}
	}
}

