	}
}

node upit_par (int cvor, int from, int to, int low, int high) {
	if (from<=low && high<=to) return par[cvor];
	if (to<low || high<from) return par[0];
	return spoji(upit_par(cvor*2, from, to, low, (low+high)/2), upit_par(cvor*2+1, from, to, (low+high)/2+1, high));
}

node upit_odd (int cvor, int from, int to, int low, int high) {
	//cout << cvor << " " << from << " " << to << " " << low << " " << high << endl;
	if (from<=low && high<=to) return odd[cvor];
	if (to<low || high<from) return odd[0];
	return spoji(upit_odd(cvor*2, from, to, low, (low+high)/2), upit_odd(cvor*2+1, from, to, (low+high)/2+1, high));
}

