inline void update(node_t *node){
    for(int i=0; i<2; i++){
        if(a[node->chd[0]->tin[i^node->chd[0]->rev]]<a[node->chd[1]->tin[i^node->chd[1]->rev]]){
            node->tin[i^node->rev]=node->chd[0]->tin[i^node->chd[0]->rev];
        }else{
            node->tin[i^node->rev]=node->chd[1]->tin[i^node->chd[1]->rev];
        }
    }
}

void build(node_t **hook, const int lef, const int rig){
    node_t *node=tail++;
    node->lef=lef;
    node->rig=rig;
    node->rev=0;
    node->cov=0;
    if(lef==rig){
        int bin=lef&1;
        node->tin[bin]=lef;
        node->tin[bin^1]=n;
        node->chd[0]=NULL;
        node->chd[1]=NULL;
    }else{
        const int mid=(lef+rig)>>1;
        build(&node->chd[0], lef, mid);
        build(&node->chd[1], mid+1, rig);
        update(node);
    }
    *hook=node;
}

void flip(node_t *node, const int lef, const int rig){
    if(lef<=node->lef && node->rig<=rig){
        node->rev^=1;
        node->cov^=1;
    }else{
        if(node->cov){
            flip(node->chd[0], 0, n-1);
            flip(node->chd[1], 0, n-1);
            node->cov=0;
        }
        if(lef<=node->chd[0]->rig){
            flip(node->chd[0], lef, rig);
        }
        if(rig>=node->chd[1]->lef){
            flip(node->chd[1], lef, rig);
        }
        update(node);
    }
}

void remove(node_t *node, const int pos){
    if(node->lef==node->rig){
        int bin=node->lef&1;
        node->tin[bin]=n;
    }else{
        if(node->cov){
            flip(node->chd[0], 0, n-1);
            flip(node->chd[1], 0, n-1);
            node->cov=0;
        }
        if(pos<=node->chd[0]->rig){
            remove(node->chd[0], pos);
        }else{
            remove(node->chd[1], pos);
        }
        update(node);
    }
}

int query(node_t *node, const int lef, const int rig, const int bin){
    if(lef<=node->lef && node->rig<=rig){
        return node->tin[bin^node->rev];
    }else{
        if(node->cov){
            flip(node->chd[0], 0, n-1);
            flip(node->chd[1], 0, n-1);
            node->cov=0;
        }
        int foo=n;
        if(lef<=node->chd[0]->rig){
            int cur=query(node->chd[0], lef, rig, bin);
            if(a[foo]>a[cur])foo=cur;
        }
        if(rig>=node->chd[1]->lef){
            int cur=query(node->chd[1], lef, rig, bin);
            if(a[foo]>a[cur])foo=cur;
        }
        return foo;
    }
}

