			q.push(Node(now.ansl + 1, now.ansr - 1));
		if (now.l < now.ansl - 1)
			q.push(Node(now.l, now.ansl - 1));
		if (now.ansr + 1 < now.r)
			q.push(Node(now.ansr + 1, now.r));
	}
