class seg {
public:
  struct node {
    node *l;
    node *r;
    int bmx;
    int wmx;
    int rev;

    void update() {
      bmx=min(l->bmx,r->bmx);
      wmx=min(l->wmx,r->wmx);
    }
    void set() {
      rev^=1;
      swap(bmx,wmx);
    }
    void push() {
      if (rev) {
        l->set();
        r->set();
        rev=0;
      }
    }
  };

  arr<node> tree;

  void build(int ll,int rr,int o=1) {
    node *t=&tree[o];
    t->rev=0;
    if (ll==rr) {
      if (ll&1) {
        t->bmx=a[ll];
        t->wmx=n;
      } else {
        t->wmx=a[ll];
        t->bmx=n;
      }
      return;
    }
    t->l=&tree[o+o];
    t->r=&tree[o+o+1];
    int mid=(ll+rr)/2;
    build(ll,mid,o+o);
    build(mid+1,rr,o+o+1);
    t->update();
  }

  int n;

  void flip(int l,int r,int ll,int rr,node *t) {
    if (ll!=rr) {
      t->push();
    }
    if (ll>=l&&rr<=r) {
      t->set();
      return;
    }
    int mid=(ll+rr)/2;
    if (l<=mid) {
      flip(l,r,ll,mid,t->l);
    }
    if (r>mid) {
      flip(l,r,mid+1,rr,t->r);
    }
    t->update();
  }

  void remove(int x,int ll,int rr,node *t) {
    if (ll!=rr) {
      t->push();
    }
    if (ll==rr) {
      t->bmx=t->wmx=n;
      return;
    }
    int mid=(ll+rr)/2;
    if (x<=mid) {
      remove(x,ll,mid,t->l);
    }
    if (x>mid) {
      remove(x,mid+1,rr,t->r);
    }
    t->update();
  }

  void flip(int l,int r) {
    flip(l,r,0,n-1,&tree[1]);
  }

  void remove(int x) {
    remove(x,0,n-1,&tree[1]);
  }

  int query(node *o,int ll,int rr,int l,int r) {
    if (ll!=rr) {
      o->push();
    }
    if (ll>=l&&rr<=r) {
      return o->bmx;
    }
    int res=n;
    int mid=(ll+rr)/2;
    if (l<=mid) {
      res=min(res,query(o->l,ll,mid,l,r));
    }
    if (r>mid) {
      res=min(res,query(o->r,mid+1,rr,l,r));
    }
    o->update();
    return res;
  }

  int query(int l,int r) {
    return query(&tree[1],0,n-1,l,r);
  }

  seg(int x) {
    n=x;
    tree.resize(x<<2);
    build(0,n-1);
  }
};

