node* create(int *arr, int L, int R)
{
	if(L == R) return new node(arr[L], NULL, NULL);
	node *x = create(arr, L, (L+R)/2);
	node *y = create(arr, (L+R)/2+1, R);
	return new node(min(x->val, y->val), x, y);
}
int ask(node *p, int L, int R, int i, int j)
{
	if(i> R || j< L) return 1e9;
	if(i<= L && R<= j) return p->val;
	int x = ask(p->left, L, (L+R)/2, i, j);
	int y = ask(p->right, (L+R)/2+1, R, i, j);
	return min(x, y);
}
void update(node *p, int L, int R, int dat, int to)
{
	if(L> dat || R< dat) return;
	if(L == R)
	{
		p->val = to;
		return;
	}
	update(p->left, L, (L+R)/2, dat, to);
	update(p->right, (L+R)/2+1, R, dat, to);
	p->val = min(p->left->val, p->right->val);
}
