struct LazySegmentTree {
    struct Node {
        Node operator*(const Node& o) const {
            return { { min(m[l], o.m[o.l]), min(m[l ^ 1], o.m[o.l ^ 1]) }, 0 };
        }
        pair<int, int> m[2];
        int l;
    };
    static const Node e;

    LazySegmentTree(int n) : n(n) {
        for (m = 2; m < n; m *= 2); // m >= n
        t = vector<Node>(m + n + n % 2, e);
    }
    Node *data() {
        return &t[m];
    }
    void build() {
        for (int i = (n - 1 + m) / 2; i > 0; i--) {
            t[i] = t[i * 2] * t[i * 2 + 1];
        }
    }
    void update(int i, const Node& o) {
        i += m;
        for (int k = 30; k > 0; k--) {
            int j = i >> k;
            if (j == 0) continue;
            propagate(j);
        }
        for (t[i] = o; i /= 2, i > 0;) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    Node query(int l, int r, int i = 1, int il = 0, int ir = -1) {
        if (ir < 0) ir = m;
        if (r - l == ir - il) return t[i];
        propagate(i);
        int im = (il + ir) / 2;
        Node o = e;
        if (l < im) o = o * query(l, min(r, im), i * 2 + 0, il, im);
        if (im < r) o = o * query(max(im, l), r, i * 2 + 1, im, ir);
        return o;
    }
    void lazy(int l, int r, int u, int i = 1, int il = 0, int ir = -1) {
        if (ir < 0) ir = m;
        if (r - l <= 0) return;
        if (r - l == ir - il) {
            t[i].l ^= u; // このあとで先祖に反映させる
            if (i == 1) propagate(i);
            return;
        }
        propagate(i);
        int im = (il + ir) / 2;
        if (l < im) lazy(l, min(r, im), u, i * 2 + 0, il, im);
        if (im < r) lazy(max(im, l), r, u, i * 2 + 1, im, ir);
        t[i] = t[i * 2] * t[i * 2 + 1]; // 子孫ノードが遅延評価の値を持っていても反映されている
    }
    void propagate(int i) {
        if (t[i].l == 0) return;
        if (i >= m) throw;
        t[i * 2 + 0].l ^= t[i].l;
        t[i * 2 + 1].l ^= t[i].l;
        swap(t[i].m[0], t[i].m[1]);
        t[i].l = 0;
    }
    vector<Node> t;
    int n, m;
};
const LazySegmentTree::Node LazySegmentTree::e = { { { 1 << 30, 0 }, { 1 << 30, 0 } }, 0 };

struct SegmentTree {
    struct Node {
        Node operator*(const Node& o) const {
            return { min(v, + o.v) };
        }
        int v;
    };
    static const Node e;

    SegmentTree(int n) : n(n) {
        for (m = 2; m < n; m *= 2); // m >= n
        t = vector<Node>(m + n + n % 2, e);
    }
    void update(int i, const Node& o) {
        for (t[i += m] = o; i /= 2, i > 0;) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    Node query(int l, int r) {
        Node o[2] = { e, e };
        for (l += m, r += m; l < r; l /= 2, r /= 2) {
            if (r & 1) o[1] = t[--r] * o[1];
            if (l & 1) o[0] = o[0] * t[l++];
        }
        return o[0] * o[1];
    }
    vector<Node> t;
    int n, m;
};
