const int INF = 1E9;

class SegmentTreeNode {
public:
	int L, R, val;
	SegmentTreeNode *left, *right;
	SegmentTreeNode(int L, int R) {
		this->L = L;
		this->R = R;
		this->left = NULL;
		this->right = NULL;
		this->val = INF;
	}
};

SegmentTreeNode * build(int L, int R) {
	SegmentTreeNode * crt = new SegmentTreeNode(L, R);
	if (L == R) return crt;
	int M = L + (R - L) / 2;
	if (M >= L) crt->left = build(L, M);
	if (M + 1 <= R) crt->right = build(M + 1, R);
	return crt;
}

void destroy(SegmentTreeNode * root) {
	if (root->left != NULL) destroy(root->left);
	if (root->right != NULL) destroy(root->right);
	delete root;
	return;
}

ll query(int L, int R, SegmentTreeNode * root) {
	if (root == NULL) return INF;
	int l = root->L;
	int r = root->R;
	if (L == l && R == r) return root->val;
	int m = root->L + (root->R - root->L) / 2;
	if (R <= m) return query(L, R, root->left);
	if (L >= m + 1) return query(L, R, root->right);
	int vl = query(L, m, root->left);
	int vr = query(m + 1, R, root->right);
	return min(vl, vr);
}

void update(int idx, int val, SegmentTreeNode * root) {
	if (root == NULL) return;
	root->val = min(root->val, val);
	int mid = root->L + (root->R - root->L) / 2;
	if (root->L <= idx && idx <= mid) update(idx, val, root->left);
	if (mid + 1 <= idx && idx <= root->R) update(idx, val, root->right);
	return;
}

int DP[200010];

int R[200010];

