int main() {
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    SegmentTreeNode * T[2];
    T[0] = build(0, N-1);
    T[1] = build(0, N-1);
    for (int i = 0;i < N;i++) {
    	cin >> R[i];
    	DP[R[i]] = i;
    	update(i, R[i], T[i & 1]);
    }
    priority_queue<node> P;
    node p;
    p.l = 0;
    p.r = N - 1;
    p.num = query(0, N - 1, T[0]);
    P.push(p);
    vector<int> sol;
    while (P.size() > 0) {
    	p = P.top();
    	P.pop();
    	int s = p.l;
    	int b = p.r;
    	int idx = DP[p.num];
    	int ot = query(idx + 1, b, T[(idx + 1) & 1]);
    	int idx2 = DP[ot];
    	sol.push_back(p.num);
    	sol.push_back(ot);
    	if (s < idx - 1) {
    		node q;
    		q.l = s;
    		q.r = idx - 1;
    		q.num = query(q.l, q.r, T[q.l & 1]);
    		P.push(q);
    	}
    	if (idx + 1 < idx2 - 1) {
    		node q;
    		q.l = idx + 1;
    		q.r = idx2 - 1;
    		q.num = query(q.l, q.r, T[q.l & 1]);
    		P.push(q);
    	}
    	if (idx2 + 1 < b) {
    		node q;
    		q.l = idx2 + 1;
    		q.r = b;
    		q.num = query(q.l, q.r, T[q.l & 1]);
    		P.push(q);
    	}
    }
    for (int i = 0;i < sol.size();i++) {
    	if (i != 0) cout << ' ';
    	cout << sol[i];
    }
    cout << endl;
    return 0;
}

