	ans[s].first=a[x];ans[s].second=a[y];
	if (l<=x-1) b[t].push_back(s+1);
	work(l,x-1);
	if (x+1<=y-1) b[t].push_back(s+1);
	work(x+1,y-1);
	if (y+1<=r) b[t].push_back(s+1);
	work(y+1,r);
}
