    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int N = 200005;
const int inf = 1e9;

int a[2][N * 4], b[N], n;

void build(int l, int r, int p) {
  if (l == r) {
    a[0][p] = a[1][p] = inf;
    if (l & 1) {
      a[1][p] = b[l];
    } else {
      a[0][p] = b[l];
    }
    return;
  }
  int m = (l + r) / 2;
  build(l, m, p * 2);
  build(m + 1, r, p * 2 + 1);
  a[0][p] = min(a[0][p * 2], a[0][p * 2 + 1]);
  a[1][p] = min(a[1][p * 2], a[1][p * 2 + 1]);
}

pair<int, int> query(int l, int r, int p, int L, int R) {
  //  cout << l << " " << r << endl;
  if (l >= L && r <= R) {
    return {a[0][p], a[1][p]};
  }
  int m = (l + r) / 2;
  auto ret = make_pair(inf, inf);
  if (L <= m) {
    auto t = query(l, m, p * 2, L, R);
    ret.first = min(ret.first, t.first);
    ret.second = min(ret.second, t.second);
  }
  if (m + 1 <= R) {
    auto t = query(m + 1, r, p * 2 + 1, L, R);
    ret.first = min(ret.first, t.first);
    ret.second = min(ret.second, t.second);
  }
  return ret;
}

void update(int l, int r, priority_queue<pair<int, pair<int, int>>>& q) {
  if (l > r) return;
  auto ret = query(1, n, 1, l, r);
  if (l & 1) {
    q.push({-ret.second, {l, r}});
  } else {
    q.push({-ret.first, {l, r}});
  }
}

int main(int argc, char *argv[]) {
  cin >> n;
  vector<int> a(n + 1), c;
  for (int i = 1; i <= n; i++) {
    cin >> b[i];
    a[b[i]] = i;
  }
  build(1, n, 1);
  auto ret = query(1, n, 1, 1, n);
  priority_queue<pair<int, pair<int, int>>> q;
  update(1, n, q);
  while (!q.empty()) {
    auto u = q.top();
    q.pop();
    c.push_back(-u.first);
    int p1 = a[-u.first], l = u.second.first, r = u.second.second;
    auto tt = query(1, n, 1, p1 + 1, r);
    int p2;
    if (l & 1) {
      c.push_back(tt.first);
      p2 = a[tt.first];
    } else {
      c.push_back(tt.second);
      p2 = a[tt.second];
    }
    //    cout << p1 << " " << p2 << endl;
    update(l, p1 - 1, q);
    update(p1 + 1, p2 - 1, q);
    update(p2 + 1, r, q);
  }
  for (auto x : c) {
    cout << x << " ";
  }
  return 0;
}

