void build(int root,int l,int r)
{
	seg[root].l=l;seg[root].r=r;
	if (l==r)
	{
		seg[root].odd=2100000000;seg[root].even=a[l];
		if (l&1) swap(seg[root].odd,seg[root].even);
		return;
	}
	int mid=(l+r)>>1;
	build(root<<1,l,mid);build((root<<1)+1,mid+1,r);
	seg[root].odd=min(seg[root<<1].odd,seg[(root<<1)+1].odd);
	seg[root].even=min(seg[root<<1].even,seg[(root<<1)+1].even);
}
int query(int root,int l,int r,int p)
{
	if ((seg[root].l>r)||(l>seg[root].r)) return 2100000000;
	if ((l<=seg[root].l)&&(seg[root].r<=r)) return p?seg[root].odd:seg[root].even;
	return min(query(root<<1,l,r,p),query((root<<1)+1,l,r,p));
}
