#include <vector>
using namespace std;

int N;
vector<int> p;

void Sort(int l, int r, queue<int> &q) {
  if (l == r) {
    return;
  }

  int minE = N + 1;
  int minEI = l - 1;
  for (int i = l; i < r; i += 2) {
    if (p[i] < minE) {
      minE = p[i];
      minEI = i;
    }
  }
  q.push(minE);

  int minO = N + 1;
  int minOI = minEI;
  for (int i = minEI + 1; i < r; i += 2) {
    if (p[i] < minO) {
      minO = p[i];
      minOI = i;
    }
  }
  q.push(minO);

  queue<int> qs[3];
  Sort(l, minEI, qs[0]);
  Sort(minEI + 1, minOI, qs[1]);
  Sort(minOI + 1, r, qs[2]);

  while (true) {
    int min = N + 1;
    int minJ = -1;
    for (int j = 0; j < 3; j++) {
      if (qs[j].empty()) {
	continue;
      }

      if (qs[j].front() < min) {
	min = qs[j].front();
	minJ = j;
      }
    }

    if (minJ == -1) {
      break;
    }

    q.push(min);
    qs[minJ].pop();
    q.push(qs[minJ].front());
    qs[minJ].pop();
  }
}

int main() {
  cin >> N;

  p.resize(N);
  for (int i = 0; i < N; i++) {
    cin >> p[i];
  }

  queue<int> q;
  Sort(0, N, q);

  int tmp = q.front();
  q.pop();
  while(!q.empty()) {
    cout << tmp << ' ';
    tmp = q.front();
    q.pop();
  }
  cout << tmp << endl;

  return 0;
}

