node merge(node a,node b)
{
	node r;
	r.sz=a.sz+b.sz;
	r.mn=min(a.mn,b.mn);
	if(a.sz%2==1)
	{
		if(a.omn<b.emn)
		{
			r.omn=a.omn;
			r.romn=min(a.romn,b.omn);
		}
		else
		{
			r.omn=b.emn;
			r.romn=b.remn;
		}
		if(a.emn<b.omn)
		{
			r.emn=a.emn;
			r.remn=min(a.remn,b.emn);
		}
		else
		{
			r.emn=b.omn;
			r.remn=b.romn;
		}
	}
	else
	{
		if(a.omn<b.omn)
		{
			r.omn=a.omn;
			r.romn=min(a.romn,b.emn);
		}
		else
		{
			r.omn=b.omn;
			r.romn=b.romn;
		}
		if(a.emn<b.emn)
		{
			r.emn=a.emn;
			r.remn=min(a.remn,b.omn);
		}
		else
		{
			r.emn=b.emn;
			r.remn=b.remn;
		}
	}
	return r;
} 

void build(int lo,int hi,int i)
{
  if(lo==hi)
  {
  	tree[i].omn=tree[i].mn=a[lo];
  	tree[i].emn=tree[i].romn=tree[i].remn=1e9+7;
  	tree[i].sz=1;
  	return;
  }	
  int mid=(lo+hi)/2;
  build(lo,mid,2*i);
  build(mid+1,hi,2*i+1);
  tree[i]=merge(tree[2*i],tree[2*i+1]);
}


node query(int left,int right,int l,int r,int i)
{
 if(left>=l&&right<=r)
 return tree[i];
 int mid=(left+right)/2;
 node t1,t2;
 if(r<=mid)
 return query(left,mid,l,r,2*i);
 if(l>mid)
 return query(mid+1,right,l,r,2*i+1);
 t2=query(mid+1,right,mid+1,r,2*i+1);
 t1=query(left,mid,l,mid,2*i);

 return merge(t1,t2);
}


