pair<int, int> calc(int l, int r, int p, int q, int k) {
	if (r < p || q < l)return mkp(0xE869120, -1);
	if (p <= l&&r <= q)return tree[k][p & 1];
	return min(calc(l, (l + r) / 2, p, q, k * 2), calc((l + r) / 2 + 1, r, p, q, k * 2 + 1));
}

void dfs(int l, int r) {
	if (l > r)return;
	int L = calc(0, (1 << 18) - 1, l, r, 1).second;
	int R = calc(0, (1 << 18) - 1, L + 1, r, 1).second;
	q.push(mkp(mkp(p[L], p[R]), mkp(L + 1, R - 1)));
	dfs(l, L - 1);
	dfs(R + 1, r);
}

