            x = even.get(l, r);
            y = odd.get(l, r);
        } else {
            x = odd.get(l, r);
            y = even.get(l, r);
        }

        int u = x.sc, v = y.sc;
        if(l + 1 < u) pque.push(f(l, u));
        if(u + 1 < v) pque.push(f(u + 1, v));
        if(v + 1 < r) pque.push(f(v + 1, r));
    }

    for(auto& z: ans) {
        cout << z << " ";
    }
    cout << endl;
}

