void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    V<ll> plist; llina(plist, n);

    ll rmap[200005];
    rep (i, n) rmap[plist[i]] = i;

    SegmentTree<ll> tree_all(n, 1e18, minll);
    SegmentTree<ll> tree_odd(n, 1e18, minll);
    SegmentTree<ll> tree_even(n, 1e18, minll);

    rep (i, n) {
        tree_all.update(i, plist[i]);
        if (i & 1LL) tree_odd.update(i, plist[i]);
        else tree_even.update(i, plist[i]);
    }

    S V<ll> ans;
    priority_queue_incr<t3> q;
    q.push(t3(1, 0, n));

    while (!q.empty()) {
        auto item = q.top(); q.pop();
        ll minval = get<0>(item);
        ll begin = get<1>(item);
        ll end = get<2>(item);

        assert(!((end - begin) & 1LL));
        assert(minval < 1e17);

        ll minidx = rmap[minval];
        ll minval2nd = 1e18;
        ll minidx2nd = 1e18;

        debug_printf("begin=%lld end=%lld minidx=%lld minval=%lld\n",
                     begin, end, minidx, minval);

        if ((minidx - begin) & 1LL) {
            if (minidx & 1LL) minval2nd = tree_even.query(begin, minidx);
            else minval2nd = tree_odd.query(begin, minidx);
            assert(minval2nd < 1e17);
            minidx2nd = rmap[minval2nd];
            ans.pb(minval2nd);
            ans.pb(minval);
        }
        else {
            if (minidx & 1LL) minval2nd = tree_even.query(minidx + 1LL, end);
            else minval2nd = tree_odd.query(minidx + 1LL, end);
            assert(minval2nd < 1e17);
            minidx2nd = rmap[minval2nd];
            ans.pb(minval);
            ans.pb(minval2nd);
        }

        debug_printf("  minidx2nd=%lld minval2nd=%lld\n",
                     minidx2nd, minval2nd);

        ll idx1 = min(minidx, minidx2nd);
        ll idx2 = max(minidx, minidx2nd);

        if (idx1 - begin >= 2LL) {
            ll nmin = tree_all.query(begin, idx1);
            q.push(t3(nmin, begin, idx1));
        }
        if (idx2 - (idx1 + 1) >= 2LL) {
            ll nmin = tree_all.query(idx1 + 1, idx2);
            q.push(t3(nmin, idx1 + 1, idx2));
        }
        if (end - (idx2 + 1) >= 2LL) {
            ll nmin = tree_all.query(idx2 + 1, end);
            q.push(t3(nmin, idx2 + 1, end));
        }
    }

