template <typename T>
class Rmq {
public:


	int n;
	vector<T> dat;

	void init(int _n) {
		n = 1;
		while (n < _n) {
			n *= 2;
		}
		dat.resize(2 * n);
		rep(i, n * 2 - 1)//n*2-1まで　nまでではない！
			dat[i] = INF;
	}

	void update(int k, int x) {
		k += n - 1;
		dat[k] = x;
		while (k > 0) {
			k = (k - 1) / 2;//k/2でない注意
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}

	}

	int find(int a, int b, int k, int l, int r) {
		if (a <= l && r <= b)
			return dat[k];
		if (r <= a || b <= l)//等号が必要
			return INF;
		else {
			int x1, x2;
			x1 = find(a, b, k * 2 + 1, l, (l + r) / 2);//ここはl,r
			x2 = find(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(x1, x2);
		}
	}
};
