vector<int> A;
vector<int> Aindex;//Aの値からインデックスをえる。
segment_base<int> seg0,seg1;//偶数、奇数0-index

vector< PII > f(int L,int R){//[L,R)
	int res1,res2;
	int res1_Index,res2_Index;
	if( L&1 ){//奇数番目から始まる場合
		res1 = seg1.query(L>>1,R>>1);
		res1_Index = Aindex[res1];
		seg1.update(res1_Index>>1,INF);

		res2 = seg0.query( (res1_Index>>1) + 1,(R>>1) + 1);
		res2_Index = Aindex[res2];
		seg0.update(res2_Index>>1 ,INF);
	}else{
		res1 = seg0.query( (L>>1),(R>>1) );
		res1_Index = Aindex[res1];
		seg0.update(res1_Index>>1 ,INF);

		res2 = seg1.query( (res1_Index>>1),(R>>1) );
		res2_Index = Aindex[res2];
		seg1.update(res2_Index>>1, INF);
	}

	vector< vector<PII> > B(3);
	vector<int> Bsize(3,0);
	vector<int> pos(3,0);
	int spL,spR;//分割地点
	spL = res1_Index;
	spR = res2_Index;
	if( L < spL ){
		B[0] = f(L,spL);
		Bsize[0] = B[0].size();
	}
	if( spL+1 < spR ){
		B[1] = f(spL+1,spR);
		Bsize[1] = B[1].size();
	}
	if( spR+1 < R ){
		B[2] = f(spR+1,R);
		Bsize[2] = B[2].size();
	}

	vector<PII> ans( (R-L)/2 );
	int posAns = 0;
	PII pii(res1,res2);
	ans[posAns] = pii;
	posAns = 1;


	while( pos[0]<Bsize[0] || pos[1]<Bsize[1] || pos[2]<Bsize[2] ){
		PII res(INF,INF);
		int num = 0;
		for(int i=0;i<3;++i){
			if( pos[i] >= Bsize[i] ) continue;
			PII now = B[i][ pos[i] ];
			if( now < res ){
				res = now;
				num = i;
			}
		}
		ans[posAns] = res;
		++posAns;
		++pos[num];
	}

	return ans;
}
void solve(){
	int N;
	cin >> N;
	A.resize(N);
	Aindex.resize(N+1);
	seg0.init(N/2,INF);
	seg1.init(N/2,INF);

	for(int i=0;i<N;++i){
		cin >> A[i];
		Aindex[ A[i] ] = i;
		if( i & 1 ){
			seg1.update(i/2,A[i]);
		}else{
			seg0.update(i/2,A[i]);
		}
	}

	vector<PII> ans = f(0,N);
	for(int i=0;i< (N/2) ;++i){
		if(i)cout << " ";
		cout << ans[i].first << " " << ans[i].second;
	}
	cout << endl;
}

