const int MAX_N = 1 << 18;
int n;
template<class V, int NV> struct SegTree{
    V comp(V l, V r) {return min(l, r);};

    vector<V> dat;

    SegTree() {
        dat = vector<V>(MAX_N, {INF, INF});
        n = 1;
        while(n < NV) n *= 2;
        rep(i, 2 * n - 1) dat[i] = {INF, INF};
    }

    // k番目の値(0-indexed)をaに変更
    void update(int k, V a) {
        k += n - 1;
        dat[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = comp(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    // [a, b)の最小値を探す．
    V query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return {INF, INF};
        if(a <= l && r <= b) return dat[k];
        else {
            V vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            V vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(vl, vr);
        }
    }
};
int N, p[200010];
SegTree<pair<int, int>, 1 << 17> st1, st2;

vector<int> E[200010];
int pR[200010];

void dfs(int L, int R, int pa = 0) {
    //cout <<"*"<< L << " " << R << endl;
    pair<int, int> mi1, mi2;
    // 区間が2であれば、ペアが確定
    if (L + 1 == R) {
        E[pa].push_back(p[L]);
        pR[p[L]] = p[R];
        return;
    }

    if (L % 2 == 0) {
        mi1 = st1.query(L, R, 0, 0, n);
        mi2 = st2.query(mi1.second + 1, R + 1, 0, 0, n);
    } else {
        mi1 = st2.query(L, R, 0, 0, n);
        mi2 = st1.query(mi1.second + 1, R + 1, 0, 0, n);
    }
    int i = mi1.second;
    int j = mi2.second;
    //cout << mi1.first << " " << mi2.first << endl;
    //ペアが決まったので、代入
    E[pa].push_back(mi1.first);
    pR[mi1.first] = mi2.first;
    //cout << "OK" << endl;
    if (L != i) dfs(L, i - 1, mi1.first);
    if (i + 1 != j) dfs(i + 1, j - 1, mi1.first);
    if (R != j) dfs(j + 1, R, mi1.first); 

}

