	int l, r, L, R;
	inline void calc() {;
		L = T[l & 1].query(l, r);
		//printf("%d %d %d\n", l, r, L);
		R = T[(l & 1) ^ 1].query(tp[L], r);
	//	printf("%d %d\n", L, R);
	}
	inline bool operator < (const Node& rhs) const {
		return L > rhs.L;
	}
}; priority_queue<Node> Q;
