struct Tree{
	int left,right,val;
	Tree *left_child,*right_child;
}t[2][N*4];

int n,m[2];
map<int,int> elenum;

void update(Tree *pos){
	pos->val=min(pos->left_child->val,pos->right_child->val);
}

void build(Tree *pos,Tree *root,int &M,int x,int y){
	pos->left=x;pos->right=y;pos->val=INT_MAX;
	if(x==y) return;
	int mid=(x+y)>>1;
	pos->left_child=root+M;M++;
	pos->right_child=root+M;M++;
	build(pos->left_child,root,M,x,mid);
	build(pos->right_child,root,M,mid+1,y);
}

void def(Tree *pos,int x,int val){
//	printf("%d %d\n",pos->left,pos->right);
	if(pos->left>x||pos->right<x) return;
	if(pos->left==pos->right&&pos->left==x){
		pos->val=val;
//		printf("%d %d\n",x,val);
		return;
	}
	def(pos->left_child,x,val);
	def(pos->right_child,x,val);
	update(pos);
}

int query(Tree *pos,int x,int y){
	if(pos->left>=x&&pos->right<=y) return pos->val;
	if(pos->left>y||pos->right<x) return INT_MAX;
	return min(query(pos->left_child,x,y),query(pos->right_child,x,y));
}

