void merge(int a, int b) {
	a = find(a), b = find(b);
	if (a != b) {
		if (sz[a] < sz[b])
			swap(a, b);
		sz[a] += sz[b];
		pp[b] = a;
	}
}

int get_left(int i) {
	if (i == 0) return -1;
	if(sz[find(i-1)] > 1)
	return i - sz[find(i - 1)] - 1;
	else return i - 1;
}

int get_right(int i) {
	if (i == n - 1) return n;
	if(sz[find(i+1)] > 1)
	return i + sz[find(i + 1)] + 1;
	else return i + 1;
}

