#include <bits/stdc++.h>
#define REP(i,n) for (int i=0;i<(n);i++)
#define RREP(i,n) for (int i=(n)-1;i>=0;i--)
using namespace std;

int N;
vector<long long> p;

vector<long long> solve(int start, int end) {
    vector<long long> retval;

    if (start >= end)
        return retval;

    assert((end - start) % 2 == 0);

    //Step1.先頭に来るものを選ぶ
    long long min_value = N + 1, min_index = 0, min_index2 = 0;
    for (int i = start; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index = i;
        }
    }
    retval.emplace_back(min_value);

    //Step2.2番目に来るものを選ぶ
    min_value = N + 1;
    for (int i = min_index + 1; i < end; i += 2) {
        if (min_value > p[i]) {
            min_value = p[i];
            min_index2 = i;
        }
    }
    retval.emplace_back(min_value);

    if (start - end == 2)
        return retval;

    //残ったところを再帰的に行う
    vector<long long> forward = solve(start, min_index);
    vector<long long> mid     = solve(min_index + 1, min_index2);
    vector<long long> back    = solve(min_index2 + 1, end);

    vector<pair<int, int> > pairs;
    for (int i = 0; i < forward.size(); i += 2) {
        pairs.emplace_back(forward[i], forward[i + 1]);
    }
    for (int i = 0; i < mid.size(); i+= 2) {
        pairs.emplace_back(mid[i], mid[i + 1]);
    }
    for (int i = 0; i < back.size(); i += 2) {
        pairs.emplace_back(back[i], back[i + 1]);
    }

    sort(pairs.begin(), pairs.end());

    for (auto p : pairs) {
        retval.push_back(p.first);
        retval.push_back(p.second);
    }

    return retval;
}

