#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
#define INF (1<<20)
typedef pair<ll, ll> pll;
vector<ll> even_p, odd_p;
vector<pll> even, odd;
ll even_n, odd_n;

/* RMQ begin */
//dat{ val , index }
int init(int n_,vector<pll>& dat) {
	int n = 1;
	while (n < n_) n *= 2;
	dat.resize(2 * n - 1);
	for (int i = 0; i < 2 * n - 1;i++) dat[i] = { INF,INF };
	return n;
}

// k = p_index
void update(int k, int a,int n,vector<pll>& dat) {
	int temp = k;
	k /= 2;
	k += n - 1;
	dat[k] = { a, temp};

	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
// [a,b)の最小値
pll query(int a, int b, int k, int l, int r,vector<pll>& dat) {
	// [a,b)と[l,r)が交差しなければ,INT_MAX
	if (r <= a || b <= l) return{ INF,INF };
	// [a,b)が[l,r)を完全に含んでいれば,この節点の値
	if (a <= l && r <= b) return dat[k];
	else {
		pll vl = query(a, b, k * 2 + 1, l, (l + r) / 2, dat);
		pll vr = query(a, b, k * 2 + 2, (l + r) / 2, r, dat);
		return min(vl, vr);
	}
}
/* RMQ end */

struct Node {
	// [l,r)
	int l, r;
	// even(odd) index 
	int a, b;

	int Min_val, Min_index;
	Node(int l, int r) :l(l), r(r) {
		if (l % 2 == 0) {
			a = l / 2;
			b = (r + 1) / 2;
			auto x = query(a, b, 0, 0, even_n, even);
			Min_val = x.first; Min_index = x.second;
		}
		else {
			a = l/ 2;
			b = r/ 2;
			auto x = query(a, b, 0, 0, odd_n, odd);
			Min_val = x.first; Min_index = x.second;
		}
	}

	bool operator <(const Node&o) const {
		// 昇順
		return o.Min_val < Min_val;
	}
};

int main() {
	cin.tie(0); ios::sync_with_stdio(false);
	int N; cin >> N;
	for (int i = 0; i < N;i++) {
		int p; cin >> p;
		if (i % 2 == 0) even_p.push_back(p);
		else odd_p.push_back(p);
	}

	// even/odd initialize
	even_n = init(even_p.size(), even);
	odd_n = init(odd_p.size(), odd);

	for (int i = 0; i < N;i++) {
		if (i % 2 == 0) update(i, even_p[i / 2], even_n, even);
		else update(i, odd_p[i / 2], odd_n, odd);
	}

	// solve
	priority_queue<Node> pq;
	pq.push(Node(0, N));

	for (int i = 0; i < N / 2;i++) {
		auto x = pq.top(); pq.pop();
		auto y = Node(x.Min_index + 1, x.r);

		cout << x.Min_val << " " << y.Min_val << " ";

		if(x.l != x.Min_index)pq.push(Node(x.l, x.Min_index));
		if(x.Min_index+1 != y.Min_index)pq.push(Node(x.Min_index + 1, y.Min_index));
		if(y.Min_index+1 != y.r)pq.push(Node(y.Min_index + 1, y.r));
	}
	cout << endl;
}

#include<bits/stdc++.h>
using namespace std;


struct SegmentTree{
    vector<int> Seg;
	int n;

	void build(vector<int>& v, int m){
		n = m;
        Seg = vector<int> (4*n,1e6);
		build(v, 1, 0, n);
	}
	void build( vector<int>& v, int id,int left, int right){
		if(left + 1 >= right){
			Seg[id] = v[left];
			return;
		}
		int mid = (left + right)/2;
		build(v, id * 2, left, mid);
		build(v, id * 2 + 1, mid, right);
		Seg[id] = min(Seg[id*2],Seg[id*2 + 1]);
	}

	int find(int x, int y){
		return find(x, y, 1, 0, n);
	}
	int find(int x, int y, int id, int left, int right){
		if(left >= y or right <= x){
			return 1e6;
		}
		if(left >= x and right <= y){
			return Seg[id];
		}
		int mid = (left + right)/2;
		return min(find(x, y, 2*id, left, mid), find(x, y, 2*id + 1, mid, right));
	}
};
SegmentTree S[2];

int pos[200010];
int s = 0;
int parent[200010];
pair<int,int> E[200010];
int leaf[200010];
int sz[200010];
int  getans(int l, int r, int p, int par) {
	if(l + 1 >= r) return 0;
	int curNode = s++;
	int x = S[p].find(l,r);
	int px = pos[x];
	int y = S[p^1].find(px + 1, r);
	int py = pos[y];

	E[curNode] = {x,y};
	if(par != -1) {
		leaf[par] = 0;
		parent[curNode] = par;
	}

	return 1 + getans(l, px, p, par) + getans(px + 1, py, p^1, curNode) + getans(py + 1, r, p, par);
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n;
	cin >> n;
	memset(leaf, -1, sizeof leaf);
	memset(parent, -1, sizeof parent);
	memset(sz, 0, sizeof sz);
	vector<int> odd(n, 1e6), even(n, 1e6);
	for(int i = 0; i < n; ++i){
		int x;
		cin >> x;
		pos[x] = i;
		if(i&1) even[i] = x;
		else odd[i] = x;
	}

	S[0].build(odd, n);
	S[1].build(even, n);
	getans(0,n,0,-1);

	int ans[n];
	priority_queue<pair<pair<int,int>,int>> pq;
	for(int i = 0; i < s; ++i) {
		if(leaf[i] == -1) pq.push({E[i],i});
	}
	int last = n-1;
	while(pq.size()) {
		auto x = pq.top();
		pq.pop();
		ans[last--] = x.first.second;
		ans[last--] = x.first.first;

		int pare = parent[x.second];
		if(pare != -1) {
			sz[pare]--;
			if(sz[pare] == 0) pq.push({E[pare], pare});
		}
	}

	for(int i = 0; i < n; ++i) cout << ans[i] << ' ';
	cout << endl;
}

