#include <bits/stdc++.h>
using namespace std;
#define PB push_back

const int N = 200000 + 5;

struct QAQ{
	int FF, SS, L, R;
	bool operator<(const QAQ &t)const{
		return tie(FF, L, R) < tie(t.FF, t.L, t.R);
	}
};

class SegTree{
	private:
		struct Node{
			QAQ v, flag;
		} nodes[4*N];
		int size;
		inline int lc(int x){return (x<<1)+1;}
		inline int rc(int x){return (x<<1)+2;}
		inline void push(int l, int r, int id){
			if(nodes[id].flag.FF == -1) return;
			if(r-l>1){
				nodes[lc(id)].flag = nodes[id].flag;
				nodes[rc(id)].flag = nodes[id].flag;
			}
			nodes[id].v = nodes[id].flag;
			nodes[id].flag.FF = -1;
		}
		inline void pull(int id){
			QAQ l=nodes[lc(id)].v;
			QAQ r=nodes[rc(id)].v;
			if(nodes[lc(id)].flag.FF != -1) l=nodes[lc(id)].flag;
			if(nodes[rc(id)].flag.FF != -1) r=nodes[rc(id)].flag;
			nodes[id].v = max(l, r);
		}
		void build(int l, int r, int id, QAQ arr[]){
			nodes[id].flag.FF = -1;
			if(r-l == 1){
				nodes[id].v=arr[l];
				return;
			}
			int mid=(l+r)>>1;
			build(l, mid, lc(id), arr);
			build(mid, r, rc(id), arr);
			nodes[id].v = max(nodes[lc(id)].v, nodes[rc(id)].v);
		}
		QAQ query(int ql, int qr, int l, int r, int id){
			if(qr <= l or r <= ql) return {0,0};
			push(l, r, id);
			if(ql <= l and r <= qr) return nodes[id].v;
			int mid=(l+r)>>1;
			return max(query(ql, qr, l, mid, lc(id)), \
				query(ql, qr, mid, r, rc(id)) );
		}
		void modify(int ql, int qr, int l, int r, QAQ v, int id){
			if(qr <= l or r <= ql) return;
			push(l, r, id);
			if(ql <= l and r <= qr){
				nodes[id].flag = v;
				return;
			}
			int mid=(l+r)>>1;
			modify(ql, qr, l, mid, v, lc(id));
			modify(ql, qr, mid, r, v, rc(id));
			pull(id);
		}
	public:
		void build(int n, QAQ arr[]){
			size=n;
			build(0, n, 0, arr);
		}
		QAQ query(int l, int r){
			return query(l, r, 0, size, 0);
		}
		void modify(int l, int r, QAQ v){
			modify(l, r, 0, size, v, 0);
		}
} seg;

int arr[N];
QAQ sm[N];
set<int> con;

int main(){
	ios_base::sync_with_stdio(0);cin.tie(0);
	int n; cin>>n;
	for(int i=0;i<n;i++){
		cin>>arr[i];
		con.insert(i);
	}
	for(int i=1;i<=n;i++) sm[i-1]={arr[i]+arr[i-1], i-1, arr[i-1], arr[i]};
	seg.build(n-1, sm);
	vector<int> ans;
	while(!con.empty()){
	 	QAQ x = seg.query(0, n-1);
	 	auto it1 = con.lower_bound(x.SS);
	 	auto it2 = con.upper_bound(x.SS);
	 	ans.PB(arr[*it2]);
