using namespace std;

const int INF = 100000000;

template<typename Monoid>
struct SegmentTree {
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n) sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x) {
        seg[k + sz] = x;
    }

    void build() {
        for(int k = sz - 1; k > 0; k--) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    void update(int k, const Monoid &x) {
        k += sz;
        seg[k] = x;
        while(k >>= 1) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    Monoid query(int a, int b) {
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1) L = f(L, seg[a++]);
            if(b & 1) R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const {
        return seg[k + sz];
    }
};

int main()
{
    int n;
    cin >> n;
    int p[200002], q[200002];
    SegmentTree<int> sego(n, [](int a, int b){return min(a, b);}, INF);
    SegmentTree<int> sege(n, [](int a, int b){return min(a, b);}, INF);
    for(int i = 0; i < n; i++){
        cin >> p[i];
        p[i]--;
        if(i % 2) sego.set(i, p[i]);
        else sege.set(i, p[i]);
        q[p[i]] = i;
    }
    sego.build();
    sege.build();
    priority_queue<int, vector<int>, greater<int>> que;
    que.push(sege.query(0, n));
    set<int> st;
    st.insert(-1);
    st.insert(n);
    while(que.size()){
        int u = que.top();
        que.pop();
        auto itr = st.lower_bound(q[u]);
        int r = *itr;
        itr--;
        int l = *itr;
        int v;
        if(q[u] % 2){
            v = sege.query(q[u], r);
            if(q[u] != l + 1) que.push(sego.query(l + 1, q[u]));
            if(q[v] != q[u] + 1) que.push(sege.query(q[u] + 1, q[v]));
            if(r != q[v] + 1) que.push(sego.query(q[v] + 1, r));
        }
        else{
            v = sego.query(q[u], r);
