const int N = 222222;
vector<int> p, q;
int poss[N];
int stree[4 * N][2];
int n;

int build(int left, int right, int pos, int even) {
    if(left == right) {
        stree[pos][even] = left % 2 == even ? N : p[left];
        return stree[pos][even];
    }
    int mid = left + right >> 1;
    int a = build(left, mid, pos * 2 + 1, even);
    int b = build(mid + 1, right, pos * 2 + 2, even);
    stree[pos][even] = min(a, b);
    return stree[pos][even];
}

int query(int left, int right, int curLeft, int curRight, int pos, int even) {
    if(curLeft > right || curRight < left) {
        return N;
    } else if(curLeft >= left && curRight <= right) {
        return stree[pos][even];
    }
    int mid = curLeft + curRight >> 1;
    int a = query(left, right, curLeft, mid, pos * 2 + 1, even);
    int b = query(left, right, mid + 1, curRight, pos * 2 + 2, even);
    return min(a, b);
}

struct compInterval {
    bool operator () (const pair<int, int> &a, const pair<int, int> &b) const {
        int aa = query(a.first, a.second, 0, n - 1, 0, a.first % 2 == 0);
        int bb = query(b.first, b.second, 0, n - 1, 0, b.first % 2 == 0);
        return aa > bb;
    }
};

