		f[x].yy=l&1?1e9:s[l];
	}
	else
	{
		int t=(l+r)>>1;
		build(x<<1,l,t);
		build(x<<1|1,t+1,r);
		merge(f[x]=f[x<<1],f[x<<1|1]);
	}
}

