struct SegmentTree{

   int sz;
   const int inf=1e9;
   vector<pii> seg;
   SegmentTree(int N){
      sz=1;
      while(sz*2<=N) sz*=2;
      seg.resize(2*sz-1);
   }

   void init(vector<int> &a, int ev){
      repeat(i, sz){
         if((i+ev)%2==1) seg[i+sz-1]={a[i], i};
         else seg[i+sz-1]={inf, i};
      }
      for(int i=sz-2; i>=0; i--){
         seg[i]=mrg(seg[2*i+1], seg[2*i+2]);
      }
   }

   pii mrg(pii l, pii r){
      pii rt;
      rt.first=min(l.first, r.first);
      rt.second=(l.first<r.first?l.second:r.second);
      return rt;
   }

   pii mi(int a, int b, int i, int l, int r){
      if(a<=l and r<=b){
         return seg[i];
      }else if(b<=l or r<=a){
         return {inf, -1};
      }else{
         int m=(r+l)/2;
         auto vl=mi(a, b, 2*i+1, l, m);
         auto vr=mi(a, b, 2*i+2, m, r);
         return mrg(vl, vr);
      }
   }

   pii mi(int a, int b){
      return mi(a, b, 0, 0, sz);
   }

   void out(){
      repeat(i, sz){
         cout<< seg[i+sz-1].first<< " ";
      }cout<< endl;
   }

};

int main(){

   int N; cin>> N;
   vector<int> a(N);
   repeat(i, N) cin>> a[i], a[i]--;

   SegmentTree st[2](N);
   st[0].init(a, 1); st[1].init(a, 0);
   priority_queue<tuple<int, int, int>> Q; // min, l, r
   Q.push(make_tuple(-st[0].mi(0, N).first, 0, N));
   vector<int> q;
   while(not Q.empty()){
      int v, i, j;
      tie(v, i, j)=Q.top(); Q.pop();
      auto ev=st[i%2].mi(i, j);
      auto od=st[(i+1)%2].mi(ev.second+1, j);
      assert(j-i>=2);
      //assert((i+ev.second)%2==0);
      //assert((i+od.second)%2==1);
      q.push_back(ev.first); q.push_back(od.first);
      if(i<ev.second){
         auto e=st[i%2].mi(i, ev.second);
         Q.push(make_tuple(-e.first, i, ev.second));
      }
      if(od.second+1<j){
         auto e=st[(od.second+1)%2].mi(od.second+1, j);
         Q.push(make_tuple(-e.first, od.second+1, j));
      }
      if(ev.second+1<od.second){
         auto e=st[(ev.second+1)%2].mi(ev.second+1, od.second);
         Q.push(make_tuple(-e.first, ev.second+1, od.second));
      }
   }

   repeat(i, N){
      if(i){
         cout<< " "<< q[i]+1;
      }else{
         cout<< q[i]+1;
      }
   }cout<< endl;

   return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
  int n;
  scanf("%d", &n);
  vector<int> p(n), pos(n);

  for (int i = 0; i < n; ++i) {
    scanf("%d", &p[i]);
    p[i]--;
    pos[p[i]] = i;
  }

  vector<array<int, 2>> st(n * 4);
  vector<int> sz(n * 4);
  constexpr int kInf = 1'000'000'000;

  auto Build = [&](auto self, int l, int r, int o = 0) {
    if (r - l == 1) {
      sz[o] = 1;
      st[o][0] = p[l];
      st[o][1] = kInf;
      return;
    }
    int m = (l + r) >> 1;
    self(self, l, m, o * 2 + 1);
    self(self, m, r, o * 2 + 2);
    sz[o] = sz[o * 2 + 1] + sz[o * 2 + 2];
    st[o][0] = min(st[o * 2 + 1][0], st[o * 2 + 2][sz[o * 2 + 1] & 1]);
    st[o][1] = min(st[o * 2 + 1][1], st[o * 2 + 2][sz[o * 2 + 1] & 1 ^ 1]);
  };

  auto Erase = [&](auto self, int l, int r, int p, int o = 0) {
    if (r - l == 1) {
      sz[o]--;
      st[o][0] = kInf;
      return;
    }
    int m = (l + r) >> 1;
    if (p < m) {
      self(self, l, m, p, o * 2 + 1);
    } else {
      self(self, m, r, p, o * 2 + 2);
    }
    sz[o] = sz[o * 2 + 1] + sz[o * 2 + 2];
    st[o][0] = min(st[o * 2 + 1][0], st[o * 2 + 2][sz[o * 2 + 1] & 1]);
    st[o][1] = min(st[o * 2 + 1][1], st[o * 2 + 2][sz[o * 2 + 1] & 1 ^ 1]);
  };

  auto QuerySize = [&](auto self, int l, int r, int ql, int qr, int o = 0) {
    if (l >= qr || ql >= r) return 0;
    if (l >= ql && r <= qr) return sz[o];
    int m = (l + r) >> 1;
    return self(self, l, m, ql, qr, o * 2 + 1) +
           self(self, m, r, ql, qr, o * 2 + 2);
  };

  auto Query = [&](auto self, int l, int r, int ql, int qr, int p, int o = 0) {
    if (l >= qr || ql >= r) return kInf;
    if (l >= ql && r <= qr) return st[o][p];
    int m = (l + r) >> 1;
    return min(self(self, l, m, ql, qr, p, o * 2 + 1),
               self(self, m, r, ql, qr, p ^ (sz[o * 2 + 1] & 1), o * 2 + 2));
  };

  Build(Build, 0, n);
  set<int> s;
  s.insert(n + 1);
  for (int it = 0; it < n / 2; ++it) {
    int a = Query(Query, 0, n, 0, n, 0);
    Erase(Erase, 0, n, pos[a]);
    s.insert(pos[a]);
    int p = QuerySize(QuerySize, 0, n, 0, pos[a]) & 1;
    int b = Query(Query, 0, n, pos[a], *s.upper_bound(pos[a]), p);
    Erase(Erase, 0, n, pos[b]);
    s.insert(pos[b]);
    printf("%d %d ", a + 1, b + 1);
  }
  puts("");
}

