		pair<int, int> mn = *s.rbegin();
		if (p[mn.fs] > p[mn.sc]) {
			ans.push_back(mn.fs);
			ans.push_back(mn.sc);
		}
		else {
			ans.push_back(mn.sc);
			ans.push_back(mn.fs);
		}
		erase_pair(mn.fs, mn.sc);
	}
	reverse(rall(ans));
	for (auto v : ans)
		cout << v << ' ';
	return 0;
}

