    rep(i,N) m[P[i]]=i;
    auto f=[](int a,int b){return min(a,b);};
    auto g=[](int a,int b){return b;};
    SegmentTree<int> seg0(N,f,g,INF),seg1(N,f,g,INF);
    for (int i=0;i<N;i+=2) seg0.update(i,P[i]);
    for (int i=1;i<N;i+=2) seg1.update(i,P[i]);
    vector<int> ans;
    priority_queue<Pii,vector<Pii>,greater<Pii>> pq;
    set<int> border;
    border.insert(-1),border.insert(N);
    int fa=seg0.query(-1,N),fb=seg1.query(m[fa],N);
    seg0.update(m[fa],INF),seg1.update(m[fb],INF);
    pq.push({fa,fb});
    while (!pq.empty()){
        Pii p=pq.top(); pq.pop();
