#include <bits/stdc++.h>
using namespace std;
pair<int, int> even[400000];
pair<int, int> odd[400000];
int arr[200000];
int n;
int sz;
const int inf=0x3f3f3f3f;
void update(int idx, pair<int, int> val, pair<int, int> *tree){
	idx+=sz;
	while(idx){
		tree[idx]=min(tree[idx], val);
		idx/=2;
	}
}
pair<int, int> query(int a, int b, pair<int, int> *tree){
	pair<int, int> ret={inf, inf};
	a+=sz;
	b+=sz;
	while(a<=b){
		if(a&1)
			ret=min(ret, tree[a++]);
		if(!(b&1))
			ret=min(ret, tree[b--]);
		a/=2;
		b/=2;
	}
	return ret;
}
vector<pair<int, pair<int, int> > > ans;
void solve(int le, int ri, int dep){
	if(le>=ri+1)
		return;
	if(le+1==ri){
		ans.push_back({dep, {arr[le], arr[ri]}});
		return;
	}
	if(le&1){
		int left=le/2;
		int right=ri/2;
		auto q=query(left, right-1, odd);
		auto p=query(q.second/2+1, right, even);
		ans.push_back({dep, {q.first, p.first}});
		solve(le, q.second-1, dep+1);
		solve(q.second+1, p.second-1, dep+1);
		solve(p.second+1, ri, dep+1);
		return;
	}
	int left=le/2;
	int right=ri/2;
	auto q=query(left, right, even);
	auto p=query(q.second/2, right, odd);
	ans.push_back({dep, {q.first, p.first}});
	solve(le, q.second-1, dep+1);
	solve(q.second+1, p.second-1, dep+1);
	solve(p.second+1, ri, dep+1);
}
int main(){
	memset(even, 0x3f, sizeof(even));
	memset(odd, 0x3f, sizeof(odd));
	scanf("%d", &n);
	sz=1;
	while(sz<n/2)sz*=2;
	for(int i=0;i<n;i++){
		int x;
		scanf("%d", &x);
		arr[i]=x;
		int idx=i/2;
		if(i&1)
			update(idx, {x, i}, odd);		
		else
			update(idx, {x, i}, even);
	}
	solve(0, n-1, 0);
	sort(ans.begin(), ans.end());
	for(int i=0;i<ans.size();i++)
		printf("%d %d ", ans[i].second.first, ans[i].second.second);
	printf("\n");
	return 0;
}

