void eval(int k, int l, int r) {
  if(lazy[k]) {
    swap(dat[k].first, dat[k].second);
    if(r-l>1) {
      lazy[2*k+1] = lazy[k];
      lazy[2*k+2] = lazy[k];
    }
    lazy[k] = false;
  }
}

