  if(b <= l || r <= a) {
    // cout << "a" << endl;
    return;
  }

  if(a <= l && r <= b) {
    // cout << "b" << endl;
    lazy[k] = true;
    eval(k, l, r);
  } else {
    // cout << "c" << endl;
    update(a, b, 2*k+1, l, (l+r)/2);
    update(a, b, 2*k+2, (l+r)/2, r);
    dat[k].first = min(dat[k*2+1].first, dat[k*2+2].first);
    dat[k].second = min(dat[k*2+1].second, dat[k*2+2].second);
  }
}

void up(int k) {
  k += n-1;
  dat[k] = {INF, INF};
  while(k > 0) {
    k = (k-1)/2;
    dat[k].first = min(dat[k*2+1].first, dat[k*2+2].first);
    dat[k].second = min(dat[k*2+1].second, dat[k*2+2].second);
  }
}

ll getMin(int a, int b, int mode, int k=0, int l=0, int r=-1) {
