  eval(k, l, r);

  if(b <= l || r <= a) {
    // cout << "a" << endl;
    return INT_MAX;
  }
  if(a <= l && r <= b) {
    // cout << "b" << endl;
    if(mode == 0) return dat[k].first;
    else return dat[k].second;
  }
  // cout << "c" << endl;
  ll vl = getMin(a, b, mode, 2*k+1, l, (l+r)/2);
  ll vr = getMin(a, b, mode, 2*k+2, (l+r)/2, r);
  return min(vl, vr);
}

