#include<stdio.h>
#include<queue>
using namespace std;
const int maxn=200001;
struct node{
	int left,right,min,max;
};
struct TreeArray{
	struct node num[maxn*10];
	int a[maxn];
	int buildmin(int left,int right,int cnt){
		int mid;
		num[cnt].left=left;
		num[cnt].right=right;
		if(left==right)
			return num[cnt].min=a[left];
		mid=(left+right)>>1;
		return num[cnt].min=min(buildmin(left,mid,cnt*2),buildmin(mid+1,right,cnt*2+1));
	}
	int query(int left,int right,int cnt){
		int mid;
		if(left==num[cnt].left&&right==num[cnt].right)
			return num[cnt].min;
		mid=(num[cnt].left+num[cnt].right)>>1;
		if(right<=mid)
			return query(left,right,cnt*2);
		else if(left>mid)
			return query(left,right,cnt*2+1);
		else 
			return min(query(left,mid,cnt*2),query(mid+1,right,cnt*2+1)); 
	}
};
struct E{
	TreeArray tr[2];
	int num[maxn],hash[maxn],N;
	void init(){
		scanf("%d",&N);
		for(int i=1;i<=N;i++){
			scanf("%d",&num[i]);
			hash[num[i]]=i;
			tr[i%2].a[(i+1)/2]=num[i];
		}
		tr[0].buildmin(1,N/2,1);
		tr[1].buildmin(1,N/2,1);
	}
	queue < pair<int,int> > getans(int l,int r){
		queue < pair<int,int> > now;
		if(r<l)return now;
		if(r-l==1){
			now.push(make_pair(num[l],num[r]));
			return now;
		}
		int s=l%2,t=r%2,ls=(l+s)/2,lt=(r+s)/2,rt=lt+t;
		int lval=tr[s].query(ls,lt,1),lpos=hash[lval];
		int rs=(lpos+s)/2+t;
		int rval=tr[t].query(rs,rt,1),rpos=hash[rval];
		queue < pair<int,int> > part1=getans(l,lpos-1),part2=getans(lpos+1,rpos-1),part3=getans(rpos+1,r);
		now.push(make_pair(lval,rval));
		for(;!part1.empty()&&!part2.empty()&&!part3.empty();){
			s=part1.front().first;t=part2.front().first;ls=part3.front().first;
			if(s>t){
				if(t>ls){
					now.push(part3.front());
					part3.pop();
				}
				else{
					now.push(part2.front());
					part2.pop();
				}
			}
			else{
				if(s>ls){
					now.push(part3.front());
					part3.pop();
				}
				else{
					now.push(part1.front());
					part1.pop();
				}
			}
		}
		if(part1.empty()){
			for(;!part2.empty()&&!part3.empty();){
				if(part2.front().first>part3.front().first){
					now.push(part3.front());
					part3.pop();
				}
				else{
					now.push(part2.front());
					part2.pop();
				}
			}
			while(!part2.empty()){
				now.push(part2.front());
				part2.pop();
			}
			while(!part3.empty()){
				now.push(part3.front());
				part3.pop();
			}
		}
		else{
			if(part2.empty()){
				for(;!part1.empty()&&!part3.empty();){
					if(part1.front().first>part3.front().first){
						now.push(part3.front());
						part3.pop();
					}
					else{
						now.push(part1.front());
						part1.pop();
					}
				}
				while(!part1.empty()){
					now.push(part1.front());
					part1.pop();
				}
				while(!part3.empty()){
					now.push(part3.front());
					part3.pop();
				}
			}
			else{
				if(part3.empty()){
					for(;!part1.empty()&&!part2.empty();){
						if(part1.front().first>part2.front().first){
							now.push(part2.front());
							part2.pop();
						}
						else{
							now.push(part1.front());
							part1.pop();
						}
					}
					while(!part1.empty()){
						now.push(part1.front());
						part1.pop();
					}
					while(!part2.empty()){
						now.push(part2.front());
						part2.pop();
					}
				}
			}
		}
		return now;
	}
	void work(){
