struct S {
    l_l oddmin;
    l_l evenmin;
};

S op(S l, S r) {
    return {min(l.oddmin, r.oddmin), min(l.evenmin, r.evenmin)};
}

S e() {
    return {{1e9, 0}, {1e9, 0}};
}

struct F {
    int type;
};

S mapping(F f, S s) {
    if(f.type == 2) return e();
    if(f.type == 1) return {s.evenmin, s.oddmin};
    if(f.type == 0) return s;
}

F composition(F l, F r) {
    if(l.type == 2 or r.type == 2) return F({2});
    return F({l.type ^ r.type});
}

F id(){
    return F({0});
}

