	vector<pii> eve(n,pii(MOD,-1)),odd(n,pii(MOD,-1));
	rep(i,n) (i%2?odd:eve)[i]=pii(a[i],i);
	RMQ<pii> rmq0(eve,pii(MOD,-1));
	RMQ<pii> rmq1(odd,pii(MOD,-1));
	//out(eve,odd,1);
	typedef tuple<pii,pii,pii> TP;
	priority_queue<TP,vector<TP>, greater<TP>> que;
	auto fun=[&](int l,int r){
		pii p=(l%2?rmq1:rmq0).get(l,r-1);
		//out(l,r,p,1);
		pii q=(l%2?rmq0:rmq1).get(p.Y,r-1);
		return make_pair(p,q);
	};
	{
		pii a,b;
		tie(a,b)=fun(0,n);
		que.emplace(a,b,pii(0,n));
	}
	vector<int> re;
	while(que.size()){
		pii p,q,I; tie(p,q,I)=que.top(); que.pop();
		//out(p,q,I,1);
		re.pb(p.X); re.pb(q.X);
		int l=p.Y, r=q.Y;
