template<typename Traits>
class SegTree {
public:
	typedef typename Traits::valueType T;
	int N;
	vector<T> dat;
	SegTree(int _N) {
		N=1; while(N<_N) N*=2;
		dat = vector<T>(2*N, Traits::e());
	}
	// idx is 0 base
	void update(int idx, T v) {
		idx += N-1;
		dat[idx] = v;
		while(idx>0) {
			idx = (idx-1)/2;
			dat[idx] = Traits::op(dat[idx*2+1], dat[idx*2+2]);
		}
	}
	// [a, b)
	T query(int a, int b) { return query(a, b, 0, 0, N); }
	T query(int a, int b, int k, int l, int r) {
		if(r<=a || b<=l) return Traits::e();
		if(a<=l && r<=b) return dat[k];
		else {
			T vl = query(a, b, k*2+1, l, (l+r)/2);
			T vr = query(a, b, k*2+2, (l+r)/2, r);
			return Traits::op(vl, vr);
		}
	}
};

// (head value, (s, e)) ... [s, e]
typedef pair<ll, pair<ll, ll>> Range;

VI naive(VI w) {
	ll N = w.size();
	set<PII> rs;
	rs.insert(MP(0, N-1));
	VI ans;
	while(rs.size()) {
		ll minL=1LL<<60;
//		DD(rs);
		for(auto r : rs) {
			ll s, e;
			tie(s, e) = r;
			for(int i=s;i<=e;i+=2) {
				minL = min(minL, w[i]);
			}
		}
		ll ss, ee;
		ll i1, i2;
		for(auto r : rs) {
			ll s, e;
			tie(s, e) = r;
			for(int i=s;i<=e;i+=2) {
				if(w[i]==minL) {
					ll minRi = i+1;
					for(int j=i+1;j<=e;j+=2) {
						if(w[j]<w[minRi]) minRi=j;
					}
					i1 = i;
					i2 = minRi;
					ss = s;
					ee = e;
				}
			}
		}
		ans.PB(w[i1]);
		ans.PB(w[i2]);
		w[i1] = w[i2] = 1LL<<60;
		rs.erase(MP(ss, ee));
		if(ss<i1-1) rs.insert(MP(ss, i1-1));
		if(i1+1<i2-1) rs.insert(MP(i1+1, i2-1));
		if(i2+1<ee) rs.insert(MP(i2+1, ee));
	}
	return ans;
}

VI solve(VI w) {
	ll N = w.size();
	vector<SegTree<Min>> st(2, SegTree<Min>(N));
	REP(i, N) {
		st[i%2].update(i, MP(w[i], i));
	}

	priority_queue<Range, vector<Range>, greater<Range>> q;
	q.push(MP(w[0], MP(0, N-1)));

	VI ans;
	auto Push = [&](ll s, ll e) {
		if(s < e) q.push(MP(st[s%2].query(s, e+1).first, MP(s, e)));
	};
	while(q.size()) {
		ll rmv, s, e;
		forward_as_tuple(rmv, tie(s, e)) = q.top();
//		DD("pop");
//		DD(rmv);
//		DD(s);
//		DD(e);
		q.pop();
		ll p1, p1i, p2, p2i;
		tie(p1, p1i) = st[s%2].query(s, e+1);
		ans.PB(p1);
		tie(p2, p2i) = st[1-s%2].query(p1i+1, e+1);
		ans.PB(p2);
		Push(s, p1i-1);
		Push(p1i+1, p2i-1);
		Push(p2i+1, e);
	}
	return ans;
}

