const int INF = 1e9;

struct SegTree {
    int init, size;
    vector<int> seg;

    // This function is used in query
    int f(int a, int b) {
        return min(a,b);
    }

    // This function is used in update
    int g(int a, int b) {
        return b;
    }

    SegTree(const vector<int>& v, int init = 0) : init{init} {
        size = 1;
        while (size < v.size()) size <<= 1;
        seg.resize(2 * size,init);
        for (int i = 0; i < v.size(); i++) {
            seg[i + size] = v[i];
        }
        for (int i = size - 1; i > 0; i--) {
            seg[i] = f(seg[2 * i], seg[2 * i + 1]);
        }
    }

    SegTree(int n, int init) : SegTree{vector<int>(n,init),init} {}

    SegTree(int n) : SegTree{n,0} {}

    SegTree() {}

    void update(int k, int x) {
        k += size;
        seg[k] = g(seg[k],x);
        k /= 2;
        for (; k > 0; k /= 2) {
            seg[k] = f(seg[2 * k], seg[2 * k + 1]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) return init;
        if (a <= l && r <= b) return seg[k];
        int x = query(a,b,2 * k,l,(l + r) / 2);
        int y = query(a,b,2 * k + 1,(l + r) / 2,r);
        return f(x,y);
    }

    int query(int a, int b) {
        return query(a,b,1,0,size);
    }
};

