vector<pair<int,int>> dfs(int l, int r) {
    vector<pair<int,int>> ret;
    if (l >= r) return ret;
    int x = st[l%2].query(l,r);
    int y = st[1-l%2].query(pos[x],r);
    ret.emplace_back(x,y);
    vector<pair<int,int>> vec[3];
    vec[0] = dfs(l,pos[x]);
    vec[1] = dfs(pos[x] + 1,pos[y]);
    vec[2] = dfs(pos[y] + 1,r);
    int sp[3] {};
    while (sp[0] < vec[0].size() || sp[1] < vec[1].size() || sp[2] < vec[2].size()) {
        int i, mi;
        pair<int,int> mn = {INF,INF};
        REP (i,3) {
            if (sp[i] < vec[i].size() && vec[i][sp[i]] < mn) {
                mn = vec[i][sp[i]];
                mi = i;
            }
        }
        ret.push_back(mn);
        sp[mi]++;
    }
    return ret;
}

