struct Node{
	int l,r,mn[2];
}T[maxn<<2];

int cmp(int x,int y){
	return A[x]<A[y]?x:y;
}

void build(int i,int l,int r){
	T[i].l=l;T[i].r=r;
	if(l==r){
		T[i].mn[l&1]=l;
		return;
	}
	int M=l+r>>1;
	build(i<<1,l,M);build(i<<1|1,M+1,r);
	REP(j,0,1)T[i].mn[j]=cmp(T[i<<1].mn[j],T[i<<1|1].mn[j]);
}

int query(int i,int l,int r,int p){
	if(l<=T[i].l&&T[i].r<=r)return T[i].mn[p];
	int ans=0,M=T[i].l+T[i].r>>1;
	if(l<=M)ans=cmp(ans,query(i<<1,l,r,p));
	if(r>M)ans=cmp(ans,query(i<<1|1,l,r,p));
	return ans;
}

int query(int l,int r){
	x=query(1,l,r,l&1);
	y=query(1,x+1,r,r&1);
	return A[x];
}

void Work(){
	Q.push(MP(query(1,n),MP(1,n)));
	while(!Q.empty()){
		int l=Q.top().se.fi,r=Q.top().se.se;Q.pop();
		query(l,r);
		int X=x,Y=y;
//		cout<<X<<' '<<Y<<endl;
		Ans[++ans]=A[x];Ans[++ans]=A[y];
		if(l<X)Q.push(MP(query(l,X-1),MP(l,X-1)));
		if(X<Y-1)Q.push(MP(query(X+1,Y-1),MP(X+1,Y-1)));
		if(Y<r)Q.push(MP(query(Y+1,r),MP(Y+1,r)));
	}
	REP(i,1,n)printf("%d ",Ans[i]);puts("");
}

void Init(){
	read(n);
	REP(i,1,n)read(A[i]);A[0]=n+1;
	build(1,1,n);
}

int main(){
	Init();
	Work();
	return 0;
}

