void init(){
    N=1;
    while(N<n) N*=2;
    vo.assign(2*N-1,inf); //変更点
    ve.assign(2*N-1,inf);
}

void init_u(){
    for(int i=N-2;i>=0;i--)
    vo[i]=min(vo[2*i+1],vo[2*i+2]); //変更点
    for(int i=N-2;i>=0;i--)
    ve[i]=min(ve[2*i+1],ve[2*i+2]);
}

//query(a,b,0,0,N);
int query_o(int a,int b,int k,int l,int r){
    if(r<=a || b<=l) return inf; //変更点
    if(a<=l && r<=b) return vo[k];
    int vl=query_o(a,b,k*2+1,l,(l+r)/2);
    int vr=query_o(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr); //変更点
}

int query_e(int a,int b,int k,int l,int r){
    if(r<=a || b<=l) return inf; //変更点
    if(a<=l && r<=b) return ve[k];
    int vl=query_e(a,b,k*2+1,l,(l+r)/2);
    int vr=query_e(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr); //変更点
}

void dfs(int a,int b,int K){
    if(a>b) return;
    int l,r;
    k++;
    if(a%2==0){
        l=query_o(a/2,b/2+1,0,0,N);
        r=query_e(pos[l]/2,b/2+1,0,0,N);
    }
    else{
        l=query_e(a/2,b/2,0,0,N);
        r=query_o((pos[l]+1)/2,b/2+1,0,0,N);
    }
    m[k]=mk(l,r);
    if(K!=-1){
        path[K].push_back(k);
        path[k].push_back(K);
    }
    K=k;
    dfs(a,pos[l]-1,K);
    dfs(pos[r]+1,b,K);
    dfs(pos[l]+1,pos[r]-1,K);
}

int main(){
    cin>>n; n/=2;
    path.assign(n,vector<int>(0));
    m.assign(n,mk(0,0));
    pos.assign(2*n+1,0);
