    init_u();
    dfs(0,2*n-1,-1);
    priority_queue<pp> que;
    vector<int> visited(2*n,0);
    que.push(mk(-m[0].first,0));
    while(!(que.empty())){
        int num,s;
        tie(num,s)=que.top();
        que.pop();
        printf("%d %d ",m[s].first,m[s].second);
        visited[s]=1;
        for(auto to:path[s]){
            if(visited[to]) continue;
            que.push(mk(-m[to].first,to));
        }
    }
}

