pair<int, int> Asort[100001];
int MIN[100001];
vector<PP> Q;

PP segA[1 << 18];
PP segB[1 << 18];

void segupdate(PP* seg, int i, int val, int p) {
	seg[i] = make_pair(val, p);
	while (i > 1) {
		i /= 2;
		seg[i] = min(seg[i * 2], seg[i * 2 + 1]);
	}
}

void segcreate(PP* seg, int* dat) {
	fill(seg, seg + (1 << 18), make_pair(INF, -1));
	REP(i, 0, N / 2) {
		segupdate(seg, i + (1 << 17), dat[i], i);
	}
}

PP segminrec(PP* seg, int a, int b, int i, int l, int r) {
	if (r <= a || b <= l) return make_pair(INF, -1);
	if (a <= l && r <= b) return seg[i];

	return min(
		segminrec(seg, a, b, i * 2, l, (l + r) / 2),
		segminrec(seg, a, b, i * 2 + 1, (l + r) / 2, r));
}
PP segmin(PP* seg, int a, int b) {
	return segminrec(seg, a, b, 1, 0, 1 << 17);
}



void input() {
	cin >> N;
	REP(i, 0, N / 2) {
		cin >> A[i];
		cin >> B[i];
	}
	return;
}
void solverec(int* a, int a_s, int* b, int b_s, PP* seg_a, PP* seg_b, int n) {
	if (n == 0) {
	} else if (n == 1) {
		Q.push_back(make_pair(a[a_s], b[b_s]));
	} else {
		auto ml = segmin(seg_a, a_s, a_s + n);
		auto mr = segmin(seg_b, b_s, b_s + n);

		Q.push_back(make_pair(ml.first, mr.first));

		solverec(a, a_s, b, b_s, seg_a, seg_b, ml.second - a_s);
		solverec(b, ml.second + (a == A ? 0 : 1), a, ml.second + 1, seg_b, seg_a, mr.second - ml.second - (a == A ? 0 : 1));
		solverec(a, mr.second + 1, b, mr.second + 1, seg_a, seg_b, b_s + n - mr.second - 1);

		sort(Q.end() - n + 1, Q.end());
	}
}

void solve() {
	REP(i, 0, N / 2) {
		Asort[i] = make_pair(A[i], i);
	}
	sort(Asort, Asort + N / 2);

	segcreate(segA, A);
	segcreate(segB, B);

	solverec(A, 0, B, 0, segA, segB, N / 2);
	return;
}

void output() {
	REP(i, 0, N / 2) {
		cout << Q[i].first << ' ' << Q[i].second << (i == N / 2 - 1 ? '\n' : ' ');
	}
	return;
}


int main() {
	input();
	solve();
	output();
	return 0;
}

