template <class T>
class SegTree {
    using F = function<T(T, T)>;
    int n;
    vector<T> data;
    const F f;
    const T e;

public:
    SegTree(const vector<T>& as, const F f, const T& e) : f(f), e(e) {
        n = 1;
        while (n < as.size()) n <<= 1;
        data.assign(2 * n, e);
        for (int i = 0; i < as.size(); i++) {
            data[n + i] = as[i];
        }
        for (int i = n - 1; i > 0; i--) {
            data[i] = f(data[2 * i], data[2 * i + 1]);
        }
    }

    void update(int k, const T& x) {
        k += n;
        data[k] = x;
        while (k >>= 1) {
            data[k] = f(data[2 * k], data[2 * k + 1]);
        }
    }

    T query(int a, int b) {
        T L = e, R = e;
        for (a += n, b += n; a < b; a >>= 1, b >>= 1) {
            if (a & 1) {
                L = f(L, data[a++]);
            }
            if (b & 1) {
                R = f(data[--b], R);
            }
        }
        return f(L, R);
    }
};

struct range {
    int l, r;
    bool even;
    bool operator<(const range& rhs) const {
        return l == rhs.l ? r < rhs.r : l < rhs.l;
    }
};

void printvec(vi& x, int size = 0) {
    if (x.size() == 0) {
        cout << endl;
        return;
    }
    cout << x.front();
    for (int i = 1; i < (size == 0 ? x.size() : size); i++) {
        cout << " " << x[i];
    }
    cout << endl;
}

int main() {
    int n;
    cin >> n;
    using ii = pair<int, int>;
    vector<ii> es, os;
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        if (i % 2 == 0) {
            es.emplace_back(p, i);
        } else {
            os.emplace_back(p, i);
        }
    }
    SegTree<ii> et(es, [](ii a, ii b) {return min(a, b);}, ii(1e9, 0));
    SegTree<ii> ot(os, [](ii a, ii b) {return min(a, b);}, ii(1e9, 0));
    set<range> er;
    range orr = {-1, -1, true};
    er.insert({0, n, true});
    vi ans;
    while (er.size() || orr.l != -1) {
        if (orr.l != -1) {
            ii m;
            if (orr.even) {
                m = et.query(orr.l / 2, (orr.r + 1) / 2);
            } else {
                m = ot.query(orr.l / 2, (orr.r + 1) / 2);
            }
            ans.push_back(m.first);
            if (m.second != orr.l) {
                er.insert({orr.l, m.second, orr.even});
            }
            if (m.second + 1 != orr.r) {
                er.insert({m.second + 1, orr.r, !orr.even});
            }
            orr = {-1, -1, true};
            continue;
        }

        int nin = 1e9, id;
        range rem;
        for (auto& r: er) {
            ii m;
            if (r.even) {
                m = et.query(r.l / 2, r.r / 2);
            } else {
                m = ot.query(r.l / 2, r.r / 2);
            }
            if (m.first < nin) {
                nin = m.first;
                rem = r;
                id = m.second;
            }
        }

        ans.push_back(nin);
        if (rem.l != id) {
            er.insert({rem.l, id, rem.even});
        }
        orr = {id + 1, rem.r, !rem.even};
        er.erase(rem);
    }

    printvec(ans);
}

