class SegmentTree {
private:
  int size_;
  vector<PII> dat;

  PII calc(PII d1, PII d2) {return min(d1, d2);}
  PII query(int a, int b, int k, int l, int r) {
    if(r <= a || b <= l) return {INT_MAX, INT_MAX};
    if(a <= l && r <= b) return dat[k];
    return calc(query(a, b, 2*k+1, l, (l+r)/2),
                  query(a, b, 2*k+2, (l+r)/2, r));
  }

public:
  SegmentTree() {}
  SegmentTree(int n) {
    for(size_ = 1; size_ < n; size_ *= 2);
    dat.assign(2*size_-1, {INT_MAX, INT_MAX});
  }

  void update(int k, PII a) {
    k += size_ - 1;
    dat[k] = a;
    while(k > 0) {
      k = (k-1) / 2;
      dat[k] = calc(dat[k*2+1], dat[k*2+2]);
    }
  }

  PII query(int a, int b) {return query(a, b, 0, 0, size_);}
};

SegmentTree seg[2];
