VI nxt[100010];
map<PII, int> toId;

void func(int l, int r, int par) {
  if(l >= r) return;

  PII a = seg[l%2].query(l, r-1),
      b = seg[(l+1)%2].query(a.second+1, r);

  if(par != -1) nxt[par].PB(piece.size());
  toId[{a.first, b.first}] = piece.size();
  piece.PB({a.first, b.first});

  int cur = piece.size() - 1;
  if(l < a.second) func(l, a.second, cur);
  func(a.second+1, b.second, cur);
  if(b.second+1 < r) func(b.second+1, r, cur);
}

