// Verified: AOJ-DSL2A, AOJ-DSL2B
template <typename T>
class SegmentTree {
 private:
  function<T(T, T)> merge_fn;
  T empty_value;
  vector<T> nodes;
  int num_nodes;

  // Returns the fold of overwrap between [node_l, node_r) and [l, r).
  // nodes[node_index] needs to correspond to [node_l, node_r).
  T GetRangeInternal(int node_index, int node_l, int node_r, int l, int r) {
    if (node_r <= l || r <= node_l) return empty_value;
    if (l <= node_l && node_r <= r) return nodes[node_index];
    int node_m = (node_l + node_r) / 2;
    return merge_fn(
        GetRangeInternal(2 * node_index, node_l, node_m, l, r),
        GetRangeInternal(2 * node_index + 1, node_m, node_r, l, r));
  }

  // The following code is the custom code for this problem.
  void FlipRangeInternal(int node_index, int node_l, int node_r, int l, int r) {
    if (node_r <= l || r <= node_l) {
      return;
    }
    if (l <= node_l && node_r <= r) {
      // Flip this node.
      swap(nodes[node_index].min_0, nodes[node_index].min_1);
      return;
    }
    int node_m = (node_l + node_r) / 2;
    FlipRangeInternal(2 * node_index, node_l, node_m, l, r);
    FlipRangeInternal(2 * node_index + 1, node_m, node_r, l, r);
    nodes[node_index] = merge_fn(nodes[2 * node_index], nodes[2 * node_index + 1]);
  }

 public:
  // Arguments:
  // in_merge: The function to merge two values. It should be a monoid.
  // in_empty_value: The identity of the monoid.
  // xs: The initial values.
  SegmentTree(
      function<T(T, T)> merge_fn, T empty_value, const vector<T>& xs) :
          merge_fn(merge_fn), empty_value(empty_value) {
    int n = xs.size();
    num_nodes = 1;
    while (num_nodes < n) num_nodes *= 2;
    num_nodes *= 2;
    nodes = vector<T>(num_nodes, empty_value);
    for (int i = 0; i < xs.size(); ++i) {
      nodes[num_nodes / 2 + i] = xs[i];
    }
    for (int i = num_nodes / 2 - 1; i >= 1; i--) {
      nodes[i] = merge_fn(nodes[2 * i], nodes[2 * i + 1]);
    }
  }

  // Updates the i-th element to x.
  void Update(int i, T x) {
    nodes[num_nodes / 2 + i] = x;
    for (int cur = (num_nodes / 2 + i) / 2; cur > 0; cur /= 2) {
      nodes[cur] = merge_fn(nodes[2 * cur], nodes[2 * cur + 1]);
    }
  }

  // Returns the value of the range [l, r) merged by merge_fn.
  T GetRange(int l, int r) {
    return GetRangeInternal(1, 0, num_nodes / 2, l, r);
  }

  T Get(int i) {
    return nodes[num_nodes / 2 + i];
  }

  // The following code is the custom code for this problem.
  void FlipRange(int l, int r) {
    FlipRangeInternal(1, 0, num_nodes / 2, l, r);
  }
};

struct Range {
  int l, r;
  Range(int l, int r) : l(l), r(r) {}
  bool operator== (Range o) const {
    return l == o.l && r == o.r;
  }
  bool operator!= (Range o) const {
    return !((*this) == o);
  }
};

// A variant of a lazy propagation segment tree for a case when range-get is
// not required.
// T: The type of values.
// U: The type of operators.
// Verified: AOJ-DSL2D
template<typename T, typename U>
class LazyPropagationSegmentTreeNoRangeGet {
 private:
  function<U(U, U)> op_merge;
  U empty_op;
  function<T(T, U)> apply_op;
  int num_nodes;
  vector<T> values;
  vector<U> op_nodes;

  void DoLazyPropagation(int node_index) {
   if (op_nodes[node_index] != empty_op) {
      if (node_index < num_nodes / 2) {
        op_nodes[2 * node_index] =
            op_merge(op_nodes[2 * node_index], op_nodes[node_index]);
        op_nodes[2 * node_index + 1] =
            op_merge(op_nodes[2 * node_index + 1], op_nodes[node_index]);
      } else {
        int value_index = node_index - num_nodes / 2;
        values[value_index] =
            apply_op(values[value_index], op_nodes[node_index]);
      }
      op_nodes[node_index] = empty_op;
    }
  }

  void ApplyOpRangeInternal(
      int node_index, int node_l, int node_r, int l, int r, U op) {
    DoLazyPropagation(node_index);

    if (node_r <= l || r <= node_l) return;

    if (l <= node_l && node_r <= r) {
      op_nodes[node_index] = op;
      DoLazyPropagation(node_index);
      return;
    }
    int node_m = (node_l + node_r) / 2;
    ApplyOpRangeInternal(2 * node_index, node_l, node_m, l, r, op);
    ApplyOpRangeInternal(2 * node_index + 1, node_m, node_r, l, r, op);
  }

  T GetInternal(int node_index, int node_l, int node_r, int i) {
    DoLazyPropagation(node_index);

    if (node_index >= num_nodes / 2) {
      return values[i];
    }

    int node_m = (node_l + node_r) / 2;
    if (i < node_m) {
      return GetInternal(2 * node_index, node_l, node_m, i);
    } else {
      return GetInternal(2 * node_index + 1, node_m, node_r, i);
    }
  }

 public:
  LazyPropagationSegmentTreeNoRangeGet(
      function<U(U, U)> in_op_merge, U in_empty_op,
      function<T(T, U)> in_apply_op, vector<T> in_values) :
          op_merge(in_op_merge), empty_op(in_empty_op), apply_op(in_apply_op),
          values(in_values) {
    int n = values.size();
    num_nodes = 1;
    while (num_nodes < n) num_nodes *= 2;
    num_nodes *= 2;
    op_nodes = vector<U>(num_nodes, empty_op);
  }

  // Applies the operator to the range [l, r).
  void ApplyOpRange(int l, int r, U op) {
    if (l >= r) return;
    return ApplyOpRangeInternal(1, 0, num_nodes / 2, l, r, op);
  }

  T Get(int i) { return GetInternal(1, 0, num_nodes / 2, i); }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> ps(n);
  for (int i = 0; i < n; i++) {
    cin >> ps[i];
  }

  constexpr int INF_INT_VALUE = 1 << 18;
  const NodeValue INF_NODE_VALUE = NodeValue(-1, INF_INT_VALUE);
  const Node INF_NODE = Node(INF_NODE_VALUE, INF_NODE_VALUE);
  vector<Node> leaf_nodes;
  for (int i = 0; i < n; i++) {
    if (i % 2 == 0) {
      leaf_nodes.push_back(Node(NodeValue(i, ps[i]), INF_NODE_VALUE));
    } else {
      leaf_nodes.push_back(Node(INF_NODE_VALUE, NodeValue(i, ps[i])));
    }
  }
  auto merge_fn = [](const Node& node1, const Node& node2) {
    return Node(
        MinNodeValue(node1.min_0, node2.min_0),
        MinNodeValue(node1.min_1, node2.min_1));
  };

  SegmentTree<Node> tree(merge_fn, INF_NODE, leaf_nodes);

  auto merge_update_fn = [](Range current_update, Range new_update) -> Range {
    return new_update;
  };
  const Range NO_UPDATE = Range(-1, -1);
  auto apply_update_fn = [](Range current_value, Range new_value) -> Range {
    if (new_value.l == -1 && new_value.r == -1) return current_value; 
    return new_value;
  };
  vector<Range> ranges;
  for (int i = 0; i < n; i++) {
    ranges.push_back(Range(0, n));
  }
  LazyPropagationSegmentTreeNoRangeGet<Range, Range> tree2(
      merge_update_fn, NO_UPDATE, apply_update_fn, ranges);

  vector<int> outputs;
  for (int iter = 0; iter < n / 2; iter++) {
    int l = tree.GetRange(0, n).min_0.index;
    // int r = tree.GetRange(l + 1, n).min_1.index;
    int r = tree.GetRange(l + 1, tree2.Get(l).r).min_1.index;
    if (DEBUG) cout << "l: " << l << " r: " << r << endl;
    if (DEBUG) cout << ps[l] << " " << ps[r] << endl;
    outputs.push_back(ps[l]);
    outputs.push_back(ps[r]);

    // Update the value l.
    tree.Update(l, INF_NODE);
    // Update the value r.
    tree.Update(r, INF_NODE);
    // Flip the range [l + 1, r - 1]
    tree.FlipRange(l + 1, r);

    int p_l = tree2.Get(l).l;
    int p_r = tree2.Get(r).r;
    tree2.ApplyOpRange(p_l, l, Range(p_l, l));
    tree2.ApplyOpRange(l, l + 1, Range(l, l + 1));
    tree2.ApplyOpRange(l + 1, r, Range(l + 1, r));
    tree2.ApplyOpRange(r, r + 1, Range(r, r + 1));
    tree2.ApplyOpRange(r + 1, p_r, Range(r + 1, p_r));
  }

  for (int i = 0; i < n; i++) {
    cout << outputs[i] << " ";
  }
  cout << endl;
}

