struct segment_tree {
	pii t[N << 2];
	segment_tree() {
		fill(t, t + (N << 2), mp(inf, inf));
	}
	void update(int v, int tl, int tr, int pos, int val) {
		if(tl == tr)
			t[v] = {val, pos};
		else {
			int mid = tl + tr >> 1;
			if(pos <= mid)
				update(v << 1, tl, mid, pos, val);
			else
				update(v << 1 | 1, mid + 1, tr, pos, val);
			t[v] = min(t[v << 1], t[v << 1 | 1]);
		}
	}
	pii get(int v, int tl, int tr, int l, int r) {
		if(tl > r || tr < l || l > r)
			return {inf, inf};
		if(tl >= l && tr <= r)
			return t[v];
		int mid = tl + tr >> 1;
		return min(get(v << 1, tl, mid, l, r), get(v << 1 | 1, mid + 1, tr, l, r));
	}
} t[2];

inline void add(int l) {
	pii nxt = t[l & 1].get(1, 0, n - 1, l, r_of[l]);
	if(nxt.f != inf)
		is.insert({nxt.f, l});
}

inline void upd(int i, int j, int l) {
	t[i & 1].update(1, 0, n - 1, i, inf);
	t[j & 1].update(1, 0, n - 1, j, inf);

	r_of[j + 1] = r_of[l];
	add(j + 1);

	r_of[l] = i - 1;
	add(l);

	r_of[i + 1] = j - 1;
	add(i + 1);
}

inline void solve() {
	while(!is.empty()) {
		int l = is.begin()->se;
		int i = pos[is.begin()->f];
		is.erase(is.begin());
		pii nxt = t[(i & 1) ^ 1].get(1, 0, n - 1, i + 1, r_of[l]);
		assert(nxt.f != inf);
		upd(i, nxt.se, l);
		ans.pb(a[i]);
		ans.pb(nxt.f);
	}
}

main() {
	ios_base::sync_with_stdio(0); cout.tie(0); cin.tie(0);
	// setin("input.txt");
	cin >> n;
	for(int i = 0; i < n; ++i) {
		cin >> a[i];
		t[i & 1].update(1, 0, n - 1, i, a[i]);
		pos[a[i]] = i;
	}
	r_of[0] = n - 1;
	add(0);

	solve();
	for(int i : ans)
		cout << i << ' ';
	return 0;
}

