struct node
{
    int first,second,u;
    bool operator <(const node &A)const
    {
        if(A.u!=u) return A.u>u;
        else if(A.first!=first) return A.first>first;
        else return A.second>second;
    }
};
vector<node>p;
void build(int l,int r,int rt)
{
    if(l==r)
    {
        scanf("%d", &a[l]);
        if(l&1)   sum1[rt]=a[l],sum2[rt]=N+1;
        else sum1[rt]=N+1,sum2[rt]=a[l];
        pos[a[l]]=l;
        return ;
    }
    int mid=(l+r)/2;
    build(l,mid,rt*2);
    build(mid+1,r,rt*2+1);
    sum1[rt]=min(sum1[rt<<1],sum1[rt<<1|1]);
    sum2[rt]=min(sum2[rt<<1],sum2[rt<<1|1]);
    return ;
}
int query1(int l,int r,int rt,int L,int R)
{
    if(L<=l&&R>=r)  return sum1[rt];
    int mid=(l+r)/2;
    int ans=N+1;
    if(L<=mid) ans=min(ans,query1(l,mid,rt*2,L,R));
    if(R>mid) ans=min(ans,query1(mid+1,r,rt*2+1,L,R));
    return ans;
}
int query2(int l,int r,int rt,int L,int R)
{
    if(L<=l&&R>=r)  return sum2[rt];
    int mid=(l+r)/2;
    int ans=N+1;
    if(L<=mid) ans=min(ans,query2(l,mid,rt*2,L,R));
    if(R>mid) ans=min(ans,query2(mid+1,r,rt*2+1,L,R));
    return ans;
}
void dfs(int l,int r,int u)
{
    if(l<1||r<1||l>r||l>n||r>n) return ;

    if(l&1)
    {
        int x=query1(1,n,1,l,r);
        int al=pos[x];
        int y=query2(1,n,1,al+1,r);
        int ar=pos[y];
        p.push_back((node){x,y,u});
        dfs(al+1,ar-1,u+1);
        dfs(l,al-1,u+1);
        dfs(ar+1,r,u+1);
    }
    else
    {
        int x=query2(1,n,1,l,r);
        int al=pos[x];
        int y=query1(1,n,1,al+1,r);
        int ar=pos[y];
        p.push_back((node){x,y,u});
        dfs(al+1,ar-1,u+1);
        dfs(l,al-1,u+1);
        dfs(ar+1,r,u+1);
    }
}

