const size_t MAX_N = (size_t)2e5 + 5;
typedef pair<int, int> ii;
#define fi first
#define se second

int pow2, p[MAX_N], n;
ii tree[2][MAX_N << 2];
vector<ii> res[MAX_N];

inline void init() { for (pow2 = 1; pow2 < n; pow2 <<= 1) {} pow2--; }
inline void push(ii* tree, int p, int val) {
    int pos = p;
    for (tree[p += pow2] = {val, pos}; p > 1; p >>= 1)
        tree[p >> 1] = min(tree[p], tree[p ^ 1]);
}
inline ii rmq(ii* tree, int l, int r) {
    ii res = {INT_MAX, INT_MAX};
    for (l += pow2, r += pow2; l < r; l >>= 1, r >>= 1) {
        if (l & 1) res = min(res, tree[l++]);
        if (r & 1) res = min(res, tree[--r]);
    }
    return res;
}
void doit(int l, int r, int st, int depth) {
    if (l >= r) return ;
    ii res1 = rmq(tree[st], l, r);
    ii res2 = rmq(tree[st ^ 1], res1.se, r);
    res[depth].emplace_back(res1.fi, res2.fi);
    doit(l, res1.se, st, depth + 1);
    doit(res1.se + 1, res2.se, st ^ 1, depth + 1);
    doit(res2.se + 1, r, st, depth + 1);
}

int main() {
    scanf("%d", &n);
    init();
    for (int i = 1; i <= n; i++) {
        scanf("%d", p + i);
        push(tree[i & 1], i, p[i]);
        push(tree[i & 1 ^ 1], i, INT_MAX);
    }
    doit(1, n + 1, 1, 0);
    for (int i = 0; i < n; i++) {
        sort(res[i].begin(), res[i].end());
        for (const auto& x: res[i]) printf("%d %d ", x.fi, x.se);
    }
    return 0;
}

