	update(n * 2 + 1,l,mid,s,e), update(n * 2 + 2,mid + 1,r,s,e);
	int lin=n * 2 + 1,rin=n * 2 + 2;

	if(sego[lin].fi < sego[rin].fi) sego[n].fi=sego[lin].fi, sego[n].se=
		sego[lin].se;
	else sego[n].fi=sego[rin].fi, sego[n].se=sego[rin].se;

