void RMI()
{
    for(int i = 2; i <= n; ++i) Log[i] = Log[i >> 1] + 1;
    for(int j = 1; (1 << j) <= n; ++j)
        for(int i = 1; i + (1 << j) - 1 <= n; ++i){
            RM[0][i][j] = a[RM[0][i][j - 1]] < a[RM[0][i + (1 << (j - 1))][j - 1]] ? RM[0][i][j - 1] : RM[0][i + (1 << (j - 1))][j - 1];
            RM[1][i][j] = a[RM[1][i][j - 1]] < a[RM[1][i + (1 << (j - 1))][j - 1]] ? RM[1][i][j - 1] : RM[1][i + (1 << (j - 1))][j - 1];
        }
}

int RMQ(int l, int r, int k)
{
    int Lg = Log[r - l + 1];
    return a[RM[k][l][Lg]] < a[RM[k][r - (1 << Lg) + 1][Lg]] ? RM[k][l][Lg] : RM[k][r - (1 << Lg) + 1][Lg];
}

void Init()
{
    scanf("%d", &n); a[0] = INF;
