{
    node u, v;
    u.x = RMQ(1, n, 1); u.y = RMQ(u.x, n, 0); u.l = 1; u.r = n;
    for(q.push(u); !q.empty();){
        u = q.top(); q.pop();
        printf("%d %d ", a[u.x], a[u.y]);
