        if(v.l < v.r){
            v.x = RMQ(v.l, v.r, v.l & 1);
            v.y = RMQ(v.x, v.r, (v.l & 1) ^ 1);
            q.push(v);
        }

        v.l = u.x + 1; v.r = u.y - 1;
        if(v.l < v.r){
            v.x = RMQ(v.l, v.r, v.l & 1);
            v.y = RMQ(v.x, v.r, (v.l & 1) ^ 1);
