P calc(P p) {
  debug(p.first, p.second);
  vector<P> vec;
  ll l = p.first;
  ll r = p.second;
  ll first;
  if (l%2 == 0) {
    first = E.query(l, r);
  } else {
    first = O.query(l, r);
  }
  ll posfirst = first%mod;
  if (l != posfirst) {
    debug(l, posfirst);
    vec.emplace_back(l, posfirst);
  }
  l = posfirst+1;
  ll second;
  if (l%2 == 0) {
    second = E.query(l, r);
  } else {
    second = O.query(l, r);
  }
  ll possecond = second%mod;
  if (l != possecond) {
    debug(l, possecond);
    vec.emplace_back(l, possecond);
  }
  if (possecond+1 < r) {
    debug(possecond+1, r);
    vec.emplace_back(possecond+1, r);
  }
  mp[p] = vec;
  return {first/mod*mod+p.first, second/mod*mod+p.second};
}

