    logf[1]=0;
    for(int i=2;i<=n;++i) logf[i]=logf[i-1]+((i&(i-1))==0?1:0);
    for(int id=0;id<2;id++)
    {
        auto &sti=st[id];
        for(int i=1;i<=n;i++)
            sti[0][i]=(i%2==id)?i:0;
        for(int i=1;i<=logf[n];i++)
            for(int j=1;j<=n;j++)
            {
                sti[i][j]=sti[i-1][j];
                if(j+(1<<(i-1))<=n)
                    sti[i][j]=minp(sti[i][j],sti[i-1][j+(1<<(i-1))]);
            }
    }
    work(1,n);
    return 0;
}

