inline int lowbit(int x){
	return x & - x;
}
inline void ADD(int x,int k){
	for(;x;x-=lowbit(x)) Del[x]=min(Del[x],k);
}
inline int ASK(int x){
	int Min=Del[x];
	for(;x<=N;x+=lowbit(x)) Min=min(Min,Del[x]);
	return Min;
}
struct kk{
	int l,r,Id1,Id2,Rev;
} T[Max_N*4+10]={};
inline void Build(int x,int l,int r){
	T[x].l=l; T[x].r=r;
	if(l==r){
		if(l%2) T[x].Id1=l;
		else T[x].Id2=l;
		return;
	}
	Build(x<<1,l,(l+r)>>1);
	Build((x<<1)+1,((l+r)>>1)+1,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
//	cout<<T[x].l<<' '<<T[x].r<<' '<<T[x].Id1<<' '<<T[x].Id2<<endl;
}
inline void DownTag(int x){
	if(T[x].Rev){
		swap(T[x<<1].Id1,T[x<<1].Id2);
		swap(T[(x<<1)+1].Id1,T[(x<<1)+1].Id2);
		T[x<<1].Rev^=1; T[(x<<1)+1].Rev^=1;
		T[x].Rev=0;
	}
}
inline void Add(int x,int k,int Val){
	DownTag(x);
	if(T[x].l==T[x].r){
		A[k]=Val;
		return;
	}
	if(k<=T[x<<1].r) Add(x<<1,k,Val);
	else Add((x<<1)+1,k,Val);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline void Change(int x,int l,int r){
	DownTag(x);
	if(l<=T[x].l&&T[x].r<=r){
		swap(T[x].Id1,T[x].Id2);
		T[x].Rev^=1;
		return;
	}
	if(l<=T[x<<1].r) Change(x<<1,l,r);
	if(r>T[x<<1].r) Change((x<<1)+1,l,r);
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
}
inline int Ask(int x,int l,int r,int Opt){
//	cout<<x<<' '<<T[x].l<<' '<<T[x].r<<' '<<l<<' '<<r<<endl;
    DownTag(x);
	if(l<=T[x].l&&T[x].r<=r) return Opt==1?T[x].Id1:T[x].Id2;
	int Ans=0,Anss=0;
	if(l<=T[x<<1].r) Ans=Ask(x<<1,l,r,Opt);
	if(r>T[x<<1].r) Anss=Ask((x<<1)+1,l,r,Opt);
	if(A[Ans]>A[Anss]) Ans=Anss;
	T[x].Id1=A[T[x<<1].Id1]<A[T[(x<<1)+1].Id1]?T[x].Id1=T[x<<1].Id1:T[x].Id1=T[(x<<1)+1].Id1;
	T[x].Id2=A[T[x<<1].Id2]<A[T[(x<<1)+1].Id2]?T[x].Id2=T[x<<1].Id2:T[x].Id2=T[(x<<1)+1].Id2;
	return Ans;
}
inline void Solv(){
	for(int i=1;i<=N/2;i++){
		int Min=Ask(1,1,N,1);
		int r=ASK(Min);
		int Minn=Ask(1,Min,r,2);
//		cout<<Min<<' '<<Minn<<' '<<r<<endl;
		B[i]=make_pair(A[Min],A[Minn]);
		Add(1,Min,1<<30); Add(1,Minn,1<<30);
		if(Min+1<Minn-1) Change(1,Min+1,Minn-1);
		ADD(Min,Min); ADD(Minn,Minn);
	}
}
