	rep(i,n) seg[i%2].update(i, p[i]);
	priority_queue<dat> pq;
	dat pu;
	pu.val = seg[0].query(0,n);
	pu.l = 0; pu.r = n; pu.f = 0;
	pq.emplace(pu);
	vector<int> ans;
	while(!pq.empty()){
		dat d = pq.top(); pq.pop();
		if(d.r - d.l == 0) continue;
		int ano = seg[1-d.f].query(pos[d.val]+1, d.r);
		ans.push_back(d.val);
