        P one = {sect.first, mim.first + 1}, two = {mim.first + 1, mim.second + 1}, three = {mim.second + 1, sect.second};
        que.push({judge(one), one});
        que.push({judge(two), two});
        que.push({judge(three), three});
    }
    for(auto v : res) cout << v << " ";
    cout << endl;
}

