// 0-indexed
template <class T>
struct SegmentTree {
  // a,b,c: T, e:T(unit)
  // abc = (ab)c = a(bc)
  // ae = ea = a
  typedef function<T(T, T)> F;
  int n;
  F f;
  T unit;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(int newn, F f, T t) : f(f), unit(t) { init(newn); }
  SegmentTree(const vector<T> &v, F f, T t) : f(f), unit(t) {
    int _n = v.size();
    init(v.size());
    for (int i = 0; i < _n; ++i) dat[n + i] = v[i];
    for (int i = n - 1; i; --i) dat[i] = f(dat[i << 1], dat[(i << 1) | 1]);
  }
  void init(int newn) {
    n = 1;
    while (n < newn) n <<= 1;
    dat.assign(n << 1, unit);
  }

  // "go up" process
  void update(int k, T newdata) {
    dat[k += n] = newdata;
    while (k >>= 1) {
      dat[k] = f(dat[(k << 1) | 0], dat[(k << 1) | 1]);
    }
  }
  // [a,b)
  T query(int a, int b) {
    T vl = unit, vr = unit;
    for (int l = a + n, r = b + n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) vl = f(vl, dat[l++]);
      if (r & 1) vr = f(dat[--r], vr);
    }
    return f(vl, vr);
  }
};

using P = pair<int, int>;
int n;
vector<int> p;
SegmentTree<P> odd, ev;
vector<P> res;

void solve(int l, int r);

int main() {
  cin >> n;
  p.resize(n);
  for (int &x : p) cin >> x;
  {
    auto f = [](P l, P r) { return min(l, r); };
    odd = SegmentTree<P>(n / 2, f, P(2 * n, 2 * n));
    ev = SegmentTree<P>(n / 2, f, P(2 * n, 2 * n));
    for (int i = 0; i < n / 2; ++i) {
      ev.update(i, P(p[2 * i], 2 * i));
      odd.update(i, P(p[2 * i + 1], 2 * i + 1));
    }
  }
  solve(0, n);
  sort(res.begin(), res.end(), [](P l, P r) {
    return min(l.first, l.second) < min(r.first, r.second);
  });
  for (int i = 0; i < n / 2; ++i)
    cout << res[i].first << " " << res[i].second << " \n"[i == n / 2 - 1];
  return 0;
}

void solve(int l, int r) {
  if (l >= r) return;
  P op = odd.query(l >> 1, r >> 1), ep = ev.query((l + 1) >> 1, (r + 1) >> 1);
  int lid = min(op.second, ep.second), rid = max(op.second, ep.second);
  if ((l ^ lid) & 1) {
    if (op.first > ep.first) {
      if (lid == op.second)
        lid = (op = odd.query(rid >> 1, r >> 1)).second;
      else
        rid = (op = odd.query(l >> 1, lid >> 1)).second;
    } else {
      if (lid == ep.second)
        lid = (ep = ev.query((rid + 1) >> 1, (r + 1) >> 1)).second;
      else
        rid = (ep = ev.query((l + 1) >> 1, (lid + 1) >> 1)).second;
    }
    swap(lid, rid);
  }
  P now(ep.first, op.first);
  if (l & 1) swap(now.first, now.second);
  res.emplace_back(now);
  solve(l, lid);
  solve(lid + 1, rid);
  solve(rid + 1, r);
}

