}
void change(int li,int ri,int no,int t1,int t2){
	if(li>t2||ri<t1) return;
	if(li>=t1&&ri<=t2){
		swap(e[no].mi[0],e[no].mi[1]);swap(e[no].num[0],e[no].num[1]);return;
	} 
	int mid=(li+ri)>>1;
	change(li,mid,e[no].l,t1,t2);change(mid+1,ri,e[no].r,t1,t2);
	e[no].num[0]=(e[e[no].l].mi[0]<e[e[no].r].mi[0])?e[e[no].l].num[0]:e[e[no].r].num[0];
	e[no].num[1]=(e[e[no].l].mi[1]<e[e[no].r].mi[1])?e[e[no].l].num[1]:e[e[no].r].num[1];
