}
void set(pair<int, int>& a, pair<int, int> b) {
    a.first = b.first;
    a.second = b.second;
}
pair<int, int> divide(int k, int l, int r) {
    if(l > r) return mp(-1, -1);
    int pos1 = rmq(k, l, r);
    int pos2 = rmq(k ^ 1, pos1+1, r);
    set(son[0][mp(pos1, pos2)] , divide(l & 1 ? 0 : 1, l, pos1-1));
    set(son[1][mp(pos1, pos2)] , divide((pos1 + 1) & 1?0:1, pos1+1, pos2-1));
    set(son[2][mp(pos1, pos2)] , divide((pos2+1) & 1?0:1, pos2+1, r));
    return mp(pos1, pos2);
} 
