const int mod = 1000000007;
const int inf = 1ll << 61;
typedef pair<int, int> P;


struct RAQ {
	int n = 1;
	vector<int>node, lazy;
	void init(int N) {
		while (n < N)n *= 2;
		node.resize(2 * n - 1);
		lazy.resize(2 * n - 1);
	}
	void eval(int k, int l, int r) {
		if (!lazy[k])return;
		node[k] += lazy[k] * (r - l);
		node[k] %= mod;
		if (k < n - 1) {
			rep(i, 2) {
				lazy[2 * k + i + 1] += lazy[k];
				lazy[2 * k + i + 1] %= mod;
			}
		}
		lazy[k] = 0;
	}
	void update(int a, int b, int x, int k, int l, int r) {
		eval(k, l, r);
		if (r <= a || b <= l)return;
		if (a <= l&&r <= b) {
			lazy[k] += x;
			lazy[k] %= mod;
			eval(k, l, r);
			return;
		}
		update(a, b, x, k * 2 + 1, l, (l + r) / 2);
		update(a, b, x, k * 2 + 2, (l + r) / 2, r);
		node[k] = node[k * 2 + 1] + node[k * 2 + 2];
		node[k] %= mod;
	}
	int calc(int a, int b, int k, int l, int r) {
		eval(k, l, r);
		if (r <= a || b <= l)return 0;
		if (a <= l&&r <= b)return node[k];
		int vl = calc(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = calc(a, b, k * 2 + 2, (l + r) / 2, r);
		return (vl + vr) % mod;
	}
	void add(int a, int b, int x) {
		update(a, b, x, 0, 0, n);
	}
	int getsum(int a, int b) {
		return calc(a, b, 0, 0, n);
	}
};
struct rmq {
	int n;
	vector<P>dat;
	void init(int n_) {
		n = 1;
		while (n < n_)n *= 2;
		dat.resize(2 * n - 1,P( inf,0));
	}
	void update(int k, P a) {
		k += n - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}
	P query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return P(inf,0);
		if (a <= l&&r <= b)return dat[k];
		else {
			return min(query(a, b, 2 * k + 1, l, (l + r) / 2),query(a,b,k*2+2,(l+r)/2,r));
		}
	}
	P getmin(int a, int b) {//[a,b)
		return query(a, b, 0, 0, n);
	}
};

rmq seg[2];
int p[200006];
int fin[200006];

