	Q1.push(P(seg[0].getmin(0, n).first, 0));
	while(Q1.size()) {
		P tp = Q1.top(); Q1.pop();
		int F = tp.first, S = tp.second;
		ans.push_back(F);
		int pos1 = seg[S & 1].getmin(S, fin[S]).second;
		P np = seg[(S + 1) & 1].getmin(pos1 + 1, fin[S]);
		ans.push_back(np.first);
		int pos2 = np.second;

		seg[S & 1].update(pos1, P(inf, 0));
		seg[(S + 1) & 1].update(pos2, P(inf, 0));
	//	cout << S<<' '<<pos1 << ' ' << pos2 << fin[S]<<endl;
		if(pos1-S>=2)Q1.push(P(seg[S & 1].getmin(S, pos1).first, S));
		if(pos2-pos1>=3)Q1.push(P(seg[(pos1 + 1) & 1].getmin(pos1 + 1, pos2).first, pos1 + 1));
		if(fin[S]-pos2>=3)Q1.push(P(seg[(pos2 + 1) & 1].getmin(pos2 + 1, fin[S]).first, pos2 + 1));

		fin[pos1 + 1] = pos2;
		fin[pos2 + 1] = fin[S];
