using namespace std;

struct node{
	int x, y;
};

int mp[200010];
node ans[100010];
node sa[100010];
int n, flag;
node x;

void join(int l1, int r1, int l2, int r2) {
	int len = 1;
	for (len = 1; l1 + len < r1; len++)
		sa[len] = ans[l1 + len];
	int i = 1, j = 1;
	int bg = 1;
	while (i < len && l2 + j < r2) {
		if (sa[i].x < ans[l2 + j].x) {
			ans[l1 + bg] = sa[i];
			i++;
		}else {
			ans[l1 + bg] = ans[l2 + j];
			j++;
		}
		bg++;
	}
	while (i < len) {
		ans[l1 + bg] = sa[i];
		i++;
		bg++;
	}
	while (l2 + j < r2) {
		ans[l1 + bg] = ans[l2 + j];
		j++;
		bg++;
	}
}

void solve(int l, int r, int num) {
	if (r - l == 1)
		return;
	if (r - l == 3) {
		ans[num + 1].x = mp[l + 1];
		ans[num + 1].y = mp[l + 2];
		return;
	}
	int i, j, mi = 2e5 + 10, mj = 2e5 + 10, ii, jj;
	for (i = l + 1; i < r; i += 2) {
		if (mp[i] < mi) {
			mi = mp[i];
			ii = i;
		}
	}
	for (j = ii + 1; j < r; j += 2) {
		if (mp[j] < mj) {
			mj = mp[j];
			jj = j;
		}
	}
	x.x = mi, x.y = mj;
	ans[num + 1].x = mi;
	ans[num + 1].y = mj;
	solve(l, ii, num + 1);
	solve(ii, jj, num + 1 + (ii - l - 1) / 2);
	solve(jj, r, num + 1 + (jj - l - 1) / 2);
	join(num + 1, num + 1 + (ii - l - 1) / 2 + 1, num + 1 + (ii - l - 1) / 2, num + 1 + (jj - l - 1) / 2 + 1);
	join(num + 1, num + 1 + (jj - l - 1) / 2 + 1, num + 1 + (jj - l - 1) / 2, num + 1 + (ii - r - 1) / 2 + 1);
}

