// ----------------------------------------------------------------------

struct seq { ll from; ll to; ll m1; ll m2; };
bool operator< (const seq &x, const seq &y){ return x.m1 > y.m1; };

int main() {
  ll N; cin >> N;
  ll p[N]; rep(i,N) cin >> p[i];
  ll pos[N+1]; rep(i,N) pos[p[i]] = i;

  SegTree st_o(N/2), st_e(N-N/2);
  rep(i,N) {
    if (i%2==0) st_e.update(i/2, p[i]);
    else st_o.update(i/2, p[i]);
  }

  priority_queue<seq> q; q.push({0,N-1,st_e.query(0,N/2),st_o.query(0,N-N/2)});
  // cout << q.top().m1 << " " << q.top().m2 << endl;
  vector<int> result;
  while (q.size()) {
    seq qt = q.top(); q.pop();
    result.push_back(qt.m1); result.push_back(qt.m2);
    // cout << qt.from << " " << qt.to << " " << qt.m1 << " " << qt.m2 << endl;

    if (qt.from!=pos[qt.m1]) {
      ll le = qt.from/2, re = (pos[qt.m1]-1-qt.from%2)/2;
      ll me = qt.from%2==0 ? st_e.query(le,re+1) : st_o.query(le,re+1);
      ll lo = (pos[me]+1)/2, ro = (pos[qt.m1]-(pos[me]+1)%2)/2;
      ll mo = qt.from%2==1 ? st_e.query(lo,ro+1) : st_o.query(lo,ro+1);
      q.push({qt.from,pos[qt.m1]-1,me,mo});
    }
    if (pos[qt.m1]+1!=pos[qt.m2]) {
      ll le = (pos[qt.m1]+1)/2, re = (pos[qt.m2]-1-(pos[qt.m1]+1)%2)/2;
      ll me = (pos[qt.m1]+1)%2==0 ? st_e.query(le,re+1) : st_o.query(le,re+1);
      ll lo = (pos[me]+1)/2, ro = (pos[qt.m2]-1-(pos[me]+1)%2)/2;
      ll mo = (pos[qt.m1]+1)%2==1 ? st_e.query(lo,ro+1) : st_o.query(lo,ro+1);
      q.push({pos[qt.m1]+1,pos[qt.m2]-1,me,mo});
    }
    if (qt.to!=pos[qt.m2]) {
      ll le = (pos[qt.m2]+1)/2, re = (qt.to-(pos[qt.m2]+1)%2)/2;
      ll me = (pos[qt.m2]+1)%2==0 ? st_e.query(le,re+1) : st_o.query(le,re+1);
      ll lo = (pos[me]+1)/2, ro = (qt.to-(pos[me]+1)%2)/2;
      ll mo = (pos[qt.m2]+1)%2==1 ? st_e.query(lo,ro+1) : st_o.query(lo,ro+1);
      q.push({pos[qt.m2]+1,qt.to,me,mo});
    }
  }
  debug(all(result));
  return 0;
}

