const int maxn = 200005;
const int inf = 0x3f3f3f3f;

int n;
int xx[maxn];

#define ls(x) (x << 1)
#define rs(x) (x << 1 | 1)

struct Tree
{
	struct Node
	{
		int jx, ox;
	} no[maxn << 1];

	int k;

	inline int minn(int a, int b)
	{
		if (!a || !b)
			return a | b;
		else
			return xx[a] < xx[b] ? a : b;
	}

	inline void push_up(int k)
	{
		no[k].jx = minn(no[ls(k)].jx, no[rs(k)].jx);
		no[k].ox = minn(no[ls(k)].ox, no[rs(k)].ox);
	}

	inline void build_tree(int n)
	{
		for (k = 1; k <= n; k <<= 1);
		for (int i = 1; i <= n; ++i)
		{
			if (i & 1)
				no[i + k].jx = i;
			else
				no[i + k].ox = i;
		}
		for (int i = k; i; --i)
			push_up(i);
	}

	inline int query(int l, int r, int kk)
	{
		int ans = 0;
		for (l += k - 1, r += k + 1; l ^ r ^ 1; l >>= 1, r >>= 1)
		{
			if (~l & 1)
				ans = minn(kk ? no[l ^ 1].jx : no[l ^ 1].ox, ans);
			if (r & 1)
				ans = minn(kk ? no[r ^ 1].jx : no[r ^ 1].ox, ans);
		}
		return ans;
	}
} tr;

struct QJ
{
	int l, r, ansl, ansr;

	friend bool operator < (QJ a, QJ b)
	{
		return xx[a.ansl] > xx[b.ansl];
	}

	QJ (int l, int r)
	{
		this->l = l;
		this->r = r;
		this->ansl = tr.query(l, r, l & 1);
		this->ansr = tr.query(l, r, r & 1);
	}
};

priority_queue<QJ> q;

int main()
{
	read(n);
	for (int i = 1; i <= n; ++i)
		read(xx[i]);
	tr.build_tree(n);
	q.push(QJ(1, n));
	while (!q.empty())
	{
		QJ now = q.top();
		q.pop();
		writesp(xx[now.ansl]);
		writesp(xx[now.ansr]);
		if (now.ansl + 1 < now.ansr - 1)
			q.push(QJ(now.ansl + 1, now.ansr - 1));
		if (now.l < now.ansl - 1)
			q.push(QJ(now.l, now.ansl - 1));
		if (now.ansr + 1 < now.r)
			q.push(QJ(now.ansr + 1, now.r));
	}
	return 0;
}

