struct SegmentTree {
    struct Node {
        Node operator*(const Node& o) const {
            return { min(v, o.v) };
        }
        int v;
    };

    SegmentTree(int n) : e({ 1 << 30 }), n(n) {
        for (m = 2; m < n; m *= 2); // m >= n
        t = vector<Node>(m + n + n % 2, e);
    }
    Node *data() {
        return &t[m];
    }
    void build() {
        for (int i = (n - 1 + m) / 2; i > 0; i--) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    const Node& root() const {
        return t[1];
    }
    void update(int i, const Node& o) {
        for (t[i += m] = o; i /= 2, i > 0;) t[i] = t[i * 2] * t[i * 2 + 1];
    }
    Node query(int l, int r) const {
        Node o[2] = { e, e };
        for (l += m, r += m; l < r; l /= 2, r /= 2) {
            if (r & 1) o[1] = t[--r] * o[1];
            if (l & 1) o[0] = o[0] * t[l++];
        }
        return o[0] * o[1];
    }
    void print() {
        for (int j = 1; j <= m; j *= 2) {
            int k = min(j * 2, m + n);
            for (int i = j; i < k; i++) {
                cout << t[i].v << " \n"[i == k - 1];
            }
        }
    }
    vector<Node> t;
    const Node e;
    int n, m;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<int> r(n), p(n + 1);
    for (int i = 0; i < n; i++) {
        cin >> r[i];
        p[r[i]] = i;
    }

    SegmentTree st[2] = { n / 2, n / 2 };
    for (int i = 0; i < n; i++) {
        st[i % 2].data()[i / 2].v = r[i];
    }
    for (int j = 0; j < 2; j++) {
        st[j].build();
    }

    using A = array<int, 3>;
    priority_queue<A, vector<A>, greater<>> q;
    q.push({ st[0].root().v, 0, n });

    for (int i = 0; i < n; i += 2) {
        auto a = q.top(); q.pop();
        r[i] = a[0];
        int p0 = p[r[i]];
        int j = p0 % 2;
        st[j].update(p0 / 2, st[j].e);

        r[i + 1] = st[j ^ 1].query((p0 + 1) / 2, (a[2] + 1) / 2).v;
        int p1 = p[r[i + 1]];
        st[j ^ 1].update(p1 / 2, st[j ^ 1].e);

        auto f = [&](int l, int r) {
            if (l == r) return;
            q.push({ st[l % 2].query(l / 2, r / 2).v, l, r });
        };
        f(a[1], p0);
        f(p0 + 1, p1);
        f(p1 + 1, a[2]);
    }

    for (int i = 0; i < n; i++) {
        cout << r[i] << " \n"[i == n - 1];
    }

    return 0;
}

#include <bits/stdc++.h>

std::vector<int> f(std::vector<int>& v, int l, int r) {
    if (r - l < 2) return {};
    int fi = l;
    for (int i = l; i < r; i += 2) if (v[fi] > v[i]) fi = i;
    int bi = fi + 1;
    for (int i = fi + 1; i < r; i += 2) if (v[bi] > v[i]) bi = i;

    auto lv = f(v, l, fi);
    auto mv = f(v, fi + 1, bi);
    auto rv = f(v, bi + 1, r);
    std::vector<std::pair<int, int>> lw(lv.size() / 2), mw(mv.size() / 2 + 1), rw(rv.size() / 2);
    for (int i = 0; i < lw.size(); i++) lw[i] = std::make_pair(lv[2 * i], lv[2 * i + 1]);
    mw[0] = std::make_pair(v[fi], v[bi]);
    for (int i = 1; i < mw.size(); i++) mw[i] = std::make_pair(mv[2 * i - 2], mv[2 * i - 1]);
    for (int i = 0; i < rw.size(); i++) rw[i] = std::make_pair(rv[2 * i], rv[2 * i + 1]);

    std::vector<std::pair<int, int>> res1, res2;
    res1.reserve(lw.size() + mw.size());
    res2.reserve(lw.size() + mw.size() + rw.size());
    std::merge(lw.begin(), lw.end(), mw.begin(), mw.end(), std::back_inserter(res1));
    std::merge(res1.begin(), res1.end(), rw.begin(), rw.end(), std::back_inserter(res2));

    std::vector<int> res;
    res.reserve(r - l);
    for (auto& el : res2) {
        res.push_back(el.first);
        res.push_back(el.second);
    }

    return res;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> p(n);
    for (int i = 0; i < n; i++) std::cin >> p[i];

    auto q = f(p, 0, p.size());

    for (int i = 0; i < n; i++) std::cout << q[i] << " ";
    std::cout << std::endl;

    return 0;
}

