//SegmentTree(セグ木)
template <class T>
class SegmentTree {
private:
	T init_val;
	std::vector<T> ary;
	std::function<T(T, T)> func;
public:
	// 使用例(データの大きさNとする)
	// SegmentTree<T> st(N,  INF, [](T l, T r){return std::min(l, r);}); 最小値
	// SegmentTree<T> st(N, -INF, [](T l, T r){return std::max(l, r);}); 最大値
	// SegmentTree<T> st(N,    0, [](T l, T r){return l+r;});            合計
	SegmentTree(int n, T val, std::function<T(T, T)> f) : init_val(val), func(f) {
		ary.resize(static_cast<int>(std::pow(2, std::ceil(std::log(n) / std::log(2)) + 1) - 1), val);
	}
	void init(int n, T val, std::function<T(T, T)> f) {
		ary.resize(static_cast<int>(std::pow(2, std::ceil(1.0*std::log(n) / std::log(2)) + 1) - 1), val);
		init_val = val;
		func = f;
	}
	void update(int i, T val) {
		i += ary.size() / 2;
		ary[i] = val;
		while (i > 0) {
			i = (i - 1) / 2;
			ary[i] = func(ary[2 * i + 1], ary[2 * i + 2]);
		}
	}
	// 区間[a, b)のfuncの返す値を返す (query_(a, b, 0, 0, n)と呼び出す)
	T query_(int a, int b, int i, int l, int r) {
		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return ary[i];
		else {
			T vl = query_(a, b, 2 * i + 1, l, (l + r) / 2);
			T vr = query_(a, b, 2 * i + 2, (l + r) / 2, r);
			return func(vl, vr);
		}
	}
	// 上限(b)は少し大きめに取るべし
	T query(int a, int b) {
		return query_(a, b, 0, 0, ary.size() / 2 + 1);
	}
};

signed main() {
	INIT;
	VAR(int, n);
	VEC(int, p, n);
	std::vector<int> inv(n);

	REP(i, n) {
		--p[i];
		inv[p[i]] = i;
	}
	SegmentTree<int> odd(n, INFINT, [](int l, int r) {return std::min(l, r); }), even(n, INFINT, [](int l, int r) {return std::min(l, r); });

	REP(i, n) {
		if (i % 2 == 0) {
			odd.update(i, p[i]);
		}
		else {
			even.update(i, p[i]);
		}
	}

	auto calc = [&](PAIR p) {
		int l = p.first, r = p.second;
		int minL, minR;
		int posL;
		if (l % 2 == 0) {
			minL = odd.query(l, r+1);
			posL = inv[minL];
			minR = even.query(posL+1, r+1);
		}
		else {
			minL = even.query(l, r+1);
			posL = inv[minL];
			minR = odd.query(posL+1, r+1);
		}
		return PAIR(minL, minR);
	};

	struct P {
		int l, r, ml, mr;
		P() {}
		P(int l, int r, int ml, int mr) :l(l), r(r), ml(ml), mr(mr){}
		bool operator<(const P rr) const {
			return ml > rr.ml;
		}
	};
	std::priority_queue<P> pq;
	{
		PAIR min(calc(PAIR(0, n - 1)));
		pq.push(P(0, n - 1, min.first, min.second));
	}
	while (!pq.empty()) {
		P now;
		while (!pq.empty()) {
			now = pq.top(); pq.pop();
			if (now.l >= now.r) continue;
			break;
		}
		if (now.l >= now.r) break;
		OUT(now.ml + 1)SP OUT(now.mr + 1)SP;
		int posL = inv[now.ml];
		int posR = inv[now.mr];
		{
			auto min(calc(PAIR(now.l, posL - 1)));
			pq.push(P(now.l, posL - 1, min.first, min.second));
		}
		{
			auto min(calc(PAIR(posL+1, posR-1)));
			pq.push(P(posL + 1, posR - 1, min.first, min.second));
		}
		{
			auto min(calc(PAIR(posR + 1, now.r)));
			pq.push(P(posR + 1, now.r, min.first, min.second));
		}
	}
	BR;
	return 0;
}

