const int N = 200054, LN = 18;

struct range {
	int l, r, v;
	range (int l_ = 0, int r_ = 0, int v_ = 0) : l(l_), r(r_), v(v_) {}
	inline bool operator < (const range &B) const;
	inline int fulfill() const;
};

int n;
int p[N], st[LN][N];
std::priority_queue <range> pq;

inline int min(const int x, const int y) {return p[x] < p[y] ? x : y;}

void build_sparse_table() {
	int *f, *g = *st, i, j, k = n;
	for (i = 0; i < n / 2; ++i) g[i] = i * 2, g[i + n / 2] = i * 2 + 1;
	for (j = 0; 1 << (j + 1) <= n; ++j) {
		f = g, g = st[j + 1], k -= 1 << j;
		for (i = 0; i < k; ++i)
			g[i] = min(f[i], f[i + (1 << j)]);
	}
}

inline int query(int L, int R) {int c = lg2(R - L); return min(st[c][L], st[c][R - (1 << c)]);}
inline bool range::operator < (const range &B) const {return p[v] > p[B.v];}
inline int range::fulfill() const {return l & 1 ? query((v + 1) / 2, (r + 1) / 2) : query((v + n) / 2, (r + n) / 2);}

inline void insert(int l, int r) {
	if (l == r) return;
	assert(!((l ^ r) & 1)), pq.emplace(l, r, l & 1 ? query((l + n) / 2, (r + n) / 2) : query(l / 2, r / 2));
}

