const int N = 2e5;
int pos[N + 5];
int ST[2][2 * N + 5];
int arr[N + 5];

void build(int k,int idx,int l,int r) {
	if(l == r) {
		ST[k][idx] = arr[2 * l + k];
		return ;
	}
	int mid = (l + r) / 2;
	build(k, 2 * idx, l, mid), build(k, 2 * idx + 1,mid + 1, r);
	ST[k][idx] = min(ST[k][2 * idx], ST[k][2 * idx + 1]);
}

priority_queue<pair<pair<int,int>, pair<int,int> > > pq;
int n;

int query(int k,int idx,int l,int r,int le,int ri) {
	if(r < le || ri < l) return 1e9;
	if(le <= l && r <= ri) return ST[k][idx];
	int mid = (l + r) / 2;
	return min(query(k, 2 * idx, l, mid, le, ri), query(k, 2 * idx + 1,mid + 1, r, le, ri));
}

vector<int> solve(int l,int r) {
	vector<int> res;
	int rl = query(0, 1, 0, n / 2 - 1, l / 2, r / 2);
	int rr = query(1, 1, 0, n / 2 - 1, pos[rl] / 2, r / 2);
	pq.push({{-rl, -rr}, {l, r}});
	while(!pq.empty()) {
		int rl = -pq.top().FI.FI;
		int rr = -pq.top().FI.SE;
		int l = pq.top().SE.FI;
		int r = pq.top().SE.SE;
		pq.pop();
		res.PB(rl), res.PB(rr);
		int pl = pos[rl];
		int pr = pos[rr];
//		cout<<"TEST "<<rl<<" "<<rr<<" "<<l<<" "<<pl<<" "<<pr<<" "<<r<<endl;
		if(l < pl - 1) {
			int flag = (l & 1);
			int rl = query(flag, 1, 0, n / 2 - 1, l / 2, (pl - 2) / 2);
			int rr = query(1 ^ flag, 1, 0, n / 2 - 1, (pos[rl] + 1) / 2, (pl - 1) / 2);
			pq.push({{-rl, -rr}, {l, pl - 1}});
		}
		if(pl + 1 < pr - 1) {
			int flag = ((pl + 1) & 1);
			int rl = query(flag, 1, 0, n / 2 - 1, (pl + 1) / 2, (pr - 2) / 2);
			int rr = query(1 ^ flag, 1, 0, n / 2 - 1, (pos[rl] + 1)/ 2, (pr - 1) / 2);
//			cout<<"HMMM " <<flag<<" "<<pl + 1<<" "<<pos[rl]<<" "<<pr - 1<<endl;
//			cout<<"RL "<<rl<<" "<<rr<<endl;
			pq.push({{-rl, -rr}, {pl + 1, pr - 1}});
		}
		if(pr + 1 < r) {
			int flag = ((pr + 1) & 1);
			int rl = query(flag, 1, 0, n / 2 - 1, (pr + 1) / 2, r / 2);
			int rr = query(1 ^ flag, 1, 0, n / 2 - 1, (pos[rl] + 1) / 2, r / 2);
			pq.push({{-rl, -rr}, {pr + 1, r}});
		}
	}
	return res;
}

