#include <bits/stdc++.h>

using namespace std;


#define MAXN 200001

template <class T>
struct sparse_table {
  const vector<T> &x;
  vector<vector<int>> table;
  int height;

  int lg2(int k) {  // returns largest p for which 2^p <= k
    return sizeof(int)*8 - 1 - __builtin_clz(k);
  }

  int argmin(int i, int j) {
    return x[i] < x[j] ? i : j;
  }

  sparse_table(const vector<T> &x) : x(x) {
    height = lg2(x.size());
    table.assign(height+1, vector<int>(x.size()));
    iota(table[0].begin(), table[0].end(), 0);
    for (int h = 0; h < height; ++h) {
      for (int i = 0; i+(1<<h) < x.size(); ++i) {
        table[h+1][i] = argmin(table[h][i], table[h][i+(1<<h)]);
      }
    }
  }

  T rmq(int i, int j) {
    int h = lg2(j-i);
    return x[argmin(table[h][i], table[h][j - (1<<h)])];
  }
};



int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  int n, ind[MAXN];
  cin >> n;
  vector<int> a[2];
  a[0].assign(n, MAXN+10);
  a[1].assign(n, MAXN+10);
  for (int i = 0; i < n; ++i) {
    cin >> a[i%2][i];
    ind[a[i%2][i]] = i;
  }
  sparse_table<int> st[2] = {a[0], a[1]};
  priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>> > pq;
  pq.push({st[0].rmq(0, n), {0, n}});
  int ans[MAXN];
  for (int i = 0; i < n/2; ++i) {
    auto el = pq.top();
    pq.pop();
    int x = el.second.first;
    int y = el.second.second;
    ans[2*i] = st[x%2].rmq(x, y);
    int I = ind[ans[2*i]];
    ans[2*i+1] = st[!(x%2)].rmq(I+1, y);
    int J = ind[ans[2*i+1]];
    if (x<I) pq.push({st[x%2].rmq(x, I), {x, I}});
    if (I+1<J) pq.push({st[!(x%2)].rmq(I+1, J), {I+1, J}});
    if (J+1<y) pq.push({st[x%2].rmq(J+1, y), {J+1, y}});
