const int INF = 1e9;

struct SegmentTree{
    int n, width;
    VI dat[2];

    void init(int x){
        n = x;
        dat[0].resize(4*n);
        dat[1].resize(4*n);
        width = 1;
        while(width < n) width *= 2;
        REP(j,2) REP(i,2*width-1) dat[j][i] = INF;
    }

    void update(int i, int x, int k){
        i += width-1;
        dat[k][i] = x;
        while (i>0){
            i = (i-1)/2;
            dat[k][i] = min(dat[k][i*2+1],dat[k][i*2+2]);
        }
    }

    int query(int a, int b, int k, int l, int r, int p){
        if (r<=a || b<=l) return INF;
        if (a<=l && r<=b) return dat[p % 2][k];
        int vl = query(a,b,k*2+1,l,(l+r)/2,p);
        int vr = query(a,b,k*2+2,(l+r)/2,r,p);
        return min(vl,vr);
    }
};

int n, a[200010], pos[200010];
SegmentTree sg;
vector<P> ans;

pair<P, pair<P, P> > calc(int l, int r){
    if (r <= 0 || l >= n || l >= r) return make_pair(P(INF,INF), make_pair(P(INF, INF), P(INF, INF)));
    // cout << l << r << endl;
    int mi = sg.query(l,r,0,0,sg.width,l%2);
    int j = pos[mi];
    int mi2 = sg.query(j+1,r,0,0,sg.width,(j+1)%2);
    int j2 = pos[mi2];
    return make_pair(P(mi, mi2), make_pair(P(j, j2), P(l, r)));
}

int main(){
    cin >> n;
    REP(i,n){
        scanf("%d", &a[i]);
        pos[a[i]] = i;
    }

    sg.init(n);
    REP(i,n){
        sg.update(i, a[i], i%2);
    }

    priority_queue<pair<P, pair<P, P> >, vector<pair<P, pair<P, P> > >, greater<pair<P, pair<P, P> > > > pq;
    pq.push(calc(0,n));

    while (ans.size() < n/2){
        pair<P, pair<P, P> > p = pq.top();
        pq.pop();
        ans.push_back(p.first);
        int l = p.second.second.first, r = p.second.second.second;
        int j1 = p.second.first.first, j2 = p.second.first.second;
        pq.push(calc(l,j1));
        pq.push(calc(j1+1,j2));
        pq.push(calc(j2+1,r));
    }

    REP(i,n/2) printf("%d %d ", ans[i].first, ans[i].second);
    cout << endl;

    return 0;
}

