void build(pair<int, int>* arb, int par, int nod, int st, int dr)
{
    if(st == dr)
    {
        if((par && st % 2 == 0) || (!par && st % 2 != 0))
            arb[nod] = make_pair(v[st], st);
        else arb[nod] = make_pair(inf, inf);
        return;
    }
    int mij = (st + dr) / 2;
    build(arb, par, nod * 2, st, mij);
    build(arb, par, nod * 2 + 1, mij + 1, dr);
    arb[nod] = min(arb[nod * 2], arb[nod * 2 + 1]);
}

