pair<int, int> query(pair<int, int>* arb, int nod, int st, int dr, int ist, int idr)
{
    if(ist <= st && dr <= idr)
    {
        return arb[nod];
    }
    int mij = (st + dr) / 2;
    pair<int, int> q1 = make_pair(inf, inf), q2 = make_pair(inf, inf);
    if(ist <= mij)
        q1 = query(arb, nod * 2, st, mij, ist, idr);
    if(idr > mij)
        q2 = query(arb, nod * 2 + 1, mij + 1, dr, ist, idr);
    return min(q1, q2);
}

int n;
using vecpair = vector<pair<int, int> >;

vecpair solve(int st, int dr, pair<int, int>* arb1, pair<int, int>* arb2)
{
    vecpair res;
    if(st > dr)
        return res;
    auto start = query(arb1, 1, 1, n, st, dr);
    auto fin = query(arb2, 1, 1, n, start.second + 1, dr);
    res.emplace_back(start.first, fin.first);
    auto v1 = solve(st, start.second - 1, arb1, arb2);
    auto v2 = solve(start.second + 1, fin.second - 1, arb2, arb1);
    auto v3 = solve(fin.second + 1, dr, arb1, arb2);

    vecpair dest1;
    std::merge(v1.begin(), v1.end(), v2.begin(), v2.end(), std::back_inserter(dest1));
    std::merge(v3.begin(), v3.end(), dest1.begin(), dest1.end(), std::back_inserter(res));
    return res;
}

