        cin >> v[i];
    build(arbp, 1, 1, 1, n);
    build(arbq, 0, 1, 1, n);
    auto r = solve(1, n, arbq, arbp);
    for(auto p : r)
    {
        cout << p.first << ' ' << p.second << ' ';
    }
    return 0;
}

