const int MAXN = 2e5 + 6;
const ll INF = 2e18;
int t1[4 * MAXN];
int t2[4 * MAXN];

map<int, int> pos;

int mn(int par, int v, int tl, int tr, int l, int r) {
	auto &t = (par == 0 ? t1 : t2);

	if (l > r)
		return 1e9;
	if (l == tl && r == tr) {
		return t[v];
	}
	int tm = (tl + tr) / 2;
	return min(mn(par, v*2, tl, tm, l, min(r, tm)),
		    mn(par, v*2+1, tm+1, tr, max(l, tm+1), r));
}

void update(int par, int v, int tl, int tr, int pos, int new_val) {
	auto &t = (par == 0 ? t1 : t2);

	if (tl == tr) {
		t[v] = new_val;
	} else {
		int tm = (tl + tr) / 2;
		if (pos <= tm)
			update(par, v*2, tl, tm, pos, new_val);
		else
			update(par, v*2+1, tm+1, tr, pos, new_val);
		t[v] = min(t[v*2], t[v*2+1]);
	}
}

int a[MAXN];
set<pair<int, int>> s;

set<pair<pair<int, int>, int>> p;

int b[MAXN];

int main() {
	#ifdef LOCAL
	setIn("in.txt");
	setOut("out.txt");
	#endif

	int n;
	cin >> n;

	p.insert({{n - 1, 0}, 0});
	for(int i = 0; i < n; i++){
		update(0, 1, 0, n - 1, i, 1e9);
		update(1, 1, 0, n - 1, i, 1e9);

	}

	for(int i = 0; i < n; i++){
		cin >> a[i];
		pos[a[i]] = i;

		if(i % 2 == 0) s.insert({a[i], 0});
		update(i % 2, 1, 0, n - 1, i, a[i]);
	}
	for(int i = 0; i < n / 2; i++){
		auto cur = s.begin();
		b[2 * i] = cur->first;

		auto interval = p.upper_bound({{pos[cur->first], 1e9}, -1});
		int l = interval->first.second, r = interval->first.first;
		int par = interval->second;
		p.erase(interval);

		int m = mn(!par, 1, 0, n - 1, pos[cur->first] + 1, r);
		b[2 * i + 1] = m;
		update(par, 1, 0, n - 1, pos[m], 1e9);

		if(r != l + 1){
			s.insert({mn((l + 1) % 2, 1, 0, n - 1, pos[cur->first] + 1, pos[m] - 1), (l + 1) % 2});
			p.insert({{pos[m] - 1, pos[cur->first] + 1}, !par});
		}

		if(pos[cur->first] - 1 > l) {
			s.insert({mn(l % 2, 1, 0, n - 1, l, pos[cur->first] - 1), l % 2});
			p.insert({{pos[cur->first] - 1, l}, par});
		}
		if(r > pos[m] + 1) {
			p.insert({{r, pos[m] + 1}, par});
			s.insert({mn((pos[m] + 1) % 2, 1, 0, n - 1, pos[m] + 1, r), (pos[m] + 1) % 2});
		}
		auto pls = s.upper_bound({m, -1});
		if(pls != s.end() && pls->first == m) s.erase(pls);
		s.erase(cur);
	}

	for(int i = 0; i < n; i++){
		cout << b[i] << " " ;
	}
}

