#define N 200000
using namespace std;
int n;
int a[N],wz[N];
bool del1;
struct node{
	int x[2];
	bool bz;
	int sum;
}f[N*4];
void combine(int x){
	f[x].x[0]=min(f[x+x].x[0],f[x+x+1].x[0]);
	f[x].x[1]=min(f[x+x].x[1],f[x+x+1].x[1]);
	f[x].sum=f[x+x].sum+f[x+x+1].sum;
}
void build(int l,int r,int s){
	if (l==r){
		f[s].x[l&1]=a[l];
		f[s].x[(l&1)^1]=n+1;
		f[s].sum=1;
		return;
	}
	build(l,(l+r)/2,s+s),build((l+r)/2+1,r,s+s+1);
	combine(s);
}
void down(int l,int r,int s){
	if (f[s].bz){
		swap(f[s].x[0],f[s].x[1]);
		f[s].bz=0;
		if (l!=r){
			f[s+s].bz^=1,f[s+s+1].bz^=1;
		}
	}
}

int find1(int l,int r,int s,int ll,bool sig){
	down(l,r,s);
	if (r<ll)return n+1;
	if (f[s].x[sig]==n+1)return n+1;
	if (l>=ll)return f[s].x[sig];
	return min(find1(l,(l+r)/2,s+s,ll,sig),find1((l+r)/2+1,r,s+s+1,ll,sig));
}
int find(int l,int r,int s,int ll,bool sig){
	down(l,r,s);
	if (r<ll)return n+1;
	if (f[s].x[sig]==n+1)return n+1;
	if (l>=ll&&f[s].sum==r-l+1)return f[s].x[sig];
	int x=find(l,(l+r)/2,s+s,ll,sig);
	if (del1)return x;
	int y=find((l+r)/2+1,r,s+s+1,ll,sig);
	if ((l+r)/2+1>=ll&&f[s+s+1].sum!=(r-((l+r)/2+1)+1))del1=1;
	return min(x,y);
}
int get(int l,int r,int s,int ll){
	down(l,r,s);
	if (l==r)return f[s].x[1]==a[l];
	if ((l+r)/2>=ll)return get(l,(l+r)/2,s+s,ll);
	else
		return get((l+r)/2+1,r,s+s+1,ll);
}
void del(int l,int r,int s,int ll){
	down(l,r,s);
	if (r<ll||l>ll)return;
	if (l==r){
		f[s].x[0]=f[s].x[1]=n+1;
		f[s].sum--;
		return;
	}
	del(l,(l+r)/2,s+s,ll);
	del((l+r)/2+1,r,s+s+1,ll);
	combine(s);
}
void change(int l,int r,int s,int ll,int rr){
	down(l,r,s);
	if (rr<l||r<ll)return;
	if (ll<=l&&r<=rr){
		f[s].bz=1;
		down(l,r,s);
		return;
	}
	change(l,(l+r)/2,s+s,ll,rr),change((l+r)/2+1,r,s+s+1,ll,rr);
	combine(s);
}
