template <typename T>
class Rmq {
public:
	int n;
	vector<T> dat;
	void init(int _n) {
		n = 1;
		while (n < _n) {
			n *= 2;
		}
		dat.resize(2 * n);
		rep(i, n * 2 - 1) {
			dat[i] = P(INF, i - n + 1);
		}
	}

	void update(int k, int x) {
		int pos = k;
		k += n - 1;
		dat[k] = P(x, pos);
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
		}

	}

	T find(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)
			return P(INF, -1);
		if (a <= l && r <= b)
			return dat[k];
		else {
			T x1, x2;
			x1 = find(a, b, k * 2 + 1, l, (l + r) / 2);
			x2 = find(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(x1, x2);
		}
	}
};


