int tr1[maxn<<2],tr2[maxn<<2],tr3[maxn];
bool rev[maxn];
int Min(int x,int y){
	return x<y?x:y;
}
void push_up(int h){
	tr1[h]=Min(tr1[h<<1],tr1[h<<1|1]);
	tr2[h]=Min(tr2[h<<1],tr2[h<<1|1]);
}
void push_down(int h){
	if(rev[h]){
		swap(tr1[h<<1],tr2[h<<1]);
		swap(tr1[h<<1|1],tr2[h<<1|1]);
		rev[h<<1]^=1,rev[h<<1|1]^=1;
		rev[h]=0;
	}
}
int cas;
void build_tree(int h,int l,int r){
	if(l==r)
	{
		if(l%2==1)
			tr1[h]=a[l],tr2[h]=INF;
		else
			tr1[h]=INF,tr2[h]=a[l];
		return;
	}
	int mid=(l+r)>>1;
	build_tree(h<<1,l,mid);
	build_tree(h<<1|1,mid+1,r);
	push_up(h);
}
int quryps(int x){
	int res=0;
	while(x){
		res=res+tr3[x];
		x-=x&(-x);
	}
	return res;
}
void updataps(int x,int v){
	while(x<=n){
		tr3[x]+=v;
		x+=x&(-x);
	}
}
int quryp(int x){
	int l=x,r=n,mid,v=quryps(x);
	while(r-l>1){
		mid=(l+r)>>1;
		if(quryps(mid)-v==mid-x)
			l=mid;
		else
			r=mid;
	}
	if(quryps(r)-v==r-x)
		l=r;
	return l;
}
int qury2(int h,int l,int r,int s,int t){
	if(s<=l&&t>=r)
	{
		return tr2[h];
	}
	int mid=(l+r)>>1;
	push_down(h);
	if(t<=mid)
		return qury2(h<<1,l,mid,s,t);
	else if(s>mid)
		return qury2(h<<1|1,mid+1,r,s,t);
	else
	{
		int res=qury2(h<<1,l,mid,s,mid);
		res=Min(res,qury2(h<<1|1,mid+1,r,mid+1,t));
		return res;
	}
}
void updata(int h,int l,int r,int p){
	if(l==p&&r==p){
		tr1[h]=INF,tr2[h]=INF;
		return;
	}
	int mid=(l+r)>>1;
	push_down(h);
	if(p<=mid)
		updata(h<<1,l,mid,p);
	else
		updata(h<<1|1,mid+1,r,p);
	push_up(h);
}
void rever(int h,int l,int r,int s,int t){
	if(s<=l&&t>=r){
		rev[h]^=1;
		swap(tr1[h],tr2[h]);
		return;
	}
	int mid=(l+r)>>1;
	push_down(h);
	if(t<=mid)
		rever(h<<1,l,mid,s,t);
	else if(s>mid)
		rever(h<<1|1,mid+1,r,s,t);
	else
	{
		rever(h<<1,l,mid,s,mid);
		rever(h<<1|1,mid+1,r,mid+1,t);
	}
	push_up(h);
}
