using namespace std;

struct node{
	int x, y;
};

int mp[200010];
int n, flag;
node x;

void join(queue<node> &q1, queue<node> &q2) {
	queue<node> q;
	while (! q1.empty() && ! q2.empty()) {
		if (q1.front().x < q2.front().x) {
			q.push(q1.front());
			q1.pop();
		}else {
			q.push(q2.front());
			q2.pop();
		}
	}
	while (! q1.empty()) {
		q.push(q1.front());
		q1.pop();
	}
	while (! q2.empty()) {
		q.push(q2.front());
		q2.pop();
	}
	q1 = q;
}

void solve(int l, int r, queue<node> &q) {
	if (r - l == 1)
		return;
	if (r - l == 3) {
		x.x = mp[l + 1];
		x.y = mp[l + 2];
		q.push(x);
		return;
	}
	int i, j, mi = 2e5 + 10, mj = 2e5 + 10, ii, jj;
	for (i = l + 1; i < r; i += 2) {
		if (mp[i] < mi) {
			mi = mp[i];
			ii = i;
		}
	}
	for (j = ii + 1; j < r; j += 2) {
		if (mp[j] < mj) {
			mj = mp[j];
			jj = j;
		}
	}
	x.x = mi, x.y = mj;
	q.push(x);
	queue<node> q1, q2, q3;
	solve(l, ii, q1);
	solve(ii, jj, q2);
	solve(jj, r, q3);
	if (q1.empty() || q2.empty())
		q1 = q2;
	else
		join(q1, q2);
	if (q1.empty() || q3.empty())
		q1 = q3;
	else
		join(q1, q3);
	while (! q1.empty()) {
		q.push(q1.front());
		q1.pop();
	}
}

