struct SegmentTree {
	int data[4 * MAX_N];

	SegmentTree() {
		for(int i = 1; i < 4 * MAX_N; i++) {
			data[i] = INF;
		}
	}

	void update(int node, int le, int ri, int ind, int val) {
		if(le > ind || ri < ind) {
			return; 
		}
		else if(le == ind && ri == ind) {
			data[node] = val;
			return;
		}

		int mid = (le + ri) / 2;
		update(2 * node, le, mid, ind, val);
		update(2 * node + 1, mid + 1, ri, ind, val);

		data[node] = min(data[2 * node], data[2 * node + 1]);
	}

	int query(int node, int le, int ri, int q_le, int q_ri) {
		if(le > q_ri || ri < q_le) {
			return INF;
		}
		else if(le >= q_le && ri <= q_ri) {
			return data[node];
		}

		int mid = (le + ri) / 2;
		return min(query(2 * node, le, mid, q_le, q_ri), query(2 * node + 1, mid + 1, ri, q_le, q_ri));
	}
} even, odd;

int n, ind_of[MAX_N];
vector< Pair > ans;

void solve(int le, int ri, int time) {
	if(le > ri) {
		return;
	}
	else if(le % 2 != 0) {
		int a = odd.query(1, 1, n, le, ri);
		int b = even.query(1, 1, n, ind_of[a], ri);

		ans.pb(Pair(a, b, time));
		solve(le, ind_of[a] - 1, time + 1);
		solve(ind_of[a] + 1, ind_of[b] - 1, time + 1);
		solve(ind_of[b] + 1, ri, time + 1);
	}
	else {
		int a = even.query(1, 1, n, le, ri);
		int b = odd.query(1, 1, n, ind_of[a], ri);

		ans.pb(Pair(a, b, time));
		solve(le, ind_of[a] - 1, time + 1);
		solve(ind_of[a] + 1, ind_of[b] - 1, time + 1);
		solve(ind_of[b] + 1, ri, time + 1);
	}
}

int main() {
	scanf(" %d", &n);

	for(int i = 1; i <= n; i++) {
		int a;
		scanf(" %d", &a);

		if(i % 2 == 0) {
			even.update(1, 1, n, i, a);
		}
		else {
			odd.update(1, 1, n, i, a);
		}

		ind_of[a] = i;
	}

	solve(1, n, 0);

	sort(ans.begin(), ans.end());

	for(Pair p : ans) {
		printf("%d %d ", p.a, p.b);
	}
	printf("\n");

	return 0;
}

