#include <bits/stdc++.h>
using namespace std;

const int maxn = 2e5 + 10, inf = 1e9 + 1;
int p[maxn], pos[maxn], q[maxn], fr[maxn], ba[maxn];

struct SegmentTree {
#define M ((L + R) >> 1)
    int val;
    SegmentTree *lc, *rc;
    SegmentTree(int L, int R) {
        lc = rc = nullptr;
        val = inf;
        if (L == R) {
            val = p[L];
            return;
        }
        lc = new SegmentTree(L, M); rc = new SegmentTree(M + 1, R);
        pull();
    }
    void pull() {
        val = min(lc->val, rc->val);
    }
    void modify(int L, int R, int x, int v) {
        if (L == R) {
            val = v;
            return;
        }
        if (x <= M) lc->modify(L, M, x, v);
        else rc->modify(M + 1, R, x, v);
        pull();
    }
    int query(int L, int R, int l, int r) {
        if (L > r || l > R) return inf;
        if (L >= l && R <= r) return val;
        return min(lc->query(L, M, l, r), rc->query(M + 1, R, l, r));
    }
} *st;

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n;
    for (int i = 1; i <= n; ++i) cin >> p[i], pos[p[i]] = i;
    // for (int i = 1; i <= n; ++i) cout << pos[i] << ' '; cout << endl;
    for (int i = 1; i <= n; ++i) ba[p[i]] = p[i + 1];
    st = new SegmentTree(1, n);
    int ind = n;
    set<int> s;
    for (int i = 1; i <= n; ++i) s.insert(i);
    for (int i = 0; i < n / 2; ++i) {
        auto it = s.end(); --it; --it; --it; --it;
        int r = *it;
        // cout << "r = " << r << endl;
        if (s.size() <= 2) {
            int a = st->query(1, n, 1, n);
            st->modify(1, n, pos[a], inf);
            int b = st->query(1, n, 1, n);
            st->modify(1, n, pos[b], inf);
            if (pos[a] > pos[b]) swap(a, b);
            // cout << a << ' ' << b << endl;
            q[1] = a; q[2] = b;
            break;
        }
        int v = st->query(1, n, 1, r);
        q[ind - 1] = ba[v]; q[ind] = ba[ba[v]];
        // cout << ba[v] << ' ' << ba[ba[v]] << endl;
        ind -= 2;
        st->modify(1, n, pos[ba[v]], inf); st->modify(1, n, pos[ba[ba[v]]], inf);
        s.erase(pos[ba[v]]); s.erase(pos[ba[ba[v]]]);
        ba[v] = ba[ba[ba[v]]];
    }
    for (int i = 1; i <= n; ++i) cout << q[i] << ' '; cout << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;
const int N = 200002;
const int INF = 1000000000;
struct node {
    int mn, mx, mnInd, mxInd;
};
int n,arr[N];
node odd[4*N], even[4*N];
vector <vector<pair<int,int> > > vec(N);

void buildOdd(int pos,int l,int r) {
    if(l == r) {
        if(l % 2)
            odd[pos] = node {arr[l],arr[l],l,l};
        else
            odd[pos] = node {INF,-INF,n,n+1};
        return;
    }
    int mid = (l+r)/2;
    buildOdd(pos*2,l,mid), buildOdd(pos*2+1,mid+1,r);
    if(odd[pos*2].mn < odd[pos*2+1].mn)
        odd[pos] = odd[pos*2];
    else
        odd[pos] = odd[pos*2+1];
}

void buildEven(int pos,int l,int r) {
    if(l == r) {
        if(l % 2 == 0)
            even[pos] = node {arr[l],arr[l],l,l};
        else
            even[pos] = node {INF,-INF,n,n+1};
        return;
    }
    int mid = (l+r)/2;
    buildEven(pos*2,l,mid), buildEven(pos*2+1,mid+1,r);
    if(even[pos*2].mn < even[pos*2+1].mn)
        even[pos] = even[pos*2];
    else
        even[pos] = even[pos*2+1];
}

node getOdd(int pos,int l,int r,int qLow,int qHigh) {
    if(l > qHigh || r < qLow || qLow>qHigh)
        return node{INF,-INF,n,n+1};
    if(l >= qLow && r <= qHigh)
        return odd[pos];
    int mid = (l+r)/2;
    node lf = getOdd(pos*2,l,mid,qLow,qHigh), ri = getOdd(pos*2+1,mid+1,r,qLow,qHigh);
    if(lf.mn < ri.mn)
        return lf;
    return ri;
}

node getEven(int pos,int l,int r,int qLow,int qHigh) {
    if(l > qHigh || r < qLow || qLow > qHigh)
        return node{INF,-INF,n,n+1};
    if(l >= qLow && r <= qHigh)
        return even[pos];
    int mid = (l+r)/2;
    node lf = getEven(pos*2,l,mid,qLow,qHigh), ri = getEven(pos*2+1,mid+1,r,qLow,qHigh);
    if(lf.mn < ri.mn)
        return lf;
    return ri;
}

void solve(int l,int r,int curr) {
    if(l > r)
        return;
    node o = getOdd(1,0,n-1,l,r);
    node e = getEven(1,0,n-1,l,r);
    if(o.mnInd <e.mnInd) {
        vec[curr].push_back(make_pair(o.mn,e.mn));
        solve(l,o.mnInd-1,curr+1);
        solve(o.mnInd+1,e.mnInd-1,curr+1);
        solve(e.mnInd+1,r,curr+1);
    } else {
        vec[curr].push_back(make_pair(e.mn,o.mn));
        solve(l,e.mnInd-1,curr+1);
        solve(e.mnInd+1,o.mnInd-1,curr+1);
        solve(o.mnInd+1,r,curr+1);
    }
}

int main()
{
    scanf("%d",&n);
    for(int i = 0;i<n;i++)
        scanf("%d",&arr[i]);
    buildOdd(1,0,n-1);
    buildEven(1,0,n-1);
    solve(0,n-1,0);
//    vector<int> temp;
//    sort(temp.begin(),temp.end());
    for(int i = 0;i<N;i++) {
        if(vec[i].size())
            sort(vec[i].begin(), vec[i].end());
    }
    for(int i = 0;i<N;i++)
        for(int j = 0;j<vec[i].size();j++)
            printf("%d %d ",vec[i][j].first,vec[i][j].second);

    return 0;
}

