const int MAXN = 500000;
const int INF = 1e9;
int a[MAXN], pos[MAXN], ans[MAXN], n;

struct Segment {
	int sum, mn[2];
} tr[MAXN];

inline int get_node(int l, int r) {
	return (l + r) | (l != r);
}

inline void update(int k, int l, int r) {
	int mid = (l + r) >> 1,
		lc = get_node(l, mid),
		rc = get_node(mid + 1, r);
	tr[k].sum = tr[lc].sum + tr[rc].sum;
	tr[k].mn[0] = min(tr[lc].mn[0], tr[rc].mn[tr[lc].sum & 1]);
	tr[k].mn[1] = min(tr[lc].mn[1], tr[rc].mn[(tr[lc].sum & 1) ^ 1]);
}

inline void build_tree(int l, int r) {
	int k = get_node(l, r);
	tr[k].sum = r - l + 1;
	if (l == r) {
		tr[k].mn[0] = INF;
		tr[k].mn[1] = a[l];
		return;
	}
	int mid = (l + r) >> 1;
	build_tree(l, mid);
	build_tree(mid + 1, r);
	update(k, l, r);
}

inline void del(int l, int r, int x) {
	int k = get_node(l, r);
	if (l == r) {
		tr[k].sum = 0;
		tr[k].mn[0] = tr[k].mn[1] = INF;
		return;
	}
	int mid = (l + r) >> 1;
	if (x > mid) {
		del(mid + 1, r, x);
	} else {
		del(l, mid, x);
	}
	update(k, l, r);
}

int flag = 0;

inline void query(int l, int r, int a, int b, int &s, int &x) {
	int k = get_node(l, r);
/*if (1) {
	cout << "query: " << l << " " << r << " " << a << " " << b << " " << s << " " << x << endl;
	cout << "info: " << tr[k].sum << " " << tr[k].mn[0] << " " << tr[k].mn[1] << endl;
}*/
	if (l == a && r == b) {
		x = min(x, tr[k].mn[s]);
		s ^= tr[k].sum & 1;
		return;
	}
	int mid = (l + r) >> 1;
	if (a > mid) {
		query(mid + 1, r, a, b, s, x);
		return;
	}
	if (b <= mid) {
		query(l, mid, a, b, s, x);
		return;
	}
	query(l, mid, a, mid, s, x);
	query(mid + 1, r, mid + 1, b, s, x);
}
