set<int> S;

struct Element {
	int x, y, l, r;
	Element() {};
	Element(int _x, int _y, int _l, int _r): x(_x), y(_y), l(_l), r(_r) {};
};

inline bool operator < (const Element &p, const Element &q) {
	return p.x != q.x ? p.x < q.x : p.y < q.y;
}

set<Element> seg;

set<int> chosen;

inline void get_segment(int l, int r, int &x, int &y) {
	if (l == r + 1) {
		return;
	}
	x = y = INF;
	set<int>::iterator it = S.upper_bound(r);
	--it;
	--it;
//cerr << l << " " << *it << endl;
	int s = 1;
	query(1, n, l, *it, s, x);
//cerr << x << endl;
//return;
	del(1, n, pos[x]);
	s = 1;
	query(1, n, pos[x], r, s, y);
	del(1, n, pos[y]);
	seg.insert(Element(x, y, l, r));
	chosen.insert(pos[x]);
	chosen.insert(pos[y]);
}

int main() {
	scanf("%d", &n);
	S.clear();
	chosen.clear();
	chosen.insert(0);
	chosen.insert(n + 1);
	for (int i = 1; i <= n; ++i) {
		scanf("%d", &a[i]);
		pos[a[i]] = i;
		S.insert(i);
	}
	S.insert(n + 1);

	build_tree(1, n);
	int x, y;
	seg.clear();
	get_segment(1, n, x, y);
	//return 0;

	int cnt = 0;
	for (int i = 0; i < n / 2; ++i) {
		Element now = *(seg.begin());
		seg.erase(seg.begin());
		ans[++cnt] = now.x;
		ans[++cnt] = now.y;
		int x = pos[now.x], y = pos[now.y], tx, ty;
		set<int>::iterator it = chosen.lower_bound(x);
		--it;
		get_segment((*it) + 1, x - 1, tx, ty);
		get_segment(x + 1, y - 1, tx, ty);
		it = chosen.lower_bound(y);
		++it;
		get_segment(y + 1, (*it) - 1, tx, ty);
	}

	for (int i = 1; i < n; ++i) {
		printf("%d ", ans[i]);
	}
	cout << ans[n] << endl;
}

