vll dfs(lli from,lli to){
	lli r,l;
	lli r_index,l_index;
	if(from % 2 == 0){
		l = sg_even.query(from,to);
		l_index = maping[l];
		r = sg_odd.query(l_index,to);
		r_index = maping[r];
	}else{
		l = sg_odd.query(from,to);
		l_index = maping[l];
		r = sg_even.query(l_index,to);
		r_index = maping[r];
	}
	return vll({l,r,from,to,l_index,r_index});
}

