	for (i = 0; i < k; i++) {
		min[0][i] = p[i*400];
		min[1][i] = p[i*400+1];
		argmin[0][i] = i * 400;
		argmin[1][i] = i * 400 + 1;
		for (j = 1; i * 400 + j < N && j < 400; j++) {
			if (p[i*400+j] < min[j%2][i]) {
				min[j%2][i] = p[i*400+j];
				argmin[j%2][i] = i * 400 + j;
			}
		}
	}

	int l, r, n, tmp, parity[500] = {}, flag[500] = {}, stop[200001] = {}, ans[200001];
	for (n = 0; n < N; n += 2) {
		ans[n] = N + 1;
		ans[n+1] = N + 1;
		for (i = 0; i < k; i++) {
			if (min[0][i] < ans[n]) {
				ans[n] = min[0][i];
				l = argmin[0][i];
			}
		}
		for (j = l + 1; j < N && j % 400 > 1 && stop[j-1] + stop[j] == 0; j += 2) {
			if (p[j] < ans[n+1]) {
				ans[n+1] = p[j];
				r = j;
			}
		}
		if (j % 400 <= 1) {
			for (i = j / 400; i < k && flag[i] == 0; i++) {
				if (min[1][i] < ans[n+1]) {
					ans[n+1] = min[1][i];
					r = argmin[1][i];
				}
			}
			for (j = i * 400 + j % 2; j < N && stop[j-1] + stop[j] == 0; j += 2) {
				if (p[j] < ans[n+1]) {
					ans[n+1] = p[j];
					r = j;
				}
			}
		}

		stop[l] = 1;
		stop[r] = 1;
		i = l / 400;
		flag[i] = 1;
