typedef struct indexNode{
  int val;
  int index;
} node;

node calcMin(node a,node b){
  return a.val<b.val?a:b;
}

const node inf={400000,0};

typedef struct RMQ{
  node *a;
  int size;
} seg;

seg* newRMQ(const int n){
  int k=1;
  while(k<n) k*=2;
  seg *res=(seg *)calloc(1,sizeof(seg));
  res->a=(node *)calloc(2*k,sizeof(node));
  res->size=k;
  for(int i=1;i<2*k;i++) res->a[i]=inf;
  return res;
}

void update(seg *s,int index,node v){
  int x=index+s->size;
  s->a[x]=v;
  x/=2;
  while(x>=1){
    s->a[x]=calcMin(s->a[2*x],s->a[2*x+1]);
    x>>=1;
  }
}

node query(seg *s,int l,int r){
  node res=inf;
  for(l+=s->size,r+=s->size;l<r;l>>=1,r>>=1){
    if(l&1) res=calcMin(res,s->a[l++]);
    if(r&1) res=calcMin(res,s->a[--r]);
  }
  return res;
}

void calc(int l,int r,seg *even,seg *odd,int *res,int *tmp){
  if(r-l<2) return;
  node p=query(even,l,r);
  update(even,p.index,inf);
  node q=query(odd,p.index,r);
  update(odd,q.index,inf);
  calc(l,p.index,even,odd,res,tmp);
  int alen=0;
  int i;
  for(i=l;i<p.index;i++){
    tmp[alen++]=res[i-l];
  }
  calc(p.index+1,q.index,odd,even,res,tmp+alen);
  int blen=0;
  for(i=p.index+1;i<q.index;i++){
    tmp[alen+blen++]=res[i-p.index-1];
  }
  calc(q.index+1,r,even,odd,res,tmp+alen+blen);
  int clen=0;
  for(i=q.index+1;i<r;i++){
    tmp[alen+blen+clen++]=res[i-q.index-1];
  }
  blen+=alen;
  clen+=blen;
  int len=0;
  res[len++]=p.val;
  res[len++]=q.val;
  i=0;
  int j=alen;
  int k=blen;
  while(i<alen || j<blen || k<clen){
    int *min=NULL;
    if(i<alen) min=&i;
    if(j<blen && (min==NULL || tmp[*min]>tmp[j])) min=&j;
    if(k<clen && (min==NULL || tmp[*min]>tmp[k])) min=&k;
    res[len++]=tmp[(*min)++];
    res[len++]=tmp[(*min)++];
  }
}

void run(void){
  int n;
  scanf("%d",&n);
  int *p=(int *)calloc(n,sizeof(int));
  int i;
  for(i=0;i<n;i++) scanf("%d",p+i);
  seg *even=newRMQ(n);
  seg *odd=newRMQ(n);
  for(i=0;i<n;i+=2) update(even,i,(node){p[i],i});
  for(i=1;i<n;i+=2) update(odd,i,(node){p[i],i});
  int *tmp=(int *)calloc(n,sizeof(int));
  calc(0,n,even,odd,p,tmp);
  for(i=0;i<n;i++) printf("%d ",p[i]);
  printf("\n");
}

int main(void){
  run();
  return 0;
}

