				if (stop[j] == 1) continue;
				if (p[j] < min[tmp][i]) {
					min[tmp][i] = p[j];
					argmin[tmp][i] = j;
				}
				tmp ^= 1;
			}
		}
	}

	for (i = 0; i < N - 1; i++) printf("%d ", ans[i]);
	printf("%d\n", ans[N-1]);
	fflush(stdout);
	return 0;
}

