public class Main {
    private static int N;
    private static ArrayList<Integer> p;

    public static void input(){
        Scanner scan = new Scanner(System.in);
        N = scan.nextInt();

        for(int i=0;i<N;i++) {
            p.add(scan.nextInt());
        }
    }

    public static ArrayList<Integer> search(ArrayList<Integer> array){
        int min = 10000000;
        int min_index = 0;
        int second_min = 10000000;

        // 最小値の探索
        for(int i : array){
            if(array.get(i) < min){
                min = array.get(i);
                min_index = i;
            }
        }

        // 最小値より後ろの値の個数が偶数なら最小値の次に小さい値を探索
        if( (N - min_index) % 2 == 1) {
            array.remove(min_index);
            search(array);
        }else{
            // 最小値以降の最小値を探索
            for(int i=min_index+1;i<N;i++){
                second_min = Math.min(second_min , array.get(i));
            }
        }

        Queue<Integer> queue = new ArrayDeque<Integer>();

        queue.add(min);
        queue.add(second_min);
        p.remove(min);
        p.remove(second_min);

        return p;
    }

    public static void main(String args[]){
        //入力
        input();

        ArrayList<Integer> temp = new ArrayList<>();

        for(int i=0;i<N/2;i++){
            temp = search(temp);
        }
    }
}

import java.util.*;

class Main {
    static int[] idx;
    static int[] A;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        A = new int[n];
        idx = new int[n+1];
        for(int i=0;i<n;i++){
            A[i] = sc.nextInt();
            idx[A[i]] = i;
        }
        ST even = new ST(n/2);
        ST odd = new ST(n/2);
        ST idxRec = new ST(n);
        for(int i=0;i<n;i+=2) even.update(i/2,A[i]);
        for(int i=1;i<n;i+=2) odd.update(i/2,A[i]);
        for(int i=0;i<n;i++) idxRec.update(i,n);
        ArrayList<Integer> res = new ArrayList<>();

        boolean[] used = new boolean[n+1];

        for(int i=1;i<=n;i++){
            if(idx[i]%2==1) continue;
            int curIdx = idx[i];
            int next = odd.find((curIdx+1)/2,n/2);
            res.add(i);
            res.add(next);
            used[i]=true;
            used[next]=true;
            idxRec.update(curIdx,curIdx);
            idxRec.update(idx[next],idx[next]);
            break;
        }
        for(int i=1;i<=n;i++){
            if(used[i]) continue;
            int curIdx = idx[i];
            int farthest = idxRec.find(curIdx,n-1);
            if(farthest-curIdx<=1) continue;
            int[] bound = computeBound(curIdx,farthest);
            int next = curIdx%2==0?odd.find(bound[0],bound[1]):even.find(bound[0],bound[1]);
            res.add(i);
            res.add(next);
            used[i]=true;
            used[next]=true;
            idxRec.update(curIdx,curIdx);
            idxRec.update(idx[next],idx[next]);
        }
        for(int i=0;i<res.size();i++){
            System.out.print(Integer.toString(res.get(i))+" ");
        }
    }
    static int[] computeBound(int cur, int farthest){
        if(cur%2==1){
            int end = farthest%2==1?farthest-1:farthest-2;
            return new int[]{(cur+1)/2,end/2};
        } else{
            int end = farthest%2==0?farthest-1:farthest-2;
            return new int[]{(cur+1)/2,end/2};
        }
    }
    static class ST{
        int n=1;
        int[] dat;

        public ST(int n_){
            while(n<n_) n*=2;
            dat = new int[2*n-1];
            for(int i=0;i<2*n-1;i++) dat[i] = Integer.MAX_VALUE/2;
        }
        public void update(int idx, int val){
            idx += n-1;
            dat[idx] = val;
            while(idx>0){
                idx = (idx-1)/2;
                dat[idx] = Math.min(dat[idx*2+1],dat[idx*2+2]);
            }
        }

        public int find(int a, int b){
            return query(a,b+1,0,0,n);
        }
        private int query(int a, int b, int k, int left, int right){
            if(b<=left||right<=a) return Integer.MAX_VALUE;
            if(a<=left&&right<=b) return dat[k];
            int v1 = query(a,b,2*k+1,left,(left+right)/2);
            int v2 = query(a,b,2*k+2,(left+right)/2,right);
            return Math.min(v1,v2);
        }
    }
}

