        p = In.ni(n);
        q = new int[n];
        e = new int[n / 2];
        o = new int[n / 2];
        for (int i = 0; i < n; i += 2) {
            e[i / 2] = p[i];
            o[i / 2] = p[i + 1];
        }
        te = new RMQ(e);
        to = new RMQ(o);
        part(0, n);
        int[] pr = new int[n];
        int[] f = new int[n / 2];
        int[] s = new int[n / 2];
        for (int i = 0; i < n; i += 2) {
            f[i / 2] = q[i];
            s[i / 2] = q[i + 1];
            pr[q[i]] = q[i + 1];
            pr[q[i + 1]] = q[i];
        }
        IntStack st = new IntStack(n / 2);
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        int[] in = new int[n];
        for (int i = 0; i < n; i++) {
            if (i < pr[i]) {
                if (st.size() > 0) {
                    g[st.peek()].add(i);
                    in[i]++;
                }
                st.add(i);
            } else {
                st.poll();
            }
        }
        PriorityQueue<Integer> pq = new PriorityQueue<>((i, j) -> p[i] - p[j]);
        for (int i = 0; i < n; i++) {
            if (i < pr[i] && in[i] == 0) {
                pq.add(i);
            }
        }
        int[] ans = new int[n];
        int idx = 0;
        while (pq.size() > 0) {
            int u = pq.poll();
            ans[idx++] = p[u];
            ans[idx++] = p[pr[u]];
            g[u].iterator().forEachRemaining((int v) -> {
                if (--in[v] == 0) {
                    pq.add(v);
                }
            });
        }
        out.append(IntArrays.join(ans, " "));
    }

    public static void part(int l, int r) {
        if (r - l == 0) {
            return;
        }
        if (r - l == 2) {
            q[idx++] = l;
            q[idx++] = l + 1;
            return;
        }
        int t1, t2;
        int m1, m2;
        if ((l & 1) == 0) {
            t1 = te.query(l / 2, r / 2);
            int k1 = te.indexOfMin(l / 2, r / 2, t1);
            t2 = to.query(k1, r / 2);
            int k2 = to.indexOfMin(k1, r / 2, t2);
            m1 = k1 * 2;
            m2 = k2 * 2 + 1;
        } else {
            t1 = to.query(l / 2, r / 2);
            int k1 = to.indexOfMin(l / 2, r / 2, t1);
            t2 = te.query(k1 + 1, r / 2 + 1);
            int k2 = te.indexOfMin(k1 + 1, r / 2 + 1, t2);
            m1 = k1 * 2 + 1;
            m2 = k2 * 2;
        }
        q[idx++] = m1;
        q[idx++] = m2;
        part(l, m1);
        part(m1 + 1, m2);
        part(m2 + 1, r);
    }
}

class RMQ {
    private final int[] t;
    private final int n;
    private final int e = Const.IINF;

    public RMQ(final int[] a) {
        int nn = 1;
        while (nn < a.length) nn <<= 1;
        this.n = nn;
        this.t = new int[n << 1];
        System.arraycopy(a, 0, t, n, a.length);
        Arrays.fill(t, n + a.length, n << 1, e);
        for (int i = n - 1; i > 0; i--) t[i] = min(t[i << 1], t[(i << 1) | 1]);
    }

    public int query(int l, int r) {
        int min = e;
        l += n; r += n;
        while (l < r) {
            if ((l & 1) != 0) min = min(min, t[l++]);
            if ((r & 1) != 0) min = min(t[--r], min);
            l >>= 1; r >>= 1;
        }
        return min;
    }

    public int indexOfMin(int l, int r, int min) {
        int k = 1;
        while (k < n) {
            k <<= 1;
            if (t[k] != min) k |= 1;
        }
        return k - n;
    }
}


