/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author HossamDoma
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, PrintWriter out) {


            int n = in.nextInt();
            int[] a = new int[n];

            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
            }

            PriorityQueue<Pair> pq = new PriorityQueue<>();

            for (int i = 0; i + 1 < n; ++i) {
                pq.add(new Pair(i, i + 1, a[i] + a[i + 1]));
            }


            int vis[] = new int[n];
            Arrays.fill(vis, -1);

            int ans[] = new int[n];
            int idx = n - 1;

            while (!pq.isEmpty() && idx > 0) {

                Pair p = pq.poll();

                if (vis[p.i] == p.j)
                    continue;

                ans[idx--] = a[p.j];
                ans[idx--] = a[p.i];

                if (p.i > 0) {
                    vis[p.i - 1] = p.i;
                }

                if (p.j < n - 1) {
                    vis[p.j] = p.j + 1;
                }

                if (p.i > 0 && p.j < n - 1) {
                    pq.add(new Pair(p.i - 1, p.j + 1, a[p.i - 1] + a[p.j + 1]));
                }

            }

            for (int i = 0; i < n; ++i) {
                if (ans[i] == 0)
                    throw new RuntimeException();
                out.print(ans[i] + (i == n - 1 ? "\n" : " "));
            }

        }

        class Pair implements Comparable<Pair> {
            int i;
            int j;
            int sum;

            public Pair(int i, int j, int sum) {
                this.i = i;
                this.j = j;
                this.sum = sum;
            }


            public int compareTo(Pair o) {
                return o.sum - sum;
            }


            public boolean equals(Object obj) {
                if (!(obj instanceof Pair))
                    return false;

                Pair p = (Pair) obj;

                return p.i == i && p.j == j && sum == p.sum;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

class Main {
    static int[] idx;
    static int[] A;
    static ST even;
    static ST odd;
    static ST all;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        A = new int[n];
        idx = new int[n+1];
        for(int i=0;i<n;i++){
            A[i] = sc.nextInt();
            idx[A[i]] = i;
        }
        even = new ST(n/2);
        odd = new ST(n/2);
        all = new ST(n);

        for(int i=0;i<n;i+=2) even.update(i/2,A[i]);
        for(int i=1;i<n;i+=2) odd.update(i/2,A[i]);
        for(int i=0;i<n;i++) all.update(i,A[i]);
        myComparator mc = new myComparator();
        PriorityQueue<int[]> pq = new PriorityQueue<>(10,mc);
        pq.add(new int[]{0,n});
        ArrayList<Integer> res = new ArrayList<>();
        while(res.size()<n){
            int[] cur = pq.poll();
            int left = cur[0];
            int right = cur[1];
            int now,next;
            if(left%2==0){
                now = even.find(left/2,right/2);
                next = odd.find((idx[now]+1)/2,(right+1)/2);
            }else{
                now = odd.find(left/2,right/2);
                next = even.find((idx[now]+1)/2,(right+1)/2);
            }
            res.add(now);
            res.add(next);
            if(left<idx[now]) pq.add(new int[]{left,idx[now]});
            if(idx[now]<idx[next]-1) pq.add(new int[]{idx[now]+1,idx[next]});
            if(idx[next]<right-1) pq.add(new int[]{idx[next]+1,right});
        }
        for(int i=0;i<res.size();i++){
            System.out.print(Integer.toString(res.get(i))+" ");
        }
    }

    static class ST{
        int n=1;
        int[] dat;

        public ST(int n_){
            while(n<n_) n*=2;
            dat = new int[2*n-1];
            for(int i=0;i<2*n-1;i++) dat[i] = Integer.MAX_VALUE/2;
        }
        public void update(int idx, int val){
            idx += n-1;
            dat[idx] = val;
            while(idx>0){
                idx = (idx-1)/2;
                dat[idx] = Math.min(dat[idx*2+1],dat[idx*2+2]);
            }
        }
        public int find(int a, int b){
            return query(a,b,0,0,n);
        }
        private int query(int a, int b, int k, int left, int right){
            if(b<=left||right<=a) return Integer.MAX_VALUE;
            if(a<=left&&right<=b) return dat[k];
            int v1 = query(a,b,2*k+1,left,(left+right)/2);
            int v2 = query(a,b,2*k+2,(left+right)/2,right);
            return Math.min(v1,v2);
        }
    }
    static class myComparator implements Comparator<int[]>{
        public int compare(int[] o1, int[] o2){
            int[][] dic = new int[][]{o1,o2};
            int[] res = new int[2];
            for(int i=0;i<2;i++){
                int[] cur = dic[i];
                int left = cur[0];
                int right = cur[1];
                int p = left%2==0?even.find(left/2,right/2):odd.find(left/2,right/2);
                res[i]=p;
            }
            return res[0]-res[1];
        }
    }
}

