    for(int i = 0; i < n; i++){
      p[i] = sc.nextInt();
    }

    int[] pos = new int[MAX + 1];
    for(int i = 0; i < n; i++){
      pos[p[i]] = i;
    }

    ArrayList< Integer > a = new ArrayList< >(n);
    TreeSet< Integer > r = new TreeSet< >();
    for(int i = 0; i < n; i++){
      a.add(p[i]);
      r.add(p[i]);
    }

    Map< Integer, Integer > map = new HashMap< >();
    for(int i = 0; i < n; i++){
      map.put(p[i], i);
    }

    int[] ans = new int[n];
    int sp = 0;
    while(!r.isEmpty()){
      int x = r.first();
      int y = r.higher(x);
