        System.out.println("x = " + x + ", y = " + y);
      }
      while(true){
        if(pos[x] > pos[y]){
          if(r.higher(y) == null){
            x = r.higher(x);
            y = r.first();
          }
          else{
            y = r.higher(y);
          }
          if(DEBUG){
            System.out.println("x = " + x + ", y = " + y);
          }
          continue;
        }
        if((pos[y] - pos[x] == map.get(y) - map.get(x)) &&
          ((pos[y] - pos[x] + 1) % 2 == 0) &&
          (a.indexOf(x) % 2 == 0 && (n - a.indexOf(y) + 1) % 2 == 0)){
          ans[sp++] = x;
          ans[sp++] = y;
          r.remove(x);
          r.remove(y);
          a.remove(new Integer(x));
          a.remove(new Integer(y));
