/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 29);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            EYoungMaids solver = new EYoungMaids();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class EYoungMaids {
        RMQ[] rmqs = new RMQ[2];
        List<Node> nodes = new ArrayList<>();

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] p = new int[n];
            in.populate(p);
            int[] even = new int[n];
            int[] odd = new int[n];
            int inf = (int) 1e9;
            Arrays.fill(even, inf);
            Arrays.fill(odd, inf);
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0) {
                    even[i] = p[i];
                } else {
                    odd[i] = p[i];
                }
            }

            rmqs[0] = new RMQ(n);
            rmqs[1] = new RMQ(rmqs[0]);
            rmqs[0].reset(0, n - 1, (a, b) -> Integer.compare(even[a], even[b]));
            rmqs[1].reset(0, n - 1, (a, b) -> Integer.compare(odd[a], odd[b]));
            build(0, n - 1, 0, null);

            PriorityQueue<Node> pq = new PriorityQueue<>(n, (a, b) -> -Integer.compare(p[a.first], p[b.first]));
            for (Node node : nodes) {
                if (node.deg == 0) {
                    pq.add(node);
                }
            }

            List<Node> reverse = new ArrayList<>(n);
            while (!pq.isEmpty()) {
                Node top = pq.remove();
                reverse.add(top);
                if (top.p != null) {
                    top.p.deg--;
                    if (top.p.deg == 0) {
                        pq.add(top.p);
                    }
                }
            }

            SequenceUtils.reverse(reverse);
            for (Node node : reverse) {
                out.append(p[node.first]).append(' ').append(p[node.second]).append(' ');
            }
        }

        public void build(int l, int r, int xor, Node top) {
            if (l >= r) {
                return;
            }
            Node node = new Node();
            node.p = top;
            if (top != null) {
                top.deg++;
            }
            node.first = rmqs[0 ^ xor].query(l, r);
            node.second = rmqs[1 ^ xor].query(node.first + 1, r);
            build(l, node.first - 1, xor, node);
            build(node.first + 1, node.second - 1, xor ^ 1, node);
            build(node.second + 1, r, xor, node);

            nodes.add(node);
        }

    }

    static class Node {
        Node p;
        int deg;
        int first;
        int second;

    }

    static interface IntegerIterator {
        boolean hasNext();

        int next();

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

