public class Main {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    class Pair {
        final int idx;
        final int val;

        public Pair(int idx, int val) {
            this.idx = idx;
            this.val = val;
        }

        @Override
        public String toString() {
            final StringBuilder sb = new StringBuilder("Pair{");
            sb.append("idx=").append(idx);
            sb.append(", val=").append(val);
            sb.append('}');
            return sb.toString();
        }
    }

    class SegmentTree {
        int N;
        int[] dat, idx;

        public SegmentTree(int n) {
            N = Integer.highestOneBit(n) << 1;
            int size = (N << 1) - 1;
            // System.out.println(N + " " + size);
            dat = new int[size];
            idx = new int[size];
            Arrays.fill(dat, Integer.MAX_VALUE);
            for (int i = 0; i < (size + 1) / 2; i++) {
                idx[i + size / 2] = i;
            }
        }

        /**
         * Update the segment tree.
         *
         * @param k the index of tree to update
         * @param a the value of tree to update
         */
        void update(int k, int a) {
            k += N - 1;
            dat[k] = a;
            while (k > 0) {
                k = (k - 1) / 2;
                if (dat[k * 2 + 1] < dat[k * 2 + 2]) {
                    dat[k] = dat[k * 2 + 1];
                    idx[k] = idx[k * 2 + 1];
                } else {
                    dat[k] = dat[k * 2 + 2];
                    idx[k] = idx[k * 2 + 2];
                }
            }
        }

        private Pair query(int a, int b, int k, int l, int r) {
            // System.out.println("query : " + a + " " + b + " " + k + " " + l + " " + r);
            if (r < a || b < l) return new Pair(-1, Integer.MAX_VALUE);

            if (a <= l && r <= b) return new Pair(idx[k], dat[k]);
            else {
                Pair vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
                Pair vr = query(a, b, k * 2 + 2, (l + r) / 2 + 1, r);
                return vl.val < vr.val ? vl : vr;
            }
        }

        Pair getMinQuery(int a, int b) {
            return query(a, b, 0, 0, N - 1);
        }

        void display() {
            System.out.println("-------------Segment Tree-------------");
            for (int i = 1; i < dat.length; i *= 2) {
                for (int j = i; j < 2 * i; j++) {
                    System.out.print(dat[j - 1] + " ");
                }
                System.out.println();
            }
            System.out.println("----------------End------------------");
            System.out.println();
        }
    }

    Queue<Integer> rec(int l, int r, SegmentTree[] segmentTrees) {
        // System.out.println(l + " " + r);
        Queue<Integer> res = new LinkedList<>();
        if (l >= r) {
            return res;
        }

        Pair min1 = segmentTrees[l%2].getMinQuery(l, r);
        final int nl = min1.idx;
        Pair min2 = segmentTrees[(l+1)%2].getMinQuery(nl + 1, r);
        final int nr = min2.idx;
        // System.out.println(nl + " " + nr + " " + min1 + " " + min2);
        Queue<Integer>[] queues = new Queue[3];

        // left
        queues[0] = rec(l, nl - 1, segmentTrees);
        // center
        queues[1] = rec(nl + 1, nr - 1, segmentTrees);
        // right
        queues[2] = rec(nr + 1, r, segmentTrees);

        res.add(min1.val);
        res.add(min2.val);

        while (!queues[0].isEmpty() || !queues[1].isEmpty() || !queues[2].isEmpty()) {
            int nextIdx = -1;
            for (int i = 0; i < 3; i++) {
                // System.out.println(i + " " + queues[i]);
                if (queues[i].isEmpty()) continue;
                if (nextIdx == -1 || queues[i].peek() < queues[nextIdx].peek()) {
                    nextIdx = i;
                }
            }
            res.add(queues[nextIdx].poll());
            res.add(queues[nextIdx].poll());
        }
        for (Queue<Integer> queue : queues) {
            res.addAll(queue);
        }
        return res;
    }

    void run() {
        int N = in.nextInt();
        int[] a = in.nextIntArray(N);

        // 0: even, 1: odd
        SegmentTree[] segmentTrees = {new SegmentTree(N), new SegmentTree(N)};
        for (int i = 0; i < N; i++) {
            segmentTrees[i%2].update(i, a[i]);
        }

        Queue<Integer> res = rec(0, N - 1, segmentTrees);
        for (int v : res) {
            out.print(v + " ");
        }
        out.println();
        out.close();
    }

    public static void main(String[] args) {
        new Main().run();
    }

    class FastScanner {
