  class Node {
    int val = Integer.MAX_VALUE;
    int index;
  }

  class Pack {
    Node first;
    Node second;
  }

  class Tree {
    Pack me = null;
    Tree parent = null;
    Tree left = null;
    Tree mid = null;
    Tree right = null;

    Tree get(int index) {
      switch (index) {
        case 0:
          return left;
        case 1:
          return mid;
        case 2:
          return right;
        default:
          return null;
      }
    }

    void clear(int index) {
      switch (index) {
        case 0:
          left = null;
          return;
        case 1:
          mid = null;
          return;
        case 2:
          right = null;
          return;
      }
    }
  }

  int n;
  SegmentTree<Node> gusu;
  SegmentTree<Node> kisu;

  Tree search(int l, int r) {
    if (l == r) {
      return null;
    }
    Tree ret = new Tree();
    Node first;
    Node second;
    if (l % 2 == 0) {
      first = gusu.reduce(l, r);
      second = kisu.reduce(first.index, r);
    } else {
      first = kisu.reduce(l, r);
      second = gusu.reduce(first.index, r);
    }
    Pack me = new Pack();
    me.first = first;
    me.second = second;
    ret.me = me;
    ret.left = search(l, first.index);
    if (ret.left != null) {
      ret.left.parent = ret;
    }
    ret.mid = search(first.index + 1, second.index);
    if (ret.mid != null) {
      ret.mid.parent = ret;
    }
    ret.right = search(second.index + 1, r);
    if (ret.right != null) {
      ret.right.parent = ret;
    }
    return ret;
  }

  LinkedList<Tree> leaf = new LinkedList<>();

  void get_leaf(Tree node) {
    if (node == null) {
      return;
    }
    if (node.mid == null) {
      leaf.add(node);
    }
    get_leaf(node.left);
    get_leaf(node.mid);
    get_leaf(node.right);
  }

  void run() {
    n = ni();
    int[] p = new int[n];
    for (int i = 0; i < n; ++i) {
      p[i] = ni();
    }
    gusu = new SegmentTree<>(n, (a, b) -> {
      if (a == null) {
        return b;
      }
      if (b == null) {
        return a;
      }
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, () -> null);
    kisu = new SegmentTree<>(n, (a, b) -> {
      if (a == null) {
        return b;
      }
      if (b == null) {
        return a;
      }
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, () -> null);
    for (int i = 0; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      gusu.set(i, node);
    }
    for (int i = 1; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      kisu.set(i, node);
    }
    Tree root = search(0, n);
    PriorityQueue<Tree> queue = new PriorityQueue<>((l, r) -> r.me.first.val - l.me.first.val);
    get_leaf(root);
    queue.addAll(leaf);
    LinkedList<Pack> ans = new LinkedList<>();
    while (queue.size() > 0) {
      Tree node = queue.poll();
//      debug(node.me.first.val, node.me.second.val);
      ans.addFirst(node.me);
      Tree parent = node.parent;
      if (parent == null) {
        continue;
      }
      boolean ok = parent.get(1) == node;
      for (int i = 0; i < 3; ++i) {
        if (node.get(i) == null) {
          continue;
        }
        ok = false;
      }
      if (ok) {
//        debug("\t\tparent : ", parent.me.first.val, parent.me.second.val);
        queue.add(parent);
      }
      for (int i = 0; i < 3; ++i) {
        if (parent.get(i) == node) {
          parent.clear(i);
        }
      }
    }
    ArrayList<Pack> bns = new ArrayList<>(ans);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n / 2; ++i) {
      if (i > 0) {
        sb.append(" ");
      }
      Pack pack = bns.get(i);
      sb.append(pack.first.val);
      sb.append(" ");
      sb.append(pack.second.val);
    }
    System.out.println(sb.toString());
  }

