                s=m1.query(l/2,r/2);
            else
                s=m0.query(l/2+1,r/2+1);
            ans[ansp]=v>>>32;
            ans[ansp+1]=s>>>32;
            ansp+=2;
            int fi=(int)v;
            int si=(int)s;
            if(l%2==0){
                fi=fi*2;
                si=si*2+1;
            }else{
                fi=fi*2+1;
