    void run() {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        ps = new int[n];
        for (int i = 0; i < n; i++) {
            ps[i] = sc.nextInt();
        }
        solve();
    }

    void solve() {
        List<Integer> ans = dfs(0, ps.length);
        for (int i = 0; i < ans.size(); i++) {
            System.out.print(ans.get(i));
            if (i < ans.size() - 1) {
                System.out.print(" ");
            } else {
                System.out.println();
            }
        }
    }

    List<Integer> dfs(int l, int r) {
       // System.out.println(l + " " + r);
        if (r == l) {
            return new ArrayList<>();
        }
        if (r - l == 2) {
            List<Integer> ret = new ArrayList<>();
            ret.add(ps[l]);
            ret.add(ps[l + 1]);
            return ret;
        }
        int minOdd = Integer.MAX_VALUE;
        int minEven = Integer.MAX_VALUE;
        int minOddIndex = -1;
        int minEvenIndex = -1;
        for (int i = l; i < r; i++) {
            if (((l + i) & 1) == 0 && ps[i] < minEven) {
                minEven = ps[i];
                minEvenIndex = i;
            }
        }
        for (int i = minEvenIndex; i < r; i++) {
            if (((l + i) & 1) == 1 && ps[i] < minOdd) {
                minOdd = ps[i];
                minOddIndex = i;
            }
        }
        List<Integer> minPair = new ArrayList<>();
        minPair.add(minEven);
        minPair.add(minOdd);
        List<Integer> ret = merge(dfs(l, minEvenIndex),
                merge(dfs(minEvenIndex + 1, minOddIndex),
                        dfs(minOddIndex + 1, r)));
        /*
        for (int i = 0; i < ret.size(); i++) {
            System.out.print(ret.get(i));
            if (i < ret.size() - 1) {
                System.out.print(" ");
            } else {
                System.out.println();
            }
        }
        */
        minPair.addAll(ret);
        return minPair;
    }

    List<Integer> merge(List<Integer> a, List<Integer> b) {
        //System.out.println(a.toString());
        //System.out.println(b.toString());
        List<Integer> ret = new ArrayList<>();
        int i = 0;
        int j = 0;
        while (i < a.size() || j < b.size()) {
            if (i == a.size()) {
                ret.add(b.get(j++));
                ret.add(b.get(j++));
            } else if (j == b.size()) {
                ret.add(a.get(i++));
                ret.add(a.get(i++));
            } else {
                if (a.get(i) < b.get(j)) {
                    ret.add(a.get(i++));
                    ret.add(a.get(i++));
                } else {
                    ret.add(b.get(j++));
                    ret.add(b.get(j++));
                }
            }
        }
        return ret;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    static int N;
    static int[] p;
    static SegTree evenSegTree;
    static SegTree oddSegTree;

    static class NumAndPos {
	int num, pos;

	public NumAndPos(int num, int pos) {
	    super();
	    this.num = num;
	    this.pos = pos;
	}

	public NumAndPos() {
	}

    }

    static class SegTree {
	NumAndPos[] dat;
	int N;

	public SegTree(int n) {
	    N = 1;
	    while (N < n) {
		N *= 2;
	    }

	    this.dat = new NumAndPos[2 * N];
	    for (int i = 0; i < 2 * N; i++) {
		dat[i] = new NumAndPos(-1, -1);
	    }

	}

	// void init(int n) {
	// N = 1;
	// while (N < n) {
	// N *= 2;
	// }
	// for (int i = 0; i < 2 * N - 1; i++) {
	// dat[i] = Integer.MAX_VALUE - 10;
	// }
	// }

	void update(int k, NumAndPos a) {
	    k += N - 1;
	    dat[k] = a;
	    while (0 < k) {
		k = (k - 1) / 2;
		// dat[k] = Math.min(dat[k * 2 + 1], dat[k * 2 + 2]);
		if (dat[k * 2 + 1].num < dat[k * 2 + 2].num) {
		    dat[k] = dat[k * 2 + 1];
		} else {
		    dat[k] = dat[k * 2 + 2];
		}
	    }
	}

	NumAndPos query(int a, int b, int k, int l, int r) {
	    if (r <= a || b <= l) {
		return new NumAndPos(Integer.MAX_VALUE - 10, 0);
	    }
	    if (a <= l && r <= b) {
		return dat[k];
	    } else {
		NumAndPos vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		NumAndPos vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		// return Math.min(vl, vr);
		if (vl.num < vr.num) {
		    return vl;
		} else {
		    return vr;
		}
	    }
	}
    }

    public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	N = sc.nextInt();
	p = new int[N];
	for (int i = 0; i < N; i++) {
	    p[i] = sc.nextInt();
	}

	evenSegTree = new SegTree(N);
	oddSegTree = new SegTree(N);

	for (int i = 0; i < N; i++) {
	    if (i % 2 == 0) {
		evenSegTree.update(i, new NumAndPos(p[i], i));
		oddSegTree.update(i, new NumAndPos(Integer.MAX_VALUE, i));
	    } else {
		oddSegTree.update(i, new NumAndPos(p[i], i));
		evenSegTree.update(i, new NumAndPos(Integer.MAX_VALUE, i));
	    }
	}

	Queue<Range> pq = new PriorityQueue<Range>(N, new MyComparator());
	pq.add(new Range(0, N));
	ArrayList<Integer> ans = new ArrayList<Integer>();
	while (ans.size() != N) {
	    Range tmpRange = pq.poll();
	    if (tmpRange.start % 2 == 0) {
		NumAndPos nap1 = evenSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap1.num);
		NumAndPos nap2 = oddSegTree.query(nap1.pos, tmpRange.end, 0, 0, N);
		ans.add(nap2.num);
		pq.add(new Range(tmpRange.start, nap1.pos));
		pq.add(new Range(nap1.pos + 1, nap2.pos));
		pq.add(new Range(nap2.pos + 1, tmpRange.end));
	    } else {
		NumAndPos nap1 = oddSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap1.num);
		NumAndPos nap2 = evenSegTree.query(nap1.pos, tmpRange.end, 0, 0, N);
		ans.add(nap2.num);
		pq.add(new Range(tmpRange.start, nap1.pos));
		pq.add(new Range(nap1.pos + 1, nap2.pos));
		pq.add(new Range(nap2.pos + 1, tmpRange.end));
	    }
	}
	ans.stream().forEach(ele -> System.out.print(ele + " "));
    }

    static class MyComparator implements Comparator<Range> {
	@Override
	public int compare(Range r1, Range r2) {
	    if (r1.start % 2 == 0) {
		return evenSegTree.query(r1.start, r1.end, 0, 0, N).num
			- evenSegTree.query(r2.start, r2.end, 0, 0, N).num;
	    } else {
		return oddSegTree.query(r1.start, r1.end, 0, 0, N).num
			- oddSegTree.query(r2.start, r2.end, 0, 0, N).num;
	    }
	}
    }

    static class Range {
	int start, end;

	public Range(int start, int end) {
	    super();
	    this.start = start;
	    this.end = end;
	}
    }

}

