			i2=2*rmq[1].minPos(i1/2, e/2)+1;
		} else {
			i1=2*rmq[1].minPos(s/2, e/2-1)+1;
			i2=2*rmq[0].minPos(i1/2+1, e/2);
		}
		List<Integer> list = new ArrayList<Integer>();
