		for(int i=0; i<3; ++i)
			subLists[i] = new ArrayList<Integer>();
		if(i1+1<i2)
			subLists[0]=genPerm2(i1+1, i2-1);
		if(i1!=s)
			subLists[1]=genPerm2(s, i1-1);
		if(i2!=e)
