import static java.lang.Math.min;



public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    static int n;
    static int[] p;
    static int[] e, o;
    static RMQ te, to;
    static int[] work;

    public static void solve(StringBuilder out) {
        n = In.ni();
        p = In.ni(n);
        e = new int[n / 2];
        o = new int[n / 2];
        for (int i = 0; i < n; i += 2) {
            e[i / 2] = p[i];
            o[i / 2] = p[i + 1];
        }
        te = new RMQ(e);
        to = new RMQ(o);
        work = new int[n];
        part(0, n);
        out.append(IntArrays.join(p, " "));
    }

    public static void part(int l, int r) {
        if (r - l <= 2) return;
        int t1, t2;
        int m1, m2;
        if ((l & 1) == 0) {
            t1 = te.query(l / 2, r / 2);
            int k1 = te.indexOfMin(l / 2, r / 2);
            te.putInf(k1);
            t2 = to.query(k1, r / 2);
            int k2 = to.indexOfMin(k1, r / 2);
            to.putInf(k2);
            m1 = k1 * 2;
            m2 = k2 * 2 + 1;
        } else {
            t1 = to.query(l / 2, r / 2);
            int k1 = to.indexOfMin(l / 2, r / 2);
            to.putInf(k1);
            t2 = te.query(k1 + 1, r / 2 + 1);
            int k2 = te.indexOfMin(k1 + 1, r / 2 + 1);
            te.putInf(k2);
            m1 = k1 * 2 + 1;
            m2 = k2 * 2;
        }
        part(l, m1);
        part(m1 + 1, m2);
        part(m2 + 1, r);
        int i1 = l, i2 = m1 + 1, i3 = m2 + 1;
        work[l] = t1;
        work[l + 1] = t2;
        for (int i = l + 2; i < r; i += 2) {
            long v1 = i1 == m1 ? Const.LINF : p[i1];
            long v2 = i2 == m2 ? Const.LINF : p[i2];
            long v3 = i3 == r ? Const.LINF : p[i3];
            long min = min(v1, min(v2, v3));
            if (min == v1) {
                work[i] = p[i1];
                work[i + 1] = p[i1 + 1];
                i1 += 2;
            } else if (min == v2) {
                work[i] = p[i2];
                work[i + 1] = p[i2 + 1];
                i2 += 2;
            } else {
                work[i] = p[i2];
                work[i + 1] = p[i2 + 1];
                i3 += 2;
            }
        }
        System.arraycopy(work, l, p, l, r - l);
    }
}

class RMQ {
    private final int[] t;
    private final int n;
    private final int e = Const.IINF;

    public RMQ(final int[] a) {
        int nn = 1;
        while (nn < a.length) nn <<= 1;
        this.n = nn;
        this.t = new int[n << 1];
        System.arraycopy(a, 0, t, n, a.length);
        Arrays.fill(t, n + a.length, n << 1, e);
        for (int i = n - 1; i > 0; i--) t[i] = min(t[i << 1], t[(i << 1) | 1]);
    }

    public void putInf(int i) {
        i += n;
        t[i] = e;
        while ((i >>= 1) > 0) t[i] = min(t[i << 1], t[(i << 1) | 1]);
    }

    public int query(int l, int r) {
        int min = e;
        l += n; r += n;
        while (l < r) {
            if ((l & 1) != 0) min = min(min, t[l++]);
            if ((r & 1) != 0) min = min(t[--r], min);
            l >>= 1; r >>= 1;
        }
        return min;
    }

    public int indexOfMin(int l, int r) {
        int min = query(l, r);
        int k = 1;
        while (k < n) {
            k <<= 1;
            if (t[k] != min) k |= 1;
        }
        return k - n;
    }
}


