					rmq.update(c[e.min], INF);
					rmq.update(c[e2], INF);
					if (c[e2] > e.a + 1) {
						pq.add(new Tuple(e.a, c[e2]));
					}
					if (c[e.min] > c[e2] + 2) {
						pq.add(new Tuple(c[e2] + 1, c[e.min]));
					}
					if (e.b > c[e.min] + 2) {
						pq.add(new Tuple(c[e.min] + 1, e.b));
					}
				} else {
					pr.println("error odd");
				}
			}
		}

		for (int i = 0, size = ans.size(); i < size; i++) {
			if (i > 0) {
				pr.print(' ');
			}
			pr.print(ans.get(i) + 1);
		}
		pr.println();
	}

	private static int n;
	private static int INF;
	private static int[] p;
