	private static SegmentTree st;
	private static RMQSegmentTree rmq;

	private static int getRmin(int i, int j, RMQSegmentTree rmq, int k, SegmentTree st) {
		// iからjの間で、最小の値で、kからその最小値の位置までの個数が2の倍数の位置にあるもの。
		// 2の倍数でなければ、領域を分けて再帰
		int ret = rmq.query(i, j);
		if (ret > n) {
			return ret;
		}

		if (st.query(k, c[ret] + 1) % 2 == 0) {
			return ret;
		}

		return Math.min(getRmin(i, c[ret], rmq, k, st), getRmin(c[ret] + 1, j, rmq, k, st));
	}

	private static int getLmin(int i, int j, RMQSegmentTree rmq, int k, SegmentTree st) {
		// iからjの間で、最小の値で、その最小値の位置からkまでの個数が2の倍数の位置にあるもの。
		// 2の倍数でなければ、領域を分けて再帰
		int ret = rmq.query(i, j);
		if (ret > n) {
			return ret;
		}

		if (st.query(c[ret], k) % 2 == 0) {
			return ret;
		}

		return Math.min(getLmin(i, c[ret], rmq, k, st), getLmin(c[ret] + 1, j, rmq, k, st));
	}

	private static class Tuple implements Comparable<Tuple> {
		int a;
		int b;
		int min;

		Tuple(int a, int b) {
			this.a = a;
			this.b = b;
			min = rmq.query(a, b);
		}

		@Override
		public int compareTo(Tuple o) {
			return Integer.compare(min, o.min);
		}

		@Override
		public int hashCode() {
