import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.AbstractCollection;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            int[] where = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt() - 1;
                where[a[i]] = i;
            }
            int[] res = new int[n];
            int ptr = 0;
            IntervalTree tree = new IntervalTree(n);
            tree.build(a);

            PriorityQueue<Segment> pq = new PriorityQueue<>();
            pq.offer(new Segment(0, n - 1, tree.min(0, n - 1)));
            while (!pq.isEmpty()) {
                Segment seg = pq.poll();
                int l = seg.l;
                int r = seg.r;
                if (l > r) {
                    continue;
                }
                int xi = tree.min(l, r);
                int i = where[xi];
                int xj = tree.min(i + 1, r);
                int j = where[xj];
                res[ptr++] = xi;
                res[ptr++] = xj;
                pq.offer(new Segment(l, i - 1, tree.min(l, i - 1)));
                pq.offer(new Segment(j + 1, r, tree.min(j + 1, r)));
                pq.offer(new Segment(i + 1, j - 1, tree.min(i + 1, j - 1)));
            }

            for (int i = 0; i < n; i++) {
                if (i > 0) {
                    out.print(" ");
                }
                out.print(res[i] + 1);
            }
            out.println();
        }

        class IntervalTree {
            int[][] min;
            int n;
            final int infinity = (int) 1e9;

            IntervalTree(int n) {
                this.n = n;
                min = new int[2][4 * n];
                Arrays.fill(min[0], infinity);
                Arrays.fill(min[1], infinity);
            }

            public void build(int[] a) {
                buildRec(0, 0, n - 1, a);
            }

            private void buildRec(int root, int L, int R, int[] leaves) {
                if (L == R) {
                    min[L % 2][root] = leaves[L];
                    min[(L + 1) % 2][root] = infinity;
                    return;
                }
                int M = (L + R) / 2;
                buildRec(2 * root + 1, L, M, leaves);
                buildRec(2 * root + 2, M + 1, R, leaves);
                pull(root);
            }

            int min(int l, int r) {
                if (l > r) {
                    return infinity;
                }
                return get(0, l, r, 0, n - 1, l % 2);
            }

            private int get(int root, int l, int r, int L, int R, int parity) {
                if (l > r || l > R || L > r || L > R) {
                    return infinity;
                }
                if (l == L && r == R) {
                    return min[parity][root];
                }
                int M = (L + R) / 2;
                int res = infinity;
                res = Math.min(res, get(2 * root + 1, l, Math.min(r, M), L, M, parity));
                res = Math.min(res, get(2 * root + 2, Math.max(l, M + 1), r, M + 1, R, parity));
                return res;
            }

            private void pull(int root) {
                for (int i = 0; i < 2; i++) {
                    min[i][root] = Math.min(min[i][2 * root + 1], min[i][2 * root + 2]);
                }
            }

        }

        class Segment implements Comparable<Segment> {
            int l;
            int r;
            int val;

            Segment(int l, int r, int val) {
                this.l = l;
                this.r = r;
                this.val = val;
            }

            public int compareTo(Segment o) {
                if (val != o.val) {
                    return val < o.val ? -1 : 1;
                }
                return 0;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    static int N;
    static int[] p;
    static SegTree evenSegTree;
    static SegTree oddSegTree;

    static class NumAndPos {
	int num, pos;

	public NumAndPos(int num, int pos) {
	    super();
	    this.num = num;
	    this.pos = pos;
	}

	public NumAndPos() {
	}

    }

    static class SegTree {
	NumAndPos[] dat;
	int N;

	public SegTree(int n) {
	    N = n;

	    this.dat = new NumAndPos[2 * N];
	    for (int i = 0; i < 2 * N; i++) {
		dat[i] = new NumAndPos(-1, -1);
	    }

	}

	// void init(int n) {
	// N = 1;
	// while (N < n) {
	// N *= 2;
	// }
	// for (int i = 0; i < 2 * N - 1; i++) {
	// dat[i] = Integer.MAX_VALUE - 10;
	// }
	// }

	void update(int k, NumAndPos a) {
	    k += N - 1;
	    dat[k] = a;
	    while (0 < k) {
		k = (k - 1) / 2;
		// dat[k] = Math.min(dat[k * 2 + 1], dat[k * 2 + 2]);
		if (dat[k * 2 + 1].num < dat[k * 2 + 2].num) {
		    dat[k] = dat[k * 2 + 1];
		} else {
		    dat[k] = dat[k * 2 + 2];
		}
	    }
	}

	NumAndPos query(int a, int b, int k, int l, int r) {
	    if (r <= a || b <= l) {
		return new NumAndPos(Integer.MAX_VALUE - 10, 0);
	    }
	    if (a <= l && r <= b) {
		return dat[k];
	    } else {
		NumAndPos vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		NumAndPos vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		// return Math.min(vl, vr);
		if (vl.num < vr.num) {
		    return vl;
		} else {
		    return vr;
		}
	    }
	}
    }

    public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	N = sc.nextInt();
	p = new int[N];
	for (int i = 0; i < N; i++) {
	    p[i] = sc.nextInt();
	}

	evenSegTree = new SegTree(N);
	oddSegTree = new SegTree(N);

	for (int i = 0; i < N; i++) {
	    if (i % 2 == 0) {
		evenSegTree.update(i, new NumAndPos(p[i], i));
		oddSegTree.update(i, new NumAndPos(Integer.MAX_VALUE, i));
	    } else {
		oddSegTree.update(i, new NumAndPos(p[i], i));
		evenSegTree.update(i, new NumAndPos(Integer.MAX_VALUE, i));
	    }
	}

	Queue<Range> pq = new PriorityQueue<Range>(N, new MyComparator());
	pq.add(new Range(0, N));
	ArrayList<Integer> ans = new ArrayList<Integer>();
	while (ans.size() != N) {
	    Range tmpRange = pq.poll();
	    if (tmpRange.start % 2 == 0) {
		NumAndPos nap1 = evenSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap1.num);
		NumAndPos nap2 = oddSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap2.num);
		pq.add(new Range(tmpRange.start, nap1.pos));
		pq.add(new Range(nap1.pos + 1, nap2.pos));
		pq.add(new Range(nap2.pos + 1, tmpRange.end));
	    } else {
		NumAndPos nap1 = oddSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap1.num);
		NumAndPos nap2 = evenSegTree.query(tmpRange.start, tmpRange.end, 0, 0, N);
		ans.add(nap2.num);
		pq.add(new Range(tmpRange.start, nap1.pos));
		pq.add(new Range(nap1.pos + 1, nap2.pos));
		pq.add(new Range(nap2.pos + 1, tmpRange.end));
	    }
	}
	ans.stream().forEach(ele -> System.out.print(ele + " "));
    }

    static class MyComparator implements Comparator<Range> {
	@Override
	public int compare(Range r1, Range r2) {
	    if (r1.start % 2 == 0) {
		return evenSegTree.query(r1.start, r1.end, 0, 0, N).num
			- evenSegTree.query(r2.start, r2.end, 0, 0, N).num;
	    } else {
		return oddSegTree.query(r1.start, r1.end, 0, 0, N).num
			- oddSegTree.query(r2.start, r2.end, 0, 0, N).num;
	    }
	}
    }

    static class Range {
	int start, end;

	public Range(int start, int end) {
	    super();
	    this.start = start;
	    this.end = end;
	}
    }

}

