public class Main {
    private static int N;
    private static ArrayList<Integer> p = new ArrayList<Integer>();
    private static Queue<Integer> queue = new ArrayDeque<Integer>();

    public static void input(){
        Scanner scan = new Scanner(System.in);
        N = scan.nextInt();

        for(int i=0;i<N;i++) {
            p.add(scan.nextInt());
        }
