    Node second;
  }

  class Tree {
    Pack me = null;
    Tree parent = null;
    Tree left = null;
    Tree mid = null;
    Tree right = null;

    Tree get(int index) {
      switch (index) {
        case 0:
          return left;
        case 1:
          return mid;
        case 2:
          return right;
        default:
          return null;
      }
    }

    void clear(int index) {
      switch (index) {
        case 0:
          left = null;
          return;
        case 1:
          mid = null;
          return;
        case 2:
          right = null;
      }
    }
  }

  int n;
  SegmentTree<Node> gusu;
  SegmentTree<Node> kisu;

  Tree search(int l, int r) {
    if (l == r) {
      return null;
    }
    Tree ret = new Tree();
    Node first;
    Node second;
    if (l % 2 == 0) {
      first = gusu.reduce(l, r);
      second = kisu.reduce(first.index, r);
    } else {
      first = kisu.reduce(l, r);
      second = gusu.reduce(first.index, r);
    }
    Pack me = new Pack();
    me.first = first;
    me.second = second;
    ret.me = me;
    ret.left = search(l, first.index);
    if (ret.left != null) {
      ret.left.parent = ret;
    }
    ret.mid = search(first.index + 1, second.index);
    if (ret.mid != null) {
      ret.mid.parent = ret;
    }
    ret.right = search(second.index + 1, r);
    if (ret.right != null) {
      ret.right.parent = ret;
    }
    return ret;
  }

  LinkedList<Tree> leaf = new LinkedList<>();

  void get_leaf(Tree node) {
    if (node == null) {
      return;
    }
    if (node.left == null
        && node.mid == null
        && node.right == null) {
//      debug("add ", node.me.first.val, node.me.second.val);
      leaf.add(node);
    }
    get_leaf(node.left);
    get_leaf(node.mid);
    get_leaf(node.right);
  }

  void run() {
    n = ni();
    int[] p = new int[n];
    for (int i = 0; i < n; ++i) {
      p[i] = ni();
    }
    gusu = new SegmentTree<>(n, (a, b) -> {
      if (a == null) {
        return b;
      }
      if (b == null) {
        return a;
      }
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, () -> null);
    kisu = new SegmentTree<>(n, (a, b) -> {
      if (a == null) {
        return b;
      }
      if (b == null) {
        return a;
      }
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, () -> null);
    for (int i = 0; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      gusu.set(i, node);
    }
    for (int i = 1; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      kisu.set(i, node);
    }
    Tree root = search(0, n);
    PriorityQueue<Tree> queue = new PriorityQueue<>((l, r) -> r.me.first.val - l.me.first.val);
    get_leaf(root);
    queue.addAll(leaf);
    LinkedList<Pack> ans = new LinkedList<>();
    while (queue.size() > 0) {
      Tree node = queue.poll();
//      debug(node.me.first.val, node.me.second.val);
