  class Tree {
    Pack me = null;
    Tree left = null;
    Tree mid = null;
    Tree right = null;

    Tree get(int index) {
      switch (index) {
        case 0:
          return left;
        case 1:
          return mid;
        case 2:
          return right;
        default:
          return null;
      }
    }
