  SegmentTree<Node> kisu;

  Tree search(int l, int r) {
    if (l == r) {
      return null;
    }
    Tree ret = new Tree();
    Node first;
    Node second;
    if (l % 2 == 0) {
      first = gusu.reduce(l, r);
      second = kisu.reduce(first.index, r);
    } else {
      first = kisu.reduce(l, r);
      second = gusu.reduce(first.index, r);
    }
    Pack me = new Pack();
    me.first = first;
    me.second = second;
    ret.me = me;
    ret.left = search(l, first.index);
    ret.mid = search(first.index + 1, second.index);
    ret.right = search(second.index + 1, r);
    return ret;
  }

