import static java.lang.System.in;
class Main {
    static int[] idx;
    static int[] A;
    static ST even;
    static ST odd;
    static ST all;
    public static void main(String[] args) throws IOException{
        //Scanner sc = new Scanner(System.in);
        //int n = sc.nextInt();
        BufferedReader reader = new BufferedReader(new InputStreamReader(in));
        String temp;
        String[] buf;
        temp = reader.readLine();
        int n = Integer.parseInt(temp);
        temp = reader.readLine();
        buf = temp.split(" ");

        A = new int[n];
        idx = new int[n+1];
        for(int i=0;i<n;i++){
            A[i] = Integer.parseInt(buf[i]);
            idx[A[i]] = i;
        }
        even = new ST(n/2);
        odd = new ST(n/2);
        all = new ST(n);

        for(int i=0;i<n;i+=2) even.update(i/2,A[i]);
        for(int i=1;i<n;i+=2) odd.update(i/2,A[i]);
        for(int i=0;i<n;i++) all.update(i,A[i]);
        myComparator mc = new myComparator();
        PriorityQueue<int[]> pq = new PriorityQueue<>(10,mc);
        pq.add(new int[]{0,n});
        ArrayList<Integer> res = new ArrayList<>();
        while(res.size()<n){
            int[] cur = pq.poll();
            int left = cur[0];
            int right = cur[1];
            int now,next;
            if(left%2==0){
                now = even.find(left/2,right/2);
                next = odd.find((idx[now]+1)/2,(right+1)/2);
            }else{
                now = odd.find(left/2,right/2);
                next = even.find((idx[now]+1)/2,(right+1)/2);
            }
            res.add(now);
            res.add(next);
            if(left<idx[now]) pq.add(new int[]{left,idx[now]});
            if(idx[now]<idx[next]-1) pq.add(new int[]{idx[now]+1,idx[next]});
            if(idx[next]<right-1) pq.add(new int[]{idx[next]+1,right});
        }
        for(int i=0;i<res.size();i++){
            System.out.print(Integer.toString(res.get(i))+" ");
        }
    }

    static class ST{
        int n=1;
        int[] dat;
        public ST(int n_){
            while(n<n_) n*=2;
            dat = new int[2*n-1];
            for(int i=0;i<2*n-1;i++) dat[i] = Integer.MAX_VALUE/2;
        }
        public void update(int idx, int val){
            idx += n-1;
            dat[idx] = val;
            while(idx>0){
                idx = (idx-1)/2;
                dat[idx] = Math.min(dat[idx*2+1],dat[idx*2+2]);
            }
        }
        public int find(int a, int b){
            return query(a,b,0,0,n);
        }
        private int query(int a, int b, int k, int left, int right){
            if(b<=left||right<=a) return Integer.MAX_VALUE;
            if(a<=left&&right<=b) return dat[k];
            int v1 = query(a,b,2*k+1,left,(left+right)/2);
            int v2 = query(a,b,2*k+2,(left+right)/2,right);
            return Math.min(v1,v2);
        }
    }
    static class myComparator implements Comparator<int[]>{
        public int compare(int[] o1, int[] o2){
            int[][] dic = new int[][]{o1,o2};
            int[] res = new int[2];
            for(int i=0;i<2;i++){
                int[] cur = dic[i];
                int left = cur[0];
                int right = cur[1];
                int p = left%2==0?even.find(left/2,right/2):odd.find(left/2,right/2);
                res[i]=p;
            }
            return res[0]-res[1];
        }
    }
}

import java.util.*;

public class Main {
    static long MOD = 109+7;

    static public void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        List<Integer> p = new ArrayList<>();
        for(int i = 0 ; i < n; i++) {
            p.add(sc.nextInt());
        }

        LinkedList<Integer> q = new LinkedList<>();

        while(p.size() > 0) {
            int id = 0;
            int former = p.get(0);
            int latter = p.get(1);
            int min = Math.min(former, latter);
            int max = Math.max(former, latter);

            for(int i = 1; i < p.size() - 1; i++) {
                int _former = p.get(i);
                int _latter = p.get(i + 1);
                int _min = Math.min(_former, _latter);
                int _max = Math.max(_former, _latter);
                boolean change = false;
                if(min < _min) {
                    change = true;
                } else if(min == _min) {
                    if(max < _max) {
                        change = true;
                    } else if(max == _max) {
                        if(former > _former) {
                            change = true;
                        }
                    }
                }

                if(change) {
                    id = i;
                    former = _former;
                    latter = _latter;
                    min = _min;
                    max = _max;
                }
            }

            q.addFirst(p.remove(id + 1));
            q.addFirst(p.remove(id));
        }

        Iterator<Integer> iterator = q.iterator();
        System.out.print(iterator.next());
        while(iterator.hasNext()) {
            System.out.print(" " + iterator.next());
        }
        System.out.println();
    }
}

