    RangeMinimumSegTreeIMax[] st;
    void solve() throws IOException {
        int n = in.nextInt();
        int[] p = new int[n];
        st = new RangeMinimumSegTreeIMax[2];
        st[0] = new RangeMinimumSegTreeIMax(n / 2);
        st[1] = new RangeMinimumSegTreeIMax(n / 2);
        for (int i = 0; i < n; i++) {
            p[i] = in.nextInt();
            st[i % 2].set(i / 2, p[i]);
        }
