  class Node {
    int val = Integer.MAX_VALUE;
    int index;
  }

  class Pack {
    Node first;
    Node second;
  }

  class Tree {
    Pack me = null;
    Tree parent = null;
    Tree left = null;
    Tree mid = null;
    Tree right = null;
  }

  int n;
  SegmentTree<Node> gusu;
  SegmentTree<Node> kisu;

  Tree search(int l, int r) {
    if (l == r) {
      return null;
    }
    Tree ret = new Tree();
    Node first;
    Node second;
    if (l % 2 == 0) {
      first = gusu.reduce(l, r);
      second = kisu.reduce(l, r);
    } else {
      first = kisu.reduce(l, r);
      second = gusu.reduce(l, r);
    }
    Pack me = new Pack();
    me.first = first;
    me.second = second;
    ret.me = me;
    ret.left = search(l, first.index);
    if (ret.left != null) {
      ret.left.parent = ret;
    }
    ret.mid = search(first.index + 1, second.index);
    if (ret.mid != null) {
      ret.mid.parent = ret;
    }
    ret.right = search(second.index + 1, r);
    if (ret.right != null) {
      ret.right.parent = ret;
    }
    return ret;
  }

  LinkedList<Tree> leaf = new LinkedList<>();

  void get_leaf(Tree node) {
    if (node == null) {
      return;
    }
    if (node.mid == null) {
//      debug("add ", node.me.first.val, node.me.second.val);
      leaf.add(node);
    }
    get_leaf(node.left);
    get_leaf(node.mid);
    get_leaf(node.right);
  }

  void run() {
    n = ni();
    int[] p = new int[n];
    for (int i = 0; i < n; ++i) {
      p[i] = ni();
    }
    gusu = new SegmentTree<>(n, (a, b) -> {
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, Node::new);
    kisu = new SegmentTree<>(n, (a, b) -> {
      if (a.val < b.val) {
        return a;
      } else {
        return b;
      }
    }, Node::new);
    for (int i = 0; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      gusu.set(i, node);
    }
    for (int i = 1; i < n; i += 2) {
      Node node = new Node();
      node.val = p[i];
      node.index = i;
      kisu.set(i, node);
    }
    Tree root = search(0, n);
    PriorityQueue<Tree> queue = new PriorityQueue<>((l, r) -> r.me.first.val - l.me.first.val);
    get_leaf(root);
    queue.addAll(leaf);
    LinkedList<Pack> ans = new LinkedList<>();
    for (; ; ) {
      Tree node = queue.poll();
//      debug(node.me.first.val, node.me.second.val);
      ans.addFirst(node.me);
      Tree parent = node.parent;
      if (parent == null) {
        break;
      }
//      debug("\t\tparent : ", parent.me.first.val, parent.me.second.val);
      if (parent.mid == node) {
        queue.add(parent);
      }
    }
    ArrayList<Pack> bns = new ArrayList<>(ans);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n / 2; ++i) {
      if (i > 0) {
        sb.append(" ");
      }
      Pack pack = bns.get(i);
      sb.append(pack.first.val);
      sb.append(" ");
      sb.append(pack.second.val);
    }
    System.out.println(sb.toString());
  }

