public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        int[] a;

        public void solve(int testNumber, InputReader in, PrintWriter out) {


            int n = in.nextInt();
            a = new int[n];

            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
            }

            PriorityQueue<Pair> pq = new PriorityQueue<>();

            for (int i = 0; i + 1 < n; ++i) {
                pq.add(new Pair(i, i + 1, a[i] + a[i + 1]));
            }


            boolean vis[] = new boolean[n];

            int ans[] = new int[n];
            int idx = n - 1;

            while (!pq.isEmpty() && idx > 0) {

                Pair p = pq.poll();

                if (vis[p.i] || vis[p.j])
                    continue;

                ans[idx--] = a[p.j];
                ans[idx--] = a[p.i];


                vis[p.i] = true;
                vis[p.j] = true;


                if (p.i > 0 && p.j < n - 1) {
                    pq.add(new Pair(p.i - 1, p.j + 1, a[p.i - 1] + a[p.j + 1]));
                }

            }

            for (int i = 0; i < n; ++i) {
                if (ans[i] == 0)
                    throw new RuntimeException();
                out.print(ans[i] + (i == n - 1 ? "\n" : " "));
            }

        }

        class Pair implements Comparable<Pair> {
            int i;
            int j;
            int sum;

            public Pair(int i, int j, int sum) {
                this.i = i;
                this.j = j;
                this.sum = sum;
            }


            public int compareTo(Pair o) {
                if (sum != o.sum)
                    return Integer.compare(o.sum, sum);
                else
                    return Integer.compare(a[i], a[o.i]);
            }


            public boolean equals(Object obj) {
                if (!(obj instanceof Pair))
                    return false;

                Pair p = (Pair) obj;

                return p.i == i && p.j == j && sum == p.sum;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    int n;
    int[] as;
    int[] ans;
    PriorityQueue<Val> queue;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        as = new int[n];
        for (int i = 0; i < n; i++) {
            as[i] = sc.nextInt();
        }
        ans = new int[n];
        queue = new PriorityQueue<>((v1, v2) -> Integer.compare(as[v1.st], as[v2.st]));
    }

    private void solve() {
        part(0, n);
        int count = 0;
        while (!queue.isEmpty()) {
            Val v = queue.poll();
            ans[count++] = as[v.st];
            ans[count++] = as[v.ed];
            if (v.st - v.rangeST > 0)
                part(v.rangeST, v.st);
            if (v.ed - v.st - 1 > 0)
                part(v.st+1, v.ed);
            if (v.rangeED - v.ed - 1 > 0)
                part(v.ed+1, v.rangeED);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n-1; i++) {
            sb.append(ans[i]);
            sb.append(" ");
        }
        sb.append(ans[n-1]);
        System.out.println(sb.toString());
    }

    private void part(int start, int end) {
        int min1 = getMin(start, end);
        int min2 = getMin(min1+1, end);
        if (min1 == -1 || min2 == -1)
            return;
        queue.add(new Val(min1, min2, start, end));
    }

    private int getMin(int start, int end) {
        if (start >= end)
            return -1;
        int minVal = Integer.MAX_VALUE;
        int minIx = -1;
        for (int i = start; i < end; i += 2) {
            if (minVal > as[i]) {
                minVal = as[i];
                minIx = i;
            }
        }
        return minIx;
    }


    private class Val {
        int st;
        int ed;
        int rangeST;
        int rangeED;
        Val (int st, int ed, int rg_st, int rg_ed) {
            this.st = st;
            this.ed = ed;
            rangeST = rg_st;
            rangeED = rg_ed;
        }
    }
}

