/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author HossamDoma
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, PrintWriter out) {


            int n = in.nextInt();
            int[] a = new int[n];

            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
            }

            PriorityQueue<Pair> pq = new PriorityQueue<>();

            for (int i = 0; i + 1 < n; ++i) {
                pq.add(new Pair(i, i + 1, a[i] + a[i + 1]));
            }


            int ans[] = new int[n];
            int idx = n - 1;

            while (pq.size() > 0) {

                Pair p = pq.poll();

                ans[idx--] = a[p.j];
                ans[idx--] = a[p.i];

                if (p.i > 0) {
                    pq.remove(new Pair(p.i - 1, p.i, a[p.i - 1] + a[p.i]));
                }

                if (p.j < n - 1) {
                    pq.remove(new Pair(p.j, p.j + 1, a[p.j] + a[p.j + 1]));
                }

                if (p.i > 0 && p.j < n - 1) {
                    pq.add(new Pair(p.i - 1, p.j + 1, a[p.i - 1] + a[p.j + 1]));
                }

            }

            for (int i = 0; i < n; ++i) {
                out.print(ans[i] + (i == n - 1 ? "\n" : " "));
            }

        }

        class Pair implements Comparable<Pair> {
            int i;
            int j;
            int sum;

            public Pair(int i, int j, int sum) {
                this.i = i;
                this.j = j;
                this.sum = sum;
            }


            public int compareTo(Pair o) {
                return o.sum - sum;
            }


            public boolean equals(Object obj) {
                if (!(obj instanceof Pair))
                    return false;

                Pair p = (Pair) obj;

                return p.i == i && p.j == j && sum == p.sum;

            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	private void solve() {
		Scanner io = new Scanner(System.in);
		int N = io.nextInt();
		ArrayList<ArrayList<Integer>> input = new ArrayList<>();
		ArrayList<Integer> first = new ArrayList<>();
		for(int i=0;i<N;i++){
			first.add(io.nextInt());
		}
		input.add(first);
		ArrayList<Integer> ans = new ArrayList<>();

		do{
			input = getTwo(input);
			ans.addAll(input.get(0));
			input.remove(0);
		}while(!input.isEmpty());

		for(int i=0;i<ans.size();i++){
			System.out.print(ans.get(i) + ((i==ans.size()-1)?"\n":" "));
		}

	}

	private ArrayList<ArrayList<Integer>> 
			getTwo(ArrayList<ArrayList<Integer>> list){
		int min = Integer.MAX_VALUE;
		int min_i = 0;
		int min_j = 0;
		for(int i=0;i<list.size();i++){
			for(int j=0;j<list.get(i).size();j++){
				if((j&1)==0){
					int num = list.get(i).get(j);
					if(num<min){
						min = num;
						min_i = i;
						min_j = j;
					}
				}
			}
		}
		int next = Integer.MAX_VALUE;
		int next_j = 0;
		for(int j=min_j+1;j<list.get(min_i).size();j++){
			if(((j-min_j-1)&1)==0){
				int num = list.get(min_i).get(j);
				if(num<next){
					next = num;
					next_j = j;
				}
			}
		}
		ArrayList<ArrayList<Integer>> ans = new ArrayList<>();
		ArrayList<Integer> ansNums = new ArrayList<>();
		ansNums.add(min);
		ansNums.add(next);
		ans.add(ansNums);
		for(int i=0;i<list.size();i++){
			if(i==min_i){
				ArrayList<Integer> splited = new ArrayList<>();
				for(int j=0;j<list.get(min_i).size();j++){
					if((j==min_j || j==next_j)){
						if(!splited.isEmpty()){
							ans.add(splited);
							splited = new ArrayList<>();
						}
					}else{
						splited.add(list.get(min_i).get(j));
					}
				}
				if(!splited.isEmpty()) ans.add(splited);
			}else{
				ans.add(list.get(i));
			}
		}
		return ans;
	}

	public static void main(String[] args) {
		new Main().solve();
	}
}

import java.util.*;

class Main {
    static int[] idx;
    static int[] A;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        A = new int[n];
        idx = new int[n+1];
        for(int i=0;i<n;i++){
            A[i] = sc.nextInt();
            idx[A[i]] = i;
        }
        ST even = new ST(n/2);
        ST odd = new ST(n/2);
        ST idxRec = new ST(n);
        ST idxFromLeft = new ST(n);
        for(int i=0;i<n;i+=2) even.update(i/2,A[i]);
        for(int i=1;i<n;i+=2) odd.update(i/2,A[i]);
        for(int i=0;i<n;i++) idxRec.update(i,n);
        for(int i=0;i<n;i++) idxFromLeft.update(i,1);
        ArrayList<Integer> res = new ArrayList<>();

        boolean[] used = new boolean[n+1];

        for(int i=1;i<=n;i++){
            if(idx[i]%2==1) continue;
            int curIdx = idx[i];
            int next = odd.find((curIdx+1)/2,n/2);
            res.add(i);
            res.add(next);
            used[i]=true;
            used[next]=true;
            idxRec.update(curIdx,curIdx);
            idxRec.update(idx[next],idx[next]);
            idxFromLeft.update(curIdx,-curIdx);
            idxFromLeft.update(idx[next],-idx[next]);
            break;
        }
        for(int i=1;i<=n;i++){
            if(used[i]) continue;
            int curIdx = idx[i];
            int farthest = idxRec.find(curIdx,n-1);
            int temp = idxFromLeft.find(0,curIdx-1);
            int leftMost = temp>0?-1:-temp;
            if(farthest-curIdx<=1||(farthest-curIdx)%2==1) continue;
            if((curIdx-leftMost)%2==0) continue;
            int[] bound = computeBound(curIdx,farthest);
            int next = curIdx%2==0?odd.find(bound[0],bound[1]):even.find(bound[0],bound[1]);
            res.add(i);
            res.add(next);
            used[i]=true;
            used[next]=true;
            idxRec.update(curIdx,curIdx);
            idxRec.update(idx[next],idx[next]);
            idxFromLeft.update(curIdx,-curIdx);
            idxFromLeft.update(idx[next],-idx[next]);
        }
        for(int i=0;i<res.size();i++){
            System.out.print(Integer.toString(res.get(i))+" ");
        }
    }
    static int[] computeBound(int cur, int farthest){
        if(cur%2==1){
            int end = farthest%2==1?farthest-1:farthest-2;
            return new int[]{(cur+1)/2,end/2};
        } else{
            int end = farthest%2==0?farthest-1:farthest-2;
            return new int[]{(cur+1)/2,end/2};
        }
    }
    static class ST{
        int n=1;
        int[] dat;

        public ST(int n_){
            while(n<n_) n*=2;
            dat = new int[2*n-1];
            for(int i=0;i<2*n-1;i++) dat[i] = Integer.MAX_VALUE/2;
        }
        public void update(int idx, int val){
            idx += n-1;
            dat[idx] = val;
            while(idx>0){
                idx = (idx-1)/2;
                dat[idx] = Math.min(dat[idx*2+1],dat[idx*2+2]);
            }
        }

        public int find(int a, int b){
            return query(a,b+1,0,0,n);
        }
        private int query(int a, int b, int k, int left, int right){
            if(b<=left||right<=a) return Integer.MAX_VALUE;
            if(a<=left&&right<=b) return dat[k];
            int v1 = query(a,b,2*k+1,left,(left+right)/2);
            int v2 = query(a,b,2*k+2,(left+right)/2,right);
            return Math.min(v1,v2);
        }
    }
}

