class SegmentTree<T>
{
    int n;
    T[] tree;
    T id;
    Func<T, T, T> ope;

    public SegmentTree(int n, T id, Func<T, T, T> ope) : this(id, ope)
    {
        this.n = 1;
        while (this.n < n) this.n *= 2;
        tree = Enumerable.Repeat(id, this.n * 2).ToArray();
    }

    public SegmentTree(T[] xs, T id, Func<T, T, T> ope) : this(id, ope)
    {
        n = 1;
        while (n < xs.Length) n *= 2;
        tree = new T[n * 2];
        for (var i = 0; i < n; i++)
            tree[i + n] = i < xs.Length ? xs[i] : id;
        for (var i = n - 1; i > 0; i--)
            tree[i] = ope(tree[i * 2], tree[i * 2 + 1]);
    }

    SegmentTree(T id, Func<T, T, T> ope)
    {
        this.id = id;
        this.ope = ope;
    }

    public T this[int i]
    {
        get { return tree[i + n]; }
        set
        {
            tree[i += n] = value;
            for (i >>= 1; i > 0; i >>= 1)
                tree[i] = ope(tree[i * 2], tree[i * 2 + 1]);
        }
    }

    public T this[int i, int j]
    {
        get
        {
            var r = id;
            i += n;
            j += n + 1;
            for (; i < j; i >>= 1, j >>= 1)
            {
                if ((j & 1) != 0) r = ope(r, tree[--j]);
                if ((i & 1) != 0) r = ope(r, tree[i++]);
            }
            return r;
        }
    }
}

class PriorityQueue<T>
{
    List<T> heap;
    int size;
    Comparison<T> compare;

    public PriorityQueue()
        : this(Enumerable.Empty<T>(), Comparer<T>.Default.Compare) { }

    public PriorityQueue(IEnumerable<T> collection)
        : this(collection, Comparer<T>.Default.Compare) { }

    public PriorityQueue(Comparison<T> comparsion)
        : this(Enumerable.Empty<T>(), comparsion) { }

    public PriorityQueue(IEnumerable<T> collection, Comparison<T> comparsion)
    {
        var array = collection.ToArray();
        Array.Sort(array, comparsion);
        heap = new List<T>(array);
        compare = comparsion;
    }

    public int Count => size;

    public bool Any() => size > 0;

    public void Clear() => size = 0;

    public T Peek() => heap[0];

    public void Enqueue(T item)
    {
        var i = size++;
        while (i > 0)
        {
            var p = (i - 1) >> 1;
            if (compare(heap[p], item) <= 0) break;
            if (i == heap.Count) heap.Add(heap[p]);
            else heap[i] = heap[p];
            i = p;
        }
        if (i == heap.Count) heap.Add(item);
        else heap[i] = item;
    }

    public T Dequeue()
    {
        var r = heap[0];
        var x = heap[--size];
        var i = 0;
        while ((i << 1) + 1 < size)
        {
            var a = (i << 1) + 1;
            var b = (i << 1) + 2;
            if (b < size && compare(heap[b], heap[a]) < 0) a = b;
            if (compare(heap[a], x) >= 0) break;
            heap[i] = heap[a];
            i = a;
        }
        heap[i] = x;
        return r;
    }
}

static class Extentions
{
    public const int Inf = int.MaxValue;
}

struct Pair : IComparable<Pair>
{
    public int X, Y, Min;

    public Pair(int x, int y, int min)
    {
        X = x; Y = y; Min = min;
    }

    public int CompareTo(Pair other) => Min.CompareTo(other.Min);
}

static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.I;
        var p = io.Is(n);

        var pi = new int[n + 1];
        for (var i = 0; i < n; i++) pi[p[i]] = i;

        var evenp = p.Select((x, i) => i % 2 == 0 ? x : Inf).ToArray();
        var oddp = p.Select((x, i) => i % 2 != 0 ? x : Inf).ToArray();
        var evenst = new SegmentTree<int>(evenp, Inf, Min);
        var oddst = new SegmentTree<int>(oddp, Inf, Min);

        var xmin = Inf;
        var xmini = 0;
        var ymin = Inf;
        var ymini = n - 1;

        var pq = new PriorityQueue<Pair>();
        pq.Enqueue(new Pair(xmini, ymini, evenst[xmini, ymini]));

        while (pq.Any())
        {
            var pair = pq.Dequeue();

            xmin = pair.X % 2 == 0 ? evenst[pair.X, pair.Y] : oddst[pair.X, pair.Y];
            xmini = pi[xmin];
            ymin = pair.X % 2 == 0 ? oddst[xmini + 1, pair.Y] : evenst[xmini + 1, pair.Y];
            ymini = pi[ymin];

            if (xmini > pair.X)
            {
                var tl = pair.X;
                var tr = xmini - 1;
                var min = pair.X % 2 == 0 ? evenst[tl, tr] : oddst[tl, tr];

                pq.Enqueue(new Pair(tl, tr, min));
            }

            if (ymini - xmini > 1)
            {
                var tl = xmini + 1;
                var tr = ymini - 1;
                var min = pair.X % 2 == 0 ? oddst[tl, tr] : evenst[tl, tr];

                pq.Enqueue(new Pair(tl, tr, min));
            }

            if (ymini < pair.Y)
            {
                var tl = ymini + 1;
                var tr = pair.Y;
                var min = pair.X % 2 == 0 ? evenst[tl, tr] : oddst[tl, tr];

                pq.Enqueue(new Pair(tl, tr, min));
            }

            Write(xmin + " " + ymin + " ");
        }
    }
}

