                {
                    right = P[i];
                    t = i;
                }
            }          
        }
        G.Add($"{depth}{max} {right}");
        //WriteLine(max + " " + depth);
        calc(a, s, depth+1);
        calc(s + 1, t, depth + 1);
        calc(t + 1, b,depth + 1);

    }

