class PQ
{
    public int Length=0;
    private const int MaxSize=1<<17;
    private S[]Tree=new S[MaxSize+1];

    public void  Push(S s)
    {
        if(s.Right-s.Left<2) return;
        Length++;
        Tree[Length]=s;
        int pos=Length;
        while(pos>1)
        {
            int u=pos/2;
            if(Tree[pos].Min.Value<Tree[u].Min.Value)
            {
                Swap(pos,u);
            }
            else
            {
                return;
            }
            pos=u;
        }
    }

    public S Pop()
    {
        S result=Tree[1];
        Length--;
        if(Length>0)
        {
            Tree[1]=Tree[Length+1];
            int pos=1;
            while(pos*2<=Length)
            {
                int left=pos*2;
                int right=pos*2+1;
                int min=Min(left,right);
                if(Tree[min].Min.Value<Tree[pos].Min.Value)
                {
                    Swap(min,pos);
                    pos=min;
                }
                else
                {
                    break;
                }
            }
        }

        return result;
    }

    private void Swap(int a,int b)
    {
        var t=Tree[a];
        Tree[a]=Tree[b];
        Tree[b]=t;
    }

    private int Min(int a,int b)
    {
        if(b>Length)
        {
            return a;
        }
        if(Tree[a].Min.Value<Tree[b].Min.Value)
        {
            return a;
        }
        else
        {
            return b;
        }
    }
}

class SegTree
{
    private int N;
    private I[]Tree;
    public SegTree(I[]array)
    {
        N=1<<18;
        Tree=new I[N*2];
        for(int i=1;i<N*2;i++)
        {
            Tree[i]=new I(int.MaxValue,-1);
        }
        for(int i=0;i<array.Length;i++)
        {
            Tree[i+N]=array[i];
        }
        for(int i=N-1;i>=1;i--)
        {
            Tree[i]=Min(Tree[i*2],Tree[i*2+1]);
        }
    }
    public I Query(int a,int b,int k,int l,int r)
    {
        if(a<=l&&r<=b)return Tree[k];
        if(b<=l||r<=a)return new I(int.MaxValue,-1);
        I left=Query(a,b,k*2,l,(l+r)/2);
        I right=Query(a,b,k*2+1,(l+r)/2,r);
        return Min(left,right);
    }
    public I Q(int a,int b)
    {
        return Query(a,b,1,0,N);
    }
    private I Min(I a,I b)
    {
        if(a.Value<b.Value)
        {
            return a;
        }
        else
        {
            return b;
        }
    }
}

class Magatro
{
    private int N;
    private SegTree G,K;
    private PQ Pq;
    private int[]Anser;
    private void Scan()
    {
        N=int.Parse(Console.ReadLine());
        var line=Console.ReadLine().Split(' ');
        Pq=new PQ();
        I[]kk=new I[N];
        I[]gg=new I[N];

        for(int i=0;i<N;i++)
        {
           int a=int.Parse(line[i]);
            if(i%2==1)
            {
                kk[i]=new I(a,i);
                gg[i]=new I(int.MaxValue,-1);
            }
            else
            {
                gg[i]=new I(a,i);
                kk[i]=new I(int.MaxValue,-1);
            }
        }
        G=new SegTree(gg);
        K=new SegTree(kk);
        Pq.Push(new S(0,N,G.Q(0,N)));
    }
    public void Solve()
    {    
        Scan();
        Anser=new int[N];
        int cnt=0;
        while(Pq.Length>0)
        {
            S top=Pq.Pop();
            int left=top.Left;
            int right=top.Right;
            I min = top.Min;
            I rightMin;
            if(left%2==0)
            {
                rightMin=K.Q(min.Index,right);
                S a=new S(left,min.Index,G.Q(left,min.Index));
                S b=new S(min.Index+1,rightMin.Index,K.Q((min.Index+1),rightMin.Index));
                S c=new S(rightMin.Index+1,right,G.Q((rightMin.Index+1),right));
                Pq.Push(a);
                Pq.Push(b);
                Pq.Push(c);
            }
            else
            {
                rightMin=G.Q(min.Index,right);
                S a=new S(left,min.Index,K.Q(left,min.Index));
                S b=new S(min.Index+1,rightMin.Index,G.Q((min.Index+1),rightMin.Index));
                S c=new S(rightMin.Index+1,right,K.Q((rightMin.Index+1),right));
                Pq.Push(a);
                Pq.Push(b);
                Pq.Push(c);
            }
            Anser[cnt]=min.Value;
            Anser[cnt+1]=rightMin.Value;
            cnt+=2;
        }
        Console.WriteLine(string.Join(" ",Anser));
    }
}

using System;
using System.Collections.Generic;


class SegTree<T>
{
    private readonly T[] Array;
    private readonly Comparison<T> Compare;
    private readonly int N;
    private readonly T Max;

    public SegTree(int size, T max) : this(size, Comparer<T>.Default, max)
    {
    }

    public SegTree(int size, IComparer<T> comparer, T max) : this(size, comparer.Compare, max)
    {
    }

    public SegTree(int size, Comparison<T> comparison, T max)
    {
        Max = max;
        N = 1;
        while (N < size)
        {
            N *= 2;
        }

        Compare = comparison;
        Array = new T[2 * N];
        for (int i = 1; i < 2 * N; i++)
        {
            Array[i] = max;
        }
    }

    new public T this[int i]
    {
        get { return Array[i + N]; }
        set { Update(value, i); }
    }


    private T Min(T x, T y)
    {
        return Compare(x, y) < 0 ? x : y;
    }

    public void Update(T item, int index)
    {
        index += N;
        Array[index] = item;
        while (index > 1)
        {
            index /= 2;
            Array[index] = Min(Array[index * 2], Array[index * 2 + 1]);
        }
    }

    private T Q(int left, int right, int k, int l, int r)
    {
        if (left <= l && r <= right)
        {
            return Array[k];
        }

        if (r <= left || right <= l)
        {
            return Max;
        }

        return Min(Q(left, right, k * 2, l, (l + r) / 2), Q(left, right, k * 2 + 1, (l + r) / 2, r));
    }

    public T Query(int left, int right)
    {
        return Q(left, right, 1, 0, N);
    }
}

#region PriorityQueue

/// <summary>
/// 指定した型のインスタンスを最も価値が低い順に取り出すことが可能な可変サイズのコレクションを表します．
/// </summary>
/// <typeparam name="T">優先度付きキュー内の要素の型を指定します．</typeparam>
/// <remarks>内部的にはバイナリヒープによって実装されています．</remarks>
public class PriorityQueue<T>
{
    readonly List<T> heap = new List<T>();
    readonly Comparison<T> cmp;

    /// <summary>
    /// デフォルトの比較子を使用してインスタンスを初期化します．
    /// </summary>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue()
    {
        cmp = Comparer<T>.Default.Compare;
    }

    /// <summary>
    /// デリゲートで表されるような比較関数を使用してインスタンスを初期化します．
    /// </summary>
    /// <param name="comparison"></param>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue(Comparison<T> comparison)
    {
        cmp = comparison;
    }

    /// <summary>
    /// 指定された比較子を使用してインスタンスを初期化します．
    /// </summary>
    /// <param name="comparer"></param>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public PriorityQueue(IComparer<T> comparer)
    {
        cmp = comparer.Compare;
    }

    /// <summary>
    /// 優先度付きキューに要素を追加します．
    /// </summary>
    /// <param name="item">優先度付きキューに追加される要素</param>
    /// <remarks>最悪計算量 O(log N) で実行されます．</remarks>
    public void Enqueue(T item)
    {
        var pos = heap.Count;
        heap.Add(item);
        while (pos > 0)
        {
            var par = (pos - 1) / 2;
            if (cmp(heap[par], item) <= 0)
                break;
            heap[pos] = heap[par];
            pos = par;
        }

        heap[pos] = item;
    }

    /// <summary>
    /// 優先度付きキューから最も価値が低い要素を削除し，返します．
    /// </summary>
    /// <returns>優先度付きキューから削除された要素．</returns>
    /// <remarks>最悪計算量 O(log N) で実行されます．</remarks>
    public T Dequeue()
    {
        var ret = heap[0];
        var pos = 0;
        var x = heap[heap.Count - 1];

        while (pos * 2 + 1 < heap.Count - 1)
        {
            var lch = pos * 2 + 1;
            var rch = pos * 2 + 2;
            if (rch < heap.Count - 1 && cmp(heap[rch], heap[lch]) < 0) lch = rch;
            if (cmp(heap[lch], x) >= 0)
                break;
            heap[pos] = heap[lch];
            pos = lch;
        }

        heap[pos] = x;
        heap.RemoveAt(heap.Count - 1);
        return ret;
    }

    /// <summary>
    ///  優先度付きキューに含まれる最も価値が低い要素を削除せずに返します．
    /// </summary>
    /// <returns>優先度付きキューに含まれる最も価値が低い要素．</returns>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public T Peek()
    {
        return heap[0];
    }

    /// <summary>
    /// 優先度付きキュー内の要素の数を取得します．
    /// </summary>
    /// <returns>優先度付キュー内にある要素の数</returns>
    /// <remarks>最悪計算量 O(1) で実行されます．</remarks>
    public int Count
    {
        get { return heap.Count; }
    }

    /// <summary>
    /// 優先度付きキュー内に要素が存在するかどうかを O(1) で判定します．
    /// </summary>
    /// <returns>優先度付キュー内にある要素が存在するならば true，そうでなければ　false．</returns>
    /// <remarks>この操作は O(1) で実行されます．</remarks>
    public bool Any()
    {
        return heap.Count > 0;
    }

    /// <summary>
    /// 優先度付きキューに含まれる要素を昇順に並べて返します．
    /// </summary>
    /// <remarks>この操作は計算量 O(N log N)で実行されます．</remarks>
    public T[] Items
    {
        get
        {
            var ret = heap.ToArray();
            Array.Sort(ret, cmp);
            return ret;
        }
    }
}

