    public class YoungMaid
    {
        private int[] data;
        private int N;

        public YoungMaid(int[] data, int N)
        {
            this.N = N;
            this.data = data;
        }

        public void Run()
        {
            var minPerm = GetMinPerm();
            for (int i = 0; i < N - 1; i++)
            {
                Console.Write(minPerm[i].ToString() + ' ');
            }
            Console.WriteLine(minPerm[N - 1]);
        }

        private List<int> GetMinPerm()
        {
            var minPerm = new List<int>();
            while (data.Max() != 0)
            {
                minPerm.AddRange(GetMin2Nums());
            }

            return minPerm;
        }

        private int[] GetMin2Nums()
        {
            int minEvenNumed;
            int minOddNumed;
            MinInts(ref data, out minEvenNumed, out minOddNumed);

            var ret = new int[2] { minEvenNumed, minOddNumed };
            return ret;
        }

        private void MinInts(ref int[] data, out int minEvenNumed, out int minOddNumed)
        {
            int firstInd = 0;
            for(int i=0; i< N; i++)
            {
                if(data[i] != 0)
                {
                    firstInd = i;
                    break;
                }
            }
            minEvenNumed = data[firstInd];

            int minInd = firstInd;
            for (int i = Get2ndNextEx0Index(data, firstInd); i < N; i = Get2ndNextEx0Index(data, i))
            {
                if (data[i] < minEvenNumed)
                {
                    minInd = i;
                    minEvenNumed = data[minInd];
                }
            }
            data[minInd] = 0;

            minOddNumed = data[minInd + 1];
            minInd = minInd + 1;

            var stopLength = minInd;
            while (stopLength < N && data[stopLength] != 0)
            {
                stopLength++;
            }

            for (int i = Get2ndNextEx0Index(data, minInd) ; i < stopLength ; i = Get2ndNextEx0Index(data, i))
            {
                if (data[i] < minOddNumed)
                {
                    minOddNumed = data[i];
                    minInd = i;
                }
                if (data[i] == 0)
                    break;
            }

            data[minInd] = 0;
        }

        public int Get2ndNextEx0Index(int[] data, int ind)
        {


            int retInd = ind + 1;
            int i = 0;
            while(true)
            {
                if (retInd > N - 1)
                    return N;
                if (data[retInd] != 0)
                {
                    i++;
                    if (i == 2)
                        break;
                    retInd++;
                }
                else
                    retInd++;
            }
            return retInd;
        }

    }
}

