        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        int[] p = new int[N];
        string[] str = Console.ReadLine().Split(' ');
        int[] next = new int[N];
        int[] before = new int[N];
        for(int i=0;i<N;i++){
            p[i] = int.Parse(str[i]);
            next[i] = i+1;
            before[i] = i-1;
        }
        Heap H = new Heap(N);
        for(int i=0;i<N-1;i++){
            H.push(new Data(i,i+1,p[i],p[i+1]));
        }
        int[] q = new int[N];
        int pointer = N-2;
        bool[] finished = new bool[N];
        while(pointer >= 0){
            Data D = H.pop();
            if(!finished[D.f] && !finished[D.s]){
                finished[D.f] = true;
                finished[D.s] = true;
                q[pointer] = D.fv;
                q[pointer+1] = D.sv;
                pointer -= 2;
                int be = before[D.f];
                int af = next[D.s];
                if(be != -1){
                    next[be] = af;
                }
                if(af != N){
                    before[af] = be;
                }
                if(af != N && be != -1){
                    H.push(new Data(be,af,p[be],p[af]));
                }
            }
        }
        for(int i=0;i<N;i++){
            sb.Append(q[i]);
            if(i == N-1){
                sb.Append("\n");
            }
            else{
                sb.Append(" ");
            }
        }
    }
