class Heap{
    public int size;
    Data[] obj;

    public Heap(int maxsize){
        size = 0;
        obj = new Data[maxsize];
    }
    public bool Compare(Data a,Data b){
        return Math.Min(a.fv,a.sv) > Math.Min(b.fv,b.sv) || (Math.Min(a.fv,a.sv) == Math.Min(b.fv,b.sv) && Math.Max(a.fv,a.sv) >= Math.Max(b.fv,b.sv));
    }
    public void push(Data a){
        int i = size;
        size++;
        while(i > 0){
            int p = (i - 1)/2;
            if(Compare(obj[p],a)){
                obj[i] = a;
                break;
            }
            obj[i] = obj[p];
            i = p;
        }
        if(i == 0){
            obj[0] = a;
        }
    }
    public Data pop(){
        Data t = obj[0];
        int i = 0;
        size--;
        while(2*i+1 < size){
            int p = 2*i+1;
            if(p+1 < size && Compare(obj[p+1],obj[p])){
                p++;
            }
            if(Compare(obj[p],obj[size])){
                obj[i] = obj[p];
                i = p;
            }
            else{
                obj[i] = obj[size];
                break;
            }
        }
        if(2*i+1 >= size){
            obj[i] = obj[size];
        }
        return t;
    }
}

