                    var q = bit.LowerBound(bit[p + 1] + 1);
                    var mi = (seg[j ^ 1].Query(p, q));
                    if (mi > n) continue;
                    ok = true;
                    seg[j ^ 1].Update(pos[mi], int.MaxValue);
                    s[j].Remove(min);
                    s[j ^ 1].Remove((int)mi);
                    bit.Add(pos[min] + 1, 1);
                    bit.Add(pos[mi] + 1, 1);
                    ans.Add(min + 1);
                    ans.Add((int)mi + 1);
                    break;
                }
                if (ok) continue;
                for (int j = 0; j < 2; j++)
                {
                    if (Ma != s[j].Min) continue;
                    var min = s[j].Min;
                    var p = pos[min];
                    var q = bit.LowerBound(bit[p + 1] + 1);
                    var mi = (seg[j ^ 1].Query(p, q));
                    if (mi > n) continue;
                    ok = true;
                    seg[j ^ 1].Update(pos[mi], int.MaxValue);
                    s[j].Remove(min);
                    s[j ^ 1].Remove((int)mi);
                    bit.Add(pos[min] + 1, 1);
                    bit.Add(pos[mi] + 1, 1);
                    ans.Add(min + 1);
                    ans.Add((int)mi + 1);
                    break;
                }
            }


            IO.Printer.Out.WriteLine(ans.AsJoinedString());
        }
        //*
        int ri => sc.Integer();
        long rl => sc.Long();
        double rd => sc.Double();
        string rs => sc.Scan();
        char rc => sc.Char();

        [System.Diagnostics.Conditional("DEBUG")]
        void put(params object[] a) => Debug.WriteLine(string.Join(" ", a));

        //*/
        public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());

        static T[] Enumerate<T>(int n, Func<int, T> f)
        {
            var a = new T[n];
            for (int i = 0; i < n; ++i) a[i] = f(i);
            return a;
        }
        static void Swap<T>(ref T a, ref T b)
        {
            var tmp = a;
            a = b;
            b = tmp;
        }
    }
