public struct Range
{
    public int Left, Right;

    public S X, Y;

    public Range(int l, int r, S x, S y)
    {
        Left = l;
        Right = r;
        X = x;
        Y = y;
    }
}

public struct S
{
    public int N;
    public int Index;

    public S(int n, int i)
    {
        N = n;
        Index = i;
    }
}

public class Program
{
    private int N;
    private int[] P;

    // 奇数　偶数
    private SegTree<S> Odd, Even;

    private PriorityQueue<Range> PQ;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        P = sc.IntArray();

        Odd = new SegTree<S>(N, (a, b) => a.N.CompareTo(b.N), new S(int.MaxValue, int.MaxValue));
        Even = new SegTree<S>(N, (a, b) => a.N.CompareTo(b.N), new S(int.MaxValue, int.MaxValue));

        for (int i = 0; i < N; i++)
        {
            if (i % 2 == 0)
            {
                Even[i] = new S(P[i], i);
            }
            else
            {
                Odd[i] = new S(P[i], i);
            }
        }

        PQ = new PriorityQueue<Range>((a, b) => a.X.N.CompareTo(b.X.N));

        Range all;
        all.Left = 0;
        all.Right = N;
        var e = Even.Query(0, N);

        all.X = e;
        var o = Odd.Query(e.Index + 1, N);
        all.Y = o;
        PQ.Enqueue(all);

        List<int> ans = new List<int>();
        while (PQ.Count > 0)
        {
            var r = PQ.Dequeue();
            ans.Add(r.X.N);
            ans.Add(r.Y.N);

            // [r.Left r.X.Index) [r.X.Index + 1, r.Y.Index) [r.Y.Index+1, r.Right)
            if (r.X.Index  - r.Left > 0)
            {
                Range a = CalcXY(r.Left, r.X.Index);
                PQ.Enqueue(a);
            }

            if (r.Y.Index - (r.X.Index + 1) > 0)
            {
                Range b = CalcXY(r.X.Index + 1, r.Y.Index );
                PQ.Enqueue(b);
            }

            if (r.Right - (r.Y.Index + 1) > 0)
            {
                Range c = CalcXY(r.Y.Index + 1, r.Right);
                PQ.Enqueue(c);
            }
        }

        Console.WriteLine(string.Join(" ",ans));
    }

    public Range CalcXY(int left, int right)
    {
        Range res;
        res.Left = left;
        res.Right = right;
        if (left % 2 == 0)
        {
            res.X = Even.Query(left, right);
            res.Y = Odd.Query(res.X.Index, right);
        }
        else
        {
            res.X = Odd.Query(left, right);
            res.Y = Even.Query(res.X.Index, right);
        }

        return res;
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

