public class RmQ: SegmentTree<long, MinData>
{
    public RmQ(int size) : base(size) { }
}
public struct MinData: IData<long>
{
    public long Identity { get { return long.MaxValue; } }
    public long Merge(long l, long r) { return Math.Min(l, r); }
}
