		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size => 1;
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		struct P : IComparable<P>
		{
			public int a, b;
			public P(int x, int y) { a = x; b = y; }
			public int CompareTo(P other) => a.CompareTo(other.a);
			public override string ToString() => $"{a} {b}";
		}
		int N;
		int[] a;
		void Read()
		{
			N = sc.Int;
			a = sc.ReadMany<int>();
		}
		void SolveOne()
		{
			for (var i = 0; i < N; i++) a[i]--;
			//var ans = Calc2(0, N);
			//pr.WriteLine(string.Join(" ", ans));
			var ans = Calc();
			pr.WriteLine(string.Join(" ", ans));
		}
		List<P> Calc()
		{
			var rev = new int[N];
			for (var i = 0; i < N; i++) rev[a[i]] = i;
			var par = new[] { new RMQ(N), new RMQ(N) };
			for (var i = 0; i < N; i++)
			{
				par[i & 1][i] = a[i];
				par[1 - (i & 1)][i] = Inf;
			}
			var que = new PriorityQueue<int>();
			var dict = new Dictionary<int, P>();
			{ var x = par[0].Min(0, N); dict[x] = new P(0, N); que.Enqueue(x); }
			var ans = new List<P>();
			while (que.Count > 0)
			{
				var x = que.Dequeue();
				var i = rev[x];
				var range = dict[x];
				var flip = range.a & 1;
				var y = par[1 - flip].Min(i + 1, range.b);
				var j = rev[y];
				ans.Add(new P(x + 1, y + 1));
				if (range.a < i)
				{
					var z = par[flip].Min(range.a, i);
					dict[z] = new P(range.a, i);
					que.Enqueue(z);
				}
				if (i + 1 < j)
				{
					var z = par[1 - flip].Min(i + 1, j);
					dict[z] = new P(i + 1, j);
					que.Enqueue(z);
				}
				if (j + 1 < range.b)
				{
					var z = par[flip].Min(j + 1, range.b);
					dict[z] = new P(j + 1, range.b);
					que.Enqueue(z);
				}
			}
			return ans;
		}
		List<P> Calc2(int l, int r)
		{
			if (r - l == 0) return new List<P>();
			var m = l;
			for (var i = l + 2; i < r; i += 2) if (a[m] > a[i]) m = i;
			var n = m + 1;
			for (var i = m + 3; i < r; i += 2) if (a[n] > a[i]) n = i;
			var ans = new List<P> { new P(a[m] + 1, a[n] + 1) };
			ans.Capacity = (r - l) / 2;
			var tmp = new[] { Calc2(l, m), Calc2(m + 1, n), Calc2(n + 1, r) };
			var j = new[] { 0, 0, 0 };
			while (true)
			{
				var x = -1;
				for (var i = 0; i < 3; i++) if (j[i] < tmp[i].Count)
					{
						if (x < 0) x = i;
						else if (tmp[x][j[x]].a > tmp[i][j[i]].a) x = i;
					}
				if (x < 0) return ans;
				ans.Add(tmp[x][j[x]++]);
			}
		}
		int[] SuffixArray(string S)
		{
			var N = S.Length;
			var sa = new int[N + 1];
			var r = new int[N + 1];
			for (var i = 0; i <= N; i++)
			{
				sa[i] = i;
				r[i] = i < N ? S[i] : -1;
			}
			var k = 1;
			Comparison<int> comp = (i, j) =>
			  {
				  if (r[i] != r[j]) return r[i] - r[j];
				  var a = i + k <= N ? r[i + k] : -1;
				  var b = j + k <= N ? r[j + k] : -1;
				  return a - b;
			  };
			for (; k <= N; k *= 2)
			{
				Array.Sort(sa, comp);
				var tmp = new int[N + 1];
				for (var i = 1; i <= N; i++) tmp[sa[i]] = tmp[sa[i - 1]] + (comp(sa[i - 1], sa[i]) < 0 ? 1 : 0);
				r = tmp;
			}
			return sa;
		}
	}
	class RangeSegmentTree
	{
		int N2;
		int[] seg, unif;
		public RangeSegmentTree(int N)
		{
			N2 = 1;
			while (N2 < N) N2 <<= 1;
			seg = new int[2 * N2 - 1];
			unif = new int[2 * N2 - 1];
		}
		void LazyEvaluate(int node)
		{
			if (unif[node] == 0) return;
			seg[node] += unif[node];
			if (node < N2 - 1)
			{
				unif[2 * node + 1] += unif[node];
				unif[2 * node + 2] += unif[node];
			}
			unif[node] = 0;
		}
		void Update(int node) => seg[node] = seg[2 * node + 1] + seg[2 * node + 2];
		public void AddRange(int from, int to, int value) => AddRange(from, to, value, 0, 0, N2);
		void AddRange(int from, int to, int value, int node, int l, int r)
		{
			if (from <= l && r <= to) unif[node] += value;
			else if (l < to && from < r)
			{
				AddRange(from, to, value, 2 * node + 1, l, (l + r) >> 1);
				AddRange(from, to, value, 2 * node + 2, (l + r) >> 1, r);
				Update(node);
			}
			LazyEvaluate(node);
		}
		public int this[int n] { get { return Sum(n, n + 1); } set { AddRange(n, n + 1, value - this[n]); } }
		public int Sum(int from, int to) => Sum(from, to, 0, 0, N2);
		int Sum(int from, int to, int node, int l, int r)
		{
			LazyEvaluate(node);
			if (to <= l || r <= from) return 0;
			else if (from <= l && r <= to) return seg[node];
			else return Sum(from, to, 2 * node + 1, l, (l + r) >> 1) + Sum(from, to, 2 * node + 2, (l + r) >> 1, r);
		}
	}
