            if (ymini - xmini > 1)
            {
                var tl = xmini + 1;
                var tr = ymini - 1;
                var min = xy.Even ? oddst[tl, tr] : evenst[tl, tr];

                pq.Enqueue(new Data(tl, tr, min, !xy.Even));
            }

            if (ymini < xy.Y)
            {
                var tl = ymini + 1;
                var tr = xy.Y;
                var min = xy.Even ? evenst[tl, tr] : oddst[tl, tr];

                pq.Enqueue(new Data(tl, tr, min, xy.Even));
            }

            Write(xmin + " " + ymin + " ");
        }
    }
}

