struct Data
{
    public int X, Y, Min;

    public Data(int x, int y, int min)
    {
        X = x; Y = y; Min = min;
    }
}

static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static Dictionary<int, int> pidxes = new Dictionary<int, int>();
    static SegmentTree<int> evenst, oddst;
    static PriorityQueue<Data> pq
        = new PriorityQueue<Data>((x, y) => x.Min.CompareTo(y.Min));

    static void Solve(IO io)
    {
        var n = io.I;
        var p = io.Is(n);

        for (var i = 0; i < n; i++) pidxes.Add(p[i], i);

        var evenp = p.Select((x, i) => i % 2 == 0 ? x : int.MaxValue).ToArray();
        var oddp = p.Select((x, i) => i % 2 != 0 ? x : int.MaxValue).ToArray();

        evenst = new SegmentTree<int>(evenp, int.MaxValue, Min);
        oddst = new SegmentTree<int>(oddp, int.MaxValue, Min);

        var xmin = int.MaxValue;
        var xmini = 0;
        var ymin = int.MaxValue;
        var ymini = n - 1;
        var even = true;

        pq.Enqueue(new Data(xmini, ymini, evenst[xmini, ymini]));

        while (pq.Any())
        {
            var xy = pq.Dequeue();

            xmin = even ? evenst[xy.X, xy.Y] : oddst[xy.X, xy.Y];
            xmini = pidxes[xmin];
            ymin = even ? oddst[xy.X, xy.Y] : evenst[xy.X, xy.Y];
            ymini = pidxes[ymin];

            if (xmini > xy.X)
            {
                var tl = xy.X;
                var tr = xmini - 1;
                var min = even ? evenst[tl, tr] : oddst[tl, tr];

                pq.Enqueue(new Data(tl, tr, min));
            }

            if (ymini - xmini > 1)
            {
                var tl = xmini + 1;
                var tr = ymini - 1;
                var min = even ? oddst[tl, tr] : evenst[tl, tr];
                even = !even;

                pq.Enqueue(new Data(tl, tr, min));
            }

            if (ymini > xy.Y)
            {
                var tl = ymini + 1;
                var tr = xy.Y;
                var min = even ? evenst[tl, tr] : oddst[tl, tr];

                pq.Enqueue(new Data(tl, tr, min));
            }

            Write(xmin + " " + ymin + " ");
        }
    }
}

