  for i:=0;i<n; {
    i0 := heap.Pop(&pq).(*Item)
    p0 := i0.val
    p1 := evn.Query(pos[p0]+1,i0.r)
    if (pos[p0]+1)%2 == 1 { p1 = odd.Query(pos[p0]+1,i0.r) }
    ans[i] = p0
    ans[i+1] = p1
    i += 2
    i1 := Item{odd.Query(i0.l,pos[p0]),i0.l,pos[p0]}
    if i0.l%2 == 0 { i1 = Item{evn.Query(i0.l,pos[p0]),i0.l,pos[p0]} }
    i2 := Item{odd.Query(pos[p0]+1,pos[p1]),pos[p0]+1,pos[p1]}
    if (pos[p0]+1)%2 == 0 { i2 = Item{evn.Query(pos[p0]+1,pos[p1]),pos[p0]+1,pos[p1]} }
    i3 := Item{odd.Query(pos[p1]+1,i0.r),pos[p1]+1,i0.r}
    if (pos[p1]+1)%2 == 0 { i3 = Item{evn.Query(pos[p1]+1,i0.r),pos[p1]+1,i0.r} }
    heap.Push(&pq,&i1)
    heap.Push(&pq,&i2)
    heap.Push(&pq,&i3)
  }
