  *pq = old[0:n-1]
  return item
}

type SegmentTree struct { n,p int;c []int }
func NewSegmentTree(n int) SegmentTree {
  p := 1
  for p < n { p *= 2 }
  c := make([]int,2*p-1)
  for i:=0;i<2*p-1;i++ { c[i] = INF }
  return SegmentTree{n,p,c}
}
func op(a,b int) int {
  if a < b { return a }
  return b
}
func(st SegmentTree) Update(i int,c int) {
  i += st.p-1
  st.c[i] = c
  for i > 0 {
    i = (i-1)/2
    st.c[i] = op(st.c[2*i+1],st.c[2*i+2])
  }
}
func(st SegmentTree) Query(l,r int) int {
  l += st.p-1
  r += st.p-1
  ret := INF
  for l < r {
    if l%2 == 0 { ret = op(ret,st.c[l]) }
    if r%2 == 0 { ret = op(ret,st.c[r-1]) }
    l = l/2
    r = (r-1)/2
  }
  return ret
}

