		ans[i] = node.v
		i++
		if r.r-r.l < 2 {
			continue
		}
		if r.l%2 == 0 {
			heap.Push(&rr, &Range{
				l:    r.l,
				r:    r.node.i,
				node: even.find(r.l/2, (r.node.i+1)/2, 0, 0, len(even)/2+1),
			})
			heap.Push(&rr, &Range{
				l:    r.node.i + 1,
				r:    node.i,
				node: odd.find(r.node.i/2, node.i/2, 0, 0, len(odd)/2+1),
