			node: odd.find((r.l-1)/2, r.node.i/2, 0, 0, len(odd)/2+1),
		})
		heap.Push(&rr, &Range{
			l:    r.node.i + 1,
			r:    node.i,
			node: even.find((r.node.i+1)/2, (node.i+1)/2, 0, 0, len(even)/2+1),
		})
		heap.Push(&rr, &Range{
			l:    node.i + 1,
			r:    r.r,
			node: odd.find(node.i/2, r.r/2, 0, 0, len(odd)/2+1),
		})
	}

	for i := 0; i < n; i++ {
