// Node ...
type Node struct {
	i, v int
}

// Nodes ...
type Nodes []*Node

func (nodes Nodes) find(l, r, k, s, t int) *Node {
	if l <= s && t <= r {
		return nodes[k]
	}
	if t <= l || r <= s {
		return &Node{
			i: -1,
			v: 1 << 30,
		}
	}
	left := nodes.find(l, r, 2*k+1, s, (s+t)/2)
	right := nodes.find(l, r, 2*k+2, (s+t)/2, t)
	if left.v < right.v {
		return left
	}
	return right
}

// P ...
type P []int

func (p P) find(l, r int) int {
	min := p[l]
	ans := l
	for i := l; i < r; i += 2 {
		if p[i] < min {
			min = p[i]
			ans = l
		}
	}
	return ans
}

func (p P) getSegTree(start int) Nodes {
	size := 1
	h := 1
	n := len(p)
	max := n >> 1
	if start == 1 {
		max = n - max
	}
	for size < max {
		size *= 2
		h++
	}
	seg := make(Nodes, 2<<uint(h)-1)
	for i := 0; i < 2<<uint(h)-1; i++ {
		seg[i] = &Node{
			i: -1,
			v: 1 << 30,
		}
	}
	leaf := 2<<uint(h-1) - 1
	for i := start; i < n; i += 2 {
		seg[leaf] = &Node{
			i: i,
			v: p[i],
		}
		for ii := leaf; ii > 0; ii = (ii - 1) >> 1 {
			if seg[(ii-1)>>1].v > p[i] {
				seg[(ii-1)>>1].v = p[i]
				seg[(ii-1)>>1].i = i
			}
		}
		leaf++
	}

	return seg
}

// Range ...
type Range struct {
	node *Node
	l, r int
}

// Ranges ...
type Ranges []*Range

func (a Ranges) Len() int           { return len(a) }
func (a Ranges) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a Ranges) Less(i, j int) bool { return a[i].node.v < a[j].node.v }

// Push ...
func (a *Ranges) Push(x interface{}) {
	*a = append(*a, x.(*Range))
}

// Pop ...
func (a *Ranges) Pop() interface{} {
	old := *a
	n := len(old)
	x := old[n-1]
	*a = old[0 : n-1]
	return x
}

