void main()
{
  int n; readV(n);
  int[] p; readA(n, p);

  auto inv = new int[](n+1);
  foreach (i; 0..n) inv[p[i]] = i;

  auto st = new segT[](2);
  foreach (i; 0..2) st[i] = new segT(n, n+1);
  foreach (i; 0..n) st[i%2][i] = p[i];

  pair[] calc(int s, int t)
  {
    if (s == t) return [];
    auto p1 = st[s%2][s..t-1];
    auto p1i = inv[p1];
    auto p2 = st[(s+1)%2][s+1..t];
    auto p2i = inv[p2];

    auto r = calc(s, p1i) ~ calc(p1i+1, p2i) ~ calc(p2i+1, t);
    r.sort();
    return pair(p1, p2) ~ r;
  }

  auto ans = calc(0, n);
  foreach (i, ai; ans) {
    write(ai.s, " ", ai.t);
    if (i < n/2-1) write(" ");
  }
  writeln;
}

