struct T{P x, y;}

void main() {
    int N = readln.chomp.to!int;
    P[] ps = readln.split.to!(int[]).enumerate.map!(a => P(a.index, a.value)).array;

    auto rmq = RMQ(ps);
    auto rmqOdd = RMQ(ps.filter!"a.i%2!=0".array);
