    auto list = DList!I(I(0, N));
    auto _list = DList!I();
    auto ans = DList!int();
    auto tree = redBlackTree!(
        (T a, T b) => a.x.v!=b.x.v ? a.x.v<b.x.v : a.y.v<b.y.v,
        false,
        T
    )();
    while(!list.empty) {
        while(!list.empty) {
            I i = list.front;
            list.removeFront;
            i.writeln;

            P p = rmq.query(i.l, i.r);
            if (p.i%2==0) {
                P q1 = (i.l+1)/2 >= (p.i+1)/2 ? initValue : rmqOdd.query((i.l+1)/2, (p.i+1)/2);
                P q2 = (p.i+1)/2 >= (i.r+1)/2 ? initValue : rmqOdd.query((p.i+1)/2, (i.r+1)/2);
                P q = fun(q1, q2);

