    // O(logN)
    T query(size_t a, size_t b) {
        T rec(size_t a, size_t b, size_t k, size_t l, size_t r) {
            if (b<=l || r<=a) return initValue;
            if (a<=l && r<=b) return _data[k];
            T vl = rec(a, b, k*2+1, l, (l+r)/2);
            T vr = rec(a, b, k*2+2, (l+r)/2, r);
