    writefln("%(%s %)", ans);
}

struct SegTree {
    private {
        int N;
        int[] data;
        int[] idx;
        immutable inf = 1001001001;
    }

    this(int n) {
        N = 1; while (N < n) N *= 2;
        data = new int[](2*N - 1);
        idx = new int[](2*N - 1);
        data[] = inf;
        idx[] = -1;
        idx[N - 1 .. 2*N - 1] = iota(N).array();
    }

    void update(int i, int x) {
        i += N - 1;
        data[i] = x;

        while (i > 0) {
            i = (i - 1) / 2;

            if (data[2*i + 1] < data[2*i + 2]) {
                data[i] = data[2*i + 1];
                idx[i] = idx[2*i + 1];
            }
            else {
                data[i] = data[2*i + 2];
                idx[i] = idx[2*i + 2];
            }
        }
    }

    //alias Pair = Tuple!(int, "v", int, "i");

    Pair getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = N;
        if (b <= l || r <= a) return Pair(inf, -1);
        if (a <= l && r <= b) return Pair(data[k], idx[k]);

        Pair v1 = getmin(a, b, 2*k + 1, l, l + (r - l) / 2);
        Pair v2 = getmin(a, b, 2*k + 2, l + (r - l) / 2, r);

        if (v1.v < v2.v) {
            return v1;
        }
        else {
            return v2;
        }
    }
}



