void main()
{
  int n; readV(n);
  int[] p; readA(n, p);

  auto inv = new int[](n+1);
  foreach (i; 0..n) inv[p[i]] = i;

  auto st = new segT[](2);
  foreach (i; 0..2) st[i] = new segT(n, n+1);
  foreach (i; 0..n) st[i%2][i] = p[i];

  int[] calc(int s, int t)
  {
    if (s == t) return [];
    auto p1 = st[s%2][s..t-1];
    auto p1i = inv[p1];
    auto p2 = st[(s+1)%2][s+1..t];
    auto p2i = inv[p2];

    auto r = new int[](t-s);
    r[0..2] = [p1, p2];

    auto r1 = calc(s, p1i), r2 = calc(p1i+1, p2i), r3 = calc(p2i+1, t);
    r1 ~= n+1; r2 ~= n+1; r3 ~= n+1;
    auto i1 = 0, i2 = 0, i3 = 0;

    while (i1+i2+i3+2 < t-s) {
      auto i = i1+i2+i3+2;
      if (r1[i1] < r2[i2] && r1[i1] < r3[i3]) {
        r[i..i+2] = r1[i1..i1+2];
        i1 += 2;
      } else if (r2[i2] < r1[i1] && r2[i2] < r3[i3]) {
        r[i..i+2] = r2[i2..i2+2];
        i2 += 2;
      } else {
        r[i..i+2] = r3[i3..i3+2];
        i3 += 2;
      }
    }

    return r;
  }

  auto ans = calc(0, n);
  foreach (i, ai; ans) {
    write(ai);
    if (i < n-1) write(" ");
  }
  writeln;
}

class SegmentTree(T, alias pred = "a + b")
{
  import core.bitop, std.functional;
  alias predFun = binaryFun!pred;

  const size_t n, an;
  T[] buf;
  T unit;

  this(size_t n, T unit = T.init)
  {
    this.n = n;
    this.unit = unit;
    an = n == 1 ? 1 : (1 << ((n-1).bsr + 1));
    buf = new T[](an*2);
    if (T.init != unit) buf[] = unit;
  }

  this(T[] init, T unit = T.init)
  {
    this(init.length, unit);
    buf[an..an+n][] = init[];
    foreach_reverse (i; 1..an)
      buf[i] = predFun(buf[i*2], buf[i*2+1]);
  }

  void opIndexAssign(T val, size_t i)
  {
    buf[i += an] = val;
    while (i /= 2)
      buf[i] = predFun(buf[i*2], buf[i*2+1]);
  }

  pure T opSlice(size_t l, size_t r)
  {
    l += an; r += an;
    T r1 = unit, r2 = unit;
    while (l != r) {
      if (l % 2) r1 = predFun(r1, buf[l++]);
      if (r % 2) r2 = predFun(buf[--r], r2);
      l /= 2; r /= 2;
    }
    return predFun(r1, r2);
  }

  pure T opIndex(size_t i) { return buf[i+an]; }
  pure size_t opDollar() { return n; }
}

