	long[] ps2 = ps[i0 .. $];
	long[] qs1 = (ps1.length > 2)? [ps1[0], ps1[$ - 1]] ~ solve(ps1[1 .. $ - 1]): ps1;
	long[] qs2 = (ps2.length > 2)? [ps2[0], ps2[$ - 1]] ~ solve(ps2[1 .. $ - 1]): ps2;
	return merge(qs1, qs2);
	}

long[] mw;
long[] merge(long[] ps1, long[] ps2){
	if(!mw.length) mw = new long[](200000);
	int i1 = 0, i2 = 0;
	int j = 0;
	while(i1 < ps1.length || i2 < ps2.length){
		if(i1 >= ps1.length) mw[j] = ps2[i2], mw[j + 1] = ps2[i2 + 1], j += 2, i2 += 2;
		else if(i2 >= ps2.length) mw[j] = ps1[i1], mw[j + 1] = ps1[i1 + 1], j += 2, i1 += 2;
		else if(ps1[i1] < ps2[i2]) mw[j] = ps1[i1], mw[j + 1] = ps1[i1 + 1], j += 2, i1 += 2;
		else mw[j] = ps2[i2], mw[j + 1] = ps2[i2 + 1], j += 2, i2 += 2;
		}
	return mw[0 .. ps1.length + ps2.length];
	}

