const int SZ = 1 << 18;
const int INF = TEN(9);

struct segtree {
	vector<pii> dat;

	const pii inf = mp(INF, INF);

	void init() {
		dat.resize(SZ * 2);
		rep(i, SZ * 2) dat[i] = inf;
	}

	void update(int pos, int x) {
		dat[pos + SZ - 1] = mp(x, pos);
		pos += SZ - 1;

		while (pos > 0) {
			pos = (pos - 1) / 2;
			dat[pos] = min(dat[pos * 2 + 1], dat[pos * 2 + 2]);
		}
	}

	pii get(int a, int b, int k = 0, int l = 0, int r = SZ) {
		if (b <= l || r <= a) return inf;
		if (a <= l && r <= b) return dat[k];
		return min(get(a, b, k * 2 + 1, l, (l + r) / 2), get(a, b, k * 2 + 2, (l + r) / 2, r));
	}
} seg[2];

int main() {
	seg[0].init();
	seg[1].init();

	int N; cin >> N;
	V<int> p(N);

	rep(i, N) {
		cin >> p[i];
		seg[i % 2].update(i, p[i]);
	}

	using Data = pair<pii, pii>;
	priority_queue<Data, vector<Data>, greater<Data>> que;

	auto add = [&](int l, int r) {
		auto p = seg[l%2].get(l, r);
		if (l >= r || p.fi == INF) return ;
		que.push(mp(seg[l%2].get(l, r), mp(l, r)));
	};

	add(0, N);
	V<int> ans;

	while (!que.empty()) {
		auto p = que.top(); que.pop();
		int val = p.fi.fi, pos = p.fi.se; 
		int l = p.se.fi, r = p.se.se;

		auto nx = seg[1-l%2].get(pos + 1, r);

		ans.pb(val);
		ans.pb(nx.fi);
		add(l, pos);
		add(pos + 1, nx.se);
		add(nx.se + 1, r);
	}

	rep(i, N) printf("%d%c", ans[i], i == N - 1 ? '\n' : ' ');

	return 0;
}

