class MinSegTree:

  def __init__(self, inf, data=None, size=None):
    if data is None and size is None:
      raise Exception('data and size both cannot be None simultaneously')
    self.size = len(data) if size is None else size
    self.depth = (self.size-1).bit_length()
    self.capacity = 1 << self.depth
    self.inf = inf
    if data is None:
      self.data = [self.inf]*(2*self.capacity)
    else:
      self.data = [self.inf]*self.capacity + data + [self.inf]*(self.capacity-len(data))
      for d in reversed(range(self.depth)):
        t = 1 << d
        for i in range(t, 2*t):
          self.data[i] = min(self.data[2*i],self.data[2*i+1])

  def _min_interval(self, a, b):
    result = self.inf
    a += self.capacity
    b += self.capacity
    while a < b:
      if a & 1:
        result = min(result,self.data[a])
        a += 1
      if b & 1:
        b -= 1
        result = min(result,self.data[b])
      a >>= 1
      b >>= 1
    return result

  def _set_val(self, a, val):
    a += self.capacity
    while self.data[a] != val and a > 0:
      self.data[a] = val
      val = min(val,self.data[a^1])
      a >>= 1

  def __getitem__(self, i):
    if isinstance(i, slice):
      return self._min_interval(
                  0 if i.start is None else i.start,
                  self.size if i.stop is None else i.stop)
    elif isinstance(i, int):
      return self.data[i+self.capacity]

  def __setitem__(self, i, x):
    self._set_val(i,x)

  def __iter__(self):
    return iter(self.data[self.capacity:])


