import sys

class SegmentTree:
    INT_MAX = sys.maxsize

    def __init__(self, origData):
        self.origData = list(origData)
        n = len(self.origData)
        self.N = 1
        while self.N < n:
            self.N *= 2
        self.tree = [(SegmentTree.INT_MAX, 0)] * (self.N * 2 - 1)
        self.build()

    def build(self):
        # O(N)
        for i in range(len(self.origData)):
            self.update(i, self.origData[i])

    def update(self, i, x):
        # update value of index i to x : O(logN)
        idx = i
        i = self.N + i - 1;
        self.tree[i] = (x[0], x[1]);
        while i > 0:
            i = (i - 1) // 2
            self.tree[i] = self.merge(self.tree[i * 2 + 1], self.tree[i * 2 + 2])

    def query(self, start, end):
        # O(logN)
        return self.query_d(start, end, 0, 0, self.N)

    def query_d(self, a, b, k, l, r):
        if r <= a or b <= l:
            return (SegmentTree.INT_MAX, 0)
        if a <= l and r <= b:
            return self.tree[k]
        else:
            lv = self.query_d(a, b, 2 * k + 1, l, (l + r) // 2)  # to left side child node
            rb = self.query_d(a, b, 2 * k + 2, (l + r) // 2, r)  # to right side child node
            return self.merge(lv, rb)

    def merge(self, l, r):
        if l[0] <= r[0]:
            return l
        else:
            return r


