import heapq

INT_MAX = 10 ** 9

class SegTreeX:

    def __init__(self, n):
        k = 1
        while k < n:
            k *= 2

        self.n = n = k
        self.dat = [INT_MAX] * (n * 2)
        self.pos = [i - n + 1 for i in range(n * 2)]


    def update(self, i, x):
        i += self.n - 1
        self.dat[i] = x
        while 0 < i:
            i = (i - 1) // 2
            d1 = self.dat[i * 2 + 1]
            d2 = self.dat[i * 2 + 2]
            if d1 < d2:
                self.dat[i] = d1
                self.pos[i] = self.pos[i * 2 + 1]
            else:
                self.dat[i] = d2
                self.pos[i] = self.pos[i * 2 + 2]


    def query(self, a, b, k = 0, l = 0, r = -1):
        if r < 0:
            r = self.n
        if r <= a or b <= l:
            return INT_MAX, -1
        if a <= l and r <= b:
            return self.dat[k], self.pos[k]
        else:
            vl, pl = self.query(a, b, k * 2 + 1, l, (l + r) // 2)
            vr, pr = self.query(a, b, k * 2 + 2, (l + r) // 2, r)
            if vl < vr:
                return vl, pl
            else:
                return vr, pr


def solve(n, p):

    seg = [SegTreeX(n) for _ in range(2)]
    for i in range(0, n, 2):
        seg[0].update(i, p[i])
    for i in range(1, n, 2):
        seg[1].update(i, p[i])

    ans = []
    q = []
    a, i = seg[0].query(0, n)
    b, j = seg[1].query(i, n)
    heapq.heappush(q, (a, b, 0, n, i, j, 0))
    while q:
        a, b, l, r, i, j, f = heapq.heappop(q)
        ans.append(a)
        ans.append(b)
        if l < i - 1:
            al, il = seg[f].query(l, i)
            bl, jl = seg[1 - f].query(il, i)
            heapq.heappush(q, (al, bl, l, i - 1, il, jl, f))
        if i + 1 < j - 1:
            am, im = seg[1 - f].query(i + 1, j)
            bm, jm = seg[f].query(im, j)
            heapq.heappush(q, (am, bm, i + 1, j - 1, im, jm, 1 - f))
        if j + 1 < r - 1:
            ar, ir = seg[f].query(j + 1, r)
            br, jr = seg[1 - f].query(ir, r)
            heapq.heappush(q, (ar, br, j + 1, r, ir, jr, f))

    return ans


def main():
