from collections import deque

class MinSegTree:

  def __init__(self, constant, size):

    self.size = size
    self.depth = (size-1).bit_length()
    self.capacity = 1 << self.depth
    self.data = [constant]*(2*self.capacity)
    self.inf = constant

  def _min_interval(self, a, b):
    result = self.inf
    a += self.capacity
    b += self.capacity
    while a < b:
      if a & 1:
        result = min(result,self.data[a])
        a += 1
      if b & 1:
        b -= 1
        result = min(result,self.data[b])
      a >>= 1
      b >>= 1
    return result

  def _set_val(self, a, val):
    a += self.capacity
    while self.data[a] != val and a > 0:
      self.data[a] = val
      val = min(val,self.data[a^1])
      a >>= 1

  def __getitem__(self, i):
    if isinstance(i, slice):
      return self._min_interval(
                  0 if i.start is None else i.start,
                  self.size if i.stop is None else i.stop)
    elif isinstance(i, int):
      return self.data[i+self.capacity]

  def __setitem__(self, i, x):
    self._set_val(i,x)

  def __iter__(self):
    return iter(self.data[self.capacity:])



