def query(h, p, start, stop):
    if stop - start <= 2:
        return h[(start, stop)]
    else:
        l = 2
        while start + 2 * l < stop:
            l *= 2
        i, u = h[(start, start + l)]
        shift = 0
        if start % 2 != (stop - l) % 2:
            shift = 1
        start0 = stop - l + shift
        stop0 = stop + shift
        j, v = h[(start0, stop0)]
        if u < v:
            return i, u
        return j, v


def solve():
    inf = 10 ** 20
