    h = {}
    for i in range(0, n):
        h[(i, i + 1)] = i, p[i]
        h[(i, i + 2)] = i, p[i]

    l = 2
    while 2 * l <= n:
        for i in range(0, n - 2 * l + 2):
            j, u = h[(i, i + l)]
            k, v = h[(i + l, i + 2 * l)]
            if u < v:
                h[(i, i + 2 * l)] = j, u
            else:
                h[(i, i + 2 * l)] = k, v
        l *= 2

    q = []
    i, u = query(h, p, 0, n)
    j, v = query(h, p, i + 1, n)

    heapq.heappush(q, (u, v, i, j, 0, n))
