            l, y = query(h, p, k + 1, j)
            heapq.heappush(q, (x, y, k, l, i + 1, j))
        if j + 1 < stop:
            k, x = query(h, p, j + 1, stop)
            l, y = query(h, p, k + 1, stop)
            heapq.heappush(q, (x, y, k, l, j + 1, stop))
        res.append((u, v))
    return res


