INT_MAX = 2**31 - 1

class SegmentTree():
    def __init__(self, n_):
        self.n = 1
        while self.n < n_:
            self.n *= 2
        self.dat = [INT_MAX] * (2 * self.n - 1)

    def update(self, k, a):
        k += self.n - 1
        self.dat[k] = a
        while k > 0:
            k = int((k - 1) / 2)
            self.dat[k] = min(self.dat[k * 2 + 1], self.dat[k * 2 + 2])

    def query(self, a, b, k, l, r):
        if (r <= a) or (b <= l):
            return INT_MAX
        if (a <= l) and (r <= b):
            return self.dat[k]
        else:
            vl = self.query(a, b, k * 2 + 1, l, (l + r) / 2)
            vr = self.query(a, b, k * 2 + 2, (l + r) / 2, r)
            return min([vl, vr])

