            SGT_0[k][j] = min(SGT_0[k-1][2*j], SGT_0[k-1][2*j+1])
    else:
        j = i
        SGT_1[0][j] = a
        for k in range(1, K2+1):
            j = j // 2
            SGT_1[k][j] = min(SGT_1[k-1][2*j], SGT_1[k-1][2*j+1])

# query [a, b)
def query_min_0(a, b, k=K2, l=0, r=N2):
    # min in even numbers in [a, b)
    if r <= a or b <= l:
        return INT_MAX
    elif a <= l and r <= b:
        return SGT_0[k][l // (2**k)]
    else:
        vl = query_min_0(a, b, k-1, l, (l+r)//2)
        vr = query_min_0(a, b, k-1, (l+r)//2, r)
        return min(vl, vr)

def query_min_1(a, b, k=K2, l=0, r=N2):
    if r <= a or b <= l:
        return INT_MAX
    elif a <= l and r <= b:
        return SGT_1[k][l // (2**k)]
    else:
        vl = query_min_1(a, b, k-1, l, (l+r)//2)
        vr = query_min_1(a, b, k-1, (l+r)//2, r)
        return min(vl, vr)

