struct SegTree<T, F>
where
    F: Fn(T, T) -> T,
    T: std::clone::Clone + std::marker::Copy,
{
    n: usize,
    dat: Vec<T>,
    init: T,
    functor: F,
}

impl<T, F> SegTree<T, F>
where
    F: Fn(T, T) -> T,
    T: std::clone::Clone + std::marker::Copy,
{
    fn new(n: usize, init: T, f: F) -> SegTree<T, F> {
        let mut m = 1;
        // For simplicity, we use 2 ** n sized SegTree.
        while m < n {
            m *= 2;
        }
        SegTree {
            n: m,
            dat: vec![init; 2 * m - 1],
            init: init,
            functor: f,
        }
    }

    // dat[k] = a;
    fn update(&mut self, k: usize, a: T) {
        let mut k = k;
        k += self.n - 1;
        self.dat[k] = a;
        while k > 0 {
            k = (k - 1) / 2;
            self.dat[k] = (self.functor)(self.dat[k * 2 + 1], self.dat[k * 2 + 2]);
        }
    }

    // [a, b)
    fn query(&self, a: usize, b: usize) -> T {
        self.query_inner(a, b, 0, 0, self.n)
    }

    fn query_inner(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> T {
        if r <= a || b <= l {
            return self.init;
        }
        if a <= l && r <= b {
            return self.dat[k];
        }

        let vl = self.query_inner(a, b, k * 2 + 1, l, (l + r) / 2);
        let vr = self.query_inner(a, b, k * 2 + 2, (l + r) / 2, r);
        (self.functor)(vl, vr)
    }
}

use proconio::input;

fn cal(a: &[u32]) -> Box<dyn Iterator<Item = (u32, u32)>> {
    assert!(a.len() % 2 == 0);
    if a.is_empty() {
        Box::new(Vec::new().into_iter())
    } else {
        let n = a.len();
        let u = (0..n)
            .filter(|&i| i % 2 == 0)
            .min_by_key(|&i| a[i])
            .unwrap();
        let v = (u + 1..n)
            .filter(|&i| i % 2 == 1)
            .min_by_key(|&i| a[i])
            .unwrap();
        Box::new(std::iter::once((a[u], a[v])).chain(itertools::kmerge(vec![
            cal(&a[0..u]),
            cal(&a[u + 1..v]),
            cal(&a[v + 1..n]),
        ])))
    }
}

fn main() {
    input!(n: usize, a: [u32; n]);
    let ans = cal(a.as_slice());
    println!(
        "{}",
        ans.map(|(x, y)| format!("{} {}", x, y))
            .fold(String::new(), |acc, x| if acc.is_empty() {
                x
            } else {
                acc + " " + x.as_ref()
            })
    );
}

