    mod semigroup {
      use std::fmt::Debug;

      pub trait Semigroup {
        type T: Clone + PartialEq + Debug;

        fn append(lhs: &Self::T, rhs: &Self::T) -> Self::T;

        fn append_assign(lhs: &mut Self::T, rhs: &Self::T) {
          *lhs = Self::append(lhs, rhs);
        }
      }
    }

    mod monoid {
      use math::algebra::Semigroup;

      pub trait Monoid: Semigroup {
        fn identity() -> Self::T;
      }
    }

    mod commutative_monoid {
      use math::algebra::Monoid;

      pub trait CommutativeMonoid: Monoid {}
    }

    mod min_monoid {
      use std::cmp::min;
      use std::marker::PhantomData;

      pub struct MinMonoid<T: Ord> {
        _marker: PhantomData<fn() -> T>,
      }

      macro_rules! min_monoid_impl {
        ($($t:ident)+) => {$(
          commutative_monoid_impl! { MinMonoid<$t>, $t, |lhs, rhs| min(*lhs, *rhs), $t::max_value() }
        )+};
      }

      min_monoid_impl! { i32 i64 isize u8 u32 u64 usize }
    }
  }
}

pub mod data_structures {
  pub use self::segment_tree::*;

  mod segment_tree {
    use math::algebra::Monoid;
    use std::iter::FromIterator;
    use std::ops::{Index, Range};

    pub struct SegmentTree<M: Monoid> {
      vec: Vec<M::T>,
      len: usize,
    }

    impl<M: Monoid> SegmentTree<M> {
      pub fn new(size: usize) -> Self {
        let len = size;
        let size = size.checked_next_power_of_two().unwrap();
        SegmentTree {
          vec: vec![M::identity(); size.checked_mul(2).unwrap()],
          len: len,
        }
      }

      pub fn len(&self) -> usize {
        self.len
      }

      fn size(&self) -> usize {
        self.vec.len() / 2
      }

      pub fn get(&mut self, index: usize) -> M::T {
        debug_assert!(index < self.len());
        self[index].clone()
      }

      pub fn set(&mut self, index: usize, x: &M::T) {
        assert!(index < self.len());
        let mut i = index + self.size();
        self.vec[i] = x.clone();
        i /= 2;
        while i > 0 {
          self.vec[i] = M::append(&self.vec[i * 2], &self.vec[i * 2 + 1]);
          i /= 2;
        }
      }

      pub fn concat(&self, range: Range<usize>) -> M::T {
        assert!(range.start <= range.end);
        assert!(range.end <= self.len());
        let mut lacc = M::identity();
        let mut racc = M::identity();
        let mut l = range.start + self.size();
        let mut r = range.end + self.size();
        while l < r {
          if l % 2 != 0 {
            lacc = M::append(&lacc, &self.vec[l]);
            l += 1;
          }
          if r % 2 != 0 {
            r -= 1;
            racc = M::append(&self.vec[r], &racc);
          }
          l /= 2;
          r /= 2;
        }
        M::append(&lacc, &racc)
      }
    }

    impl<M: Monoid> FromIterator<M::T> for SegmentTree<M> {
      fn from_iter<I: IntoIterator<Item = M::T>>(iter: I) -> Self {
        let iter = iter.into_iter();
        match iter.size_hint() {
          (lower_bound, Some(upper_bound)) if lower_bound == upper_bound => Self::from_exact_size_iter(upper_bound, iter),
          _ => {
            let vec = iter.collect::<Vec<_>>();
            Self::from_exact_size_iter(vec.len(), vec)
          }
        }
      }
    }

    impl<M: Monoid> SegmentTree<M> {
      fn from_exact_size_iter<I: IntoIterator<Item = M::T>>(len: usize, iter: I) -> Self {
        let iter = iter.into_iter();
        let size = len.checked_next_power_of_two().unwrap();
        let mut vec = Vec::with_capacity(size.checked_mul(2).unwrap());
        for _ in 0..size {
          vec.push(M::identity());
        }
        vec.extend(iter);
        for _ in 0..size - len {
          vec.push(M::identity());
        }
        for i in (1..size).rev() {
          vec[i] = M::append(&vec[i * 2], &vec[i * 2 + 1]);
        }
        SegmentTree { vec: vec, len: len }
      }
    }

    impl<M: Monoid> Index<usize> for SegmentTree<M> {
      type Output = M::T;

      fn index(&self, index: usize) -> &M::T {
        assert!(index < self.len());
        &self.vec[index + self.size()]
      }
    }
  }
}

pub mod io {
  pub use self::scanner::*;

  mod scanner {
    use std::io::BufRead;
    use std::marker::PhantomData;
    use std::str::{from_utf8, FromStr};

    pub struct Scanner<R> {
      reader: R,
      buffer: Vec<u8>,
      position: usize,
    }

    impl<R: BufRead> Scanner<R> {
      pub fn new(reader: R) -> Self {
        Scanner { reader: reader, buffer: vec![], position: 0 }
      }

      pub fn next<T: Parse>(&mut self) -> Option<T> {
        Parse::parse(self.next_bytes().unwrap_or(&[]))
      }

      pub fn take<T: Parse>(&mut self, n: usize) -> Take<R, T> {
        Take { scanner: self, n: n, _marker: PhantomData }
      }

      pub fn next_bytes(&mut self) -> Option<&[u8]> {
        if self.buffer.is_empty() {
          self.read_line();
        }
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') => self.position += 1,
            Some(&b'\n') => self.read_line(),
            Some(_) => break,
            None => return None,
          }
        }
        let start = self.position;
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') | Some(&b'\n') | None => break,
            Some(_) => self.position += 1,
          }
        }
        Some(&self.buffer[start..self.position])
      }

      fn read_line(&mut self) {
        self.position = 0;
        self.buffer.clear();
        self.reader.read_until(b'\n', &mut self.buffer).unwrap();
      }
    }

    pub struct Take<'a, R: 'a, T> {
      scanner: &'a mut Scanner<R>,
      n: usize,
      _marker: PhantomData<fn() -> T>,
    }

    impl<'a, R: BufRead, T: Parse> Iterator for Take<'a, R, T> {
      type Item = Option<T>;

      fn next(&mut self) -> Option<Self::Item> {
        if self.n > 0 {
          self.n -= 1;
          Some(self.scanner.next())
        } else {
          None
        }
      }

      fn size_hint(&self) -> (usize, Option<usize>) {
        (self.n, Some(self.n))
      }
    }

    impl<'a, R: BufRead, T: Parse> ExactSizeIterator for Take<'a, R, T> {}

    pub trait Parse: Sized {
      fn parse(bytes: &[u8]) -> Option<Self>;
    }

    impl Parse for u8 {
      fn parse(bytes: &[u8]) -> Option<Self> {
        if bytes.len() == 1 {
          Some(*unsafe { bytes.get_unchecked(0) })
        } else {
          None
        }
      }
    }

    macro_rules! parse_impl {
      ($($t:ident)+) => {$(
        impl Parse for $t {
          fn parse(bytes: &[u8]) -> Option<Self> {
            from_utf8(bytes).ok().and_then(|s| $t::from_str(s).ok())
          }
        }
      )+};
    }

    parse_impl! { i32 i64 u32 u64 isize usize String }
  }
}

use self::sparse_table::SparseTable;
use std::cmp::min;
use std::collections::BinaryHeap;

const INF: i64 = 1 << 50;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let odd_a: Vec<_> = a
        .iter()
        .enumerate()
        .map(|(i, &a)| if i % 2 == 1 { (a, i) } else { (INF, 0) })
        .collect();
    let even_a: Vec<_> = a
        .iter()
        .enumerate()
        .map(|(i, &a)| if i % 2 == 0 { (a, i) } else { (INF, 0) })
        .collect();
    let odd = sparse_table::SparseTable::from(&odd_a, (INF, 0), min);
    let even = sparse_table::SparseTable::from(&even_a, (INF, 0), min);

    let mut heap = BinaryHeap::new();
    heap.push((0, 0, n, false));
    let mut ans = vec![];
    while let Some((_, l, r, swap)) = heap.pop() {
        let (odd, even) = if swap { (&even, &odd) } else { (&odd, &even) };
        let (first_min, first_pos) = even.get(l, r);
        let (second_min, second_pos) = odd.get(first_pos, r);
        ans.push(first_min);
        ans.push(second_min);

        if first_pos - l > 0 {
            let t = even.get(l, first_pos).0;
            heap.push((-t, l, first_pos, swap));
            assert_ne!(INF, t);
        }
        if second_pos - (first_pos + 1) > 0 {
            let t = odd.get(first_pos + 1, second_pos).0;
            heap.push((-t, first_pos + 1, second_pos, !swap));
            assert_ne!(INF, t);
        }
        if r - (second_pos + 1) > 0 {
            let t = even.get(second_pos + 1, r).0;
            heap.push((-t, second_pos + 1, r, swap));
            assert_ne!(INF, t);
        }
    }

    for i in 0..n {
        if i > 0 {
            sc.write(" ");
        }
        sc.write(ans[i]);
    }
    sc.write("\n");
}

pub mod sparse_table {

    pub struct SparseTable<T, F> {
        data: Vec<Vec<T>>,
        op: F,
    }

    impl<T, F> SparseTable<T, F>
    where
        T: Copy,
        F: Fn(T, T) -> T,
    {
        pub fn from(v: &[T], init: T, op: F) -> Self {
            let size = v.len().next_power_of_two();
            let count = size.trailing_zeros() as usize + 1;
            let mut data = vec![vec![init; size]; count];
            for (i, v) in v.iter().cloned().enumerate() {
                data[0][i] = v;
            }
            for c in 1..count {
                for i in 0..size {
                    let next = ::std::cmp::min(size - 1, i + (1 << (c - 1)));
                    data[c][i] = op(data[c - 1][i], data[c - 1][next]);
                }
            }

            SparseTable { data: data, op: op }
        }

        /// get the result for [l, r)
        pub fn get(&self, l: usize, r: usize) -> T {
            assert!(l < r);
            let length = r - l;
            if length == 1 {
                return self.data[0][l];
            }
            let block_size = length.next_power_of_two() >> 1;
            let c = block_size.trailing_zeros() as usize;
            let left = self.data[c][l];
            let right = self.data[c][r - block_size];
            (self.op)(left, right)
        }
    }
}
pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io;
use std::str::FromStr;
use std::cmp;
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::collections::HashMap;

const INT_MAX: i64 = 200001;

struct SegmentTree {
    n: usize, 
    dat: Vec<i64>
}

impl SegmentTree {
    fn new(nn: usize) -> SegmentTree {
        let mut n = 1;
        while n < nn {
            n *= 2;
        }
        let dat = vec![INT_MAX; 2*n-1];
        return SegmentTree {n: n, dat: dat};
    }

    fn update(&mut self, k: usize, a: i64) {
        let mut i = k + (self.n - 1);
        self.dat[i] = a;
        while i > 0 {
            i = (i - 1) / 2;
            self.dat[i] = cmp::min(self.dat[i*2+1], self.dat[i*2+2]);
        }
    }
    fn query(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> i64 {
        if (r <= a) || (b <= l) {
            return INT_MAX;
        }
        if (a <= l) && (r <= b) {
            return self.dat[k];
        }
        let vl = self.query(a, b, k*2+1, l, (l+r)/2);
        let vr = self.query(a, b, k*2+2, (l+r)/2, r);
        return cmp::min(vl, vr);
    }
}

enum EvenOdd {
    E,
    O,
}

#[derive(Copy, Clone, Eq, PartialEq)]
struct Item {
    v: i64,
    i: usize,
    left: usize,
    right: usize,
}

// Priority Queue
impl Ord for Item {
    fn cmp(&self, other: &Item) -> Ordering {
        other.v.cmp(&self.v)
    }
}

impl PartialOrd for Item {
    fn partial_cmp(&self, other: &Item) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let stdin = io::stdin();
    let mut buf = String::new();
    stdin.read_line(&mut buf).ok();
    let n = usize::from_str(buf.trim()).unwrap();
    buf = String::new();
    stdin.read_line(&mut buf).ok();
    let arr: Vec<i64> = buf.split_whitespace()
        .map(|n| i64::from_str(n).unwrap())
        .collect();
    let mut st_even = SegmentTree::new(n);
    let mut st_odd = SegmentTree::new(n);
    let mut h = HashMap::new();
    for (i, a) in arr.iter().enumerate() {
        h.insert(a, i);
        if i % 2 == 0 {
            st_even.update(i, a.clone());
        } else {
            st_odd.update(i, a.clone());
        }
    }

    let wrap_query = |t: EvenOdd, a: usize, b: usize, k: usize, l: usize| {
        match (t, a%2) {
            (EvenOdd::E, 0) => st_even.query(a, b, k, l, st_even.n),
            (EvenOdd::E, 1) => st_odd.query(a, b, k, l, st_odd.n),
            (EvenOdd::O, 0) => st_odd.query(a, b, k, l, st_odd.n),
            _ => st_even.query(a, b, k, l, st_even.n),
        }
    };

    let mut q = vec![0; n];
    let mut pq = BinaryHeap::<Item>::new();
    let x = wrap_query(EvenOdd::E, 0, n, 0, 0);
    pq.push(Item{v: x, i: h[&x], left: 0, right: n});
    let mut ii = 0;
    while pq.len() != 0 {
        let item = pq.pop().unwrap();
        q[ii] = item.v;
        ii = ii + 1;
        let q1 = wrap_query(EvenOdd::O, item.i, item.right, 0, 0);
        let j = h[&q1];
        q[ii] = q1;
        ii = ii + 1;
        if item.i - item.left > 1 {
            let x = wrap_query(EvenOdd::E, item.left, item.i, 0, 0);
            pq.push(Item{v: x, i: h[&x], left: item.left, right: item.i});
        }
        if j - (item.i + 1) > 1 {
			let x = wrap_query(EvenOdd::E, item.i+1, j, 0, 0);
			pq.push(Item{v: x, i: h[&x], left: item.i + 1, right: j});
        }
        if item.right - (j + 1) > 1 {
			let x = wrap_query(EvenOdd::E, j+1, item.right, 0, 0);
			pq.push(Item{v: x, i: h[&x], left: j + 1, right: item.right});
        }
    }
    let mut ret = String::new();
    for (i, x) in q.iter().enumerate() {
        if i == n - 1 {
            ret.push_str(&format!("{}", x));
        } else {
            ret.push_str(&format!("{} ", x));
        }
    }
    println!("{}", ret);
}

use proconio::input;

fn cal(a: &[u32]) -> Vec<(u32, u32)> {
    assert!(a.len() % 2 == 0);
    if a.is_empty() {
        Vec::new()
    } else {
        let n = a.len();
        let u = (0..n)
            .filter(|&i| i % 2 == 0)
            .min_by_key(|&i| a[i])
            .unwrap();
        let v = (u + 1..n)
            .filter(|&i| i % 2 == 1)
            .min_by_key(|&i| a[i])
            .unwrap();
        [(a[u], a[v])]
            .iter()
            .chain(itertools::kmerge(&[
                cal(&a[0..u]),
                cal(&a[u + 1..v]),
                cal(&a[v + 1..n]),
            ]))
            .cloned()
            .collect()
    }
}

fn main() {
    input!(n: usize, a: [u32; n]);
    let ans = cal(a.as_slice());
    println!(
        "{}",
        ans.iter()
            .map(|&(x, y)| format!("{} {}", x, y))
            .fold(String::new(), |acc, x| if acc.is_empty() {
                x
            } else {
                acc + " " + x.as_ref()
            })
    );
}

