struct SegTree<T> {
    elems: Vec<Option<T>>,
    num: usize,
}

impl<T: Clone + Copy + Ord> SegTree<T> {
    fn new(xs: &Vec<T>) -> Self {
        let l = xs.len();
        let n = (l as f64).log2().ceil().exp2() as usize;

        let mut res = SegTree {
            elems: vec![None; 2 * n - 1],
            num: l,
        };

        for (i, &x) in xs.iter().enumerate() {
            res.update(x, i);
        }

        res
    }

    fn update(&mut self, v: T, idx: usize) {
        let mut i = self.num + idx - 1;

        self.elems[i] = Some(v);

        while i > 0 {
            i = (i - 1) / 2;

            self.elems[i] =
            if let (Some(lhs), Some(rhs)) = (self.elems[i * 2 + 1], self.elems[i * 2 + 2]) {
                Some(std::cmp::max(lhs, rhs))
            }
            else {
                self.elems[i * 2 + 1]
            };
        }
    }

    fn query(&self, lb: usize, rb: usize) -> T {
        self.qf(lb, rb, 0, 0, self.num).unwrap()
    }

    fn qf(&self, lb: usize, rb: usize, i: usize, clb: usize, crb: usize) -> Option<T> {
        if lb >= crb || clb >= rb {
            None
        }
        else if clb >= lb && rb >= crb {
            self.elems[i]
        }
        else {
            let mid = (clb + crb) / 2;

            let lv = self.qf(lb, rb, i * 2 + 1, clb, mid);
            let rv = self.qf(lb, rb, i * 2 + 2, mid, crb);

            match (lv, rv) {
                (Some(lhs), Some(rhs)) => {
                    Some(std::cmp::max(lhs, rhs))
                },
                (Some(lhs), _) => {
                    Some(lhs)
                },
                (_, Some(rhs)) => {
                    Some(rhs)
                },
                _ => {
                    None
                }
            }
        }
    }
}

fn main() {
    let n = readln();
    let ps = reads();

    let mut es = vec![];
    let mut os = vec![];
    let mut oes = vec![];

    for i in 0..n {
        let e = E {num: ps[i], idx: i};
        let d = E {num: n + 1, idx: i};

        if i % 2 == 0 {
            es.push(e);
            os.push(d);
        }
        else {
            es.push(d);
            os.push(e);
        }
        oes.push(e);
    }

    let est = SegTree::new(&es);
    let ost = SegTree::new(&os);
    let st = SegTree::new(&oes);

    let mut q = BinaryHeap::new();
    q.push(
        R {
            num: st.query(0, n),
            lb: 0,
            rb: n,
        }
    );

    let mut qs = vec![];

    while let Some(r) = q.pop() {
        if (r.num.idx - r.lb) % 2 == 0 {
            let next =
            if r.num.idx % 2 == 0 {
                ost.query(r.num.idx + 1, r.rb)
            }
            else {
                est.query(r.num.idx + 1, r.rb)
            };

            qs.push(r.num.num);
            qs.push(next.num);

            if r.num.idx > r.lb {
                q.push(
                    R {
                        num: st.query(r.lb, r.num.idx),
                        lb: r.lb,
                        rb: r.num.idx,
                    }
                );
            }

            if next.idx > r.num.idx + 1 {
                q.push(
                    R {
                        num: st.query(r.num.idx + 1, next.idx),
                        lb: r.num.idx + 1,
                        rb: next.idx,
                    }
                );
            }

            if r.rb > next.idx + 1 {
                q.push(
                    R {
                        num: st.query(next.idx + 1, r.rb),
                        lb: next.idx + 1,
                        rb: r.rb,
                    }
                );
            }
        }
        else {
            let next =
            if r.num.idx % 2 == 0 {
                ost.query(r.lb, r.num.idx)
            }
            else {
                est.query(r.lb, r.num.idx)
            };

            qs.push(next.num);
            qs.push(r.num.num);

            if next.idx > r.lb {
                q.push(
                    R {
                        num: st.query(r.lb, next.idx),
                        lb: r.lb,
                        rb: next.idx,
                    }
                );
            }

            if r.num.idx > next.idx + 1 {
                q.push(
                    R {
                        num: st.query(next.idx + 1, r.num.idx),
                        lb: next.idx + 1,
                        rb: r.num.idx,
                    }
                );
            }


            if r.rb > r.num.idx + 1 {
                q.push(
                    R {
                        num: st.query(r.num.idx + 1, r.rb),
                        lb: r.num.idx + 1,
                        rb: r.rb,
                    }
                );
            }
        }
    }

    for i in 0..(n - 1) {
        print!("{} ", qs[i]);
    }
    println!("{}", qs[n - 1]);
}

