fn make(mut p: Vec<usize>) -> Vec<(usize, usize)>  {
    if p.len() == 0 {
        return Vec::new();
    } else if p.len() == 2 {
        return vec![(p[0],p[1])];
    }
    let mut mn = std::usize::MAX;
    let mut mni = 0;
    for i in 0..p.len()-1 {
        if i % 2 == 1 {
            continue;
        }
        if mn > p[i] {
            mn = p[i];
            mni = i;
        }
    }
    let mut mn2 = std::usize::MAX;
    let mut mn2i = 0;
    for i in (mni+1)..p.len() {
        if i % 2 == 0 {
            continue;
        }
        if mn2 > p[i] {
            mn2 =  p[i];
            mn2i = i;
        }
    }

    let vec1 = make(p.drain(0..mni).collect::<Vec<_>>());
    let vec2 = make(p.drain(1..mn2i-mni).collect::<Vec<_>>());
    let vec3 = make(p.drain(2..).collect::<Vec<_>>());
    let mut vec = merge(merge(vec1, vec2),vec3);
    let mut p = vec![(p[0],p[1])];
    p.append(&mut vec);
    p
}

fn merge(vec1: Vec<(usize,usize)>, vec2: Vec<(usize, usize)>) ->  Vec<(usize, usize)> {
    let mut i = 0;
    let mut j = 0;
    let mut vec = vec![(0,0); vec1.len()+vec2.len()];
    while i < vec1.len() || j < vec2.len() {
        if j >= vec2.len() || (i < vec1.len() && vec1[i].0 < vec2[j].0) {
            vec[i+j] = vec1[i];
            i += 1;
        } else {
            vec[i+j] = vec2[j];
            j += 1;
        }
    }
    vec
}


