fn dfs(vec: &[usize], k: usize) -> Vec<usize> {
    if k == 1 {
        return vec.to_vec();
    }
    let mut mnf = Vec::new();
    let mut mnb = Vec::new();
    for i in 1..k {
        let l = dfs(&vec[0..2*i], i);
        let r = dfs(&vec[2*i..2*k], k-i);
        if l[0] < r[0] {
            if mnf.len() == 0 || mnf[0] > l[0] || (mnf[0] == l[0] && mnf[1] > l[1]) {
                mnf = l;
                mnb = r;
            }
        } else {
            if mnf.len() == 0 || mnf[0] > r[0] || (mnf[0] == r[0] && mnf[1] > r[1]) {
                mnf = r;
                mnb = l;
            }
        }
    }
    let mut l = dfs(&[vec[0], vec[2*k-1]], 1);
    let mut r = dfs(&vec[1..2*k-1], k-1);
    if mnf[0] > l[0] || (mnf[0] == l[0] && mnf[1] > l[1]) {
        l.append(&mut r);
        return l;
    }
    merge(mnf, mnb)
}

fn merge(vec1: Vec<usize>, vec2: Vec<usize>) ->  Vec<usize> {
    let mut i = 0;
    let mut j = 0;
    let len1 = vec1.len()/2;
    let len2 = vec2.len()/2;
    let mut vec = vec![0; vec1.len()+vec2.len()];
    while i < len1 || j < len2 {
        if j >= len2 || (i < len1 && vec1[2*i] < vec2[2*j]) {
            vec[2*(i+j)] = vec1[2*i];
            vec[2*(i+j)+1] = vec1[2*i+1];
            i += 1;
        } else {
            vec[2*(i+j)] = vec2[2*j];
            vec[2*(i+j)+1] = vec2[2*j+1];
            j += 1;
        }
    }
    vec
}

fn solve() {
    let n = get!(usize);
    let p = get!([usize]);

    let res = dfs(p.as_slice(), n/2);
    for e in res {
        print!("{} ", e);
    }
    println!("");
}

use std::error::Error;
use std::io::{self, BufReader};
