fn exec() {
    let mut sc = Scanner::new(io::stdin());
    let n: usize = sc.ne();
    let (mut even, mut odd) = {
        let mut e = Vec::new();
        let mut o = Vec::new();
        for i in 0..n {
            let x: i32 = sc.ne();
            if (i & 1) == 0 {
                e.push((x, i));
            } else {
                o.push((x, i));
            }
        }
        (SegTree::fromseq(&e), SegTree::fromseq(&o))
    };
    enum Qtype {
        A,
        B(bool),
    };
    let mut q = |from: usize, to: usize, qt: Qtype| -> (i32, usize) {
        let is_even = match qt {
            Qtype::A => (from & 1) == 0,
            Qtype::B(b) => b,
        };
        if is_even {
            even.query((from + 1) / 2, (to + 1) / 2)
        } else {
            odd.query(from / 2, to / 2)
        }
    };
    let mut heap = std::collections::BinaryHeap::new();
    heap.push((0, (0, n)));
    let mut ans = Vec::new();
    while let Some((_, (from, to))) = heap.pop() {
        if from + 1 >= to {
            continue;
        }
        if ans.len() == n {
            break;
        }
        let x = q(from, to, Qtype::A);
        let y = q(x.1 + 1, to, Qtype::B((from & 1) == 1));
        ans.push(x.0);
        ans.push(y.0);
        heap.push((-q(from, x.1, Qtype::A).0, (from, x.1)));
        heap.push((-q(x.1 + 1, y.1, Qtype::A).0, (x.1 + 1, y.1)));
        heap.push((-q(y.1 + 1, to, Qtype::A).0, (y.1 + 1, to)));
    }
    for x in ans {
        print!("{} ", x);
    }
    println!("");
}

