                (x.0 + y.0, min(x.1, y.2), min(x.2, y.1))
            } else {
                (x.0 + y.0, min(x.1, y.1), min(x.2, y.2))
            }
        }),
    );
    let mut bit = BinaryIndexedTree::new(n + 1, AddGroup::new(0i32));
    let mut c = vec![0; n];
    for i in 0..n {
        c[p[i]] = i;
        bit.update(n + 1, 1);
    }
    for _ in 0..n / 2 {
        let x = seg.query(0, n);
        print!("{} ", x.1 + 1);
        seg.update(c[x.1], id);
        bit.update(c[x.1] + 1, 1);
        let k = bit.query(c[x.1] + 1);
        let r = bit.lower_bound(k + 1).0;
        let r = if r == n { r } else { r + 1 };
        let x = seg.query(c[x.1], r);
        print!("{} ", x.1 + 1);
        seg.update(c[x.1], id);
        bit.update(c[x.1] + 1, 1);
    }
    println!("");
}

