struct Node {
    v1: usize,
    v2: usize,
    child: Vec<(usize,usize)>
}

impl Ord for Node {
    fn cmp(&self, other: &Node) -> Ordering {
        other.v1.cmp(&self.v1)
    }
}

impl PartialOrd for Node {
    fn partial_cmp(&self, other: &Node) -> Option<Ordering> {
