fn solve_sub_range(l:usize,r:usize,a:&Vec<usize>) -> Range {
    let mut li = l;
    let mut ri = l+1;
    for i in l..r {
        if i%2==l%2 {
            if a[i] < a[li] {
                li = i;
            }
        } else {
            if a[i] < a[ri] {
                ri = i
            }
        }
    }
    Range::new(li, ri+1, l, r)
}



