fn main() {
    let input = read_string();
    let mut sc = Scanner::new(&input);
    let n: usize = sc.next();
    let ps: Vec<usize> = sc.next_vec(n);
    let mut pq: BinaryHeap<Node> = BinaryHeap::new();
    let head = solve(&ps ,n);
    print!("{} {}", head.v1, head.v2);
    for v in head.child {
        pq.push(solve(&v, n));
    }
    loop {
        if pq.is_empty() {
            break;
        }
        let node = pq.pop().unwrap();
        print!(" {} {}", node.v1, node.v2);
        for v in node.child {
            pq.push(solve(&v, n));
        }
    }
    print!("\n");
}

fn solve(v: &Vec<usize>, n: usize) -> Node {
    let mut e = n + 1;
    let mut ei = 0;
    let mut o = n + 1;
    let mut oi = 0;
    for i in 0..v.len() {
        if i % 2 == 0 {
            if e > v[i] {
                e = v[i];
                ei = i;
                o = n + 1;
            }
        } else if o > v[i] {
            o = v[i];
            oi = i;
        }
    }
    let mut child: Vec<Vec<usize>> = Vec::new();
    if 0 < ei {
        child.push(v[0..ei].iter().map(|x| *x).collect());
    }
    if ei + 1 < oi {
        child.push(v[ei+1..oi].iter().map(|x| *x).collect());
    }
    if oi + 1 < v.len() {
        child.push(v[oi+1..].iter().map(|x| *x).collect());
    }
    Node{v1: e, v2: o, child: child}
}

