fn cal(a: &[u32]) -> (Reverse<u32>, Reverse<u32>, usize, usize) {
    let n = a.len();
    assert!(!a.is_empty() && a.len() % 2 == 0);
    let u = (0..n)
        .filter(|&i| i % 2 == 0)
        .min_by_key(|&i| a[i])
        .unwrap();
    let v = (u + 1..n)
        .filter(|&i| i % 2 == 1)
        .min_by_key(|&i| a[i])
        .unwrap();
    (Reverse(a[u]), Reverse(a[v]), u, v)
}
fn main() {
    input!(n: usize, a: [u32; n]);
    let mut ans = Vec::new();
    let mut heap = std::collections::BinaryHeap::from(vec![(cal(&a[0..n]), &a[0..n])]);
    while let Some(((au, av, u, v), seq)) = heap.pop() {
        ans.push((au, av));
        for subseq in [&seq[0..u], &seq[u + 1..v], &seq[v + 1..seq.len()]].iter() {
            if !subseq.is_empty() {
                heap.push((cal(subseq), subseq));
            }
        }
    }
    println!(
        "{}",
        ans.iter()
            .map(|&(Reverse(x), Reverse(y))| format!("{} {}", x, y))
            .fold(String::new(), |acc, x| if acc.is_empty() {
                x
            } else {
                acc + " " + x.as_ref()
            })
    );
}

