fn dfs<F: Fn((usize, usize), (usize, usize)) -> (usize, usize)>(
    from: usize,
    to: usize,
    odd_seg: &SegmentTree<(usize, usize), F>,
    even_seg: &SegmentTree<(usize, usize), F>,
) -> Vec<(usize, usize)> {
    if from == to {
        return vec![];
    }
    let (l, left) = even_seg.query(from, to);
    let (r, right) = odd_seg.query(left, to);
    let mut result = vec![(l, r)];
    let mut ans1 = dfs(from, left, odd_seg, even_seg);
    let mut ans2 = dfs(left + 1, right, even_seg, odd_seg);
    let mut ans3 = dfs(right + 1, to, odd_seg, even_seg);
    ans1.reverse();
    ans2.reverse();
    ans3.reverse();
    let mut ans = vec![ans1, ans2, ans3];
    while !ans[0].is_empty() || !ans[1].is_empty() || !ans[2].is_empty() {
        let mut tmp = vec![];
        for i in 0..3 {
            if let Some(a) = ans[i].pop() {
                tmp.push((a, i));
            }
        }
        tmp.sort();
        result.push(tmp[0].0);
        for i in 1..tmp.len() {
            ans[tmp[i].1].push(tmp[i].0);
        }
    }

    result
}

pub struct SegmentTree<T, F> {
    seg: Vec<T>,
    n: usize,
    f: F,
    initial_value: T,
}

impl<T: Copy, F> SegmentTree<T, F>
where
    F: Fn(T, T) -> T,
{
    pub fn new(size: usize, initial_value: T, f: F) -> SegmentTree<T, F> {
        let mut m = 1;
        while m <= size {
            m <<= 1;
        }
        SegmentTree {
            seg: vec![initial_value; m * 2],
            n: m,
            f: f,
            initial_value: initial_value,
        }
    }

    pub fn update(&mut self, k: usize, value: T) {
        let mut k = k;
        k += self.n - 1;
        self.seg[k] = value;
        while k > 0 {
            k = (k - 1) >> 1;
            self.seg[k] = (self.f)(self.seg[k * 2 + 1], self.seg[k * 2 + 2]);
        }
    }

    /// Get the minimum value in the array in the range [a, b)
    ///
    /// # Panics
    ///
    /// Panics if `a >= b`.
    pub fn query(&self, a: usize, b: usize) -> T {
        assert!(a < b, "a={} b={}", a, b);
        self.query_range(a, b, 0, 0, self.n)
    }

    fn query_range(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> T {
        if r <= a || b <= l {
            self.initial_value
        } else if a <= l && r <= b {
            self.seg[k]
        } else {
            let x = self.query_range(a, b, k * 2 + 1, l, (l + r) >> 1);
            let y = self.query_range(a, b, k * 2 + 2, (l + r) >> 1, r);
            (self.f)(x, y)
        }
    }
}
pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

