use std::io::{BufRead, Write};
use std::io;

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let _: usize = s.trim().parse().unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let mut a: Vec<usize> = s.split_whitespace().map(|x| x.parse().unwrap()).collect();
    let mut b: Vec<usize> = Vec::with_capacity(a.len());
    while !a.is_empty() {
        let (max_index, _) = a.windows(2)
            .enumerate()
            .max_by_key(|&(_, w)| (w[0] + w[1], w[1]))
            .unwrap();
        b.push(a.remove(max_index + 1));
        b.push(a.remove(max_index));
    }
    let result: Vec<_> = b.iter().rev().map(|x| x.to_string()).collect();
    writeln!(output, "{}", result.join(" ")).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

