fn rec(p: &[usize]) -> Vec<(usize, usize)> {
    if p.len() < 2 {
        return Vec::new();
    }
    let mut pair = ((400000, 0), 0, 0);
    for i in 0..p.len() / 2 {
        let a = i * 2;
        for k in 0.. {
            let b = a + 1 + 2 * k;
            if b >= p.len() {
                break;
            }
            pair = min(pair, ((p[a], p[b]), a, b));
        }
    }
    let mut res = vec![(p[pair.1], p[pair.2])];
    let x1 = rec(&p[0..pair.1]);
    let x2 = rec(&p[pair.1 + 1..pair.2]);
    let x3 = rec(&p[pair.2 + 1..]);
    let l = 0..x1.len() + x2.len() + x3.len();

    let mut list = [x1, x2, x3];
    for _ in l {
        let y = {
            (0..3)
                .min_by_key(|&i| list[i].last().cloned().unwrap_or((400000, 0)))
                .unwrap()
        };
        res.push(list[y].pop().unwrap());
    }
    res.into_iter().rev().collect()
}

