fn make(mut p: Vec<usize>) -> Vec<(usize, usize)>  {
    if p.len() == 0 {
        return Vec::new();
    } else if p.len() == 2 {
        return vec![(p[0],p[1])];
    }
    let mut mn = std::usize::MAX;
    let mut mni = 0;
    for i in 0..p.len()-1 {
        if i % 2 == 1 {
            continue;
        }
        if mn > p[i] {
            mn = p[i];
            mni = i;
        }
    }
    let mut mn2 = std::usize::MAX;
    let mut mn2i = 0;
    for i in (mni+1)..p.len() {
        if i % 2 == 0 {
            continue;
        }
        if mn2 > p[i] {
            mn2 =  p[i];
            mn2i = i;
        }
    }

    let mut vec = Vec::new();
    vec.append(&mut make(p.drain(0..mni).collect::<Vec<_>>()));
    vec.append(&mut make(p.drain(1..mn2i-mni).collect::<Vec<_>>()));
    vec.append(&mut make(p.drain(2..).collect::<Vec<_>>()));
    let mut p = vec![(p[0],p[1])];
    vec.sort_by_key(|e| e.0);
    for e in vec {
        p.push(e);
    }
    p
}

