fn solve<R: BufRead, W: Write>(_reader: R, _writer: &mut W) {
  let mut _scanner = Scanner::new(_reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($t:ty) => {
      _scanner.next::<$t>().unwrap()
    };
    ($($t:ty),+) => {
      ($(scan!($t)),+)
    };
    ($t:ty; $n:expr) => {
      scan_iter!($t; $n).collect::<Vec<_>>()
    };
    ($t_0:ty, $t_1:ty; $n:expr) => {
      scan!($t_0 = 0, $t_1 = 1; $n)
    };
    ($t_0:ty, $t_1:ty, $t_2:ty; $n:expr) => {
      scan!($t_0 = 0, $t_1 = 1, $t_2 = 2; $n)
    };
    ($($t:ty = $i:tt),+; $n:expr) => {{
      let mut vecs = ($(Vec::<$t>::with_capacity($n)),+);
      for _ in 0..$n {$(
        vecs.$i.push(scan!($t));
      )+}
      vecs
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($t:ty; $n:expr) => {
      _scanner.take::<$t>($n).map(|x| x.unwrap())
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(_writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(_writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    () => {
      writeln!(_writer).unwrap()
    };
    ($fmt:expr) => {
      writeln!(_writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(_writer, $fmt, $($arg)*).unwrap()
    };
  }

  use data_structures::DisjointSparseTable;
  use math::algebra::MinMonoid;
  use std::collections::BinaryHeap;
  use std::iter::FromIterator;

  let n = scan!(usize);
  let p = scan!(i64; n);
  let mut p_i_map = vec![0; n + 1];
  for (i, p_i) in p.iter().cloned().enumerate() {
    p_i_map[p_i as usize] = i;
  }

  let even_p_iter = p.iter().cloned().enumerate().map(|(i, x)| if i % 2 == 0 { x } else { i64::max_value() });
  let even_st = DisjointSparseTable::<MinMonoid<i64>>::from_iter(even_p_iter);
  let odd_p_iter = p.iter().cloned().enumerate().map(|(i, x)| if i % 2 != 0 { x } else { i64::max_value() });
  let odd_st = DisjointSparseTable::<MinMonoid<i64>>::from_iter(odd_p_iter);

  let min_x_i = 0usize;
  let min_y_i = n;
  let mut pq = BinaryHeap::new();
  pq.push((-even_st.concat(min_x_i..min_y_i), min_x_i, min_y_i));

  while let Some((_, l, r)) = pq.pop() {
    let min_x = if l % 2 == 0 { &even_st } else { &odd_st }.concat(l..r);
    let min_x_i = p_i_map[min_x as usize];
    let min_y = if l % 2 == 0 { &odd_st } else { &even_st }.concat(min_x_i + 1..r);
    let min_y_i = p_i_map[min_y as usize];

    print!("{} {} ", min_x, min_y);

    {
      let new_r = min_x_i;
      if (l..new_r).len() > 0 {
        let min = if l % 2 == 0 { &even_st } else { &odd_st }.concat(l..new_r);
        pq.push((-min, l, new_r));
      }
    }
    {
      let new_l = min_x_i + 1;
      let new_r = min_y_i;
      if (new_l..new_r).len() > 0 {
        let min = if l % 2 == 0 { &odd_st } else { &even_st }.concat(new_l..new_r);
        pq.push((-min, new_l, new_r));
      }
    }
    {
      let new_l = min_y_i + 1;
      if (new_l..r).len() > 0 {
        let min = if l % 2 == 0 { &even_st } else { &odd_st }.concat(new_l..r);
        pq.push((-min, new_l, r));
      }
    }
  }
}

