pub mod data_structures {
  pub use self::disjoint_sparse_table::*;

  mod disjoint_sparse_table {
    use math::algebra::Semigroup;
    use std::iter::FromIterator;
    use std::mem::size_of;
    use std::ops::Range;

    pub struct DisjointSparseTable<SG: Semigroup> {
      vecs: Vec<Vec<SG::T>>,
    }

    impl<SG: Semigroup> DisjointSparseTable<SG> {
      pub fn len(&self) -> usize {
        self.vecs[0].len()
      }

      pub fn concat(&self, range: Range<usize>) -> SG::T {
        assert!(range.start < range.end);
        assert!(range.end <= self.len());
        if range.start == range.end - 1 {
          return self.vecs[0][range.start].clone();
        }
        let row_index = size_of::<usize>() * 8 - (range.start ^ range.end - 1).leading_zeros() as usize - 1;
        SG::append(&self.vecs[row_index][range.start], &self.vecs[row_index][range.end - 1])
      }
    }

    impl<SG: Semigroup> FromIterator<SG::T> for DisjointSparseTable<SG> {
      fn from_iter<I: IntoIterator<Item = SG::T>>(iter: I) -> Self {
        let base = iter.into_iter().collect::<Vec<_>>();
        let len = base.len();
        let size = len.next_power_of_two();
        if size < 2 {
          return DisjointSparseTable { vecs: vec![base] };
        }
        let mut vecs = Vec::with_capacity(size.trailing_zeros() as usize);
        vecs.push(base);
        let mut r_width = 2usize;
        while r_width < len {
          let mut vec = Vec::with_capacity(len);
          unsafe {
            vec.set_len(len);
          }
          let mut r_mid = r_width;
          while r_mid - r_width < len {
            let (l_mid, l_width) = if r_mid < len {
              vec[r_mid] = vecs[0][r_mid].clone();
              for i in (r_mid + 1..r_mid + r_width).take_while(|i| *i < len) {
                vec[i] = SG::append(&vec[i - 1], &vecs[0][i]);
              }
              (r_mid - 1, r_width)
            } else {
              (len - 1, r_width - (r_mid - len))
            };
            vec[l_mid] = vecs[0][l_mid].clone();
            for i in (l_mid + 1 - l_width..l_mid).rev() {
              vec[i] = SG::append(&vecs[0][i], &vec[i + 1]);
            }
            r_mid += r_width * 2;
          }
          vecs.push(vec);
          r_width *= 2;
        }
        debug_assert_eq!(vecs.len(), size.trailing_zeros() as usize);
        DisjointSparseTable { vecs: vecs }
      }
    }
  }
}

pub mod io {
  pub use self::scanner::*;

  mod scanner {
    use std::io::BufRead;
    use std::marker::PhantomData;
    use std::str::{from_utf8, FromStr};

    pub struct Scanner<R> {
      reader: R,
      buffer: Vec<u8>,
      position: usize,
    }

    impl<R: BufRead> Scanner<R> {
      pub fn new(reader: R) -> Self {
        Scanner { reader: reader, buffer: vec![], position: 0 }
      }

      pub fn next<T: Parse>(&mut self) -> Option<T> {
        Parse::parse(self.next_bytes().unwrap_or(&[]))
      }

      pub fn take<T: Parse>(&mut self, n: usize) -> Take<R, T> {
        Take { scanner: self, n: n, _marker: PhantomData }
      }

      pub fn next_bytes(&mut self) -> Option<&[u8]> {
        if self.buffer.is_empty() {
          self.read_line();
        }
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') => self.position += 1,
            Some(&b'\n') => self.read_line(),
            Some(_) => break,
            None => return None,
          }
        }
        let start = self.position;
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') | Some(&b'\n') | None => break,
            Some(_) => self.position += 1,
          }
        }
        Some(&self.buffer[start..self.position])
      }

      fn read_line(&mut self) {
        self.position = 0;
        self.buffer.clear();
        self.reader.read_until(b'\n', &mut self.buffer).unwrap();
      }
    }

    pub struct Take<'a, R: 'a, T> {
      scanner: &'a mut Scanner<R>,
      n: usize,
      _marker: PhantomData<fn() -> T>,
    }

    impl<'a, R: BufRead, T: Parse> Iterator for Take<'a, R, T> {
      type Item = Option<T>;

      fn next(&mut self) -> Option<Self::Item> {
        if self.n > 0 {
          self.n -= 1;
          Some(self.scanner.next())
        } else {
          None
        }
      }

      fn size_hint(&self) -> (usize, Option<usize>) {
        (self.n, Some(self.n))
      }
    }

    impl<'a, R: BufRead, T: Parse> ExactSizeIterator for Take<'a, R, T> {}

    pub trait Parse: Sized {
      fn parse(bytes: &[u8]) -> Option<Self>;
    }

    impl Parse for u8 {
      fn parse(bytes: &[u8]) -> Option<Self> {
        if bytes.len() == 1 {
          Some(*unsafe { bytes.get_unchecked(0) })
        } else {
          None
        }
      }
    }

    macro_rules! parse_impl {
      ($($t:ident)+) => {$(
        impl Parse for $t {
          fn parse(bytes: &[u8]) -> Option<Self> {
            from_utf8(bytes).ok().and_then(|s| $t::from_str(s).ok())
          }
        }
      )+};
    }

    parse_impl! { i32 i64 u32 u64 isize usize String }
  }
}

