fn main() {
    input! {
        n: usize,
        q: [i32; n]
    };

    let INF = 1e9 as i32;
    let mut odd = SegmentTree::new(n, (INF,n), Rc::new(|a,b| min(a,b)));
    let mut even = SegmentTree::new(n, (INF,n), Rc::new(|a,b| min(a,b)));
    for i in 0..n {
        if i % 2 == 0 {
            odd.set(i, (INF, i));
            even.set(i, (q[i], i));
        } else {
            odd.set(i, (q[i], i));
            even.set(i, (INF, i));
        }
    }

    let extract = |l:usize, r:usize| {
        if l + 1 == r {
            return (-q[l], -q[r], vec![]);
        }
        let mut parts = vec![];
        let e = ifv!(l % 2 == 0, even.compute_range(l, r+1), odd.compute_range(l, r+1));
        let o = ifv!(l % 2 == 0, odd.compute_range(e.1, r+1), even.compute_range(e.1, r+1));
        let ll = e.1;
        let rr = o.1;
        if l < ll {
            parts.push((l, ll-1));
        }
        if ll+1 < rr {
            parts.push((ll+1, rr-1));
        }
        if rr+1 < r {
            parts.push((rr+1, r));
        }
        (-e.0, -o.0, parts)
    };

    let mut q = BinaryHeap::new();
    q.push(extract(0, n));
    let mut ans = vec![];
    while let Some((v1, v2, parts)) = q.pop() {
        ans.push(-v1);
        ans.push(-v2);
        for p in parts {
            q.push((extract(p.0, p.1)));
        }
    }
    println!("{}", join!(ans, " "));
}

