#[derive(Debug, Copy, Clone, Eq, PartialEq)]
struct Candidate {
    minimum: i64,
    from: usize,
    until: usize,
}

impl Ord for Candidate {
    fn cmp(&self, other: &Candidate) -> Ordering {
        // Notice that the we flip the ordering on costs.
        // In case of a tie we compare positions - this step is necessary
        // to make implementations of `PartialEq` and `Ord` consistent.
        other.minimum.cmp(&self.minimum)
    }
}

// `PartialOrd` needs to be implemented as well.
impl PartialOrd for Candidate {
    fn partial_cmp(&self, other: &Candidate) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn go(from: usize, until: usize, even_rmq: &RangeMinimumQuery, odd_rmq: &RangeMinimumQuery, rev: &Vec<usize>, ans: &mut Vec<i64>, arr: &Vec<i64>) {
    let mut heap = BinaryHeap::new();
    heap.push(Candidate { minimum: 0, from: from, until: until });
    while !heap.is_empty() {
        let s: Candidate = heap.pop().unwrap();
        let from = s.from;
        let until = s.until;

        let (head, tail) = if from % 2 == 0 {
            let minimum_value = even_rmq.query(from, until);
            let minimum_index = rev[minimum_value as usize];
            let pair = odd_rmq.query(minimum_index + 1, until);
            let pair_index = rev[pair as usize];
            (minimum_index, pair_index)
        } else {
            let minimum_value = odd_rmq.query(from, until);
            let minimum_index = rev[minimum_value as usize];
            let pair = even_rmq.query(minimum_index + 1, until);
            let pair_index = rev[pair as usize];
            (minimum_index, pair_index)
        };
        ans.push(arr[head]);
        ans.push(arr[tail]);

        if from < head {
            let (left, right) = (from, head);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
        if head + 1 < tail {
            let (left, right) = (head + 1, tail);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
        if tail + 1 < until {
            let (left, right) = (tail + 1, until);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
    }
}

