#[derive(Debug, Copy, Clone, Eq, PartialEq)]
struct Candidate {
    minimum: i64,
    from: usize,
    until: usize,
}

impl Ord for Candidate {
    fn cmp(&self, other: &Candidate) -> Ordering {
        // Notice that the we flip the ordering on costs.
        // In case of a tie we compare positions - this step is necessary
        // to make implementations of `PartialEq` and `Ord` consistent.
        other.minimum.cmp(&self.minimum)
    }
}

// `PartialOrd` needs to be implemented as well.
impl PartialOrd for Candidate {
    fn partial_cmp(&self, other: &Candidate) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn go(from: usize, until: usize, even_rmq: &RangeMinimumQuery, odd_rmq: &RangeMinimumQuery, rev: &Vec<usize>, ans: &mut Vec<i64>, arr: &Vec<i64>) {
    let mut heap = BinaryHeap::new();
    heap.push(Candidate { minimum: 0, from: from, until: until });
    while !heap.is_empty() {
        let s: Candidate = heap.pop().unwrap();
        let from = s.from;
        let until = s.until;

        let (head, tail) = if from % 2 == 0 {
            let minimum_value = even_rmq.query(from, until);
            let minimum_index = rev[minimum_value as usize];
            let pair = odd_rmq.query(minimum_index + 1, until);
            let pair_index = rev[pair as usize];
            (minimum_index, pair_index)
        } else {
            let minimum_value = odd_rmq.query(from, until);
            let minimum_index = rev[minimum_value as usize];
            let pair = even_rmq.query(minimum_index + 1, until);
            let pair_index = rev[pair as usize];
            (minimum_index, pair_index)
        };
        ans.push(arr[head]);
        ans.push(arr[tail]);

        if from < head {
            let (left, right) = (from, head);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
        if head + 1 < tail {
            let (left, right) = (head + 1, tail);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
        if tail + 1 < until {
            let (left, right) = (tail + 1, until);
            let minimum = if left % 2 == 0 {
                even_rmq.query(left, right)
            } else {
                odd_rmq.query(left, right)
            };
            heap.push(Candidate { minimum: minimum, from: left, until: right });
        }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n = sc.parse::<usize>();
    let arr = (0..n).map(|_| {
        sc.parse::<i64>() - 1
    }).collect::<Vec<_>>();
    let mut rev = vec![0; n];
    for i in 0..n {
        rev[arr[i] as usize] = i;
    }

    let mut even_rmq = RangeMinimumQuery::new(n);
    let mut odd_rmq = RangeMinimumQuery::new(n);
    for i in 0..n {
        if i % 2 == 0 {
            even_rmq.update(i, arr[i]);
        } else {
            odd_rmq.update(i, arr[i]);
        }
    }

    let mut ans = Vec::new();
    go(0, n, &even_rmq, &odd_rmq, &rev, &mut ans, &arr);
    for t in &ans {
        print!("{} ", t + 1);
    }
    println!();
}

pub struct RangeMinimumQuery {
    seg: Vec<i64>,
    n: usize,
}

impl RangeMinimumQuery {
    pub fn new(size: usize) -> RangeMinimumQuery {
        let mut m = 1;
        while m <= size {
            m *= 2;
        }
        RangeMinimumQuery {
            seg: vec![MAX; m * 2],
            n: m,
        }
    }

    pub fn update(&mut self, mut k: usize, value: i64) {
        k += self.n - 1;
        self.seg[k] = value;
        while k > 0 {
            k = (k - 1) / 2;
            self.seg[k] = cmp::min(self.seg[k * 2 + 1], self.seg[k * 2 + 2]);
        }
    }

    /// Get the minimum value in the array in the range [a, b)
    ///
    /// # Panics
    ///
    /// Panics if `a >= b`.
    pub fn query(&self, a: usize, b: usize) -> i64 {
        assert!(a < b);
        return self.query_range(a, b, 0, 0, self.n);
    }

    pub fn query_range(&self, a: usize, b: usize, k: usize, l: usize, r: usize) -> i64 {
        if r <= a || b <= l {
            return MAX;
        }
        if a <= l && r <= b {
            return self.seg[k];
        }
        let x = self.query_range(a, b, k * 2 + 1, l, (l + r) / 2);
        let y = self.query_range(a, b, k * 2 + 2, (l + r) / 2, r);
        cmp::min(x, y)
    }
}

struct Scanner {
    stdin: Stdin,
    buf: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner {
            stdin: io::stdin(),
            buf: Vec::with_capacity(256),
        }
    }

    fn parse<T: FromStr>(&mut self) -> T
        where <T as FromStr>::Err: Debug
    {
        self.buf.clear();
        let mut it = self.stdin.lock().bytes();
        let mut c = it.next().unwrap().unwrap();
        while c == ' ' as u8 || c == '\n' as u8 {
            c = it.next().unwrap().unwrap();
        }
        while !(c == ' ' as u8 || c == '\n' as u8) {
            self.buf.push(c);
            c = it.next().unwrap().unwrap();
        }
        str::from_utf8(&self.buf).unwrap().parse::<T>().unwrap()
    }
}

#[allow(unused_macros)]
macro_rules! parse_line {
    ( $t:ty ) => (
        {
            let mut line = String::new();
            ::std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            iter.next().unwrap().parse::<$t>().unwrap()
        }
    );

    ( $( $t:ty), +) => (
        {
            let mut line = String::new();
            ::std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            ( $(iter.next().unwrap().parse::<$t>().unwrap()),* )
        }
    );
}

#[allow(unused_macros)]
macro_rules! read_line {
    () => (
        {
            let mut line = String::new();
            ::std::io::stdin().read_line(&mut line).unwrap();
            line.pop();
            line
        }
    )
}

#[allow(unused_macros)]
macro_rules! parse_vec {
    ( $t:ty ) => (
        {
            let mut line = String::new();
            ::std::io::stdin().read_line(&mut line).unwrap();
            let iter = line.split_whitespace();
            iter.map(|v| v.parse::<$t>().unwrap()).collect::<Vec<_>>()
        }
    )
}

use std::rc::Rc;
use std::cell::RefCell;

fn init_(k: usize, l:usize, r:usize, rmq: Rc<RefCell<Vec<(usize, usize)>>>, vs: &Vec<usize>) -> (usize, usize) {
    use std::cmp::min;

    if r-l==1 {
        if l < vs.len() {
            rmq.borrow_mut()[k] = (vs[l], l);
        } else {
            rmq.borrow_mut()[k] = (std::usize::MAX, l);
        }
    } else {
        let chl = k*2 + 1;
        let chr = k*2 + 2;

        let lv = init_(chl, l, (l+r)/2, rmq.clone(), vs);
        let rv = init_(chr, (l+r)/2, r, rmq.clone(), vs);
        if lv.0 < rv.0 {
            rmq.borrow_mut()[k] = lv;
        } else {
            rmq.borrow_mut()[k] = rv;
        }
    }

    rmq.borrow()[k]
}

fn init(vs: Vec<usize>) -> Vec<(usize, usize)> {
    let n_ = vs.len();
    let mut n = 1;
    while n < n_ {
        n *= 2;
    }

    let mut rmq = Rc::new(RefCell::new(vec![(std::usize::MAX, std::usize::MAX); 2*n-1]));

    init_(0, 0, n_, rmq.clone(), &vs);

    Rc::try_unwrap(rmq).ok().unwrap().into_inner()
}

// min value in [a, b)
fn query_(a: usize, b: usize, k: usize, l: usize, r: usize, rmq: &Vec<(usize, usize)>) -> (usize, usize) {
    use std::cmp::min;

    //println!("a,b,l,r = {}, {}, {}, {}", a,b,l,r);

    if r <= a || b <= l {
        return (std::usize::MAX, std::usize::MAX)
    }

    if a <= l && r <= b {
        rmq[k]
    } else {
        let vl = query_(a,b,k*2+1, l, (l+r)/2, rmq);
        let vr = query_(a,b,k*2+2, (l+r)/2, r, rmq);
        if vl.0 < vr.0 {
            vl
        } else {
            vr
        }
    }
}

fn query(a: usize, b: usize, rmq: &Vec<(usize, usize)>) -> (usize, usize) {
    let n = rmq.len();

    query_(a,b,0,0,(n+1)/2,rmq)
}

fn solve(ps: Vec<usize>) -> Vec<usize> {
    use std::collections::BinaryHeap;

    let n = ps.len();

    let mut evs = Vec::new();
    let mut odds = Vec::new();

    for (i, &p) in ps.iter().enumerate() {
        if i % 2 == 0 {
            evs.push(p);
        } else {
            odds.push(p);
        }
    }

    let evs = init(evs);
    let odds = init(odds);

    //println!("evs = {:?}", evs);
    //println!("odds = {:?}", odds);

    let mut ans: Vec<usize> = Vec::new();
    let mut heap = BinaryHeap::new();

    heap.push(Range{pri: evs[0].0, range:(0,n)});

    while !heap.is_empty() {

        let range = heap.pop().unwrap();
        let (a,b) = range.range;
        //println!("a,b = {}, {}", a,b);

        let (min_p, pos_l) =  if (a % 2) == 0 {
            query((a+a%2)/2, (b+b%2)/2, &evs)
        } else {
            query(a/2, b/2, &odds)
        };

        //println!("min_p, pos_l = {}, {}", min_p, pos_l);

        ans.push(min_p);

        let l = pos_l*2 + (a % 2);

        if a < l {
            let (pal, _) = if a % 2 == 0 {
                query((a+a%2)/2, (l+l%2)/2, &evs)
            } else {
                query(a/2, l/2, &odds)
            };
            //println!("a < l: ({}, {})", a, l);
            heap.push(Range{ pri:pal, range:(a, l)});
        }

        //println!("l, b, odds = {} {} {:?}", l, b, odds);

        let (pr, pos_r) = if l % 2 == 0 {
            query(l/2, b/2, &odds)
        } else {
            query((l+l%2)/2, (b+b%2)/2, &evs)
        };
        ans.push(pr);

        //println!("pos_r = {}", pos_r);

        let r = pos_r * 2 + if l % 2 == 1 { 0 } else { 1 };

        if l+1 < r {
            let l = l+1;
            let (plr, _) = if l % 2 == 0 {
                query((l+l%2)/2, (r+r%2)/2, &evs)
            } else {
                query(l/2, r/2, &odds)
            };
            //println!("l+1 < r: ({}, {})", l, r);
            heap.push(Range {pri: plr, range:(l,r)});
        }

        if r+1 < b {
            let r = r+1;
            let (prb, _) = if r % 2 == 0 {
                query((r+r%2)/2, (b+b%2)/2, &evs)
            } else {
                query(r/2, b/2, &odds)
            };

            //println!("r+1 < b: ({}, {})", r, b);
            heap.push(Range {pri: prb, range:(r, b)});
        }

        //println!("ans = {:?}", ans);
        //println!("a,l,r,b = {},{},{},{}", a,l,r,b);
        //println!("heap.len() = {}", heap.len());
        assert!(ans.len() <= n);
    }

    ans
}

use std::cmp::Ordering;

#[derive(PartialEq)]
struct Range {
    pri: usize,
    range: (usize, usize)
}

impl Eq for Range {}

impl PartialOrd for Range {
    fn partial_cmp(&self, other: &Range) -> Option<Ordering> {
        other.pri.partial_cmp(&self.pri)
    }
}

impl Ord for Range {
    fn cmp(&self, other: &Range) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn main() {
    read_line!();

    let ps = parse_vec!(usize);
    println!("{}", solve(ps).iter().map(|p| p.to_string()).collect::<Vec<String>>().join(" "));
}
